def literal_eval_untrusted_source(value: Any) -> Any:
    """Parse captured literals without leaking source-authored warnings to operators."""

    with warnings.catch_warnings():
        warnings.simplefilter("ignore", SyntaxWarning)
        return ast.literal_eval(value)


@dataclass
class BestEffortJsonProgressEmitter:
    """Keep non-authoritative progress transport failures out of semantic work."""

    enabled: bool
    stream: Any = None
    emitted_count: int = 0
    failed_count: int = 0
    suppressed_count: int = 0
    detached: bool = False
    failure_kind: str = ""

    def emit(self, payload: dict[str, Any]) -> bool:
        if not self.enabled:
            return False
        if self.failure_kind:
            self.suppressed_count += 1
            return False
        target = self.stream if self.stream is not None else sys.stderr
        try:
            print(
                json.dumps(payload, ensure_ascii=False),
                file=target,
                flush=True,
            )
        except BrokenPipeError:
            self.failed_count += 1
            self.failure_kind = "BrokenPipeError"
            self.detached = detach_broken_progress_stream(target)
            return False
        self.emitted_count += 1
        return True

    def summary(self) -> dict[str, Any]:
        if not self.enabled:
            status = "not_requested"
        elif self.failure_kind:
            status = "detached_broken_pipe"
        elif self.emitted_count:
            status = "delivered"
        else:
            status = "no_event_emitted"
        return {
            "schema_version": 1,
            "requested": self.enabled,
            "status": status,
            "emitted_count": self.emitted_count,
            "failed_count": self.failed_count,
            "suppressed_count": self.suppressed_count,
            "stream_detached": self.detached,
            "failure_kind": self.failure_kind,
            "authority_boundary": (
                "progress transport is non-authoritative; projection receipts "
                "and resolvable evidence prove semantic progress"
            ),
        }


def detach_broken_progress_stream(stream: Any) -> bool:
    """Redirect a broken OS pipe to /dev/null so interpreter shutdown stays clean."""

    try:
        stream_fd = int(stream.fileno())
    except (AttributeError, OSError, TypeError, ValueError):
        return False
    try:
        devnull_fd = os.open(os.devnull, os.O_WRONLY)
    except OSError:
        return False
    try:
        os.dup2(devnull_fd, stream_fd)
    except OSError:
        return False
    finally:
        os.close(devnull_fd)
    return True


