def label_sequence_from(label: str | None, session_date: str) -> int | None:
    if not label:
        return None
    match = re.match(rf"^{re.escape(session_date)}__(\d{{3}})__", label)
    if not match:
        return None
    return int(match.group(1))


def next_daily_sequence(aoa_root: Path, session_date: str, session_id: str) -> int:
    registry = read_json(aoa_root / REGISTRY_NAME, {"sessions": []})
    used: set[int] = set()
    sessions = registry.get("sessions", []) if isinstance(registry, dict) else []
    for item in sessions if isinstance(sessions, list) else []:
        if not isinstance(item, dict) or item.get("session_id") == session_id:
            continue
        display = item.get("display")
        label = display.get("label") if isinstance(display, dict) else item.get("session_label")
        sequence = label_sequence_from(str(label or ""), session_date)
        if sequence is not None:
            used.add(sequence)
    for root_name in (SESSION_ROOT, LEGACY_SESSION_ROOT):
        archive_root = aoa_root / root_name
        if archive_root.exists():
            for path in archive_root.iterdir():
                sequence = label_sequence_from(path.name, session_date)
                if sequence is not None:
                    used.add(sequence)
    sequence = 1
    while sequence in used:
        sequence += 1
    return sequence


def session_display(
    *,
    aoa_root: Path,
    session_dir: Path,
    session_id: str,
    event: dict[str, Any],
    transcript_path: Path | None,
    events: list[RawEvent],
    existing: dict[str, Any],
    now: str,
) -> dict[str, Any]:
    existing_display = existing.get("display") if isinstance(existing.get("display"), dict) else {}
    title, title_source = session_title(events, event, transcript_path)
    session_date = first_session_date(events, event, transcript_path, str(existing.get("created_at") or now)[:10])
    existing_label = str(existing_display.get("label") or "")
    existing_sequence = label_sequence_from(existing_label, session_date)
    sequence = existing_sequence or next_daily_sequence(aoa_root, session_date, session_id)
    if existing_label and display_quality(str(existing_display.get("title_source"))) > display_quality(title_source):
        label = existing_label
        title = str(existing_display.get("title") or title)
        title_source = str(existing_display.get("title_source") or title_source)
    else:
        label = f"{session_date}__{sequence:03d}__{readable_slug(title)}"
    archive_path = aoa_root / SESSION_ROOT / label
    return {
        "date": session_date,
        "sequence": sequence,
        "title": title,
        "title_source": title_source,
        "label": label,
        "path": str(archive_path),
        "archive_path": str(archive_path),
        "navigation_path": str(archive_path),
    }


def merge_or_move_session_dir(source_dir: Path, target_dir: Path) -> Path:
    if source_dir == target_dir:
        target_dir.mkdir(parents=True, exist_ok=True)
        return target_dir
    if target_dir.is_symlink():
        target_dir.unlink()
    if not source_dir.exists():
        target_dir.mkdir(parents=True, exist_ok=True)
        return target_dir
    if not target_dir.exists():
        target_dir.parent.mkdir(parents=True, exist_ok=True)
        source_dir.rename(target_dir)
        return target_dir
    for child in source_dir.iterdir():
        destination = target_dir / child.name
        if destination.exists():
            if child.is_dir() and not child.is_symlink() and destination.is_dir():
                for nested in child.iterdir():
                    nested_destination = destination / nested.name
                    if not nested_destination.exists():
                        nested.rename(nested_destination)
            continue
        child.rename(destination)
    try:
        source_dir.rmdir()
    except OSError:
        pass
    return target_dir


def update_artifact_paths_after_move(session_dir: Path, manifest: dict[str, Any]) -> None:
    raw = manifest.get("raw")
    if isinstance(raw, dict) and raw.get("path"):
        raw["path"] = str(session_dir / "raw" / Path(str(raw["path"])).name)
        if raw.get("blocks_index"):
            raw["blocks_index"] = str(session_dir / "raw" / RAW_BLOCK_INDEX_JSON)
        if raw.get("compaction_events"):
            raw["compaction_events"] = str(session_dir / "raw" / RAW_COMPACTION_EVENTS_JSONL)
    raw_blocks = manifest.get("raw_blocks")
    if isinstance(raw_blocks, dict):
        if raw_blocks.get("index"):
            raw_blocks["index"] = str(session_dir / "raw" / RAW_BLOCK_INDEX_JSON)
        if raw_blocks.get("compaction_events"):
            raw_blocks["compaction_events"] = str(session_dir / "raw" / RAW_COMPACTION_EVENTS_JSONL)
        for block in raw_blocks.get("blocks", []) if isinstance(raw_blocks.get("blocks"), list) else []:
            if not isinstance(block, dict):
                continue
            for key in ("path", "plain_path", "compressed_path"):
                if block.get(key):
                    block[key] = str(session_dir / "raw" / RAW_BLOCKS_DIR / Path(str(block[key])).name)
    for segment in manifest.get("segments", []) if isinstance(manifest.get("segments"), list) else []:
        if not isinstance(segment, dict):
            continue
        raw_block = segment.get("raw_block") if isinstance(segment.get("raw_block"), dict) else {}
        for key in ("path", "plain_path", "compressed_path"):
            if raw_block.get(key):
                raw_block[key] = str(session_dir / "raw" / RAW_BLOCKS_DIR / Path(str(raw_block[key])).name)
        if segment.get("markdown"):
            segment["markdown"] = str(session_dir / "segments" / Path(str(segment["markdown"])).name)
        if segment.get("index"):
            segment["index"] = str(session_dir / "segments" / Path(str(segment["index"])).name)
    legacy_raw_source_path = session_dir / "raw" / LEGACY_RAW_SOURCE_JSON
    raw_source_path = session_dir / "raw" / RAW_SOURCE_JSON
    if not raw_source_path.exists() and legacy_raw_source_path.exists():
        legacy_raw_source_path.rename(raw_source_path)
    if legacy_raw_source_path.exists():
        legacy_raw_source_path.unlink()
    refresh_semantic_name_anchors(session_dir, manifest)


def target_session_dir_for_display(aoa_root: Path, display: dict[str, Any]) -> Path:
    label = str(display.get("label") or "").strip()
    return aoa_root / SESSION_ROOT / (label or f"unresolved-session-{compact_stamp()}")


def rebuild_session_labels(aoa_root: Path) -> dict[str, Any]:
    now = utc_now()
    entries: list[dict[str, Any]] = []
    seen_session_ids: set[str] = set()
    source_roots = [aoa_root / LEGACY_SESSION_ROOT, aoa_root / SESSION_ROOT]
    if not any(root.exists() for root in source_roots):
        return {"schema_version": SCHEMA_VERSION, "updated_at": now, "sessions": []}
    for session_root in source_roots:
        if not session_root.exists():
            continue
        for manifest_path in sorted(session_root.glob("*/session.manifest.json")):
            session_dir = manifest_path.parent
            manifest = read_json(manifest_path, {})
            if not isinstance(manifest, dict):
                continue
            session_id = str(manifest.get("session_id") or session_dir.name)
            if session_id in seen_session_ids:
                continue
            seen_session_ids.add(session_id)
            source = manifest.get("source", {}) if isinstance(manifest.get("source"), dict) else {}
            transcript_value = source.get("transcript_path")
            transcript_path = Path(str(transcript_value)) if transcript_value else None
            raw = manifest.get("raw", {}) if isinstance(manifest.get("raw"), dict) else {}
            raw_value = raw.get("path") or session_dir / "raw" / "session.raw.jsonl"
            raw_path = Path(str(raw_value))
            events = parse_raw_event_sample(raw_path) if raw_path.exists() else []
            fallback = str(manifest.get("created_at") or manifest.get("updated_at") or now)
            entry_event = {
                "cwd": source.get("cwd"),
                "model": source.get("model"),
                "permission_mode": source.get("permission_mode"),
            }
            session_date = first_session_date(events, entry_event, transcript_path, fallback)
            title, title_source = session_title(events, entry_event, transcript_path)
            existing_display = manifest.get("display") if isinstance(manifest.get("display"), dict) else {}
            if display_quality(str(existing_display.get("title_source"))) > display_quality(title_source):
                title = str(existing_display.get("title") or title)
                title_source = str(existing_display.get("title_source") or title_source)
            entries.append(
                {
                    "session_id": session_id,
                    "session_dir": session_dir,
                    "manifest": manifest,
                    "manifest_path": manifest_path,
                    "date": session_date,
                    "sort_key": str(manifest.get("created_at") or manifest.get("updated_at") or session_id),
                    "title": title,
                    "title_source": title_source,
                }
            )

    entries.sort(key=lambda item: (item["date"], item["sort_key"], item["session_id"]))
    per_date: defaultdict[str, int] = defaultdict(int)
    relabeled: list[dict[str, Any]] = []
    for entry in entries:
        session_date = str(entry["date"])
        per_date[session_date] += 1
        sequence = per_date[session_date]
        session_dir = entry["session_dir"]
        manifest = entry["manifest"]
        previous_display = manifest.get("display") if isinstance(manifest.get("display"), dict) else {}
        previous_label = str(previous_display.get("label") or manifest.get("session_label") or "")
        title = str(entry["title"])
        label = f"{session_date}__{sequence:03d}__{readable_slug(title)}"
        old_session_dir = entry["session_dir"]
        session_dir = aoa_root / SESSION_ROOT / label
        session_dir = merge_or_move_session_dir(old_session_dir, session_dir)
        manifest_path = session_dir / "session.manifest.json"
        display = {
            "date": session_date,
            "sequence": sequence,
            "title": title,
            "title_source": entry["title_source"],
            "label": label,
            "path": str(session_dir),
            "archive_path": str(session_dir),
            "navigation_path": str(session_dir),
        }
        manifest["schema_version"] = SCHEMA_VERSION
        manifest["session_id"] = entry["session_id"]
        manifest["display"] = display
        manifest["session_label"] = label
        manifest["session_title"] = title
        update_artifact_paths_after_move(session_dir, manifest)
        refresh_session_metadata_generation_identity(manifest)
        write_json(manifest_path, manifest)
        update_registry(aoa_root, manifest, session_dir)
        projection_rebuild = reindex_session_from_raw(
            aoa_root,
            registry_record(manifest, session_dir),
        )
        relabeled.append(
            {
                "session_id": entry["session_id"],
                "label": label,
                "path": str(session_dir),
                "projection_rebuild_status": (
                    projection_rebuild.get("status")
                ),
                "projection_rebuild_diagnostics": (
                    projection_rebuild.get("diagnostics", [])
                ),
            }
        )
    legacy_root = aoa_root / LEGACY_SESSION_ROOT
    if legacy_root.exists():
        try:
            legacy_root.rmdir()
        except OSError:
            pass
    return {"schema_version": SCHEMA_VERSION, "updated_at": now, "sessions": relabeled}


def anchor_for(event: RawEvent) -> str:
    title_slug = safe_slug(event.title.lower(), fallback="event")
    return f"event-{event.event_id}--{event.event_type.lower()}--{title_slug}"


def markdown_escape_fence(raw: str) -> str:
    return raw


def event_relationships(events: list[RawEvent]) -> dict[str, list[dict[str, Any]]]:
    relationships: dict[str, list[dict[str, Any]]] = {event.event_id: [] for event in events}
    by_correlation: dict[str, list[RawEvent]] = defaultdict(list)
    for idx, event in enumerate(events):
        if idx > 0:
            relationships[event.event_id].append({"rel": "previous_event", "event_id": events[idx - 1].event_id})
        if idx + 1 < len(events):
            relationships[event.event_id].append({"rel": "next_event", "event_id": events[idx + 1].event_id})
        if event.correlation_id:
            by_correlation[event.correlation_id].append(event)

    for correlation_id, related in by_correlation.items():
        calls = [
            event
            for event in related
            if event.facets.get("payload_type") in {"function_call", "tool_call", "custom_tool_call"}
        ]
        outputs = [
            event
            for event in related
            if event.facets.get("payload_type") in {
                "function_call_output",
                "tool_call_output",
                "custom_tool_call_output",
            }
        ]
        agent_activity_statuses = [
            event
            for event in related
            if task_episode_is_correlated_agent_activity_status(event)
        ]
        for call in calls:
            for status in agent_activity_statuses:
                if call.event_id == status.event_id:
                    continue
                relationships[call.event_id].append(
                    {
                        "rel": "has_correlated_status",
                        "event_id": status.event_id,
                        "correlation_id": correlation_id,
                    }
                )
            for output in outputs:
                if call.event_id == output.event_id:
                    continue
                relationships[call.event_id].append({"rel": "answered_by", "event_id": output.event_id, "correlation_id": correlation_id})
                relationships[output.event_id].append({"rel": "responds_to", "event_id": call.event_id, "correlation_id": correlation_id})
    return relationships


def event_route_signals(event: RawEvent) -> list[dict[str, Any]]:
    route_signals = event.facets.get("route_signals") if isinstance(event.facets, dict) else None
    if not isinstance(route_signals, list):
        return []
    return [signal for signal in route_signals if isinstance(signal, dict) and signal.get("layer") and signal.get("key")]


def route_signal_token(layer: str, key: str) -> str:
    return f"{layer}:{key}"


def route_signal_counts_for_events(events: list[RawEvent]) -> dict[str, dict[str, int]]:
    counts: dict[str, Counter[str]] = defaultdict(Counter)
    for event in events:
        for signal in event_route_signals(event):
            counts[str(signal["layer"])][str(signal["key"])] += 1
    return {layer: dict(sorted(counter.items())) for layer, counter in sorted(counts.items())}


TOKEN_ACCOUNTING_COUNT_FIELDS = [
    "input_tokens",
    "output_tokens",
    "total_tokens",
    "cached_tokens",
    "reasoning_tokens",
    "context_tokens",
    "context_window_tokens",
]
TOKEN_ACCOUNTING_CONTEXT_FIELDS = {"context_tokens", "context_window_tokens"}


def token_accounting_int(value: Any) -> int | None:
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, int):
        return value if value >= 0 else None
    if isinstance(value, float):
        if value >= 0 and value.is_integer():
            return int(value)
        return None
    text = str(value).strip()
    if re.fullmatch(r"\d+", text):
        return int(text)
    return None


def token_count_from_keys(payload: dict[str, Any], keys: Iterable[str]) -> int | None:
    for key in keys:
        if key in payload:
            value = token_accounting_int(payload.get(key))
            if value is not None:
                return value
    return None


def token_accounting_counts_from_payload(payload: dict[str, Any], *, allow_generic_tokens: bool = False) -> dict[str, int]:
    details: list[dict[str, Any]] = []
    for key in ("prompt_tokens_details", "input_tokens_details", "completion_tokens_details", "output_tokens_details"):
        value = payload.get(key)
        if isinstance(value, dict):
            details.append(value)

    counts: dict[str, int] = {}
    mapped = {
        "input_tokens": token_count_from_keys(payload, ("input_tokens", "prompt_tokens")),
        "output_tokens": token_count_from_keys(payload, ("output_tokens", "completion_tokens")),
        "total_tokens": token_count_from_keys(
            payload,
            ("total_tokens", "total_token_count", "token_count", "tokens") if allow_generic_tokens else ("total_tokens", "total_token_count"),
        ),
        "cached_tokens": token_count_from_keys(payload, ("cached_tokens", "input_cached_tokens", "cached_input_tokens", "prompt_cached_tokens")),
        "reasoning_tokens": token_count_from_keys(payload, ("reasoning_tokens", "output_reasoning_tokens", "reasoning_output_tokens", "completion_reasoning_tokens")),
        "context_tokens": token_count_from_keys(payload, ("context_tokens", "context_used_tokens", "used_tokens")),
        "context_window_tokens": token_count_from_keys(payload, ("context_window_tokens", "model_context_window_tokens", "context_window", "model_context_window")),
    }
    for key, value in mapped.items():
        if value is not None:
            counts[key] = value

    for detail in details:
        cached = token_count_from_keys(detail, ("cached_tokens", "cache_read_tokens", "cache_creation_tokens"))
        if cached is not None:
            counts["cached_tokens"] = counts.get("cached_tokens", 0) + cached
        reasoning = token_count_from_keys(detail, ("reasoning_tokens",))
        if reasoning is not None:
            counts["reasoning_tokens"] = counts.get("reasoning_tokens", 0) + reasoning

    if "total_tokens" not in counts:
        input_tokens = counts.get("input_tokens")
        output_tokens = counts.get("output_tokens")
        if input_tokens is not None and output_tokens is not None:
            counts["total_tokens"] = input_tokens + output_tokens
    return {key: value for key, value in counts.items() if value is not None}


def payload_has_primary_token_counts(payload: dict[str, Any], *, allow_generic_tokens: bool = False) -> bool:
    primary_keys = {
        "input_tokens",
        "prompt_tokens",
        "output_tokens",
        "completion_tokens",
        "total_tokens",
        "total_token_count",
        "token_count",
    }
    if allow_generic_tokens:
        primary_keys.add("tokens")
    return any(token_accounting_int(payload.get(key)) is not None for key in primary_keys if key in payload)


def token_accounting_usage_candidates(value: Any, *, path: str = "$", depth: int = 0) -> list[tuple[str, dict[str, Any]]]:
    if depth > 5:
        return []
    candidates: list[tuple[str, dict[str, Any]]] = []
    if isinstance(value, dict):
        payload_type = str(value.get("type") or "")
        allow_generic = payload_type == "token_count" or path.endswith(".usage")
        if payload_has_primary_token_counts(value, allow_generic_tokens=allow_generic):
            candidates.append((path, value))
        for key, child in value.items():
            if isinstance(child, (dict, list)):
                candidates.extend(token_accounting_usage_candidates(child, path=f"{path}.{key}", depth=depth + 1))
    elif isinstance(value, list):
        for idx, child in enumerate(value[:64]):
            if isinstance(child, (dict, list)):
                candidates.extend(token_accounting_usage_candidates(child, path=f"{path}[{idx}]", depth=depth + 1))
    return candidates


def token_accounting_privacy() -> dict[str, bool]:
    return {
        "raw_text_logged": False,
        "prompt_text_logged": False,
        "stores_counts_only": True,
        "stores_refs": True,
    }


def token_accounting_observation(
    *,
    event: RawEvent,
    count_basis: str,
    source_kind: str,
    counts: dict[str, int],
    tokenizer_id: str | None = None,
    model_id: str | None = None,
    payload_path: str | None = None,
    count_semantics: str | None = None,
) -> dict[str, Any]:
    payload = event.parsed.get("payload") if isinstance(event.parsed, dict) else {}
    if not model_id and isinstance(payload, dict):
        model_id = str(payload.get("model") or payload.get("model_id") or "") or None
    item: dict[str, Any] = {
        "schema": TOKEN_ACCOUNTING_CONTRACT,
        "schema_version": TOKEN_ACCOUNTING_SCHEMA_VERSION,
        "event_id": event.event_id,
        "raw_ref": f"raw:line:{event.line_no}",
        "timestamp": event.timestamp,
        "source_type": event.source_type,
        "event_type": event.event_type,
        "source_kind": source_kind,
        "count_basis": count_basis,
        "privacy": token_accounting_privacy(),
    }
    if tokenizer_id:
        item["tokenizer_id"] = tokenizer_id
    if model_id:
        item["model_id"] = model_id
    if payload_path:
        item["payload_path"] = payload_path
    if count_semantics:
        item["count_semantics"] = count_semantics
    for key in TOKEN_ACCOUNTING_COUNT_FIELDS:
        if key in counts:
            item[key] = counts[key]
    return item


def estimated_semantic_token_count(text: str) -> int:
    return len(re.findall(r"\w+|[^\w\s]", text, flags=re.UNICODE))


def token_accounting_for_codex_token_count(event: RawEvent, payload: dict[str, Any]) -> list[dict[str, Any]]:
    info = payload.get("info") if isinstance(payload.get("info"), dict) else {}
    source_payload: dict[str, Any] | None = None
    payload_path = "payload"
    source_kind = "codex_token_count"
    count_semantics: str | None = None

    if isinstance(info.get("last_token_usage"), dict):
        source_payload = info["last_token_usage"]
        payload_path = "payload.info.last_token_usage"
        source_kind = "codex_last_token_usage"
    elif payload_has_primary_token_counts(payload, allow_generic_tokens=True):
        source_payload = payload
    elif isinstance(info.get("total_token_usage"), dict):
        source_payload = info["total_token_usage"]
        payload_path = "payload.info.total_token_usage"
        source_kind = "codex_total_token_usage_snapshot"
        count_semantics = "cumulative_snapshot"

    if not isinstance(source_payload, dict):
        return []

    counts = token_accounting_counts_from_payload(source_payload, allow_generic_tokens=True)
    context_window = token_count_from_keys(info, ("context_window_tokens", "model_context_window_tokens", "context_window", "model_context_window"))
    if "context_tokens" not in counts and token_accounting_int(counts.get("input_tokens")) is not None:
        counts["context_tokens"] = int(counts["input_tokens"])
    if context_window is not None:
        counts["context_window_tokens"] = context_window
    if not counts:
        return []
    return [
        token_accounting_observation(
            event=event,
            count_basis="provider_reported",
            source_kind=source_kind,
            counts=counts,
            model_id=str(payload.get("model") or payload.get("model_id") or "") or None,
            payload_path=payload_path,
            count_semantics=count_semantics,
        )
    ]


def token_accounting_for_event(event: RawEvent) -> list[dict[str, Any]]:
    observations: list[dict[str, Any]] = []
    parsed = event.parsed if isinstance(event.parsed, dict) else {}
    payload = parsed.get("payload") if isinstance(parsed.get("payload"), dict) else {}
    if isinstance(payload, dict):
        if str(payload.get("type") or "") == "token_count":
            observations = token_accounting_for_codex_token_count(event, payload)
            if observations:
                return observations
        for payload_path, candidate in token_accounting_usage_candidates(payload, path="payload"):
            payload_type = str(candidate.get("type") or payload.get("type") or "")
            counts = token_accounting_counts_from_payload(candidate, allow_generic_tokens=payload_type == "token_count" or payload_path.endswith(".usage"))
            if not counts:
                continue
            source_kind = "codex_token_count" if payload_type == "token_count" else "provider_usage"
            observations.append(
                token_accounting_observation(
                    event=event,
                    count_basis="provider_reported",
                    source_kind=source_kind,
                    counts=counts,
                    model_id=str(candidate.get("model") or payload.get("model") or "") or None,
                    payload_path=payload_path,
                )
            )

    if observations:
        return observations

    text = semantic_text_for_classification(event.source_type, payload)
    estimated = estimated_semantic_token_count(text)
    if estimated <= 0:
        return []
    return [
        token_accounting_observation(
            event=event,
            count_basis="estimated",
            source_kind="semantic_text_estimate",
            counts={"total_tokens": estimated},
            tokenizer_id=TOKEN_ACCOUNTING_ESTIMATOR_ID,
        )
    ]


def token_accounting_summary_for_observations(
    observations: list[dict[str, Any]],
    *,
    scope: dict[str, Any],
    include_observations: bool = False,
) -> dict[str, Any]:
    totals_by_basis: dict[str, dict[str, int]] = {}
    count_by_basis: Counter[str] = Counter()
    observed_event_ids: set[str] = set()
    estimated_event_ids: set[str] = set()
    provider_event_ids: set[str] = set()
    for observation in observations:
        basis = str(observation.get("count_basis") or "unknown")
        count_by_basis[basis] += 1
        event_id = str(observation.get("event_id") or "")
        if event_id:
            if basis == "estimated":
                estimated_event_ids.add(event_id)
            if basis == "provider_reported":
                provider_event_ids.add(event_id)
            observed_event_ids.add(event_id)
        totals = totals_by_basis.setdefault(basis, {})
        cumulative_snapshot = str(observation.get("count_semantics") or "") == "cumulative_snapshot"
        for key in TOKEN_ACCOUNTING_COUNT_FIELDS:
            value = token_accounting_int(observation.get(key))
            if value is not None:
                if key in TOKEN_ACCOUNTING_CONTEXT_FIELDS or cumulative_snapshot:
                    totals[key] = max(totals.get(key, 0), value)
                else:
                    totals[key] = totals.get(key, 0) + value
    payload: dict[str, Any] = {
        "schema": TOKEN_ACCOUNTING_CONTRACT,
        "schema_version": TOKEN_ACCOUNTING_SCHEMA_VERSION,
        "generator_version": TOKEN_ACCOUNTING_GENERATOR_VERSION,
        "scope": scope,
        "privacy": token_accounting_privacy(),
        "observed_event_count": len(observed_event_ids),
        "provider_reported_event_count": len(provider_event_ids),
        "estimated_event_count": len(estimated_event_ids),
        "observation_count": len(observations),
        "count_by_basis": dict(sorted(count_by_basis.items())),
        "totals_by_basis": {basis: dict(sorted(values.items())) for basis, values in sorted(totals_by_basis.items())},
        "basis_rule": "provider_reported and estimated counts are separate ledgers; estimates are never promoted to exact.",
    }
    if include_observations:
        payload["observations"] = observations
    return payload


def token_accounting_summary_for_events(
    events: list[RawEvent],
    *,
    scope: dict[str, Any],
    include_observations: bool = False,
) -> dict[str, Any]:
    observations: list[dict[str, Any]] = []
    for event in events:
        observations.extend(token_accounting_for_event(event))
    return token_accounting_summary_for_observations(observations, scope=scope, include_observations=include_observations)


def token_accounting_summary_for_session(
    events: list[RawEvent],
    *,
    session_id: str,
    include_observations: bool = False,
) -> dict[str, Any]:
    return token_accounting_summary_for_events(
        events,
        scope={"kind": "session", "session_id": session_id},
        include_observations=include_observations,
    )


def token_accounting_empty_summary(*, scope: dict[str, Any]) -> dict[str, Any]:
    return token_accounting_summary_for_observations([], scope=scope)


def token_accounting_rescope_summary(
    summary: dict[str, Any],
    *,
    scope: dict[str, Any],
) -> dict[str, Any]:
    """Reuse aggregate counts under an equivalent component scope."""
    return {
        **{
            key: value
            for key, value in summary.items()
            if key not in {"scope", "observations"}
        },
        "scope": scope,
    }


def token_accounting_merge_summaries(summaries: Iterable[dict[str, Any]], *, scope: dict[str, Any]) -> dict[str, Any]:
    totals_by_basis: dict[str, dict[str, int]] = {}
    count_by_basis: Counter[str] = Counter()
    observed_event_count = 0
    provider_reported_event_count = 0
    estimated_event_count = 0
    observation_count = 0
    for summary in summaries:
        if not isinstance(summary, dict):
            continue
        observed_event_count += int(token_accounting_int(summary.get("observed_event_count")) or 0)
        provider_reported_event_count += int(token_accounting_int(summary.get("provider_reported_event_count")) or 0)
        estimated_event_count += int(token_accounting_int(summary.get("estimated_event_count")) or 0)
        observation_count += int(token_accounting_int(summary.get("observation_count")) or 0)
        for basis, count in (summary.get("count_by_basis") if isinstance(summary.get("count_by_basis"), dict) else {}).items():
            normalized = str(basis or "unknown")
            count_by_basis[normalized] += int(token_accounting_int(count) or 0)
        for basis, totals in (summary.get("totals_by_basis") if isinstance(summary.get("totals_by_basis"), dict) else {}).items():
            target = totals_by_basis.setdefault(str(basis or "unknown"), {})
            if not isinstance(totals, dict):
                continue
            for key in TOKEN_ACCOUNTING_COUNT_FIELDS:
                value = token_accounting_int(totals.get(key))
                if value is not None:
                    if key in TOKEN_ACCOUNTING_CONTEXT_FIELDS:
                        target[key] = max(target.get(key, 0), value)
                    else:
                        target[key] = target.get(key, 0) + value
    return {
        "schema": TOKEN_ACCOUNTING_CONTRACT,
        "schema_version": TOKEN_ACCOUNTING_SCHEMA_VERSION,
        "generator_version": TOKEN_ACCOUNTING_GENERATOR_VERSION,
        "scope": scope,
        "privacy": token_accounting_privacy(),
        "observed_event_count": observed_event_count,
        "provider_reported_event_count": provider_reported_event_count,
        "estimated_event_count": estimated_event_count,
        "observation_count": observation_count,
        "count_by_basis": dict(sorted(count_by_basis.items())),
        "totals_by_basis": {basis: dict(sorted(values.items())) for basis, values in sorted(totals_by_basis.items())},
        "basis_rule": "provider_reported and estimated counts are separate ledgers; estimates are never promoted to exact.",
    }


def conversation_act_counts_for_events(events: list[RawEvent]) -> dict[str, int]:
    return dict(
        sorted(
            Counter(
                str(event.facets.get("conversation_act", {}).get("kind"))
                for event in events
                if isinstance(event.facets.get("conversation_act"), dict) and event.facets["conversation_act"].get("kind")
            ).items()
        )
    )


def session_act_counts_for_events(events: list[RawEvent]) -> dict[str, int]:
    return dict(
        sorted(
            Counter(
                str(event.facets.get("session_act", {}).get("kind"))
                for event in events
                if isinstance(event.facets.get("session_act"), dict) and event.facets["session_act"].get("kind")
            ).items()
        )
    )


def agent_event_for_event(event: RawEvent) -> dict[str, Any]:
    return event.facets.get("agent_event") if isinstance(event.facets.get("agent_event"), dict) else {}


def agent_event_class_for_event(event: RawEvent) -> str:
    agent_event = agent_event_for_event(event)
    return str(agent_event.get("class") or "")


def agent_event_counts_for_events(events: list[RawEvent]) -> dict[str, int]:
    return dict(
        sorted(
            Counter(
                agent_class
                for agent_class in (agent_event_class_for_event(event) for event in events)
                if agent_class
            ).items()
        )
    )


def task_episode_counts_for_episodes(episodes: list[dict[str, Any]]) -> dict[str, Any]:
    status_counts = Counter(str(episode.get("status") or "unknown") for episode in episodes)
    confidence_counts = Counter(str(episode.get("confidence") or "unknown") for episode in episodes)
    return {
        "total": len(episodes),
        "by_status": dict(sorted(status_counts.items())),
        "by_confidence": dict(sorted(confidence_counts.items())),
    }


def segment_for_line(segments: list[dict[str, Any]], line_no: int) -> dict[str, Any]:
    # Generated segment manifests are ordered by non-overlapping source range.
    # Episode construction resolves several refs per event, so a linear scan
    # makes the full reduction proportional to events times segment count.
    low = 0
    high = len(segments)
    while low < high:
        midpoint = (low + high) // 2
        candidate = segments[midpoint]
        source_range = (
            candidate.get("source_range")
            if isinstance(candidate, dict)
            and isinstance(candidate.get("source_range"), dict)
            else {}
        )
        if int_value(source_range.get("from_line"), 0) <= line_no:
            low = midpoint + 1
        else:
            high = midpoint
    if low <= 0:
        return {}
    segment = segments[low - 1]
    if not isinstance(segment, dict):
        return {}
    source_range = (
        segment.get("source_range")
        if isinstance(segment.get("source_range"), dict)
        else {}
    )
    from_line = int_value(source_range.get("from_line"), 0)
    to_line = int_value(source_range.get("to_line"), 0)
    if from_line and to_line and from_line <= line_no <= to_line:
        return segment
    return {}


def task_episode_event_ref(event: RawEvent, segments: list[dict[str, Any]]) -> dict[str, Any]:
    segment = segment_for_line(segments, event.line_no)
    conversation_act = event.facets.get("conversation_act") if isinstance(event.facets.get("conversation_act"), dict) else {}
    session_act = event.facets.get("session_act") if isinstance(event.facets.get("session_act"), dict) else {}
    agent_event = agent_event_for_event(event)
    ref = {
        "event_id": event.event_id,
        "line": event.line_no,
        "raw_ref": f"raw:line:{event.line_no}",
        "segment_id": str(segment.get("segment_id") or ""),
        "segment_ref": str(segment.get("markdown") or ""),
        "segment_index": str(segment.get("index") or ""),
        "event_type": event.event_type,
        "source_type": event.source_type,
        "title": event.title,
        "timestamp": event.timestamp,
        "conversation_act": str(conversation_act.get("kind") or ""),
        "session_act": str(session_act.get("kind") or ""),
        "agent_event": str(agent_event.get("class") or ""),
    }
    return {key: value for key, value in ref.items() if value not in {"", None}}


def append_task_episode_ref(episode: dict[str, Any], bucket: str, event: RawEvent, segments: list[dict[str, Any]]) -> None:
    refs = episode.setdefault(bucket, [])
    if not isinstance(refs, list):
        return
    displaced = bounded_head_tail_append(
        refs,
        task_episode_event_ref(event, segments),
        limit=TASK_EPISODE_REF_LIMIT_PER_BUCKET,
    )
    if displaced:
        omitted = episode.setdefault("omitted_ref_counts", {})
        if isinstance(omitted, dict):
            omitted[bucket] = int_value(omitted.get(bucket), 0) + 1


def new_task_episode(
    *,
    ordinal: int,
    user_event: RawEvent,
    segments: list[dict[str, Any]],
    previous_episode_id: str,
    transition_reason: str,
) -> dict[str, Any]:
    conversation_act = user_event.facets.get("conversation_act") if isinstance(user_event.facets.get("conversation_act"), dict) else {}
    flags: list[str] = []
    canonical_user = (
        user_event.source_type == "response_item"
        and isinstance(user_event.parsed, dict)
        and isinstance(user_event.parsed.get("payload"), dict)
        and str(user_event.parsed["payload"].get("type") or "") == "message"
        and str(user_event.parsed["payload"].get("role") or "") == "user"
    )
    if not canonical_user:
        flags.append("noncanonical_user_start")
    if previous_episode_id:
        flags.append("transition_from_previous_episode")
    episode_id = f"task-{ordinal:04d}"
    start_ref = task_episode_event_ref(user_event, segments)
    return {
        "schema_version": TASK_EPISODE_SCHEMA_VERSION,
        "episode_id": episode_id,
        "boundary_policy": {
            "version": TASK_EPISODE_BOUNDARY_POLICY_VERSION,
            "semantic_unit": "work_lifecycle",
            "coordinate_only": ["turn", "segment", "compaction"],
            "transport_envelopes_are_boundaries": False,
        },
        "status": "open",
        "confidence": "high" if canonical_user else "medium",
        "ambiguity_flags": flags,
        "transition": {
            "reason": transition_reason,
            "previous_episode_id": previous_episode_id,
            "user_conversation_act": str(conversation_act.get("kind") or ""),
        },
        "start_user_ref": start_ref,
        "start_ref_role": (
            "canonical_user_intent"
            if canonical_user
            else "noncanonical_boundary"
        ),
        "intent_refs": [start_ref],
        "semantic_continuations": [],
        "event_range": {
            "from_event_id": user_event.event_id,
            "to_event_id": user_event.event_id,
            "from_line": user_event.line_no,
            "to_line": user_event.line_no,
        },
        "time_span": {
            "from": user_event.timestamp or "",
            "to": user_event.timestamp or "",
        },
        "reasoning_refs": [],
        "plan_refs": [],
        "progress_refs": [],
        "answer_refs": [],
        "action_refs": [],
        "tool_refs": [],
        "verification_refs": [],
        "error_refs": [],
        "closeout_refs": [],
        "blocker_refs": [],
        "transition_refs": [],
        "correlation_chain": [],
        "omitted_ref_counts": {},
        "_representation_candidates": [],
    }


def close_open_task_episode_for_transition(
    episode: dict[str, Any],
    transition_event: RawEvent,
    segments: list[dict[str, Any]],
    *,
    structural_lineage_boundary: bool = False,
) -> None:
    if episode.get("status") == "open":
        episode["status"] = "interrupted"
        flags = episode.setdefault("ambiguity_flags", [])
        transition_flag = (
            "bounded_by_structural_lineage_boundary"
            if structural_lineage_boundary
            else "interrupted_by_new_user_prompt"
        )
        if isinstance(flags, list) and transition_flag not in flags:
            flags.append(transition_flag)
    append_task_episode_ref(episode, "transition_refs", transition_event, segments)


def update_task_episode_range(episode: dict[str, Any], event: RawEvent) -> None:
    event_range = episode.setdefault("event_range", {})
    if not isinstance(event_range, dict):
        return
    if not event_range.get("from_event_id"):
        event_range["from_event_id"] = event.event_id
        event_range["from_line"] = event.line_no
    event_range["to_event_id"] = event.event_id
    event_range["to_line"] = event.line_no
    time_span = episode.setdefault("time_span", {})
    if isinstance(time_span, dict) and event.timestamp:
        if not time_span.get("from"):
            time_span["from"] = event.timestamp
        time_span["to"] = event.timestamp


def task_episode_payload(event: RawEvent) -> dict[str, Any]:
    if not isinstance(event.parsed, dict):
        return {}
    payload = event.parsed.get("payload")
    return payload if isinstance(payload, dict) else {}


def task_episode_source_lane(event: RawEvent) -> str:
    payload = task_episode_payload(event)
    payload_type = str(payload.get("type") or "")
    if event.source_type == "response_item":
        if payload_type == "message":
            role = str(payload.get("role") or "unknown")
            return f"message_{role}"
        if payload_type == "agent_message":
            return (
                "structured_inter_agent_task"
                if event.event_type == "INTER_AGENT_TASK"
                else "structured_inter_agent_message"
            )
        if payload_type in {"function_call", "tool_call", "custom_tool_call"}:
            return "structured_tool_call"
        if payload_type in {"function_call_output", "tool_call_output", "custom_tool_call_output"}:
            return "structured_tool_result"
        if payload_type == "reasoning":
            return "assistant_reasoning_summary"
    if event.source_type == "event_msg":
        if payload_type == "sub_agent_activity" and event.correlation_id:
            return "structured_agent_activity_status"
        return "event_msg_stream"
    if event.source_type in {"compacted", "turn_context"}:
        return "generated_context_summary"
    return str(event.source_type or "unknown")


def task_episode_is_structured_result(event: RawEvent) -> bool:
    payload_type = str(task_episode_payload(event).get("type") or "")
    return payload_type in {"function_call_output", "tool_call_output", "custom_tool_call_output"}


def task_episode_is_structured_verification_action(
    event: RawEvent,
) -> bool:
    payload_type = str(task_episode_payload(event).get("type") or "")
    return bool(
        payload_type
        in {"function_call", "tool_call", "custom_tool_call"}
        and (
            str(event.facets.get("command_kind") or "")
            == "verification"
            or "verification_command" in event.tags
        )
        and event.correlation_id
    )


def task_episode_is_correlation_matched_verification_result(
    event: RawEvent,
    linked_action_record: dict[str, Any],
    *,
    semantic_text: str | None = None,
) -> bool:
    """Require a matched verification action and an explicit semantic success."""
    return bool(
        task_episode_is_structured_result(event)
        and event.correlation_id
        and linked_action_record.get("verification_action") is True
        and event.outcome not in {"failed", "blocked"}
        and has_success_signal(
            (
                event_semantic_text(event)
                if semantic_text is None
                else semantic_text
            ).casefold()
        )
    )


def task_episode_is_correlated_agent_activity_status(event: RawEvent) -> bool:
    payload = task_episode_payload(event)
    return bool(
        event.event_type == "CONTEXT_STATE"
        and event.source_type == "event_msg"
        and str(payload.get("type") or "") == "sub_agent_activity"
        and event.correlation_id
    )


def task_episode_representation_role(
    event: RawEvent,
    agent_class: str,
    *,
    semantic_text: str | None = None,
) -> tuple[str, int, str]:
    payload = task_episode_payload(event)
    payload_type = str(payload.get("type") or "")
    message_role = str(payload.get("role") or "") if payload_type == "message" else ""
    if event.event_type == "USER_INTENT" and message_role == "user":
        return "intents", 100, "canonical_user_intent"
    if event.event_type == "INTER_AGENT_TASK":
        return (
            "intents",
            95,
            "structured_inter_agent_task_delegation",
        )
    if payload_type in {"function_call", "tool_call", "custom_tool_call"} or event.event_type in {"COMMAND", "FILE_READ", "FILE_WRITE", "DIFF", "TOOL_CALL"}:
        return "actions", 85, "structured_operational_action"
    if task_episode_is_structured_result(event):
        if event.outcome in {"failed", "blocked"}:
            return "failures", 100, "structured_failed_result"
        return "outcomes", 80, "structured_result_status"
    if task_episode_is_correlated_agent_activity_status(event):
        return "outcomes", 90, "structured_correlated_status"
    if event.event_type == "ERROR" or event.outcome in {"failed", "blocked"} or agent_class == "assistant_blocker_report":
        return "failures", 100, "failure_or_blocker"
    if event.event_type == "DECISION" or agent_class == "assistant_decision":
        return "outcomes", 95, "assistant_decision"
    if event.event_type == "VERIFICATION" or agent_class == "assistant_verification_report":
        return "verification", 90, "verification_observation"
    if agent_class == "assistant_final_closeout":
        return "outcomes", 100, "assistant_final_closeout"
    if agent_class == "assistant_plan":
        return "plans", 70, "assistant_plan"
    if agent_class in {
        "assistant_answer",
        "assistant_progress_update",
        "assistant_correction_ack",
        "assistant_checkpoint",
        "assistant_process_lesson",
        "assistant_handoff",
        "assistant_resume",
        "assistant_handoff_or_resume",
    }:
        return "outcomes", 72, "assistant_observation"
    if agent_class == "assistant_reasoning_boundary" and (
        event_semantic_text(event)
        if semantic_text is None
        else semantic_text
    ):
        return "reasoning", 35, "assistant_reasoning_summary"
    return "", 0, "not_semantically_admitted"


def task_episode_inter_agent_task_text(event: RawEvent) -> str:
    metadata = (
        event.facets.get("inter_agent_message")
        if isinstance(event.facets.get("inter_agent_message"), dict)
        else {}
    )
    clear_payload = re.sub(
        r"\s+",
        " ",
        str(metadata.get("clear_payload_text") or ""),
    ).strip()
    author = str(metadata.get("author") or "")
    recipient = str(metadata.get("recipient") or "")
    prefix = "Inter-agent NEW_TASK delegation"
    if author or recipient:
        prefix += (
            f" from {author or 'unknown'} to {recipient or 'unknown'}"
        )
    if clear_payload:
        return short_text(
            f"{prefix}: {clear_payload}",
            max_chars=TASK_EPISODE_REPRESENTATION_MAX_CHARS,
        )
    content_status = str(
        metadata.get("content_status") or "transport_envelope_only"
    )
    return (
        f"{prefix}; task content status={content_status}; "
        "do not infer encrypted or absent task details"
    )


def task_episode_result_status_text(event: RawEvent, linked_action: str = "") -> str:
    action = short_text(linked_action, max_chars=500).strip()
    status = str(event.outcome or "observed")
    correlation = str(event.correlation_id or "")
    if action:
        return f"{action} -> {status}" + (f" [{correlation}]" if correlation else "")
    return f"structured result: {status}" + (f" [{correlation}]" if correlation else "")


def task_episode_agent_activity_status_text(
    event: RawEvent,
    linked_action: str = "",
) -> str:
    payload = task_episode_payload(event)
    action = short_text(linked_action, max_chars=500).strip()
    kind = short_text(payload.get("kind") or "unknown", max_chars=80)
    agent_path = short_text(payload.get("agent_path") or "", max_chars=160)
    correlation = str(event.correlation_id or "")
    details = [f"kind={kind}"]
    if agent_path:
        details.append(f"agent_path={agent_path}")
    status = "structured agent activity status: " + "; ".join(details)
    if action:
        status = f"{action} -> {status}"
    if correlation:
        status += f" [{correlation}]"
    return status


def task_episode_compact_success_observation_text(
    event: RawEvent,
    *,
    linked_action: str,
    linked_action_event_type: str,
) -> str:
    """Admit small command facts without turning source/document dumps into episode prose."""
    if not task_episode_is_structured_result(event) or event.outcome in {"failed", "blocked"}:
        return ""
    if linked_action_event_type == "FILE_READ":
        return ""
    output = task_episode_payload(event).get("output")
    text = str(output or "").strip()
    if not text:
        return ""
    lines = text.splitlines()
    if len(text) > TASK_EPISODE_COMPACT_SUCCESS_OUTPUT_MAX_CHARS or len(lines) > TASK_EPISODE_COMPACT_SUCCESS_OUTPUT_MAX_LINES:
        return ""
    lowered = text.casefold()
    if any(marker in lowered for marker in ("output truncated", "truncated after", "remaining output omitted")):
        return ""
    output_marker = re.search(r"(?:^|\n)Output:\s*(.*)\Z", text, flags=re.DOTALL)
    observation = output_marker.group(1).strip() if output_marker else text
    if not observation:
        return ""
    observation = derived_text_privacy_text(observation)
    return search_doc_text(
        [
            task_episode_result_status_text(event, linked_action),
            f"compact successful output observation: {observation}",
        ],
        max_chars=TASK_EPISODE_REPRESENTATION_MAX_CHARS,
    )


