TASK_EPISODE_RETRIEVAL_CONTROL_APIS = {
    "archived_session_exact_search": "archived-raw-search",
    "episode_semantic_query_terms": "episode-search",
    "episode_semantic_required_exact_anchors": "episode-search",
    "episode_semantic_search": "episode-search",
    "live_tail_episode_search": "live-tail-search",
    "live_tail_exact_search": "live-tail-search",
    "search_sessions": "search",
}
TASK_EPISODE_RAW_TRANSCRIPT_SEARCH_EXECUTABLES = frozenset(
    {"ack", "ag", "grep", "rg", "ripgrep"}
)
TASK_EPISODE_RAW_TRANSCRIPT_READ_EXECUTABLES = frozenset(
    {"awk", "cat", "head", "jq", "python", "python3", "sed", "tail"}
)


def task_episode_raw_transcript_retrieval_control(semantic: str) -> str:
    """Classify direct raw-transcript inspection used to select retrieval gold."""
    text = str(semantic or "").casefold()
    codex_raw_path = (
        "/.codex/sessions/" in text
        and ".jsonl" in text
    )
    archived_raw_path = (
        "/.aoa/sessions/" in text
        and (
            "/raw/" in text
            or "session.raw.jsonl" in text
            or ".raw.jsonl" in text
        )
    )
    if not (codex_raw_path or archived_raw_path):
        return ""
    executable_tokens = set(
        re.findall(r"(?<![a-z0-9_.-])([a-z][a-z0-9_.-]*)(?=\s)", text)
    )
    executable_names = {
        Path(token).name
        for token in executable_tokens
    }
    if executable_names & TASK_EPISODE_RAW_TRANSCRIPT_SEARCH_EXECUTABLES:
        return "raw-transcript-search"
    if executable_names & TASK_EPISODE_RAW_TRANSCRIPT_READ_EXECUTABLES:
        return "raw-transcript-read"
    return ""


def task_episode_retrieval_control_semantic(semantic: str) -> str:
    semantic = str(semantic or "").casefold()
    mcp_wrapper = re.search(
        r"\bmcp__aoa_session_memory__(aoa_session_[a-z0-9_]+)\s*\(",
        semantic,
    )
    if mcp_wrapper:
        return str(mcp_wrapper.group(1) or "search")
    for match in re.finditer(r"\baoa_session_memory\.py\b", semantic):
        # Shell strings and argv arrays differ only in punctuation after the script
        # token.  Tokenize one bounded suffix instead of requiring whitespace so a
        # retrieval batch cannot re-enter its own query text as topical evidence.
        suffix = semantic[match.end() : match.end() + 192]
        for token in re.findall(r"[a-z][a-z0-9-]*", suffix):
            if token in TASK_EPISODE_RETRIEVAL_CONTROL_COMMANDS:
                return token
    for api_name, command in TASK_EPISODE_RETRIEVAL_CONTROL_APIS.items():
        if re.search(rf"\b(?:[a-z_][a-z0-9_]*\.)?{re.escape(api_name)}\s*\(", semantic):
            return command
    if (
        ("aoa-search.sqlite3" in semantic or "/.aoa/search/" in semantic)
        and "select" in semantic
        and any(
            table in semantic
            for table in ("documents_fts", "episode_semantic_fts", "exact_literal_postings_fts")
        )
    ):
        return "search"
    return task_episode_raw_transcript_retrieval_control(semantic)


def task_episode_retrieval_control_structured_payload(
    payload: dict[str, Any],
) -> str:
    """Recognize the access-plane tool from structure before event classification."""
    payload_type = str(payload.get("type") or "")
    tool_name = ""
    if payload_type in {"function_call", "tool_call", "custom_tool_call"}:
        tool_name = str(payload.get("name") or "")
    elif payload_type.startswith("mcp_tool_call_"):
        invocation = (
            payload.get("invocation")
            if isinstance(payload.get("invocation"), dict)
            else {}
        )
        tool_name = str(
            invocation.get("tool")
            or payload.get("tool")
            or ""
        )
    else:
        return ""
    namespace_prefix = "mcp__aoa_session_memory__"
    if tool_name.startswith(namespace_prefix):
        tool_name = tool_name[len(namespace_prefix) :]
    if re.fullmatch(r"aoa_session_[a-z0-9_]+", tool_name):
        return tool_name
    return ""


def task_episode_retrieval_control_command(
    event: RawEvent,
    *,
    semantic_text: str | None = None,
) -> str:
    payload = task_episode_payload(event)
    structured_control = task_episode_retrieval_control_structured_payload(payload)
    if structured_control:
        return structured_control
    structured_action = str(payload.get("type") or "") in {
        "function_call",
        "tool_call",
        "custom_tool_call",
    }
    if not structured_action and event.event_type not in {"COMMAND", "FILE_READ", "TOOL_CALL"}:
        return ""
    return task_episode_retrieval_control_semantic(
        event_semantic_text(event)
        if semantic_text is None
        else semantic_text
    )


def task_episode_retrieval_control_result_semantic(semantic: str) -> str:
    semantic = str(semantic or "").casefold()
    if "episode_semantic_search_results" in semantic:
        return "episode-search"
    if (
        "target_rank" in semantic
        and "raw_ref" in semantic
        and ("fts" in semantic or "normalized_query" in semantic)
    ):
        return "search"
    return ""


def task_episode_retrieval_control_result_command(
    event: RawEvent,
    *,
    semantic_text: str | None = None,
) -> str:
    if not task_episode_is_structured_result(event):
        return ""
    return task_episode_retrieval_control_result_semantic(
        event_semantic_text(event)
        if semantic_text is None
        else semantic_text
    )


def task_episode_retrieval_control_typed_anchors(
    event: RawEvent,
    evidence_role: str,
) -> list[dict[str, str]]:
    anchors = task_episode_typed_anchors(event, evidence_role)
    return [
        item
        for item in anchors
        if str(item.get("layer") or "") in {"tool", "script", "mcp", "api"}
        and (
            "aoa_session_memory" in str(item.get("key") or "")
            or str(item.get("key") or "") in {"exec", "exec_command", "namespace_tool"}
        )
    ]


def task_episode_nested_read_anchor_keys(event: RawEvent) -> set[tuple[str, str]]:
    commands = event.facets.get("nested_commands")
    if not isinstance(commands, list):
        return set()
    keys: set[tuple[str, str]] = set()
    for command_value in commands[:16]:
        command = str(command_value or "").strip()
        if not command:
            continue
        command_info = command_classifier(command)
        command_tags = {
            str(tag)
            for tag in command_info.get("tags", [])
            if str(tag)
        }
        command_tags.update(["command", "file_read_command", "nested_exec_command"])
        command_facets = (
            dict(command_info.get("facets"))
            if isinstance(command_info.get("facets"), dict)
            else {}
        )
        for signal in route_signals_for_event(
            "FILE_READ",
            "response_item",
            {},
            command,
            command,
            command_tags,
            command_facets,
            "requested",
            None,
        ):
            layer = str(signal.get("layer") or "")
            key = str(signal.get("key") or "")
            if layer and key:
                keys.add((layer, key))
    return keys


def task_episode_typed_anchors(event: RawEvent, evidence_role: str) -> list[dict[str, str]]:
    structured_result = task_episode_is_structured_result(event)
    if structured_result and event.outcome not in {"failed", "blocked"}:
        return []
    anchors: list[dict[str, str]] = []
    nested_read_scoped = bool(event.facets.get("nested_commands"))
    nested_read_anchor_keys = (
        task_episode_nested_read_anchor_keys(event)
        if nested_read_scoped and event.event_type == "FILE_READ"
        else set()
    )
    for signal in event_route_signals(event):
        layer = str(signal.get("layer") or "")
        key = str(signal.get("key") or "")
        if layer not in TASK_EPISODE_TYPED_ANCHOR_LAYERS or not key or key.isdigit():
            continue
        if structured_result:
            if layer not in {"error", "failure_mode"}:
                continue
            relation = "failed_with"
        elif evidence_role == "actions":
            signal_source = str(signal.get("source") or "")
            if layer == "tool" and (
                key in {"exec_command", "namespace_codex_developer_tool"}
                or signal_source in {"tool_name", "tool_namespace"}
            ):
                relation = "invoked"
            elif event.event_type == "FILE_READ":
                relation = (
                    "inspected"
                    if not nested_read_scoped or (layer, key) in nested_read_anchor_keys
                    else "referenced_by_action"
                )
            elif event.event_type in {"FILE_WRITE", "DIFF"}:
                relation = "modified"
            elif event.event_type == "TOOL_CALL" and layer == "mcp":
                relation = (
                    "invoked"
                    if signal_source in {"mcp_tool", "mcp_tool_service"}
                    else "referenced_by_action"
                )
            elif event.event_type == "TOOL_CALL" and layer == "api":
                relation = (
                    "invoked"
                    if signal_source in {"api_tool", "api_tool_service"}
                    else "referenced_by_action"
                )
            elif event.event_type == "COMMAND" and layer in {"tool", "script", "test", "validator", "git", "github"}:
                relation = "invoked"
            else:
                relation = "referenced_by_action"
        elif evidence_role == "failures":
            relation = "failed_with"
        elif evidence_role == "verification":
            relation = "verified_by"
        else:
            relation = "mentioned"
        item = {
            "layer": layer,
            "key": key,
            "route_signal": str(signal.get("route_signal") or route_signal_token(layer, key)),
            "relation": relation,
        }
        if item not in anchors:
            anchors.append(item)
        if len(anchors) >= 32:
            break
    return anchors


def task_episode_representation_entry(
    event: RawEvent,
    segments: list[dict[str, Any]],
    *,
    linked_action: str = "",
    linked_action_event_type: str = "",
    semantic_text: str | None = None,
) -> dict[str, Any] | None:
    structured_skill = isinstance(event.facets.get("structured_skill_input"), dict)
    if structured_skill:
        return None
    semantic = (
        event_semantic_text(event)
        if semantic_text is None
        else semantic_text
    )
    if event.event_type == "INTER_AGENT_TASK":
        semantic = task_episode_inter_agent_task_text(event)
    if event.event_type == "USER_INTENT" and naming_evidence_text_is_runtime_envelope(semantic):
        return None
    agent_class = agent_event_class_for_event(event)
    role, score, admission_basis = task_episode_representation_role(
        event,
        agent_class,
        semantic_text=semantic,
    )
    if not role:
        return None
    retrieval_command = task_episode_retrieval_control_command(
        event,
        semantic_text=semantic,
    )
    retrieval_result_command = task_episode_retrieval_control_result_command(
        event,
        semantic_text=semantic,
    )
    linked_retrieval_control = str(linked_action or "").startswith(TASK_EPISODE_RETRIEVAL_CONTROL_PREFIX)
    if retrieval_command:
        semantic = f"{TASK_EPISODE_RETRIEVAL_CONTROL_PREFIX} invocation: {retrieval_command}"
        admission_basis = "retrieval_control_invocation_query_text_suppressed"
        score = min(score, 25)
    elif (retrieval_result_command or linked_retrieval_control) and task_episode_is_structured_result(event):
        linked_command = (
            retrieval_result_command
            or str(linked_action or "").partition(":")[2].strip()
            or "query"
        )
        semantic = (
            f"{TASK_EPISODE_RETRIEVAL_CONTROL_PREFIX} result: {linked_command}; "
            f"outcome={event.outcome or 'observed'}"
        )
        admission_basis = "retrieval_control_result_payload_suppressed"
        score = min(score, 20)
    elif task_episode_is_correlated_agent_activity_status(event):
        semantic = task_episode_agent_activity_status_text(event, linked_action)
    elif task_episode_is_structured_result(event) and event.outcome not in {"failed", "blocked"}:
        compact_observation = task_episode_compact_success_observation_text(
            event,
            linked_action=linked_action,
            linked_action_event_type=linked_action_event_type,
        )
        if compact_observation:
            semantic = compact_observation
            admission_basis = "structured_compact_success_observation"
            score += 10
        else:
            semantic = task_episode_result_status_text(event, linked_action)
    elif task_episode_is_structured_result(event) and event.outcome in {"failed", "blocked"}:
        semantic = search_doc_text([linked_action, semantic], max_chars=TASK_EPISODE_REPRESENTATION_MAX_CHARS)
    semantic = redact_derived_text(
        short_text(
            semantic,
            max_chars=TASK_EPISODE_REPRESENTATION_MAX_CHARS,
        ).strip()
    )
    if not semantic:
        return None
    ref = task_episode_event_ref(event, segments)
    typed_anchors = (
        []
        if event.event_type == "INTER_AGENT_TASK"
        else (
            task_episode_retrieval_control_typed_anchors(event, role)
            if (
                retrieval_command
                or retrieval_result_command
                or linked_retrieval_control
            )
            else task_episode_typed_anchors(event, role)
        )
    )
    entry = {
        "text": semantic,
        "source_lane": task_episode_source_lane(event),
        "evidence_role": role,
        "admission_basis": admission_basis,
        "confidence": "high" if event.source_type == "response_item" else "medium",
        "score": score + (5 if event.source_type == "response_item" else 0),
        "correlation_id": str(event.correlation_id or ""),
        "event_type": event.event_type,
        "outcome": event.outcome,
        "timestamp": event.timestamp or "",
        "line": event.line_no,
        "refs": {
            "raw": str(ref.get("raw_ref") or ""),
            "segment": str(ref.get("segment_ref") or ""),
            "segment_index": str(ref.get("segment_index") or ""),
        },
        "typed_anchors": typed_anchors,
    }
    if retrieval_command or retrieval_result_command or linked_retrieval_control:
        entry["retrieval_control_command"] = (
            retrieval_command
            or retrieval_result_command
            or str(linked_action or "").partition(":")[2].strip()
            or "query"
        )
    return entry


def task_episode_candidate_identity(entry: dict[str, Any]) -> str:
    normalized = re.sub(r"\s+", " ", str(entry.get("text") or "").casefold()).strip()
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest() if normalized else ""


def bounded_head_tail_append(
    items: list[Any],
    item: Any,
    *,
    limit: int,
    head_keep: int | None = None,
) -> bool:
    """Append to a bounded sequence while retaining its beginning and moving tail."""
    effective_limit = max(1, int_value(limit, 1))
    if len(items) < effective_limit:
        items.append(item)
        return False
    effective_head = min(
        max(1, int_value(head_keep, max(1, effective_limit // 4))),
        effective_limit - 1,
    )
    del items[effective_head]
    items.append(item)
    return True


def task_episode_select_representations(entries: list[dict[str, Any]], *, limit: int) -> list[dict[str, Any]]:
    deduped: dict[str, dict[str, Any]] = {}
    for entry in entries:
        identity = task_episode_candidate_identity(entry)
        if not identity:
            continue
        current = deduped.get(identity)
        if current is None or int_value(entry.get("score")) > int_value(current.get("score")):
            deduped[identity] = entry
    candidates = list(deduped.values())
    if len(candidates) <= limit:
        selected = candidates
    else:
        chronological = sorted(candidates, key=lambda item: (int_value(item.get("line")), -int_value(item.get("score"))))
        head_count = max(1, limit // 8)
        tail_count = max(2, limit // 2)
        selected = [*chronological[:head_count], *chronological[-tail_count:]]
        selected = list({id(item): item for item in selected}.values())
        selected_ids = {id(item) for item in selected}
        slots = max(0, limit - len(selected))
        ranked = sorted(
            (item for item in candidates if id(item) not in selected_ids),
            key=lambda item: (-int_value(item.get("score")), int_value(item.get("line"))),
        )
        high_count = min(len(ranked), max(0, slots // 2))
        selected.extend(ranked[:high_count])
        selected_ids = {id(item) for item in selected}
        remaining = [item for item in chronological if id(item) not in selected_ids]
        slots = max(0, limit - len(selected))
        if slots == 1 and remaining:
            selected.append(remaining[len(remaining) // 2])
        elif slots > 1 and remaining:
            indexes = {
                round(index * (len(remaining) - 1) / (slots - 1))
                for index in range(slots)
            }
            selected.extend(remaining[index] for index in sorted(indexes))
            if len(selected) < limit:
                for item in remaining:
                    if item not in selected:
                        selected.append(item)
                    if len(selected) >= limit:
                        break
    selected.sort(key=lambda item: (int_value(item.get("line")), -int_value(item.get("score"))))
    return [
        {
            key: value
            for key, value in entry.items()
            if key != "score" and value is not None and value != ""
        }
        for entry in selected[:limit]
    ]


def task_episode_narrative(representations: dict[str, list[dict[str, Any]]]) -> str:
    parts: list[str] = []
    labels = {
        "intents": "Intent",
        "plans": "Plan",
        "actions": "Actions",
        "failures": "Failure",
        "outcomes": "Outcome",
        "verification": "Verification",
    }
    for role in ("intents", "plans", "actions", "failures", "outcomes", "verification"):
        entries = representations.get(role, [])
        if not entries:
            continue
        sample = entries if role == "intents" else entries[-3:]
        text = " | ".join(short_text(str(item.get("text") or ""), max_chars=500) for item in sample if item.get("text"))
        if text:
            parts.append(f"{labels[role]}: {text}")
    return short_text("\n".join(parts), max_chars=3600)


def finalize_task_episode_semantics(episode: dict[str, Any]) -> None:
    raw_candidates = episode.pop("_representation_candidates", [])
    candidates = raw_candidates if isinstance(raw_candidates, list) else []
    representations: dict[str, list[dict[str, Any]]] = {}
    omitted: dict[str, int] = {}
    for role, limit in TASK_EPISODE_REPRESENTATION_LIMITS.items():
        role_candidates = [item for item in candidates if isinstance(item, dict) and item.get("evidence_role") == role]
        selected = task_episode_select_representations(role_candidates, limit=limit)
        representations[role] = selected
        if len(role_candidates) > len(selected):
            omitted[role] = len(role_candidates) - len(selected)
    semantic_parts: list[str] = []
    for role in ("intents", "plans", "actions", "failures", "outcomes", "verification", "reasoning"):
        for entry in representations.get(role, []):
            if entry.get("text"):
                semantic_parts.append(f"{role}: {entry['text']}")
    episode["semantic_contract"] = {
        "version": TASK_EPISODE_REPRESENTATION_VERSION,
        "source_aware_admission": True,
        "successful_tool_output_policy": "compact_non_file_read_observation_else_status_and_correlation_raw_dump_excluded",
        "verification_policy": "structured_verification_action_plus_same_correlation_explicit_success_signal",
        "compact_success_output_limits": {
            "max_chars": TASK_EPISODE_COMPACT_SUCCESS_OUTPUT_MAX_CHARS,
            "max_lines": TASK_EPISODE_COMPACT_SUCCESS_OUTPUT_MAX_LINES,
        },
        "typed_anchor_policy": "wrapper_invoked_file_targets_inspected_success_output_edges_excluded_failures_error_layers_only",
        "stream_copy_policy": "exact_text_deduplicated_prefer_canonical_response_item",
        "bounded": True,
        "omitted_representation_counts": omitted,
    }
    episode["representations"] = representations
    episode["intent"] = short_text(
        "\n".join(str(item.get("text") or "") for item in representations.get("intents", [])),
        max_chars=2400,
    )
    episode["actions"] = representations.get("actions", [])
    episode["outcome"] = short_text(
        "\n".join(str(item.get("text") or "") for item in representations.get("outcomes", [])),
        max_chars=3600,
    )
    episode["verification"] = representations.get("verification", [])
    episode["failures"] = representations.get("failures", [])
    episode["narrative"] = task_episode_narrative(representations)
    episode["semantic_text"] = short_text("\n".join(semantic_parts), max_chars=TASK_EPISODE_SEMANTIC_TEXT_MAX_CHARS)
    episode["provenance"] = {
        "authority": "raw_session_transcript",
        "representation_ref_count": sum(len(items) for items in representations.values()),
        "all_representations_require_raw_segment_session_refs": True,
        "selection": "salience_plus_head_tail_timeline_coverage_v2",
    }


def append_task_episode_correlation(
    episode: dict[str, Any],
    event: RawEvent,
    segments: list[dict[str, Any]],
    *,
    linked_action: str = "",
) -> None:
    correlation_id = str(event.correlation_id or "")
    if not correlation_id:
        return
    chain = episode.setdefault("correlation_chain", [])
    if not isinstance(chain, list):
        return
    ref = task_episode_event_ref(event, segments)
    role = "result" if task_episode_is_structured_result(event) else "action"
    item = {
        "correlation_id": correlation_id,
        "role": role,
        "event_type": event.event_type,
        "outcome": event.outcome,
        "timestamp": event.timestamp or "",
        "linked_action": short_text(linked_action, max_chars=500) if role == "result" else "",
        "refs": {
            "raw": str(ref.get("raw_ref") or ""),
            "segment": str(ref.get("segment_ref") or ""),
            "segment_index": str(ref.get("segment_index") or ""),
        },
    }
    displaced = bounded_head_tail_append(
        chain,
        {key: value for key, value in item.items() if value is not None and value != ""},
        limit=TASK_EPISODE_REF_LIMIT_PER_BUCKET,
    )
    if displaced:
        omitted = episode.setdefault("omitted_ref_counts", {})
        if isinstance(omitted, dict):
            omitted["correlation_chain"] = int_value(omitted.get("correlation_chain"), 0) + 1


def normalized_task_episode_intent_text(value: Any) -> str:
    return re.sub(r"\s+", " ", str(value or "").casefold()).strip()


def task_episode_replayed_intent_is_specific(value: Any) -> bool:
    normalized = normalized_task_episode_intent_text(value)
    if not normalized or len(normalized) < 12:
        return False
    if re.fullmatch(
        r"(?:"
        r"да|давай|ок|окей|хорошо|сделай|делай|"
        r"продолжай|продолжаем|"
        r"yes|ok|okay|do it|go ahead|continue|resume"
        r")",
        normalized,
        flags=re.IGNORECASE,
    ):
        return False
    tokens = re.findall(r"\w+", normalized, flags=re.UNICODE)
    return len(tokens) >= 3 or bool(
        re.search(r"(?:[/\\]|--|\.[a-z0-9]{1,8}\b|`)", normalized)
    )


def task_episode_observed_intent_texts(episode: dict[str, Any]) -> set[str]:
    texts: set[str] = set()
    candidates = (
        episode.get("_representation_candidates")
        if isinstance(episode.get("_representation_candidates"), list)
        else []
    )
    for candidate in candidates:
        if not isinstance(candidate, dict) or candidate.get("evidence_role") != "intents":
            continue
        normalized = normalized_task_episode_intent_text(candidate.get("text"))
        if normalized:
            texts.add(normalized)
    representations = (
        episode.get("representations")
        if isinstance(episode.get("representations"), dict)
        else {}
    )
    for candidate in (
        representations.get("intents")
        if isinstance(representations.get("intents"), list)
        else []
    ):
        if not isinstance(candidate, dict):
            continue
        normalized = normalized_task_episode_intent_text(candidate.get("text"))
        if normalized:
            texts.add(normalized)
    return texts


def task_episode_user_continuation_candidate_relation(
    episode: dict[str, Any],
    event: RawEvent,
) -> str:
    """Return the typed relation without deciding whether a boundary may bridge."""
    conversation_act = (
        event.facets.get("conversation_act")
        if isinstance(event.facets.get("conversation_act"), dict)
        else {}
    )
    conversation_kind = str(conversation_act.get("kind") or "")
    normalized = normalized_task_episode_intent_text(event_semantic_text(event))
    if (
        normalized
        and normalized in task_episode_observed_intent_texts(episode)
        and task_episode_replayed_intent_is_specific(normalized)
    ):
        return "replayed_intent"
    return {
        "operator_correction": "correction",
        "operator_context_addition": "context_addition",
        "operator_failure_observation": "failure_observation",
        "operator_resume_request": "resume",
    }.get(conversation_kind, "")


def task_episode_user_continuation_relation(
    episode: dict[str, Any],
    event: RawEvent,
) -> str:
    """Return a semantic continuation only when the open lifecycle proves one."""
    if str(episode.get("status") or "") != "open":
        return ""
    return task_episode_user_continuation_candidate_relation(
        episode,
        event,
    )


def task_episode_is_empty_runtime_turn_boundary(
    episode: dict[str, Any],
) -> bool:
    transition = (
        episode.get("transition")
        if isinstance(episode.get("transition"), dict)
        else {}
    )
    if (
        str(episode.get("status") or "") != "open"
        or str(transition.get("boundary_kind") or "")
        != "runtime_task_started_boundary"
        or episode.get("intent_refs")
        or episode.get("semantic_continuations")
        or task_episode_agent_response_ref_count(episode) > 0
    ):
        return False
    evidence_buckets = (
        "action_refs",
        "tool_refs",
        "error_refs",
        "verification_refs",
        "correlation_chain",
    )
    return not any(episode.get(bucket) for bucket in evidence_buckets)


def append_task_episode_semantic_continuation(
    episode: dict[str, Any],
    event: RawEvent,
    segments: list[dict[str, Any]],
    *,
    relation: str,
) -> None:
    update_task_episode_range(episode, event)
    ref = task_episode_event_ref(event, segments)
    intent_refs = episode.setdefault("intent_refs", [])
    if isinstance(intent_refs, list):
        displaced = bounded_head_tail_append(
            intent_refs,
            ref,
            limit=TASK_EPISODE_REF_LIMIT_PER_BUCKET,
        )
        if displaced:
            omitted = episode.setdefault("omitted_ref_counts", {})
            if isinstance(omitted, dict):
                omitted["intent_refs"] = int_value(
                    omitted.get("intent_refs"),
                    0,
                ) + 1
    continuation = {
        **ref,
        "relation": relation,
        "admission_basis": (
            "exact_normalized_prior_intent"
            if relation == "replayed_intent"
            else "typed_operator_conversation_act"
        ),
    }
    continuations = episode.setdefault("semantic_continuations", [])
    if isinstance(continuations, list):
        displaced = bounded_head_tail_append(
            continuations,
            continuation,
            limit=TASK_EPISODE_REF_LIMIT_PER_BUCKET,
        )
        if displaced:
            omitted = episode.setdefault("omitted_ref_counts", {})
            if isinstance(omitted, dict):
                omitted["semantic_continuations"] = int_value(
                    omitted.get("semantic_continuations"),
                    0,
                ) + 1
    append_task_episode_ref(episode, "transition_refs", event, segments)
    representation = task_episode_representation_entry(event, segments)
    if representation is not None:
        representation["semantic_continuation_relation"] = relation
        candidates = episode.setdefault("_representation_candidates", [])
        if isinstance(candidates, list):
            candidates.append(representation)


def task_episode_agent_response_ref_count(episode: dict[str, Any]) -> int:
    response_buckets = tuple(
        bucket for bucket in AGENT_EVENT_REF_BUCKETS if bucket != "transition_refs"
    )
    count = sum(
        len(episode.get(bucket, []))
        for bucket in response_buckets
        if isinstance(episode.get(bucket), list)
    )
    transition_refs = (
        episode.get("transition_refs")
        if isinstance(episode.get("transition_refs"), list)
        else []
    )
    count += sum(
        1
        for ref in transition_refs
        if isinstance(ref, dict)
        and str(ref.get("agent_event") or "").startswith("assistant_")
    )
    return count


def task_episode_terminal_status_has_canonical_evidence(
    episode: dict[str, Any],
    status: str,
) -> bool:
    if status == "blocked":
        refs = (
            episode.get("blocker_refs")
            if isinstance(episode.get("blocker_refs"), list)
            else []
        )
        return any(
            isinstance(ref, dict)
            and str(ref.get("source_type") or "")
            == "response_item"
            for ref in refs
        )
    if status == "handoff":
        refs = (
            episode.get("transition_refs")
            if isinstance(
                episode.get("transition_refs"),
                list,
            )
            else []
        )
        return any(
            isinstance(ref, dict)
            and str(ref.get("source_type") or "")
            == "response_item"
            and str(ref.get("agent_event") or "")
            in {
                "assistant_handoff",
                "assistant_handoff_or_resume",
            }
            for ref in refs
        )
    return False


class TaskEpisodeBuilder:
    def __init__(
        self,
        segments: list[dict[str, Any]],
        *,
        forced_episode_starts: dict[int, str] | None = None,
        semantic_query_terms: list[dict[str, Any]] | None = None,
        semantic_query_text: str = "",
        runtime_goal_continuation_boundaries: bool = False,
        episode_ordinal_offset: int = 0,
        previous_episode_id: str = "",
    ) -> None:
        self.segments = segments
        self.episodes: list[dict[str, Any]] = []
        self.current: dict[str, Any] | None = None
        self.episode_ordinal_offset = max(
            0, int_value(episode_ordinal_offset)
        )
        self.previous_episode_id = str(previous_episode_id or "")
        self.action_by_correlation: dict[str, dict[str, str]] = {}
        self.forced_episode_starts = forced_episode_starts or {}
        self.semantic_query_terms = [
            dict(item)
            for item in (semantic_query_terms or [])
            if isinstance(item, dict) and str(item.get("token") or "")
        ]
        self.semantic_query_text = re.sub(
            r"\s+",
            " ",
            str(semantic_query_text or "").casefold(),
        ).strip()
        self.runtime_goal_continuation_boundaries = runtime_goal_continuation_boundaries
        self.semantic_query_control_correlations: set[str] = set()
        self.semantic_query_control_event_count = 0
        self.query_relevant_representation_candidate_count = 0
        self.runtime_goal_continuation_boundary_count = 0

    def bridge_runtime_turn_boundary_for_user(
        self,
        event: RawEvent,
    ) -> str:
        if (
            self.current is None
            or len(self.episodes) < 2
            or self.episodes[-1] is not self.current
            or not task_episode_is_empty_runtime_turn_boundary(
                self.current
            )
        ):
            return ""
        previous = self.episodes[-2]
        previous_flags = (
            previous.get("ambiguity_flags")
            if isinstance(previous.get("ambiguity_flags"), list)
            else []
        )
        if (
            str(previous.get("status") or "")
            not in {"closed", "blocked", "handoff"}
            or "runtime_task_complete_observed"
            not in previous_flags
        ):
            return ""
        relation = task_episode_user_continuation_candidate_relation(
            previous,
            event,
        )
        if not relation:
            return ""

        boundary_ref = (
            dict(self.current.get("start_user_ref"))
            if isinstance(self.current.get("start_user_ref"), dict)
            else {}
        )
        if not boundary_ref.get("raw_ref"):
            return ""
        boundary_ref["runtime_boundary_role"] = (
            "bridged_runtime_task_started"
        )
        transition_refs = previous.setdefault(
            "transition_refs",
            [],
        )
        if isinstance(transition_refs, list):
            displaced = bounded_head_tail_append(
                transition_refs,
                boundary_ref,
                limit=TASK_EPISODE_REF_LIMIT_PER_BUCKET,
            )
            if displaced:
                omitted = previous.setdefault(
                    "omitted_ref_counts",
                    {},
                )
                if isinstance(omitted, dict):
                    omitted["transition_refs"] = int_value(
                        omitted.get("transition_refs"),
                        0,
                    ) + 1

        prior_status = str(previous.get("status") or "")
        bridge = {
            "relation": relation,
            "admission_basis": (
                "typed_operator_conversation_act_across_empty_runtime_turn"
            ),
            "runtime_task_started_ref": boundary_ref.get(
                "raw_ref"
            ),
            "previous_terminal_status": prior_status,
        }
        bridges = previous.setdefault(
            "transport_boundary_continuations",
            [],
        )
        if isinstance(bridges, list):
            bounded_head_tail_append(
                bridges,
                bridge,
                limit=TASK_EPISODE_REF_LIMIT_PER_BUCKET,
            )
        previous["status"] = "open"
        if (
            isinstance(previous_flags, list)
            and (
                "runtime_turn_boundary_bridged_by_typed_continuation"
                not in previous_flags
            )
        ):
            previous_flags.append(
                "runtime_turn_boundary_bridged_by_typed_continuation"
            )
        if (
            previous.get("closeout_refs")
            and isinstance(previous_flags, list)
            and (
                "prior_closeout_followed_by_operator_continuation"
                not in previous_flags
            )
        ):
            previous_flags.append(
                "prior_closeout_followed_by_operator_continuation"
            )

        self.episodes.pop()
        self.current = previous
        append_task_episode_semantic_continuation(
            previous,
            event,
            self.segments,
            relation=relation,
        )
        return relation

    def adopt_empty_runtime_turn_boundary_for_user(
        self,
        event: RawEvent,
    ) -> bool:
        if (
            self.current is None
            or not task_episode_is_empty_runtime_turn_boundary(
                self.current
            )
        ):
            return False
        update_task_episode_range(self.current, event)
        append_task_episode_ref(
            self.current,
            "intent_refs",
            event,
            self.segments,
        )
        representation = task_episode_representation_entry(
            event,
            self.segments,
        )
        if representation is not None:
            candidates = self.current.setdefault(
                "_representation_candidates",
                [],
            )
            if isinstance(candidates, list):
                candidates.append(representation)
        conversation_act = (
            event.facets.get("conversation_act")
            if isinstance(
                event.facets.get("conversation_act"),
                dict,
            )
            else {}
        )
        transition = (
            self.current.get("transition")
            if isinstance(self.current.get("transition"), dict)
            else {}
        )
        transition.update(
            {
                "first_semantic_intent_ref": (
                    f"raw:line:{event.line_no}"
                ),
                "semantic_intent_reason": (
                    str(conversation_act.get("kind") or "")
                    or "user_prompt"
                ),
                "user_conversation_act": str(
                    conversation_act.get("kind") or ""
                ),
            }
        )
        self.current["transition"] = transition
        self.current["confidence"] = "high"
        flags = self.current.setdefault(
            "ambiguity_flags",
            [],
        )
        if (
            isinstance(flags, list)
            and (
                "runtime_boundary_adopted_by_first_semantic_intent"
                not in flags
            )
        ):
            flags.append(
                "runtime_boundary_adopted_by_first_semantic_intent"
            )
        return True

    def observe(self, event: RawEvent) -> None:
        conversation_act = event.facets.get("conversation_act") if isinstance(event.facets.get("conversation_act"), dict) else {}
        conversation_kind = str(conversation_act.get("kind") or "")
        agent_class = agent_event_class_for_event(event)
        forced_transition_reason = str(self.forced_episode_starts.get(event.line_no) or "")
        if forced_transition_reason:
            if self.current is not None:
                close_open_task_episode_for_transition(
                    self.current,
                    event,
                    self.segments,
                    structural_lineage_boundary=True,
                )
                self.previous_episode_id = str(self.current.get("episode_id") or "")
            self.current = new_task_episode(
                ordinal=(
                    self.episode_ordinal_offset
                    + len(self.episodes)
                    + 1
                ),
                user_event=event,
                segments=self.segments,
                previous_episode_id=self.previous_episode_id,
                transition_reason=forced_transition_reason,
            )
            self.current["intent_refs"] = []
            self.current["start_ref_role"] = (
                "structural_lineage_boundary"
            )
            flags = self.current.setdefault("ambiguity_flags", [])
            if isinstance(flags, list) and "structural_lineage_boundary_start" not in flags:
                flags.append("structural_lineage_boundary_start")
            transition = self.current.get("transition") if isinstance(self.current.get("transition"), dict) else {}
            transition["boundary_kind"] = "fork_local_task_start"
            transition["boundary_ref"] = f"raw:line:{event.line_no}"
            transition["boundary_is_semantic_intent"] = False
            self.current["transition"] = transition
            self.episodes.append(self.current)
            self.action_by_correlation = {}
            return
        structured_skill_selection = isinstance(event.facets.get("structured_skill_input"), dict)
        semantic_text = event_semantic_text(event)
        runtime_envelope = (
            event.event_type == "USER_INTENT"
            and naming_evidence_text_is_runtime_envelope(semantic_text)
        )
        runtime_goal_continuation = bool(
            runtime_envelope
            and re.match(
                r"""^\s*<codex_internal_context\b[^>]*\bsource\s*=\s*["']goal["'][^>]*>""",
                semantic_text,
                flags=re.IGNORECASE,
            )
        )
        if runtime_goal_continuation and self.runtime_goal_continuation_boundaries:
            if self.current is not None:
                close_open_task_episode_for_transition(
                    self.current,
                    event,
                    self.segments,
                    structural_lineage_boundary=True,
                )
                self.previous_episode_id = str(self.current.get("episode_id") or "")
            self.current = new_task_episode(
                ordinal=(
                    self.episode_ordinal_offset
                    + len(self.episodes)
                    + 1
                ),
                user_event=event,
                segments=self.segments,
                previous_episode_id=self.previous_episode_id,
                transition_reason="automatic_goal_continuation",
            )
            self.current["start_ref_role"] = (
                "runtime_goal_continuation_boundary"
            )
            flags = self.current.setdefault("ambiguity_flags", [])
            if isinstance(flags, list) and "runtime_goal_continuation_boundary" not in flags:
                flags.append("runtime_goal_continuation_boundary")
            transition = (
                self.current.get("transition")
                if isinstance(self.current.get("transition"), dict)
                else {}
            )
            transition["boundary_kind"] = "automatic_goal_continuation"
            transition["runtime_envelope_text_admitted"] = False
            self.current["transition"] = transition
            self.episodes.append(self.current)
            self.action_by_correlation = {}
            self.runtime_goal_continuation_boundary_count += 1
            return
        if structured_skill_selection or runtime_envelope:
            if self.current is not None and self.current.get("status") == "open":
                update_task_episode_range(self.current, event)
                append_task_episode_ref(self.current, "transition_refs", event, self.segments)
            return
        canonical_user_message = (
            event.event_type == "USER_INTENT"
            and event.source_type == "response_item"
            and isinstance(event.parsed, dict)
            and isinstance(event.parsed.get("payload"), dict)
            and str(event.parsed["payload"].get("type") or "") == "message"
            and str(event.parsed["payload"].get("role") or "") == "user"
        )
        fallback_user_message = event.event_type == "USER_INTENT" and event.source_type == "event_msg"
        if canonical_user_message or (fallback_user_message and self.current is None):
            if (
                canonical_user_message
                and self.bridge_runtime_turn_boundary_for_user(
                    event
                )
            ):
                return
            if (
                canonical_user_message
                and self.adopt_empty_runtime_turn_boundary_for_user(
                    event
                )
            ):
                return
            continuation_relation = (
                task_episode_user_continuation_relation(self.current, event)
                if canonical_user_message and self.current is not None
                else ""
            )
            if self.current is not None and continuation_relation:
                append_task_episode_semantic_continuation(
                    self.current,
                    event,
                    self.segments,
                    relation=continuation_relation,
                )
                return
            if self.current is not None:
                close_open_task_episode_for_transition(self.current, event, self.segments)
                self.previous_episode_id = str(self.current.get("episode_id") or "")
            self.current = new_task_episode(
                ordinal=(
                    self.episode_ordinal_offset
                    + len(self.episodes)
                    + 1
                ),
                user_event=event,
                segments=self.segments,
                previous_episode_id=self.previous_episode_id,
                transition_reason=conversation_kind or "user_prompt",
            )
            self.episodes.append(self.current)
            intent_entry = task_episode_representation_entry(
                event,
                self.segments,
                semantic_text=semantic_text,
            )
            if intent_entry is not None:
                self.current["_representation_candidates"].append(intent_entry)
            return
        runtime_task_started = (
            event.source_type == "event_msg"
            and str(
                task_episode_payload(event).get("type") or ""
            )
            == "task_started"
        )
        if (
            runtime_task_started
            and self.current is not None
            and str(self.current.get("status") or "")
            != "open"
        ):
            previous_terminal_status = str(
                self.current.get("status") or ""
            )
            self.previous_episode_id = str(
                self.current.get("episode_id") or ""
            )
            self.current = new_task_episode(
                ordinal=(
                    self.episode_ordinal_offset
                    + len(self.episodes)
                    + 1
                ),
                user_event=event,
                segments=self.segments,
                previous_episode_id=self.previous_episode_id,
                transition_reason=(
                    "runtime_task_started_after_terminal"
                ),
            )
            self.current["intent_refs"] = []
            self.current["start_ref_role"] = (
                "runtime_task_started_boundary"
            )
            flags = self.current.setdefault(
                "ambiguity_flags",
                [],
            )
            if isinstance(flags, list):
                if "noncanonical_user_start" in flags:
                    flags.remove("noncanonical_user_start")
                if "runtime_task_started_boundary" not in flags:
                    flags.append(
                        "runtime_task_started_boundary"
                    )
            transition = (
                self.current.get("transition")
                if isinstance(
                    self.current.get("transition"),
                    dict,
                )
                else {}
            )
            transition.update(
                {
                    "boundary_kind": (
                        "runtime_task_started_boundary"
                    ),
                    "boundary_ref": (
                        f"raw:line:{event.line_no}"
                    ),
                    "boundary_is_semantic_intent": False,
                    "previous_terminal_status": (
                        previous_terminal_status
                    ),
                }
            )
            self.current["transition"] = transition
            self.episodes.append(self.current)
            self.action_by_correlation = {}
            return
        if event.event_type == "INTER_AGENT_TASK" and (
            self.current is None
            or str(self.current.get("status") or "") != "open"
        ):
            previous_terminal_status = (
                str(self.current.get("status") or "")
                if self.current is not None
                else ""
            )
            if self.current is not None:
                self.previous_episode_id = str(
                    self.current.get("episode_id") or ""
                )
            self.current = new_task_episode(
                ordinal=(
                    self.episode_ordinal_offset
                    + len(self.episodes)
                    + 1
                ),
                user_event=event,
                segments=self.segments,
                previous_episode_id=self.previous_episode_id,
                transition_reason=(
                    "structured_inter_agent_task_after_terminal"
                    if previous_terminal_status
                    else "structured_inter_agent_task_start"
                ),
            )
            self.current["intent_refs"] = []
            self.current["start_ref_role"] = (
                "structured_inter_agent_task"
            )
            flags = self.current.setdefault(
                "ambiguity_flags",
                [],
            )
            if isinstance(flags, list):
                if "noncanonical_user_start" in flags:
                    flags.remove("noncanonical_user_start")
                if (
                    "structured_inter_agent_task_start"
                    not in flags
                ):
                    flags.append(
                        "structured_inter_agent_task_start"
                    )
            transition = (
                self.current.get("transition")
                if isinstance(
                    self.current.get("transition"),
                    dict,
                )
                else {}
            )
            transition.update(
                {
                    "boundary_kind": (
                        "structured_inter_agent_task_start"
                    ),
                    "boundary_ref": (
                        f"raw:line:{event.line_no}"
                    ),
                    "boundary_is_semantic_intent": True,
                    "previous_terminal_status": (
                        previous_terminal_status
                    ),
                }
            )
            self.current["transition"] = transition
            self.episodes.append(self.current)
            self.action_by_correlation = {}
        if self.current is None:
            return
        update_task_episode_range(self.current, event)
        event_payload = task_episode_payload(event)
        runtime_task_complete = (
            event.source_type == "event_msg"
            and str(event_payload.get("type") or "") == "task_complete"
        )
        correlation_id = str(event.correlation_id or "")
        event_semantic_tokens = (
            episode_semantic_field_tokens(semantic_text)
            if self.semantic_query_terms
            else set()
        )
        event_query_match_count = sum(
            1
            for term in self.semantic_query_terms
            if episode_semantic_term_matches_tokens(term, event_semantic_tokens)
        )
        normalized_event_semantic = re.sub(
            r"\s+",
            " ",
            semantic_text.casefold(),
        ).strip()
        query_echo_threshold = max(
            3,
            math.ceil(
                len(self.semantic_query_terms)
                * LIVE_TAIL_SEMANTIC_QUERY_ECHO_MIN_TERM_COVERAGE
            ),
        )
        payload_type = str(event_payload.get("type") or "")
        structured_query_action = (
            event.source_type == "response_item"
            and payload_type in {"function_call", "tool_call", "custom_tool_call"}
        )
        recognized_semantic_query_control = (
            (
                task_episode_retrieval_control_structured_payload(event_payload)
                or task_episode_retrieval_control_semantic(semantic_text)
            )
            if structured_query_action
            else ""
        )
        semantic_query_control_action = bool(
            structured_query_action
            and self.semantic_query_terms
            and recognized_semantic_query_control
            and (
                (
                    self.semantic_query_text
                    and self.semantic_query_text in normalized_event_semantic
                )
                or event_query_match_count >= query_echo_threshold
            )
        )
        if semantic_query_control_action and correlation_id:
            self.semantic_query_control_correlations.add(correlation_id)
        linked_action_record = self.action_by_correlation.get(correlation_id, {}) if correlation_id else {}
        linked_action = str(linked_action_record.get("text") or "")
        linked_action_event_type = str(linked_action_record.get("event_type") or "")
        correlated_semantic_query_control = bool(
            correlation_id
            and correlation_id in self.semantic_query_control_correlations
        )
        if correlated_semantic_query_control:
            linked_action = f"{TASK_EPISODE_RETRIEVAL_CONTROL_PREFIX} query-echo"
        representation = task_episode_representation_entry(
            event,
            self.segments,
            linked_action=linked_action,
            linked_action_event_type=linked_action_event_type,
            semantic_text=semantic_text,
        )
        if representation is not None:
            if semantic_query_control_action:
                representation.update(
                    {
                        "text": (
                            f"{TASK_EPISODE_RETRIEVAL_CONTROL_PREFIX} "
                            "invocation: query-echo"
                        ),
                        "admission_basis": (
                            "query_time_semantic_control_invocation_text_suppressed"
                        ),
                        "score": min(int_value(representation.get("score")), 25),
                        "retrieval_control_command": "query-echo",
                    }
                )
                self.semantic_query_control_event_count += 1
            elif (
                correlated_semantic_query_control
                and task_episode_is_structured_result(event)
            ):
                self.semantic_query_control_event_count += 1
            if (
                self.semantic_query_terms
                and not representation.get("retrieval_control_command")
            ):
                representation_tokens = episode_semantic_field_tokens(
                    representation.get("text")
                )
                matched_query_term_count = sum(
                    1
                    for term in self.semantic_query_terms
                    if episode_semantic_term_matches_tokens(
                        term,
                        representation_tokens,
                    )
                )
                if matched_query_term_count:
                    representation["score"] = (
                        int_value(representation.get("score"))
                        + LIVE_TAIL_SEMANTIC_QUERY_MATCH_SCORE_BASE
                        + (matched_query_term_count * 100)
                    )
                    self.query_relevant_representation_candidate_count += 1
            candidates = self.current.setdefault("_representation_candidates", [])
            if isinstance(candidates, list):
                candidates.append(representation)
                if (
                    task_episode_is_correlation_matched_verification_result(
                        event,
                        linked_action_record,
                        semantic_text=semantic_text,
                    )
                ):
                    verification_representation = {
                        **representation,
                        "refs": dict(
                            representation.get("refs")
                            if isinstance(
                                representation.get("refs"),
                                dict,
                            )
                            else {}
                        ),
                        "evidence_role": "verification",
                        "admission_basis": (
                            "correlation_matched_structured_verification_result"
                        ),
                        "verification_correlation_status": (
                            "accepted_same_correlation_identity"
                        ),
                    }
                    candidates.append(
                        verification_representation
                    )
                    append_task_episode_ref(
                        self.current,
                        "verification_refs",
                        event,
                        self.segments,
                    )
            if (
                event.event_type == "INTER_AGENT_TASK"
                and representation.get("evidence_role") == "intents"
            ):
                append_task_episode_ref(
                    self.current,
                    "intent_refs",
                    event,
                    self.segments,
                )
                transition = (
                    self.current.get("transition")
                    if isinstance(self.current.get("transition"), dict)
                    else {}
                )
                transition.setdefault(
                    "delegated_task_ref",
                    f"raw:line:{event.line_no}",
                )
                inter_agent = (
                    event.facets.get("inter_agent_message")
                    if isinstance(
                        event.facets.get("inter_agent_message"),
                        dict,
                    )
                    else {}
                )
                transition.setdefault(
                    "delegated_task_content_status",
                    str(
                        inter_agent.get("content_status")
                        or "unresolved"
                    ),
                )
                self.current["transition"] = transition
                if str(
                    inter_agent.get("content_status") or ""
                ) != "clear_payload_available":
                    flags = self.current.setdefault(
                        "ambiguity_flags",
                        [],
                    )
                    if (
                        isinstance(flags, list)
                        and "inter_agent_task_content_unresolved"
                        not in flags
                    ):
                        flags.append(
                            "inter_agent_task_content_unresolved"
                        )
            if representation.get("evidence_role") == "actions" and correlation_id:
                verification_action = (
                    task_episode_is_structured_verification_action(
                        event
                    )
                )
                self.action_by_correlation[correlation_id] = {
                    "text": str(representation.get("text") or ""),
                    "event_type": str(event.event_type or ""),
                    "verification_action": verification_action,
                }
                linked_action = str(representation.get("text") or "")
                if verification_action:
                    append_task_episode_ref(
                        self.current,
                        "verification_refs",
                        event,
                        self.segments,
                    )
            append_task_episode_correlation(
                self.current,
                event,
                self.segments,
                linked_action=linked_action,
            )
        if agent_class == "assistant_reasoning_boundary":
            append_task_episode_ref(self.current, "reasoning_refs", event, self.segments)
        elif agent_class == "assistant_plan":
            append_task_episode_ref(self.current, "plan_refs", event, self.segments)
        elif agent_class == "assistant_progress_update":
            append_task_episode_ref(self.current, "progress_refs", event, self.segments)
        elif agent_class == "assistant_verification_report":
            append_task_episode_ref(self.current, "verification_refs", event, self.segments)
        elif agent_class == "assistant_final_closeout":
            append_task_episode_ref(self.current, "closeout_refs", event, self.segments)
            self.current["status"] = "closed"
        elif agent_class == "assistant_blocker_report":
            append_task_episode_ref(self.current, "blocker_refs", event, self.segments)
            self.current["status"] = "blocked"
        elif agent_class in {"assistant_handoff", "assistant_resume", "assistant_handoff_or_resume", "assistant_correction_ack"}:
            append_task_episode_ref(self.current, "transition_refs", event, self.segments)
            if agent_class in {"assistant_handoff", "assistant_handoff_or_resume"} and self.current.get("status") == "open":
                self.current["status"] = "handoff"
        elif agent_class == "assistant_answer":
            append_task_episode_ref(self.current, "answer_refs", event, self.segments)
        if event.event_type in {"COMMAND", "FILE_READ", "FILE_WRITE", "DIFF", "TOOL_CALL"}:
            append_task_episode_ref(self.current, "action_refs", event, self.segments)
            if event.event_type == "TOOL_CALL":
                append_task_episode_ref(self.current, "tool_refs", event, self.segments)
        if event.event_type in {"COMMAND_OUTPUT", "TOOL_OUTPUT"} and event.outcome == "failed":
            append_task_episode_ref(self.current, "error_refs", event, self.segments)
        elif event.event_type == "ERROR" or event.outcome == "failed":
            append_task_episode_ref(self.current, "error_refs", event, self.segments)
        if event.event_type == "VERIFICATION" or conversation_kind == "assistant_verification_report":
            append_task_episode_ref(self.current, "verification_refs", event, self.segments)
        if runtime_task_complete:
            append_task_episode_ref(self.current, "transition_refs", event, self.segments)
            current_status = str(
                self.current.get("status") or ""
            )
            if current_status == "open":
                self.current["status"] = "closed"
            flags = self.current.setdefault("ambiguity_flags", [])
            if isinstance(flags, list) and "runtime_task_complete_observed" not in flags:
                flags.append("runtime_task_complete_observed")
            if (
                current_status in {"blocked", "handoff"}
                and not task_episode_terminal_status_has_canonical_evidence(
                    self.current,
                    current_status,
                )
            ):
                self.current["status"] = "closed"
                if (
                    isinstance(flags, list)
                    and (
                        "noncanonical_terminal_status_overridden_by_runtime_complete"
                        not in flags
                    )
                ):
                    flags.append(
                        "noncanonical_terminal_status_overridden_by_runtime_complete"
                    )

    def finish(self) -> list[dict[str, Any]]:
        for episode in self.episodes:
            flags = episode.setdefault("ambiguity_flags", [])
            response_ref_count = task_episode_agent_response_ref_count(episode)
            if isinstance(flags, list):
                if response_ref_count == 0 and episode.get("status") == "open":
                    episode["status"] = "interrupted"
                    if "no_agent_response_seen" not in flags:
                        flags.append("no_agent_response_seen")
                if not episode.get("closeout_refs") and episode.get("status") == "open":
                    flags.append("no_closeout_seen")
                if not episode.get("verification_refs"):
                    flags.append("no_verification_refs")
                if episode.get("omitted_ref_counts"):
                    flags.append("bounded_ref_lists")
            if episode.get("status") == "open" and episode.get("closeout_refs"):
                episode["status"] = "closed"
            if "semantic_contract" not in episode:
                finalize_task_episode_semantics(episode)
        return self.episodes


def generated_task_episodes_for_events(
    events: list[RawEvent],
    segments: list[dict[str, Any]],
    *,
    lineage: dict[str, Any] | None = None,
    episode_ordinal_offset: int = 0,
    previous_episode_id: str = "",
) -> list[dict[str, Any]]:
    history_prefix = (
        lineage.get("history_prefix")
        if isinstance(lineage, dict) and isinstance(lineage.get("history_prefix"), dict)
        else {}
    )
    local_work_from_line = int_value(history_prefix.get("local_work_from_line"), 0)
    forced_episode_starts = (
        {local_work_from_line: "fork_local_task_start"}
        if lineage and lineage.get("relationship") == "forked_from" and local_work_from_line > 0
        else {}
    )
    bootstrap_control_line = line_from_raw_ref(
        history_prefix.get("bootstrap_control_ref")
    ) or 0
    builder = TaskEpisodeBuilder(
        segments,
        forced_episode_starts=forced_episode_starts,
        episode_ordinal_offset=episode_ordinal_offset,
        previous_episode_id=previous_episode_id,
    )
    for event in events:
        if (
            bootstrap_control_line > 0
            and event.line_no == bootstrap_control_line
        ):
            continue
        builder.observe(event)
    return builder.finish()


def attach_task_episode_session_context(
    episodes: list[dict[str, Any]],
    *,
    session_dir: Path,
    manifest: dict[str, Any],
) -> None:
    session_id = str(manifest.get("session_id") or "")
    session_ref = str(session_dir / "session.manifest.json")
    source = manifest.get("source") if isinstance(manifest.get("source"), dict) else {}
    work_context = manifest.get("work_context") if isinstance(manifest.get("work_context"), dict) else {}
    session_lineage = manifest.get("lineage") if isinstance(manifest.get("lineage"), dict) else {}
    context = {
        "session_id": session_id,
        "cwd": str(source.get("cwd") or ""),
        "model": str(source.get("model") or ""),
        "work_context": work_context,
    }

    def attach_event_ref(ref: Any) -> None:
        if isinstance(ref, dict):
            ref["session_ref"] = session_ref

    for index, episode in enumerate(episodes):
        if not isinstance(episode, dict):
            continue
        event_range = episode.get("event_range") if isinstance(episode.get("event_range"), dict) else {}
        episode_lineage = task_episode_lineage_for_range(session_lineage, event_range)
        if episode_lineage:
            episode["lineage"] = episode_lineage
        episode_id = str(episode.get("episode_id") or "")
        from_event_id = str(event_range.get("from_event_id") or "")
        episode["stable_id"] = f"{session_id}:{episode_id}:{from_event_id}"
        canonical_material = f"{session_id}\0{from_event_id}".encode("utf-8")
        episode["identity"] = {
            "version": TASK_EPISODE_IDENTITY_VERSION,
            "scheme": "session_and_initiating_event_sha256_v1",
            "canonical_id": (
                "episode:"
                + hashlib.sha256(canonical_material).hexdigest()
            ),
            "session_id": session_id,
            "initiating_event_id": from_event_id,
            "legacy_stable_id": episode["stable_id"],
        }
        episode["context"] = context
        next_episode = episodes[index + 1] if index + 1 < len(episodes) and isinstance(episodes[index + 1], dict) else {}
        episode["validity"] = {
            "status": "historical_episode",
            "valid_during": episode.get("time_span", {}),
            "superseded_by": str(next_episode.get("episode_id") or ""),
        }
        attach_event_ref(episode.get("start_user_ref"))
        for bucket in (
            "intent_refs",
            "semantic_continuations",
            *AGENT_EVENT_REF_BUCKETS,
        ):
            for ref in (
                episode.get(bucket)
                if isinstance(episode.get(bucket), list)
                else []
            ):
                attach_event_ref(ref)
        representations = episode.get("representations") if isinstance(episode.get("representations"), dict) else {}
        semantic_texts: list[str] = []
        operational_anchors: list[dict[str, str]] = []
        mentioned_anchors: list[dict[str, str]] = []
        for items in representations.values():
            if not isinstance(items, list):
                continue
            for item in items:
                if not isinstance(item, dict):
                    continue
                refs = item.setdefault("refs", {})
                if isinstance(refs, dict):
                    refs["session"] = session_ref
                if item.get("text"):
                    semantic_texts.append(str(item["text"]))
                for anchor in item.get("typed_anchors", []) if isinstance(item.get("typed_anchors"), list) else []:
                    if not isinstance(anchor, dict):
                        continue
                    target = mentioned_anchors if anchor.get("relation") == "mentioned" else operational_anchors
                    compact_anchor = {
                        "layer": str(anchor.get("layer") or ""),
                        "key": str(anchor.get("key") or ""),
                        "route_signal": str(anchor.get("route_signal") or ""),
                        "relation": str(anchor.get("relation") or ""),
                    }
                    if compact_anchor.get("route_signal") and compact_anchor not in target:
                        target.append(compact_anchor)
        correlation_chain = episode.get("correlation_chain") if isinstance(episode.get("correlation_chain"), list) else []
        correlation_ids: list[str] = []
        for item in correlation_chain:
            if not isinstance(item, dict):
                continue
            refs = item.setdefault("refs", {})
            if isinstance(refs, dict):
                refs["session"] = session_ref
            correlation_id = str(item.get("correlation_id") or "")
            if correlation_id and correlation_id not in correlation_ids:
                correlation_ids.append(correlation_id)
        episode["anchors"] = {
            "correlation_ids": correlation_ids,
            "paths": extract_path_terms(semantic_texts, limit=24),
            "operational": operational_anchors[:96],
            "mentioned": mentioned_anchors[:48],
            "anchor_scope": "episode_admitted_text_not_raw_dump",
        }
        provenance = episode.setdefault("provenance", {})
        if isinstance(provenance, dict):
            provenance["session_ref"] = session_ref
            if episode_lineage:
                provenance["lineage_evidence_ref"] = episode_lineage.get("lineage_evidence_ref")
            provenance["raw_ref_resolvable"] = bool(
                any(
                    isinstance(item, dict) and isinstance(item.get("refs"), dict) and item["refs"].get("raw")
                    for items in representations.values()
                    if isinstance(items, list)
                    for item in items
                )
            )
        episode["projection_integrity"] = {
            "version": TASK_EPISODE_EVIDENCE_INTEGRITY_VERSION,
            "status": "pending_raw_and_digest_verification",
            "authority": "raw_session_transcript",
            "admissible": False,
        }


def task_episode_id_for_event(event: RawEvent, episodes: list[dict[str, Any]]) -> str:
    for episode in episodes:
        if not isinstance(episode, dict):
            continue
        event_range = episode.get("event_range") if isinstance(episode.get("event_range"), dict) else {}
        from_line = int_value(event_range.get("from_line"), 0)
        to_line = int_value(event_range.get("to_line"), 0)
        if from_line and to_line and from_line <= event.line_no <= to_line:
            return str(episode.get("episode_id") or "")
    return ""


def unique_preserving_order(values: Iterable[Any], *, limit: int = 200) -> list[str]:
    selected: list[str] = []
    seen: set[str] = set()
    for value in values:
        text = str(value or "")
        if not text or text in seen:
            continue
        seen.add(text)
        selected.append(text)
        if len(selected) >= limit:
            break
    return selected


def compact_value_present(value: Any) -> bool:
    return value is not None and value != ""


def goal_usage_fields_from_mapping(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        return {}
    selected: dict[str, Any] = {}
    for key in (
        "token_budget",
        "tokens_used",
        "tokensUsed",
        "remaining_tokens",
        "remainingTokens",
        "time_used_seconds",
        "timeUsedSeconds",
        "elapsed_seconds",
        "elapsed_ms",
        "status",
    ):
        if key in value and compact_value_present(value.get(key)):
            selected[key] = value.get(key)
    for nested_key in ("goal", "usage", "completionBudgetReport"):
        nested = value.get(nested_key)
        nested_fields = goal_usage_fields_from_mapping(nested)
        if nested_fields:
            selected[nested_key] = nested_fields
    return selected


def goal_usage_fields_from_output_event(event: RawEvent) -> dict[str, Any]:
    if not isinstance(event.parsed, dict):
        return {}
    payload = event.parsed.get("payload")
    if not isinstance(payload, dict):
        return {}
    output = payload.get("output")
    if isinstance(output, str):
        parsed_output = json_object_from_string(output)
        return goal_usage_fields_from_mapping(parsed_output)
    if isinstance(output, dict):
        return goal_usage_fields_from_mapping(output)
    return {}


def goal_state_fields_from_mapping(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        return {}
    selected: dict[str, Any] = {}
    candidates: list[dict[str, Any]] = []
    goal = value.get("goal")
    if isinstance(goal, dict):
        candidates.append(goal)
    candidates.append(value)
    for candidate in candidates:
        for key in ("threadId", "objective", "status", "createdAt", "updatedAt"):
            if key not in selected and key in candidate and compact_value_present(candidate.get(key)):
                candidate_value = candidate.get(key)
                selected[key] = (
                    derived_text_privacy_text(candidate_value)
                    if isinstance(candidate_value, str)
                    else candidate_value
                )
    return selected


def goal_state_fields_from_output_event(event: RawEvent) -> dict[str, Any]:
    if not isinstance(event.parsed, dict):
        return {}
    payload = event.parsed.get("payload")
    if not isinstance(payload, dict):
        return {}
    output = payload.get("output")
    if isinstance(output, str):
        parsed_output = json_object_from_string(output)
        return goal_state_fields_from_mapping(parsed_output)
    if isinstance(output, dict):
        return goal_state_fields_from_mapping(output)
    return {}


def goal_event_ref(
    event: RawEvent,
    segments: list[dict[str, Any]],
    *,
    session_id: str,
    task_episode_id: str = "",
) -> dict[str, Any]:
    ref = task_episode_event_ref(event, segments)
    segment_id = str(ref.get("segment_id") or "")
    event_id = str(ref.get("event_id") or event.event_id)
    if task_episode_id:
        ref["task_episode_id"] = task_episode_id
    if segment_id and event_id:
        ref["graph_event_node"] = f"event:{session_id}:{segment_id}:{event_id}"
    return ref


def goal_event_from_raw_event(
    event: RawEvent,
    *,
    session_id: str,
    segments: list[dict[str, Any]],
    task_episodes: list[dict[str, Any]],
) -> dict[str, Any] | None:
    payload = event.parsed.get("payload") if isinstance(event.parsed, dict) else {}
    if not isinstance(payload, dict):
        payload = {}
    facets = event.facets if isinstance(event.facets, dict) else {}
    session_act = facets.get("session_act") if isinstance(facets.get("session_act"), dict) else {}
    tool_name = str(facets.get("tool_name") or tool_name_from_payload(payload))
    kind = str(session_act.get("kind") or "")
    if kind not in GOAL_SESSION_ACTS:
        kind = goal_session_act_for_tool_payload(tool_name, payload) or ""
    if kind not in GOAL_SESSION_ACTS:
        return None
    args = command_payload_args(payload) if payload else {}
    task_episode_id = task_episode_id_for_event(event, task_episodes)
    ref = goal_event_ref(event, segments, session_id=session_id, task_episode_id=task_episode_id)
    objective = derived_text_privacy_text(
        str(args.get("objective") or args.get("goal") or "").strip()
    )
    status_arg = str(args.get("status") or "").strip()
    return {
        "schema_version": GOAL_LIFECYCLE_SCHEMA_VERSION,
        "event_id": event.event_id,
        "kind": kind,
        "tool_name": normalized_tool_name(tool_name) or tool_name,
        "tool_namespace": str(facets.get("tool_namespace") or tool_namespace_for_name(tool_name) if tool_name else ""),
        "objective": objective,
        "status_arg": status_arg,
        "usage": goal_usage_fields_from_mapping(args),
        "timestamp": event.timestamp,
        "line": event.line_no,
        "correlation_id": event.correlation_id,
        "task_episode_id": task_episode_id,
        "refs": ref,
        "route_signals": (
            [
                route_signal_token(
                    "goal",
                    str(signal.get("key") or ""),
                )
                for signal in event_route_signals(event)
                if str(signal.get("layer") or "") == "goal"
                and str(signal.get("key") or "")
            ]
            or [route_signal_token("goal", kind)]
        ),
    }


def new_goal_lifecycle(
    *,
    session_id: str,
    session_label: str,
    ordinal: int,
    flags: list[str] | None = None,
) -> dict[str, Any]:
    goal_id = f"goal-{ordinal:04d}"
    return {
        "schema_version": GOAL_LIFECYCLE_SCHEMA_VERSION,
        "goal_id": goal_id,
        "goal_instance_id": f"{session_id}:{goal_id}",
        "session_id": session_id,
        "session_label": session_label,
        "status": "unknown",
        "objective": "",
        "event_count": 0,
        "event_kinds": [],
        "event_ids": [],
        "events": [],
        "task_episode_ids": [],
        "raw_refs": [],
        "segment_refs": [],
        "graph_refs": [],
        "usage": {},
        "usage_observations": [],
        "observed_goal": {},
        "state_observations": [],
        "objective_source": "",
        "ambiguity_flags": list(flags or []),
    }


def goal_lifecycle_event_kinds(event: dict[str, Any]) -> list[str]:
    kinds = [str(event.get("kind") or "")]
    route_signals = event.get("route_signals")
    if isinstance(route_signals, list):
        for signal in route_signals:
            if isinstance(signal, str):
                layer, _, key = signal.partition(":")
                if layer == "goal":
                    kinds.append(key)
            elif isinstance(signal, dict) and str(signal.get("layer") or "") == "goal":
                kinds.append(str(signal.get("key") or ""))
    return unique_preserving_order(kinds)


def append_goal_lifecycle_event(lifecycle: dict[str, Any], event: dict[str, Any]) -> None:
    events = lifecycle.setdefault("events", [])
    if isinstance(events, list):
        events.append(event)
    lifecycle["event_count"] = int_value(lifecycle.get("event_count"), 0) + 1
    kind = str(event.get("kind") or "")
    event_kinds = goal_lifecycle_event_kinds(event)
    lifecycle["event_kinds"] = unique_preserving_order([*lifecycle.get("event_kinds", []), *event_kinds])
    lifecycle["event_ids"] = unique_preserving_order([*lifecycle.get("event_ids", []), event.get("event_id")])
    task_episode_id = str(event.get("task_episode_id") or "")
    lifecycle["task_episode_ids"] = unique_preserving_order([*lifecycle.get("task_episode_ids", []), task_episode_id])
    refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
    lifecycle["raw_refs"] = unique_preserving_order([*lifecycle.get("raw_refs", []), refs.get("raw_ref")])
    lifecycle["segment_refs"] = unique_preserving_order([*lifecycle.get("segment_refs", []), refs.get("segment_ref")])
    lifecycle["graph_refs"] = unique_preserving_order(
        [
            *lifecycle.get("graph_refs", []),
            refs.get("graph_event_node"),
            *(graph_route_node_id("goal", event_kind) for event_kind in event_kinds),
        ]
    )
    if not lifecycle.get("first_ref"):
        lifecycle["first_ref"] = refs
    lifecycle["last_ref"] = refs
    if kind == "goal_create_requested":
        lifecycle["requested_ref"] = refs
        lifecycle["status"] = "create_requested"
    elif kind == "goal_create_failed":
        lifecycle["failed_ref"] = refs
        lifecycle["status"] = "create_failed"
        goal_lifecycle_add_flag(lifecycle, "create_rejected")
    elif kind == "goal_created":
        lifecycle["created_ref"] = refs
        lifecycle["status"] = "active"
    elif kind == "goal_completed":
        lifecycle["completed_ref"] = refs
        lifecycle["status"] = "complete"
    elif kind == "goal_blocked":
        lifecycle["blocked_ref"] = refs
        lifecycle["status"] = "blocked"
    elif kind == "goal_updated" and lifecycle.get("status") in {"unknown", "active", "inspected"}:
        lifecycle["status"] = "updated"
    elif kind == "goal_inspected" and lifecycle.get("status") == "unknown":
        lifecycle["status"] = "inspected"
    objective = str(event.get("objective") or "").strip()
    if objective and not lifecycle.get("objective"):
        lifecycle["objective"] = objective
        lifecycle["objective_source"] = "goal_tool_args"
    usage = event.get("usage") if isinstance(event.get("usage"), dict) else {}
    if usage:
        observations = lifecycle.setdefault("usage_observations", [])
        if isinstance(observations, list):
            observations.append({"source": "goal_tool_args", "event_id": event.get("event_id"), "usage": usage})
        merged_usage = lifecycle.setdefault("usage", {})
        if isinstance(merged_usage, dict):
            merged_usage.update({key: value for key, value in usage.items() if compact_value_present(value)})


def append_goal_lifecycle_output_observation(
    lifecycle: dict[str, Any],
    raw_event: RawEvent,
    *,
    segments: list[dict[str, Any]],
    session_id: str,
    task_episodes: list[dict[str, Any]],
    usage_output: dict[str, Any],
    state_output: dict[str, Any],
) -> None:
    task_episode_id = task_episode_id_for_event(raw_event, task_episodes)
    ref = goal_event_ref(raw_event, segments, session_id=session_id, task_episode_id=task_episode_id)
    if usage_output:
        observations = lifecycle.setdefault("usage_observations", [])
        if isinstance(observations, list):
            observations.append(
                {
                    "source": "goal_tool_output",
                    "event_id": raw_event.event_id,
                    "usage": usage_output,
                    "refs": ref,
                }
            )
        merged_usage = lifecycle.setdefault("usage", {})
        if isinstance(merged_usage, dict):
            merged_usage.update({key: value for key, value in usage_output.items() if compact_value_present(value)})
    if not state_output:
        return
    observations = lifecycle.setdefault("state_observations", [])
    if isinstance(observations, list):
        observations.append(
            {
                "source": "goal_tool_output",
                "event_id": raw_event.event_id,
                "state": state_output,
                "refs": ref,
            }
        )
    observed_goal = lifecycle.setdefault("observed_goal", {})
    if isinstance(observed_goal, dict):
        for key, value in state_output.items():
            if compact_value_present(value):
                observed_goal[key] = value
    objective = str(state_output.get("objective") or "").strip()
    if objective and not lifecycle.get("objective"):
        lifecycle["objective"] = objective
        lifecycle["objective_source"] = "goal_tool_output"
        goal_lifecycle_add_flag(lifecycle, "objective_from_goal_inspection")
    status = str(state_output.get("status") or "").strip().lower()
    if status in {"active", "complete", "blocked"} and lifecycle.get("status") in {"unknown", "inspected"}:
        lifecycle["status"] = status
    if state_output.get("createdAt") and "missing_create" in lifecycle.get("ambiguity_flags", []):
        goal_lifecycle_add_flag(lifecycle, "create_time_from_goal_inspection")


def goal_lifecycle_add_flag(lifecycle: dict[str, Any], flag: str) -> None:
    flags = lifecycle.setdefault("ambiguity_flags", [])
    if isinstance(flags, list) and flag not in flags:
        flags.append(flag)


def goal_lifecycle_counts_for_lifecycles(lifecycles: list[dict[str, Any]], goal_events: list[dict[str, Any]]) -> dict[str, Any]:
    return {
        "total": len(lifecycles),
        "event_total": len(goal_events),
        "by_status": dict(sorted(Counter(str(item.get("status") or "unknown") for item in lifecycles).items())),
        "by_event_kind": dict(sorted(Counter(str(item.get("kind") or "unknown") for item in goal_events).items())),
        "with_missing_create": sum(1 for item in lifecycles if "missing_create" in item.get("ambiguity_flags", [])),
        "with_missing_close": sum(1 for item in lifecycles if "missing_close" in item.get("ambiguity_flags", [])),
    }


def goal_lifecycle_line_range(
    lifecycle: dict[str, Any],
) -> tuple[int, int] | None:
    lines = [
        int_value(item.get("line"))
        for item in (
            lifecycle.get("events")
            if isinstance(lifecycle.get("events"), list)
            else []
        )
        if isinstance(item, dict) and int_value(item.get("line")) > 0
    ]
    if not lines:
        for raw_ref in (
            lifecycle.get("raw_refs")
            if isinstance(lifecycle.get("raw_refs"), list)
            else []
        ):
            matched = re.search(r"raw:line:(\d+)", str(raw_ref or ""))
            if matched:
                lines.append(int(matched.group(1)))
    return (min(lines), max(lines)) if lines else None


def incremental_goal_lifecycles_for_events(
    *,
    events: list[RawEvent],
    segments: list[dict[str, Any]],
    task_episodes: list[dict[str, Any]],
    previous_index: dict[str, Any],
    replay_from_line: int,
    session_id: str,
    session_label: str,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    """Merge stable goal lifecycles with one bounded affected tail."""
    previous_lifecycles = (
        previous_index.get("goal_lifecycles")
        if isinstance(previous_index.get("goal_lifecycles"), list)
        else None
    )
    previous_events = (
        previous_index.get("goal_events")
        if isinstance(previous_index.get("goal_events"), list)
        else None
    )
    if (
        replay_from_line <= 0
        or previous_lifecycles is None
        or previous_events is None
    ):
        return None, {
            "mode": "full_event_reduction_required",
            "reason": "previous_goal_components_unavailable",
        }
    stable_lifecycles: list[dict[str, Any]] = []
    for lifecycle in previous_lifecycles:
        if not isinstance(lifecycle, dict):
            return None, {
                "mode": "full_event_reduction_required",
                "reason": "previous_goal_lifecycle_invalid",
            }
        line_range = goal_lifecycle_line_range(lifecycle)
        if line_range is None:
            return None, {
                "mode": "full_event_reduction_required",
                "reason": "previous_goal_lifecycle_range_unavailable",
            }
        if line_range[1] < replay_from_line:
            stable_lifecycles.append(dict(lifecycle))
            continue
        if line_range[0] < replay_from_line:
            return None, {
                "mode": "full_event_reduction_required",
                "reason": "goal_lifecycle_crosses_replay_boundary",
                "required_replay_from_line": line_range[0],
            }
    stable_events = [
        dict(item)
        for item in previous_events
        if isinstance(item, dict)
        and int_value(item.get("line")) > 0
        and int_value(item.get("line")) < replay_from_line
    ]
    tail = generated_goal_lifecycles_for_events(
        events,
        segments,
        task_episodes,
        session_id=session_id,
        session_label=session_label,
        ordinal_offset=len(stable_lifecycles),
    )
    tail_lifecycles = [
        dict(item)
        for item in tail.get("goal_lifecycles", [])
        if isinstance(item, dict)
    ]
    tail_events = [
        dict(item)
        for item in tail.get("goal_events", [])
        if isinstance(item, dict)
        and int_value(item.get("line")) >= replay_from_line
    ]
    combined_lifecycles = [*stable_lifecycles, *tail_lifecycles]
    combined_events = [*stable_events, *tail_events]
    goal_ids = [
        str(item.get("goal_id") or "")
        for item in combined_lifecycles
    ]
    event_ids = [
        str(item.get("event_id") or "") for item in combined_events
    ]
    if (
        len(set(goal_ids)) != len(goal_ids)
        or len(set(event_ids)) != len(event_ids)
    ):
        return None, {
            "mode": "full_event_reduction_required",
            "reason": "incremental_goal_identity_collision",
        }
    return {
        "goal_lifecycles": combined_lifecycles,
        "goal_events": combined_events,
        "goal_lifecycle_counts": goal_lifecycle_counts_for_lifecycles(
            combined_lifecycles, combined_events
        ),
        "goal_event_counts": dict(
            sorted(
                Counter(
                    str(item.get("kind") or "unknown")
                    for item in combined_events
                ).items()
            )
        ),
    }, {
        "mode": "append_stable_goal_tail_merge_v1",
        "replay_from_line": replay_from_line,
        "stable_lifecycle_count": len(stable_lifecycles),
        "rebuilt_lifecycle_count": len(tail_lifecycles),
        "stable_event_count": len(stable_events),
        "rebuilt_event_count": len(tail_events),
    }


def goal_lifecycle_incremental_replay_admitted(
    previous_index: dict[str, Any], replay_from_line: int
) -> bool:
    lifecycles = previous_index.get("goal_lifecycles")
    goal_events = previous_index.get("goal_events")
    if not isinstance(lifecycles, list) or not isinstance(goal_events, list):
        return False
    for lifecycle in lifecycles:
        if not isinstance(lifecycle, dict):
            return False
        line_range = goal_lifecycle_line_range(lifecycle)
        if line_range is None:
            return False
        if line_range[0] < replay_from_line <= line_range[1]:
            return False
    return True


def generated_goal_lifecycles_for_events(
    events: list[RawEvent],
    segments: list[dict[str, Any]],
    task_episodes: list[dict[str, Any]],
    *,
    session_id: str,
    session_label: str,
    ordinal_offset: int = 0,
) -> dict[str, Any]:
    lifecycles: list[dict[str, Any]] = []
    goal_events: list[dict[str, Any]] = []
    current: dict[str, Any] | None = None
    correlation_to_lifecycle: dict[str, dict[str, Any]] = {}
    ordinal = max(0, ordinal_offset)
    compaction_lines = [event.line_no for event in events if event.compaction_boundary or event.event_type == "COMPACTION_EVENT"]

    for raw_event in events:
        usage_output = goal_usage_fields_from_output_event(raw_event)
        state_output = goal_state_fields_from_output_event(raw_event)
        if (usage_output or state_output) and raw_event.correlation_id in correlation_to_lifecycle:
            lifecycle = correlation_to_lifecycle[raw_event.correlation_id]
            append_goal_lifecycle_output_observation(
                lifecycle,
                raw_event,
                segments=segments,
                session_id=session_id,
                task_episodes=task_episodes,
                usage_output=usage_output,
                state_output=state_output,
            )
            continue

        goal_event = goal_event_from_raw_event(
            raw_event,
            session_id=session_id,
            segments=segments,
            task_episodes=task_episodes,
        )
        if not goal_event:
            continue
        goal_events.append(goal_event)
        kind = str(goal_event.get("kind") or "")
        if kind in {"goal_create_requested", "goal_created"}:
            if current is not None and current.get("status") not in {"complete", "blocked"}:
                goal_lifecycle_add_flag(current, "missing_close")
            ordinal += 1
            current = new_goal_lifecycle(session_id=session_id, session_label=session_label, ordinal=ordinal)
            lifecycles.append(current)
        elif current is None:
            ordinal += 1
            current = new_goal_lifecycle(
                session_id=session_id,
                session_label=session_label,
                ordinal=ordinal,
                flags=["missing_create"],
            )
            lifecycles.append(current)

        append_goal_lifecycle_event(current, goal_event)
        if goal_event.get("correlation_id"):
            correlation_to_lifecycle[str(goal_event["correlation_id"])] = current
        if kind == "goal_updated" and sum(
            1 for item in current.get("events", []) if isinstance(item, dict) and item.get("kind") == "goal_updated"
        ) > 1:
            goal_lifecycle_add_flag(current, "repeated_update")
        if not goal_event.get("refs", {}).get("raw_ref"):
            goal_lifecycle_add_flag(current, "raw_unavailable")
        if kind in GOAL_TERMINAL_SESSION_ACTS:
            current = None

    for lifecycle in lifecycles:
        if lifecycle.get("status") not in {"create_failed", "complete", "blocked"}:
            goal_lifecycle_add_flag(lifecycle, "missing_close")
        event_lines = [
            int_value(event.get("line"), 0)
            for event in lifecycle.get("events", [])
            if isinstance(event, dict) and int_value(event.get("line"), 0)
        ]
        if event_lines and any(min(event_lines) <= line <= max(event_lines) for line in compaction_lines):
            goal_lifecycle_add_flag(lifecycle, "compaction_boundary")
        if not lifecycle.get("raw_refs"):
            goal_lifecycle_add_flag(lifecycle, "raw_unavailable")

    return {
        "goal_lifecycles": lifecycles,
        "goal_events": goal_events,
        "goal_lifecycle_counts": goal_lifecycle_counts_for_lifecycles(lifecycles, goal_events),
        "goal_event_counts": dict(sorted(Counter(str(item.get("kind") or "unknown") for item in goal_events).items())),
    }


def event_index_record(
    event: RawEvent,
    md_name: str,
    relationships: list[dict[str, Any]] | None = None,
    *,
    literal_policy: DerivedSessionSensitiveLiteralPolicy | None = None,
    token_observations: list[dict[str, Any]] | None = None,
    markdown_anchor_materialized: bool = True,
    redact_output: bool = True,
) -> dict[str, Any]:
    observed_tokens = (
        token_accounting_for_event(event)
        if token_observations is None
        else token_observations
    )
    record = {
        "event_id": event.event_id,
        "line": event.line_no,
        "type": event.event_type,
        "family": event.family,
        "phase": event.phase,
        "actor": event.actor,
        "action": event.action,
        "object": event.object_ref,
        "outcome": event.outcome,
        "confidence": event.confidence,
        "title": event.title,
        "importance": event.importance,
        "tags": event.tags,
        "md_anchor": (
            f"{md_name}#{anchor_for(event)}"
            if markdown_anchor_materialized
            else md_name
        ),
        "markdown_anchor_materialized": markdown_anchor_materialized,
        "raw_ref": f"raw:line:{event.line_no}",
        "timestamp": event.timestamp,
        "source_type": event.source_type,
    }
    if event.correlation_id:
        record["correlation_id"] = event.correlation_id
    if event.facets:
        record["facets"] = event.facets
    if observed_tokens:
        record["token_accounting"] = (
            observed_tokens[0]
            if len(observed_tokens) == 1
            else token_accounting_summary_for_observations(
                observed_tokens,
                scope={"kind": "event", "event_id": event.event_id, "raw_ref": f"raw:line:{event.line_no}"},
                include_observations=True,
            )
        )
    if relationships:
        record["relationships"] = relationships
    if len(event.raw) > DERIVED_SEGMENT_RAW_VIEW_MAX_CHARS:
        record["raw_body_view"] = {
            "status": "omitted_large_raw_event",
            "raw_chars": len(event.raw),
            "authority_boundary": (
                "generated body omitted; open raw_ref for evidence"
            ),
        }
    if not redact_output:
        return record
    return redact_derived_value(
        record,
        literal_policy=literal_policy,
    )


def raw_block_status_for_role(role: str) -> str:
    return "sealed" if role in {"initial-to-compaction", "compaction-to-compaction"} else "open"


def clear_generated_raw_blocks(session_dir: Path) -> None:
    raw_dir = session_dir / "raw"
    blocks_dir = raw_dir / RAW_BLOCKS_DIR
    if blocks_dir.exists():
        for path in blocks_dir.iterdir():
            if path.name.endswith(".raw.jsonl") or path.name.endswith(".raw.jsonl.gz") or path.name == RAW_BLOCK_INDEX_JSON:
                path.unlink()
    compaction_events_path = raw_dir / RAW_COMPACTION_EVENTS_JSONL
    if compaction_events_path.exists():
        compaction_events_path.unlink()


def write_raw_block_artifacts(
    session_dir: Path,
    raw_rel: str,
    ranges: list[tuple[int, int, str]],
    events: list[RawEvent],
    *,
    reference_session_dir: Path | None = None,
    publish_identity: dict[str, Any] | None = None,
    published_raw_blocks: dict[str, Any] | None = None,
    attested_prefix_to_line: int = 0,
    execution_metrics_out: dict[str, Any] | None = None,
    segment_no_offset: int = 0,
    prefix_block_records: list[dict[str, Any]] | None = None,
    defer_token_accounting: bool = False,
) -> dict[str, Any]:
    raw_dir = session_dir / "raw"
    reference_raw_dir = (
        (reference_session_dir or session_dir) / "raw"
    )
    blocks_dir = raw_dir / RAW_BLOCKS_DIR
    reference_blocks_dir = reference_raw_dir / RAW_BLOCKS_DIR
    blocks_dir.mkdir(parents=True, exist_ok=True)
    block_records: list[dict[str, Any]] = [
        dict(item)
        for item in (prefix_block_records or [])
        if isinstance(item, dict)
    ]
    compaction_records: list[dict[str, Any]] = []
    token_accounting_seconds = 0.0
    reused_block_count = len(block_records)
    attested_sealed_reused_block_count = len(block_records)
    rebuilt_block_count = 0
    deferred_token_accounting_block_count = 0
    prior_blocks_by_segment = {
        str(item.get("segment_id") or ""): item
        for item in (
            published_raw_blocks.get("blocks", [])
            if isinstance(published_raw_blocks, dict)
            and isinstance(published_raw_blocks.get("blocks"), list)
            else []
        )
        if isinstance(item, dict) and item.get("segment_id")
    }
    for prefix_block in block_records:
        relative = Path(str(prefix_block.get("rel") or ""))
        source_block_path = reference_session_dir / relative if (
            reference_session_dir is not None
            and relative
            and not relative.is_absolute()
        ) else Path(str(prefix_block.get("path") or ""))
        target_block_path = blocks_dir / source_block_path.name
        if not source_block_path.is_file():
            raise ValueError("incremental_prefix_raw_block_missing")
        target_block_path.unlink(missing_ok=True)
        stage_projection_path_with_links(
            source=source_block_path,
            target=target_block_path,
        )
    if reference_session_dir is not None and block_records:
        previous_compaction_path = (
            reference_session_dir
            / "raw"
            / RAW_COMPACTION_EVENTS_JSONL
        )
        if previous_compaction_path.is_file():
            prefix_ids = {
                str(item.get("segment_id") or "")
                for item in block_records
            }
            for line in previous_compaction_path.read_text(
                encoding="utf-8", errors="replace"
            ).splitlines():
                try:
                    item = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if (
                    isinstance(item, dict)
                    and str(item.get("segment_id") or "") in prefix_ids
                ):
                    compaction_records.append(dict(item))
    for local_segment_no, (start, end, role) in enumerate(ranges):
        segment_no = segment_no_offset + local_segment_no
        segment_id = f"{segment_no:03d}"
        block_name = f"{segment_id}__{role}.raw.jsonl"
        block_path = blocks_dir / block_name
        block_events = events[start:end]
        first_line = block_events[0].line_no if block_events else None
        last_line = block_events[-1].line_no if block_events else None
        boundary_events = [event for event in block_events if event.compaction_boundary]
        source_block_path = reference_blocks_dir / block_name
        prior_block = prior_blocks_by_segment.get(segment_id)
        prior_summary = (
            prior_block.get("token_accounting")
            if isinstance(prior_block, dict)
            and isinstance(prior_block.get("token_accounting"), dict)
            else {}
        )
        prior_range = (
            prior_block.get("source_range")
            if isinstance(prior_block, dict)
            and isinstance(prior_block.get("source_range"), dict)
            else {}
        )
        attested_sealed_reuse = bool(
            isinstance(prior_block, dict)
            and raw_block_status_for_role(role) == "sealed"
            and int_value(last_line) <= attested_prefix_to_line
            and str(prior_block.get("role") or "") == role
            and int_value(prior_block.get("line_count"), -1)
            == len(block_events)
            and prior_range.get("from_line") == first_line
            and prior_range.get("to_line") == last_line
            and source_block_path.is_file()
            and source_block_path.stat().st_size
            == int_value(prior_block.get("bytes"), -1)
        )
        if attested_sealed_reuse:
            block_bytes = int_value(prior_block.get("bytes"))
            block_sha256 = str(prior_block.get("sha256") or "")
        else:
            block_hasher = hashlib.sha256()
            block_bytes = 0
            for event in block_events:
                encoded = event.raw.encode("utf-8")
                block_hasher.update(encoded)
                block_hasher.update(b"\n")
                block_bytes += len(encoded) + 1
            block_sha256 = block_hasher.hexdigest()
        reusable_block = bool(
            attested_sealed_reuse
            or (
            isinstance(prior_block, dict)
            and str(prior_block.get("role") or "") == role
            and int_value(prior_block.get("line_count"), -1)
            == len(block_events)
            and int_value(prior_block.get("bytes"), -1)
            == block_bytes
            and str(prior_block.get("sha256") or "")
            == block_sha256
            and prior_range.get("from_line") == first_line
            and prior_range.get("to_line") == last_line
            and source_block_path.is_file()
            and source_block_path.stat().st_size == block_bytes
            and sha256_file(source_block_path) == block_sha256
            )
        )
        if reusable_block:
            block_path.unlink(missing_ok=True)
            stage_projection_path_with_links(
                source=source_block_path,
                target=block_path,
            )
            reused_block_count += 1
            if attested_sealed_reuse:
                attested_sealed_reused_block_count += 1
        else:
            with block_path.open("w", encoding="utf-8") as handle:
                for event in block_events:
                    handle.write(event.raw)
                    handle.write("\n")
            rebuilt_block_count += 1
        token_started = time.monotonic()
        if reusable_block and token_accounting_summary_schema_current(
            prior_summary
        ):
            block_token_accounting = prior_summary
        elif defer_token_accounting:
            block_token_accounting = None
            deferred_token_accounting_block_count += 1
        else:
            block_token_accounting = token_accounting_summary_for_events(
                block_events,
                scope={
                    "kind": "raw_block",
                    "block_id": segment_id,
                    "segment_id": segment_id,
                    "role": role,
                },
                include_observations=False,
            )
        token_accounting_seconds += time.monotonic() - token_started
        block_stat = block_path.stat()
        record = {
            "block_id": segment_id,
            "segment_id": segment_id,
            "role": role,
            "status": raw_block_status_for_role(role),
            "storage_mode": RAW_BLOCK_STORAGE_MODE_PLAIN,
            "path": str(reference_blocks_dir / block_name),
            "rel": f"raw/{RAW_BLOCKS_DIR}/{block_name}",
            "plain_path": str(reference_blocks_dir / block_name),
            "plain_rel": f"raw/{RAW_BLOCKS_DIR}/{block_name}",
            "source_raw": raw_rel,
            "source_range": {"from_line": first_line, "to_line": last_line},
            "line_count": len(block_events),
            "bytes": block_bytes,
            "sha256": block_sha256,
            "closed_by_compaction": bool(boundary_events),
            "boundary_event_ids": [event.event_id for event in boundary_events],
            "artifact_receipts": {
                "plain": {
                    "bytes": block_stat.st_size,
                    "sha256": block_sha256,
                    "mtime_ns": block_stat.st_mtime_ns,
                    "ctime_ns": block_stat.st_ctime_ns,
                },
            },
        }
        if block_token_accounting is not None:
            record["token_accounting"] = block_token_accounting
        block_records.append(record)
        for event in boundary_events:
            compaction_records.append(
                {
                    "schema_version": SCHEMA_VERSION,
                    "segment_id": segment_id,
                    "block_id": segment_id,
                    "event_id": event.event_id,
                    "line": event.line_no,
                    "timestamp": event.timestamp,
                    "title": event.title,
                    "source_type": event.source_type,
                    "raw_ref": f"raw:line:{event.line_no}",
                }
            )

    write_json(
        raw_dir / RAW_BLOCK_INDEX_JSON,
        {
            "schema_version": SCHEMA_VERSION,
            "source_raw": raw_rel,
            "projection_publish": publish_identity or {},
            "blocks": block_records,
        },
    )
    compaction_path = raw_dir / RAW_COMPACTION_EVENTS_JSONL
    if compaction_records:
        compaction_path.write_text(
            "\n".join(json.dumps(record, ensure_ascii=False) for record in compaction_records) + "\n",
            encoding="utf-8",
        )
    else:
        compaction_path.write_text("", encoding="utf-8")
    if execution_metrics_out is not None:
        execution_metrics_out.clear()
        execution_metrics_out.update(
            {
                "reused_block_count": reused_block_count,
                "attested_sealed_reused_block_count": (
                    attested_sealed_reused_block_count
                ),
                "rebuilt_block_count": rebuilt_block_count,
                "token_accounting_ms": int(
                    token_accounting_seconds * 1000
                ),
                "token_accounting_mode": (
                    "deferred_to_segment_components_v1"
                    if deferred_token_accounting_block_count
                    else "raw_block_event_reduction_v1"
                ),
                "deferred_token_accounting_block_count": (
                    deferred_token_accounting_block_count
                ),
            }
        )
    return {
        "index": str(reference_raw_dir / RAW_BLOCK_INDEX_JSON),
        "compaction_events": str(
            reference_raw_dir / RAW_COMPACTION_EVENTS_JSONL
        ),
        "projection_publish": publish_identity or {},
        "blocks": block_records,
    }


def immutable_component_artifact_receipt(path: Path) -> dict[str, Any]:
    stat = path.stat()
    receipt = {
        "bytes": stat.st_size,
        "sha256": sha256_file(path),
        "mtime_ns": stat.st_mtime_ns,
        "ctime_ns": stat.st_ctime_ns,
    }
    if path.name.endswith(".index.json"):
        receipt["semantic_sha256"] = (
            session_projection_json_semantic_sha256(
                read_json(path, {})
            )
        )
        receipt["semantic_mode"] = (
            "canonical_json_without_projection_clocks_v1"
        )
    return receipt


def immutable_component_artifact_receipt_metadata_current(
    path: Path, receipt: Any
) -> bool:
    if not isinstance(receipt, dict) or not path.is_file():
        return False
    stat = path.stat()
    ctime_current = bool(
        receipt.get("metadata_mode") == "size_mtime_v1"
        or stat.st_ctime_ns == int_value(receipt.get("ctime_ns"), -1)
    )
    return bool(
        receipt.get("sha256")
        and stat.st_size == int_value(receipt.get("bytes"), -1)
        and stat.st_mtime_ns == int_value(receipt.get("mtime_ns"), -1)
        and ctime_current
    )


def immutable_component_artifact_receipt_from_attested_link(
    path: Path, source_receipt: dict[str, Any]
) -> dict[str, Any]:
    stat = path.stat()
    receipt = {
        "bytes": stat.st_size,
        "sha256": str(source_receipt.get("sha256") or ""),
        "mtime_ns": stat.st_mtime_ns,
        "ctime_ns": stat.st_ctime_ns,
        "metadata_mode": "size_mtime_v1",
    }
    if source_receipt.get("semantic_sha256"):
        receipt["semantic_sha256"] = str(
            source_receipt["semantic_sha256"]
        )
        receipt["semantic_mode"] = str(
            source_receipt.get("semantic_mode") or ""
        )
    elif path.name.endswith(".index.json"):
        receipt["semantic_sha256"] = (
            session_projection_json_semantic_sha256(
                read_json(path, {})
            )
        )
        receipt["semantic_mode"] = (
            "canonical_json_without_projection_clocks_v1"
        )
    return receipt


def deep_audit_artifact_receipt(
    path: Path, receipt: Any
) -> list[str]:
    """Re-hash one metadata-admitted artifact for the explicit audit lane."""
    if not isinstance(receipt, dict):
        return ["receipt_missing_or_invalid"]
    if not path.is_file():
        return ["artifact_missing"]
    stat = path.stat()
    reasons: list[str] = []
    if stat.st_size != int_value(receipt.get("bytes"), -1):
        reasons.append("artifact_byte_count_mismatch")
    expected_sha256 = str(receipt.get("sha256") or "")
    if not expected_sha256:
        reasons.append("artifact_sha256_missing")
    elif sha256_file_exact(path) != expected_sha256:
        reasons.append("artifact_sha256_mismatch")
    return reasons


def deep_audit_session_projection_artifacts(
    *, session_dir: Path, manifest: dict[str, Any]
) -> dict[str, Any]:
    """Verify immutable hot-path attestations by reading their full content."""
    diagnostics: list[str] = []
    artifact_count = 0
    content_bytes_read = 0
    segment_component_count = 0
    legacy_unreceipted_segment_count = 0
    classification_block_count = 0
    task_episode_component_count = 0

    segments = (
        manifest.get("segments")
        if isinstance(manifest.get("segments"), list)
        else []
    )
    for segment in segments:
        if not isinstance(segment, dict):
            diagnostics.append("segment_manifest_record_invalid")
            continue
        segment_id = str(segment.get("segment_id") or "unknown")
        component_identity = (
            segment.get("component_identity")
            if isinstance(segment.get("component_identity"), dict)
            else {}
        )
        receipts = (
            segment.get("artifact_receipts")
            if isinstance(segment.get("artifact_receipts"), dict)
            else {}
        )
        if not component_identity:
            legacy_unreceipted_segment_count += 1
            continue
        segment_component_count += 1
        expected_component = segment_component_identity(
            segment_id=segment_id,
            role=str(segment.get("role") or ""),
            source_range=(
                segment.get("source_range")
                if isinstance(segment.get("source_range"), dict)
                else {}
            ),
            input_digest=str(segment.get("input_digest") or ""),
            raw_block=(
                segment.get("raw_block")
                if isinstance(segment.get("raw_block"), dict)
                else None
            ),
        )
        if component_identity != expected_component:
            diagnostics.append(
                f"segment_component_identity_mismatch:{segment_id}"
            )
        artifact_paths = {
            "markdown": projection_path_from_ref(
                segment.get("markdown"), base=session_dir
            ),
            "index": projection_path_from_ref(
                segment.get("index"), base=session_dir
            ),
        }
        for role, artifact_path in artifact_paths.items():
            receipt = receipts.get(role)
            reasons = deep_audit_artifact_receipt(
                artifact_path, receipt
            )
            diagnostics.extend(
                f"segment_{role}:{segment_id}:{reason}"
                for reason in reasons
            )
            if artifact_path.is_file():
                artifact_count += 1
                content_bytes_read += artifact_path.stat().st_size
        index_payload = read_json(artifact_paths["index"], {})
        if not isinstance(index_payload, dict):
            diagnostics.append(f"segment_index_invalid:{segment_id}")
        else:
            if index_payload.get("component_identity") != (
                component_identity
            ):
                diagnostics.append(
                    f"segment_index_component_identity_mismatch:{segment_id}"
                )
            diagnostics.extend(
                f"segment_index:{segment_id}:{reason}"
                for reason in generated_segment_index_stale_reasons(
                    index_payload
                )
            )

    cache_root = event_classification_cache_root(session_dir)
    cache_index_path = event_classification_cache_index_path(cache_root)
    if cache_index_path.is_file():
        cache_index = read_json(cache_index_path, {})
        if not isinstance(cache_index, dict):
            diagnostics.append("classification_cache_index_invalid")
        else:
            generation_identity = (
                cache_index.get("generation_identity")
                if isinstance(
                    cache_index.get("generation_identity"), dict
                )
                else {}
            )
            records = (
                cache_index.get("blocks")
                if isinstance(cache_index.get("blocks"), dict)
                else {}
            )
            normalized_records = {
                str(key): dict(record)
                for key, record in records.items()
                if isinstance(record, dict)
            }
            if str(cache_index.get("records_root_sha256") or "") != (
                event_classification_cache_records_root_sha256(
                    normalized_records
                )
            ):
                diagnostics.append(
                    "classification_cache_records_root_mismatch"
                )
            for cache_key, record in normalized_records.items():
                classification_block_count += 1
                block = (
                    record.get("block")
                    if isinstance(record.get("block"), dict)
                    else {}
                )
                artifact_path = cache_root / str(
                    record.get("artifact") or ""
                )
                artifact_count += int(artifact_path.is_file())
                if artifact_path.is_file():
                    content_bytes_read += artifact_path.stat().st_size
                if not event_classification_cache_record_current(
                    cache_root=cache_root,
                    record=record,
                    block=block,
                    verify_content=True,
                ):
                    diagnostics.append(
                        "classification_cache_artifact_invalid:"
                        f"{cache_key}"
                    )
                    continue
                payload = read_gzip_json(artifact_path)
                classifications = (
                    payload.get("classifications")
                    if isinstance(payload.get("classifications"), list)
                    else []
                )
                if (
                    payload.get("generation_identity")
                    != generation_identity
                    or payload.get("block") != block
                    or len(classifications)
                    != int_value(block.get("line_count"), -1)
                ):
                    diagnostics.append(
                        "classification_cache_payload_invalid:"
                        f"{cache_key}"
                    )

    component_manifest = read_json(
        session_dir
        / SESSION_INDEX_SHARDS_DIR
        / SESSION_INDEX_SHARD_MANIFEST_JSON,
        {},
    )
    task_episode_records = (
        component_manifest.get("components", {}).get(
            "task_episodes", []
        )
        if isinstance(component_manifest, dict)
        and isinstance(component_manifest.get("components"), dict)
        and isinstance(
            component_manifest.get("components", {}).get(
                "task_episodes"
            ),
            list,
        )
        else []
    )
    expected_parent = (
        Path(SESSION_INDEX_SHARDS_DIR)
        / SESSION_INDEX_TASK_EPISODE_SHARDS_DIR
    )
    for ordinal, record in enumerate(task_episode_records):
        if not isinstance(record, dict):
            diagnostics.append(
                f"task_episode_shard_record_invalid:{ordinal}"
            )
            continue
        relative = Path(str(record.get("ref") or ""))
        if (
            relative.is_absolute()
            or ".." in relative.parts
            or relative.parent != expected_parent
            or relative.suffix != ".json"
        ):
            diagnostics.append(
                f"task_episode_shard_ref_invalid:{ordinal}"
            )
            continue
        artifact_path = session_dir / relative
        task_episode_component_count += 1
        artifact_count += int(artifact_path.is_file())
        if artifact_path.is_file():
            content_bytes_read += artifact_path.stat().st_size
        receipt = record.get("artifact_receipt")
        diagnostics.extend(
            f"task_episode_shard:{ordinal}:{reason}"
            for reason in deep_audit_artifact_receipt(
                artifact_path,
                receipt,
            )
        )
        artifact_sha256 = str(record.get("artifact_sha256") or "")
        if artifact_path.stem != artifact_sha256:
            diagnostics.append(
                f"task_episode_shard_filename_mismatch:{ordinal}"
            )
        envelope = read_json(artifact_path, {})
        payload = (
            envelope.get("payload")
            if isinstance(envelope.get("payload"), dict)
            else None
        )
        if (
            not isinstance(payload, dict)
            or envelope.get("artifact_type")
            != "session_index_component_shard"
            or envelope.get("component") != "task_episodes"
            or str(envelope.get("component_key") or "")
            != str(record.get("component_key") or "")
            or session_index_shard_payload_sha256(payload)
            != str(record.get("payload_sha256") or "")
            or str(envelope.get("payload_sha256") or "")
            != str(record.get("payload_sha256") or "")
        ):
            diagnostics.append(
                f"task_episode_shard_payload_invalid:{ordinal}"
            )

    return {
        "schema_version": 1,
        "status": "current" if not diagnostics else "failed",
        "ok": not diagnostics,
        "session_dir": str(session_dir),
        "artifact_count": artifact_count,
        "content_bytes_read": content_bytes_read,
        "segment_component_count": segment_component_count,
        "legacy_unreceipted_segment_count": (
            legacy_unreceipted_segment_count
        ),
        "classification_block_count": classification_block_count,
        "task_episode_component_count": (
            task_episode_component_count
        ),
        "diagnostics": diagnostics,
        "admission": (
            "full_sha256_rehash_of_hot_metadata_attestations_v1"
        ),
    }


def segment_component_identity(
    *,
    segment_id: str,
    role: str,
    source_range: dict[str, Any],
    input_digest: str,
    raw_block: dict[str, Any] | None,
    generation_identity: dict[str, Any] | None = None,
) -> dict[str, Any]:
    generation = generation_identity or segment_index_generation_identity()
    payload = {
        "schema_version": 1,
        "component_type": "segment_index",
        "segment_id": segment_id,
        "role": role,
        "source_range": dict(source_range),
        "input_digest": input_digest,
        "raw_block_sha256": str(
            (raw_block or {}).get("sha256") or ""
        ),
        "generation_id": str(generation.get("generation_id") or ""),
    }
    return {
        **payload,
        "component_id": hashlib.sha256(
            json.dumps(
                payload,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest(),
    }


def write_segment(
    session_dir: Path,
    raw_rel: str,
    segment_no: int,
    role: str,
    events: list[RawEvent],
    raw_block: dict[str, Any] | None = None,
    *,
    reference_session_dir: Path | None = None,
    publish_identity: dict[str, Any] | None = None,
    literal_policy: DerivedSessionSensitiveLiteralPolicy | None = None,
    markdown_render_mode: str = "index_first_compact_v1",
    classification_metadata_pre_redacted: bool = False,
) -> dict[str, Any]:
    segment_id = f"{segment_no:03d}"
    md_name = f"{segment_id}__{role}.md"
    index_name = f"{segment_id}__{role}.index.json"
    md_path = session_dir / "segments" / md_name
    index_path = session_dir / "segments" / index_name
    reference_segments_dir = (
        reference_session_dir or session_dir
    ) / "segments"
    reference_md_path = reference_segments_dir / md_name
    reference_index_path = reference_segments_dir / index_name
    md_path.parent.mkdir(parents=True, exist_ok=True)

    first_line = events[0].line_no if events else None
    last_line = events[-1].line_no if events else None
    input_digest = session_projection_segment_input_digest(
        events=events,
        role=role,
        raw_block=raw_block,
    )
    full_markdown_render = markdown_render_mode == "full_review_v1"
    compact_review_limit = max(2, SEGMENT_COMPACT_REVIEW_EVENT_LIMIT)
    compact_review_head = compact_review_limit // 2
    compact_review_tail = compact_review_limit - compact_review_head
    compact_review_events = (
        list(events)
        if len(events) <= compact_review_limit
        else [
            *events[:compact_review_head],
            *events[-compact_review_tail:],
        ]
    )
    compact_review_event_ids = {
        event.event_id for event in compact_review_events
    }
    event_views = (
        [
            (
                event,
                *derived_segment_event_view(
                    event,
                    literal_policy=literal_policy,
                ),
            )
            for event in events
        ]
        if full_markdown_render
        else []
    )
    redaction_kind_counts: Counter[str] = Counter()
    redacted_event_count = 0
    for _event, _view, report in event_views:
        if report.get("redacted"):
            redacted_event_count += 1
        redaction_kind_counts.update(
            report.get("kind_counts")
            if isinstance(report.get("kind_counts"), dict)
            else {}
        )
    segment_redaction = {
        "policy_version": DERIVED_TEXT_REDACTION_POLICY_VERSION,
        "redacted_event_count": redacted_event_count,
        "redaction_count": sum(redaction_kind_counts.values()),
        "kind_counts": dict(sorted(redaction_kind_counts.items())),
        "raw_authority_preserved": True,
        "markdown_render_mode": markdown_render_mode,
        "full_raw_views_rendered": full_markdown_render,
        "session_sensitive_literals": (
            literal_policy.report()
            if literal_policy is not None
            else {
                "policy_version": DERIVED_TEXT_REDACTION_POLICY_VERSION,
                "literal_count": 0,
                "values_persisted": False,
                "reversible_digests_persisted": False,
            }
        ),
    }
    lines = [
        "---",
        "aoa_artifact_type: codex_compaction_segment",
        "schema_version: 1",
        f"derived_text_redaction_policy_version: {DERIVED_TEXT_REDACTION_POLICY_VERSION}",
        f"segment_id: {segment_id}",
        f"segment_role: {role}",
        f"source_raw: {raw_rel}",
        f"source_block: {raw_block.get('rel') if isinstance(raw_block, dict) else ''}",
        f"source_from_line: {first_line}",
        f"source_to_line: {last_line}",
        "status: generated_redacted_view",
        f"index: ./{index_name}",
        "---",
        "",
        f"# Segment {segment_id}: {role}",
        "",
        "## Legend",
        "",
        "This file presents one Codex session interval as generated Markdown.",
        "Credential-bearing values and oversized bodies are omitted from this view.",
        "The raw transcript and raw block remain authoritative and unchanged.",
        "It is generated from raw JSONL and is not final reviewed truth.",
        "Use the sibling index file to locate event types before reading the full segment.",
        "Promote claims only after reviewing raw refs or the relevant event body.",
        "",
    ]
    if full_markdown_render:
        for event, redacted_event_view, redaction_report in event_views:
            anchor = anchor_for(event)
            lines.extend(
                [
                    f'<a id="{anchor}"></a>',
                    "",
                    f"## EVENT {event.event_id} - {event.event_type} - {event.importance}",
                    f"- line: {event.line_no}",
                    f"- time: {event.timestamp or ''}",
                    f"- source: {event.source_type}",
                    f"- family: {event.family}",
                    f"- phase: {event.phase}",
                    f"- actor: {event.actor}",
                    f"- action: {event.action}",
                    f"- object: {event.object_ref}",
                    f"- outcome: {event.outcome}",
                    f"- refs: raw:line:{event.line_no}",
                    f"- correlation_id: {event.correlation_id or ''}",
                    f"- tags: {json.dumps(event.tags, ensure_ascii=False)}",
                    f"- derived_view_redacted: {str(bool(redaction_report.get('redacted'))).lower()}",
                    "",
                    "### Title",
                    "",
                    event.title,
                    "",
                    "### Raw",
                    "",
                    "````json",
                    markdown_escape_fence(redacted_event_view),
                    "````",
                    "",
                ]
            )
    else:
        lines.extend(
            [
                "## Index-first view",
                "",
                "Raw event bodies are rendered only on explicit review demand.",
                "The sibling JSON index and raw refs are the primary navigation surface.",
                f"Total events: {len(events)}.",
                f"Synopsis events: {len(compact_review_events)}.",
                f"Events omitted from synopsis: {max(0, len(events) - len(compact_review_events))}.",
                "",
            ]
        )
        for event in compact_review_events:
            lines.extend(
                [
                    f'<a id="{anchor_for(event)}"></a>',
                    "",
                    f"## EVENT {event.event_id} - {event.event_type} - {event.importance}",
                    f"- line: {event.line_no}",
                    f"- time: {event.timestamp or ''}",
                    f"- source: {event.source_type}",
                    f"- family: {event.family}",
                    f"- phase: {event.phase}",
                    f"- actor: {event.actor}",
                    f"- action: {event.action}",
                    f"- outcome: {event.outcome}",
                    f"- refs: raw:line:{event.line_no}",
                    "",
                    "### Title",
                    "",
                    event.title,
                    "",
                ]
            )
    md_path.write_text(
        redact_derived_text(
            "\n".join(lines),
            literal_policy=literal_policy,
        ),
        encoding="utf-8",
    )

    relationship_map = event_relationships(events)
    token_observations: list[dict[str, Any]] = []
    records: list[dict[str, Any]] = []
    for event in events:
        event_token_observations = token_accounting_for_event(event)
        if classification_metadata_pre_redacted:
            # Classification metadata came from an integrity-checked cache
            # whose generation identity includes the active privacy policy.
            # Token observations are derived from parsed raw at rehydration
            # time, so sanitize that one non-cache subtree before admission.
            event_token_observations = redact_derived_value(
                event_token_observations,
                literal_policy=literal_policy,
            )
        token_observations.extend(event_token_observations)
        records.append(
            event_index_record(
                event,
                md_name,
                relationship_map.get(event.event_id, []),
                literal_policy=literal_policy,
                token_observations=event_token_observations,
                markdown_anchor_materialized=(
                    full_markdown_render
                    or event.event_id in compact_review_event_ids
                ),
                # The complete segment envelope is redacted exactly once at
                # the write boundary below.  Redacting every event here and
                # then recursively redacting the containing envelope repeats
                # the dominant privacy scan without changing its output.
                redact_output=False,
            )
        )
    by_type: dict[str, list[str]] = defaultdict(list)
    by_tag: dict[str, list[str]] = defaultdict(list)
    by_source_type: dict[str, list[str]] = defaultdict(list)
    by_family: dict[str, list[str]] = defaultdict(list)
    by_phase: dict[str, list[str]] = defaultdict(list)
    by_actor: dict[str, list[str]] = defaultdict(list)
    by_action: dict[str, list[str]] = defaultdict(list)
    by_outcome: dict[str, list[str]] = defaultdict(list)
    by_correlation: dict[str, list[str]] = defaultdict(list)
    by_conversation_act: dict[str, list[str]] = defaultdict(list)
    by_session_act: dict[str, list[str]] = defaultdict(list)
    by_agent_event: dict[str, list[str]] = defaultdict(list)
    by_route_layer: dict[str, dict[str, list[str]]] = defaultdict(lambda: defaultdict(list))
    by_route_signal: dict[str, list[str]] = defaultdict(list)
    for event in events:
        by_type[event.event_type].append(event.event_id)
        by_source_type[event.source_type].append(event.event_id)
        by_family[event.family].append(event.event_id)
        by_phase[event.phase].append(event.event_id)
        by_actor[event.actor].append(event.event_id)
        by_action[event.action].append(event.event_id)
        by_outcome[event.outcome].append(event.event_id)
        if event.correlation_id:
            by_correlation[event.correlation_id].append(event.event_id)
        conversation_act = event.facets.get("conversation_act") if isinstance(event.facets.get("conversation_act"), dict) else {}
        if conversation_act.get("kind"):
            by_conversation_act[str(conversation_act["kind"])].append(event.event_id)
        session_act = event.facets.get("session_act") if isinstance(event.facets.get("session_act"), dict) else {}
        if session_act.get("kind"):
            by_session_act[str(session_act["kind"])].append(event.event_id)
        agent_event = agent_event_for_event(event)
        if agent_event.get("class"):
            by_agent_event[str(agent_event["class"])].append(event.event_id)
        for signal in event_route_signals(event):
            layer = str(signal["layer"])
            key = str(signal["key"])
            by_route_layer[layer][key].append(event.event_id)
            by_route_signal[route_signal_token(layer, key)].append(event.event_id)
        for tag in event.tags:
            by_tag[tag].append(event.event_id)

    token_accounting = token_accounting_summary_for_observations(
        token_observations,
        scope={"kind": "segment", "segment_id": segment_id, "segment_role": role},
        include_observations=True,
    )
    compact_token_accounting = token_accounting_summary_for_observations(
        token_observations,
        scope={"kind": "segment", "segment_id": segment_id, "segment_role": role},
        include_observations=False,
    )
    if isinstance(raw_block, dict) and not token_accounting_summary_schema_current(
        raw_block.get("token_accounting")
    ):
        raw_block = {
            **raw_block,
            "token_accounting": token_accounting_rescope_summary(
                compact_token_accounting,
                scope={
                    "kind": "raw_block",
                    "block_id": segment_id,
                    "segment_id": segment_id,
                    "role": role,
                },
            ),
        }
    generation_identity = segment_index_generation_identity()
    source_range = {"from_line": first_line, "to_line": last_line}
    component_identity = segment_component_identity(
        segment_id=segment_id,
        role=role,
        source_range=source_range,
        input_digest=input_digest,
        raw_block=raw_block,
        generation_identity=generation_identity,
    )
    index = {
        "schema_version": SCHEMA_VERSION,
        "generation_id": generation_identity["generation_id"],
        "generation_identity": generation_identity,
        "component_identity": component_identity,
        "projection_publish": publish_identity or {},
        "conversation_act_schema_version": CONVERSATION_ACT_SCHEMA_VERSION,
        "session_act_schema_version": SESSION_ACT_SCHEMA_VERSION,
        "agent_event_schema_version": AGENT_EVENT_SCHEMA_VERSION,
        "route_signal_schema_version": ROUTE_SIGNAL_SCHEMA_VERSION,
        "route_signal_classifier_version": ROUTE_SIGNAL_CLASSIFIER_VERSION,
        "token_accounting_schema_version": TOKEN_ACCOUNTING_SCHEMA_VERSION,
        "derived_text_redaction": segment_redaction,
        "markdown_render": {
            "mode": markdown_render_mode,
            "full_raw_views_rendered": full_markdown_render,
            "on_demand_supported": True,
            "synopsis_event_limit": (
                None
                if full_markdown_render
                else compact_review_limit
            ),
            "synopsis_event_count": (
                len(events)
                if full_markdown_render
                else len(compact_review_events)
            ),
        },
        "segment_id": segment_id,
        "segment_role": role,
        "input_digest": input_digest,
        "source_raw": raw_rel,
        "source_block": raw_block if isinstance(raw_block, dict) else None,
        "source_range": source_range,
        "markdown": str(reference_md_path),
        "events": records,
        # Facet maps remain in the enclosing privacy pass.  Their derived
        # keys provide field context used by the established redaction policy,
        # so skipping that pass could change navigation output even though the
        # source classification values were already sanitized.
        "by_type": dict(sorted(by_type.items())),
        "by_tag": dict(sorted(by_tag.items())),
        "by_source_type": dict(sorted(by_source_type.items())),
        "by_family": dict(sorted(by_family.items())),
        "by_phase": dict(sorted(by_phase.items())),
        "by_actor": dict(sorted(by_actor.items())),
        "by_action": dict(sorted(by_action.items())),
        "by_outcome": dict(sorted(by_outcome.items())),
        "by_correlation": dict(sorted(by_correlation.items())),
        "by_conversation_act": dict(sorted(by_conversation_act.items())),
        "by_session_act": dict(sorted(by_session_act.items())),
        "by_agent_event": dict(sorted(by_agent_event.items())),
        "by_route_layer": {
            layer: dict(sorted(keys.items()))
            for layer, keys in sorted(by_route_layer.items())
        },
        "by_route_signal": dict(sorted(by_route_signal.items())),
        "token_accounting": token_accounting,
    }
    if classification_metadata_pre_redacted:
        # These two complete containers are assembled only from the
        # generation-bound classification projection plus token observations
        # sanitized above.  Keep every contextual facet map in the ordinary
        # policy pass because its derived keys affect field-aware redaction.
        admitted_keys = {"events", "token_accounting"}
        policy_scanned = redact_derived_value(
            {
                key: value
                for key, value in index.items()
                if key not in admitted_keys
            },
            literal_policy=literal_policy,
        )
        index_payload = {
            key: index[key] if key in admitted_keys else policy_scanned[key]
            for key in index
        }
    else:
        index_payload = redact_derived_value(
            index,
            literal_policy=literal_policy,
        )
    write_json(index_path, index_payload)
    artifact_receipts = {
        "markdown": immutable_component_artifact_receipt(md_path),
        "index": immutable_component_artifact_receipt(index_path),
    }
    return {
        "segment_id": segment_id,
        "role": role,
        "input_digest": input_digest,
        "markdown": str(reference_md_path),
        "index": str(reference_index_path),
        "event_count": len(events),
        "source_range": source_range,
        "raw_block": raw_block if isinstance(raw_block, dict) else None,
        "component_identity": component_identity,
        "artifact_receipts": artifact_receipts,
        "token_accounting": compact_token_accounting,
        "markdown_render": index["markdown_render"],
    }


def session_projection_segment_input_digest(
    *,
    events: list[RawEvent],
    role: str,
    raw_block: dict[str, Any] | None,
    segment_generation_id: str | None = None,
) -> str:
    payload = {
        "schema_version": 1,
        "role": role,
        "event_count": len(events),
        "source_range": {
            "from_line": events[0].line_no if events else None,
            "to_line": events[-1].line_no if events else None,
        },
        "event_raw_sha256": hashlib.sha256(
            "\n".join(event.raw for event in events).encode("utf-8")
        ).hexdigest(),
        "raw_block_sha256": (
            str(raw_block.get("sha256") or "")
            if isinstance(raw_block, dict)
            else ""
        ),
        "segment_generation_id": (
            segment_generation_id
            or segment_index_generation_identity()["generation_id"]
        ),
        "derived_text_privacy_policy_version": (
            DERIVED_TEXT_PRIVACY_POLICY_VERSION
        ),
        "derived_text_redaction_policy_version": (
            DERIVED_TEXT_REDACTION_POLICY_VERSION
        ),
    }
    return hashlib.sha256(
        json.dumps(
            payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()


def render_segment_markdown_on_demand(
    *,
    session_dir: Path,
    segment: str,
) -> dict[str, Any]:
    manifest = read_json(session_dir / "session.manifest.json", {})
    if not isinstance(manifest, dict) or not manifest:
        raise ValueError("segment_render_session_manifest_missing")
    candidates = (
        manifest.get("segments")
        if isinstance(manifest.get("segments"), list)
        else []
    )
    requested = str(segment or "").strip()
    selected = next(
        (
            item
            for item in candidates
            if isinstance(item, dict)
            and requested
            in {
                str(item.get("segment_id") or ""),
                Path(str(item.get("index") or "")).name,
                Path(str(item.get("markdown") or "")).name,
                Path(str(item.get("index") or "")).stem,
                Path(str(item.get("markdown") or "")).stem,
            }
        ),
        None,
    )
    if not isinstance(selected, dict):
        raise ValueError(f"segment_render_target_unresolved:{requested}")
    index_path = projection_path_from_ref(
        selected.get("index"),
        base=session_dir,
    )
    index = read_json(index_path, {})
    if not isinstance(index, dict) or not index:
        raise ValueError("segment_render_index_missing")
    source_raw = projection_path_from_ref(
        index.get("source_raw") or "raw/session.raw.jsonl",
        base=session_dir,
    )
    if not source_raw.is_file():
        raise ValueError("segment_render_raw_missing")
    source_range = (
        index.get("source_range")
        if isinstance(index.get("source_range"), dict)
        else {}
    )
    from_line = int_value(source_range.get("from_line"), 0)
    to_line = int_value(source_range.get("to_line"), 0)
    if from_line <= 0 or to_line < from_line:
        raise ValueError("segment_render_source_range_invalid")
    source_block = (
        index.get("source_block")
        if isinstance(index.get("source_block"), dict)
        else {}
    )
    selected_lines: list[tuple[int, str]] = []
    source_read_mode = "legacy_raw_range_scan"
    bytes_read = 0
    if source_block:
        block_path, compressed, _storage_mode = raw_block_payload_path(
            session_dir,
            source_block,
        )
        if block_path.is_file():
            stored_block_bytes = block_path.read_bytes()
            block_bytes = (
                gzip.decompress(stored_block_bytes)
                if compressed
                else stored_block_bytes
            )
            bytes_read = block_path.stat().st_size
            expected_block_sha256 = str(
                source_block.get("uncompressed_sha256")
                or source_block.get("sha256")
                or ""
            )
            if (
                expected_block_sha256
                and hashlib.sha256(block_bytes).hexdigest()
                != expected_block_sha256
            ):
                raise ValueError(
                    "segment_render_raw_block_digest_mismatch"
                )
            block_from_line = int_value(
                (
                    source_block.get("source_range")
                    if isinstance(
                        source_block.get("source_range"), dict
                    )
                    else {}
                ).get("from_line"),
                from_line,
            )
            selected_lines = [
                (
                    block_from_line + offset,
                    raw_line.decode("utf-8", errors="replace").rstrip(
                        "\r\n"
                    ),
                )
                for offset, raw_line in enumerate(
                    block_bytes.splitlines(keepends=True)
                )
            ]
            selected_lines = [
                item
                for item in selected_lines
                if from_line <= item[0] <= to_line
            ]
            source_read_mode = "verified_raw_block"
    if not selected_lines:
        with source_raw.open(
            "r", encoding="utf-8", errors="replace"
        ) as raw_handle:
            for line_no, raw_line in enumerate(raw_handle, start=1):
                bytes_read += len(
                    raw_line.encode("utf-8", errors="replace")
                )
                if line_no < from_line:
                    continue
                if line_no > to_line:
                    break
                selected_lines.append(
                    (line_no, raw_line.rstrip("\r\n"))
                )
    privacy_scan_bytes = 0

    def privacy_scan_lines() -> Iterable[str]:
        nonlocal privacy_scan_bytes
        with source_raw.open(
            "r", encoding="utf-8", errors="replace"
        ) as raw_handle:
            for raw_line in raw_handle:
                privacy_scan_bytes += len(
                    raw_line.encode("utf-8", errors="replace")
                )
                yield raw_line.rstrip("\r\n")

    # Session-sensitive literals discovered in another block may recur in the
    # selected block.  Until privacy-safe structural marker summaries select
    # every necessary block, keep the exact whole-session scan process-local.
    literal_values = derived_session_sensitive_literal_values_from_texts(
        privacy_scan_lines()
    )
    literal_policy = DerivedSessionSensitiveLiteralPolicy(
        values_by_kind=literal_values
    )
    records_by_line = {
        int_value(item.get("line")): item
        for item in (
            index.get("events")
            if isinstance(index.get("events"), list)
            else []
        )
        if isinstance(item, dict) and int_value(item.get("line")) > 0
    }
    lines = [
        "---",
        "aoa_artifact_type: codex_compaction_segment_on_demand_review",
        "schema_version: 1",
        f"segment_id: {index.get('segment_id')}",
        f"source_index: {index_path}",
        f"source_raw: {source_raw}",
        f"source_from_line: {from_line}",
        f"source_to_line: {to_line}",
        "status: generated_redacted_on_demand_view",
        "---",
        "",
        f"# Segment {index.get('segment_id')}: on-demand review",
        "",
        "This file is a disposable redacted review view. Raw refs remain authoritative.",
        "",
    ]
    rendered_event_count = 0
    for line_no, raw_line in selected_lines:
        record = records_by_line.get(line_no, {})
        event_id = str(
            record.get("event_id") or f"event-{line_no:06d}"
        )
        event_anchor = safe_slug(
            event_id.lower(), fallback="event"
        )
        lines.extend(
            [
                f'<a id="event-{event_anchor}"></a>',
                "",
                f"## EVENT {event_id} - {record.get('type') or 'RAW_EVENT'}",
                f"- line: {line_no}",
                f"- refs: raw:line:{line_no}",
                "",
                "### Raw",
                "",
                "````json",
                markdown_escape_fence(
                    redact_derived_text(
                        raw_line,
                        literal_policy=literal_policy,
                    )
                ),
                "````",
                "",
            ]
        )
        rendered_event_count += 1
    rendered_path = (
        session_dir
        / "segments"
        / "rendered"
        / f"{Path(str(selected.get('markdown') or '')).stem}.full.md"
    )
    rendered_path.parent.mkdir(parents=True, exist_ok=True)
    rendered_path.write_text("\n".join(lines), encoding="utf-8")
    return {
        "schema_version": 1,
        "artifact_type": "segment_markdown_on_demand_render_receipt",
        "status": "rendered",
        "session_id": manifest.get("session_id"),
        "segment_id": index.get("segment_id"),
        "index_path": str(index_path),
        "raw_path": str(source_raw),
        "rendered_path": str(rendered_path),
        "rendered_event_count": rendered_event_count,
        "source_read_mode": source_read_mode,
        "source_bytes_read": bytes_read,
        "privacy_scan_bytes_read": privacy_scan_bytes,
        "privacy_scan_mode": (
            "whole_session_process_local_until_safe_block_markers_v1"
        ),
        "bytes": rendered_path.stat().st_size,
        "sha256": sha256_file(rendered_path),
        "privacy": literal_policy.report(),
        "authority": "disposable_redacted_review_view",
    }


def reuse_published_session_segment(
    *,
    stage_dir: Path,
    session_dir: Path,
    segment_no: int,
    role: str,
    events: list[RawEvent],
    raw_block: dict[str, Any] | None,
    published_segment: Any,
    publish_identity: dict[str, Any],
    attested_prefix_to_line: int = 0,
    source_range_override: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if not isinstance(published_segment, dict):
        return None
    segment_id = f"{segment_no:03d}"
    current_generation = segment_index_generation_identity()
    admitted_generation_ids = {
        str(current_generation["generation_id"]),
        *DECLARED_PROJECTION_PREDECESSOR_GENERATION_IDS.get(
            "segment_index",
            frozenset(),
        ),
    }
    published_digest = str(
        published_segment.get("input_digest") or ""
    )
    published_range = (
        published_segment.get("source_range")
        if isinstance(published_segment.get("source_range"), dict)
        else {}
    )
    published_raw_block = (
        published_segment.get("raw_block")
        if isinstance(published_segment.get("raw_block"), dict)
        else {}
    )
    current_range = (
        dict(source_range_override)
        if isinstance(source_range_override, dict)
        else {
            "from_line": events[0].line_no if events else None,
            "to_line": events[-1].line_no if events else None,
        }
    )
    attested_current_digest = bool(
        published_digest
        and raw_block_status_for_role(role) == "sealed"
        and int_value(current_range.get("to_line"))
        <= attested_prefix_to_line
        and published_range == current_range
        and isinstance(raw_block, dict)
        and str(raw_block.get("sha256") or "")
        == str(published_raw_block.get("sha256") or "")
        and raw_block.get("source_range")
        == published_raw_block.get("source_range")
    )
    expected_digests = (
        {
            str(current_generation["generation_id"]): (
                published_digest
            )
        }
        if attested_current_digest
        else {
            generation_id: session_projection_segment_input_digest(
                events=events,
                role=role,
                raw_block=raw_block,
                segment_generation_id=generation_id,
            )
            for generation_id in admitted_generation_ids
        }
    )
    matched_generation_id = next(
        (
            generation_id
            for generation_id, digest in expected_digests.items()
            if digest == published_digest
        ),
        "",
    )
    expected_digest = expected_digests[
        str(current_generation["generation_id"])
    ]
    if (
        str(published_segment.get("segment_id") or "") != segment_id
        or str(published_segment.get("role") or "") != role
        or not matched_generation_id
    ):
        return None
    source_md = Path(str(published_segment.get("markdown") or ""))
    source_index = Path(str(published_segment.get("index") or ""))
    target_md = stage_dir / "segments" / source_md.name
    target_index = stage_dir / "segments" / source_index.name
    current_component_identity = segment_component_identity(
        segment_id=segment_id,
        role=role,
        source_range=current_range,
        input_digest=expected_digest,
        raw_block=raw_block,
        generation_identity=current_generation,
    )
    published_receipts = (
        published_segment.get("artifact_receipts")
        if isinstance(published_segment.get("artifact_receipts"), dict)
        else {}
    )
    immutable_component_reuse = bool(
        matched_generation_id
        == str(current_generation.get("generation_id") or "")
        and published_segment.get("component_identity")
        == current_component_identity
        and immutable_component_artifact_receipt_metadata_current(
            source_md, published_receipts.get("markdown")
        )
        and immutable_component_artifact_receipt_metadata_current(
            source_index, published_receipts.get("index")
        )
    )
    if immutable_component_reuse:
        target_md.parent.mkdir(parents=True, exist_ok=True)
        target_md.unlink(missing_ok=True)
        target_index.unlink(missing_ok=True)
        stage_projection_path_with_links(
            source=source_md, target=target_md
        )
        stage_projection_path_with_links(
            source=source_index, target=target_index
        )
        return {
            **published_segment,
            "segment_id": segment_id,
            "role": role,
            "input_digest": expected_digest,
            "markdown": str(session_dir / "segments" / source_md.name),
            "index": str(session_dir / "segments" / source_index.name),
            "raw_block": raw_block,
            "component_identity": current_component_identity,
            "artifact_receipts": {
                "markdown": (
                    immutable_component_artifact_receipt_from_attested_link(
                        target_md,
                        dict(published_receipts["markdown"]),
                    )
                ),
                "index": (
                    immutable_component_artifact_receipt_from_attested_link(
                        target_index,
                        dict(published_receipts["index"]),
                    )
                ),
            },
            "reuse_mode": "immutable_component_link_v1",
        }
    existing_index = read_json(source_index, {})
    generation_admission = projection_generation_admission(
        projection="segment_index",
        stored_identity=(
            existing_index.get("generation_identity")
            if isinstance(existing_index, dict)
            else {}
        ),
        expected_identity=current_generation,
    )
    required_mapping_keys = (
        "by_type",
        "by_tag",
        "by_source_type",
        "by_family",
        "by_phase",
        "by_actor",
        "by_action",
        "by_outcome",
        "by_correlation",
        "by_conversation_act",
        "by_session_act",
        "by_agent_event",
        "by_route_layer",
        "by_route_signal",
    )
    indexed_events = (
        existing_index.get("events")
        if isinstance(existing_index, dict)
        and isinstance(existing_index.get("events"), list)
        else []
    )
    expected_event_count = max(
        0,
        int_value(current_range.get("to_line"))
        - int_value(current_range.get("from_line"))
        + 1,
    )
    universal_structure_current = bool(
        len(indexed_events) == expected_event_count
        and all(
            isinstance(existing_index.get(key), dict)
            for key in required_mapping_keys
        )
        and all(
            isinstance(item, dict)
            and all(
                field in item
                for field in (
                    "event_id",
                    "type",
                    "family",
                    "phase",
                    "actor",
                    "action",
                    "outcome",
                    "raw_ref",
                )
            )
            for item in indexed_events
        )
    )
    if not (
        source_md.is_file()
        and source_index.is_file()
        and isinstance(existing_index, dict)
        and universal_structure_current
        and str(existing_index.get("input_digest") or "")
        == published_digest
        and str(existing_index.get("generation_id") or "")
        == matched_generation_id
        and generation_admission["compatible"]
        and not generated_segment_index_stale_reasons(
            existing_index
        )
    ):
        return None
    target_md.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source_md, target_md)
    reused_index = dict(existing_index)
    reused_index["generation_id"] = current_generation[
        "generation_id"
    ]
    reused_index["generation_identity"] = current_generation
    reused_index["input_digest"] = expected_digest
    reused_index["component_identity"] = current_component_identity
    if generation_admission["requires_restamp"]:
        reused_index["generation_transition"] = {
            "schema_version": (
                PROJECTION_PREDECESSOR_ATTESTATION_VERSION
            ),
            "from_generation_id": matched_generation_id,
            "to_generation_id": current_generation[
                "generation_id"
            ],
            "basis": "declared_predecessor_reuse_then_restamp",
        }
    reused_index["projection_publish"] = publish_identity
    reused_index["source_block"] = raw_block
    write_json(target_index, reused_index)
    artifact_receipts = {
        "markdown": immutable_component_artifact_receipt(target_md),
        "index": immutable_component_artifact_receipt(target_index),
    }
    return {
        **published_segment,
        "segment_id": segment_id,
        "role": role,
        "input_digest": expected_digest,
        "markdown": str(session_dir / "segments" / source_md.name),
        "index": str(session_dir / "segments" / source_index.name),
        "raw_block": raw_block,
        "component_identity": current_component_identity,
        "artifact_receipts": artifact_receipts,
        "reuse_mode": "validated_migration_restamp_v1",
    }


def write_segment_process_task(
    task: tuple[
        Path,
        str,
        int,
        str,
        str,
        list[dict[str, Any]],
        dict[str, Any],
        int,
        int,
        dict[str, dict[str, Any]],
        dict[str, Any] | None,
        Path,
        dict[str, Any],
        dict[str, set[str]],
    ],
) -> tuple[int, str, dict[str, Any]]:
    (
        stage_dir,
        raw_rel,
        segment_no,
        role,
        raw_path_text,
        classification_block_refs,
        classification_generation_identity,
        from_line,
        to_line,
        reconciliation_patches,
        raw_block,
        reference_session_dir,
        publish_identity,
        sensitive_values_by_kind,
    ) = task
    events = load_raw_event_classification_range(
        raw_path=Path(raw_path_text),
        block_refs=classification_block_refs,
        generation_identity=(
            classification_generation_identity
        ),
        from_line=from_line,
        to_line=to_line,
        reconciliation_patches=reconciliation_patches,
    )
    literal_policy = DerivedSessionSensitiveLiteralPolicy(
        values_by_kind=sensitive_values_by_kind
    )
    return (
        segment_no,
        role,
        write_segment(
            stage_dir,
            raw_rel,
            segment_no,
            role,
            events,
            raw_block,
            reference_session_dir=reference_session_dir,
            publish_identity=publish_identity,
            literal_policy=literal_policy,
            classification_metadata_pre_redacted=True,
        ),
    )


def write_segment_route_index_only(
    session_dir: Path,
    segment: dict[str, Any],
    events: list[RawEvent],
    *,
    publish_identity: dict[str, Any] | None = None,
) -> dict[str, Any]:
    segment_id = str(segment.get("segment_id") or "000")
    role = str(segment.get("role") or segment.get("segment_role") or "segment")
    md_path = Path(str(segment.get("markdown") or session_dir / "segments" / f"{segment_id}__{role}.md"))
    index_path = Path(str(segment.get("index") or session_dir / "segments" / f"{segment_id}__{role}.index.json"))
    index_path.parent.mkdir(parents=True, exist_ok=True)
    existing_index = read_json(index_path, {})
    existing_event_records = {
        str(item.get("event_id")): item
        for item in existing_index.get("events", [])
        if isinstance(item, dict) and item.get("event_id")
    } if isinstance(existing_index.get("events"), list) else {}
    relationship_map = event_relationships(events)
    records: list[dict[str, Any]] = []
    for event in events:
        record = {
            "event_id": event.event_id,
            "line": event.line_no,
            "type": event.event_type,
            "family": event.family,
            "phase": event.phase,
            "actor": event.actor,
            "action": event.action,
            "object": event.object_ref,
            "outcome": event.outcome,
            "confidence": event.confidence,
            "title": event.title,
            "importance": event.importance,
            "tags": event.tags,
            "md_anchor": f"{md_path.name}#{anchor_for(event)}",
            "raw_ref": f"raw:line:{event.line_no}",
            "timestamp": event.timestamp,
            "source_type": event.source_type,
        }
        if event.correlation_id:
            record["correlation_id"] = event.correlation_id
        if event.facets:
            record["facets"] = event.facets
        existing_event = existing_event_records.get(event.event_id)
        if isinstance(existing_event, dict) and isinstance(existing_event.get("token_accounting"), dict):
            record["token_accounting"] = existing_event["token_accounting"]
        relationships = relationship_map.get(event.event_id, [])
        if relationships:
            record["relationships"] = relationships
        records.append(redact_derived_value(record))
    by_type: dict[str, list[str]] = defaultdict(list)
    by_tag: dict[str, list[str]] = defaultdict(list)
    by_source_type: dict[str, list[str]] = defaultdict(list)
    by_family: dict[str, list[str]] = defaultdict(list)
    by_phase: dict[str, list[str]] = defaultdict(list)
    by_actor: dict[str, list[str]] = defaultdict(list)
    by_action: dict[str, list[str]] = defaultdict(list)
    by_outcome: dict[str, list[str]] = defaultdict(list)
    by_correlation: dict[str, list[str]] = defaultdict(list)
    by_conversation_act: dict[str, list[str]] = defaultdict(list)
    by_session_act: dict[str, list[str]] = defaultdict(list)
    by_agent_event: dict[str, list[str]] = defaultdict(list)
    by_route_layer: dict[str, dict[str, list[str]]] = defaultdict(lambda: defaultdict(list))
    by_route_signal: dict[str, list[str]] = defaultdict(list)
    for event in events:
        by_type[event.event_type].append(event.event_id)
        by_source_type[event.source_type].append(event.event_id)
        by_family[event.family].append(event.event_id)
        by_phase[event.phase].append(event.event_id)
        by_actor[event.actor].append(event.event_id)
        by_action[event.action].append(event.event_id)
        by_outcome[event.outcome].append(event.event_id)
        if event.correlation_id:
            by_correlation[event.correlation_id].append(event.event_id)
        conversation_act = event.facets.get("conversation_act") if isinstance(event.facets.get("conversation_act"), dict) else {}
        if conversation_act.get("kind"):
            by_conversation_act[str(conversation_act["kind"])].append(event.event_id)
        session_act = event.facets.get("session_act") if isinstance(event.facets.get("session_act"), dict) else {}
        if session_act.get("kind"):
            by_session_act[str(session_act["kind"])].append(event.event_id)
        agent_event = agent_event_for_event(event)
        if agent_event.get("class"):
            by_agent_event[str(agent_event["class"])].append(event.event_id)
        for signal in event_route_signals(event):
            layer = str(signal["layer"])
            key = str(signal["key"])
            by_route_layer[layer][key].append(event.event_id)
            by_route_signal[route_signal_token(layer, key)].append(event.event_id)
        for tag in event.tags:
            by_tag[tag].append(event.event_id)
    source_range = segment.get("source_range") if isinstance(segment.get("source_range"), dict) else {}
    first_line = int_value(source_range.get("from_line")) or (events[0].line_no if events else None)
    last_line = int_value(source_range.get("to_line")) or (events[-1].line_no if events else None)
    token_accounting = existing_index.get("token_accounting") if isinstance(existing_index.get("token_accounting"), dict) else {}
    generation_identity = segment_index_generation_identity()
    index = {
        "schema_version": SCHEMA_VERSION,
        "generation_id": generation_identity["generation_id"],
        "generation_identity": generation_identity,
        "projection_publish": (
            publish_identity
            or (
                existing_index.get("projection_publish")
                if isinstance(
                    existing_index.get("projection_publish"),
                    dict,
                )
                else {}
            )
        ),
        "conversation_act_schema_version": CONVERSATION_ACT_SCHEMA_VERSION,
        "session_act_schema_version": SESSION_ACT_SCHEMA_VERSION,
        "agent_event_schema_version": AGENT_EVENT_SCHEMA_VERSION,
        "route_signal_schema_version": ROUTE_SIGNAL_SCHEMA_VERSION,
        "route_signal_classifier_version": ROUTE_SIGNAL_CLASSIFIER_VERSION,
        "token_accounting_schema_version": TOKEN_ACCOUNTING_SCHEMA_VERSION,
        "derived_text_redaction": {
            "policy_version": DERIVED_TEXT_REDACTION_POLICY_VERSION,
            "route_only_refresh": True,
            "raw_authority_preserved": True,
        },
        "segment_id": segment_id,
        "segment_role": role,
        "source_raw": existing_index.get("source_raw") or "raw/session.raw.jsonl",
        "source_block": existing_index.get("source_block") or "",
        "source_range": {"from_line": first_line, "to_line": last_line},
        "markdown": str(md_path),
        "events": records,
        "by_type": dict(sorted(by_type.items())),
        "by_tag": dict(sorted(by_tag.items())),
        "by_source_type": dict(sorted(by_source_type.items())),
        "by_family": dict(sorted(by_family.items())),
        "by_phase": dict(sorted(by_phase.items())),
        "by_actor": dict(sorted(by_actor.items())),
        "by_action": dict(sorted(by_action.items())),
        "by_outcome": dict(sorted(by_outcome.items())),
        "by_correlation": dict(sorted(by_correlation.items())),
        "by_conversation_act": dict(sorted(by_conversation_act.items())),
        "by_session_act": dict(sorted(by_session_act.items())),
        "by_agent_event": dict(sorted(by_agent_event.items())),
        "by_route_layer": {
            layer: dict(sorted(keys.items()))
            for layer, keys in sorted(by_route_layer.items())
        },
        "by_route_signal": dict(sorted(by_route_signal.items())),
        "token_accounting": token_accounting,
    }
    write_json(index_path, index)
    return {
        **segment,
        "segment_id": segment_id,
        "role": role,
        "markdown": str(md_path),
        "index": str(index_path),
        "event_count": len(events),
        "source_range": {"from_line": first_line, "to_line": last_line},
        "token_accounting": segment.get("token_accounting", {}),
    }


def clear_generated_segments(session_dir: Path) -> None:
    segments = session_dir / "segments"
    if not segments.exists():
        return
    for path in segments.iterdir():
        if re.match(r"^\d{3}__.+(\.md|\.index\.json)$", path.name):
            path.unlink()


def write_session_index(
    session_dir: Path,
    manifest: dict[str, Any],
    events: list[RawEvent],
    *,
    reference_session_dir: Path | None = None,
    publish_identity: dict[str, Any] | None = None,
    literal_policy: DerivedSessionSensitiveLiteralPolicy | None = None,
    workers: int = 1,
    cooperative_deadline_monotonic: float | None = None,
    execution_metrics_out: dict[str, Any] | None = None,
    event_summary: dict[str, Any] | None = None,
    processed_to_line: int | None = None,
) -> dict[str, Any]:
    return write_session_index_impl(
        session_dir,
        manifest,
        events,
        reference_session_dir=reference_session_dir,
        publish_identity=publish_identity,
        literal_policy=literal_policy,
        workers=workers,
        cooperative_deadline_monotonic=(
            cooperative_deadline_monotonic
        ),
        execution_metrics_out=execution_metrics_out,
        event_summary=event_summary,
        processed_to_line=processed_to_line,
    )


def session_index_shard_json_bytes(value: Any) -> bytes:
    return json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")


def session_index_shard_payload_sha256(value: Any) -> str:
    return hashlib.sha256(
        session_index_shard_json_bytes(value)
    ).hexdigest()


def session_index_task_episode_shard_key(
    episode: dict[str, Any],
    ordinal: int,
) -> str:
    identity = (
        episode.get("identity")
        if isinstance(episode.get("identity"), dict)
        else {}
    )
    stable = str(
        identity.get("canonical_id")
        or episode.get("stable_id")
        or episode.get("episode_id")
        or f"ordinal-{ordinal:04d}"
    )
    return f"{ordinal:04d}:{stable}"


def task_episode_component_source_identity(
    episode: dict[str, Any],
    *,
    generation_identity: dict[str, Any],
) -> dict[str, Any]:
    semantic_source = session_projection_semantic_digest_value(
        episode
    )
    source_sha256 = hashlib.sha256(
        json.dumps(
            semantic_source,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    event_range = (
        episode.get("event_range")
        if isinstance(episode.get("event_range"), dict)
        else {}
    )
    return {
        "schema_version": 1,
        "identity_mode": "append_stable_episode_component_v1",
        "task_episode_generation_id": str(
            generation_identity.get("generation_id") or ""
        ),
        "episode_source_sha256": source_sha256,
        "event_range": {
            "from_line": int_value(event_range.get("from_line")),
            "to_line": int_value(event_range.get("to_line")),
        },
        "privacy_policy_version": DERIVED_TEXT_PRIVACY_POLICY_VERSION,
        "redaction_policy_version": DERIVED_TEXT_REDACTION_POLICY_VERSION,
    }


def session_index_task_episode_shard_envelope(
    task: tuple[
        int,
        str,
        dict[str, Any],
        DerivedSessionSensitiveLiteralPolicy,
        dict[str, Any],
        dict[str, Any] | None,
    ],
) -> tuple[int, str, dict[str, Any]]:
    (
        ordinal,
        component_key,
        episode,
        literal_policy,
        source_identity,
        pre_redacted_payload,
    ) = task
    payload = (
        dict(pre_redacted_payload)
        if isinstance(pre_redacted_payload, dict)
        else redact_derived_value(
            episode,
            literal_policy=literal_policy,
        )
    )
    envelope = {
        "schema_version": SESSION_INDEX_SHARD_SCHEMA_VERSION,
        "artifact_type": "session_index_component_shard",
        "component": "task_episodes",
        "component_key": component_key,
        "source_identity": source_identity,
        "redaction": {
            "privacy_policy_version": (
                DERIVED_TEXT_PRIVACY_POLICY_VERSION
            ),
            "redaction_policy_version": (
                DERIVED_TEXT_REDACTION_POLICY_VERSION
            ),
            "whole_session_literal_policy": True,
        },
        "payload_sha256": session_index_shard_payload_sha256(
            payload
        ),
        "payload": payload,
    }
    return ordinal, component_key, envelope


def write_session_index_component_shard(
    shard_dir: Path,
    envelope: dict[str, Any],
) -> dict[str, Any]:
    shard_dir.mkdir(parents=True, exist_ok=True)
    descriptor, temporary_name = tempfile.mkstemp(
        prefix=".component-shard-",
        suffix=".json",
        dir=shard_dir,
    )
    os.close(descriptor)
    temporary_path = Path(temporary_name)
    try:
        write_json(temporary_path, envelope)
        artifact_sha256 = sha256_file(temporary_path)
        final_path = shard_dir / f"{artifact_sha256}.json"
        if final_path.is_file():
            if sha256_file(final_path) != artifact_sha256:
                raise ValueError(
                    "session_index_component_shard_digest_mismatch"
                )
            temporary_path.unlink(missing_ok=True)
        else:
            temporary_path.replace(final_path)
        final_stat = final_path.stat()
        return {
            "component_key": str(
                envelope.get("component_key") or ""
            ),
            "source_identity": (
                dict(envelope.get("source_identity"))
                if isinstance(envelope.get("source_identity"), dict)
                else {}
            ),
            "ref": str(
                Path(SESSION_INDEX_SHARDS_DIR)
                / SESSION_INDEX_TASK_EPISODE_SHARDS_DIR
                / final_path.name
            ),
            "artifact_sha256": artifact_sha256,
            "payload_sha256": str(
                envelope.get("payload_sha256") or ""
            ),
            "bytes": final_stat.st_size,
            "artifact_receipt": {
                "bytes": final_stat.st_size,
                "sha256": artifact_sha256,
                "mtime_ns": final_stat.st_mtime_ns,
                "ctime_ns": final_stat.st_ctime_ns,
            },
        }
    finally:
        temporary_path.unlink(missing_ok=True)


def staged_session_index_task_episode_shards(
    session_dir: Path,
) -> dict[str, tuple[dict[str, Any], dict[str, Any]]]:
    shard_dir = (
        session_dir
        / SESSION_INDEX_SHARDS_DIR
        / SESSION_INDEX_TASK_EPISODE_SHARDS_DIR
    )
    current: dict[
        str, tuple[dict[str, Any], dict[str, Any]]
    ] = {}
    if not shard_dir.is_dir():
        return current
    manifest_path = (
        session_dir
        / SESSION_INDEX_SHARDS_DIR
        / SESSION_INDEX_SHARD_MANIFEST_JSON
    )
    component_manifest = read_json(manifest_path, {})
    manifest_records = (
        component_manifest.get("components", {}).get(
            "task_episodes"
        )
        if isinstance(component_manifest, dict)
        and isinstance(component_manifest.get("components"), dict)
        else None
    )
    if (
        isinstance(component_manifest, dict)
        and int_value(component_manifest.get("schema_version"))
        == SESSION_INDEX_SHARD_SCHEMA_VERSION
        and component_manifest.get("artifact_type")
        == "session_index_shard_manifest"
        and component_manifest.get("storage_mode")
        == "content_addressed_components_manifest_first_v1"
        and isinstance(manifest_records, list)
        and int_value(
            component_manifest.get("component_counts", {}).get(
                "task_episodes"
            )
            if isinstance(
                component_manifest.get("component_counts"), dict
            )
            else -1,
            -1,
        )
        == len(manifest_records)
    ):
        admitted: dict[
            str, tuple[dict[str, Any], dict[str, Any]]
        ] = {}
        manifest_valid = True
        for raw_record in manifest_records:
            if not isinstance(raw_record, dict):
                manifest_valid = False
                break
            record = dict(raw_record)
            component_key = str(record.get("component_key") or "")
            artifact_sha256 = str(
                record.get("artifact_sha256") or ""
            )
            payload_sha256 = str(
                record.get("payload_sha256") or ""
            )
            relative_ref = Path(str(record.get("ref") or ""))
            receipt = (
                record.get("artifact_receipt")
                if isinstance(record.get("artifact_receipt"), dict)
                else {}
            )
            artifact_path = session_dir / relative_ref
            if (
                not component_key
                or component_key in admitted
                or len(artifact_sha256) != 64
                or len(payload_sha256) != 64
                or relative_ref.is_absolute()
                or ".." in relative_ref.parts
                or relative_ref.parent
                != Path(SESSION_INDEX_SHARDS_DIR)
                / SESSION_INDEX_TASK_EPISODE_SHARDS_DIR
                or relative_ref.name != f"{artifact_sha256}.json"
                or not artifact_path.is_file()
            ):
                manifest_valid = False
                break
            artifact_stat = artifact_path.stat()
            if not (
                int_value(record.get("bytes"), -1)
                == artifact_stat.st_size
                == int_value(receipt.get("bytes"), -2)
                and str(receipt.get("sha256") or "")
                == artifact_sha256
                and int_value(receipt.get("mtime_ns"), -1)
                == artifact_stat.st_mtime_ns
                and int_value(receipt.get("ctime_ns"), -1)
                == artifact_stat.st_ctime_ns
                and isinstance(record.get("source_identity"), dict)
            ):
                manifest_valid = False
                break
            record["_artifact_path"] = str(artifact_path)
            record["_manifest_admitted"] = True
            admitted[component_key] = (
                {
                    "source_identity": dict(
                        record["source_identity"]
                    ),
                    "payload_sha256": payload_sha256,
                },
                record,
            )
        if manifest_valid:
            return admitted
    for path in sorted(shard_dir.glob("*.json")):
        if path.stem != sha256_file(path):
            continue
        envelope = read_json(path, {})
        if (
            int_value(envelope.get("schema_version"))
            != SESSION_INDEX_SHARD_SCHEMA_VERSION
            or envelope.get("artifact_type")
            != "session_index_component_shard"
            or envelope.get("component") != "task_episodes"
            or not isinstance(envelope.get("source_identity"), dict)
            or not isinstance(envelope.get("payload"), dict)
            or session_index_shard_payload_sha256(
                envelope["payload"]
            )
            != str(envelope.get("payload_sha256") or "")
        ):
            continue
        component_key = str(
            envelope.get("component_key") or ""
        )
        if not component_key:
            continue
        current[component_key] = (
            envelope,
            {
                "component_key": component_key,
                "source_identity": dict(
                    envelope.get("source_identity")
                    if isinstance(
                        envelope.get("source_identity"), dict
                    )
                    else {}
                ),
                "ref": str(
                    Path(SESSION_INDEX_SHARDS_DIR)
                    / SESSION_INDEX_TASK_EPISODE_SHARDS_DIR
                    / path.name
                ),
                "artifact_sha256": path.stem,
                "payload_sha256": str(
                    envelope.get("payload_sha256") or ""
                ),
                "bytes": path.stat().st_size,
                "artifact_receipt": {
                    "bytes": path.stat().st_size,
                    "sha256": path.stem,
                    "mtime_ns": path.stat().st_mtime_ns,
                    "ctime_ns": path.stat().st_ctime_ns,
                },
                "_artifact_path": str(path),
            },
        )
    return current


def materialize_session_index_task_episode_shards(
    session_dir: Path,
    task_episodes: list[dict[str, Any]],
    *,
    published_session_dir: Path | None = None,
    publish_identity: dict[str, Any],
    literal_policy: DerivedSessionSensitiveLiteralPolicy,
    workers: int,
    cooperative_deadline_monotonic: float | None = None,
    pre_redacted_episode_count: int = 0,
) -> dict[str, Any]:
    generation_identity = task_episode_source_generation_identity()
    source = (
        publish_identity.get("source")
        if isinstance(publish_identity.get("source"), dict)
        else {}
    )
    source_identity = {
        "raw_sha256": str(source.get("raw_sha256") or ""),
        "raw_bytes": int_value(source.get("raw_bytes")),
        "raw_line_count": int_value(
            source.get("raw_line_count")
        ),
        "task_episode_generation_id": str(
            generation_identity.get("generation_id") or ""
        ),
    }
    existing = staged_session_index_task_episode_shards(
        session_dir,
    )
    if (
        published_session_dir is not None
        and published_session_dir != session_dir
    ):
        published_existing = (
            staged_session_index_task_episode_shards(
                published_session_dir,
            )
        )
        for component_key, candidate in published_existing.items():
            existing.setdefault(component_key, candidate)
    payloads: dict[int, dict[str, Any]] = {}
    records: dict[int, dict[str, Any]] = {}
    pending: list[
        tuple[
            int,
            str,
            dict[str, Any],
            DerivedSessionSensitiveLiteralPolicy,
            dict[str, Any],
            dict[str, Any] | None,
        ]
    ] = []
    reused_count = 0
    manifest_admitted_reused_count = 0
    migrated_predecessor_count = 0
    for ordinal, episode in enumerate(task_episodes):
        component_key = session_index_task_episode_shard_key(
            episode,
            ordinal,
        )
        component_source_identity = (
            task_episode_component_source_identity(
                episode,
                generation_identity=generation_identity,
            )
        )
        prior = existing.get(component_key)
        expected_payload: dict[str, Any] | None = None
        expected_payload_sha256 = ""
        if prior is not None:
            envelope, record = prior
            prior_source_identity = (
                envelope.get("source_identity")
                if isinstance(envelope.get("source_identity"), dict)
                else {}
            )
            prior_generation_id = str(
                prior_source_identity.get(
                    "task_episode_generation_id"
                )
                or ""
            )
            if (
                ordinal < pre_redacted_episode_count
                and prior_source_identity
                == component_source_identity
            ):
                # The bounded stable prefix was hydrated from previously
                # redacted shards.  Its exact source identity includes the
                # privacy/redaction generations, so re-running recursive
                # redaction over every historical episode adds no safety.
                expected_payload = dict(episode)
            else:
                expected_payload = redact_derived_value(
                    episode,
                    literal_policy=literal_policy,
                )
            expected_payload_sha256 = (
                session_index_shard_payload_sha256(
                    expected_payload
                )
            )
            prior_payload_matches = bool(
                str(envelope.get("payload_sha256") or "")
                == expected_payload_sha256
            )
            if (
                prior_source_identity == component_source_identity
                and prior_payload_matches
            ):
                reusable_record = dict(record)
                manifest_admitted = bool(
                    reusable_record.pop("_manifest_admitted", False)
                )
                source_artifact = Path(
                    str(reusable_record.pop("_artifact_path", ""))
                )
                target_artifact = session_dir / str(
                    reusable_record.get("ref") or ""
                )
                if source_artifact != target_artifact:
                    stage_projection_path_with_links(
                        source=source_artifact,
                        target=target_artifact,
                    )
                target_stat = target_artifact.stat()
                reusable_record["artifact_receipt"] = {
                    "bytes": target_stat.st_size,
                    "sha256": str(
                        reusable_record.get("artifact_sha256") or ""
                    ),
                    "mtime_ns": target_stat.st_mtime_ns,
                    "ctime_ns": target_stat.st_ctime_ns,
                }
                payloads[ordinal] = (
                    dict(expected_payload)
                    if manifest_admitted
                    and isinstance(expected_payload, dict)
                    else dict(envelope["payload"])
                )
                records[ordinal] = reusable_record
                reused_count += 1
                if manifest_admitted:
                    manifest_admitted_reused_count += 1
                continue
            legacy_source_matches = bool(
                prior_payload_matches
                and "raw_sha256" in prior_source_identity
                and "raw_bytes" in prior_source_identity
                and "raw_line_count" in prior_source_identity
                and (
                    prior_generation_id
                    == str(generation_identity.get("generation_id") or "")
                    or prior_generation_id
                    in DECLARED_PROJECTION_PREDECESSOR_GENERATION_IDS.get(
                        "task_episode_source",
                        frozenset(),
                    )
                )
            )
            if legacy_source_matches:
                _, _, restamped = (
                    session_index_task_episode_shard_envelope(
                        (
                            ordinal,
                            component_key,
                            episode,
                            literal_policy,
                            component_source_identity,
                            expected_payload,
                        )
                    )
                )
                new_record = write_session_index_component_shard(
                    session_dir
                    / SESSION_INDEX_SHARDS_DIR
                    / SESSION_INDEX_TASK_EPISODE_SHARDS_DIR,
                    restamped,
                )
                payloads[ordinal] = dict(restamped["payload"])
                records[ordinal] = new_record
                reused_count += 1
                migrated_predecessor_count += 1
                continue
        pending.append(
            (
                ordinal,
                component_key,
                episode,
                literal_policy,
                component_source_identity,
                expected_payload,
            )
        )

    configured_workers = max(1, min(6, int_value(workers, 1)))
    actual_workers = min(configured_workers, len(pending))
    fallback_reason = ""
    execution_mode = "serial"
    shard_dir = (
        session_dir
        / SESSION_INDEX_SHARDS_DIR
        / SESSION_INDEX_TASK_EPISODE_SHARDS_DIR
    )

    def record_result(
        result: tuple[int, str, dict[str, Any]],
    ) -> None:
        ordinal, _, envelope = result
        record = write_session_index_component_shard(
            shard_dir,
            envelope,
        )
        payloads[ordinal] = dict(envelope["payload"])
        records[ordinal] = record

    processed_pending = 0
    if actual_workers > 1:
        try:
            execution_mode = "process_pool"
            with ProcessPoolExecutor(
                max_workers=actual_workers,
                mp_context=multiprocessing.get_context("fork"),
            ) as executor:
                for wave_start in range(
                    0, len(pending), actual_workers
                ):
                    wave = pending[
                        wave_start : wave_start + actual_workers
                    ]
                    for result in executor.map(
                        session_index_task_episode_shard_envelope,
                        wave,
                    ):
                        record_result(result)
                        processed_pending += 1
                    if (
                        cooperative_deadline_monotonic is not None
                        and time.monotonic()
                        >= cooperative_deadline_monotonic
                    ):
                        break
        except Exception as exc:
            fallback_reason = f"{type(exc).__name__}:{exc}"
            execution_mode = "serial_fallback"
    if actual_workers <= 1 or fallback_reason:
        for task in pending[processed_pending:]:
            record_result(
                session_index_task_episode_shard_envelope(task)
            )
            processed_pending += 1
            if (
                cooperative_deadline_monotonic is not None
                and time.monotonic()
                >= cooperative_deadline_monotonic
            ):
                break

    complete = len(payloads) == len(task_episodes)
    ordered_payloads = [
        payloads[index]
        for index in range(len(task_episodes))
        if index in payloads
    ]
    ordered_records = [
        records[index]
        for index in range(len(task_episodes))
        if index in records
    ]
    if complete and shard_dir.is_dir():
        referenced_names = {
            Path(str(record.get("ref") or "")).name
            for record in ordered_records
        }
        for path in shard_dir.glob("*.json"):
            if path.name not in referenced_names:
                path.unlink()
    return {
        "complete": complete,
        "payloads": ordered_payloads,
        "records": ordered_records,
        "source_identity": source_identity,
        "execution": {
            "configured_workers": configured_workers,
            "actual_workers": max(1, actual_workers),
            "mode": execution_mode,
            "parallel_fallback_reason": fallback_reason,
            "planned_shard_count": len(task_episodes),
            "completed_shard_count": len(payloads),
            "checkpoint_reused_shard_count": reused_count,
            "manifest_admitted_reused_shard_count": (
                manifest_admitted_reused_count
            ),
            "migrated_predecessor_shard_count": (
                migrated_predecessor_count
            ),
            "rebuilt_shard_count": processed_pending,
            "pre_redacted_episode_count": min(
                len(task_episodes),
                max(0, pre_redacted_episode_count),
            ),
        },
    }


def write_session_index_shard_manifest(
    session_dir: Path,
    *,
    publish_identity: dict[str, Any],
    source_identity: dict[str, Any],
    task_episode_records: list[dict[str, Any]],
) -> dict[str, Any]:
    manifest = {
        "schema_version": SESSION_INDEX_SHARD_SCHEMA_VERSION,
        "artifact_type": "session_index_shard_manifest",
        "storage_mode": (
            "content_addressed_components_manifest_first_v1"
        ),
        "projection_publish": publish_identity,
        "source_identity": source_identity,
        "components": {
            "task_episodes": task_episode_records,
        },
        "component_counts": {
            "task_episodes": len(task_episode_records),
        },
        "authority": (
            "rebuildable acceleration and storage projection; raw, "
            "manifest, and segment evidence remain stronger"
        ),
    }
    manifest_path = (
        session_dir
        / SESSION_INDEX_SHARDS_DIR
        / SESSION_INDEX_SHARD_MANIFEST_JSON
    )
    write_json(manifest_path, manifest)
    return manifest


def session_index_task_episode_component_read(
    session_dir: Path,
    session_index: dict[str, Any],
    *,
    order: str = "chronological",
    limit: int | None = None,
    selector: Callable[[dict[str, Any]], bool] | None = None,
) -> dict[str, Any]:
    """Hydrate only the manifest-first task-episode shards a reader needs.

    Every returned shard is content-address verified.  A bounded positive read
    deliberately does not claim that unvisited components are globally valid;
    deep/audit callers use the unbounded compatibility wrapper below.
    """
    embedded = (
        session_index.get("task_episodes")
        if isinstance(session_index.get("task_episodes"), list)
        else []
    )
    storage = (
        session_index.get("component_storage")
        if isinstance(session_index.get("component_storage"), dict)
        else {}
    )
    effective_limit = (
        None if limit is None else max(0, int_value(limit))
    )

    def selected_payloads(
        payloads: Iterable[dict[str, Any]],
        *,
        total_count: int,
        reader_mode: str,
    ) -> dict[str, Any]:
        ordered = list(payloads)
        if order == "recent":
            ordered.reverse()
        elif order != "chronological":
            return {
                "status": "invalid",
                "payloads": [],
                "diagnostics": ["task_episode_component_order_invalid"],
                "reader_mode": reader_mode,
                "component_count": total_count,
                "hydrated_component_count": 0,
                "selected_component_count": 0,
                "scan_complete": False,
                "global_component_integrity": "unresolved",
            }
        selected: list[dict[str, Any]] = []
        hydrated = 0
        if effective_limit == 0:
            return {
                "status": "current",
                "payloads": [],
                "diagnostics": [],
                "reader_mode": reader_mode,
                "component_count": total_count,
                "hydrated_component_count": 0,
                "selected_component_count": 0,
                "scan_complete": total_count == 0,
                "global_component_integrity": (
                    "verified" if total_count == 0 else "unresolved"
                ),
            }
        for payload in ordered:
            hydrated += 1
            if selector is not None and not selector(payload):
                continue
            selected.append(dict(payload))
            if effective_limit is not None and len(selected) >= effective_limit:
                break
        scan_complete = hydrated == total_count
        return {
            "status": "current",
            "payloads": selected,
            "diagnostics": [],
            "reader_mode": reader_mode,
            "component_count": total_count,
            "hydrated_component_count": hydrated,
            "selected_component_count": len(selected),
            "scan_complete": scan_complete,
            "global_component_integrity": (
                "verified" if scan_complete else "unresolved"
            ),
        }

    embedded_payloads = [
        dict(item) for item in embedded if isinstance(item, dict)
    ]
    if embedded and not storage:
        return selected_payloads(
            embedded_payloads,
            total_count=len(embedded_payloads),
            reader_mode="embedded_legacy_compatibility",
        )
    manifest_ref = str(storage.get("manifest_ref") or "")
    relative_manifest = Path(manifest_ref)
    if (
        not manifest_ref
        or relative_manifest.is_absolute()
        or ".." in relative_manifest.parts
    ):
        if embedded_payloads:
            return selected_payloads(
                embedded_payloads,
                total_count=len(embedded_payloads),
                reader_mode="embedded_legacy_compatibility",
            )
        return {
            "status": "invalid",
            "payloads": [],
            "diagnostics": ["session_index_shard_manifest_ref_invalid"],
            "reader_mode": "manifest_first",
            "component_count": 0,
            "hydrated_component_count": 0,
            "selected_component_count": 0,
            "scan_complete": False,
            "global_component_integrity": "unresolved",
        }
    component_manifest = read_json(
        session_dir / relative_manifest,
        {},
    )
    if not (
        isinstance(component_manifest, dict)
        and int_value(component_manifest.get("schema_version"))
        == SESSION_INDEX_SHARD_SCHEMA_VERSION
        and component_manifest.get("artifact_type")
        == "session_index_shard_manifest"
        and component_manifest.get("storage_mode")
        == "content_addressed_components_manifest_first_v1"
    ):
        return {
            "status": "invalid",
            "payloads": [],
            "diagnostics": ["session_index_shard_manifest_invalid"],
            "reader_mode": "manifest_first",
            "component_count": 0,
            "hydrated_component_count": 0,
            "selected_component_count": 0,
            "scan_complete": False,
            "global_component_integrity": "unresolved",
        }
    expected_publish_id = projection_publish_id(
        session_index.get("projection_publish")
        if isinstance(session_index.get("projection_publish"), dict)
        else {}
    )
    manifest_publish_id = projection_publish_id(
        component_manifest.get("projection_publish")
        if isinstance(component_manifest.get("projection_publish"), dict)
        else {}
    )
    if not expected_publish_id or manifest_publish_id != expected_publish_id:
        return {
            "status": "invalid",
            "payloads": [],
            "diagnostics": [
                "session_index_shard_manifest_publish_id_mismatch"
            ],
            "reader_mode": "manifest_first",
            "component_count": 0,
            "hydrated_component_count": 0,
            "selected_component_count": 0,
            "scan_complete": False,
            "global_component_integrity": "unresolved",
        }
    components = (
        component_manifest.get("components")
        if isinstance(component_manifest, dict)
        and isinstance(component_manifest.get("components"), dict)
        else {}
    )
    records = (
        components.get("task_episodes")
        if isinstance(components.get("task_episodes"), list)
        else []
    )
    expected_count = int_value(
        storage.get("task_episode_shard_count"), -1
    )
    if expected_count != len(records):
        return {
            "status": "invalid",
            "payloads": [],
            "diagnostics": [
                "session_index_component_storage_count_mismatch"
            ],
            "reader_mode": "manifest_first",
            "component_count": len(records),
            "hydrated_component_count": 0,
            "selected_component_count": 0,
            "scan_complete": False,
            "global_component_integrity": "unresolved",
        }
    indexed_records = list(enumerate(records))
    if order == "recent":
        indexed_records.reverse()
    elif order != "chronological":
        return {
            "status": "invalid",
            "payloads": [],
            "diagnostics": ["task_episode_component_order_invalid"],
            "reader_mode": "manifest_first",
            "component_count": len(records),
            "hydrated_component_count": 0,
            "selected_component_count": 0,
            "scan_complete": False,
            "global_component_integrity": "unresolved",
        }
    episodes: list[dict[str, Any]] = []
    hydrated_count = 0
    if effective_limit == 0:
        return {
            "status": "current",
            "payloads": [],
            "diagnostics": [],
            "reader_mode": "manifest_first",
            "component_count": len(records),
            "hydrated_component_count": 0,
            "selected_component_count": 0,
            "scan_complete": len(records) == 0,
            "global_component_integrity": (
                "verified" if not records else "unresolved"
            ),
        }
    for ordinal, record in indexed_records:
        hydrated_count += 1
        if not isinstance(record, dict):
            return {
                "status": "invalid",
                "payloads": [],
                "diagnostics": [
                    f"session_index_task_episode_shard_record_invalid:{ordinal}"
                ],
                "reader_mode": "manifest_first",
                "component_count": len(records),
                "hydrated_component_count": hydrated_count,
                "selected_component_count": 0,
                "scan_complete": False,
                "global_component_integrity": "unresolved",
            }
        relative = Path(str(record.get("ref") or ""))
        expected_parent = (
            Path(SESSION_INDEX_SHARDS_DIR)
            / SESSION_INDEX_TASK_EPISODE_SHARDS_DIR
        )
        if (
            relative.is_absolute()
            or ".." in relative.parts
            or relative.parent != expected_parent
            or relative.suffix != ".json"
        ):
            return {
                "status": "invalid",
                "payloads": [],
                "diagnostics": [
                    f"session_index_task_episode_shard_ref_invalid:{ordinal}"
                ],
                "reader_mode": "manifest_first",
                "component_count": len(records),
                "hydrated_component_count": hydrated_count,
                "selected_component_count": 0,
                "scan_complete": False,
                "global_component_integrity": "unresolved",
            }
        artifact = session_dir / relative
        artifact_sha256 = str(record.get("artifact_sha256") or "")
        if not (
            artifact.is_file()
            and artifact.stem == artifact_sha256
            and sha256_file(artifact) == artifact_sha256
        ):
            return {
                "status": "invalid",
                "payloads": [],
                "diagnostics": [
                    f"session_index_task_episode_shard_artifact_mismatch:{ordinal}"
                ],
                "reader_mode": "manifest_first",
                "component_count": len(records),
                "hydrated_component_count": hydrated_count,
                "selected_component_count": 0,
                "scan_complete": False,
                "global_component_integrity": "unresolved",
            }
        envelope = read_json(artifact, {})
        payload = (
            envelope.get("payload")
            if isinstance(envelope.get("payload"), dict)
            else None
        )
        if not isinstance(payload, dict):
            return {
                "status": "invalid",
                "payloads": [],
                "diagnostics": [
                    f"session_index_task_episode_shard_payload_mismatch:{ordinal}"
                ],
                "reader_mode": "manifest_first",
                "component_count": len(records),
                "hydrated_component_count": hydrated_count,
                "selected_component_count": 0,
                "scan_complete": False,
                "global_component_integrity": "unresolved",
            }
        payload_sha256 = session_index_shard_payload_sha256(payload)
        if not (
            envelope.get("artifact_type")
            == "session_index_component_shard"
            and envelope.get("component") == "task_episodes"
            and str(envelope.get("component_key") or "")
            == str(record.get("component_key") or "")
            and str(envelope.get("payload_sha256") or "")
            == payload_sha256
            and str(record.get("payload_sha256") or "")
            == payload_sha256
            and envelope.get("source_identity")
            == record.get("source_identity")
        ):
            return {
                "status": "invalid",
                "payloads": [],
                "diagnostics": [
                    f"session_index_task_episode_shard_payload_mismatch:{ordinal}"
                ],
                "reader_mode": "manifest_first",
                "component_count": len(records),
                "hydrated_component_count": hydrated_count,
                "selected_component_count": 0,
                "scan_complete": False,
                "global_component_integrity": "unresolved",
            }
        if selector is not None and not selector(payload):
            continue
        episodes.append(dict(payload))
        if effective_limit is not None and len(episodes) >= effective_limit:
            break
    scan_complete = hydrated_count == len(records)
    return {
        "status": "current",
        "payloads": episodes,
        "diagnostics": [],
        "reader_mode": "manifest_first",
        "component_count": len(records),
        "hydrated_component_count": hydrated_count,
        "selected_component_count": len(episodes),
        "scan_complete": scan_complete,
        "global_component_integrity": (
            "verified" if scan_complete else "unresolved"
        ),
    }


def session_index_task_episode_components(
    session_dir: Path,
    session_index: dict[str, Any],
) -> list[dict[str, Any]]:
    result = session_index_task_episode_component_read(
        session_dir,
        session_index,
    )
    if result.get("status") != "current" or not result.get(
        "scan_complete"
    ):
        return []
    return [
        dict(item)
        for item in result.get("payloads", [])
        if isinstance(item, dict)
    ]


def append_stable_segment_prefix(
    previous_segments: Iterable[dict[str, Any]],
    current_segments: Iterable[dict[str, Any]],
) -> dict[str, Any]:
    stable_to_line = 0
    stable_segment_count = 0
    for previous, current in zip(
        previous_segments, current_segments, strict=False
    ):
        if not isinstance(previous, dict) or not isinstance(current, dict):
            break
        previous_range = (
            previous.get("source_range")
            if isinstance(previous.get("source_range"), dict)
            else {}
        )
        current_range = (
            current.get("source_range")
            if isinstance(current.get("source_range"), dict)
            else {}
        )
        if any(
            (
                str(previous.get("segment_id") or "")
                != str(current.get("segment_id") or ""),
                str(previous.get("role") or "")
                != str(current.get("role") or ""),
                str(previous.get("input_digest") or "")
                != str(current.get("input_digest") or ""),
                previous_range != current_range,
            )
        ):
            break
        stable_to_line = int_value(
            current_range.get("to_line"), stable_to_line
        )
        stable_segment_count += 1
    return {
        "stable_to_line": stable_to_line,
        "stable_segment_count": stable_segment_count,
    }


def incremental_task_episodes_for_events(
    *,
    events: list[RawEvent],
    segments: list[dict[str, Any]],
    lineage: dict[str, Any],
    published_session_dir: Path | None,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Reuse sealed episode components and replay only a bounded tail."""
    full_metrics = {
        "mode": "full_builder_replay",
        "reused_sealed_episode_count": 0,
        "replayed_event_count": len(events),
        "replay_from_line": 1 if events else 0,
        "stable_segment_count": 0,
        "stable_to_line": 0,
        "admission": "no_compatible_previous_projection",
    }
    if published_session_dir is None:
        return (
            generated_task_episodes_for_events(
                events, segments, lineage=lineage
            ),
            full_metrics,
        )
    previous_index = read_json(
        published_session_dir / SESSION_INDEX_JSON,
        {},
    )
    previous_manifest = read_json(
        published_session_dir / "session.manifest.json",
        {},
    )
    stored_generation = (
        previous_index.get("dependency_generation_identities", {}).get(
            "task_episode_source"
        )
        if isinstance(
            previous_index.get("dependency_generation_identities"),
            dict,
        )
        else {}
    )
    generation_admission = projection_generation_admission(
        projection="task_episode_source",
        stored_identity=stored_generation,
        expected_identity=task_episode_source_generation_identity(),
    )
    if (
        not previous_index
        or not previous_manifest
        or not generation_admission.get("compatible")
    ):
        return (
            generated_task_episodes_for_events(
                events, segments, lineage=lineage
            ),
            full_metrics,
        )
    previous_episodes = session_index_task_episode_components(
        published_session_dir,
        previous_index,
    )
    prefix = append_stable_segment_prefix(
        previous_manifest.get("segments", [])
        if isinstance(previous_manifest.get("segments"), list)
        else [],
        segments,
    )
    stable_to_line = int_value(prefix.get("stable_to_line"))
    stable_episode_count = 0
    for episode in previous_episodes:
        event_range = (
            episode.get("event_range")
            if isinstance(episode, dict)
            and isinstance(episode.get("event_range"), dict)
            else {}
        )
        to_line = int_value(event_range.get("to_line"))
        if to_line <= 0 or to_line > stable_to_line:
            break
        stable_episode_count += 1
    # Keep two boundary-adjacent episodes in replay so transport-turn
    # bridging and semantic continuations can still revise the tail.
    reused_count = max(0, stable_episode_count - 2)
    if reused_count <= 0:
        return (
            generated_task_episodes_for_events(
                events, segments, lineage=lineage
            ),
            {
                **full_metrics,
                "stable_segment_count": int_value(
                    prefix.get("stable_segment_count")
                ),
                "stable_to_line": stable_to_line,
                "admission": "stable_prefix_too_small_for_bounded_reuse",
            },
        )
    reused = [
        dict(item)
        for item in previous_episodes[:reused_count]
        if isinstance(item, dict)
    ]
    replay_episode = previous_episodes[reused_count]
    replay_range = (
        replay_episode.get("event_range")
        if isinstance(replay_episode, dict)
        and isinstance(replay_episode.get("event_range"), dict)
        else {}
    )
    replay_from_line = int_value(replay_range.get("from_line"))
    replay_events = [
        event for event in events if event.line_no >= replay_from_line
    ]
    previous_episode_id = str(
        reused[-1].get("episode_id") or ""
    )
    replayed = generated_task_episodes_for_events(
        replay_events,
        segments,
        lineage=lineage,
        episode_ordinal_offset=len(reused),
        previous_episode_id=previous_episode_id,
    )
    return (
        [*reused, *replayed],
        {
            "mode": "append_stable_bounded_tail_replay_v1",
            "reused_sealed_episode_count": len(reused),
            "replayed_event_count": len(replay_events),
            "replay_from_line": replay_from_line,
            "stable_segment_count": int_value(
                prefix.get("stable_segment_count")
            ),
            "stable_to_line": stable_to_line,
            "admission": "matching_episode_abi_and_segment_digest_prefix",
            "previous_episode_count": len(previous_episodes),
        },
    )


def task_episode_builder_state_payload(
    *,
    episodes: list[dict[str, Any]],
    manifest: dict[str, Any],
    build_metrics: dict[str, Any],
    processed_to_line: int,
) -> dict[str, Any]:
    last_episode = episodes[-1] if episodes else {}
    last_two = episodes[-2:]
    correlation_ids = sorted(
        {
            str(item.get("correlation_id") or "")
            for episode in last_two
            if isinstance(episode, dict)
            for item in (
                episode.get("correlation_chain")
                if isinstance(episode.get("correlation_chain"), list)
                else []
            )
            if isinstance(item, dict)
            and str(item.get("correlation_id") or "")
        }
    )
    raw_blocks = (
        manifest.get("raw_blocks", {}).get("blocks", [])
        if isinstance(manifest.get("raw_blocks"), dict)
        and isinstance(
            manifest.get("raw_blocks", {}).get("blocks"), list
        )
        else []
    )
    last_block = raw_blocks[-1] if raw_blocks else {}
    lineage = (
        manifest.get("lineage")
        if isinstance(manifest.get("lineage"), dict)
        else {}
    )
    history_prefix = (
        lineage.get("history_prefix")
        if isinstance(lineage.get("history_prefix"), dict)
        else {}
    )
    return {
        "schema_version": TASK_EPISODE_BUILDER_STATE_VERSION,
        "artifact_type": "task_episode_builder_frontier",
        "generation_identity": (
            task_episode_source_generation_identity()
        ),
        "processed_to_line": processed_to_line,
        "last_processed_block": {
            "block_id": str(last_block.get("block_id") or ""),
            "sha256": str(last_block.get("sha256") or ""),
            "source_range": last_block.get("source_range", {}),
        },
        "sealed_episode_count": max(0, len(episodes) - 2),
        "tail_episode_ids": [
            str(episode.get("episode_id") or "")
            for episode in last_two
            if isinstance(episode, dict)
        ],
        "current_episode_id": str(
            last_episode.get("episode_id") or ""
        ),
        "current_episode_status": str(
            last_episode.get("status") or ""
        ),
        "transition_state": (
            last_episode.get("transition", {})
            if isinstance(last_episode, dict)
            and isinstance(last_episode.get("transition"), dict)
            else {}
        ),
        "correlation_frontier": correlation_ids,
        "lineage_context": {
            "relationship": str(lineage.get("relationship") or ""),
            "parent_session_id": str(
                lineage.get("parent_session_id") or ""
            ),
            "local_work_from_line": int_value(
                history_prefix.get("local_work_from_line")
            ),
        },
        "build_contract": (
            "append_frontier_with_bounded_replay_v1"
        ),
        "truth_status": (
            "append_frontier_for_bounded_replay_not_raw_authority"
        ),
    }


def write_session_index_impl(
    session_dir: Path,
    manifest: dict[str, Any],
    events: list[RawEvent],
    *,
    reference_session_dir: Path | None = None,
    publish_identity: dict[str, Any] | None = None,
    literal_policy: DerivedSessionSensitiveLiteralPolicy | None = None,
    workers: int = 1,
    cooperative_deadline_monotonic: float | None = None,
    execution_metrics_out: dict[str, Any] | None = None,
    event_summary: dict[str, Any] | None = None,
    processed_to_line: int | None = None,
) -> dict[str, Any]:
    execution_started = time.monotonic()
    execution_metrics: dict[str, Any] = {}
    if literal_policy is None:
        literal_policy = DerivedSessionSensitiveLiteralPolicy(
            values_by_kind={},
        )
    aggregate = event_summary if isinstance(event_summary, dict) else {}
    aggregate_mode = bool(aggregate)
    if aggregate_mode:
        by_type = dict(aggregate.get("event_counts", {}))
        family_counts = dict(aggregate.get("family_counts", {}))
        phase_counts = dict(aggregate.get("phase_counts", {}))
        actor_counts = dict(aggregate.get("actor_counts", {}))
        outcome_counts = dict(aggregate.get("outcome_counts", {}))
        conversation_act_counts = dict(
            aggregate.get("conversation_act_counts", {})
        )
        session_act_counts = dict(
            aggregate.get("session_act_counts", {})
        )
        agent_event_counts = dict(
            aggregate.get("agent_event_counts", {})
        )
        route_signal_counts = dict(
            aggregate.get("route_signal_counts", {})
        )
        total_event_count = int_value(aggregate.get("event_count"))
    else:
        counts = Counter(event.event_type for event in events)
        by_type = {
            event_type: counts[event_type]
            for event_type in EVENT_TYPE_ORDER
            if counts[event_type]
        }
        family_counts = dict(
            sorted(Counter(event.family for event in events).items())
        )
        phase_counts = dict(
            sorted(Counter(event.phase for event in events).items())
        )
        actor_counts = dict(
            sorted(Counter(event.actor for event in events).items())
        )
        outcome_counts = dict(
            sorted(Counter(event.outcome for event in events).items())
        )
        conversation_act_counts = conversation_act_counts_for_events(
            events
        )
        session_act_counts = session_act_counts_for_events(events)
        agent_event_counts = agent_event_counts_for_events(events)
        route_signal_counts = route_signal_counts_for_events(events)
        total_event_count = len(events)
    execution_metrics["event_aggregate_mode"] = (
        "classification_block_summary_merge_v1"
        if aggregate_mode
        else "full_event_reduction_v1"
    )
    phase_started = time.monotonic()
    task_episode_segments = (
        manifest.get("segments", [])
        if isinstance(manifest.get("segments"), list)
        else []
    )
    task_episodes, task_episode_incremental_build = (
        incremental_task_episodes_for_events(
            events=events,
            segments=task_episode_segments,
            lineage=(
                manifest.get("lineage")
                if isinstance(manifest.get("lineage"), dict)
                else {}
            ),
            published_session_dir=reference_session_dir,
        )
    )
    execution_metrics["task_episode_generation_ms"] = int(
        (time.monotonic() - phase_started) * 1000
    )
    execution_metrics["task_episode_incremental_build"] = dict(
        task_episode_incremental_build
    )
    phase_started = time.monotonic()
    attach_task_episode_session_context(
        task_episodes,
        session_dir=reference_session_dir or session_dir,
        manifest=manifest,
    )
    execution_metrics["task_episode_context_ms"] = int(
        (time.monotonic() - phase_started) * 1000
    )
    phase_started = time.monotonic()
    task_episode_shards = (
        materialize_session_index_task_episode_shards(
            session_dir,
            task_episodes,
            published_session_dir=reference_session_dir,
            publish_identity=(publish_identity or {}),
            literal_policy=literal_policy,
            workers=workers,
            cooperative_deadline_monotonic=(
                cooperative_deadline_monotonic
            ),
            pre_redacted_episode_count=int_value(
                task_episode_incremental_build.get(
                    "reused_sealed_episode_count"
                )
            ),
        )
    )
    execution_metrics["task_episode_shards_ms"] = int(
        (time.monotonic() - phase_started) * 1000
    )
    execution_metrics["task_episode_shards"] = dict(
        task_episode_shards.get("execution", {})
    )
    if not task_episode_shards.get("complete"):
        execution_metrics["total_ms"] = int(
            (time.monotonic() - execution_started) * 1000
        )
        if execution_metrics_out is not None:
            execution_metrics_out.update(execution_metrics)
        return {
            "status": "checkpointed",
            "checkpoint_phase": "session_index_task_episode_shards",
            "execution": execution_metrics,
        }
    task_episodes = [
        dict(item)
        for item in task_episode_shards.get("payloads", [])
        if isinstance(item, dict)
    ]
    task_episode_counts = task_episode_counts_for_episodes(
        task_episodes,
    )
    task_episode_builder_state = task_episode_builder_state_payload(
        episodes=task_episodes,
        manifest=manifest,
        build_metrics=task_episode_incremental_build,
        processed_to_line=(
            int_value(processed_to_line)
            if processed_to_line is not None
            else total_event_count
        ),
    )
    phase_started = time.monotonic()
    replay_from_line = int_value(
        task_episode_incremental_build.get("replay_from_line")
    )
    tail_has_goal_signal = any(
        event.line_no >= replay_from_line
        and str(
            (
                event.facets.get("session_act")
                if isinstance(
                    event.facets.get("session_act"), dict
                )
                else {}
            ).get("kind")
            or ""
        )
        in GOAL_SESSION_ACTS
        for event in events
    ) if replay_from_line > 0 else False
    previous_index_for_goal = (
        read_json(reference_session_dir / SESSION_INDEX_JSON, {})
        if reference_session_dir is not None
        else {}
    )
    incremental_episode_mode = bool(
        str(task_episode_incremental_build.get("mode") or "")
        == "append_stable_bounded_tail_replay_v1"
        and isinstance(
            previous_index_for_goal.get("goal_lifecycles"), list
        )
        and isinstance(previous_index_for_goal.get("goal_events"), list)
    )
    goal_lifecycle_incremental_execution: dict[str, Any] = {}
    if incremental_episode_mode and not tail_has_goal_signal:
        prior_goal_lifecycles = [
            dict(item)
            for item in previous_index_for_goal.get(
                "goal_lifecycles", []
            )
            if isinstance(item, dict)
        ]
        prior_goal_events = [
            dict(item)
            for item in previous_index_for_goal.get("goal_events", [])
            if isinstance(item, dict)
        ]
        goal_lifecycle_payload = {
            "goal_lifecycles": prior_goal_lifecycles,
            "goal_events": prior_goal_events,
            "goal_lifecycle_counts": (
                previous_index_for_goal.get("goal_lifecycle_counts", {})
            ),
            "goal_event_counts": previous_index_for_goal.get(
                "goal_event_counts", {}
            ),
        }
        goal_lifecycle_mode = "reuse_no_goal_signal_in_tail_v1"
        goal_lifecycle_incremental_execution = {
            "mode": goal_lifecycle_mode,
            "stable_lifecycle_count": len(prior_goal_lifecycles),
            "rebuilt_lifecycle_count": 0,
        }
    elif incremental_episode_mode:
        goal_replay_from_line = min(
            value
            for value in (
                replay_from_line,
                events[0].line_no if events else 0,
            )
            if value > 0
        )
        (
            incremental_goal_payload,
            goal_lifecycle_incremental_execution,
        ) = incremental_goal_lifecycles_for_events(
            events=events,
            segments=(
                manifest.get("segments", [])
                if isinstance(manifest.get("segments"), list)
                else []
            ),
            task_episodes=task_episodes,
            previous_index=previous_index_for_goal,
            replay_from_line=goal_replay_from_line,
            session_id=str(manifest["session_id"]),
            session_label=str(
                (
                    manifest.get("display")
                    if isinstance(manifest.get("display"), dict)
                    else {}
                ).get("label")
                or manifest.get("session_label")
                or ""
            ),
        )
        if incremental_goal_payload is None:
            if event_summary is not None:
                raise ValueError(
                    "incremental_goal_lifecycle_merge_failed:"
                    + str(
                        goal_lifecycle_incremental_execution.get(
                            "reason"
                        )
                        or "unknown"
                    )
                )
            goal_lifecycle_payload = generated_goal_lifecycles_for_events(
                events,
                manifest.get("segments", []) if isinstance(manifest.get("segments"), list) else [],
                task_episodes,
                session_id=str(manifest["session_id"]),
                session_label=str((manifest.get("display") if isinstance(manifest.get("display"), dict) else {}).get("label") or manifest.get("session_label") or ""),
            )
            goal_lifecycle_mode = "full_event_reduction_v1"
        else:
            goal_lifecycle_payload = incremental_goal_payload
            goal_lifecycle_mode = "append_stable_goal_tail_merge_v1"
    else:
        goal_lifecycle_payload = generated_goal_lifecycles_for_events(
            events,
            manifest.get("segments", []) if isinstance(manifest.get("segments"), list) else [],
            task_episodes,
            session_id=str(manifest["session_id"]),
            session_label=str((manifest.get("display") if isinstance(manifest.get("display"), dict) else {}).get("label") or manifest.get("session_label") or ""),
        )
        goal_lifecycle_mode = "full_event_reduction_v1"
    execution_metrics["goal_lifecycle_generation_ms"] = int(
        (time.monotonic() - phase_started) * 1000
    )
    execution_metrics["goal_lifecycle_mode"] = goal_lifecycle_mode
    execution_metrics["goal_lifecycle_incremental_build"] = (
        goal_lifecycle_incremental_execution
    )
    display = manifest.get("display", {}) if isinstance(manifest.get("display"), dict) else {}
    lineage = manifest.get("lineage") if isinstance(manifest.get("lineage"), dict) else {}
    semantic_names = semantic_names_payload(manifest)
    work_context = manifest.get("work_context") if isinstance(manifest.get("work_context"), dict) else {}
    token_accounting = (
        manifest.get("token_accounting")
        if isinstance(manifest.get("token_accounting"), dict)
        else token_accounting_summary_for_session(events, session_id=str(manifest.get("session_id") or "unknown"))
    )
    generation_identity = session_index_generation_identity()
    episode_source_generation = (
        task_episode_source_generation_identity()
    )
    segment_generation = segment_index_generation_identity()
    metadata_generation = (
        manifest.get("metadata_generation")
        if isinstance(
            manifest.get("metadata_generation"),
            dict,
        )
        else session_metadata_generation_identity(manifest)
    )
    task_episode_digest = task_episode_semantic_digest(
        session_id=str(manifest["session_id"]),
        display=display,
        task_episodes=task_episodes,
        source_generation_id=str(
            episode_source_generation.get("generation_id") or ""
        ),
        projection_publish=(
            publish_identity if isinstance(publish_identity, dict) else {}
        ),
        logical_root=reference_session_dir or session_dir,
    )
    session_index_json = {
        "schema_version": SCHEMA_VERSION,
        "generation_id": generation_identity["generation_id"],
        "generation_identity": generation_identity,
        "projection_publish": publish_identity or {},
        "dependency_generation_identities": {
            "segment_index": segment_generation,
            "task_episode_source": episode_source_generation,
            "session_metadata": metadata_generation,
        },
        "metadata_generation": metadata_generation,
        "session_act_schema_version": SESSION_ACT_SCHEMA_VERSION,
        "conversation_act_schema_version": CONVERSATION_ACT_SCHEMA_VERSION,
        "agent_event_schema_version": AGENT_EVENT_SCHEMA_VERSION,
        "task_episode_schema_version": TASK_EPISODE_SCHEMA_VERSION,
        "task_episode_semantic_digest": task_episode_digest,
        "session_lineage_schema_version": SESSION_LINEAGE_SCHEMA_VERSION,
        "goal_lifecycle_schema_version": GOAL_LIFECYCLE_SCHEMA_VERSION,
        "route_signal_schema_version": ROUTE_SIGNAL_SCHEMA_VERSION,
        "route_signal_classifier_version": ROUTE_SIGNAL_CLASSIFIER_VERSION,
        "token_accounting_schema_version": TOKEN_ACCOUNTING_SCHEMA_VERSION,
        "work_context_schema_version": WORK_CONTEXT_SCHEMA_VERSION,
        "session_id": manifest["session_id"],
        "lineage": manifest.get("lineage", {}) if isinstance(manifest.get("lineage"), dict) else {},
        "display": display,
        "semantic_names": semantic_names,
        "work_context": work_context,
        "token_accounting": token_accounting,
        "updated_at": manifest["updated_at"],
        "archive_status": manifest["archive_status"],
        "distillation_status": manifest.get("distillation_status", "raw_archived"),
        "event_count": total_event_count,
        "event_counts": by_type,
        "family_counts": family_counts,
        "phase_counts": phase_counts,
        "actor_counts": actor_counts,
        "outcome_counts": outcome_counts,
        "conversation_act_counts": conversation_act_counts,
        "session_act_counts": session_act_counts,
        "agent_event_counts": agent_event_counts,
        "task_episode_counts": task_episode_counts,
        "task_episodes": [],
        "task_episode_builder_state": task_episode_builder_state,
        "goal_lifecycle_counts": goal_lifecycle_payload["goal_lifecycle_counts"],
        "goal_event_counts": goal_lifecycle_payload["goal_event_counts"],
        "goal_lifecycles": goal_lifecycle_payload["goal_lifecycles"],
        "goal_events": goal_lifecycle_payload["goal_events"],
        "route_signal_counts": route_signal_counts,
        "segments": manifest.get("segments", []),
        "raw_blocks": manifest.get("raw_blocks", {}),
        "read_order": [
            "session.manifest.json",
            SESSION_INDEX_JSON,
            "latest segment index",
            "relevant segment markdown",
        ],
    }
    session_index_json["derived_text_redaction"] = {
        "policy_version": DERIVED_TEXT_REDACTION_POLICY_VERSION,
        "raw_authority_preserved": True,
        "applies_to": [
            "task_episode_representations",
            "goal_lifecycle_text",
            "generated_metadata_text",
        ],
        "session_sensitive_literals": (
            literal_policy.report()
        ),
    }
    phase_started = time.monotonic()
    session_index_json = redact_derived_value(
        session_index_json,
        literal_policy=literal_policy,
    )
    execution_metrics["root_redaction_ms"] = int(
        (time.monotonic() - phase_started) * 1000
    )
    shard_manifest = write_session_index_shard_manifest(
        session_dir,
        publish_identity=(publish_identity or {}),
        source_identity=dict(
            task_episode_shards.get("source_identity", {})
        ),
        task_episode_records=[
            dict(item)
            for item in task_episode_shards.get("records", [])
            if isinstance(item, dict)
        ],
    )
    session_index_json["component_storage"] = {
        "schema_version": SESSION_INDEX_SHARD_SCHEMA_VERSION,
        "mode": shard_manifest["storage_mode"],
        "manifest_ref": str(
            Path(SESSION_INDEX_SHARDS_DIR)
            / SESSION_INDEX_SHARD_MANIFEST_JSON
        ),
        "task_episode_shard_count": len(task_episodes),
        "embedded_compatibility_view": False,
        "reader_mode": "manifest_first",
    }
    phase_started = time.monotonic()
    write_json(session_dir / SESSION_INDEX_JSON, session_index_json)
    execution_metrics["compatibility_json_write_ms"] = int(
        (time.monotonic() - phase_started) * 1000
    )
    legacy_json = session_dir / LEGACY_SESSION_INDEX_JSON
    if legacy_json.exists():
        legacy_json.unlink()

    lines = [
        "---",
        "aoa_artifact_type: session_index",
        "schema_version: 1",
        f"session_id: {manifest['session_id']}",
        f"session_label: {display.get('label', '')}",
        f"session_title: {display.get('title', '')}",
        f"archive_status: {manifest['archive_status']}",
        f"distillation_status: {manifest.get('distillation_status', 'raw_archived')}",
        f"updated_at: {manifest['updated_at']}",
        "---",
        "",
        f"# {display.get('label') or 'Session Index'}",
        "",
        "## Identity",
        "",
        f"- title: `{display.get('title', '')}`",
        f"- label: `{display.get('label', '')}`",
        f"- date: `{display.get('date', '')}`",
        f"- sequence: `{display.get('sequence', '')}`",
        f"- session_id: `{manifest['session_id']}`",
        f"- path: `{display.get('path', str(session_dir))}`",
        f"- source transcript: `{manifest.get('source', {}).get('transcript_path', '') if isinstance(manifest.get('source'), dict) else ''}`",
        *(
            [
                f"- lineage: `{lineage.get('relationship', '')}`",
                f"- parent session: `{lineage.get('parent_session_id', '')}`",
                f"- lineage evidence: `{(lineage.get('evidence') or {}).get('raw_ref', '')}`",
                f"- local work boundary: `{(lineage.get('history_prefix') or {}).get('boundary_ref', '')}`",
            ]
            if lineage
            else []
        ),
        *semantic_name_identity_lines(manifest),
        "",
        "## Work Context",
        "",
        f"- status: `{work_context.get('status', '')}`",
        f"- work_name: `{work_context.get('work_name', '')}`",
        f"- work_family: `{work_context.get('work_family', '')}`",
        f"- work_root: `{work_context.get('work_root', '')}`",
        f"- confidence: `{work_context.get('confidence', '')}`",
        "",
        "## Status",
        "",
        f"- archive_status: `{manifest['archive_status']}`",
        f"- distillation_status: `{manifest.get('distillation_status', 'raw_archived')}`",
        f"- events: `{total_event_count}`",
        "",
        "## Token Accounting",
        "",
        f"- schema: `{TOKEN_ACCOUNTING_CONTRACT}`",
        f"- provider_reported_events: `{token_accounting.get('provider_reported_event_count', 0)}`",
        f"- estimated_events: `{token_accounting.get('estimated_event_count', 0)}`",
        f"- count_basis: `{json.dumps(token_accounting.get('count_by_basis', {}), ensure_ascii=False)}`",
        "",
        "## Read Order",
        "",
        "1. `session.manifest.json`",
        f"2. `{SESSION_INDEX_JSON}`",
        "3. latest relevant `segments/*.index.json`",
        "4. relevant `segments/*.md`",
        "",
        "## Segments",
        "",
    ]
    for segment in manifest.get("segments", []):
        raw_block = segment.get("raw_block") if isinstance(segment, dict) and isinstance(segment.get("raw_block"), dict) else {}
        lines.append(
            f"- `{Path(segment['markdown']).name}`: {segment['role']}, "
            f"{segment['event_count']} events, lines "
            f"{segment['source_range'].get('from_line')}..{segment['source_range'].get('to_line')}, "
            f"raw block `{raw_block.get('rel', '')}`"
        )
    lines.extend(["", "## Event Counts", ""])
    for event_type, count in by_type.items():
        lines.append(f"- `{event_type}`: {count}")
    lines.extend(["", "## Universal Facets", ""])
    lines.append("### Families")
    for family, count in family_counts.items():
        lines.append(f"- `{family}`: {count}")
    lines.append("")
    lines.append("### Phases")
    for phase, count in phase_counts.items():
        lines.append(f"- `{phase}`: {count}")
    lines.append("")
    lines.append("### Outcomes")
    for outcome, count in outcome_counts.items():
        lines.append(f"- `{outcome}`: {count}")
    lines.append("")
    if session_act_counts:
        lines.append("### Session Acts")
        for act, count in session_act_counts.items():
            lines.append(f"- `{act}`: {count}")
        lines.append("")
    if agent_event_counts:
        lines.append("### Agent Events")
        for act, count in agent_event_counts.items():
            lines.append(f"- `{act}`: {count}")
        lines.append("")
    if task_episodes:
        lines.append("### Task Episodes")
        lines.append(f"- total: `{len(task_episodes)}`")
        for status, count in task_episode_counts.get("by_status", {}).items():
            lines.append(f"- `{status}`: {count}")
        lines.append("")
    if goal_lifecycle_payload["goal_lifecycles"]:
        lines.append("### Goal Lifecycles")
        lines.append(f"- total: `{len(goal_lifecycle_payload['goal_lifecycles'])}`")
        for status, count in goal_lifecycle_payload["goal_lifecycle_counts"].get("by_status", {}).items():
            lines.append(f"- `{status}`: {count}")
        for kind, count in goal_lifecycle_payload["goal_event_counts"].items():
            lines.append(f"- event `{kind}`: {count}")
        lines.append("")
    if route_signal_counts:
        lines.append("### Route Signals")
        for layer, keys in route_signal_counts.items():
            lines.append(f"- `{layer}`: {sum(keys.values())}")
            for key, count in list(keys.items())[:12]:
                lines.append(f"  - `{key}`: {count}")
        lines.append("")
    phase_started = time.monotonic()
    (session_dir / SESSION_INDEX_MARKDOWN).write_text(
        redact_derived_text(
            "\n".join(lines),
            literal_policy=literal_policy,
        ),
        encoding="utf-8",
    )
    legacy_md = session_dir / LEGACY_SESSION_INDEX_MARKDOWN
    if legacy_md.exists():
        legacy_md.unlink()
    execution_metrics["markdown_write_ms"] = int(
        (time.monotonic() - phase_started) * 1000
    )
    execution_metrics["total_ms"] = int(
        (time.monotonic() - execution_started) * 1000
    )
    if execution_metrics_out is not None:
        execution_metrics_out.update(execution_metrics)
    return {
        "status": "complete",
        "component_storage": session_index_json[
            "component_storage"
        ],
        "execution": execution_metrics,
    }


def projection_outbox_root_for_session(
    session_dir: Path,
) -> Path:
    return session_dir.parent.parent / PROJECTION_OUTBOX_ROOT


def projection_component_snapshot(
    projection_dir: Path,
) -> dict[str, dict[str, Any]]:
    """Describe independently replaceable published contributions.

    The snapshot contains only component identities, content digests, bounded
    source refs, and generation identities.  It never hydrates raw bodies or
    task-episode payloads.
    """
    components: dict[str, dict[str, Any]] = {}
    manifest = read_json(
        projection_dir / "session.manifest.json",
        {},
    )
    session_index = read_json(
        projection_dir / SESSION_INDEX_JSON,
        {},
    )

    def add_component(
        component_id: str,
        *,
        component_type: str,
        digest: str,
        source_ref: str,
        generation_identity: dict[str, Any] | None = None,
    ) -> None:
        if not component_id or not digest:
            return
        components[component_id] = {
            "component_id": component_id,
            "component_type": component_type,
            "digest": digest,
            "source_ref": source_ref,
            "generation_identity": (
                dict(generation_identity)
                if isinstance(generation_identity, dict)
                else {}
            ),
        }

    manifest_path = projection_dir / "session.manifest.json"
    if manifest_path.is_file():
        add_component(
            "session:manifest",
            component_type="session_manifest",
            digest=sha256_file(manifest_path),
            source_ref="session.manifest.json",
            generation_identity=(
                manifest.get("metadata_generation")
                if isinstance(manifest, dict)
                and isinstance(manifest.get("metadata_generation"), dict)
                else {}
            ),
        )
    session_index_path = projection_dir / SESSION_INDEX_JSON
    if session_index_path.is_file():
        add_component(
            "session:index",
            component_type="session_component_manifest",
            digest=sha256_file(session_index_path),
            source_ref=SESSION_INDEX_JSON,
            generation_identity=(
                session_index.get("generation_identity")
                if isinstance(session_index, dict)
                and isinstance(
                    session_index.get("generation_identity"), dict
                )
                else {}
            ),
        )

    for segment in (
        manifest.get("segments", [])
        if isinstance(manifest, dict)
        and isinstance(manifest.get("segments"), list)
        else []
    ):
        if not isinstance(segment, dict):
            continue
        segment_id = str(segment.get("segment_id") or "")
        index_name = Path(str(segment.get("index") or "")).name
        index_path = projection_dir / "segments" / index_name
        if not segment_id or not index_path.is_file():
            continue
        segment_index = read_json(index_path, {})
        segment_generation = (
            segment_index.get("generation_identity")
            if isinstance(segment_index, dict)
            and isinstance(
                segment_index.get("generation_identity"), dict
            )
            else {}
        )
        semantic_digest = hashlib.sha256(
            json.dumps(
                {
                    "input_digest": str(
                        segment_index.get("input_digest") or ""
                    ),
                    "generation_id": str(
                        segment_generation.get("generation_id") or ""
                    ),
                },
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        add_component(
            f"segment:{segment_id}",
            component_type="segment_index",
            digest=semantic_digest,
            source_ref=str(Path("segments") / index_name),
            generation_identity=segment_generation,
        )

    raw_block_index = read_json(
        projection_dir / "raw" / RAW_BLOCK_INDEX_JSON,
        {},
    )
    for ordinal, block in enumerate(
        raw_block_index.get("blocks", [])
        if isinstance(raw_block_index, dict)
        and isinstance(raw_block_index.get("blocks"), list)
        else []
    ):
        if not isinstance(block, dict):
            continue
        block_id = str(
            block.get("block_id")
            or block.get("sha256")
            or f"{ordinal:06d}"
        )
        digest = str(block.get("sha256") or "")
        add_component(
            f"raw_block:{block_id}",
            component_type="raw_block",
            digest=digest,
            source_ref=str(
                block.get("rel")
                or block.get("path")
                or block.get("plain_rel")
                or ""
            ),
            generation_identity={},
        )

    shard_manifest = read_json(
        projection_dir
        / SESSION_INDEX_SHARDS_DIR
        / SESSION_INDEX_SHARD_MANIFEST_JSON,
        {},
    )
    shard_records = (
        shard_manifest.get("components", {}).get("task_episodes", [])
        if isinstance(shard_manifest, dict)
        and isinstance(shard_manifest.get("components"), dict)
        and isinstance(
            shard_manifest.get("components", {}).get("task_episodes"),
            list,
        )
        else []
    )
    for ordinal, record in enumerate(shard_records):
        if not isinstance(record, dict):
            continue
        component_key = str(
            record.get("component_key") or f"{ordinal:04d}"
        )
        add_component(
            f"task_episode:{component_key}",
            component_type="task_episode",
            digest=str(record.get("artifact_sha256") or ""),
            source_ref=str(record.get("ref") or ""),
            generation_identity=(
                record.get("source_identity")
                if isinstance(record.get("source_identity"), dict)
                else {}
            ),
        )
    return components


def projection_component_required_consumers(
    component_type: str,
) -> list[str]:
    if component_type == "task_episode":
        return [
            "episode_semantic",
            "entity_registry",
            "exact_and_lexical_search",
            "graph",
        ]
    if component_type == "raw_block":
        return ["exact_and_lexical_search", "entity_registry"]
    return list(PROJECTION_OUTBOX_CONSUMERS)


def session_projection_outbox_record(
    *,
    session_dir: Path,
    old_snapshot: dict[str, dict[str, Any]],
    new_snapshot: dict[str, dict[str, Any]],
    old_publish_id: str,
    new_publish_id: str,
    session_id: str | None = None,
) -> dict[str, Any]:
    changes: list[dict[str, Any]] = []
    required_consumers: set[str] = set()
    for component_id in sorted(set(old_snapshot) | set(new_snapshot)):
        old = old_snapshot.get(component_id, {})
        new = new_snapshot.get(component_id, {})
        if old == new:
            continue
        component_type = str(
            new.get("component_type")
            or old.get("component_type")
            or "unknown"
        )
        consumers = projection_component_required_consumers(
            component_type
        )
        required_consumers.update(consumers)
        changes.append(
            {
                "component_id": component_id,
                "component_type": component_type,
                "operation": (
                    "replace"
                    if old and new
                    else ("publish" if new else "tombstone")
                ),
                "old_digest": str(old.get("digest") or ""),
                "new_digest": str(new.get("digest") or ""),
                "source_ref": str(
                    new.get("source_ref")
                    or old.get("source_ref")
                    or ""
                ),
                "generation_identity": (
                    new.get("generation_identity")
                    if isinstance(
                        new.get("generation_identity"), dict
                    )
                    else {}
                ),
                "required_consumers": consumers,
            }
        )
    identity_payload = {
        "schema_version": PROJECTION_OUTBOX_SCHEMA_VERSION,
        "session_id": str(session_id or session_dir.name),
        "old_publish_id": old_publish_id,
        "new_publish_id": new_publish_id,
        "changes": changes,
        "required_consumers": sorted(required_consumers),
    }
    record_id = hashlib.sha256(
        json.dumps(
            identity_payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return {
        **identity_payload,
        "artifact_type": "session_projection_component_outbox",
        "record_id": record_id,
        "created_at": utc_now(),
        "status": "pending",
        "retry_policy": {
            "mode": "bounded_idempotent_consumer_replay_v1",
            "max_attempts_per_cycle": 3,
        },
        "publication_receipt": {
            "session_dir": str(session_dir),
            "publish_id": new_publish_id,
        },
        "truth_status": (
            "changed_component_work_intent_not_downstream_completion"
        ),
    }


def projection_outbox_record_path(
    session_dir: Path,
    record_id: str,
) -> Path:
    return (
        projection_outbox_root_for_session(session_dir)
        / "records"
        / f"{record_id}.json"
    )


def write_projection_outbox_record(
    session_dir: Path,
    record: dict[str, Any],
) -> dict[str, Any]:
    record_id = str(record.get("record_id") or "")
    if not record_id:
        raise ValueError("projection_outbox_record_id_missing")
    path = projection_outbox_record_path(session_dir, record_id)
    existing = read_json(path, {})
    if isinstance(existing, dict) and existing:
        comparable_keys = (
            "schema_version",
            "artifact_type",
            "record_id",
            "session_id",
            "old_publish_id",
            "new_publish_id",
            "changes",
            "required_consumers",
        )
        if any(
            existing.get(key) != record.get(key)
            for key in comparable_keys
        ):
            raise ValueError("projection_outbox_record_collision")
        return {
            "status": "reused",
            "path": str(path),
            "record_id": record_id,
            "change_count": len(record.get("changes", [])),
        }
    write_json_durable(path, record)
    return {
        "status": "written",
        "path": str(path),
        "record_id": record_id,
        "change_count": len(record.get("changes", [])),
    }


def projection_outbox_consumer_state_path(
    session_dir: Path,
    *,
    consumer: str,
    record_id: str,
) -> Path:
    return (
        projection_outbox_root_for_session(session_dir)
        / "consumer-state"
        / safe_slug(consumer, fallback="consumer")
        / f"{record_id}.json"
    )


def write_projection_outbox_consumer_state(
    session_dir: Path,
    *,
    record: dict[str, Any],
    consumer: str,
    status: str,
    reason: str,
    completion_receipt: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if consumer not in PROJECTION_OUTBOX_CONSUMERS:
        raise ValueError(
            f"projection_outbox_consumer_unknown:{consumer}"
        )
    record_id = str(record.get("record_id") or "")
    if not record_id:
        raise ValueError("projection_outbox_record_id_missing")
    path = projection_outbox_consumer_state_path(
        session_dir,
        consumer=consumer,
        record_id=record_id,
    )
    existing = read_json(path, {})
    if isinstance(existing, dict) and existing.get("status") == "complete":
        if status != "complete" or (
            isinstance(completion_receipt, dict)
            and existing.get("completion_receipt")
            == completion_receipt
            and existing.get("source_publish_id")
            == record.get("new_publish_id")
        ):
            return {
                "status": "already_complete",
                "path": str(path),
                "consumer": consumer,
                "record_id": record_id,
            }
        raise ValueError(
            "projection_outbox_completion_receipt_conflict"
        )
    attempts = int_value(
        existing.get("attempt_count")
        if isinstance(existing, dict)
        else 0
    )
    payload = {
        "schema_version": 1,
        "artifact_type": "projection_outbox_consumer_state",
        "record_id": record_id,
        "session_id": record.get("session_id"),
        "consumer": consumer,
        "source_publish_id": record.get("new_publish_id"),
        "status": status,
        "reason": reason,
        "attempt_count": attempts + 1,
        "updated_at": utc_now(),
        "component_ids": [
            str(item.get("component_id") or "")
            for item in record.get("changes", [])
            if isinstance(item, dict)
            and consumer
            in (
                item.get("required_consumers")
                if isinstance(item.get("required_consumers"), list)
                else []
            )
        ],
        "semantic_completion": status == "complete",
        "completion_receipt": (
            dict(completion_receipt)
            if isinstance(completion_receipt, dict)
            else {}
        ),
        "truth_status": (
            "consumer_completion_receipt"
            if status == "complete"
            else "consumer_work_state_not_semantic_completion"
        ),
    }
    if status == "complete" and not payload["completion_receipt"]:
        raise ValueError(
            "projection_outbox_completion_receipt_required"
        )
    write_json_durable(path, payload)
    return {
        "status": status,
        "path": str(path),
        "consumer": consumer,
        "record_id": record_id,
    }


def route_projection_outbox_record(
    session_dir: Path,
    *,
    outbox_path: Path,
    consumer_statuses: dict[str, tuple[str, str]],
) -> dict[str, Any]:
    record = read_json(outbox_path, {})
    if not isinstance(record, dict) or not record:
        return {
            "ok": False,
            "status": "outbox_record_unavailable",
            "diagnostics": [str(outbox_path)],
        }
    current_manifest = read_json(
        session_dir / "session.manifest.json",
        {},
    )
    current_publish_id = projection_publish_id(
        current_manifest.get("index_schema")
        if isinstance(current_manifest, dict)
        and isinstance(current_manifest.get("index_schema"), dict)
        else {}
    )
    if current_publish_id != str(record.get("new_publish_id") or ""):
        return {
            "ok": False,
            "status": "outbox_source_publish_not_current",
            "record_id": record.get("record_id"),
            "expected_publish_id": record.get("new_publish_id"),
            "current_publish_id": current_publish_id,
            "diagnostics": ["outbox_record_not_current_publication"],
        }
    states = []
    for consumer in record.get("required_consumers", []):
        if consumer not in consumer_statuses:
            continue
        status, reason = consumer_statuses[consumer]
        states.append(
            write_projection_outbox_consumer_state(
                session_dir,
                record=record,
                consumer=consumer,
                status=status,
                reason=reason,
            )
        )
    return {
        "ok": True,
        "status": "routed",
        "record_id": record.get("record_id"),
        "consumer_states": states,
        "semantic_completion": False,
    }


def session_projection_outbox_record_for_publish(
    aoa_root: Path,
    *,
    session_id: str,
    publish_id: str,
) -> tuple[Path | None, dict[str, Any]]:
    records_dir = aoa_root / PROJECTION_OUTBOX_RECORDS_DIR
    matches: list[tuple[str, Path, dict[str, Any]]] = []
    for path in records_dir.glob("*.json"):
        record = read_json(path, {})
        if not isinstance(record, dict):
            continue
        if (
            str(record.get("session_id") or "") == session_id
            and str(record.get("new_publish_id") or "") == publish_id
        ):
            matches.append(
                (str(record.get("created_at") or ""), path, record)
            )
    if not matches:
        return None, {}
    _created_at, path, record = max(matches, key=lambda item: item[0])
    return path, record


def projection_outbox_ready_sessions(
    aoa_root: Path,
    *,
    limit: int = 16,
) -> dict[str, Any]:
    records_dir = aoa_root / PROJECTION_OUTBOX_RECORDS_DIR
    selected_by_session: dict[str, tuple[str, dict[str, Any]]] = {}
    inspected_count = 0
    stale_record_count = 0
    for path in sorted(
        records_dir.glob("*.json"),
        key=lambda item: item.stat().st_mtime_ns,
        reverse=True,
    ):
        record = read_json(path, {})
        if not isinstance(record, dict) or not record:
            continue
        inspected_count += 1
        session_id = str(record.get("session_id") or "")
        session_dir = Path(
            str(
                (
                    record.get("publication_receipt")
                    if isinstance(
                        record.get("publication_receipt"), dict
                    )
                    else {}
                ).get("session_dir")
                or ""
            )
        )
        if not session_id or not session_dir.is_dir():
            stale_record_count += 1
            continue
        manifest = read_json(
            session_dir / "session.manifest.json",
            {},
        )
        publish_id = projection_publish_id(
            manifest.get("index_schema")
            if isinstance(manifest, dict)
            and isinstance(manifest.get("index_schema"), dict)
            else {}
        )
        if publish_id != str(record.get("new_publish_id") or ""):
            stale_record_count += 1
            continue
        pending_consumers: list[str] = []
        for consumer in record.get("required_consumers", []):
            state = read_json(
                projection_outbox_consumer_state_path(
                    session_dir,
                    consumer=str(consumer),
                    record_id=str(record.get("record_id") or ""),
                ),
                {},
            )
            if str(state.get("status") or "") != "complete":
                pending_consumers.append(str(consumer))
        if not pending_consumers:
            continue
        display = (
            manifest.get("display")
            if isinstance(manifest, dict)
            and isinstance(manifest.get("display"), dict)
            else {}
        )
        candidate = {
            "path": str(session_dir),
            "session_id": session_id,
            "session_label": str(
                display.get("label")
                or manifest.get("session_label")
                or session_dir.name
            ),
            "session_title": str(
                display.get("title")
                or manifest.get("session_title")
                or ""
            ),
            "archive_status": str(
                manifest.get("archive_status") or "indexed"
            ),
            "outbox_record_id": str(record.get("record_id") or ""),
            "outbox_record_path": str(path),
            "outbox_created_at": str(record.get("created_at") or ""),
            "outbox_mtime_ns": path.stat().st_mtime_ns,
            "pending_consumers": pending_consumers,
            "changed_component_count": len(record.get("changes", [])),
        }
        existing = selected_by_session.get(session_id)
        ordering = str(record.get("created_at") or "")
        if existing is None or ordering > existing[0]:
            selected_by_session[session_id] = (ordering, candidate)
        if len(selected_by_session) >= max(1, limit):
            break
    records = [
        item[1]
        for item in sorted(
            selected_by_session.values(),
            key=lambda pair: (
                pair[0],
                int_value(pair[1].get("outbox_mtime_ns")),
                str(pair[1].get("session_id") or ""),
            ),
        )
    ]
    return {
        "schema_version": 1,
        "artifact_type": "projection_outbox_ready_sessions",
        "generated_at": utc_now(),
        "status": "ready" if records else "empty",
        "records": records,
        "ready_session_count": len(records),
        "inspected_record_count": inspected_count,
        "stale_record_count": stale_record_count,
        "raw_bytes_read": 0,
        "archive_manifest_scan_performed": False,
        "truth_status": (
            "current_publication_pending_consumer_work_not_semantic_completion"
        ),
    }


def complete_projection_outbox_consumers_for_session(
    *,
    aoa_root: Path,
    session_dir: Path,
    consumers: Iterable[str],
    completion_receipt: dict[str, Any],
) -> dict[str, Any]:
    manifest = read_json(
        session_dir / "session.manifest.json",
        {},
    )
    session_id = str(
        manifest.get("session_id")
        if isinstance(manifest, dict)
        else ""
    )
    publish_id = projection_publish_id(
        manifest.get("index_schema")
        if isinstance(manifest, dict)
        and isinstance(manifest.get("index_schema"), dict)
        else {}
    )
    outbox_path, record = session_projection_outbox_record_for_publish(
        aoa_root,
        session_id=session_id,
        publish_id=publish_id,
    )
    if outbox_path is None or not record:
        return {
            "ok": True,
            "status": "no_current_outbox_record",
            "completed_consumers": [],
        }
    required = {
        str(item) for item in record.get("required_consumers", [])
    }
    completed: list[str] = []
    states: list[dict[str, Any]] = []
    for consumer in consumers:
        consumer_name = str(consumer)
        if consumer_name not in required:
            continue
        existing_state_path = projection_outbox_consumer_state_path(
            session_dir,
            consumer=consumer_name,
            record_id=str(record.get("record_id") or ""),
        )
        existing_state = read_json(existing_state_path, {})
        if (
            isinstance(existing_state, dict)
            and existing_state.get("status") == "complete"
            and existing_state.get("source_publish_id") == publish_id
            and existing_state.get("record_id") == record.get("record_id")
        ):
            completed.append(consumer_name)
            states.append(
                {
                    "status": "already_complete",
                    "path": str(existing_state_path),
                    "consumer": consumer_name,
                    "record_id": record.get("record_id"),
                }
            )
            continue
        state = write_projection_outbox_consumer_state(
            session_dir,
            record=record,
            consumer=consumer_name,
            status="complete",
            reason="exact_consumer_transaction_committed",
            completion_receipt={
                **completion_receipt,
                "consumer": consumer_name,
                "source_publish_id": publish_id,
                "outbox_record_id": record.get("record_id"),
                "completed_at": utc_now(),
            },
        )
        completed.append(consumer_name)
        states.append(state)
    return {
        "ok": True,
        "status": "completed" if completed else "not_required",
        "record_id": record.get("record_id"),
        "outbox_ref": str(outbox_path),
        "completed_consumers": completed,
        "consumer_states": states,
    }


def complete_graph_outbox_consumers_from_ledger(
    aoa_root: Path,
    *,
    limit: int = 32,
) -> dict[str, Any]:
    ready = projection_outbox_ready_sessions(aoa_root, limit=limit)
    ledger = read_graph_source_state_ledger(aoa_root)
    entries = (
        ledger.get("sources")
        if isinstance(ledger.get("sources"), dict)
        else {}
    )
    completions: list[dict[str, Any]] = []
    deferred: list[dict[str, Any]] = []
    for candidate in ready.get("records", []):
        if not isinstance(candidate, dict) or "graph" not in (
            candidate.get("pending_consumers") or []
        ):
            continue
        session_dir = Path(str(candidate.get("path") or ""))
        record = read_json(
            Path(str(candidate.get("outbox_record_path") or "")),
            {},
        )
        session_id = str(candidate.get("session_id") or "")
        publish_id = str(record.get("new_publish_id") or "")
        required_keys = {
            graph_source_key("session", session_id, "")
        }
        for change in record.get("changes", []):
            if not isinstance(change, dict):
                continue
            component_id = str(change.get("component_id") or "")
            if component_id.startswith("segment:"):
                required_keys.add(
                    graph_source_key(
                        "segment",
                        session_id,
                        component_id.split(":", 1)[1],
                    )
                )
        unresolved = [
            source_key
            for source_key in sorted(required_keys)
            if not (
                isinstance(entries.get(source_key), dict)
                and str(entries[source_key].get("status") or "")
                == "current"
                and str(
                    entries[source_key].get(
                        "source_projection_publish_id"
                    )
                    or ""
                )
                == publish_id
            )
        ]
        if unresolved:
            deferred.append(
                {
                    "session_id": session_id,
                    "record_id": record.get("record_id"),
                    "unresolved_source_keys": unresolved,
                }
            )
            continue
        completion = complete_projection_outbox_consumers_for_session(
            aoa_root=aoa_root,
            session_dir=session_dir,
            consumers=["graph"],
            completion_receipt={
                "artifact_type": "graph_consumer_ledger_receipt",
                "graph_store": str(graph_paths(aoa_root)["store"]),
                "graph_ledger": str(
                    graph_paths(aoa_root)["source_state_ledger"]
                ),
                "source_keys": sorted(required_keys),
                "ledger_updated_at": ledger.get("updated_at"),
            },
        )
        if completion.get("completed_consumers"):
            completions.append(completion)
    return {
        "ok": True,
        "status": "completed" if completions else "no_completion",
        "completed_count": len(completions),
        "completions": completions,
        "deferred": deferred,
    }


def complete_entity_registry_outbox_consumers(
    aoa_root: Path,
    *,
    limit: int = 32,
) -> dict[str, Any]:
    """Acknowledge entity work only from an exact persisted registry view."""
    registry_state = entity_registry_maintenance_status(aoa_root)
    observed_route_source = str(
        registry_state.get("observed_route_source") or ""
    )
    route_dependency: dict[str, Any] = {}
    dependency_current = False
    if observed_route_source == "operational_route_rollup":
        route_dependency = entity_registry_observed_rollup_ready(
            aoa_root
        )
        dependency_current = bool(route_dependency.get("ready"))
    elif observed_route_source == "archived_route_terms":
        route_dependency = {
            "status": "current"
            if search_db_path(aoa_root).is_file()
            else "missing",
            "path": str(search_db_path(aoa_root)),
        }
        dependency_current = search_db_path(aoa_root).is_file()
    if (
        registry_state.get("status") != "current"
        or not dependency_current
    ):
        return {
            "ok": True,
            "status": "deferred_registry_dependency_not_current",
            "completed_count": 0,
            "completions": [],
            "deferred": [
                {
                    "reason": "entity_registry_or_observed_route_dependency_not_current",
                    "entity_registry_status": registry_state.get(
                        "status"
                    ),
                    "observed_route_source": observed_route_source,
                    "route_dependency_status": route_dependency.get(
                        "status"
                    ),
                }
            ],
        }

    ready = projection_outbox_ready_sessions(aoa_root, limit=limit)
    completions: list[dict[str, Any]] = []
    deferred: list[dict[str, Any]] = []
    for candidate in ready.get("records", []):
        if not isinstance(candidate, dict) or "entity_registry" not in (
            candidate.get("pending_consumers") or []
        ):
            continue
        session_dir = Path(str(candidate.get("path") or ""))
        record = read_json(
            Path(str(candidate.get("outbox_record_path") or "")),
            {},
        )
        record_id = str(record.get("record_id") or "")
        search_state = read_json(
            projection_outbox_consumer_state_path(
                session_dir,
                consumer="exact_and_lexical_search",
                record_id=record_id,
            ),
            {},
        )
        if str(search_state.get("status") or "") != "complete":
            deferred.append(
                {
                    "session_id": candidate.get("session_id"),
                    "record_id": record_id,
                    "reason": "exact_search_predecessor_not_complete",
                }
            )
            continue
        completion = complete_projection_outbox_consumers_for_session(
            aoa_root=aoa_root,
            session_dir=session_dir,
            consumers=["entity_registry"],
            completion_receipt={
                "artifact_type": "entity_registry_consumer_receipt",
                "registry_path": registry_state.get("path"),
                "registry_generated_at": registry_state.get(
                    "generated_at"
                ),
                "registry_semantic_digest": registry_state.get(
                    "semantic_digest"
                ),
                "observed_route_source": observed_route_source,
                "observed_source_dependency": registry_state.get(
                    "observed_source_dependency"
                ),
                "route_dependency": route_dependency,
                "search_predecessor_state": search_state,
            },
        )
        if completion.get("completed_consumers"):
            completions.append(completion)
    return {
        "ok": True,
        "status": "completed" if completions else "no_completion",
        "completed_count": len(completions),
        "completions": completions,
        "deferred": deferred,
    }


def session_projection_freshness_vector(
    *,
    aoa_root: Path,
    session_dir: Path,
    returned_evidence: dict[str, Any] | None = None,
) -> dict[str, Any]:
    manifest = read_json(session_dir / "session.manifest.json", {})
    session_index = read_json(
        session_dir / SESSION_INDEX_JSON,
        {},
    )
    session_id = str(
        manifest.get("session_id")
        if isinstance(manifest, dict)
        else ""
    ) or session_dir.name
    capture_state = raw_capture_state_for_session(session_dir)
    source_path = Path(str(capture_state.get("source_path") or ""))
    capture_reasons: list[str] = []
    try:
        source_stat = source_path.stat()
    except OSError:
        source_stat = None
        capture_reasons.append("capture_source_unavailable")
    captured_bytes = int_value(capture_state.get("raw_bytes"), -1)
    captured_snapshot = (
        capture_state.get("source_snapshot_after")
        if isinstance(
            capture_state.get("source_snapshot_after"), dict
        )
        else {}
    )
    capture_current = bool(
        source_stat is not None
        and source_stat.st_size == captured_bytes
        and (
            not captured_snapshot.get("device")
            or source_stat.st_dev
            == int_value(captured_snapshot.get("device"), -1)
        )
        and (
            not captured_snapshot.get("inode")
            or source_stat.st_ino
            == int_value(captured_snapshot.get("inode"), -1)
        )
    )
    if not capture_current and source_stat is not None:
        capture_reasons.append("source_advanced_beyond_capture_watermark")

    overlay = read_json(
        persistent_live_tail_index_path(session_dir),
        {},
    )
    overlay_reasons: list[str] = []
    overlay_current = bool(
        capture_current
        and isinstance(overlay, dict)
        and overlay.get("artifact_type")
        == "persistent_live_tail_overlay"
        and int_value(overlay.get("captured_bytes"), -1)
        == captured_bytes
        and str(overlay.get("source_path") or "")
        == str(source_path)
        and str(overlay.get("ledger_chain_sha256") or "")
        == str(capture_state.get("ledger_chain_sha256") or "")
    )
    if not overlay_current:
        overlay_reasons.append(
            "persistent_live_overlay_not_at_capture_watermark"
        )

    stable_reasons = (
        ["session_projection_publish_in_progress"]
        if session_projection_publish_in_progress(session_dir)
        else generated_session_index_stale_reasons_for_session(
            session_dir,
            session_index,
        )
        if isinstance(session_index, dict) and session_index
        else ["session_index_missing"]
    )
    archived_bytes = int_value(
        (
            manifest.get("raw")
            if isinstance(manifest, dict)
            and isinstance(manifest.get("raw"), dict)
            else {}
        ).get("bytes"),
        -1,
    )
    if captured_bytes > archived_bytes:
        stable_reasons = unique_preserving_order(
            [*stable_reasons, "captured_tail_not_in_stable_projection"]
        )
    stable_current = not stable_reasons
    publish_id = projection_publish_id(
        manifest.get("index_schema")
        if isinstance(manifest, dict)
        and isinstance(manifest.get("index_schema"), dict)
        else {}
    )
    outbox_path, outbox_record = (
        session_projection_outbox_record_for_publish(
            aoa_root,
            session_id=session_id,
            publish_id=publish_id,
        )
    )
    downstream: dict[str, Any] = {}
    for consumer in PROJECTION_OUTBOX_CONSUMERS:
        state_path: Path | None = (
            projection_outbox_consumer_state_path(
                session_dir,
                consumer=consumer,
                record_id=str(outbox_record.get("record_id") or ""),
            )
            if outbox_record
            else None
        )
        state = read_json(state_path, {}) if state_path is not None else {}
        observed_status = str(state.get("status") or "unresolved")
        downstream[consumer] = {
            "status": observed_status,
            "current": observed_status == "complete",
            "semantic_completion": bool(
                state.get("semantic_completion")
            ),
            "source_publish_id": str(
                state.get("source_publish_id") or publish_id
            ),
            "record_id": str(outbox_record.get("record_id") or ""),
            "state_ref": str(state_path) if state_path is not None else "",
            "reason": str(state.get("reason") or ""),
        }
    returned = dict(returned_evidence or {})
    returned_status = str(returned.get("status") or "not_returned")
    if returned.get("persistent_overlay") and overlay_current:
        returned_status = "current"
    global_recall_complete = bool(
        stable_current
        and all(item["current"] for item in downstream.values())
    )
    return {
        "schema_version": 1,
        "artifact_type": "session_projection_freshness_vector",
        "generated_at": utc_now(),
        "session_id": session_id,
        "session_dir": str(session_dir),
        "source_publish_id": publish_id,
        "axes": {
            "raw_capture": {
                "status": "current" if capture_current else "stale",
                "current": capture_current,
                "captured_bytes": captured_bytes,
                "source_bytes": (
                    source_stat.st_size if source_stat is not None else -1
                ),
                "reasons": capture_reasons,
            },
            "live_overlay": {
                "status": "current" if overlay_current else "stale",
                "current": overlay_current,
                "captured_bytes": int_value(
                    overlay.get("captured_bytes"), -1
                ),
                "reasons": overlay_reasons,
            },
            "stable_session_projection": {
                "status": "current" if stable_current else "stale-readable",
                "current": stable_current,
                "archived_bytes": archived_bytes,
                "reasons": stable_reasons,
            },
            "search": downstream["exact_and_lexical_search"],
            "episode_semantic": downstream["episode_semantic"],
            "entity_registry": downstream["entity_registry"],
            "graph": downstream["graph"],
            "returned_evidence": {
                "status": returned_status,
                "current": returned_status == "current",
                "source": returned,
            },
            "global_recall": {
                "status": (
                    "complete" if global_recall_complete else "incomplete"
                ),
                "complete": global_recall_complete,
                "negative_claims_admitted": global_recall_complete,
            },
        },
        "outbox": {
            "record_ref": str(outbox_path) if outbox_path else "",
            "record_id": str(outbox_record.get("record_id") or ""),
            "status": str(outbox_record.get("status") or "unresolved"),
        },
        "truth_status": (
            "independent_freshness_axes_no_cross_axis_promotion"
        ),
    }


