def session_projection_artifact_receipt(path: Path) -> dict[str, Any]:
    return {
        "rel": str(path),
        "bytes": path.stat().st_size,
        "sha256": sha256_file(path),
    }


def session_projection_attested_artifact_receipt(
    path: Path, *, sha256: str
) -> dict[str, Any]:
    stat = path.stat()
    return {
        "rel": str(path),
        "bytes": stat.st_size,
        "sha256": sha256,
        "mtime_ns": stat.st_mtime_ns,
        "ctime_ns": stat.st_ctime_ns,
        "validation_mode": "attested_metadata_v1",
        "metadata_mode": "size_mtime_v1",
    }


def session_projection_artifact_receipt_current(
    receipt: Any,
) -> bool:
    if not isinstance(receipt, dict):
        return False
    path = Path(str(receipt.get("rel") or ""))
    if not path.is_file():
        return False
    stat = path.stat()
    if stat.st_size != int_value(receipt.get("bytes"), -1):
        return False
    if receipt.get("validation_mode") == "attested_metadata_v1":
        return bool(
            receipt.get("sha256")
            and stat.st_mtime_ns
            == int_value(receipt.get("mtime_ns"), -1)
            and (
                receipt.get("metadata_mode") == "size_mtime_v1"
                or stat.st_ctime_ns
                == int_value(receipt.get("ctime_ns"), -1)
            )
        )
    return sha256_file(path) == str(receipt.get("sha256") or "")


def session_projection_segment_checkpoint_current(
    item: Any,
) -> bool:
    if not isinstance(item, dict):
        return False
    artifacts = (
        item.get("artifacts")
        if isinstance(item.get("artifacts"), list)
        else []
    )
    return len(artifacts) == 2 and all(
        session_projection_artifact_receipt_current(artifact)
        for artifact in artifacts
    )


def remove_projection_publish_path(path: Path) -> None:
    if path.is_dir() and not path.is_symlink():
        shutil.rmtree(path)
    elif path.exists() or path.is_symlink():
        path.unlink()


def publish_session_projection_replace(
    source: Path,
    target: Path,
) -> None:
    source.replace(target)


def recover_interrupted_session_projection_publish(
    session_dir: Path,
) -> dict[str, Any]:
    journal_path = session_projection_publish_journal_path(
        session_dir
    )
    journal = read_json(journal_path, {})
    if not isinstance(journal, dict) or not journal:
        return {"status": "no_journal", "recovered": False}
    stage_dir = Path(str(journal.get("stage_dir") or ""))
    backup_root = Path(str(journal.get("backup_root") or ""))
    if journal.get("status") == "published":
        if stage_dir.name.startswith(
            f".{session_dir.name}.projection-stage-"
        ) or stage_dir.name.startswith(
            f".{session_dir.name}.projection-work-"
        ):
            remove_projection_publish_path(stage_dir)
        if backup_root.name.startswith(
            f".{session_dir.name}.projection-backup-"
        ):
            remove_projection_publish_path(backup_root)
        journal_path.unlink(missing_ok=True)
        return {
            "status": "finalized_committed_publish",
            "recovered": True,
            "restored": [],
            "removed_new": [],
            "outbox_record": journal.get("outbox_record", {}),
        }
    operations = (
        journal.get("operations")
        if isinstance(journal.get("operations"), list)
        else []
    )
    restored: list[str] = []
    removed_new: list[str] = []
    for operation in reversed(operations):
        if not isinstance(operation, dict):
            continue
        final_path = Path(str(operation.get("final") or ""))
        backup_path = Path(str(operation.get("backup") or ""))
        published = bool(operation.get("published"))
        had_original = bool(operation.get("had_original"))
        if backup_path.exists() or backup_path.is_symlink():
            remove_projection_publish_path(final_path)
            final_path.parent.mkdir(parents=True, exist_ok=True)
            publish_session_projection_replace(
                backup_path,
                final_path,
            )
            restored.append(str(final_path))
        elif published and not had_original:
            remove_projection_publish_path(final_path)
            removed_new.append(str(final_path))
    outbox_record = (
        journal.get("outbox_record")
        if isinstance(journal.get("outbox_record"), dict)
        else {}
    )
    outbox_path = Path(str(outbox_record.get("path") or ""))
    if (
        outbox_path.name
        and bool(outbox_record.get("written"))
        and not bool(outbox_record.get("preexisting"))
    ):
        outbox_path.unlink(missing_ok=True)
    if stage_dir.name.startswith(
        f".{session_dir.name}.projection-stage-"
    ):
        remove_projection_publish_path(stage_dir)
    if backup_root.name.startswith(
        f".{session_dir.name}.projection-backup-"
    ):
        remove_projection_publish_path(backup_root)
    journal_path.unlink(missing_ok=True)
    return {
        "status": "rolled_back_interrupted_publish",
        "recovered": True,
        "restored": restored,
        "removed_new": removed_new,
        "removed_outbox_record": (
            str(outbox_path) if outbox_path.name else ""
        ),
    }


SESSION_PROJECTION_SEMANTIC_DIGEST_VERSION = 2
SESSION_PROJECTION_SEMANTIC_DIGEST_VOLATILE_KEYS = (
    PROJECTION_SEMANTIC_VOLATILE_KEYS
)
PROJECTION_SEMANTIC_JSON_FINGERPRINT_MODE = (
    "canonical_json_without_projection_clocks_and_local_root_v1"
)
PROJECTION_SEMANTIC_MARKDOWN_FINGERPRINT_MODE = (
    "markdown_without_frontmatter_projection_clocks_and_local_root_v1"
)
PROJECTION_SEMANTIC_RAW_FINGERPRINT_MODE = "raw_file_sha256_v1"


def projection_semantic_digest_value(
    value: Any,
    *,
    volatile_keys: frozenset[str],
    logical_root: Path | None = None,
) -> Any:
    """Normalize generated content while preserving evidence-bearing values."""
    if isinstance(value, dict):
        return {
            str(key): projection_semantic_digest_value(
                item,
                volatile_keys=volatile_keys,
                logical_root=logical_root,
            )
            for key, item in sorted(value.items())
            if str(key) not in volatile_keys
        }
    if isinstance(value, list):
        return [
            projection_semantic_digest_value(
                item,
                volatile_keys=volatile_keys,
                logical_root=logical_root,
            )
            for item in value
        ]
    if isinstance(value, str) and logical_root is not None:
        root_text = str(logical_root)
        if root_text:
            return value.replace(root_text, "{projection_root}")
    return value


def session_projection_semantic_digest_value(
    value: Any,
) -> Any:
    return projection_semantic_digest_value(
        value,
        volatile_keys=(
            SESSION_PROJECTION_SEMANTIC_DIGEST_VOLATILE_KEYS
        ),
    )


def projection_logical_path(
    path: Path,
    *,
    logical_root: Path,
    ordinal: int = 0,
) -> str:
    try:
        return path.relative_to(logical_root).as_posix()
    except ValueError:
        return f"external/{ordinal:04d}/{path.name}"


def projection_semantic_markdown_text(
    text: str,
    *,
    logical_root: Path,
) -> str:
    lines = text.splitlines(keepends=True)
    in_frontmatter = bool(lines and lines[0].strip() == "---")
    normalized: list[str] = []
    for index, line in enumerate(lines):
        stripped = line.strip()
        if index > 0 and in_frontmatter and stripped == "---":
            in_frontmatter = False
            normalized.append(line)
            continue
        if in_frontmatter and ":" in stripped:
            key = stripped.split(":", 1)[0].strip()
            if key in SESSION_PROJECTION_SEMANTIC_DIGEST_VOLATILE_KEYS:
                continue
        normalized.append(
            line.replace(str(logical_root), "{projection_root}")
        )
    return "".join(normalized)


def projection_semantic_file_fingerprint(
    path: Path,
    *,
    logical_root: Path,
) -> dict[str, Any]:
    if path.suffix.casefold() == ".json":
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            payload = None
        if payload is not None:
            comparable = projection_semantic_digest_value(
                payload,
                volatile_keys=(
                    SESSION_PROJECTION_SEMANTIC_DIGEST_VOLATILE_KEYS
                ),
                logical_root=logical_root,
            )
            return {
                "sha256": hashlib.sha256(
                    json.dumps(
                        comparable,
                        ensure_ascii=False,
                        sort_keys=True,
                        separators=(",", ":"),
                    ).encode("utf-8")
                ).hexdigest(),
                "mode": PROJECTION_SEMANTIC_JSON_FINGERPRINT_MODE,
            }
    if path.suffix.casefold() in {".md", ".markdown"}:
        try:
            text = path.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            text = ""
        else:
            comparable_text = projection_semantic_markdown_text(
                text,
                logical_root=logical_root,
            )
            return {
                "sha256": hashlib.sha256(
                    comparable_text.encode("utf-8")
                ).hexdigest(),
                "mode": PROJECTION_SEMANTIC_MARKDOWN_FINGERPRINT_MODE,
            }
    return {
        "sha256": sha256_file(path),
        "mode": PROJECTION_SEMANTIC_RAW_FINGERPRINT_MODE,
    }


def projection_semantic_json_hash_update(
    digest: Any,
    value: Any,
    *,
    volatile_keys: frozenset[str],
    logical_root: Path | None = None,
) -> None:
    """Feed canonical semantic JSON into a digest without bulk materialization."""
    if isinstance(value, dict):
        digest.update(b"{")
        first = True
        items = sorted(
            (
                (str(key), item)
                for key, item in value.items()
                if str(key) not in volatile_keys
            ),
            key=lambda pair: pair[0],
        )
        for key, item in items:
            if not first:
                digest.update(b",")
            first = False
            digest.update(
                json.dumps(
                    key,
                    ensure_ascii=False,
                    separators=(",", ":"),
                ).encode("utf-8")
            )
            digest.update(b":")
            projection_semantic_json_hash_update(
                digest,
                item,
                volatile_keys=volatile_keys,
                logical_root=logical_root,
            )
        digest.update(b"}")
        return
    if isinstance(value, (list, tuple)):
        digest.update(b"[")
        for index, item in enumerate(value):
            if index:
                digest.update(b",")
            projection_semantic_json_hash_update(
                digest,
                item,
                volatile_keys=volatile_keys,
                logical_root=logical_root,
            )
        digest.update(b"]")
        return
    if isinstance(value, str) and logical_root is not None:
        root_text = str(logical_root)
        if root_text:
            value = value.replace(root_text, "{projection_root}")
    digest.update(
        json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    )


def session_projection_json_semantic_sha256(value: Any) -> str:
    digest = hashlib.sha256()
    projection_semantic_json_hash_update(
        digest,
        value,
        volatile_keys=(
            SESSION_PROJECTION_SEMANTIC_DIGEST_VOLATILE_KEYS
        ),
    )
    return digest.hexdigest()


def session_projection_semantic_digest(
    projection_dir: Path,
) -> dict[str, Any]:
    manifest = read_json(
        projection_dir / "session.manifest.json", {}
    )
    component_digests = {
        "manifest": session_projection_json_semantic_sha256(
            manifest
        ),
        "raw_block_index": session_projection_json_semantic_sha256(
            read_json(
                projection_dir / "raw" / RAW_BLOCK_INDEX_JSON,
                {},
            )
        ),
        "raw_capture_state": session_projection_json_semantic_sha256(
            read_json(
                projection_dir / "raw" / RAW_CAPTURE_STATE_JSON,
                {},
            )
        ),
        "raw_source": session_projection_json_semantic_sha256(
            read_json(
                projection_dir / "raw" / RAW_SOURCE_JSON,
                {},
            )
        ),
        "session_index": session_projection_json_semantic_sha256(
            read_json(
                projection_dir / SESSION_INDEX_JSON,
                {},
            )
        ),
    }
    segment_index_count = 0
    segment_markdown_count = 0
    metadata_admitted_index_count = 0
    metadata_admitted_markdown_count = 0
    content_read_index_count = 0
    content_read_markdown_count = 0
    segments = (
        manifest.get("segments")
        if isinstance(manifest, dict)
        and isinstance(manifest.get("segments"), list)
        else []
    )
    if not any(isinstance(segment, dict) for segment in segments):
        segments_dir = projection_dir / "segments"
        index_paths = (
            sorted(segments_dir.glob("*.index.json"))
            if segments_dir.is_dir()
            else []
        )
        markdown_by_stem = {
            path.name.removesuffix(".md"): path
            for path in (
                sorted(segments_dir.glob("*.md"))
                if segments_dir.is_dir()
                else []
            )
        }
        segments = [
            {
                "index": str(index_path),
                "markdown": str(
                    markdown_by_stem.get(
                        index_path.name.removesuffix(".index.json"),
                        segments_dir
                        / (
                            index_path.name.removesuffix(".index.json")
                            + ".md"
                        ),
                    )
                ),
                "artifact_receipts": {},
            }
            for index_path in index_paths
        ]
    for segment in segments:
        if not isinstance(segment, dict):
            continue
        receipts = (
            segment.get("artifact_receipts")
            if isinstance(segment.get("artifact_receipts"), dict)
            else {}
        )
        index_path = projection_path_from_ref(
            segment.get("index"), base=projection_dir
        )
        if index_path.parent != projection_dir / "segments":
            index_path = (
                projection_dir / "segments" / index_path.name
            )
        markdown_path = projection_path_from_ref(
            segment.get("markdown"), base=projection_dir
        )
        if markdown_path.parent != projection_dir / "segments":
            markdown_path = (
                projection_dir / "segments" / markdown_path.name
            )
        index_receipt = (
            receipts.get("index")
            if isinstance(receipts.get("index"), dict)
            else {}
        )
        markdown_receipt = (
            receipts.get("markdown")
            if isinstance(receipts.get("markdown"), dict)
            else {}
        )
        semantic_index_sha256 = str(
            index_receipt.get("semantic_sha256") or ""
        )
        if (
            len(semantic_index_sha256) == 64
            and index_receipt.get("semantic_mode")
            == "canonical_json_without_projection_clocks_v1"
            and immutable_component_artifact_receipt_metadata_current(
                index_path, index_receipt
            )
        ):
            metadata_admitted_index_count += 1
        else:
            semantic_index_sha256 = (
                session_projection_json_semantic_sha256(
                    read_json(index_path, {})
                )
            )
            content_read_index_count += 1
        component_digests[
            f"segment_index:{index_path.name}"
        ] = semantic_index_sha256
        segment_index_count += 1
        markdown_sha256 = str(markdown_receipt.get("sha256") or "")
        if (
            len(markdown_sha256) == 64
            and immutable_component_artifact_receipt_metadata_current(
                markdown_path, markdown_receipt
            )
        ):
            metadata_admitted_markdown_count += 1
        else:
            markdown_sha256 = sha256_file(markdown_path)
            content_read_markdown_count += 1
        component_digests[
            f"segment_markdown:{markdown_path.name}"
        ] = markdown_sha256
        segment_markdown_count += 1
    root_payload = {
        "schema_version": SESSION_PROJECTION_SEMANTIC_DIGEST_VERSION,
        "mode": "merkle_component_semantic_roots_v1",
        "components": {
            key: component_digests[key]
            for key in sorted(component_digests)
        },
    }
    root_sha256 = hashlib.sha256(
        json.dumps(
            root_payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return {
        "version": SESSION_PROJECTION_SEMANTIC_DIGEST_VERSION,
        "sha256": root_sha256,
        "mode": "merkle_component_semantic_roots_v1",
        "component_count": len(component_digests),
        "segment_index_count": segment_index_count,
        "segment_markdown_count": segment_markdown_count,
        "metadata_admitted_index_count": (
            metadata_admitted_index_count
        ),
        "metadata_admitted_markdown_count": (
            metadata_admitted_markdown_count
        ),
        "content_read_index_count": content_read_index_count,
        "content_read_markdown_count": content_read_markdown_count,
        "excluded_keys": sorted(
            SESSION_PROJECTION_SEMANTIC_DIGEST_VOLATILE_KEYS
        ),
        "truth_status": (
            "semantic_component_root_not_filesystem_layout_digest"
        ),
    }


def staged_session_index_shard_diagnostics(
    *,
    stage_dir: Path,
    session_index: dict[str, Any],
    expected_publish_id: str,
    validation_metrics_out: dict[str, Any] | None = None,
) -> list[str]:
    storage = (
        session_index.get("component_storage")
        if isinstance(
            session_index.get("component_storage"), dict
        )
        else {}
    )
    if not storage:
        return []
    diagnostics: list[str] = []
    expected_manifest_ref = str(
        Path(SESSION_INDEX_SHARDS_DIR)
        / SESSION_INDEX_SHARD_MANIFEST_JSON
    )
    if str(storage.get("manifest_ref") or "") != (
        expected_manifest_ref
    ):
        return ["session_index_shard_manifest_ref_invalid"]
    manifest_path = stage_dir / expected_manifest_ref
    manifest = read_json(manifest_path, {})
    if (
        int_value(manifest.get("schema_version"))
        != SESSION_INDEX_SHARD_SCHEMA_VERSION
        or manifest.get("artifact_type")
        != "session_index_shard_manifest"
    ):
        return ["session_index_shard_manifest_invalid"]
    if projection_publish_id(
        manifest.get("projection_publish")
        if isinstance(manifest.get("projection_publish"), dict)
        else {}
    ) != expected_publish_id:
        diagnostics.append(
            "session_index_shard_manifest_publish_id_mismatch"
        )
    components = (
        manifest.get("components")
        if isinstance(manifest.get("components"), dict)
        else {}
    )
    records = (
        components.get("task_episodes")
        if isinstance(components.get("task_episodes"), list)
        else []
    )
    if int_value(storage.get("task_episode_shard_count"), -1) != len(
        records
    ):
        diagnostics.append(
            "session_index_component_storage_count_mismatch"
        )
    if storage.get("embedded_compatibility_view") is not False:
        diagnostics.append(
            "session_index_component_storage_not_manifest_first"
        )
    metadata_receipt_admitted_count = 0
    full_content_validation_count = 0
    for ordinal, record in enumerate(records):
        if not isinstance(record, dict):
            diagnostics.append(
                f"session_index_task_episode_shard_record_invalid:{ordinal}"
            )
            continue
        ref = str(record.get("ref") or "")
        relative = Path(ref)
        expected_parent = (
            Path(SESSION_INDEX_SHARDS_DIR)
            / SESSION_INDEX_TASK_EPISODE_SHARDS_DIR
        )
        if (
            relative.is_absolute()
            or ".." in relative.parts
            or relative.parent != expected_parent
            or relative.suffix != ".json"
        ):
            diagnostics.append(
                f"session_index_task_episode_shard_ref_invalid:{ordinal}"
            )
            continue
        shard_path = stage_dir / relative
        artifact_sha256 = str(
            record.get("artifact_sha256") or ""
        )
        artifact_receipt = (
            record.get("artifact_receipt")
            if isinstance(record.get("artifact_receipt"), dict)
            else {}
        )
        metadata_receipt_admitted = bool(
            artifact_sha256
            and str(artifact_receipt.get("sha256") or "")
            == artifact_sha256
            and shard_path.stem == artifact_sha256
            and immutable_component_artifact_receipt_metadata_current(
                shard_path,
                artifact_receipt,
            )
        )
        if (
            not shard_path.is_file()
            or artifact_sha256 != shard_path.stem
            or (
                not metadata_receipt_admitted
                and sha256_file(shard_path) != artifact_sha256
            )
        ):
            diagnostics.append(
                f"session_index_task_episode_shard_artifact_mismatch:{ordinal}"
            )
            continue
        if metadata_receipt_admitted:
            metadata_receipt_admitted_count += 1
            if (
                not str(record.get("component_key") or "")
                or not isinstance(record.get("source_identity"), dict)
                or not str(record.get("payload_sha256") or "")
            ):
                diagnostics.append(
                    f"session_index_task_episode_shard_record_invalid:{ordinal}"
                )
            continue
        full_content_validation_count += 1
        envelope = read_json(shard_path, {})
        payload = (
            envelope.get("payload")
            if isinstance(envelope.get("payload"), dict)
            else {}
        )
        expected_key = session_index_task_episode_shard_key(
            payload,
            ordinal,
        )
        if str(record.get("component_key") or "") != expected_key:
            diagnostics.append(
                f"session_index_task_episode_shard_key_mismatch:{ordinal}"
            )
        payload_sha256 = session_index_shard_payload_sha256(
            payload
        )
        if (
            int_value(envelope.get("schema_version"))
            != SESSION_INDEX_SHARD_SCHEMA_VERSION
            or envelope.get("artifact_type")
            != "session_index_component_shard"
            or envelope.get("component") != "task_episodes"
            or envelope.get("source_identity")
            != record.get("source_identity")
            or str(envelope.get("component_key") or "")
            != expected_key
            or str(envelope.get("payload_sha256") or "")
            != payload_sha256
            or str(record.get("payload_sha256") or "")
            != payload_sha256
            or session_index_shard_payload_sha256(payload)
            != payload_sha256
        ):
            diagnostics.append(
                f"session_index_task_episode_shard_payload_mismatch:{ordinal}"
            )
    if validation_metrics_out is not None:
        validation_metrics_out.update(
            {
                "metadata_receipt_admitted_count": (
                    metadata_receipt_admitted_count
                ),
                "full_content_validation_count": (
                    full_content_validation_count
                ),
                "policy": (
                    "metadata_receipt_else_full_content_validation_v1"
                ),
            }
        )
    return diagnostics


def validate_staged_session_projection(
    *,
    stage_dir: Path,
    session_dir: Path,
    publish_identity: dict[str, Any],
) -> dict[str, Any]:
    expected_publish_id = projection_publish_id(
        publish_identity
    )
    expected_raw_sha256 = str(
        (
            publish_identity.get("source")
            if isinstance(publish_identity.get("source"), dict)
            else {}
        ).get("raw_sha256")
        or ""
    )
    expected_raw_bytes = int_value(
        (
            publish_identity.get("source")
            if isinstance(publish_identity.get("source"), dict)
            else {}
        ).get("raw_bytes")
    )
    diagnostics: list[str] = []
    session_index_shard_validation: dict[str, Any] = {}
    raw_validation_mode = "published_last_good_raw_v1"
    staged_raw_path = (
        stage_dir / "raw" / "session.raw.jsonl"
    )
    if staged_raw_path.is_file():
        if staged_raw_snapshot_receipt_current(
            stage_dir=stage_dir,
            staged_raw_path=staged_raw_path,
            expected_raw_sha256=expected_raw_sha256,
            expected_raw_bytes=expected_raw_bytes,
        ):
            raw_validation_mode = (
                "current_ficlone_snapshot_receipt_v1"
            )
        else:
            raw_validation_mode = "full_sha256_v1"
            staged_raw_sha256 = sha256_file_exact(staged_raw_path)
            if staged_raw_sha256 != expected_raw_sha256:
                diagnostics.append("staged_raw_sha256_mismatch")
    elif expected_raw_sha256 and not (
        session_dir / "raw" / "session.raw.jsonl"
    ).is_file():
        diagnostics.append("staged_and_published_raw_missing")
    staged_manifest = read_json(
        stage_dir / "session.manifest.json",
        {},
    )
    staged_session_index = read_json(
        stage_dir / SESSION_INDEX_JSON,
        {},
    )
    if projection_publish_id(
        (
            staged_manifest.get("index_schema")
            if isinstance(staged_manifest, dict)
            else {}
        )
    ) != expected_publish_id:
        diagnostics.append("manifest_publish_id_mismatch")
    if isinstance(staged_session_index, dict):
        diagnostics.extend(
            generated_session_index_stale_reasons(
                staged_session_index,
                expected_publish_id=expected_publish_id,
                expected_raw_sha256=expected_raw_sha256,
            )
        )
        diagnostics.extend(
            generated_session_metadata_stale_reasons(
                staged_session_index,
                staged_manifest
                if isinstance(staged_manifest, dict)
                else {},
            )
        )
        diagnostics.extend(
            staged_session_index_shard_diagnostics(
                stage_dir=stage_dir,
                session_index=staged_session_index,
                expected_publish_id=expected_publish_id,
                validation_metrics_out=(
                    session_index_shard_validation
                ),
            )
        )
    else:
        diagnostics.append("staged_session_index_missing")
    segments = (
        staged_manifest.get("segments")
        if isinstance(staged_manifest, dict)
        and isinstance(staged_manifest.get("segments"), list)
        else []
    )
    for segment in segments:
        if not isinstance(segment, dict):
            diagnostics.append("staged_segment_manifest_invalid")
            continue
        final_index_path = projection_path_from_ref(
            segment.get("index"),
            base=session_dir,
        )
        staged_index_path = (
            stage_dir
            / "segments"
            / final_index_path.name
        )
        staged_markdown_path = (
            stage_dir
            / "segments"
            / Path(str(segment.get("markdown") or "")).name
        )
        component_identity = (
            segment.get("component_identity")
            if isinstance(segment.get("component_identity"), dict)
            else {}
        )
        artifact_receipts = (
            segment.get("artifact_receipts")
            if isinstance(segment.get("artifact_receipts"), dict)
            else {}
        )
        expected_component_identity = segment_component_identity(
            segment_id=str(segment.get("segment_id") or ""),
            role=str(segment.get("role") or ""),
            source_range=(
                segment.get("source_range")
                if isinstance(segment.get("source_range"), dict)
                else {}
            ),
            input_digest=str(segment.get("input_digest") or ""),
            raw_block=(
                segment.get("raw_block")
                if isinstance(segment.get("raw_block"), dict)
                else None
            ),
        )
        immutable_component_admitted = bool(
            component_identity == expected_component_identity
            and immutable_component_artifact_receipt_metadata_current(
                staged_index_path, artifact_receipts.get("index")
            )
            and immutable_component_artifact_receipt_metadata_current(
                staged_markdown_path,
                artifact_receipts.get("markdown"),
            )
        )
        if immutable_component_admitted:
            continue
        staged_segment_index = read_json(
            staged_index_path,
            {},
        )
        if not isinstance(staged_segment_index, dict):
            diagnostics.append(
                f"staged_segment_index_missing:{final_index_path.name}"
            )
            continue
        diagnostics.extend(
            f"{final_index_path.name}:{reason}"
            for reason in generated_segment_index_stale_reasons(
                staged_segment_index,
                expected_publish_id=expected_publish_id,
                expected_raw_sha256=expected_raw_sha256,
            )
        )
        if not staged_markdown_path.is_file():
            diagnostics.append(
                f"staged_segment_markdown_missing:{segment.get('segment_id')}"
            )
    raw_block_index = read_json(
        stage_dir / "raw" / RAW_BLOCK_INDEX_JSON,
        {},
    )
    published_manifest = read_json(
        session_dir / "session.manifest.json", {}
    )
    published_raw_blocks = {
        str(item.get("block_id") or ""): item
        for item in (
            published_manifest.get("raw_blocks", {}).get("blocks", [])
            if isinstance(published_manifest.get("raw_blocks"), dict)
            and isinstance(
                published_manifest.get("raw_blocks", {}).get("blocks"),
                list,
            )
            else []
        )
        if isinstance(item, dict) and str(item.get("block_id") or "")
    }
    raw_block_metadata_admitted_count = 0
    raw_block_reused_last_good_count = 0
    raw_block_full_sha256_count = 0
    if projection_publish_id(raw_block_index) != expected_publish_id:
        diagnostics.append("raw_block_index_publish_id_mismatch")
    for block in (
        raw_block_index.get("blocks")
        if isinstance(raw_block_index, dict)
        and isinstance(raw_block_index.get("blocks"), list)
        else []
    ):
        if not isinstance(block, dict):
            diagnostics.append("raw_block_record_invalid")
            continue
        staged_plain_path = (
            stage_dir / "raw" / RAW_BLOCKS_DIR
            / Path(
                str(
                    block.get("plain_path")
                    or block.get("path")
                    or ""
                )
            ).name
        )
        staged_compressed_path = (
            stage_dir / "raw" / RAW_BLOCKS_DIR
            / Path(
                str(block.get("compressed_path") or "")
            ).name
        )
        block_id = block.get("block_id")
        expected_uncompressed_sha256 = str(
            block.get("uncompressed_sha256")
            or block.get("sha256")
            or ""
        )
        storage_mode = str(
            block.get("storage_mode")
            or RAW_BLOCK_STORAGE_MODE_PLAIN
        )
        plain_removed = bool(block.get("plain_removed"))
        published_block = published_raw_blocks.get(str(block_id), {})
        published_plain_path = Path(
            str(
                published_block.get("plain_path")
                or published_block.get("path")
                or ""
            )
        )
        reused_last_good_plain = bool(
            isinstance(published_block, dict)
            and str(block.get("status") or "") == "sealed"
            and str(published_block.get("sha256") or "")
            == expected_uncompressed_sha256
            and published_block.get("source_range")
            == block.get("source_range")
            and staged_plain_path.is_file()
            and published_plain_path.is_file()
            and os.path.samefile(staged_plain_path, published_plain_path)
        )
        block_artifact_receipts = (
            block.get("artifact_receipts")
            if isinstance(block.get("artifact_receipts"), dict)
            else {}
        )
        plain_artifact_receipt = (
            block_artifact_receipts.get("plain")
            if isinstance(block_artifact_receipts.get("plain"), dict)
            else {}
        )
        metadata_receipt_admitted = bool(
            str(
                plain_artifact_receipt.get("sha256")
                or ""
            )
            == expected_uncompressed_sha256
            and immutable_component_artifact_receipt_metadata_current(
                staged_plain_path,
                plain_artifact_receipt,
            )
        )
        if not plain_removed:
            if not staged_plain_path.is_file():
                diagnostics.append(
                    f"staged_raw_block_missing:{block_id}"
                )
            elif reused_last_good_plain:
                raw_block_reused_last_good_count += 1
            elif metadata_receipt_admitted:
                raw_block_metadata_admitted_count += 1
            else:
                raw_block_full_sha256_count += 1
                if expected_uncompressed_sha256 != sha256_file_exact(
                    staged_plain_path
                ):
                    diagnostics.append(
                        f"staged_raw_block_digest_mismatch:{block_id}"
                    )
        if storage_mode == RAW_BLOCK_STORAGE_MODE_GZIP:
            if not staged_compressed_path.is_file():
                diagnostics.append(
                    f"staged_compressed_raw_block_missing:{block_id}"
                )
            else:
                expected_compressed_sha256 = str(
                    block.get("compressed_sha256") or ""
                )
                if (
                    not expected_compressed_sha256
                    or expected_compressed_sha256
                    != sha256_file_exact(staged_compressed_path)
                ):
                    diagnostics.append(
                        "staged_compressed_raw_block_digest_mismatch:"
                        f"{block_id}"
                    )
                try:
                    uncompressed_sha256 = hashlib.sha256(
                        gzip.decompress(
                            staged_compressed_path.read_bytes()
                        )
                    ).hexdigest()
                except (OSError, EOFError):
                    diagnostics.append(
                        "staged_compressed_raw_block_unreadable:"
                        f"{block_id}"
                    )
                else:
                    if (
                        expected_uncompressed_sha256
                        != uncompressed_sha256
                    ):
                        diagnostics.append(
                            "staged_compressed_raw_block_payload_mismatch:"
                            f"{block_id}"
                        )
    classification_cache_root = (
        event_classification_cache_root(stage_dir)
    )
    classification_cache_index = read_json(
        event_classification_cache_index_path(
            classification_cache_root
        ),
        {},
    )
    expected_classification_generation = (
        event_classification_generation_identity()
    )
    if classification_cache_root.exists() and (
        not isinstance(classification_cache_index, dict)
        or classification_cache_index.get(
            "generation_identity"
        )
        != expected_classification_generation
    ):
        diagnostics.append("classification_cache_generation_mismatch")
    elif classification_cache_root.exists():
        classification_records = (
            classification_cache_index.get("blocks")
            if isinstance(
                classification_cache_index.get("blocks"), dict
            )
            else {}
        )
        classification_records_root_current = bool(
            str(
                classification_cache_index.get(
                    "records_root_sha256"
                )
                or ""
            )
            == event_classification_cache_records_root_sha256(
                {
                    str(key): dict(value)
                    for key, value in classification_records.items()
                    if isinstance(value, dict)
                }
            )
        )
        for cache_key, classification_record in (
            classification_records.items()
        ):
            block = (
                classification_record.get("block")
                if isinstance(classification_record, dict)
                else {}
            )
            metadata_reuse_admitted = bool(
                classification_records_root_current
                and isinstance(classification_record, dict)
                and classification_record.get("validation_mode")
                == "attested_published_artifact_metadata_reuse_v1"
            )
            if not event_classification_cache_record_current(
                cache_root=classification_cache_root,
                record=classification_record,
                block=block,
                verify_content=not metadata_reuse_admitted,
            ):
                diagnostics.append(
                    "classification_cache_artifact_invalid:"
                    f"{cache_key}"
                )
                continue
            if metadata_reuse_admitted:
                continue
            cached_payload = read_gzip_json(
                classification_cache_root
                / str(classification_record.get("artifact") or "")
            )
            if (
                cached_payload.get("generation_identity")
                != expected_classification_generation
                or cached_payload.get("block") != block
            ):
                diagnostics.append(
                    "classification_cache_payload_invalid:"
                    f"{cache_key}"
                )
    raw_capture_state = read_json(
        stage_dir / "raw" / RAW_CAPTURE_STATE_JSON,
        {},
    )
    if (
        not isinstance(raw_capture_state, dict)
        or int_value(raw_capture_state.get("schema_version"))
        != RAW_CAPTURE_STATE_SCHEMA_VERSION
    ):
        diagnostics.append(
            "staged_raw_capture_state_schema_mismatch"
        )
    else:
        if (
            str(raw_capture_state.get("status") or "")
            != "indexed_with_projection"
        ):
            diagnostics.append(
                "staged_raw_capture_state_not_indexed"
            )
        if (
            str(raw_capture_state.get("raw_sha256") or "")
            != expected_raw_sha256
        ):
            diagnostics.append(
                "staged_raw_capture_state_digest_mismatch"
            )
        if (
            str(
                raw_capture_state.get(
                    "projection_publish_id"
                )
                or ""
            )
            != expected_publish_id
        ):
            diagnostics.append(
                "staged_raw_capture_state_publish_id_mismatch"
            )
    staged_distillation_dir = (
        stage_dir / "distillation"
    )
    if staged_distillation_dir.is_dir():
        staged_distillation = read_json(
            staged_distillation_dir
            / "distillation.index.json",
            {},
        )
        if not isinstance(staged_distillation, dict):
            diagnostics.append(
                "staged_first_pass_distillation_missing"
            )
        else:
            diagnostics.extend(
                first_pass_distillation_stale_reasons(
                    aoa_root=session_dir.parents[1],
                    projection_dir=stage_dir,
                    session_dir=session_dir,
                    manifest=(
                        staged_manifest
                        if isinstance(
                            staged_manifest,
                            dict,
                        )
                        else {}
                    ),
                    payload=staged_distillation,
                )
            )
        if not (
            staged_distillation_dir
            / "001__first-pass__experience-map.md"
        ).is_file():
            diagnostics.append(
                "staged_first_pass_distillation_markdown_missing"
            )
    migration_receipts = (
        staged_manifest.get("generation_migration_receipts")
        if isinstance(staged_manifest, dict)
        and isinstance(
            staged_manifest.get("generation_migration_receipts"), list
        )
        else []
    )
    for migration_receipt in migration_receipts:
        if not isinstance(migration_receipt, dict):
            diagnostics.append("generation_migration_receipt_invalid")
            continue
        if str(migration_receipt.get("publish_id") or "") != (
            expected_publish_id
        ):
            continue
        receipt_payload = {
            key: value
            for key, value in migration_receipt.items()
            if key not in {"receipt_id", "recorded_at"}
        }
        expected_receipt_id = hashlib.sha256(
            json.dumps(
                receipt_payload,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        transitions = (
            migration_receipt.get("transitions")
            if isinstance(
                migration_receipt.get("transitions"), list
            )
            else []
        )
        transition_count = sum(
            int_value(item.get("artifact_count"))
            for item in transitions
            if isinstance(item, dict)
        )
        if (
            str(migration_receipt.get("receipt_id") or "")
            != expected_receipt_id
            or migration_receipt.get("source")
            != publish_identity.get("source")
            or transition_count <= 0
            or transition_count
            != int_value(migration_receipt.get("artifact_count"))
            or migration_receipt.get("raw_authority_changed") is not False
            or migration_receipt.get("unknown_generation_admission")
            is not False
        ):
            diagnostics.append(
                "generation_migration_receipt_payload_mismatch"
            )
            continue
        for transition in transitions:
            if not isinstance(transition, dict):
                diagnostics.append(
                    "generation_migration_transition_invalid"
                )
                continue
            projection = str(transition.get("projection") or "")
            current_generation_ids = {
                "raw_event_classification_cache": str(
                    event_classification_generation_identity().get(
                        "generation_id"
                    )
                    or ""
                ),
                "segment_index": str(
                    segment_index_generation_identity().get(
                        "generation_id"
                    )
                    or ""
                ),
                "task_episode_source": str(
                    task_episode_source_generation_identity().get(
                        "generation_id"
                    )
                    or ""
                ),
            }
            if sorted(
                str(item)
                for item in transition.get(
                    "from_generation_ids", []
                )
            ) != sorted(
                DECLARED_PROJECTION_PREDECESSOR_GENERATION_IDS.get(
                    projection, frozenset()
                )
            ):
                diagnostics.append(
                    "generation_migration_predecessor_allowlist_mismatch:"
                    f"{projection}"
                )
            if (
                transition.get("admission")
                != "exact_declared_predecessor_reuse_then_restamp_v1"
                or str(transition.get("to_generation_id") or "")
                != current_generation_ids.get(projection, "")
            ):
                diagnostics.append(
                    "generation_migration_transition_target_mismatch:"
                    f"{projection}"
                )
    producer_source_state = (
        session_memory_loaded_producer_source_state()
    )
    if not producer_source_state.get("stable"):
        diagnostics.append(
            "producer_source_changed_during_process"
        )
    return {
        "ok": not diagnostics,
        "publish_id": expected_publish_id,
        "segment_count": len(segments),
        "raw_block_count": len(
            raw_block_index.get("blocks", [])
            if isinstance(raw_block_index, dict)
            and isinstance(raw_block_index.get("blocks"), list)
            else []
        ),
        "diagnostics": diagnostics,
        "raw_validation_mode": raw_validation_mode,
        "raw_block_validation": {
            "metadata_receipt_admitted_count": (
                raw_block_metadata_admitted_count
            ),
            "reused_last_good_count": (
                raw_block_reused_last_good_count
            ),
            "full_sha256_count": raw_block_full_sha256_count,
            "policy": (
                "metadata_receipt_or_samefile_reuse_else_full_sha256_v1"
            ),
        },
        "session_index_shard_validation": (
            session_index_shard_validation
        ),
        "producer_source_state": producer_source_state,
        "semantic_digest": (
            session_projection_semantic_digest(stage_dir)
        ),
    }


def stage_projection_path_with_links(
    *,
    source: Path,
    target: Path,
) -> None:
    if source.is_dir() and not source.is_symlink():
        target.mkdir(parents=True, exist_ok=True)
        for child in sorted(source.iterdir()):
            stage_projection_path_with_links(
                source=child,
                target=target / child.name,
            )
        return
    target.parent.mkdir(parents=True, exist_ok=True)
    try:
        os.link(source, target)
    except OSError:
        shutil.copy2(source, target)


def stage_raw_snapshot(
    *,
    source: Path,
    target: Path,
    expected_sha256: str,
) -> dict[str, Any]:
    """Create an immutable-for-this-build CoW snapshot when supported."""
    target.parent.mkdir(parents=True, exist_ok=True)
    target.unlink(missing_ok=True)
    source_before = file_snapshot(source)
    mode = "copy2_fallback"
    error = ""
    try:
        # Linux FICLONE. The portable fallback remains exact but is reported
        # as full-source I/O rather than being mistaken for delta work.
        with source.open("rb") as source_handle, target.open(
            "wb"
        ) as target_handle:
            fcntl.ioctl(
                target_handle.fileno(),
                0x40049409,
                source_handle.fileno(),
            )
        shutil.copystat(source, target)
        mode = "ficlone_snapshot_v1"
    except OSError as exc:
        error = f"{exc.__class__.__name__}:{exc}"
        target.unlink(missing_ok=True)
        shutil.copy2(source, target)
    source_after = file_snapshot(source)
    target_snapshot = file_snapshot(target)
    if source_before != source_after:
        target.unlink(missing_ok=True)
        raise ValueError("raw_snapshot_source_changed_during_clone")
    if target_snapshot["size"] != source_before["size"]:
        target.unlink(missing_ok=True)
        raise ValueError("raw_snapshot_size_mismatch")
    return {
        "schema_version": 1,
        "artifact_type": "session_projection_raw_snapshot_receipt",
        "mode": mode,
        "source_snapshot": source_before,
        "target_snapshot": target_snapshot,
        "expected_sha256": expected_sha256,
        "source_bytes_read": (
            0 if mode == "ficlone_snapshot_v1" else source_before["size"]
        ),
        "target_bytes_written": (
            0 if mode == "ficlone_snapshot_v1" else target_snapshot["size"]
        ),
        "fallback_error": error,
        "truth_status": (
            "kernel_cow_snapshot_bound_by_source_and_target_stat"
            if mode == "ficlone_snapshot_v1"
            else "portable_full_copy_requires_full_digest_validation"
        ),
    }


def staged_raw_snapshot_receipt_current(
    *,
    stage_dir: Path,
    staged_raw_path: Path,
    expected_raw_sha256: str,
    expected_raw_bytes: int,
) -> bool:
    checkpoint = read_json(
        session_projection_work_checkpoint_path(stage_dir), {}
    )
    receipt = (
        checkpoint.get("raw_snapshot_execution")
        if isinstance(checkpoint, dict)
        and isinstance(
            checkpoint.get("raw_snapshot_execution"), dict
        )
        else {}
    )
    target_snapshot = (
        receipt.get("target_snapshot")
        if isinstance(receipt.get("target_snapshot"), dict)
        else {}
    )
    if not (
        receipt.get("mode") == "ficlone_snapshot_v1"
        and str(receipt.get("expected_sha256") or "")
        == expected_raw_sha256
        and staged_raw_path.is_file()
        and staged_raw_path.stat().st_size == expected_raw_bytes
        and int_value(target_snapshot.get("size"), -1)
        == expected_raw_bytes
        and int_value(target_snapshot.get("mtime_ns"), -1)
        == staged_raw_path.stat().st_mtime_ns
    ):
        return False
    return True


def stage_existing_session_projection(
    session_dir: Path,
) -> Path:
    stage_dir = Path(
        tempfile.mkdtemp(
            prefix=session_projection_stage_prefix(
                session_dir
            ),
            dir=session_dir.parent,
        )
    )
    relative_paths = [
        Path("raw") / "session.raw.jsonl",
        Path("raw") / EVENT_CLASSIFICATION_CACHE_DIR,
        Path("segments"),
        Path("raw") / RAW_BLOCKS_DIR,
        Path("raw") / RAW_BLOCK_INDEX_JSON,
        Path("raw") / RAW_COMPACTION_EVENTS_JSONL,
        Path("raw") / RAW_SOURCE_JSON,
        Path("raw") / RAW_CAPTURE_STATE_JSON,
        Path(SESSION_INDEX_MARKDOWN),
        Path("session.manifest.json"),
        Path(SESSION_INDEX_JSON),
        Path(SESSION_INDEX_SHARDS_DIR),
    ]
    try:
        for relative_path in relative_paths:
            source = session_dir / relative_path
            if not source.exists() and not source.is_symlink():
                continue
            stage_projection_path_with_links(
                source=source,
                target=stage_dir / relative_path,
            )
    except BaseException:
        remove_projection_publish_path(stage_dir)
        raise
    return stage_dir


def atomic_publish_session_projection(
    *,
    stage_dir: Path,
    session_dir: Path,
    publish_identity: dict[str, Any],
) -> dict[str, Any]:
    atomic_started = time.monotonic()
    recovery = recover_interrupted_session_projection_publish(
        session_dir
    )
    validation_started = time.monotonic()
    validation = validate_staged_session_projection(
        stage_dir=stage_dir,
        session_dir=session_dir,
        publish_identity=publish_identity,
    )
    validation_ms = int(
        (time.monotonic() - validation_started) * 1000
    )
    if not validation.get("ok"):
        raise ValueError(
            "staged_session_projection_invalid:"
            + ",".join(validation.get("diagnostics", []))
        )
    old_snapshot = projection_component_snapshot(session_dir)
    new_snapshot = projection_component_snapshot(stage_dir)
    old_manifest = read_json(
        session_dir / "session.manifest.json",
        {},
    )
    old_publish_id = projection_publish_id(
        old_manifest.get("index_schema")
        if isinstance(old_manifest, dict)
        and isinstance(old_manifest.get("index_schema"), dict)
        else {}
    )
    if old_publish_id == "None":
        old_publish_id = ""
    new_publish_id = projection_publish_id(publish_identity)
    new_manifest = read_json(
        stage_dir / "session.manifest.json",
        {},
    )
    outbox_record = session_projection_outbox_record(
        session_dir=session_dir,
        old_snapshot=old_snapshot,
        new_snapshot=new_snapshot,
        old_publish_id=old_publish_id,
        new_publish_id=new_publish_id,
        session_id=str(
            new_manifest.get("session_id")
            if isinstance(new_manifest, dict)
            else ""
        ),
    )
    outbox_path = projection_outbox_record_path(
        session_dir,
        str(outbox_record["record_id"]),
    )
    outbox_preexisting = outbox_path.is_file()
    publish_started = time.monotonic()
    backup_root = Path(
        tempfile.mkdtemp(
            prefix=(
                f".{session_dir.name}.projection-backup-"
            ),
            dir=session_dir.parent,
        )
    )
    journal_path = session_projection_publish_journal_path(
        session_dir
    )
    relative_paths = [
        Path("raw") / "session.raw.jsonl",
        Path("raw") / EVENT_CLASSIFICATION_CACHE_DIR,
        Path("segments"),
        Path("raw") / RAW_BLOCKS_DIR,
        Path("raw") / RAW_BLOCK_INDEX_JSON,
        Path("raw") / RAW_COMPACTION_EVENTS_JSONL,
        Path("raw") / RAW_SOURCE_JSON,
        Path("raw") / RAW_CAPTURE_STATE_JSON,
        Path(SESSION_INDEX_MARKDOWN),
        Path("session.manifest.json"),
        Path(SESSION_INDEX_JSON),
        Path(SESSION_INDEX_SHARDS_DIR),
        Path("distillation"),
    ]
    operations: list[dict[str, Any]] = []
    for relative_path in relative_paths:
        staged_path = stage_dir / relative_path
        if not staged_path.exists() and not staged_path.is_symlink():
            continue
        final_path = session_dir / relative_path
        operations.append(
            {
                "relative": str(relative_path),
                "staged": str(staged_path),
                "final": str(final_path),
                "backup": str(backup_root / relative_path),
                "had_original": bool(
                    final_path.exists() or final_path.is_symlink()
                ),
                "backed_up": False,
                "published": False,
            }
        )
    journal = {
        "schema_version": 1,
        "status": "publishing",
        "publish_id": projection_publish_id(publish_identity),
        "stage_dir": str(stage_dir),
        "backup_root": str(backup_root),
        "operations": operations,
        "outbox_record": {
            "record_id": outbox_record["record_id"],
            "path": str(outbox_path),
            "preexisting": outbox_preexisting,
            "written": False,
            "change_count": len(outbox_record["changes"]),
        },
    }
    write_json(journal_path, journal)
    try:
        for operation in operations:
            staged_path = Path(operation["staged"])
            final_path = Path(operation["final"])
            backup_path = Path(operation["backup"])
            final_path.parent.mkdir(parents=True, exist_ok=True)
            if operation["had_original"]:
                backup_path.parent.mkdir(
                    parents=True,
                    exist_ok=True,
                )
                publish_session_projection_replace(
                    final_path,
                    backup_path,
                )
                operation["backed_up"] = True
                write_json(journal_path, journal)
            publish_session_projection_replace(
                staged_path,
                final_path,
            )
            operation["published"] = True
            write_json(journal_path, journal)
        producer_source_state = (
            session_memory_loaded_producer_source_state()
        )
        if not producer_source_state.get("stable"):
            raise ValueError(
                "producer_source_changed_during_session_publish"
            )
        outbox_write = write_projection_outbox_record(
            session_dir,
            outbox_record,
        )
        journal["outbox_record"]["written"] = True
        journal["outbox_record"]["write_status"] = (
            outbox_write["status"]
        )
        write_json(journal_path, journal)
    except BaseException:
        write_json(journal_path, journal)
        recover_interrupted_session_projection_publish(
            session_dir
        )
        raise
    journal["status"] = "published"
    write_json(journal_path, journal)
    remove_projection_publish_path(backup_root)
    remove_projection_publish_path(stage_dir)
    journal_path.unlink(missing_ok=True)
    return {
        "status": "published",
        "publish_id": projection_publish_id(publish_identity),
        "operation_count": len(operations),
        "validation": validation,
        "producer_source_state": producer_source_state,
        "prior_recovery": recovery,
        "outbox": outbox_write,
        "changed_components": outbox_record["changes"],
        "required_downstream_consumers": outbox_record[
            "required_consumers"
        ],
        "phase_timings_ms": {
            "projection_validation": validation_ms,
            "atomic_publish": int(
                (time.monotonic() - publish_started) * 1000
            ),
            "total": int(
                (time.monotonic() - atomic_started) * 1000
            ),
        },
    }


def write_session_agents(session_dir: Path) -> None:
    path = session_dir / "AGENTS.md"
    path.write_text(
        """# AGENTS.md

## Session-local instructions

This folder contains one Codex session archive.

Always read:

1. root `.aoa/DESIGN.md` if available
2. `SESSION.md`
3. `session.manifest.json`
4. the relevant `segments/*.index.json`
5. only then the relevant `segments/*.md`

## Rules

- Raw material is evidence, not final reviewed truth.
- Segment Markdown is generated and may be regenerated from raw JSONL.
- Important claims must point to raw refs or segment event IDs.
- Distillation artifacts remain provisional unless reviewed.
- If raw is missing or unreadable, inspect `incidents/` before continuing.
""",
        encoding="utf-8",
    )


def hook_source_metadata(session_dir: Path) -> dict[str, Any]:
    metadata: dict[str, Any] = {}
    events_path = session_dir / "hooks" / "events.jsonl"
    if not events_path.exists():
        return metadata
    with events_path.open("r", encoding="utf-8", errors="replace") as handle:
        for line in handle:
            try:
                row = json.loads(line)
            except json.JSONDecodeError:
                continue
            event = row.get("event")
            if not isinstance(event, dict):
                continue
            for key in ("cwd", "model", "permission_mode"):
                value = event.get(key)
                if value:
                    metadata[key] = value
            if event.get("turn_id"):
                metadata["last_turn_id"] = event.get("turn_id")
    return metadata


def session_source(
    event: dict[str, Any],
    transcript_path: Path | None,
    *,
    existing_source: dict[str, Any] | None = None,
    hook_source: dict[str, Any] | None = None,
) -> dict[str, Any]:
    source = {
        "transcript_path": str(transcript_path) if transcript_path else None,
        "cwd": event.get("cwd"),
        "model": event.get("model"),
        "permission_mode": event.get("permission_mode"),
        "last_turn_id": event.get("turn_id"),
    }
    for key in ("cwd", "model", "permission_mode", "last_turn_id"):
        if source.get(key):
            continue
        for fallback in (hook_source, existing_source):
            if isinstance(fallback, dict) and fallback.get(key):
                source[key] = fallback.get(key)
                break
    return source


def file_snapshot(path: Path) -> dict[str, Any]:
    stat = path.stat()
    return {
        "path": str(path),
        "size": stat.st_size,
        "mtime_ns": stat.st_mtime_ns,
    }


def raw_capture_state_path(session_dir: Path) -> Path:
    return session_dir / "raw" / RAW_CAPTURE_STATE_JSON


def raw_capture_state_for_session(session_dir: Path) -> dict[str, Any]:
    state = read_json(raw_capture_state_path(session_dir), {})
    return state if isinstance(state, dict) else {}


def raw_capture_hooks_seen(
    session_dir: Path,
) -> list[str]:
    state = raw_capture_state_for_session(session_dir)
    values = (
        state.get("hooks_seen")
        if isinstance(state.get("hooks_seen"), list)
        else []
    )
    return sorted({str(value) for value in values if value})


def operational_hooks_seen(
    session_dir: Path,
    manifest: dict[str, Any] | None = None,
) -> list[str]:
    manifest_values = (
        manifest.get("hooks_seen")
        if isinstance(manifest, dict)
        and isinstance(manifest.get("hooks_seen"), list)
        else []
    )
    worker_state = read_json(
        session_dir / HOOK_WORKER_SEEN_JSON,
        {},
    )
    worker_values = (
        worker_state.get("hooks_seen")
        if isinstance(worker_state, dict)
        and isinstance(worker_state.get("hooks_seen"), list)
        else []
    )
    return sorted(
        {
            *(
                str(value)
                for value in manifest_values
                if value
            ),
            *raw_capture_hooks_seen(session_dir),
            *(
                str(value)
                for value in worker_values
                if value
            ),
        }
    )


def record_operational_hook_observation(
    *,
    session_dir: Path,
    manifest: dict[str, Any],
    hook_event_name: str,
    basis: str,
    detail: dict[str, Any] | None = None,
) -> dict[str, Any]:
    state_path = session_dir / HOOK_WORKER_SEEN_JSON
    prior_state = read_json(state_path, {})
    hooks_seen = set(
        operational_hooks_seen(session_dir, manifest)
    )
    added = bool(
        hook_event_name
        and hook_event_name not in hooks_seen
    )
    if hook_event_name:
        hooks_seen.add(hook_event_name)
    observations = (
        prior_state.get("observations")
        if isinstance(prior_state, dict)
        and isinstance(prior_state.get("observations"), list)
        else []
    )
    observation = {
        "hook_event_name": hook_event_name,
        "observed_at": utc_now(),
        "basis": basis,
    }
    if detail:
        observation["detail"] = detail
    observations.append(observation)
    state = {
        "schema_version": 1,
        "artifact_type": (
            "operational_hook_observation_state"
        ),
        "session_id": manifest.get("session_id"),
        "updated_at": utc_now(),
        "hooks_seen": sorted(hooks_seen),
        "observations": observations[-128:],
        "semantic_projection_mutated": False,
    }
    write_json(state_path, state)
    return {
        "updated": added,
        "reason": (
            "hook_seen_recorded"
            if added
            else "hook_seen_already_present"
        ),
        "session_id": manifest.get("session_id"),
        "session_dir": str(session_dir),
        "hooks_seen": state["hooks_seen"],
        "state_path": str(state_path),
        "semantic_projection_mutated": False,
    }


def raw_capture_state_semantic_stale_reasons(
    session_dir: Path,
    manifest: dict[str, Any],
) -> list[str]:
    state = raw_capture_state_for_session(session_dir)
    if not state:
        return []
    reasons: list[str] = []
    state_schema_version = int_value(state.get("schema_version"))
    if state_schema_version not in {1, RAW_CAPTURE_STATE_SCHEMA_VERSION}:
        reasons.append("raw_capture_state_schema_incompatible")
    capture_path_value = state.get("capture_path")
    capture_path = (
        Path(str(capture_path_value))
        if capture_path_value
        else None
    )
    if capture_path is None or not capture_path.is_file():
        reasons.append("raw_capture_payload_missing")
    capture_sha256 = str(state.get("raw_sha256") or "")
    if not capture_sha256 and not (
        state_schema_version == RAW_CAPTURE_STATE_SCHEMA_VERSION
        and state.get("raw_digest_status") == "deferred_to_projection"
        and state.get("ledger_chain_sha256")
    ):
        reasons.append("raw_capture_sha256_missing")
    if (
        state_schema_version == RAW_CAPTURE_STATE_SCHEMA_VERSION
        and state.get("capture_mode")
        == "append_only_immutable_block_ledger_v1"
    ):
        ledger_path = Path(str(state.get("ledger_path") or ""))
        overlay_path = Path(
            str(state.get("persistent_live_tail_index") or "")
        )
        if not ledger_path.is_file():
            reasons.append("raw_capture_ledger_missing")
        if not overlay_path.is_file():
            reasons.append("persistent_live_tail_index_missing")
    raw = (
        manifest.get("raw")
        if isinstance(manifest.get("raw"), dict)
        else {}
    )
    projection_raw_sha256 = str(raw.get("sha256") or "")
    status = str(state.get("status") or "")
    if status in {
        "preserved_unindexed",
        "preserved_unstable_unindexed",
    }:
        if (
            capture_sha256 != projection_raw_sha256
            if capture_sha256
            else int_value(state.get("raw_bytes"), -1)
            != int_value(raw.get("bytes"), -2)
        ):
            reasons.append(
                "preserved_raw_capture_ahead_of_session_projection"
            )
        if not bool(state.get("source_stable_during_capture", True)):
            reasons.append(
                "raw_capture_source_changed_during_capture"
            )
    elif status == "captured_matches_indexed_projection":
        if capture_sha256 != projection_raw_sha256:
            reasons.append(
                "raw_capture_match_state_digest_mismatch"
            )
    elif status == "indexed_with_projection":
        (
            expected_publish_id,
            expected_raw_sha256,
        ) = session_manifest_projection_expectations(manifest)
        if capture_sha256 != expected_raw_sha256:
            reasons.append(
                "indexed_raw_capture_digest_mismatch"
            )
        state_publish_id = str(
            state.get("projection_publish_id") or ""
        )
        if (
            expected_publish_id
            and state_publish_id != expected_publish_id
        ):
            reasons.append(
                "raw_capture_projection_publish_mismatch"
            )
        if not bool(
            state.get("source_stable_during_capture", True)
        ):
            reasons.append(
                "raw_capture_source_changed_during_capture"
            )
    else:
        reasons.append("raw_capture_state_unknown_status")
    return reasons


def raw_capture_ledger_path(session_dir: Path) -> Path:
    return session_dir / "raw" / RAW_CAPTURE_LEDGER_JSON


def persistent_live_tail_index_path(session_dir: Path) -> Path:
    return session_dir / "raw" / PERSISTENT_LIVE_TAIL_INDEX_JSON


def persistent_live_tail_postings_path(session_dir: Path) -> Path:
    return session_dir / "raw" / PERSISTENT_LIVE_TAIL_POSTINGS_JSON


def persistent_live_tail_postings_shard_root(
    session_dir: Path,
    *,
    epoch_id: str,
    generation_id: str,
) -> Path:
    return (
        session_dir
        / "raw"
        / PERSISTENT_LIVE_TAIL_POSTINGS_SHARD_DIR
        / epoch_id
        / generation_id[:16]
    )


def persistent_live_tail_postings_shard_path(
    session_dir: Path,
    *,
    epoch_id: str,
    generation_id: str,
    ordinal: int,
    revision_id: str,
) -> Path:
    return persistent_live_tail_postings_shard_root(
        session_dir,
        epoch_id=epoch_id,
        generation_id=generation_id,
    ) / f"{ordinal:06d}-{revision_id[:16]}.json"


def capture_watch_state_path(aoa_root: Path) -> Path:
    return aoa_root / DIAGNOSTICS_ROOT / CAPTURE_WATCH_STATE_JSON


def capture_watch_state_lock_path(aoa_root: Path) -> Path:
    return aoa_root / DIAGNOSTICS_ROOT / CAPTURE_WATCH_STATE_LOCK


def register_capture_watch(
    *,
    aoa_root: Path,
    session_id: str,
    session_dir: Path,
    transcript_path: Path,
    observed_at: str,
) -> dict[str, Any]:
    """Remember one hook-observed source for bounded timer reconciliation."""
    lock_path = capture_watch_state_lock_path(aoa_root)
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    with lock_path.open("w", encoding="utf-8") as lock_handle:
        fcntl.flock(lock_handle, fcntl.LOCK_EX)
        path = capture_watch_state_path(aoa_root)
        state = read_json(path, {})
        entries = (
            dict(state.get("entries"))
            if isinstance(state, dict)
            and isinstance(state.get("entries"), dict)
            else {}
        )
        prior = (
            dict(entries.get(session_id))
            if isinstance(entries.get(session_id), dict)
            else {}
        )
        try:
            snapshot = file_snapshot(transcript_path)
            source_available = True
        except OSError:
            snapshot = {
                "path": str(transcript_path),
                "size": -1,
                "mtime_ns": -1,
            }
            source_available = False
        entries[session_id] = {
            **prior,
            "session_id": session_id,
            "session_dir": str(session_dir),
            "transcript_path": str(transcript_path),
            "observed_at": observed_at,
            "observed_size": int_value(snapshot.get("size"), -1),
            "observed_mtime_ns": int_value(
                snapshot.get("mtime_ns"), -1
            ),
            "source_available": source_available,
        }
        payload = {
            "schema_version": CAPTURE_WATCH_STATE_SCHEMA_VERSION,
            "artifact_type": "session_memory_capture_watch_state",
            "updated_at": observed_at,
            "entries": entries,
            "authority": (
                "operational_source_watch_only_raw_capture_is_authority"
            ),
        }
        write_json(path, payload)
        return dict(entries[session_id])


def reconcile_capture_watch(
    *,
    aoa_root: Path,
    limit: int,
    apply: bool,
    target: str = "all",
    now: str | None = None,
) -> dict[str, Any]:
    """Recover missed capture hooks from a bounded watched-source frontier."""
    checked_at = now or utc_now()
    path = capture_watch_state_path(aoa_root)
    state = read_json(path, {})
    entries = (
        state.get("entries")
        if isinstance(state, dict)
        and isinstance(state.get("entries"), dict)
        else {}
    )
    selected = sorted(
        (
            dict(item)
            for item in entries.values()
            if isinstance(item, dict)
            and (
                target == "all"
                or str(item.get("session_id") or "") == target
            )
        ),
        key=lambda item: (
            str(item.get("last_checked_at") or ""),
            str(item.get("observed_at") or ""),
            str(item.get("session_id") or ""),
        ),
    )[: max(0, limit)]
    results: list[dict[str, Any]] = []
    updates: dict[str, dict[str, Any]] = {}
    for watched in selected:
        session_id = str(watched.get("session_id") or "")
        transcript_path = Path(
            str(watched.get("transcript_path") or "")
        )
        result: dict[str, Any] = {
            "session_id": session_id,
            "transcript_path": str(transcript_path),
            "status": "unchanged",
            "mutates": False,
        }
        if (
            not session_id
            or not transcript_path.is_file()
            or not os.access(transcript_path, os.R_OK)
        ):
            result["status"] = "source_unavailable"
            results.append(result)
            updates[session_id] = {
                "last_checked_at": checked_at,
                "last_status": result["status"],
            }
            continue
        source_snapshot = file_snapshot(transcript_path)
        resolved_session_dir = session_dir_for_id(
            aoa_root, session_id
        )
        stored_session_dir = Path(
            str(watched.get("session_dir") or resolved_session_dir)
        )
        session_dir = (
            resolved_session_dir
            if resolved_session_dir.exists()
            else stored_session_dir
        )
        manifest = read_json(
            session_dir / "session.manifest.json", {}
        )
        capture_state = raw_capture_state_for_session(session_dir)
        captured_snapshot = (
            capture_state.get("source_snapshot_after")
            if isinstance(
                capture_state.get("source_snapshot_after"), dict
            )
            else {}
        )
        capture_current = bool(
            str(capture_state.get("source_path") or "")
            == str(transcript_path)
            and int_value(captured_snapshot.get("size"), -1)
            == int_value(source_snapshot.get("size"), -2)
            and int_value(captured_snapshot.get("mtime_ns"), -1)
            == int_value(source_snapshot.get("mtime_ns"), -2)
        )
        result["source_snapshot"] = source_snapshot
        result["capture_current_before"] = capture_current
        if not capture_current:
            result["status"] = "capture_change_detected"
            if apply:
                if isinstance(manifest, dict) and manifest.get(
                    "session_id"
                ):
                    captured = preserve_unindexed_raw_capture(
                        session_dir=session_dir,
                        session_id=session_id,
                        transcript_path=transcript_path,
                        manifest=manifest,
                        hook_event_name="TimerWatchRecovery",
                        now=checked_at,
                    )
                    result.update(
                        {
                            "status": "missed_hook_capture_recovered",
                            "mutates": True,
                            "session_dir": str(session_dir),
                            "appended_bytes": int_value(
                                captured.get("appended_bytes")
                            ),
                            "capture_ref": str(
                                captured.get("capture_ref") or ""
                            ),
                        }
                    )
                else:
                    mirrored = mirror_transcript_without_indexing(
                        aoa_root=aoa_root,
                        event={
                            "session_id": session_id,
                            "transcript_path": str(transcript_path),
                        },
                        transcript_path=transcript_path,
                        hook_event_name="TimerWatchRecovery",
                        now=checked_at,
                    )
                    result.update(
                        {
                            "status": "missed_hook_session_recovered",
                            "mutates": True,
                            "session_dir": str(
                                mirrored.get("session_dir") or ""
                            ),
                            "appended_bytes": int_value(
                                mirrored.get("capture", {}).get(
                                    "appended_bytes"
                                )
                                if isinstance(
                                    mirrored.get("capture"), dict
                                )
                                else 0
                            ),
                        }
                    )
        results.append(result)
        updates[session_id] = {
            "last_checked_at": checked_at,
            "last_status": result["status"],
            "last_source_size": int_value(
                source_snapshot.get("size"), -1
            ),
            "last_source_mtime_ns": int_value(
                source_snapshot.get("mtime_ns"), -1
            ),
        }
    if apply and updates:
        lock_path = capture_watch_state_lock_path(aoa_root)
        lock_path.parent.mkdir(parents=True, exist_ok=True)
        with lock_path.open("w", encoding="utf-8") as lock_handle:
            fcntl.flock(lock_handle, fcntl.LOCK_EX)
            current = read_json(path, {})
            current_entries = (
                dict(current.get("entries"))
                if isinstance(current, dict)
                and isinstance(current.get("entries"), dict)
                else {}
            )
            for session_id, update in updates.items():
                if not session_id:
                    continue
                prior = (
                    dict(current_entries.get(session_id))
                    if isinstance(
                        current_entries.get(session_id), dict
                    )
                    else {}
                )
                current_entries[session_id] = {**prior, **update}
            write_json(
                path,
                {
                    "schema_version": (
                        CAPTURE_WATCH_STATE_SCHEMA_VERSION
                    ),
                    "artifact_type": (
                        "session_memory_capture_watch_state"
                    ),
                    "updated_at": checked_at,
                    "entries": current_entries,
                    "authority": (
                        "operational_source_watch_only_raw_capture_is_authority"
                    ),
                },
            )
    return {
        "schema_version": CAPTURE_WATCH_STATE_SCHEMA_VERSION,
        "artifact_type": "session_memory_capture_watch_reconciliation",
        "generated_at": checked_at,
        "ok": True,
        "status": "applied" if apply else "planned",
        "apply": apply,
        "watched_source_count": len(entries),
        "selected_count": len(selected),
        "changed_count": sum(
            result.get("capture_current_before") is False
            for result in results
        ),
        "recovered_count": sum(
            bool(result.get("mutates")) for result in results
        ),
        "archive_manifest_scan_performed": False,
        "raw_payload_read_for_unchanged_sources": False,
        "results": results,
        "truth_status": (
            "bounded_known_source_reconciliation_not_global_source_discovery"
        ),
    }


