                "episode_semantic_repair_remaining_count",
                "episode_semantic_repair_limited",
                "episode_posting_cardinality_metadata_incomplete_session_count",
                "episode_posting_cardinality_metadata_remaining_count",
                "episode_posting_cardinality",
                "final_episode_posting_cardinality",
                "repair_limit",
                "search_repair_limit",
                "search_shard_repair_limit",
                "route_max_raw_bytes",
                "route_drift_count",
                "route_repair_candidate_count",
                "route_repair_session_count",
                "route_repair_remaining_count",
                "route_repair_limited",
                "route_repair_sessions",
                "route_repair_deferred_count",
                "route_repair_blocked_count",
                "route_repair_deferred",
                "token_backfill",
                "search_dirty_session_count",
                "search_state_refresh_candidate_count",
                "search_state_refresh_count",
                "search_reindex_candidate_count",
                "search_reindex_session_count",
                "search_repair_remaining_count",
                "search_repair_limited",
                "search_shards_repair_needed",
                "search_shards_dirty_session_count",
                "search_shards_repair_session_count",
                "search_shards_repair_scoped_candidate_count",
                "search_shards_repair_scoped_remaining_count",
