def exact_literal_fts_query_plan_from_user(query: str) -> dict[str, Any]:
    query_text = str(query or "").strip()
    tokens = search_tokenize(query)
    if not tokens:
        return {
            "fts_query": "",
            "mode": "empty",
            "near_distance": None,
            "anchor_type": "",
            "transition_only": False,
        }
    selected_tokens = tokens[:16]
    transition_match = re.fullmatch(r"(\S+)\s*(?:->|=>|→)\s*(\S+)", query_text)
    if transition_match and 2 <= len(selected_tokens) <= 16:
        return {
            "fts_query": f'"{" ".join(selected_tokens)}"',
            "mode": "patch_transition_phrase",
            "near_distance": None,
            "anchor_type": "same_field_patch_transition",
            "transition_only": True,
        }
    identifier_anchor = literal_query_identifier_anchor(query_text)
    project_record_anchor = literal_query_project_record_identifier_anchor(query_text)
    embedded_identifier = bool(
        identifier_anchor
        and query_text.strip("`'\"").casefold() != identifier_anchor.casefold()
    )
    if project_record_anchor or embedded_identifier:
        anchor_tokens = search_tokenize(identifier_anchor)
        anchor_token_keys = {token.casefold() for token in anchor_tokens}
        context_tokens: list[str] = []
        seen_context: set[str] = set()
        for token in selected_tokens:
            normalized_token = token.casefold()
            if (
                normalized_token in anchor_token_keys
                or normalized_token in SEARCH_LITERAL_IDENTIFIER_CONTEXT_STOPWORDS
                or len(normalized_token) < 2
                or normalized_token in seen_context
            ):
                continue
            seen_context.add(normalized_token)
            context_tokens.append(token)
        escaped_anchor = " ".join(token.replace('"', '""') for token in anchor_tokens)
        anchor_clause = f'"{escaped_anchor}"'
        anchor_type = (
            "project_record_identifier"
            if project_record_anchor
            else "structured_correlation_identifier"
        )
        if context_tokens:
            escaped_context_tokens = [
                token.replace('"', '""')
                for token in context_tokens[:12]
            ]
            context_clause = " OR ".join(
                f'"{token}"'
                for token in escaped_context_tokens
            )
            return {
                "fts_query": f"({anchor_clause}) AND ({context_clause})",
                "mode": "identifier_context_or_rank",
                "near_distance": None,
                "anchor_type": anchor_type,
                "anchor": identifier_anchor,
                "context_tokens": context_tokens[:12],
                "transition_only": False,
            }
        return {
            "fts_query": anchor_clause,
            "mode": "identifier_anchor_phrase",
            "near_distance": None,
            "anchor_type": anchor_type,
            "anchor": identifier_anchor,
            "context_tokens": [],
            "transition_only": False,
        }
    anchor = selected_tokens[0]
    subject_tokens = selected_tokens[1:]
    commit_identifier_subject = bool(
        3 <= len(selected_tokens) <= 12
        and re.fullmatch(r"[0-9a-fA-F]{7,40}", anchor)
        and re.search(r"[a-fA-F]", anchor)
        and any(re.search(r"[^\W\d_]", token, flags=re.UNICODE) for token in subject_tokens)
    )
    if commit_identifier_subject:
        subject_phrase = " ".join(subject_tokens)
        return {
            "fts_query": (
                f'NEAR("{anchor}" "{subject_phrase}", '
                f"{SEARCH_EXACT_LITERAL_IDENTIFIER_SUBJECT_NEAR_DISTANCE})"
            ),
            "mode": "identifier_subject_near_16",
            "near_distance": SEARCH_EXACT_LITERAL_IDENTIFIER_SUBJECT_NEAR_DISTANCE,
            "anchor_type": "git_commit_identifier",
            "transition_only": False,
        }
    return {
        "fts_query": f'"{" ".join(selected_tokens)}"',
        "mode": "ordered_token_phrase",
        "near_distance": None,
        "anchor_type": "",
        "transition_only": False,
    }


def exact_literal_fts_query_from_user(query: str) -> str:
    return str(exact_literal_fts_query_plan_from_user(query).get("fts_query") or "")


