# A deliberately small operational bridge for mixed-language session queries.
# These aliases are query-time navigation aids only: they do not rewrite the
# transcript, assert translation truth, or promote generated evidence over raw
# refs.  Keep the vocabulary bounded to recurring failure/recovery language.
EPISODE_SEMANTIC_CROSS_LANGUAGE_ALIASES: dict[str, tuple[str, ...]] = {
    "fix": ("fix", "исправ", "патч"),
    "restart": ("restart", "relaunch", "перезапуск", "запуск"),
    "failure": ("fail", "error", "ошиб", "сбой", "неудач", "заверш"),
    "safer": ("safe", "аккурат", "безопас"),
    "process": ("process", "процесс"),
    "selection": ("selection", "select", "выбор", "фильтр"),
    "successful": ("success", "succeed", "успеш"),
    "capture": ("capture", "captur", "захват", "съём", "съем"),
    "recovery": ("recover", "восстанов"),
    # Reverse bridges are rooted where Russian inflection would otherwise
    # hide the operational English token from the compact episode document.
    "перезапуск": ("перезапуск", "restart", "relaunch", "launch"),
    # Do not bridge to bare ``self``: recurrent ``selftest`` commands would
    # turn almost every operational episode into a false process-kill match.
    "убил": ("убил", "kill", "pkill"),
    "восстанов": ("восстанов", "recover", "success", "captur"),
}

