def episode_semantic_query_scope(
    query: str,
    *,
    session: str | None = None,
) -> dict[str, Any]:
    """Separate retrieval scope coordinates from semantic content terms.

    Session UUIDs and human calendar dates are useful filters, but allowing
    their fragments to dominate FTS/BM25 makes a later self-reference outrank
    the episode the user actually described.  This parser is intentionally
    bounded: it strips a UUID only when it is an explicit session selector,
    and it exposes calendar-date semantics instead of pretending they are UTC
    event-time bounds.
    """
    original = str(query or "").strip()
    semantic_text = original
    requested_session = str(session or "").strip()
    embedded_session = literal_query_session_target(original)
    explicit_session_selector = False
    if embedded_session:
        explicit_session_selector = bool(
            requested_session == embedded_session
            or re.search(
                rf"(?:\b(?:session|thread)\b|\bсесси[ияеюи]\w*\b)"
                rf"(?:\s+(?:id|uuid))?\s*[:#]?\s*{re.escape(embedded_session)}",
                original,
                flags=re.IGNORECASE,
            )
            or original.strip("`'\" ") == embedded_session
        )
    effective_session = requested_session
    removed_fragments: list[dict[str, str]] = []
    if embedded_session and explicit_session_selector:
        if not effective_session:
            effective_session = embedded_session
        semantic_text = semantic_text.replace(embedded_session, " ")
        removed_fragments.append(
            {"kind": "session_selector", "value": embedded_session}
        )
        semantic_text = re.sub(
            r"(?:\b(?:в|in)\s+)?"
            r"(?:\b(?:session|thread)\b|\bсесси[ияеюи]\w*\b)"
            r"(?:\s+(?:id|uuid))?\s*[:#]?",
            " ",
            semantic_text,
            flags=re.IGNORECASE,
        )

    natural_date = ""
    natural_date_mode = "not_requested"
    date_match = re.search(
        r"(?<!\d)([0-3]?\d)\s+"
        r"(января|февраля|марта|апреля|мая|июня|июля|августа|"
        r"сентября|октября|ноября|декабря)\s+(20\d{2})"
        r"(?:\s*г(?:ода)?\.?)?",
        semantic_text,
        flags=re.IGNORECASE,
    )
    if date_match:
        day = int(date_match.group(1))
        month = EPISODE_SEMANTIC_RUSSIAN_MONTHS[
            date_match.group(2).casefold()
        ]
        year = int(date_match.group(3))
        try:
            parsed_date = datetime(year, month, day, tzinfo=timezone.utc)
        except ValueError:
            parsed_date = None
        if parsed_date is not None:
            natural_date = parsed_date.strftime("%Y-%m-%d")
            prefix = semantic_text[max(0, date_match.start() - 24) : date_match.start()].casefold()
            approximate = bool(
                re.search(r"(?:около|примерно|приблизительно|around|near)\s*$", prefix)
            )
            # A date written in natural language normally reflects the
            # operator's local calendar, while session_date is derived from
            # the archived UTC timestamp.  Without an explicit timezone, an
            # exact one-day filter can therefore reject the right session at
            # either side of midnight.  Keep the navigation bounded, but make
            # the uncertainty visible instead of pretending this is event
            # time or an exact UTC calendar claim.
            natural_date_mode = (
                "session_calendar_date_approximate_timezone_tolerant"
                if approximate
                else "session_calendar_date_timezone_tolerant"
            )
            removed_fragments.append(
                {"kind": "calendar_date", "value": date_match.group(0)}
            )
            semantic_text = (
                semantic_text[: date_match.start()]
                + " "
                + semantic_text[date_match.end() :]
            )
            semantic_text = re.sub(
                r"\b(?:около|примерно|приблизительно|around|near)\s*$",
                " ",
                semantic_text[: date_match.start()],
                flags=re.IGNORECASE,
            ) + semantic_text[date_match.start() :]

    semantic_text = re.sub(r"\s+", " ", semantic_text).strip(" ,;:-")
    date_from = ""
    date_to = ""
    if natural_date:
        parsed = datetime.fromisoformat(natural_date).replace(tzinfo=timezone.utc)
        radius = 1
        date_from = (parsed - timedelta(days=radius)).strftime("%Y-%m-%d")
        date_to = (parsed + timedelta(days=radius)).strftime("%Y-%m-%d")
    return {
        "schema": "aoa_session_memory_episode_query_scope_v1",
        "requested_session": requested_session,
        "embedded_session_target": embedded_session,
        "embedded_session_selector": explicit_session_selector,
        "effective_session": effective_session,
        "semantic_query_text": semantic_text,
        "removed_scope_fragments": removed_fragments,
        "natural_calendar_date": natural_date,
        "natural_calendar_date_mode": natural_date_mode,
        "natural_calendar_date_from": date_from,
        "natural_calendar_date_to": date_to,
        "date_authority": (
            "session_display_calendar_date_navigation"
            if natural_date
            else "not_requested"
        ),
        "event_time_claim_allowed": False,
    }


def episode_semantic_morphology_stem(
    token: str,
    *,
    source_token: bool = False,
) -> tuple[str, str]:
    normalized = str(token or "").casefold()
    if re.search(r"[а-яё]", normalized):
        suffixes = (
            EPISODE_SEMANTIC_RUSSIAN_SUFFIXES
            + EPISODE_SEMANTIC_BOUNDED_SOURCE_SUFFIXES
            if source_token
            else EPISODE_SEMANTIC_RUSSIAN_SUFFIXES
        )
    else:
        suffixes = EPISODE_SEMANTIC_ENGLISH_SUFFIXES
    minimum_token_length = 5 if source_token else 6
    if len(normalized) < minimum_token_length:
        return normalized, ""
    for suffix in suffixes:
        if (
            normalized.endswith(suffix)
            and len(normalized) - len(suffix) >= 4
        ):
            return normalized[: -len(suffix)], suffix
    return normalized, ""


def episode_semantic_query_terms(query: str) -> list[dict[str, Any]]:
    raw_tokens = [token.casefold() for token in search_tokenize(query)]
    filtered = [
        token
        for token in raw_tokens
        if token not in EPISODE_SEMANTIC_STOPWORDS and (len(token) > 1 or token.isdigit())
    ]
    if not filtered:
        filtered = [token for token in raw_tokens if len(token) > 1 or token.isdigit()]
    terms: list[dict[str, Any]] = []
    seen: set[str] = set()
    for token in filtered:
        if token in seen:
            continue
        seen.add(token)
        prefixes: list[str] = []
        loose_prefixes: list[str] = []
        bounded_morphology_stems: list[str] = []
        stem, matched_suffix = episode_semantic_morphology_stem(token)
        if stem != token:
            prefixes.append(stem)
            if (
                matched_suffix
                in EPISODE_SEMANTIC_BOUNDED_MORPHOLOGY_SUFFIXES
            ):
                bounded_morphology_stems.append(stem)
            else:
                loose_prefixes.append(stem)
        exact = [token]
        aliases: list[str] = []
        for alias_root, root_aliases in EPISODE_SEMANTIC_CROSS_LANGUAGE_ALIASES.items():
            if token == alias_root or (len(alias_root) >= 5 and token.startswith(alias_root)):
                aliases.extend(root_aliases)
        for alias in aliases:
            if alias not in exact:
                exact.append(alias)
            if len(alias) >= 4 and alias not in prefixes:
                prefixes.append(alias)
            if len(alias) >= 4 and alias not in loose_prefixes:
                loose_prefixes.append(alias)
        terms.append(
            {
                "token": token,
                "exact": exact,
                "prefixes": prefixes,
                "loose_prefixes": loose_prefixes,
                "bounded_morphology_stems": bounded_morphology_stems,
            }
        )
        if len(terms) >= 24:
            break
    return terms


def episode_semantic_required_exact_anchors(query: str) -> list[dict[str, str]]:
    """Extract concrete query anchors that semantic neighbors may not ignore."""
    text = str(query or "").strip()
    anchors: list[dict[str, str]] = []
    seen: set[str] = set()

    def add(value: Any, *, kind: str) -> None:
        anchor = str(value or "").strip().strip("`'\"").rstrip(".,;!?)]}")
        identity = anchor.casefold()
        if not anchor or identity in seen:
            return
        seen.add(identity)
        anchors.append({"anchor": anchor, "kind": kind})

    for match in re.finditer(
        r"\b[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-"
        r"[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\b",
        text,
    ):
        add(match.group(0), kind="uuid")
    for match in re.finditer(
        r"(?<![A-Za-zА-Яа-яЁё0-9])"
        r"(?:raw:(?:line|block):[A-Za-z0-9_.:/#-]+)"
        r"(?![A-Za-zА-Яа-яЁё0-9])",
        text,
        flags=re.IGNORECASE,
    ):
        add(match.group(0), kind="raw_ref")
    path_anchor = literal_query_path_anchor(text)
    if path_anchor:
        add(path_anchor, kind="path")
    for match in re.finditer(
        r"(?<![A-Za-zА-Яа-яЁё0-9])"
        r"([A-Za-zА-Яа-яЁё][A-Za-zА-Яа-яЁё0-9_.:-]{3,})"
        r"(?![A-Za-zА-Яа-яЁё0-9])",
        text,
    ):
        candidate = match.group(1)
        if (
            any(character.isdigit() for character in candidate)
            and any(separator in candidate for separator in ("_", "-", ":", "."))
        ):
            add(candidate, kind="structured_identifier")
    return anchors[:8]


def episode_semantic_required_anchor_matches(
    text: str,
    anchors: list[dict[str, str]],
) -> set[str]:
    lowered = str(text or "").casefold()
    return {
        str(item.get("anchor") or "")
        for item in anchors
        if str(item.get("anchor") or "")
        and str(item.get("anchor") or "").casefold() in lowered
    }


def episode_semantic_fts_query(terms: list[dict[str, Any]]) -> str:
    clauses: list[str] = []
    seen: set[tuple[str, bool]] = set()
    for term in terms:
        for value in term.get("exact", []) if isinstance(term.get("exact"), list) else []:
            token = str(value or "").replace('"', '""')
            identity = (token, False)
            if token and identity not in seen:
                seen.add(identity)
                clauses.append(f'"{token}"')
        for value in term.get("prefixes", []) if isinstance(term.get("prefixes"), list) else []:
            token = str(value or "").replace('"', '""')
            identity = (token, True)
            if token and identity not in seen:
                seen.add(identity)
                clauses.append(f'"{token}"*')
    return " OR ".join(clauses[:48])


def episode_semantic_term_matches_tokens(term: dict[str, Any], tokens: set[str]) -> bool:
    exact = {str(value) for value in term.get("exact", []) if value} if isinstance(term.get("exact"), list) else set()
    if exact & tokens:
        return True
    bounded_stems = (
        {
            str(value)
            for value in term.get("bounded_morphology_stems", [])
            if value
        }
        if isinstance(term.get("bounded_morphology_stems"), list)
        else set()
    )
    if bounded_stems:
        token_stems = {
            episode_semantic_morphology_stem(
                token,
                source_token=True,
            )[0]
            for token in tokens
            if token
        }
        if bounded_stems & (tokens | token_stems):
            return True
    prefixes_source = (
        term.get("loose_prefixes")
        if isinstance(term.get("loose_prefixes"), list)
        else term.get("prefixes", [])
    )
    prefixes = [
        str(value)
        for value in prefixes_source
        if value
    ]
    return any(
        token.startswith(prefix)
        for prefix in prefixes
        for token in tokens
    )


def episode_semantic_field_tokens(text: Any) -> set[str]:
    normalized = (
        str(text or "")
        .replace("\\r\\n", " ")
        .replace("\\n", " ")
        .replace("\\r", " ")
        .replace("\\t", " ")
    )
    return {token.casefold() for token in search_tokenize(normalized)}


def episode_semantic_episode_by_id(session_index: dict[str, Any], episode_id: str) -> dict[str, Any]:
    episodes = session_index.get("task_episodes") if isinstance(session_index.get("task_episodes"), list) else []
    for episode in episodes:
        if isinstance(episode, dict) and str(episode.get("episode_id") or "") == episode_id:
            return episode
    return {}


def episode_semantic_payload_from_blob(value: Any) -> dict[str, Any]:
    if value is None:
        return {}
    try:
        payload = json.loads(zlib.decompress(bytes(value)).decode("utf-8"))
    except (TypeError, ValueError, zlib.error, json.JSONDecodeError, UnicodeDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


EPISODE_DENSE_ROLE_QUOTAS = (
    ("failures", 600),
    ("verification", 800),
    ("outcomes", 900),
    ("actions", 300),
    ("plans", 200),
    ("intents", 200),
)


def episode_dense_tail_text(items: Any, quota: int) -> str:
    entries = items if isinstance(items, list) else []
    texts = [
        str(item.get("text") or "").strip()
        for item in entries
        if isinstance(item, dict) and str(item.get("text") or "").strip()
    ]
    selected: list[str] = []
    remaining = max(0, int_value(quota))
    selected_texts = texts[-min(4, len(texts)) :]
    per_item_cap = max(96, remaining // max(1, len(selected_texts))) if remaining else 0
    for text in reversed(selected_texts):
        if remaining <= 0:
            break
        piece = text[-min(remaining, per_item_cap) :]
        selected.append(piece)
        remaining -= len(piece) + 1
    return "\n".join(reversed(selected))


def episode_dense_document(episode: dict[str, Any]) -> str:
    """Build one bounded episode-level passage without letting a long session goal dominate it."""
    representations = episode.get("representations") if isinstance(episode.get("representations"), dict) else {}
    parts: list[str] = []
    anchors = episode_semantic_anchor_text(episode)
    if anchors:
        parts.append(f"anchors: {anchors[:400]}")
    for role, quota in EPISODE_DENSE_ROLE_QUOTAS:
        text = episode_dense_tail_text(representations.get(role), quota)
        if text:
            parts.append(f"{role}: {text}")
    passage = "passage: " + "\n".join(parts)
    return passage[:EPISODE_DENSE_DOCUMENT_MAX_CHARS]


EPISODE_DENSE_REPRESENTATION_ROLES = tuple(
    role for role, _quota in reversed(EPISODE_DENSE_ROLE_QUOTAS)
)


def episode_dense_representation_documents(
    episode: dict[str, Any],
    *,
    doc_id: str,
    session_id: str,
    episode_id: str,
) -> list[dict[str, Any]]:
    """Build bounded independently attributable passages for one episode."""
    representations = (
        episode.get("representations")
        if isinstance(episode.get("representations"), dict)
        else {}
    )
    documents: list[dict[str, Any]] = []
    for role in EPISODE_DENSE_REPRESENTATION_ROLES:
        entries = [
            item
            for item in (
                representations.get(role)
                if isinstance(representations.get(role), list)
                else []
            )
            if isinstance(item, dict)
            and str(item.get("text") or "").strip()
            and isinstance(item.get("refs"), dict)
            and item["refs"].get("raw")
        ][-EPISODE_DENSE_REPRESENTATION_PER_ROLE_LIMIT:]
        for item in entries:
            refs = item.get("refs") if isinstance(item.get("refs"), dict) else {}
            raw_ref = str(refs.get("raw") or "")
            text = str(item.get("text") or "").strip()[
                :EPISODE_DENSE_REPRESENTATION_TEXT_MAX_CHARS
            ]
            identity_payload = {
                "doc_id": doc_id,
                "role": role,
                "raw_ref": raw_ref,
                "source_lane": str(item.get("source_lane") or ""),
                "admission_basis": str(item.get("admission_basis") or ""),
                "outcome": str(item.get("outcome") or ""),
                "text_sha256": hashlib.sha256(
                    text.encode("utf-8")
                ).hexdigest(),
            }
            identity_digest = hashlib.sha256(
                json.dumps(
                    identity_payload,
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()[:24]
            document = (
                "passage: "
                f"role={role}; "
                f"source={item.get('source_lane') or 'unknown'}; "
                f"basis={item.get('admission_basis') or 'unknown'}; "
                f"outcome={item.get('outcome') or 'unknown'}\n"
                f"{text}"
            )
            documents.append(
                {
                    "representation_id": (
                        f"{doc_id}:representation:{identity_digest}"
                    ),
                    "doc_id": doc_id,
                    "session_id": session_id,
                    "episode_id": episode_id,
                    "role": role,
                    "raw_ref": raw_ref,
                    "segment_ref": str(refs.get("segment") or ""),
                    "session_ref": str(refs.get("session") or ""),
                    "source_lane": str(item.get("source_lane") or ""),
                    "admission_basis": str(
                        item.get("admission_basis") or ""
                    ),
                    "outcome": str(item.get("outcome") or ""),
                    "document": document,
                    "document_sha256": hashlib.sha256(
                        document.encode("utf-8")
                    ).hexdigest(),
                }
            )
    documents.sort(
        key=lambda item: (
            str(item.get("role") or ""),
            line_from_raw_ref(item.get("raw_ref")),
            str(item.get("representation_id") or ""),
        )
    )
    return documents


def episode_dense_representation_support(
    episode: dict[str, Any],
    matches: Any,
) -> list[dict[str, Any]]:
    """Resolve vector matches back to distinct evidence-bearing representations."""
    representations = (
        episode.get("representations")
        if isinstance(episode.get("representations"), dict)
        else {}
    )
    by_role_ref: dict[tuple[str, str], dict[str, Any]] = {}
    for role, entries in representations.items():
        if not isinstance(entries, list):
            continue
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            refs = (
                entry.get("refs")
                if isinstance(entry.get("refs"), dict)
                else {}
            )
            raw_ref = str(refs.get("raw") or "")
            if raw_ref:
                by_role_ref.setdefault((str(role), raw_ref), entry)
    support: list[dict[str, Any]] = []
    seen_raw_refs: set[str] = set()
    for match in matches if isinstance(matches, list) else []:
        if not isinstance(match, dict):
            continue
        role = str(match.get("role") or "")
        raw_ref = str(match.get("raw_ref") or "")
        if not raw_ref or raw_ref in seen_raw_refs:
            continue
        entry = by_role_ref.get((role, raw_ref))
        if not isinstance(entry, dict):
            continue
        refs = (
            entry.get("refs")
            if isinstance(entry.get("refs"), dict)
            else {}
        )
        support.append(
            {
                "role": role,
                "text": short_text(
                    str(entry.get("text") or ""),
                    max_chars=700,
                ),
                "matched_query_terms": [],
                "source_lane": entry.get("source_lane"),
                "admission_basis": entry.get("admission_basis"),
                "correlation_id": str(
                    entry.get("correlation_id") or ""
                ),
                "event_type": entry.get("event_type"),
                "outcome": entry.get("outcome"),
                "timestamp": entry.get("timestamp"),
                "line": entry.get("line")
                or line_from_raw_ref(raw_ref),
                "refs": {
                    "raw": raw_ref,
                    "segment": str(refs.get("segment") or ""),
                    "segment_index": str(
                        refs.get("segment_index") or ""
                    ),
                    "session": str(refs.get("session") or ""),
                },
                "dense_representation": {
                    "representation_id": str(
                        match.get("representation_id") or ""
                    ),
                    "score": match.get("score"),
                    "rank_within_episode": int_value(
                        match.get("rank_within_episode")
                    ),
                    "truth_status": (
                        "dense_representation_navigation_not_claim_truth"
                    ),
                    "selection_basis": str(
                        match.get("selection_basis") or ""
                    ),
                },
                "reading_score": round(
                    120.0
                    - float(
                        int_value(
                            match.get("rank_within_episode"),
                            1,
                        )
                    ),
                    4,
                ),
                "reading_signals": [
                    "dense_representation_match",
                    "representation_raw_ref_resolved",
                ],
            }
        )
        seen_raw_refs.add(raw_ref)
        if (
            len(support)
            >= EPISODE_DENSE_REPRESENTATION_MATCH_LIMIT
        ):
            break
    return support


def episode_dense_hydrate_result_support(
    result: dict[str, Any],
    episode: dict[str, Any],
    matches: Any,
) -> dict[str, Any]:
    clone = dict(result)
    dense_support = episode_dense_representation_support(
        episode,
        matches,
    )
    if not dense_support:
        return clone
    existing = (
        clone.get("supporting_evidence")
        if isinstance(clone.get("supporting_evidence"), list)
        else []
    )
    merged: list[dict[str, Any]] = []
    seen_raw_refs: set[str] = set()
    for entry in [*dense_support, *existing]:
        if not isinstance(entry, dict):
            continue
        refs = (
            entry.get("refs")
            if isinstance(entry.get("refs"), dict)
            else {}
        )
        raw_ref = str(refs.get("raw") or "")
        if raw_ref and raw_ref in seen_raw_refs:
            continue
        if raw_ref:
            seen_raw_refs.add(raw_ref)
        merged.append(entry)
        if len(merged) >= 12:
            break
    clone["supporting_evidence"] = merged
    clone["dense_representation_matches"] = [
        {
            key: match.get(key)
            for key in (
                "representation_id",
                "role",
                "raw_ref",
                "score",
                "rank_within_episode",
                "selection_basis",
            )
        }
        for match in matches
        if isinstance(match, dict)
        and match.get("raw_ref")
    ][:EPISODE_DENSE_REPRESENTATION_MATCH_LIMIT]
    return clone


def episode_dense_provider(aoa_root: Path) -> dict[str, Any]:
    config = search_provider_config(aoa_root)
    providers = config.get("providers") if isinstance(config.get("providers"), dict) else {}
    provider = providers.get("abyss_machine_nervous") if isinstance(providers.get("abyss_machine_nervous"), dict) else {}
    return {
        "name": "abyss_machine_nervous",
        "enabled": bool(provider.get("episode_dense_enabled")),
        "embedding_api_url": str(provider.get("embedding_api_url") or ""),
        "rerank_api_health_url": str(
            provider.get("rerank_api_health_url") or ""
        ),
        "rerank_api_url": str(provider.get("rerank_api_url") or ""),
        "expected_model": str(provider.get("embedding_model") or EPISODE_DENSE_DEFAULT_MODEL),
    }


def episode_dense_normalize_vector(values: Any) -> list[float]:
    if not isinstance(values, list) or not values:
        return []
    try:
        vector = [float(value) for value in values]
    except (TypeError, ValueError):
        return []
    if not all(math.isfinite(value) for value in vector):
        return []
    norm = math.sqrt(sum(value * value for value in vector))
    if norm <= 0.0:
        return []
    return [value / norm for value in vector]


def episode_dense_vector_blob(values: list[float]) -> bytes:
    vector = array.array("f", values)
    if sys.byteorder != "little":
        vector.byteswap()
    return vector.tobytes()


def episode_dense_vector_values(blob: Any, dimension: int) -> array.array[float]:
    vector = array.array("f")
    try:
        vector.frombytes(bytes(blob))
    except (TypeError, ValueError):
        return array.array("f")
    if sys.byteorder != "little":
        vector.byteswap()
    if len(vector) != dimension:
        return array.array("f")
    return vector


def episode_dense_embed_texts(
    *,
    url: str,
    texts: list[str],
    batch_size: int = EPISODE_DENSE_EMBED_BATCH_SIZE,
    timeout: int = EPISODE_DENSE_INDEX_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    started = time.monotonic()
    if not url:
        return {"ok": False, "status": "embedding_api_not_configured", "vectors": [], "diagnostics": ["embedding_api_url_missing"]}
    if not texts:
        return {"ok": True, "status": "empty", "vectors": [], "model": "", "dimension": 0, "elapsed_ms": 0, "diagnostics": []}
    vectors: list[list[float]] = []
    models: set[str] = set()
    dimensions: set[int] = set()
    prompt_tokens = 0
    effective_batch = max(1, min(int_value(batch_size, EPISODE_DENSE_EMBED_BATCH_SIZE), 16))
    for offset in range(0, len(texts), effective_batch):
        response = run_json_url(
            url,
            method="POST",
            payload={"input": texts[offset : offset + effective_batch]},
            timeout=timeout,
        )
        payload = response.get("payload") if isinstance(response.get("payload"), dict) else {}
        data = payload.get("data") if isinstance(payload.get("data"), list) else []
        ordered = sorted(
            (item for item in data if isinstance(item, dict)),
            key=lambda item: int_value(item.get("index")),
        )
        if not response.get("ok") or len(ordered) != len(texts[offset : offset + effective_batch]):
            return {
                "ok": False,
                "status": str(response.get("status") or "embedding_api_failed"),
                "vectors": [],
                "elapsed_ms": int((time.monotonic() - started) * 1000),
                "diagnostics": [
                    str(response.get("error") or response.get("body") or "embedding response count mismatch")
                ],
            }
        for item in ordered:
            vector = episode_dense_normalize_vector(item.get("embedding"))
            if not vector:
                return {
                    "ok": False,
                    "status": "invalid_embedding_vector",
                    "vectors": [],
                    "elapsed_ms": int((time.monotonic() - started) * 1000),
                    "diagnostics": ["embedding vector is empty, non-finite, or zero norm"],
                }
            vectors.append(vector)
            dimensions.add(len(vector))
        model = str(payload.get("model") or "")
        if model:
            models.add(model)
        usage = payload.get("usage") if isinstance(payload.get("usage"), dict) else {}
        prompt_tokens += int_value(usage.get("total_tokens") or usage.get("prompt_tokens"))
    if len(dimensions) != 1 or len(models) > 1:
        return {
            "ok": False,
            "status": "embedding_contract_drift",
            "vectors": [],
            "elapsed_ms": int((time.monotonic() - started) * 1000),
            "diagnostics": [f"models={sorted(models)} dimensions={sorted(dimensions)}"],
        }
    return {
        "ok": True,
        "status": "embedded",
        "vectors": vectors,
        "model": next(iter(models), EPISODE_DENSE_DEFAULT_MODEL),
        "dimension": next(iter(dimensions), 0),
        "prompt_tokens": prompt_tokens,
        "batch_size": effective_batch,
        "elapsed_ms": int((time.monotonic() - started) * 1000),
        "diagnostics": [],
    }


def episode_dense_provider_preflight(provider: dict[str, Any]) -> dict[str, Any]:
    """Probe the complete embedding route once before attributing failures to sessions."""
    started = time.monotonic()
    embedding = episode_dense_embed_texts(
        url=str(provider.get("embedding_api_url") or ""),
        texts=[EPISODE_DENSE_PROVIDER_PROBE_TEXT],
        batch_size=1,
        timeout=min(EPISODE_DENSE_QUERY_TIMEOUT_SECONDS, EPISODE_DENSE_INDEX_TIMEOUT_SECONDS),
    )
    provider_status = str(embedding.get("status") or "embedding_api_failed")
    elapsed_ms = int((time.monotonic() - started) * 1000)
    if not embedding.get("ok"):
        unavailable = provider_status in EPISODE_DENSE_PROVIDER_UNAVAILABLE_STATUSES
        return {
            "ok": False,
            "status": "provider_unavailable" if unavailable else "provider_probe_failed",
            "provider_status": provider_status,
            "model": str(embedding.get("model") or ""),
            "dimension": int_value(embedding.get("dimension")),
            "elapsed_ms": int_value(embedding.get("elapsed_ms"), elapsed_ms),
            "diagnostics": [str(item) for item in embedding.get("diagnostics", []) if item],
        }
    model = str(embedding.get("model") or "")
    dimension = int_value(embedding.get("dimension"))
    expected_model = str(provider.get("expected_model") or EPISODE_DENSE_DEFAULT_MODEL)
    if model != expected_model or dimension != EPISODE_DENSE_DEFAULT_DIMENSION:
        return {
            "ok": False,
            "status": "provider_contract_drift",
            "provider_status": provider_status,
            "model": model,
            "expected_model": expected_model,
            "dimension": dimension,
            "expected_dimension": EPISODE_DENSE_DEFAULT_DIMENSION,
            "elapsed_ms": int_value(embedding.get("elapsed_ms"), elapsed_ms),
            "diagnostics": [
                f"episode_dense_provider_contract_drift:model={model}:dimension={dimension}"
            ],
        }
    return {
        "ok": True,
        "status": "available",
        "provider_status": provider_status,
        "model": model,
        "dimension": dimension,
        "prompt_tokens": int_value(embedding.get("prompt_tokens")),
        "elapsed_ms": int_value(embedding.get("elapsed_ms"), elapsed_ms),
        "diagnostics": [],
    }


def episode_dense_projection_state(
    aoa_root: Path,
    *,
    records: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    provider = episode_dense_provider(aoa_root)
    expected_generations = session_memory_expected_generation_identities(
        aoa_root
    )
    expected_episode_generation_id = str(
        expected_generations["episode_semantic"]["generation_id"]
    )
    expected_dense_generation_identity = expected_generations[
        "episode_dense"
    ]
    expected_dense_generation_id = str(
        expected_dense_generation_identity["generation_id"]
    )
    enabled = bool(provider.get("enabled")) and bool(str(provider.get("embedding_api_url") or "").strip())
    db_path = search_db_path(aoa_root)
    if not db_path.exists():
        return {
            "status": "missing" if enabled else "disabled_unconfigured",
            "enabled": enabled,
            "needs_refresh": False,
            "current_session_count": 0,
            "source_session_count": 0,
            "vector_count": 0,
            "representation_vector_count": 0,
            "implicit_no_task_session_count": 0,
            "dirty_session_count": 0,
            "dirty_session_ids": [],
            "provider": provider,
            "diagnostics": [],
        }
    conn: sqlite3.Connection | None = None
    try:
        conn = connect_existing_search_db(db_path)
        selected_session_ids = (
            {
                str(record.get("session_id") or "")
                for record in records
                if isinstance(record, dict) and str(record.get("session_id") or "")
            }
            if records is not None
            else None
        )
        source_rows = conn.execute(
            "SELECT session_id, episode_count FROM episode_semantic_session_state "
            "WHERE projection_version = ? AND route_signal_classifier_version = ? "
            "AND generation_id = ? "
            "AND status IN ('current', 'no_task_episodes', 'no_admitted_episode_text')",
            (
                EPISODE_SEMANTIC_PROJECTION_VERSION,
                ROUTE_SIGNAL_CLASSIFIER_VERSION,
                expected_episode_generation_id,
            ),
        ).fetchall()
        if selected_session_ids is not None:
            source_rows = [
                row for row in source_rows
                if str(row["session_id"] or "") in selected_session_ids
            ]
        dense_rows = conn.execute("SELECT * FROM episode_dense_session_state").fetchall()
        dense_by_id = {str(row["session_id"]): row for row in dense_rows}
        dirty: list[str] = []
        current_count = 0
        vector_count = 0
        representation_vector_count = 0
        implicit_no_task_count = 0
        for source in source_rows:
            session_id = str(source["session_id"] or "")
            dense = dense_by_id.get(session_id)
            expected_count = int_value(source["episode_count"])
            stored_vector_count = int_value(dense["vector_count"]) if dense else 0
            stored_representation_count = (
                int_value(dense["representation_vector_count"], -1)
                if dense
                and "representation_vector_count" in dense.keys()
                else -1
            )
            stored_representation_document_count = (
                int_value(
                    dense["representation_document_count"],
                    -1,
                )
                if dense
                and "representation_document_count" in dense.keys()
                else -1
            )
            implicit_no_task = (
                expected_count == 0
                and stored_vector_count == 0
                and stored_representation_count in {-1, 0}
            )
            is_current = implicit_no_task or bool(
                dense
                and int_value(dense["source_episode_projection_version"]) == EPISODE_SEMANTIC_PROJECTION_VERSION
                and "source_route_signal_classifier_version" in dense.keys()
                and int_value(dense["source_route_signal_classifier_version"]) == ROUTE_SIGNAL_CLASSIFIER_VERSION
                and str(dense["generation_id"] or "")
                == expected_dense_generation_id
                and int_value(dense["dense_projection_version"]) == EPISODE_DENSE_PROJECTION_VERSION
                and int_value(dense["dense_document_version"]) == EPISODE_DENSE_DOCUMENT_VERSION
                and str(dense["model"] or "") == EPISODE_DENSE_DEFAULT_MODEL
                and int_value(dense["episode_document_count"]) == expected_count
                and int_value(dense["vector_count"]) == expected_count
                and stored_representation_document_count >= 0
                and stored_representation_count
                == stored_representation_document_count
                and str(dense["status"] or "") in {"current", "no_task_episodes"}
            )
            if is_current:
                current_count += 1
                vector_count += stored_vector_count
                representation_vector_count += max(
                    0,
                    stored_representation_count,
                )
                implicit_no_task_count += 1 if implicit_no_task else 0
            elif session_id:
                dirty.append(session_id)
        return {
            "status": (
                "disabled_unconfigured"
                if dirty and not enabled
                else "current"
                if source_rows and current_count == len(source_rows)
                else ("partial" if current_count else "empty")
            ),
            "enabled": enabled,
            "needs_refresh": bool(dirty) and enabled,
            "projection_dirty": bool(dirty),
            "projection_version": EPISODE_DENSE_PROJECTION_VERSION,
            "document_version": EPISODE_DENSE_DOCUMENT_VERSION,
            "model": EPISODE_DENSE_DEFAULT_MODEL,
            "generation_identity": expected_dense_generation_identity,
            "current_session_count": current_count,
            "source_session_count": len(source_rows),
            "vector_count": vector_count,
            "representation_vector_count": (
                representation_vector_count
            ),
            "implicit_no_task_session_count": implicit_no_task_count,
            "dirty_session_count": len(dirty),
            "dirty_session_ids": dirty,
            "provider": provider,
            "truth_status": "dense_state_compared_to_current_episode_projection",
            "diagnostics": [],
        }
    except sqlite3.Error as exc:
        status = sqlite_error_status(exc)
        return {
            "status": status,
            "enabled": enabled,
            "needs_refresh": status != "sqlite_locked" and enabled,
            "projection_dirty": False,
            "projection_version": EPISODE_DENSE_PROJECTION_VERSION,
            "document_version": EPISODE_DENSE_DOCUMENT_VERSION,
            "model": EPISODE_DENSE_DEFAULT_MODEL,
            "current_session_count": 0,
            "source_session_count": 0,
            "vector_count": 0,
            "representation_vector_count": 0,
            "implicit_no_task_session_count": 0,
            "dirty_session_count": 0,
            "dirty_session_ids": [],
            "provider": provider,
            "truth_status": "dense_state_unavailable_from_read_only_search_projection",
            "diagnostics": [sqlite_error_diagnostic(exc)],
        }
    finally:
        if conn is not None:
            conn.close()


EPISODE_SEMANTIC_FIELD_WEIGHTS = {
    "intents": 8.0,
    "plans": 2.0,
    "actions": 5.0,
    "outcomes": 7.0,
    "verification": 7.0,
    "failures": 8.0,
    "reasoning": 1.0,
    "narrative": 3.0,
    "anchors": 9.0,
}

EPISODE_SEMANTIC_SUPPORT_BASIS_WEIGHTS = {
    "verification_observation": 38.0,
    "assistant_final_closeout": 36.0,
    "assistant_decision": 36.0,
    "structured_compact_success_observation": 34.0,
    "assistant_observation": 32.0,
    "canonical_user_intent": 24.0,
    "canonical_user_replayed_intent": 34.0,
    "canonical_user_failure_observation": 34.0,
    "canonical_user_resume_request": 34.0,
    "canonical_user_correction": 34.0,
    "canonical_user_intent_from_raw_ref": 28.0,
    "structured_failed_result": 22.0,
    "bounded_episode_ref_raw_expansion": 16.0,
    "structured_operational_action": 14.0,
    "assistant_plan": 12.0,
    "structured_result_status": 8.0,
}

EPISODE_SEMANTIC_COHERENT_TERM_BONUS = 18.0


def episode_semantic_token_has_prefix(tokens: set[str], prefixes: tuple[str, ...]) -> bool:
    return any(token.startswith(prefix) for token in tokens for prefix in prefixes)


def episode_semantic_reading_intents(
    terms: list[dict[str, Any]],
    *,
    query_text: str = "",
) -> dict[str, bool]:
    query_tokens: set[str] = set()
    for term in terms:
        query_tokens.update(str(value).casefold() for value in term.get("exact", []) if value)
        query_tokens.update(str(value).casefold() for value in term.get("prefixes", []) if value)
    query_tokens.update(token.casefold() for token in search_tokenize(query_text))
    interaction_status = episode_semantic_token_has_prefix(
        query_tokens,
        ("interact", "взаимодейств"),
    )
    explicit_agent_activity = bool(
        episode_semantic_token_has_prefix(
            query_tokens,
            ("agent", "subagent", "агент", "субагент"),
        )
        and episode_semantic_token_has_prefix(
            query_tokens,
            ("activity", "активност", "деятельност"),
        )
    )
    agent_activity_status = bool(
        episode_semantic_token_has_prefix(query_tokens, ("status", "статус"))
        and (interaction_status or explicit_agent_activity)
    )
    return {
        "causal_explanation": bool(
            query_tokens & {"почему", "why", "how", "как"}
            or episode_semantic_token_has_prefix(query_tokens, ("причин", "cause", "because"))
        ),
        "prior_state": episode_semantic_token_has_prefix(
            query_tokens,
            ("уже", "стоя", "ран", "преж", "тогда", "prior", "before", "previous", "histor"),
        ),
        "negative_state": episode_semantic_token_has_prefix(
            query_tokens,
            ("хват", "отсутств", "недоступ", "missing", "absent", "without", "lack"),
        ),
        "failure_recovery": episode_semantic_token_has_prefix(
            query_tokens,
            (
                "убил", "заверш", "ошиб", "сбой", "восстанов", "перезапуск",
                "завис", "продолж", "возобнов", "stall", "hang", "hung",
                "fail", "error", "recover", "restart", "relaunch", "resume", "continue", "safer", "successful",
            ),
        ),
        "agent_activity_status": agent_activity_status,
    }


def episode_semantic_support_collision_reason(
    item: dict[str, Any],
    *,
    reading_intents: dict[str, bool],
) -> str:
    """Reject a broad lexical token when the query names a stronger typed status."""
    if not reading_intents.get("agent_activity_status"):
        return ""
    if str(item.get("admission_basis") or "") == "structured_correlated_status":
        return ""
    matches = {
        str(token).casefold()
        for token in (
            item.get("matched_query_terms")
            if isinstance(item.get("matched_query_terms"), list)
            else []
        )
        if token
    }
    if matches and all(token.startswith(("status", "статус")) for token in matches):
        return "generic_status_token_outside_structured_agent_activity"
    return ""


def episode_semantic_support_reading_score(
    item: dict[str, Any],
    *,
    matched_term_count: int,
    reading_intents: dict[str, bool],
    event_range: dict[str, Any],
) -> tuple[float, list[str]]:
    text_tokens = episode_semantic_field_tokens(item.get("text"))
    text_tokens.update(
        str(token).casefold()
        for token in (
            item.get("semantic_signal_terms")
            if isinstance(item.get("semantic_signal_terms"), list)
            else []
        )
        if token
    )
    basis = str(item.get("admission_basis") or "")
    role = str(item.get("role") or "")
    score = matched_term_count * 24.0
    score += EPISODE_SEMANTIC_SUPPORT_BASIS_WEIGHTS.get(basis, 10.0)
    score += EPISODE_SEMANTIC_FIELD_WEIGHTS.get(role, 0.0)
    signals: list[str] = []
    if reading_intents.get("prior_state"):
        if episode_semantic_token_has_prefix(
            text_tokens,
            ("уже", "пока", "тогда", "ранее", "прежде", "prior", "before", "previous", "currently"),
        ):
            score += 48.0
            signals.append("prior_state_marker")
        from_line = int_value(event_range.get("from_line"))
        to_line = int_value(event_range.get("to_line"))
        line = int_value(item.get("line"))
        if from_line > 0 and to_line > from_line and from_line <= line <= to_line:
            phase = (line - from_line) / (to_line - from_line)
            score += max(0.0, 28.0 * (1.0 - phase))
            signals.append("prior_state_timeline_bias")
    if reading_intents.get("negative_state") and episode_semantic_token_has_prefix(
        text_tokens,
        ("отсутств", "недоступ", "нет", "missing", "absent", "unavailable", "without"),
    ):
        score += 56.0
        signals.append("negative_state_marker")
    if reading_intents.get("causal_explanation"):
        causal_marker = episode_semantic_token_has_prefix(
            text_tokens,
            (
                "потому", "поэтому", "причин", "из-за", "игнор", "следств",
                "because", "therefore", "cause", "caused", "ignored", "hence",
            ),
        )
        if causal_marker:
            score += 64.0
            signals.append("causal_explanation_marker")
    if reading_intents.get("failure_recovery"):
        failure_marker = episode_semantic_token_has_prefix(
            text_tokens,
            ("pkill", "kill", "self", "убил", "заверш", "совпад", "fail", "error", "ошиб", "сбой", "stall", "hang", "hung", "завис"),
        )
        recovery_marker = episode_semantic_token_has_prefix(
            text_tokens,
            (
                "recover", "restart", "relaunch", "launch", "safe", "success", "succeed", "captur",
                "resume", "continue", "continued", "восстанов", "перезапуск", "запуск", "продолж", "возобнов", "аккурат", "безопас", "успеш", "фильтр",
            ),
        )
        if role == "failures":
            score += 64.0
            signals.append("failure_role_for_recovery_query")
        if failure_marker:
            score += 42.0
            signals.append("failure_marker")
        if recovery_marker:
            score += 34.0
            signals.append("recovery_marker")
    return score, signals


EPISODE_OPERATIONAL_GROUP_CARDINALITY_WORDS = {
    "два": 2,
    "две": 2,
    "три": 3,
    "четыре": 4,
    "пять": 5,
    "шесть": 6,
    "семь": 7,
    "восемь": 8,
    "девять": 9,
    "десять": 10,
    "two": 2,
    "three": 3,
    "four": 4,
    "five": 5,
    "six": 6,
    "seven": 7,
    "eight": 8,
    "nine": 9,
    "ten": 10,
}


def episode_delegated_lifecycle_query(query: str) -> dict[str, Any]:
    """Parse structural delegated-task lifecycle questions.

    NEW_TASK is a transport/delegation marker.  An arrow between lifecycle
    states denotes an ordered path, not causality, and repeated task names do
    not establish replay or semantic identity.
    """

    text = str(query or "").strip()
    lowered = text.casefold()
    tokens = [token.casefold() for token in search_tokenize(text)]
    lifecycle_markers = bool(
        re.search(
            r"\b(?:new_task|task_started|task_complete)\b",
            lowered,
        )
        or (
            any(token.startswith(("delegat", "делегир", "задач")) for token in tokens)
            and any(token.startswith(("fork", "agent", "агент")) for token in tokens)
        )
    )
    if not lifecycle_markers:
        return {
            "active": False,
            "status": "not_a_delegated_lifecycle_query",
        }
    requested_cardinality = 0
    cardinality_token = ""
    for token in tokens:
        if token.isdigit() and 1 <= int(token) <= 100:
            requested_cardinality = int(token)
            cardinality_token = token
            break
        mapped = EPISODE_OPERATIONAL_GROUP_CARDINALITY_WORDS.get(token)
        if mapped:
            requested_cardinality = mapped
            cardinality_token = token
            break
    semantic_identity = bool(
        re.search(r"\breplay(?:ed|ing)?\b", lowered)
        or any(
            token.startswith(
                (
                    "одинаков",
                    "повтор",
                    "переигр",
                    "дубликат",
                    "тождеств",
                    "same",
                    "identical",
                    "duplicate",
                )
            )
            for token in tokens
        )
        or "одно задание" in lowered
        or "same task" in lowered
    )
    count_requested = bool(
        requested_cardinality
        or any(
            token.startswith(("сколько", "count", "количеств"))
            for token in tokens
        )
    )
    ordered_path = bool(
        "->" in text
        or "→" in text
        or any(
            token.startswith(("путь", "цепоч", "последоват", "path", "sequence"))
            for token in tokens
        )
    )
    mode = (
        "semantic_identity"
        if semantic_identity
        else "count"
        if count_requested
        else "ordered_path"
        if ordered_path
        else "structural_lookup"
    )
    target_match = re.search(
        r"(?<![A-Za-z0-9_.-])(/root/[A-Za-z0-9_.-]+)",
        text,
    )
    target = str(target_match.group(1) if target_match else "")
    retrieval_text = (
        "inter agent NEW_TASK delegation task_started task_complete "
        "local fork work"
    )
    return {
        "active": True,
        "status": "delegated_lifecycle_query_parsed",
        "mode": mode,
        "requested_cardinality": requested_cardinality,
        "cardinality_token": cardinality_token,
        "target": target,
        "ordered_path_requested": ordered_path,
        "semantic_identity_requested": semantic_identity,
        "claim_boundary": (
            "structural lifecycle identity is distinct from semantic task "
            "identity or replay"
        ),
        "retrieval_query_text": retrieval_text,
        "retrieval_terms": episode_semantic_query_terms(retrieval_text),
        "retrieval_term_basis": "typed_delegated_lifecycle_structure",
    }


def episode_operational_group_query(query: str) -> dict[str, Any]:
    text = str(query or "").strip()
    tokens = [token.casefold() for token in search_tokenize(text)]
    parallel = any(
        token in {"parallel", "concurrently", "simultaneously", "параллельно", "одновременно"}
        or token.startswith("параллель")
        for token in tokens
    )
    read_intent = any(
        token in {"read", "reading", "reads", "читали", "прочитали", "чтение"}
        or token.startswith("чита")
        for token in tokens
    )
    requested_cardinality = 0
    cardinality_token = ""
    for token in tokens:
        if token.isdigit() and 2 <= int(token) <= EPISODE_OPERATIONAL_GROUP_MAX_MEMBERS:
            requested_cardinality = int(token)
            cardinality_token = token
            break
        mapped = EPISODE_OPERATIONAL_GROUP_CARDINALITY_WORDS.get(token)
        if mapped:
            requested_cardinality = mapped
            cardinality_token = token
            break
    if not parallel or not read_intent or requested_cardinality < 2:
        return {"active": False, "status": "not_an_operational_group_query"}
    query_frames = re.split(
        r"\b(?:перед|до|before|prior\s+to)\b",
        text,
        maxsplit=1,
        flags=re.IGNORECASE,
    )
    subject_frame = query_frames[0]
    context_text = query_frames[1].strip(" `\"'.,;:") if len(query_frames) > 1 else ""
    removable = {
        "где",
        "where",
        "parallel",
        "concurrently",
        "simultaneously",
        "параллельно",
        "одновременно",
        "read",
        "reading",
        "reads",
        "читали",
        "прочитали",
        "чтение",
        cardinality_token,
    }
    subject_text = " ".join(
        token
        for token in search_tokenize(subject_frame)
        if token.casefold() not in removable
    )
    subject_terms = episode_semantic_query_terms(subject_text)
    if not subject_terms:
        return {"active": False, "status": "operational_group_subject_empty"}
    context_terms = episode_semantic_query_terms(context_text)
    retrieval_terms: list[dict[str, Any]] = []
    seen_retrieval_terms: set[str] = set()
    for term in [*subject_terms, *context_terms]:
        token = str(term.get("token") or "")
        if not token or token in seen_retrieval_terms:
            continue
        seen_retrieval_terms.add(token)
        retrieval_terms.append(term)
    return {
        "active": True,
        "status": "parallel_operational_group_parsed",
        "relation_basis": "explicit_parallel_cardinality",
        "requested_cardinality": requested_cardinality,
        "operation": "read",
        "subject_text": subject_text,
        "subject_terms": subject_terms,
        "context_text": context_text,
        "context_terms": context_terms,
        "retrieval_terms": retrieval_terms,
        "retrieval_query_text": " ".join(
            str(term.get("token") or "") for term in retrieval_terms
        ),
        "retrieval_term_basis": "typed_subject_plus_context_without_relation_words",
    }


EPISODE_QUANTITATIVE_COMPARISON_MAX_RAW_BYTES = 32 * 1024 * 1024
EPISODE_QUANTITATIVE_COMPARISON_MAX_LINES = 100_000
EPISODE_QUANTITATIVE_COMPARISON_MAX_ACTIONS = 256
EPISODE_QUANTITATIVE_COMPARISON_MAX_CHAINS = 8
