        "компонент",
        "модули",
        "модуль",
        "сильнее",
        "больше",
        "чаще",
        "меньше",
        "всего",
        "изменились",
        "изменился",
        "изменилась",
        "изменилось",
        "были",
        "был",
        "была",
        "было",
        "длиннее",
        "короче",
        "после",
        "what",
        "which",
        "parts",
        "part",
        "sections",
        "section",
        "components",
        "component",
        "modules",
        "module",
        "most",
