def episode_quantitative_comparison_query(query: str) -> dict[str, Any]:
    """Parse a bounded comparative question that needs measured result rows.

    A phrase such as ``which parts changed most`` is not answerable from
    lexical episode similarity alone.  It requires one structured counting
    action and its correlation-owned numeric result.  Keep the parser narrow
    so ordinary mentions of versions, parts, or changes do not activate the
    relation gate.
    """
    text = str(query or "").strip()
    tokens = [token.casefold() for token in search_tokenize(text)]
    question = any(
        token in {"какие", "какой", "какая", "какое", "what", "which"}
        for token in tokens
    )
    ranked_change_comparison = any(
        token in {
            "сильнее",
            "больше",
            "чаще",
            "меньше",
            "most",
            "least",
            "highest",
            "lowest",
            "largest",
            "smallest",
            "top",
        }
        or token.startswith(("наибольш", "максим", "миним"))
        for token in tokens
    )
    length_comparison = any(
        token in {"longer", "shorter"}
        or token.startswith(("длин", "короч"))
        for token in tokens
    )
    change_intent = any(
        token.startswith(("измен", "changed", "change", "diff"))
        for token in tokens
    )
    measured_object = any(
        token in {
            "части",
            "часть",
            "разделы",
            "раздел",
            "компоненты",
            "компонент",
            "модули",
            "модуль",
            "parts",
            "part",
            "sections",
            "section",
            "components",
            "component",
            "modules",
            "module",
            "files",
            "file",
        }
        for token in tokens
    )
    named_file_subject = bool(
        re.search(
            r"(?<![\w.-])[\w.+-]+\.[A-Za-z0-9]{1,12}(?![\w.-])",
            text,
        )
    )
    ranked_change_query = bool(
        ranked_change_comparison
        and change_intent
        and measured_object
    )
    length_query = bool(
        length_comparison
        and (measured_object or named_file_subject)
    )
    if not (question and (ranked_change_query or length_query)):
        return {
            "active": False,
            "status": "not_a_quantitative_comparison_query",
        }

    subject_text = ""
    context_text = ""
    if length_query:
        length_subject_match = re.search(
            r"\b(?:какие|какой|какая|какое|which|what)\s+"
            r"(?P<subject>.+?)\s+"
            r"(?:(?:были|был|была|было|were|was)\s+)?"
            r"(?:длиннее|короче|longer|shorter)\b",
            text,
            flags=re.IGNORECASE,
        )
        if length_subject_match:
            subject_text = length_subject_match.group("subject").strip(
                " `\"'.,;:"
            )
    else:
        english_prefix_match = re.search(
            r"\b(?P<subject>[A-Za-z0-9_.:/+-]+)\s+"
            r"(?:parts|sections|components|modules)"
            r"(?:\s+in\s+(?P<context>.+?))?"
            r"(?=\s+(?:changed|changes|change)\s+"
            r"(?:most|least|highest|lowest|largest|smallest|top)\b)",
            text,
            flags=re.IGNORECASE,
        )
        subject_context_match = re.search(
            r"\b(?:части|разделы|компоненты|модули|parts|sections|components|modules)"
            r"(?:\s+of)?\s+(?P<subject>.+?)\s+(?:в|in)\s+(?P<context>.+?)"
            r"(?=\s+(?:(?:changed|changes|change)\s+)?"
            r"(?:сильнее|больше|чаще|меньше|most|least|highest|lowest|"
            r"largest|smallest|top)\b)",
            text,
            flags=re.IGNORECASE,
        )
        if english_prefix_match:
            subject_text = english_prefix_match.group("subject").strip(
                " `\"'.,;:"
            )
            context_text = str(
                english_prefix_match.group("context") or ""
            ).strip(" `\"'.,;:")
        elif subject_context_match:
            subject_text = subject_context_match.group("subject").strip(
                " `\"'.,;:"
            )
            context_text = subject_context_match.group("context").strip(
                " `\"'.,;:"
            )
        else:
            subject_match = re.search(
                r"\b(?:части|разделы|компоненты|модули|parts|sections|components|modules)"
                r"(?:\s+of)?\s+(?P<subject>.+?)"
                r"(?=\s+(?:(?:changed|changes|change)\s+)?"
                r"(?:сильнее|больше|чаще|меньше|most|least|highest|lowest|"
                r"largest|smallest|top|после|after|since)\b)",
                text,
                flags=re.IGNORECASE,
            )
            if subject_match:
                subject_text = subject_match.group("subject").strip(
                    " `\"'.,;:"
                )

    baseline_match = re.search(
        r"\b(?:после|after|since)\s+(?P<baseline>.+?)\s*[?!.]*$",
        text,
        flags=re.IGNORECASE,
    )
    baseline_text = (
        baseline_match.group("baseline").strip(" `\"'.,;:")
        if baseline_match
        else ""
    )
    subject_terms = episode_semantic_query_terms(subject_text)
    context_terms = episode_semantic_query_terms(context_text)
    baseline_terms = episode_semantic_query_terms(baseline_text)
    if not subject_terms:
        fallback_terms = episode_semantic_query_terms(text)
        subject_terms = [
            term
            for term in fallback_terms
            if str(term.get("token") or "").casefold()
            not in EPISODE_QUANTITATIVE_COMPARISON_META_TOKENS
            and not str(term.get("token") or "").isdigit()
        ][:4]
    if not subject_terms:
        return {
            "active": False,
            "status": "quantitative_comparison_subject_empty",
        }
    return {
        "active": True,
        "status": "quantitative_comparison_parsed",
        "relation_basis": (
            "line_count_comparison_requires_correlated_numeric_result"
            if length_query
            else "ranked_change_count_requires_correlated_numeric_result"
        ),
        "operation": (
            "line_count"
            if length_query
            else "change_count"
        ),
        "direction": (
            "ascending"
            if any(
                token in {
                    "меньше",
                    "least",
                    "lowest",
                    "smallest",
                    "shorter",
                }
                or token.startswith(("миним", "короч"))
                for token in tokens
            )
            else "descending"
        ),
        "subject_text": subject_text,
        "context_text": context_text,
        "baseline_text": baseline_text,
        "subject_terms": subject_terms,
        "context_terms": context_terms,
        "baseline_terms": baseline_terms,
    }


def episode_temporal_left_source_profile(text: Any) -> dict[str, str]:
    """Bind an actor-framed antecedent to the matching message lane.

    An operational result can display documentation or a prior record that
    repeats the same words.  When the query explicitly attributes the
    antecedent to the agent or user, that displayed text is not compatible
    evidence for the requested temporal relation.
    """
    lowered = str(text or "").casefold()
    if episode_temporal_exact_anchor_identifiers(lowered):
        return {
            "policy": "any_evidence_lane",
            "expected_message_role": "",
        }
    if re.search(r"\b(?:agent|assistant|агент\w*|ассистент\w*)\b", lowered):
        return {
            "policy": "canonical_message_role_required",
            "expected_message_role": "assistant",
        }
    if re.search(r"\b(?:user|operator|пользовател\w*|оператор\w*)\b", lowered):
        return {
            "policy": "canonical_message_role_required",
            "expected_message_role": "user",
        }
    return {
        "policy": "any_evidence_lane",
        "expected_message_role": "",
    }


def episode_temporal_action_sequence_requirements(text: Any) -> list[str]:
    """Extract explicitly asserted action-result stages in query order."""
    value = str(text or "")
    stage_patterns = {
        "discovery": re.compile(
            r"\b(?:наш(?:ли|ёл|ел|ла|ло)|найден\w*|обнаруж\w*|выяв\w*|"
            r"found|discover\w*|locat\w*|identif(?:y|ied|ies))\b",
            flags=re.IGNORECASE,
        ),
        "mutation": re.compile(
            r"\b(?:удал(?:ил\w*|ён\w*|ен\w*)|убра(?:л\w*|н\w*)|"
            r"очист(?:ил\w*|или)|очищен\w*|"
            r"removed?|delet(?:ed|ion)|cleaned|purged)\b",
            flags=re.IGNORECASE,
        ),
        "verification": re.compile(
            r"\b(?:провер(?:ил\w*|ен\w*)|перепровер\w*|"
            r"подтверд(?:ил\w*)|подтвержд(?:ен\w*)|"
            r"verified|checked|confirmed)\b",
            flags=re.IGNORECASE,
        ),
    }
    matches: list[tuple[int, str]] = []
    for stage, pattern in stage_patterns.items():
        match = pattern.search(value)
        if match is not None:
            matches.append((match.start(), stage))
    matches.sort()
    return list(dict.fromkeys(stage for _position, stage in matches))


def episode_temporal_left_candidate_allowed(
    anchor: dict[str, Any],
    temporal_span: dict[str, Any],
) -> bool:
    policy = str(
        temporal_span.get("left_source_policy") or "any_evidence_lane"
    )
    if policy != "canonical_message_role_required":
        return True
    kind = str(anchor.get("kind") or anchor.get("event_kind") or "")
    source_lane = str(anchor.get("source_lane") or "")
    if kind and kind != "canonical_message_observation":
        return False
    if not kind and not source_lane.startswith("message_"):
        return False
    expected_role = str(
        temporal_span.get("left_expected_message_role") or ""
    )
    observed_role = str(anchor.get("message_role") or "")
    if not observed_role and source_lane.startswith("message_"):
        observed_role = source_lane.removeprefix("message_")
    return not expected_role or observed_role == expected_role


def episode_temporal_operational_action_stages(command: Any) -> list[str]:
    """Classify bounded structured commands for multi-stage temporal proof."""
    lowered = str(command or "").casefold()
    if not lowered:
        return []
    stages: list[str] = []
    mutation_signal = bool(
        re.search(
            r"(?:^|[\n;&|]\s*)(?:sudo\s+)?(?:rm|rmdir|unlink)\b",
            lowered,
        )
        or re.search(r"\bfind\b[^\n]*(?:-delete|-exec\s+rm\b)", lowered)
        or re.search(r"(?:^|[\n;&|]\s*)apply_patch\b", lowered)
    )
    inspection_signal = bool(
        re.search(
            r"(?:^|[\n;&|]\s*)(?:sudo\s+)?"
            r"(?:rg|grep|find|ls|tree|stat|test|jq|sed|cat|head|tail|wc)\b",
            lowered,
        )
    )
    if mutation_signal:
        stages.append("mutation")
    if inspection_signal and not mutation_signal:
        # A read after a mutation can be verification; the ordered sequence
        # builder decides whether this occurrence is the initial discovery or
        # the later verification.
        stages.extend(("discovery", "verification"))
    return stages


def episode_temporal_quoted_anchor_pair(
    text: str,
) -> tuple[str, str] | None:
    """Return two explicit quoted anchors without treating framing words as evidence."""
    matches = re.findall(
        r'"([^"]{1,})"|\'([^\']{1,})\'|«([^»]{1,})»|“([^”]{1,})”',
        str(text or ""),
    )
    anchors = [
        next(
            (
                str(candidate).strip()
                for candidate in match
                if str(candidate).strip()
            ),
            "",
        )
        for match in matches
    ]
    anchors = [anchor for anchor in anchors if anchor]
    if len(anchors) < 2:
        return None
    return anchors[0], anchors[1]


def episode_temporal_span_query(query: str) -> dict[str, Any]:
    text = str(query or "").strip()
    after_clause_match = re.search(
        r"^(?:(?:где|where|что\s+(?:произошло|было|сделали)|"
        r"what\s+(?:happened|occurred|was\s+done))\s+)?"
        r"(?:после\s+того\s+как|after)\s+(.+?)[,;]\s+(.+)$",
        text,
        flags=re.IGNORECASE,
    )
    if after_clause_match:
        left_text = after_clause_match.group(1).strip(" `\"'.,;:")
        right_text = after_clause_match.group(2).strip(" `\"'.,;:")
        right_has_event_motion = bool(
            re.search(
                r"\b(?:потребовал\w*|переш\w*|исправ\w*|наш\w*|удал\w*|"
                r"очист\w*|провер\w*|выполн\w*|запуст\w*|обнов\w*|"
                r"demand\w*|switch\w*|fix\w*|found|remov\w*|clean\w*|"
                r"verif\w*|check\w*|execut\w*|run|ran|start\w*|updat\w*)\b",
                right_text,
                flags=re.IGNORECASE,
            )
        )
        left_terms = episode_semantic_query_terms(left_text)
        right_terms = episode_semantic_query_terms(right_text)
        if left_terms and right_terms and right_has_event_motion:
            left_source_profile = episode_temporal_left_source_profile(left_text)
            action_requirements = episode_temporal_action_sequence_requirements(
                right_text
            )
            return {
                "active": True,
                "status": "temporal_after_clause_anchors_parsed",
                "left_text": left_text,
                "right_text": right_text,
                "left_terms": left_terms,
                "right_terms": right_terms,
                "left_source_policy": left_source_profile["policy"],
                "left_expected_message_role": left_source_profile[
                    "expected_message_role"
                ],
                "right_action_requirements": action_requirements,
                "right_action_sequence_required": len(action_requirements) >= 2,
                "temporal_intent_basis": "explicit_after_clause_relation",
                "answer_scope": "ordered_relation",
            }
    after_match = re.search(
        r"^(?:(?:где|where|что\s+(?:произошло|было|сделали)|"
        r"what\s+(?:happened|occurred|was\s+done))\s+)?(?:после|after)\s+(.+?)\s+"
        r"((?:запускали|запустили|запускался|запускалась|запускалось|запускались|"
        r"переэкспортировали|экспортировали|перестраивали|перестроили|"
        r"проверили|перепроверили|выполнили|вызвали|прочитали|создали|обновили|"
        r"исправили|нашли|удалили|очистили|"
        r"перезапустили|ran|started|launched|re-?exported|exported|rebuilt|"
        r"verified|checked|executed|called|read(?![-_/])|created|updated|restarted)\b.+)$",
        text,
        flags=re.IGNORECASE,
    )
    if after_match:
        left_text = after_match.group(1).strip(" `\"'.,;:")
        right_text = after_match.group(2).strip(" `\"'.,;:")
        left_terms = episode_semantic_query_terms(left_text)
        right_terms = episode_semantic_query_terms(right_text)
        if not left_terms or not right_terms:
            return {"active": False, "status": "temporal_span_anchor_empty"}
        left_source_profile = episode_temporal_left_source_profile(left_text)
        action_requirements = episode_temporal_action_sequence_requirements(
            right_text
        )
        return {
            "active": True,
            "status": "temporal_after_anchors_parsed",
            "left_text": left_text,
            "right_text": right_text,
            "left_terms": left_terms,
            "right_terms": right_terms,
            "left_source_policy": left_source_profile["policy"],
            "left_expected_message_role": left_source_profile[
                "expected_message_role"
            ],
            "right_action_requirements": action_requirements,
            "right_action_sequence_required": len(action_requirements) >= 2,
            "temporal_intent_basis": "explicit_after_action_relation",
            "answer_scope": "ordered_relation",
        }
    match = re.search(
        r"(?:\bbetween\b|\bмежду\b)\s+(.+?)\s+(?:\band\b|\bи\b)\s+(.+)$",
        text,
        flags=re.IGNORECASE,
    )
    if not match:
        return {"active": False, "status": "not_a_temporal_span_query"}
    head_text = text[: match.start()].strip()
    query_date_match = re.search(
        r"(?<!\d)(20\d{2}-[01]\d-[0-3]\d)(?!\d)",
        head_text,
    )
    query_date = str(query_date_match.group(1) if query_date_match else "")
    query_time_scope: dict[str, str] = {}
    if query_date:
        try:
            query_date_start = datetime.strptime(
                query_date,
                "%Y-%m-%d",
            ).replace(tzinfo=timezone.utc)
        except ValueError:
            return {
                "active": True,
                "status": "invalid_temporal_query_date",
                "query_date": query_date,
                "temporal_intent_basis": "explicit_event_frame",
            }
        query_date_end = (
            query_date_start
            + timedelta(days=1)
            - timedelta(microseconds=1)
        )
        query_time_scope = {
            "query_date": query_date,
            "query_time_from": query_date_start.isoformat(
                timespec="microseconds"
            ).replace("+00:00", "Z"),
            "query_time_to": query_date_end.isoformat(
                timespec="microseconds"
            ).replace("+00:00", "Z"),
            "query_time_basis": "explicit_event_frame_date",
        }
    explicit_event_frame = bool(
        re.search(
            r"(?:what\s+(?:happened|occurred|changed)|"
            r"что\s+(?:произошло|происходило|было|случилось|шло|изменилось|поменялось))"
            r"(?:\s+(?:(?:on|в)\s+)?\d{4}-\d{2}-\d{2})?\s*$",
            head_text,
            flags=re.IGNORECASE,
        )
    )
    head_tail = " ".join(search_tokenize(head_text)[-5:])
    bounded_interval_head = bool(
        re.search(
            r"(?:events?|commands?|steps?|observations?|actions?|changes?|timeline|period|interval|"
            r"событи\w*|команд\w*|шаг\w*|наблюдени\w*|действи\w*|изменени\w*|период\w*|интервал\w*)",
            head_tail,
            flags=re.IGNORECASE,
        )
    )
    comparison_head = bool(
        re.search(
            r"(?:difference|distinction|mismatch|relationship|comparison|"
            r"разниц\w*|различи\w*|рассинхрон\w*|связ\w*|сравнени\w*)",
            head_tail,
            flags=re.IGNORECASE,
        )
    )
    if not explicit_event_frame and (not bounded_interval_head or comparison_head):
        return {
            "active": False,
            "status": "between_relation_without_temporal_interval_intent",
            "head_text": head_text,
        }
    quoted_anchor_pair = episode_temporal_quoted_anchor_pair(
        text[match.start():]
    )
    if quoted_anchor_pair is not None:
        left_text, right_text = quoted_anchor_pair
        anchor_parse_basis = "explicit_quoted_anchor_pair"
        quoted_anchor_source_policy = (
            "canonical_message_required"
            if re.search(
                r"\b(?:messages?|сообщени\w*)\b",
                text[match.start():],
                flags=re.IGNORECASE,
            )
            else "any_evidence_lane"
        )
    else:
        left_text = match.group(1).strip(" `\"'.,;:")
        right_text = match.group(2).strip(" `\"'.,;:")
        anchor_parse_basis = "between_connector_spans"
        quoted_anchor_source_policy = "not_applicable"
    left_terms = episode_semantic_query_terms(left_text)
    right_terms = episode_semantic_query_terms(right_text)
    if not left_terms or not right_terms:
        return {"active": False, "status": "temporal_span_anchor_empty"}
    return {
        "active": True,
        "status": "temporal_span_anchors_parsed",
        "left_text": left_text,
        "right_text": right_text,
        "anchor_parse_basis": anchor_parse_basis,
        "left_match_policy": (
            "normalized_exact_phrase"
            if quoted_anchor_pair is not None
            else "semantic_term_coverage"
        ),
        "right_match_policy": (
            "normalized_exact_phrase"
            if quoted_anchor_pair is not None
            else "semantic_term_coverage"
        ),
        "quoted_anchor_source_policy": quoted_anchor_source_policy,
        "left_terms": left_terms,
        "right_terms": right_terms,
        "left_source_policy": "any_evidence_lane",
        "left_expected_message_role": "",
        "right_action_requirements": [],
        "right_action_sequence_required": False,
        "temporal_intent_basis": (
            "explicit_event_frame" if explicit_event_frame else "bounded_interval_head"
        ),
        "answer_scope": "interval_contents",
        **query_time_scope,
    }


def episode_temporal_span_evidence(
    episode: dict[str, Any],
    temporal_span: dict[str, Any],
) -> dict[str, Any]:
    if not temporal_span.get("active"):
        return {"active": False, "status": str(temporal_span.get("status") or "not_requested"), "ranking_boost": 0.0}
    representations = episode.get("representations") if isinstance(episode.get("representations"), dict) else {}

    def candidates_for(terms: list[dict[str, Any]]) -> list[dict[str, Any]]:
        candidates: list[dict[str, Any]] = []
        for role, items in representations.items():
            for item in items if isinstance(items, list) else []:
                if not isinstance(item, dict):
                    continue
                tokens = episode_semantic_field_tokens(item.get("text"))
                matches = [
                    str(term.get("token") or "")
                    for term in terms
                    if episode_semantic_term_matches_tokens(term, tokens)
                ]
                if not matches:
                    continue
                coverage = len(set(matches)) / len(terms)
                refs = item.get("refs") if isinstance(item.get("refs"), dict) else {}
                candidates.append(
                    {
                        "role": str(role),
                        "line": int_value(item.get("line") or line_from_raw_ref(refs.get("raw"))),
                        "coverage": coverage,
                        "matched_query_terms": sorted(set(matches)),
                        "text": short_text(str(item.get("text") or ""), max_chars=500),
                        "source_lane": str(item.get("source_lane") or ""),
                        "admission_basis": str(item.get("admission_basis") or ""),
                        "event_type": str(item.get("event_type") or ""),
                        "correlation_id": str(item.get("correlation_id") or ""),
                        "refs": {
                            "raw": str(refs.get("raw") or ""),
                            "segment": str(refs.get("segment") or ""),
                            "segment_index": str(refs.get("segment_index") or ""),
                            "session": str(refs.get("session") or ""),
                        },
                    }
                )
        candidates.sort(
            key=lambda item: (
                -float(item.get("coverage") or 0.0),
                -len(item.get("matched_query_terms", [])),
                -EPISODE_SEMANTIC_FIELD_WEIGHTS.get(str(item.get("role") or ""), 0.0),
                int_value(item.get("line")),
            )
        )
        return candidates[:24]

    left_candidates = [
        candidate
        for candidate in candidates_for(temporal_span.get("left_terms", []))
        if episode_temporal_left_candidate_allowed(candidate, temporal_span)
    ]
    right_candidates = candidates_for(temporal_span.get("right_terms", []))
    ordered_pairs: list[tuple[tuple[float, float, float, int], dict[str, Any], dict[str, Any]]] = []
    for left in left_candidates:
        for right in right_candidates:
            left_line = int_value(left.get("line"))
            right_line = int_value(right.get("line"))
            if left_line <= 0 or right_line <= left_line:
                continue
            left_coverage = float(left.get("coverage") or 0.0)
            right_coverage = float(right.get("coverage") or 0.0)
            minimum_coverage = min(left_coverage, right_coverage)
            average_coverage = (left_coverage + right_coverage) / 2.0
            ordered_pairs.append(
                (
                    (minimum_coverage, average_coverage, left_coverage + right_coverage, -(right_line - left_line)),
                    left,
                    right,
                )
            )
    if not ordered_pairs:
        return {
            "active": True,
            "status": "temporal_span_unresolved_or_unordered",
            "ranking_boost": 0.0,
            "left_candidate_count": len(left_candidates),
            "right_candidate_count": len(right_candidates),
        }
    ordered_pairs.sort(key=lambda item: item[0], reverse=True)
    _quality, left, right = ordered_pairs[0]
    left_coverage = float(left.get("coverage") or 0.0)
    right_coverage = float(right.get("coverage") or 0.0)
    minimum_coverage = min(left_coverage, right_coverage)
    admission_basis = ""
    if minimum_coverage >= EPISODE_TEMPORAL_SPAN_MIN_ANCHOR_COVERAGE:
        admission_basis = "full_anchor_coverage"
    else:
        right_source_lane = str(right.get("source_lane") or "")
        right_admission_basis = str(right.get("admission_basis") or "")
        distance_lines = int_value(right.get("line")) - int_value(left.get("line"))
        combined_match_count = len(left.get("matched_query_terms", [])) + len(
            right.get("matched_query_terms", [])
        )
        combined_term_count = len(temporal_span.get("left_terms", [])) + len(
            temporal_span.get("right_terms", [])
        )
        combined_coverage = (
            combined_match_count / combined_term_count if combined_term_count else 0.0
        )
        right_is_structured = bool(
            right_source_lane in {"structured_tool_call", "structured_tool_result"}
            or right_admission_basis.startswith("structured_")
        )
        adjacent_structured_partial = bool(
            temporal_span.get("temporal_intent_basis") == "explicit_after_action_relation"
            and minimum_coverage >= 0.5
            and len(left.get("matched_query_terms", [])) >= 2
            and len(right.get("matched_query_terms", [])) >= 2
            and combined_coverage >= EPISODE_TEMPORAL_SPAN_MIN_ANCHOR_COVERAGE
            and 0 < distance_lines <= EPISODE_TEMPORAL_SCOPED_RAW_ADJACENT_MAX_DISTANCE_LINES
            and right_is_structured
        )
        if adjacent_structured_partial:
            admission_basis = "adjacent_structured_partial_lexical_coverage"
    accepted = bool(admission_basis)
    ranking_boost = (80.0 * minimum_coverage) + (30.0 * ((left_coverage + right_coverage) / 2.0)) + 20.0 if accepted else 0.0
    return {
        "active": True,
        "status": "ordered_span_found" if accepted else "ordered_span_below_anchor_coverage",
        "accepted": accepted,
        "admission_basis": admission_basis,
        "ranking_boost": round(ranking_boost, 4),
        "minimum_anchor_coverage": round(minimum_coverage, 4),
        "left": left,
        "right": right,
        "distance_lines": int_value(right.get("line")) - int_value(left.get("line")),
        "authority": "generated_episode_refs_require_raw_verification",
    }


EPISODE_TEMPORAL_RAW_CALL_TYPES = frozenset(
    {"function_call", "tool_call", "custom_tool_call"}
)
EPISODE_TEMPORAL_RAW_RESULT_TYPES = frozenset(
    {"function_call_output", "tool_call_output", "custom_tool_call_output"}
)
EPISODE_TEMPORAL_RAW_MCP_RECEIPT_TYPES = frozenset(
    {"mcp_tool_call_end"}
)
EPISODE_TEMPORAL_RAW_DIRECT_EVENT_TYPES = frozenset({"task_complete"})
EPISODE_TEMPORAL_RAW_STATUS_EVENT_TYPES = frozenset(
    {"patch_apply_end", "sub_agent_activity"}
)
EPISODE_TEMPORAL_RAW_IDENTIFIER_RE = re.compile(
    r"\b(?:call[_-][A-Za-z0-9_-]{6,}|"
    r"[A-Za-z][A-Za-z0-9]*(?:[-_][A-Za-z0-9]+)+|"
    r"[0-9A-Fa-f]{12,}|\d{9,})\b"
)


def episode_temporal_raw_anchor_identifiers(text: Any) -> list[str]:
    identifiers = list(
        dict.fromkeys(
            match.group(0).casefold()
            for match in EPISODE_TEMPORAL_RAW_IDENTIFIER_RE.finditer(str(text or ""))
        )
    )
    strong_identifiers = [
        identifier
        for identifier in identifiers
        if re.fullmatch(
            r"(?:call[_-][a-z0-9_-]{6,}|[0-9a-f]{12,}|\d{9,})",
            identifier,
            flags=re.IGNORECASE,
        )
    ]
    return strong_identifiers or identifiers


def episode_temporal_exact_anchor_identifiers(text: Any) -> list[str]:
    return [
        identifier
        for identifier in (
            match.group(0).casefold()
            for match in EPISODE_TEMPORAL_RAW_IDENTIFIER_RE.finditer(
                str(text or "")
            )
        )
        if re.fullmatch(
            r"(?:call[_-][a-z0-9_-]{6,}|[0-9a-f]{12,}|\d{9,})",
            identifier,
            flags=re.IGNORECASE,
        )
    ]


EPISODE_TEMPORAL_RELATION_META_TOKENS = frozenset(
    {
        "agent",
        "assistant",
        "user",
        "then",
        "агент",
        "затем",
        "исправление",
        "найдены",
        "объяснений",
        "остатки",
        "ошибочно",
        "перейти",
        "пользователь",
        "потребовал",
        "проверены",
        "режиму",
        "работы",
        "свёл",
        "требование",
        "удалены",
        "чистой",
    }
)

EPISODE_TEMPORAL_RAW_STRONG_QUALIFIER_RE = re.compile(
    r"^(?:absen|block|cancel|complet|current|defer|deni|error|fail|"
    r"invalid|miss|pass|recover|reject|rollback|stale|succeed|success|"
    r"timeout|unknown|verif|актуаль|восстанов|заблок|заверш|неизвест|"
    r"отлож|отклон|отмен|отсутств|ошиб|провал|провер|сбо|текущ|"
    r"таймаут|успеш|устар)",
    flags=re.IGNORECASE,
)


def episode_temporal_raw_effective_anchor_terms(
    text: Any,
    terms: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], str]:
    """Prefer exact/code anchors over discourse words for raw relation proof."""
    identifiers = episode_temporal_raw_anchor_identifiers(text)
    exact_identifiers = set(episode_temporal_exact_anchor_identifiers(text))
    strong_identifiers = [
        identifier
        for identifier in identifiers
        if identifier in exact_identifiers
        or any(char.isdigit() for char in identifier)
    ]
    identifier_tokens = {
        token.casefold()
        for identifier in strong_identifiers
        for token in search_tokenize(identifier)
        if token
    }
    identifier_terms = [
        term
        for term in terms
        if str(term.get("token") or "").casefold() in identifier_tokens
    ]
    if identifier_terms:
        return identifier_terms, "exact_compound_identifier_terms"
    code_terms = [
        term
        for term in terms
        if re.fullmatch(r"[a-z][a-z0-9_]{2,}", str(term.get("token") or "").casefold())
        and str(term.get("token") or "").casefold()
        not in EPISODE_TEMPORAL_RELATION_META_TOKENS
    ]
    if len(code_terms) >= 2:
        return code_terms, "multiple_code_anchor_terms"
    content_terms = [
        term
        for term in terms
        if str(term.get("token") or "").casefold()
        not in EPISODE_TEMPORAL_RELATION_META_TOKENS
    ]
    if len(content_terms) >= 2:
        return content_terms, "relation_meta_terms_removed"
    return terms, "full_anchor_terms"


def episode_temporal_raw_required_qualifier_terms(
    terms: list[dict[str, Any]],
) -> list[str]:
    """Keep outcome, verification, polarity, and numeric anchor terms mandatory."""
    required: list[str] = []
    for term in terms:
        token = str(term.get("token") or "").casefold()
        if not token:
            continue
        forms = [
            token,
            *[
                str(value).casefold()
                for value in term.get("exact", [])
                if str(value)
            ],
            *[
                str(value).casefold()
                for value in term.get("prefixes", [])
                if str(value)
            ],
        ]
        if any(char.isdigit() for char in token) or any(
            EPISODE_TEMPORAL_RAW_STRONG_QUALIFIER_RE.match(value)
            for value in forms
        ):
            required.append(token)
    return list(dict.fromkeys(required))


def episode_temporal_raw_anchor_match(
    text: str,
    terms: list[dict[str, Any]],
    identifiers: list[str],
) -> dict[str, Any]:
    tokens = episode_semantic_field_tokens(text)
    lowered = text.casefold()

    def matches_temporal_absence_relation(term: dict[str, Any]) -> bool:
        token = str(term.get("token") or "").casefold()
        if token not in {
            "absent",
            "missing",
            "unknown",
            "нет",
            "неизвестен",
            "неизвестна",
            "неизвестно",
            "отсутствует",
        }:
            return False
        return bool(
            re.search(
                r"\b(?:missing|absent|unknown|unregistered|"
                r"неизвест\w*|отсутств\w*)\b|"
                r"\b(?:does|did|can|could)\s+not\s+"
                r"(?:know|find|recogniz\w*|resolve|locate|register\w*)\b|"
                r"\b(?:cannot|can't)\s+"
                r"(?:know|find|recogniz\w*|resolve|locate|register\w*)\b|"
                r"\bне\s+(?:знает|видит|находит|зарегистрирован\w*)\b|"
                r"\bбез\s+(?:добавления\s+)?(?:repo\s+)?alias\b",
                lowered,
                flags=re.IGNORECASE,
            )
        )

    matched_terms = sorted(
        {
            str(term.get("token") or "")
            for term in terms
            if episode_semantic_term_matches_tokens(term, tokens)
            or matches_temporal_absence_relation(term)
        }
    )
    matched_identifiers = [identifier for identifier in identifiers if identifier in lowered]
    return {
        "matched_query_terms": matched_terms,
        "coverage": len(matched_terms) / len(terms) if terms else 0.0,
        "matched_identifiers": matched_identifiers,
    }


def episode_temporal_parent_agent_path(agent_path: Any) -> str:
    """Return the structural parent for one Codex collaboration agent path."""
    value = "/" + str(agent_path or "").strip().strip("/")
    if value in {"/", "/root"}:
        return ""
    parent = value.rsplit("/", 1)[0]
    return parent or "/root"


def episode_temporal_structured_alias_support(
    anchor_text: Any,
    terms: list[dict[str, Any]],
    *,
    payload_type: str,
    tool_name: str,
    arguments: dict[str, Any],
    agent_path: str,
) -> dict[str, Any]:
    """Resolve a narrow natural-language action anchor from typed raw fields.

    This does not perform broad synonym expansion.  It admits only query terms
    whose meaning is proven by the structured action identity and, when the
    query says "parent", by an exact target-to-parent path comparison.
    """
    if payload_type not in EPISODE_TEMPORAL_RAW_CALL_TYPES:
        return {}
    if normalized_tool_name(tool_name) != "send_message":
        return {}
    query_tokens = [
        str(term.get("token") or "").casefold()
        for term in terms
        if isinstance(term, dict) and str(term.get("token") or "")
    ]
    send_terms = [
        token
        for token in query_tokens
        if token.startswith(("отправ", "посла"))
        or token.startswith("send")
        or token in {"sent"}
    ]
    message_terms = [
        token
        for token in query_tokens
        if token.startswith("сообщен")
        or token.startswith("message")
    ]
    if not send_terms or not message_terms:
        return {}
    parent_terms = [
        token
        for token in query_tokens
        if token.startswith("родител")
        or token.startswith("parent")
    ]
    parent_agent_path = episode_temporal_parent_agent_path(agent_path)
    target = str(arguments.get("target") or "").strip()
    parent_target_proven = bool(
        parent_agent_path and target and target == parent_agent_path
    )
    supported_terms = [*send_terms, *message_terms]
    if parent_terms and parent_target_proven:
        supported_terms.extend(parent_terms)
    return {
        "basis": (
            "structured_send_message_to_parent"
            if parent_terms and parent_target_proven
            else "structured_send_message_action"
        ),
        "matched_query_terms": sorted(set(supported_terms)),
        "query_parent_qualifier_present": bool(parent_terms),
        "parent_target_proven": parent_target_proven,
        "tool_name": "send_message",
        "target_relation": (
            "parent_agent_path" if parent_target_proven else "unresolved"
        ),
        "message_body_read": False,
        "authority": "structured_tool_call_fields",
    }


def episode_temporal_structured_argument_text(
    tool_name: Any,
    arguments: dict[str, Any],
) -> str:
    """Project only anchor-safe structured arguments into temporal evidence.

    A collaboration message body can be private or encrypted and is not
    required to prove that ``send_message`` targeted a structural parent.
    Keep the typed target field available while omitting the body from the
    retrieval/read contract and its context budget.
    """
    projected_arguments = arguments
    if normalized_tool_name(tool_name) == "send_message":
        target = str(arguments.get("target") or "").strip()
        projected_arguments = {"target": target} if target else {}
    if not projected_arguments:
        return ""
    return derived_text_privacy_text(
        json.dumps(projected_arguments, ensure_ascii=False, sort_keys=True),
        max_chars=1000,
    )


def episode_temporal_required_direct_event_type(anchor_text: Any) -> str:
    """Return a bounded lifecycle event explicitly named as a code anchor."""
    value = str(anchor_text or "").casefold()
    for event_type in sorted(EPISODE_TEMPORAL_RAW_DIRECT_EVENT_TYPES):
        variants = {event_type, event_type.replace("_", "-")}
        if any(
            re.search(
                rf"(?<![a-z0-9]){re.escape(variant)}(?![a-z0-9])",
                value,
            )
            for variant in variants
        ):
            return event_type
    return ""


EPISODE_TEMPORAL_STRUCTURED_OUTCOME_ANCHOR_RE = re.compile(
    r"(?<![a-zа-я0-9_-])(?:"
    r"(?:mcp[\s_-]+)?receipt|result|output|status|"
    r"квитанц\w*|результат\w*|вывод\w*|статус\w*"
    r")(?![a-zа-я0-9_-])",
    flags=re.IGNORECASE,
)
EPISODE_TEMPORAL_STRUCTURED_FAILURE_QUALIFIER_RE = re.compile(
    r"(?<![a-zа-я0-9_-])(?:"
    r"failed?|failure|error|errored|unsuccessful|timeout|timed[\s_-]+out|"
    r"не[\s_-]*успеш\w*|ошиб\w*|провал\w*|сбо\w*|таймаут\w*"
    r")(?![a-zа-я0-9_-])",
    flags=re.IGNORECASE,
)
EPISODE_TEMPORAL_STRUCTURED_SUCCESS_QUALIFIER_RE = re.compile(
    r"(?<![a-zа-я0-9_-])(?:"
    r"success|successful|succeeded|"
    r"успех\w*|успеш\w*"
    r")(?![a-zа-я0-9_-])",
    flags=re.IGNORECASE,
)


def episode_temporal_required_structured_outcome(anchor_text: Any) -> str:
    """Read an explicit result polarity without trusting nearby prose.

    Outcome words become admission constraints only when the same anchor names
    an outcome-bearing surface.  This keeps a generic phrase such as
    ``successful approach`` from excluding narrative evidence while making
    ``successful MCP receipt`` a typed assertion that raw evidence must prove.
    """
    value = str(anchor_text or "").casefold()
    if not EPISODE_TEMPORAL_STRUCTURED_OUTCOME_ANCHOR_RE.search(value):
        return ""
    failed = bool(
        EPISODE_TEMPORAL_STRUCTURED_FAILURE_QUALIFIER_RE.search(value)
    )
    succeeded = bool(
        EPISODE_TEMPORAL_STRUCTURED_SUCCESS_QUALIFIER_RE.search(value)
    )
    if failed and succeeded:
        return "conflicting"
    if failed:
        return "failed"
    if succeeded:
        return "succeeded"
    return ""


def episode_temporal_enforce_structured_outcome_anchor(
    match: dict[str, Any],
    anchor_text: Any,
    *,
    unit_kind: str,
    result_outcome: Any,
) -> dict[str, Any]:
    """Require typed result evidence for an explicit outcome-qualified anchor."""
    required_outcome = episode_temporal_required_structured_outcome(
        anchor_text
    )
    if not required_outcome:
        return match
    observed_outcome = str(result_outcome or "").strip().casefold()
    outcome_bearing_kinds = {
        "structured_action_result_chain",
        "async_action_wait_result_chain",
        "structured_mcp_receipt",
        "structured_status_event",
        "structured_terminal_event",
    }
    outcome_proven = bool(
        required_outcome in {"succeeded", "failed"}
        and unit_kind in outcome_bearing_kinds
        and observed_outcome == required_outcome
    )
    if outcome_proven:
        return {
            **match,
            "required_structured_outcome": required_outcome,
            "observed_structured_outcome": observed_outcome,
            "structured_outcome_proven": True,
        }
    return {
        **match,
        "matched_query_terms": [],
        "matched_identifiers": [],
        "coverage": 0.0,
        "required_structured_outcome": required_outcome,
        "observed_structured_outcome": observed_outcome,
        "structured_outcome_proven": False,
        "anchor_rejection": (
            "conflicting_structured_outcome_qualifiers"
            if required_outcome == "conflicting"
            else "required_structured_outcome_not_proven"
        ),
    }


def episode_temporal_enforce_direct_event_anchor(
    match: dict[str, Any],
    anchor_text: Any,
    *,
    unit_kind: str,
    payload_type: str,
) -> dict[str, Any]:
    """Prevent a lifecycle-event mention from impersonating the event."""
    required_type = episode_temporal_required_direct_event_type(anchor_text)
    if not required_type:
        return match
    if (
        unit_kind == "structured_terminal_event"
        and payload_type == required_type
    ):
        return {
            **match,
            "required_direct_event_type": required_type,
            "direct_event_type_proven": True,
        }
    return {
        **match,
        "matched_query_terms": [],
        "matched_identifiers": [],
        "coverage": 0.0,
        "required_direct_event_type": required_type,
        "direct_event_type_proven": False,
        "anchor_rejection": "direct_event_name_observed_only_as_text",
    }


def episode_temporal_enforce_explicit_quoted_anchor(
    match: dict[str, Any],
    anchor_text: Any,
    observed_text: Any,
    *,
    match_policy: Any,
    source_policy: Any,
    unit_kind: str,
) -> dict[str, Any]:
    """Keep an explicit quoted endpoint from degrading into token similarity.

    A quoted message body is an exact lexical anchor supplied by the caller.
    Matching its individual terms in a later paraphrase can move the endpoint
    and silently omit part of the requested interval.  Preserve structured
    quoted anchors for other lanes, but require a canonical message when the
    query explicitly says that the endpoints are messages.
    """
    if str(match_policy or "") != "normalized_exact_phrase":
        return match
    normalized_anchor = re.sub(
        r"\s+",
        " ",
        str(anchor_text or "").casefold(),
    ).strip()
    normalized_observed = re.sub(
        r"\s+",
        " ",
        str(observed_text or "").casefold(),
    ).strip()
    exact_phrase_proven = bool(
        normalized_anchor
        and normalized_anchor in normalized_observed
    )
    canonical_message_proven = bool(
        str(source_policy or "") != "canonical_message_required"
        or unit_kind == "canonical_message_observation"
    )
    if exact_phrase_proven and canonical_message_proven:
        return {
            **match,
            "explicit_quoted_anchor_proven": True,
            "quoted_anchor_match_policy": "normalized_exact_phrase",
            "quoted_anchor_source_policy": str(source_policy or ""),
        }
    return {
        **match,
        "matched_query_terms": [],
        "matched_identifiers": [],
        "coverage": 0.0,
        "explicit_quoted_anchor_proven": False,
        "quoted_anchor_match_policy": "normalized_exact_phrase",
        "quoted_anchor_source_policy": str(source_policy or ""),
        "anchor_rejection": (
            "quoted_message_anchor_requires_canonical_message"
            if exact_phrase_proven and not canonical_message_proven
            else "quoted_anchor_exact_phrase_not_observed"
        ),
    }


def episode_temporal_merge_typed_alias_support(
    match: dict[str, Any],
    typed_support: dict[str, Any],
    terms: list[dict[str, Any]],
) -> dict[str, Any]:
    if not typed_support:
        return match
    matched_query_terms = sorted(
        {
            *[
                str(value)
                for value in match.get("matched_query_terms", [])
                if value
            ],
            *[
                str(value)
                for value in typed_support.get("matched_query_terms", [])
                if value
            ],
        }
    )
    return {
        **match,
        "matched_query_terms": matched_query_terms,
        "coverage": (
            len(matched_query_terms) / len(terms)
            if terms
            else 0.0
        ),
        "typed_alias_support": typed_support,
    }


def episode_temporal_raw_pair_admission(
    left: dict[str, Any],
    right: dict[str, Any],
    *,
    left_identifiers: list[str],
    right_identifiers: list[str],
    left_required_qualifier_terms: list[str] | None = None,
    right_required_qualifier_terms: list[str] | None = None,
) -> str:
    for anchor in (left, right):
        typed_support = (
            anchor.get("typed_alias_support")
            if isinstance(anchor.get("typed_alias_support"), dict)
            else {}
        )
        if (
            typed_support.get("query_parent_qualifier_present") is True
            and typed_support.get("parent_target_proven") is not True
        ):
            return ""
    left_coverage = float(left.get("coverage") or 0.0)
    right_coverage = float(right.get("coverage") or 0.0)
    minimum_coverage = min(left_coverage, right_coverage)
    left_matches = [str(item) for item in left.get("matched_query_terms", []) if item]
    right_matches = [str(item) for item in right.get("matched_query_terms", []) if item]
    if not {
        str(value).casefold()
        for value in left_required_qualifier_terms or []
        if str(value)
    } <= {value.casefold() for value in left_matches}:
        return ""
    if not {
        str(value).casefold()
        for value in right_required_qualifier_terms or []
        if str(value)
    } <= {value.casefold() for value in right_matches}:
        return ""
    distance = int_value(right.get("line")) - int_value(left.get("line"))
    # Identifiers narrow the requested relation, not merely its ranking.  A
    # different py_compile/pytest pair can have high generic coverage while
    # still being the wrong operational chain.
    left_matched_identifiers = {
        str(value).casefold()
        for value in left.get("matched_identifiers", [])
        if str(value)
    }
    right_matched_identifiers = {
        str(value).casefold()
        for value in right.get("matched_identifiers", [])
        if str(value)
    }
    if left_identifiers and not {
        str(value).casefold()
        for value in left_identifiers
        if str(value)
    } <= left_matched_identifiers:
        return ""
    if right_identifiers and not {
        str(value).casefold()
        for value in right_identifiers
        if str(value)
    } <= right_matched_identifiers:
        return ""
    if minimum_coverage >= EPISODE_TEMPORAL_SPAN_MIN_ANCHOR_COVERAGE:
        return (
            "identifier_backed_full_anchor_coverage"
            if left_identifiers or right_identifiers
            else "full_anchor_coverage"
        )
    identifier_backed = bool(
        left_identifiers
        and right_identifiers
        and left.get("matched_identifiers")
        and right.get("matched_identifiers")
        and left_coverage >= 0.5
        and right_coverage >= 0.5
        and len(left_matches) >= 2
        and len(right_matches) >= 2
    )
    if identifier_backed:
        return "identifier_backed_partial_lexical_coverage"
    left_specific = [token for token in left_matches if len(token) >= 4 or any(char.isdigit() for char in token)]
    right_specific = [token for token in right_matches if len(token) >= 4 or any(char.isdigit() for char in token)]
    adjacent_specific = bool(
        minimum_coverage >= 0.5
        and len(left_matches) >= 2
        and len(right_matches) >= 2
        and left_specific
        and right_specific
        and 0 < distance <= EPISODE_TEMPORAL_SCOPED_RAW_ADJACENT_MAX_DISTANCE_LINES
        and len(set(left_matches + right_matches)) >= 4
    )
    return "adjacent_specific_partial_lexical_coverage" if adjacent_specific else ""


def episode_temporal_exact_anchor_seed_candidates(
    *,
    aoa_root: Path,
    session_id: str,
    results: list[dict[str, Any]],
    temporal_span: dict[str, Any],
    terms: list[dict[str, Any]],
    query_text: str,
    normalized_query: str,
    explain: bool,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Seed scoped temporal episodes from fresh exact identifier postings."""
    started = time.monotonic()
    base_report = {
        "status": "not_requested",
        "applied": False,
        "mutates": False,
        "input_candidate_count": len(results),
        "output_candidate_count": len(results),
        "seeded_episode_count": 0,
        "added_episode_count": 0,
        "source": "fresh_exact_literal_postings_to_episode_range",
    }
    if not temporal_span.get("active"):
        return results, {**base_report, "status": "not_a_temporal_span_query"}
    identifiers_by_side = {
        "left": episode_temporal_exact_anchor_identifiers(
            temporal_span.get("left_text")
        )[
            :EPISODE_TEMPORAL_EXACT_SEED_MAX_IDENTIFIERS_PER_SIDE
        ],
        "right": episode_temporal_exact_anchor_identifiers(
            temporal_span.get("right_text")
        )[
            :EPISODE_TEMPORAL_EXACT_SEED_MAX_IDENTIFIERS_PER_SIDE
        ],
    }
    if not any(identifiers_by_side.values()):
        return results, {
            **base_report,
            "status": "no_exact_anchor_identifiers",
            "identifiers": identifiers_by_side,
        }
    if not session_id:
        return results, {
            **base_report,
            "status": "session_scope_missing",
            "identifiers": identifiers_by_side,
        }
    db_path = search_db_path(aoa_root)
    if not db_path.exists():
        return results, {
            **base_report,
            "status": "search_index_missing",
            "identifiers": identifiers_by_side,
        }
    conn: sqlite3.Connection | None = None
    try:
        conn = connect_existing_search_db(db_path)
        required_tables = (
            "documents",
            "exact_literal_postings_fts",
            "exact_literal_posting_meta",
            "exact_literal_session_state",
            "episode_semantic_meta",
            "episode_semantic_payloads",
        )
        missing_tables = [table for table in required_tables if not sqlite_table_exists(conn, table)]
        if missing_tables:
            return results, {
                **base_report,
                "status": "exact_or_episode_projection_missing",
                "identifiers": identifiers_by_side,
                "diagnostics": [f"table_missing:{table}" for table in missing_tables],
            }
        state = conn.execute(
            "SELECT status, projection_version, indexed_at "
            "FROM exact_literal_session_state WHERE session_id = ? LIMIT 1",
            (session_id,),
        ).fetchone()
        scope_current = bool(
            state
            and str(state["status"] or "") == "current"
            and int_value(state["projection_version"]) == SEARCH_EXACT_LITERAL_POSTINGS_VERSION
        )
        if not scope_current:
            return results, {
                **base_report,
                "status": "exact_anchor_projection_not_current",
                "identifiers": identifiers_by_side,
                "exact_scope": {
                    "status": str(state["status"] or "missing") if state else "missing",
                    "projection_version": int_value(state["projection_version"]) if state else 0,
                    "expected_projection_version": SEARCH_EXACT_LITERAL_POSTINGS_VERSION,
                },
            }
        anchor_hits: list[dict[str, Any]] = []
        seen_hits: set[tuple[str, str, int]] = set()
        for side, identifiers in identifiers_by_side.items():
            for identifier in identifiers:
                literal_query = exact_literal_fts_query_from_user(identifier)
                if not literal_query:
                    continue
                rows = conn.execute(
                    "SELECT documents.raw_ref, documents.event_type, documents.rowid "
                    "FROM exact_literal_postings_fts "
                    "JOIN documents ON documents.rowid = exact_literal_postings_fts.rowid "
                    "JOIN exact_literal_posting_meta "
                    "ON exact_literal_posting_meta.doc_rowid = documents.rowid "
                    "WHERE exact_literal_postings_fts MATCH ? AND documents.session_id = ? "
                    "ORDER BY bm25(exact_literal_postings_fts), documents.rowid "
                    "LIMIT ?",
                    (
                        literal_query,
                        session_id,
                        EPISODE_TEMPORAL_EXACT_SEED_MAX_DOCS_PER_IDENTIFIER,
                    ),
                ).fetchall()
                for row in rows:
                    raw_ref = str(row["raw_ref"] or "")
                    raw_line = line_from_raw_ref(raw_ref)
                    key = (side, identifier, raw_line)
                    if raw_line <= 0 or key in seen_hits:
                        continue
                    seen_hits.add(key)
                    anchor_hits.append(
                        {
                            "side": side,
                            "identifier": identifier,
                            "raw_line": raw_line,
                            "raw_ref": raw_ref,
                            "event_type": str(row["event_type"] or ""),
                        }
                    )
        if not anchor_hits:
            return results, {
                **base_report,
                "status": "exact_anchor_postings_not_found",
                "applied": True,
                "identifiers": identifiers_by_side,
                "exact_scope": {
                    "status": "current",
                    "projection_version": SEARCH_EXACT_LITERAL_POSTINGS_VERSION,
                },
            }
        episode_conditions = " OR ".join(
            "(episode_semantic_meta.from_line <= ? AND episode_semantic_meta.to_line >= ?)"
            for _hit in anchor_hits
        )
        episode_params: list[Any] = [
            session_id,
            EPISODE_SEMANTIC_PROJECTION_VERSION,
        ]
        for hit in anchor_hits:
            episode_params.extend([hit["raw_line"], hit["raw_line"]])
        episode_params.append(EPISODE_TEMPORAL_EXACT_SEED_MAX_EPISODES)
        episode_rows = conn.execute(
            "SELECT episode_semantic_meta.*, episode_semantic_payloads.payload_zlib "
            "FROM episode_semantic_meta JOIN episode_semantic_payloads "
            "ON episode_semantic_payloads.doc_rowid = episode_semantic_meta.doc_rowid "
            "WHERE episode_semantic_meta.session_id = ? "
            "AND episode_semantic_meta.projection_version = ? "
            f"AND ({episode_conditions}) "
            "ORDER BY episode_semantic_meta.from_line, episode_semantic_meta.to_line "
            "LIMIT ?",
            episode_params,
        ).fetchall()
        existing_by_id = {
            str(item.get("doc_id") or ""): dict(item)
            for item in results
            if isinstance(item, dict) and item.get("doc_id")
        }
        seeded_ids: list[str] = []
        seeded_results: list[dict[str, Any]] = []
        for row in episode_rows:
            doc_id = str(row["doc_id"] or "")
            from_line = int_value(row["from_line"])
            to_line = int_value(row["to_line"])
            supporting_hits = [
                hit
                for hit in anchor_hits
                if from_line <= int_value(hit.get("raw_line")) <= to_line
            ]
            if not supporting_hits:
                continue
            result = existing_by_id.get(doc_id)
            if result is None:
                result = episode_semantic_result_from_row(
                    row,
                    terms=terms,
                    temporal_span=temporal_span,
                    query_text=query_text,
                    normalized_query=normalized_query,
                    explain=explain,
                    bm25_rank=0.0,
                    match_channel="episode_exact_temporal_anchor_seed",
                )
            result = dict(result)
            result["temporal_exact_anchor_seed"] = {
                "status": "seeded",
                "source": "fresh_exact_literal_postings",
                "hits": supporting_hits,
                "authority": "exact posting routes to raw ref; raw transcript remains authority",
            }
            result["match_channels"] = list(
                dict.fromkeys(
                    [
                        *list(result.get("match_channels") or []),
                        str(result.get("match_channel") or ""),
                        "episode_exact_temporal_anchor_seed",
                    ]
                )
            )
            seeded_results.append(result)
            seeded_ids.append(doc_id)
            existing_by_id.pop(doc_id, None)
        output = [*seeded_results, *existing_by_id.values()]
        return output, {
            **base_report,
            "status": "applied",
            "applied": True,
            "identifiers": identifiers_by_side,
            "exact_scope": {
                "status": "current",
                "projection_version": SEARCH_EXACT_LITERAL_POSTINGS_VERSION,
                "indexed_at": str(state["indexed_at"] or ""),
            },
            "anchor_hit_count": len(anchor_hits),
            "anchor_hits": anchor_hits,
            "seeded_episode_count": len(seeded_results),
            "seeded_episode_ids": seeded_ids,
            "added_episode_count": sum(1 for doc_id in seeded_ids if doc_id not in {str(item.get('doc_id') or '') for item in results}),
            "input_candidate_count": len(results),
            "output_candidate_count": len(output),
            "elapsed_ms": int((time.monotonic() - started) * 1000),
            "authority_boundary": "exact and episode projections are navigation; raw refs remain evidence authority",
        }
    except sqlite3.Error as exc:
        return results, {
            **base_report,
            "status": sqlite_error_status(exc),
            "identifiers": identifiers_by_side,
            "elapsed_ms": int((time.monotonic() - started) * 1000),
            "diagnostics": [sqlite_error_diagnostic(exc)],
        }
    finally:
        if conn is not None:
            conn.close()


def episode_temporal_scoped_raw_hydration(
    *,
    raw_path: Path | None,
    raw_sources: list[dict[str, Any]] | None = None,
    segments: list[dict[str, Any]],
    results: list[dict[str, Any]],
    temporal_span: dict[str, Any],
    time_from: str | None = None,
    time_to: str | None = None,
    max_raw_bytes: int = EPISODE_TEMPORAL_SCOPED_RAW_MAX_BYTES,
    max_lines: int = EPISODE_TEMPORAL_SCOPED_RAW_MAX_LINES,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Hydrate explicit scoped temporal anchors from raw structured chains.

    Episode representations are intentionally bounded and cannot retain every
    operational anchor from a long task.  This fallback scans one explicitly
    selected session, keeps only query-matching units, joins call/result
    correlation, and leaves the raw transcript authoritative.
    """
    started = time.monotonic()
    candidate_block_mode = raw_sources is not None
    read_scope = "candidate_raw_blocks" if candidate_block_mode else "archived_raw_snapshot"
    base_report = {
        "status": "not_requested",
        "applied": False,
        "mutates": False,
        "candidate_count": len(results),
        "qualified_candidate_count": 0,
        "evidence_source": (
            "hash_verified_candidate_raw_blocks"
            if candidate_block_mode
            else "scoped_raw_structured_chain"
        ),
        "read_scope": read_scope,
    }
    if not temporal_span.get("active"):
        return results, {**base_report, "status": "not_a_temporal_span_query"}

    def normalized_temporal_timestamp(value: Any) -> str:
        try:
            return str(parse_timestamp_arg(str(value or "")) or "")
        except ValueError:
            return ""

    query_time_from = str(temporal_span.get("query_time_from") or "")
    query_time_to = str(temporal_span.get("query_time_to") or "")
    explicit_time_from = normalized_temporal_timestamp(time_from)
    explicit_time_to = normalized_temporal_timestamp(time_to)
    query_normalized_time_from = normalized_temporal_timestamp(
        query_time_from
    )
    query_normalized_time_to = normalized_temporal_timestamp(query_time_to)
    normalized_time_from = max(
        [
            value
            for value in (
                explicit_time_from,
                query_normalized_time_from,
            )
            if value
        ],
        default="",
    )
    normalized_time_to = min(
        [
            value
            for value in (
                explicit_time_to,
                query_normalized_time_to,
            )
            if value
        ],
        default="",
    )
    time_scope_requested = bool(normalized_time_from or normalized_time_to)
    if (
        (time_from and not explicit_time_from)
        or (time_to and not explicit_time_to)
        or (query_time_from and not query_normalized_time_from)
        or (query_time_to and not query_normalized_time_to)
    ):
        return [dict(item) for item in results], {
            **base_report,
            "status": "invalid_time_scope",
            "requested_time_from": str(
                time_from or query_time_from or ""
            ),
            "requested_time_to": str(time_to or query_time_to or ""),
        }
    if (
        normalized_time_from
        and normalized_time_to
        and normalized_time_from > normalized_time_to
    ):
        return [dict(item) for item in results], {
            **base_report,
            "status": "invalid_time_scope_order",
            "requested_time_from": normalized_time_from,
            "requested_time_to": normalized_time_to,
        }
    source_integrity: dict[str, Any] = {
        "status": "not_checked_by_hydrator",
        "required": candidate_block_mode,
        "requested_count": len(raw_sources or []),
        "verified_count": 0,
        "usable_count": 0,
        "failed_count": 0,
        "unverified_count": 0,
        "missing_count": 0,
        "read_failure_count": 0,
        "coordinate_mismatch_count": 0,
        "rejected_samples": [],
    }
    prepared_sources: list[dict[str, Any]] = []
    raw_bytes = 0
    stored_raw_bytes = 0
    if candidate_block_mode:
        seen_sources: set[tuple[str, str]] = set()
        for raw_source in raw_sources or []:
            if not isinstance(raw_source, dict):
                source_integrity["unverified_count"] += 1
                continue
            source_path_ref = str(raw_source.get("path") or "")
            source_path = Path(source_path_ref).expanduser() if source_path_ref else Path()
            session_id = str(raw_source.get("session_id") or "")
            source_key = (session_id, str(source_path))
            if source_key in seen_sources:
                continue
            seen_sources.add(source_key)
            declared_uncompressed_bytes = int_value(
                raw_source.get("uncompressed_bytes"),
                int_value(raw_source.get("stored_bytes")),
            )
            declared_stored_bytes = int_value(raw_source.get("stored_bytes"))
            raw_bytes += max(0, declared_uncompressed_bytes)
            stored_raw_bytes += max(0, declared_stored_bytes)
            if not source_path_ref or not source_path.is_file():
                source_integrity["missing_count"] += 1
                source_integrity["rejected_samples"].append(
                    {"session_id": session_id, "path": source_path_ref, "reason": "missing"}
                )
                continue
            expected_sha256 = str(raw_source.get("expected_sha256") or "").strip().lower()
            if not expected_sha256:
                source_integrity["unverified_count"] += 1
                source_integrity["rejected_samples"].append(
                    {
                        "session_id": session_id,
                        "path": str(source_path),
                        "reason": "expected_sha256_missing",
                    }
                )
                continue
            try:
                actual_sha256 = sha256_file(source_path).lower()
            except OSError as exc:
                source_integrity["failed_count"] += 1
                source_integrity["rejected_samples"].append(
                    {
                        "session_id": session_id,
                        "path": str(source_path),
                        "reason": "sha256_read_failed",
                        "diagnostic": str(exc),
                    }
                )
                continue
            if actual_sha256 != expected_sha256:
                source_integrity["failed_count"] += 1
                source_integrity["rejected_samples"].append(
                    {
                        "session_id": session_id,
                        "path": str(source_path),
                        "reason": "sha256_mismatch",
                        "expected_sha256": expected_sha256,
                        "actual_sha256": actual_sha256,
                    }
                )
                continue
            source_integrity["verified_count"] += 1
            prepared_sources.append({**raw_source, "_path": source_path})
        source_integrity["rejected_samples"] = source_integrity["rejected_samples"][:8]
        if not prepared_sources:
            source_integrity["status"] = "failed"
            return [dict(item) for item in results], {
                **base_report,
                "status": "candidate_raw_block_integrity_failed",
                "raw_bytes": raw_bytes,
                "stored_raw_bytes": stored_raw_bytes,
                "max_raw_bytes": max_raw_bytes,
                "source_integrity": source_integrity,
                "elapsed_ms": int((time.monotonic() - started) * 1000),
            }
        prepared_sources.sort(
            key=lambda item: (
                str(item.get("session_id") or ""),
                int_value(item.get("from_line")),
                str(item.get("path") or ""),
            )
        )
    else:
        if not raw_path or not raw_path.is_file():
            return results, {**base_report, "status": "raw_path_missing"}
        raw_bytes = raw_path.stat().st_size
        stored_raw_bytes = raw_bytes
        candidate_session_ids = {
            str(item.get("session_id") or "")
            for item in results
            if isinstance(item, dict) and str(item.get("session_id") or "")
        }
        scoped_session_id = next(iter(candidate_session_ids)) if len(candidate_session_ids) == 1 else ""
        prepared_sources = [
            {
                "_path": raw_path,
                "path": str(raw_path),
                "compression": "plain",
                "session_id": scoped_session_id,
                "from_line": 1,
                "to_line": 0,
                "line_count": 0,
            }
        ]
    if max_raw_bytes <= 0 or raw_bytes > max_raw_bytes:
        return results, {
            **base_report,
            "status": "raw_over_bounded_hydration_limit",
            "raw_bytes": raw_bytes,
            "stored_raw_bytes": stored_raw_bytes,
            "max_raw_bytes": max_raw_bytes,
            "source_integrity": source_integrity,
        }
    clones = [dict(item) for item in results]
    candidate_ranges: list[tuple[str, int, int, dict[str, Any]]] = []
    for item in clones:
        event_range = item.get("event_range") if isinstance(item.get("event_range"), dict) else {}
        from_line = int_value(event_range.get("from_line"))
        to_line = int_value(event_range.get("to_line"))
        if from_line > 0 and to_line >= from_line:
            candidate_ranges.append(
                (str(item.get("session_id") or ""), from_line, to_line, item)
            )
    if not candidate_ranges:
        return clones, {
            **base_report,
            "status": "candidate_ranges_missing",
            "raw_bytes": raw_bytes,
            "stored_raw_bytes": stored_raw_bytes,
            "source_integrity": source_integrity,
        }
    candidate_ranges.sort(key=lambda item: (item[0], item[1], item[2]))
    candidate_by_doc_id = {
        str(item.get("doc_id") or ""): item
        for item in clones
        if str(item.get("doc_id") or "")
    }
    left_query_terms = [
        item for item in temporal_span.get("left_terms", []) if isinstance(item, dict)
    ]
    right_query_terms = [
        item for item in temporal_span.get("right_terms", []) if isinstance(item, dict)
    ]
    left_terms, left_term_basis = episode_temporal_raw_effective_anchor_terms(
        temporal_span.get("left_text"),
        left_query_terms,
    )
    right_terms, right_term_basis = episode_temporal_raw_effective_anchor_terms(
        temporal_span.get("right_text"),
        right_query_terms,
    )
    left_required_qualifier_terms = (
        episode_temporal_raw_required_qualifier_terms(left_terms)
    )
    right_required_qualifier_terms = (
        episode_temporal_raw_required_qualifier_terms(right_terms)
    )
    left_identifiers = episode_temporal_raw_anchor_identifiers(temporal_span.get("left_text"))
    right_identifiers = episode_temporal_raw_anchor_identifiers(temporal_span.get("right_text"))
    # A global first-match cap lets generic words in early transcript lines
    # consume the whole budget before a later identifier-backed chain is
    # reached.  Keep a bounded best-evidence reservoir for each candidate and
    # anchor side instead.  Correlated call/result observations share one key,
    # so a richer result chain replaces its thinner call without increasing
    # cardinality.
    candidate_side_limit = max(
        1,
        EPISODE_TEMPORAL_SCOPED_RAW_MAX_MATCHED_UNITS
        // max(1, len(candidate_ranges) * 2),
    )
    matched_left_by_doc: dict[
        str,
        dict[tuple[str, int], tuple[tuple[float, ...], dict[str, Any]]],
    ] = defaultdict(dict)
    matched_right_by_doc: dict[
        str,
        dict[tuple[str, int], tuple[tuple[float, ...], dict[str, Any]]],
    ] = defaultdict(dict)
    interval_units_by_doc: dict[
        str,
        dict[tuple[int, int, str, str], dict[str, Any]],
    ] = defaultdict(dict)
    interval_units_truncated_docs: set[str] = set()
    interval_unit_limit = max(
        EPISODE_TEMPORAL_INTERVAL_OUTPUT_EVENT_LIMIT,
        EPISODE_TEMPORAL_SCOPED_RAW_MAX_MATCHED_UNITS
        // max(1, len(candidate_ranges)),
    )
    pending_actions: dict[str, dict[str, Any]] = {}
    pending_order: deque[tuple[int, str]] = deque()
    async_origins: dict[tuple[str, str], dict[str, Any]] = {}
    wait_origins: dict[str, dict[str, Any]] = {}
    lines_scanned = 0
    parsed_event_count = 0
    admitted_event_count = 0
    matched_unit_count = 0
    matched_unit_observed_count = 0
    matched_unit_truncated = False
    line_budget_exhausted = False
    byte_budget_exhausted = False
    decoded_bytes_scanned = 0
    usable_source_count = 0
    time_scope_filtered_event_count = 0
    time_scope_unverifiable_event_count = 0
    typed_anchor_support_observed_count = 0

    def retain_candidate_evidence(
        *,
        doc_id: str,
        side: str,
        unit: dict[str, Any],
    ) -> None:
        nonlocal matched_unit_truncated
        match = unit.get(side) if isinstance(unit.get(side), dict) else {}
        matched_terms = [str(value) for value in match.get("matched_query_terms", []) if value]
        if not matched_terms:
            return
        matched_identifiers = [str(value) for value in match.get("matched_identifiers", []) if value]
        kind = str(unit.get("kind") or "")
        kind_weight = {
            "async_action_wait_result_chain": 4.0,
            "structured_action_result_chain": 3.0,
            "structured_mcp_receipt": 3.0,
            "structured_terminal_event": 3.0,
            "structured_action": 2.0,
            "canonical_message_observation": 1.0,
        }.get(kind, 0.0)
        specific_term_count = sum(
            1
            for token in matched_terms
            if len(token) >= 4 or any(char.isdigit() for char in token)
        )
        priority = (
            float(bool(matched_identifiers)),
            float(len(matched_identifiers)),
            float(bool(match.get("typed_alias_support"))),
            float(match.get("coverage") or 0.0),
            float(len(matched_terms)),
            float(specific_term_count),
            kind_weight,
            float(int_value(unit.get("line"))),
        )
        correlation_id = str(unit.get("correlation_id") or "")
        retention_key = (
            correlation_id or f"line:{int_value(unit.get('line'))}",
            int_value(unit.get("chain_from_line")),
        )
        store = matched_left_by_doc[doc_id] if side == "left" else matched_right_by_doc[doc_id]
        previous = store.get(retention_key)
        if previous is not None:
            if priority > previous[0]:
                store[retention_key] = (priority, unit)
            return
        if len(store) < candidate_side_limit:
            store[retention_key] = (priority, unit)
            return
        matched_unit_truncated = True
        weakest_key, weakest = min(store.items(), key=lambda item: item[1][0])
        if priority > weakest[0]:
            store.pop(weakest_key, None)
            store[retention_key] = (priority, unit)

    def retain_interval_unit(
        *,
        doc_id: str,
        unit: dict[str, Any],
    ) -> None:
        """Keep bounded source-aware units for a later interval read.

        Anchor discovery and interval reading are separate contracts.  The
        former keeps only query matches; the latter must retain the canonical
        messages and structured operational events between an admitted pair.
        """
        key = (
            int_value(unit.get("line")),
            int_value(unit.get("chain_from_line")),
            str(unit.get("kind") or ""),
            str(unit.get("correlation_id") or ""),
        )
        store = interval_units_by_doc[doc_id]
        if key in store:
            store[key] = unit
            return
        if len(store) >= interval_unit_limit:
            interval_units_truncated_docs.add(doc_id)
            return
        store[key] = unit

    def prune_pending(current_line: int) -> None:
        while pending_order and (
            len(pending_actions) > EPISODE_TEMPORAL_SCOPED_RAW_PENDING_ACTION_LIMIT
            or current_line - pending_order[0][0] > EPISODE_TEMPORAL_SCOPED_RAW_PENDING_ACTION_MAX_AGE_LINES
        ):
            old_line, correlation_id = pending_order.popleft()
            current = pending_actions.get(correlation_id)
            if current and int_value(current.get("line")) == old_line:
                pending_actions.pop(correlation_id, None)

    def iter_raw_source_lines(source: dict[str, Any]) -> Iterable[tuple[int, str]]:
        nonlocal byte_budget_exhausted, decoded_bytes_scanned, usable_source_count
        source_path = source.get("_path")
        if not isinstance(source_path, Path):
            return
        source_from_line = max(1, int_value(source.get("from_line"), 1))
        source_to_line = int_value(source.get("to_line"))
        expected_line_count = int_value(
            source.get("line_count"),
            source_to_line - source_from_line + 1
            if source_to_line >= source_from_line
            else 0,
        )
        observed_line_count = 0
        source_complete = True
        try:
            opener = gzip.open if str(source.get("compression") or "") == "gzip" else open
            with opener(source_path, "rt", encoding="utf-8", errors="replace") as handle:
                for local_line_no, line in enumerate(handle, start=1):
                    line_no = source_from_line + local_line_no - 1
                    if source_to_line >= source_from_line and line_no > source_to_line:
                        source_integrity["coordinate_mismatch_count"] += 1
                        source_complete = False
                        break
                    line_bytes = len(line.encode("utf-8", errors="replace"))
                    if decoded_bytes_scanned + line_bytes > max_raw_bytes:
                        byte_budget_exhausted = True
                        source_complete = False
                        break
                    decoded_bytes_scanned += line_bytes
                    observed_line_count += 1
                    yield line_no, line
        except (OSError, EOFError) as exc:
            source_integrity["read_failure_count"] += 1
            source_integrity["rejected_samples"].append(
                {
                    "session_id": str(source.get("session_id") or ""),
                    "path": str(source_path),
                    "reason": "raw_source_read_failed",
                    "diagnostic": str(exc),
                }
            )
            source_complete = False
        if (
            source_complete
            and expected_line_count > 0
            and observed_line_count != expected_line_count
        ):
            source_integrity["coordinate_mismatch_count"] += 1
            source_integrity["rejected_samples"].append(
                {
                    "session_id": str(source.get("session_id") or ""),
                    "path": str(source_path),
                    "reason": "line_coordinate_mismatch",
                    "expected_line_count": expected_line_count,
                    "observed_line_count": observed_line_count,
                }
            )
            source_complete = False
        if source_complete:
            usable_source_count += 1

    for source in prepared_sources:
        source_agent_path = str(source.get("agent_path") or "")
        for line_no, line in iter_raw_source_lines(source):
            if lines_scanned >= max_lines:
                line_budget_exhausted = True
                break
            lines_scanned += 1
            try:
                parsed = json.loads(line)
            except json.JSONDecodeError:
                continue
            if not isinstance(parsed, dict):
                continue
            parsed_event_count += 1
            source_type = str(parsed.get("type") or "")
            payload = parsed.get("payload") if isinstance(parsed.get("payload"), dict) else {}
            payload_type = str(payload.get("type") or "")
            event_timestamp = normalized_temporal_timestamp(
                parsed.get("timestamp")
            )
            if source_type == "session_meta":
                observed_agent_path = str(payload.get("agent_path") or "")
                if not observed_agent_path:
                    source_meta = (
                        payload.get("source")
                        if isinstance(payload.get("source"), dict)
                        else {}
                    )
                    subagent_meta = (
                        source_meta.get("subagent")
                        if isinstance(source_meta.get("subagent"), dict)
                        else {}
                    )
                    spawn_meta = (
                        subagent_meta.get("thread_spawn")
                        if isinstance(subagent_meta.get("thread_spawn"), dict)
                        else {}
                    )
                    observed_agent_path = str(
                        spawn_meta.get("agent_path") or ""
                    )
                if observed_agent_path and not source_agent_path:
                    source_agent_path = observed_agent_path
                continue
            message_role = ""
            if source_type == "response_item":
                if payload_type == "message":
                    message_role = str(payload.get("role") or "")
                    if message_role not in {"user", "assistant"}:
                        continue
                    unit_kind = "canonical_message_observation"
                elif payload_type in EPISODE_TEMPORAL_RAW_CALL_TYPES:
                    unit_kind = "structured_action"
                elif payload_type in EPISODE_TEMPORAL_RAW_RESULT_TYPES:
                    unit_kind = "structured_action_result_chain"
                else:
                    continue
            elif (
                source_type == "event_msg"
                and payload_type in EPISODE_TEMPORAL_RAW_MCP_RECEIPT_TYPES
            ):
                unit_kind = "structured_mcp_receipt"
            elif (
                source_type == "event_msg"
                and payload_type in EPISODE_TEMPORAL_RAW_DIRECT_EVENT_TYPES
            ):
                unit_kind = "structured_terminal_event"
            elif (
                source_type == "event_msg"
                and payload_type in EPISODE_TEMPORAL_RAW_STATUS_EVENT_TYPES
            ):
                unit_kind = "structured_status_event"
            else:
                continue
            admitted_event_count += 1
            correlation_id = str(payload_correlation_id(payload) or "")
            semantic = (
                search_doc_text(
                    [payload_type, correlation_id, payload.get("status")]
                )
                if source_type == "event_msg"
                else short_text(
                    semantic_text_for_classification(source_type, payload),
                    max_chars=EPISODE_TEMPORAL_SCOPED_RAW_EVENT_MAX_CHARS,
                ).strip()
            )
            if (
                not semantic
                and payload_type in EPISODE_TEMPORAL_RAW_RESULT_TYPES
                and correlation_id
            ):
                semantic = search_doc_text([payload_type, correlation_id])
            if not semantic:
                continue
            chain_from_line = line_no
            chain_from_timestamp = event_timestamp
            combined = semantic
            tool_name = ""
            command_text = ""
            result_outcome = (
                str(payload.get("status") or "")
                if source_type == "event_msg"
                else ""
            )
            arguments: dict[str, Any] = {}
            if payload_type in EPISODE_TEMPORAL_RAW_CALL_TYPES:
                tool_name = normalized_tool_name(tool_name_from_payload(payload))
                command_text = command_text_from_payload(payload)
                arguments = command_payload_args(payload)
                argument_text = episode_temporal_structured_argument_text(
                    tool_name,
                    arguments,
                )
                continuation_identity = (
                    async_continuation_transport_identity_from_payload(payload)
                )
                continuation_key = (
                    str(continuation_identity.get("kind") or ""),
                    str(continuation_identity.get("id") or ""),
                )
                if all(continuation_key):
                    origin = async_origins.get(continuation_key)
                    if origin:
                        chain_from_line = int_value(origin.get("line"), line_no)
                        chain_from_timestamp = str(
                            origin.get("timestamp") or event_timestamp
                        )
                        combined = search_doc_text(
                            [origin.get("text"), correlation_id, semantic, argument_text],
                            max_chars=EPISODE_TEMPORAL_SCOPED_RAW_EVENT_MAX_CHARS,
                        )
                        if correlation_id:
                            wait_origins[correlation_id] = origin
                if combined == semantic:
                    combined = search_doc_text(
                        [correlation_id, semantic, argument_text],
                        max_chars=EPISODE_TEMPORAL_SCOPED_RAW_EVENT_MAX_CHARS,
                    )
                if correlation_id:
                    pending_actions[correlation_id] = {
                        "line": line_no,
                        "chain_from_line": chain_from_line,
                        "timestamp": chain_from_timestamp,
                        "text": combined,
                        "tool_name": tool_name,
                        "command_text": command_text,
                    }
                    pending_order.append((line_no, correlation_id))
                    prune_pending(line_no)
            elif payload_type in EPISODE_TEMPORAL_RAW_RESULT_TYPES:
                action = pending_actions.get(correlation_id) if correlation_id else None
                if action:
                    chain_from_line = int_value(action.get("chain_from_line"), int_value(action.get("line"), line_no))
                    chain_from_timestamp = str(
                        action.get("timestamp") or event_timestamp
                    )
                    combined = search_doc_text(
                        [correlation_id, action.get("text"), semantic],
                        max_chars=EPISODE_TEMPORAL_SCOPED_RAW_EVENT_MAX_CHARS,
                    )
                    tool_name = str(action.get("tool_name") or "")
                    command_text = str(action.get("command_text") or "")
                result_outcome = str(
                    structured_payload_outcome(payload)
                    or command_output_envelope_outcome(semantic)
                    or ""
                )
                running_identity = async_running_transport_identity_from_payload(payload)
                running_key = (
                    str(running_identity.get("kind") or ""),
                    str(running_identity.get("id") or ""),
                )
                if all(running_key) and action:
                    async_origins[running_key] = {
                        "line": int_value(action.get("chain_from_line"), int_value(action.get("line"), line_no)),
                        "timestamp": str(
                            action.get("timestamp") or event_timestamp
                        ),
                        "text": str(action.get("text") or ""),
                    }
                if correlation_id in wait_origins:
                    unit_kind = "async_action_wait_result_chain"
            elif payload_type in EPISODE_TEMPORAL_RAW_MCP_RECEIPT_TYPES:
                invocation = (
                    payload.get("invocation")
                    if isinstance(payload.get("invocation"), dict)
                    else {}
                )
                server = str(invocation.get("server") or "")
                invocation_tool = str(invocation.get("tool") or "")
                tool_name = (
                    f"mcp__{server}__{invocation_tool}"
                    if server and invocation_tool
                    else invocation_tool
                )
                arguments = (
                    invocation.get("arguments")
                    if isinstance(invocation.get("arguments"), dict)
                    else {}
                )
                result_outcome = str(
                    structured_payload_outcome(payload) or ""
                )
                combined = search_doc_text(
                    [
                        "mcp receipt",
                        payload_type,
                        correlation_id,
                        server,
                        invocation_tool,
                        episode_temporal_structured_argument_text(
                            tool_name,
                            arguments,
                        ),
                        result_outcome,
                    ],
                    max_chars=EPISODE_TEMPORAL_SCOPED_RAW_EVENT_MAX_CHARS,
                )
                semantic = combined
            if time_scope_requested:
                evidence_timestamps = [event_timestamp]
                if (
                    chain_from_line != line_no
                    or chain_from_timestamp != event_timestamp
                ):
                    evidence_timestamps.append(chain_from_timestamp)
                if not all(evidence_timestamps):
                    time_scope_unverifiable_event_count += 1
                    continue
                if any(
                    (normalized_time_from and timestamp < normalized_time_from)
                    or (normalized_time_to and timestamp > normalized_time_to)
                    for timestamp in evidence_timestamps
                ):
                    time_scope_filtered_event_count += 1
                    continue
            left_match = episode_temporal_raw_anchor_match(
                combined,
                left_terms,
                left_identifiers,
            )
            right_match = episode_temporal_raw_anchor_match(
                combined,
                right_terms,
                right_identifiers,
            )
            left_match = episode_temporal_merge_typed_alias_support(
                left_match,
                episode_temporal_structured_alias_support(
                    temporal_span.get("left_text"),
                    left_terms,
                    payload_type=payload_type,
                    tool_name=tool_name,
                    arguments=arguments,
                    agent_path=source_agent_path,
                ),
                left_terms,
            )
            right_match = episode_temporal_merge_typed_alias_support(
                right_match,
                episode_temporal_structured_alias_support(
                    temporal_span.get("right_text"),
                    right_terms,
                    payload_type=payload_type,
                    tool_name=tool_name,
                    arguments=arguments,
                    agent_path=source_agent_path,
                ),
                right_terms,
            )
            left_match = episode_temporal_enforce_direct_event_anchor(
                left_match,
                temporal_span.get("left_text"),
                unit_kind=unit_kind,
                payload_type=payload_type,
            )
            right_match = episode_temporal_enforce_direct_event_anchor(
                right_match,
                temporal_span.get("right_text"),
                unit_kind=unit_kind,
                payload_type=payload_type,
            )
            left_match = episode_temporal_enforce_structured_outcome_anchor(
                left_match,
                temporal_span.get("left_text"),
                unit_kind=unit_kind,
                result_outcome=result_outcome,
            )
            right_match = episode_temporal_enforce_structured_outcome_anchor(
                right_match,
                temporal_span.get("right_text"),
                unit_kind=unit_kind,
                result_outcome=result_outcome,
            )
            left_match = episode_temporal_enforce_explicit_quoted_anchor(
                left_match,
                temporal_span.get("left_text"),
                combined,
                match_policy=temporal_span.get("left_match_policy"),
                source_policy=temporal_span.get(
                    "quoted_anchor_source_policy"
                ),
                unit_kind=unit_kind,
            )
            right_match = episode_temporal_enforce_explicit_quoted_anchor(
                right_match,
                temporal_span.get("right_text"),
                combined,
                match_policy=temporal_span.get("right_match_policy"),
                source_policy=temporal_span.get(
                    "quoted_anchor_source_policy"
                ),
                unit_kind=unit_kind,
            )
            source_segment = (
                source.get("segment") if isinstance(source.get("segment"), dict) else {}
            )
            segment = source_segment or segment_for_line(segments, line_no)
            event_identity = ""
            event_identity_basis = ""
            if unit_kind == "structured_terminal_event":
                for identity_field in ("turn_id", "event_id", "id"):
                    identity_value = str(payload.get(identity_field) or "").strip()
                    if identity_value:
                        event_identity = identity_value
                        event_identity_basis = identity_field
                        break
            unit = {
                "line": line_no,
                "chain_from_line": chain_from_line,
                "kind": unit_kind,
                "source_lane": source_type,
                "payload_type": payload_type,
                "message_role": message_role,
                "timestamp": event_timestamp,
                "chain_from_timestamp": chain_from_timestamp,
                "correlation_id": correlation_id,
                "tool_name": tool_name,
                "command_text": command_text,
                "result_outcome": result_outcome,
                "event_identity": event_identity,
                "event_identity_basis": event_identity_basis,
                "action_stages": episode_temporal_operational_action_stages(
                    command_text
                ),
                "event_text": short_text(semantic, max_chars=700),
                "text": short_text(combined, max_chars=700),
                "refs": {
                    "raw": f"raw:line:{line_no}",
                    "segment": str(segment.get("markdown") or ""),
                    "segment_index": str(segment.get("index") or ""),
                    "raw_block": str(
                        source.get("raw_block_ref") or source.get("path") or ""
                    ),
                },
                "left": left_match,
                "right": right_match,
            }
            candidate: dict[str, Any] | None = None
            source_session_id = str(source.get("session_id") or "")
            for candidate_session_id, from_line, to_line, candidate in candidate_ranges:
                if (
                    source_session_id
                    and candidate_session_id
                    and source_session_id != candidate_session_id
                ):
                    continue
                if from_line <= line_no <= to_line:
                    break
            else:
                candidate = None
            if candidate is None:
                continue
            unit["doc_id"] = str(candidate.get("doc_id") or "")
            unit["session_id"] = str(candidate.get("session_id") or "")
            unit["task_episode_id"] = str(
                candidate.get("task_episode_id") or ""
            )
            doc_id = str(candidate.get("doc_id") or "")
            retain_interval_unit(doc_id=doc_id, unit=unit)
            if (
                not left_match["matched_query_terms"]
                and not right_match["matched_query_terms"]
            ):
                continue
            if left_match.get("typed_alias_support") or right_match.get(
                "typed_alias_support"
            ):
                typed_anchor_support_observed_count += 1
            matched_unit_observed_count += 1
            retain_candidate_evidence(doc_id=doc_id, side="left", unit=unit)
            retain_candidate_evidence(doc_id=doc_id, side="right", unit=unit)
        if line_budget_exhausted or byte_budget_exhausted:
            break

    source_integrity["usable_count"] = usable_source_count
    source_integrity["rejected_samples"] = source_integrity["rejected_samples"][:8]
    if candidate_block_mode:
        source_integrity["status"] = (
            "verified"
            if usable_source_count == len(prepared_sources)
            and not any(
                int_value(source_integrity.get(key))
                for key in (
                    "failed_count",
                    "unverified_count",
                    "missing_count",
                    "read_failure_count",
                    "coordinate_mismatch_count",
                )
            )
            else "partial"
            if usable_source_count
            else "failed"
        )
    if not usable_source_count:
        return clones, {
            **base_report,
            "status": (
                "raw_evidence_budget_exhausted"
                if line_budget_exhausted or byte_budget_exhausted
                else "candidate_raw_block_integrity_failed"
                if candidate_block_mode
                else "raw_source_unreadable"
            ),
            "raw_path": str(raw_path) if raw_path else "",
            "raw_bytes": raw_bytes,
            "stored_raw_bytes": stored_raw_bytes,
            "max_raw_bytes": max_raw_bytes,
            "max_lines": max_lines,
            "lines_scanned": lines_scanned,
            "decoded_bytes_scanned": decoded_bytes_scanned,
            "line_budget_exhausted": line_budget_exhausted,
            "byte_budget_exhausted": byte_budget_exhausted,
            "source_count": 0,
            "source_integrity": source_integrity,
            "elapsed_ms": int((time.monotonic() - started) * 1000),
        }

    matched_by_doc: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for doc_id in set(matched_left_by_doc) | set(matched_right_by_doc):
        units_by_key: dict[tuple[int, int, str, str], dict[str, Any]] = {}
        retained = list(matched_left_by_doc.get(doc_id, {}).values()) + list(
            matched_right_by_doc.get(doc_id, {}).values()
        )
        for _priority, unit in retained:
            key = (
                int_value(unit.get("line")),
                int_value(unit.get("chain_from_line")),
                str(unit.get("correlation_id") or ""),
                str(unit.get("kind") or ""),
            )
            units_by_key[key] = unit
        matched_by_doc[doc_id] = sorted(
            units_by_key.values(),
            key=lambda item: (int_value(item.get("line")), int_value(item.get("chain_from_line"))),
        )
    matched_unit_count = sum(len(items) for items in matched_by_doc.values())

    qualified_candidate_count = 0
    qualified_pair_count = 0

    def logical_anchor_key(anchor: dict[str, Any]) -> tuple[Any, ...]:
        if str(anchor.get("kind") or "") == "structured_terminal_event":
            payload_type = str(anchor.get("payload_type") or "")
            event_identity = str(anchor.get("event_identity") or "")
            return (
                "structured_terminal_event",
                payload_type,
                event_identity or f"raw:line:{int_value(anchor.get('line'))}",
            )
        matched_identifiers = tuple(sorted(str(value) for value in anchor.get("matched_identifiers", []) if value))
        if matched_identifiers:
            return ("query_identifier", *matched_identifiers)
        chain_from_line = int_value(anchor.get("chain_from_line"))
        if chain_from_line > 0:
            return ("chain_origin", chain_from_line)
        correlation_id = str(anchor.get("correlation_id") or "")
        if correlation_id:
            return ("correlation", correlation_id.casefold())
        return ("raw_line", int_value(anchor.get("line")))

    def anchor_source_profile(anchor_text: Any) -> str:
        lowered = str(anchor_text or "").casefold()
        if re.search(
            r"\b(?:diagnos\w*|interpret\w*|conclusion\w*|assessment\w*|"
            r"диагност\w*|интерпретац\w*|вывод\w*|объяснен\w*|оценк\w*)\b",
            lowered,
            flags=re.IGNORECASE,
        ):
            return "interpretive_observation"
        if re.search(
            r"\b(?:check\w*|verif\w*|call\w*|command\w*|output\w*|result\w*|"
            r"error\w*|fail\w*|tool\w*|провер\w*|вызов\w*|команд\w*|"
            r"вывод\w*|результат\w*|ошиб\w*|сбо\w*)\b",
            lowered,
            flags=re.IGNORECASE,
        ):
            return "structured_operational_observation"
        return "source_aware_observation"

    def anchor_source_priority(
        anchor: dict[str, Any],
        anchor_text: Any,
    ) -> tuple[int, int]:
        profile = anchor_source_profile(anchor_text)
        kind = str(anchor.get("kind") or anchor.get("event_kind") or "")
        role = str(anchor.get("message_role") or "")
        structured_result = kind in {
            "async_action_wait_result_chain",
            "structured_action_result_chain",
            "structured_mcp_receipt",
            "structured_terminal_event",
        }
        structured_action = kind == "structured_action"
        canonical_message = kind == "canonical_message_observation"
        if profile == "interpretive_observation":
            primary = (
                6
                if canonical_message and role == "assistant"
                else 5
                if canonical_message and role == "user"
                else 4
                if structured_result
                else 3
                if structured_action
                else 1
            )
        elif profile == "structured_operational_observation":
            primary = (
                6
                if structured_result
                else 5
                if structured_action
                else 4
                if canonical_message and role == "assistant"
                else 3
                if canonical_message and role == "user"
                else 1
            )
        else:
            primary = (
                5
                if structured_result
                else 4
                if canonical_message and role == "assistant"
                else 3
                if canonical_message and role == "user"
                else 2
                if structured_action
                else 1
            )
        return primary, 1 if role == "assistant" else 0

    def equivalent_anchor_observations(
        left_anchor: dict[str, Any],
        right_anchor: dict[str, Any],
        *,
        query_identifiers: list[str],
    ) -> bool:
        if logical_anchor_key(left_anchor) == logical_anchor_key(right_anchor):
            return True
        # Exact identifiers identify one requested anchor.  Do not merge a
        # nearby lexical reflection unless it resolves to that same logical
        # identifier/correlation chain.
        if query_identifiers:
            return False
        left_correlation = str(left_anchor.get("correlation_id") or "")
        right_correlation = str(right_anchor.get("correlation_id") or "")
        if (
            left_correlation
            and right_correlation
            and left_correlation != right_correlation
        ):
            return False
        left_terms = {
            str(value)
            for value in left_anchor.get("matched_query_terms", [])
            if value
        }
        right_terms = {
            str(value)
            for value in right_anchor.get("matched_query_terms", [])
            if value
        }
        if not left_terms or left_terms != right_terms:
            return False
        if min(
            float(left_anchor.get("coverage") or 0.0),
            float(right_anchor.get("coverage") or 0.0),
        ) < EPISODE_TEMPORAL_SPAN_MIN_ANCHOR_COVERAGE:
            return False
        left_line = int_value(left_anchor.get("line"))
        right_line = int_value(right_anchor.get("line"))
        if (
            left_line <= 0
            or right_line <= 0
            or abs(right_line - left_line)
            > EPISODE_TEMPORAL_SCOPED_RAW_ADJACENT_MAX_DISTANCE_LINES
        ):
            return False
        left_kind = str(left_anchor.get("kind") or "")
        right_kind = str(right_anchor.get("kind") or "")
        left_message = left_kind == "canonical_message_observation"
        right_message = right_kind == "canonical_message_observation"
        left_structured = left_kind in {
            "structured_action",
            "structured_action_result_chain",
            "async_action_wait_result_chain",
            "structured_mcp_receipt",
            "structured_terminal_event",
        }
        right_structured = right_kind in {
            "structured_action",
            "structured_action_result_chain",
            "async_action_wait_result_chain",
            "structured_mcp_receipt",
            "structured_terminal_event",
        }
        # A nearby canonical explanation and its structured action/result are
        # two observations of one local anchor.  Two messages or two distinct
        # structured correlations remain separate possible events.
        return (left_message and right_structured) or (
            right_message and left_structured
        )

    def clustered_anchor_candidates(
        candidates: list[dict[str, Any]],
        *,
        anchor_text: Any,
        query_identifiers: list[str],
    ) -> list[dict[str, Any]]:
        clusters: list[list[dict[str, Any]]] = []
        for candidate in sorted(
            candidates,
            key=lambda item: (
                int_value(item.get("line")),
                int_value(item.get("chain_from_line")),
            ),
        ):
            candidate_correlation = str(candidate.get("correlation_id") or "")
            destination: list[dict[str, Any]] | None = None
            for cluster in reversed(clusters):
                cluster_correlations = {
                    str(item.get("correlation_id") or "")
                    for item in cluster
                    if str(item.get("correlation_id") or "")
                }
                if (
                    candidate_correlation
                    and cluster_correlations
                    and candidate_correlation not in cluster_correlations
                    and not any(
                        logical_anchor_key(candidate)
                        == logical_anchor_key(existing)
                        for existing in cluster
                    )
                ):
                    continue
                if any(
                    equivalent_anchor_observations(
                        candidate,
                        existing,
                        query_identifiers=query_identifiers,
                    )
                    for existing in cluster
                ):
                    destination = cluster
                    break
            if destination is None:
                clusters.append([candidate])
            else:
                destination.append(candidate)
        representatives: list[dict[str, Any]] = []
        for cluster in clusters:
            representative = max(
                cluster,
                key=lambda anchor: (
                    anchor_source_priority(anchor, anchor_text),
                    float(anchor.get("coverage") or 0.0),
                    len(anchor.get("matched_query_terms", [])),
                    len(anchor.get("matched_identifiers", [])),
                    int_value(anchor.get("line")),
                ),
            )
            clone = dict(representative)
            clone["_source_profile"] = anchor_source_profile(anchor_text)
            clone["_source_priority"] = list(
                anchor_source_priority(representative, anchor_text)
            )
            clone["_equivalent_observations"] = sorted(
                (dict(item) for item in cluster),
                key=lambda item: int_value(item.get("line")),
            )
            representatives.append(clone)
        return representatives

    def compact_temporal_anchor(anchor: dict[str, Any]) -> dict[str, Any]:
        observations = [
            item
            for item in anchor.get("_equivalent_observations", [])
            if isinstance(item, dict)
        ]
        compact_observations = [
            {
                "line": int_value(item.get("line")),
                "chain_from_raw_ref": (
                    f"raw:line:{int_value(item.get('chain_from_line'))}"
                ),
                "timestamp": str(item.get("timestamp") or ""),
                "event_kind": str(item.get("kind") or ""),
                "message_role": str(item.get("message_role") or ""),
                "correlation_id": str(item.get("correlation_id") or ""),
                "event_identity": str(item.get("event_identity") or ""),
                "event_identity_basis": str(
                    item.get("event_identity_basis") or ""
                ),
                "coverage": round(float(item.get("coverage") or 0.0), 4),
                "matched_query_terms": list(
                    item.get("matched_query_terms") or []
                ),
                "refs": dict(item.get("refs") or {}),
            }
            for item in observations[:8]
        ]
        return {
            "line": int_value(anchor.get("line")),
            "chain_from_raw_ref": f"raw:line:{int_value(anchor.get('chain_from_line'))}",
            "timestamp": str(anchor.get("timestamp") or ""),
            "chain_from_timestamp": str(
                anchor.get("chain_from_timestamp")
                or anchor.get("timestamp")
                or ""
            ),
            "coverage": round(float(anchor.get("coverage") or 0.0), 4),
            "matched_query_terms": list(anchor.get("matched_query_terms") or []),
            "matched_identifiers": list(anchor.get("matched_identifiers") or []),
            "correlation_id": str(anchor.get("correlation_id") or ""),
            "event_kind": str(anchor.get("kind") or ""),
            "message_role": str(anchor.get("message_role") or ""),
            "tool_name": str(anchor.get("tool_name") or ""),
            "payload_type": str(anchor.get("payload_type") or ""),
            "result_outcome": str(anchor.get("result_outcome") or ""),
            "required_structured_outcome": str(
                anchor.get("required_structured_outcome") or ""
            ),
            "observed_structured_outcome": str(
                anchor.get("observed_structured_outcome") or ""
            ),
            "structured_outcome_proven": bool(
                anchor.get("structured_outcome_proven")
            ),
            "explicit_quoted_anchor_proven": bool(
                anchor.get("explicit_quoted_anchor_proven")
            ),
            "quoted_anchor_match_policy": str(
                anchor.get("quoted_anchor_match_policy") or ""
            ),
            "quoted_anchor_source_policy": str(
                anchor.get("quoted_anchor_source_policy") or ""
            ),
            "event_identity": str(anchor.get("event_identity") or ""),
            "event_identity_basis": str(
                anchor.get("event_identity_basis") or ""
            ),
            "typed_alias_support": dict(
                anchor.get("typed_alias_support") or {}
            ),
            "action_stages": list(anchor.get("action_stages") or []),
            "source_profile": str(anchor.get("_source_profile") or ""),
            "source_priority": list(anchor.get("_source_priority") or []),
            "equivalent_observation_count": len(observations) or 1,
            "equivalent_observations": compact_observations,
            "text": str(anchor.get("text") or ""),
            "refs": dict(anchor.get("refs") or {}),
        }

    def temporal_evidence_time_scope(
        anchors: Iterable[dict[str, Any]],
    ) -> dict[str, Any]:
        evidence_timestamps: list[str] = []
        for anchor in anchors:
            if not isinstance(anchor, dict):
                continue
            for value in (
                anchor.get("chain_from_timestamp"),
                anchor.get("timestamp"),
            ):
                normalized = normalized_temporal_timestamp(value)
                if normalized and normalized not in evidence_timestamps:
                    evidence_timestamps.append(normalized)
        timestamp_coverage_complete = bool(
            evidence_timestamps
            and all(
                normalized_temporal_timestamp(anchor.get("timestamp"))
                for anchor in anchors
                if isinstance(anchor, dict)
            )
        )
        all_evidence_in_requested_window = bool(
            time_scope_requested
            and timestamp_coverage_complete
            and all(
                (not normalized_time_from or timestamp >= normalized_time_from)
                and (not normalized_time_to or timestamp <= normalized_time_to)
                for timestamp in evidence_timestamps
            )
        )
        return {
            "status": (
                "all_temporal_evidence_in_requested_window"
                if all_evidence_in_requested_window
                else "temporal_time_scope_not_requested"
                if not time_scope_requested
                else "temporal_evidence_outside_or_missing_time_scope"
            ),
            "requested_time_from": normalized_time_from,
            "requested_time_to": normalized_time_to,
            "from_timestamp": min(evidence_timestamps, default=""),
            "to_timestamp": max(evidence_timestamps, default=""),
            "timestamp_coverage_complete": timestamp_coverage_complete,
            "all_evidence_in_requested_window": (
                all_evidence_in_requested_window
            ),
        }

    def compact_temporal_interval_event(
        unit: dict[str, Any],
    ) -> dict[str, Any]:
        candidate = candidate_by_doc_id.get(
            str(unit.get("doc_id") or ""),
            {},
        )
        candidate_refs = (
            candidate.get("refs")
            if isinstance(candidate.get("refs"), dict)
            else {}
        )
        refs = dict(unit.get("refs") or {})
        if not refs.get("segment"):
            refs["segment"] = str(
                candidate_refs.get("segment")
                or candidate.get("segment_ref")
                or ""
            )
        if not refs.get("session"):
            refs["session"] = str(
                candidate_refs.get("session")
                or candidate.get("session_ref")
                or ""
            )
        event_kind = str(unit.get("kind") or "")
        display_text = (
            str(unit.get("event_text") or "")
            if event_kind
            in {
                "structured_action_result_chain",
                "async_action_wait_result_chain",
                "structured_mcp_receipt",
                "structured_status_event",
            }
            else str(unit.get("text") or "")
        )
        return {
            "line": int_value(unit.get("line")),
            "timestamp": str(unit.get("timestamp") or ""),
            "chain_from_raw_ref": (
                f"raw:line:{int_value(unit.get('chain_from_line'))}"
            ),
            "event_kind": event_kind,
            "source_lane": str(unit.get("source_lane") or ""),
            "payload_type": str(unit.get("payload_type") or ""),
            "message_role": str(unit.get("message_role") or ""),
            "tool_name": str(unit.get("tool_name") or ""),
            "correlation_id": str(unit.get("correlation_id") or ""),
            "result_outcome": str(unit.get("result_outcome") or ""),
            "text": short_text(display_text, max_chars=700),
            "refs": refs,
        }

    def temporal_interval_contents_packet(
        *,
        session_id: str,
        left: dict[str, Any],
        right: dict[str, Any],
    ) -> dict[str, Any]:
        left_line = int_value(left.get("line"))
        right_line = int_value(right.get("line"))
        applicable_doc_ids = {
            str(candidate.get("doc_id") or "")
            for (
                candidate_session_id,
                candidate_from,
                candidate_to,
                candidate,
            ) in candidate_ranges
            if (
                (not session_id or candidate_session_id == session_id)
                and candidate_from < right_line
                and candidate_to > left_line
            )
        }
        units_by_key: dict[
            tuple[int, int, str, str],
            dict[str, Any],
        ] = {}
        for doc_id in applicable_doc_ids:
            for key, unit in interval_units_by_doc.get(doc_id, {}).items():
                line = int_value(unit.get("line"))
                if left_line < line < right_line:
                    units_by_key[key] = unit
        interval_units = sorted(
            units_by_key.values(),
            key=lambda item: (
                int_value(item.get("line")),
                int_value(item.get("chain_from_line")),
                str(item.get("kind") or ""),
            ),
        )
        retention_truncated = bool(
            applicable_doc_ids & interval_units_truncated_docs
        )
        output_truncated = (
            len(interval_units)
            > EPISODE_TEMPORAL_INTERVAL_OUTPUT_EVENT_LIMIT
        )
        source_read_truncated = bool(
            line_budget_exhausted
            or byte_budget_exhausted
            or (
                candidate_block_mode
                and source_integrity.get("status") != "verified"
            )
        )
        truncated = bool(
            retention_truncated
            or output_truncated
            or source_read_truncated
        )
        returned_units = interval_units[
            :EPISODE_TEMPORAL_INTERVAL_OUTPUT_EVENT_LIMIT
        ]
        interval_time_scope = temporal_evidence_time_scope(
            returned_units
        )
        interval_time_scope_admitted = bool(
            not time_scope_requested
            or interval_time_scope.get(
                "all_evidence_in_requested_window"
            )
            is True
        )
        if not interval_units:
            status = "no_readable_interval_contents"
        elif truncated:
            status = "bounded_interval_contents_truncated"
        elif not interval_time_scope_admitted:
            status = "interval_contents_outside_requested_time_scope"
        else:
            status = "bounded_interval_contents_read"
        events = [
            compact_temporal_interval_event(unit)
            for unit in returned_units
        ]
        return {
            "status": status,
            "from_raw_ref": f"raw:line:{left_line}",
            "to_raw_ref": f"raw:line:{right_line}",
            "readable_event_count": len(interval_units),
            "returned_event_count": len(events),
            "omitted_event_count": max(
                0,
                len(interval_units) - len(events),
            ),
            "event_limit": EPISODE_TEMPORAL_INTERVAL_OUTPUT_EVENT_LIMIT,
            "truncated": truncated,
            "retention_truncated": retention_truncated,
            "output_truncated": output_truncated,
            "source_read_truncated": source_read_truncated,
            "events": events,
            "event_raw_refs": [
                str((item.get("refs") or {}).get("raw") or "")
                for item in events
            ],
            "evidence_time_scope": interval_time_scope,
            "content_policy": {
                "source_lanes": [
                    "canonical_user_or_assistant_message",
                    "structured_tool_call_or_result",
                    "structured_operational_status",
                ],
                "hidden_reasoning_included": False,
                "token_count_included": False,
                "runtime_message_mirror_included": False,
                "private_message_body_read": False,
            },
            "authority": (
                "hash_verified_archived_raw_blocks"
                if candidate_block_mode
                else "raw_session_transcript"
            ),
        }

    for item in clones:
        units = matched_by_doc.get(str(item.get("doc_id") or ""), [])
        left_candidates: list[dict[str, Any]] = []
        right_candidates: list[dict[str, Any]] = []
        for unit in units:
            if (unit.get("left") or {}).get("matched_query_terms"):
                left_candidate = {**unit, **unit["left"]}
                if episode_temporal_left_candidate_allowed(
                    left_candidate,
                    temporal_span,
                ):
                    left_candidates.append(left_candidate)
            if (unit.get("right") or {}).get("matched_query_terms"):
                right_candidates.append({**unit, **unit["right"]})
        observed_left_candidates = left_candidates
        observed_right_candidates = right_candidates
        left_candidates = clustered_anchor_candidates(
            observed_left_candidates,
            anchor_text=temporal_span.get("left_text"),
            query_identifiers=left_identifiers,
        )
        right_candidates = clustered_anchor_candidates(
            observed_right_candidates,
            anchor_text=temporal_span.get("right_text"),
            query_identifiers=right_identifiers,
        )

        def admitted_pairs(
            candidate_left: list[dict[str, Any]],
            candidate_right: list[dict[str, Any]],
        ) -> list[
            tuple[
                tuple[float, ...],
                tuple[float, ...],
                str,
                dict[str, Any],
                dict[str, Any],
            ]
        ]:
            admitted: list[
                tuple[
                    tuple[float, ...],
                    tuple[float, ...],
                    str,
                    dict[str, Any],
                    dict[str, Any],
                ]
            ] = []
            for left in candidate_left:
                for right in candidate_right:
                    if int_value(right.get("line")) <= int_value(left.get("line")):
                        continue
                    admission_basis = episode_temporal_raw_pair_admission(
                        left,
                        right,
                        left_identifiers=left_identifiers,
                        right_identifiers=right_identifiers,
                        left_required_qualifier_terms=(
                            left_required_qualifier_terms
                        ),
                        right_required_qualifier_terms=(
                            right_required_qualifier_terms
                        ),
                    )
                    if not admission_basis:
                        continue
                    left_coverage = float(left.get("coverage") or 0.0)
                    right_coverage = float(right.get("coverage") or 0.0)
                    distance = int_value(right.get("line")) - int_value(left.get("line"))
                    identifier_score = len(left.get("matched_identifiers", [])) + len(right.get("matched_identifiers", []))
                    basis_score = 2 if "full_anchor_coverage" in admission_basis else 1
                    semantic_score = (
                        float(identifier_score),
                        float(basis_score),
                        min(left_coverage, right_coverage),
                        (left_coverage + right_coverage) / 2.0,
                    )
                    left_source_priority = anchor_source_priority(
                        left,
                        temporal_span.get("left_text"),
                    )
                    right_source_priority = anchor_source_priority(
                        right,
                        temporal_span.get("right_text"),
                    )
                    presentation_score = (
                        *semantic_score,
                        float(left_source_priority[0] + right_source_priority[0]),
                        float(left_source_priority[1] + right_source_priority[1]),
                        float(-distance),
                    )
                    admitted.append(
                        (
                            presentation_score,
                            semantic_score,
                            admission_basis,
                            left,
                            right,
                        )
                    )
            return admitted

        observed_pairs = admitted_pairs(
            observed_left_candidates,
            observed_right_candidates,
        )
        pairs = admitted_pairs(left_candidates, right_candidates)
        if not pairs:
            continue
        observed_pair_count = len(observed_pairs)
        distinct_admissible_pair_count = len(pairs)
        pairs.sort(key=lambda pair: pair[0], reverse=True)
        top_semantic_score = pairs[0][1]
        competitive_pairs = [
            pair for pair in pairs if pair[1] == top_semantic_score
        ]
        lower_quality_pair_count = len(pairs) - len(competitive_pairs)
        pairs = competitive_pairs
        _score, _semantic_score, admission_basis, left, right = pairs[0]
        minimum_coverage = min(float(left.get("coverage") or 0.0), float(right.get("coverage") or 0.0))

        alternative_ordered_spans = [
            {
                "admission_basis": alternative_basis,
                "semantic_score": [round(value, 4) for value in semantic_score],
                "left": compact_temporal_anchor(alternative_left),
                "right": compact_temporal_anchor(alternative_right),
                "distance_lines": (
                    int_value(alternative_right.get("line"))
                    - int_value(alternative_left.get("line"))
                ),
            }
            for (
                _presentation_score,
                semantic_score,
                alternative_basis,
                alternative_left,
                alternative_right,
            ) in pairs[1:5]
        ]
        collapsed_equivalent_pair_count = max(
            0,
            observed_pair_count - distinct_admissible_pair_count,
        )
        answer_scope = str(
            temporal_span.get("answer_scope") or "ordered_relation"
        )
        interval_contents = (
            temporal_interval_contents_packet(
                session_id=str(item.get("session_id") or ""),
                left=left,
                right=right,
            )
            if answer_scope == "interval_contents"
            else {}
        )
        temporal_span_payload = {
            "active": True,
            "status": "ordered_span_found",
            "accepted": True,
            "answer_scope": answer_scope,
            "admission_basis": admission_basis,
            "evidence_source": (
                "hash_verified_candidate_raw_blocks"
                if candidate_block_mode
                else "scoped_raw_structured_chain"
            ),
            "minimum_anchor_coverage": round(minimum_coverage, 4),
            "left": compact_temporal_anchor(left),
            "right": compact_temporal_anchor(right),
            "distance_lines": int_value(right.get("line")) - int_value(left.get("line")),
            "qualified_pair_count": len(pairs),
            "distinct_admissible_pair_count": distinct_admissible_pair_count,
            "lower_quality_pair_count": lower_quality_pair_count,
            "qualified_pair_observation_count": observed_pair_count,
            "collapsed_equivalent_pair_count": collapsed_equivalent_pair_count,
            "alternative_ordered_span_count": max(0, len(pairs) - 1),
            "alternative_ordered_spans": alternative_ordered_spans,
            "ambiguous_within_episode": len(pairs) > 1,
            "ranking_boost": 130.0 if admission_basis.startswith("identifier_backed") else 110.0,
            "evidence_time_scope": temporal_evidence_time_scope(
                [left, right]
            ),
            "authority": (
                "hash_verified_archived_raw_blocks"
                if candidate_block_mode
                else "raw_session_transcript"
            ),
        }
        if interval_contents:
            temporal_span_payload.update(
                {
                    "interval_contents_status": str(
                        interval_contents.get("status") or ""
                    ),
                    "interval_contents": interval_contents,
                }
            )
            if (
                interval_contents.get("status")
                == "bounded_interval_contents_read"
            ):
                item["reading_contract"] = {
                    **(
                        item.get("reading_contract")
                        if isinstance(item.get("reading_contract"), dict)
                        else {}
                    ),
                    "status": "bounded_raw_interval_read",
                    "support_scope": "ordered_temporal_interval",
                    "accepted_claim_requires": (
                        "use only returned interval events and preserve "
                        "their raw/segment/session refs"
                    ),
                    "authority": (
                        "hash_verified_archived_raw_blocks"
                        if candidate_block_mode
                        else "raw_session_transcript"
                    ),
                }
        item["temporal_span"] = temporal_span_payload
        qualified_candidate_count += 1
        qualified_pair_count += len(pairs)
    cross_episode_pairs_by_target: dict[
        str,
        list[
            tuple[
                tuple[float, ...],
                str,
                dict[str, Any],
                dict[str, Any],
                dict[str, Any],
                dict[str, Any],
            ]
        ],
    ] = defaultdict(list)
    for left_item in clones:
        left_doc_id = str(left_item.get("doc_id") or "")
        left_session_id = str(left_item.get("session_id") or "")
        left_range = (
            left_item.get("event_range")
            if isinstance(left_item.get("event_range"), dict)
            else {}
        )
        left_to = int_value(left_range.get("to_line"))
        left_units = matched_by_doc.get(left_doc_id, [])
        left_candidates = [
            {**unit, **unit["left"]}
            for unit in left_units
            if (unit.get("left") or {}).get("matched_query_terms")
            and episode_temporal_left_candidate_allowed(
                {**unit, **unit["left"]},
                temporal_span,
            )
        ]
        if not left_candidates or left_to <= 0:
            continue
        for right_item in clones:
            right_doc_id = str(right_item.get("doc_id") or "")
            if right_doc_id == left_doc_id:
                continue
            right_session_id = str(right_item.get("session_id") or "")
            if left_session_id and right_session_id and left_session_id != right_session_id:
                continue
            right_range = (
                right_item.get("event_range")
                if isinstance(right_item.get("event_range"), dict)
                else {}
            )
            right_from = int_value(right_range.get("from_line"))
            episode_gap = right_from - left_to
            if (
                right_from <= left_to
                or episode_gap
                > EPISODE_TEMPORAL_SCOPED_RAW_CROSS_EPISODE_MAX_DISTANCE_LINES
            ):
                continue
            right_units = matched_by_doc.get(right_doc_id, [])
            right_candidates = [
                {**unit, **unit["right"]}
                for unit in right_units
                if (unit.get("right") or {}).get("matched_query_terms")
                and str(unit.get("kind") or "")
                in {
                    "structured_action",
                    "structured_action_result_chain",
                    "async_action_wait_result_chain",
                    "structured_mcp_receipt",
                }
            ]
            for left in left_candidates:
                for right in right_candidates:
                    distance = int_value(right.get("line")) - int_value(left.get("line"))
                    if (
                        distance <= 0
                        or distance
                        > EPISODE_TEMPORAL_SCOPED_RAW_CROSS_EPISODE_MAX_DISTANCE_LINES
                    ):
                        continue
                    admission_basis = episode_temporal_raw_pair_admission(
                        left,
                        right,
                        left_identifiers=left_identifiers,
                        right_identifiers=right_identifiers,
                        left_required_qualifier_terms=(
                            left_required_qualifier_terms
                        ),
                        right_required_qualifier_terms=(
                            right_required_qualifier_terms
                        ),
                    )
                    if not admission_basis:
                        continue
                    left_coverage = float(left.get("coverage") or 0.0)
                    right_coverage = float(right.get("coverage") or 0.0)
                    result_chain_score = (
                        2.0
                        if str(right.get("kind") or "")
                        in {
                            "structured_action_result_chain",
                            "async_action_wait_result_chain",
                            "structured_mcp_receipt",
                        }
                        else 1.0
                    )
                    score = (
                        float(
                            len(left.get("matched_identifiers", []))
                            + len(right.get("matched_identifiers", []))
                        ),
                        2.0 if admission_basis == "full_anchor_coverage" else 1.0,
                        min(left_coverage, right_coverage),
                        (left_coverage + right_coverage) / 2.0,
                        result_chain_score,
                        float(-distance),
                    )
                    cross_episode_pairs_by_target[right_doc_id].append(
                        (
                            score,
                            admission_basis,
                            left,
                            right,
                            left_item,
                            right_item,
                        )
                    )
    cross_episode_qualified_pair_count = 0
    cross_episode_qualified_candidate_count = 0
    for right_doc_id, cross_pairs in cross_episode_pairs_by_target.items():
        carrier = next(
            (
                item
                for item in clones
                if str(item.get("doc_id") or "") == right_doc_id
            ),
            None,
        )
        if carrier is None:
            continue
        existing_span = (
            carrier.get("temporal_span")
            if isinstance(carrier.get("temporal_span"), dict)
            else {}
        )
        if (
            existing_span.get("status") == "ordered_span_found"
            and existing_span.get("accepted") is True
        ):
            continue
        logical_cross_pairs: dict[
            tuple[tuple[Any, ...], tuple[Any, ...]],
            tuple[
                tuple[float, ...],
                str,
                dict[str, Any],
                dict[str, Any],
                dict[str, Any],
                dict[str, Any],
            ],
        ] = {}
        for pair in cross_pairs:
            score, _basis, left, right, _left_item, _right_item = pair
            key = (logical_anchor_key(left), logical_anchor_key(right))
            previous = logical_cross_pairs.get(key)
            if previous is None or score > previous[0]:
                logical_cross_pairs[key] = pair
        ranked_cross_pairs = sorted(
            logical_cross_pairs.values(),
            key=lambda pair: pair[0],
            reverse=True,
        )
        if not ranked_cross_pairs:
            continue
        (
            _score,
            admission_basis,
            left,
            right,
            left_item,
            right_item,
        ) = ranked_cross_pairs[0]
        minimum_coverage = min(
            float(left.get("coverage") or 0.0),
            float(right.get("coverage") or 0.0),
        )
        answer_scope = str(
            temporal_span.get("answer_scope") or "ordered_relation"
        )
        interval_contents = (
            temporal_interval_contents_packet(
                session_id=str(carrier.get("session_id") or ""),
                left=left,
                right=right,
            )
            if answer_scope == "interval_contents"
            else {}
        )
        temporal_span_payload = {
            "active": True,
            "status": "ordered_span_found",
            "accepted": True,
            "answer_scope": answer_scope,
            "admission_basis": f"cross_episode_{admission_basis}",
            "evidence_source": (
                "hash_verified_candidate_raw_blocks"
                if candidate_block_mode
                else "scoped_raw_structured_chain"
            ),
            "minimum_anchor_coverage": round(minimum_coverage, 4),
            "left": compact_temporal_anchor(left),
            "right": compact_temporal_anchor(right),
            "distance_lines": int_value(right.get("line"))
            - int_value(left.get("line")),
            "cross_episode": True,
            "source_episode_id": str(left_item.get("task_episode_id") or ""),
            "target_episode_id": str(right_item.get("task_episode_id") or ""),
            "qualified_pair_count": len(ranked_cross_pairs),
            "distinct_admissible_pair_count": len(
                ranked_cross_pairs
            ),
            "qualified_pair_observation_count": len(cross_pairs),
            "collapsed_equivalent_pair_count": len(cross_pairs)
            - len(ranked_cross_pairs),
            "alternative_ordered_span_count": max(0, len(ranked_cross_pairs) - 1),
            "ambiguous_within_episode": False,
            "ranking_boost": 140.0,
            "evidence_time_scope": temporal_evidence_time_scope(
                [left, right]
            ),
            "authority": (
                "hash_verified_archived_raw_blocks"
                if candidate_block_mode
                else "raw_session_transcript"
            ),
        }
        if interval_contents:
            temporal_span_payload.update(
                {
                    "interval_contents_status": str(
                        interval_contents.get("status") or ""
                    ),
                    "interval_contents": interval_contents,
                }
            )
            if (
                interval_contents.get("status")
                == "bounded_interval_contents_read"
            ):
                carrier["reading_contract"] = {
                    **(
                        carrier.get("reading_contract")
                        if isinstance(
                            carrier.get("reading_contract"),
                            dict,
                        )
                        else {}
                    ),
                    "status": "bounded_raw_interval_read",
                    "support_scope": "ordered_temporal_interval",
                    "accepted_claim_requires": (
                        "use only returned interval events and preserve "
                        "their raw/segment/session refs"
                    ),
                    "authority": (
                        "hash_verified_archived_raw_blocks"
                        if candidate_block_mode
                        else "raw_session_transcript"
                    ),
                }
        carrier["temporal_span"] = temporal_span_payload
        cross_episode_qualified_candidate_count += 1
        cross_episode_qualified_pair_count += len(ranked_cross_pairs)
        qualified_candidate_count += 1
        qualified_pair_count += len(ranked_cross_pairs)
    action_sequence_requirements = [
        str(value)
        for value in temporal_span.get("right_action_requirements", [])
        if str(value)
    ]
    action_sequence_report: dict[str, Any] = {
        "status": "not_requested",
        "required": bool(
            temporal_span.get("right_action_sequence_required")
        ),
        "required_stages": action_sequence_requirements,
        "candidate_sequence_count": 0,
        "applied": False,
    }
    if (
        temporal_span.get("right_action_sequence_required")
        and len(action_sequence_requirements) >= 2
    ):
        sequence_units: list[dict[str, Any]] = []
        seen_sequence_units: set[
            tuple[str, int, int, str, str]
        ] = set()
        for doc_id, units in matched_by_doc.items():
            for unit in units:
                unit_key = (
                    doc_id,
                    int_value(unit.get("line")),
                    int_value(unit.get("chain_from_line")),
                    str(unit.get("correlation_id") or ""),
                    str(unit.get("kind") or ""),
                )
                if unit_key in seen_sequence_units:
                    continue
                seen_sequence_units.add(unit_key)
                sequence_units.append(unit)
        sequence_units.sort(
            key=lambda item: (
                int_value(item.get("line")),
                int_value(item.get("chain_from_line")),
            )
        )
        sequence_left_candidates: list[dict[str, Any]] = []
        for unit in sequence_units:
            left_match = (
                unit.get("left")
                if isinstance(unit.get("left"), dict)
                else {}
            )
            if not left_match.get("matched_query_terms"):
                continue
            candidate = {**unit, **left_match}
            if not episode_temporal_left_candidate_allowed(
                candidate,
                temporal_span,
            ):
                continue
            full_left_match = episode_temporal_raw_anchor_match(
                str(unit.get("text") or ""),
                left_query_terms,
                left_identifiers,
            )
            candidate["full_query_coverage"] = float(
                full_left_match.get("coverage") or 0.0
            )
            candidate["full_query_matched_term_count"] = len(
                full_left_match.get("matched_query_terms") or []
            )
            sequence_left_candidates.append(candidate)
        sequence_candidates: list[
            tuple[
                tuple[float, ...],
                dict[str, Any],
                list[tuple[str, dict[str, Any]]],
            ]
        ] = []
        for left in sequence_left_candidates:
            left_line = int_value(left.get("line"))
            cursor_line = left_line
            selected_stages: list[tuple[str, dict[str, Any]]] = []
            for required_stage in action_sequence_requirements:
                eligible: list[dict[str, Any]] = []
                for unit in sequence_units:
                    unit_line = int_value(unit.get("line"))
                    if (
                        unit_line <= cursor_line
                        or unit_line - left_line
                        > EPISODE_TEMPORAL_SCOPED_RAW_ACTION_SEQUENCE_MAX_DISTANCE_LINES
                    ):
                        continue
                    if required_stage not in {
                        str(value)
                        for value in unit.get("action_stages", [])
                        if str(value)
                    }:
                        continue
                    if str(unit.get("kind") or "") not in {
                        "structured_action_result_chain",
                        "async_action_wait_result_chain",
                    }:
                        continue
                    if str(unit.get("result_outcome") or "") != "succeeded":
                        continue
                    right_match = (
                        unit.get("right")
                        if isinstance(unit.get("right"), dict)
                        else {}
                    )
                    matched_terms = [
                        str(value)
                        for value in right_match.get(
                            "matched_query_terms",
                            [],
                        )
                        if str(value)
                    ]
                    if (
                        float(right_match.get("coverage") or 0.0) < 0.5
                        or len(matched_terms) < 2
                    ):
                        continue
                    eligible.append({**unit, **right_match})
                if not eligible:
                    selected_stages = []
                    break
                eligible.sort(
                    key=lambda item: (
                        int_value(item.get("line")),
                        -float(item.get("coverage") or 0.0),
                        -len(item.get("matched_query_terms") or []),
                    )
                )
                selected = dict(eligible[0])
                if required_stage == "verification":
                    first_verification_line = int_value(
                        selected.get("line")
                    )
                    verification_supporting: list[dict[str, Any]] = []
                    previous_verification_line = first_verification_line
                    for anchor in eligible[1:]:
                        anchor_line = int_value(anchor.get("line"))
                        if anchor_line <= previous_verification_line:
                            continue
                        if (
                            anchor_line - first_verification_line
                            > EPISODE_TEMPORAL_SCOPED_RAW_ADJACENT_MAX_DISTANCE_LINES
                            or anchor_line - previous_verification_line
                            > EPISODE_TEMPORAL_SCOPED_RAW_VERIFICATION_BUNDLE_MAX_GAP_LINES
                        ):
                            break
                        verification_supporting.append(dict(anchor))
                        previous_verification_line = anchor_line
                    selected["_sequence_supporting_anchors"] = (
                        verification_supporting
                    )
                selected_stages.append((required_stage, selected))
                cursor_line = max(
                    [
                        int_value(selected.get("line")),
                        *[
                            int_value(anchor.get("line"))
                            for anchor in selected.get(
                                "_sequence_supporting_anchors",
                                [],
                            )
                            if isinstance(anchor, dict)
                        ],
                    ]
                )
            if len(selected_stages) != len(action_sequence_requirements):
                continue
            expected_role = str(
                temporal_span.get("left_expected_message_role") or ""
            )
            role_score = float(
                not expected_role
                or str(left.get("message_role") or "") == expected_role
            )
            minimum_stage_coverage = min(
                float(anchor.get("coverage") or 0.0)
                for _stage, anchor in selected_stages
            )
            final_selected = selected_stages[-1][1]
            completion_line = max(
                [
                    int_value(final_selected.get("line")),
                    *[
                        int_value(anchor.get("line"))
                        for anchor in final_selected.get(
                            "_sequence_supporting_anchors",
                            [],
                        )
                        if isinstance(anchor, dict)
                    ],
                ]
            )
            score = (
                role_score,
                float(left.get("full_query_coverage") or 0.0),
                float(left.get("full_query_matched_term_count") or 0),
                minimum_stage_coverage,
                float(-(completion_line - left_line)),
                float(-completion_line),
            )
            sequence_candidates.append((score, left, selected_stages))
        sequence_candidates.sort(key=lambda item: item[0], reverse=True)
        action_sequence_report["candidate_sequence_count"] = len(
            sequence_candidates
        )
        sequence_ambiguous = bool(
            len(sequence_candidates) > 1
            and sequence_candidates[0][0][:-1]
            == sequence_candidates[1][0][:-1]
            and (
                int_value(sequence_candidates[0][1].get("line"))
                != int_value(sequence_candidates[1][1].get("line"))
            )
        )
        if sequence_candidates and not sequence_ambiguous:
            _score, sequence_left, selected_stages = sequence_candidates[0]
            final_stage_primary = selected_stages[-1][1]
            final_stage_supporting = [
                anchor
                for anchor in final_stage_primary.get(
                    "_sequence_supporting_anchors",
                    [],
                )
                if isinstance(anchor, dict)
            ]
            final_stage_anchor = (
                final_stage_supporting[-1]
                if final_stage_supporting
                else final_stage_primary
            )
            carrier_doc_id = str(final_stage_anchor.get("doc_id") or "")
            carrier = next(
                (
                    item
                    for item in clones
                    if str(item.get("doc_id") or "") == carrier_doc_id
                ),
                None,
            )
            if carrier is not None:
                source_episode_ids = list(
                    dict.fromkeys(
                        [
                            str(sequence_left.get("task_episode_id") or ""),
                            *[
                                str(anchor.get("task_episode_id") or "")
                                for _stage, anchor in selected_stages
                            ],
                            *[
                                str(support.get("task_episode_id") or "")
                                for _stage, anchor in selected_stages
                                for support in anchor.get(
                                    "_sequence_supporting_anchors",
                                    [],
                                )
                                if isinstance(support, dict)
                            ],
                        ]
                    )
                )
                source_episode_ids = [
                    value for value in source_episode_ids if value
                ]

                stage_evidence_anchors: list[dict[str, Any]] = []
                for _stage, anchor in selected_stages:
                    stage_evidence_anchors.append(anchor)
                    stage_evidence_anchors.extend(
                        support
                        for support in anchor.get(
                            "_sequence_supporting_anchors",
                            [],
                        )
                        if isinstance(support, dict)
                    )
                evidence_anchors = [
                    sequence_left,
                    *stage_evidence_anchors,
                ]
                sequence_time_scope = temporal_evidence_time_scope(
                    evidence_anchors
                )
                for item in clones:
                    existing_span = (
                        item.get("temporal_span")
                        if isinstance(item.get("temporal_span"), dict)
                        else {}
                    )
                    if (
                        str(item.get("doc_id") or "") != carrier_doc_id
                        and existing_span.get("accepted") is True
                    ):
                        item["temporal_span"] = {
                            "active": True,
                            "status": (
                                "subsumed_by_complete_action_sequence"
                            ),
                            "accepted": False,
                            "sequence_carrier_episode_id": str(
                                carrier.get("task_episode_id") or ""
                            ),
                            "prior_admission_basis": str(
                                existing_span.get("admission_basis") or ""
                            ),
                            "authority": (
                                "component evidence retained on sequence carrier"
                            ),
                        }
                compact_left = compact_temporal_anchor(sequence_left)
                compact_stages = [
                    {
                        "stage": stage,
                        "episode_id": str(
                            anchor.get("task_episode_id") or ""
                        ),
                        "anchor": compact_temporal_anchor(anchor),
                        "supporting_anchors": [
                            compact_temporal_anchor(support)
                            for support in anchor.get(
                                "_sequence_supporting_anchors",
                                [],
                            )
                            if isinstance(support, dict)
                        ],
                    }
                    for stage, anchor in selected_stages
                ]
                minimum_anchor_coverage = min(
                    float(sequence_left.get("coverage") or 0.0),
                    *[
                        float(anchor.get("coverage") or 0.0)
                        for _stage, anchor in selected_stages
                    ],
                )
                carrier["temporal_span"] = {
                    "active": True,
                    "status": "ordered_span_found",
                    "accepted": True,
                    "admission_basis": (
                        "source_aware_complete_action_sequence"
                    ),
                    "evidence_source": (
                        "hash_verified_candidate_raw_blocks"
                        if candidate_block_mode
                        else "scoped_raw_structured_chain"
                    ),
                    "sequence_status": "ordered_complete_action_sequence",
                    "required_action_stages": action_sequence_requirements,
                    "matched_action_stages": [
                        stage for stage, _anchor in selected_stages
                    ],
                    "action_sequence": compact_stages,
                    "minimum_anchor_coverage": round(
                        minimum_anchor_coverage,
                        4,
                    ),
                    "left": compact_left,
                    "right": compact_temporal_anchor(final_stage_anchor),
                    "distance_lines": int_value(
                        final_stage_anchor.get("line")
                    )
                    - int_value(sequence_left.get("line")),
                    "cross_episode": len(source_episode_ids) > 1,
                    "source_episode_id": str(
                        sequence_left.get("task_episode_id") or ""
                    ),
                    "source_episode_ids": source_episode_ids,
                    "target_episode_id": str(
                        carrier.get("task_episode_id") or ""
                    ),
                    "qualified_pair_count": 1,
                    "qualified_pair_observation_count": sum(
                        1 + len(item.get("supporting_anchors") or [])
                        for item in compact_stages
                    ),
                    "collapsed_equivalent_pair_count": 0,
                    "alternative_ordered_span_count": max(
                        0,
                        len(sequence_candidates) - 1,
                    ),
                    "ambiguous_within_episode": False,
                    "ranking_boost": 180.0,
                    "evidence_time_scope": sequence_time_scope,
                    "authority": (
                        "hash_verified_archived_raw_blocks"
                        if candidate_block_mode
                        else "raw_session_transcript"
                    ),
                }
                qualified_candidate_count = 1
                qualified_pair_count = 1
                cross_episode_qualified_candidate_count = int(
                    len(source_episode_ids) > 1
                )
                cross_episode_qualified_pair_count = int(
                    len(source_episode_ids) > 1
                )
                action_sequence_report.update(
                    {
                        "status": "applied_complete",
                        "applied": True,
                        "carrier_episode_id": str(
                            carrier.get("task_episode_id") or ""
                        ),
                        "source_episode_ids": source_episode_ids,
                        "left_raw_ref": str(
                            (compact_left.get("refs") or {}).get("raw")
                            or ""
                        ),
                        "stage_raw_refs": {
                            item["stage"]: str(
                                (item["anchor"].get("refs") or {}).get(
                                    "raw"
                                )
                                or ""
                            )
                            for item in compact_stages
                        },
                        "stage_support_raw_refs": {
                            item["stage"]: [
                                str(
                                    (
                                        support.get("refs") or {}
                                    ).get("raw")
                                    or ""
                                )
                                for support in (
                                    item.get("supporting_anchors") or []
                                )
                            ]
                            for item in compact_stages
                        },
                    }
                )
        elif sequence_ambiguous:
            action_sequence_report["status"] = (
                "ambiguous_complete_action_sequences"
            )
            action_sequence_report["candidate_samples"] = [
                {
                    "left_raw_ref": str(
                        ((compact_temporal_anchor(left).get("refs") or {}).get("raw"))
                        or ""
                    ),
                    "stage_raw_refs": {
                        stage: str(
                            (
                                (
                                    compact_temporal_anchor(anchor).get(
                                        "refs"
                                    )
                                    or {}
                                ).get("raw")
                            )
                            or ""
                        )
                        for stage, anchor in selected
                    },
                }
                for _score, left, selected in sequence_candidates[:4]
            ]
        else:
            action_sequence_report["status"] = (
                "required_action_sequence_incomplete"
            )
        if not action_sequence_report.get("applied"):
            for item in clones:
                existing_span = (
                    item.get("temporal_span")
                    if isinstance(item.get("temporal_span"), dict)
                    else {}
                )
                if existing_span.get("accepted") is True:
                    item["temporal_span"] = {
                        "active": True,
                        "status": str(
                            action_sequence_report.get("status")
                            or "required_action_sequence_incomplete"
                        ),
                        "accepted": False,
                        "required_action_stages": (
                            action_sequence_requirements
                        ),
                        "prior_admission_basis": str(
                            existing_span.get("admission_basis") or ""
                        ),
                        "authority": (
                            "partial pair cannot prove the asserted action sequence"
                        ),
                    }
            qualified_candidate_count = 0
            qualified_pair_count = 0
            cross_episode_qualified_candidate_count = 0
            cross_episode_qualified_pair_count = 0
    status = "applied"
    if (
        line_budget_exhausted
        or byte_budget_exhausted
        or matched_unit_truncated
        or source_integrity.get("status") == "partial"
    ):
        status = "applied_truncated"
    return clones, {
        **base_report,
        "status": status,
        "applied": True,
        "raw_path": str(raw_path) if raw_path else "",
        "raw_bytes": raw_bytes,
        "stored_raw_bytes": stored_raw_bytes,
        "max_raw_bytes": max_raw_bytes,
        "max_lines": max_lines,
        "lines_scanned": min(lines_scanned, max_lines),
        "decoded_bytes_scanned": decoded_bytes_scanned,
        "parsed_event_count": parsed_event_count,
        "admitted_event_count": admitted_event_count,
        "time_scope_requested": time_scope_requested,
        "requested_time_from": normalized_time_from,
        "requested_time_to": normalized_time_to,
        "time_scope_filtered_event_count": time_scope_filtered_event_count,
        "time_scope_unverifiable_event_count": (
            time_scope_unverifiable_event_count
        ),
        "source_count": usable_source_count,
        "source_integrity": source_integrity,
        "left_anchor_term_basis": left_term_basis,
        "right_anchor_term_basis": right_term_basis,
        "left_query_term_count": len(left_query_terms),
        "right_query_term_count": len(right_query_terms),
        "left_effective_anchor_term_count": len(left_terms),
        "right_effective_anchor_term_count": len(right_terms),
        "left_required_qualifier_terms": left_required_qualifier_terms,
        "right_required_qualifier_terms": right_required_qualifier_terms,
        "retention_policy": "bounded_candidate_evidence_priority",
        "candidate_side_limit": candidate_side_limit,
        "interval_unit_limit": interval_unit_limit,
        "interval_retained_unit_count": sum(
            len(items) for items in interval_units_by_doc.values()
        ),
        "interval_truncated_candidate_count": len(
            interval_units_truncated_docs
        ),
        "matched_unit_observed_count": matched_unit_observed_count,
        "matched_unit_count": matched_unit_count,
        "typed_anchor_support_observed_count": (
            typed_anchor_support_observed_count
        ),
        "matched_unit_truncated": matched_unit_truncated,
        "line_budget_exhausted": line_budget_exhausted,
        "byte_budget_exhausted": byte_budget_exhausted,
        "qualified_candidate_count": qualified_candidate_count,
        "qualified_pair_count": qualified_pair_count,
        "cross_episode_qualified_candidate_count": (
            cross_episode_qualified_candidate_count
        ),
        "cross_episode_qualified_pair_count": cross_episode_qualified_pair_count,
        "action_sequence": action_sequence_report,
        "elapsed_ms": int((time.monotonic() - started) * 1000),
        "authority_boundary": "raw transcript evidence hydrated read-only; episode remains navigation",
    }


def episode_temporal_relation_gate(
    results: list[dict[str, Any]],
    temporal_span: dict[str, Any],
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    if not temporal_span.get("active"):
        return results, {
            "status": "not_applied",
            "candidate_count": len(results),
            "qualified_count": len(results),
            "rejected_count": 0,
        }
    qualified: list[dict[str, Any]] = []
    rejected: list[dict[str, Any]] = []
    for item in results:
        evidence = item.get("temporal_span") if isinstance(item.get("temporal_span"), dict) else {}
        minimum_coverage = float(evidence.get("minimum_anchor_coverage") or 0.0)
        if (
            evidence.get("status") == "ordered_span_found"
            and (
                evidence.get("accepted") is True
                or minimum_coverage >= EPISODE_TEMPORAL_SPAN_MIN_ANCHOR_COVERAGE
            )
        ):
            qualified.append(item)
            continue
        rejected.append(
            {
                "doc_id": str(item.get("doc_id") or ""),
                "session_id": str(item.get("session_id") or ""),
                "task_episode_id": str(item.get("task_episode_id") or ""),
                "status": str(evidence.get("status") or "temporal_span_missing"),
                "minimum_anchor_coverage": round(minimum_coverage, 4),
                "left_raw_ref": str(((evidence.get("left") or {}).get("refs") or {}).get("raw") or ""),
                "right_raw_ref": str(((evidence.get("right") or {}).get("refs") or {}).get("raw") or ""),
            }
        )
    ambiguous_within_episode = sum(
        1
        for item in qualified
        if isinstance(item.get("temporal_span"), dict)
        and item["temporal_span"].get("ambiguous_within_episode") is True
    )
    ambiguous = len(qualified) > 1 or ambiguous_within_episode > 0
    return qualified, {
        "status": (
            "ambiguous_ordered_spans_available"
            if ambiguous
            else "qualified_ordered_spans_available"
            if qualified
            else "no_qualified_ordered_span"
        ),
        "minimum_anchor_coverage": EPISODE_TEMPORAL_SPAN_MIN_ANCHOR_COVERAGE,
        "candidate_count": len(results),
        "qualified_count": len(qualified),
        "rejected_count": len(rejected),
        "ambiguous": ambiguous,
        "ambiguous_within_episode_count": ambiguous_within_episode,
        "rejected_samples": rejected[:5],
        "policy": "explicit temporal-span queries expose only source-backed ordered anchors; multiple qualified chains remain ambiguous rather than becoming one answer",
    }


EPISODE_OPERATIONAL_READ_COMMAND_RE = re.compile(
    r"(?:^|(?:&&|\|\||[;|])\s*)(?:env\s+)?(?:[A-Za-z_][A-Za-z0-9_]*=[^\s]+\s+)*"
    r"(?:sudo\s+)?(?:sed|cat|head|tail|less|bat|rg|grep|wc)\b",
    flags=re.IGNORECASE,
)
EPISODE_OPERATIONAL_PATH_RE = re.compile(
    r"(?<![A-Za-z0-9_.-])(?:\.{0,2}/|/)?[A-Za-z0-9_.-]+(?:/[A-Za-z0-9_.-]+)+"
)
CUSTOM_EXEC_NESTED_COMMAND_LITERAL_RE = re.compile(
    r"\btools\.exec_command\s*\(\s*\{[^{}]{0,8192}?"
    r"(?:[\"']?(?:cmd|command|shell_command)[\"']?)\s*:\s*"
    r"(?P<literal>\"(?:\\.|[^\"\\])*\"|'(?:\\.|[^'\\])*')",
    flags=re.DOTALL,
)
CUSTOM_EXEC_NESTED_WORKDIR_LITERAL_RE = re.compile(
    r"\btools\.exec_command\s*\(\s*\{[^{}]{0,8192}?"
    r"(?:[\"']?workdir[\"']?)\s*:\s*"
    r"(?P<literal>\"(?:\\.|[^\"\\])*\"|'(?:\\.|[^'\\])*')",
    flags=re.DOTALL,
)


def custom_exec_shell_commands(payload: dict[str, Any]) -> list[str]:
    if (
        str(payload.get("type") or "") != "custom_tool_call"
        or normalized_tool_name(tool_name_from_payload(payload)) != "exec"
    ):
        return []
    source = payload.get("input")
    if not isinstance(source, str) or not source.strip():
        return []
    bounded_source = source[:131072]
    commands: list[str] = []
    for match in CUSTOM_EXEC_NESTED_COMMAND_LITERAL_RE.finditer(bounded_source):
        try:
            value = literal_eval_untrusted_source(match.group("literal"))
        except (SyntaxError, ValueError):
            continue
        if isinstance(value, str) and value.strip() and value.strip() not in commands:
            commands.append(value.strip())
        if len(commands) >= 16:
            break
    if commands:
        return commands
    if "tools." not in bounded_source:
        return [bounded_source.strip()]
    return []


SESSION_MEMORY_QUERY_DEMAND_CLI_COMMANDS = frozenset(
    {
        *TASK_EPISODE_RETRIEVAL_CONTROL_COMMANDS,
        "evidence-window",
        "goal-lifecycles",
        "rehydrate",
        "search-provider-status",
    }
)
SESSION_MEMORY_QUERY_DEMAND_POSITIONAL_SESSION_COMMANDS = frozenset(
    {"evidence-window", "rehydrate", "task-episodes"}
)
SESSION_MEMORY_QUERY_DEMAND_SESSION_FLAGS = frozenset(
    {"--session", "--session-id", "--session_id"}
)
SESSION_MEMORY_QUERY_DEMAND_MCP_CALL_RE = re.compile(
    r"\btools\.(?P<name>mcp__aoa_session_memory__[A-Za-z0-9_]+)\s*\("
)
CUSTOM_EXEC_NESTED_TOOL_CALL_RE = re.compile(
    r"\btools\.(?P<name>[A-Za-z_][A-Za-z0-9_]*)\s*\("
)
SESSION_MEMORY_QUERY_DEMAND_SESSION_KEY_RE = re.compile(
    r"\b(?:session_id|session)\s*:"
)


def session_memory_query_demand_aliases(
    records: list[dict[str, Any]],
) -> tuple[dict[str, str], set[str]]:
    candidates: dict[str, set[str]] = defaultdict(set)
    session_ids: set[str] = set()
    for record in records:
        session_id = str(record.get("session_id") or "").strip()
        if not session_id:
            continue
        session_ids.add(session_id)
        display = record.get("display") if isinstance(record.get("display"), dict) else {}
        aliases = {
            session_id,
            str(record.get("session_label") or "").strip(),
            str(record.get("session_title") or "").strip(),
            str(record.get("path") or "").strip(),
            Path(str(record.get("path") or "")).name,
            str(display.get("label") or "").strip(),
            str(display.get("title") or "").strip(),
        }
        for alias in aliases:
            if alias and alias not in {"all", "latest"}:
                candidates[alias].add(session_id)
    return (
        {
            alias: next(iter(ids))
            for alias, ids in candidates.items()
            if len(ids) == 1
        },
        session_ids,
    )


def session_memory_query_demand_shell_segments(command: str) -> list[list[str]]:
    try:
        lexer = shlex.shlex(
            str(command or ""),
            posix=True,
            punctuation_chars=";&|()\n",
        )
        # Newlines are shell command boundaries, not ordinary spaces.  Keeping
        # them out of ``whitespace`` also exposes commands nested in ``$(...)``
        # as independent executable segments while shlex still protects quoted
        # documentation and search strings.
        lexer.whitespace = " \t\r"
        lexer.whitespace_split = True
        lexer.commenters = ""
        tokens = list(lexer)
    except ValueError:
        return []
    segments: list[list[str]] = []
    current: list[str] = []
    for token in tokens:
        if token and set(token) <= {";", "&", "|", "(", ")", "\n"}:
            if current:
                segments.append(current)
                current = []
            continue
        current.append(token)
    if current:
        segments.append(current)
    return segments


def session_memory_query_demand_cli_invocation(
    argv: list[str],
) -> tuple[str, list[str]] | None:
    if not argv:
        return None
    index = 0
    if argv[index] == "do":
        index += 1
    while index < len(argv) and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*=.*", argv[index]):
        index += 1
    if index < len(argv) and Path(argv[index]).name == "env":
        index += 1
        while index < len(argv):
            token = argv[index]
            if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*=.*", token):
                index += 1
                continue
            if token in {"-u", "--unset"} and index + 1 < len(argv):
                index += 2
                continue
            if token.startswith("-"):
                index += 1
                continue
            break
    if index < len(argv) and Path(argv[index]).name == "sudo":
        index += 1
        while index < len(argv) and argv[index].startswith("-"):
            index += 1
    if index < len(argv) and Path(argv[index]).name == "timeout":
        index += 1
        while index < len(argv) and argv[index].startswith("-"):
            index += 1
        if index < len(argv):
            index += 1
    if index >= len(argv):
        return None
    executable = Path(argv[index]).name
    if re.fullmatch(r"python(?:3(?:\.\d+)*)?", executable):
        index += 1
        while index < len(argv) and argv[index] in {"-B", "-E", "-I", "-s", "-S", "-u"}:
            index += 1
        if index >= len(argv) or Path(argv[index]).name != "aoa_session_memory.py":
            return None
        index += 1
    elif executable == "aoa_session_memory.py":
        index += 1
    else:
        return None
    if index >= len(argv):
        return None
    route = str(argv[index] or "").strip().lower()
    if route not in SESSION_MEMORY_QUERY_DEMAND_CLI_COMMANDS:
        return None
    return route, argv[index + 1 :]


def session_memory_query_demand_cli_targets(
    command: str,
    *,
    alias_to_session_id: dict[str, str],
) -> list[dict[str, str]]:
    targets: list[dict[str, str]] = []
    for segment in session_memory_query_demand_shell_segments(command):
        invocation = session_memory_query_demand_cli_invocation(segment)
        if invocation is None:
            continue
        route, arguments = invocation
        target_value = ""
        for index, token in enumerate(arguments):
            if token in SESSION_MEMORY_QUERY_DEMAND_SESSION_FLAGS and index + 1 < len(arguments):
                target_value = str(arguments[index + 1] or "").strip()
                break
            for flag in SESSION_MEMORY_QUERY_DEMAND_SESSION_FLAGS:
                prefix = f"{flag}="
                if token.startswith(prefix):
                    target_value = token[len(prefix) :].strip()
                    break
            if target_value:
                break
        if not target_value and route in SESSION_MEMORY_QUERY_DEMAND_POSITIONAL_SESSION_COMMANDS:
            target_value = next(
                (
                    str(token).strip()
                    for token in arguments
                    if str(token).strip() and not str(token).startswith("-")
                ),
                "",
            )
        session_id = alias_to_session_id.get(target_value, "")
        if session_id:
            targets.append(
                {
                    "session_id": session_id,
                    "route": route,
                    "access_plane": "cli",
                }
            )
    return targets


def javascript_code_mask(source: str) -> str:
    text = str(source or "")
    masked = list(text)
    index = 0
    state = "code"
    quote = ""
    while index < len(text):
        char = text[index]
        following = text[index + 1] if index + 1 < len(text) else ""
        if state == "code":
            if char in {"'", '"', "`"}:
                quote = char
                state = "string"
                masked[index] = " "
            elif char == "/" and following == "/":
                state = "line_comment"
                masked[index] = masked[index + 1] = " "
                index += 1
            elif char == "/" and following == "*":
                state = "block_comment"
                masked[index] = masked[index + 1] = " "
                index += 1
        elif state == "string":
            if char == "\\":
                masked[index] = " "
                if index + 1 < len(text):
                    masked[index + 1] = " "
                    index += 1
            elif char == quote:
                masked[index] = " "
                state = "code"
                quote = ""
            elif char not in {"\n", "\r"}:
                masked[index] = " "
        elif state == "line_comment":
            if char in {"\n", "\r"}:
                state = "code"
            else:
                masked[index] = " "
        elif state == "block_comment":
            masked[index] = " " if char not in {"\n", "\r"} else char
            if char == "*" and following == "/":
                masked[index + 1] = " "
                index += 1
                state = "code"
        index += 1
    return "".join(masked)


def javascript_matching_call_end(masked_source: str, open_paren_index: int) -> int:
    depth = 0
    for index in range(open_paren_index, len(masked_source)):
        char = masked_source[index]
        if char == "(":
            depth += 1
        elif char == ")":
            depth -= 1
            if depth == 0:
                return index + 1
    return min(len(masked_source), open_paren_index + 16384)


def custom_exec_nested_tool_call_spans(
    payload: dict[str, Any],
) -> tuple[str, list[dict[str, Any]]]:
    if (
        str(payload.get("type") or "") != "custom_tool_call"
        or normalized_tool_name(tool_name_from_payload(payload)) != "exec"
    ):
        return "", []
    source = payload.get("input")
    if not isinstance(source, str) or not source.strip():
        return "", []
    bounded_source = source[:262144]
    masked = javascript_code_mask(bounded_source)
    calls: list[dict[str, Any]] = []
    for match in CUSTOM_EXEC_NESTED_TOOL_CALL_RE.finditer(masked):
        name = str(match.group("name") or "")
        open_paren = masked.find("(", match.start(), match.end())
        if not name or open_paren < 0:
            continue
        namespace = tool_namespace_for_name(name)
        calls.append(
            {
                "name": name,
                "namespace": namespace,
                "mcp_service_key": (
                    mcp_service_key_for_tool_name(name)
                    if namespace == "mcp"
                    else ""
                ),
                "open_paren": open_paren,
                "call_end": javascript_matching_call_end(masked, open_paren),
            }
        )
        if len(calls) >= 32:
            break
    return bounded_source, calls


def custom_exec_nested_tool_invocations(payload: dict[str, Any]) -> list[dict[str, str]]:
    _source, calls = custom_exec_nested_tool_call_spans(payload)
    return [
        {
            "name": str(item.get("name") or ""),
            "namespace": str(item.get("namespace") or ""),
            "mcp_service_key": str(item.get("mcp_service_key") or ""),
        }
        for item in calls
    ]


def custom_exec_operational_entity_text(payload: dict[str, Any]) -> str:
    """Keep invoked tool identity while removing MCP query arguments from usage signals."""
    source, calls = custom_exec_nested_tool_call_spans(payload)
    if not source or not any(str(item.get("namespace") or "") == "mcp" for item in calls):
        return derived_text_privacy_text(source)
    masked_source = list(source)
    for item in calls:
        if str(item.get("namespace") or "") != "mcp":
            continue
        start = max(0, int_value(item.get("open_paren")) + 1)
        end = max(start, min(len(masked_source), int_value(item.get("call_end")) - 1))
        for index in range(start, end):
            if masked_source[index] not in {"\n", "\r"}:
                masked_source[index] = " "
    return derived_text_privacy_text("".join(masked_source))


def session_memory_query_demand_mcp_targets_from_source(
    source: str,
    *,
    alias_to_session_id: dict[str, str],
) -> list[dict[str, str]]:
    bounded_source = str(source or "")[:262144]
    masked = javascript_code_mask(bounded_source)
    targets: list[dict[str, str]] = []
    for call_match in SESSION_MEMORY_QUERY_DEMAND_MCP_CALL_RE.finditer(masked):
        open_paren = masked.find("(", call_match.start(), call_match.end())
        if open_paren < 0:
            continue
        call_end = javascript_matching_call_end(masked, open_paren)
        call_mask = masked[open_paren + 1 : call_end]
        for key_match in SESSION_MEMORY_QUERY_DEMAND_SESSION_KEY_RE.finditer(call_mask):
            value_offset = open_paren + 1 + key_match.end()
            literal = re.match(
                r"\s*(['\"])(?P<value>[^'\"]{1,512})\1",
                bounded_source[value_offset:],
            )
            if literal is None:
                continue
            target_value = str(literal.group("value") or "").strip()
            session_id = alias_to_session_id.get(target_value, "")
            if session_id:
                targets.append(
                    {
                        "session_id": session_id,
                        "route": str(call_match.group("name") or ""),
                        "access_plane": "mcp",
                    }
                )
                break
        if len(targets) >= 16:
            break
    return targets


def session_memory_query_demand_json_targets(
    value: Any,
    *,
    alias_to_session_id: dict[str, str],
) -> list[str]:
    targets: list[str] = []
    if isinstance(value, dict):
        for key, item in value.items():
            if str(key) in {"session", "session_id"} and isinstance(item, str):
                session_id = alias_to_session_id.get(item.strip(), "")
                if session_id:
                    targets.append(session_id)
            else:
                targets.extend(
                    session_memory_query_demand_json_targets(
                        item,
                        alias_to_session_id=alias_to_session_id,
                    )
                )
    elif isinstance(value, list):
        for item in value[:64]:
            targets.extend(
                session_memory_query_demand_json_targets(
                    item,
                    alias_to_session_id=alias_to_session_id,
                )
            )
    return list(dict.fromkeys(targets))


def session_memory_query_demand_targets_from_payload(
    payload: dict[str, Any],
    *,
    alias_to_session_id: dict[str, str],
) -> list[dict[str, str]]:
    payload_type = str(payload.get("type") or "")
    tool_name = str(tool_name_from_payload(payload) or "")
    tool_namespace = str(payload.get("namespace") or "")
    normalized_name = normalized_tool_name(tool_name)
    if payload_type == "custom_tool_call" and normalized_name == "exec":
        shell_commands = custom_exec_shell_commands(payload)
        if shell_commands:
            targets: list[dict[str, str]] = []
            for command in shell_commands:
                targets.extend(
                    session_memory_query_demand_cli_targets(
                        command,
                        alias_to_session_id=alias_to_session_id,
                    )
                )
            return targets
        return session_memory_query_demand_mcp_targets_from_source(
            str(payload.get("input") or ""),
            alias_to_session_id=alias_to_session_id,
        )
    if payload_type in {"function_call", "tool_call"} and normalized_name == "exec_command":
        return session_memory_query_demand_cli_targets(
            command_text_from_payload(payload),
            alias_to_session_id=alias_to_session_id,
        )
    is_session_memory_mcp_call = tool_name.startswith(
        "mcp__aoa_session_memory__"
    ) or (
        tool_namespace == "mcp__aoa_session_memory"
        and tool_name.startswith("aoa_session_")
    )
    if (
        payload_type in {"function_call", "tool_call"}
        and is_session_memory_mcp_call
    ):
        arguments = command_payload_args(payload)
        return [
            {
                "session_id": session_id,
                "route": tool_name,
                "access_plane": "mcp",
            }
            for session_id in session_memory_query_demand_json_targets(
                arguments,
                alias_to_session_id=alias_to_session_id,
            )
        ]
    return []


def session_memory_query_demand_tail_rows(
    path: Path,
    *,
    max_tail_bytes: int,
    max_events: int,
    total_line_count_hint: int | None = None,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    stat = path.stat()
    bounded_bytes = max(4096, int_value(max_tail_bytes, SESSION_MEMORY_QUERY_DEMAND_MAX_TAIL_BYTES))
    start_offset = max(0, stat.st_size - bounded_bytes)
    rows: deque[tuple[int, str]] = deque(maxlen=max(1, int_value(max_events, SESSION_MEMORY_QUERY_DEMAND_MAX_EVENTS)))
    complete_line_count = 0
    bytes_read = 0
    with path.open("rb") as handle:
        handle.seek(start_offset)
        if start_offset:
            skipped = handle.readline()
            start_offset = handle.tell()
            bytes_read += len(skipped)
        while handle.tell() < stat.st_size:
            byte_offset = handle.tell()
            raw = handle.readline()
            if not raw:
                break
            bytes_read += len(raw)
            if not raw.endswith(b"\n"):
                break
            complete_line_count += 1
            rows.append((byte_offset, raw[:-1].decode("utf-8", errors="replace")))
    if start_offset == 0:
        first_line = max(1, complete_line_count - len(rows) + 1)
    elif total_line_count_hint is not None and total_line_count_hint >= len(rows):
        first_line = total_line_count_hint - len(rows) + 1
    else:
        first_line = 0
    parsed_rows: list[dict[str, Any]] = []
    for offset, (byte_offset, raw_line) in enumerate(rows):
        try:
            loaded = json.loads(raw_line)
        except json.JSONDecodeError:
            continue
        if not isinstance(loaded, dict):
            continue
        parsed_rows.append(
            {
                "row": loaded,
                "line_no": first_line + offset if first_line else 0,
                "byte_offset": byte_offset,
            }
        )
    return parsed_rows, {
        "path": str(path),
        "source_size": stat.st_size,
        "source_mtime": stat.st_mtime,
        "scan_start_offset": start_offset,
        "bytes_read": bytes_read,
        "complete_line_count": complete_line_count,
        "parsed_event_count": len(parsed_rows),
        "byte_truncated": start_offset > 0,
        "event_truncated": complete_line_count > len(rows),
        "absolute_line_numbers_available": bool(first_line),
    }


def session_memory_query_demand_projection(
    records: list[dict[str, Any]],
    *,
    now_epoch: float | None = None,
    ttl_seconds: float = SESSION_MEMORY_QUERY_DEMAND_TTL_SECONDS,
    max_source_files: int = SESSION_MEMORY_QUERY_DEMAND_MAX_SOURCE_FILES,
    max_tail_bytes: int = SESSION_MEMORY_QUERY_DEMAND_MAX_TAIL_BYTES,
    max_events: int = SESSION_MEMORY_QUERY_DEMAND_MAX_EVENTS,
    evidence_limit: int = SESSION_MEMORY_QUERY_DEMAND_EVIDENCE_LIMIT,
    max_targets: int = SESSION_MEMORY_QUERY_DEMAND_MAX_TARGETS,
) -> dict[str, Any]:
    started = time.monotonic()
    effective_now = time.time() if now_epoch is None else float(now_epoch)
    effective_ttl = max(60.0, float(ttl_seconds))
    alias_to_session_id, eligible_session_ids = session_memory_query_demand_aliases(records)
    sources: list[tuple[float, Path, dict[str, Any]]] = []
    seen_paths: set[str] = set()
    for record in records:
        path_value = record.get("transcript_path")
        if not path_value:
            raw = record.get("raw") if isinstance(record.get("raw"), dict) else {}
            path_value = raw.get("source_path") or raw.get("path")
        if not path_value:
            continue
        path = Path(str(path_value)).expanduser()
        path_key = str(path)
        if path_key in seen_paths:
            continue
        try:
            stat = path.stat()
        except OSError:
            continue
        if not path.is_file() or stat.st_mtime < effective_now - effective_ttl:
            continue
        seen_paths.add(path_key)
        sources.append((stat.st_mtime, path, record))
    sources.sort(key=lambda item: (item[0], str(item[1])), reverse=True)
    selected_sources = sources[: max(1, int_value(max_source_files, SESSION_MEMORY_QUERY_DEMAND_MAX_SOURCE_FILES))]
    demand_counts: Counter[str] = Counter()
    latest_epoch: dict[str, float] = {}
    evidence: list[dict[str, Any]] = []
    source_scans: list[dict[str, Any]] = []
    rejected_text_noise_count = 0
    ignored_output_count = 0
    for _mtime, path, record in selected_sources:
        raw = record.get("raw") if isinstance(record.get("raw"), dict) else {}
        source_snapshot = raw.get("source_snapshot") if isinstance(raw.get("source_snapshot"), dict) else {}
        line_count_hint: int | None = None
        try:
            if int_value(source_snapshot.get("size")) == path.stat().st_size:
                candidate_line_count = int_value(raw.get("line_count"))
                line_count_hint = candidate_line_count if candidate_line_count > 0 else None
        except OSError:
            pass
        try:
            tail_rows, scan = session_memory_query_demand_tail_rows(
                path,
                max_tail_bytes=max_tail_bytes,
                max_events=max_events,
                total_line_count_hint=line_count_hint,
            )
        except OSError as exc:
            source_scans.append({"path": str(path), "status": "unreadable", "diagnostics": [str(exc)]})
            continue
        scan["query_session_id"] = str(record.get("session_id") or "")
        source_scans.append(scan)
        for item in tail_rows:
            row = item.get("row") if isinstance(item.get("row"), dict) else {}
            if str(row.get("type") or "") != "response_item":
                continue
            payload = row.get("payload") if isinstance(row.get("payload"), dict) else {}
            payload_type = str(payload.get("type") or "")
            if payload_type in {"custom_tool_call_output", "function_call_output", "tool_call_output"}:
                ignored_output_count += 1
                continue
            timestamp = str(row.get("timestamp") or payload.get("timestamp") or "")
            parsed_timestamp = parse_utc_timestamp(timestamp)
            event_epoch = parsed_timestamp.timestamp() if parsed_timestamp is not None else float(scan.get("source_mtime") or 0.0)
            if event_epoch < effective_now - effective_ttl or event_epoch > effective_now + 300:
                continue
            targets = session_memory_query_demand_targets_from_payload(
                payload,
                alias_to_session_id=alias_to_session_id,
            )
            if not targets and payload_type == "custom_tool_call" and normalized_tool_name(
                tool_name_from_payload(payload)
            ) == "exec":
                source = str(payload.get("input") or "")
                if "aoa_session_memory" in source and any(
                    alias in source
                    for alias in alias_to_session_id
                    if alias and len(alias) >= 16
                ):
                    rejected_text_noise_count += 1
            for target in targets[:16]:
                session_id = str(target.get("session_id") or "")
                if session_id not in eligible_session_ids:
                    continue
                demand_counts[session_id] += 1
                latest_epoch[session_id] = max(latest_epoch.get(session_id, 0.0), event_epoch)
                if len(evidence) < max(1, int_value(evidence_limit, SESSION_MEMORY_QUERY_DEMAND_EVIDENCE_LIMIT)):
                    line_no = int_value(item.get("line_no"))
                    byte_offset = int_value(item.get("byte_offset"))
                    evidence.append(
                        {
                            "target_session_id": session_id,
                            "query_session_id": str(record.get("session_id") or ""),
                            "timestamp": timestamp,
                            "route": str(target.get("route") or ""),
                            "access_plane": str(target.get("access_plane") or ""),
                            "correlation_id": str(payload_correlation_id(payload) or ""),
                            "raw_ref": f"raw:line:{line_no}" if line_no > 0 else "",
                            "source_path": str(path),
                            "source_byte_offset": byte_offset,
                        }
                    )
    all_priority_session_ids = sorted(
        demand_counts,
        key=lambda session_id: (
            -latest_epoch.get(session_id, 0.0),
            -demand_counts[session_id],
            session_id,
        ),
    )
    effective_max_targets = max(
        1,
        int_value(max_targets, SESSION_MEMORY_QUERY_DEMAND_MAX_TARGETS),
    )
    priority_session_ids = all_priority_session_ids[:effective_max_targets]
    priority_session_id_set = set(priority_session_ids)
    evidence = [
        item
        for item in evidence
        if str(item.get("target_session_id") or "") in priority_session_id_set
    ]
    return {
        "schema_version": 1,
        "artifact_type": "session_memory_query_demand_projection",
        "classifier_version": SESSION_MEMORY_QUERY_DEMAND_CLASSIFIER_VERSION,
        "generated_at": datetime.fromtimestamp(effective_now, tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        "ok": True,
        "status": "observed" if priority_session_ids else "empty",
        "mutates": False,
        "ttl_seconds": effective_ttl,
        "priority_session_ids": priority_session_ids,
        "priority_session_count_total": len(all_priority_session_ids),
        "priority_session_ids_truncated": len(all_priority_session_ids) > len(priority_session_ids),
        "demand_counts": {
            session_id: demand_counts[session_id]
            for session_id in priority_session_ids
        },
        "latest_query_at": {
            session_id: datetime.fromtimestamp(latest_epoch[session_id], tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
            for session_id in priority_session_ids
        },
        "evidence": evidence,
        "eligible_session_count": len(eligible_session_ids),
        "candidate_source_file_count": len(sources),
        "source_file_count": len(selected_sources),
        "source_files_truncated": len(sources) > len(selected_sources),
        "source_scans": source_scans,
        "rejected_text_noise_count": rejected_text_noise_count,
        "ignored_output_count": ignored_output_count,
        "cost_profile": {
            "max_source_files": max_source_files,
            "max_tail_bytes_per_source": max_tail_bytes,
            "max_events_per_source": max_events,
            "max_targets": effective_max_targets,
            "bytes_read": sum(int_value(item.get("bytes_read")) for item in source_scans),
            "elapsed_ms": int((time.monotonic() - started) * 1000),
        },
        "truth_status": "structured_session_memory_query_invocations_projected_for_bounded_scheduler_priority",
        "authority_boundary": "generated scheduling demand only; raw transcript and target session refs remain evidence authority",
    }


def custom_exec_read_only_shell_commands(payload: dict[str, Any]) -> list[str]:
    commands = custom_exec_shell_commands(payload)
    if not commands:
        return []
    for command in commands:
        if re.search(r"(?:^|\s)(?:>>?|[0-9]*>|&>)\s*\S", command):
            return []
        parts = [
            part.strip()
            for part in re.split(r"\s*(?:&&|\|\||[;|])\s*", command)
            if part.strip()
        ]
        if not parts:
            return []
        for part in parts:
            command_info = command_classifier(part)
            if str(command_info.get("event_type") or "") != "FILE_READ":
                return []
            if re.search(r"(?:^|\s)sed\s+[^;&|]*?(?:^|\s)-i(?:\s|$)", part, flags=re.IGNORECASE):
                return []
    return [
        derived_text_privacy_text(command)
        for command in commands
    ]


def episode_operational_command_operation(command: str) -> str:
    return "read" if EPISODE_OPERATIONAL_READ_COMMAND_RE.search(str(command or "")) else "other"


def episode_operational_command_targets(command: str) -> list[str]:
    return list(
        dict.fromkeys(
            match.group(0).rstrip(".,;:")
            for match in EPISODE_OPERATIONAL_PATH_RE.finditer(str(command or ""))
        )
    )


def episode_operational_group_candidate_raw_blocks(
    results: list[dict[str, Any]],
    *,
    candidate_limit: int = EPISODE_OPERATIONAL_GROUP_GLOBAL_CANDIDATE_LIMIT,
    block_limit: int = EPISODE_OPERATIONAL_GROUP_GLOBAL_BLOCK_LIMIT,
    max_uncompressed_bytes: int = EPISODE_OPERATIONAL_GROUP_GLOBAL_MAX_UNCOMPRESSED_BYTES,
    selection_depth: str = "anchor",
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Select sealed raw blocks only for the leading semantic episode candidates."""
    started = time.monotonic()
    effective_selection_depth = "expanded" if selection_depth == "expanded" else "anchor"
    effective_candidate_limit = max(1, min(int_value(candidate_limit), 64))
    effective_block_limit = max(1, min(int_value(block_limit), 256))
    effective_max_bytes = max(1, int_value(max_uncompressed_bytes))
    selected: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    unresolved_candidate_count = 0
    skipped_budget_count = 0
    deferred_expansion_block_count = 0
    candidate_anchor_line_count = 0
    selected_anchor_hit_count = 0
    selected_uncompressed_bytes = 0
    selected_stored_bytes = 0
    considered = [item for item in results[:effective_candidate_limit] if isinstance(item, dict)]
    candidate_limit_truncated = len(results) > effective_candidate_limit
    for item in considered:
        manifest_ref = str(
            item.get("session_ref")
            or ((item.get("refs") or {}).get("session") if isinstance(item.get("refs"), dict) else "")
            or ""
        )
        manifest_path = Path(manifest_ref).expanduser() if manifest_ref else Path()
        if not manifest_ref or not manifest_path.is_file():
            unresolved_candidate_count += 1
            continue
        manifest = read_json(manifest_path, {})
        if not isinstance(manifest, dict) or not manifest:
            unresolved_candidate_count += 1
            continue
        session_id = str(item.get("session_id") or manifest.get("session_id") or manifest_path.parent.name)
        event_range = item.get("event_range") if isinstance(item.get("event_range"), dict) else {}
        candidate_from = int_value(event_range.get("from_line"))
        candidate_to = int_value(event_range.get("to_line"))
        if candidate_from <= 0 or candidate_to < candidate_from:
            unresolved_candidate_count += 1
            continue
        candidate_anchor_lines: list[int] = []
        query_coverage = (
            item.get("query_coverage") if isinstance(item.get("query_coverage"), dict) else {}
        )
        coherent_support = (
            query_coverage.get("coherent_support")
            if isinstance(query_coverage.get("coherent_support"), dict)
            else {}
        )
        support_candidates = [
            coherent_support,
            *(
                item.get("supporting_evidence")[:8]
                if isinstance(item.get("supporting_evidence"), list)
                else []
            ),
        ]
        for support in support_candidates:
            if not isinstance(support, dict):
                continue
            refs = support.get("refs") if isinstance(support.get("refs"), dict) else {}
            support_line = int_value(
                support.get("line") or line_from_raw_ref(str(refs.get("raw") or ""))
            )
            if candidate_from <= support_line <= candidate_to:
                candidate_anchor_lines.append(support_line)
        candidate_anchor_lines = list(dict.fromkeys(candidate_anchor_lines))
        candidate_anchor_line_count += len(candidate_anchor_lines)
        matched_segment = False
        candidate_sources: list[dict[str, Any]] = []
        for segment in manifest.get("segments", []) if isinstance(manifest.get("segments"), list) else []:
            if not isinstance(segment, dict):
                continue
            source_range = segment.get("source_range") if isinstance(segment.get("source_range"), dict) else {}
            segment_from = int_value(source_range.get("from_line"))
            segment_to = int_value(source_range.get("to_line"))
            if segment_from <= 0 or segment_to < segment_from:
                continue
            if segment_to < candidate_from or segment_from > candidate_to:
                continue
            raw_block = segment.get("raw_block") if isinstance(segment.get("raw_block"), dict) else {}
            compressed_ref = str(raw_block.get("compressed_path") or raw_block.get("compressed_rel") or "")
            plain_ref = str(
                raw_block.get("path")
                or raw_block.get("plain_path")
                or raw_block.get("rel")
                or raw_block.get("plain_rel")
                or ""
            )

            def resolved_path(ref: str) -> Path:
                path = Path(ref).expanduser()
                return path if path.is_absolute() else manifest_path.parent / path

            compressed_path = resolved_path(compressed_ref) if compressed_ref else Path()
            plain_path = resolved_path(plain_ref) if plain_ref else Path()
            if compressed_ref and compressed_path.is_file():
                block_path = compressed_path
                compression = "gzip"
                expected_sha256 = str(raw_block.get("compressed_sha256") or "")
                stored_bytes = int_value(raw_block.get("compressed_bytes"), block_path.stat().st_size)
            elif plain_ref and plain_path.is_file():
                block_path = plain_path
                compression = "plain"
                expected_sha256 = str(
                    raw_block.get("sha256") or raw_block.get("uncompressed_sha256") or ""
                )
                stored_bytes = int_value(raw_block.get("bytes"), block_path.stat().st_size)
            else:
                continue
            matched_segment = True
            uncompressed_bytes = int_value(
                raw_block.get("uncompressed_bytes"),
                int_value(raw_block.get("bytes"), stored_bytes),
            )
            anchor_hits = [
                line for line in candidate_anchor_lines if segment_from <= line <= segment_to
            ]
            anchor_distance = (
                0
                if anchor_hits
                else min(
                    (
                        min(abs(line - segment_from), abs(line - segment_to))
                        for line in candidate_anchor_lines
                    ),
                    default=max(0, segment_from - candidate_from),
                )
            )
            candidate_sources.append(
                {
                    "path": str(block_path),
                    "compression": compression,
                    "expected_sha256": expected_sha256,
                    "session_id": session_id,
                    "from_line": segment_from,
                    "to_line": segment_to,
                    "line_count": int_value(
                        raw_block.get("line_count"), segment_to - segment_from + 1
                    ),
                    "stored_bytes": stored_bytes,
                    "uncompressed_bytes": uncompressed_bytes,
                    "segment": {
                        "segment_id": str(segment.get("segment_id") or ""),
                        "markdown": str(segment.get("markdown") or ""),
                        "index": str(segment.get("index") or ""),
                    },
                    "raw_block_ref": str(
                        raw_block.get("compressed_rel")
                        or raw_block.get("rel")
                        or raw_block.get("compressed_path")
                        or raw_block.get("path")
                        or ""
                    ),
                    "selection_basis": (
                        "candidate_support_anchor_block"
                        if anchor_hits
                        else "nearest_candidate_event_block"
                    ),
                    "anchor_hit_count": len(anchor_hits),
                    "anchor_distance_lines": anchor_distance,
                }
            )
        candidate_sources.sort(
            key=lambda source: (
                0 if int_value(source.get("anchor_hit_count")) else 1,
                int_value(source.get("anchor_distance_lines")),
                int_value(source.get("from_line")),
            )
        )
        available_sources = [
            source
            for source in candidate_sources
            if (session_id, str(source.get("path") or "")) not in seen
        ]
        if effective_selection_depth == "anchor" and available_sources:
            deferred_expansion_block_count += max(0, len(available_sources) - 1)
            available_sources = available_sources[:1]
        for source in available_sources:
            key = (session_id, str(source.get("path") or ""))
            uncompressed_bytes = int_value(source.get("uncompressed_bytes"))
            if (
                len(selected) >= effective_block_limit
                or selected_uncompressed_bytes + uncompressed_bytes > effective_max_bytes
            ):
                skipped_budget_count += 1
                continue
            seen.add(key)
            selected.append(source)
            if int_value(source.get("anchor_hit_count")):
                selected_anchor_hit_count += 1
            selected_uncompressed_bytes += uncompressed_bytes
            selected_stored_bytes += int_value(source.get("stored_bytes"))
        if not matched_segment:
            unresolved_candidate_count += 1
    status = (
        "candidate_raw_blocks_selected_truncated"
        if selected and (skipped_budget_count or candidate_limit_truncated)
        else "candidate_raw_blocks_selected"
        if selected
        else "candidate_raw_blocks_unavailable"
    )
    return selected, {
        "status": status,
        "candidate_limit": effective_candidate_limit,
        "input_candidate_count": len(results),
        "considered_candidate_count": len(considered),
        "candidate_limit_truncated": candidate_limit_truncated,
        "selection_depth": effective_selection_depth,
        "selected_block_count": len(selected),
        "selected_session_count": len({str(item.get('session_id') or '') for item in selected}),
        "selected_uncompressed_bytes": selected_uncompressed_bytes,
        "selected_stored_bytes": selected_stored_bytes,
        "max_uncompressed_bytes": effective_max_bytes,
        "block_limit": effective_block_limit,
        "unresolved_candidate_count": unresolved_candidate_count,
        "skipped_budget_count": skipped_budget_count,
        "deferred_expansion_block_count": deferred_expansion_block_count,
        "expansion_available": bool(deferred_expansion_block_count),
        "candidate_anchor_line_count": candidate_anchor_line_count,
        "selected_anchor_hit_count": selected_anchor_hit_count,
        "mutates": False,
        "authority": "hash-verified archived raw blocks",
        "elapsed_ms": int((time.monotonic() - started) * 1000),
    }


def episode_operational_group_scoped_raw_hydration(
    *,
    raw_path: Path | None,
    raw_sources: list[dict[str, Any]] | None = None,
    segments: list[dict[str, Any]],
    results: list[dict[str, Any]],
    group_query: dict[str, Any],
    max_raw_bytes: int = EPISODE_OPERATIONAL_GROUP_SCOPED_RAW_MAX_BYTES,
    max_lines: int = EPISODE_OPERATIONAL_GROUP_SCOPED_RAW_MAX_LINES,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Build bounded typed parallel-call groups from scoped raw evidence."""
    started = time.monotonic()
    candidate_block_mode = raw_sources is not None
    read_scope = "candidate_raw_blocks" if candidate_block_mode else "archived_raw_snapshot"
    base_report = {
        "status": "not_requested",
        "applied": False,
        "mutates": False,
        "candidate_count": len(results),
        "qualified_candidate_count": 0,
        "evidence_source": (
            "hash_verified_candidate_raw_blocks"
            if candidate_block_mode
            else "scoped_raw_parallel_tool_call_group"
        ),
        "read_scope": read_scope,
    }
    if not group_query.get("active"):
        return results, {**base_report, "status": "not_an_operational_group_query"}
    source_integrity: dict[str, Any] = {
        "status": "not_checked_by_hydrator",
        "required": candidate_block_mode,
        "requested_count": len(raw_sources or []),
        "verified_count": 0,
        "usable_count": 0,
        "failed_count": 0,
        "unverified_count": 0,
        "missing_count": 0,
        "read_failure_count": 0,
        "coordinate_mismatch_count": 0,
        "rejected_samples": [],
    }
    prepared_sources: list[dict[str, Any]] = []
    raw_bytes = 0
    stored_raw_bytes = 0
    if candidate_block_mode:
        seen_sources: set[tuple[str, str]] = set()
        for raw_source in raw_sources or []:
            if not isinstance(raw_source, dict):
                source_integrity["unverified_count"] += 1
                continue
            source_path_ref = str(raw_source.get("path") or "")
            source_path = Path(source_path_ref).expanduser() if source_path_ref else Path()
            session_id = str(raw_source.get("session_id") or "")
            source_key = (session_id, str(source_path))
            if source_key in seen_sources:
                continue
            seen_sources.add(source_key)
            declared_uncompressed_bytes = int_value(
                raw_source.get("uncompressed_bytes"),
                int_value(raw_source.get("stored_bytes")),
            )
            declared_stored_bytes = int_value(raw_source.get("stored_bytes"))
            raw_bytes += max(0, declared_uncompressed_bytes)
            stored_raw_bytes += max(0, declared_stored_bytes)
            if not source_path_ref or not source_path.is_file():
                source_integrity["missing_count"] += 1
                source_integrity["rejected_samples"].append(
                    {"session_id": session_id, "path": source_path_ref, "reason": "missing"}
                )
                continue
            expected_sha256 = str(raw_source.get("expected_sha256") or "").strip().lower()
            if not expected_sha256:
                source_integrity["unverified_count"] += 1
                source_integrity["rejected_samples"].append(
                    {
                        "session_id": session_id,
                        "path": str(source_path),
                        "reason": "expected_sha256_missing",
                    }
                )
                continue
            try:
                actual_sha256 = sha256_file(source_path).lower()
            except OSError as exc:
                source_integrity["failed_count"] += 1
                source_integrity["rejected_samples"].append(
                    {
                        "session_id": session_id,
                        "path": str(source_path),
                        "reason": "sha256_read_failed",
                        "diagnostic": str(exc),
                    }
                )
                continue
            if actual_sha256 != expected_sha256:
                source_integrity["failed_count"] += 1
                source_integrity["rejected_samples"].append(
                    {
                        "session_id": session_id,
                        "path": str(source_path),
                        "reason": "sha256_mismatch",
                        "expected_sha256": expected_sha256,
                        "actual_sha256": actual_sha256,
                    }
                )
                continue
            source_integrity["verified_count"] += 1
            prepared_sources.append({**raw_source, "_path": source_path})
        source_integrity["rejected_samples"] = source_integrity["rejected_samples"][:8]
        if not prepared_sources:
            source_integrity["status"] = "failed"
            return [dict(item) for item in results], {
                **base_report,
                "status": "candidate_raw_block_integrity_failed",
                "raw_bytes": raw_bytes,
                "stored_raw_bytes": stored_raw_bytes,
                "max_raw_bytes": max_raw_bytes,
                "source_count": 0,
                "source_integrity": source_integrity,
                "elapsed_ms": int((time.monotonic() - started) * 1000),
            }
        prepared_sources.sort(
            key=lambda item: (
                str(item.get("session_id") or ""),
                int_value(item.get("from_line")),
                str(item.get("path") or ""),
            )
        )
    else:
        if not raw_path or not raw_path.is_file():
            return results, {**base_report, "status": "raw_path_missing"}
        raw_bytes = raw_path.stat().st_size
        stored_raw_bytes = raw_bytes
        candidate_session_ids = {
            str(item.get("session_id") or "")
            for item in results
            if isinstance(item, dict) and str(item.get("session_id") or "")
        }
        scoped_session_id = next(iter(candidate_session_ids)) if len(candidate_session_ids) == 1 else ""
        prepared_sources = [
            {
                "_path": raw_path,
                "path": str(raw_path),
                "compression": "plain",
                "session_id": scoped_session_id,
                "from_line": 1,
                "to_line": 0,
                "line_count": 0,
            }
        ]
    if max_raw_bytes <= 0 or raw_bytes > max_raw_bytes:
        return results, {
            **base_report,
            "status": "raw_over_bounded_group_limit",
            "raw_bytes": raw_bytes,
            "stored_raw_bytes": stored_raw_bytes,
            "max_raw_bytes": max_raw_bytes,
            "source_integrity": source_integrity,
        }
    clones = [dict(item) for item in results]
    candidate_ranges: list[tuple[str, int, int, dict[str, Any]]] = []
    for item in clones:
        event_range = item.get("event_range") if isinstance(item.get("event_range"), dict) else {}
        from_line = int_value(event_range.get("from_line"))
        to_line = int_value(event_range.get("to_line"))
        if from_line > 0 and to_line >= from_line:
            candidate_ranges.append((str(item.get("session_id") or ""), from_line, to_line, item))
    if not candidate_ranges:
        return clones, {
            **base_report,
            "status": "candidate_ranges_missing",
            "raw_bytes": raw_bytes,
            "stored_raw_bytes": stored_raw_bytes,
            "source_integrity": source_integrity,
        }
    candidate_ranges.sort(key=lambda value: (value[0], value[1], value[2]))
    observed_groups: list[dict[str, Any]] = []
    results_by_call_id: dict[tuple[str, str], dict[str, Any]] = {}
    lines_scanned = 0
    decoded_bytes_scanned = 0
    parsed_event_count = 0
    line_budget_exhausted = False
    byte_budget_exhausted = False
    usable_source_count = 0
    for source in prepared_sources:
        source_path = source.get("_path")
        if not isinstance(source_path, Path):
            continue
        session_id = str(source.get("session_id") or "")
        source_from_line = max(1, int_value(source.get("from_line"), 1))
        source_to_line = int_value(source.get("to_line"))
        expected_line_count = int_value(
            source.get("line_count"),
            source_to_line - source_from_line + 1 if source_to_line >= source_from_line else 0,
        )
        source_segment = source.get("segment") if isinstance(source.get("segment"), dict) else {}
        source_raw_block_ref = str(source.get("raw_block_ref") or source.get("path") or "")
        source_groups: list[dict[str, Any]] = []
        source_results: dict[tuple[str, str], dict[str, Any]] = {}
        current_members: list[dict[str, Any]] = []
        source_line_count = 0
        source_complete = True

        def source_segment_for_line(line_no: int) -> dict[str, Any]:
            return source_segment or segment_for_line(segments, line_no)

        def flush_source_group() -> None:
            nonlocal current_members
            if len(current_members) >= 2:
                source_groups.append(
                    {
                        "kind": "parallel_tool_call_group",
                        "session_id": session_id,
                        "from_line": int_value(current_members[0].get("line")),
                        "to_line": int_value(current_members[-1].get("line")),
                        "members": current_members,
                        "raw_block_ref": source_raw_block_ref,
                        "parallelism_basis": (
                            "multiple_calls_emitted_before_first_correlated_result"
                        ),
                    }
                )
            current_members = []

        try:
            opener = gzip.open if str(source.get("compression") or "") == "gzip" else open
            with opener(source_path, "rt", encoding="utf-8", errors="replace") as handle:
                for local_line_no, line in enumerate(handle, start=1):
                    if lines_scanned >= max_lines:
                        line_budget_exhausted = True
                        source_complete = False
                        break
                    line_bytes = len(line.encode("utf-8", errors="replace"))
                    if decoded_bytes_scanned + line_bytes > max_raw_bytes:
                        byte_budget_exhausted = True
                        source_complete = False
                        break
                    line_no = source_from_line + local_line_no - 1
                    if source_to_line >= source_from_line and line_no > source_to_line:
                        source_integrity["coordinate_mismatch_count"] += 1
                        source_complete = False
                        break
                    lines_scanned += 1
                    source_line_count += 1
                    decoded_bytes_scanned += line_bytes
                    try:
                        parsed = json.loads(line)
                    except json.JSONDecodeError:
                        continue
                    if not isinstance(parsed, dict):
                        continue
                    parsed_event_count += 1
                    if str(parsed.get("type") or "") != "response_item":
                        continue
                    payload = parsed.get("payload") if isinstance(parsed.get("payload"), dict) else {}
                    payload_type = str(payload.get("type") or "")
                    if payload_type in EPISODE_TEMPORAL_RAW_CALL_TYPES:
                        if current_members and (
                            line_no - int_value(current_members[-1].get("line"))
                            > EPISODE_OPERATIONAL_GROUP_MAX_CALL_LINE_GAP
                            or len(current_members) >= EPISODE_OPERATIONAL_GROUP_MAX_MEMBERS
                        ):
                            flush_source_group()
                        arguments = command_payload_args(payload)
                        raw_command = str(
                            arguments.get("cmd")
                            or arguments.get("command")
                            or ""
                        )
                        command = derived_text_privacy_text(
                            raw_command,
                            max_chars=700,
                        )
                        correlation_id = str(payload_correlation_id(payload) or "")
                        segment = source_segment_for_line(line_no)
                        current_members.append(
                            {
                                "session_id": session_id,
                                "line": line_no,
                                "timestamp": str(parsed.get("timestamp") or ""),
                                "correlation_id": correlation_id,
                                "tool_name": normalized_tool_name(tool_name_from_payload(payload)),
                                "operation": episode_operational_command_operation(
                                    raw_command
                                ),
                                "command": command,
                                "targets": episode_operational_command_targets(command)[:12],
                                "refs": {
                                    "raw": f"raw:line:{line_no}",
                                    "segment": str(segment.get("markdown") or ""),
                                    "segment_index": str(segment.get("index") or ""),
                                    "raw_block": source_raw_block_ref,
                                },
                            }
                        )
                        continue
                    if payload_type in EPISODE_TEMPORAL_RAW_RESULT_TYPES:
                        flush_source_group()
                        correlation_id = str(payload_correlation_id(payload) or "")
                        output = str(payload.get("output") or "")
                        exit_match = re.search(r"Process exited with code\s+(-?\d+)", output)
                        exit_code = int(exit_match.group(1)) if exit_match else None
                        segment = source_segment_for_line(line_no)
                        if correlation_id:
                            source_results[(session_id, correlation_id)] = {
                                "line": line_no,
                                "exit_code": exit_code,
                                "status": (
                                    "succeeded"
                                    if exit_code == 0
                                    else "failed"
                                    if exit_code is not None
                                    else "observed"
                                ),
                                "refs": {
                                    "raw": f"raw:line:{line_no}",
                                    "segment": str(segment.get("markdown") or ""),
                                    "segment_index": str(segment.get("index") or ""),
                                    "raw_block": source_raw_block_ref,
                                },
                            }
                        continue
                    if payload_type in {"message", "reasoning"}:
                        flush_source_group()
        except (OSError, EOFError) as exc:
            source_integrity["read_failure_count"] += 1
            source_integrity["rejected_samples"].append(
                {
                    "session_id": session_id,
                    "path": str(source_path),
                    "reason": "raw_source_read_failed",
                    "diagnostic": str(exc),
                }
            )
            source_complete = False
        flush_source_group()
        if (
            source_complete
            and expected_line_count > 0
            and source_line_count != expected_line_count
        ):
            source_integrity["coordinate_mismatch_count"] += 1
            source_integrity["rejected_samples"].append(
                {
                    "session_id": session_id,
                    "path": str(source_path),
                    "reason": "line_coordinate_mismatch",
                    "expected_line_count": expected_line_count,
                    "observed_line_count": source_line_count,
                }
            )
            source_complete = False
        if source_complete:
            observed_groups.extend(source_groups)
            results_by_call_id.update(source_results)
            usable_source_count += 1
        if line_budget_exhausted or byte_budget_exhausted:
            break
    source_integrity["usable_count"] = usable_source_count
    source_integrity["rejected_samples"] = source_integrity["rejected_samples"][:8]
    if candidate_block_mode:
        source_integrity["status"] = (
            "verified"
            if usable_source_count == len(prepared_sources)
            and not any(
                int_value(source_integrity.get(key))
                for key in (
                    "failed_count",
                    "unverified_count",
                    "missing_count",
                    "read_failure_count",
                    "coordinate_mismatch_count",
                )
            )
            else "partial"
            if usable_source_count
            else "failed"
        )
    if not usable_source_count:
        return clones, {
            **base_report,
            "status": (
                "raw_evidence_budget_exhausted"
                if line_budget_exhausted or byte_budget_exhausted
                else "candidate_raw_block_integrity_failed"
                if candidate_block_mode
                else "raw_source_unreadable"
            ),
            "raw_path": str(raw_path) if raw_path else "",
            "raw_bytes": raw_bytes,
            "stored_raw_bytes": stored_raw_bytes,
            "max_raw_bytes": max_raw_bytes,
            "max_lines": max_lines,
            "lines_scanned": lines_scanned,
            "decoded_bytes_scanned": decoded_bytes_scanned,
            "line_budget_exhausted": line_budget_exhausted,
            "byte_budget_exhausted": byte_budget_exhausted,
            "source_count": 0,
            "source_integrity": source_integrity,
            "elapsed_ms": int((time.monotonic() - started) * 1000),
        }

    requested_cardinality = int_value(group_query.get("requested_cardinality"))
    requested_operation = str(group_query.get("operation") or "")
    subject_terms = [
        term for term in group_query.get("subject_terms", []) if isinstance(term, dict)
    ]
    groups_by_doc: dict[tuple[str, str], list[dict[str, Any]]] = defaultdict(list)
    for group in observed_groups:
        group_session_id = str(group.get("session_id") or "")
        members = [dict(member) for member in group.get("members", []) if isinstance(member, dict)]
        for member in members:
            result = results_by_call_id.get(
                (group_session_id, str(member.get("correlation_id") or "")),
                {},
            )
            refs = dict(member.get("refs") or {})
            refs["result_raw"] = str((result.get("refs") or {}).get("raw") or "")
            refs["result_segment"] = str((result.get("refs") or {}).get("segment") or "")
            member["refs"] = refs
            member["result_status"] = str(result.get("status") or "missing")
            member["exit_code"] = result.get("exit_code")
        cardinality = len(members)
        read_member_count = sum(1 for member in members if member.get("operation") == "read")
        targets = list(
            dict.fromkeys(
                str(target)
                for member in members
                for target in member.get("targets", [])
                if target
            )
        )
        successful_result_count = sum(
            1 for member in members if member.get("result_status") == "succeeded"
        )
        group_text = search_doc_text(
            [
                *[member.get("command") for member in members],
                *targets,
            ],
            max_chars=6000,
        )
        group_tokens = episode_semantic_field_tokens(group_text)
        matched_subject_terms = sorted(
            {
                str(term.get("token") or "")
                for term in subject_terms
                if episode_semantic_term_matches_tokens(term, group_tokens)
            }
        )
        subject_coverage = (
            len(matched_subject_terms) / len(subject_terms) if subject_terms else 0.0
        )
        accepted = bool(
            cardinality == requested_cardinality
            and (requested_operation != "read" or read_member_count == cardinality)
            and len(targets) >= requested_cardinality
            and successful_result_count == cardinality
            and subject_coverage >= EPISODE_OPERATIONAL_GROUP_MIN_SUBJECT_COVERAGE
            and len(matched_subject_terms) >= min(2, len(subject_terms))
        )
        evidence = {
            **{key: value for key, value in group.items() if key != "members"},
            "active": True,
            "accepted": accepted,
            "status": "parallel_operational_group_found" if accepted else "parallel_group_below_contract",
            "admission_basis": (
                "parallel_cardinality_distinct_successful_reads" if accepted else ""
            ),
            "cardinality": cardinality,
            "requested_cardinality": requested_cardinality,
            "read_member_count": read_member_count,
            "successful_result_count": successful_result_count,
            "distinct_target_count": len(targets),
            "targets": targets[:EPISODE_OPERATIONAL_GROUP_MAX_MEMBERS],
            "matched_subject_terms": matched_subject_terms,
            "subject_coverage": round(subject_coverage, 4),
            "members": members,
            "authority": (
                "hash_verified_archived_raw_block"
                if candidate_block_mode
                else "raw_session_transcript"
            ),
        }
        candidate: dict[str, Any] | None = None
        from_line = int_value(group.get("from_line"))
        to_line = int_value(group.get("to_line"))
        for candidate_session_id, candidate_from, candidate_to, candidate_item in candidate_ranges:
            if group_session_id and candidate_session_id != group_session_id:
                continue
            if candidate_from <= from_line and to_line <= candidate_to:
                candidate = candidate_item
                break
        if candidate is not None:
            groups_by_doc[
                (str(candidate.get("session_id") or ""), str(candidate.get("doc_id") or ""))
            ].append(evidence)

    qualified_candidate_count = 0
    qualified_group_count = 0
    for item in clones:
        groups = groups_by_doc.get(
            (str(item.get("session_id") or ""), str(item.get("doc_id") or "")),
            [],
        )
        accepted_groups = [group for group in groups if group.get("accepted") is True]
        if not accepted_groups:
            continue
        accepted_groups.sort(
            key=lambda group: (
                -float(group.get("subject_coverage") or 0.0),
                -int_value(group.get("successful_result_count")),
                int_value(group.get("from_line")),
            )
        )
        evidence = dict(accepted_groups[0])
        evidence["qualified_group_count"] = len(accepted_groups)
        evidence["ambiguous_within_episode"] = len(accepted_groups) > 1
        item["operational_group"] = evidence
        qualified_candidate_count += 1
        qualified_group_count += len(accepted_groups)
    return clones, {
        **base_report,
        "status": (
            "applied_truncated"
            if line_budget_exhausted
            or byte_budget_exhausted
            or source_integrity.get("status") == "partial"
            else "applied"
        ),
        "applied": True,
        "raw_path": str(raw_path) if raw_path else "",
        "raw_bytes": raw_bytes,
        "stored_raw_bytes": stored_raw_bytes,
        "max_raw_bytes": max_raw_bytes,
        "max_lines": max_lines,
        "lines_scanned": lines_scanned,
        "decoded_bytes_scanned": decoded_bytes_scanned,
        "parsed_event_count": parsed_event_count,
        "line_budget_exhausted": line_budget_exhausted,
        "byte_budget_exhausted": byte_budget_exhausted,
        "source_count": usable_source_count,
        "source_integrity": source_integrity,
        "observed_parallel_group_count": len(observed_groups),
        "qualified_candidate_count": qualified_candidate_count,
        "qualified_group_count": qualified_group_count,
        "elapsed_ms": int((time.monotonic() - started) * 1000),
        "authority_boundary": "typed group is query-time navigation over raw call/result refs",
    }


def episode_operational_group_relation_gate(
    results: list[dict[str, Any]],
    group_query: dict[str, Any],
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    if not group_query.get("active"):
        return results, {
            "status": "not_applied",
            "candidate_count": len(results),
            "qualified_count": len(results),
            "rejected_count": 0,
        }
    qualified: list[dict[str, Any]] = []
    rejected: list[dict[str, Any]] = []
    for item in results:
        evidence = item.get("operational_group") if isinstance(item.get("operational_group"), dict) else {}
        if evidence.get("accepted") is True:
            qualified.append(item)
            continue
        rejected.append(
            {
                "doc_id": str(item.get("doc_id") or ""),
                "session_id": str(item.get("session_id") or ""),
                "task_episode_id": str(item.get("task_episode_id") or ""),
                "status": str(evidence.get("status") or "operational_group_missing"),
            }
        )
    ambiguous_within_episode = sum(
        1
        for item in qualified
        if isinstance(item.get("operational_group"), dict)
        and item["operational_group"].get("ambiguous_within_episode") is True
    )
    ambiguous = len(qualified) > 1 or ambiguous_within_episode > 0
    return qualified, {
        "status": (
            "ambiguous_operational_groups_available"
            if ambiguous
            else "qualified_operational_groups_available"
            if qualified
            else "no_qualified_operational_group"
        ),
        "requested_cardinality": int_value(group_query.get("requested_cardinality")),
        "operation": str(group_query.get("operation") or ""),
        "candidate_count": len(results),
        "qualified_count": len(qualified),
        "rejected_count": len(rejected),
        "ambiguous": ambiguous,
        "ambiguous_within_episode_count": ambiguous_within_episode,
        "rejected_samples": rejected[:5],
        "policy": "explicit parallel-cardinality queries require a typed raw call group with distinct successful members",
    }


EPISODE_DELEGATED_LIFECYCLE_MAX_CANDIDATES = 64


def episode_delegated_lifecycle_raw_rows(
    raw_path: Path,
    lines: set[int],
) -> tuple[dict[int, dict[str, Any]], dict[str, Any]]:
    selected: dict[int, dict[str, Any]] = {}
    requested = sorted(line for line in lines if line > 0)
    if not requested:
        return {}, {"status": "no_requested_lines", "bounded": True}
    maximum = requested[-1]
    handle_context = (
        gzip.open(raw_path, "rt", encoding="utf-8", errors="replace")
        if raw_path.suffix == ".gz"
        else raw_path.open("r", encoding="utf-8", errors="replace")
    )
    with handle_context as handle:
        for line_no, raw_line in enumerate(handle, start=1):
            if line_no in lines:
                try:
                    row = json.loads(raw_line)
                except json.JSONDecodeError:
                    row = {}
                if isinstance(row, dict):
                    selected[line_no] = row
            if line_no >= maximum:
                break
    missing = [line for line in requested if line not in selected]
    return selected, {
        "status": "complete" if not missing else "incomplete",
        "requested_line_count": len(requested),
        "line_count": len(selected),
        "missing_lines": missing,
        "scanned_to_line": maximum,
        "bounded": True,
    }


def episode_delegated_task_content_status(
    payload: dict[str, Any],
) -> tuple[str, str]:
    content = payload.get("content") if isinstance(payload.get("content"), list) else []
    encrypted = any(
        isinstance(item, dict)
        and str(item.get("type") or "") == "encrypted_content"
        for item in content
    )
    clear_text = "\n".join(
        str(item.get("text") or "")
        for item in content
        if isinstance(item, dict)
        and str(item.get("type") or "") in {"input_text", "text"}
    )
    payload_match = re.search(
        r"(?:^|\n)Payload:\s*(?P<payload>.*)\Z",
        clear_text,
        flags=re.DOTALL | re.IGNORECASE,
    )
    clear_payload = (
        str(payload_match.group("payload") or "").strip()
        if payload_match
        else ""
    )
    if clear_payload:
        return "clear_payload_available", clear_payload
    if encrypted:
        return "encrypted_payload_unavailable", ""
    return "transport_envelope_only", ""


def episode_delegated_lifecycle_relation_gate(
    *,
    aoa_root: Path,
    session_record: dict[str, Any],
    results: list[dict[str, Any]],
    query: dict[str, Any],
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    clones = [dict(item) for item in results]
    base = {
        "schema_version": 1,
        "active": bool(query.get("active")),
        "applied": False,
        "mutates": False,
        "mode": str(query.get("mode") or ""),
        "requested_cardinality": int_value(query.get("requested_cardinality")),
        "target": str(query.get("target") or ""),
        "structural_claim_admitted": False,
        "semantic_identity_claim_admitted": False,
        "replay_claim_admitted": False,
        "authority": "hash_verified_archived_raw_session_snapshot",
    }
    if not query.get("active"):
        return clones, {**base, "status": "not_requested"}
    if not session_record:
        return clones, {
            **base,
            "status": "session_record_unresolved",
            "reason": "delegated lifecycle admission requires one exact session",
        }
    session_dir = session_dir_from_record(session_record)
    manifest_path = session_dir / "session.manifest.json"
    session_index_path = session_dir / SESSION_INDEX_JSON
    manifest = read_json(manifest_path, {})
    session_index = read_json(session_index_path, {})
    if not isinstance(manifest, dict) or not manifest:
        return clones, {**base, "status": "manifest_unavailable"}
    if not isinstance(session_index, dict) or not session_index:
        return clones, {**base, "status": "session_index_unavailable"}
    expected_publish_id, expected_raw_sha256 = session_manifest_projection_expectations(manifest)
    generation_reasons = generated_session_index_stale_reasons(
        session_index,
        expected_publish_id=expected_publish_id,
        expected_raw_sha256=expected_raw_sha256,
    )
    generation_packet = {
        "expected": session_memory_expected_generation_identities(aoa_root).get("session_index", {}),
        "observed": (
            session_index.get("generation_identity")
            if isinstance(session_index.get("generation_identity"), dict)
            else {}
        ),
        "compatible": not generation_reasons,
        "reasons": generation_reasons,
    }
    if generation_reasons:
        return clones, {
            **base,
            "status": "incompatible_session_index_generation",
            "generation_identity": generation_packet,
        }
    raw_path = manifest_raw_path(session_dir, manifest)
    archive_integrity = search_manifest_archived_raw_integrity(manifest, raw_path)
    if archive_integrity.get("status") != "verified":
        return clones, {
            **base,
            "status": "archived_raw_integrity_unverified",
            "generation_identity": generation_packet,
            "archive_integrity": archive_integrity,
        }
    task_episodes = session_index_task_episode_components(
        session_dir,
        session_index,
    )
    candidates = [
        (episode, episode_delegated_lifecycle_alignment(episode, query=query))
        for episode in task_episodes
    ]
    candidates = [
        pair
        for pair in candidates
        if pair[1].get("status") == "typed_delegated_lifecycle_candidate"
    ]
    candidate_window_truncated = len(candidates) > EPISODE_DELEGATED_LIFECYCLE_MAX_CANDIDATES
    candidates = candidates[:EPISODE_DELEGATED_LIFECYCLE_MAX_CANDIDATES]
    requested_lines: set[int] = set()
    for _episode, alignment in candidates:
        refs = alignment.get("structural_refs") or {}
        requested_lines.update(
            line_from_raw_ref(refs.get(key))
            for key in ("task_started", "delegation", "terminal_candidate")
        )
    raw_rows, raw_read = episode_delegated_lifecycle_raw_rows(raw_path, requested_lines)
    target = str(query.get("target") or "")
    all_chains: list[dict[str, Any]] = []
    for episode, alignment in candidates:
        refs = alignment.get("structural_refs") or {}
        start_line = line_from_raw_ref(refs.get("task_started"))
        delegation_line = line_from_raw_ref(refs.get("delegation"))
        terminal_line = line_from_raw_ref(refs.get("terminal_candidate"))
        start_row = raw_rows.get(start_line, {})
        delegation_row = raw_rows.get(delegation_line, {})
        terminal_row = raw_rows.get(terminal_line, {})
        start_payload = start_row.get("payload") if isinstance(start_row.get("payload"), dict) else {}
        delegation_payload = delegation_row.get("payload") if isinstance(delegation_row.get("payload"), dict) else {}
        terminal_payload = terminal_row.get("payload") if isinstance(terminal_row.get("payload"), dict) else {}
        metadata = delegation_payload.get("internal_chat_message_metadata_passthrough")
        metadata = metadata if isinstance(metadata, dict) else {}
        turns = (
            str(start_payload.get("turn_id") or ""),
            str(metadata.get("turn_id") or ""),
            str(terminal_payload.get("turn_id") or ""),
        )
        recipient = str(delegation_payload.get("recipient") or "")
        content_status, clear_payload = episode_delegated_task_content_status(delegation_payload)
        rejection_reasons: list[str] = []
        if str(start_row.get("type") or "") != "event_msg" or str(start_payload.get("type") or "") != "task_started":
            rejection_reasons.append("task_started_row_invalid")
        if str(delegation_row.get("type") or "") != "response_item" or str(delegation_payload.get("type") or "") != "agent_message":
            rejection_reasons.append("delegation_row_invalid")
        if str(terminal_row.get("type") or "") != "event_msg" or str(terminal_payload.get("type") or "") != "task_complete":
            rejection_reasons.append("task_complete_row_invalid")
        if not turns[0] or len(set(turns)) != 1:
            rejection_reasons.append("turn_identity_mismatch")
        if not (0 < start_line < delegation_line < terminal_line):
            rejection_reasons.append("lifecycle_order_invalid")
        if not recipient:
            rejection_reasons.append("delegation_recipient_missing")
        if str(delegation_payload.get("author") or "") != "/root":
            rejection_reasons.append("delegation_author_unexpected")
        if str(episode.get("status") or "") != "closed":
            rejection_reasons.append("episode_not_closed")
        all_chains.append(
            {
                "episode_id": str(episode.get("episode_id") or ""),
                "stable_id": str(alignment.get("stable_id") or ""),
                "status": "qualified" if not rejection_reasons else "rejected",
                "turn_id": turns[0],
                "author": str(delegation_payload.get("author") or ""),
                "recipient": recipient,
                "content_status": content_status,
                "clear_payload_sha256": (
                    hashlib.sha256(clear_payload.encode("utf-8")).hexdigest()
                    if clear_payload
                    else ""
                ),
                "transition_reason": str(alignment.get("transition_reason") or ""),
                "previous_episode_id": str(alignment.get("previous_episode_id") or ""),
                "lineage_scope": str(alignment.get("lineage_scope") or ""),
                "refs": {
                    "task_started": f"raw:line:{start_line}",
                    "delegation": f"raw:line:{delegation_line}",
                    "task_complete": f"raw:line:{terminal_line}",
                    "session": str(manifest_path),
                    "session_index": str(session_index_path),
                },
                "rejection_reasons": rejection_reasons,
            }
        )
    all_chains.sort(
        key=lambda item: line_from_raw_ref(
            (item.get("refs") or {}).get("task_started")
        )
    )
    recipient_groups: defaultdict[str, list[dict[str, Any]]] = defaultdict(
        list
    )
    for chain in all_chains:
        recipient = str(chain.get("recipient") or "")
        if recipient:
            recipient_groups[recipient].append(chain)
    requested_cardinality = int_value(query.get("requested_cardinality"))
    group_selection_status = ""
    selected_recipient = ""
    if target:
        selected_recipient = target
        chains = list(recipient_groups.get(target, []))
        group_selection_status = (
            "exact_target_group_selected"
            if chains
            else "exact_target_group_missing"
        )
    else:
        cardinality_groups = [
            recipient
            for recipient, group in recipient_groups.items()
            if not requested_cardinality
            or len(
                [item for item in group if item.get("status") == "qualified"]
            )
            == requested_cardinality
        ]
        if len(cardinality_groups) == 1:
            selected_recipient = cardinality_groups[0]
            chains = list(recipient_groups[selected_recipient])
            group_selection_status = "unique_recipient_group_selected"
        elif len(cardinality_groups) > 1:
            chains = []
            group_selection_status = "ambiguous_recipient_groups"
        elif len(recipient_groups) == 1:
            selected_recipient = next(iter(recipient_groups))
            chains = list(recipient_groups[selected_recipient])
            group_selection_status = "sole_recipient_group_cardinality_mismatch"
        else:
            chains = []
            group_selection_status = "recipient_group_unresolved"
    selected_episode_ids = {
        str(item.get("episode_id") or "") for item in chains
    }
    out_of_scope_chains = [
        item
        for item in all_chains
        if str(item.get("episode_id") or "") not in selected_episode_ids
    ]
    sequence_continuity_warnings: list[str] = []
    for previous, current in zip(chains, chains[1:]):
        if str(current.get("previous_episode_id") or "") != str(previous.get("episode_id") or ""):
            sequence_continuity_warnings.append(
                f"{current.get('episode_id')}:previous_episode_mismatch"
            )
    continuity_reasons: list[str] = []
    turn_ids = [str(item.get("turn_id") or "") for item in chains]
    if len(turn_ids) != len(set(turn_ids)):
        continuity_reasons.append("delegated_lifecycle_turn_ids_not_distinct")
    qualified = [item for item in chains if item.get("status") == "qualified"]
    cardinality_matches = not requested_cardinality or len(qualified) == requested_cardinality
    group_selection_resolved = group_selection_status in {
        "exact_target_group_selected",
        "unique_recipient_group_selected",
        "sole_recipient_group_cardinality_mismatch",
    }
    structural_admitted = bool(
        qualified
        and len(qualified) == len(chains)
        and group_selection_resolved
        and not continuity_reasons
        and cardinality_matches
        and not candidate_window_truncated
        and raw_read.get("status") == "complete"
    )
    chain_by_episode = {str(item.get("episode_id") or ""): item for item in chains}
    for result in clones:
        chain = chain_by_episode.get(str(result.get("task_episode_id") or ""))
        if not chain:
            continue
        result["delegated_lifecycle_evidence"] = chain
        result["rerank_score"] = float(result.get("rerank_score") or 0.0) + (
            900.0 if chain.get("status") == "qualified" else 0.0
        )
        supporting = list(result.get("supporting_evidence") or [])
        for role in ("task_started", "delegation", "task_complete"):
            supporting.append(
                {
                    "role": f"delegated_lifecycle_{role}",
                    "admission_basis": "hash_verified_structured_raw_row",
                    "refs": {
                        "raw": str((chain.get("refs") or {}).get(role) or ""),
                        "session": str(manifest_path),
                    },
                }
            )
        result["supporting_evidence"] = supporting
        freshness = dict(result.get("freshness") or {})
        freshness.update(
            {
                "source_fingerprint": str(archive_integrity.get("sha256") or ""),
                "hash_verification": "performed_on_relation_gate",
            }
        )
        result["freshness"] = freshness
    clones.sort(
        key=lambda item: (
            0 if item.get("delegated_lifecycle_evidence") else 1,
            line_from_raw_ref(
                (
                    item.get("delegated_lifecycle_evidence", {}).get("refs", {})
                    if isinstance(item.get("delegated_lifecycle_evidence"), dict)
                    else {}
                ).get("task_started")
            ),
            str(item.get("doc_id") or ""),
        )
    )
    semantic_identity_requested = str(query.get("mode") or "") == "semantic_identity"
    return clones, {
        **base,
        "applied": True,
        "status": (
            "semantic_identity_unresolved"
            if semantic_identity_requested and structural_admitted
            else "qualified_delegated_lifecycle_group"
            if structural_admitted
            else "delegated_lifecycle_group_unresolved"
        ),
        "structural_claim_admitted": structural_admitted,
        "semantic_identity_claim_admitted": False,
        "replay_claim_admitted": False,
        "qualified_count": len(qualified),
        "selected_candidate_count": len(chains),
        "candidate_count": len(all_chains),
        "candidate_count_exhaustive": not candidate_window_truncated and raw_read.get("status") == "complete",
        "cardinality_matches": cardinality_matches,
        "continuity_reasons": continuity_reasons,
        "sequence_continuity_warnings": sequence_continuity_warnings,
        "group_selection_status": group_selection_status,
        "selected_recipient": selected_recipient,
        "recipient_groups": [
            {
                "recipient": recipient,
                "candidate_count": len(group),
                "qualified_count": sum(
                    1 for item in group if item.get("status") == "qualified"
                ),
            }
            for recipient, group in sorted(recipient_groups.items())
        ],
        "out_of_scope_candidate_count": len(out_of_scope_chains),
        "out_of_scope_samples": [
            {
                "episode_id": str(item.get("episode_id") or ""),
                "recipient": str(item.get("recipient") or ""),
                "status": str(item.get("status") or ""),
            }
            for item in out_of_scope_chains[:8]
        ],
        "candidate_window_truncated": candidate_window_truncated,
        "chains": chains,
        "generation_identity": generation_packet,
        "archive_integrity": archive_integrity,
        "raw_read": raw_read,
        "freshness": {
            "global": manifest_live_source_snapshot_freshness(manifest),
            "scoped_archive": {
                "status": "current",
                "source_fingerprint": str(archive_integrity.get("sha256") or ""),
                "coverage": "complete" if structural_admitted else "partial",
                "scope": str(session_index.get("session_id") or ""),
            },
        },
        "semantic_identity_status": (
            "unresolved_encrypted_or_absent_task_payload"
            if semantic_identity_requested
            and any(item.get("content_status") != "clear_payload_available" for item in qualified)
            else "replay_relation_not_proven"
            if semantic_identity_requested
            else "not_requested"
        ),
        "claim_boundary": (
            "distinct source-backed lifecycles do not prove that encrypted "
            "tasks were semantically equal, duplicates, or replayed"
        ),
    }


def episode_quantitative_comparison_numeric_rows(output: str) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for match in re.finditer(
        r"(?m)^\s*(?P<count>\d+)\s+(?P<label>[^\s][^\r\n]*?)\s*$",
        str(output or ""),
    ):
        label = re.sub(r"\s+", " ", str(match.group("label") or "")).strip()
        if not label or label.casefold().startswith(
            ("original token count", "process exited", "wall time")
        ):
            continue
        rows.append(
            {
                "count": int_value(match.group("count")),
                "label": derived_text_privacy_text(
                    label,
                    max_chars=160,
                ),
            }
        )
    return rows[:64]


def episode_quantitative_comparison_command_profile(command: str) -> dict[str, Any]:
    text = str(command or "")
    folded = text.casefold()
    change_scope = bool(
        re.search(r"\bgit(?:\s+-c\s+\S+|\s+-C\s+\S+)*\s+diff\b", text)
        or re.search(r"(?<![a-z0-9_])diff(?:\s|$)", folded)
    )
    count_scope = bool(
        re.search(r"(?<![a-z0-9_])uniq\s+-[a-z]*c", folded)
        or re.search(r"(?<![a-z0-9_])wc\s+-[a-z]*l", folded)
        or re.search(r"(?<![a-z0-9_])count\s*\(", folded)
        or re.search(r"\bgroup\s+by\b", folded)
        or "counter(" in folded
    )
    descending_rank = bool(
        re.search(r"(?<![a-z0-9_])sort\s+-[a-z]*n[a-z]*r[a-z]*", folded)
        or re.search(r"(?<![a-z0-9_])sort\s+-[a-z]*r[a-z]*n[a-z]*", folded)
    )
    ascending_rank = bool(
        re.search(r"(?<![a-z0-9_])sort\s+-[a-z]*n[a-z]*", folded)
    )
    line_count_scope = bool(
        re.search(r"(?<![a-z0-9_])wc\s+-[a-z]*l", folded)
        and not change_scope
    )
    measurement_kind = (
        "ranked_change_count"
        if change_scope
        else "line_count"
        if line_count_scope
        else "unknown"
    )
    return {
        "change_scope": change_scope,
        "count_scope": count_scope,
        "descending_rank": descending_rank,
        "ascending_rank": ascending_rank,
        "line_count_scope": line_count_scope,
        "measurement_kind": measurement_kind,
        "accepted_shape": bool(
            (
                change_scope
                and count_scope
                and (descending_rank or ascending_rank)
            )
            or line_count_scope
        ),
    }


def episode_quantitative_comparison_chain_entry(
    *,
    role: str,
    line: int,
    text: str,
    correlation_id: str,
    refs: dict[str, Any],
    matched_query_terms: list[str],
    command: str = "",
    workdir: str = "",
    result_status: str = "",
    exit_code: int | None = None,
) -> dict[str, Any]:
    entry = {
        "role": role,
        "line": line,
        "text": derived_text_privacy_text(text, max_chars=1200),
        "source_lane": (
            "structured_tool_call"
            if role == "actions"
            else "structured_tool_result"
        ),
        "event_type": "COMMAND" if role == "actions" else "COMMAND_OUTPUT",
        "admission_basis": (
            "structured_quantitative_count_action"
            if role == "actions"
            else "correlation_owned_quantitative_numeric_result"
        ),
        "correlation_id": correlation_id,
        "matched_query_terms": sorted(set(matched_query_terms)),
        "refs": {
            key: str(value)
            for key, value in refs.items()
            if value
        },
    }
    if command:
        entry["command"] = derived_text_privacy_text(command)
    if workdir:
        entry["workdir"] = derived_text_privacy_text(workdir)
    if result_status:
        entry["result_status"] = result_status
    if exit_code is not None:
        entry["exit_code"] = exit_code
    return entry


def episode_quantitative_comparison_scoped_raw_hydration(
    *,
    raw_path: Path | None,
    segments: list[dict[str, Any]],
    results: list[dict[str, Any]],
    comparison_query: dict[str, Any],
    max_raw_bytes: int = EPISODE_QUANTITATIVE_COMPARISON_MAX_RAW_BYTES,
    max_lines: int = EPISODE_QUANTITATIVE_COMPARISON_MAX_LINES,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Hydrate one ranked-count action/result chain from bounded raw evidence."""
    started = time.monotonic()
    clones = [dict(item) for item in results if isinstance(item, dict)]
    base_report: dict[str, Any] = {
        "status": "not_requested",
        "applied": False,
        "mutates": False,
        "candidate_count": len(clones),
        "qualified_candidate_count": 0,
        "evidence_source": "scoped_raw_quantitative_action_result_chain",
    }
    if not comparison_query.get("active"):
        return clones, {
            **base_report,
            "status": "not_a_quantitative_comparison_query",
        }
    if not raw_path or not raw_path.is_file():
        return clones, {**base_report, "status": "raw_path_missing"}
    stored_raw_bytes = raw_path.stat().st_size
    if max_raw_bytes <= 0 or stored_raw_bytes > max_raw_bytes:
        return clones, {
            **base_report,
            "status": "raw_over_bounded_quantitative_limit",
            "stored_raw_bytes": stored_raw_bytes,
            "max_raw_bytes": max_raw_bytes,
        }
    candidate_ranges: list[tuple[str, int, int, dict[str, Any]]] = []
    for item in clones:
        event_range = (
            item.get("event_range")
            if isinstance(item.get("event_range"), dict)
            else {}
        )
        from_line = int_value(event_range.get("from_line"))
        to_line = int_value(event_range.get("to_line"))
        if from_line > 0 and to_line >= from_line:
            candidate_ranges.append(
                (
                    str(item.get("session_id") or ""),
                    from_line,
                    to_line,
                    item,
                )
            )
    if not candidate_ranges:
        return clones, {
            **base_report,
            "status": "candidate_ranges_missing",
            "stored_raw_bytes": stored_raw_bytes,
        }
    candidate_ranges.sort(key=lambda item: (item[0], item[1], item[2]))
    candidate_session_ids = {
        session_id for session_id, _from, _to, _item in candidate_ranges if session_id
    }
    session_id = (
        next(iter(candidate_session_ids))
        if len(candidate_session_ids) == 1
        else ""
    )

    actions: list[dict[str, Any]] = []
    results_by_correlation: dict[str, dict[str, Any]] = {}
    lines_scanned = 0
    decoded_bytes_scanned = 0
    parsed_event_count = 0
    line_budget_exhausted = False
    byte_budget_exhausted = False
    try:
        opener = gzip.open if raw_path.suffix == ".gz" else open
        with opener(raw_path, "rt", encoding="utf-8", errors="replace") as handle:
            for line_no, line in enumerate(handle, start=1):
                if lines_scanned >= max_lines:
                    line_budget_exhausted = True
                    break
                line_bytes = len(line.encode("utf-8", errors="replace"))
                if decoded_bytes_scanned + line_bytes > max_raw_bytes:
                    byte_budget_exhausted = True
                    break
                lines_scanned += 1
                decoded_bytes_scanned += line_bytes
                try:
                    parsed = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if not isinstance(parsed, dict):
                    continue
                parsed_event_count += 1
                if str(parsed.get("type") or "") != "response_item":
                    continue
                payload = (
                    parsed.get("payload")
                    if isinstance(parsed.get("payload"), dict)
                    else {}
                )
                payload_type = str(payload.get("type") or "")
                correlation_id = str(payload_correlation_id(payload) or "")
                if payload_type in EPISODE_TEMPORAL_RAW_CALL_TYPES:
                    if (
                        len(actions)
                        >= EPISODE_QUANTITATIVE_COMPARISON_MAX_ACTIONS
                    ):
                        continue
                    arguments = command_payload_args(payload)
                    raw_command = str(
                        arguments.get("cmd")
                        or arguments.get("command")
                        or ""
                    )
                    profile = episode_quantitative_comparison_command_profile(
                        raw_command
                    )
                    if not profile.get("accepted_shape") or not correlation_id:
                        continue
                    workdir = str(
                        arguments.get("workdir")
                        or arguments.get("cwd")
                        or ""
                    )
                    command = derived_text_privacy_text(raw_command)
                    segment = segment_for_line(segments, line_no)
                    actions.append(
                        {
                            "line": line_no,
                            "timestamp": str(parsed.get("timestamp") or ""),
                            "correlation_id": correlation_id,
                            "tool_name": normalized_tool_name(
                                tool_name_from_payload(payload)
                            ),
                            "command": command,
                            "workdir": derived_text_privacy_text(workdir),
                            "profile": profile,
                            "refs": {
                                "raw": f"raw:line:{line_no}",
                                "segment": str(segment.get("markdown") or ""),
                                "segment_index": str(segment.get("index") or ""),
                            },
                        }
                    )
                    continue
                if (
                    payload_type in EPISODE_TEMPORAL_RAW_RESULT_TYPES
                    and correlation_id
                ):
                    raw_output = str(
                        payload.get("output")
                        or payload.get("content")
                        or ""
                    )
                    exit_match = re.search(
                        r"Process exited with code\s+(-?\d+)",
                        raw_output,
                    )
                    exit_code = (
                        int(exit_match.group(1))
                        if exit_match
                        else None
                    )
                    segment = segment_for_line(segments, line_no)
                    results_by_correlation[correlation_id] = {
                        "line": line_no,
                        "timestamp": str(parsed.get("timestamp") or ""),
                        "correlation_id": correlation_id,
                        "output": derived_text_privacy_text(raw_output),
                        "exit_code": exit_code,
                        "status": (
                            "succeeded"
                            if exit_code == 0
                            else "failed"
                            if exit_code is not None
                            else "observed"
                        ),
                        "numeric_rows": (
                            episode_quantitative_comparison_numeric_rows(
                                raw_output
                            )
                        ),
                        "refs": {
                            "raw": f"raw:line:{line_no}",
                            "segment": str(segment.get("markdown") or ""),
                            "segment_index": str(segment.get("index") or ""),
                        },
                    }
    except (OSError, EOFError) as exc:
        return clones, {
            **base_report,
            "status": "raw_source_unreadable",
            "stored_raw_bytes": stored_raw_bytes,
            "diagnostics": [str(exc)],
        }

    subject_terms = [
        term
        for term in comparison_query.get("subject_terms", [])
        if isinstance(term, dict)
    ]
    context_terms = [
        term
        for term in comparison_query.get("context_terms", [])
        if isinstance(term, dict)
    ]
    baseline_terms = [
        term
        for term in comparison_query.get("baseline_terms", [])
        if isinstance(term, dict)
    ]
    requested_direction = str(
        comparison_query.get("direction") or "descending"
    )
    chains_by_doc: dict[str, list[dict[str, Any]]] = defaultdict(list)
    rejected_action_count = 0
    for action in actions:
        result = results_by_correlation.get(
            str(action.get("correlation_id") or ""),
            {},
        )
        if not result or int_value(result.get("line")) <= int_value(
            action.get("line")
        ):
            rejected_action_count += 1
            continue
        numeric_rows = [
            row
            for row in result.get("numeric_rows") or []
            if isinstance(row, dict)
        ]
        if comparison_query.get("operation") == "line_count":
            numeric_rows = [
                row
                for row in numeric_rows
                if str(row.get("label") or "").strip().casefold()
                not in {"total", "итого"}
            ]
        if (
            str(result.get("status") or "") != "succeeded"
            or len(numeric_rows) < 2
        ):
            rejected_action_count += 1
            continue
        profile = (
            action.get("profile")
            if isinstance(action.get("profile"), dict)
            else {}
        )
        if (
            comparison_query.get("operation") == "change_count"
            and requested_direction == "descending"
            and not profile.get("descending_rank")
        ):
            rejected_action_count += 1
            continue
        evidence_text = " ".join(
            (
                str(action.get("command") or ""),
                str(action.get("workdir") or ""),
            )
        )
        evidence_tokens = episode_semantic_field_tokens(evidence_text)

        def matched(terms: list[dict[str, Any]]) -> list[str]:
            return sorted(
                {
                    str(term.get("token") or "")
                    for term in terms
                    if episode_semantic_term_matches_tokens(
                        term,
                        evidence_tokens,
                    )
                }
            )

        matched_subject_terms = matched(subject_terms)
        matched_context_terms = matched(context_terms)
        matched_baseline_terms = matched(baseline_terms)
        subject_coverage = (
            len(matched_subject_terms) / len(subject_terms)
            if subject_terms
            else 0.0
        )
        context_coverage = (
            len(matched_context_terms) / len(context_terms)
            if context_terms
            else 1.0
        )
        baseline_coverage = (
            len(matched_baseline_terms) / len(baseline_terms)
            if baseline_terms
            else 1.0
        )
        if (
            not matched_subject_terms
            or subject_coverage < 0.5
            or context_coverage < 0.5
            or baseline_coverage < 1.0
        ):
            rejected_action_count += 1
            continue
        action_line = int_value(action.get("line"))
        candidate = next(
            (
                item
                for candidate_session_id, candidate_from, candidate_to, item
                in candidate_ranges
                if (
                    (not session_id or not candidate_session_id or candidate_session_id == session_id)
                    and candidate_from <= action_line <= candidate_to
                )
            ),
            None,
        )
        if not isinstance(candidate, dict):
            rejected_action_count += 1
            continue
        matched_query_terms = [
            *matched_subject_terms,
            *matched_context_terms,
            *matched_baseline_terms,
        ]
        action_entry = episode_quantitative_comparison_chain_entry(
            role="actions",
            line=action_line,
            text=str(action.get("command") or ""),
            command=str(action.get("command") or ""),
            workdir=str(action.get("workdir") or ""),
            correlation_id=str(action.get("correlation_id") or ""),
            refs=(
                action.get("refs")
                if isinstance(action.get("refs"), dict)
                else {}
            ),
            matched_query_terms=matched_query_terms,
        )
        result_entry = episode_quantitative_comparison_chain_entry(
            role="outcomes",
            line=int_value(result.get("line")),
            text=str(result.get("output") or ""),
            correlation_id=str(result.get("correlation_id") or ""),
            refs=(
                result.get("refs")
                if isinstance(result.get("refs"), dict)
                else {}
            ),
            matched_query_terms=[],
            result_status=str(result.get("status") or ""),
            exit_code=(
                int_value(result.get("exit_code"))
                if result.get("exit_code") is not None
                else None
            ),
        )
        chain = {
            "active": True,
            "accepted": True,
            "status": "correlation_owned_ranked_count_available",
            "relation_basis": (
                "structured_measurement_action_plus_"
                "correlation_owned_successful_numeric_result"
            ),
            "correlation_id": str(action.get("correlation_id") or ""),
            "action": action_entry,
            "result": result_entry,
            "result_status": str(result.get("status") or ""),
            "numeric_rows": numeric_rows,
            "numeric_row_count": len(numeric_rows),
            "matched_subject_terms": matched_subject_terms,
            "matched_context_terms": matched_context_terms,
            "matched_baseline_terms": matched_baseline_terms,
            "subject_coverage": round(subject_coverage, 4),
            "context_coverage": round(context_coverage, 4),
            "baseline_coverage": round(baseline_coverage, 4),
            "direction": requested_direction,
            "authority": "raw_session_transcript",
        }
        chains_by_doc[str(candidate.get("doc_id") or "")].append(chain)

    qualified_candidate_count = 0
    qualified_chain_count = 0
    for item in clones:
        chains = chains_by_doc.get(str(item.get("doc_id") or ""), [])
        if not chains:
            continue
        chains.sort(
            key=lambda chain: (
                -float(chain.get("subject_coverage") or 0.0),
                -float(chain.get("context_coverage") or 0.0),
                -float(chain.get("baseline_coverage") or 0.0),
                -int_value(chain.get("numeric_row_count")),
                int_value((chain.get("action") or {}).get("line")),
            )
        )
        evidence = dict(chains[0])
        evidence["qualified_chain_count"] = len(chains)
        evidence["ambiguous_within_episode"] = len(chains) > 1
        item["quantitative_comparison"] = evidence
        exact_support: list[dict[str, Any]] = []
        for role, signal in (
            ("action", "quantitative_comparison_action"),
            ("result", "correlation_owned_quantitative_result"),
        ):
            entry = evidence.get(role)
            if not isinstance(entry, dict):
                continue
            support_entry = dict(entry)
            support_entry["reading_score"] = round(
                800.0 - len(exact_support),
                4,
            )
            support_entry["reading_signals"] = [
                signal,
                "typed_relation_evidence",
                "raw_correlation_verified",
            ]
            exact_support.append(support_entry)
        existing_support = (
            item.get("supporting_evidence")
            if isinstance(item.get("supporting_evidence"), list)
            else []
        )
        selected_support: list[dict[str, Any]] = []
        seen_raw_refs: set[str] = set()
        for entry in [*exact_support, *existing_support]:
            if not isinstance(entry, dict):
                continue
            refs = (
                entry.get("refs")
                if isinstance(entry.get("refs"), dict)
                else {}
            )
            raw_ref = str(refs.get("raw") or "")
            if raw_ref and raw_ref in seen_raw_refs:
                continue
            if raw_ref:
                seen_raw_refs.add(raw_ref)
            selected_support.append(entry)
            if len(selected_support) >= 12:
                break
        item["supporting_evidence"] = selected_support
        item["match_channels"] = list(
            dict.fromkeys(
                [
                    *list(item.get("match_channels") or []),
                    str(item.get("match_channel") or ""),
                    "episode_quantitative_comparison_raw_hydration",
                ]
            )
        )
        qualified_candidate_count += 1
        qualified_chain_count += len(chains)
    clones.sort(
        key=lambda item: (
            0
            if isinstance(item.get("quantitative_comparison"), dict)
            and item["quantitative_comparison"].get("accepted") is True
            else 1,
            int_value(item.get("sparse_rank"), 2**31 - 1),
            str(item.get("doc_id") or ""),
        )
    )
    return clones, {
        **base_report,
        "status": (
            "applied_truncated"
            if line_budget_exhausted or byte_budget_exhausted
            else "applied"
        ),
        "applied": True,
        "raw_path": str(raw_path),
        "stored_raw_bytes": stored_raw_bytes,
        "decoded_bytes_scanned": decoded_bytes_scanned,
        "max_raw_bytes": max_raw_bytes,
        "max_lines": max_lines,
        "lines_scanned": lines_scanned,
        "parsed_event_count": parsed_event_count,
        "line_budget_exhausted": line_budget_exhausted,
        "byte_budget_exhausted": byte_budget_exhausted,
        "candidate_action_count": len(actions),
        "rejected_action_count": rejected_action_count,
        "qualified_candidate_count": qualified_candidate_count,
        "qualified_chain_count": qualified_chain_count,
        "elapsed_ms": int((time.monotonic() - started) * 1000),
        "authority_boundary": (
            "typed quantitative chain is query-time navigation over "
            "correlation-owned raw action/result refs"
        ),
    }


def episode_quantitative_comparison_relation_gate(
    results: list[dict[str, Any]],
    comparison_query: dict[str, Any],
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    if not comparison_query.get("active"):
        return results, {
            "status": "not_applied",
            "candidate_count": len(results),
            "qualified_count": len(results),
            "rejected_count": 0,
        }
    qualified: list[dict[str, Any]] = []
    rejected: list[dict[str, Any]] = []
    for item in results:
        evidence = (
            item.get("quantitative_comparison")
            if isinstance(item.get("quantitative_comparison"), dict)
            else {}
        )
        if evidence.get("accepted") is True:
            qualified.append(item)
            continue
        rejected.append(
            {
                "doc_id": str(item.get("doc_id") or ""),
                "session_id": str(item.get("session_id") or ""),
                "task_episode_id": str(item.get("task_episode_id") or ""),
                "status": str(
                    evidence.get("status")
                    or "quantitative_comparison_missing"
                ),
            }
        )
    ambiguous_within_episode = sum(
        1
        for item in qualified
        if isinstance(item.get("quantitative_comparison"), dict)
        and item["quantitative_comparison"].get(
            "ambiguous_within_episode"
        )
        is True
    )
    ambiguous = len(qualified) > 1 or ambiguous_within_episode > 0
    return qualified, {
        "status": (
            "ambiguous_quantitative_comparisons_available"
            if ambiguous
            else "qualified_quantitative_comparison_available"
            if qualified
            else "no_qualified_quantitative_comparison"
        ),
        "operation": str(comparison_query.get("operation") or ""),
        "direction": str(comparison_query.get("direction") or ""),
        "candidate_count": len(results),
        "qualified_count": len(qualified),
        "rejected_count": len(rejected),
        "ambiguous": ambiguous,
        "ambiguous_within_episode_count": ambiguous_within_episode,
        "rejected_samples": rejected[:5],
        "policy": (
            "quantitative comparative claims require one subject-matched "
            "counting action and its correlation-owned successful numeric result"
        ),
    }


def episode_semantic_candidate_evidence(
    episode: dict[str, Any],
    terms: list[dict[str, Any]],
    *,
    temporal_span: dict[str, Any] | None = None,
    query_text: str = "",
) -> dict[str, Any]:
    representations = episode.get("representations") if isinstance(episode.get("representations"), dict) else {}
    field_texts = {
        role: episode_semantic_role_text(episode, role)
        for role in ("intents", "plans", "actions", "outcomes", "verification", "failures", "reasoning")
    }
    field_texts["narrative"] = str(episode.get("narrative") or "")
    field_texts["anchors"] = episode_semantic_anchor_text(episode)
    field_tokens = {field: episode_semantic_field_tokens(text) for field, text in field_texts.items()}
    matched_by_field: dict[str, list[str]] = {}
    matched_terms: set[str] = set()
    best_weight_by_term: dict[str, float] = {}
    reading_intents = episode_semantic_reading_intents(terms, query_text=query_text)
    event_range = episode.get("event_range") if isinstance(episode.get("event_range"), dict) else {}
    for field, tokens in field_tokens.items():
        matches = [str(term.get("token") or "") for term in terms if episode_semantic_term_matches_tokens(term, tokens)]
        if matches:
            matched_by_field[field] = matches
            for token in matches:
                matched_terms.add(token)
                best_weight_by_term[token] = max(best_weight_by_term.get(token, 0.0), EPISODE_SEMANTIC_FIELD_WEIGHTS[field])
    support: list[dict[str, Any]] = []
    for role, items in representations.items():
        if not isinstance(items, list):
            continue
        for item in items:
            if not isinstance(item, dict):
                continue
            tokens = episode_semantic_field_tokens(item.get("text"))
            matches = [str(term.get("token") or "") for term in terms if episode_semantic_term_matches_tokens(term, tokens)]
            if not matches:
                continue
            refs = item.get("refs") if isinstance(item.get("refs"), dict) else {}
            raw_ref = str(refs.get("raw") or "")
            support_item = {
                "role": str(role),
                "text": short_text(str(item.get("text") or ""), max_chars=700),
                "matched_query_terms": matches,
                "source_lane": item.get("source_lane"),
                "admission_basis": item.get("admission_basis"),
                "correlation_id": str(item.get("correlation_id") or ""),
                "event_type": item.get("event_type"),
                "outcome": item.get("outcome"),
                "timestamp": item.get("timestamp"),
                "line": item.get("line") or line_from_raw_ref(raw_ref),
                "refs": {
                    "raw": raw_ref,
                    "segment": str(refs.get("segment") or ""),
                    "segment_index": str(refs.get("segment_index") or ""),
                    "session": str(refs.get("session") or ""),
                },
            }
            reading_score, reading_signals = episode_semantic_support_reading_score(
                support_item,
                matched_term_count=len(matches),
                reading_intents=reading_intents,
                event_range=event_range,
            )
            support_item["reading_score"] = round(reading_score, 4)
            support_item["reading_signals"] = reading_signals
            support.append(support_item)
    support_rejections: list[dict[str, Any]] = []
    canonical_support_texts = {
        re.sub(r"\s+", " ", str(item.get("text") or "")).casefold().strip()
        for item in support
        if str(item.get("source_lane") or "") == "message_assistant"
        and str(item.get("text") or "").strip()
    }
    accepted_support: list[dict[str, Any]] = []
    for item in support:
        support_text_identity = re.sub(
            r"\s+",
            " ",
            str(item.get("text") or ""),
        ).casefold().strip()
        collision_reason = (
            "runtime_stream_copy_shadowed_by_canonical_response"
            if (
                str(item.get("source_lane") or "") == "event_msg_stream"
                and support_text_identity
                and support_text_identity in canonical_support_texts
            )
            else episode_semantic_support_collision_reason(
                item,
                reading_intents=reading_intents,
            )
        )
        if not collision_reason:
            accepted_support.append(item)
            continue
        refs = item.get("refs") if isinstance(item.get("refs"), dict) else {}
        support_rejections.append(
            {
                "reason": collision_reason,
                "line": int_value(item.get("line")),
                "matched_query_terms": list(item.get("matched_query_terms") or []),
                "source_lane": str(item.get("source_lane") or ""),
                "admission_basis": str(item.get("admission_basis") or ""),
                "refs": {
                    key: str(refs.get(key) or "")
                    for key in ("raw", "segment", "segment_index", "session")
                    if refs.get(key)
                },
            }
        )
    support = accepted_support
    coherent_support = max(
        support,
        key=lambda item: (
            len(set(item.get("matched_query_terms", []))),
            float(item.get("reading_score") or 0.0),
            EPISODE_SEMANTIC_FIELD_WEIGHTS.get(str(item.get("role") or ""), 0.0),
            -int_value(item.get("line")),
        ),
        default={},
    )
    coherent_terms = sorted(set(coherent_support.get("matched_query_terms", [])))
    coherent_term_count = len(coherent_terms)
    coherent_coverage = coherent_term_count / len(terms) if terms else 0.0
    coherent_support_summary = {
        "role": str(coherent_support.get("role") or ""),
        "line": int_value(coherent_support.get("line")),
        "matched_query_terms": coherent_terms,
        "source_lane": coherent_support.get("source_lane"),
        "admission_basis": coherent_support.get("admission_basis"),
        "refs": coherent_support.get("refs") if isinstance(coherent_support.get("refs"), dict) else {},
    } if coherent_support else {}
    support.sort(
        key=lambda item: (
            -float(item.get("reading_score") or 0.0),
            -len(item.get("matched_query_terms", [])),
            -EPISODE_SEMANTIC_FIELD_WEIGHTS.get(str(item.get("role") or ""), 0.0),
            int_value(item.get("line")),
        )
    )
    support_limit = 6
    per_role_limit = 2 if reading_intents.get("failure_recovery") else 3
    selected_support: list[dict[str, Any]] = []
    selected_raw_refs: set[str] = set()
    selected_role_counts: Counter[str] = Counter()
    for item in support:
        role = str(item.get("role") or "")
        raw_ref = str(((item.get("refs") or {}).get("raw")) or "")
        if raw_ref and raw_ref in selected_raw_refs:
            continue
        if selected_role_counts[role] >= per_role_limit:
            continue
        selected_support.append(item)
        selected_role_counts[role] += 1
        if raw_ref:
            selected_raw_refs.add(raw_ref)
        if len(selected_support) >= support_limit:
            break
    if len(selected_support) < support_limit and not reading_intents.get("failure_recovery"):
        for item in support:
            raw_ref = str(((item.get("refs") or {}).get("raw")) or "")
            if item in selected_support or (raw_ref and raw_ref in selected_raw_refs):
                continue
            selected_support.append(item)
            if raw_ref:
                selected_raw_refs.add(raw_ref)
            if len(selected_support) >= support_limit:
                break
    coverage = len(matched_terms) / len(terms) if terms else 0.0
    weighted_match = sum(best_weight_by_term.values())
    temporal_evidence = episode_temporal_span_evidence(episode, temporal_span or {})
    return {
        "coverage": coverage,
        "matched_term_count": len(matched_terms),
        "matched_query_terms": sorted(matched_terms),
        "matched_by_field": matched_by_field,
        "weighted_field_match": weighted_match,
        "coherent_term_count": coherent_term_count,
        "coherent_coverage": coherent_coverage,
        "coherent_support": coherent_support_summary,
        "reading_intents": reading_intents,
        "supporting_evidence": selected_support,
        "support_rejections": support_rejections,
        "temporal_span": temporal_evidence,
    }


def episode_semantic_rerank_score(
    evidence: dict[str, Any],
    *,
    bm25_rank: float = 0.0,
    operation_alignment: dict[str, Any] | None = None,
    asserted_mutation: dict[str, Any] | None = None,
    causal_attribution: dict[str, Any] | None = None,
    decision_followup: dict[str, Any] | None = None,
    failure_recovery: dict[str, Any] | None = None,
    issue_resolution: dict[str, Any] | None = None,
    replay_alignment: dict[str, Any],
    lineage_alignment: dict[str, Any] | None = None,
    source_kind_alignment: dict[str, Any] | None = None,
) -> tuple[float, float]:
    coherent_support_bonus = (
        float(evidence.get("coherent_term_count") or 0)
        * EPISODE_SEMANTIC_COHERENT_TERM_BONUS
    )
    score = round(
        float(evidence.get("coverage") or 0.0) * 100.0
        + float(evidence.get("weighted_field_match") or 0.0)
        + min(12.0, float(evidence.get("matched_term_count") or 0) * 2.0)
        + coherent_support_bonus
        + max(0.0, min(10.0, -float(bm25_rank or 0.0)))
        + float((evidence.get("temporal_span") or {}).get("ranking_boost") or 0.0)
        + float((operation_alignment or {}).get("ranking_boost") or 0.0)
        + float((asserted_mutation or {}).get("ranking_boost") or 0.0)
        + float((causal_attribution or {}).get("ranking_boost") or 0.0)
        + float((decision_followup or {}).get("ranking_boost") or 0.0)
        + float((failure_recovery or {}).get("ranking_boost") or 0.0)
        + float((issue_resolution or {}).get("ranking_boost") or 0.0)
        + float((replay_alignment or {}).get("ranking_boost") or 0.0)
        + float((lineage_alignment or {}).get("ranking_boost") or 0.0)
        + float((source_kind_alignment or {}).get("ranking_boost") or 0.0),
        4,
    )
    return score, coherent_support_bonus


def episode_query_operation_profile(terms: list[dict[str, Any]]) -> dict[str, bool]:
    tokens = {str(term.get("token") or "").casefold() for term in terms if isinstance(term, dict)}
    inspect = any(
        token.startswith(prefix)
        for token in tokens
        for prefix in ("инспект", "чит", "просмотр", "откры", "inspect", "read", "show")
    )
    schema = any(token.startswith(("схем", "schema")) for token in tokens)
    fields = bool(
        tokens
        & {
            "поле",
            "поля",
            "полей",
            "field",
            "fields",
            "properties",
            "property",
            "required",
            "keys",
        }
    )
    return {
        "inspect": inspect,
        "schema": schema,
        "fields": fields,
        "active": inspect or schema or fields,
    }


def episode_action_command_chains(text: str) -> list[str]:
    """Keep shell pipelines together while separating adjacent commands in one tool call."""
    normalized = str(text or "").replace("\\r\\n", "\n").replace("\\n", "\n")
    command_start = (
        r"(?:git(?:\s+-C\s+\S+)?\s+show|sed\s+-n|cat(?:\s|$)|head(?:\s|$)|"
        r"tail(?:\s|$)|jq(?:\s|$)|rg(?:\s|$)|find(?:\s|$))"
    )
    chains = [
        " ".join(part.split())
        for part in re.split(
            rf"(?:\r?\n|;|&&|\|\||(?<![|;&])\s+(?={command_start}))+",
            normalized,
            flags=re.IGNORECASE,
        )
        if part.strip()
    ]
    return chains or ([" ".join(normalized.split())] if normalized.strip() else [])


def episode_evidence_operation_alignment(
    evidence: dict[str, Any],
    terms: list[dict[str, Any]],
) -> dict[str, Any]:
    profile = episode_query_operation_profile(terms)
    if not profile.get("active"):
        return {
            "active": False,
            "profile": profile,
            "ranking_boost": 0.0,
            "aligned_refs": [],
            "policy": "inactive_without_explicit_operation_or_object_terms",
        }
    support = evidence.get("supporting_evidence") if isinstance(evidence.get("supporting_evidence"), list) else []
    aligned: list[dict[str, Any]] = []
    best_score = 0.0
    for item in support:
        if not isinstance(item, dict) or str(item.get("role") or "") != "actions":
            continue
        text = str(item.get("text") or "")
        event_type = str(item.get("event_type") or "")
        chains = episode_action_command_chains(text)
        best_chain: dict[str, Any] | None = None
        for chain_index, chain in enumerate(chains):
            folded = chain.casefold()
            explicit_inspect_command = bool(
                re.search(
                    r"(?<![a-z0-9_])(?:git(?:\s+-c\s+\S+)?\s+show|sed\s+-n|cat\s+|head\s+|tail\s+|jq\s+|rg\s+|find\s+)",
                    folded,
                )
            )
            inspect_evidence = explicit_inspect_command or bool(event_type == "FILE_READ" and len(chains) == 1)
            schema_evidence = bool(re.search(r"(?:schema(?:\.json)?|\.schema\.json|схем)", folded))
            projected_fields = bool(
                schema_evidence
                and re.search(r"(?<![a-z0-9_])jq\s+", folded)
                and re.search(r"(?:required|properties|keys|\.properties\.|select\s*\()", folded)
            )
            # An explicitly requested action and object are gates. Field detail remains
            # graded so a full-schema read can stay a weaker, still useful neighbor.
            if profile.get("inspect") and not inspect_evidence:
                continue
            if profile.get("schema") and not schema_evidence:
                continue
            score = 0.0
            signals: list[str] = []
            if profile.get("inspect") and inspect_evidence:
                score += 12.0
                signals.append("inspect_action")
            if profile.get("schema") and schema_evidence:
                score += 12.0
                signals.append("schema_object")
            if profile.get("fields") and projected_fields:
                score += 36.0
                signals.append("field_projection")
            elif profile.get("fields") and schema_evidence:
                score += 4.0
                signals.append("schema_without_explicit_field_projection")
            required_signal_count = sum(
                1
                for key in ("inspect", "schema", "fields")
                if profile.get(key)
            )
            positive_signal_count = sum(
                1
                for key, present in (
                    ("inspect", inspect_evidence),
                    ("schema", schema_evidence),
                    ("fields", projected_fields),
                )
                if profile.get(key) and present
            )
            if required_signal_count >= 2 and positive_signal_count == required_signal_count:
                score += 10.0
                signals.append("same_ref_operation_object_coherence")
            candidate = {
                "command_chain_index": chain_index,
                "score": round(score, 4),
                "signals": signals,
            }
            if best_chain is None or float(candidate["score"]) > float(best_chain["score"]):
                best_chain = candidate
        if not best_chain or float(best_chain.get("score") or 0.0) <= 0:
            continue
        refs = item.get("refs") if isinstance(item.get("refs"), dict) else {}
        aligned.append(
            {
                "line": int_value(item.get("line")),
                "raw_ref": str(refs.get("raw") or ""),
                "event_type": event_type,
                "command_chain_index": int_value(best_chain.get("command_chain_index")),
                "score": float(best_chain.get("score") or 0.0),
                "signals": list(best_chain.get("signals") or []),
            }
        )
        best_score = max(best_score, float(best_chain.get("score") or 0.0))
    aligned.sort(key=lambda item: (-float(item.get("score") or 0.0), int_value(item.get("line"))))
    return {
        "active": True,
        "profile": profile,
        "ranking_boost": round(best_score, 4),
        "aligned_refs": aligned[:5],
        "policy": "explicit query operation and object must cohere within one source-aware command chain",
    }


