EPISODE_ENTITY_RELATION_PRIORITY = {
    "invoked": 0,
    "modified": 1,
    "failed_with": 2,
    "verified_by": 3,
    "inspected": 4,
    "referenced_by_action": 5,
    "mentioned": 6,
}


EPISODE_ENTITY_TIME_SCOPED_RAW_OUTPUT_MAX_CHARS = 128 * 1024
EPISODE_ENTITY_TIME_SCOPED_RAW_OBSERVATION_LIMIT = 200
EPISODE_ENTITY_TIME_SCOPED_RAW_OBSERVATION_HARD_LIMIT = 1000


def episode_entity_exact_name_observed(
    text: Any,
    names: Iterable[str],
) -> bool:
    value = str(text or "")
    if not value:
        return False
    return any(
        re.search(
            rf"(?<![A-Za-z0-9_]){re.escape(name)}(?![A-Za-z0-9_])",
            value,
            flags=re.IGNORECASE,
        )
        for name in names
        if name
    )


def episode_entity_time_scoped_raw_state(
    *,
    session_dir: Path,
    manifest: dict[str, Any],
    identities: list[dict[str, str]],
    time_from: str,
    time_to: str,
    max_raw_bytes: int = ARCHIVED_SESSION_EXACT_SEARCH_DEFAULT_MAX_BYTES,
    max_lines: int = ARCHIVED_SESSION_EXACT_SEARCH_DEFAULT_MAX_LINES,
    max_observations: int = (
        EPISODE_ENTITY_TIME_SCOPED_RAW_OBSERVATION_LIMIT
    ),
) -> dict[str, Any]:
    """Prove a bounded MCP-tool invocation state from one archived raw source.

    Compact episode postings are intentionally selective and cannot prove that
    no call occurred before a cutoff.  A time-qualified current-state query
    therefore gets one session-scoped, digest-verified raw read.  Structured
    calls and receipts prove invocation; tool listings remain mention-only.
    """
    requested_route_keys = {
        str(identity.get("route_key") or "")
        for identity in identities
        if str(identity.get("route_key") or "")
    }
    effective_observation_limit = max(
        1,
        min(
            int_value(
                max_observations,
                EPISODE_ENTITY_TIME_SCOPED_RAW_OBSERVATION_LIMIT,
            ),
            EPISODE_ENTITY_TIME_SCOPED_RAW_OBSERVATION_HARD_LIMIT,
        ),
    )
    base = {
        "active": bool(time_from or time_to),
        "status": "not_requested",
        "applied": False,
        "mutates": False,
        "time_from": time_from,
        "time_to": time_to,
        "requested_route_keys": sorted(requested_route_keys),
        "invocation_observations": [],
        "mention_observations": [],
        "invocation_observed": False,
        "invocation_count": 0,
        "invocation_evidence_count": 0,
        "returned_invocation_evidence_count": 0,
        "omitted_invocation_evidence_count": 0,
        "invocation_observations_truncated": False,
        "receipt_count": 0,
        "mention_count": 0,
        "returned_mention_count": 0,
        "omitted_mention_count": 0,
        "mention_observations_truncated": False,
        "max_observations": effective_observation_limit,
        "absence_claim_allowed": False,
        "answer_state": "unresolved",
        "authority": "digest_verified_archived_raw_session",
    }
    if not base["active"]:
        return base
    if not requested_route_keys:
        return {
            **base,
            "status": "mcp_tool_identity_unresolved",
        }
    raw_path = manifest_raw_path(session_dir, manifest)
    raw_manifest = (
        manifest.get("raw")
        if isinstance(manifest.get("raw"), dict)
        else {}
    )
    expected_sha256 = str(raw_manifest.get("sha256") or "").strip().lower()
    if not raw_path or not raw_path.is_file():
        return {
            **base,
            "status": "archived_raw_source_missing",
            "raw_path": str(raw_path or ""),
        }
    try:
        stored_bytes = raw_path.stat().st_size
    except OSError as exc:
        return {
            **base,
            "status": "archived_raw_stat_failed",
            "raw_path": str(raw_path),
            "diagnostics": [str(exc)],
        }
    effective_max_bytes = max(
        1,
        min(
            int_value(
                max_raw_bytes,
                ARCHIVED_SESSION_EXACT_SEARCH_DEFAULT_MAX_BYTES,
            ),
            ARCHIVED_SESSION_EXACT_SEARCH_HARD_MAX_BYTES,
        ),
    )
    effective_max_lines = max(
        1,
        min(
            int_value(
                max_lines,
                ARCHIVED_SESSION_EXACT_SEARCH_DEFAULT_MAX_LINES,
            ),
            ARCHIVED_SESSION_EXACT_SEARCH_HARD_MAX_LINES,
        ),
    )
    if stored_bytes > effective_max_bytes:
        return {
            **base,
            "status": "archived_raw_over_bounded_state_limit",
            "raw_path": str(raw_path),
            "stored_bytes": stored_bytes,
            "max_raw_bytes": effective_max_bytes,
        }
    if not expected_sha256:
        return {
            **base,
            "status": "archived_raw_digest_missing",
            "raw_path": str(raw_path),
            "stored_bytes": stored_bytes,
        }
    try:
        actual_sha256 = sha256_file(raw_path).lower()
    except OSError as exc:
        return {
            **base,
            "status": "archived_raw_digest_read_failed",
            "raw_path": str(raw_path),
            "diagnostics": [str(exc)],
        }
    if actual_sha256 != expected_sha256:
        return {
            **base,
            "status": "archived_raw_digest_mismatch",
            "raw_path": str(raw_path),
            "expected_sha256": expected_sha256,
            "actual_sha256": actual_sha256,
        }

    requested_names: set[str] = set(requested_route_keys)
    for identity in identities:
        service_key = str(identity.get("service_key") or "")
        tool_key = str(identity.get("tool_key") or "")
        route_key = str(identity.get("route_key") or "")
        service_namespace = service_key.removesuffix("_mcp")
        if tool_key:
            requested_names.add(tool_key)
        if service_namespace and tool_key:
            requested_names.add(
                f"mcp__{service_namespace}__{tool_key}"
            )
        if route_key:
            requested_names.add(route_key)

    segments = [
        segment
        for segment in (
            manifest.get("segments")
            if isinstance(manifest.get("segments"), list)
            else []
        )
        if isinstance(segment, dict)
    ]
    manifest_path = session_dir / "session.manifest.json"
    observations: deque[dict[str, Any]] = deque(
        maxlen=effective_observation_limit
    )
    mentions: deque[dict[str, Any]] = deque(
        maxlen=effective_observation_limit
    )
    observation_keys: set[tuple[str, str, int, str]] = set()
    mention_keys: set[tuple[str, str, int, str]] = set()
    requested_invocation_correlation_ids: set[str] = set()
    invocation_count = 0
    receipt_count = 0
    invocation_evidence_count = 0
    mention_count = 0
    lines_scanned = 0
    decoded_bytes_scanned = 0
    invalid_json_count = 0
    invalid_timestamp_count = 0
    relevant_undated_event_count = 0
    line_budget_exhausted = False
    byte_budget_exhausted = False

    def in_requested_window(timestamp: str) -> bool:
        return bool(
            timestamp
            and (not time_from or timestamp >= time_from)
            and (not time_to or timestamp <= time_to)
        )

    def compact_observation(
        *,
        line_no: int,
        timestamp: str,
        payload: dict[str, Any],
        relation: str,
        evidence_role: str,
        source_lane: str,
        admission_basis: str,
        outcome: str,
        route_key: str,
    ) -> dict[str, Any]:
        segment = segment_for_line(segments, line_no)
        return {
            "session_id": str(manifest.get("session_id") or ""),
            "session_label": str(
                (
                    manifest.get("display")
                    if isinstance(manifest.get("display"), dict)
                    else {}
                ).get("label")
                or session_dir.name
            ),
            "episode_id": "",
            "evidence_role": evidence_role,
            "source_lane": source_lane,
            "admission_basis": admission_basis,
            "event_type": str(payload.get("type") or ""),
            "outcome": outcome,
            "route_layer": "tool",
            "route_key": route_key,
            "route_signal": route_signal_token("tool", route_key),
            "relation": relation,
            "event_timestamp": timestamp,
            "raw_line": line_no,
            "raw_ref": f"raw:line:{line_no}",
            "segment_ref": str(segment.get("markdown") or ""),
            "segment_index_ref": str(segment.get("index") or ""),
            "session_ref": str(manifest_path),
            "correlation_id": str(
                payload_correlation_id(payload) or ""
            ),
        }

    def record_observation(
        target: deque[dict[str, Any]],
        seen: set[tuple[str, str, int, str]],
        observation: dict[str, Any],
    ) -> bool:
        identity = (
            str(observation.get("route_signal") or ""),
            str(observation.get("relation") or ""),
            int_value(observation.get("raw_line")),
            str(observation.get("source_lane") or ""),
        )
        if identity in seen:
            return False
        seen.add(identity)
        target.append(observation)
        return True

    opener = gzip.open if raw_path.suffix == ".gz" else open
    try:
        with opener(
            raw_path,
            "rt",
            encoding="utf-8",
            errors="replace",
        ) as handle:
            for line_no, line in enumerate(handle, start=1):
                if lines_scanned >= effective_max_lines:
                    line_budget_exhausted = True
                    break
                line_bytes = len(line.encode("utf-8", errors="replace"))
                if decoded_bytes_scanned + line_bytes > effective_max_bytes:
                    byte_budget_exhausted = True
                    break
                lines_scanned += 1
                decoded_bytes_scanned += line_bytes
                try:
                    parsed = json.loads(line)
                except json.JSONDecodeError:
                    invalid_json_count += 1
                    continue
                if not isinstance(parsed, dict):
                    invalid_json_count += 1
                    continue
                payload = (
                    parsed.get("payload")
                    if isinstance(parsed.get("payload"), dict)
                    else {}
                )
                if not payload:
                    continue
                raw_timestamp = str(parsed.get("timestamp") or "")
                try:
                    timestamp = str(
                        parse_timestamp_arg(raw_timestamp) or ""
                    )
                except ValueError:
                    timestamp = ""
                    if raw_timestamp:
                        invalid_timestamp_count += 1
                invocation_identities = (
                    mcp_tool_invocation_identities_from_payload(payload)
                )
                invocation_route_keys = {
                    str(identity.get("route_key") or "")
                    for identity in invocation_identities
                    if str(identity.get("route_key") or "")
                    in requested_route_keys
                }
                receipt_identity = structured_mcp_result_identity(payload)
                receipt_route_key = str(
                    receipt_identity.get("route_key") or ""
                )
                receipt_matches = (
                    receipt_route_key in requested_route_keys
                )
                if invocation_route_keys or receipt_matches:
                    matched_correlation_id = str(
                        payload_correlation_id(payload) or ""
                    )
                    if matched_correlation_id:
                        requested_invocation_correlation_ids.add(
                            matched_correlation_id
                        )
                    if not timestamp:
                        relevant_undated_event_count += 1
                        continue
                    if not in_requested_window(timestamp):
                        continue
                    if invocation_route_keys:
                        for route_key in sorted(
                            invocation_route_keys
                        ):
                            if record_observation(
                                observations,
                                observation_keys,
                                compact_observation(
                                    line_no=line_no,
                                    timestamp=timestamp,
                                    payload=payload,
                                    relation="invoked",
                                    evidence_role="actions",
                                    source_lane=(
                                        "structured_mcp_tool_invocation"
                                    ),
                                    admission_basis=(
                                        "exact_namespaced_mcp_tool_call"
                                    ),
                                    outcome="requested",
                                    route_key=route_key,
                                ),
                            ):
                                invocation_count += 1
                                invocation_evidence_count += 1
                    if receipt_matches:
                        receipt_outcome = str(
                            structured_payload_outcome(payload)
                            or "observed"
                        )
                        if record_observation(
                            observations,
                            observation_keys,
                            compact_observation(
                                line_no=line_no,
                                timestamp=timestamp,
                                payload=payload,
                                relation=(
                                    "failed_with"
                                    if receipt_outcome == "failed"
                                    else "verified_by"
                                ),
                                evidence_role="outcomes",
                                source_lane="structured_mcp_receipt",
                                admission_basis=(
                                    "exact_namespaced_mcp_tool_receipt"
                                ),
                                outcome=receipt_outcome,
                                route_key=receipt_route_key,
                            ),
                        ):
                            receipt_count += 1
                            invocation_evidence_count += 1
                    continue
                if not in_requested_window(timestamp):
                    continue
                payload_type = str(payload.get("type") or "")
                if payload_type not in EPISODE_TEMPORAL_RAW_RESULT_TYPES:
                    continue
                output_text = text_from_content(
                    payload.get("output"),
                    max_chars=(
                        EPISODE_ENTITY_TIME_SCOPED_RAW_OUTPUT_MAX_CHARS
                    ),
                )
                if not episode_entity_exact_name_observed(
                    output_text,
                    requested_names,
                ):
                    continue
                output_correlation_id = str(
                    payload_correlation_id(payload) or ""
                )
                correlated_output_mirror = bool(
                    output_correlation_id
                    and output_correlation_id
                    in requested_invocation_correlation_ids
                )
                for route_key in sorted(requested_route_keys):
                    if record_observation(
                        mentions,
                        mention_keys,
                        compact_observation(
                            line_no=line_no,
                            timestamp=timestamp,
                            payload=payload,
                            relation="mentioned",
                            evidence_role="context",
                            source_lane=(
                                "correlated_mcp_tool_output_mirror"
                                if correlated_output_mirror
                                else "structured_tool_listing_output"
                            ),
                            admission_basis=(
                                "correlated_output_mirror_not_independent_invocation_evidence"
                                if correlated_output_mirror
                                else "exact_tool_name_in_result_body_not_invocation"
                            ),
                            outcome="observed",
                            route_key=route_key,
                        ),
                    ):
                        mention_count += 1
    except (OSError, EOFError) as exc:
        return {
            **base,
            "status": "archived_raw_read_failed",
            "raw_path": str(raw_path),
            "expected_sha256": expected_sha256,
            "actual_sha256": actual_sha256,
            "diagnostics": [str(exc)],
        }

    returned_observations = list(observations)
    returned_mentions = list(mentions)
    source_freshness = manifest_live_source_snapshot_freshness(
        manifest
    )
    scan_complete = bool(
        not line_budget_exhausted
        and not byte_budget_exhausted
        and invalid_json_count == 0
        and relevant_undated_event_count == 0
    )
    source_current = str(
        source_freshness.get("status") or ""
    ) == "current"
    absence_claim_allowed = bool(scan_complete and source_current)
    if invocation_evidence_count:
        status = "typed_invocation_observed"
        answer_state = "invoked_in_requested_time_scope"
    elif absence_claim_allowed:
        status = "bounded_no_invocation_observed"
        answer_state = "not_invoked_in_requested_time_scope"
    else:
        status = "time_scoped_invocation_state_unresolved"
        answer_state = "unresolved"
    return {
        **base,
        "status": status,
        "applied": True,
        "answer_state": answer_state,
        "absence_claim_allowed": absence_claim_allowed,
        "invocation_observations": returned_observations,
        "mention_observations": returned_mentions,
        "invocation_observed": bool(invocation_evidence_count),
        "invocation_count": invocation_count,
        "direct_invocation_event_count": invocation_count,
        "invocation_evidence_count": invocation_evidence_count,
        "returned_invocation_evidence_count": len(
            returned_observations
        ),
        "omitted_invocation_evidence_count": max(
            0,
            invocation_evidence_count - len(returned_observations),
        ),
        "invocation_observations_truncated": bool(
            invocation_evidence_count > len(returned_observations)
        ),
        "receipt_count": receipt_count,
        "mention_count": mention_count,
        "returned_mention_count": len(returned_mentions),
        "omitted_mention_count": max(
            0,
            mention_count - len(returned_mentions),
        ),
        "mention_observations_truncated": bool(
            mention_count > len(returned_mentions)
        ),
        "raw_path": str(raw_path),
        "stored_bytes": stored_bytes,
        "decoded_bytes_scanned": decoded_bytes_scanned,
        "lines_scanned": lines_scanned,
        "max_raw_bytes": effective_max_bytes,
        "max_lines": effective_max_lines,
        "scan_complete": scan_complete,
        "line_budget_exhausted": line_budget_exhausted,
        "byte_budget_exhausted": byte_budget_exhausted,
        "invalid_json_count": invalid_json_count,
        "invalid_timestamp_count": invalid_timestamp_count,
        "relevant_undated_event_count": (
            relevant_undated_event_count
        ),
        "source_integrity": {
            "status": "verified",
            "expected_sha256": expected_sha256,
            "actual_sha256": actual_sha256,
        },
        "source_freshness": source_freshness,
        "count_contract": {
            "invocation_count": (
                "direct structured MCP call events only"
            ),
            "receipt_count": (
                "structured MCP receipt events; a receipt proves an "
                "invocation occurred but is not added to invocation_count"
            ),
            "invocation_evidence_count": (
                "direct call events plus receipt events; evidence-event "
                "cardinality, not distinct call cardinality"
            ),
            "do_not_sum_invocation_and_receipt_counts": True,
        },
        "policy": (
            "structured namespaced MCP calls and receipts prove "
            "invocation; exact names inside result bodies remain "
            "mention-only, and correlation-owned output mirrors are "
            "distinguished from tool listings"
        ),
    }


def episode_entity_candidate_signals(
    anchor: str,
    kind: str,
    *,
    aoa_root: Path | None = None,
    session: str | None = None,
) -> list[str]:
    requested_kind = str(kind or "auto").strip().lower()
    normalized_kind = normalize_trace_route_kind(kind)
    signals: list[str] = []
    if aoa_root is not None and normalized_kind in {
        "auto",
        "tool",
        "mcp_tool",
    }:
        resolution = mcp_tool_route_resolution(
            aoa_root,
            anchor,
            session=session,
        )
        if resolution.get("status") == "resolved":
            signals.extend(
                str(candidate.get("route_signal") or "")
                for candidate in resolution.get("route_candidates", [])
                if isinstance(candidate, dict)
                and str(candidate.get("route_signal") or "")
            )
            if requested_kind == "mcp_tool":
                return unique_preserving_order(signals)[:32]
    if ":" in anchor:
        layer, key = anchor.split(":", 1)
        if layer and key:
            signals.append(route_signal_token(layer, key))
    for candidate in trace_route_lookup_candidates(
        trace_route_candidates(anchor, kind=normalized_kind),
        suppress_generic=True,
    ):
        route_signal = str(candidate.get("route_signal") or "")
        if route_signal and route_signal not in signals:
            signals.append(route_signal)
    if normalized_kind != "auto":
        key = canonical_skill_entity_key(anchor) if normalized_kind == "skill" else route_key_slug(anchor, fallback="entity", max_chars=80)
        route_signal = route_signal_token(normalized_kind, key)
        if key and route_signal not in signals:
            signals.append(route_signal)
    return unique_preserving_order(signals)[:32]


def episode_entity_state_search(
    *,
    aoa_root: Path,
    anchor: str,
    kind: str = "auto",
    session: str | None = None,
    time_from: str | None = None,
    time_to: str | None = None,
    limit: int = 20,
) -> dict[str, Any]:
    started = time.monotonic()
    now = utc_now()
    privacy_gate = derived_text_privacy_field_gate(anchor=anchor)
    if privacy_gate["blocked"]:
        return derived_text_privacy_blocked_navigation_result(
            artifact_type="episode_entity_state_results",
            fields=privacy_gate["fields"],
            metadata=privacy_gate["derived_text_privacy"],
        )
    requested_kind = route_key_slug(kind, fallback="auto")
    normalized_kind = normalize_trace_route_kind(kind)
    if normalized_kind not in TRACE_ROUTE_KINDS:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "episode_entity_state_results",
            "generated_at": now,
            "ok": False,
            "anchor": anchor,
            **trace_kind_payload_fields(kind, normalized_kind),
            "diagnostics": [f"unknown trace kind: {kind}"],
        }
    try:
        normalized_time_from = str(
            parse_timestamp_arg(time_from) or ""
        ) if time_from else ""
        normalized_time_to = str(
            parse_timestamp_arg(time_to) or ""
        ) if time_to else ""
    except ValueError as exc:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "episode_entity_state_results",
            "generated_at": now,
            "ok": False,
            "anchor": anchor,
            **trace_kind_payload_fields(kind, normalized_kind),
            "diagnostics": [str(exc)],
        }
    if (
        normalized_time_from
        and normalized_time_to
        and normalized_time_from > normalized_time_to
    ):
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "episode_entity_state_results",
            "generated_at": now,
            "ok": False,
            "anchor": anchor,
            **trace_kind_payload_fields(kind, normalized_kind),
            "diagnostics": ["invalid_time_scope_order"],
        }
    time_scope_requested = bool(
        normalized_time_from or normalized_time_to
    )
    mcp_tool_resolution = (
        mcp_tool_route_resolution(
            aoa_root,
            anchor,
            session=session,
        )
        if normalized_kind in {"auto", "tool", "mcp_tool"}
        else {}
    )
    if isinstance(mcp_tool_resolution, dict):
        mcp_tool_resolution.pop("_session_hits", None)
    mcp_raw_state_required = bool(
        requested_kind == "mcp_tool"
        or mcp_tool_resolution.get("status")
        in {"resolved", "ambiguous"}
    )
    candidate_signals = episode_entity_candidate_signals(
        anchor,
        kind,
        aoa_root=aoa_root,
        session=session,
    )
    if not candidate_signals:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "episode_entity_state_results",
            "generated_at": now,
            "ok": False,
            "anchor": anchor,
            **trace_kind_payload_fields(kind, normalized_kind),
            "candidate_route_signals": [],
            "diagnostics": ["no_specific_entity_route_signal"],
        }
    db_path = search_db_path(aoa_root)
    expected_episode_generation_id = str(
        session_memory_expected_generation_identities(aoa_root)[
            "episode_semantic"
        ]["generation_id"]
    )
    if not db_path.exists():
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "episode_entity_state_results",
            "generated_at": now,
            "ok": False,
            "anchor": anchor,
            "candidate_route_signals": candidate_signals,
            "diagnostics": ["search_index_missing"],
        }
    session_id = ""
    resolved_session_record: dict[str, Any] = {}
    if session:
        try:
            resolved_session_record = resolve_session_record(
                aoa_root,
                session,
            )
            session_id = str(
                resolved_session_record.get("session_id") or ""
            )
        except ValueError:
            if re.fullmatch(r"[0-9a-fA-F-]{36}", str(session)):
                session_id = str(session)
    placeholders = ",".join("?" for _ in candidate_signals)
    sql = (
        "SELECT episode_entity_postings.* FROM episode_entity_postings "
        "JOIN episode_semantic_meta "
        "ON episode_semantic_meta.doc_rowid = episode_entity_postings.doc_rowid "
        "JOIN episode_semantic_session_state AS episode_semantic_state "
        "ON episode_semantic_state.session_id = episode_entity_postings.session_id "
        f"WHERE episode_entity_postings.route_signal IN ({placeholders}) "
        "AND episode_semantic_meta.projection_version = ? "
        "AND episode_semantic_meta.generation_id = ? "
        "AND episode_semantic_state.projection_version = ? "
        "AND episode_semantic_state.route_signal_classifier_version = ? "
        "AND episode_semantic_state.generation_id = ? "
        "AND episode_semantic_state.status IN "
        "('current', 'no_task_episodes', 'no_admitted_episode_text')"
    )
    params: list[Any] = [
        *candidate_signals,
        EPISODE_SEMANTIC_PROJECTION_VERSION,
        expected_episode_generation_id,
        EPISODE_SEMANTIC_PROJECTION_VERSION,
        ROUTE_SIGNAL_CLASSIFIER_VERSION,
        expected_episode_generation_id,
    ]
    if session_id:
        sql += " AND episode_entity_postings.session_id = ?"
        params.append(session_id)
    if normalized_time_from:
        sql += (
            " AND julianday(episode_entity_postings.event_timestamp) "
            ">= julianday(?)"
        )
        params.append(normalized_time_from)
    if normalized_time_to:
        sql += (
            " AND julianday(episode_entity_postings.event_timestamp) "
            "<= julianday(?)"
        )
        params.append(normalized_time_to)
    requested_limit = max(1, min(200, int_value(limit, 20)))
    if time_scope_requested:
        sql += (
            " ORDER BY CASE episode_entity_postings.relation "
            "WHEN 'invoked' THEN 0 "
            "WHEN 'failed_with' THEN 1 "
            "WHEN 'verified_by' THEN 2 "
            "ELSE 3 END ASC, "
            "episode_entity_postings.event_timestamp DESC, "
            "episode_entity_postings.raw_line DESC LIMIT ?"
        )
    else:
        sql += (
            " ORDER BY episode_entity_postings.session_date DESC, "
            "episode_entity_postings.event_timestamp ASC, "
            "episode_entity_postings.raw_line ASC LIMIT ?"
        )
    params.append(requested_limit)
    conn: sqlite3.Connection | None = None
    query_diagnostics: list[str] = []
    try:
        conn = connect_existing_search_db(db_path)
        if not sqlite_table_exists(conn, "episode_entity_postings"):
            return {
                "schema_version": SCHEMA_VERSION,
                "artifact_type": "episode_entity_state_results",
                "generated_at": now,
                "ok": False,
                "anchor": anchor,
                "candidate_route_signals": candidate_signals,
                "diagnostics": ["episode_entity_postings_missing"],
            }
        episode_state_columns = {
            str(row[1])
            for row in conn.execute("PRAGMA table_info(episode_semantic_session_state)").fetchall()
        }
        episode_meta_columns = {
            str(row[1])
            for row in conn.execute(
                "PRAGMA table_info(episode_semantic_meta)"
            ).fetchall()
        }
        if (
            "route_signal_classifier_version" not in episode_state_columns
            or "generation_id" not in episode_state_columns
            or "generation_id" not in episode_meta_columns
        ):
            rows = []
            query_diagnostics.append(
                "episode_semantic_generation_identity_or_classifier_missing"
            )
        else:
            rows = conn.execute(sql, params).fetchall()
    except sqlite3.Error as exc:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "episode_entity_state_results",
            "generated_at": now,
            "ok": False,
            "anchor": anchor,
            "candidate_route_signals": candidate_signals,
            "diagnostics": [sqlite_error_diagnostic(exc)],
        }
    finally:
        if conn is not None:
            conn.close()
    results = [dict(row) for row in rows]
    projected_row_limit_reached = bool(
        len(rows) >= requested_limit
    )
    projection = episode_semantic_route_state(
        aoa_root,
        session=session,
    )
    time_scoped_raw_state: dict[str, Any] = {
        "active": time_scope_requested,
        "status": (
            "pending"
            if time_scope_requested
            else "not_requested"
        ),
        "applied": False,
        "time_from": normalized_time_from,
        "time_to": normalized_time_to,
        "answer_state": "unresolved",
        "absence_claim_allowed": False,
    }
    if time_scope_requested:
        if not session or not resolved_session_record:
            time_scoped_raw_state = {
                **time_scoped_raw_state,
                "status": (
                    "resolved_session_scope_required_for_raw_state"
                ),
            }
        elif not mcp_raw_state_required:
            time_scoped_raw_state = {
                **time_scoped_raw_state,
                "status": (
                    "generic_entity_raw_absence_route_not_available"
                ),
            }
        elif mcp_tool_resolution.get("status") != "resolved":
            time_scoped_raw_state = {
                **time_scoped_raw_state,
                "status": "mcp_tool_identity_unresolved",
                "mcp_tool_resolution": mcp_tool_resolution,
            }
        else:
            session_dir = session_dir_from_record(
                resolved_session_record
            )
            manifest = read_json(
                session_dir / "session.manifest.json",
                {},
            )
            if not isinstance(manifest, dict) or not manifest:
                time_scoped_raw_state = {
                    **time_scoped_raw_state,
                    "status": "session_manifest_missing",
                }
            else:
                time_scoped_raw_state = (
                    episode_entity_time_scoped_raw_state(
                        session_dir=session_dir,
                        manifest=manifest,
                        identities=[
                            identity
                            for identity in mcp_tool_resolution.get(
                                "identities",
                                [],
                            )
                            if isinstance(identity, dict)
                        ],
                        time_from=normalized_time_from,
                        time_to=normalized_time_to,
                        max_observations=max(
                            8,
                            min(200, requested_limit * 4),
                        ),
                    )
                )
                raw_observations = [
                    item
                    for item in [
                        *(
                            time_scoped_raw_state.get(
                                "invocation_observations",
                                [],
                            )
                            if isinstance(
                                time_scoped_raw_state.get(
                                    "invocation_observations"
                                ),
                                list,
                            )
                            else []
                        ),
                        *(
                            time_scoped_raw_state.get(
                                "mention_observations",
                                [],
                            )
                            if isinstance(
                                time_scoped_raw_state.get(
                                    "mention_observations"
                                ),
                                list,
                            )
                            else []
                        ),
                    ]
                    if isinstance(item, dict)
                ]
                existing_by_key = {
                    (
                        str(item.get("route_signal") or ""),
                        str(item.get("relation") or ""),
                        int_value(item.get("raw_line")),
                        str(item.get("raw_ref") or ""),
                    ): index
                    for index, item in enumerate(results)
                }
                for observation in raw_observations:
                    identity = (
                        str(observation.get("route_signal") or ""),
                        str(observation.get("relation") or ""),
                        int_value(observation.get("raw_line")),
                        str(observation.get("raw_ref") or ""),
                    )
                    existing_index = existing_by_key.get(identity)
                    if existing_index is not None:
                        results[existing_index] = {
                            **results[existing_index],
                            **observation,
                        }
                        continue
                    existing_by_key[identity] = len(results)
                    results.append(observation)
    candidate_result_count = len(results)
    result_truncated_by_limit = bool(
        candidate_result_count > requested_limit
    )
    accepted_candidate_count = 0
    context_candidate_count = 0
    omitted_context_result_count = 0
    if time_scope_requested:
        results.sort(
            key=lambda item: (
                str(item.get("event_timestamp") or ""),
                int_value(item.get("raw_line")),
                EPISODE_ENTITY_RELATION_PRIORITY.get(
                    str(item.get("relation") or ""),
                    99,
                ),
            )
        )
        accepted_results = [
            item
            for item in results
            if str(item.get("relation") or "")
            in {"invoked", "verified_by", "failed_with"}
        ]
        context_results = [
            item
            for item in results
            if str(item.get("relation") or "")
            not in {"invoked", "verified_by", "failed_with"}
        ]
        accepted_candidate_count = len(accepted_results)
        context_candidate_count = len(context_results)
        if result_truncated_by_limit:
            selected_results = accepted_results[-requested_limit:]
            remaining = requested_limit - len(selected_results)
            if remaining > 0:
                selected_results = [
                    *context_results[-remaining:],
                    *selected_results,
                ]
            omitted_context_result_count = max(
                0,
                context_candidate_count
                - sum(
                    1
                    for item in selected_results
                    if str(item.get("relation") or "")
                    not in {
                        "invoked",
                        "verified_by",
                        "failed_with",
                    }
                ),
            )
            results = sorted(
                selected_results,
                key=lambda item: (
                    str(item.get("event_timestamp") or ""),
                    int_value(item.get("raw_line")),
                    EPISODE_ENTITY_RELATION_PRIORITY.get(
                        str(item.get("relation") or ""),
                        99,
                    ),
                ),
            )
    else:
        results.sort(
            key=lambda item: (
                EPISODE_ENTITY_RELATION_PRIORITY.get(
                    str(item.get("relation") or ""),
                    99,
                ),
                -ymd_sort_value(item.get("session_date")),
                str(item.get("event_timestamp") or ""),
                int_value(item.get("raw_line")),
            )
        )
        results = results[:requested_limit]
    relation_counts = Counter(str(item.get("relation") or "unknown") for item in results)
    scoped_current = bool(session) and str(projection.get("status") or "") == "current"
    projected_identity_safe = bool(
        mcp_tool_resolution.get("status") != "ambiguous"
        and (
            requested_kind != "mcp_tool"
            or mcp_tool_resolution.get("status") == "resolved"
        )
    )
    projected_invocation_observed = bool(
        time_scope_requested
        and scoped_current
        and relation_counts.get("invoked")
        and projected_identity_safe
    )
    invocation_evidence_available = bool(
        time_scoped_raw_state.get("invocation_observed")
        or projected_invocation_observed
    )
    if (
        time_scope_requested
        and invocation_evidence_available
    ):
        entity_state = "invocation_observed_in_requested_time_scope"
    elif (
        time_scope_requested
        and time_scoped_raw_state.get("absence_claim_allowed")
        and time_scoped_raw_state.get("mention_count")
    ):
        entity_state = (
            "mention_only_without_observed_invocation_in_requested_time_scope"
        )
    elif (
        time_scope_requested
        and time_scoped_raw_state.get("absence_claim_allowed")
    ):
        entity_state = (
            "no_observed_entity_evidence_in_requested_time_scope"
        )
    elif time_scope_requested:
        entity_state = "time_scoped_entity_state_unresolved"
    elif relation_counts.get("invoked"):
        entity_state = "invocation_observed"
    elif relation_counts.get("modified"):
        entity_state = "modified_without_observed_invocation"
    elif relation_counts.get("inspected"):
        entity_state = "inspected_without_observed_invocation"
    elif relation_counts.get("referenced_by_action"):
        entity_state = "action_reference_without_observed_invocation"
    elif relation_counts.get("mentioned") or results:
        entity_state = "mention_only_without_observed_invocation"
    else:
        entity_state = "no_typed_entity_evidence"
    answer_admitted = bool(
        time_scope_requested
        and (
            invocation_evidence_available
            or time_scoped_raw_state.get("absence_claim_allowed")
        )
    )
    if time_scope_requested and answer_admitted:
        abstention_status = (
            "typed_time_scoped_invocation_evidence_available"
            if invocation_evidence_available
            else "bounded_absence_of_invocation_in_current_scope"
        )
    elif time_scope_requested:
        abstention_status = "time_scoped_entity_state_unresolved"
    elif session and not scoped_current:
        abstention_status = "insufficient_projection_coverage"
    elif results:
        abstention_status = "typed_entity_evidence_available"
    elif scoped_current:
        abstention_status = "no_observed_entity_evidence_in_current_scope"
    else:
        abstention_status = "insufficient_projection_coverage"
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "episode_entity_state_results",
        "generated_at": now,
        "ok": True,
        "mutates": False,
        "truth_status": (
            "digest_verified_archived_raw_time_scoped_entity_state"
            if time_scoped_raw_state.get("applied")
            else "current_time_filtered_typed_invocation_navigation_requires_raw_ref_resolution"
            if projected_invocation_observed
            else "generated_episode_entity_postings_are_navigation_not_raw_truth"
        ),
        "anchor": anchor,
        **trace_kind_payload_fields(kind, normalized_kind),
        "session": session or "",
        "time_from": normalized_time_from,
        "time_to": normalized_time_to,
        "candidate_route_signals": candidate_signals,
        "mcp_tool_resolution": mcp_tool_resolution,
        "entity_state": entity_state,
        "relation_counts": dict(sorted(relation_counts.items())),
        "result_count": len(results),
        "candidate_result_count": candidate_result_count,
        "results": results,
        "projection": projection,
        "time_scoped_raw_state": time_scoped_raw_state,
        "answer_admission": {
            "admitted": answer_admitted,
            "status": (
                "invoked_in_requested_time_scope"
                if invocation_evidence_available
                else "not_invoked_in_requested_time_scope"
                if time_scoped_raw_state.get(
                    "absence_claim_allowed"
                )
                else "unresolved"
                if time_scope_requested
                else "not_requested"
            ),
            "basis": (
                "exact_namespaced_mcp_invocation_or_receipt"
                if time_scoped_raw_state.get(
                    "invocation_observed"
                )
                else "current_time_filtered_typed_invocation_posting"
                if projected_invocation_observed
                else "complete_digest_verified_absence"
                if time_scoped_raw_state.get(
                    "absence_claim_allowed"
                )
                else "time_scoped_raw_state_not_complete"
                if time_scope_requested
                else "not_requested"
            ),
        },
        "abstention": {
            "status": abstention_status,
            "policy": (
                "a negative time-scoped invocation answer is bounded to "
                "one resolved session and requires a complete digest-verified "
                "raw scan current with its live source"
                if time_scope_requested
                else "absence means no observed typed evidence in the "
                "covered scope, never proof that an entity was never used"
            ),
        },
        "truncation": {
            "truncated": bool(
                result_truncated_by_limit
                or projected_row_limit_reached
                or time_scoped_raw_state.get(
                    "invocation_observations_truncated"
                )
                or time_scoped_raw_state.get(
                    "mention_observations_truncated"
                )
            ),
            "result_limit": requested_limit,
            "result_limit_reached": bool(
                len(results) >= requested_limit
            ),
            "candidate_result_count": candidate_result_count,
            "accepted_candidate_count": accepted_candidate_count,
            "context_candidate_count": context_candidate_count,
            "omitted_context_result_count": (
                omitted_context_result_count
            ),
            "projected_row_limit_reached": (
                projected_row_limit_reached
            ),
            "raw_invocation_observations_truncated": bool(
                time_scoped_raw_state.get(
                    "invocation_observations_truncated"
                )
            ),
            "raw_mention_observations_truncated": bool(
                time_scoped_raw_state.get(
                    "mention_observations_truncated"
                )
            ),
            "omitted_raw_invocation_evidence_count": int_value(
                time_scoped_raw_state.get(
                    "omitted_invocation_evidence_count"
                )
            ),
            "omitted_raw_mention_count": int_value(
                time_scoped_raw_state.get("omitted_mention_count")
            ),
        },
        "reading_contract": {
            "accepted_claim_requires": "resolve raw_ref plus segment_ref/session_ref and preserve relation and scope qualifiers",
            "invocation_relations": ["invoked"],
            "outcome_relations": ["verified_by", "failed_with"],
            "non_invocation_relations": [
                "inspected",
                "referenced_by_action",
                "mentioned",
                "verified_by",
                "failed_with",
            ],
            "time_scoped_absence_requires": (
                "complete digest-verified raw scan plus current live-source "
                "watermark"
            ),
        },
        "cost_profile": {
            "source": (
                "compact_episode_entity_postings_plus_digest_verified_raw"
                if time_scoped_raw_state.get("applied")
                else "compact_episode_entity_postings"
            ),
            "monolith_scanned": False,
            "row_limit": requested_limit,
            "raw_bytes_scanned": int_value(
                time_scoped_raw_state.get("decoded_bytes_scanned")
            ),
            "raw_lines_scanned": int_value(
                time_scoped_raw_state.get("lines_scanned")
            ),
        },
        "elapsed_ms": int((time.monotonic() - started) * 1000),
        "diagnostics": query_diagnostics,
    }


def exact_literal_postings_query_eligible(query: str) -> bool:
    text = str(query or "").strip()
    tokens = search_tokenize(text)
    if not text or not tokens or len(tokens) > 16:
        return False
    return bool(
        (2 <= len(tokens) <= 12 and len(text) <= 240)
        or
        re.search(r"[/\\_.:=+-]", text)
        or re.search(r"\b[0-9a-fA-F]{8,}\b", text)
        or re.search(r"\b\d+(?:\.\d+)+(?:[A-Za-z0-9-]+)?\b", text)
    )


def exact_literal_postings_state(
    conn: sqlite3.Connection,
    *,
    expected_generation_id: str = "",
) -> dict[str, Any]:
    if (
        not sqlite_table_exists(conn, "exact_literal_postings_fts")
        or not sqlite_table_exists(conn, "exact_literal_posting_meta")
        or not sqlite_table_exists(conn, "exact_literal_transition_postings_fts")
        or not sqlite_table_exists(conn, "exact_literal_transition_posting_meta")
        or not sqlite_table_exists(conn, "exact_literal_session_state")
    ):
        return {
            "status": "missing",
            "projection_version": SEARCH_EXACT_LITERAL_POSTINGS_VERSION,
            "covered_session_count": 0,
            "indexed_session_count": 0,
            "complete": False,
        }
    state_columns = {
        str(row[1])
        for row in conn.execute(
            "PRAGMA table_info(exact_literal_session_state)"
        ).fetchall()
    }
    meta_columns = {
        str(row[1])
        for row in conn.execute(
            "PRAGMA table_info(exact_literal_posting_meta)"
        ).fetchall()
    }
    transition_meta_columns = {
        str(row[1])
        for row in conn.execute(
            "PRAGMA table_info(exact_literal_transition_posting_meta)"
        ).fetchall()
    }
    generation_supported = bool(
        "generation_id" in state_columns
        and "generation_id" in meta_columns
        and "generation_id" in transition_meta_columns
    )
    generation_clause = (
        " AND generation_id = ?"
        if expected_generation_id and generation_supported
        else ""
    )
    generation_params: tuple[Any, ...] = (
        (expected_generation_id,)
        if generation_clause
        else ()
    )
    indexed_session_count = int_value(conn.execute("SELECT COUNT(*) FROM session_index_state").fetchone()[0])
    covered_session_count = int_value(
        conn.execute(
            "SELECT COUNT(*) FROM exact_literal_session_state "
            "WHERE projection_version = ?"
            + generation_clause,
            (
                SEARCH_EXACT_LITERAL_POSTINGS_VERSION,
                *generation_params,
            ),
        ).fetchone()[0]
    )
    status_rows = conn.execute(
        """
        SELECT status, COUNT(*) AS count
        FROM exact_literal_session_state
        WHERE projection_version = ?
        """
        + generation_clause
        +
        """
        GROUP BY status
        ORDER BY status
        """,
        (
            SEARCH_EXACT_LITERAL_POSTINGS_VERSION,
            *generation_params,
        ),
    ).fetchall()
    posting_document_count = int_value(
        conn.execute(
            "SELECT COUNT(*) FROM exact_literal_posting_meta"
            + (
                " WHERE generation_id = ?"
                if expected_generation_id and generation_supported
                else ""
            ),
            generation_params,
        ).fetchone()[0]
    )
    transition_posting_document_count = int_value(
        conn.execute(
            "SELECT COUNT(*) FROM exact_literal_transition_posting_meta"
            + (
                " WHERE generation_id = ?"
                if expected_generation_id and generation_supported
                else ""
            ),
            generation_params,
        ).fetchone()[0]
    )
    complete = bool(
        generation_supported
        and indexed_session_count > 0
        and covered_session_count >= indexed_session_count
    )
    return {
        "status": "current" if complete else ("partial" if covered_session_count else "empty"),
        "projection_version": SEARCH_EXACT_LITERAL_POSTINGS_VERSION,
        "covered_session_count": covered_session_count,
        "indexed_session_count": indexed_session_count,
        "complete": complete,
        "generation_supported": generation_supported,
        "expected_generation_id": expected_generation_id,
        "session_status_counts": {str(row["status"]): int_value(row["count"]) for row in status_rows},
        "posting_document_count": posting_document_count,
        "transition_posting_document_count": transition_posting_document_count,
        "storage_mode": "contentless_fts5_detail_full_plus_typed_patch_transition_postings",
        "source_scope": "structured correlation and provider identifiers plus source-aware event text, streamed structured patch calls with bounded same-field transitions, and compact successful observations; file-read and large raw outputs excluded",
        "transition_source_admission": "raw_structured_patch_call_marker_independent_of_derived_segment_event_type",
        "deduplication": (
            "adjacent_source_lane_mirror_collapse_preserves_distinct_"
            "within_session_and_cross_session_provenance"
        ),
        "authority_boundary": "postings route to event/raw refs; raw transcript remains authority",
    }


def session_scope_live_source_freshness(aoa_root: Path, session: str | None) -> dict[str, Any]:
    if not session:
        return {"status": "not_scoped", "checked": False}
    try:
        record = resolve_session_record(aoa_root, session)
    except ValueError as exc:
        return {"status": "unresolved", "checked": False, "diagnostics": [str(exc)]}
    session_dir = session_dir_from_record(record)
    manifest = read_json(session_dir / "session.manifest.json", {})
    if not isinstance(manifest, dict) or not manifest:
        return {
            "status": "unverifiable",
            "checked": False,
            "session_id": str(record.get("session_id") or ""),
            "session_label": str(record.get("session_label") or ""),
            "diagnostics": ["session_manifest_missing"],
        }
    raw = manifest.get("raw") if isinstance(manifest.get("raw"), dict) else {}
    source_fingerprint = str(raw.get("sha256") or "")
    return {
        **manifest_live_source_snapshot_freshness(manifest),
        "checked": True,
        "session_id": str(manifest.get("session_id") or record.get("session_id") or ""),
        "session_label": str(
            (manifest.get("display") if isinstance(manifest.get("display"), dict) else {}).get("label")
            or manifest.get("session_label")
            or record.get("session_label")
            or ""
        ),
        "source_fingerprint": source_fingerprint,
        "source_contributions": [
            {
                "session_id": str(
                    manifest.get("session_id")
                    or record.get("session_id")
                    or ""
                ),
                "source_fingerprint": source_fingerprint,
                "source_ref": str(session_dir / "session.manifest.json"),
                "basis": (
                    "archived_raw_sha256_declared_by_session_manifest"
                ),
            }
        ],
    }


def exact_literal_session_projection_freshness(
    record: dict[str, Any],
    *,
    exact_state: dict[str, Any],
    search_state: dict[str, Any],
    expected_exact_generation_id: str = "",
    expected_search_generation_id: str = "",
) -> dict[str, Any]:
    """Prove one exact-postings scope against its current generated sources."""
    started = time.monotonic()
    session_id = str(record.get("session_id") or exact_state.get("session_id") or "")
    session_label = str(
        record.get("session_label")
        or exact_state.get("session_label")
        or ""
    )
    base = {
        "session_id": session_id,
        "session_label": session_label,
        "expected_projection_version": SEARCH_EXACT_LITERAL_POSTINGS_VERSION,
        "expected_search_schema_version": SEARCH_SCHEMA_VERSION,
        "expected_route_signal_classifier_version": (
            ROUTE_SIGNAL_CLASSIFIER_VERSION
        ),
        "expected_projection_fingerprint_mode": (
            SEARCH_PROJECTION_FINGERPRINT_MODE
        ),
        "expected_exact_generation_id": expected_exact_generation_id,
        "expected_search_generation_id": expected_search_generation_id,
        "mutates": False,
    }
    if not exact_state:
        return {
            **base,
            "status": "uncovered",
            "scope_status": "scope_uncovered",
            "scope_current": False,
            "reasons": ["exact_literal_session_state_missing"],
            "fingerprint_check_performed": False,
            "elapsed_ms": int((time.monotonic() - started) * 1000),
        }
    exact_status = str(exact_state.get("status") or "")
    exact_projection_version = int_value(exact_state.get("projection_version"))
    if (
        exact_status != "current"
        or exact_projection_version != SEARCH_EXACT_LITERAL_POSTINGS_VERSION
    ):
        reasons: list[str] = []
        if exact_status != "current":
            reasons.append("exact_literal_session_state_not_current")
        if exact_projection_version != SEARCH_EXACT_LITERAL_POSTINGS_VERSION:
            reasons.append("exact_literal_projection_version_changed")
        return {
            **base,
            "status": "uncovered",
            "scope_status": "scope_uncovered",
            "scope_current": False,
            "reasons": reasons,
            "exact_state": {
                "status": exact_status,
                "projection_version": exact_projection_version,
                "indexed_at": str(exact_state.get("indexed_at") or ""),
            },
            "fingerprint_check_performed": False,
            "elapsed_ms": int((time.monotonic() - started) * 1000),
        }
    if not search_state:
        return {
            **base,
            "status": "unverifiable",
            "scope_status": "scope_unverifiable",
            "scope_current": False,
            "reasons": ["search_session_state_missing"],
            "exact_state": {
                "status": exact_status,
                "projection_version": exact_projection_version,
                "indexed_at": str(exact_state.get("indexed_at") or ""),
            },
            "fingerprint_check_performed": False,
            "elapsed_ms": int((time.monotonic() - started) * 1000),
        }

    exact_fingerprint = str(exact_state.get("source_fingerprint") or "")
    indexed_fingerprint = str(search_state.get("source_fingerprint") or "")
    indexed_mtime = float(search_state.get("source_latest_mtime") or 0.0)
    activity = session_projection_activity_state(
        record,
        include_rendered_markdown=False,
    )
    current_mtime = float(activity.get("latest_source_mtime") or 0.0)
    reasons = []
    if str(search_state.get("search_schema_version") or "") != str(
        SEARCH_SCHEMA_VERSION
    ):
        reasons.append("search_schema_version_changed")
    if (
        int_value(search_state.get("route_signal_classifier_version"))
        != ROUTE_SIGNAL_CLASSIFIER_VERSION
    ):
        reasons.append("route_signal_classifier_version_changed")
    if (
        str(search_state.get("projection_fingerprint_mode") or "")
        != SEARCH_PROJECTION_FINGERPRINT_MODE
    ):
        reasons.append("projection_fingerprint_mode_changed")
    if (
        expected_exact_generation_id
        and str(exact_state.get("generation_id") or "")
        != expected_exact_generation_id
    ):
        reasons.append("exact_literal_generation_identity_changed")
    if (
        expected_search_generation_id
        and str(search_state.get("generation_id") or "")
        != expected_search_generation_id
    ):
        reasons.append("search_generation_identity_changed")
    if not exact_fingerprint or not indexed_fingerprint:
        reasons.append("stored_source_fingerprint_missing")
    elif exact_fingerprint != indexed_fingerprint:
        reasons.append("exact_and_search_source_fingerprint_mismatch")
    if indexed_mtime <= 0 or current_mtime <= 0:
        reasons.append("source_latest_mtime_unverifiable")
    elif abs(current_mtime - indexed_mtime) > 0.001:
        reasons.append("source_latest_mtime_changed")

    current_projection: dict[str, Any] = {}
    fingerprint_check_performed = False
    if not reasons:
        try:
            current_projection = session_projection_fingerprint(
                record,
                include_rendered_markdown=False,
            )
            fingerprint_check_performed = True
        except OSError as exc:
            reasons.append(
                f"current_source_fingerprint_failed:{exc.__class__.__name__}"
            )
        if current_projection:
            post_activity = session_projection_activity_state(
                record,
                include_rendered_markdown=False,
            )
            projection_mtime = float(
                current_projection.get("latest_source_mtime") or 0.0
            )
            post_mtime = float(post_activity.get("latest_source_mtime") or 0.0)
            if (
                projection_mtime <= 0
                or post_mtime <= 0
                or abs(projection_mtime - post_mtime) > 0.001
            ):
                reasons.append("source_changed_during_fingerprint_check")
            current_fingerprint = str(
                current_projection.get("fingerprint") or ""
            )
            if not current_fingerprint:
                reasons.append("current_source_fingerprint_missing")
            elif current_fingerprint != indexed_fingerprint:
                reasons.append("current_source_fingerprint_changed")

    scope_current = not reasons
    return {
        **base,
        "status": "current" if scope_current else "stale-readable",
        "scope_status": (
            "scope_current" if scope_current else "scope_stale_readable"
        ),
        "scope_current": scope_current,
        "reasons": reasons,
        "exact_state": {
            "status": exact_status,
            "projection_version": exact_projection_version,
            "indexed_at": str(exact_state.get("indexed_at") or ""),
            "source_fingerprint": exact_fingerprint,
            "generation_id": str(exact_state.get("generation_id") or ""),
        },
        "search_state": {
            "indexed_at": str(search_state.get("indexed_at") or ""),
            "source_fingerprint": indexed_fingerprint,
            "source_latest_mtime": indexed_mtime,
            "search_schema_version": str(
                search_state.get("search_schema_version") or ""
            ),
            "route_signal_classifier_version": int_value(
                search_state.get("route_signal_classifier_version")
            ),
            "projection_fingerprint_mode": str(
                search_state.get("projection_fingerprint_mode") or ""
            ),
            "generation_id": str(search_state.get("generation_id") or ""),
        },
        "current_source": {
            "fingerprint": str(current_projection.get("fingerprint") or ""),
            "latest_source_mtime": current_mtime,
            "source_path_count": int_value(activity.get("source_path_count")),
        },
        "fingerprint_check_performed": fingerprint_check_performed,
        "truth_status": (
            "current_generated_source_fingerprint_matches_exact_and_search_state"
            if scope_current
            else "generated_source_state_changed_after_exact_projection"
        ),
        "elapsed_ms": int((time.monotonic() - started) * 1000),
    }


def exact_literal_postings_route_state(aoa_root: Path, *, session: str | None = None) -> dict[str, Any]:
    db_path = search_db_path(aoa_root)
    if not db_path.exists():
        return {
            "status": "missing",
            "projection_version": SEARCH_EXACT_LITERAL_POSTINGS_VERSION,
            "route_available": False,
            "scope_status": "search_index_missing",
            "db_path": str(db_path),
        }
    conn: sqlite3.Connection | None = None
    try:
        conn = connect_existing_search_db(db_path)
        expected_generations = session_memory_expected_generation_identities(
            aoa_root
        )
        expected_exact_generation_id = str(
            expected_generations["exact_literal"]["generation_id"]
        )
        state = exact_literal_postings_state(
            conn,
            expected_generation_id=expected_exact_generation_id,
        )
        scope_status = "global_current" if state.get("complete") else str(state.get("status") or "unknown")
        scope_current = bool(state.get("complete"))
        scope_session_id = ""
        scope_session_label = ""
        scope_projection_freshness: dict[str, Any] = {
            "status": "not_scoped",
            "scope_status": scope_status,
            "scope_current": scope_current,
            "mutates": False,
        }
        if session:
            try:
                record = resolve_session_record(aoa_root, session)
            except ValueError:
                record = {}
            scope_session_id = str(record.get("session_id") or session)
            scope_session_label = str(record.get("session_label") or "")
            clauses = ["session_id = ?"]
            values: list[Any] = [scope_session_id]
            if scope_session_label:
                clauses.append("session_label = ?")
                values.append(scope_session_label)
            row = conn.execute(
                "SELECT session_id, session_label, source_fingerprint, status, "
                "projection_version, indexed_at, generation_id "
                "FROM exact_literal_session_state WHERE ("
                + " OR ".join(clauses)
                + ") ORDER BY indexed_at DESC LIMIT 1",
                values,
            ).fetchone()
            search_row = None
            if (
                record
                and sqlite_table_exists(conn, "session_index_state")
            ):
                columns = {
                    str(column[1])
                    for column in conn.execute(
                        "PRAGMA table_info(session_index_state)"
                    ).fetchall()
                }
                projection_mode_expr = (
                    "projection_fingerprint_mode"
                    if "projection_fingerprint_mode" in columns
                    else "'' AS projection_fingerprint_mode"
                )
                search_row = conn.execute(
                    "SELECT session_id, session_label, source_fingerprint, "
                    "source_latest_mtime, search_schema_version, "
                    "route_signal_classifier_version, indexed_at, "
                    + projection_mode_expr
                    + ", generation_id "
                    + " FROM session_index_state WHERE session_id = ? LIMIT 1",
                    (scope_session_id,),
                ).fetchone()
            if record:
                scope_projection_freshness = (
                    exact_literal_session_projection_freshness(
                        record,
                        exact_state=dict(row) if row else {},
                        search_state=dict(search_row) if search_row else {},
                        expected_exact_generation_id=(
                            expected_exact_generation_id
                        ),
                        expected_search_generation_id=str(
                            expected_generations["lexical_search"][
                                "generation_id"
                            ]
                        ),
                    )
                )
                scope_current = bool(
                    scope_projection_freshness.get("scope_current")
                )
                scope_status = str(
                    scope_projection_freshness.get("scope_status")
                    or "scope_unverifiable"
                )
            else:
                scope_current = False
                scope_status = "scope_unresolved"
                scope_projection_freshness = {
                    "status": "unresolved",
                    "scope_status": scope_status,
                    "scope_current": False,
                    "reasons": ["session_scope_unresolved"],
                    "mutates": False,
                }
        live_source_freshness = session_scope_live_source_freshness(aoa_root, session)
        if session and str(live_source_freshness.get("status") or "") in {"deferred", "stale"}:
            scope_current = False
            scope_status = (
                "scope_deferred_live"
                if live_source_freshness.get("status") == "deferred"
                else "scope_stale_readable"
            )
        return {
            **state,
            "route_available": str(state.get("status") or "") in {"partial", "current"},
            "scope_status": scope_status,
            "scope_current": scope_current,
            "scope_session_id": scope_session_id,
            "scope_session_label": scope_session_label,
            "scope_projection_freshness": scope_projection_freshness,
            "live_source_freshness": live_source_freshness,
            "db_path": str(db_path),
        }
    except sqlite3.Error as exc:
        return {
            "status": sqlite_error_status(exc),
            "projection_version": SEARCH_EXACT_LITERAL_POSTINGS_VERSION,
            "route_available": False,
            "scope_status": "unavailable",
            "db_path": str(db_path),
            "diagnostics": [sqlite_error_diagnostic(exc)],
        }
    finally:
        if conn is not None:
            conn.close()


def session_search_scope_freshness(
    live_source_freshness: dict[str, Any],
    exact_literal_scope: dict[str, Any],
) -> dict[str, Any]:
    """Keep live-source and generated-projection freshness as separate axes."""
    live = dict(live_source_freshness)
    if not exact_literal_scope:
        return live
    scope_status = str(exact_literal_scope.get("scope_status") or "")
    projection = (
        exact_literal_scope.get("scope_projection_freshness")
        if isinstance(
            exact_literal_scope.get("scope_projection_freshness"),
            dict,
        )
        else {}
    )
    payload = {
        **live,
        "exact_literal_projection": {
            "status": str(projection.get("status") or ""),
            "scope_status": scope_status,
            "scope_current": bool(
                exact_literal_scope.get("scope_current")
            ),
            "reasons": list(projection.get("reasons") or []),
            "truth_status": str(projection.get("truth_status") or ""),
            "fingerprint_check_performed": bool(
                projection.get("fingerprint_check_performed")
            ),
        },
    }
    if str(live.get("status") or "") in {"deferred", "stale"}:
        payload["basis"] = (
            "live_source_snapshot_plus_exact_projection_fingerprint"
        )
        return payload
    if scope_status == "scope_current":
        payload["basis"] = (
            "live_source_snapshot_plus_current_exact_projection_fingerprint"
        )
        return payload
    projection_reasons = list(projection.get("reasons") or [])
    if scope_status in {"scope_unverifiable", "scope_unresolved"}:
        status = "unresolved"
        readability = "unverified-projection"
    else:
        status = "stale"
        readability = "stale-readable"
    payload.update(
        {
            "status": status,
            "readability": readability,
            "reasons": sorted(
                set(
                    [
                        *list(live.get("reasons") or []),
                        *projection_reasons,
                        "exact_literal_session_projection_not_current",
                    ]
                )
            ),
            "basis": (
                "generated_exact_projection_source_fingerprint_check"
            ),
            "fallback_required": True,
        }
    )
    return payload


def normalized_search_fts_query_timeout_ms(query_timeout_ms: int | None) -> int:
    if query_timeout_ms is None:
        return SEARCH_FTS_QUERY_TIMEOUT_MS
    return max(0, int_value(query_timeout_ms, SEARCH_FTS_QUERY_TIMEOUT_MS))


def install_search_fts_query_deadline(
    conn: sqlite3.Connection,
    *,
    query_timeout_ms: int | None,
) -> tuple[int, float | None]:
    effective_timeout_ms = normalized_search_fts_query_timeout_ms(query_timeout_ms)
    if effective_timeout_ms <= 0:
        return 0, None
    deadline = time.monotonic() + (effective_timeout_ms / 1000.0)
    conn.set_progress_handler(
        lambda: 1 if time.monotonic() >= deadline else 0,
        SEARCH_FTS_QUERY_PROGRESS_OPCODES,
    )
    return effective_timeout_ms, deadline


def clear_search_fts_query_deadline(conn: sqlite3.Connection) -> None:
    try:
        conn.set_progress_handler(None, 0)
    except sqlite3.Error:
        pass


def search_fts_timeout_next_command(
    command: str,
    *,
    query: str,
    limit: int,
    query_timeout_ms: int,
    options: list[tuple[str, Any]] | None = None,
    expand_timeout: bool = True,
    use_shards: bool = False,
    max_shards: int = 24,
) -> str:
    next_timeout_ms = (
        max(query_timeout_ms * 4 if query_timeout_ms > 0 else SEARCH_FTS_QUERY_TIMEOUT_MS * 4, 30000)
        if expand_timeout
        else max(0, query_timeout_ms)
    )
    args = [
        "python3",
        "scripts/aoa_session_memory.py",
        command,
        "--query",
        str(query or ""),
        "--limit",
        str(max(1, int_value(limit, 20))),
        "--query-timeout-ms",
        str(next_timeout_ms),
    ]
    for flag, value in options or []:
        if value is None or value == "" or value is False:
            continue
        if isinstance(value, (list, tuple)):
            for item in value:
                if item is not None and item != "":
                    args.extend([flag, str(item)])
        elif value is True:
            args.append(flag)
        else:
            args.extend([flag, str(value)])
    if use_shards:
        args.extend(["--use-shards", "--max-shards", str(max(1, int_value(max_shards, 24)))])
    return shlex.join(args)


def search_fts_timeout_payload(
    *,
    aoa_root: Path,
    query: str,
    normalized_query: str,
    db_path: Path,
    provider: str,
    projection_mode: str,
    query_timeout_ms: int,
    elapsed_ms: int,
    command: str,
    limit: int,
    options: list[tuple[str, Any]],
    cost_profile: dict[str, Any],
    provider_config: dict[str, Any],
    exc: sqlite3.Error,
    timeout_scope: str = "fts",
) -> dict[str, Any]:
    structured_timeout = timeout_scope == "structured_filter"
    diagnostic = (
        f"search_structured_query_timeout:{query_timeout_ms}ms"
        if structured_timeout
        else f"search_fts_query_timeout:{query_timeout_ms}ms"
    )
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "search_results",
        "search_schema_version": SEARCH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": False,
        "truth_status": "generated_search_projection_timeout_no_source_truth",
        "query": query,
        "normalized_query": normalized_query,
        "db_path": str(db_path),
        "aoa_root": str(aoa_root),
        "result_count": 0,
        "results": [],
        "search_projection": {
            "mode": projection_mode,
            "db_path": str(db_path),
            "fallback_db_path": str(search_db_path(aoa_root)),
        },
        "cost_profile": {
            **cost_profile,
            "query_timeout_ms": query_timeout_ms,
            "bounded_query_timeout": True,
            "elapsed_ms": elapsed_ms,
        },
        "provider": {
            "selected": provider,
            "authoritative_result_provider": "portable_sqlite",
            "status": SEARCH_FTS_QUERY_TIMEOUT_STATUS,
            "authority_law": provider_config.get("authority_law"),
        },
        "bounded_timeout": {
            "status": SEARCH_FTS_QUERY_TIMEOUT_STATUS,
            "scope": timeout_scope,
            "query_timeout_ms": query_timeout_ms,
            "elapsed_ms": elapsed_ms,
            "next_route": (
                (
                    "Retry the same structured filters through bounded monthly shards; narrow the session, date, "
                    "route signal, or typed owner route if the shard path also times out."
                )
                if structured_timeout
                else (
                    "Prefer structured filters, shard-backed routes, or entity/agent-event/goal routes. "
                    "Raise --query-timeout-ms only for an explicit offline raw-text scan."
                )
            ),
            "next_expansion_command": search_fts_timeout_next_command(
                command,
                query=query,
                limit=limit,
                query_timeout_ms=query_timeout_ms,
                options=options,
                expand_timeout=not structured_timeout,
                use_shards=structured_timeout and projection_mode == SEARCH_ACTIVE_PROJECTION_MONOLITH,
            ),
        },
        "diagnostics": [diagnostic, sqlite_error_diagnostic(exc)],
    }


def recover_search_projection_failure_with_archived_raw_exact(
    failure_payload: dict[str, Any],
    *,
    aoa_root: Path,
    query: str,
    session: str | None,
    limit: int,
    event_id_before: str | None,
    doc_type: str | None,
    event_type: str | None,
    family: str | None,
    outcome: str | None,
    conversation_act: str | None,
    session_act: str | None,
    agent_event: str | None,
    usage_role: str | None,
    task_episode_id: str | None,
    route_layer: str | None,
    route_signal: str | None,
    archive_status: str | None,
    freshness_status: str | None,
    date_from: str | None,
    date_to: str | None,
    exclude_agent_event_stream_copies: bool,
    explain: bool,
    enabled: bool,
    failure_kind: str,
    failure_scope: str = "",
) -> dict[str, Any]:
    if failure_kind not in {"index_missing", "index_timeout"}:
        raise ValueError(f"unsupported search projection failure kind: {failure_kind}")
    exact_session_fallback_eligible = bool(
        session and exact_literal_postings_query_eligible(query)
    )
    if not enabled:
        fallback_command = (
            literal_query_archived_raw_command_line(
                aoa_root=aoa_root,
                query=query,
                session=str(session),
                date_from=date_from,
                date_to=date_to,
            )
            if exact_session_fallback_eligible
            else ""
        )
        failure_payload["archived_raw_fallback"] = {
            "status": "disabled",
            "attempted": False,
            "reason": (
                "caller disabled automatic archived raw fallback; the exact "
                "read remains available as an explicit non-mutating route"
            ),
            "eligible": exact_session_fallback_eligible,
            "mutates": False,
        }
        failure_payload.setdefault("cost_profile", {}).update(
            {
                "archived_raw_fallback_enabled": False,
                "archived_raw_fallback_attempted": False,
                "persistent_archived_raw_index_written": False,
            }
        )
        failure_payload["truth_status"] = (
            f"generated_search_{failure_kind}_automatic_raw_fallback_disabled"
        )
        if fallback_command:
            failure_payload["next_command"] = fallback_command
            failure_payload["next_route"] = {
                "route_id": "session_archived_raw_exact_read",
                "kind": "cli_command",
                "status": "ready",
                "reason": (
                    "the generated search projection is unavailable and the "
                    "caller disabled its automatic raw fallback"
                ),
                "command": fallback_command,
                "mutates": False,
            }
        else:
            failure_payload["next_route"] = {
                "route_id": "search_projection_rebuild_or_abstention",
                "kind": "maintenance_or_abstention",
                "status": "unresolved",
                "reason": (
                    "no session-scoped exact raw route can satisfy the current "
                    "query and filter shape"
                ),
                "command": "",
                "mutates": False,
            }
        return failure_payload
    if (
        (failure_kind == "index_timeout" and failure_scope != "fts")
        or not exact_session_fallback_eligible
    ):
        return failure_payload
    failure_suffix = (
        "after_index_timeout"
        if failure_kind == "index_timeout"
        else "after_index_missing"
    )
    failure_reason = (
        "the index timed out"
        if failure_kind == "index_timeout"
        else "the published index was unavailable"
    )
    blockers = search_live_tail_exact_filter_blockers(
        query=query,
        session=session,
        doc_type=doc_type,
        conversation_act=conversation_act,
        session_act=session_act,
        agent_event=agent_event,
        usage_role=usage_role,
        task_episode_id=task_episode_id,
        route_layer=route_layer,
        route_signal=route_signal,
    )
    if blockers:
        failure_payload["archived_raw_fallback"] = {
            "status": f"not_applicable_{failure_suffix}",
            "attempted": False,
            "blockers": blockers,
            "mutates": False,
        }
        failure_payload.setdefault("diagnostics", []).extend(
            f"session_scope_archived_raw_fallback_blocked:{item}" for item in blockers
        )
        return failure_payload
    raw_payload = archived_session_exact_search(
        aoa_root=aoa_root,
        session=str(session),
        query=query,
        limit=max(1, int_value(limit, 20)),
        event_id_before=event_id_before,
        event_type=event_type,
        family=family,
        outcome=outcome,
        date_from=date_from,
        date_to=date_to,
        exclude_agent_event_stream_copies=(
            exclude_agent_event_stream_copies
        ),
        explain=explain,
    )
    candidates = [
        item
        for item in (raw_payload.get("results") if isinstance(raw_payload.get("results"), list) else [])
        if isinstance(item, dict)
        and live_tail_exact_result_matches_search_filters(
            item,
            event_type=event_type,
            family=family,
            outcome=outcome,
            archive_status=archive_status,
            freshness_status=str(freshness_status or "") or None,
        )
    ]
    for item in candidates:
        item["retrieval_partition"] = "archived_raw_fallback"
        if explain:
            recovery_explain = {
                "status": "recovered_from_complete_verified_archived_raw",
                (
                    "timed_out_projection"
                    if failure_kind == "index_timeout"
                    else "failed_projection"
                ): failure_payload.get("search_projection") or {},
            }
            item.setdefault("explain", {})[
                f"{failure_kind}_recovery"
            ] = recovery_explain
    scan = raw_payload.get("scan") if isinstance(raw_payload.get("scan"), dict) else {}
    archive = raw_payload.get("archive") if isinstance(raw_payload.get("archive"), dict) else {}
    integrity = archive.get("integrity") if isinstance(archive.get("integrity"), dict) else {}
    complete_verified = bool(
        str(scan.get("status") or "") == "complete_verified"
        and integrity.get("status") == "verified"
    )
    if candidates and complete_verified:
        fallback_status = f"applied_verified_{failure_suffix}"
    elif complete_verified:
        fallback_status = f"no_match_complete_verified_{failure_suffix}"
    elif not raw_payload.get("ok"):
        fallback_status = f"failed_{failure_suffix}"
    else:
        fallback_status = f"truncated_or_unverifiable_{failure_suffix}"
    failure_payload["archived_raw_fallback"] = {
        "status": fallback_status,
        "attempted": True,
        "reason": (
            "complete digest-verified archived raw recovered the exact query after "
            f"{failure_reason}"
            if candidates and complete_verified
            else "complete digest-verified archived raw proved no exact match after "
            f"{failure_reason}"
            if complete_verified
            else (
                "bounded archived raw could not safely replace the "
                "unavailable index result"
            )
        ),
        "route": raw_payload.get("route") or {},
        "archive": archive,
        "scan": scan,
        "raw_occurrence_count": int_value(raw_payload.get("raw_occurrence_count")),
        "candidate_count": int_value(raw_payload.get("candidate_count")),
        "bounded_candidate_count": int_value(
            raw_payload.get("bounded_candidate_count")
        ),
        "ranked_candidate_count": int_value(
            raw_payload.get("ranked_candidate_count")
        ),
        "result_limit": int_value(raw_payload.get("result_limit")),
        "results_omitted": int_value(
            raw_payload.get("results_omitted")
        ),
        "candidate_heap_truncated": bool(
            raw_payload.get("candidate_heap_truncated")
        ),
        "result_truncated": bool(
            raw_payload.get("result_truncated")
        ),
        "truncated": bool(raw_payload.get("result_truncated")),
        "structured_filter": raw_payload.get("structured_filter") or {},
        "result_count": len(candidates),
        "abstention": raw_payload.get("abstention") or {},
        "cost_profile": raw_payload.get("cost_profile") or {},
        "diagnostics": list(raw_payload.get("diagnostics") or []),
        "mutates": False,
        "truth_status": raw_payload.get("truth_status") or "",
    }
    failure_payload.setdefault("cost_profile", {}).update(
        {
            "archived_raw_fallback_enabled": True,
            "archived_raw_fallback_attempted": True,
            "archived_raw_fallback_result_count": len(candidates),
            "persistent_archived_raw_index_written": False,
        }
    )
    failure_payload.setdefault("diagnostics", []).extend(
        str(item) for item in raw_payload.get("diagnostics", []) if item
    )
    if complete_verified:
        failure_payload["ok"] = True
        failure_payload["results"] = candidates
        failure_payload["result_count"] = len(candidates)
        if failure_kind == "index_timeout":
            failure_payload.setdefault("bounded_timeout", {})[
                "recovered_by"
            ] = "session_archived_raw_exact_fallback"
            failure_payload["bounded_timeout"][
                "recovery_status"
            ] = fallback_status
        else:
            failure_payload["search_projection_recovery"] = {
                "status": fallback_status,
                "recovered_by": "session_archived_raw_exact_fallback",
                "failed_projection": (
                    failure_payload.get("search_projection") or {}
                ),
                "mutates": False,
            }
        failure_payload.setdefault("diagnostics", []).append(
            f"search_{failure_kind}_recovered_by_archived_raw:"
            f"{len(candidates)}"
        )
        failure_payload["truth_status"] = (
            f"{failure_kind}_recovered_by_complete_verified_archived_raw"
        )
    return failure_payload


def search_json_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return derived_text_privacy_text(value)
    return derived_text_privacy_text(
        json.dumps(value, ensure_ascii=False, sort_keys=True)
    )


def search_doc_text(parts: list[Any], *, max_chars: int = 4000) -> str:
    text = " ".join(part.strip() for part in (search_json_text(part) for part in parts) if part.strip())
    text = re.sub(r"\s+", " ", text).strip()
    return redact_derived_text(text[:max_chars])


def search_raw_lexical_policy(
    max_raw_bytes: int | None = None,
    *,
    use_default_budget: bool = True,
) -> dict[str, Any]:
    requested_max_raw_bytes = max_raw_bytes
    source = "default" if use_default_budget else "unbounded_no_default"
    effective_max_raw_bytes: int | None
    if max_raw_bytes is None:
        effective_max_raw_bytes = SEARCH_RAW_LEXICAL_DEFAULT_MAX_BYTES if use_default_budget else None
    else:
        explicit = int_value(max_raw_bytes)
        if explicit < 0:
            effective_max_raw_bytes = None
            source = "explicit_unbounded"
        else:
            effective_max_raw_bytes = explicit
            source = "explicit"
    effective_max_raw_mb = (
        effective_max_raw_bytes / (1024 * 1024)
        if effective_max_raw_bytes is not None
        else None
    )
    return {
        "mode": SEARCH_RAW_LEXICAL_POLICY_MODE,
        "source": source,
        "requested_max_raw_bytes": requested_max_raw_bytes,
        "default_max_raw_bytes": SEARCH_RAW_LEXICAL_DEFAULT_MAX_BYTES,
        "default_max_raw_mb": SEARCH_RAW_LEXICAL_DEFAULT_MAX_MB,
        "effective_max_raw_bytes": effective_max_raw_bytes,
        "effective_max_raw_mb": effective_max_raw_mb,
        "unbounded": effective_max_raw_bytes is None,
        "skip_status": "skipped_raw_too_large",
        "quality_note": "Raw transcript remains authority; bounded lexical skips only remove heavy raw semantic text from generated FTS and keep refs for proof routes.",
    }


def search_raw_lexical_policy_from_metadata(metadata: dict[str, Any]) -> dict[str, Any]:
    if not metadata:
        return {
            "mode": "unknown",
            "source": "metadata_missing",
            "default_max_raw_bytes": SEARCH_RAW_LEXICAL_DEFAULT_MAX_BYTES,
            "default_max_raw_mb": SEARCH_RAW_LEXICAL_DEFAULT_MAX_MB,
            "effective_max_raw_bytes": None,
            "effective_max_raw_mb": None,
            "unbounded": None,
            "diagnostics": ["search_metadata_missing"],
        }
    raw_value = metadata.get("search_raw_lexical_max_bytes")
    source = str(metadata.get("search_raw_lexical_policy_source") or "metadata")
    diagnostics: list[str] = []
    effective_max_raw_bytes: int | None
    raw_text = "" if raw_value is None else str(raw_value)
    if raw_text in {"", "None", "unbounded"}:
        effective_max_raw_bytes = None
    else:
        try:
            effective_max_raw_bytes = int(raw_text)
        except (TypeError, ValueError):
            effective_max_raw_bytes = None
            diagnostics.append("search_raw_lexical_max_bytes_unreadable")
    effective_max_raw_mb = (
        effective_max_raw_bytes / (1024 * 1024)
        if effective_max_raw_bytes is not None
        else None
    )
    return {
        "mode": str(metadata.get("search_raw_lexical_policy_mode") or "unknown"),
        "source": source,
        "default_max_raw_bytes": int_value(metadata.get("search_raw_lexical_default_max_bytes"), SEARCH_RAW_LEXICAL_DEFAULT_MAX_BYTES),
        "default_max_raw_mb": SEARCH_RAW_LEXICAL_DEFAULT_MAX_MB,
        "effective_max_raw_bytes": effective_max_raw_bytes,
        "effective_max_raw_mb": effective_max_raw_mb,
        "unbounded": effective_max_raw_bytes is None,
        "skip_status": str(metadata.get("search_raw_lexical_skip_status") or "skipped_raw_too_large"),
        "diagnostics": diagnostics,
    }


def search_raw_lexical_policy_status(policy: dict[str, Any]) -> str:
    mode = str(policy.get("mode") or "")
    unbounded = policy.get("unbounded")
    if mode == SEARCH_RAW_LEXICAL_POLICY_MODE and unbounded is False:
        return "bounded_policy_recorded"
    if unbounded is True:
        return "unbounded_or_legacy_policy"
    return "policy_missing_or_unknown"


def packed_route_values(values: Iterable[str]) -> str:
    items = sorted({str(value) for value in values if str(value or "").strip()})
    return "|" + "|".join(items) + "|" if items else ""


def route_fields_from_counts(route_counts: dict[str, Any]) -> tuple[str, str]:
    layers: list[str] = []
    signals: list[str] = []
    for layer, keys in route_counts.items() if isinstance(route_counts, dict) else []:
        if not isinstance(keys, dict):
            continue
        layer_text = str(layer)
        layers.append(layer_text)
        for key, _count in sorted(keys.items(), key=lambda item: (-int_value(item[1]), str(item[0]))):
            signals.append(route_signal_token(layer_text, str(key)))
    return packed_route_values(layers), packed_route_values(signals)


def route_fields_from_signals(signals_value: Any) -> tuple[str, str]:
    layers: list[str] = []
    signals: list[str] = []
    for signal in signals_value if isinstance(signals_value, list) else []:
        if not isinstance(signal, dict):
            continue
        layer = str(signal.get("layer") or "")
        key = str(signal.get("key") or "")
        if layer:
            layers.append(layer)
        if layer and key:
            signals.append(route_signal_token(layer, key))
    return packed_route_values(layers), packed_route_values(signals)


def unpacked_route_values(value: Any) -> list[str]:
    seen: set[str] = set()
    items: list[str] = []
    for token in str(value or "").strip("|").split("|"):
        normalized = token.strip()
        if not normalized or normalized in seen:
            continue
        seen.add(normalized)
        items.append(normalized)
    return items


def aggregate_route_posting_limit(doc_type: str, layer: str) -> int | None:
    if doc_type not in SEARCH_AGGREGATE_ROUTE_POSTING_DOC_TYPES:
        return None
    return SEARCH_AGGREGATE_ROUTE_POSTING_LAYER_LIMITS.get(layer, SEARCH_AGGREGATE_ROUTE_POSTING_DEFAULT_LAYER_LIMIT)


def document_route_entries(route_layers: Any, route_signals: Any, *, doc_type: str = "") -> list[dict[str, str]]:
    entries: list[dict[str, str]] = []
    seen: set[tuple[str, str]] = set()
    per_layer_counts: Counter[str] = Counter()
    normalized_doc_type = str(doc_type or "")
    for signal in unpacked_route_values(route_signals):
        if ":" not in signal:
            continue
        layer, key = signal.split(":", 1)
        normalized_layer = route_key_slug(layer, fallback="")
        normalized_key = route_key_slug(key, fallback="")
        if not normalized_layer or not normalized_key:
            continue
        layer_limit = aggregate_route_posting_limit(normalized_doc_type, normalized_layer)
        if layer_limit is not None and per_layer_counts[normalized_layer] >= layer_limit:
            continue
        token = (normalized_layer, normalized_key)
        if token in seen:
            continue
        seen.add(token)
        per_layer_counts[normalized_layer] += 1
        entries.append(
            {
                "layer": normalized_layer,
                "key": normalized_key,
                "route_signal": route_signal_token(normalized_layer, normalized_key),
            }
        )
    if not entries:
        for layer in unpacked_route_values(route_layers):
            normalized_layer = route_key_slug(layer, fallback="")
            if not normalized_layer:
                continue
            token = (normalized_layer, "")
            if token in seen:
                continue
            seen.add(token)
            entries.append({"layer": normalized_layer, "key": "", "route_signal": f"{normalized_layer}:"})
    return entries


def normalize_search_context_tail_omission_policy(value: str | None) -> str:
    text = str(value or "").strip()
    if not text:
        return SEARCH_CONTEXT_TAIL_OMISSION_POLICY_AUTO
    return SEARCH_CONTEXT_TAIL_OMISSION_POLICY_CLI_VALUES.get(text, text)


def search_context_tail_omission_policy_cli_value(policy: str) -> str:
    normalized = normalize_search_context_tail_omission_policy(policy)
    for cli_value, internal_value in SEARCH_CONTEXT_TAIL_OMISSION_POLICY_CLI_VALUES.items():
        if internal_value == normalized:
            return cli_value
    return "keep-all"


def search_context_tail_omission_policy_from_metadata(metadata: dict[str, Any]) -> str:
    policy = normalize_search_context_tail_omission_policy(
        str(metadata.get("search_context_tail_omission_policy") or "")
    )
    if policy in {
        SEARCH_CONTEXT_TAIL_OMISSION_POLICY_KEEP_ALL,
        SEARCH_CONTEXT_TAIL_OMISSION_POLICY_ROUTE_REF_BACKED,
    }:
        return policy
    return ""


def search_context_tail_omission_policy_resolution(
    *,
    aoa_root: Path | None,
    requested_policy: str | None,
    structured_only: bool,
    shard_keys: Iterable[str] | None = None,
) -> dict[str, Any]:
    requested = normalize_search_context_tail_omission_policy(requested_policy)
    normalized_shards = sorted({str(item or "").strip() for item in (shard_keys or []) if str(item or "").strip()})
    if not structured_only:
        resolved = (
            SEARCH_CONTEXT_TAIL_OMISSION_POLICY_KEEP_ALL
            if requested == SEARCH_CONTEXT_TAIL_OMISSION_POLICY_AUTO
            else requested
        )
        return {
            "requested_policy": requested,
            "resolved_policy": resolved,
            "source": "full_text_shards_force_keep_all" if requested == SEARCH_CONTEXT_TAIL_OMISSION_POLICY_AUTO else "explicit",
            "structured_only": False,
            "shards_considered": normalized_shards,
            "shard_policies": [],
            "diagnostics": [],
        }
    if requested != SEARCH_CONTEXT_TAIL_OMISSION_POLICY_AUTO:
        return {
            "requested_policy": requested,
            "resolved_policy": requested,
            "source": "explicit",
            "structured_only": True,
            "shards_considered": normalized_shards,
            "shard_policies": [],
            "diagnostics": [],
        }
    shard_policies: list[dict[str, Any]] = []
    if aoa_root is not None:
        for shard_key in normalized_shards:
            db_path = search_shard_db_path(aoa_root, shard_key)
            policy = search_context_tail_omission_policy_from_metadata(search_db_metadata_at_path(db_path))
            if not policy:
                continue
            shard_policies.append(
                {
                    "shard": shard_key,
                    "db_path": str(db_path),
                    "policy": policy,
                }
            )
    policy_values = {str(item.get("policy") or "") for item in shard_policies}
    diagnostics: list[str] = []
    if SEARCH_CONTEXT_TAIL_OMISSION_POLICY_ROUTE_REF_BACKED in policy_values:
        resolved = SEARCH_CONTEXT_TAIL_OMISSION_POLICY_ROUTE_REF_BACKED
        source = "existing_shard_meta"
        if len(policy_values) > 1:
            source = "mixed_existing_shard_meta_route_ref_backed_preferred"
            diagnostics.append("context_tail_omission_policy_auto_mixed_existing_shard_meta")
    elif SEARCH_CONTEXT_TAIL_OMISSION_POLICY_KEEP_ALL in policy_values:
        resolved = SEARCH_CONTEXT_TAIL_OMISSION_POLICY_KEEP_ALL
        source = "existing_shard_meta"
    else:
        resolved = SEARCH_CONTEXT_TAIL_OMISSION_POLICY_KEEP_ALL
        source = "auto_default_keep_all_no_existing_shard_policy"
    return {
        "requested_policy": requested,
        "resolved_policy": resolved,
        "source": source,
        "structured_only": True,
        "shards_considered": normalized_shards,
        "shard_policies": shard_policies,
        "diagnostics": diagnostics,
        "truth_status": "generated_search_projection_policy_selection_not_archive_truth",
    }


def search_document_is_context_tail_candidate(doc: dict[str, Any]) -> bool:
    return (
        str(doc.get("doc_type") or "") == "event"
        and str(doc.get("usage_role") or "") == SEARCH_OPERATIONAL_EVENT_CONTEXT_ROLE
        and not str(doc.get("agent_event") or "").strip()
        and not str(doc.get("task_episode_id") or "").strip()
        and str(doc.get("event_type") or "") not in SEARCH_OPERATIONAL_EVENT_PROTECTED_CONTEXT_EVENT_TYPES
    )


def search_document_has_route_ref_backing(doc: dict[str, Any]) -> bool:
    return any(
        item.get("key")
        for item in document_route_entries(
            doc.get("route_layers"),
            doc.get("route_signals"),
            doc_type=str(doc.get("doc_type") or ""),
        )
    )


def omitted_context_tail_route_ref_rows_for_doc(doc: dict[str, Any]) -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    for entry in document_route_entries(
        doc.get("route_layers"),
        doc.get("route_signals"),
        doc_type=str(doc.get("doc_type") or ""),
    ):
        layer = str(entry.get("layer") or "")
        key = str(entry.get("key") or "")
        if not layer or not key:
            continue
        route_signal = str(entry.get("route_signal") or route_signal_token(layer, key))
        rows.append(
            {
                "doc_id": str(doc.get("id") or ""),
                "session_id": str(doc.get("session_id") or ""),
                "session_label": str(doc.get("session_label") or ""),
                "session_date": str(doc.get("session_date") or ""),
                "event_id": str(doc.get("event_id") or ""),
                "event_type": str(doc.get("event_type") or ""),
                "raw_ref": str(doc.get("raw_ref") or ""),
                "segment_ref": str(doc.get("segment_ref") or ""),
                "layer": layer,
                "key": key,
                "route_signal": route_signal,
            }
        )
    return rows


def insert_omitted_context_tail_route_refs(conn: sqlite3.Connection, rows: Iterable[dict[str, Any]]) -> int:
    normalized_rows = [
        {
            "doc_id": str(row.get("doc_id") or ""),
            "session_id": str(row.get("session_id") or ""),
            "session_label": str(row.get("session_label") or ""),
            "session_date": str(row.get("session_date") or ""),
            "event_id": str(row.get("event_id") or ""),
            "event_type": str(row.get("event_type") or ""),
            "raw_ref": str(row.get("raw_ref") or ""),
            "segment_ref": str(row.get("segment_ref") or ""),
            "layer": str(row.get("layer") or ""),
            "key": str(row.get("key") or ""),
            "route_signal": str(row.get("route_signal") or ""),
        }
        for row in rows
        if str(row.get("layer") or "") and str(row.get("key") or "")
    ]
    if not normalized_rows:
        return 0
    conn.executemany(
        """
        INSERT INTO omitted_context_tail_route_refs(
            doc_id, session_id, session_label, session_date, event_id,
            event_type, raw_ref, segment_ref, layer, key, route_signal
        ) VALUES (
            :doc_id, :session_id, :session_label, :session_date, :event_id,
            :event_type, :raw_ref, :segment_ref, :layer, :key, :route_signal
        )
        """,
        normalized_rows,
    )
    return len(normalized_rows)


def apply_search_context_tail_omission_policy(
    documents: list[dict[str, Any]],
    *,
    policy: str | None,
) -> tuple[list[dict[str, Any]], dict[str, Any], list[dict[str, str]]]:
    normalized_policy = normalize_search_context_tail_omission_policy(policy)
    if normalized_policy == SEARCH_CONTEXT_TAIL_OMISSION_POLICY_AUTO:
        normalized_policy = SEARCH_CONTEXT_TAIL_OMISSION_POLICY_KEEP_ALL
    counts: Counter[str] = Counter()
    kept: list[dict[str, Any]] = []
    omitted_route_ref_rows: list[dict[str, str]] = []
    omitted_examples: list[dict[str, Any]] = []
    for doc in documents:
        counts["input_document_count"] += 1
        if not search_document_is_context_tail_candidate(doc):
            counts["non_candidate_keep_count"] += 1
            kept.append(doc)
            continue
        counts["candidate_context_tail_count"] += 1
        if not search_document_has_route_ref_backing(doc):
            counts["unrouted_keep_candidate_count"] += 1
            kept.append(doc)
            continue
        counts["route_ref_backed_omission_candidate_count"] += 1
        if normalized_policy != SEARCH_CONTEXT_TAIL_OMISSION_POLICY_ROUTE_REF_BACKED:
            counts["route_ref_backed_keep_candidate_count"] += 1
            kept.append(doc)
            continue
        counts["omitted_document_count"] += 1
        doc_route_ref_rows = omitted_context_tail_route_ref_rows_for_doc(doc)
        omitted_route_ref_rows.extend(doc_route_ref_rows)
        counts["omitted_route_ref_row_count"] += len(doc_route_ref_rows)
        if len(omitted_examples) < 5:
            omitted_examples.append(
                {
                    "id": str(doc.get("id") or ""),
                    "event_id": str(doc.get("event_id") or ""),
                    "session_label": str(doc.get("session_label") or ""),
                    "event_type": str(doc.get("event_type") or ""),
                    "raw_ref": str(doc.get("raw_ref") or ""),
                    "segment_ref": str(doc.get("segment_ref") or ""),
                    "route_signals": unpacked_route_values(doc.get("route_signals"))[:8],
                }
            )
    counts["output_document_count"] = len(kept)
    return kept, {
        "schema_version": 1,
        "policy": normalized_policy,
        "policy_cli_value": search_context_tail_omission_policy_cli_value(normalized_policy),
        "applied": normalized_policy == SEARCH_CONTEXT_TAIL_OMISSION_POLICY_ROUTE_REF_BACKED,
        "counts": dict(sorted(counts.items())),
        "input_document_count": int_value(counts.get("input_document_count")),
        "output_document_count": int_value(counts.get("output_document_count")),
        "candidate_context_tail_count": int_value(counts.get("candidate_context_tail_count")),
        "route_ref_backed_omission_candidate_count": int_value(
            counts.get("route_ref_backed_omission_candidate_count")
        ),
        "unrouted_keep_candidate_count": int_value(counts.get("unrouted_keep_candidate_count")),
        "omitted_document_count": int_value(counts.get("omitted_document_count")),
        "omitted_route_ref_row_count": int_value(counts.get("omitted_route_ref_row_count")),
        "omitted_examples": omitted_examples,
        "protected_boundary": (
            "agent_event, task_episode, protected event types, and unrouted context-tail rows are kept"
        ),
        "authority_boundary": (
            "this omits only generated structured-shard rows; raw transcripts, segment indexes, and monolith "
            "raw-text fallback remain authority"
        ),
        "truth_status": "generated_search_projection_policy_not_archive_truth",
    }, omitted_route_ref_rows


def bounded_packed_route_values(value: Any, *, max_chars: int) -> str:
    text = str(value or "")
    if len(text) <= max_chars:
        return text
    tokens = unpacked_route_values(text)
    if not tokens:
        return bounded_storage_text(text, max_chars=max_chars)
    kept: list[str] = []
    for token in tokens:
        candidate = "|" + "|".join([*kept, token]) + "|"
        if len(candidate) > max_chars:
            break
        kept.append(token)
    if not kept:
        return bounded_storage_text(text, max_chars=max_chars)
    return "|" + "|".join(kept) + "|"


def search_document_storage_profile(*, store_raw_text: bool) -> dict[str, Any]:
    if store_raw_text:
        return {
            "name": SEARCH_DOCUMENT_STORAGE_PROFILE_FULL,
            "body_preview_chars": SEARCH_BODY_PREVIEW_CHARS,
            "route_layers_preview_chars": SEARCH_ROUTE_LAYERS_PREVIEW_CHARS,
            "route_signals_preview_chars": SEARCH_ROUTE_SIGNALS_PREVIEW_CHARS,
            "tags_preview_chars": SEARCH_TAGS_PREVIEW_CHARS,
            "tags_storage_policy": SEARCH_TAGS_STORAGE_POLICY_FULL,
            "ref_path_storage_policy": SEARCH_REF_PATH_STORAGE_POLICY_DERIVED,
            "store_raw_path": False,
            "store_segment_index_path": False,
        }
    return {
        "name": SEARCH_DOCUMENT_STORAGE_PROFILE_STRUCTURED_SHARD,
        "body_preview_chars": SEARCH_STRUCTURED_SHARD_BODY_PREVIEW_CHARS,
        "route_layers_preview_chars": SEARCH_STRUCTURED_SHARD_ROUTE_LAYERS_PREVIEW_CHARS,
        "route_signals_preview_chars": SEARCH_STRUCTURED_SHARD_ROUTE_SIGNALS_PREVIEW_CHARS,
        "tags_preview_chars": SEARCH_STRUCTURED_SHARD_TAGS_PREVIEW_CHARS,
        "tags_storage_policy": SEARCH_TAGS_STORAGE_POLICY_STRUCTURED_SHARD,
        "ref_path_storage_policy": SEARCH_REF_PATH_STORAGE_POLICY_DERIVED,
        "store_raw_path": False,
        "store_segment_index_path": False,
    }


def compact_search_tags_for_storage(value: Any, *, max_chars: int, policy: str) -> str:
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    if not text:
        return ""
    if policy in {SEARCH_TAGS_STORAGE_POLICY_DROP_ROUTE_SIGNAL_TOKENS, SEARCH_TAGS_STORAGE_POLICY_STRUCTURED_SHARD}:
        kept = [
            token
            for token in text.split()
            if not token.startswith("route_signal:") and not token.startswith("route_layer:")
        ]
        text = " ".join(kept).strip()
    if max_chars <= 0:
        return text
    return bounded_storage_text(text, max_chars=max_chars)


def route_term_id(conn: sqlite3.Connection, entry: dict[str, str]) -> int:
    layer = str(entry.get("layer") or "")
    key = str(entry.get("key") or "")
    route_signal = str(entry.get("route_signal") or route_signal_token(layer, key))
    cache = search_route_term_cache(conn)
    token = (layer, key)
    cached = cache.get(token)
    if cached is not None:
        return cached
    conn.execute(
        "INSERT OR IGNORE INTO route_terms(layer, key, route_signal) VALUES (?, ?, ?)",
        (layer, key, route_signal),
    )
    row = conn.execute("SELECT id FROM route_terms WHERE layer = ? AND key = ?", (layer, key)).fetchone()
    route_id = int(row[0]) if row else 0
    if route_id:
        cache[token] = route_id
    return route_id


def event_search_text_limit(event_type: str) -> int:
    if event_type in {"USER_INTENT", "ASSISTANT_PLAN", "ASSISTANT_MESSAGE", "DECISION", "ASSUMPTION", "CHECKPOINT", "FINAL_STATE", "PROCESS_LESSON", "OPEN_THREAD"}:
        return 1400
    if event_type in {"COMMAND", "FILE_READ", "FILE_WRITE", "DIFF", "TOOL_CALL"}:
        return 1000
    if event_type in {"COMMAND_OUTPUT", "TOOL_OUTPUT", "ERROR", "VERIFICATION"}:
        return 700
    return 500


def event_type_gets_raw_search_text(event_type: str, outcome: str) -> bool:
    if event_type in {
        "USER_INTENT",
        "ASSISTANT_PLAN",
        "ASSISTANT_MESSAGE",
        "DECISION",
        "ASSUMPTION",
        "CHECKPOINT",
        "FINAL_STATE",
        "PROCESS_LESSON",
        "OPEN_THREAD",
        "COMMAND",
        "FILE_READ",
        "FILE_WRITE",
        "DIFF",
        "TOOL_CALL",
        "ERROR",
        "VERIFICATION",
    }:
        return True
    return event_type in {"COMMAND_OUTPUT", "TOOL_OUTPUT"} and outcome == "failed"


def bounded_file_head_tail_equal(
    left: Path,
    right: Path,
    *,
    sample_bytes: int = 64 * 1024,
) -> bool:
    """Cheap evidence for append-only transcript equivalence after mtime-only drift."""
    try:
        left_stat = left.stat()
        right_stat = right.stat()
        if left_stat.st_size != right_stat.st_size:
            return False
        size = left_stat.st_size
        with left.open("rb") as left_handle, right.open("rb") as right_handle:
            if size <= sample_bytes * 2:
                return left_handle.read() == right_handle.read()
            if left_handle.read(sample_bytes) != right_handle.read(sample_bytes):
                return False
            left_handle.seek(-sample_bytes, os.SEEK_END)
            right_handle.seek(-sample_bytes, os.SEEK_END)
            return left_handle.read(sample_bytes) == right_handle.read(sample_bytes)
    except OSError:
        return False


def manifest_live_source_snapshot_freshness(
    manifest: dict[str, Any],
    *,
    quiet_seconds: float = GRAPH_HOT_LIVE_DEFER_SECONDS,
    now_ts: float | None = None,
) -> dict[str, Any]:
    raw = manifest.get("raw") if isinstance(manifest.get("raw"), dict) else {}
    source = manifest.get("source") if isinstance(manifest.get("source"), dict) else {}
    snapshot = raw.get("source_snapshot") if isinstance(raw.get("source_snapshot"), dict) else {}
    source_path_text = str(snapshot.get("path") or raw.get("source_path") or source.get("transcript_path") or "")
    if not source_path_text:
        return {"status": "unverifiable", "reasons": ["live_source_path_missing"], "source_path": ""}
    source_path = Path(source_path_text)
    if not source_path.exists() or not source_path.is_file():
        return {
            "status": "archive_only",
            "reasons": [],
            "source_path": source_path_text,
            "readability": "archived_raw_available",
        }
    try:
        source_stat = source_path.stat()
    except OSError:
        return {"status": "unverifiable", "reasons": ["live_source_stat_failed"], "source_path": source_path_text}
    expected_size = int_value(snapshot.get("size"), -1)
    expected_mtime_ns = int_value(snapshot.get("mtime_ns"), -1)
    reasons: list[str] = []
    if expected_size >= 0 and source_stat.st_size != expected_size:
        reasons.append("source_size_changed")
    if expected_mtime_ns >= 0 and source_stat.st_mtime_ns != expected_mtime_ns:
        reasons.append("source_mtime_changed")
    raw_path_text = str(raw.get("path") or "")
    raw_path = Path(raw_path_text).expanduser() if raw_path_text else None
    if (
        reasons == ["source_mtime_changed"]
        and raw_path is not None
        and raw_path.is_file()
        and bounded_file_head_tail_equal(source_path, raw_path)
    ):
        return {
            "status": "current",
            "reasons": [],
            "source_path": source_path_text,
            "source_size": source_stat.st_size,
            "source_mtime": source_stat.st_mtime,
            "source_mtime_ns": source_stat.st_mtime_ns,
            "snapshot_mtime_ns": expected_mtime_ns,
            "mtime_only_drift": True,
            "equivalence_basis": "same_size_plus_bounded_archive_head_tail",
        }
    if not reasons:
        return {
            "status": "current",
            "reasons": [],
            "source_path": source_path_text,
            "source_size": source_stat.st_size,
            "source_mtime": source_stat.st_mtime,
            "source_mtime_ns": source_stat.st_mtime_ns,
        }
    now_value = time.time() if now_ts is None else float(now_ts)
    age_seconds = max(0.0, now_value - source_stat.st_mtime)
    status = "deferred" if age_seconds < max(0.0, float(quiet_seconds)) else "stale"
    return {
        "status": status,
        "reasons": reasons,
        "source_path": source_path_text,
        "source_size": source_stat.st_size,
        "source_mtime": source_stat.st_mtime,
        "source_mtime_ns": source_stat.st_mtime_ns,
        "snapshot_size": expected_size if expected_size >= 0 else None,
        "snapshot_mtime_ns": expected_mtime_ns if expected_mtime_ns >= 0 else None,
        "age_seconds": age_seconds,
        "quiet_seconds": max(0.0, float(quiet_seconds)),
        "readability": "stale-readable",
    }


def sha256_file_prefix(
    path: Path,
    byte_count: int,
    *,
    budget_ms: int | None = None,
) -> dict[str, Any]:
    """Hash exactly one recorded prefix without reading the active tail past it."""
    started = time.monotonic()
    expected = max(0, int_value(byte_count))
    effective_budget_ms = max(1, int_value(budget_ms)) if budget_ms is not None else None
    remaining = expected
    digest = hashlib.sha256()
    observed = 0
    try:
        with path.open("rb") as handle:
            while remaining > 0:
                chunk = handle.read(min(LIVE_TAIL_SEARCH_PREFIX_CHUNK_BYTES, remaining))
                if not chunk:
                    break
                digest.update(chunk)
                observed += len(chunk)
                remaining -= len(chunk)
                elapsed_ms = int((time.monotonic() - started) * 1000)
                if (
                    remaining > 0
                    and effective_budget_ms is not None
                    and elapsed_ms >= effective_budget_ms
                ):
                    return {
                        "ok": False,
                        "status": "prefix_hash_budget_exhausted",
                        "expected_bytes": expected,
                        "observed_bytes": observed,
                        "sha256": "",
                        "elapsed_ms": elapsed_ms,
                        "budget_ms": effective_budget_ms,
                        "diagnostics": ["live_source_prefix_hash_budget_exhausted"],
                    }
    except OSError as exc:
        return {
            "ok": False,
            "status": "prefix_read_failed",
            "expected_bytes": expected,
            "observed_bytes": observed,
            "sha256": "",
            "elapsed_ms": int((time.monotonic() - started) * 1000),
            "budget_ms": effective_budget_ms,
            "diagnostics": [f"live_source_prefix_read_failed:{exc}"],
        }
    return {
        "ok": observed == expected,
        "status": "hashed" if observed == expected else "prefix_truncated_during_read",
        "expected_bytes": expected,
        "observed_bytes": observed,
        "sha256": digest.hexdigest() if observed == expected else "",
        "elapsed_ms": int((time.monotonic() - started) * 1000),
        "budget_ms": effective_budget_ms,
        "diagnostics": [] if observed == expected else ["live_source_prefix_short_read"],
    }


def live_tail_search_limits(
    *,
    max_delta_bytes: int | None = None,
    max_lines: int | None = None,
) -> tuple[int, int]:
    requested_bytes = int_value(max_delta_bytes, LIVE_TAIL_SEARCH_DEFAULT_MAX_DELTA_BYTES)
    requested_lines = int_value(max_lines, LIVE_TAIL_SEARCH_DEFAULT_MAX_LINES)
    return (
        max(1, min(requested_bytes, LIVE_TAIL_SEARCH_HARD_MAX_DELTA_BYTES)),
        max(1, min(requested_lines, LIVE_TAIL_SEARCH_HARD_MAX_LINES)),
    )


def persistent_live_tail_source_snapshot(
    *,
    session_dir: Path,
    source_path: Path,
    archived_bytes: int,
    archived_lines: int,
    expected_prefix_sha256: str,
    max_delta_bytes: int,
    base: dict[str, Any],
    started: float,
) -> dict[str, Any] | None:
    overlay = read_json(
        persistent_live_tail_index_path(session_dir),
        {},
    )
    if (
        not isinstance(overlay, dict)
        or int_value(overlay.get("schema_version"))
        != PERSISTENT_LIVE_TAIL_INDEX_SCHEMA_VERSION
        or overlay.get("artifact_type")
        != "persistent_live_tail_overlay"
        or str(overlay.get("source_path") or "")
        != str(source_path)
    ):
        return None
    materialization_path = Path(
        str(overlay.get("materialization_path") or "")
    )
    ledger_path = Path(str(overlay.get("ledger_path") or ""))
    if not ledger_path.is_file():
        ledger_path = raw_capture_ledger_path(session_dir)
    if not materialization_path.is_file():
        materialization_path = (
            session_dir
            / "raw"
            / RAW_CAPTURES_DIR
            / materialization_path.name
        )
    ledger = read_json(ledger_path, {})
    epochs = (
        ledger.get("epochs")
        if isinstance(ledger, dict)
        and isinstance(ledger.get("epochs"), list)
        else []
    )
    epoch = next(
        (
            item
            for item in reversed(epochs)
            if isinstance(item, dict)
            and str(item.get("epoch_id") or "")
            == str(overlay.get("epoch_id") or "")
        ),
        None,
    )
    if not isinstance(epoch, dict):
        return None
    captured_bytes = int_value(overlay.get("captured_bytes"), -1)
    if captured_bytes <= archived_bytes:
        return None
    try:
        source_stat = source_path.stat()
        materialized_stat = materialization_path.stat()
    except OSError:
        return None
    if not (
        source_stat.st_dev == int_value(overlay.get("source_device"), -1)
        and source_stat.st_ino == int_value(overlay.get("source_inode"), -1)
        and source_stat.st_size == captured_bytes
        and materialized_stat.st_size == captured_bytes
        and int_value(epoch.get("captured_bytes"), -1) == captured_bytes
        and str(epoch.get("chain_sha256") or "")
        == str(overlay.get("ledger_chain_sha256") or "")
        and captured_bytes >= archived_bytes
    ):
        return None
    prefix_record = (
        overlay.get("archive_prefixes", {}).get(str(archived_bytes))
        if isinstance(overlay.get("archive_prefixes"), dict)
        else None
    )
    if not (
        isinstance(prefix_record, dict)
        and prefix_record.get("matches") is True
        and str(prefix_record.get("sha256") or "")
        == expected_prefix_sha256
    ):
        return None
    blocks = (
        epoch.get("blocks")
        if isinstance(epoch.get("blocks"), list)
        else []
    )
    if blocks:
        last = blocks[-1] if isinstance(blocks[-1], dict) else {}
        last_path = Path(str(last.get("path") or ""))
        if not last_path.is_file():
            last_path = (
                session_dir
                / "raw"
                / RAW_CAPTURE_BLOCKS_DIR
                / last_path.name
            )
        if not (
            last_path.is_file()
            and last_path.stat().st_size
            == int_value(last.get("byte_count"), -1)
            and sha256_file(last_path) == str(last.get("sha256") or "")
        ):
            return None
    delta_bytes = captured_bytes - archived_bytes
    scan_end = min(captured_bytes, archived_bytes + max_delta_bytes)
    byte_truncated = scan_end < captured_bytes
    snapshot_id = hashlib.sha256(
        (
            f"{overlay.get('epoch_id')}:{overlay.get('ledger_chain_sha256')}:"
            f"{captured_bytes}"
        ).encode("utf-8")
    ).hexdigest()[:24]
    return {
        **base,
        "ok": True,
        "status": "truncated" if byte_truncated else "persistent_overlay",
        "fallback_reason": (
            "persistent_live_tail_overlay_covers_unarchived_delta"
        ),
        "live_source_path": str(materialization_path),
        "source_size": captured_bytes,
        "source_mtime_ns": materialized_stat.st_mtime_ns,
        "source_device": materialized_stat.st_dev,
        "source_inode": materialized_stat.st_ino,
        "owner_source_device": source_stat.st_dev,
        "owner_source_inode": source_stat.st_ino,
        "snapshot_id": snapshot_id,
        "snapshot_end_offset": captured_bytes,
        "scan_start_offset": archived_bytes,
        "scan_end_offset": scan_end,
        "delta_bytes": delta_bytes,
        "scan_bytes": scan_end - archived_bytes,
        "unscanned_bytes": max(0, captured_bytes - scan_end),
        "line_start": archived_lines + 1,
        "byte_truncated": byte_truncated,
        "persistent_overlay": True,
        "persistent_live_tail_index": str(
            persistent_live_tail_index_path(session_dir)
        ),
        "persistent_live_tail_postings": str(
            persistent_live_tail_postings_path(session_dir)
        ),
        "persistent_live_tail_postings_sha256": str(
            overlay.get("postings_manifest_sha256") or ""
        ),
        "persistent_live_tail_postings_bytes": int_value(
            overlay.get("postings_manifest_bytes")
        ),
        "ledger_epoch_id": overlay.get("epoch_id"),
        "ledger_chain_sha256": overlay.get(
            "ledger_chain_sha256"
        ),
        "prefix_validation": {
            "ok": True,
            "status": "persistent_capture_archive_prefix_attested",
            "expected_sha256": expected_prefix_sha256,
            "sha256": prefix_record.get("sha256"),
            "bytes_hashed": archived_bytes,
            "archive_boundary_line_aligned": True,
        },
        "authority": {
            "source": "persistent_captured_raw_overlay",
            "projection": "none_query_time_candidate",
            "archive_projection": "stale-readable",
            "segment_ref_available": False,
        },
        "diagnostics": (
            ["live_tail_byte_budget_truncated"]
            if byte_truncated
            else []
        ),
        "elapsed_ms": int((time.monotonic() - started) * 1000),
    }


def session_live_tail_source_snapshot(
    *,
    aoa_root: Path,
    session: str,
    max_delta_bytes: int | None = None,
    max_lines: int | None = None,
) -> dict[str, Any]:
    """Capture a bounded, read-only append snapshot for one resolved archived session."""
    started = time.monotonic()
    effective_max_bytes, effective_max_lines = live_tail_search_limits(
        max_delta_bytes=max_delta_bytes,
        max_lines=max_lines,
    )
    try:
        record = resolve_session_record(aoa_root, session)
    except ValueError as exc:
        return {
            "schema_version": LIVE_TAIL_SEARCH_SCHEMA_VERSION,
            "ok": False,
            "status": "unresolved",
            "mutates": False,
            "diagnostics": [f"live_tail_session_unresolved:{exc}"],
        }
    session_dir = session_dir_from_record(record)
    manifest_path = session_dir / "session.manifest.json"
    manifest = read_json(manifest_path, {})
    if not isinstance(manifest, dict) or not manifest:
        return {
            "schema_version": LIVE_TAIL_SEARCH_SCHEMA_VERSION,
            "ok": False,
            "status": "unresolved",
            "mutates": False,
            "session_id": str(record.get("session_id") or ""),
            "session_label": str(record.get("session_label") or ""),
            "manifest_path": str(manifest_path),
            "diagnostics": ["live_tail_session_manifest_missing"],
        }
    raw = manifest.get("raw") if isinstance(manifest.get("raw"), dict) else {}
    source = manifest.get("source") if isinstance(manifest.get("source"), dict) else {}
    source_snapshot = raw.get("source_snapshot") if isinstance(raw.get("source_snapshot"), dict) else {}
    archive_path_text = str(raw.get("path") or "")
    source_path_text = str(
        source_snapshot.get("path")
        or raw.get("source_path")
        or source.get("transcript_path")
        or ""
    )
    archived_bytes = int_value(source_snapshot.get("size"), int_value(raw.get("bytes"), -1))
    archived_lines = int_value(raw.get("line_count"), int_value(manifest.get("latest_event_count"), 0))
    expected_prefix_sha256 = str(raw.get("sha256") or "")
    archive_path = Path(archive_path_text).expanduser() if archive_path_text else Path()
    source_path = Path(source_path_text).expanduser() if source_path_text else Path()
    base = {
        "schema_version": LIVE_TAIL_SEARCH_SCHEMA_VERSION,
        "artifact_type": "session_live_tail_source_snapshot",
        "mutates": False,
        "read_mode": "read_only_snapshot",
        "session_id": str(manifest.get("session_id") or record.get("session_id") or ""),
        "session_label": str(manifest.get("session_label") or record.get("session_label") or session_dir.name),
        "session_title": str(manifest.get("session_title") or record.get("session_title") or ""),
        "session_date": session_record_date(record),
        "session_dir": str(session_dir),
        "manifest_path": str(manifest_path),
        "archive_raw_path": archive_path_text,
        "live_source_path": source_path_text,
        "archived_bytes": archived_bytes,
        "archived_line_count": archived_lines,
        "max_delta_bytes": effective_max_bytes,
        "max_lines": effective_max_lines,
        "scan_budget_ms": LIVE_TAIL_SEARCH_SCAN_BUDGET_MS,
        "projection_freshness": manifest_live_source_snapshot_freshness(manifest),
    }
    persistent_snapshot = persistent_live_tail_source_snapshot(
        session_dir=session_dir,
        source_path=source_path,
        archived_bytes=archived_bytes,
        archived_lines=archived_lines,
        expected_prefix_sha256=expected_prefix_sha256,
        max_delta_bytes=effective_max_bytes,
        base=base,
        started=started,
    )
    if persistent_snapshot is not None:
        return persistent_snapshot
    diagnostics: list[str] = []
    if not source_path_text or not source_path.is_file():
        return {
            **base,
            "ok": False,
            "status": "unresolved",
            "diagnostics": ["live_tail_source_unavailable"],
        }
    if not archive_path_text or not archive_path.is_file():
        return {
            **base,
            "ok": False,
            "status": "unresolved",
            "diagnostics": ["live_tail_archive_raw_unavailable"],
        }
    if archived_bytes < 0 or archived_lines <= 0 or not expected_prefix_sha256:
        if archived_bytes < 0:
            diagnostics.append("live_tail_archive_byte_watermark_missing")
        if archived_lines <= 0:
            diagnostics.append("live_tail_archive_line_watermark_missing")
        if not expected_prefix_sha256:
            diagnostics.append("live_tail_archive_sha256_missing")
        return {**base, "ok": False, "status": "unresolved", "diagnostics": diagnostics}
    try:
        archive_stat = archive_path.stat()
        source_stat = source_path.stat()
    except OSError as exc:
        return {
            **base,
            "ok": False,
            "status": "unresolved",
            "diagnostics": [f"live_tail_source_stat_failed:{exc}"],
        }
    if archive_stat.st_size != archived_bytes:
        diagnostics.append("live_tail_archive_size_does_not_match_manifest_watermark")
    if source_stat.st_size < archived_bytes:
        diagnostics.append("live_tail_source_shorter_than_archived_watermark")
    if diagnostics:
        return {
            **base,
            "ok": False,
            "status": "unresolved",
            "source_size": source_stat.st_size,
            "diagnostics": diagnostics,
        }
    if source_stat.st_size == archived_bytes:
        return {
            **base,
            "ok": True,
            "status": "no_unarchived_tail",
            "source_size": source_stat.st_size,
            "snapshot_end_offset": source_stat.st_size,
            "scan_end_offset": source_stat.st_size,
            "delta_bytes": 0,
            "scan_bytes": 0,
            "line_start": archived_lines + 1,
            "prefix_validation": {"status": "not_needed_no_delta"},
            "diagnostics": [],
            "elapsed_ms": int((time.monotonic() - started) * 1000),
        }
    boundary_aligned = archived_bytes == 0
    try:
        if archived_bytes > 0:
            with source_path.open("rb") as source_handle:
                source_handle.seek(archived_bytes - 1)
                boundary_aligned = source_handle.read(1) == b"\n"
    except OSError as exc:
        return {
            **base,
            "ok": False,
            "status": "unresolved",
            "diagnostics": [f"live_tail_boundary_read_failed:{exc}"],
        }
    if not boundary_aligned:
        return {
            **base,
            "ok": False,
            "status": "unresolved",
            "diagnostics": ["live_tail_archive_boundary_not_line_aligned"],
        }
    prefix = sha256_file_prefix(
        source_path,
        archived_bytes,
        budget_ms=LIVE_TAIL_SEARCH_PREFIX_HASH_BUDGET_MS,
    )
    if prefix.get("status") == "prefix_hash_budget_exhausted":
        return {
            **base,
            "ok": False,
            "status": "deferred_prefix_validation",
            "source_size": source_stat.st_size,
            "readability": "stale-readable",
            "prefix_validation": {
                **prefix,
                "expected_sha256": expected_prefix_sha256,
                "archive_boundary_line_aligned": True,
            },
            "retry_policy": "automatic_projection_catch_up_or_later_bounded_retry",
            "diagnostics": list(prefix.get("diagnostics") or []),
            "elapsed_ms": int((time.monotonic() - started) * 1000),
        }
    if not prefix.get("ok") or str(prefix.get("sha256") or "") != expected_prefix_sha256:
        mismatch_diagnostics = list(prefix.get("diagnostics") or [])
        if prefix.get("ok"):
            mismatch_diagnostics.append("live_tail_source_prefix_sha256_mismatch")
        return {
            **base,
            "ok": False,
            "status": "unresolved",
            "source_size": source_stat.st_size,
            "prefix_validation": {
                **prefix,
                "status": "mismatch" if prefix.get("ok") else prefix.get("status"),
                "expected_sha256": expected_prefix_sha256,
            },
            "diagnostics": mismatch_diagnostics,
        }
    try:
        post_prefix_stat = source_path.stat()
    except OSError as exc:
        return {
            **base,
            "ok": False,
            "status": "unresolved",
            "diagnostics": [f"live_tail_post_prefix_stat_failed:{exc}"],
        }
    same_file = bool(
        source_stat.st_dev == post_prefix_stat.st_dev
        and source_stat.st_ino == post_prefix_stat.st_ino
        and post_prefix_stat.st_size >= source_stat.st_size
    )
    if not same_file:
        return {
            **base,
            "ok": False,
            "status": "unresolved",
            "diagnostics": ["live_tail_source_replaced_or_truncated_during_prefix_validation"],
        }
    snapshot_end = source_stat.st_size
    delta_bytes = snapshot_end - archived_bytes
    scan_end = min(snapshot_end, archived_bytes + effective_max_bytes)
    byte_truncated = scan_end < snapshot_end
    snapshot_id = hashlib.sha256(
        f"{source_stat.st_dev}:{source_stat.st_ino}:{snapshot_end}:{source_stat.st_mtime_ns}".encode("utf-8")
    ).hexdigest()[:24]
    return {
        **base,
        "ok": True,
        "status": "truncated" if byte_truncated else "fallback",
        "fallback_reason": "archived_projection_does_not_cover_append_only_live_tail",
        "source_size": snapshot_end,
        "source_mtime_ns": source_stat.st_mtime_ns,
        "source_device": source_stat.st_dev,
        "source_inode": source_stat.st_ino,
        "snapshot_id": snapshot_id,
        "snapshot_end_offset": snapshot_end,
        "scan_start_offset": archived_bytes,
        "scan_end_offset": scan_end,
        "delta_bytes": delta_bytes,
        "scan_bytes": scan_end - archived_bytes,
        "unscanned_bytes": max(0, snapshot_end - scan_end),
        "line_start": archived_lines + 1,
        "byte_truncated": byte_truncated,
        "prefix_validation": {
            **prefix,
            "status": "full_archived_prefix_sha256_match",
            "expected_sha256": expected_prefix_sha256,
            "archive_boundary_line_aligned": True,
        },
        "authority": {
            "source": "live_raw_transcript_snapshot",
            "projection": "none_query_time_candidate",
            "archive_projection": "stale-readable",
            "segment_ref_available": False,
        },
        "diagnostics": (["live_tail_byte_budget_truncated"] if byte_truncated else []),
        "elapsed_ms": int((time.monotonic() - started) * 1000),
    }


def live_tail_semantic_source_weight(
    source_type: str,
    payload: dict[str, Any],
) -> tuple[float, str]:
    payload_type = str(payload.get("type") or "")
    role = str(payload.get("role") or "")
    if source_type == "response_item" and payload_type == "message" and role == "assistant":
        return 1.0, "assistant_message"
    if source_type == "event_msg":
        return 0.8, "event_message"
    if source_type == "response_item" and payload_type == "message" and role == "user":
        return 0.35, "user_intent"
    if payload_type in {"function_call", "tool_call", "custom_tool_call"}:
        return 0.65, "structured_action"
    if payload_type in {
        "function_call_output",
        "tool_call_output",
        "custom_tool_call_output",
    }:
        return 0.5, "structured_result"
    return 0.25, f"{source_type}:{payload_type or 'untyped'}"


def live_tail_semantic_query_term_matches(
    text: str,
    terms: list[dict[str, Any]],
) -> list[str]:
    tokens = episode_semantic_field_tokens(text)
    return [
        str(term.get("token") or "")
        for term in terms
        if episode_semantic_term_matches_tokens(term, tokens)
    ]


def live_tail_semantic_goal_continuation(text: str) -> bool:
    return bool(
        re.match(
            r"""^\s*<codex_internal_context\b[^>]*\bsource\s*=\s*["']goal["'][^>]*>""",
            str(text or ""),
            flags=re.IGNORECASE,
        )
    )


def live_tail_semantic_clipped_window(
    episode: dict[str, Any],
    hit: dict[str, Any],
) -> dict[str, Any] | None:
    positions = (
        episode.get("_line_positions")
        if isinstance(episode.get("_line_positions"), list)
        else []
    )
    if not positions:
        return None
    hit_line = int_value(hit.get("line"))
    hit_index = next(
        (
            index
            for index, item in enumerate(positions)
            if int_value(item[0]) == hit_line
        ),
        -1,
    )
    if hit_index < 0:
        return None
    start_index = max(0, hit_index - LIVE_TAIL_SEMANTIC_HIT_CONTEXT_LINES)
    end_index = min(
        len(positions),
        hit_index + LIVE_TAIL_SEMANTIC_HIT_CONTEXT_LINES + 1,
    )
    if end_index - start_index > LIVE_TAIL_SEMANTIC_MAX_WINDOW_LINES:
        half = LIVE_TAIL_SEMANTIC_MAX_WINDOW_LINES // 2
        start_index = max(0, hit_index - half)
        end_index = min(
            len(positions),
            start_index + LIVE_TAIL_SEMANTIC_MAX_WINDOW_LINES,
        )
        start_index = max(0, end_index - LIVE_TAIL_SEMANTIC_MAX_WINDOW_LINES)
    while end_index - start_index > 1:
        window_bytes = int_value(positions[end_index - 1][2]) - int_value(
            positions[start_index][1]
        )
        if window_bytes <= LIVE_TAIL_SEMANTIC_MAX_WINDOW_BYTES:
            break
        before = hit_index - start_index
        after = end_index - hit_index - 1
        if before >= after and start_index < hit_index:
            start_index += 1
        elif end_index - 1 > hit_index:
            end_index -= 1
        else:
            break
    window_bytes = int_value(positions[end_index - 1][2]) - int_value(
        positions[start_index][1]
    )
    if window_bytes > LIVE_TAIL_SEMANTIC_MAX_WINDOW_BYTES:
        return None
    start_line = int_value(positions[start_index][0])
    end_line = int_value(positions[end_index - 1][0])
    return {
        "episode_ordinal": int_value(episode.get("ordinal")),
        "episode_score": float(episode.get("score") or 0.0),
        "boundary_kind": str(episode.get("boundary_kind") or ""),
        "selection_kind": "query_hit_centered_episode_clip",
        "start_line": start_line,
        "end_line": end_line,
        "start_offset": int_value(positions[start_index][1]),
        "end_offset": int_value(positions[end_index - 1][2]),
        "line_count": end_line - start_line + 1,
        "byte_count": window_bytes,
        "primary_hit_line": hit_line,
        "primary_hit_score": float(hit.get("score") or 0.0),
        "query_hit_lines": sorted(
            {
                int_value(item.get("line"))
                for item in episode.get("hits", [])
                if start_line
                <= int_value(item.get("line"))
                <= end_line
            }
        )[:32],
        "covers_full_structural_episode": False,
    }


def live_tail_semantic_discover_windows(
    snapshot: dict[str, Any],
    *,
    terms: list[dict[str, Any]],
    query: str,
    normalized_time_from: str | None = None,
    normalized_time_to: str | None = None,
    budget_ms: int | None = None,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Select query-bearing structural episode windows before costly hydration."""
    started = time.monotonic()
    effective_budget_ms = max(
        1,
        int_value(budget_ms, LIVE_TAIL_SEMANTIC_DISCOVERY_BUDGET_MS),
    )
    source_path = Path(str(snapshot.get("live_source_path") or ""))
    start_offset = int_value(snapshot.get("scan_start_offset"))
    end_offset = int_value(snapshot.get("scan_end_offset"))
    max_lines = int_value(snapshot.get("max_lines"), LIVE_TAIL_SEARCH_DEFAULT_MAX_LINES)
    normalized_query = re.sub(r"\s+", " ", str(query or "").casefold()).strip()
    required_exact_anchors = episode_semantic_required_exact_anchors(query)
    required_exact_anchor_values = {
        str(item.get("anchor") or "")
        for item in required_exact_anchors
        if str(item.get("anchor") or "")
    }
    episodes: list[dict[str, Any]] = []
    current: dict[str, Any] | None = None
    suppressed_correlations: set[str] = set()
    complete_line_count = 0
    bytes_read = 0
    line_no = int_value(snapshot.get("archived_line_count"))
    scan_end_offset = start_offset
    time_budget_exhausted = False
    line_budget_exhausted = False
    incomplete_final_line_skipped = False
    query_control_event_count = 0
    query_intent_echo_count = 0
    time_window_excluded_hit_count = 0
    undated_time_window_excluded_hit_count = 0
    diagnostics: list[str] = []

    def start_episode(
        *,
        boundary_kind: str,
        boundary_line: int,
        boundary_offset: int,
    ) -> dict[str, Any]:
        episode = {
            "ordinal": len(episodes) + 1,
            "boundary_kind": boundary_kind,
            "start_line": boundary_line,
            "end_line": boundary_line,
            "start_offset": boundary_offset,
            "end_offset": boundary_offset,
            "hits": [],
            "term_weights": {},
            "required_anchor_matches": set(),
            "_line_positions": [],
        }
        episodes.append(episode)
        return episode

    try:
        with source_path.open("rb") as handle:
            handle.seek(start_offset)
            while handle.tell() < end_offset:
                elapsed_ms = int((time.monotonic() - started) * 1000)
                if (
                    complete_line_count > 0
                    and elapsed_ms >= effective_budget_ms
                ):
                    time_budget_exhausted = True
                    break
                if complete_line_count >= max_lines:
                    line_budget_exhausted = True
                    break
                line_offset = handle.tell()
                raw_bytes = handle.readline(end_offset - line_offset)
                if not raw_bytes:
                    break
                if not raw_bytes.endswith(b"\n"):
                    incomplete_final_line_skipped = True
                    break
                line_no += 1
                complete_line_count += 1
                bytes_read += len(raw_bytes)
                scan_end_offset = handle.tell()
                raw_line = raw_bytes[:-1].decode("utf-8", errors="replace")
                try:
                    loaded = json.loads(raw_line)
                    parsed = loaded if isinstance(loaded, dict) else {}
                except json.JSONDecodeError:
                    parsed = {}
                source_type = str(parsed.get("type") or "")
                payload = (
                    parsed.get("payload")
                    if isinstance(parsed.get("payload"), dict)
                    else {}
                )
                payload_type = str(payload.get("type") or "")
                role = str(payload.get("role") or "")
                semantic = semantic_text_for_classification(
                    source_type,
                    payload,
                    max_chars=LIVE_TAIL_SEMANTIC_DISCOVERY_TEXT_MAX_CHARS,
                )
                canonical_user = bool(
                    source_type == "response_item"
                    and payload_type == "message"
                    and role == "user"
                )
                runtime_envelope = bool(
                    canonical_user
                    and naming_evidence_text_is_runtime_envelope(semantic)
                )
                goal_continuation = bool(
                    runtime_envelope
                    and live_tail_semantic_goal_continuation(semantic)
                )
                structured_skill = bool(
                    canonical_user
                    and structured_skill_input_for_payload(
                        payload,
                        source_type=source_type,
                    )
                )
                if goal_continuation or (
                    canonical_user
                    and not runtime_envelope
                    and not structured_skill
                ):
                    current = start_episode(
                        boundary_kind=(
                            "automatic_goal_continuation"
                            if goal_continuation
                            else "user_prompt"
                        ),
                        boundary_line=line_no,
                        boundary_offset=line_offset,
                    )
                elif current is None:
                    current = start_episode(
                        boundary_kind="archive_boundary_continuation",
                        boundary_line=line_no,
                        boundary_offset=line_offset,
                    )
                current["end_line"] = line_no
                current["end_offset"] = handle.tell()
                current["_line_positions"].append(
                    (line_no, line_offset, handle.tell())
                )
                if runtime_envelope or structured_skill:
                    continue
                correlation_id = str(payload_correlation_id(payload) or "")
                structured_action = payload_type in {
                    "function_call",
                    "tool_call",
                    "custom_tool_call",
                }
                structured_result = payload_type in {
                    "function_call_output",
                    "tool_call_output",
                    "custom_tool_call_output",
                }
                matched_terms = live_tail_semantic_query_term_matches(
                    semantic,
                    terms,
                )
                normalized_semantic = re.sub(
                    r"\s+",
                    " ",
                    semantic.casefold(),
                ).strip()
                recognized_control = (
                    task_episode_retrieval_control_structured_payload(payload)
                    or (
                        task_episode_retrieval_control_semantic(semantic)
                        if structured_action
                        else ""
                    )
                )
                if recognized_control:
                    if correlation_id:
                        suppressed_correlations.add(correlation_id)
                    query_control_event_count += 1
                    continue
                if structured_result and (
                    (
                        correlation_id
                        and correlation_id in suppressed_correlations
                    )
                    or task_episode_retrieval_control_result_semantic(semantic)
                ):
                    query_control_event_count += 1
                    continue
                current["required_anchor_matches"].update(
                    episode_semantic_required_anchor_matches(
                        semantic,
                        required_exact_anchors,
                    )
                )
                if not matched_terms:
                    continue
                exact_user_query_echo = bool(
                    canonical_user
                    and normalized_query
                    and normalized_query in normalized_semantic
                )
                if exact_user_query_echo:
                    query_intent_echo_count += 1
                    continue
                if normalized_time_from or normalized_time_to:
                    timestamp = str(parsed.get("timestamp") or "")
                    try:
                        event_timestamp = (
                            parse_timestamp_arg(timestamp)
                            if timestamp
                            else None
                        )
                    except ValueError:
                        event_timestamp = None
                    if not event_timestamp:
                        time_window_excluded_hit_count += 1
                        undated_time_window_excluded_hit_count += 1
                        continue
                    if (
                        normalized_time_from
                        and event_timestamp < normalized_time_from
                    ):
                        time_window_excluded_hit_count += 1
                        continue
                    if normalized_time_to and event_timestamp > normalized_time_to:
                        time_window_excluded_hit_count += 1
                        continue
                source_weight, source_lane = live_tail_semantic_source_weight(
                    source_type,
                    payload,
                )
                hit = {
                    "line": line_no,
                    "matched_terms": matched_terms,
                    "matched_term_count": len(matched_terms),
                    "source_weight": source_weight,
                    "source_lane": source_lane,
                }
                current["hits"].append(hit)
                for token in matched_terms:
                    current["term_weights"][token] = max(
                        float(current["term_weights"].get(token) or 0.0),
                        source_weight,
                    )
    except OSError as exc:
        diagnostics.append(f"live_tail_semantic_discovery_failed:{exc}")

    all_hit_episodes = [
        episode
        for episode in episodes
        if episode.get("hits")
    ]
    hit_episodes = [
        episode
        for episode in all_hit_episodes
        if (
            not required_exact_anchor_values
            or required_exact_anchor_values
            <= set(episode.get("required_anchor_matches") or set())
        )
    ]
    anchor_rejected_hit_episode_count = (
        len(all_hit_episodes) - len(hit_episodes)
    )
    document_frequency = {
        str(term.get("token") or ""): sum(
            1
            for episode in hit_episodes
            if str(term.get("token") or "") in episode.get("term_weights", {})
        )
        for term in terms
    }
    hit_episode_count = max(1, len(hit_episodes))
    inverse_document_frequency = {
        token: 1.0
        + math.log(
            (hit_episode_count + 1)
            / (int_value(frequency) + 1)
        )
        for token, frequency in document_frequency.items()
    }
    for episode in hit_episodes:
        for hit in episode.get("hits", []):
            hit["score"] = round(
                float(hit.get("source_weight") or 0.0)
                * sum(
                    inverse_document_frequency.get(str(token), 1.0)
                    for token in hit.get("matched_terms", [])
                ),
                6,
            )
        best_hit = max(
            episode.get("hits", []),
            key=lambda item: (
                float(item.get("score") or 0.0),
                int_value(item.get("matched_term_count")),
                -int_value(item.get("line")),
            ),
        )
        episode["score"] = round(
            sum(
                float(weight)
                * inverse_document_frequency.get(str(token), 1.0)
                for token, weight in episode.get("term_weights", {}).items()
            )
            + (
                float(best_hit.get("source_weight") or 0.0)
                * int_value(best_hit.get("matched_term_count"))
                * 0.35
            ),
            6,
        )
        episode["best_hit_line"] = int_value(best_hit.get("line"))
        episode["best_hit_score"] = float(best_hit.get("score") or 0.0)
    ranked_episodes = sorted(
        hit_episodes,
        key=lambda item: (
            -float(item.get("score") or 0.0),
            -float(item.get("best_hit_score") or 0.0),
            int_value(item.get("start_line")),
        ),
    )
    window_candidates: list[dict[str, Any]] = []
    oversized_hit_count = 0
    for episode_rank, episode in enumerate(ranked_episodes, start=1):
        positions = episode.get("_line_positions", [])
        if not positions:
            continue
        full_line_count = len(positions)
        full_byte_count = int_value(positions[-1][2]) - int_value(
            positions[0][1]
        )
        if (
            full_line_count <= LIVE_TAIL_SEMANTIC_MAX_WINDOW_LINES
            and full_byte_count <= LIVE_TAIL_SEMANTIC_MAX_WINDOW_BYTES
        ):
            candidate = {
                "episode_ordinal": int_value(episode.get("ordinal")),
                "episode_rank": episode_rank,
                "episode_score": float(episode.get("score") or 0.0),
                "boundary_kind": str(episode.get("boundary_kind") or ""),
                "selection_kind": "full_query_bearing_structural_episode",
                "start_line": int_value(positions[0][0]),
                "end_line": int_value(positions[-1][0]),
                "start_offset": int_value(positions[0][1]),
                "end_offset": int_value(positions[-1][2]),
                "line_count": full_line_count,
                "byte_count": full_byte_count,
                "primary_hit_line": int_value(episode.get("best_hit_line")),
                "primary_hit_score": float(episode.get("best_hit_score") or 0.0),
                "query_hit_lines": sorted(
                    {
                        int_value(item.get("line"))
                        for item in episode.get("hits", [])
                    }
                )[:32],
                "covers_full_structural_episode": True,
            }
            window_candidates.append(candidate)
            continue
        accepted_ranges: list[tuple[int, int]] = []
        for hit in sorted(
            episode.get("hits", []),
            key=lambda item: (
                -float(item.get("score") or 0.0),
                -int_value(item.get("matched_term_count")),
                int_value(item.get("line")),
            ),
        ):
            if len(accepted_ranges) >= 2:
                break
            clipped = live_tail_semantic_clipped_window(episode, hit)
            if clipped is None:
                oversized_hit_count += 1
                continue
            clipped["episode_rank"] = episode_rank
            clipped_range = (
                int_value(clipped.get("start_line")),
                int_value(clipped.get("end_line")),
            )
            if any(
                clipped_range[0] <= existing_end
                and clipped_range[1] >= existing_start
                for existing_start, existing_end in accepted_ranges
            ):
                continue
            accepted_ranges.append(clipped_range)
            window_candidates.append(clipped)

    selected_windows: list[dict[str, Any]] = []
    total_selected_lines = 0
    total_selected_bytes = 0
    for candidate in window_candidates:
        if len(selected_windows) >= LIVE_TAIL_SEMANTIC_MAX_WINDOWS:
            break
        line_count = int_value(candidate.get("line_count"))
        byte_count = int_value(candidate.get("byte_count"))
        if (
            total_selected_lines + line_count
            > LIVE_TAIL_SEMANTIC_TOTAL_WINDOW_LINES
            or total_selected_bytes + byte_count
            > LIVE_TAIL_SEMANTIC_TOTAL_WINDOW_BYTES
        ):
            continue
        selected = dict(candidate)
        selected["selection_rank"] = len(selected_windows) + 1
        selected_windows.append(selected)
        total_selected_lines += line_count
        total_selected_bytes += byte_count
    selected_windows.sort(
        key=lambda item: (
            int_value(item.get("start_offset")),
            int_value(item.get("end_offset")),
        )
    )
    selected_full_episode_ordinals = {
        int_value(item.get("episode_ordinal"))
        for item in selected_windows
        if item.get("covers_full_structural_episode")
    }
    hit_episode_ordinals = {
        int_value(item.get("ordinal"))
        for item in hit_episodes
    }
    discovery_truncated = bool(
        time_budget_exhausted
        or line_budget_exhausted
        or incomplete_final_line_skipped
        or scan_end_offset < end_offset
        or diagnostics
    )
    candidate_coverage_exhaustive = bool(
        not discovery_truncated
        and not snapshot.get("byte_truncated")
        and hit_episode_ordinals <= selected_full_episode_ordinals
        and oversized_hit_count == 0
    )
    if time_budget_exhausted:
        diagnostics.append("live_tail_semantic_discovery_time_budget_truncated")
    if line_budget_exhausted:
        diagnostics.append("live_tail_semantic_discovery_line_budget_truncated")
    if incomplete_final_line_skipped:
        diagnostics.append(
            "live_tail_semantic_discovery_incomplete_snapshot_final_line_skipped"
        )
    if len(selected_full_episode_ordinals) < len(hit_episode_ordinals):
        diagnostics.append(
            "live_tail_semantic_query_window_selection_non_exhaustive"
        )
    if oversized_hit_count:
        diagnostics.append(
            f"live_tail_semantic_oversized_hit_window_unselected:{oversized_hit_count}"
        )
    if anchor_rejected_hit_episode_count:
        diagnostics.append(
            "live_tail_semantic_required_exact_anchor_unmatched:"
            f"{anchor_rejected_hit_episode_count}"
        )
    episode_summaries = [
        {
            "episode_rank": rank,
            "episode_ordinal": int_value(episode.get("ordinal")),
            "boundary_kind": str(episode.get("boundary_kind") or ""),
            "start_line": int_value(episode.get("start_line")),
            "end_line": int_value(episode.get("end_line")),
            "score": float(episode.get("score") or 0.0),
            "query_hit_count": len(episode.get("hits", [])),
            "best_hit_line": int_value(episode.get("best_hit_line")),
            "best_hit_score": float(episode.get("best_hit_score") or 0.0),
        }
        for rank, episode in enumerate(ranked_episodes[:12], start=1)
    ]
    public_windows = [
        {
            key: item.get(key)
            for key in (
                "selection_rank",
                "episode_rank",
                "episode_ordinal",
                "episode_score",
                "boundary_kind",
                "selection_kind",
                "start_line",
                "end_line",
                "start_offset",
                "end_offset",
                "line_count",
                "byte_count",
                "primary_hit_line",
                "primary_hit_score",
                "query_hit_lines",
                "covers_full_structural_episode",
            )
        }
        for item in selected_windows
    ]
    payload = {
        "schema_version": LIVE_TAIL_SEARCH_SCHEMA_VERSION,
        "artifact_type": "live_tail_semantic_query_window_discovery",
        "status": (
            "truncated"
            if discovery_truncated
            else "selected"
            if selected_windows
            else "no_query_term_windows"
        ),
        "strategy": "query_driven_structural_episode_windows_v1",
        "mutates": False,
        "scan_start_offset": start_offset,
        "scan_end_offset": scan_end_offset,
        "snapshot_scan_end_offset": end_offset,
        "first_line": int_value(snapshot.get("archived_line_count")) + 1,
        "last_line": line_no,
        "complete_line_count": complete_line_count,
        "bytes_read": bytes_read,
        "budget_ms": effective_budget_ms,
        "elapsed_ms": int((time.monotonic() - started) * 1000),
        "time_budget_exhausted": time_budget_exhausted,
        "line_budget_exhausted": line_budget_exhausted,
        "incomplete_final_line_skipped": incomplete_final_line_skipped,
        "structural_episode_count": len(episodes),
        "query_hit_episode_count": len(all_hit_episodes),
        "anchor_qualified_hit_episode_count": len(hit_episodes),
        "anchor_rejected_hit_episode_count": anchor_rejected_hit_episode_count,
        "query_hit_count": sum(
            len(item.get("hits", []))
            for item in all_hit_episodes
        ),
        "required_exact_anchors": required_exact_anchors,
        "selected_window_count": len(selected_windows),
        "selected_window_lines": total_selected_lines,
        "selected_window_bytes": total_selected_bytes,
        "omitted_query_hit_episode_count": max(
            0,
            len(hit_episode_ordinals - selected_full_episode_ordinals),
        ),
        "candidate_coverage_exhaustive": candidate_coverage_exhaustive,
        "query_control_event_count": query_control_event_count,
        "query_control_correlation_count": len(suppressed_correlations),
        "query_intent_echo_count": query_intent_echo_count,
        "time_window_excluded_hit_count": time_window_excluded_hit_count,
        "undated_time_window_excluded_hit_count": (
            undated_time_window_excluded_hit_count
        ),
        "episode_candidates": episode_summaries,
        "selected_windows": public_windows,
        "diagnostics": list(dict.fromkeys(diagnostics)),
        "truth_status": (
            "bounded_query_candidate_discovery_not_semantic_answer_proof"
        ),
    }
    return payload, selected_windows


def live_tail_semantic_recent_reserve_snapshot(
    snapshot: dict[str, Any],
    discovery: dict[str, Any],
) -> dict[str, Any] | None:
    """Reserve one bounded recent range when prefix discovery exhausts its budget."""
    source_path = Path(str(snapshot.get("live_source_path") or ""))
    primary_end_offset = int_value(discovery.get("scan_end_offset"))
    snapshot_end_offset = int_value(snapshot.get("scan_end_offset"))
    if (
        not source_path.is_file()
        or primary_end_offset <= 0
        or primary_end_offset >= snapshot_end_offset
    ):
        return None
    desired_start_offset = max(
        primary_end_offset,
        snapshot_end_offset - LIVE_TAIL_SEMANTIC_RECENT_RESERVE_BYTES,
    )
    line_base = int_value(discovery.get("last_line"))
    aligned_start_offset = desired_start_offset
    try:
        with source_path.open("rb") as handle:
            if desired_start_offset > primary_end_offset:
                handle.seek(primary_end_offset)
                remaining = desired_start_offset - primary_end_offset
                skipped_line_count = 0
                while remaining > 0:
                    chunk = handle.read(min(1024 * 1024, remaining))
                    if not chunk:
                        return None
                    skipped_line_count += chunk.count(b"\n")
                    remaining -= len(chunk)
                handle.seek(desired_start_offset - 1)
                begins_at_line_boundary = handle.read(1) == b"\n"
                handle.seek(desired_start_offset)
                if not begins_at_line_boundary:
                    partial = handle.readline(
                        snapshot_end_offset - desired_start_offset
                    )
                    if not partial.endswith(b"\n"):
                        return None
                    skipped_line_count += 1
                aligned_start_offset = handle.tell()
                line_base += skipped_line_count
    except OSError:
        return None
    if aligned_start_offset >= snapshot_end_offset:
        return None
    original_line_base = int_value(snapshot.get("archived_line_count"))
    remaining_line_budget = int_value(
        snapshot.get("max_lines"),
        LIVE_TAIL_SEARCH_DEFAULT_MAX_LINES,
    ) - max(0, line_base - original_line_base)
    if remaining_line_budget <= 0:
        return None
    return {
        **snapshot,
        "scan_start_offset": aligned_start_offset,
        "scan_end_offset": snapshot_end_offset,
        "archived_line_count": line_base,
        "scan_line_base_count": line_base,
        "max_lines": remaining_line_budget,
    }


def live_tail_semantic_merge_discovery_reserve(
    snapshot: dict[str, Any],
    primary: dict[str, Any],
    recent: dict[str, Any],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Merge prefix and recent candidates without presenting bounded coverage as exhaustive."""
    candidates: list[dict[str, Any]] = []
    seen_ranges: set[tuple[int, int]] = set()
    for pass_name, payload in (("prefix", primary), ("recent", recent)):
        for item in payload.get("selected_windows", []):
            if not isinstance(item, dict):
                continue
            key = (
                int_value(item.get("start_offset")),
                int_value(item.get("end_offset")),
            )
            if key in seen_ranges:
                continue
            seen_ranges.add(key)
            candidate = dict(item)
            candidate["discovery_pass"] = pass_name
            candidates.append(candidate)
    candidates.sort(
        key=lambda item: (
            -float(item.get("episode_score") or 0.0),
            -float(item.get("primary_hit_score") or 0.0),
            -int_value(item.get("primary_hit_line")),
            int_value(item.get("start_offset")),
        )
    )
    selected_windows: list[dict[str, Any]] = []
    selected_line_count = 0
    selected_byte_count = 0
    for candidate in candidates:
        if len(selected_windows) >= LIVE_TAIL_SEMANTIC_MAX_WINDOWS:
            break
        line_count = int_value(candidate.get("line_count"))
        byte_count = int_value(candidate.get("byte_count"))
        if (
            selected_line_count + line_count
            > LIVE_TAIL_SEMANTIC_TOTAL_WINDOW_LINES
            or selected_byte_count + byte_count
            > LIVE_TAIL_SEMANTIC_TOTAL_WINDOW_BYTES
        ):
            continue
        selected = dict(candidate)
        selected["selection_rank"] = len(selected_windows) + 1
        selected_windows.append(selected)
        selected_line_count += line_count
        selected_byte_count += byte_count
    selected_windows.sort(
        key=lambda item: (
            int_value(item.get("start_offset")),
            int_value(item.get("end_offset")),
        )
    )
    snapshot_end_offset = int_value(snapshot.get("scan_end_offset"))
    primary_end_offset = int_value(primary.get("scan_end_offset"))
    recent_start_offset = int_value(recent.get("scan_start_offset"))
    recent_end_offset = int_value(recent.get("scan_end_offset"))
    unscanned_gap_bytes = max(0, recent_start_offset - primary_end_offset)
    total_hit_episode_count = (
        int_value(primary.get("anchor_qualified_hit_episode_count"))
        + int_value(recent.get("anchor_qualified_hit_episode_count"))
    )
    selected_full_episode_count = sum(
        1
        for item in selected_windows
        if item.get("covers_full_structural_episode")
    )
    omitted_hit_episode_count = max(
        0,
        total_hit_episode_count - selected_full_episode_count,
    )
    diagnostics = [
        *list(primary.get("diagnostics") or []),
        *list(recent.get("diagnostics") or []),
        "live_tail_semantic_recent_reserve_applied",
    ]
    if unscanned_gap_bytes:
        diagnostics.append(
            "live_tail_semantic_recent_reserve_unscanned_middle:"
            f"{unscanned_gap_bytes}"
        )
    coverage_exhaustive = bool(
        not snapshot.get("byte_truncated")
        and unscanned_gap_bytes == 0
        and recent_end_offset >= snapshot_end_offset
        and not recent.get("line_budget_exhausted")
        and not recent.get("incomplete_final_line_skipped")
        and omitted_hit_episode_count == 0
        and not int_value(primary.get("anchor_rejected_hit_episode_count"))
        and not int_value(recent.get("anchor_rejected_hit_episode_count"))
    )
    if coverage_exhaustive:
        diagnostics = [
            item
            for item in diagnostics
            if item
            != "live_tail_semantic_discovery_time_budget_truncated"
        ]
        diagnostics.append(
            "live_tail_semantic_prefix_budget_exhausted_recent_reserve_completed"
        )
    status = (
        "selected"
        if coverage_exhaustive and selected_windows
        else "no_query_term_windows"
        if coverage_exhaustive and not selected_windows
        else "truncated"
    )
    episode_candidates: list[dict[str, Any]] = []
    for pass_name, payload in (("prefix", primary), ("recent", recent)):
        for item in payload.get("episode_candidates", []):
            if isinstance(item, dict):
                candidate = dict(item)
                candidate["discovery_pass"] = pass_name
                episode_candidates.append(candidate)
    episode_candidates.sort(
        key=lambda item: (
            -float(item.get("score") or 0.0),
            -int_value(item.get("best_hit_line")),
        )
    )
    for rank, item in enumerate(episode_candidates, start=1):
        item["episode_rank"] = rank
    payload = {
        **primary,
        "status": status,
        "strategy": "query_driven_structural_episode_windows_v2_recent_reserve",
        "scan_end_offset": max(primary_end_offset, recent_end_offset),
        "snapshot_scan_end_offset": snapshot_end_offset,
        "last_line": max(
            int_value(primary.get("last_line")),
            int_value(recent.get("last_line")),
        ),
        "complete_line_count": (
            int_value(primary.get("complete_line_count"))
            + int_value(recent.get("complete_line_count"))
        ),
        "bytes_read": (
            int_value(primary.get("bytes_read"))
            + int_value(recent.get("bytes_read"))
        ),
        "budget_ms": (
            int_value(primary.get("budget_ms"))
            + int_value(recent.get("budget_ms"))
        ),
        "elapsed_ms": (
            int_value(primary.get("elapsed_ms"))
            + int_value(recent.get("elapsed_ms"))
        ),
        "time_budget_exhausted": bool(
            not coverage_exhaustive
            and (
                primary.get("time_budget_exhausted")
                or recent.get("time_budget_exhausted")
            )
        ),
        "line_budget_exhausted": bool(
            primary.get("line_budget_exhausted")
            or recent.get("line_budget_exhausted")
        ),
        "incomplete_final_line_skipped": bool(
            recent.get("incomplete_final_line_skipped")
        ),
        "structural_episode_count": (
            int_value(primary.get("structural_episode_count"))
            + int_value(recent.get("structural_episode_count"))
        ),
        "query_hit_episode_count": (
            int_value(primary.get("query_hit_episode_count"))
            + int_value(recent.get("query_hit_episode_count"))
        ),
        "anchor_qualified_hit_episode_count": total_hit_episode_count,
        "anchor_rejected_hit_episode_count": (
            int_value(primary.get("anchor_rejected_hit_episode_count"))
            + int_value(recent.get("anchor_rejected_hit_episode_count"))
        ),
        "query_hit_count": (
            int_value(primary.get("query_hit_count"))
            + int_value(recent.get("query_hit_count"))
        ),
        "selected_window_count": len(selected_windows),
        "selected_window_lines": selected_line_count,
        "selected_window_bytes": selected_byte_count,
        "omitted_query_hit_episode_count": omitted_hit_episode_count,
        "candidate_coverage_exhaustive": coverage_exhaustive,
        "query_control_event_count": (
            int_value(primary.get("query_control_event_count"))
            + int_value(recent.get("query_control_event_count"))
        ),
        "query_control_correlation_count": (
            int_value(primary.get("query_control_correlation_count"))
            + int_value(recent.get("query_control_correlation_count"))
        ),
        "query_intent_echo_count": (
            int_value(primary.get("query_intent_echo_count"))
            + int_value(recent.get("query_intent_echo_count"))
        ),
        "time_window_excluded_hit_count": (
            int_value(primary.get("time_window_excluded_hit_count"))
            + int_value(recent.get("time_window_excluded_hit_count"))
        ),
        "undated_time_window_excluded_hit_count": (
            int_value(primary.get("undated_time_window_excluded_hit_count"))
            + int_value(recent.get("undated_time_window_excluded_hit_count"))
        ),
        "episode_candidates": episode_candidates[:12],
        "selected_windows": selected_windows,
        "discovery_passes": [
            {
                "name": "prefix",
                "scan_start_offset": int_value(primary.get("scan_start_offset")),
                "scan_end_offset": primary_end_offset,
                "bytes_read": int_value(primary.get("bytes_read")),
                "complete_line_count": int_value(primary.get("complete_line_count")),
                "time_budget_exhausted": bool(
                    primary.get("time_budget_exhausted")
                ),
            },
            {
                "name": "recent",
                "scan_start_offset": recent_start_offset,
                "scan_end_offset": recent_end_offset,
                "bytes_read": int_value(recent.get("bytes_read")),
                "complete_line_count": int_value(recent.get("complete_line_count")),
                "time_budget_exhausted": bool(
                    recent.get("time_budget_exhausted")
                ),
            },
        ],
        "unscanned_gap_bytes": unscanned_gap_bytes,
        "diagnostics": list(dict.fromkeys(diagnostics)),
    }
    return payload, selected_windows


def live_tail_semantic_discover_windows_bounded(
    snapshot: dict[str, Any],
    *,
    terms: list[dict[str, Any]],
    query: str,
    normalized_time_from: str | None = None,
    normalized_time_to: str | None = None,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Use prefix discovery plus one recent reserve without widening persistence."""
    primary, primary_windows = live_tail_semantic_discover_windows(
        snapshot,
        terms=terms,
        query=query,
        normalized_time_from=normalized_time_from,
        normalized_time_to=normalized_time_to,
    )
    if (
        primary.get("status") != "truncated"
        or int_value(primary.get("scan_end_offset"))
        >= int_value(snapshot.get("scan_end_offset"))
    ):
        return primary, primary_windows
    recent_snapshot = live_tail_semantic_recent_reserve_snapshot(
        snapshot,
        primary,
    )
    if recent_snapshot is None:
        return primary, primary_windows
    recent, _recent_windows = live_tail_semantic_discover_windows(
        recent_snapshot,
        terms=terms,
        query=query,
        normalized_time_from=normalized_time_from,
        normalized_time_to=normalized_time_to,
        budget_ms=LIVE_TAIL_SEMANTIC_RECENT_RESERVE_BUDGET_MS,
    )
    return live_tail_semantic_merge_discovery_reserve(
        snapshot,
        primary,
        recent,
    )


def iter_live_tail_complete_lines(
    snapshot: dict[str, Any],
    scan: dict[str, Any],
) -> Iterable[tuple[int, str, int, int]]:
    source_path = Path(str(snapshot.get("live_source_path") or ""))
    start_offset = int_value(snapshot.get("scan_start_offset"))
    end_offset = int_value(snapshot.get("scan_end_offset"))
    max_lines = int_value(snapshot.get("max_lines"), LIVE_TAIL_SEARCH_DEFAULT_MAX_LINES)
    scan_budget_ms = max(
        1,
        int_value(snapshot.get("scan_budget_ms"), LIVE_TAIL_SEARCH_SCAN_BUDGET_MS),
    )
    started = time.monotonic()
    line_no = int_value(
        snapshot.get("scan_line_base_count"),
        int_value(snapshot.get("archived_line_count")),
    )
    scan.update(
        {
            "status": "scanning",
            "bytes_read": 0,
            "complete_line_count": 0,
            "first_line": line_no + 1,
            "last_line": line_no,
            "line_budget_exhausted": False,
            "time_budget_exhausted": False,
            "incomplete_final_line_skipped": False,
            "scan_end_offset": start_offset,
            "budget_ms": scan_budget_ms,
            "elapsed_ms": 0,
        }
    )
    with source_path.open("rb") as handle:
        handle.seek(start_offset)
        while handle.tell() < end_offset:
            elapsed_ms = int((time.monotonic() - started) * 1000)
            if scan["complete_line_count"] > 0 and elapsed_ms >= scan_budget_ms:
                scan["time_budget_exhausted"] = True
                scan["elapsed_ms"] = elapsed_ms
                break
            if scan["complete_line_count"] >= max_lines:
                scan["line_budget_exhausted"] = True
                break
            line_offset = handle.tell()
            remaining = end_offset - line_offset
            raw_bytes = handle.readline(remaining)
            if not raw_bytes:
                break
            if not raw_bytes.endswith(b"\n"):
                scan["incomplete_final_line_skipped"] = True
                scan["incomplete_final_line_bytes"] = len(raw_bytes)
                break
            line_no += 1
            scan["bytes_read"] += len(raw_bytes)
            scan["complete_line_count"] += 1
            scan["last_line"] = line_no
            scan["scan_end_offset"] = handle.tell()
            yield (
                line_no,
                raw_bytes[:-1].decode("utf-8", errors="replace"),
                line_offset,
                len(raw_bytes),
            )
    scan["elapsed_ms"] = int((time.monotonic() - started) * 1000)
    if scan.get("line_budget_exhausted") or scan.get("time_budget_exhausted"):
        scan["status"] = "truncated"
    elif scan.get("incomplete_final_line_skipped"):
        scan["status"] = "snapshot_complete_lines_only"
    else:
        scan["status"] = "complete"


def finalize_live_tail_scan(snapshot: dict[str, Any], scan: dict[str, Any]) -> dict[str, Any]:
    source_path = Path(str(snapshot.get("live_source_path") or ""))
    diagnostics: list[str] = []
    try:
        current = source_path.stat()
    except OSError as exc:
        return {
            **scan,
            "ok": False,
            "status": "unresolved",
            "diagnostics": [f"live_tail_post_scan_stat_failed:{exc}"],
        }
    same_file = bool(
        current.st_dev == int_value(snapshot.get("source_device"), -1)
        and current.st_ino == int_value(snapshot.get("source_inode"), -1)
        and current.st_size >= int_value(snapshot.get("snapshot_end_offset"))
    )
    if not same_file:
        diagnostics.append("live_tail_source_replaced_or_truncated_during_scan")
    if snapshot.get("byte_truncated"):
        diagnostics.append("live_tail_byte_budget_truncated")
    if scan.get("line_budget_exhausted"):
        diagnostics.append("live_tail_line_budget_truncated")
    if scan.get("time_budget_exhausted"):
        diagnostics.append("live_tail_time_budget_truncated")
    if scan.get("incomplete_final_line_skipped"):
        diagnostics.append("live_tail_incomplete_snapshot_final_line_skipped")
    truncated = bool(
        snapshot.get("byte_truncated")
        or scan.get("line_budget_exhausted")
        or scan.get("time_budget_exhausted")
    )
    return {
        **scan,
        "ok": same_file,
        "status": "unresolved" if not same_file else ("truncated" if truncated else "complete"),
        "truncated": truncated,
        "source_grew_after_snapshot": current.st_size > int_value(snapshot.get("snapshot_end_offset")),
        "source_size_after_scan": current.st_size,
        "captured_snapshot_end_offset": int_value(snapshot.get("snapshot_end_offset")),
        "diagnostics": diagnostics,
    }


def finalize_live_tail_semantic_window_scans(
    snapshot: dict[str, Any],
    discovery: dict[str, Any],
    window_scans: list[dict[str, Any]],
) -> dict[str, Any]:
    source_path = Path(str(snapshot.get("live_source_path") or ""))
    diagnostics = list(discovery.get("diagnostics") or [])
    try:
        current = source_path.stat()
    except OSError as exc:
        return {
            "ok": False,
            "status": "unresolved",
            "truncated": True,
            "diagnostics": [
                *diagnostics,
                f"live_tail_post_scan_stat_failed:{exc}",
            ],
        }
    same_file = bool(
        current.st_dev == int_value(snapshot.get("source_device"), -1)
        and current.st_ino == int_value(snapshot.get("source_inode"), -1)
        and current.st_size >= int_value(snapshot.get("snapshot_end_offset"))
    )
    if not same_file:
        diagnostics.append("live_tail_source_replaced_or_truncated_during_scan")
    selected_window_count = int_value(discovery.get("selected_window_count"))
    hydrated_window_count = len(window_scans)
    hydration_truncated = False
    for item in window_scans:
        if (
            item.get("status") == "truncated"
            or item.get("time_budget_exhausted")
            or item.get("line_budget_exhausted")
        ):
            hydration_truncated = True
        diagnostics.extend(str(value) for value in item.get("diagnostics", []) if value)
    if hydrated_window_count < selected_window_count:
        hydration_truncated = True
        diagnostics.append(
            "live_tail_semantic_hydration_budget_left_selected_windows_unread:"
            f"{selected_window_count - hydrated_window_count}"
        )
    if snapshot.get("byte_truncated"):
        diagnostics.append("live_tail_byte_budget_truncated")
    if hydration_truncated:
        diagnostics.append("live_tail_semantic_hydration_truncated")
    candidate_coverage_exhaustive = bool(
        discovery.get("candidate_coverage_exhaustive")
        and not hydration_truncated
        and hydrated_window_count == selected_window_count
    )
    truncated = bool(
        snapshot.get("byte_truncated")
        or discovery.get("status") == "truncated"
        or not candidate_coverage_exhaustive
    )
    attempted_first_lines = [
        int_value(item.get("first_line"))
        for item in window_scans
        if int_value(item.get("complete_line_count")) > 0
    ]
    attempted_last_lines = [
        int_value(item.get("last_line"))
        for item in window_scans
        if int_value(item.get("complete_line_count")) > 0
    ]
    return {
        "ok": same_file,
        "status": (
            "unresolved"
            if not same_file
            else "truncated"
            if truncated
            else "complete"
        ),
        "truncated": truncated,
        "candidate_coverage_exhaustive": candidate_coverage_exhaustive,
        "first_line": (
            min(attempted_first_lines)
            if attempted_first_lines
            else int_value(discovery.get("first_line"))
        ),
        "last_line": (
            max(attempted_last_lines)
            if attempted_last_lines
            else int_value(discovery.get("last_line"))
        ),
        "complete_line_count": sum(
            int_value(item.get("complete_line_count"))
            for item in window_scans
        ),
        "bytes_read": sum(int_value(item.get("bytes_read")) for item in window_scans),
        "scan_end_offset": max(
            (
                int_value(item.get("scan_end_offset"))
                for item in window_scans
            ),
            default=int_value(discovery.get("scan_end_offset")),
        ),
        "selected_window_count": selected_window_count,
        "hydrated_window_count": hydrated_window_count,
        "window_scans": window_scans,
        "line_budget_exhausted": any(
            bool(item.get("line_budget_exhausted"))
            for item in window_scans
        ),
        "time_budget_exhausted": any(
            bool(item.get("time_budget_exhausted"))
            for item in window_scans
        ),
        "budget_ms": LIVE_TAIL_SEMANTIC_HYDRATION_BUDGET_MS,
        "elapsed_ms": sum(
            int_value(item.get("elapsed_ms"))
            for item in window_scans
        ),
        "source_grew_after_snapshot": (
            current.st_size > int_value(snapshot.get("snapshot_end_offset"))
        ),
        "source_size_after_scan": current.st_size,
        "captured_snapshot_end_offset": int_value(
            snapshot.get("snapshot_end_offset")
        ),
        "semantic_window_selection": {
            "strategy": str(discovery.get("strategy") or ""),
            "status": str(discovery.get("status") or ""),
            "candidate_coverage_exhaustive": candidate_coverage_exhaustive,
            "structural_episode_count": int_value(
                discovery.get("structural_episode_count")
            ),
            "query_hit_episode_count": int_value(
                discovery.get("query_hit_episode_count")
            ),
            "selected_window_count": selected_window_count,
            "hydrated_window_count": hydrated_window_count,
            "omitted_query_hit_episode_count": int_value(
                discovery.get("omitted_query_hit_episode_count")
            ),
        },
        "diagnostics": list(dict.fromkeys(diagnostics)),
    }


def live_tail_fallback_status(payload: dict[str, Any], *, candidate_count: int) -> str:
    """Describe fallback evidence without treating a bounded partial scan as exhaustive."""
    snapshot = payload.get("snapshot") if isinstance(payload.get("snapshot"), dict) else {}
    scan = payload.get("scan") if isinstance(payload.get("scan"), dict) else {}
    snapshot_status = str(snapshot.get("status") or "")
    scan_status = str(scan.get("status") or "")
    if snapshot_status == "no_unarchived_tail":
        return "no_unarchived_tail"
    if not payload.get("ok"):
        if snapshot_status == "deferred_prefix_validation":
            return snapshot_status
        if scan_status == "unresolved":
            return "unresolved"
        return snapshot_status or scan_status or "unresolved"
    truncated = bool(
        snapshot_status == "truncated"
        or scan_status == "truncated"
        or scan.get("truncated")
    )
    if candidate_count > 0:
        return "applied_truncated" if truncated else "applied"
    return "truncated_without_match" if truncated else "no_matching_live_evidence"


def live_tail_fallback_reason(status: str) -> str:
    reasons = {
        "applied": (
            "session-scoped archive projection trails a proven append-only live source; "
            "the captured complete-line tail produced matching candidates"
        ),
        "applied_truncated": (
            "session-scoped archive projection trails a proven append-only live source; "
            "matching candidates were observed, but the byte, line, or time budget truncated the scan"
        ),
        "truncated_without_match": (
            "the bounded live-tail scan ended before the captured snapshot was exhausted; "
            "no match was observed in the scanned portion, so absence is not established"
        ),
        "no_matching_live_evidence": (
            "the captured complete-line append-only live-tail snapshot was scanned without a matching candidate"
        ),
        "no_unarchived_tail": "the archived projection already covers the captured live source",
        "deferred_prefix_validation": (
            "live-tail append-only validation exceeded the bounded prefix budget; archive remains stale-readable"
        ),
        "unresolved": "live-tail fallback could not establish a stable readable snapshot",
    }
    return reasons.get(status, "live-tail fallback could not establish supported current evidence")


def live_tail_result_freshness(snapshot: dict[str, Any], scan: dict[str, Any]) -> dict[str, Any]:
    truncated = bool(snapshot.get("byte_truncated") or scan.get("truncated"))
    persistent_overlay = bool(snapshot.get("persistent_overlay"))
    return {
        "status": "truncated" if truncated else "fallback",
        "basis": (
            "persistent_capture_ledger_with_attested_archived_prefix"
            if persistent_overlay
            else "read_only_append_snapshot_with_full_archived_prefix_sha256"
        ),
        "persistent_overlay": persistent_overlay,
        "archive_projection_status": "stale-readable",
        "projection_freshness_status": str((snapshot.get("projection_freshness") or {}).get("status") or "unverifiable"),
        "live_source_snapshot_status": "current_at_captured_end_offset",
        "evidence_lifecycle": "live_source_unarchived",
        "snapshot_id": str(snapshot.get("snapshot_id") or ""),
        "snapshot_end_offset": int_value(snapshot.get("snapshot_end_offset")),
        "source_grew_after_snapshot": bool(scan.get("source_grew_after_snapshot")),
        "truncated": truncated,
        "readability": "raw_live_source_refs_available",
    }


def live_tail_event_refs(snapshot: dict[str, Any], line_no: int) -> dict[str, Any]:
    return {
        "session": str(snapshot.get("manifest_path") or ""),
        "raw": f"raw:line:{line_no}",
        "raw_path": str(snapshot.get("live_source_path") or ""),
        "live_source": {
            "path": str(snapshot.get("live_source_path") or ""),
            "line": line_no,
            "snapshot_id": str(snapshot.get("snapshot_id") or ""),
        },
    }


LIVE_TAIL_EXACT_EVENT_WEIGHTS = {
    "FILE_WRITE": 150.0,
    "DIFF": 150.0,
    "FILE_READ": 145.0,
    "COMMAND": 140.0,
    "TOOL_CALL": 138.0,
    "VERIFICATION": 132.0,
    "COMMAND_OUTPUT": 125.0,
    "TOOL_OUTPUT": 125.0,
    "ERROR": 120.0,
    "USER_INTENT": 110.0,
    "DECISION": 108.0,
    "ASSISTANT_MESSAGE": 100.0,
    "ASSISTANT_PLAN": 92.0,
    "ASSISTANT_REASONING_BOUNDARY": 70.0,
}


def live_tail_exact_event_score(
    event: RawEvent,
    *,
    needle: str,
    raw: str,
    query_class: str = "",
) -> tuple[float, dict[str, Any]]:
    semantic = event_semantic_text(event)
    semantic_match = bool(needle and needle.casefold() in semantic.casefold())
    source_lane = task_episode_source_lane(event)
    score = LIVE_TAIL_EXACT_EVENT_WEIGHTS.get(event.event_type, 40.0)
    query_intent_adjustment = 0.0
    if query_class == "command":
        if event.event_type == "COMMAND":
            query_intent_adjustment = 60.0
        elif event.event_type in {"DIFF", "FILE_WRITE", "FILE_READ"}:
            query_intent_adjustment = -30.0
    score += query_intent_adjustment
    if semantic_match:
        score += 45.0
    if event.source_type == "response_item":
        score += 15.0
    if event.correlation_id:
        score += 8.0
    if source_lane in {"message_system", "message_developer", "generated_context_summary"}:
        score -= 120.0
    if isinstance(event.facets.get("structured_skill_input"), dict):
        score -= 100.0
    raw_chars = len(raw)
    output_dump_penalty = 0.0
    if event.event_type in {"TOOL_OUTPUT", "COMMAND_OUTPUT"}:
        if raw_chars > 64_000:
            output_dump_penalty = 160.0
        elif raw_chars > 16_000:
            output_dump_penalty = 120.0
        elif raw_chars > 4_000:
            output_dump_penalty = 80.0
        score -= output_dump_penalty
    occurrence_count = raw.casefold().count(needle.casefold()) if needle else 0
    score += min(12.0, float(occurrence_count) * 2.0)
    return score, {
        "semantic_match": semantic_match,
        "source_lane": source_lane,
        "occurrence_count": occurrence_count,
        "raw_chars": raw_chars,
        "output_dump_penalty": output_dump_penalty,
        "query_class": query_class,
        "query_intent_adjustment": query_intent_adjustment,
    }


def exact_raw_event_evidence_text(
    event: RawEvent,
    raw_line: str,
    retrieval_control_by_correlation: dict[str, str],
) -> str:
    """Remove transport/query echoes while keeping their structured evidence."""
    retrieval_command = task_episode_retrieval_control_command(event)
    if retrieval_command and event.correlation_id:
        retrieval_control_by_correlation[str(event.correlation_id)] = retrieval_command
    linked_retrieval_command = retrieval_control_by_correlation.get(str(event.correlation_id or ""), "")
    structured_correlation = (
        f"; correlation_id={event.correlation_id}"
        if event.correlation_id
        else ""
    )
    if retrieval_command:
        return (
            f"{TASK_EPISODE_RETRIEVAL_CONTROL_PREFIX} invocation: "
            f"{retrieval_command}{structured_correlation}"
        )
    payload = task_episode_payload(event)
    correlated_transport_echo = bool(
        event.source_type == "event_msg"
        and str(payload.get("type") or "").startswith("mcp_tool_call_")
    )
    if linked_retrieval_command and (
        task_episode_is_structured_result(event)
        or correlated_transport_echo
    ):
        return (
            f"{TASK_EPISODE_RETRIEVAL_CONTROL_PREFIX} result: {linked_retrieval_command}; "
            f"outcome={event.outcome or 'observed'}{structured_correlation}"
        )
    if (
        event.source_type == "event_msg"
        and str(payload.get("type") or "") == "task_complete"
        and isinstance(payload.get("last_agent_message"), str)
    ):
        return json.dumps(
            {
                "type": event.source_type,
                "payload": {
                    key: value
                    for key, value in payload.items()
                    if key != "last_agent_message"
                },
            },
            ensure_ascii=False,
            sort_keys=True,
        )
    return raw_line


def exact_raw_event_is_completion_message_echo(event: RawEvent) -> bool:
    payload = (
        event.parsed.get("payload")
        if isinstance(event.parsed, dict)
        and isinstance(event.parsed.get("payload"), dict)
        else {}
    )
    return bool(
        event.source_type == "event_msg"
        and str(payload.get("type") or "") == "task_complete"
        and isinstance(payload.get("last_agent_message"), str)
    )


def exact_raw_event_is_generated_context_summary(event: RawEvent) -> bool:
    """Exclude compaction copies from exact occurrence candidates."""
    return task_episode_source_lane(event) == "generated_context_summary"


def exact_raw_ordered_token_phrase_pattern(
    query: str,
) -> re.Pattern[str] | None:
    plan = exact_literal_fts_query_plan_from_user(query)
    if str(plan.get("mode") or "") != "ordered_token_phrase":
        return None
    tokens = search_tokenize(query)[:16]
    if len(tokens) < 2:
        return None
    separator = r"(?:\\[nrt]|[\W_])+"
    return re.compile(
        r"(?<![^\W_])"
        + separator.join(re.escape(token) for token in tokens)
        + r"(?![^\W_])",
        flags=re.IGNORECASE,
    )


def exact_raw_ordered_token_phrase_anchor(query: str) -> str:
    plan = exact_literal_fts_query_plan_from_user(query)
    if str(plan.get("mode") or "") != "ordered_token_phrase":
        return ""
    tokens = search_tokenize(query)[:16]
    if len(tokens) < 2:
        return ""
    return max(tokens, key=lambda token: (len(token), token.casefold())).casefold()


def exact_raw_query_match_mode(
    text: str,
    *,
    needle: str,
    ordered_token_phrase_pattern: re.Pattern[str] | None,
    ordered_token_phrase_anchor: str = "",
) -> str:
    value = str(text or "")
    folded = value.casefold()
    if needle and needle.casefold() in folded:
        return "literal_substring"
    if (
        ordered_token_phrase_pattern is not None
        and (
            not ordered_token_phrase_anchor
            or ordered_token_phrase_anchor in folded
        )
        and ordered_token_phrase_pattern.search(value)
    ):
        return "ordered_token_phrase"
    return ""


EXACT_EVENT_DATE_FILTER_BASIS = "event_timestamp_with_session_date_fallback"


def query_date_filter_contract(
    date_from: str | None,
    date_to: str | None,
) -> dict[str, Any]:
    return {
        "requested": bool(date_from or date_to),
        "date_from": parse_date_arg(date_from) if date_from else "",
        "date_to": parse_date_arg(date_to) if date_to else "",
        "basis_by_evidence_grain": {
            "exact_event": EXACT_EVENT_DATE_FILTER_BASIS,
            "session_document": "session_date",
            "episode": "episode_time_span_overlap_with_session_date_fallback",
        },
        "truth_status": "route_filter_contract_not_execution_evidence",
    }


def query_time_filter_contract(
    time_from: str | None,
    time_to: str | None,
) -> dict[str, Any]:
    return {
        "requested": bool(time_from or time_to),
        "time_from": parse_timestamp_arg(time_from) if time_from else "",
        "time_to": parse_timestamp_arg(time_to) if time_to else "",
        "basis_by_evidence_grain": {
            "episode": (
                "episode_time_span_overlap_then_session_scoped_event_timestamp_"
                "evidence_gate"
            ),
        },
        "session_scope_required_for_answer_admission": bool(
            time_from or time_to
        ),
        "unsupported_fallback_grains": [
            "general_session_document",
            "unscoped_raw_text",
        ],
        "truth_status": "route_filter_contract_not_execution_evidence",
    }


def exact_event_date_filter_decision(
    *,
    event_timestamp: str | None,
    session_date: str,
    date_from: str | None,
    date_to: str | None,
) -> dict[str, Any]:
    event_date = ""
    if event_timestamp:
        try:
            event_date = str(parse_timestamp_arg(event_timestamp) or "")[:10]
        except ValueError:
            event_date = ""
    source = "event_timestamp" if event_date else "session_date_fallback"
    comparable_date = event_date or str(session_date or "")
    accepted = bool(
        not comparable_date
        or (
            (not date_from or comparable_date >= date_from)
            and (not date_to or comparable_date <= date_to)
        )
    )
    return {
        "accepted": accepted,
        "date": comparable_date,
        "source": source,
        "basis": EXACT_EVENT_DATE_FILTER_BASIS,
    }


def normalize_exact_event_id_before(value: str | None) -> str:
    normalized = str(value or "").strip()
    if normalized.isdigit():
        return normalized.zfill(6)
    return normalized


def exact_raw_event_structured_filter_rejections(
    event: RawEvent,
    *,
    event_id_before: str | None = None,
    event_type: str | None = None,
    family: str | None = None,
    outcome: str | None = None,
    exclude_agent_event_stream_copies: bool = False,
) -> list[str]:
    """Apply evidence-scope filters before any bounded candidate ranking."""
    rejections: list[str] = []
    normalized_event_id_before = normalize_exact_event_id_before(
        event_id_before
    )
    if (
        normalized_event_id_before
        and str(event.event_id or "") >= normalized_event_id_before
    ):
        rejections.append("event_id_before")
    for key, requested, observed in (
        ("event_type", event_type, event.event_type),
        ("family", family, event.family),
        ("outcome", outcome, event.outcome),
    ):
        if requested and str(observed or "") != str(requested):
            rejections.append(key)
    if exclude_agent_event_stream_copies and (
        "agent_event_source:event_msg_stream" in event.tags
        or task_episode_source_lane(event) == "event_msg_stream"
    ):
        rejections.append("agent_event_stream_copy")
    return rejections


def exact_raw_structured_filter_packet(
    *,
    event_id_before: str | None,
    event_type: str | None,
    family: str | None,
    outcome: str | None,
    exclude_agent_event_stream_copies: bool,
    rejected_candidate_count: int,
    rejection_counts: dict[str, int],
) -> dict[str, Any]:
    requested = {
        "event_id_before": normalize_exact_event_id_before(
            event_id_before
        ),
        "event_type": str(event_type or ""),
        "family": str(family or ""),
        "outcome": str(outcome or ""),
        "exclude_agent_event_stream_copies": bool(
            exclude_agent_event_stream_copies
        ),
    }
    applied = bool(
        any(
            (
                requested["event_id_before"],
                requested["event_type"],
                requested["family"],
                requested["outcome"],
                requested["exclude_agent_event_stream_copies"],
            )
        )
    )
    normalized_counts = {
        str(key): int_value(value)
        for key, value in sorted(rejection_counts.items())
        if int_value(value) > 0
    }
    return {
        "requested": requested,
        "applied": applied,
        "placement": "before_bounded_candidate_ranking",
        "rejected_candidate_count": int_value(
            rejected_candidate_count
        ),
        "rejection_counts": normalized_counts,
        "truth_status": (
            "raw_event_scope_filter_applied_before_candidate_bound"
            if applied
            else "no_raw_event_scope_filter_requested"
        ),
    }


def bounded_exact_candidate_append(
    candidates: list[dict[str, Any]],
    candidate: dict[str, Any],
    *,
    max_candidates: int,
) -> None:
    if len(candidates) < max_candidates:
        candidates.append(candidate)
        return
    weakest_index = min(
        range(len(candidates)),
        key=lambda index: (
            float(candidates[index].get("match_score") or 0.0),
            -int_value(candidates[index].get("raw_line")),
        ),
    )
    weakest = candidates[weakest_index]
    if (
        float(candidate.get("match_score") or 0.0),
        -int_value(candidate.get("raw_line")),
    ) > (
        float(weakest.get("match_score") or 0.0),
        -int_value(weakest.get("raw_line")),
    ):
        candidates[weakest_index] = candidate


def live_tail_exact_deduplicate_mirrored_messages(
    candidates: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], int]:
    """Collapse adjacent event_msg/response_item copies of one assistant text."""
    ordered = sorted(
        (dict(candidate) for candidate in candidates),
        key=lambda item: int_value(item.get("raw_line")),
    )
    deduplicated: list[dict[str, Any]] = []
    collapsed_count = 0
    for candidate in ordered:
        previous = deduplicated[-1] if deduplicated else None
        is_mirror = bool(
            isinstance(previous, dict)
            and {
                str(previous.get("source_type") or ""),
                str(candidate.get("source_type") or ""),
            }
            == {"event_msg", "response_item"}
            and str(previous.get("preview") or "")
            == str(candidate.get("preview") or "")
            and 0
            < int_value(candidate.get("raw_line"))
            - int_value(previous.get("raw_line"))
            <= 2
        )
        if not is_mirror:
            deduplicated.append(candidate)
            continue
        winner = next(
            item
            for item in (previous, candidate)
            if str(item.get("source_type") or "") == "response_item"
        )
        mirror = candidate if winner is previous else previous
        merged = dict(winner)
        raw_refs = list(
            dict.fromkeys(
                str((item.get("refs") or {}).get("raw") or "")
                for item in (previous, candidate)
                if isinstance(item.get("refs"), dict)
                and (item.get("refs") or {}).get("raw")
            )
        )
        merged["mirror_evidence"] = {
            "status": "adjacent_exact_assistant_message_mirror_collapsed",
            "basis": "identical_text_adjacent_event_msg_and_response_item",
            "raw_refs": raw_refs,
            "source_types": sorted(
                {
                    str(previous.get("source_type") or ""),
                    str(candidate.get("source_type") or ""),
                }
            ),
            "primary_raw_ref": str(
                (winner.get("refs") or {}).get("raw") or ""
            ),
            "mirrored_raw_ref": str(
                (mirror.get("refs") or {}).get("raw") or ""
            ),
        }
        deduplicated[-1] = merged
        collapsed_count += 1
    return deduplicated, collapsed_count


def live_tail_exact_search_from_persistent_postings(
    *,
    snapshot: dict[str, Any],
    needle: str,
    limit: int,
    event_id_before: str | None,
    event_type: str | None,
    family: str | None,
    outcome: str | None,
    date_from: str | None,
    date_to: str | None,
    exclude_agent_event_stream_copies: bool,
) -> dict[str, Any] | None:
    path = Path(
        str(snapshot.get("persistent_live_tail_postings") or "")
    )
    postings = read_json(path, {}) if path.is_file() else {}
    session_id = str(snapshot.get("session_id") or "")
    epoch_id = str(snapshot.get("ledger_epoch_id") or "")
    generation_identity = (
        persistent_live_tail_postings_generation_identity()
    )
    current_manifest = bool(
        isinstance(postings, dict)
        and int_value(postings.get("schema_version"))
        == PERSISTENT_LIVE_TAIL_POSTINGS_SCHEMA_VERSION
        and postings.get("artifact_type")
        == "persistent_live_tail_postings"
        and str(postings.get("session_id") or "") == session_id
        and str(postings.get("epoch_id") or "") == epoch_id
        and postings.get("generation_identity")
        == generation_identity
        and int_value(postings.get("source_captured_bytes"))
        == int_value(snapshot.get("snapshot_end_offset"))
    )
    predecessor_manifest = bool(
        isinstance(postings, dict)
        and int_value(postings.get("schema_version")) == 2
        and postings.get("artifact_type")
        == "persistent_live_tail_postings"
        and str(postings.get("session_id") or "") == session_id
        and str(postings.get("epoch_id") or "") == epoch_id
        and str(
            (
                postings.get("generation_identity")
                if isinstance(
                    postings.get("generation_identity"), dict
                )
                else {}
            ).get("generation_id")
            or ""
        )
        in PERSISTENT_LIVE_TAIL_POSTINGS_PREDECESSOR_GENERATION_IDS
        and int_value(postings.get("source_captured_bytes"))
        == int_value(snapshot.get("snapshot_end_offset"))
    )
    if not current_manifest and not predecessor_manifest:
        return None
    manifest_bytes = path.stat().st_size if path.is_file() else 0
    if current_manifest:
        expected_manifest_sha256 = str(
            snapshot.get(
                "persistent_live_tail_postings_sha256"
            )
            or ""
        )
        expected_manifest_bytes = int_value(
            snapshot.get("persistent_live_tail_postings_bytes"),
            -1,
        )
        if not (
            expected_manifest_sha256
            and expected_manifest_bytes == manifest_bytes
            and sha256_file_exact(path)
            == expected_manifest_sha256
        ):
            return None
    query_tokens = persistent_live_tail_safe_tokens(needle)
    if not query_tokens:
        return None
    archived_lines = int_value(snapshot.get("archived_line_count"))
    session_dir = path.parent.parent
    descriptors = (
        [
            dict(item)
            for item in postings.get("shards", [])
            if isinstance(item, dict)
        ]
        if current_manifest
        and isinstance(postings.get("shards"), list)
        else []
    )
    shard_payloads: list[tuple[dict[str, Any], dict[str, Any]]] = []
    if predecessor_manifest:
        shard_payloads.append(
            (
                {
                    "format": "legacy_monolith_v2_inline",
                    "ordinal": 0,
                    "bytes": manifest_bytes,
                },
                postings,
            )
        )
    entries: list[dict[str, Any]] = []
    candidate_position_count = 0
    shard_bytes_read = 0
    shard_count_examined = 0
    shard_descriptor_count_examined = 0
    shard_count_filtered = 0
    candidate_limit = max(32, max(1, limit) * 8)
    descriptor_iter = sorted(
        descriptors,
        key=lambda item: int_value(item.get("ordinal")),
        reverse=True,
    )
    for descriptor in descriptor_iter:
        if int_value(descriptor.get("to_line")) <= archived_lines:
            continue
        shard_descriptor_count_examined += 1
        if not persistent_live_tail_token_filter_might_contain(
            descriptor.get("token_filter"),
            query_tokens,
        ):
            shard_count_filtered += 1
            continue
        try:
            payload = read_persistent_live_tail_postings_descriptor(
                session_dir=session_dir,
                session_id=session_id,
                epoch_id=epoch_id,
                generation_identity=generation_identity,
                descriptor=descriptor,
            )
        except (OSError, ValueError):
            return None
        shard_payloads.append((descriptor, payload))
        token_postings = payload.get("token_postings")
        posting_entries = payload.get("entries")
        if not (
            isinstance(token_postings, dict)
            and isinstance(posting_entries, list)
        ):
            return None
        shard_count_examined += 1
        shard_bytes_read += int_value(descriptor.get("bytes"))
        candidate_positions: set[int] | None = None
        for token in query_tokens:
            positions = token_postings.get(token)
            if not isinstance(positions, list):
                candidate_positions = set()
                break
            normalized_positions = {
                int_value(position, -1)
                for position in positions
                if 0
                <= int_value(position, -1)
                < len(posting_entries)
            }
            candidate_positions = (
                normalized_positions
                if candidate_positions is None
                else candidate_positions & normalized_positions
            )
            if not candidate_positions:
                break
        candidate_position_count += len(candidate_positions or set())
        for position in sorted(
            candidate_positions or set(), reverse=True
        ):
            item = posting_entries[position]
            if (
                isinstance(item, dict)
                and int_value(item.get("line")) > archived_lines
            ):
                entries.append(item)
                if len(entries) >= candidate_limit:
                    break
        if len(entries) >= candidate_limit:
            break
    if predecessor_manifest:
        descriptor, payload = shard_payloads[0]
        token_postings = payload.get("token_postings")
        posting_entries = payload.get("entries")
        if not (
            isinstance(token_postings, dict)
            and isinstance(posting_entries, list)
        ):
            return None
        shard_count_examined = 1
        shard_bytes_read = manifest_bytes
        candidate_positions: set[int] | None = None
        for token in query_tokens:
            positions = token_postings.get(token)
            if not isinstance(positions, list):
                candidate_positions = set()
                break
            normalized_positions = {
                int_value(position, -1)
                for position in positions
                if 0 <= int_value(position, -1) < len(posting_entries)
            }
            candidate_positions = (
                normalized_positions
                if candidate_positions is None
                else candidate_positions & normalized_positions
            )
            if not candidate_positions:
                break
        candidate_position_count = len(candidate_positions or set())
        entries = [
            posting_entries[position]
            for position in sorted(
                candidate_positions or set(), reverse=True
            )
            if isinstance(posting_entries[position], dict)
            and int_value(posting_entries[position].get("line"))
            > archived_lines
        ][:candidate_limit]
    if not entries:
        return None
    source_path = Path(str(snapshot.get("live_source_path") or ""))
    if not source_path.is_file():
        return None
    normalized_date_from = parse_date_arg(date_from) if date_from else None
    normalized_date_to = parse_date_arg(date_to) if date_to else None
    ordered_pattern = exact_raw_ordered_token_phrase_pattern(needle)
    ordered_anchor = exact_raw_ordered_token_phrase_anchor(needle)
    results: list[dict[str, Any]] = []
    bytes_read = 0
    for posting in entries:
        byte_offset = int_value(posting.get("byte_offset"), -1)
        byte_count = int_value(posting.get("byte_count"), 0)
        if (
            byte_offset < int_value(snapshot.get("scan_start_offset"))
            or byte_count <= 0
            or byte_offset + byte_count
            > int_value(snapshot.get("snapshot_end_offset"))
        ):
            continue
        with source_path.open("rb") as handle:
            handle.seek(byte_offset)
            raw_bytes = handle.read(byte_count)
        bytes_read += len(raw_bytes)
        if len(raw_bytes) != byte_count or not raw_bytes.endswith(b"\n"):
            continue
        raw_line = raw_bytes[:-1].decode("utf-8", errors="replace")
        try:
            loaded = json.loads(raw_line)
            parsed = loaded if isinstance(loaded, dict) else None
        except json.JSONDecodeError:
            parsed = None
        line_no = int_value(posting.get("line"))
        event = classify_raw_event(raw_line, parsed, line_no)
        evidence_text = exact_raw_event_evidence_text(
            event,
            raw_line,
            {},
        )
        match_mode = exact_raw_query_match_mode(
            evidence_text,
            needle=needle,
            ordered_token_phrase_pattern=ordered_pattern,
            ordered_token_phrase_anchor=ordered_anchor,
        )
        if not match_mode:
            continue
        if exact_raw_event_structured_filter_rejections(
            event,
            event_id_before=event_id_before,
            event_type=event_type,
            family=family,
            outcome=outcome,
            exclude_agent_event_stream_copies=(
                exclude_agent_event_stream_copies
            ),
        ):
            continue
        date_filter = exact_event_date_filter_decision(
            event_timestamp=event.timestamp,
            session_date=str(snapshot.get("session_date") or ""),
            date_from=normalized_date_from,
            date_to=normalized_date_to,
        )
        if not date_filter["accepted"]:
            continue
        score, _match = live_tail_exact_event_score(
            event,
            needle=needle,
            raw=raw_line,
            query_class=str(
                literal_query_shape(needle).get("primary") or ""
            ),
        )
        refs = live_tail_event_refs(snapshot, line_no)
        results.append(
            {
                "rank": -round(score, 4),
                "match_score": round(score, 4),
                "match_channel": (
                    "persistent_live_tail_posting_verified_raw"
                ),
                "raw_query_match_mode": match_mode,
                "doc_id": (
                    f"live-event:{snapshot.get('session_id')}:"
                    f"{event.event_id}"
                ),
                "doc_type": "event",
                "session_id": str(snapshot.get("session_id") or ""),
                "session_label": str(
                    snapshot.get("session_label") or ""
                ),
                "session_title": str(
                    snapshot.get("session_title") or ""
                ),
                "session_date": str(
                    snapshot.get("session_date") or ""
                ),
                "archive_status": "live_source_unarchived",
                "event_id": event.event_id,
                "raw_line": line_no,
                "event_type": event.event_type,
                "source_type": event.source_type,
                "family": event.family,
                "phase": event.phase,
                "actor": event.actor,
                "action": event.action,
                "outcome": event.outcome,
                "correlation_id": event.correlation_id or "",
                "timestamp": event.timestamp or "",
                "date_filter": date_filter,
                "title": str(
                    posting.get("event_type") or event.event_type
                ),
                "preview": str(posting.get("preview") or ""),
                "refs": refs,
                "raw_ref": refs["raw"],
                "raw_path": refs["raw_path"],
                "session_ref": refs["session"],
                "byte_offset": byte_offset,
                "byte_count": byte_count,
                "freshness": {
                    "status": "current_at_captured_watermark",
                    "returned_evidence_current": True,
                    "global_recall_complete": False,
                },
            }
        )
        if len(results) >= max(1, limit * 3):
            break
    if not results:
        return None
    results.sort(
        key=lambda item: (
            float(item.get("rank") or 0),
            -int_value(item.get("raw_line")),
        )
    )
    return {
        "results": results[: max(1, limit)],
        "scan": {
            "status": "persistent_postings_selected_raw_verification",
            "bytes_read": bytes_read,
            "posting_entry_count": int_value(
                postings.get("entry_count")
            ),
            "posting_candidate_count": len(entries),
            "posting_entries_examined": candidate_position_count,
            "posting_manifest_bytes_read": manifest_bytes,
            "posting_shards_examined": shard_count_examined,
            "posting_shard_descriptors_examined": (
                shard_descriptor_count_examined
            ),
            "posting_shards_filtered_without_read": (
                shard_count_filtered
            ),
            "posting_shard_bytes_read": shard_bytes_read,
            "posting_storage_mode": (
                "bounded_json_shards_v1"
                if current_manifest
                else "legacy_monolith_v2_predecessor"
            ),
            "posting_full_scan_performed": False,
            "candidate_selection": "inverted_token_intersection",
            "raw_verified_result_count": len(results),
            "global_recall_complete": False,
        },
        "postings_path": str(path),
    }


def live_tail_exact_search(
    *,
    aoa_root: Path,
    session: str,
    query: str,
    limit: int = 20,
    event_id_before: str | None = None,
    event_type: str | None = None,
    family: str | None = None,
    outcome: str | None = None,
    date_from: str | None = None,
    date_to: str | None = None,
    exclude_agent_event_stream_copies: bool = False,
    max_delta_bytes: int | None = None,
    max_lines: int | None = None,
    explain: bool = False,
) -> dict[str, Any]:
    started = time.monotonic()
    needle = str(query or "").strip().strip("`'\"")
    if not needle:
        return {
            "schema_version": LIVE_TAIL_SEARCH_SCHEMA_VERSION,
            "artifact_type": "live_tail_exact_search_results",
            "generated_at": utc_now(),
            "ok": False,
            "query": query,
            "result_count": 0,
            "results": [],
            "diagnostics": ["live_tail_exact_query_empty"],
        }
    query_projection = derived_text_privacy_projection(
        needle,
        max_chars=700,
    )
    safe_query = str(query_projection.get("text") or "")
    if query_projection.get("redaction_count"):
        return {
            "schema_version": LIVE_TAIL_SEARCH_SCHEMA_VERSION,
            "artifact_type": "live_tail_exact_search_results",
            "generated_at": utc_now(),
            "ok": True,
            "mutates": False,
            "query": safe_query,
            "normalized_query": safe_query,
            "session": session,
            "route": {
                "id": "read_only_live_tail_exact_fallback",
                "status": "blocked_before_raw_scan",
                "reason": (
                    "credential-like literal queries are not admitted to "
                    "raw transcript scans"
                ),
                "authority": "derived_text_privacy_policy",
            },
            "scan": {
                "status": "blocked_before_raw_scan",
                "bytes_read": 0,
                "complete_line_count": 0,
            },
            "result_count": 0,
            "results": [],
            "abstention": {
                "status": "sensitive_literal_query_blocked",
                "reason": (
                    "query contains a credential-like literal; search by its "
                    "non-secret label or another evidence anchor"
                ),
            },
            "derived_text_privacy": derived_text_privacy_metadata(
                query_projection
            ),
            "diagnostics": [
                "sensitive_literal_query_blocked_before_raw_scan"
            ],
            "elapsed_ms": int((time.monotonic() - started) * 1000),
            "truth_status": (
                "credential_literal_withheld_and_raw_scan_not_started"
            ),
        }
    snapshot = session_live_tail_source_snapshot(
        aoa_root=aoa_root,
        session=session,
        max_delta_bytes=max_delta_bytes,
        max_lines=max_lines,
    )
    if not snapshot.get("ok") or snapshot.get("status") == "no_unarchived_tail":
        snapshot_status = str(snapshot.get("status") or "unresolved")
        deferred_prefix = snapshot_status == "deferred_prefix_validation"
        return {
            "schema_version": LIVE_TAIL_SEARCH_SCHEMA_VERSION,
            "artifact_type": "live_tail_exact_search_results",
            "generated_at": utc_now(),
            "ok": bool(snapshot.get("ok")),
            "query": query,
            "normalized_query": needle,
            "session": session,
            "snapshot": snapshot,
            "result_count": 0,
            "results": [],
            "abstention": {
                "status": (
                    "no_unarchived_tail"
                    if snapshot_status == "no_unarchived_tail"
                    else snapshot_status if deferred_prefix else "unresolved"
                ),
                "reason": (
                    ""
                    if snapshot_status == "no_unarchived_tail"
                    else "synchronous prefix validation exceeded the bounded query budget; archive remains stale-readable"
                    if deferred_prefix
                    else "live source snapshot could not be proven append-only"
                ),
            },
            "diagnostics": list(snapshot.get("diagnostics") or []),
            "elapsed_ms": int((time.monotonic() - started) * 1000),
            "cost_profile": {
                "snapshot_elapsed_ms": int_value(snapshot.get("elapsed_ms")),
                "prefix_hash_budget_ms": LIVE_TAIL_SEARCH_PREFIX_HASH_BUDGET_MS,
                "bounded_prefix_validation": True,
            },
        }
    posting_result = live_tail_exact_search_from_persistent_postings(
        snapshot=snapshot,
        needle=needle,
        limit=max(1, min(100, int_value(limit, 20))),
        event_id_before=event_id_before,
        event_type=event_type,
        family=family,
        outcome=outcome,
        date_from=date_from,
        date_to=date_to,
        exclude_agent_event_stream_copies=(
            exclude_agent_event_stream_copies
        ),
    )
    if posting_result is not None:
        posting_results = [
            redact_derived_value(item)
            for item in posting_result.get("results", [])
            if isinstance(item, dict)
        ]
        return {
            "schema_version": LIVE_TAIL_SEARCH_SCHEMA_VERSION,
            "artifact_type": "live_tail_exact_search_results",
            "generated_at": utc_now(),
            "ok": True,
            "mutates": False,
            "query": safe_query,
            "normalized_query": needle,
            "session": session,
            "route": {
                "id": "persistent_live_tail_postings",
                "reason": (
                    "safe persistent posting selected bounded raw refs; "
                    "only returned lines were reread and verified"
                ),
                "authority": "captured_raw_line_verification",
            },
            "snapshot": snapshot,
            "scan": posting_result["scan"],
            "result_count": len(posting_results),
            "results": posting_results,
            "abstention": {
                "status": "exact_live_evidence_available",
                "reason": "",
            },
            "cost_profile": {
                "prefix_bytes_hashed": 0,
                "tail_bytes_read": int_value(
                    posting_result["scan"].get("bytes_read")
                ),
                "tail_lines_read": len(posting_results),
                "persistent_index_written": True,
                "persistent_postings_path": posting_result.get(
                    "postings_path"
                ),
                "global_recall_complete": False,
            },
            "elapsed_ms": int(
                (time.monotonic() - started) * 1000
            ),
            "diagnostics": [],
            "truth_status": (
                "verified_live_raw_evidence_current_global_recall_incomplete"
            ),
        }
    session_date = str(snapshot.get("session_date") or "")
    normalized_date_from = parse_date_arg(date_from) if date_from else None
    normalized_date_to = parse_date_arg(date_to) if date_to else None
    scan: dict[str, Any] = {}
    raw_occurrence_count = 0
    candidate_count = 0
    date_filtered_candidate_count = 0
    event_timestamp_date_candidate_count = 0
    session_date_fallback_candidate_count = 0
    structured_filter_rejected_candidate_count = 0
    structured_filter_rejection_counts: dict[str, int] = {}
    retrieval_control_suppressed_count = 0
    completion_message_echo_suppressed_count = 0
    generated_context_summary_suppressed_count = 0
    ordered_token_phrase_match_count = 0
    retrieval_control_by_correlation: dict[str, str] = {}
    candidates: list[dict[str, Any]] = []
    query_class = str(literal_query_shape(needle).get("primary") or "")
    ordered_token_phrase_pattern = exact_raw_ordered_token_phrase_pattern(
        needle
    )
    ordered_token_phrase_anchor = exact_raw_ordered_token_phrase_anchor(needle)
    try:
        for line_no, raw_line, byte_offset, byte_count in iter_live_tail_complete_lines(snapshot, scan):
            parsed: dict[str, Any] | None = None
            try:
                loaded = json.loads(raw_line)
                parsed = loaded if isinstance(loaded, dict) else None
            except json.JSONDecodeError:
                parsed = None
            payload = (
                parsed.get("payload")
                if isinstance(parsed, dict)
                and isinstance(parsed.get("payload"), dict)
                else {}
            )
            payload_type = str(payload.get("type") or "")
            structured_action = payload_type in {
                "function_call",
                "tool_call",
                "custom_tool_call",
            }
            retrieval_command = ""
            if structured_action:
                retrieval_command = task_episode_retrieval_control_structured_payload(
                    payload
                )
                semantic = semantic_text_for_classification(
                    str(parsed.get("type") or ""),
                    payload,
                    max_chars=LIVE_TAIL_SEMANTIC_DISCOVERY_TEXT_MAX_CHARS,
                )
                if not retrieval_command:
                    retrieval_command = task_episode_retrieval_control_semantic(
                        semantic
                    )
                correlation_id = str(payload_correlation_id(payload) or "")
                if correlation_id and retrieval_command:
                    retrieval_control_by_correlation[correlation_id] = retrieval_command
            raw_match_mode = exact_raw_query_match_mode(
                raw_line,
                needle=needle,
                ordered_token_phrase_pattern=ordered_token_phrase_pattern,
                ordered_token_phrase_anchor=ordered_token_phrase_anchor,
            )
            if not raw_match_mode:
                continue
            raw_occurrence_count += 1
            event = classify_raw_event(raw_line, parsed, line_no)
            if exact_raw_event_is_generated_context_summary(event):
                generated_context_summary_suppressed_count += 1
                continue
            exact_evidence_text = exact_raw_event_evidence_text(
                event,
                raw_line,
                retrieval_control_by_correlation,
            )
            evidence_match_mode = exact_raw_query_match_mode(
                exact_evidence_text,
                needle=needle,
                ordered_token_phrase_pattern=ordered_token_phrase_pattern,
                ordered_token_phrase_anchor=ordered_token_phrase_anchor,
            )
            if not evidence_match_mode:
                if exact_raw_event_is_completion_message_echo(event):
                    completion_message_echo_suppressed_count += 1
                else:
                    retrieval_control_suppressed_count += 1
                continue
            if evidence_match_mode == "ordered_token_phrase":
                ordered_token_phrase_match_count += 1
            structured_filter_rejections = (
                exact_raw_event_structured_filter_rejections(
                    event,
                    event_id_before=event_id_before,
                    event_type=event_type,
                    family=family,
                    outcome=outcome,
                    exclude_agent_event_stream_copies=(
                        exclude_agent_event_stream_copies
                    ),
                )
            )
            if structured_filter_rejections:
                structured_filter_rejected_candidate_count += 1
                for reason in structured_filter_rejections:
                    structured_filter_rejection_counts[reason] = (
                        structured_filter_rejection_counts.get(reason, 0)
                        + 1
                    )
                continue
            date_filter = exact_event_date_filter_decision(
                event_timestamp=event.timestamp,
                session_date=session_date,
                date_from=normalized_date_from,
                date_to=normalized_date_to,
            )
            if date_filter["source"] == "event_timestamp":
                event_timestamp_date_candidate_count += 1
            else:
                session_date_fallback_candidate_count += 1
            if not date_filter["accepted"]:
                date_filtered_candidate_count += 1
                continue
            candidate_count += 1
            score, match = live_tail_exact_event_score(
                event,
                needle=needle,
                raw=raw_line,
                query_class=query_class,
            )
            if evidence_match_mode == "ordered_token_phrase":
                score += 40.0
                match["ordered_token_phrase_match"] = True
            semantic = event_semantic_text(event)
            refs = live_tail_event_refs(snapshot, line_no)
            candidate = {
                "rank": -round(score, 4),
                "match_score": round(score, 4),
                "match_channel": "live_tail_exact_substring",
                "raw_query_match_mode": evidence_match_mode,
                "doc_id": f"live-event:{snapshot.get('session_id')}:{event.event_id}",
                "doc_type": "event",
                "session_id": str(snapshot.get("session_id") or ""),
                "session_label": str(snapshot.get("session_label") or ""),
                "session_title": str(snapshot.get("session_title") or ""),
                "session_date": session_date,
                "archive_status": "live_source_unarchived",
                "event_id": event.event_id,
                "raw_line": line_no,
                "event_type": event.event_type,
                "source_type": event.source_type,
                "family": event.family,
                "phase": event.phase,
                "actor": event.actor,
                "action": event.action,
                "outcome": event.outcome,
                "correlation_id": event.correlation_id or "",
                "timestamp": event.timestamp or "",
                "date_filter": date_filter,
                "title": event.title,
                "preview": short_text(semantic or event.title, max_chars=700),
                "refs": refs,
                "raw_ref": refs["raw"],
                "raw_path": refs["raw_path"],
                "session_ref": refs["session"],
                "freshness": {},
                "reading_contract": {
                    "status": "candidate_navigation_only",
                    "accepted_claim_requires": "open the named live raw source line and preserve its unarchived qualifier",
                    "authority": "live_raw_transcript_snapshot",
                },
                "byte_offset": byte_offset,
                "byte_count": byte_count,
            }
            if explain:
                candidate["explain"] = {
                    **match,
                    "ranking": "source-aware exact occurrence ranking over one proven append-only live-tail snapshot",
                    "segment_ref_unavailable": True,
                }
            candidate = redact_derived_value(candidate)
            bounded_exact_candidate_append(
                candidates,
                candidate,
                max_candidates=LIVE_TAIL_SEARCH_MAX_EXACT_CANDIDATES,
            )
    except OSError as exc:
        scan.update({"ok": False, "status": "unresolved", "diagnostics": [f"live_tail_scan_failed:{exc}"]})
    finalized_scan = finalize_live_tail_scan(snapshot, scan) if scan.get("status") != "unresolved" else scan
    freshness = live_tail_result_freshness(snapshot, finalized_scan)
    for candidate in candidates:
        candidate["freshness"] = freshness
    bounded_candidate_count = len(candidates)
    candidates, mirrored_candidate_deduplicated_count = (
        live_tail_exact_deduplicate_mirrored_messages(candidates)
    )
    candidates.sort(
        key=lambda item: (
            -float(item.get("match_score") or 0.0),
            int_value(item.get("raw_line")),
        )
    )
    ranked_candidate_count = len(candidates)
    result_limit = max(1, min(100, int_value(limit, 20)))
    results = candidates[:result_limit]
    results_omitted = max(0, ranked_candidate_count - len(results))
    candidate_heap_truncated = candidate_count > bounded_candidate_count
    result_truncated = bool(
        results_omitted or candidate_heap_truncated
    )
    structured_filter = exact_raw_structured_filter_packet(
        event_id_before=event_id_before,
        event_type=event_type,
        family=family,
        outcome=outcome,
        exclude_agent_event_stream_copies=(
            exclude_agent_event_stream_copies
        ),
        rejected_candidate_count=(
            structured_filter_rejected_candidate_count
        ),
        rejection_counts=structured_filter_rejection_counts,
    )
    diagnostics = [*list(snapshot.get("diagnostics") or []), *list(finalized_scan.get("diagnostics") or [])]
    if candidate_heap_truncated:
        diagnostics.append(
            "live_tail_exact_candidate_heap_truncated:"
            f"{candidate_count}:{bounded_candidate_count}"
        )
    if results_omitted:
        diagnostics.append(
            "live_tail_exact_return_limit_truncated:"
            f"{ranked_candidate_count}:{len(results)}"
        )
    if retrieval_control_suppressed_count:
        diagnostics.append(f"live_tail_exact_retrieval_control_query_echo_suppressed:{retrieval_control_suppressed_count}")
    if completion_message_echo_suppressed_count:
        diagnostics.append(
            "live_tail_exact_completion_message_echo_suppressed:"
            f"{completion_message_echo_suppressed_count}"
        )
    if generated_context_summary_suppressed_count:
        diagnostics.append(
            "live_tail_exact_generated_context_summary_suppressed:"
            f"{generated_context_summary_suppressed_count}"
        )
    if ordered_token_phrase_match_count:
        diagnostics.append(
            "live_tail_exact_ordered_token_phrase_match:"
            f"{ordered_token_phrase_match_count}"
        )
    if date_filtered_candidate_count:
        diagnostics.append(f"live_tail_exact_event_date_filter_rejected:{date_filtered_candidate_count}")
    if mirrored_candidate_deduplicated_count:
        diagnostics.append(
            "live_tail_exact_adjacent_message_mirror_deduplicated:"
            f"{mirrored_candidate_deduplicated_count}"
        )
    for reason, count in structured_filter_rejection_counts.items():
        diagnostics.append(
            "live_tail_exact_structured_filter_rejected:"
            f"{reason}:{count}"
        )
    return {
        "schema_version": LIVE_TAIL_SEARCH_SCHEMA_VERSION,
        "artifact_type": "live_tail_exact_search_results",
        "generated_at": utc_now(),
        "ok": bool(finalized_scan.get("ok")),
        "mutates": False,
        "query": safe_query,
        "normalized_query": needle,
        "session": session,
        "route": {
            "id": "read_only_live_tail_exact_fallback",
            "reason": "session-scoped archived exact projections do not cover the proven append-only live tail",
            "authority": "live_raw_transcript_snapshot",
        },
        "snapshot": snapshot,
        "scan": finalized_scan,
        "raw_occurrence_count": raw_occurrence_count,
        "candidate_count": candidate_count,
        "bounded_candidate_count": bounded_candidate_count,
        "ranked_candidate_count": ranked_candidate_count,
        "result_limit": result_limit,
        "results_omitted": results_omitted,
        "candidate_heap_truncated": candidate_heap_truncated,
        "result_truncated": result_truncated,
        "truncated": result_truncated,
        "structured_filter": structured_filter,
        "date_filter": {
            "basis": EXACT_EVENT_DATE_FILTER_BASIS,
            "date_from": normalized_date_from or "",
            "date_to": normalized_date_to or "",
            "event_timestamp_candidate_count": event_timestamp_date_candidate_count,
            "session_date_fallback_candidate_count": session_date_fallback_candidate_count,
            "rejected_candidate_count": date_filtered_candidate_count,
        },
        "result_count": len(results),
        "results": results,
        "abstention": {
            "status": "exact_live_evidence_available" if results else "insufficient_live_tail_exact_evidence",
            "reason": (
                ""
                if results
                else (
                    "no exact event satisfied the requested structured "
                    "filters in the bounded complete-line live snapshot"
                )
                if structured_filter.get("applied")
                else (
                    "the exact substring was not present in the bounded "
                    "complete-line live snapshot"
                )
            ),
        },
        "cost_profile": {
            "prefix_bytes_hashed": int_value((snapshot.get("prefix_validation") or {}).get("observed_bytes")),
            "tail_bytes_read": int_value(finalized_scan.get("bytes_read")),
            "tail_lines_read": int_value(finalized_scan.get("complete_line_count")),
            "tail_scan_budget_ms": int_value(finalized_scan.get("budget_ms")),
            "tail_scan_elapsed_ms": int_value(finalized_scan.get("elapsed_ms")),
            "tail_scan_time_budget_exhausted": bool(finalized_scan.get("time_budget_exhausted")),
            "retrieval_control_query_echo_suppressed_count": retrieval_control_suppressed_count,
            "completion_message_echo_suppressed_count": completion_message_echo_suppressed_count,
            "generated_context_summary_suppressed_count": (
                generated_context_summary_suppressed_count
            ),
            "ordered_token_phrase_match_count": ordered_token_phrase_match_count,
            "ranking_query_class": query_class,
            "ranked_candidate_count": ranked_candidate_count,
            "result_limit": result_limit,
            "results_omitted": results_omitted,
            "candidate_heap_truncated": candidate_heap_truncated,
            "event_date_filter_rejected_candidate_count": date_filtered_candidate_count,
            "structured_filter_rejected_candidate_count": (
                structured_filter_rejected_candidate_count
            ),
            "bounded_candidate_count_before_mirror_deduplication": (
                bounded_candidate_count
            ),
            "mirrored_candidate_deduplicated_count": (
                mirrored_candidate_deduplicated_count
            ),
            "persistent_index_written": False,
        },
        "elapsed_ms": int((time.monotonic() - started) * 1000),
        "diagnostics": list(dict.fromkeys(str(item) for item in diagnostics if item)),
        "truth_status": "live_raw_candidate_navigation_not_archive_projection_current",
    }


def archived_session_exact_search(
    *,
    aoa_root: Path,
    session: str,
    query: str,
    limit: int = 20,
    event_id_before: str | None = None,
    event_type: str | None = None,
    family: str | None = None,
    outcome: str | None = None,
    date_from: str | None = None,
    date_to: str | None = None,
    exclude_agent_event_stream_copies: bool = False,
    max_bytes: int | None = None,
    max_lines: int | None = None,
    scan_budget_ms: int | None = None,
    explain: bool = False,
) -> dict[str, Any]:
    """Scan one immutable archived raw transcript for an exact substring.

    The route is deliberately session-scoped and bounded.  A negative result is
    exhaustive only when the whole archived snapshot was read and its manifest
    digest was verified during the same pass.
    """
    started = time.monotonic()
    needle = str(query or "").strip().strip("`'\"")
    query_projection = derived_text_privacy_projection(
        needle,
        max_chars=700,
    )
    safe_query = str(query_projection.get("text") or "")
    base_payload = {
        "schema_version": ARCHIVED_SESSION_EXACT_SEARCH_SCHEMA_VERSION,
        "artifact_type": "archived_session_exact_search_results",
        "generated_at": utc_now(),
        "mutates": False,
        "query": safe_query,
        "normalized_query": safe_query,
        "session": session,
    }
    if not needle:
        return {
            **base_payload,
            "ok": False,
            "result_count": 0,
            "results": [],
            "diagnostics": ["archived_session_exact_query_empty"],
        }
    if query_projection.get("redaction_count"):
        return {
            **base_payload,
            "ok": True,
            "route": {
                "id": "session_archived_raw_exact_fallback",
                "status": "blocked_before_raw_scan",
                "reason": (
                    "credential-like literal queries are not admitted to "
                    "raw transcript scans"
                ),
                "authority": "derived_text_privacy_policy",
            },
            "scan": {
                "status": "blocked_before_raw_scan",
                "complete": False,
                "bytes_read": 0,
                "complete_line_count": 0,
            },
            "result_count": 0,
            "results": [],
            "abstention": {
                "status": "sensitive_literal_query_blocked",
                "negative_result_exhaustive": False,
                "reason": (
                    "query contains a credential-like literal; search by its "
                    "non-secret label or another evidence anchor"
                ),
            },
            "derived_text_privacy": derived_text_privacy_metadata(
                query_projection
            ),
            "diagnostics": [
                "sensitive_literal_query_blocked_before_raw_scan"
            ],
            "elapsed_ms": int((time.monotonic() - started) * 1000),
            "truth_status": (
                "credential_literal_withheld_and_raw_scan_not_started"
            ),
        }
    try:
        record = resolve_session_record(aoa_root, session)
    except ValueError as exc:
        return {
            **base_payload,
            "ok": False,
            "result_count": 0,
            "results": [],
            "diagnostics": [f"archived_session_exact_session_unresolved:{exc}"],
        }
    session_dir = session_dir_from_record(record)
    manifest_path = session_dir / "session.manifest.json"
    manifest = read_json(manifest_path, {})
    if not isinstance(manifest, dict) or not manifest:
        return {
            **base_payload,
            "ok": False,
            "result_count": 0,
            "results": [],
            "diagnostics": [f"archived_session_exact_manifest_missing:{manifest_path}"],
        }
    raw_path = manifest_raw_path(session_dir, manifest)
    if not raw_path.is_file():
        return {
            **base_payload,
            "ok": False,
            "result_count": 0,
            "results": [],
            "diagnostics": [f"archived_session_exact_raw_missing:{raw_path}"],
        }
    display = manifest.get("display") if isinstance(manifest.get("display"), dict) else {}
    session_id = str(manifest.get("session_id") or record.get("session_id") or "")
    session_label = str(
        manifest.get("session_label")
        or display.get("label")
        or record.get("session_label")
        or session_dir.name
    )
    session_title = str(manifest.get("session_title") or display.get("title") or record.get("session_title") or "")
    session_date = str(display.get("date") or session_record_date(record) or "")
    normalized_date_from = parse_date_arg(date_from) if date_from else None
    normalized_date_to = parse_date_arg(date_to) if date_to else None

    requested_max_bytes = int_value(max_bytes, ARCHIVED_SESSION_EXACT_SEARCH_DEFAULT_MAX_BYTES)
    requested_max_lines = int_value(max_lines, ARCHIVED_SESSION_EXACT_SEARCH_DEFAULT_MAX_LINES)
    requested_budget_ms = int_value(scan_budget_ms, ARCHIVED_SESSION_EXACT_SEARCH_SCAN_BUDGET_MS)
    effective_max_bytes = max(1, min(requested_max_bytes, ARCHIVED_SESSION_EXACT_SEARCH_HARD_MAX_BYTES))
    effective_max_lines = max(1, min(requested_max_lines, ARCHIVED_SESSION_EXACT_SEARCH_HARD_MAX_LINES))
    effective_budget_ms = max(1, min(requested_budget_ms, ARCHIVED_SESSION_EXACT_SEARCH_HARD_SCAN_BUDGET_MS))
    raw_manifest = manifest.get("raw") if isinstance(manifest.get("raw"), dict) else {}
    expected_sha = str(raw_manifest.get("sha256") or "")
    expected_bytes = int_value(raw_manifest.get("bytes"))
    segments = manifest.get("segments") if isinstance(manifest.get("segments"), list) else []
    diagnostics: list[str] = []
    scan_started = time.monotonic()
    scan_deadline = scan_started + (effective_budget_ms / 1000.0)
    stat_before = raw_path.stat()
    raw_bytes = stat_before.st_size
    bytes_read = 0
    complete_line_count = 0
    partial_line_bytes = 0
    truncation_reasons: list[str] = []
    raw_occurrence_count = 0
    candidate_count = 0
    date_filtered_candidate_count = 0
    event_timestamp_date_candidate_count = 0
    session_date_fallback_candidate_count = 0
    structured_filter_rejected_candidate_count = 0
    structured_filter_rejection_counts: dict[str, int] = {}
    retrieval_control_suppressed_count = 0
    completion_message_echo_suppressed_count = 0
    generated_context_summary_suppressed_count = 0
    ordered_token_phrase_match_count = 0
    retrieval_control_by_correlation: dict[str, str] = {}
    candidates: list[dict[str, Any]] = []
    digest = hashlib.sha256()
    query_class = str(literal_query_shape(needle).get("primary") or "")
    ordered_token_phrase_pattern = exact_raw_ordered_token_phrase_pattern(
        needle
    )
    ordered_token_phrase_anchor = exact_raw_ordered_token_phrase_anchor(needle)
    scan_error = ""
    try:
        with raw_path.open("rb") as handle:
            while handle.tell() < raw_bytes:
                if complete_line_count >= effective_max_lines:
                    truncation_reasons.append("max_lines_exhausted")
                    break
                if bytes_read >= effective_max_bytes:
                    truncation_reasons.append("max_bytes_exhausted")
                    break
                if time.monotonic() >= scan_deadline:
                    truncation_reasons.append("time_budget_exhausted")
                    break
                line_offset = handle.tell()
                remaining_bytes = effective_max_bytes - bytes_read
                raw_line_bytes = handle.readline(remaining_bytes)
                if not raw_line_bytes:
                    break
                bytes_read += len(raw_line_bytes)
                digest.update(raw_line_bytes)
                reached_snapshot_end = handle.tell() >= raw_bytes
                if not raw_line_bytes.endswith(b"\n") and not reached_snapshot_end:
                    partial_line_bytes = len(raw_line_bytes)
                    truncation_reasons.extend(["max_bytes_exhausted", "partial_line_excluded"])
                    break
                complete_line_count += 1
                raw_line = raw_line_bytes.decode("utf-8", errors="replace").rstrip("\r\n")
                raw_match_mode = exact_raw_query_match_mode(
                    raw_line,
                    needle=needle,
                    ordered_token_phrase_pattern=ordered_token_phrase_pattern,
                    ordered_token_phrase_anchor=ordered_token_phrase_anchor,
                )
                if not raw_match_mode:
                    continue
                raw_occurrence_count += 1
                try:
                    loaded = json.loads(raw_line)
                    parsed = loaded if isinstance(loaded, dict) else None
                except json.JSONDecodeError:
                    parsed = None
                event = classify_raw_event(raw_line, parsed, complete_line_count)
                if exact_raw_event_is_generated_context_summary(event):
                    generated_context_summary_suppressed_count += 1
                    continue
                exact_evidence_text = exact_raw_event_evidence_text(
                    event,
                    raw_line,
                    retrieval_control_by_correlation,
                )
                evidence_match_mode = exact_raw_query_match_mode(
                    exact_evidence_text,
                    needle=needle,
                    ordered_token_phrase_pattern=ordered_token_phrase_pattern,
                    ordered_token_phrase_anchor=ordered_token_phrase_anchor,
                )
                if not evidence_match_mode:
                    if exact_raw_event_is_completion_message_echo(event):
                        completion_message_echo_suppressed_count += 1
                    else:
                        retrieval_control_suppressed_count += 1
                    continue
                if evidence_match_mode == "ordered_token_phrase":
                    ordered_token_phrase_match_count += 1
                structured_filter_rejections = (
                    exact_raw_event_structured_filter_rejections(
                        event,
                        event_id_before=event_id_before,
                        event_type=event_type,
                        family=family,
                        outcome=outcome,
                        exclude_agent_event_stream_copies=(
                            exclude_agent_event_stream_copies
                        ),
                    )
                )
                if structured_filter_rejections:
                    structured_filter_rejected_candidate_count += 1
                    for reason in structured_filter_rejections:
                        structured_filter_rejection_counts[reason] = (
                            structured_filter_rejection_counts.get(
                                reason, 0
                            )
                            + 1
                        )
                    continue
                date_filter = exact_event_date_filter_decision(
                    event_timestamp=event.timestamp,
                    session_date=session_date,
                    date_from=normalized_date_from,
                    date_to=normalized_date_to,
                )
                if date_filter["source"] == "event_timestamp":
                    event_timestamp_date_candidate_count += 1
                else:
                    session_date_fallback_candidate_count += 1
                if not date_filter["accepted"]:
                    date_filtered_candidate_count += 1
                    continue
                candidate_count += 1
                score, match = live_tail_exact_event_score(
                    event,
                    needle=needle,
                    raw=raw_line,
                    query_class=query_class,
                )
                if evidence_match_mode == "ordered_token_phrase":
                    score += 40.0
                    match["ordered_token_phrase_match"] = True
                event_ref = task_episode_event_ref(event, segments)
                segment = segment_for_line(segments, complete_line_count)
                raw_block = segment.get("raw_block") if isinstance(segment.get("raw_block"), dict) else {}
                refs = {
                    "session": str(manifest_path),
                    "segment": str(event_ref.get("segment_ref") or ""),
                    "segment_index": str(event_ref.get("segment_index") or ""),
                    "raw": str(event_ref.get("raw_ref") or f"raw:line:{complete_line_count}"),
                    "raw_block": str(raw_block.get("rel") or raw_block.get("path") or ""),
                }
                semantic = event_semantic_text(event)
                candidate = {
                    "rank": -round(score, 4),
                    "match_score": round(score, 4),
                    "match_channel": "archived_raw_exact_substring",
                    "raw_query_match_mode": evidence_match_mode,
                    "match_occurrence_count": int_value(match.get("occurrence_count")),
                    "doc_id": f"archived-raw-event:{session_id}:{event.event_id}",
                    "doc_type": "event",
                    "session_id": session_id,
                    "session_label": session_label,
                    "session_title": session_title,
                    "session_date": session_date,
                    "archive_status": str(manifest.get("archive_status") or "archived"),
                    "segment_id": str(event_ref.get("segment_id") or ""),
                    "event_id": event.event_id,
                    "raw_line": complete_line_count,
                    "event_type": event.event_type,
                    "source_type": event.source_type,
                    "family": event.family,
                    "phase": event.phase,
                    "actor": event.actor,
                    "action": event.action,
                    "outcome": event.outcome,
                    "correlation_id": event.correlation_id or "",
                    "timestamp": event.timestamp or "",
                    "date_filter": date_filter,
                    "title": event.title,
                    "preview": short_text(semantic or event.title, max_chars=700),
                    "refs": refs,
                    **route_result_ref_fields(refs),
                    "raw_path": str(raw_path),
                    "byte_offset": line_offset,
                    "byte_count": len(raw_line_bytes),
                    "freshness": {},
                    "reading_contract": {
                        "status": "candidate_navigation_only",
                        "accepted_claim_requires": "open the named archived raw line and require complete manifest digest verification",
                        "authority": "archived_raw_snapshot",
                    },
                }
                if explain:
                    candidate["explain"] = {
                        **match,
                        "ranking": "source-aware exact occurrence ranking over one bounded archived raw snapshot",
                        "scan_integrity_required_for_absence_claim": True,
                    }
                candidate = redact_derived_value(candidate)
                bounded_exact_candidate_append(
                    candidates,
                    candidate,
                    max_candidates=ARCHIVED_SESSION_EXACT_SEARCH_MAX_CANDIDATES,
                )
    except OSError as exc:
        scan_error = str(exc)
        diagnostics.append(f"archived_session_exact_scan_failed:{exc}")

    stat_after = raw_path.stat() if raw_path.exists() else None
    source_changed = bool(
        stat_after is None
        or stat_after.st_size != stat_before.st_size
        or stat_after.st_mtime_ns != stat_before.st_mtime_ns
    )
    if source_changed:
        diagnostics.append("archived_session_exact_source_changed_during_scan")
    truncation_reasons = list(dict.fromkeys(truncation_reasons))
    scan_complete = bool(
        not scan_error
        and not source_changed
        and not truncation_reasons
        and bytes_read == raw_bytes
    )
    observed_sha = digest.hexdigest() if scan_complete else ""
    if scan_complete and expected_sha and observed_sha == expected_sha:
        archive_integrity = {
            "status": "verified",
            "reasons": [],
            "sha256": observed_sha,
            "bytes": raw_bytes,
            "authority": "archived_raw_snapshot",
        }
        scan_status = "complete_verified"
    elif scan_complete and expected_sha:
        archive_integrity = {
            "status": "stale",
            "reasons": ["raw_sha_mismatch"],
            "expected_raw_sha256": expected_sha,
            "current_raw_sha256": observed_sha,
        }
        scan_status = "hash_mismatch"
        diagnostics.append("archived_session_exact_raw_sha_mismatch")
    elif scan_complete:
        archive_integrity = {"status": "unverifiable", "reasons": ["raw_sha_missing"]}
        scan_status = "complete_unverifiable"
        diagnostics.append("archived_session_exact_raw_sha_missing")
    else:
        archive_integrity = {
            "status": "unverifiable",
            "reasons": ["bounded_scan_incomplete", *truncation_reasons],
        }
        scan_status = "unresolved" if scan_error else "truncated"
    if expected_bytes and expected_bytes != raw_bytes:
        diagnostics.append(f"archived_session_exact_manifest_bytes_mismatch:{expected_bytes}:{raw_bytes}")
    freshness = (
        search_manifest_freshness(
            manifest,
            raw_path,
            archived_raw_integrity=archive_integrity,
        )
        if archive_integrity.get("status") == "verified"
        else dict(archive_integrity)
    )
    for candidate in candidates:
        candidate["freshness"] = freshness
    bounded_candidate_count = len(candidates)
    candidates, mirrored_candidate_deduplicated_count = (
        live_tail_exact_deduplicate_mirrored_messages(candidates)
    )
    candidates.sort(
        key=lambda item: (
            -float(item.get("match_score") or 0.0),
            int_value(item.get("raw_line")),
        )
    )
    ranked_candidate_count = len(candidates)
    result_limit = max(1, min(100, int_value(limit, 20)))
    results = candidates[:result_limit]
    results_omitted = max(0, ranked_candidate_count - len(results))
    candidate_heap_truncated = candidate_count > bounded_candidate_count
    result_truncated = bool(results_omitted or candidate_heap_truncated)
    if candidate_heap_truncated:
        diagnostics.append(
            "archived_session_exact_candidate_heap_truncated:"
            f"{candidate_count}:{bounded_candidate_count}"
        )
    if results_omitted:
        diagnostics.append(
            "archived_session_exact_return_limit_truncated:"
            f"{ranked_candidate_count}:{len(results)}"
        )
    if retrieval_control_suppressed_count:
        diagnostics.append(
            "archived_session_exact_retrieval_control_query_echo_suppressed:"
            f"{retrieval_control_suppressed_count}"
        )
    if completion_message_echo_suppressed_count:
        diagnostics.append(
            "archived_session_exact_completion_message_echo_suppressed:"
            f"{completion_message_echo_suppressed_count}"
        )
    if generated_context_summary_suppressed_count:
        diagnostics.append(
            "archived_session_exact_generated_context_summary_suppressed:"
            f"{generated_context_summary_suppressed_count}"
        )
    if ordered_token_phrase_match_count:
        diagnostics.append(
            "archived_session_exact_ordered_token_phrase_match:"
            f"{ordered_token_phrase_match_count}"
        )
    if mirrored_candidate_deduplicated_count:
        diagnostics.append(
            "archived_session_exact_adjacent_message_mirror_deduplicated:"
            f"{mirrored_candidate_deduplicated_count}"
        )
    if date_filtered_candidate_count:
        diagnostics.append(
            "archived_session_exact_event_date_filter_rejected:"
            f"{date_filtered_candidate_count}"
        )
    for reason, count in structured_filter_rejection_counts.items():
        diagnostics.append(
            "archived_session_exact_structured_filter_rejected:"
            f"{reason}:{count}"
        )
    structured_filter = exact_raw_structured_filter_packet(
        event_id_before=event_id_before,
        event_type=event_type,
        family=family,
        outcome=outcome,
        exclude_agent_event_stream_copies=(
            exclude_agent_event_stream_copies
        ),
        rejected_candidate_count=(
            structured_filter_rejected_candidate_count
        ),
        rejection_counts=structured_filter_rejection_counts,
    )
    scan_elapsed_ms = int((time.monotonic() - scan_started) * 1000)
    negative_exhaustive = bool(scan_status == "complete_verified" and not results)
    return {
        **base_payload,
        "ok": bool(not scan_error and scan_status != "hash_mismatch"),
        "session_id": session_id,
        "session_label": session_label,
        "session_title": session_title,
        "session_date": session_date,
        "route": {
            "id": "session_archived_raw_exact_fallback",
            "reason": "session-scoped exact postings can omit bounded document suffixes; scan archived raw without building another persistent index",
            "authority": "archived_raw_snapshot",
        },
        "archive": {
            "manifest_path": str(manifest_path),
            "raw_path": str(raw_path),
            "raw_bytes": raw_bytes,
            "expected_raw_bytes": expected_bytes,
            "expected_raw_sha256": expected_sha,
            "integrity": archive_integrity,
        },
        "scan": {
            "status": scan_status,
            "complete": scan_complete,
            "truncated": not scan_complete and not bool(scan_error),
            "truncation_reasons": truncation_reasons,
            "bytes_read": bytes_read,
            "complete_line_count": complete_line_count,
            "partial_line_bytes": partial_line_bytes,
            "max_bytes": effective_max_bytes,
            "max_lines": effective_max_lines,
            "budget_ms": effective_budget_ms,
            "elapsed_ms": scan_elapsed_ms,
            "source_changed_during_scan": source_changed,
            "observed_raw_sha256": observed_sha,
        },
        "raw_occurrence_count": raw_occurrence_count,
        "candidate_count": candidate_count,
        "bounded_candidate_count": bounded_candidate_count,
        "ranked_candidate_count": ranked_candidate_count,
        "result_limit": result_limit,
        "results_omitted": results_omitted,
        "candidate_heap_truncated": candidate_heap_truncated,
        "result_truncated": result_truncated,
        "truncated": result_truncated,
        "structured_filter": structured_filter,
        "date_filter": {
            "basis": EXACT_EVENT_DATE_FILTER_BASIS,
            "date_from": normalized_date_from or "",
            "date_to": normalized_date_to or "",
            "event_timestamp_candidate_count": event_timestamp_date_candidate_count,
            "session_date_fallback_candidate_count": session_date_fallback_candidate_count,
            "rejected_candidate_count": date_filtered_candidate_count,
        },
        "result_count": len(results),
        "results": results,
        "abstention": {
            "status": (
                "exact_archived_evidence_available"
                if results and archive_integrity.get("status") == "verified"
                else "exact_archived_candidates_unverified"
                if results
                else "exact_substring_absent_in_complete_verified_filtered_scope"
                if negative_exhaustive and structured_filter.get("applied")
                else "exact_substring_absent_in_complete_verified_archive"
                if negative_exhaustive
                else "bounded_scan_cannot_prove_absence"
            ),
            "negative_result_exhaustive": negative_exhaustive,
            "reason": (
                ""
                if results and archive_integrity.get("status") == "verified"
                else "candidate refs require archive integrity review"
                if results
                else (
                    "no exact event satisfied the requested structured "
                    "filters in the complete digest-verified archived "
                    "snapshot"
                )
                if negative_exhaustive and structured_filter.get("applied")
                else "the exact substring was absent from the complete digest-verified archived snapshot"
                if negative_exhaustive
                else "the bounded scan did not verify the complete archived snapshot"
            ),
        },
        "cost_profile": {
            "archive_bytes_read": bytes_read,
            "archive_lines_read": complete_line_count,
            "archive_scan_budget_ms": effective_budget_ms,
            "archive_scan_elapsed_ms": scan_elapsed_ms,
            "retrieval_control_query_echo_suppressed_count": retrieval_control_suppressed_count,
            "completion_message_echo_suppressed_count": completion_message_echo_suppressed_count,
            "generated_context_summary_suppressed_count": (
                generated_context_summary_suppressed_count
            ),
            "ordered_token_phrase_match_count": ordered_token_phrase_match_count,
            "ranking_query_class": query_class,
            "ranked_candidate_count": ranked_candidate_count,
            "result_limit": result_limit,
            "results_omitted": results_omitted,
            "candidate_heap_truncated": candidate_heap_truncated,
            "event_date_filter_rejected_candidate_count": date_filtered_candidate_count,
            "structured_filter_rejected_candidate_count": (
                structured_filter_rejected_candidate_count
            ),
            "bounded_candidate_count_before_mirror_deduplication": (
                bounded_candidate_count
            ),
            "mirrored_candidate_deduplicated_count": (
                mirrored_candidate_deduplicated_count
            ),
            "persistent_index_written": False,
        },
        "elapsed_ms": int((time.monotonic() - started) * 1000),
        "diagnostics": list(dict.fromkeys(str(item) for item in diagnostics if item)),
        "truth_status": (
            "archived_raw_exact_filtered_candidate_navigation_complete_verified"
            if scan_status == "complete_verified"
            and structured_filter.get("applied")
            else "archived_raw_exact_candidate_navigation_complete_verified"
            if scan_status == "complete_verified"
            else "archived_raw_exact_candidate_navigation_incomplete_or_unverified"
        ),
    }


def live_tail_bound_representation_candidates(episode: dict[str, Any]) -> None:
    candidates = episode.get("_representation_candidates")
    if not isinstance(candidates, list) or len(candidates) <= LIVE_TAIL_SEARCH_MAX_REPRESENTATION_CANDIDATES:
        return
    deduped: dict[str, dict[str, Any]] = {}
    for item in candidates:
        if not isinstance(item, dict):
            continue
        identity = task_episode_candidate_identity(item)
        if not identity:
            continue
        current = deduped.get(identity)
        if current is None or int_value(item.get("score")) > int_value(current.get("score")):
            deduped[identity] = item
    unique = sorted(deduped.values(), key=lambda item: (int_value(item.get("line")), -int_value(item.get("score"))))
    limit = LIVE_TAIL_SEARCH_MAX_REPRESENTATION_CANDIDATES
    head = unique[: max(1, limit // 8)]
    tail = unique[-max(2, limit // 4) :]
    selected_ids = {id(item) for item in [*head, *tail]}
    remaining = sorted(
        (item for item in unique if id(item) not in selected_ids),
        key=lambda item: (-int_value(item.get("score")), int_value(item.get("line"))),
    )
    selected = [*head, *tail, *remaining[: max(0, limit - len(head) - len(tail))]]
    selected.sort(key=lambda item: (int_value(item.get("line")), -int_value(item.get("score"))))
    episode["_representation_candidates"] = selected[:limit]
    omitted = episode.setdefault("omitted_ref_counts", {})
    if isinstance(omitted, dict):
        omitted["live_tail_representation_candidates"] = int_value(
            omitted.get("live_tail_representation_candidates")
        ) + max(0, len(candidates) - len(selected[:limit]))


def live_tail_episode_matches_filters(
    episode: dict[str, Any],
    *,
    session_date: str,
    episode_status: str | None,
    date_from: str | None,
    date_to: str | None,
    time_from: str | None,
    time_to: str | None,
) -> bool:
    if episode_status and str(episode.get("status") or "") != episode_status:
        return False
    span = episode.get("time_span") if isinstance(episode.get("time_span"), dict) else {}
    from_timestamp = str(span.get("from") or "")
    to_timestamp = str(span.get("to") or "")
    episode_from_date = from_timestamp[:10] if from_timestamp else session_date
    episode_to_date = to_timestamp[:10] if to_timestamp else session_date
    if date_from and episode_to_date and episode_to_date < str(parse_date_arg(date_from) or ""):
        return False
    if date_to and episode_from_date and episode_from_date > str(parse_date_arg(date_to) or ""):
        return False
    normalized_time_from = parse_timestamp_arg(time_from) if time_from else None
    normalized_time_to = parse_timestamp_arg(time_to) if time_to else None
    comparable_from = parse_timestamp_arg(from_timestamp) if from_timestamp else None
    comparable_to = parse_timestamp_arg(to_timestamp) if to_timestamp else None
    if normalized_time_from and comparable_to and comparable_to < normalized_time_from:
        return False
    if normalized_time_to and comparable_from and comparable_from > normalized_time_to:
        return False
    return True


def live_tail_episode_search(
    *,
    aoa_root: Path,
    session: str,
    query: str,
    limit: int = 20,
    episode_status: str | None = None,
    date_from: str | None = None,
    date_to: str | None = None,
    time_from: str | None = None,
    time_to: str | None = None,
    max_delta_bytes: int | None = None,
    max_lines: int | None = None,
    rerank_local: bool = False,
    rerank_candidate_limit: int | None = None,
    explain: bool = False,
) -> dict[str, Any]:
    started = time.monotonic()
    privacy_gate = derived_text_privacy_field_gate(query=query)
    if privacy_gate["blocked"]:
        return {
            **derived_text_privacy_blocked_navigation_result(
                artifact_type="live_tail_episode_search_results",
                fields={
                    **privacy_gate["fields"],
                    "session": session,
                },
                metadata=privacy_gate["derived_text_privacy"],
            ),
            "live_tail_search_schema_version": (
                LIVE_TAIL_SEARCH_SCHEMA_VERSION
            ),
        }
    terms = episode_semantic_query_terms(query)
    temporal_span = episode_temporal_span_query(query)
    normalized_time_from = parse_timestamp_arg(time_from) if time_from else None
    normalized_time_to = parse_timestamp_arg(time_to) if time_to else None
    if not terms:
        return {
            "schema_version": LIVE_TAIL_SEARCH_SCHEMA_VERSION,
            "artifact_type": "live_tail_episode_search_results",
            "generated_at": utc_now(),
            "ok": False,
            "query": query,
            "result_count": 0,
            "results": [],
            "diagnostics": ["live_tail_episode_query_empty_after_normalization"],
        }
    snapshot = session_live_tail_source_snapshot(
        aoa_root=aoa_root,
        session=session,
        max_delta_bytes=max_delta_bytes,
        max_lines=max_lines,
    )
    if not snapshot.get("ok") or snapshot.get("status") == "no_unarchived_tail":
        snapshot_status = str(snapshot.get("status") or "unresolved")
        deferred_prefix = snapshot_status == "deferred_prefix_validation"
        return {
            "schema_version": LIVE_TAIL_SEARCH_SCHEMA_VERSION,
            "artifact_type": "live_tail_episode_search_results",
            "generated_at": utc_now(),
            "ok": bool(snapshot.get("ok")),
            "query": query,
            "session": session,
            "snapshot": snapshot,
            "result_count": 0,
            "results": [],
            "abstention": {
                "status": (
                    "no_unarchived_tail"
                    if snapshot_status == "no_unarchived_tail"
                    else snapshot_status if deferred_prefix else "unresolved"
                ),
                "reason": (
                    ""
                    if snapshot_status == "no_unarchived_tail"
                    else "synchronous prefix validation exceeded the bounded query budget; archive remains stale-readable"
                    if deferred_prefix
                    else "live source snapshot could not be proven append-only"
                ),
            },
            "diagnostics": list(snapshot.get("diagnostics") or []),
            "elapsed_ms": int((time.monotonic() - started) * 1000),
            "cost_profile": {
                "snapshot_elapsed_ms": int_value(snapshot.get("elapsed_ms")),
                "prefix_hash_budget_ms": LIVE_TAIL_SEARCH_PREFIX_HASH_BUDGET_MS,
                "bounded_prefix_validation": True,
            },
        }
    discovery, selected_windows = live_tail_semantic_discover_windows_bounded(
        snapshot,
        terms=terms,
        query=query,
        normalized_time_from=normalized_time_from,
        normalized_time_to=normalized_time_to,
    )
    snapshot = dict(snapshot)
    snapshot["semantic_scan_window"] = {
        "strategy": str(discovery.get("strategy") or ""),
        "status": str(discovery.get("status") or ""),
        "candidate_coverage_exhaustive": bool(
            discovery.get("candidate_coverage_exhaustive")
        ),
        "structural_episode_count": int_value(
            discovery.get("structural_episode_count")
        ),
        "query_hit_episode_count": int_value(
            discovery.get("query_hit_episode_count")
        ),
        "anchor_qualified_hit_episode_count": int_value(
            discovery.get("anchor_qualified_hit_episode_count")
        ),
        "anchor_rejected_hit_episode_count": int_value(
            discovery.get("anchor_rejected_hit_episode_count")
        ),
        "required_exact_anchors": list(
            discovery.get("required_exact_anchors") or []
        ),
        "selected_window_count": int_value(
            discovery.get("selected_window_count")
        ),
        "selected_window_lines": int_value(
            discovery.get("selected_window_lines")
        ),
        "selected_window_bytes": int_value(
            discovery.get("selected_window_bytes")
        ),
        "omitted_query_hit_episode_count": int_value(
            discovery.get("omitted_query_hit_episode_count")
        ),
        "selected_windows": list(discovery.get("selected_windows") or []),
        "exhaustive": bool(discovery.get("candidate_coverage_exhaustive")),
    }
    window_scans: list[dict[str, Any]] = []
    episodes: list[dict[str, Any]] = []
    parsed_event_count = 0
    admitted_event_count = 0
    time_window_excluded_count = 0
    undated_time_window_excluded_count = 0
    query_relevant_representation_candidate_count = 0
    runtime_goal_continuation_boundary_count = 0
    semantic_query_control_event_count = 0
    hydration_started = time.monotonic()
    for window in selected_windows:
        remaining_budget_ms = max(
            0,
            LIVE_TAIL_SEMANTIC_HYDRATION_BUDGET_MS
            - int((time.monotonic() - hydration_started) * 1000),
        )
        if remaining_budget_ms <= 0:
            break
        window_snapshot = {
            **snapshot,
            "scan_start_offset": int_value(window.get("start_offset")),
            "scan_end_offset": int_value(window.get("end_offset")),
            "scan_line_base_count": int_value(window.get("start_line")) - 1,
            "line_start": int_value(window.get("start_line")),
            "max_lines": max(1, int_value(window.get("line_count"))),
            "scan_budget_ms": remaining_budget_ms,
        }
        scan: dict[str, Any] = {}
        builder = TaskEpisodeBuilder(
            [],
            semantic_query_terms=terms,
            semantic_query_text=query,
            runtime_goal_continuation_boundaries=True,
        )
        try:
            for (
                line_no,
                raw_line,
                _byte_offset,
                _byte_count,
            ) in iter_live_tail_complete_lines(window_snapshot, scan):
                parsed: dict[str, Any] | None = None
                try:
                    loaded = json.loads(raw_line)
                    parsed = loaded if isinstance(loaded, dict) else None
                except json.JSONDecodeError:
                    parsed = None
                event = classify_raw_event(raw_line, parsed, line_no)
                parsed_event_count += 1
                if normalized_time_from or normalized_time_to:
                    try:
                        event_timestamp = (
                            parse_timestamp_arg(event.timestamp)
                            if event.timestamp
                            else None
                        )
                    except ValueError:
                        event_timestamp = None
                    if not event_timestamp:
                        time_window_excluded_count += 1
                        undated_time_window_excluded_count += 1
                        continue
                    if (
                        normalized_time_from
                        and event_timestamp < normalized_time_from
                    ):
                        time_window_excluded_count += 1
                        continue
                    if normalized_time_to and event_timestamp > normalized_time_to:
                        time_window_excluded_count += 1
                        continue
                admitted_event_count += 1
                if builder.current is None and event.event_type != "USER_INTENT":
                    prelude_representation = task_episode_representation_entry(
                        event,
                        [],
                    )
                    if prelude_representation is not None:
                        continuation = new_task_episode(
                            ordinal=1,
                            user_event=event,
                            segments=[],
                            previous_episode_id="",
                            transition_reason="archive_boundary_continuation",
                        )
                        continuation["start_event_ref"] = continuation.pop(
                            "start_user_ref",
                            {},
                        )
                        flags = continuation.setdefault("ambiguity_flags", [])
                        if (
                            isinstance(flags, list)
                            and "live_tail_continuation_without_user_start"
                            not in flags
                        ):
                            flags.append(
                                "live_tail_continuation_without_user_start"
                            )
                        builder.current = continuation
                        builder.episodes.append(continuation)
                episode_count_before = len(builder.episodes)
                builder.observe(event)
                if len(builder.episodes) > episode_count_before:
                    for prior_episode in builder.episodes[:-1]:
                        if "semantic_contract" not in prior_episode:
                            finalize_task_episode_semantics(prior_episode)
                if builder.current is not None:
                    live_tail_bound_representation_candidates(builder.current)
        except OSError as exc:
            scan.update(
                {
                    "ok": False,
                    "status": "unresolved",
                    "diagnostics": [f"live_tail_scan_failed:{exc}"],
                }
            )
        scan["window"] = {
            key: window.get(key)
            for key in (
                "selection_rank",
                "episode_rank",
                "selection_kind",
                "start_line",
                "end_line",
                "line_count",
                "byte_count",
                "primary_hit_line",
                "covers_full_structural_episode",
            )
        }
        window_scans.append(scan)
        window_episodes = builder.finish()
        window_id_map: dict[str, str] = {}
        for episode in window_episodes:
            event_range = (
                episode.get("event_range")
                if isinstance(episode.get("event_range"), dict)
                else {}
            )
            old_id = str(episode.get("episode_id") or "")
            new_id = (
                f"live-tail-{int_value(event_range.get('from_line')):06d}"
            )
            window_id_map[old_id] = new_id
            episode["episode_id"] = new_id
        for episode in window_episodes:
            transition = (
                episode.get("transition")
                if isinstance(episode.get("transition"), dict)
                else {}
            )
            previous_id = str(transition.get("previous_episode_id") or "")
            if previous_id:
                transition["previous_episode_id"] = window_id_map.get(
                    previous_id,
                    previous_id,
                )
        episodes.extend(window_episodes)
        query_relevant_representation_candidate_count += (
            builder.query_relevant_representation_candidate_count
        )
        runtime_goal_continuation_boundary_count += (
            builder.runtime_goal_continuation_boundary_count
        )
        semantic_query_control_event_count += (
            builder.semantic_query_control_event_count
        )
    finalized_scan = finalize_live_tail_semantic_window_scans(
        snapshot,
        discovery,
        window_scans,
    )
    finalized_scan["evidence_time_window"] = {
        "active": bool(normalized_time_from or normalized_time_to),
        "time_from": normalized_time_from or "",
        "time_to": normalized_time_to or "",
        "parsed_event_count": parsed_event_count,
        "admitted_event_count": admitted_event_count,
        "excluded_event_count": time_window_excluded_count,
        "undated_excluded_event_count": undated_time_window_excluded_count,
        "discovery_excluded_hit_count": int_value(
            discovery.get("time_window_excluded_hit_count")
        ),
        "discovery_undated_excluded_hit_count": int_value(
            discovery.get("undated_time_window_excluded_hit_count")
        ),
        "policy": "event_evidence_must_fall_inside_explicit_query_window",
    }
    if not finalized_scan.get("ok"):
        return {
            "schema_version": LIVE_TAIL_SEARCH_SCHEMA_VERSION,
            "artifact_type": "live_tail_episode_search_results",
            "generated_at": utc_now(),
            "ok": False,
            "query": query,
            "session": session,
            "snapshot": snapshot,
            "scan": finalized_scan,
            "semantic_query_window_discovery": discovery,
            "result_count": 0,
            "results": [],
            "diagnostics": list(finalized_scan.get("diagnostics") or []),
        }
    session_dir = Path(str(snapshot.get("session_dir") or ""))
    manifest = read_json(Path(str(snapshot.get("manifest_path") or "")), {})
    attach_task_episode_session_context(episodes, session_dir=session_dir, manifest=manifest)
    live_source_path = str(snapshot.get("live_source_path") or "")
    for episode in episodes:
        episode["projection_scope"] = "query_time_live_tail_candidate"
        episode["validity"] = {
            "status": "provisional_live_tail_episode",
            "valid_during": episode.get("time_span", {}),
            "superseded_by": "",
        }
        provenance = episode.setdefault("provenance", {})
        if isinstance(provenance, dict):
            provenance.update(
                {
                    "authority": "live_raw_transcript_snapshot",
                    "live_source_path": live_source_path,
                    "snapshot_id": str(snapshot.get("snapshot_id") or ""),
                    "archive_projection_status": "stale-readable",
                    "segment_ref_available": False,
                }
            )
        representations = episode.get("representations") if isinstance(episode.get("representations"), dict) else {}
        for entries in representations.values():
            for entry in entries if isinstance(entries, list) else []:
                if isinstance(entry, dict) and isinstance(entry.get("refs"), dict):
                    entry["refs"]["raw_path"] = live_source_path
        for item in episode.get("correlation_chain", []) if isinstance(episode.get("correlation_chain"), list) else []:
            if isinstance(item, dict) and isinstance(item.get("refs"), dict):
                item["refs"]["raw_path"] = live_source_path
    session_date = str(snapshot.get("session_date") or "")
    ranked: list[dict[str, Any]] = []
    for episode in episodes:
        if not live_tail_episode_matches_filters(
            episode,
            session_date=session_date,
            episode_status=episode_status,
            date_from=date_from,
            date_to=date_to,
            time_from=time_from,
            time_to=time_to,
        ):
            continue
        evidence = episode_semantic_candidate_evidence(
            episode,
            terms,
            temporal_span=temporal_span,
            query_text=query,
        )
        operation_alignment = episode_evidence_operation_alignment(evidence, terms)
        decision_followup = episode_decision_followup_alignment(episode, terms)
        failure_recovery = episode_failure_recovery_alignment(episode, terms)
        issue_resolution = episode_issue_resolution_alignment(
            episode,
            terms,
            query_text=query,
        )
        causal_attribution = episode_causal_attribution_alignment(
            episode,
            evidence,
            terms,
            query_text=query,
        )
        asserted_mutation = episode_asserted_mutation_alignment(
            episode,
            evidence,
            terms,
            query_text=query,
        )
        replay_alignment = episode_replay_alignment(
            episode,
            terms,
            query_text=query,
        )
        lineage_alignment = episode_lineage_alignment(
            episode,
            terms,
            query_text=query,
        )
        evidence["supporting_evidence"] = episode_relation_prioritized_support(
            evidence,
            decision_followup=decision_followup,
            failure_recovery=failure_recovery,
            replay_alignment=replay_alignment,
            issue_resolution=issue_resolution,
            asserted_mutation=asserted_mutation,
            causal_attribution=causal_attribution,
        )
        source_kind_alignment = episode_source_kind_alignment(
            evidence,
            terms,
            query_text=query,
        )
        matched_count = int_value(evidence.get("matched_term_count"))
        if matched_count <= 0:
            continue
        score, coherent_support_bonus = episode_semantic_rerank_score(
            evidence,
            operation_alignment=operation_alignment,
            asserted_mutation=asserted_mutation,
            causal_attribution=causal_attribution,
            decision_followup=decision_followup,
            failure_recovery=failure_recovery,
            issue_resolution=issue_resolution,
            replay_alignment=replay_alignment,
            lineage_alignment=lineage_alignment,
            source_kind_alignment=source_kind_alignment,
        )
        event_range = episode.get("event_range") if isinstance(episode.get("event_range"), dict) else {}
        supporting = evidence.get("supporting_evidence") if isinstance(evidence.get("supporting_evidence"), list) else []
        for item in supporting:
            if isinstance(item, dict) and isinstance(item.get("refs"), dict):
                item["refs"]["raw_path"] = live_source_path
                item["refs"]["session"] = str(snapshot.get("manifest_path") or "")
        primary_raw_ref = str(((supporting[0].get("refs") or {}).get("raw")) if supporting else "")
        if not primary_raw_ref:
            primary_raw_ref = f"raw:line:{int_value(event_range.get('from_line'))}"
        primary_line = line_from_raw_ref(primary_raw_ref) or int_value(event_range.get("from_line"))
        coverage = float(evidence.get("coverage") or 0.0)
        confidence_band = "strong" if coverage >= 0.6 and matched_count >= 2 else (
            "moderate" if coverage >= 0.35 or matched_count >= 2 else "weak"
        )
        refs = live_tail_event_refs(snapshot, primary_line)
        result = {
            "rank": 0.0,
            "rerank_score": score,
            "match_channel": "live_tail_source_aware_episode",
            "match_channels": ["live_tail_source_aware_episode"],
            "confidence_band": confidence_band,
            "doc_id": f"live-episode:{snapshot.get('session_id')}:{episode.get('episode_id')}",
            "candidate_id": f"live-episode:{snapshot.get('session_id')}:{episode.get('episode_id')}",
            "doc_type": "task_episode",
            "session_id": str(snapshot.get("session_id") or ""),
            "session_label": str(snapshot.get("session_label") or ""),
            "session_title": str(snapshot.get("session_title") or ""),
            "session_date": session_date,
            "task_episode_id": str(episode.get("episode_id") or ""),
            "source_task_episode_schema_version": TASK_EPISODE_SCHEMA_VERSION,
            "episode_status": str(episode.get("status") or ""),
            "event_range": {
                "from_line": int_value(event_range.get("from_line")),
                "to_line": int_value(event_range.get("to_line")),
            },
            "time_span": episode.get("time_span", {}),
            "preview": str(episode.get("narrative") or ""),
            "query_coverage": {
                key: evidence.get(key)
                for key in (
                    "coverage",
                    "matched_term_count",
                    "matched_query_terms",
                    "matched_by_field",
                    "coherent_term_count",
                    "coherent_coverage",
                    "coherent_support",
                )
            },
            "supporting_evidence": supporting,
            "operation_alignment": operation_alignment,
            "asserted_mutation": asserted_mutation,
            "causal_attribution": causal_attribution,
            "decision_followup": decision_followup,
            "failure_recovery": failure_recovery,
            "issue_resolution": issue_resolution,
            "replay_alignment": replay_alignment,
            "lineage_alignment": lineage_alignment,
            "source_kind_alignment": source_kind_alignment,
            "temporal_span": evidence.get("temporal_span", {}),
            "causal_chain": episode.get("correlation_chain", [])[:12],
            "refs": refs,
            "raw_ref": primary_raw_ref,
            "raw_line": primary_line,
            "raw_path": live_source_path,
            "segment_ref": "",
            "session_ref": str(snapshot.get("manifest_path") or ""),
            "session_index_ref": "",
            "freshness": live_tail_result_freshness(snapshot, finalized_scan),
            "reading_contract": {
                "status": "candidate_navigation_only",
                "accepted_claim_requires": "read supporting live raw refs and preserve live-tail/provisional qualifiers",
                "authority": "live_raw_transcript_snapshot",
            },
            "expansion_routes": {
                "live_source_path": live_source_path,
                "from_line": int_value(event_range.get("from_line")),
                "to_line": int_value(event_range.get("to_line")),
            },
        }
        if explain:
            result["explain"] = {
                "matched_by_field": evidence.get("matched_by_field", {}),
                "weighted_field_match": evidence.get("weighted_field_match", 0.0),
                "coherent_support_bonus": coherent_support_bonus,
                "coherent_support": evidence.get("coherent_support", {}),
                "operation_alignment": operation_alignment,
                "asserted_mutation": asserted_mutation,
                "causal_attribution": causal_attribution,
                "decision_followup": decision_followup,
                "failure_recovery": failure_recovery,
                "issue_resolution": issue_resolution,
                "replay_alignment": replay_alignment,
                "lineage_alignment": lineage_alignment,
                "source_kind_alignment": source_kind_alignment,
                "ranking": "source-aware coverage, coherent raw-support bonus, and typed relation alignment over query-time episodes built only from the proven append-only tail snapshot",
                "why_this_is_not_projection_current": "No archive, segment, persistent episode, dense, or graph projection was written by this route.",
            }
        ranked.append(result)
    ranked.sort(
        key=lambda item: (
            -float(item.get("rerank_score") or 0.0),
            -int_value(item.get("raw_line")),
            str(item.get("doc_id") or ""),
        )
    )
    ranked, temporal_relation_gate = episode_temporal_relation_gate(ranked, temporal_span)
    rerank_payload: dict[str, Any] = {"ok": False, "status": "not_requested", "diagnostics": []}
    if rerank_local and ranked:
        rerank_payload = episode_selective_local_rerank(
            aoa_root=aoa_root,
            query=query,
            results=ranked,
            candidate_limit=rerank_candidate_limit,
        )
        if rerank_payload.get("ok"):
            ranked = rerank_payload.pop("results", ranked)
    ranked, causal_claim_shape_gate = episode_causal_claim_shape_gate(
        ranked,
        query_text=query,
    )
    ranked, asserted_mutation_scope = episode_asserted_mutation_scope_gate(ranked)
    ranked, causal_attribution_scope = episode_causal_attribution_scope_gate(ranked)
    results = ranked[: max(1, min(100, int_value(limit, 20)))]
    top = results[0] if results else {}
    answer_admission = episode_answer_admission(
        top,
        query_term_count=len(terms),
        temporal_relation_gate=(temporal_relation_gate if temporal_span.get("active") else None),
    ) if top else {
        "admitted": False,
        "status": "no_candidate",
        "basis": "no_candidate",
    }
    required_exact_anchor_gate = {
        "active": bool(discovery.get("required_exact_anchors")),
        "status": (
            "not_required"
            if not discovery.get("required_exact_anchors")
            else "matched"
            if int_value(discovery.get("anchor_qualified_hit_episode_count"))
            > 0
            else "unmatched"
        ),
        "required_exact_anchors": list(
            discovery.get("required_exact_anchors") or []
        ),
        "qualified_episode_count": int_value(
            discovery.get("anchor_qualified_hit_episode_count")
        ),
        "rejected_episode_count": int_value(
            discovery.get("anchor_rejected_hit_episode_count")
        ),
        "policy": (
            "a semantic neighbor cannot satisfy a query that contains an "
            "unmatched concrete identifier, path, UUID, or raw ref"
        ),
    }
    diagnostics = [*list(snapshot.get("diagnostics") or []), *list(finalized_scan.get("diagnostics") or [])]
    if time_window_excluded_count:
        diagnostics.append(f"live_tail_evidence_time_window_excluded:{time_window_excluded_count}")
    if undated_time_window_excluded_count:
        diagnostics.append(f"live_tail_evidence_time_window_undated_excluded:{undated_time_window_excluded_count}")
    return {
        "schema_version": LIVE_TAIL_SEARCH_SCHEMA_VERSION,
        "artifact_type": "live_tail_episode_search_results",
        "generated_at": utc_now(),
        "ok": True,
        "mutates": False,
        "query": query,
        "query_terms": [str(term.get("token") or "") for term in terms],
        "session": session,
        "route": {
            "id": "read_only_live_tail_episode_fallback",
            "reason": "session-scoped archived episode projections do not cover the proven append-only live tail",
            "authority": "live_raw_transcript_snapshot",
        },
        "snapshot": snapshot,
        "scan": finalized_scan,
        "semantic_query_window_discovery": discovery,
        "episode_candidate_count": len(episodes),
        "parsed_event_count": parsed_event_count,
        "candidate_count": len(ranked),
        "result_count": len(results),
        "results": results,
        "retrieval": {
            "effective_mode": "live_tail_source_aware_sparse",
            "answer_admission": answer_admission,
            "temporal_relation_gate": temporal_relation_gate,
            "asserted_mutation_scope": asserted_mutation_scope,
            "causal_attribution_scope": causal_attribution_scope,
            "causal_claim_shape_gate": causal_claim_shape_gate,
            "required_exact_anchor_gate": required_exact_anchor_gate,
            "rerank": {key: rerank_payload.get(key) for key in ("ok", "status", "candidate_count", "top_score", "margin", "model", "elapsed_ms", "diagnostics")},
        },
        "abstention": {
            "status": (
                "required_exact_anchor_unmatched"
                if required_exact_anchor_gate.get("status") == "unmatched"
                else "ambiguous_causal_evidence"
                if causal_attribution_scope.get("ambiguous")
                else "evidence_candidates_available"
                if answer_admission.get("admitted")
                else "insufficient_episode_evidence"
            ),
            "reason": (
                "the concrete query anchor was observed only in retrieval "
                "control/query-echo context or not observed at all"
                if required_exact_anchor_gate.get("status") == "unmatched"
                else ""
                if answer_admission.get("admitted")
                else (
                "multiple correlation-owned operation results remain compatible with the query"
                if causal_attribution_scope.get("ambiguous")
                else "no live-tail episode candidate"
                if not results
                else "top live-tail candidate remains navigation-only below answer admission"
                )
            ),
            "policy": "do not synthesize an answer from weak or incomplete live-tail candidates",
        },
        "cost_profile": {
            "prefix_bytes_hashed": int_value((snapshot.get("prefix_validation") or {}).get("observed_bytes")),
            "tail_bytes_read": int_value(finalized_scan.get("bytes_read")),
            "tail_lines_read": int_value(finalized_scan.get("complete_line_count")),
            "tail_scan_budget_ms": int_value(finalized_scan.get("budget_ms")),
            "tail_scan_elapsed_ms": int_value(finalized_scan.get("elapsed_ms")),
            "tail_scan_time_budget_exhausted": bool(finalized_scan.get("time_budget_exhausted")),
            "semantic_scan_strategy": str(
                (snapshot.get("semantic_scan_window") or {}).get("strategy") or ""
            ),
            "semantic_scan_window_status": str(
                (snapshot.get("semantic_scan_window") or {}).get("status") or ""
            ),
            "semantic_scan_window_bytes": int_value(
                (snapshot.get("semantic_scan_window") or {}).get(
                    "selected_window_bytes"
                )
            ),
            "semantic_scan_window_lines": int_value(
                (snapshot.get("semantic_scan_window") or {}).get(
                    "selected_window_lines"
                )
            ),
            "semantic_selected_window_count": int_value(
                discovery.get("selected_window_count")
            ),
            "semantic_candidate_coverage_exhaustive": bool(
                finalized_scan.get("candidate_coverage_exhaustive")
            ),
            "semantic_omitted_query_hit_episode_count": int_value(
                discovery.get("omitted_query_hit_episode_count")
            ),
            "semantic_discovery_bytes_read": int_value(
                discovery.get("bytes_read")
            ),
            "semantic_discovery_lines_read": int_value(
                discovery.get("complete_line_count")
            ),
            "semantic_discovery_budget_ms": int_value(
                discovery.get("budget_ms")
            ),
            "semantic_discovery_elapsed_ms": int_value(
                discovery.get("elapsed_ms")
            ),
            "semantic_discovery_time_budget_exhausted": bool(
                discovery.get("time_budget_exhausted")
            ),
            "query_relevant_representation_candidate_count": (
                query_relevant_representation_candidate_count
            ),
            "runtime_goal_continuation_boundary_count": (
                runtime_goal_continuation_boundary_count
            ),
            "semantic_query_control_event_count": (
                semantic_query_control_event_count
            ),
            "semantic_discovery_query_control_event_count": int_value(
                discovery.get("query_control_event_count")
            ),
            "semantic_discovery_query_intent_echo_count": int_value(
                discovery.get("query_intent_echo_count")
            ),
            "parsed_event_count": parsed_event_count,
            "admitted_event_count": admitted_event_count,
            "time_window_excluded_event_count": time_window_excluded_count,
            "episode_count": len(episodes),
            "persistent_index_written": False,
            "dense_vectors_written": False,
        },
        "elapsed_ms": int((time.monotonic() - started) * 1000),
        "diagnostics": list(dict.fromkeys(str(item) for item in diagnostics if item)),
        "truth_status": "live_raw_candidate_navigation_not_archive_projection_current",
    }


def search_manifest_archived_raw_integrity(
    manifest: dict[str, Any],
    raw_path: Path | None,
) -> dict[str, Any]:
    """Verify the immutable archived snapshot independently from its live tail."""
    raw = manifest.get("raw") if isinstance(manifest.get("raw"), dict) else {}
    expected_sha = str(raw.get("sha256") or "")
    if not raw_path or not raw_path.exists():
        return {"status": "unverifiable", "reasons": ["raw_path_missing"]}
    if not expected_sha:
        return {"status": "unverifiable", "reasons": ["raw_sha_missing"]}
    current_sha = sha256_file(raw_path)
    if current_sha != expected_sha:
        return {"status": "stale", "reasons": ["raw_sha_mismatch"], "current_raw_sha256": current_sha}
    return {
        "status": "verified",
        "reasons": [],
        "sha256": current_sha,
        "bytes": raw_path.stat().st_size,
        "authority": "archived_raw_snapshot",
    }


def search_manifest_freshness(
    manifest: dict[str, Any],
    raw_path: Path | None,
    *,
    archived_raw_integrity: dict[str, Any] | None = None,
) -> dict[str, Any]:
    archive_integrity = (
        archived_raw_integrity
        if isinstance(archived_raw_integrity, dict)
        else search_manifest_archived_raw_integrity(manifest, raw_path)
    )
    if archive_integrity.get("status") != "verified":
        return dict(archive_integrity)
    live_source = manifest_live_source_snapshot_freshness(manifest)
    if live_source.get("status") in {"deferred", "stale"}:
        return {
            "status": "stale",
            "reasons": list(live_source.get("reasons") or []),
            "live_source": live_source,
            "readability": "stale-readable",
            "archive_integrity": archive_integrity,
        }
    return {
        "status": "fresh",
        "reasons": [],
        "live_source": live_source,
        "archive_integrity": archive_integrity,
    }


def episode_temporal_scoped_raw_readiness(
    manifest: dict[str, Any],
    raw_path: Path | None,
) -> dict[str, Any]:
    """Keep verified archived evidence readable even while a live tail is stale."""
    archive_integrity = search_manifest_archived_raw_integrity(manifest, raw_path)
    projection_freshness = search_manifest_freshness(
        manifest,
        raw_path,
        archived_raw_integrity=archive_integrity,
    )
    readable = archive_integrity.get("status") == "verified"
    return {
        "status": (
            "archived_raw_snapshot_readable"
            if readable
            else "archived_raw_snapshot_unreadable"
        ),
        "readable": readable,
        "read_scope": "archived_raw_snapshot_only",
        "archive_integrity": archive_integrity,
        "projection_freshness": projection_freshness,
        "policy": (
            "live-tail drift changes currentness but does not invalidate a hash-verified archived prefix"
        ),
    }


def segment_index_freshness(index_path: Path | None, expected_sha: str | None) -> dict[str, Any]:
    if not index_path or not index_path.exists():
        return {"status": "unverifiable", "reasons": ["segment_index_missing"]}
    if not expected_sha:
        return {"status": "unverifiable", "reasons": ["segment_index_sha_missing"]}
    current_sha = sha256_file(index_path)
    if current_sha != expected_sha:
        return {"status": "stale", "reasons": ["segment_index_sha_mismatch"], "current_segment_index_sha256": current_sha}
    return {"status": "fresh", "reasons": []}


def combine_freshness(*items: dict[str, Any]) -> dict[str, Any]:
    reasons: list[str] = []
    status = "fresh"
    combined: dict[str, Any] = {}
    for item in items:
        item_status = str(item.get("status") or "")
        if item_status == "stale":
            status = "stale"
        elif item_status == "unverifiable" and status != "stale":
            status = "unverifiable"
        for reason in item.get("reasons", []) if isinstance(item.get("reasons"), list) else []:
            if reason not in reasons:
                reasons.append(str(reason))
        for key, value in item.items():
            if key not in {"status", "reasons"}:
                combined[key] = value
    return {"status": status, "reasons": reasons, **combined}


SEARCH_DOCUMENT_COLUMN_KEYS = frozenset(
    {
        "id",
        "doc_type",
        "session_id",
        "session_label",
        "session_title",
        "session_date",
        "cwd",
        "archive_status",
        "distillation_status",
        "review_status",
        "segment_id",
        "event_id",
        "event_type",
        "family",
        "phase",
        "actor",
        "action",
        "object",
        "outcome",
        "conversation_act",
        "session_act",
        "agent_event",
        "usage_role",
        "task_episode_id",
        "route_layers",
        "route_signals",
        "tags",
        "raw_ref",
        "raw_block_ref",
        "segment_ref",
        "manifest_path",
        "raw_path",
        "segment_index_path",
        "raw_sha256",
        "segment_index_sha256",
        "freshness_status",
        "stale_reason",
        "title",
        "body",
        "payload_json",
        "generation_id",
    }
)


def search_doc_payload(doc: dict[str, Any]) -> dict[str, Any]:
    return {
        key: value
        for key, value in doc.items()
        if key not in SEARCH_DOCUMENT_COLUMN_KEYS and not key.startswith("exact_literal_")
    }


SEARCH_DOCUMENT_DELTA_VOLATILE_COLUMNS = frozenset({"raw_sha256", "session_date"})


def canonical_search_payload(value: Any) -> Any:
    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            return value
    return value


def search_document_storage_signature_from_parts(
    *,
    column_values: dict[str, Any],
    payload: Any,
    body_sha256: str,
    body_chars: int,
    route_entries: list[dict[str, str]],
) -> str:
    comparable = {
        "columns": {
            key: column_values.get(key)
            for key in sorted(SEARCH_DOCUMENT_COLUMN_KEYS)
            if key not in {"payload_json", *SEARCH_DOCUMENT_DELTA_VOLATILE_COLUMNS}
        },
        "payload": canonical_search_payload(payload),
        "body_sha256": body_sha256,
        "body_chars": body_chars,
        "route_entries": route_entries,
    }
    return hashlib.sha256(
        json.dumps(comparable, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()


def search_document_storage_signature(doc: dict[str, Any]) -> str:
    doc = redact_derived_value(doc)
    profile = search_document_storage_profile(store_raw_text=True)
    payload = search_doc_payload(doc)
    full_body = str(doc.get("body") or "")
    route_layers_preview = bounded_packed_route_values(
        doc.get("route_layers"),
        max_chars=int_value(profile.get("route_layers_preview_chars"), SEARCH_ROUTE_LAYERS_PREVIEW_CHARS),
    )
    route_signals_preview = bounded_packed_route_values(
        doc.get("route_signals"),
        max_chars=int_value(profile.get("route_signals_preview_chars"), SEARCH_ROUTE_SIGNALS_PREVIEW_CHARS),
    )
    body_preview = bounded_storage_text(
        full_body,
        max_chars=int_value(profile.get("body_preview_chars"), SEARCH_BODY_PREVIEW_CHARS),
    )
    tags_preview = compact_search_tags_for_storage(
        doc.get("tags"),
        max_chars=int_value(profile.get("tags_preview_chars")),
        policy=str(profile.get("tags_storage_policy") or SEARCH_TAGS_STORAGE_POLICY_FULL),
    )
    column_values = {key: doc.get(key) for key in SEARCH_DOCUMENT_COLUMN_KEYS}
    column_values["route_layers"] = route_layers_preview
    column_values["route_signals"] = route_signals_preview
    column_values["body"] = body_preview
    column_values["tags"] = tags_preview
    if not profile.get("store_raw_path", True):
        column_values["raw_path"] = ""
    if not profile.get("store_segment_index_path", True):
        column_values["segment_index_path"] = ""
    return search_document_storage_signature_from_parts(
        column_values=column_values,
        payload=payload,
        body_sha256=hashlib.sha256(full_body.encode("utf-8")).hexdigest(),
        body_chars=len(full_body),
        route_entries=document_route_entries(
            route_layers_preview,
            route_signals_preview,
            doc_type=str(doc.get("doc_type") or ""),
        ),
    )


def search_document_existing_signatures(conn: sqlite3.Connection, *, doc_type: str) -> dict[str, dict[str, Any]]:
    rows = conn.execute(
        """
        SELECT documents.*,
               document_bodies.body_sha256 AS stored_body_sha256,
               document_bodies.body_chars AS stored_body_chars
        FROM documents
        LEFT JOIN document_bodies ON document_bodies.doc_rowid = documents.rowid
        WHERE documents.doc_type = ?
        """,
        (doc_type,),
    ).fetchall()
    signatures: dict[str, dict[str, Any]] = {}
    for row in rows:
        row_keys = set(row.keys())
        doc_id = str(row["id"] or "")
        if not doc_id:
            continue
        body_preview = str(row["body"] or "")
        body_sha256 = str(row["stored_body_sha256"] or hashlib.sha256(body_preview.encode("utf-8")).hexdigest())
        body_chars = int_value(row["stored_body_chars"], len(body_preview))
        column_values = {
            key: row[key] if key in row_keys else None
            for key in SEARCH_DOCUMENT_COLUMN_KEYS
            if key != "payload_json"
        }
        signatures[doc_id] = {
            "rowid": int_value(row["rowid"]),
            "signature": search_document_storage_signature_from_parts(
                column_values=column_values,
                payload=row["payload_json"] if "payload_json" in row_keys else "",
                body_sha256=body_sha256,
                body_chars=body_chars,
                route_entries=document_route_entries(
                    row["route_layers"] if "route_layers" in row_keys else "",
                    row["route_signals"] if "route_signals" in row_keys else "",
                    doc_type=str(row["doc_type"] or ""),
                ),
            ),
        }
    return signatures


def entity_registry_snapshot_signature(payload: dict[str, Any]) -> str:
    root_text = str(payload.get("aoa_root") or "")
    return str(
        entity_registry_semantic_digest(
            payload,
            aoa_root=Path(root_text) if root_text else None,
        ).get("sha256")
        or ""
    )


def entity_registry_search_sync_meta(conn: sqlite3.Connection) -> dict[str, str]:
    rows = conn.execute(
        """
        SELECT key, value
        FROM meta
        WHERE key IN (
            'entity_registry_search_sync_version',
            'entity_registry_search_snapshot_signature',
            'entity_registry_search_document_count',
            'entity_registry_search_schema_version',
            'entity_registry_search_generation_id'
        )
        """
    ).fetchall()
    return {str(row[0]): str(row[1]) for row in rows}


def record_entity_registry_search_sync_meta(
    conn: sqlite3.Connection,
    *,
    snapshot_signature: str,
    document_count: int,
    generation_id: str,
) -> None:
    conn.executemany(
        "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
        [
            ("entity_registry_search_sync_version", str(ENTITY_REGISTRY_SEARCH_SYNC_VERSION)),
            ("entity_registry_search_snapshot_signature", snapshot_signature),
            ("entity_registry_search_document_count", str(max(0, int_value(document_count)))),
            ("entity_registry_search_schema_version", str(SEARCH_SCHEMA_VERSION)),
            ("entity_registry_search_generation_id", generation_id),
        ],
    )


def entity_registry_search_sync_current_noop(
    conn: sqlite3.Connection,
    *,
    aoa_root: Path,
    registry_state: dict[str, Any],
    observed_source: str = "auto",
    history_policy: str = (
        ENTITY_REGISTRY_HISTORY_POLICY_INCREMENTAL
    ),
) -> dict[str, Any] | None:
    if registry_state.get("needs_maintenance"):
        return None
    registry_path = aoa_root / ENTITY_REGISTRY_PATH
    registry = read_json(registry_path, {})
    if not isinstance(registry, dict) or registry.get("artifact_type") != "entity_registry_snapshot":
        return None
    requested_observed_source = route_key_slug(
        observed_source,
        fallback="auto",
    ).replace("_", "-")
    if requested_observed_source not in {
        "auto",
        "route-rollup",
        "route-terms",
        "none",
    }:
        requested_observed_source = "auto"
    history_policy_aliases = {
        "incremental": (
            ENTITY_REGISTRY_HISTORY_POLICY_INCREMENTAL
        ),
        "authoritative-rebuild": (
            ENTITY_REGISTRY_HISTORY_POLICY_AUTHORITATIVE_REBUILD
        ),
    }
    requested_history_policy = history_policy_aliases.get(
        str(history_policy or "").strip(),
        str(history_policy or "").strip(),
    )
    if requested_history_policy not in {
        ENTITY_REGISTRY_HISTORY_POLICY_INCREMENTAL,
        ENTITY_REGISTRY_HISTORY_POLICY_AUTHORITATIVE_REBUILD,
    }:
        requested_history_policy = (
            ENTITY_REGISTRY_HISTORY_POLICY_INCREMENTAL
        )
    if (
        requested_observed_source != "auto"
        and str(registry.get("observed_source") or "")
        != requested_observed_source
    ):
        return None
    if (
        str(registry.get("history_policy") or "")
        != requested_history_policy
    ):
        return None
    entity_count = int_value(registry.get("entity_count"))
    actual_count = int_value(conn.execute("SELECT COUNT(*) FROM documents WHERE doc_type = 'entity_registry'").fetchone()[0])
    if actual_count != entity_count:
        return None
    signature = entity_registry_snapshot_signature(registry)
    meta = entity_registry_search_sync_meta(conn)
    if meta.get("entity_registry_search_sync_version") != str(ENTITY_REGISTRY_SEARCH_SYNC_VERSION):
        return None
    if meta.get("entity_registry_search_schema_version") != str(SEARCH_SCHEMA_VERSION):
        return None
    expected_generation_id = str(
        session_memory_expected_generation_identities(aoa_root)[
            "lexical_search"
        ]["generation_id"]
    )
    if (
        meta.get("entity_registry_search_generation_id")
        != expected_generation_id
    ):
        return None
    if meta.get("entity_registry_search_document_count") != str(entity_count):
        return None
    if meta.get("entity_registry_search_snapshot_signature") != signature:
        return None
    return {
        "inserted_count": 0,
        "updated_count": 0,
        "unchanged_count": entity_count,
        "removed_count": 0,
        "replaced_count": 0,
        "touched_count": 0,
        "target_count": entity_count,
        "skipped": True,
        "skip_reason": "entity_registry_search_sync_current",
        "snapshot_signature": signature,
    }


def insert_search_document(
    conn: sqlite3.Connection,
    doc: dict[str, Any],
    *,
    store_raw_text: bool = True,
    storage_profile: dict[str, Any] | None = None,
    generation_identities: dict[str, dict[str, Any]] | None = None,
) -> None:
    doc = redact_derived_value(doc)
    profile = storage_profile or search_document_storage_profile(store_raw_text=store_raw_text)
    payload = search_doc_payload(doc)
    full_body = str(doc.get("body") or "")
    body_preview = bounded_storage_text(full_body, max_chars=int_value(profile.get("body_preview_chars"), SEARCH_BODY_PREVIEW_CHARS))
    route_layers_preview = bounded_packed_route_values(
        doc.get("route_layers"),
        max_chars=int_value(profile.get("route_layers_preview_chars"), SEARCH_ROUTE_LAYERS_PREVIEW_CHARS),
    )
    route_signals_preview = bounded_packed_route_values(
        doc.get("route_signals"),
        max_chars=int_value(profile.get("route_signals_preview_chars"), SEARCH_ROUTE_SIGNALS_PREVIEW_CHARS),
    )
    tags_preview = compact_search_tags_for_storage(
        doc.get("tags"),
        max_chars=int_value(profile.get("tags_preview_chars")),
        policy=str(profile.get("tags_storage_policy") or SEARCH_TAGS_STORAGE_POLICY_FULL),
    )
    raw_path_value = doc.get("raw_path") if profile.get("store_raw_path", True) else ""
    segment_index_path_value = doc.get("segment_index_path") if profile.get("store_segment_index_path", True) else ""
    route_entries = document_route_entries(
        doc.get("route_layers"),
        doc.get("route_signals"),
        doc_type=str(doc.get("doc_type") or ""),
    )
    identities = (
        generation_identities
        if isinstance(generation_identities, dict)
        else {}
    )
    lexical_generation_id = str(
        (
            identities.get("lexical_search")
            if isinstance(identities.get("lexical_search"), dict)
            else {}
        ).get("generation_id")
        or doc.get("generation_id")
        or ""
    )
    exact_generation_id = str(
        (
            identities.get("exact_literal")
            if isinstance(identities.get("exact_literal"), dict)
            else {}
        ).get("generation_id")
        or ""
    )
    cursor = conn.execute(
        """
        INSERT INTO documents (
            id, doc_type, session_id, session_label, session_title, session_date,
            cwd, archive_status, distillation_status, review_status, segment_id,
            event_id, event_type, family, phase, actor, action, object, outcome,
            conversation_act, session_act, agent_event, usage_role, task_episode_id, route_layers, route_signals, tags, raw_ref, raw_block_ref, segment_ref,
            manifest_path, raw_path, segment_index_path, raw_sha256,
            segment_index_sha256, freshness_status, stale_reason, title, body,
            payload_json, generation_id
        )
        VALUES (
            :id, :doc_type, :session_id, :session_label, :session_title, :session_date,
            :cwd, :archive_status, :distillation_status, :review_status, :segment_id,
            :event_id, :event_type, :family, :phase, :actor, :action, :object, :outcome,
            :conversation_act, :session_act, :agent_event, :usage_role, :task_episode_id, :route_layers, :route_signals, :tags, :raw_ref, :raw_block_ref, :segment_ref,
            :manifest_path, :raw_path, :segment_index_path, :raw_sha256,
            :segment_index_sha256, :freshness_status, :stale_reason, :title, :body,
            :payload_json, :generation_id
        )
        """,
        {
            **{key: doc.get(key) for key in [
                "id",
                "doc_type",
                "session_id",
                "session_label",
                "session_title",
                "session_date",
                "cwd",
                "archive_status",
                "distillation_status",
                "review_status",
                "segment_id",
                "event_id",
                "event_type",
                "family",
                "phase",
                "actor",
                "action",
                "object",
                "outcome",
                "conversation_act",
                "session_act",
                "agent_event",
                "usage_role",
                "task_episode_id",
                "raw_ref",
                "raw_block_ref",
                "segment_ref",
                "manifest_path",
                "raw_sha256",
                "segment_index_sha256",
                "freshness_status",
                "stale_reason",
                "title",
                "body",
            ]},
            "route_layers": route_layers_preview,
            "route_signals": route_signals_preview,
            "tags": tags_preview,
            "body": body_preview,
            "raw_path": raw_path_value,
            "segment_index_path": segment_index_path_value,
            "payload_json": json.dumps(payload, ensure_ascii=False, sort_keys=True),
            "generation_id": lexical_generation_id,
        },
    )
    rowid = cursor.lastrowid
    if store_raw_text:
        conn.execute(
            "INSERT INTO documents_fts(rowid, title, body, session_label, session_title) VALUES (?, ?, ?, ?, ?)",
            (rowid, doc.get("title") or "", full_body, doc.get("session_label") or "", doc.get("session_title") or ""),
        )
        body_bytes = full_body.encode("utf-8")
        conn.execute(
            "INSERT OR REPLACE INTO document_bodies(doc_rowid, body_zlib, body_sha256, body_chars) VALUES (?, ?, ?, ?)",
            (rowid, sqlite3.Binary(zlib.compress(body_bytes, level=6)), hashlib.sha256(body_bytes).hexdigest(), len(full_body)),
        )
    exact_literal_text = str(doc.get("exact_literal_text") or "").strip()
    if exact_literal_text and sqlite_table_exists(conn, "exact_literal_postings_fts"):
        conn.execute(
            "INSERT INTO exact_literal_postings_fts(rowid, text) VALUES (?, ?)",
            (rowid, exact_literal_text),
        )
        conn.execute(
            """
            INSERT OR REPLACE INTO exact_literal_posting_meta (
                doc_rowid, text_sha256, source_timestamp, source_lane,
                text_chars, generation_id
            ) VALUES (?, ?, ?, ?, ?, ?)
            """,
            (
                rowid,
                hashlib.sha256(exact_literal_text.encode("utf-8")).hexdigest(),
                str(doc.get("exact_literal_source_timestamp") or ""),
                str(doc.get("exact_literal_source_lane") or ""),
                len(exact_literal_text),
                exact_generation_id,
            ),
        )
    exact_literal_transition_text = str(doc.get("exact_literal_transition_text") or "").strip()
    if exact_literal_transition_text and sqlite_table_exists(conn, "exact_literal_transition_postings_fts"):
        conn.execute(
            "INSERT INTO exact_literal_transition_postings_fts(rowid, text) VALUES (?, ?)",
            (rowid, exact_literal_transition_text),
        )
        conn.execute(
            """
            INSERT OR REPLACE INTO exact_literal_transition_posting_meta (
                doc_rowid, text_sha256, text_chars, generation_id
            ) VALUES (?, ?, ?, ?)
            """,
            (
                rowid,
                hashlib.sha256(exact_literal_transition_text.encode("utf-8")).hexdigest(),
                len(exact_literal_transition_text),
                exact_generation_id,
            ),
        )
    if route_entries:
        postings = [(rowid, route_term_id(conn, entry)) for entry in route_entries]
        conn.executemany(
            """
            INSERT OR IGNORE INTO document_routes (
                doc_rowid, route_id
            )
            VALUES (?, ?)
            """,
            [(doc_rowid, route_id_value) for doc_rowid, route_id_value in postings if route_id_value],
        )


def search_documents_for_entity_registry(
    aoa_root: Path,
    *,
    write_snapshot: bool = False,
    route_terms_db_path: Path | None = None,
    route_terms_source_ref_path: Path | None = None,
    observed_source: str = "auto",
    history_policy: str = (
        ENTITY_REGISTRY_HISTORY_POLICY_INCREMENTAL
    ),
) -> list[dict[str, Any]]:
    registry = build_entity_registry(
        aoa_root=aoa_root,
        write=write_snapshot,
        include_runtime=True,
        route_terms_db_path=route_terms_db_path,
        route_terms_source_ref_path=route_terms_source_ref_path,
        observed_source=observed_source,
        history_policy=history_policy,
        limit=None,
    )
    registry_path = aoa_root / ENTITY_REGISTRY_PATH
    documents: list[dict[str, Any]] = []
    base = {
        "session_id": "entity-registry",
        "session_label": "entity-registry",
        "session_title": "Generated entity registry",
        "session_date": registry.get("generated_at", "")[:10],
        "cwd": str(aoa_root),
        "archive_status": "generated_navigation",
        "distillation_status": "not_reviewed_truth",
        "review_status": "generated",
        "manifest_path": str(registry_path),
        "raw_path": "",
        "raw_sha256": "",
        "freshness_status": "fresh" if registry_path.exists() else "generated_in_memory",
        "stale_reason": "",
    }

    def compact_registry_ref_path(value: Any) -> str:
        text = str(value or "")
        if not text:
            return ""
        path = Path(text)
        if path.is_absolute():
            try:
                return str(path.relative_to(aoa_root))
            except ValueError:
                parts = path.parts
                for marker in ("scripts", "skills", "config", "tests"):
                    marker_indexes = [index for index, part in enumerate(parts) if part == marker]
                    if marker_indexes:
                        return "/".join(parts[marker_indexes[-1] :])
                return "/".join(parts[-4:]) if len(parts) >= 4 else path.name
        return text

    def compact_registry_payload(entry: dict[str, Any], refs: list[dict[str, Any]]) -> dict[str, Any]:
        freshness = entry.get("freshness") if isinstance(entry.get("freshness"), dict) else {}
        compact_refs = [
            {
                "source_type": ref.get("source_type"),
                "path": compact_registry_ref_path(ref.get("path")),
                "status": ref.get("status"),
            }
            for ref in refs[:2]
            if isinstance(ref, dict)
        ]
        aliases = entry.get("aliases", []) if isinstance(entry.get("aliases"), list) else []
        return {
            "entity_id": entry.get("entity_id"),
            "kind": entry.get("kind"),
            "canonical_key": entry.get("canonical_key"),
            "aliases": aliases[:4],
            "alias_count": len(aliases),
            "status": entry.get("status"),
            "route_layer": entry.get("route_layer"),
            "route_signal": entry.get("route_signal"),
            "source_surface": entry.get("source_surface"),
            "owner": entry.get("owner"),
            "source_ref_count": len(refs),
            "source_refs_sample": compact_refs,
            "freshness": {
                "status": freshness.get("status"),
                "signal_count": freshness.get("signal_count"),
                "session_count": freshness.get("session_count"),
            },
        }

    for entry in registry.get("entries", []) if isinstance(registry.get("entries"), list) else []:
        if not isinstance(entry, dict):
            continue
        route_layer = str(entry.get("route_layer") or "")
        route_key = str(entry.get("canonical_key") or "")
        route_layers, route_signals = route_fields_from_signals(
            [{"layer": route_layer, "key": route_key}] if route_layer and route_key else []
        )
        refs = entry.get("source_refs") if isinstance(entry.get("source_refs"), list) else []
        compact_payload = compact_registry_payload(entry, refs)
        body = search_doc_text(
            [
                entry.get("entity_id"),
                entry.get("kind"),
                entry.get("canonical_key"),
                entry.get("aliases"),
                entry.get("status"),
                entry.get("source_surface"),
                entry.get("owner"),
                compact_payload.get("freshness"),
                compact_payload.get("source_refs_sample"),
            ],
            max_chars=3600,
        )
        documents.append(
            {
                **base,
                "id": f"entity_registry:{entry.get('entity_id')}",
                "doc_type": "entity_registry",
                "title": f"{entry.get('kind')} {entry.get('canonical_key')} {entry.get('status')}".strip(),
                "body": body,
                "segment_ref": str(registry_path),
                "route_layers": route_layers,
                "route_signals": route_signals,
                "tags": f"entity_registry {entry.get('kind')} {entry.get('status')}",
                "entity_registry": compact_payload,
                "truth_status": registry.get("truth_status"),
            }
        )
    return documents


def session_semantic_names_text(manifest: dict[str, Any]) -> str:
    semantic = semantic_names_payload(manifest)
    parts = [
        semantic.get("active"),
        semantic.get("active_session"),
    ]
    for item in semantic.get("names", []) if isinstance(semantic.get("names"), list) else []:
        if isinstance(item, dict):
            parts.extend([item.get("name"), item.get("slug"), item.get("scope"), item.get("coverage_note")])
    return search_doc_text(parts, max_chars=1600)


def raw_search_text_line_limits_from_segments(segments: list[dict[str, Any]]) -> dict[int, int]:
    line_limits: dict[int, int] = {}
    for segment in segments:
        if not isinstance(segment, dict):
            continue
        index_path = Path(str(segment.get("index") or ""))
        segment_index = read_json(index_path, {}) if index_path.exists() else {}
        for event in segment_index.get("events", []) if isinstance(segment_index.get("events"), list) else []:
            if not isinstance(event, dict):
                continue
            event_type = str(event.get("type") or "")
            outcome = str(event.get("outcome") or "")
            if not event_type_gets_raw_search_text(event_type, outcome):
                continue
            line_no = int_value(event.get("line"))
            if line_no <= 0:
                continue
            line_limits[line_no] = max(line_limits.get(line_no, 0), event_search_text_limit(event_type))
    return line_limits


def event_gets_exact_literal_posting(event_type: str, outcome: str) -> bool:
    return event_type_gets_raw_search_text(event_type, outcome) or (
        event_type in {"COMMAND_OUTPUT", "TOOL_OUTPUT"} and outcome not in {"failed", "blocked"}
    )


def bounded_exact_literal_posting_text(
    value: Any,
    *,
    max_chars: int = SEARCH_EXACT_LITERAL_POSTINGS_MAX_CHARS,
) -> str:
    text = re.sub(
        r"\s+",
        " ",
        redact_derived_text(value),
    ).strip()
    if max_chars <= 0 or len(text) <= max_chars:
        return text[: max(0, max_chars)]
    marker = SEARCH_EXACT_LITERAL_OMITTED_MIDDLE_MARKER
    content_budget = max_chars - len(marker) - 2
    if content_budget < 2:
        return text[:max_chars]
    head_budget = (content_budget + 1) // 2
    tail_budget = content_budget - head_budget
    head = text[:head_budget].rstrip()
    tail = text[-tail_budget:].lstrip()
    if head_budget < len(text) and re.match(r"[^\W_]", text[head_budget], flags=re.UNICODE):
        head = re.sub(r"[^\W_]+$", "", head, flags=re.UNICODE).rstrip()
    tail_start = len(text) - tail_budget
    if tail_start > 0 and re.match(r"[^\W_]", text[tail_start - 1], flags=re.UNICODE):
        tail = re.sub(r"^[^\W_]+", "", tail, flags=re.UNICODE).lstrip()
    return f"{head} {marker} {tail}".strip()[:max_chars]


def event_exact_literal_posting_text(raw_text: str, event: dict[str, Any]) -> str:
    correlation_id = str(event.get("correlation_id") or "").strip()
    if correlation_id and correlation_id.casefold() not in raw_text.casefold():
        return bounded_exact_literal_posting_text(
            f"{correlation_id} {raw_text}",
        )
    return bounded_exact_literal_posting_text(raw_text)


EXACT_LITERAL_PATCH_FIELD_ASSIGNMENT_RE = re.compile(
    r'''^\s*["']?([A-Za-z_][A-Za-z0-9_.-]*)["']?\s*[:=]\s*(.*?)\s*,?\s*$'''
)


def exact_literal_patch_transition_value(value: Any) -> str:
    text = str(value or "").strip().rstrip(",").strip()
    if len(text) >= 2 and text[0] in {'"', "'"} and text[-1] == text[0]:
        text = text[1:-1].strip()
    tokens = search_tokenize(text)
    if not text or len(text) > 160 or not tokens or len(tokens) > 12:
        return ""
    if not (re.search(r"[_./:@+-]", text) or any(len(token) >= 8 for token in tokens)):
        return ""
    return text


def exact_literal_patch_transition_summary(
    text: Any,
    *,
    max_chars: int = SEARCH_EXACT_LITERAL_PATCH_TRANSITION_MAX_CHARS,
) -> str:
    patch_text = str(text or "")
    if "*** Begin Patch" not in patch_text or max_chars <= 0:
        return ""
    transitions: list[tuple[str, str, str]] = []
    removed: dict[str, list[str]] = {}
    added: dict[str, list[str]] = {}

    def flush_change_scope() -> None:
        nonlocal removed, added
        for key in sorted(set(removed) & set(added)):
            old_values = list(dict.fromkeys(removed[key]))
            new_values = list(dict.fromkeys(added[key]))
            if len(old_values) != 1 or len(new_values) != 1 or old_values[0] == new_values[0]:
                continue
            old_value = exact_literal_patch_transition_value(old_values[0])
            new_value = exact_literal_patch_transition_value(new_values[0])
            if old_value and new_value:
                transitions.append((key, old_value, new_value))
        removed = {}
        added = {}

    for line in patch_text.splitlines():
        if line.startswith(("*** Update File:", "*** Add File:", "*** Delete File:", "@@")):
            flush_change_scope()
            continue
        if not line.startswith(("+", "-")) or line.startswith(("+++", "---")):
            continue
        match = EXACT_LITERAL_PATCH_FIELD_ASSIGNMENT_RE.match(line[1:])
        if not match:
            continue
        target = added if line.startswith("+") else removed
        target.setdefault(match.group(1), []).append(match.group(2))
    flush_change_scope()

    rendered: list[str] = []
    seen: set[tuple[str, str, str]] = set()
    rendered_chars = 0
    for key, old_value, new_value in transitions:
        transition = (key, old_value, new_value)
        if transition in seen:
            continue
        seen.add(transition)
        part = f"{old_value} -> {new_value}"
        added_chars = len(part) + (1 if rendered else 0)
        if rendered_chars + added_chars > max_chars:
            break
        rendered.append(part)
        rendered_chars += added_chars
    return " ".join(rendered)


def raw_exact_literal_line_limits_from_segments(segments: list[dict[str, Any]]) -> dict[int, int]:
    line_limits: dict[int, int] = {}
    for segment in segments:
        if not isinstance(segment, dict):
            continue
        index_path = Path(str(segment.get("index") or ""))
        segment_index = read_json(index_path, {}) if index_path.exists() else {}
        events = segment_index.get("events") if isinstance(segment_index.get("events"), list) else []
        for event in events:
            if not isinstance(event, dict):
                continue
            event_type = str(event.get("type") or "")
            outcome = str(event.get("outcome") or "")
            if not event_gets_exact_literal_posting(event_type, outcome):
                continue
            line_no = int_value(event.get("line"))
            if line_no <= 0:
                continue
            line_limits[line_no] = SEARCH_EXACT_LITERAL_POSTINGS_MAX_CHARS
    return line_limits


def exact_literal_structured_identifiers(payload: Any) -> list[str]:
    if not isinstance(payload, dict):
        return []
    payload_type = str(payload.get("type") or "")
    if payload_type not in {
        "function_call",
        "tool_call",
        "custom_tool_call",
        "function_call_output",
        "tool_call_output",
        "custom_tool_call_output",
    }:
        return []
    identifiers: list[str] = []
    for key in (
        "id",
        "call_id",
        "tool_call_id",
        "request_id",
        "run_id",
        "thread_id",
        "step_id",
        "message_id",
        "response_id",
    ):
        value = payload.get(key)
        if not isinstance(value, str):
            continue
        identifier = value.strip()
        identifier_projection = derived_text_privacy_projection(identifier)
        identifier = str(identifier_projection.get("text") or "")
        if not identifier or len(identifier) > 256 or identifier in identifiers:
            continue
        identifiers.append(identifier)
    return identifiers


def raw_event_search_text_by_line(
    raw_path: Path | None,
    *,
    line_limits: dict[int, int] | None = None,
    include_structured_identifiers: bool = False,
    exact_head_tail: bool = False,
) -> dict[int, str]:
    if not raw_path or not raw_path.exists():
        return {}
    texts: dict[int, str] = {}
    wanted_lines = set(line_limits) if line_limits is not None else None
    with raw_path.open("r", encoding="utf-8", errors="replace") as handle:
        for line_no, line in enumerate(handle, start=1):
            if wanted_lines is not None and line_no not in wanted_lines:
                continue
            raw = line.rstrip("\n")
            parsed: dict[str, Any] | None = None
            try:
                loaded = json.loads(raw)
                if isinstance(loaded, dict):
                    parsed = loaded
            except json.JSONDecodeError:
                parsed = None
            if parsed is None:
                continue
            source_type = str(parsed.get("type") or "unresolved-source")
            payload = parsed.get("payload")
            semantic = redact_derived_text(
                semantic_text_for_classification(source_type, payload)
            )
            if semantic:
                max_chars = line_limits.get(line_no, 500) if line_limits is not None else 500
                identifiers = exact_literal_structured_identifiers(payload) if include_structured_identifiers else []
                if exact_head_tail:
                    full_text = " ".join(
                        part.strip()
                        for part in (
                            search_json_text(part)
                            for part in [*identifiers, semantic]
                        )
                        if part.strip()
                    )
                    texts[line_no] = bounded_exact_literal_posting_text(
                        full_text,
                        max_chars=max_chars,
                    )
                else:
                    texts[line_no] = search_doc_text(
                        [*identifiers, semantic],
                        max_chars=max_chars,
                    )
    return texts


def raw_event_exact_literal_transitions_by_line(
    raw_path: Path | None,
    *,
    line_limits: dict[int, int] | None = None,
) -> dict[int, str]:
    if not raw_path or not raw_path.exists():
        return {}
    transitions: dict[int, str] = {}
    with raw_path.open("r", encoding="utf-8", errors="replace") as handle:
        for line_no, line in enumerate(handle, start=1):
            # Segment event types are a derived projection and older archives can
            # still classify a real apply_patch call as RAW_EVENT.  The raw
            # structured call is the stronger source for this exact lane.  A
            # cheap marker filter keeps the scan streaming and avoids decoding
            # unrelated raw events, including large tool outputs.
            if "*** Begin Patch" not in line:
                continue
            try:
                parsed = json.loads(line)
            except json.JSONDecodeError:
                continue
            if not isinstance(parsed, dict):
                continue
            source_type = str(parsed.get("type") or "unresolved-source")
            payload = parsed.get("payload") if isinstance(parsed.get("payload"), dict) else {}
            if source_type != "response_item" or str(payload.get("type") or "") not in {
                "function_call",
                "tool_call",
                "custom_tool_call",
            }:
                continue
            semantic = semantic_text_for_classification(source_type, payload)
            summary = exact_literal_patch_transition_summary(semantic)
            if summary:
                transitions[line_no] = summary
    return transitions


def raw_event_semantic_records_by_line(
    raw_path: Path | None,
    *,
    line_limits: dict[int, int] | None = None,
    resolved_lines: set[int] | None = None,
) -> dict[int, dict[str, Any]]:
    if not raw_path or not raw_path.exists():
        return {}
    records: dict[int, dict[str, Any]] = {}
    wanted_lines = set(line_limits) if line_limits is not None else None
    with raw_path.open("r", encoding="utf-8", errors="replace") as handle:
        for line_no, line in enumerate(handle, start=1):
            if wanted_lines is not None and line_no not in wanted_lines:
                continue
            try:
                parsed = json.loads(line)
            except json.JSONDecodeError:
                continue
            if not isinstance(parsed, dict):
                continue
            if resolved_lines is not None:
                resolved_lines.add(line_no)
            source_type = str(parsed.get("type") or "unresolved-source")
            payload = parsed.get("payload") if isinstance(parsed.get("payload"), dict) else {}
            semantic = redact_derived_text(
                semantic_text_for_classification(source_type, payload)
            )
            if not semantic:
                continue
            classified_event = classify_raw_event(line.rstrip("\n"), parsed, line_no)
            if classified_event.event_type in {"COMMAND", "FILE_READ", "FILE_WRITE", "DIFF", "TOOL_CALL"}:
                typed_anchors = task_episode_typed_anchors(classified_event, "actions")
            elif classified_event.event_type in {"ERROR", "COMMAND_OUTPUT", "TOOL_OUTPUT"} and classified_event.outcome in {"failed", "blocked"}:
                typed_anchors = task_episode_typed_anchors(classified_event, "failures")
            else:
                typed_anchors = []
            max_chars = line_limits.get(line_no, TASK_EPISODE_REPRESENTATION_MAX_CHARS) if line_limits is not None else TASK_EPISODE_REPRESENTATION_MAX_CHARS
            record = {
                "event_id": classified_event.event_id,
                "line": line_no,
                "raw_ref": f"raw:line:{line_no}",
                "text": short_text(semantic, max_chars=max_chars),
                "source_type": source_type,
                "payload_type": str(payload.get("type") or ""),
                "message_role": str(payload.get("role") or ""),
                "timestamp": str(parsed.get("timestamp") or ""),
                "event_type": classified_event.event_type,
                "outcome": classified_event.outcome,
                "correlation_id": classified_event.correlation_id,
                "typed_anchors": typed_anchors,
                "retrieval_control_command": task_episode_retrieval_control_command(classified_event),
                "retrieval_control_result_command": task_episode_retrieval_control_result_command(classified_event),
            }
            compact_output = str(payload.get("output") or "") if task_episode_is_structured_result(classified_event) else ""
            compact_output_lowered = compact_output.casefold()
            if (
                compact_output
                and classified_event.outcome not in {"failed", "blocked"}
                and len(compact_output) <= TASK_EPISODE_COMPACT_SUCCESS_OUTPUT_MAX_CHARS
                and len(compact_output.splitlines()) <= TASK_EPISODE_COMPACT_SUCCESS_OUTPUT_MAX_LINES
                and not any(
                    marker in compact_output_lowered
                    for marker in ("output truncated", "truncated after", "remaining output omitted")
                )
            ):
                # RawEvent retains the full raw JSON line. Keep it only for outputs that can
                # actually become compact observations; retaining large result events caused
                # linear memory growth during a real 566 MB legacy-session catch-up.
                record["classified_event"] = classified_event
            records[line_no] = record
    return records


def search_documents_for_record(
    aoa_root: Path,
    record: dict[str, Any],
    *,
    max_raw_bytes: int | None = None,
    include_raw_event_text: bool = True,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    session_dir = session_dir_from_record(record)
    manifest_path = session_dir / "session.manifest.json"
    manifest = read_json(manifest_path, {})
    if not isinstance(manifest, dict) or not manifest:
        return [], {"status": "diagnostic", "session_label": record.get("session_label"), "diagnostics": ["manifest_missing"], "document_count": 0}

    session_id = str(manifest.get("session_id") or record.get("session_id") or session_dir.name)
    display = manifest.get("display") if isinstance(manifest.get("display"), dict) else {}
    source = manifest.get("source") if isinstance(manifest.get("source"), dict) else {}
    raw = manifest.get("raw") if isinstance(manifest.get("raw"), dict) else {}
    raw_path = Path(str(raw.get("path"))) if raw.get("path") else None
    literal_policy = (
        derived_session_sensitive_literal_policy_from_raw_path(raw_path)
        if raw_path is not None and raw_path.is_file()
        else DerivedSessionSensitiveLiteralPolicy(values_by_kind={})
    )
    raw_sha = str(raw.get("sha256") or "")
    session_label = str(display.get("label") or manifest.get("session_label") or record.get("session_label") or session_dir.name)
    session_title = str(display.get("title") or manifest.get("session_title") or record.get("session_title") or "")
    session_date = str(display.get("date") or session_record_date(record))
    archive_status = str(manifest.get("archive_status") or record.get("archive_status") or "")
    distillation_status = str(manifest.get("distillation_status") or record.get("distillation_status") or "")
    review_status = str(manifest.get("review_status") or record.get("review_status") or "")
    cwd = str(source.get("cwd") or record.get("cwd") or "")
    work_context = manifest.get("work_context") if isinstance(manifest.get("work_context"), dict) else {}
    session_index_payload = read_json(session_dir / SESSION_INDEX_JSON, {})
    session_route_index_current = (
        isinstance(session_index_payload, dict)
        and not generated_session_index_stale_reasons_for_session(
            session_dir,
            session_index_payload,
        )
    )
    session_route_counts = (
        session_index_payload.get("route_signal_counts")
        if session_route_index_current and isinstance(session_index_payload.get("route_signal_counts"), dict)
        else {}
    )
    session_route_layers, session_route_signals = route_fields_from_counts(session_route_counts)
    raw_freshness = search_manifest_freshness(manifest, raw_path)
    raw_bytes = raw_path.stat().st_size if raw_path and raw_path.exists() else 0
    raw_text_status = "not_available"
    if not include_raw_event_text:
        raw_text_status = "skipped_structured_projection"
    elif raw_path and raw_path.exists():
        raw_text_status = "available"
        if max_raw_bytes is not None and raw_bytes > max_raw_bytes:
            raw_text_status = "skipped_raw_too_large"
    documents: list[dict[str, Any]] = []

    base = {
        "session_id": session_id,
        "session_label": session_label,
        "session_title": session_title,
        "session_date": session_date,
        "cwd": cwd,
        "archive_status": archive_status,
        "distillation_status": distillation_status,
        "review_status": review_status,
        "manifest_path": str(manifest_path),
        "raw_path": str(raw_path) if raw_path else "",
        "raw_sha256": raw_sha,
        "freshness_status": raw_freshness["status"],
        "stale_reason": ",".join(raw_freshness.get("reasons", [])),
    }
    raw_blocks = manifest.get("raw_blocks") if isinstance(manifest.get("raw_blocks"), dict) else {}
    session_body = search_doc_text(
        [
            session_label,
            session_title,
            session_semantic_names_text(manifest),
            archive_status,
            distillation_status,
            review_status,
            cwd,
            work_context,
            source.get("transcript_path") if isinstance(source, dict) else "",
            raw.get("source_path"),
            raw.get("indexing_status"),
            raw_blocks.get("index"),
            session_route_counts,
        ],
        max_chars=3000,
    )
    documents.append(
        {
            **base,
            "id": f"session:{session_id}",
            "doc_type": "session",
            "title": session_title or session_label,
            "body": session_body,
            "raw_ref": "",
            "raw_block_ref": "",
            "segment_ref": str(session_dir / SESSION_INDEX_MARKDOWN),
            "route_layers": session_route_layers,
            "route_signals": session_route_signals,
            "tags": "",
        }
    )

    task_episodes = session_index_task_episode_components(
        session_dir,
        session_index_payload,
    )
    task_episode_ranges = session_index_task_episode_ranges(
        session_index_payload,
        session_dir=session_dir,
    )
    event_episode_ids: dict[str, str] = {}
    for episode in task_episodes:
        if not isinstance(episode, dict):
            continue
        episode_id = str(episode.get("episode_id") or "")
        if not episode_id:
            continue
        for bucket in (
            "reasoning_refs",
            "plan_refs",
            "progress_refs",
            "answer_refs",
            "action_refs",
            "tool_refs",
            "verification_refs",
            "error_refs",
            "closeout_refs",
            "blocker_refs",
            "transition_refs",
        ):
            for ref in episode.get(bucket, []) if isinstance(episode.get(bucket), list) else []:
                if isinstance(ref, dict) and ref.get("event_id"):
                    event_episode_ids[str(ref["event_id"])] = episode_id
        start_ref = episode.get("start_user_ref") if isinstance(episode.get("start_user_ref"), dict) else {}
        if start_ref.get("event_id"):
            event_episode_ids[str(start_ref["event_id"])] = episode_id
        episode_segment_index_path = Path(str(start_ref.get("segment_index") or ""))
        episode_segment_index_sha = sha256_file(episode_segment_index_path) if episode_segment_index_path.exists() else ""
        episode_anchors = episode.get("anchors") if isinstance(episode.get("anchors"), dict) else {}
        operational_anchors = (
            episode_anchors.get("operational")
            if isinstance(episode_anchors.get("operational"), list)
            else []
        )
        episode_route_layers, episode_route_signals = route_fields_from_signals(
            [
                {
                    "layer": str(item.get("layer") or ""),
                    "key": str(item.get("key") or ""),
                    "route_signal": str(item.get("route_signal") or ""),
                }
                for item in operational_anchors
                if isinstance(item, dict) and item.get("layer") and item.get("key")
            ]
        )
        episode_body = search_doc_text(
            [
                session_label,
                session_title,
                episode_id,
                episode.get("status"),
                episode.get("confidence"),
                episode.get("context"),
                episode.get("time_span"),
                episode.get("transition"),
                start_ref,
                episode.get("intent"),
                episode.get("semantic_text"),
                episode.get("narrative"),
                episode_anchors.get("paths"),
                episode_anchors.get("correlation_ids"),
                episode.get("ambiguity_flags"),
                {
                    "reasoning_ref_count": len(episode.get("reasoning_refs", [])) if isinstance(episode.get("reasoning_refs"), list) else 0,
                    "plan_ref_count": len(episode.get("plan_refs", [])) if isinstance(episode.get("plan_refs"), list) else 0,
                    "progress_ref_count": len(episode.get("progress_refs", [])) if isinstance(episode.get("progress_refs"), list) else 0,
                    "answer_ref_count": len(episode.get("answer_refs", [])) if isinstance(episode.get("answer_refs"), list) else 0,
                    "verification_ref_count": len(episode.get("verification_refs", [])) if isinstance(episode.get("verification_refs"), list) else 0,
                    "closeout_ref_count": len(episode.get("closeout_refs", [])) if isinstance(episode.get("closeout_refs"), list) else 0,
                    "error_ref_count": len(episode.get("error_refs", [])) if isinstance(episode.get("error_refs"), list) else 0,
                },
            ],
            max_chars=20000,
        )
        documents.append(
            {
                **base,
                "id": f"task_episode:{session_id}:{episode_id}",
                "doc_type": "task_episode",
                "task_episode_id": episode_id,
                "title": f"{session_label} {episode_id} {episode.get('status') or ''}".strip(),
                "body": episode_body,
                "raw_ref": str(start_ref.get("raw_ref") or ""),
                "raw_block_ref": "",
                "segment_ref": str(start_ref.get("segment_ref") or session_dir / SESSION_INDEX_MARKDOWN),
                "segment_index_path": str(start_ref.get("segment_index") or ""),
                "segment_index_sha256": episode_segment_index_sha,
                "route_layers": episode_route_layers,
                "route_signals": episode_route_signals,
                "tags": "task_episode episode_semantic_v1 " + " ".join(str(item) for item in episode.get("ambiguity_flags", []) if item) if isinstance(episode.get("ambiguity_flags"), list) else "task_episode episode_semantic_v1",
            }
        )

    goal_lifecycles = session_index_payload.get("goal_lifecycles") if isinstance(session_index_payload.get("goal_lifecycles"), list) else []
    for lifecycle in goal_lifecycles:
        if not isinstance(lifecycle, dict):
            continue
        goal_id = str(lifecycle.get("goal_id") or "")
        if not goal_id:
            continue
        event_kinds = [str(item) for item in lifecycle.get("event_kinds", []) if item] if isinstance(lifecycle.get("event_kinds"), list) else []
        route_signal_items = [
            {"layer": "goal", "key": kind, "route_signal": route_signal_token("goal", kind)}
            for kind in event_kinds
            if kind
        ]
        route_layers, route_signals = route_fields_from_signals(route_signal_items)
        first_ref = lifecycle.get("first_ref") if isinstance(lifecycle.get("first_ref"), dict) else {}
        last_ref = lifecycle.get("last_ref") if isinstance(lifecycle.get("last_ref"), dict) else {}
        task_episode_ids = (
            [str(item) for item in lifecycle.get("task_episode_ids", []) if item]
            if isinstance(lifecycle.get("task_episode_ids"), list)
            else []
        )
        lifecycle_body = search_doc_text(
            [
                session_label,
                session_title,
                goal_id,
                lifecycle.get("goal_instance_id"),
                lifecycle.get("objective"),
                lifecycle.get("status"),
                event_kinds,
                lifecycle.get("event_ids"),
                task_episode_ids,
                lifecycle.get("raw_refs"),
                lifecycle.get("segment_refs"),
                lifecycle.get("graph_refs"),
                lifecycle.get("usage"),
                lifecycle.get("ambiguity_flags"),
            ],
            max_chars=4200,
        )
        documents.append(
            {
                **base,
                "id": f"goal_lifecycle:{session_id}:{goal_id}",
                "doc_type": "goal_lifecycle",
                "event_type": "GOAL_LIFECYCLE",
                "session_act": str(lifecycle.get("status") or ""),
                "task_episode_id": task_episode_ids[0] if task_episode_ids else "",
                "title": f"{session_label} {goal_id} {lifecycle.get('status') or ''} {lifecycle.get('objective') or ''}".strip(),
                "body": lifecycle_body,
                "raw_ref": str(first_ref.get("raw_ref") or last_ref.get("raw_ref") or ""),
                "raw_block_ref": "",
                "segment_ref": str(first_ref.get("segment_ref") or last_ref.get("segment_ref") or session_dir / SESSION_INDEX_MARKDOWN),
                "segment_index_path": str(first_ref.get("segment_index") or last_ref.get("segment_index") or ""),
                "route_layers": route_layers,
                "route_signals": route_signals,
                "tags": "goal_lifecycle "
                + " ".join(str(item) for item in lifecycle.get("ambiguity_flags", []) if item)
                if isinstance(lifecycle.get("ambiguity_flags"), list)
                else "goal_lifecycle",
            }
        )

    for incident_path in sorted((session_dir / "incidents").glob("*")):
        if not incident_path.is_file() or incident_path.suffix not in {".md", ".json"}:
            continue
        text = short_text(incident_path.read_text(encoding="utf-8", errors="replace"), max_chars=3000)
        documents.append(
            {
                **base,
                "id": f"incident:{session_id}:{incident_path.name}",
                "doc_type": "incident",
                "title": incident_path.name,
                "body": search_doc_text([session_label, session_title, archive_status, text], max_chars=3600),
                "raw_ref": "",
                "raw_block_ref": "",
                "segment_ref": str(incident_path),
                "route_layers": session_route_layers,
                "route_signals": session_route_signals,
                "tags": "incident",
            }
        )

    segments = manifest.get("segments") if isinstance(manifest.get("segments"), list) else []
    raw_text_by_line = (
        {}
        if raw_text_status in {"skipped_raw_too_large", "skipped_structured_projection"}
        else raw_event_search_text_by_line(raw_path, line_limits=raw_search_text_line_limits_from_segments(segments))
    )
    raw_exact_literal_by_line = (
        {}
        if raw_text_status == "skipped_structured_projection"
        else raw_event_search_text_by_line(
            raw_path,
            line_limits=raw_exact_literal_line_limits_from_segments(segments),
            include_structured_identifiers=True,
            exact_head_tail=True,
        )
    )
    raw_exact_literal_transitions_by_line = (
        {}
        if raw_text_status == "skipped_structured_projection"
        else raw_event_exact_literal_transitions_by_line(
            raw_path,
            line_limits=raw_exact_literal_line_limits_from_segments(segments),
        )
    )
    (
        expected_segment_publish_id,
        expected_segment_raw_sha256,
    ) = session_manifest_projection_expectations(manifest)
    for segment in segments:
        if not isinstance(segment, dict):
            continue
        segment_id = str(segment.get("segment_id") or "")
        index_path = Path(str(segment.get("index") or ""))
        segment_index = read_json(index_path, {}) if index_path.exists() else {}
        segment_sha = sha256_file(index_path) if index_path.exists() else ""
        segment_freshness = segment_index_freshness(index_path if index_path.exists() else None, segment_sha)
        segment_route_index_current = (
            isinstance(segment_index, dict)
            and generated_segment_index_is_current(
                segment_index,
                expected_publish_id=expected_segment_publish_id,
                expected_raw_sha256=expected_segment_raw_sha256,
            )
        )
        if not segment_route_index_current:
            segment_freshness.setdefault("reasons", []).extend(
                generated_segment_index_stale_reasons(
                    segment_index
                    if isinstance(segment_index, dict)
                    else {},
                    expected_publish_id=expected_segment_publish_id,
                    expected_raw_sha256=expected_segment_raw_sha256,
                )
            )
            segment_freshness["status"] = "stale"
        freshness = combine_freshness(raw_freshness, segment_freshness)
        segment_route_layers, segment_route_signals = route_fields_from_counts(
            segment_index.get("by_route_layer") if segment_route_index_current and isinstance(segment_index.get("by_route_layer"), dict) else {}
        )
        source_block = segment.get("raw_block") if isinstance(segment.get("raw_block"), dict) else {}
        source_range = segment.get("source_range") if isinstance(segment.get("source_range"), dict) else {}
        segment_body = search_doc_text(
            [
                session_label,
                session_title,
                segment.get("role"),
                source_range,
                source_block.get("rel"),
                " ".join((segment_index.get("by_type") or {}).keys()) if isinstance(segment_index.get("by_type"), dict) else "",
                " ".join((segment_index.get("by_conversation_act") or {}).keys()) if isinstance(segment_index.get("by_conversation_act"), dict) else "",
                " ".join((segment_index.get("by_session_act") or {}).keys()) if isinstance(segment_index.get("by_session_act"), dict) else "",
                " ".join((segment_index.get("by_route_signal") or {}).keys()) if segment_route_index_current and isinstance(segment_index.get("by_route_signal"), dict) else "",
            ],
            max_chars=2600,
        )
        documents.append(
            {
                **base,
                "id": f"segment:{session_id}:{segment_id}",
                "doc_type": "segment",
                "segment_id": segment_id,
                "raw_block_ref": source_block.get("rel") or "",
                "segment_ref": str(segment.get("markdown") or ""),
                "segment_index_path": str(index_path),
                "segment_index_sha256": segment_sha,
                "freshness_status": freshness["status"],
                "stale_reason": ",".join(freshness.get("reasons", [])),
                "title": f"{session_label} segment {segment_id} {segment.get('role') or ''}".strip(),
                "body": segment_body,
                "raw_ref": "",
                "route_layers": segment_route_layers,
                "route_signals": segment_route_signals,
                "tags": "segment",
            }
        )

        for event in segment_index.get("events", []) if isinstance(segment_index.get("events"), list) else []:
            if not isinstance(event, dict):
                continue
            facets = event.get("facets") if isinstance(event.get("facets"), dict) else {}
            conversation_act = facets.get("conversation_act") if isinstance(facets.get("conversation_act"), dict) else {}
            session_act = facets.get("session_act") if isinstance(facets.get("session_act"), dict) else {}
            agent_event = facets.get("agent_event") if isinstance(facets.get("agent_event"), dict) else {}
            agent_event_class = str(agent_event.get("class") or "")
            line_no = int_value(event.get("line"))
            task_episode_id = (
                event_episode_ids.get(
                    str(event.get("event_id") or ""),
                    "",
                )
                or task_episode_id_for_indexed_event_line(
                    line_no,
                    task_episode_ranges,
                )
            )
            route_layers, route_signals = route_fields_from_signals(facets.get("route_signals")) if segment_route_index_current else ("", "")
            event_type = str(event.get("type") or "")
            raw_text = raw_text_by_line.get(line_no, "")
            exact_literal_text = event_exact_literal_posting_text(
                raw_exact_literal_by_line.get(line_no, ""),
                event,
            )
            exact_literal_transition_text = raw_exact_literal_transitions_by_line.get(line_no, "")
            structured_skill = (
                facets.get("structured_skill_input")
                if isinstance(facets.get("structured_skill_input"), dict)
                else {}
            )
            if structured_skill:
                raw_text = structured_skill_semantic_text(structured_skill)
            tags = " ".join(str(tag) for tag in event.get("tags", []) if tag) if isinstance(event.get("tags"), list) else ""
            exact_literal_source_lane = str(agent_event.get("source_lane") or agent_event_source_from_tags(tags) or "")
            command = facets.get("command") or facets.get("tool_name") or facets.get("payload_type")
            event_body = search_doc_text(
                [
                    event.get("title"),
                    raw_text,
                    tags,
                    event_type,
                    event.get("family"),
                    event.get("phase"),
                    event.get("actor"),
                    event.get("action"),
                    event.get("object"),
                    event.get("outcome"),
                    conversation_act.get("kind"),
                    conversation_act.get("intent"),
                    session_act.get("kind"),
                    agent_event_class,
                    task_episode_id,
                    session_act.get("memory_surface"),
                    session_act.get("tool_namespace"),
                    route_layers,
                    route_signals,
                    command,
                    event.get("raw_ref"),
                    event.get("md_anchor"),
                ],
                max_chars=3600,
            )
            documents.append(
                {
                    **base,
                    "id": f"event:{session_id}:{segment_id}:{event.get('event_id')}",
                    "doc_type": "event",
                    "segment_id": segment_id,
                    "event_id": str(event.get("event_id") or ""),
                    "event_type": event_type,
                    "family": str(event.get("family") or ""),
                    "phase": str(event.get("phase") or ""),
                    "actor": str(event.get("actor") or ""),
                    "action": str(event.get("action") or ""),
                    "object": str(event.get("object") or ""),
                    "outcome": str(event.get("outcome") or ""),
                    "conversation_act": str(conversation_act.get("kind") or ""),
                    "session_act": str(session_act.get("kind") or ""),
                    "agent_event": agent_event_class,
                    "usage_role": entity_usage_event_role(
                        event_type,
                        str(conversation_act.get("kind") or ""),
                        str(session_act.get("kind") or ""),
                    ),
                    "task_episode_id": task_episode_id,
                    "route_layers": route_layers,
                    "route_signals": route_signals,
                    "tags": tags,
                    "raw_ref": str(event.get("raw_ref") or ""),
                    "raw_block_ref": source_block.get("rel") or "",
                    "segment_ref": str(event.get("md_anchor") or segment.get("markdown") or ""),
                    "segment_index_path": str(index_path),
                    "segment_index_sha256": segment_sha,
                    "freshness_status": freshness["status"],
                    "stale_reason": ",".join(freshness.get("reasons", [])),
                    "title": str(event.get("title") or event_type or "event"),
                    "body": event_body,
                    "exact_literal_text": exact_literal_text,
                    "exact_literal_transition_text": exact_literal_transition_text,
                    "exact_literal_source_timestamp": str(event.get("timestamp") or ""),
                    "exact_literal_source_lane": exact_literal_source_lane,
                }
            )
    documents = redact_derived_value(
        documents,
        literal_policy=literal_policy,
    )
    return documents, {
        "status": "indexed",
        "session_id": session_id,
        "session_label": session_label,
        "document_count": len(documents),
        "raw_text_status": raw_text_status,
        "exact_literal_status": (
            "skipped_structured_projection"
            if raw_text_status == "skipped_structured_projection"
            else (
                "deferred_live"
                if (raw_freshness.get("live_source") or {}).get("status") == "deferred"
                else (
                    "stale_readable"
                    if (raw_freshness.get("live_source") or {}).get("status") == "stale"
                    else ("current" if raw_path and raw_path.exists() else "raw_unavailable")
                )
            )
        ),
        "include_raw_event_text": include_raw_event_text,
        "raw_bytes": raw_bytes,
        "max_raw_bytes": max_raw_bytes,
        "diagnostics": [],
        "derived_text_redaction": {
            "policy_version": DERIVED_TEXT_REDACTION_POLICY_VERSION,
            "session_sensitive_literals": literal_policy.report(),
        },
    }


def search_slow_session_rows(
    session_timings: list[dict[str, Any]],
    *,
    limit: int = OPS_SLOW_SESSION_SAMPLE_LIMIT,
) -> list[dict[str, Any]]:
    rows = sorted(
        (item for item in session_timings if isinstance(item, dict)),
        key=lambda item: int_value(item.get("elapsed_ms")),
        reverse=True,
    )
    compact_rows: list[dict[str, Any]] = []
    for item in rows[: max(0, limit)]:
        compact_rows.append(
            {
                key: item.get(key)
                for key in (
                    "session_id",
                    "session_label",
                    "shard",
                    "record_index",
                    "selected_count",
                    "status",
                    "active_phase",
                    "active_phase_elapsed_ms",
                    "raw_text_status",
                    "document_count",
                    "candidate_document_count",
                    "removed_document_count",
                    "elapsed_ms",
                    "documents_per_second",
                    "warning",
                )
                if key in item
            }
        )
    return compact_rows


def search_index_sessions(
    *,
    aoa_root: Path,
    target: str = "all",
    since: str | None = None,
    until: str | None = None,
    limit: int | None = None,
    max_raw_bytes: int | None = None,
    use_default_raw_lexical_budget: bool = True,
    rebuild: bool = True,
    write_report: bool = False,
    selected_records: list[dict[str, Any]] | None = None,
    budget_seconds: float | None = None,
    progress_every: int = 0,
    db_path_override: Path | None = None,
    refresh_catalog: bool = True,
    include_entity_registry: bool = True,
    include_raw_event_text: bool = True,
    store_raw_text: bool = True,
    projection_storage_mode: str | None = None,
    context_tail_omission_policy: str = SEARCH_CONTEXT_TAIL_OMISSION_POLICY_AUTO,
    source_scope_complete: bool | None = None,
) -> dict[str, Any]:
    now = utc_now()
    started = time.monotonic()
    deadline = started + budget_seconds if budget_seconds is not None and budget_seconds > 0 else None
    db_path = db_path_override or search_db_path(aoa_root)
    raw_lexical_policy = search_raw_lexical_policy(
        max_raw_bytes,
        use_default_budget=use_default_raw_lexical_budget,
    )
    effective_max_raw_bytes = raw_lexical_policy.get("effective_max_raw_bytes")
    effective_body_storage_mode = projection_storage_mode or (
        SEARCH_BODY_STORAGE_MODE if store_raw_text else SEARCH_STRUCTURED_SHARD_BODY_STORAGE_MODE
    )
    effective_fts_storage_mode = SEARCH_FTS_STORAGE_MODE if store_raw_text else SEARCH_STRUCTURED_SHARD_FTS_STORAGE_MODE
    raw_text_query_support = (
        SEARCH_RAW_TEXT_QUERY_SUPPORT_FULL if store_raw_text else SEARCH_RAW_TEXT_QUERY_SUPPORT_MONOLITH_FALLBACK
    )
    storage_profile = search_document_storage_profile(store_raw_text=store_raw_text)
    requested_context_tail_omission_policy = normalize_search_context_tail_omission_policy(context_tail_omission_policy)
    policy_resolution = search_context_tail_omission_policy_resolution(
        aoa_root=aoa_root,
        requested_policy=requested_context_tail_omission_policy,
        structured_only=not store_raw_text,
        shard_keys=[search_shard_key_from_db_path(db_path)] if db_path_override is not None else [],
    )
    effective_context_tail_omission_policy = (
        SEARCH_CONTEXT_TAIL_OMISSION_POLICY_KEEP_ALL
        if store_raw_text
        else str(policy_resolution.get("resolved_policy") or SEARCH_CONTEXT_TAIL_OMISSION_POLICY_KEEP_ALL)
    )
    write_db_path = db_path
    temp_db_path: Path | None = None
    if rebuild:
        temp_db_path = search_rebuild_temp_path(db_path)
        cleanup_search_rebuild_temp(temp_db_path)
        write_db_path = temp_db_path
    try:
        if selected_records is not None:
            records = selected_records
        elif target and target != "all":
            records = [resolve_session_record(aoa_root, target)]
        else:
            records = chronological_session_records(aoa_root, since=since, until=until, limit=limit)
    except ValueError as exc:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "search_index",
            "search_schema_version": SEARCH_SCHEMA_VERSION,
            "generated_at": now,
            "ok": False,
            "target": target,
            "selected_count": 0,
            "document_count": 0,
            "max_raw_bytes": effective_max_raw_bytes,
            "requested_max_raw_bytes": max_raw_bytes,
            "raw_lexical_policy": raw_lexical_policy,
            "search_body_storage_mode": effective_body_storage_mode,
            "search_fts_storage_mode": effective_fts_storage_mode,
            "raw_text_query_support": raw_text_query_support,
            "requested_context_tail_omission_policy": requested_context_tail_omission_policy,
            "context_tail_omission_policy": effective_context_tail_omission_policy,
            "context_tail_omission_policy_resolution": policy_resolution,
            "db_path": str(db_path),
            "diagnostics": [str(exc)],
            "sessions": [],
        }
    inferred_source_scope_complete = bool(
        selected_records is None
        and target == "all"
        and since is None
        and until is None
        and limit is None
        and db_path_override is None
    )
    requested_source_scope_complete = (
        inferred_source_scope_complete
        if source_scope_complete is None
        else bool(source_scope_complete)
    )
    effective_source_scope_complete = bool(
        requested_source_scope_complete
        and session_registry_source_set_is_complete(aoa_root)
    )
    previous_source_set_identity: dict[str, Any] = {}
    source_set_tombstones: list[dict[str, Any]] = []
    if db_path.exists():
        previous_conn: sqlite3.Connection | None = None
        try:
            previous_conn = connect_existing_search_db(db_path)
            previous_metadata = search_index_metadata(previous_conn)
            previous_source_set_identity = (
                search_source_set_identity_from_metadata(
                    previous_metadata
                )
            )
            if effective_source_scope_complete:
                source_set_tombstones = (
                    search_projection_orphaned_session_states(
                        previous_conn,
                        active_session_ids=(
                            search_source_set_session_ids_for_records(
                                records
                            )
                        ),
                    )
                )
        except sqlite3.Error:
            previous_source_set_identity = {}
            source_set_tombstones = []
        finally:
            if previous_conn is not None:
                previous_conn.close()
    if source_set_tombstones and not rebuild:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "search_index",
            "search_schema_version": SEARCH_SCHEMA_VERSION,
            "generated_at": now,
            "ok": False,
            "status": "deferred_source_set_replacement_to_deep",
            "target": target,
            "selected_count": len(records),
            "processed_count": 0,
            "remaining_count": len(source_set_tombstones),
            "document_count": 0,
            "removed_document_count": 0,
            "source_scope_complete": effective_source_scope_complete,
            "source_set_tombstone_count": len(
                source_set_tombstones
            ),
            "source_set_tombstones": source_set_tombstones,
            "exact_next_command": [
                "python3",
                "scripts/aoa_session_memory.py",
                "auto-maintenance",
                "deep",
                "all",
                "--aoa-root",
                str(aoa_root),
                "--apply",
                "--write-report",
            ],
            "diagnostics": [
                "search_source_set_removed_clean_replacement_required"
            ],
            "truth_status": (
                "generated_projection_retirement_not_raw_deletion"
            ),
            "sessions": [],
        }
    authoritative_empty_rebuild = bool(
        not records
        and rebuild
        and effective_source_scope_complete
        and previous_source_set_identity
    )
    if not records and not authoritative_empty_rebuild:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "search_index",
            "search_schema_version": SEARCH_SCHEMA_VERSION,
            "generated_at": now,
            "ok": False,
            "target": target,
            "selected_count": 0,
            "document_count": 0,
            "max_raw_bytes": effective_max_raw_bytes,
            "requested_max_raw_bytes": max_raw_bytes,
            "raw_lexical_policy": raw_lexical_policy,
            "search_body_storage_mode": effective_body_storage_mode,
            "search_fts_storage_mode": effective_fts_storage_mode,
            "raw_text_query_support": raw_text_query_support,
            "requested_context_tail_omission_policy": requested_context_tail_omission_policy,
            "context_tail_omission_policy": effective_context_tail_omission_policy,
            "context_tail_omission_policy_resolution": policy_resolution,
            "db_path": str(db_path),
            "diagnostics": ["no sessions selected"],
            "sessions": [],
        }
    conn = init_search_db(write_db_path, rebuild=rebuild, create_indexes=not rebuild, budget_deadline=deadline)
    generation_identities = session_memory_expected_generation_identities(
        aoa_root
    )
    if deadline is not None:
        conn.set_progress_handler(lambda: 1 if time.monotonic() >= deadline else 0, 10000)
    if rebuild:
        reset_search_db(conn)
        conn.commit()
    counts: Counter[str] = Counter()
    removed_document_count = 0
    diagnostics: list[str] = []
    session_results: list[dict[str, Any]] = []
    session_timings: list[dict[str, Any]] = []
    raw_text_status_counts: Counter[str] = Counter()
    phase_timings: list[dict[str, Any]] = []
    inline_optimize_count = 0
    committed_count = 0
    removed_entity_registry_document_count = 0
    inserted_entity_registry_document_count = 0
    updated_entity_registry_document_count = 0
    unchanged_entity_registry_document_count = 0
    context_tail_omission_counts: Counter[str] = Counter()
    context_tail_omission_session_samples: list[dict[str, Any]] = []
    exact_literal_posting_document_count = 0
    exact_literal_transition_posting_document_count = 0
    exact_literal_session_status_counts: Counter[str] = Counter()
    episode_semantic_document_count = 0
    episode_semantic_session_status_counts: Counter[str] = Counter()
    budget_exhausted = False
    active_session: dict[str, Any] | None = None
    active_session_started = 0.0
    active_phase_started = 0.0
    progress_telemetry = BestEffortJsonProgressEmitter(
        enabled=progress_every > 0
    )

    def progress_event(event: str, payload: dict[str, Any]) -> None:
        packet = {
            "event": event,
            "elapsed_ms": int((time.monotonic() - started) * 1000),
            **payload,
        }
        progress_telemetry.emit(packet)

    def record_phase(phase: str, phase_started: float, **extra: Any) -> None:
        item = {
            "phase": phase,
            "elapsed_ms": int((time.monotonic() - phase_started) * 1000),
            **extra,
        }
        phase_timings.append(item)
        progress_event("search_index_phase_done", item)

    def set_active_phase(phase: str, **extra: Any) -> None:
        nonlocal active_phase_started
        active_phase_started = time.monotonic()
        if active_session is not None:
            active_session["active_phase"] = phase
            active_session.update(extra)

    def active_session_snapshot() -> dict[str, Any]:
        if active_session is None:
            return {}
        row = dict(active_session)
        elapsed_ms = int((time.monotonic() - active_session_started) * 1000) if active_session_started else 0
        phase_elapsed_ms = int((time.monotonic() - active_phase_started) * 1000) if active_phase_started else 0
        row["elapsed_ms"] = elapsed_ms
        row["active_phase_elapsed_ms"] = phase_elapsed_ms
        row["warning"] = elapsed_ms >= OPS_SEARCH_SESSION_WARNING_MS
        return row

    def remaining_session_samples() -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        snapshot = active_session_snapshot()
        if snapshot:
            rows.append(snapshot)
            start_index = int_value(snapshot.get("record_index"))
        else:
            start_index = committed_count
        for offset, record in enumerate(records[start_index : start_index + max(0, OPS_SLOW_SESSION_SAMPLE_LIMIT - len(rows))], start=1):
            rows.append(
                search_record_route_sample(
                    record,
                    record_index=start_index + offset,
                    selected_count=len(records),
                    extra={"active_phase": "pending"},
                )
            )
        return rows

    try:
        conn.execute("INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)", ("schema_version", str(SEARCH_SCHEMA_VERSION)))
        conn.execute("INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)", ("generated_at", now))
        conn.execute("INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)", ("aoa_root", str(aoa_root)))
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            (
                "generation_identities_json",
                json.dumps(
                    generation_identities,
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ),
            ),
        )
        if effective_source_scope_complete:
            published_source_set_identity = (
                search_source_set_identity_for_records(records)
            )
        elif previous_source_set_identity:
            published_source_set_identity = (
                search_source_set_identity_for_session_ids(
                    [
                        *previous_source_set_identity.get(
                            "session_ids", []
                        ),
                        *search_source_set_session_ids_for_records(
                            records
                        ),
                    ]
                )
            )
        else:
            published_source_set_identity = {}
        if published_source_set_identity:
            conn.execute(
                "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
                (
                    SEARCH_SOURCE_SET_META_KEY,
                    json.dumps(
                        published_source_set_identity,
                        ensure_ascii=False,
                        sort_keys=True,
                        separators=(",", ":"),
                    ),
                ),
            )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_body_storage_mode", effective_body_storage_mode if rebuild else f"{effective_body_storage_mode}_mixed"),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_fts_storage_mode", effective_fts_storage_mode),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_raw_text_query_support", raw_text_query_support),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_projection_storage_mode", effective_body_storage_mode),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_payload_storage_mode", SEARCH_PAYLOAD_STORAGE_MODE if rebuild else f"{SEARCH_PAYLOAD_STORAGE_MODE}_mixed"),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_document_storage_profile", str(storage_profile.get("name") or "")),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_index_profile", SEARCH_INDEX_PROFILE),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_ref_path_storage_policy", str(storage_profile.get("ref_path_storage_policy") or "")),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_body_preview_chars", str(storage_profile.get("body_preview_chars") or "")),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_route_layers_preview_chars", str(storage_profile.get("route_layers_preview_chars") or "")),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_route_signals_preview_chars", str(storage_profile.get("route_signals_preview_chars") or "")),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_tags_preview_chars", str(storage_profile.get("tags_preview_chars") or "")),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_tags_storage_policy", str(storage_profile.get("tags_storage_policy") or "")),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_route_posting_policy_mode", SEARCH_ROUTE_POSTING_POLICY_MODE),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_context_tail_omission_policy", effective_context_tail_omission_policy),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_requested_context_tail_omission_policy", requested_context_tail_omission_policy),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_context_tail_omission_policy_source", str(policy_resolution.get("source") or "")),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_aggregate_route_posting_doc_types", ",".join(sorted(SEARCH_AGGREGATE_ROUTE_POSTING_DOC_TYPES))),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            (
                "search_aggregate_route_posting_default_layer_limit",
                str(SEARCH_AGGREGATE_ROUTE_POSTING_DEFAULT_LAYER_LIMIT),
            ),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_raw_lexical_policy_mode", str(raw_lexical_policy.get("mode") or "")),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_raw_lexical_policy_source", str(raw_lexical_policy.get("source") or "")),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            (
                "search_raw_lexical_max_bytes",
                "unbounded" if effective_max_raw_bytes is None else str(effective_max_raw_bytes),
            ),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_raw_lexical_default_max_bytes", str(SEARCH_RAW_LEXICAL_DEFAULT_MAX_BYTES)),
        )
        conn.execute(
            "INSERT OR REPLACE INTO meta(key, value) VALUES (?, ?)",
            ("search_raw_lexical_skip_status", str(raw_lexical_policy.get("skip_status") or "skipped_raw_too_large")),
        )
        conn.commit()
        bulk_started = time.monotonic()
        for record_index, record in enumerate(records, start=1):
            if deadline is not None and record_index > 1 and time.monotonic() >= deadline:
                budget_exhausted = True
                break
            record_started = time.monotonic()
            active_session_started = record_started
            active_session = search_record_route_sample(
                record,
                record_index=record_index,
                selected_count=len(records),
                extra={"active_phase": "begin"},
            )
            conn.execute("BEGIN")
            set_active_phase("projection_fingerprint")
            projection_state = session_projection_fingerprint(record, include_rendered_markdown=False)
            if active_session is not None:
                active_session.update(
                    {
                        "source_fingerprint": str(projection_state.get("fingerprint") or ""),
                        "source_latest_mtime": ops_float_value(projection_state.get("latest_source_mtime")),
                        "source_path_count": int_value(projection_state.get("source_path_count")),
                    }
                )
            set_active_phase("document_generation")
            documents, result = search_documents_for_record(
                aoa_root,
                record,
                max_raw_bytes=effective_max_raw_bytes,
                include_raw_event_text=include_raw_event_text,
            )
            result["source_fingerprint"] = str(
                projection_state.get("fingerprint") or ""
            )
            documents, omission_summary, omitted_route_ref_rows = apply_search_context_tail_omission_policy(
                documents,
                policy=effective_context_tail_omission_policy if not store_raw_text else SEARCH_CONTEXT_TAIL_OMISSION_POLICY_KEEP_ALL,
            )
            omission_counts = omission_summary.get("counts") if isinstance(omission_summary.get("counts"), dict) else {}
            context_tail_omission_counts.update({str(key): int_value(value) for key, value in omission_counts.items()})
            if int_value(omission_summary.get("omitted_document_count")) > 0:
                context_tail_omission_session_samples.append(
                    {
                        "session_id": str(result.get("session_id") or record.get("session_id") or ""),
                        "session_label": str(result.get("session_label") or record.get("session_label") or ""),
                        "omitted_document_count": omission_summary.get("omitted_document_count"),
                        "candidate_context_tail_count": omission_summary.get("candidate_context_tail_count"),
                        "route_ref_backed_omission_candidate_count": omission_summary.get(
                            "route_ref_backed_omission_candidate_count"
                        ),
                        "unrouted_keep_candidate_count": omission_summary.get("unrouted_keep_candidate_count"),
                        "omitted_examples": omission_summary.get("omitted_examples", []),
                    }
                )
            if active_session is not None:
                active_session.update(
                    {
                        "session_id": str(result.get("session_id") or active_session.get("session_id") or ""),
                        "session_label": str(result.get("session_label") or active_session.get("session_label") or ""),
                        "status": result.get("status"),
                        "raw_text_status": result.get("raw_text_status"),
                        "candidate_document_count": int_value(omission_summary.get("input_document_count"), len(documents)),
                        "context_tail_omission_policy": effective_context_tail_omission_policy,
                        "context_tail_omitted_document_count": omission_summary.get("omitted_document_count"),
                        "context_tail_omitted_route_ref_row_count": omission_summary.get("omitted_route_ref_row_count"),
                        "indexed_document_count_after_omission": len(documents),
                    }
                )
            session_results.append(result)
            raw_text_status_counts[str(result.get("raw_text_status") or "unknown")] += 1
            record_counts: Counter[str] = Counter()
            record_removed_document_count = 0
            if result.get("diagnostics"):
                diagnostics.extend(str(item) for item in result.get("diagnostics", []))
            if not rebuild:
                set_active_phase("delete_existing_documents")
                record_removed_document_count = delete_search_documents_for_session(
                    conn,
                    session_label=str(result.get("session_label") or record.get("session_label") or session_dir_from_record(record).name),
                    session_id=str(record.get("session_id") or ""),
                )
                if active_session is not None:
                    active_session["removed_document_count"] = record_removed_document_count
            set_active_phase("insert_documents")
            omitted_route_ref_row_count = insert_omitted_context_tail_route_refs(conn, omitted_route_ref_rows)
            if active_session is not None:
                active_session["omitted_route_ref_row_count"] = omitted_route_ref_row_count
            for doc in documents:
                doc["generation_id"] = str(
                    generation_identities["lexical_search"][
                        "generation_id"
                    ]
                )
                insert_search_document(
                    conn,
                    doc,
                    store_raw_text=store_raw_text,
                    storage_profile=storage_profile,
                    generation_identities=generation_identities,
                )
                record_counts[str(doc.get("doc_type") or "unknown")] += 1
            record_exact_literal_posting_count = sum(
                1 for doc in documents if str(doc.get("exact_literal_text") or "").strip()
            )
            exact_literal_posting_document_count += record_exact_literal_posting_count
            record_exact_literal_transition_posting_count = sum(
                1 for doc in documents if str(doc.get("exact_literal_transition_text") or "").strip()
            )
            exact_literal_transition_posting_document_count += record_exact_literal_transition_posting_count
            exact_literal_status = str(result.get("exact_literal_status") or "not_materialized")
            exact_literal_session_status_counts[exact_literal_status] += 1
            set_active_phase("episode_semantic_projection")
            episode_semantic_projection = insert_episode_semantic_projection_for_session(
                conn,
                session_dir=session_dir_from_record(record),
                projection_state=projection_state,
                indexed_at=now,
                generation_identity=generation_identities[
                    "episode_semantic"
                ],
            )
            record_episode_semantic_count = int_value(episode_semantic_projection.get("episode_count"))
            episode_semantic_document_count += record_episode_semantic_count
            episode_semantic_status = str(episode_semantic_projection.get("status") or "unknown")
            episode_semantic_session_status_counts[episode_semantic_status] += 1
            result["episode_semantic_projection"] = episode_semantic_projection
            if active_session is not None:
                active_session["episode_semantic_document_count"] = record_episode_semantic_count
                active_session["episode_semantic_status"] = episode_semantic_status
            set_active_phase("session_state_upsert")
            upsert_search_session_state(
                conn,
                projection_state=projection_state,
                indexed_at=now,
                document_count=len(documents),
                generation_identity=generation_identities[
                    "lexical_search"
                ],
            )
            upsert_exact_literal_session_state(
                conn,
                projection_state=projection_state,
                indexed_at=now,
                status=exact_literal_status,
                posting_document_count=record_exact_literal_posting_count,
                generation_identity=generation_identities[
                    "exact_literal"
                ],
            )
            set_active_phase("commit")
            conn.commit()
            counts.update(record_counts)
            removed_document_count += record_removed_document_count
            committed_count += 1
            record_elapsed_ms = int((time.monotonic() - record_started) * 1000)
            record_document_count = len(documents)
            record_elapsed_seconds = record_elapsed_ms / 1000.0 if record_elapsed_ms > 0 else 0.0
            session_timings.append(
                {
                    "session_id": str(result.get("session_id") or record.get("session_id") or ""),
                    "session_label": str(result.get("session_label") or record.get("session_label") or ""),
                    "status": result.get("status"),
                    "raw_text_status": result.get("raw_text_status"),
                    "document_count": record_document_count,
                    "removed_document_count": record_removed_document_count,
                    "elapsed_ms": record_elapsed_ms,
                    "documents_per_second": round(record_document_count / record_elapsed_seconds, 2)
                    if record_elapsed_seconds > 0 and record_document_count > 0
                    else None,
                    "warning": record_elapsed_ms >= OPS_SEARCH_SESSION_WARNING_MS,
                }
            )
            active_session = None
            if progress_every > 0 and record_index % progress_every == 0:
                progress_event(
                    "search_index_progress",
                    {
                        "processed": record_index,
                        "selected_count": len(records),
                    },
                )
            optimize_every = SEARCH_REBUILD_INLINE_OPTIMIZE_EVERY if rebuild else SEARCH_INCREMENTAL_INLINE_OPTIMIZE_EVERY
            if optimize_every > 0 and record_index % optimize_every == 0:
                conn.execute("PRAGMA optimize")
                inline_optimize_count += 1
        record_phase(
            "session_bulk_index",
            bulk_started,
            selected_count=len(records),
            processed_count=committed_count,
            inline_optimize_count=inline_optimize_count,
        )
        if rebuild:
            index_started = time.monotonic()
            progress_event("search_index_phase_start", {"phase": "sqlite_index_build"})
            index_timings = create_search_db_indexes(
                conn,
                progress_callback=lambda event, payload: progress_event(
                    event,
                    {"phase": "sqlite_index_build", **payload},
                ),
            )
            conn.commit()
            record_phase(
                "sqlite_index_build",
                index_started,
                index_count=len(index_timings),
                index_timings=index_timings,
            )
        if include_entity_registry and not budget_exhausted and (deadline is None or time.monotonic() < deadline):
            registry_started = time.monotonic()
            progress_event("search_index_phase_start", {"phase": "entity_registry_refresh"})
            registry_state = entity_registry_maintenance_status(aoa_root)
            registry_snapshot = read_json(
                aoa_root / ENTITY_REGISTRY_PATH,
                {},
            )
            registry_observed_source = (
                "route-terms"
                if rebuild
                else str(
                    registry_snapshot.get("observed_source")
                    if isinstance(registry_snapshot, dict)
                    else ""
                )
                or "auto"
            )
            registry_history_policy = (
                ENTITY_REGISTRY_HISTORY_POLICY_AUTHORITATIVE_REBUILD
                if rebuild
                else str(
                    registry_snapshot.get("history_policy")
                    if isinstance(registry_snapshot, dict)
                    else ""
                )
                or ENTITY_REGISTRY_HISTORY_POLICY_INCREMENTAL
            )
            registry_refresh = entity_registry_search_sync_current_noop(
                conn,
                aoa_root=aoa_root,
                registry_state=registry_state,
                observed_source=registry_observed_source,
                history_policy=registry_history_policy,
            )
            if registry_refresh is None:
                registry_refresh = refresh_search_entity_registry_documents(
                    conn,
                    aoa_root=aoa_root,
                    route_terms_db_path=write_db_path,
                    observed_source=registry_observed_source,
                    history_policy=registry_history_policy,
                )
            entity_registry_document_count = int_value(registry_refresh.get("target_count"))
            inserted_entity_registry_document_count = int_value(registry_refresh.get("inserted_count"))
            updated_entity_registry_document_count = int_value(registry_refresh.get("updated_count"))
            unchanged_entity_registry_document_count = int_value(registry_refresh.get("unchanged_count"))
            counts["entity_registry"] += entity_registry_document_count
            removed_entity_registry_document_count = int_value(registry_refresh.get("removed_count"))
            record_phase(
                "entity_registry_refresh",
                registry_started,
                document_count=entity_registry_document_count,
                inserted_count=inserted_entity_registry_document_count,
                updated_count=updated_entity_registry_document_count,
                unchanged_count=unchanged_entity_registry_document_count,
                removed_count=removed_entity_registry_document_count,
                skipped=bool(registry_refresh.get("skipped")),
                skip_reason=str(registry_refresh.get("skip_reason") or ""),
            )
        elif not include_entity_registry:
            record_phase("entity_registry_refresh", time.monotonic(), inserted_count=0, removed_count=0, skipped=True)
    except sqlite3.Error as exc:
        interrupted = "interrupted" in str(exc).lower()
        if interrupted and deadline is not None and time.monotonic() >= deadline:
            budget_exhausted = True
            try:
                conn.rollback()
            except sqlite3.Error:
                pass
            conn.close()
            if rebuild and temp_db_path is not None:
                cleanup_search_rebuild_temp(temp_db_path)
            return {
                "schema_version": SCHEMA_VERSION,
                "artifact_type": "search_index",
                "search_schema_version": SEARCH_SCHEMA_VERSION,
                "generated_at": now,
                "ok": False,
                "target": target,
                "since": since,
                "until": until,
                "limit": limit,
                "selected_count": len(records),
                "processed_count": committed_count,
                "remaining_count": max(0, len(records) - committed_count),
                "budget_seconds": budget_seconds,
                "budget_exhausted": True,
                "partial": True,
                "document_count": sum(counts.values()),
                "removed_document_count": removed_document_count,
                "removed_entity_registry_document_count": removed_entity_registry_document_count,
                "inserted_entity_registry_document_count": inserted_entity_registry_document_count,
                "updated_entity_registry_document_count": updated_entity_registry_document_count,
                "unchanged_entity_registry_document_count": unchanged_entity_registry_document_count,
                "max_raw_bytes": effective_max_raw_bytes,
                "requested_max_raw_bytes": max_raw_bytes,
                "raw_lexical_policy": raw_lexical_policy,
                "search_body_storage_mode": effective_body_storage_mode,
                "search_fts_storage_mode": effective_fts_storage_mode,
                "raw_text_query_support": raw_text_query_support,
                "store_raw_text": store_raw_text,
                "include_raw_event_text": include_raw_event_text,
                "requested_context_tail_omission_policy": requested_context_tail_omission_policy,
                "context_tail_omission_policy": effective_context_tail_omission_policy,
                "context_tail_omission_policy_resolution": policy_resolution,
                "context_tail_omission": {
                    "policy": effective_context_tail_omission_policy,
                    "counts": dict(sorted(context_tail_omission_counts.items())),
                    "omitted_document_count": int_value(context_tail_omission_counts.get("omitted_document_count")),
                    "omitted_route_ref_row_count": int_value(context_tail_omission_counts.get("omitted_route_ref_row_count")),
                    "session_samples": context_tail_omission_session_samples[:OPS_SLOW_SESSION_SAMPLE_LIMIT],
                    "authority_boundary": "raw transcripts, segment indexes, and monolith fallback remain authority",
                },
                "raw_text_status_counts": dict(sorted(raw_text_status_counts.items())),
                "raw_text_skipped_session_count": raw_text_status_counts.get("skipped_raw_too_large", 0),
                "search_route_posting_policy_mode": SEARCH_ROUTE_POSTING_POLICY_MODE,
                "search_aggregate_route_posting_doc_types": sorted(SEARCH_AGGREGATE_ROUTE_POSTING_DOC_TYPES),
                "search_aggregate_route_posting_default_layer_limit": SEARCH_AGGREGATE_ROUTE_POSTING_DEFAULT_LAYER_LIMIT,
                "phase_timings": phase_timings,
                "session_timings": session_timings,
                "slow_sessions": search_slow_session_rows(session_timings),
                "active_session": active_session_snapshot(),
                "remaining_sessions": remaining_session_samples(),
                "slow_session_warning_count": sum(1 for item in session_timings if item.get("warning")),
                "slow_session_threshold_ms": OPS_SEARCH_SESSION_WARNING_MS,
                "inline_optimize_policy": {
                    "rebuild_every": SEARCH_REBUILD_INLINE_OPTIMIZE_EVERY,
                    "incremental_every": SEARCH_INCREMENTAL_INLINE_OPTIMIZE_EVERY,
                },
                "inline_optimize_count": inline_optimize_count,
                "db_path": str(db_path),
                "build_db_path": str(write_db_path),
                "diagnostics": ["search_index_budget_exhausted"],
                "sessions": session_results[:committed_count],
            }
        conn.rollback()
        conn.close()
        if rebuild and temp_db_path is not None:
            cleanup_search_rebuild_temp(temp_db_path)
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "search_index",
            "search_schema_version": SEARCH_SCHEMA_VERSION,
            "generated_at": now,
            "ok": False,
            "target": target,
            "selected_count": len(records),
            "document_count": 0,
            "removed_document_count": removed_document_count,
            "removed_entity_registry_document_count": removed_entity_registry_document_count,
            "inserted_entity_registry_document_count": inserted_entity_registry_document_count,
            "updated_entity_registry_document_count": updated_entity_registry_document_count,
            "unchanged_entity_registry_document_count": unchanged_entity_registry_document_count,
            "max_raw_bytes": effective_max_raw_bytes,
            "requested_max_raw_bytes": max_raw_bytes,
            "raw_lexical_policy": raw_lexical_policy,
            "search_body_storage_mode": effective_body_storage_mode,
            "search_fts_storage_mode": effective_fts_storage_mode,
            "raw_text_query_support": raw_text_query_support,
            "store_raw_text": store_raw_text,
            "include_raw_event_text": include_raw_event_text,
            "requested_context_tail_omission_policy": requested_context_tail_omission_policy,
            "context_tail_omission_policy": effective_context_tail_omission_policy,
            "context_tail_omission_policy_resolution": policy_resolution,
            "context_tail_omission": {
                "policy": effective_context_tail_omission_policy,
                "counts": dict(sorted(context_tail_omission_counts.items())),
                "omitted_document_count": int_value(context_tail_omission_counts.get("omitted_document_count")),
                "omitted_route_ref_row_count": int_value(context_tail_omission_counts.get("omitted_route_ref_row_count")),
                "session_samples": context_tail_omission_session_samples[:OPS_SLOW_SESSION_SAMPLE_LIMIT],
                "authority_boundary": "raw transcripts, segment indexes, and monolith fallback remain authority",
            },
            "raw_text_status_counts": dict(sorted(raw_text_status_counts.items())),
            "raw_text_skipped_session_count": raw_text_status_counts.get("skipped_raw_too_large", 0),
            "search_route_posting_policy_mode": SEARCH_ROUTE_POSTING_POLICY_MODE,
            "search_aggregate_route_posting_doc_types": sorted(SEARCH_AGGREGATE_ROUTE_POSTING_DOC_TYPES),
            "search_aggregate_route_posting_default_layer_limit": SEARCH_AGGREGATE_ROUTE_POSTING_DEFAULT_LAYER_LIMIT,
            "phase_timings": phase_timings,
            "session_timings": session_timings,
            "slow_sessions": search_slow_session_rows(session_timings),
            "active_session": active_session_snapshot(),
            "remaining_sessions": remaining_session_samples(),
            "slow_session_warning_count": sum(1 for item in session_timings if item.get("warning")),
            "slow_session_threshold_ms": OPS_SEARCH_SESSION_WARNING_MS,
            "inline_optimize_policy": {
                "rebuild_every": SEARCH_REBUILD_INLINE_OPTIMIZE_EVERY,
                "incremental_every": SEARCH_INCREMENTAL_INLINE_OPTIMIZE_EVERY,
            },
            "inline_optimize_count": inline_optimize_count,
            "db_path": str(db_path),
            "build_db_path": str(write_db_path),
            "diagnostics": [f"sqlite_error:{exc}"],
            "sessions": session_results,
        }
    finally:
        try:
            conn.set_progress_handler(None, 0)
        except sqlite3.Error:
            pass
        conn.close()
    document_count = sum(counts.values())
    processed_count = committed_count
    completed_session_ids = projection_completed_session_ids(
        {"session_timings": session_timings}
    )
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "search_index",
        "search_schema_version": SEARCH_SCHEMA_VERSION,
        "search_body_storage_mode": effective_body_storage_mode if rebuild else f"{effective_body_storage_mode}_mixed",
        "search_fts_storage_mode": effective_fts_storage_mode,
        "raw_text_query_support": raw_text_query_support,
        "store_raw_text": store_raw_text,
        "include_raw_event_text": include_raw_event_text,
        "requested_context_tail_omission_policy": requested_context_tail_omission_policy,
        "context_tail_omission_policy": effective_context_tail_omission_policy,
        "context_tail_omission_policy_resolution": policy_resolution,
        "context_tail_omission": {
            "policy": effective_context_tail_omission_policy,
            "counts": dict(sorted(context_tail_omission_counts.items())),
            "omitted_document_count": int_value(context_tail_omission_counts.get("omitted_document_count")),
            "omitted_route_ref_row_count": int_value(context_tail_omission_counts.get("omitted_route_ref_row_count")),
            "session_samples": context_tail_omission_session_samples[:OPS_SLOW_SESSION_SAMPLE_LIMIT],
            "protected_boundary": "agent_event, task_episode, protected event types, and unrouted context-tail rows are kept",
            "authority_boundary": "raw transcripts, segment indexes, and monolith fallback remain authority",
            "truth_status": "generated_search_projection_policy_not_archive_truth",
        },
        "search_payload_storage_mode": SEARCH_PAYLOAD_STORAGE_MODE if rebuild else f"{SEARCH_PAYLOAD_STORAGE_MODE}_mixed",
        "search_document_storage_profile": storage_profile.get("name"),
        "search_index_profile": SEARCH_INDEX_PROFILE,
        "search_ref_path_storage_policy": storage_profile.get("ref_path_storage_policy"),
        "search_body_preview_chars": storage_profile.get("body_preview_chars"),
        "search_route_layers_preview_chars": storage_profile.get("route_layers_preview_chars"),
        "search_route_signals_preview_chars": storage_profile.get("route_signals_preview_chars"),
        "search_tags_preview_chars": storage_profile.get("tags_preview_chars"),
        "search_tags_storage_policy": storage_profile.get("tags_storage_policy"),
        "generated_at": now,
        "source_scope_complete": effective_source_scope_complete,
        "source_set_identity": published_source_set_identity,
        "previous_source_set_identity": (
            previous_source_set_identity
        ),
        "source_set_tombstone_count": len(source_set_tombstones),
        "source_set_tombstones": source_set_tombstones,
        "source_set_tombstone_truth_status": (
            "generated_projection_retirement_not_raw_deletion"
        ),
        "ok": bool(
            (document_count > 0 or authoritative_empty_rebuild)
            and not diagnostics
            and not (rebuild and budget_exhausted)
        ),
        "target": target,
        "since": since,
        "until": until,
        "limit": limit,
        "max_raw_bytes": effective_max_raw_bytes,
        "requested_max_raw_bytes": max_raw_bytes,
        "raw_lexical_policy": raw_lexical_policy,
        "raw_text_status_counts": dict(sorted(raw_text_status_counts.items())),
        "raw_text_skipped_session_count": raw_text_status_counts.get("skipped_raw_too_large", 0),
        "literal_postings": {
            "projection_version": SEARCH_EXACT_LITERAL_POSTINGS_VERSION,
            "posting_document_count": exact_literal_posting_document_count,
            "transition_posting_document_count": exact_literal_transition_posting_document_count,
            "session_status_counts": dict(sorted(exact_literal_session_status_counts.items())),
            "max_chars_per_output": SEARCH_EXACT_LITERAL_POSTINGS_MAX_CHARS,
            "max_chars_per_patch_transition_posting": SEARCH_EXACT_LITERAL_PATCH_TRANSITION_MAX_CHARS,
            "source_scope": "structured correlation and provider identifiers plus source-aware event text, streamed structured patch calls with bounded same-field transitions, and compact successful observations; file-read and large raw outputs excluded",
            "transition_source_admission": "raw_structured_patch_call_marker_independent_of_derived_segment_event_type",
            "storage_mode": "contentless_fts5_detail_full_plus_typed_patch_transition_postings",
            "deduplication": (
                "adjacent_source_lane_mirror_collapse_preserves_distinct_"
                "within_session_and_cross_session_provenance"
            ),
            "authority_boundary": "postings route to event/raw refs; raw transcript remains authority",
        },
        "episode_semantic_projection": {
            "projection_version": EPISODE_SEMANTIC_PROJECTION_VERSION,
            "task_episode_schema_version": TASK_EPISODE_SCHEMA_VERSION,
            "episode_document_count": episode_semantic_document_count,
            "session_status_counts": dict(sorted(episode_semantic_session_status_counts.items())),
            "storage_mode": "stored_bounded_fts5_plus_compressed_evidence_payload_v1",
            "source_scope": "source-aware bounded task-episode representations",
            "authority_boundary": "episode hits route to raw, segment, and session refs; raw transcript remains authority",
        },
        "search_route_posting_policy_mode": SEARCH_ROUTE_POSTING_POLICY_MODE,
        "search_aggregate_route_posting_doc_types": sorted(SEARCH_AGGREGATE_ROUTE_POSTING_DOC_TYPES),
        "search_aggregate_route_posting_default_layer_limit": SEARCH_AGGREGATE_ROUTE_POSTING_DEFAULT_LAYER_LIMIT,
        "phase_timings": phase_timings,
        "session_timings": session_timings,
        "slow_sessions": search_slow_session_rows(session_timings),
        "active_session": active_session_snapshot(),
        "remaining_sessions": remaining_session_samples() if budget_exhausted else [],
        "slow_session_warning_count": sum(1 for item in session_timings if item.get("warning")),
        "slow_session_threshold_ms": OPS_SEARCH_SESSION_WARNING_MS,
        "inline_optimize_policy": {
            "rebuild_every": SEARCH_REBUILD_INLINE_OPTIMIZE_EVERY,
            "incremental_every": SEARCH_INCREMENTAL_INLINE_OPTIMIZE_EVERY,
        },
        "inline_optimize_count": inline_optimize_count,
        "selected_count": len(records),
        "processed_count": processed_count,
        "completed_session_ids": completed_session_ids,
        "remaining_count": max(0, len(records) - processed_count),
        "budget_seconds": budget_seconds,
        "budget_exhausted": budget_exhausted,
        "partial": budget_exhausted,
        "document_count": document_count,
        "removed_document_count": removed_document_count,
        "removed_entity_registry_document_count": removed_entity_registry_document_count,
        "inserted_entity_registry_document_count": inserted_entity_registry_document_count,
        "updated_entity_registry_document_count": updated_entity_registry_document_count,
        "unchanged_entity_registry_document_count": unchanged_entity_registry_document_count,
        "session_document_count": counts.get("session", 0),
        "segment_document_count": counts.get("segment", 0),
        "event_document_count": counts.get("event", 0),
        "incident_document_count": counts.get("incident", 0),
        "task_episode_document_count": counts.get("task_episode", 0),
        "goal_lifecycle_document_count": counts.get("goal_lifecycle", 0),
        "entity_registry_document_count": counts.get("entity_registry", 0),
        "db_path": str(db_path),
        "build_db_path": str(write_db_path),
        "progress_telemetry": progress_telemetry.summary(),
        "diagnostics": diagnostics,
        "sessions": session_results,
    }
    producer_source_state = (
        session_memory_loaded_producer_source_state()
    )
    payload["producer_source_state"] = producer_source_state
    if not producer_source_state.get("stable"):
        payload["ok"] = False
        payload.setdefault("diagnostics", []).append(
            "producer_source_changed_during_search_build"
        )
    if rebuild and temp_db_path is not None:
        if payload["ok"]:
            cleanup_sqlite_sidecars(db_path)
            os.replace(temp_db_path, db_path)
            cleanup_search_rebuild_temp(temp_db_path)
            payload["replaced_db_path"] = str(db_path)
        else:
            cleanup_search_rebuild_temp(temp_db_path)
            payload["discarded_build_db_path"] = str(temp_db_path)
    if payload["ok"] and refresh_catalog:
        catalog_started = time.monotonic()
        catalog_refresh = build_search_catalog(aoa_root, write=True, selected_records=records)
        record_phase(
            "search_catalog_refresh",
            catalog_started,
            status=catalog_refresh.get("status"),
            session_count=int_value(catalog_refresh.get("session_count")),
            shard_count=int_value(catalog_refresh.get("shard_count")),
            catalog_state_basis=str(catalog_refresh.get("catalog_state_basis") or ""),
        )
        payload["search_catalog"] = search_catalog_summary(catalog_refresh)
        if not catalog_refresh.get("ok"):
            payload["ok"] = False
            payload.setdefault("diagnostics", []).append(f"search_catalog_refresh_failed:{catalog_refresh.get('status')}")
    outbox_completions: list[dict[str, Any]] = []
    if payload["ok"]:
        result_by_session_id = {
            str(item.get("session_id") or ""): item
            for item in session_results
            if isinstance(item, dict)
            and str(item.get("session_id") or "")
        }
        for record in records[:committed_count]:
            session_dir = session_dir_from_record(record)
            session_id = str(record.get("session_id") or "")
            result = result_by_session_id.get(session_id, {})
            episode_status = str(
                (
                    result.get("episode_semantic_projection")
                    if isinstance(
                        result.get("episode_semantic_projection"), dict
                    )
                    else {}
                ).get("status")
                or ""
            )
            completed_consumers = ["exact_and_lexical_search"]
            if episode_status in {
                "current",
                "no_task_episodes",
                "no_admitted_episode_text",
            }:
                completed_consumers.append("episode_semantic")
            completion = complete_projection_outbox_consumers_for_session(
                aoa_root=aoa_root,
                session_dir=session_dir,
                consumers=completed_consumers,
                completion_receipt={
                    "artifact_type": "search_consumer_transaction_receipt",
                    "db_path": str(db_path),
                    "db_size_bytes": (
                        db_path.stat().st_size if db_path.is_file() else 0
                    ),
                    "source_fingerprint": str(
                        result.get("source_fingerprint") or ""
                    ),
                    "lexical_generation_id": str(
                        generation_identities["lexical_search"].get(
                            "generation_id"
                        )
                        or ""
                    ),
                    "episode_semantic_generation_id": str(
                        generation_identities["episode_semantic"].get(
                            "generation_id"
                        )
                        or ""
                    ),
                    "episode_semantic_status": episode_status,
                    "indexed_at": now,
                },
            )
            if completion.get("completed_consumers"):
                outbox_completions.append(completion)
    payload["outbox_completions"] = outbox_completions
    if write_report:
        diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
        diagnostics_dir.mkdir(parents=True, exist_ok=True)
        stem = f"{compact_stamp()}__search-index"
        report_json = diagnostics_dir / f"{stem}.json"
        report_md = diagnostics_dir / f"{stem}.md"
        write_json(report_json, payload)
        write_markdown(report_md, search_report_markdown(payload))
        payload["report_json"] = str(report_json)
        payload["report_markdown"] = str(report_md)
    return payload


def episode_semantic_index_sessions(
    *,
    aoa_root: Path,
    target: str = "all",
    since: str | None = None,
    until: str | None = None,
    limit: int | None = None,
    budget_seconds: float | None = None,
    progress_every: int = 0,
    write_report: bool = False,
    dirty_only: bool = False,
    max_cost_class: str = "auto",
    selected_records: list[dict[str, Any]] | None = None,
    query_demand_counts: dict[str, int] | None = None,
    priority_session_ids: list[str] | None = None,
) -> dict[str, Any]:
    now = utc_now()
    episode_generation_identity = (
        session_memory_expected_generation_identities(aoa_root)[
            "episode_semantic"
        ]
    )
    started = time.monotonic()
    deadline = started + budget_seconds if budget_seconds is not None and budget_seconds > 0 else None
    try:
        records = list(selected_records) if selected_records is not None else (
            [resolve_session_record(aoa_root, target)]
            if target and target != "all"
            else chronological_session_records(
                aoa_root,
                since=since,
                until=until,
                limit=None if dirty_only else limit,
            )
        )
    except ValueError as exc:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "episode_semantic_index",
            "generated_at": now,
            "ok": False,
            "target": target,
            "selected_count": 0,
            "processed_count": 0,
            "diagnostics": [str(exc)],
        }
    if not records:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "episode_semantic_index",
            "generated_at": now,
            "ok": False,
            "target": target,
            "selected_count": 0,
            "processed_count": 0,
            "diagnostics": ["no sessions selected"],
        }
    queue_seed: dict[str, Any] = {}
    scheduled_queue_rows: list[dict[str, Any]] = []
    deferred_resource_count = 0
    dirty_state: dict[str, Any] = {}
    scope_ids: set[str] = set()
    initial_dirty_ids: set[str] = set()
    priority_order = list(
        dict.fromkeys(str(item) for item in (priority_session_ids or []) if item)
    )
    scheduled_priority_ids: list[str] = []
    deferred_priority_ids: list[str] = []
    if dirty_only:
        bootstrap_conn = init_search_db(search_db_path(aoa_root), rebuild=False, create_indexes=False)
        bootstrap_conn.close()
        dirty_state = episode_semantic_projection_state(aoa_root, records=records)
        initial_dirty_ids = {
            str(item)
            for item in dirty_state.get("dirty_session_ids", [])
            if item
        }
        queue_seed = episode_semantic_queue_seed(
            aoa_root,
            projection_state=dirty_state,
            now=now,
            query_demand_counts=query_demand_counts,
        )
        normalized_max_cost = str(max_cost_class or "auto")
        if normalized_max_cost == "auto":
            if budget_seconds is not None and budget_seconds <= 75:
                allow_cost_classes = {"light"}
            elif budget_seconds is not None and budget_seconds <= 240:
                allow_cost_classes = {"light", "warm"}
            else:
                allow_cost_classes = {"light", "warm", "heavy"}
        elif normalized_max_cost == "light":
            allow_cost_classes = {"light"}
        elif normalized_max_cost == "warm":
            allow_cost_classes = {"light", "warm"}
        elif normalized_max_cost == "heavy":
            allow_cost_classes = {"light", "warm", "heavy"}
        else:
            return {
                "schema_version": SCHEMA_VERSION,
                "artifact_type": "episode_semantic_index",
                "generated_at": now,
                "ok": False,
                "target": target,
                "selected_count": 0,
                "processed_count": 0,
                "diagnostics": [f"unknown max cost class: {max_cost_class}"],
            }
        scope_ids = {str(record.get("session_id") or "") for record in records if record.get("session_id")}
        scheduled_queue_rows = episode_semantic_queue_schedule(
            aoa_root,
            limit=limit,
            allow_cost_classes=allow_cost_classes,
            now=now,
            session_ids=scope_ids,
            priority_session_ids=priority_order,
        )
        scheduled_ids = {str(item.get("session_id") or "") for item in scheduled_queue_rows}
        scheduled_priority_ids = [
            session_id
            for session_id in priority_order
            if session_id in scheduled_ids
        ]
        deferred_priority_ids = [
            session_id
            for session_id in priority_order
            if session_id in initial_dirty_ids and session_id not in scheduled_ids
        ]
        scheduled_query_demand_ids = [
            str(item.get("session_id") or "")
            for item in scheduled_queue_rows
            if int_value(item.get("demand_count")) > 0
        ]
        deferred_resource_count = sum(
            1
            for item in dirty_state.get("dirty_sessions", [])
            if isinstance(item, dict)
            and str(item.get("session_id") or "") in scope_ids
            and str(item.get("cost_class") or "light") not in allow_cost_classes
        )
        record_by_id = {str(record.get("session_id") or ""): record for record in records}
        records = [record_by_id[session_id] for session_id in scheduled_ids if session_id in record_by_id]
        records.sort(
            key=lambda record: next(
                (
                    index
                    for index, item in enumerate(scheduled_queue_rows)
                    if str(item.get("session_id") or "") == str(record.get("session_id") or "")
                ),
                len(scheduled_queue_rows),
            )
        )
        queue_conn = init_search_db(search_db_path(aoa_root), rebuild=False, create_indexes=False)
        try:
            if deferred_resource_count and scope_ids:
                disallowed = sorted({"light", "warm", "heavy"} - allow_cost_classes)
                placeholders = ",".join("?" for _ in disallowed)
                if placeholders:
                    queue_conn.execute(
                        f"UPDATE episode_semantic_queue SET status = 'deferred_resource' "
                        f"WHERE session_id IN ({','.join('?' for _ in scope_ids)}) AND cost_class IN ({placeholders})",
                        [*sorted(scope_ids), *disallowed],
                    )
            queue_conn.commit()
        finally:
            queue_conn.close()
        if not records:
            queue_remainder = episode_semantic_queue_summary(aoa_root, session_ids=scope_ids)
            return {
                "schema_version": SCHEMA_VERSION,
                "artifact_type": "episode_semantic_index",
                "generated_at": now,
                "ok": True,
                "target": target,
                "dirty_only": True,
                "selected_count": 0,
                "processed_count": 0,
                "successful_count": 0,
                "remaining_count": len(initial_dirty_ids),
                "budget_seconds": budget_seconds,
                "budget_exhausted": False,
                "queue": {
                    **queue_seed,
                    "query_demand_counts": dict(query_demand_counts or {}),
                    "scheduled_query_demand_session_ids": scheduled_query_demand_ids,
                    "priority_requested_session_ids": priority_order,
                    "selected_priority_session_ids": scheduled_priority_ids,
                    "deferred_priority_session_ids": deferred_priority_ids,
                    "deferred_resource_count": deferred_resource_count,
                    "final": queue_remainder,
                },
                "diagnostics": [],
            }
    db_path = search_db_path(aoa_root)
    conn = init_search_db(db_path, rebuild=False, create_indexes=False)
    results: list[dict[str, Any]] = []
    diagnostics: list[str] = []
    removed_episode_count = 0
    indexed_episode_count = 0
    budget_exhausted = False
    completed_dirty_ids: set[str] = set()
    progress_telemetry = BestEffortJsonProgressEmitter(
        enabled=progress_every > 0
    )
    try:
        for record_index, record in enumerate(records, start=1):
            if deadline is not None and record_index > 1 and time.monotonic() >= deadline:
                budget_exhausted = True
                break
            record_started = time.monotonic()
            session_dir = session_dir_from_record(record)
            projection_state = episode_semantic_source_fingerprint(record)
            session_id = str(projection_state.get("session_id") or record.get("session_id") or "")
            if dirty_only and session_id and sqlite_table_exists(conn, "episode_semantic_queue"):
                conn.execute(
                    "UPDATE episode_semantic_queue SET status = 'running', last_attempt_at = ?, "
                    "attempt_count = attempt_count + 1 WHERE session_id = ?",
                    (now, session_id),
                )
                conn.commit()
            conn.execute("BEGIN")
            try:
                removed = delete_episode_semantic_for_session(
                    conn,
                    session_label=str(projection_state.get("session_label") or session_dir.name),
                    session_id=str(projection_state.get("session_id") or record.get("session_id") or ""),
                )
                projection = insert_episode_semantic_projection_for_session(
                    conn,
                    session_dir=session_dir,
                    projection_state=projection_state,
                    indexed_at=now,
                    generation_identity=episode_generation_identity,
                )
                conn.commit()
            except (OSError, ValueError, sqlite3.Error) as exc:
                conn.rollback()
                diagnostic = f"episode_semantic_index_session_failed:{projection_state.get('session_id') or session_dir.name}:{exc}"
                diagnostics.append(diagnostic)
                results.append(
                    {
                        "session_id": str(projection_state.get("session_id") or ""),
                        "session_label": str(projection_state.get("session_label") or session_dir.name),
                        "status": "failed",
                        "elapsed_ms": int((time.monotonic() - record_started) * 1000),
                        "diagnostics": [diagnostic],
                    }
                )
                attempt_count = 1
                if sqlite_table_exists(conn, "episode_semantic_queue") and session_id:
                    attempt_row = conn.execute(
                        "SELECT attempt_count FROM episode_semantic_queue WHERE session_id = ?",
                        (session_id,),
                    ).fetchone()
                    attempt_count = max(1, int_value(attempt_row["attempt_count"]) if attempt_row else 1)
                retry_delay_seconds = min(3600, 60 * (2 ** min(5, max(0, attempt_count - 1))))
                retry_after = (datetime.now(timezone.utc) + timedelta(seconds=retry_delay_seconds)).strftime(
                    "%Y-%m-%dT%H:%M:%SZ"
                )
                if sqlite_table_exists(conn, "episode_semantic_queue") and session_id:
                    if attempt_count >= EPISODE_SEMANTIC_QUEUE_MAX_ATTEMPTS:
                        conn.execute(
                            "UPDATE episode_semantic_queue SET status = 'blocked_retry_exhausted', "
                            "retry_after = '', last_error = ? WHERE session_id = ?",
                            (short_text(diagnostic, max_chars=900), session_id),
                        )
                    else:
                        conn.execute(
                            "UPDATE episode_semantic_queue SET status = 'failed_retryable', retry_after = ?, last_error = ? "
                            "WHERE session_id = ?",
                            (retry_after, short_text(diagnostic, max_chars=900), session_id),
                        )
                    conn.commit()
                continue
            removed_episode_count += removed
            indexed_count = int_value(projection.get("episode_count"))
            indexed_episode_count += indexed_count
            if sqlite_table_exists(conn, "episode_semantic_queue") and session_id:
                if str(projection.get("status") or "") in {"current", "no_task_episodes", "no_admitted_episode_text"}:
                    conn.execute("DELETE FROM episode_semantic_queue WHERE session_id = ?", (session_id,))
                    completed_dirty_ids.add(session_id)
                else:
                    conn.execute(
                        "UPDATE episode_semantic_queue SET status = 'blocked', last_error = ? WHERE session_id = ?",
                        (str(projection.get("status") or "unknown"), session_id),
                    )
                conn.commit()
            results.append(
                {
                    "session_id": str(projection_state.get("session_id") or ""),
                    "session_label": str(projection_state.get("session_label") or session_dir.name),
                    "status": str(projection.get("status") or "unknown"),
                    "source_episode_count": int_value(projection.get("source_episode_count")),
                    "episode_count": indexed_count,
                    "removed_episode_count": removed,
                    "source_task_episode_schema_version": int_value(
                        projection.get("source_task_episode_schema_version")
                    ),
                    "source_generation_compatible": bool(
                        projection.get(
                            "source_generation_compatible"
                        )
                    ),
                    "source_generation_reasons": (
                        projection.get(
                            "source_generation_reasons",
                            [],
                        )
                    ),
                    "source_recovery_route": projection.get(
                        "source_recovery_route",
                        [],
                    ),
                    "normalized_legacy_task_episode_schema": bool(
                        projection.get("normalized_legacy_task_episode_schema")
                    ),
                    "normalization_mode": str(projection.get("normalization_mode") or ""),
                    "route_signal_classifier_version": int_value(
                        projection.get("route_signal_classifier_version")
                    ),
                    "freshness": projection.get("freshness", {}),
                    "elapsed_ms": int((time.monotonic() - record_started) * 1000),
                }
            )
            if progress_every > 0 and record_index % progress_every == 0:
                progress_telemetry.emit(
                    {
                        "event": "episode_semantic_index_progress",
                        "processed": len(results),
                        "selected_count": len(records),
                        "elapsed_ms": int(
                            (time.monotonic() - started) * 1000
                        ),
                    }
                )
        indexed_session_count = int_value(conn.execute("SELECT COUNT(*) FROM session_index_state").fetchone()[0])
        covered_session_count = int_value(
            conn.execute(
                "SELECT COUNT(*) FROM episode_semantic_session_state "
                "WHERE projection_version = ? AND route_signal_classifier_version = ? "
                "AND generation_id = ? "
                "AND status IN ('current', 'no_task_episodes', 'no_admitted_episode_text')",
                (
                    EPISODE_SEMANTIC_PROJECTION_VERSION,
                    ROUTE_SIGNAL_CLASSIFIER_VERSION,
                    str(episode_generation_identity["generation_id"]),
                ),
            ).fetchone()[0]
        )
        total_episode_document_count = int_value(
            conn.execute(
                "SELECT COUNT(*) FROM episode_semantic_meta AS meta "
                "JOIN episode_semantic_session_state AS state ON state.session_id = meta.session_id "
                "WHERE meta.projection_version = ? AND state.projection_version = ? "
                "AND state.route_signal_classifier_version = ? "
                "AND meta.generation_id = ? "
                "AND state.generation_id = ? "
                "AND state.status IN ('current', 'no_task_episodes', 'no_admitted_episode_text')",
                (
                    EPISODE_SEMANTIC_PROJECTION_VERSION,
                    EPISODE_SEMANTIC_PROJECTION_VERSION,
                    ROUTE_SIGNAL_CLASSIFIER_VERSION,
                    str(episode_generation_identity["generation_id"]),
                    str(episode_generation_identity["generation_id"]),
                ),
            ).fetchone()[0]
        )
    finally:
        conn.close()
    processed_count = len(results)
    unsuccessful_statuses = {
        "failed",
        "schema_missing",
        "task_episode_schema_mismatch",
        "source_generation_incompatible_requires_raw_reindex",
        "invalid_episode_evidence_refs",
    }
    successful_count = sum(
        1
        for item in results
        if item.get("status") not in unsuccessful_statuses
    )
    completed_session_ids = projection_completed_session_ids({"sessions": results})
    remaining_dirty_count = max(0, len(initial_dirty_ids - completed_dirty_ids)) if dirty_only else max(0, len(records) - processed_count)
    queue_remainder = episode_semantic_queue_summary(aoa_root, session_ids=scope_ids) if dirty_only else {}
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "episode_semantic_index",
        "generated_at": now,
        "ok": successful_count == processed_count and processed_count > 0 and not diagnostics and not budget_exhausted,
        "target": target,
        "dirty_only": dirty_only,
        "since": since,
        "until": until,
        "limit": limit,
        "projection_version": EPISODE_SEMANTIC_PROJECTION_VERSION,
        "route_signal_classifier_version": ROUTE_SIGNAL_CLASSIFIER_VERSION,
        "task_episode_schema_version": TASK_EPISODE_SCHEMA_VERSION,
        "selected_count": len(records),
        "processed_count": processed_count,
        "successful_count": successful_count,
        "completed_session_ids": completed_session_ids,
        "remaining_count": remaining_dirty_count,
        "budget_seconds": budget_seconds,
        "budget_exhausted": budget_exhausted,
        "indexed_episode_count": indexed_episode_count,
        "removed_episode_count": removed_episode_count,
        "queue": {
            **queue_seed,
            "scheduled_count": len(scheduled_queue_rows),
            "query_demand_counts": dict(query_demand_counts or {}),
            "scheduled_query_demand_session_ids": [
                str(item.get("session_id") or "")
                for item in scheduled_queue_rows
                if int_value(item.get("demand_count")) > 0
            ],
            "priority_requested_session_ids": priority_order,
            "selected_priority_session_ids": scheduled_priority_ids,
            "deferred_priority_session_ids": deferred_priority_ids,
            "deferred_resource_count": deferred_resource_count,
            "final": queue_remainder,
        },
        "coverage": {
            "status": "current" if indexed_session_count > 0 and covered_session_count >= indexed_session_count else (
                "partial" if covered_session_count else "empty"
            ),
            "covered_session_count": covered_session_count,
            "indexed_session_count": indexed_session_count,
            "episode_document_count": total_episode_document_count,
        },
        "storage_mode": "stored_bounded_fts5_plus_compressed_evidence_payload_v1",
        "source_scope": "source-aware task episodes plus bounded typed episode-ref expansion",
        "authority_boundary": "generated episode navigation; raw transcript remains authority",
        "elapsed_ms": int((time.monotonic() - started) * 1000),
        "db_path": str(db_path),
        "progress_telemetry": progress_telemetry.summary(),
        "diagnostics": diagnostics,
        "sessions": results,
    }
    if write_report:
        diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
        diagnostics_dir.mkdir(parents=True, exist_ok=True)
        stem = f"{compact_stamp()}__episode-semantic-index"
        report_json = diagnostics_dir / f"{stem}.json"
        write_json(report_json, payload)
        payload["report_json"] = str(report_json)
    return payload


def episode_dense_repair_cost_class(episode_count: int) -> str:
    count = max(0, int_value(episode_count))
    if count <= 16:
        return "light"
    if count <= 64:
        return "warm"
    return "heavy"


def episode_dense_repair_selection(
    rows: list[Any],
    *,
    limit: int | None,
    priority_session_ids: list[str] | None = None,
) -> tuple[list[Any], dict[str, Any]]:
    candidates = list(rows)
    priority_order = list(
        dict.fromkeys(str(item) for item in (priority_session_ids or []) if item)
    )
    priority_rank = {
        session_id: index for index, session_id in enumerate(priority_order)
    }
    priority_candidates = sorted(
        (
            row
            for row in candidates
            if str(row["session_id"] or "") in priority_rank
        ),
        key=lambda row: priority_rank[str(row["session_id"] or "")],
    )
    normal_candidates = [
        row
        for row in candidates
        if str(row["session_id"] or "") not in priority_rank
    ]
    cost_counts = Counter(
        episode_dense_repair_cost_class(int_value(row["episode_count"]))
        for row in candidates
    )
    recent_order = sorted(
        normal_candidates,
        key=lambda row: (
            str(row["session_date"] or ""),
            str(row["indexed_at"] or ""),
            str(row["session_id"] or ""),
        ),
        reverse=True,
    )
    cost_rank = {"light": 0, "warm": 1, "heavy": 2}
    ordered = sorted(
        recent_order,
        key=lambda row: cost_rank[episode_dense_repair_cost_class(int_value(row["episode_count"]))],
    )
    requested_limit = len(candidates) if limit is None else max(0, int_value(limit))
    selected_priority = priority_candidates[:requested_limit]
    normal_limit = max(0, requested_limit - len(selected_priority))
    selected_normal = ordered[:normal_limit]
    oldest_fairness_reserved = False
    oldest_fairness_session_id = ""
    if normal_limit >= 2 and len(ordered) > normal_limit:
        oldest = min(
            ordered,
            key=lambda row: (
                str(row["session_date"] or str(row["indexed_at"] or "")[:10] or "9999-12-31"),
                str(row["indexed_at"] or ""),
                str(row["session_id"] or ""),
            ),
        )
        if oldest not in selected_normal:
            selected_normal[-1] = oldest
            oldest_fairness_reserved = True
            oldest_fairness_session_id = str(oldest["session_id"] or "")
    selected = [*selected_priority, *selected_normal]
    selected_priority_ids = [str(row["session_id"] or "") for row in selected_priority]
    deferred_priority_ids = [
        str(row["session_id"] or "")
        for row in priority_candidates[len(selected_priority) :]
    ]
    selected_cost_counts = Counter(
        episode_dense_repair_cost_class(int_value(row["episode_count"]))
        for row in selected
    )
    return selected, {
        "policy": (
            "same_cycle_dependency_then_cost_recent_fairness_v2"
            if priority_order
            else "cost_class_then_recent_with_oldest_fairness_v1"
        ),
        "candidate_count": len(candidates),
        "requested_limit": limit,
        "selected_count": len(selected),
        "priority_requested_session_ids": priority_order,
        "priority_candidate_count": len(priority_candidates),
        "selected_priority_session_ids": selected_priority_ids,
        "deferred_priority_session_ids": deferred_priority_ids,
        "candidate_cost_class_counts": dict(sorted(cost_counts.items())),
        "selected_cost_class_counts": dict(sorted(selected_cost_counts.items())),
        "oldest_fairness_reserved": oldest_fairness_reserved,
        "oldest_fairness_session_id": oldest_fairness_session_id,
        "selected_session_ids": [str(row["session_id"] or "") for row in selected],
    }


def episode_dense_index_sessions(
    *,
    aoa_root: Path,
    target: str = "all",
    since: str | None = None,
    until: str | None = None,
    limit: int | None = None,
    budget_seconds: float | None = None,
    dirty_only: bool = False,
    write_report: bool = False,
    selected_records: list[dict[str, Any]] | None = None,
    priority_session_ids: list[str] | None = None,
) -> dict[str, Any]:
    now = utc_now()
    started = time.monotonic()
    deadline = started + budget_seconds if budget_seconds is not None and budget_seconds > 0 else None
    db_path = search_db_path(aoa_root)
    conn = init_search_db(db_path, rebuild=False, create_indexes=False)
    provider = episode_dense_provider(aoa_root)
    expected_generations = session_memory_expected_generation_identities(
        aoa_root
    )
    episode_generation_id = str(
        expected_generations["episode_semantic"]["generation_id"]
    )
    dense_generation_identity = expected_generations["episode_dense"]
    dense_generation_id, dense_generation_identity_json = (
        projection_generation_storage(dense_generation_identity)
    )
    diagnostics: list[str] = []
    results: list[dict[str, Any]] = []
    try:
        source_rows = conn.execute(
            """
            SELECT state.session_id, state.session_label, state.episode_count,
                   state.status, state.indexed_at,
                   COALESCE(MAX(meta.session_date), '') AS session_date
            FROM episode_semantic_session_state AS state
            LEFT JOIN episode_semantic_meta AS meta ON meta.session_id = state.session_id
            WHERE state.projection_version = ?
              AND state.route_signal_classifier_version = ?
              AND state.generation_id = ?
              AND state.status IN ('current', 'no_task_episodes', 'no_admitted_episode_text')
            GROUP BY state.session_id, state.session_label, state.episode_count,
                     state.status, state.indexed_at
            ORDER BY session_date, state.session_id
            """,
            (
                EPISODE_SEMANTIC_PROJECTION_VERSION,
                ROUTE_SIGNAL_CLASSIFIER_VERSION,
                episode_generation_id,
            ),
        ).fetchall()
        target_session_id = ""
        if target and target != "all":
            try:
                record = resolve_session_record(aoa_root, target)
                target_session_id = str(record.get("session_id") or "")
            except ValueError:
                target_session_id = str(target)
        selected_session_ids = (
            {
                str(record.get("session_id") or "")
                for record in selected_records
                if isinstance(record, dict) and str(record.get("session_id") or "")
            }
            if selected_records is not None
            else None
        )
        selected = []
        for row in source_rows:
            session_id = str(row["session_id"] or "")
            session_date = str(row["session_date"] or "")
            if selected_session_ids is not None and session_id not in selected_session_ids:
                continue
            if selected_records is None:
                if target_session_id and session_id != target_session_id:
                    continue
                if since and session_date and session_date < parse_date_arg(since):
                    continue
                if until and session_date and session_date > parse_date_arg(until):
                    continue
            selected.append(row)
        dense_state = episode_dense_projection_state(aoa_root, records=selected_records)
        dirty_ids = set(str(item) for item in dense_state.get("dirty_session_ids", []) if item)
        selection = {
            "policy": "chronological_v1",
            "candidate_count": len(selected),
            "requested_limit": limit,
            "selected_count": len(selected),
            "priority_requested_session_ids": list(
                dict.fromkeys(str(item) for item in (priority_session_ids or []) if item)
            ),
            "priority_candidate_count": 0,
            "selected_priority_session_ids": [],
            "deferred_priority_session_ids": [],
            "oldest_fairness_reserved": False,
            "oldest_fairness_session_id": "",
            "selected_session_ids": [str(row["session_id"] or "") for row in selected],
        }
        if dirty_only:
            selected = [row for row in selected if str(row["session_id"] or "") in dirty_ids]
            selected, selection = episode_dense_repair_selection(
                selected,
                limit=limit,
                priority_session_ids=priority_session_ids,
            )
        elif limit is not None:
            selected = selected[: max(0, int_value(limit))]
            selection["selected_count"] = len(selected)
            selection["selected_session_ids"] = [str(row["session_id"] or "") for row in selected]
        selected_count = len(selected)
        if not selected:
            generation_publish = (
                publish_search_projection_generation_identity(
                    aoa_root=aoa_root,
                    projection="episode_dense",
                    identity=dense_generation_identity,
                    coverage_current=bool(
                        dense_state.get("status") == "current"
                        and not dense_state.get("projection_dirty")
                        and int_value(
                            dense_state.get("current_session_count")
                        )
                        == int_value(
                            dense_state.get("source_session_count")
                        )
                    ),
                )
            )
            return {
                "schema_version": SCHEMA_VERSION,
                "artifact_type": "episode_dense_index",
                "generated_at": now,
                "ok": True,
                "status": "no_work",
                "target": target,
                "dirty_only": dirty_only,
                "selected_count": 0,
                "processed_count": 0,
                "successful_count": 0,
                "completed_session_ids": [],
                "selection": selection,
                "coverage": dense_state,
                "provider": {**provider, "embedding_api_url": provider.get("embedding_api_url")},
                "generation_publish": generation_publish,
                "elapsed_ms": int((time.monotonic() - started) * 1000),
                "diagnostics": [],
            }
        provider_preflight = episode_dense_provider_preflight(provider)
        if not provider_preflight.get("ok"):
            provider_unavailable = provider_preflight.get("status") == "provider_unavailable"
            diagnostics = [
                (
                    "episode_dense_provider_unavailable:"
                    f"{provider_preflight.get('provider_status') or 'unknown'}"
                )
                if provider_unavailable
                else (
                    "episode_dense_provider_preflight_failed:"
                    f"{provider_preflight.get('status') or 'unknown'}"
                )
            ]
            diagnostics.extend(
                str(item)
                for item in provider_preflight.get("diagnostics", [])
                if item
            )
            payload = {
                "schema_version": SCHEMA_VERSION,
                "artifact_type": "episode_dense_index",
                "generated_at": now,
                "ok": False,
                "status": (
                    "deferred_provider_unavailable"
                    if provider_unavailable
                    else "failed_provider_preflight"
                ),
                "target": target,
                "dirty_only": dirty_only,
                "since": since,
                "until": until,
                "limit": limit,
                "budget_seconds": budget_seconds,
                "budget_exhausted": False,
                "selected_count": selected_count,
                "processed_count": 0,
                "successful_count": 0,
                "deferred_count": selected_count if provider_unavailable else 0,
                "completed_session_ids": [],
                "selection": selection,
                "projection_version": EPISODE_DENSE_PROJECTION_VERSION,
                "document_version": EPISODE_DENSE_DOCUMENT_VERSION,
                "source_episode_projection_version": EPISODE_SEMANTIC_PROJECTION_VERSION,
                "provider": provider,
                "provider_preflight": provider_preflight,
                "coverage": dense_state,
                "storage_mode": (
                    "normalized_float32_exact_cosine_"
                    "episode_and_representation_sidecars_v2"
                ),
                "index_choice": (
                    "exact vector scan is lossless and bounded at the current episode cardinality; "
                    "ANN is deferred until measured scale requires it"
                ),
                "authority_boundary": (
                    "dense scores navigate generated episode representations; "
                    "only resolved raw transcript refs remain authority"
                ),
                "elapsed_ms": int((time.monotonic() - started) * 1000),
                "db_path": str(db_path),
                "diagnostics": diagnostics,
                "sessions": [],
            }
            if write_report:
                diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
                diagnostics_dir.mkdir(parents=True, exist_ok=True)
                stem = f"{compact_stamp()}__episode-dense-index"
                report_json = diagnostics_dir / f"{stem}.json"
                write_json(report_json, payload)
                payload["report_json"] = str(report_json)
            return payload
        for selected_index, source in enumerate(selected, start=1):
            if deadline is not None and selected_index > 1 and time.monotonic() >= deadline:
                diagnostics.append("episode_dense_index_budget_exhausted")
                break
            session_started = time.monotonic()
            session_id = str(source["session_id"] or "")
            episode_rows = conn.execute(
                """
                SELECT meta.doc_id, meta.episode_id, payloads.payload_zlib
                FROM episode_semantic_meta AS meta
                JOIN episode_semantic_payloads AS payloads ON payloads.doc_rowid = meta.doc_rowid
                WHERE meta.session_id = ? AND meta.projection_version = ?
                  AND meta.generation_id = ?
                ORDER BY meta.doc_rowid
                """,
                (
                    session_id,
                    EPISODE_SEMANTIC_PROJECTION_VERSION,
                    episode_generation_id,
                ),
            ).fetchall()
            expected_count = int_value(source["episode_count"])
            if len(episode_rows) != expected_count:
                diagnostic = f"episode_dense_source_count_mismatch:{session_id}:{len(episode_rows)}/{expected_count}"
                diagnostics.append(diagnostic)
                results.append(
                    {
                        "session_id": session_id,
                        "status": "source_count_mismatch",
                        "episode_document_count": len(episode_rows),
                        "expected_episode_document_count": expected_count,
                        "elapsed_ms": int((time.monotonic() - session_started) * 1000),
                        "diagnostics": [diagnostic],
                    }
                )
                continue
            documents: list[str] = []
            document_hashes: list[str] = []
            representation_documents: list[dict[str, Any]] = []
            payload_ok = True
            for episode_row in episode_rows:
                episode = episode_semantic_payload_from_blob(episode_row["payload_zlib"])
                document = episode_dense_document(episode) if episode else ""
                if not document.strip() or document == "passage: ":
                    payload_ok = False
                    break
                documents.append(document)
                document_hashes.append(hashlib.sha256(document.encode("utf-8")).hexdigest())
                representation_documents.extend(
                    episode_dense_representation_documents(
                        episode,
                        doc_id=str(episode_row["doc_id"] or ""),
                        session_id=session_id,
                        episode_id=str(
                            episode_row["episode_id"] or ""
                        ),
                    )
                )
            if not payload_ok:
                diagnostic = f"episode_dense_payload_unreadable:{session_id}"
                diagnostics.append(diagnostic)
                results.append(
                    {
                        "session_id": session_id,
                        "status": "payload_unreadable",
                        "episode_document_count": len(episode_rows),
                        "elapsed_ms": int((time.monotonic() - session_started) * 1000),
                        "diagnostics": [diagnostic],
                    }
                )
                continue
            embedding = episode_dense_embed_texts(
                url=str(provider.get("embedding_api_url") or ""),
                texts=[
                    *documents,
                    *[
                        str(item.get("document") or "")
                        for item in representation_documents
                    ],
                ],
                timeout=EPISODE_DENSE_INDEX_TIMEOUT_SECONDS,
            ) if documents or representation_documents else {
                "ok": True,
                "status": "no_task_episodes",
                "vectors": [],
                "model": EPISODE_DENSE_DEFAULT_MODEL,
                "dimension": EPISODE_DENSE_DEFAULT_DIMENSION,
                "prompt_tokens": 0,
                "elapsed_ms": 0,
                "diagnostics": [],
            }
            model = str(embedding.get("model") or EPISODE_DENSE_DEFAULT_MODEL)
            dimension = int_value(embedding.get("dimension"), EPISODE_DENSE_DEFAULT_DIMENSION)
            vectors = embedding.get("vectors") if isinstance(embedding.get("vectors"), list) else []
            expected_vector_count = (
                len(episode_rows)
                + len(representation_documents)
            )
            if (
                not embedding.get("ok")
                or len(vectors) != expected_vector_count
                or model != EPISODE_DENSE_DEFAULT_MODEL
                or (episode_rows and dimension != EPISODE_DENSE_DEFAULT_DIMENSION)
            ):
                diagnostic = (
                    f"episode_dense_embedding_failed:{session_id}:status={embedding.get('status')}:"
                    f"model={model}:dimension={dimension}:"
                    f"vectors={len(vectors)}/{expected_vector_count}"
                )
                diagnostics.append(diagnostic)
                results.append(
                    {
                        "session_id": session_id,
                        "status": "embedding_failed",
                        "episode_document_count": len(episode_rows),
                        "embedding": {
                            key: embedding.get(key)
                            for key in ("status", "model", "dimension", "prompt_tokens", "elapsed_ms", "diagnostics")
                        },
                        "elapsed_ms": int((time.monotonic() - session_started) * 1000),
                        "diagnostics": [diagnostic],
                    }
                )
                continue
            episode_vectors = vectors[: len(episode_rows)]
            representation_vectors = vectors[len(episode_rows) :]
            conn.execute("BEGIN")
            try:
                conn.execute("DELETE FROM episode_dense_vectors WHERE session_id = ?", (session_id,))
                conn.execute(
                    "DELETE FROM episode_dense_representation_vectors "
                    "WHERE session_id = ?",
                    (session_id,),
                )
                for episode_row, document_hash, vector in zip(
                    episode_rows,
                    document_hashes,
                    episode_vectors,
                    strict=True,
                ):
                    conn.execute(
                        """
                        INSERT INTO episode_dense_vectors (
                            doc_id, session_id, episode_id,
                            source_episode_projection_version,
                            source_route_signal_classifier_version, dense_projection_version,
                            dense_document_version, model, dimension, document_sha256,
                            vector_f32, indexed_at, generation_id
                        )
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                        """,
                        (
                            str(episode_row["doc_id"] or ""),
                            session_id,
                            str(episode_row["episode_id"] or ""),
                            EPISODE_SEMANTIC_PROJECTION_VERSION,
                            ROUTE_SIGNAL_CLASSIFIER_VERSION,
                            EPISODE_DENSE_PROJECTION_VERSION,
                            EPISODE_DENSE_DOCUMENT_VERSION,
                            model,
                            dimension,
                            document_hash,
                            sqlite3.Binary(episode_dense_vector_blob(vector)),
                            now,
                            dense_generation_id,
                        ),
                    )
                for representation, vector in zip(
                    representation_documents,
                    representation_vectors,
                    strict=True,
                ):
                    conn.execute(
                        """
                        INSERT INTO episode_dense_representation_vectors (
                            representation_id, doc_id, session_id,
                            episode_id, role, raw_ref, segment_ref,
                            session_ref, source_lane, admission_basis,
                            outcome, source_episode_projection_version,
                            source_route_signal_classifier_version,
                            dense_projection_version,
                            dense_document_version,
                            representation_version, model, dimension,
                            document_sha256, vector_f32, indexed_at,
                            generation_id
                        )
                        VALUES (
                            ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                            ?, ?, ?, ?, ?, ?, ?, ?, ?
                        )
                        """,
                        (
                            str(
                                representation.get(
                                    "representation_id"
                                )
                                or ""
                            ),
                            str(representation.get("doc_id") or ""),
                            session_id,
                            str(
                                representation.get("episode_id")
                                or ""
                            ),
                            str(representation.get("role") or ""),
                            str(representation.get("raw_ref") or ""),
                            str(
                                representation.get("segment_ref")
                                or ""
                            ),
                            str(
                                representation.get("session_ref")
                                or ""
                            ),
                            str(
                                representation.get("source_lane")
                                or ""
                            ),
                            str(
                                representation.get(
                                    "admission_basis"
                                )
                                or ""
                            ),
                            str(
                                representation.get("outcome")
                                or ""
                            ),
                            EPISODE_SEMANTIC_PROJECTION_VERSION,
                            ROUTE_SIGNAL_CLASSIFIER_VERSION,
                            EPISODE_DENSE_PROJECTION_VERSION,
                            EPISODE_DENSE_DOCUMENT_VERSION,
                            EPISODE_DENSE_REPRESENTATION_VERSION,
                            model,
                            dimension,
                            str(
                                representation.get(
                                    "document_sha256"
                                )
                                or ""
                            ),
                            sqlite3.Binary(
                                episode_dense_vector_blob(vector)
                            ),
                            now,
                            dense_generation_id,
                        ),
                    )
                status = "current" if episode_rows else "no_task_episodes"
                conn.execute(
                    """
                    INSERT OR REPLACE INTO episode_dense_session_state (
                        session_id, status, source_episode_projection_version,
                        source_route_signal_classifier_version,
                        dense_projection_version, dense_document_version, model,
                        dimension, episode_document_count, vector_count,
                        representation_document_count,
                        representation_vector_count, indexed_at,
                        last_error, generation_id, generation_identity_json
                    )
                    VALUES (
                        ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, '',
                        ?, ?
                    )
                    """,
                    (
                        session_id,
                        status,
                        EPISODE_SEMANTIC_PROJECTION_VERSION,
                        ROUTE_SIGNAL_CLASSIFIER_VERSION,
                        EPISODE_DENSE_PROJECTION_VERSION,
                        EPISODE_DENSE_DOCUMENT_VERSION,
                        model,
                        dimension,
                        len(episode_rows),
                        len(episode_vectors),
                        len(representation_documents),
                        len(representation_vectors),
                        now,
                        dense_generation_id,
                        dense_generation_identity_json,
                    ),
                )
                conn.commit()
            except (sqlite3.Error, ValueError) as exc:
                conn.rollback()
                diagnostic = f"episode_dense_store_failed:{session_id}:{exc}"
                diagnostics.append(diagnostic)
                results.append(
                    {
                        "session_id": session_id,
                        "status": "store_failed",
                        "episode_document_count": len(episode_rows),
                        "elapsed_ms": int((time.monotonic() - session_started) * 1000),
                        "diagnostics": [diagnostic],
                    }
                )
                continue
            results.append(
                {
                    "session_id": session_id,
                    "status": status,
                    "episode_document_count": len(episode_rows),
                    "vector_count": len(episode_vectors),
                    "representation_document_count": len(
                        representation_documents
                    ),
                    "representation_vector_count": len(
                        representation_vectors
                    ),
                    "model": model,
                    "dimension": dimension,
                    "document_chars": sum(
                        len(item) for item in documents
                    ),
                    "representation_document_chars": sum(
                        len(str(item.get("document") or ""))
                        for item in representation_documents
                    ),
                    "embedding_elapsed_ms": int_value(embedding.get("elapsed_ms")),
                    "prompt_tokens": int_value(embedding.get("prompt_tokens")),
                    "elapsed_ms": int((time.monotonic() - session_started) * 1000),
                    "diagnostics": [],
                }
            )
    finally:
        conn.close()
    coverage = episode_dense_projection_state(aoa_root, records=selected_records)
    generation_publish = (
        publish_search_projection_generation_identity(
            aoa_root=aoa_root,
            projection="episode_dense",
            identity=dense_generation_identity,
            coverage_current=bool(
                coverage.get("status") == "current"
                and not coverage.get("projection_dirty")
                and int_value(coverage.get("current_session_count"))
                == int_value(coverage.get("source_session_count"))
            ),
        )
    )
    processed_count = len(results)
    successful_count = sum(1 for item in results if item.get("status") in {"current", "no_task_episodes"})
    completed_session_ids = [
        str(item.get("session_id") or "")
        for item in results
        if item.get("status") in {"current", "no_task_episodes"} and str(item.get("session_id") or "")
    ]
    budget_exhausted = "episode_dense_index_budget_exhausted" in diagnostics
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "episode_dense_index",
        "generated_at": now,
        "ok": processed_count > 0 and successful_count == processed_count and not diagnostics and not budget_exhausted,
        "status": "current" if processed_count and successful_count == processed_count else "partial_or_failed",
        "target": target,
        "dirty_only": dirty_only,
        "since": since,
        "until": until,
        "limit": limit,
        "budget_seconds": budget_seconds,
        "budget_exhausted": budget_exhausted,
        "selected_count": selected_count,
        "processed_count": processed_count,
        "successful_count": successful_count,
        "completed_session_ids": completed_session_ids,
        "selection": selection,
        "projection_version": EPISODE_DENSE_PROJECTION_VERSION,
        "document_version": EPISODE_DENSE_DOCUMENT_VERSION,
        "source_episode_projection_version": EPISODE_SEMANTIC_PROJECTION_VERSION,
        "provider": provider,
        "coverage": coverage,
        "generation_publish": generation_publish,
        "storage_mode": (
            "normalized_float32_exact_cosine_"
            "episode_and_representation_sidecars_v2"
        ),
        "index_choice": "exact vector scan is lossless and bounded at the current episode cardinality; ANN is deferred until measured scale requires it",
        "authority_boundary": (
            "dense scores navigate generated episode representations; "
            "only resolved raw transcript refs remain authority"
        ),
        "elapsed_ms": int((time.monotonic() - started) * 1000),
        "db_path": str(db_path),
        "diagnostics": diagnostics,
        "sessions": results,
    }
    if write_report:
        diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
        diagnostics_dir.mkdir(parents=True, exist_ok=True)
        stem = f"{compact_stamp()}__episode-dense-index"
        report_json = diagnostics_dir / f"{stem}.json"
        write_json(report_json, payload)
        payload["report_json"] = str(report_json)
    return payload


def episode_dense_optional_provider_unavailable(result: dict[str, Any]) -> bool:
    """Separate optional accelerator absence from projection/data corruption."""
    if str(result.get("status") or "") == "deferred_provider_unavailable":
        return int_value(result.get("selected_count")) > 0
    if int_value(result.get("selected_count")) <= 0 or int_value(result.get("successful_count")) > 0:
        return False
    sessions = result.get("sessions") if isinstance(result.get("sessions"), list) else []
    if not sessions:
        return False
    for session in sessions:
        if not isinstance(session, dict) or str(session.get("status") or "") != "embedding_failed":
            return False
        embedding = session.get("embedding") if isinstance(session.get("embedding"), dict) else {}
        if str(embedding.get("status") or "") not in EPISODE_DENSE_PROVIDER_UNAVAILABLE_STATUSES:
            return False
    return True


def episode_dense_post_write_coherence(
    *,
    action_results: list[dict[str, Any]],
    final_dense_state: dict[str, Any],
    final_snapshot_captured: bool,
    upstream_changed_session_ids: list[str] | None = None,
) -> dict[str, Any]:
    dense_action = next(
        (
            action
            for action in action_results
            if isinstance(action, dict) and str(action.get("id") or "") == "refresh_episode_dense_projection"
        ),
        {},
    )
    dense_result = dense_action.get("result") if isinstance(dense_action.get("result"), dict) else {}
    completed_session_items = dense_result.get("completed_session_ids")
    if not isinstance(completed_session_items, list):
        completed_session_items = []
    completed_session_ids = sorted(
        {
            str(item)
            for item in completed_session_items
            if item
        }
    )
    upstream_session_ids = sorted(
        {
            str(item)
            for item in (upstream_changed_session_ids or [])
            if item
        }
    )
    selection = dense_result.get("selection") if isinstance(dense_result.get("selection"), dict) else {}
    selected_priority_session_ids = sorted(
        {
            str(item)
            for item in selection.get("selected_priority_session_ids", [])
            if item
        }
    )
    declared_deferred_priority_ids = {
        str(item)
        for item in selection.get("deferred_priority_session_ids", [])
        if item
    }
    final_dense_status = str(final_dense_state.get("status") or "")
    final_dirty_items = final_dense_state.get("dirty_session_ids")
    final_state_readable = bool(
        final_snapshot_captured
        and isinstance(final_dirty_items, list)
        and final_dense_status != "missing"
        and not final_dense_status.startswith("sqlite_")
    )
    base = {
        "completed_session_count": len(completed_session_ids),
        "completed_session_ids": completed_session_ids,
        "upstream_changed_session_count": len(upstream_session_ids),
        "upstream_changed_session_ids": upstream_session_ids,
        "selected_priority_session_ids": selected_priority_session_ids,
        "final_dense_status": final_dense_status,
        "final_dirty_session_count": int_value(final_dense_state.get("dirty_session_count")),
        "final_snapshot_captured": final_snapshot_captured,
        "final_state_readable": final_state_readable,
    }
    if not completed_session_ids and not upstream_session_ids:
        return {
            "status": "not_applicable",
            **base,
            "lost_completed_session_ids": [],
            "unrestored_upstream_session_ids": [],
            "deferred_upstream_session_ids": [],
            "diagnostics": [],
        }
    if not final_state_readable:
        return {
            "status": "unverified",
            **base,
            "lost_completed_session_ids": [],
            "unrestored_upstream_session_ids": [],
            "deferred_upstream_session_ids": [],
            "diagnostics": ["episode_dense_post_write_coherence_unverified"],
        }
    final_dirty_ids = {
        str(item)
        for item in final_dirty_items
        if item
    }
    lost_completed_session_ids = sorted(set(completed_session_ids) & final_dirty_ids)
    dirty_upstream_ids = set(upstream_session_ids) & final_dirty_ids
    deferred_action = str(dense_action.get("status") or "") in {
        "deferred_budget_exhausted",
        "applied_partial_budget_exhausted",
        "deferred_optional_provider_unavailable",
    }
    deferred_upstream_session_ids = sorted(
        dirty_upstream_ids
        if deferred_action
        else dirty_upstream_ids & declared_deferred_priority_ids
    )
    unrestored_upstream_session_ids = sorted(
        dirty_upstream_ids
        - set(deferred_upstream_session_ids)
        - set(lost_completed_session_ids)
    )
    diagnostics = [
        f"episode_dense_completed_session_still_dirty:{session_id}"
        for session_id in lost_completed_session_ids
    ]
    diagnostics.extend(
        f"episode_dense_upstream_session_not_restored:{session_id}"
        for session_id in unrestored_upstream_session_ids
    )
    return {
        "status": "failed" if diagnostics else ("remaining" if deferred_upstream_session_ids else "passed"),
        **base,
        "lost_completed_session_ids": lost_completed_session_ids,
        "unrestored_upstream_session_ids": unrestored_upstream_session_ids,
        "deferred_upstream_session_ids": deferred_upstream_session_ids,
        "diagnostics": diagnostics,
    }


def search_index_default_rebuild(
    *,
    target: str,
    since: str | None = None,
    until: str | None = None,
    limit: int | None = None,
    force_rebuild: bool = False,
    no_rebuild: bool = False,
) -> bool:
    if force_rebuild and no_rebuild:
        raise ValueError("--rebuild and --no-rebuild cannot be used together")
    if force_rebuild:
        return True
    if no_rebuild:
        return False
    return (not target or target == "all") and since is None and until is None and limit is None


def search_rebuild_temp_path(db_path: Path) -> Path:
    return db_path.with_name(f".{db_path.name}.rebuild-{os.getpid()}")


def cleanup_search_rebuild_temp(temp_db_path: Path) -> None:
    for suffix in ("", "-journal", "-wal", "-shm"):
        path = Path(str(temp_db_path) + suffix)
        if path.exists():
            path.unlink()


def search_row_value(row: sqlite3.Row, key: str, default: Any = "") -> Any:
    return row[key] if key in row.keys() else default


def search_row_session_dir(row: sqlite3.Row) -> Path | None:
    manifest_path = Path(str(search_row_value(row, "manifest_path", "") or ""))
    if manifest_path.name == "session.manifest.json":
        return manifest_path.parent
    raw_path = Path(str(search_row_value(row, "raw_path", "") or ""))
    if raw_path.parent.name == "raw":
        return raw_path.parent.parent
    return None


def search_row_raw_path(row: sqlite3.Row) -> Path | None:
    raw_path_value = str(search_row_value(row, "raw_path", "") or "")
    if raw_path_value:
        return Path(raw_path_value)
    session_dir = search_row_session_dir(row)
    if not session_dir:
        return None
    manifest_path = session_dir / "session.manifest.json"
    if manifest_path.exists():
        manifest = read_json(manifest_path, {})
        if isinstance(manifest, dict):
            return manifest_raw_path(session_dir, manifest)
    return session_dir / "raw" / "session.raw.jsonl"


def segment_id_from_artifact_ref(value: Any) -> str:
    name = path_without_anchor(value).name
    if "__" in name:
        prefix = name.split("__", 1)[0]
        if prefix.isdigit():
            return prefix
    return ""


def search_row_segment_id(row: sqlite3.Row) -> str:
    segment_id = str(search_row_value(row, "segment_id", "") or "")
    if segment_id:
        return segment_id
    for key in ("segment_index_path", "segment_ref", "raw_block_ref"):
        segment_id = segment_id_from_artifact_ref(search_row_value(row, key, ""))
        if segment_id:
            return segment_id
    return ""


def search_ref_for_session_path(path: Path, session_dir: Path, *, prefer_basename: bool = False) -> str:
    if prefer_basename:
        return path.name
    try:
        return path.relative_to(session_dir).as_posix()
    except ValueError:
        return str(path)


def ref_anchor_suffix(value: Any) -> str:
    text = str(value or "")
    return "#" + text.split("#", 1)[1] if "#" in text else ""


def segment_event_from_index(index_path: Path, event_id: str) -> dict[str, Any] | None:
    if not event_id or not index_path.exists():
        return None
    segment_index = read_json(index_path, {})
    events = segment_index.get("events") if isinstance(segment_index, dict) and isinstance(segment_index.get("events"), list) else []
    for event in events:
        if isinstance(event, dict) and str(event.get("event_id") or "") == event_id:
            return event
    return None


def live_segment_index_candidate(session_dir: Path, segment_id: str, event_id: str = "") -> tuple[Path | None, dict[str, Any] | None]:
    if not segment_id:
        return None, None
    candidates = sorted((session_dir / "segments").glob(f"{segment_id}__*.index.json"))
    if event_id:
        for candidate in candidates:
            event = segment_event_from_index(candidate, event_id)
            if event:
                return candidate, event
    if len(candidates) == 1:
        return candidates[0], None
    return None, None


def live_segment_artifact_candidate(session_dir: Path, segment_id: str, *, subdir: str, suffix: str) -> Path | None:
    if not segment_id:
        return None
    candidates = sorted((session_dir / subdir).glob(f"{segment_id}__*{suffix}"))
    if len(candidates) == 1:
        return candidates[0]
    return None


def resolve_search_result_refs(row: sqlite3.Row) -> tuple[dict[str, str], dict[str, Any]]:
    refs = {
        "session": str(search_row_value(row, "manifest_path", "") or ""),
        "segment": str(search_row_value(row, "segment_ref", "") or ""),
        "segment_index": str(search_row_value(row, "segment_index_path", "") or ""),
        "raw": str(search_row_value(row, "raw_ref", "") or ""),
        "raw_block": str(search_row_value(row, "raw_block_ref", "") or ""),
    }
    resolution: dict[str, Any] = {"resolved": False, "diagnostics": []}
    session_dir = search_row_session_dir(row)
    segment_id = search_row_segment_id(row)
    event_id = str(search_row_value(row, "event_id", "") or "")
    if not session_dir or not segment_id:
        return refs, resolution

    original_segment_index = refs["segment_index"]
    segment_index_path = Path(original_segment_index) if original_segment_index else Path()
    event: dict[str, Any] | None = None
    if not original_segment_index:
        candidate, event = live_segment_index_candidate(session_dir, segment_id, event_id)
        if candidate:
            refs["segment_index"] = str(candidate)
            resolution["resolved"] = True
            resolution["segment_index"] = str(candidate)
            resolution["diagnostics"].append("segment_index_ref_derived_by_segment_id")
    elif not segment_index_path.exists():
        candidate, event = live_segment_index_candidate(session_dir, segment_id, event_id)
        if candidate:
            refs["segment_index"] = str(candidate)
            resolution["resolved"] = True
            resolution["original_segment_index"] = original_segment_index
            resolution["segment_index"] = str(candidate)
            resolution["diagnostics"].append("segment_index_ref_resolved_by_segment_id")

    raw_path_value = str(search_row_raw_path(row) or "")
    segment_ref_path = resolve_evidence_ref_path(refs["segment"], raw_path_value=raw_path_value)
    if refs["segment"] and not segment_ref_path.exists():
        if event is None and refs["segment_index"]:
            event = segment_event_from_index(Path(refs["segment_index"]), event_id)
        event_anchor = str(event.get("md_anchor") or "") if isinstance(event, dict) else ""
        if event_anchor:
            refs["segment"] = event_anchor
            resolution["resolved"] = True
            resolution["diagnostics"].append("segment_ref_resolved_from_live_event_anchor")
        else:
            candidate = live_segment_artifact_candidate(session_dir, segment_id, subdir="segments", suffix=".md")
            if candidate:
                refs["segment"] = f"{candidate.name}{ref_anchor_suffix(search_row_value(row, 'segment_ref', ''))}"
                resolution["resolved"] = True
                resolution["diagnostics"].append("segment_ref_resolved_by_segment_id")

    raw_block_ref = refs["raw_block"]
    raw_block_path = resolve_evidence_ref_path(raw_block_ref, raw_path_value=raw_path_value)
    if raw_block_ref and not raw_block_path.exists():
        candidate = live_segment_artifact_candidate(session_dir, segment_id, subdir="raw/blocks", suffix=".raw.jsonl")
        if candidate:
            refs["raw_block"] = search_ref_for_session_path(candidate, session_dir)
            resolution["resolved"] = True
            resolution["diagnostics"].append("raw_block_ref_resolved_by_segment_id")

    resolution["diagnostics"] = sorted(set(str(item) for item in resolution["diagnostics"] if item))
    return refs, resolution


def route_result_ref_fields(refs: dict[str, Any]) -> dict[str, Any]:
    raw_ref = str(refs.get("raw") or "")
    segment_ref = str(refs.get("segment") or "")
    segment_index_ref = str(refs.get("segment_index") or "")
    return {
        "session_ref": str(refs.get("session") or ""),
        "segment_ref": segment_ref,
        "segment_index": segment_index_ref,
        "segment_index_ref": segment_index_ref,
        "raw_ref": raw_ref,
        "raw_line": line_from_raw_ref(raw_ref),
        "raw_block_ref": str(refs.get("raw_block") or ""),
    }


def search_result_freshness(
    row: sqlite3.Row,
    *,
    resolved_refs: dict[str, str] | None = None,
    ref_resolution: dict[str, Any] | None = None,
) -> dict[str, Any]:
    status = str(row["freshness_status"] or "unverifiable")
    reasons = [reason for reason in str(row["stale_reason"] or "").split(",") if reason]
    payload = {
        "status": status,
        "reasons": reasons,
        "basis": "indexed_snapshot",
        "live_verification": "not_checked_fast_route",
    }
    session_id = str(search_row_value(row, "session_id", "") or "")
    indexed_classifier_value = (
        row["indexed_route_signal_classifier_version"]
        if "indexed_route_signal_classifier_version" in row.keys()
        else None
    )
    if session_id and indexed_classifier_value is not None:
        indexed_classifier_version = int_value(indexed_classifier_value)
        payload["indexed_route_signal_classifier_version"] = indexed_classifier_version
        payload["route_signal_classifier_version"] = ROUTE_SIGNAL_CLASSIFIER_VERSION
        if indexed_classifier_version != ROUTE_SIGNAL_CLASSIFIER_VERSION:
            reasons = sorted(set([*reasons, "route_signal_classifier_version_changed"]))
            payload.update(
                {
                    "status": "stale",
                    "reasons": reasons,
                    "basis": "indexed_snapshot_plus_projection_epoch_check",
                    "readability": "stale-readable",
                    "indexed_snapshot_status": status,
                }
            )
    manifest_path_value = str(search_row_value(row, "manifest_path", "") or "")
    live_source_check: dict[str, Any] = {}
    if manifest_path_value:
        manifest_path = Path(manifest_path_value)
        manifest = read_json(manifest_path, {}) if manifest_path.exists() else {}
        raw_manifest = manifest.get("raw") if isinstance(manifest, dict) else None
        if isinstance(manifest, dict) and isinstance(raw_manifest, dict) and raw_manifest:
            live_source_check = manifest_live_source_snapshot_freshness(manifest)
            payload["live_source"] = live_source_check
            payload["live_verification"] = "live_source_stat_checked"
            if live_source_check.get("status") in {"deferred", "stale"}:
                payload.update(
                    {
                        "status": str(live_source_check.get("status")),
                        "reasons": sorted(
                            set([*list(payload.get("reasons") or reasons), *list(live_source_check.get("reasons") or [])])
                        ),
                        "basis": "live_source_snapshot_check",
                        "readability": "stale-readable",
                        "indexed_snapshot_status": status,
                    }
                )
    segment_path_value = (resolved_refs or {}).get("segment_index") or (row["segment_index_path"] if "segment_index_path" in row.keys() else "")
    if not segment_path_value:
        session_dir = search_row_session_dir(row)
        segment_id = search_row_segment_id(row)
        if session_dir and segment_id:
            candidate, _event = live_segment_index_candidate(session_dir, segment_id, str(search_row_value(row, "event_id", "") or ""))
            if candidate:
                segment_path_value = str(candidate)
    segment_sha = row["segment_index_sha256"] if "segment_index_sha256" in row.keys() else ""
    if segment_path_value:
        segment_check = segment_index_freshness(Path(str(segment_path_value)), segment_sha)
        if ref_resolution and ref_resolution.get("resolved"):
            segment_check["ref_resolution"] = {
                "diagnostics": ref_resolution.get("diagnostics", []),
                "original_segment_index": ref_resolution.get("original_segment_index", ""),
                "segment_index": ref_resolution.get("segment_index", ""),
            }
        payload["segment_index_live_check"] = segment_check.get("status")
        if segment_check.get("status") != "fresh":
            segment_reasons = list(segment_check.get("reasons") or [])
            return {
                **segment_check,
                "reasons": sorted(set([*list(payload.get("reasons") or []), *segment_reasons])),
                "live_source": live_source_check,
                "basis": "segment_index_live_check",
                "raw_live_verification": "not_checked_fast_route",
                **(
                    {
                        "indexed_route_signal_classifier_version": payload["indexed_route_signal_classifier_version"],
                        "route_signal_classifier_version": payload["route_signal_classifier_version"],
                    }
                    if "indexed_route_signal_classifier_version" in payload
                    else {}
                ),
            }
    if ref_resolution and ref_resolution.get("resolved"):
        payload["ref_resolution"] = {
            "diagnostics": ref_resolution.get("diagnostics", []),
            "original_segment_index": ref_resolution.get("original_segment_index", ""),
            "segment_index": ref_resolution.get("segment_index", ""),
        }
    return payload


def agent_event_source_from_tags(tags: Any) -> str:
    for token in str(tags or "").split():
        if token.startswith("agent_event_source:"):
            return token.split(":", 1)[1]
    return ""


def exact_session_filter_for_search(aoa_root: Path, session: str | None) -> tuple[str | None, str | None]:
    if not session:
        return None, None
    text = str(session).strip()
    if not text:
        return None, None
    if text.lower() == "latest":
        try:
            record = resolve_session_record(aoa_root, text)
        except ValueError:
            record = {}
        label = str(record.get("session_label") or "")
        session_id = str(record.get("session_id") or "")
        if label:
            return "documents.session_label", label
        if session_id:
            return "documents.session_id", session_id
    if re.fullmatch(r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}", text):
        return "documents.session_id", text
    if (aoa_root / "sessions" / text).is_dir():
        return "documents.session_label", text
    return None, None


LIGHTWEIGHT_SEARCH_PREVIEW_TOKEN_PREFIXES = (
    "route_signal:",
    "route_layer:",
)


def lightweight_search_body_preview(text: Any, *, max_chars: int = 420) -> str:
    raw = re.sub(r"\s+", " ", str(text or "")).strip()
    if not raw:
        return ""
    tokens = [
        token
        for token in raw.split()
        if not any(token.startswith(prefix) for prefix in LIGHTWEIGHT_SEARCH_PREVIEW_TOKEN_PREFIXES)
    ]
    cleaned = " ".join(tokens).strip()
    return short_text(cleaned or raw, max_chars=max_chars)


def compact_search_result(
    row: sqlite3.Row,
    *,
    explain: bool = False,
    query: str = "",
    full_body: str | None = None,
    semantic_preview: bool = True,
    raw_ref_preview: bool | None = None,
) -> dict[str, Any]:
    refs, ref_resolution = resolve_search_result_refs(row)
    freshness = search_result_freshness(row, resolved_refs=refs, ref_resolution=ref_resolution)
    body_source = full_body if full_body is not None else row["body"]
    snippet = (
        short_text(body_source, max_chars=420)
        if semantic_preview
        else lightweight_search_body_preview(body_source, max_chars=420)
    )
    use_raw_ref_preview = semantic_preview if raw_ref_preview is None else bool(raw_ref_preview)
    raw_semantic_preview = (
        route_raw_semantic_preview(row, refs, max_chars=420)
        if use_raw_ref_preview
        else {"status": "skipped", "text": ""}
    )
    event_timestamp = (
        str(row["exact_literal_source_timestamp"] or "")
        if "exact_literal_source_timestamp" in row.keys()
        else ""
    )
    preview = raw_semantic_preview.get("text") or snippet
    preview_source = raw_semantic_preview.get("status") if raw_semantic_preview.get("text") else "search_body"
    result = {
        "rank": row["rank"] if "rank" in row.keys() else 0,
        "match_channel": (
            str(row["match_channel"])
            if "match_channel" in row.keys() and row["match_channel"]
            else ("semantic_fts" if query else "structured_filter")
        ),
        "doc_id": row["id"],
        "doc_type": row["doc_type"],
        "session_id": row["session_id"],
        "session_label": row["session_label"],
        "session_title": row["session_title"],
        "session_date": row["session_date"],
        "archive_status": row["archive_status"],
        "segment_id": row["segment_id"],
        "event_id": row["event_id"],
        "event_timestamp": event_timestamp,
        "event_type": row["event_type"],
        "family": row["family"],
        "phase": row["phase"],
        "actor": row["actor"],
        "action": row["action"],
        "outcome": row["outcome"],
        "conversation_act": row["conversation_act"],
        "session_act": row["session_act"] if "session_act" in row.keys() else None,
        "agent_event": row["agent_event"] if "agent_event" in row.keys() else None,
        "usage_role": row["usage_role"] if "usage_role" in row.keys() else None,
        "agent_event_source": agent_event_source_from_tags(row["tags"] if "tags" in row.keys() else ""),
        "task_episode_id": row["task_episode_id"] if "task_episode_id" in row.keys() else None,
        "route_layers": row["route_layers"] if "route_layers" in row.keys() else "",
        "route_signals": row["route_signals"] if "route_signals" in row.keys() else "",
        "title": row["title"],
        "snippet": snippet,
        "preview": preview,
        "bounded_preview": preview,
        "preview_source": preview_source,
        "refs": refs,
        **route_result_ref_fields(refs),
        "search_catalog": {
            "active_projection": SEARCH_ACTIVE_PROJECTION_MONOLITH,
            "shard_strategy": SEARCH_SHARD_STRATEGY,
            "shard": search_shard_key_for_session(str(row["session_label"] or ""), str(row["session_date"] or "")),
        },
        "freshness": freshness,
    }
    if ref_resolution.get("resolved"):
        result["ref_resolution"] = {
            "diagnostics": ref_resolution.get("diagnostics", []),
            "original_segment_index": ref_resolution.get("original_segment_index", ""),
            "segment_index": ref_resolution.get("segment_index", ""),
        }
    if explain:
        result["explain"] = {
            "query": query,
            "matched_document_layer": row["doc_type"],
            "routing_fields": {
                "event_type": row["event_type"],
                "family": row["family"],
                "conversation_act": row["conversation_act"],
                "session_act": row["session_act"] if "session_act" in row.keys() else None,
                "agent_event": row["agent_event"] if "agent_event" in row.keys() else None,
                "usage_role": row["usage_role"] if "usage_role" in row.keys() else None,
                "agent_event_source": agent_event_source_from_tags(row["tags"] if "tags" in row.keys() else ""),
                "task_episode_id": row["task_episode_id"] if "task_episode_id" in row.keys() else None,
                "route_layers": row["route_layers"] if "route_layers" in row.keys() else "",
                "route_signals": row["route_signals"] if "route_signals" in row.keys() else "",
                "archive_status": row["archive_status"],
                "event_timestamp": event_timestamp,
            },
            "why_this_is_not_authority": "Search result routes to raw/segment refs; raw transcript and segment indexes remain stronger evidence.",
        }
        if not semantic_preview:
            result["explain"]["semantic_preview"] = "skipped_for_lightweight_route"
        if (
            str(result.get("match_channel") or "") == "exact_literal_postings"
            and str(literal_query_shape(query).get("primary") or "") == LITERAL_QUERY_KIND_PATH
        ):
            source_score, source_signals = exact_literal_path_candidate_score(row)
            result["explain"]["exact_literal_source_ranking"] = {
                "score": round(source_score, 4),
                "signals": source_signals,
                "policy": "path_event_role_then_chronological_v1",
                "bm25_role": "bounded_candidate_generation_only",
            }
    return result


def search_document_bodies_for_rows(conn: sqlite3.Connection, rows: list[sqlite3.Row]) -> dict[int, str]:
    if not rows or not sqlite_table_exists(conn, "document_bodies"):
        return {}
    rowids = [int_value(row["rowid"]) for row in rows if "rowid" in row.keys()]
    if not rowids:
        return {}
    bodies: dict[int, str] = {}
    for rowid in rowids:
        try:
            row = conn.execute("SELECT body_zlib FROM document_bodies WHERE doc_rowid = ?", (rowid,)).fetchone()
        except sqlite3.Error:
            return {}
        if not row:
            continue
        try:
            bodies[rowid] = zlib.decompress(bytes(row["body_zlib"])).decode("utf-8", errors="replace")
        except (zlib.error, TypeError, ValueError):
            continue
    return bodies


def search_index_metadata(conn: sqlite3.Connection) -> dict[str, Any]:
    if not sqlite_table_exists(conn, "meta"):
        return {}
    rows = conn.execute("SELECT key, value FROM meta").fetchall()
    return {str(row["key"]): row["value"] for row in rows}


SEARCH_PROJECTION_SEMANTIC_DIGEST_VERSION = 2
SEARCH_PROJECTION_SEMANTIC_DIGEST_TABLE_ORDER = (
    ("documents", "id"),
    ("document_bodies", "doc_rowid"),
    ("route_terms", "layer, key, route_signal"),
    ("document_routes", "doc_rowid, route_id"),
    ("omitted_context_tail_route_refs", "id"),
    ("session_index_state", "session_id"),
    ("search_freshness_state", "session_id"),
    ("exact_literal_posting_meta", "doc_rowid"),
    ("exact_literal_transition_posting_meta", "doc_rowid"),
    ("exact_literal_session_state", "session_id"),
    ("episode_semantic_meta", "doc_id"),
    ("episode_semantic_payloads", "doc_rowid"),
    (
        "episode_entity_postings",
        "session_id, episode_id, route_signal, relation, raw_line, raw_ref",
    ),
    ("episode_semantic_session_state", "session_id"),
    ("episode_dense_vectors", "doc_id"),
    ("episode_dense_session_state", "session_id"),
)
SEARCH_PROJECTION_SEMANTIC_DIGEST_VOLATILE_COLUMNS = frozenset(
    {
        "indexed_at",
        "updated_at",
        "last_checked",
        "last_indexed_at",
        "source_latest_mtime",
        "live_transcript_mtime",
        "session_dir",
        "live_transcript_path",
    }
)


def search_projection_semantic_digest(
    conn: sqlite3.Connection,
) -> dict[str, Any]:
    """Hash semantic projection content without publication-time metadata."""

    digest = hashlib.sha256()
    table_counts: dict[str, int] = {}
    for table, order_by in SEARCH_PROJECTION_SEMANTIC_DIGEST_TABLE_ORDER:
        if not sqlite_table_exists(conn, table):
            continue
        columns = [
            str(row[1])
            for row in conn.execute(
                f"PRAGMA table_info({table})"
            ).fetchall()
            if str(row[1])
            not in SEARCH_PROJECTION_SEMANTIC_DIGEST_VOLATILE_COLUMNS
        ]
        if not columns:
            continue
        quoted_columns = ", ".join(
            '"' + column.replace('"', '""') + '"'
            for column in columns
        )
        row_count = 0
        digest.update(f"table:{table}\n".encode("utf-8"))
        for row in conn.execute(
            f"SELECT {quoted_columns} FROM {table} ORDER BY {order_by}"
        ):
            canonical_values: list[Any] = []
            for value in row:
                if isinstance(value, (bytes, bytearray, memoryview)):
                    raw = bytes(value)
                    canonical_values.append(
                        {
                            "blob_sha256": hashlib.sha256(raw).hexdigest(),
                            "blob_bytes": len(raw),
                        }
                    )
                else:
                    canonical_values.append(value)
            digest.update(
                json.dumps(
                    canonical_values,
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            )
            digest.update(b"\n")
            row_count += 1
        table_counts[table] = row_count
    return {
        "version": SEARCH_PROJECTION_SEMANTIC_DIGEST_VERSION,
        "sha256": digest.hexdigest(),
        "table_counts": table_counts,
        "excluded_columns": sorted(
            SEARCH_PROJECTION_SEMANTIC_DIGEST_VOLATILE_COLUMNS
        ),
        "truth_status": (
            "semantic_projection_content_digest_not_sqlite_binary_digest"
        ),
    }


def sqlite_table_exists(conn: sqlite3.Connection, name: str) -> bool:
    row = conn.execute("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ? LIMIT 1", (name,)).fetchone()
    return row is not None


REQUIRED_SEARCH_DOCUMENT_COLUMNS = {
    "id",
    "doc_type",
    "session_id",
    "session_label",
    "session_act",
    "agent_event",
    "usage_role",
    "task_episode_id",
    "route_layers",
    "route_signals",
    "payload_json",
}


REQUIRED_SEARCH_TABLES = {
    "documents",
    "documents_fts",
    "document_bodies",
    "route_terms",
    "document_routes",
    "session_index_state",
    "meta",
}


def search_schema_diagnostics(conn: sqlite3.Connection) -> list[str]:
    tables = {str(row[0]) for row in conn.execute("SELECT name FROM sqlite_master WHERE type = 'table'").fetchall()}
    diagnostics: list[str] = []
    for table in sorted(REQUIRED_SEARCH_TABLES - tables):
        diagnostics.append(f"search_schema_missing_table:{table}")
    if "documents" in tables:
        columns = {str(row[1]) for row in conn.execute("PRAGMA table_info(documents)").fetchall()}
        for column in sorted(REQUIRED_SEARCH_DOCUMENT_COLUMNS - columns):
            diagnostics.append(f"search_schema_missing_column:documents.{column}")
    return diagnostics


def search_usage_role_filter_supported(aoa_root: Path, *, provider: str = "portable_sqlite") -> bool:
    if provider != "portable_sqlite":
        return False
    db_path = search_db_path(aoa_root)
    if not db_path.exists():
        return False
    conn: sqlite3.Connection | None = None
    try:
        conn = connect_existing_search_db(db_path)
        columns = {str(row[1]) for row in conn.execute("PRAGMA table_info(documents)").fetchall()}
        return "usage_role" in columns
    except sqlite3.Error:
        return False
    finally:
        if conn is not None:
            conn.close()


def search_route_storage_counts(conn: sqlite3.Connection) -> dict[str, int]:
    route_count = 0
    route_doc_count = 0
    route_term_count = 0
    if sqlite_table_exists(conn, "document_routes"):
        route_count = int(conn.execute("SELECT COUNT(*) FROM document_routes").fetchone()[0])
        route_doc_count = int(conn.execute("SELECT COUNT(DISTINCT doc_rowid) FROM document_routes").fetchone()[0])
    if sqlite_table_exists(conn, "route_terms"):
        route_term_count = int(conn.execute("SELECT COUNT(*) FROM route_terms").fetchone()[0])
    return {
        "route_index_count": route_count,
        "route_index_document_count": route_doc_count,
        "route_term_count": route_term_count,
    }


def ymd_sort_value(value: Any) -> int:
    text = str(value or "")
    match = re.match(r"(20\d{2})-([01]\d)-([0-3]\d)", text)
    if not match:
        return 0
    return int("".join(match.groups()))


def search_shard_overlaps_date_filter(shard_key: str, date_from: str | None, date_to: str | None) -> bool:
    match = re.match(r"month/(20\d{2})-([01]\d)$", str(shard_key or ""))
    if not match:
        return True
    month_start = f"{match.group(1)}-{match.group(2)}-01"
    year = int(match.group(1))
    month = int(match.group(2))
    next_year = year + 1 if month == 12 else year
    next_month = 1 if month == 12 else month + 1
    next_month_start = f"{next_year:04d}-{next_month:02d}-01"
    if date_to and month_start > parse_date_arg(date_to):
        return False
    if date_from and next_month_start <= parse_date_arg(date_from):
        return False
    return True


def search_result_event_sort_value(result: dict[str, Any]) -> int:
    for key in ("raw_line", "line"):
        value = int_value(result.get(key), 0)
        if value > 0:
            return value
    event_id = str(result.get("event_id") or "")
    if event_id.isdigit():
        return int(event_id)
    doc_id = str(result.get("doc_id") or "")
    match = re.search(r":(\d+):(\d+)$", doc_id)
    if match:
        return int(match.group(1)) * 1_000_000 + int(match.group(2))
    return 0


def search_result_order_key(result: dict[str, Any], *, query: str) -> tuple[float, int, int, str]:
    try:
        rank = float(result.get("rank") or 0.0)
    except (TypeError, ValueError):
        rank = 0.0
    rank_key = rank if fts_query_from_user(query) else 0.0
    return (
        rank_key,
        -ymd_sort_value(result.get("session_date")),
        -search_result_event_sort_value(result),
        str(result.get("doc_id") or ""),
    )


