def goal_lifecycle_route_search(
    *,
    aoa_root: Path,
    target: str = "all",
    session: str | None = None,
    goal_id: str | None = None,
    status: str | None = None,
    event_kind: str | None = None,
    limit: int = 20,
    order: str = "recent",
) -> dict[str, Any]:
    now = utc_now()
    try:
        if session:
            records = [resolve_session_record(aoa_root, session)]
        elif target and target != "all":
            records = [resolve_session_record(aoa_root, target)]
        else:
            records = chronological_session_records(aoa_root, limit=None)
    except ValueError as exc:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "goal_lifecycle_route_results",
            "goal_lifecycle_schema_version": GOAL_LIFECYCLE_SCHEMA_VERSION,
            "generated_at": now,
            "ok": False,
            "result_count": 0,
            "results": [],
            "diagnostics": [str(exc)],
        }
    results: list[dict[str, Any]] = []
    selected_count = 0
    incompatible_session_indexes: list[dict[str, Any]] = []
    ordered_records = list(reversed(records)) if order == "recent" else list(records)
    normalized_event_kind = route_key_slug(event_kind, fallback="") if event_kind else ""
    for record in ordered_records:
        session_dir = session_dir_from_record(record)
        index = read_json(session_dir / SESSION_INDEX_JSON, {})
        if not isinstance(index, dict):
            continue
        index_stale_reasons = (
            generated_session_index_stale_reasons_for_session(
                session_dir,
                index,
            )
        )
        if index_stale_reasons:
            session_identity = str(
                record.get("session_id")
                or record.get("session_label")
                or session_dir.name
            )
            incompatible_session_indexes.append(
                {
                    "session": session_identity,
                    "reasons": index_stale_reasons,
                    "next_command": (
                        "python3 scripts/aoa_session_memory.py "
                        "reindex-sessions "
                        f"{shlex.quote(session_identity)}"
                    ),
                }
            )
            continue
        display = index.get("display") if isinstance(index.get("display"), dict) else {}
        session_label = str(display.get("label") or record.get("session_label") or session_dir.name)
        session_id = str(index.get("session_id") or record.get("session_id") or "")
        lifecycles = index.get("goal_lifecycles", []) if isinstance(index.get("goal_lifecycles"), list) else []
        task_episodes = session_index_task_episode_components(
            session_dir,
            index,
        )
        lifecycle_items = list(reversed(lifecycles)) if order == "recent" else list(lifecycles)
        for item in lifecycle_items:
            if not isinstance(item, dict):
                continue
            selected_count += 1
            compact = compact_goal_lifecycle(
                item,
                session_label=session_label,
                session_id=session_id,
                aoa_root=aoa_root,
                task_episodes=task_episodes,
            )
            if goal_id and str(compact.get("goal_id") or "") != goal_id:
                continue
            if status and str(compact.get("status") or "") != status:
                continue
            if normalized_event_kind and normalized_event_kind not in {
                route_key_slug(kind, fallback="")
                for kind in compact.get("event_kinds", [])
                if kind
            }:
                continue
            results.append(compact)
            if len(results) >= max(1, limit):
                break
        if len(results) >= max(1, limit):
            break
    provider_status = search_provider_status(aoa_root=aoa_root, provider_name="portable_sqlite")
    provider_summary = compact_search_provider_status_for_route(provider_status, provider_name="portable_sqlite")
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "goal_lifecycle_route_results",
        "goal_lifecycle_schema_version": GOAL_LIFECYCLE_SCHEMA_VERSION,
        "generated_at": now,
        "ok": True,
        "target": target,
        "session": session or "",
        "goal_id": goal_id or "",
        "status": status or "",
        "event_kind": event_kind or "",
        "order": order,
        "selected_goal_lifecycle_count": selected_count,
        "result_count": len(results),
        "results": results,
        "incompatible_session_indexes": (
            incompatible_session_indexes
        ),
        "generation_identity": session_index_generation_identity(),
        "provider": provider_summary,
        "diagnostics": (
            ["goal_lifecycle_source_generation_incompatible"]
            if incompatible_session_indexes
            else []
        ),
        "next_route": "Use work_chain next_expansion for task/answer context, then refs, graph_refs, raw_refs, and segment_refs for authority; lifecycle packets are generated navigation.",
    }


TRACE_ROUTE_KINDS = {
    "auto",
    "entity",
    "skill",
    "mcp",
    "hook",
    "receipt",
    "tool",
    "api",
    "agent_event",
    "plugin",
    "agent",
    "script",
    "validator",
    "test",
    "eval",
    "playbook",
    "technique",
    "mechanic",
    "graph",
    "memory",
    "git",
    "github",
    "path",
    "goal",
    "failure",
    "error",
    "decision",
    "owner_route",
    "route_next_action",
    "external",
}
TRACE_ROUTE_KIND_ALIASES = {
    "mcp_service": "mcp",
    "mcp_tool": "tool",
    "failure_mode": "failure",
    "hook_health": "receipt",
    "route": "owner_route",
}
TRACE_ROUTE_KIND_CHOICES = sorted(TRACE_ROUTE_KINDS | set(TRACE_ROUTE_KIND_ALIASES))
TRACE_TEXT_FALLBACK_RECALL_THRESHOLD = "recall_threshold"
TRACE_TEXT_FALLBACK_SPECIFIC_ROUTE_HIT = "specific_route_hit"
TRACE_TEXT_FALLBACK_POLICIES = {
    TRACE_TEXT_FALLBACK_RECALL_THRESHOLD,
    TRACE_TEXT_FALLBACK_SPECIFIC_ROUTE_HIT,
}

def normalize_trace_route_kind(kind: str | None) -> str:
    normalized = str(kind or "auto").strip().lower()
    return TRACE_ROUTE_KIND_ALIASES.get(normalized, normalized)


def trace_kind_payload_fields(requested_kind: str | None, normalized_kind: str) -> dict[str, str]:
    requested = str(requested_kind or "auto").strip().lower() or "auto"
    fields = {"kind": normalized_kind}
    if requested != normalized_kind:
        fields["requested_kind"] = requested
    return fields


def trace_anchor_aliases(anchor: str) -> list[str]:
    raw = str(anchor or "").strip()
    aliases: list[str] = []

    def add_alias(value: str) -> None:
        text = str(value or "").strip().strip("`'\"")
        if text and text not in aliases:
            aliases.append(text)

    add_alias(raw)
    if not raw:
        return aliases
    canonical_skill_key = canonical_skill_entity_key(raw)
    if canonical_skill_key:
        add_alias(canonical_skill_key)
        add_alias(canonical_skill_key.replace("_", "-"))
    add_alias(raw.replace("-", "_"))
    add_alias(raw.replace("_", "-"))
    slug = route_key_slug(raw, fallback="")
    if slug:
        add_alias(slug)
        add_alias(slug.replace("_", "-"))
    config_service_key = mcp_config_service_key(raw)
    if config_service_key:
        add_alias(config_service_key)
        add_alias(config_service_key.replace("_", "-"))
    for match in SKILL_PATH_ENTITY_PATTERN.finditer(raw):
        add_alias(match.group(1))
    for match in MCP_SERVICE_PATH_PATTERN.finditer(raw):
        add_alias(match.group(1))
    pathish = raw.replace("\\", "/")
    if "/" in pathish:
        parts = [part for part in pathish.split("/") if part and part not in {".", ".."}]
        for part in reversed(parts[-3:]):
            if part.lower() == "skill.md" and len(parts) >= 2:
                add_alias(parts[-2])
            elif part:
                add_alias(part)
    for alias in list(aliases):
        lowered = route_key_slug(alias, fallback="")
        for suffix in ("_skill", "_hook", "_tool"):
            if lowered.endswith(suffix):
                add_alias(lowered[: -len(suffix)])
    return aliases


def infer_trace_route_kinds(anchor: str, explicit_kind: str = "auto") -> list[str]:
    kind = normalize_trace_route_kind(explicit_kind)
    if kind != "auto":
        return [kind]
    lowered = str(anchor or "").strip().lower()
    aliases = trace_anchor_aliases(anchor)
    kinds: list[str] = []

    def add_kind(value: str) -> None:
        if value not in kinds:
            kinds.append(value)

    if "skill" in lowered or "skills/" in lowered:
        add_kind("skill")
    if "mcp" in lowered or any(canonical_mcp_service_key(alias, path_source="/" in alias) for alias in aliases):
        add_kind("mcp")
    hook_names = {route_key_slug(name, fallback=name) for name in HOOK_EVENT_ORDER}
    if "hook" in lowered or "receipt" in lowered or route_key_slug(lowered, fallback="") in hook_names:
        add_kind("hook")
    if "api" in lowered or any(api_entity_candidates_from_texts([alias]) for alias in aliases):
        add_kind("api")
    if any(AGENT_EVENT_ROUTE_ALIASES.get(route_key_slug(alias, fallback="")) for alias in aliases) or "agent_event" in lowered:
        add_kind("agent_event")
    if "plugin" in lowered or "plugin://" in lowered:
        add_kind("plugin")
    if "agent" in lowered or "agents/" in lowered:
        add_kind("agent")
    if "scripts/" in lowered or lowered.endswith((".sh", ".js", ".ts")):
        add_kind("script")
    if "validator" in lowered or "validate_" in lowered or "release_check" in lowered:
        add_kind("validator")
    if "pytest" in lowered or "tests/" in lowered or re.search(r"\btest[_-]", lowered):
        add_kind("test")
    if "eval" in lowered or "evaluation" in lowered or "inspect-ai" in lowered or "lighteval" in lowered or "evals/" in lowered:
        add_kind("eval")
    if "playbook" in lowered or "playbooks/" in lowered or "плейбук" in lowered:
        add_kind("playbook")
    if "technique" in lowered or "techniques/" in lowered or "техник" in lowered:
        add_kind("technique")
    if "mechanic" in lowered or "mechanics/" in lowered or "механик" in lowered:
        add_kind("mechanic")
    if "graph" in lowered or "graphrag" in lowered or "nodes" in lowered:
        add_kind("graph")
    if "memory" in lowered or "памят" in lowered or ".aoa/sessions" in lowered or ".codex/memories" in lowered:
        add_kind("memory")
    toolish = normalized_tool_name(anchor)
    if toolish and (
        toolish in {"exec_command", "write_stdin", "apply_patch", "update_plan", "view_image"}
        or toolish.startswith("mcp__")
        or "." in str(anchor)
    ):
        add_kind("tool")
    if lowered in {"git", "gh", "github"} or lowered.startswith("git ") or lowered.startswith("gh ") or "github" in lowered:
        add_kind("github" if "github" in lowered or lowered == "gh" else "git")
    if "/" in lowered or lowered.endswith((".md", ".py", ".json", ".toml", ".yaml", ".yml")):
        add_kind("path")
    if "goal" in lowered or "цель" in lowered or route_key_slug(lowered, fallback="") in {"create_goal", "update_goal", "get_goal", "goal_created", "goal_updated", "goal_completed", "goal_blocked", "goal_inspected"}:
        add_kind("goal")
    if "failure" in lowered or "failed" in lowered or "error" in lowered or "ошиб" in lowered or "timeout" in lowered or "stale" in lowered:
        add_kind("failure")
    if "decision" in lowered or "assumption" in lowered or "open thread" in lowered or "решен" in lowered:
        add_kind("decision")
    add_kind("entity")
    return kinds


def trace_route_candidate_is_generic(candidate: dict[str, Any]) -> bool:
    key = str(candidate.get("key") or "")
    source = str(candidate.get("source") or "")
    return (
        not key
        or key.startswith("namespace_")
        or source.endswith("_namespace_alias")
        or source.endswith("_layer_hint")
    )


def trace_route_candidate_is_specific(candidate: dict[str, Any]) -> bool:
    return bool(candidate.get("key")) and not trace_route_candidate_is_generic(candidate)


def trace_route_candidate_matches_anchor(
    candidate: dict[str, Any],
    *,
    anchor: str,
) -> bool:
    if not trace_route_candidate_is_specific(candidate):
        return False
    alias_keys = {
        route_key_slug(alias, fallback="")
        for alias in trace_anchor_aliases(anchor)
        if route_key_slug(alias, fallback="")
    }
    return str(candidate.get("key") or "") in alias_keys


def trace_route_owner_anchor_is_specific(anchor: str) -> bool:
    text = str(anchor or "").strip()
    if not text:
        return False
    if literal_query_is_natural_language_lookup(text):
        return False
    if len(search_tokenize(text)) > 4:
        return False
    slug = route_key_slug(text, fallback="")
    return bool(slug and slug not in {"owner", "owner_route", "route"})


def trace_route_lookup_candidates(candidates: list[dict[str, Any]], *, suppress_generic: bool = False) -> list[dict[str, Any]]:
    has_specific = any(trace_route_candidate_is_specific(candidate) for candidate in candidates)
    selected: list[dict[str, Any]] = []
    for candidate in candidates:
        if suppress_generic and trace_route_candidate_is_generic(candidate):
            continue
        if trace_route_candidate_is_generic(candidate) and has_specific:
            continue
        if str(candidate.get("key") or "").startswith("namespace_"):
            continue
        selected.append(candidate)
    return selected


def trace_route_candidates(anchor: str, *, kind: str = "auto") -> list[dict[str, Any]]:
    aliases = trace_anchor_aliases(anchor)
    kinds = infer_trace_route_kinds(anchor, kind)
    lowered = " ".join(aliases).lower()
    candidates: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()

    def add_candidate(layer: str, key: str = "", *, source: str, confidence: str = "medium", detail: str = "") -> None:
        normalized_layer = route_key_slug(layer, fallback=layer)
        normalized_key = route_key_slug(key, fallback=key) if key else ""
        if not normalized_layer:
            return
        route_signal = route_signal_token(normalized_layer, normalized_key) if normalized_key else ""
        token = (normalized_layer, normalized_key, route_signal)
        if token in seen:
            return
        seen.add(token)
        candidates.append(
            {
                "layer": normalized_layer,
                "key": normalized_key,
                "route_signal": route_signal,
                "axis": ROUTE_SIGNAL_LAYER_TO_AXIS.get(normalized_layer, ""),
                "source": source,
                "confidence": confidence,
                "detail": detail or key or layer,
            }
        )

    if any(item in kinds for item in {"skill", "entity", "mcp"}):
        for alias in aliases:
            mcp_service_key = canonical_mcp_service_key(alias, path_source="/" in alias) if "mcp" in kinds else None
            skill_key = skill_entity_key(alias, explicit=True, path_source="/" in alias) if "skill" in kinds else None
            if not mcp_service_key and not skill_key:
                for entity in named_entity_candidates_from_text(alias):
                    add_candidate("entity", entity, source="named_entity_alias", detail=alias)
            slug = route_key_slug(alias, fallback="")
            if not mcp_service_key and not skill_key and slug and (slug.startswith("aoa_") or slug.startswith("abyss_") or "skill" in kinds):
                add_candidate("entity", slug, source="canonical_alias", detail=alias)

    if "skill" in kinds:
        add_candidate("skill", "", source="skill_layer_hint", confidence="low", detail="generic skill route layer")
        canonical_skill_key = canonical_skill_entity_key(anchor)
        if canonical_skill_key:
            add_candidate("skill", canonical_skill_key, source="canonical_skill_alias", confidence="high", detail=anchor)
            add_candidate("entity", canonical_skill_key, source="canonical_skill_entity_alias", confidence="high", detail=anchor)
        else:
            for key in sorted(skill_entity_candidates_from_texts(aliases + [anchor]))[:8]:
                add_candidate("skill", key, source="skill_text_alias", confidence="high", detail=anchor)
                add_candidate("entity", key, source="skill_text_entity_alias", confidence="medium", detail=anchor)

    if "mcp" in kinds:
        add_candidate("mcp", "", source="mcp_layer_hint", confidence="low", detail="generic MCP route layer")
        for alias in aliases:
            key = canonical_mcp_service_key(alias, path_source="/" in alias)
            if key:
                add_candidate("mcp", key, source="mcp_service_alias", confidence="high", detail=alias)
                add_candidate("entity", key, source="mcp_service_entity_alias", confidence="high", detail=alias)
        if any(alias in {"read_mcp_resource", "list_mcp_resources", "list_mcp_resource_templates"} for alias in aliases):
            add_candidate("external_snapshot", "mcp", source="mcp_tool_alias", detail=anchor)

    if any(item in kinds for item in {"hook", "receipt"}):
        add_candidate("hook_health", "", source="hook_layer_hint", confidence="low", detail="generic hook route layer")
        hook_slug_by_name = {route_key_slug(name, fallback=name): name for name in HOOK_EVENT_ORDER}
        for alias in aliases:
            alias_slug = route_key_slug(alias, fallback="")
            if alias_slug in hook_slug_by_name:
                add_candidate("hook_health", hook_slug_by_name[alias_slug], source="hook_name_alias", confidence="high", detail=alias)
        if "raw_unavailable" in lowered or "raw unavailable" in lowered:
            add_candidate("hook_health", "raw_unavailable", source="hook_health_alias", confidence="high", detail=anchor)
        if "deferred" in lowered or "queue" in lowered or "worker" in lowered:
            add_candidate("hook_health", "deferred_sync_or_worker_queue", source="hook_health_alias", confidence="medium", detail=anchor)
        if "hook" in kinds:
            add_candidate("mutation_surface", "hooks", source="hook_surface_alias", confidence="medium", detail=anchor)

    if "goal" in kinds:
        add_candidate("goal", "", source="goal_layer_hint", confidence="low", detail="generic goal route layer")
        goal_aliases = {
            "create_goal": "goal_create_requested",
            "update_goal": "goal_updated",
            "get_goal": "goal_inspected",
            "goal_create_requested": "goal_create_requested",
            "goal_create_failed": "goal_create_failed",
            "goal_created": "goal_created",
            "goal_updated": "goal_updated",
            "goal_completed": "goal_completed",
            "goal_blocked": "goal_blocked",
            "goal_inspected": "goal_inspected",
        }
        for alias in aliases:
            slug = route_key_slug(alias, fallback="")
            key = goal_aliases.get(slug)
            if key:
                add_candidate("goal", key, source="goal_tool_alias", confidence="high", detail=alias)
            elif slug and slug not in {"goal", "цель"}:
                add_candidate("goal", slug, source="goal_alias", confidence="medium", detail=alias)

    if any(item in kinds for item in {"failure", "error"}):
        add_candidate("failure_mode", "", source="failure_layer_hint", confidence="low", detail="generic failure route layer")
        failure_aliases = {
            "timeout": "timeout",
            "timed_out": "timeout",
            "test_failure": "test_failure",
            "failed_tests": "test_failure",
            "schema_mismatch": "schema_mismatch",
            "missing_file": "missing_file",
            "permission": "permission",
            "command_not_found": "command_not_found",
            "raw_unavailable": "hook_raw_unavailable",
            "hook_raw_unavailable": "hook_raw_unavailable",
            "stale": "external_state_drift",
            "drift": "external_state_drift",
        }
        for alias in aliases:
            slug = route_key_slug(alias, fallback="")
            key = failure_aliases.get(slug, slug if slug and slug not in {"failure", "failed", "ошибка"} else "")
            if key:
                add_candidate("failure_mode", key, source="failure_alias", confidence="medium", detail=alias)

    if "decision" in kinds:
        add_candidate("decision_thread", "", source="decision_layer_hint", confidence="low", detail="generic decision route layer")
        decision_aliases = {
            "decision": "decision",
            "assumption": "assumption",
            "open_thread": "open_thread",
            "remaining_gap": "remaining_gap",
            "blocked": "blocked",
            "operator_accepted": "operator_accepted",
            "operator_rejected": "operator_rejected",
        }
        for alias in aliases:
            slug = route_key_slug(alias, fallback="")
            key = decision_aliases.get(slug, slug if slug and slug not in {"decision", "решение"} else "")
            if key:
                add_candidate("decision_thread", key, source="decision_alias", confidence="medium", detail=alias)

    if "owner_route" in kinds:
        add_candidate("owner_route", "", source="owner_route_layer_hint", confidence="low", detail="generic owner-route layer")
        if trace_route_owner_anchor_is_specific(anchor):
            for alias in aliases:
                slug = route_key_slug(alias, fallback="")
                if slug and slug not in {"owner", "owner_route", "route"}:
                    add_candidate("owner_route", slug, source="owner_route_alias", confidence="medium", detail=alias)

    if "route_next_action" in kinds:
        add_candidate("route_next_action", "", source="route_next_action_layer_hint", confidence="low", detail="generic route-next-action layer")
        for alias in aliases:
            slug = route_key_slug(alias, fallback="")
            if slug and slug not in {"route_next_action", "route", "next_action"}:
                add_candidate("route_next_action", slug, source="route_next_action_alias", confidence="medium", detail=alias)

    if "tool" in kinds:
        add_candidate("tool", "", source="tool_layer_hint", confidence="low", detail="generic tool route layer")
        for alias in aliases:
            short = normalized_tool_name(alias)
            if short:
                add_candidate("tool", short, source="tool_alias", confidence="high", detail=alias)
                namespace = tool_namespace_for_name(alias)
                if namespace and namespace != "unknown":
                    add_candidate("tool", f"namespace_{namespace}", source="tool_namespace_alias", confidence="medium", detail=alias)
                mcp_kind = session_act_for_mcp_tool(alias)
                if mcp_kind:
                    add_candidate("mcp", mcp_kind, source="mcp_tool_alias", confidence="high", detail=alias)

    for layer, candidate_func in (
        ("api", api_entity_candidates_from_texts),
        ("plugin", plugin_entity_candidates_from_texts),
        ("agent", agent_entity_candidates_from_texts),
        ("script", script_entity_candidates_from_texts),
        ("validator", validator_entity_candidates_from_texts),
        ("test", test_entity_candidates_from_texts),
        ("eval", eval_entity_candidates_from_texts),
        ("playbook", playbook_entity_candidates_from_texts),
        ("technique", technique_entity_candidates_from_texts),
        ("mechanic", mechanic_entity_candidates_from_texts),
        ("graph", graph_entity_candidates_from_texts),
        ("memory", memory_entity_candidates_from_texts),
    ):
        if layer not in kinds:
            continue
        add_candidate(layer, "", source=f"{layer}_layer_hint", confidence="low", detail=f"generic {layer} route layer")
        candidate_keys = set(candidate_func(aliases + [anchor]))
        if layer == "script" and not candidate_keys:
            # A consumer may already know the entity kind while holding only a
            # basename such as ``generate_decision_indexes.py`` or a stable
            # bare slug such as ``build_candidate_handoff``.  Event-side
            # extraction normally sees ``scripts/...`` or a command prefix,
            # but an explicitly typed lookup must not collapse that precise
            # identity to the generic ``script:*`` layer.
            for alias in aliases + [anchor]:
                bare_name = str(alias or "").strip().strip("`'\"")
                is_bare_filename = bool(
                    re.fullmatch(
                        r"[A-Za-z0-9_.-]+\.(?:py|sh|js|ts|tsx|go|rs)",
                        bare_name,
                        flags=re.IGNORECASE,
                    )
                )
                is_bare_slug = bool(
                    re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]+", bare_name)
                    and ("_" in bare_name or "-" in bare_name)
                )
                if not (is_bare_filename or is_bare_slug):
                    continue
                key = path_stem_entity_key(bare_name)
                if key and key not in {"script", "scripts"}:
                    candidate_keys.add(key)
        for key in sorted(candidate_keys)[:8]:
            add_candidate(layer, key, source=f"{layer}_alias", confidence="high", detail=anchor)
            if layer != "memory":
                add_candidate("entity", key, source=f"{layer}_entity_alias", confidence="medium", detail=anchor)

    if "agent_event" in kinds:
        add_candidate("agent_event", "", source="agent_event_layer_hint", confidence="low", detail="generic agent event route layer")
        for alias in aliases:
            slug = route_key_slug(alias, fallback="")
            key = AGENT_EVENT_ROUTE_ALIASES.get(slug, slug if slug.startswith("assistant_") else "")
            if key:
                add_candidate("agent_event", key, source="agent_event_alias", confidence="high", detail=alias)

    if "path" in kinds:
        for alias in aliases:
            if "/" in alias or "." in Path(alias).name:
                add_candidate("path", route_key_slug(alias, fallback="path", max_chars=96), source="path_alias", confidence="medium", detail=alias)

    if any(item in kinds for item in {"git", "github"}):
        add_candidate("git", "", source="git_layer_hint", confidence="low", detail="generic git route layer")
        for key in sorted(git_entity_candidates_from_texts(aliases + [anchor]))[:8]:
            add_candidate("git", key, source="git_alias", confidence="high", detail=anchor)
            add_candidate("entity", key, source="git_entity_alias", confidence="medium", detail=anchor)
        add_candidate("delivery_state", "", source="git_layer_hint", confidence="low", detail="generic delivery route layer")
        if "status" in lowered or "diff" in lowered:
            add_candidate("delivery_state", "local_diff", source="git_alias", confidence="medium", detail=anchor)
        if "commit" in lowered or "committed" in lowered:
            add_candidate("delivery_state", "committed", source="git_alias", confidence="medium", detail=anchor)
        if "push" in lowered or "pushed" in lowered:
            add_candidate("delivery_state", "pushed", source="git_alias", confidence="medium", detail=anchor)
        if "pr" in lowered or "pull request" in lowered:
            add_candidate("delivery_state", "pr_opened", source="github_alias", confidence="medium", detail=anchor)
        if "merge" in lowered or "merged" in lowered:
            add_candidate("delivery_state", "merged", source="github_alias", confidence="medium", detail=anchor)
        if "github" in lowered or "gh" in lowered:
            add_candidate("external_snapshot", "github", source="github_alias", confidence="medium", detail=anchor)
            add_candidate("entity", "github", source="github_alias", confidence="medium", detail=anchor)

    if "external" in kinds:
        for key in ("github", "gmail", "google_drive", "google_calendar", "web", "mcp"):
            if key.replace("_", " ") in lowered or key in lowered:
                add_candidate("external_snapshot", key, source="external_alias", confidence="medium", detail=anchor)

    return candidates


def compact_trace_result(result: dict[str, Any]) -> dict[str, Any]:
    return {
        "doc_id": result.get("doc_id"),
        "doc_type": result.get("doc_type"),
        "session_label": result.get("session_label"),
        "session_date": result.get("session_date"),
        "event_type": result.get("event_type"),
        "conversation_act": result.get("conversation_act"),
        "session_act": result.get("session_act"),
        "matched_routes": result.get("matched_routes", []),
        "title": result.get("title"),
        "refs": result.get("refs"),
        "freshness": result.get("freshness"),
    }


def route_trace_markdown(payload: dict[str, Any]) -> str:
    lines = [
        "# Route Trace",
        "",
        f"- generated_at: `{payload.get('generated_at')}`",
        f"- anchor: `{payload.get('anchor')}`",
        f"- kind: `{payload.get('kind')}`",
        f"- inferred_kinds: `{', '.join(payload.get('inferred_kinds', []))}`",
        f"- result_count: `{payload.get('result_count')}`",
        "",
        "## Route Candidates",
        "",
        "| layer | key | confidence | source |",
        "| --- | --- | --- | --- |",
    ]
    for candidate in payload.get("route_candidates", []) if isinstance(payload.get("route_candidates"), list) else []:
        lines.append(
            "| `{layer}` | `{key}` | `{confidence}` | `{source}` |".format(
                layer=candidate.get("layer", ""),
                key=candidate.get("key", "") or "*",
                confidence=candidate.get("confidence", ""),
                source=candidate.get("source", ""),
            )
        )
    lines.extend(["", "## Results", "", "| route | session | event | refs |", "| --- | --- | --- | --- |"])
    for result in payload.get("results", []) if isinstance(payload.get("results"), list) else []:
        refs = result.get("refs") if isinstance(result.get("refs"), dict) else {}
        lines.append(
            "| `{route}` | `{session}` | `{event}` | `{refs}` |".format(
                route=", ".join(str(item) for item in result.get("matched_routes", [])[:4]),
                session=result.get("session_label", ""),
                event=result.get("event_type", ""),
                refs=refs.get("raw") or refs.get("segment") or refs.get("session") or "",
            )
        )
    diagnostics = payload.get("diagnostics") if isinstance(payload.get("diagnostics"), list) else []
    if diagnostics:
        lines.extend(["", "## Diagnostics", ""])
        lines.extend(f"- {item}" for item in diagnostics)
    return "\n".join(lines) + "\n"


def trace_route(
    *,
    aoa_root: Path,
    anchor: str,
    kind: str = "auto",
    limit: int = 40,
    per_route_limit: int = 12,
    provider: str = "portable_sqlite",
    doc_type: str | None = "event",
    session: str | None = None,
    explain: bool = True,
    write_report: bool = False,
    text_fallback_policy: str = TRACE_TEXT_FALLBACK_RECALL_THRESHOLD,
) -> dict[str, Any]:
    now = utc_now()
    normalized_kind = normalize_trace_route_kind(kind)
    if normalized_kind not in TRACE_ROUTE_KINDS:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "route_trace",
            "generated_at": now,
            "ok": False,
            "anchor": anchor,
            **trace_kind_payload_fields(kind, normalized_kind),
            "result_count": 0,
            "results": [],
            "diagnostics": [f"unknown trace kind: {kind}"],
        }
    limit = max(1, int_value(limit, 40))
    per_route_limit = max(1, int_value(per_route_limit, 12))
    selected_text_fallback_policy = str(
        text_fallback_policy
        or TRACE_TEXT_FALLBACK_RECALL_THRESHOLD
    ).strip()
    if selected_text_fallback_policy not in TRACE_TEXT_FALLBACK_POLICIES:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "route_trace",
            "generated_at": now,
            "ok": False,
            "anchor": anchor,
            **trace_kind_payload_fields(kind, normalized_kind),
            "result_count": 0,
            "results": [],
            "text_fallback_policy": selected_text_fallback_policy,
            "diagnostics": [
                "unknown trace text fallback policy: "
                f"{selected_text_fallback_policy}"
            ],
        }
    resolved_doc_type = None if str(doc_type or "").lower() in {"", "all"} else str(doc_type)
    diagnostics: list[str] = trace_identity_diagnostics(anchor, kind=normalized_kind)
    candidates = trace_route_candidates(anchor, kind=normalized_kind)
    if (
        normalized_kind == "owner_route"
        and not any(trace_route_candidate_is_specific(candidate) for candidate in candidates)
    ):
        diagnostics.append(
            "owner_route_requires_specific_historical_anchor; a natural-language "
            "current-state query requires an external owner/runtime handoff"
        )
    lookup_candidates = trace_route_lookup_candidates(candidates, suppress_generic=bool(diagnostics))
    route_results: list[dict[str, Any]] = []
    merged: dict[str, dict[str, Any]] = {}

    def merge_results(results: list[dict[str, Any]], matched_route: str) -> None:
        for item in results:
            doc_id = str(item.get("doc_id") or "")
            if not doc_id:
                continue
            existing = merged.get(doc_id)
            if existing is None:
                existing = dict(item)
                existing["matched_routes"] = []
                merged[doc_id] = existing
            matched = existing.setdefault("matched_routes", [])
            if isinstance(matched, list) and matched_route and matched_route not in matched:
                matched.append(matched_route)

    for candidate in lookup_candidates:
        route_signal_value = str(candidate.get("route_signal") or "")
        route_layer_value = str(candidate.get("layer") or "") if not route_signal_value else None
        matched_route = route_signal_value or f"{candidate.get('layer')}:*"
        payload = search_sessions(
            aoa_root=aoa_root,
            query="",
            limit=per_route_limit,
            provider=provider,
            session=session,
            doc_type=resolved_doc_type,
            route_layer=route_layer_value,
            route_signal=route_signal_value or None,
            explain=explain,
        )
        route_results.append(
            {
                "candidate": candidate,
                "ok": payload.get("ok"),
                "result_count": payload.get("result_count"),
                "diagnostics": payload.get("diagnostics", []),
            }
        )
        if not payload.get("ok"):
            diagnostics.extend(str(item) for item in payload.get("diagnostics", []))
            continue
        merge_results(payload.get("results", []) if isinstance(payload.get("results"), list) else [], matched_route)

    route_hit_count = len(merged)
    text_search_skipped = False
    text_search_skip_reason = ""
    skip_text_search = bool(diagnostics) and not lookup_candidates
    route_hit_threshold = max(1, min(limit, per_route_limit))
    specific_lookup_candidate_present = any(
        trace_route_candidate_is_specific(candidate)
        for candidate in lookup_candidates
    )
    exact_anchor_lookup_candidate_present = any(
        trace_route_candidate_matches_anchor(
            candidate,
            anchor=anchor,
        )
        for candidate in lookup_candidates
    )
    if (
        not skip_text_search
        and lookup_candidates
        and (
            (
                selected_text_fallback_policy
                == TRACE_TEXT_FALLBACK_SPECIFIC_ROUTE_HIT
                and specific_lookup_candidate_present
                and route_hit_count > 0
            )
            or (
                selected_text_fallback_policy
                == TRACE_TEXT_FALLBACK_RECALL_THRESHOLD
                and route_hit_count >= route_hit_threshold
                and normalized_kind not in {"auto", "entity", "path"}
            )
        )
    ):
        skip_text_search = True
        text_search_skipped = True
        text_search_skip_reason = (
            "specific_route_hit_sufficient_for_bounded_seed"
            if selected_text_fallback_policy
            == TRACE_TEXT_FALLBACK_SPECIFIC_ROUTE_HIT
            else "typed_route_recall_threshold_satisfied"
        )
    elif (
        not skip_text_search
        and selected_text_fallback_policy
        == TRACE_TEXT_FALLBACK_SPECIFIC_ROUTE_HIT
        and normalized_kind == "auto"
        and specific_lookup_candidate_present
        and not exact_anchor_lookup_candidate_present
    ):
        skip_text_search = True
        text_search_skipped = True
        text_search_skip_reason = (
            "auto_partial_route_candidates_not_exact_graph_seed"
        )
    elif skip_text_search:
        text_search_skip_reason = "unknown_typed_identity"
    if skip_text_search:
        text_payload = {
            "ok": False,
            "result_count": 0,
            "diagnostics": [
                "text_search_skipped_for_typed_route_hits"
                if text_search_skipped
                else "text_search_skipped_for_unknown_typed_identity"
            ],
        }
    else:
        text_payload = search_sessions(
            aoa_root=aoa_root,
            query=anchor,
            limit=per_route_limit,
            provider=provider,
            session=session,
            doc_type=resolved_doc_type,
            explain=explain,
        )
        if text_payload.get("ok"):
            merge_results(text_payload.get("results", []) if isinstance(text_payload.get("results"), list) else [], "text")
        else:
            diagnostics.extend(str(item) for item in text_payload.get("diagnostics", []))

    results = list(merged.values())[:limit]
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "route_trace",
        "generated_at": now,
        "ok": not diagnostics,
        "anchor": anchor,
        **trace_kind_payload_fields(kind, normalized_kind),
        "inferred_kinds": infer_trace_route_kinds(anchor, normalized_kind),
        "aliases": trace_anchor_aliases(anchor),
        "doc_type": resolved_doc_type or "all",
        "session": session or "",
        "route_candidates": lookup_candidates,
        "candidate_diagnostics": diagnostics,
        "route_result_summaries": route_results,
        "route_hit_count_before_text_fallback": route_hit_count,
        "text_fallback_policy": selected_text_fallback_policy,
        "text_fallback_route_hit_threshold": route_hit_threshold,
        "specific_lookup_candidate_present": (
            specific_lookup_candidate_present
        ),
        "exact_anchor_lookup_candidate_present": (
            exact_anchor_lookup_candidate_present
        ),
        "text_search_skipped": text_search_skipped,
        "text_search_attempted": not skip_text_search,
        "text_search_skip_reason": text_search_skip_reason,
        "text_result_count": text_payload.get("result_count"),
        "result_count": len(results),
        "results": results,
        "diagnostics": diagnostics,
        "next_route": "Read result refs in order: raw_ref, segment_ref, session_ref. Search hits are routes, not authority.",
    }
    payload["evidence_envelope"] = session_memory_evidence_envelope(
        aoa_root=aoa_root,
        query=anchor,
        payload=payload,
        route_id="trace_route",
        route_reason="resolve one typed historical anchor before reading refs",
        route_authority="generated_route_index_navigation_only",
        next_route={
            "kind": "bounded_evidence_ref_read",
            "status": "ready" if results else "unresolved",
            "evidence_refs": [
                {
                    "candidate_id": item.get("doc_id"),
                    "refs": item.get("refs"),
                }
                for item in results[:8]
                if isinstance(item, dict)
                and isinstance(item.get("refs"), dict)
            ],
            "mutates": False,
        },
        budgets={
            "result_limit": limit,
            "per_route_limit": per_route_limit,
            "bounded": True,
        },
    )
    if write_report:
        diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
        diagnostics_dir.mkdir(parents=True, exist_ok=True)
        stem = f"{compact_stamp()}__route-trace__{readable_slug(anchor, fallback='anchor', max_chars=80)}"
        report_json = diagnostics_dir / f"{stem}.json"
        report_md = diagnostics_dir / f"{stem}.md"
        write_json(report_json, payload)
        write_markdown(report_md, route_trace_markdown(payload))
        payload["report_json"] = str(report_json)
        payload["report_markdown"] = str(report_md)
    return payload


