def graph_node_contract_kind(node_id: Any) -> str:
    value = str(node_id or "")
    if value.startswith("route:"):
        return "route"
    prefix = value.partition(":")[0]
    return {
        "session": "session",
        "segment": "segment",
        "event": "event",
        "task_episode": "task_episode",
        "goal_lifecycle": "goal_lifecycle",
        "work_context": "work_context",
        "raw_ref": "raw_ref",
        "entity_registry": "entity_registry",
        "decision": "decision",
        "artifact": "artifact",
    }.get(prefix, "unknown")


def graph_relation_evidence_status(edge: dict[str, Any]) -> dict[str, Any]:
    refs = (
        edge.get("evidence_refs")
        if isinstance(edge.get("evidence_refs"), list)
        else []
    )
    strong_ref_count = 0
    for ref in refs:
        if isinstance(ref, str) and ref.strip():
            strong_ref_count += 1
            continue
        if not isinstance(ref, dict):
            continue
        nested = ref.get("refs") if isinstance(ref.get("refs"), dict) else ref
        if any(
            str(nested.get(key) or "").strip()
            for key in (
                "raw",
                "raw_block",
                "segment",
                "segment_index",
                "session",
                "receipt",
                "registry",
            )
        ):
            strong_ref_count += 1
    return {
        "status": "present" if strong_ref_count else "missing",
        "evidence_ref_count": len(refs),
        "strong_evidence_ref_count": strong_ref_count,
    }


def graph_relation_temporal_semantics(
    edge: dict[str, Any],
    contract: dict[str, Any] | None,
) -> dict[str, Any]:
    source_event_time = str(
        edge.get("event_timestamp")
        or edge.get("source_event_timestamp")
        or edge.get("timestamp")
        or ""
    )
    target_event_time = str(edge.get("target_event_timestamp") or "")
    required_order = str(
        contract.get("temporal_order") if contract else ""
    )
    source_dt = parse_utc_timestamp(source_event_time) if source_event_time else None
    target_dt = parse_utc_timestamp(target_event_time) if target_event_time else None
    if not required_order:
        order_status = "not_required"
    elif source_dt is None or target_dt is None:
        order_status = "unverified_open_boundary"
    elif required_order == "source_before_target":
        order_status = "valid" if source_dt <= target_dt else "invalid"
    elif required_order == "source_after_target":
        order_status = "valid" if source_dt >= target_dt else "invalid"
    elif required_order == "target_before_source":
        order_status = "valid" if target_dt <= source_dt else "invalid"
    else:
        order_status = "unverified_policy"
    valid_from = str(edge.get("valid_from") or "")
    valid_to = str(edge.get("valid_to") or "")
    valid_from_dt = parse_utc_timestamp(valid_from) if valid_from else None
    valid_to_dt = parse_utc_timestamp(valid_to) if valid_to else None
    if valid_from and valid_to and (
        valid_from_dt is None
        or valid_to_dt is None
        or valid_from_dt > valid_to_dt
    ):
        validity_status = "invalid"
    elif valid_from or valid_to:
        validity_status = "bounded_or_open_interval"
    else:
        validity_status = "not_declared"
    open_boundaries = [
        key
        for key, value in (
            ("source_event_time", source_event_time),
            ("target_event_time", target_event_time),
            ("valid_from", valid_from),
            ("valid_to", valid_to),
        )
        if not value
    ]
    return {
        "event_time": source_event_time,
        "source_event_time": source_event_time,
        "target_event_time": target_event_time,
        "recorded_at": str(
            edge.get("recorded_at")
            or edge.get("ingested_at")
            or ""
        ),
        "valid_from": valid_from,
        "valid_to": valid_to,
        "required_order": required_order or "none",
        "order_status": order_status,
        "validity_status": validity_status,
        "supersession_state": str(
            edge.get("supersession_state") or "not_declared"
        ),
        "projection_time": "graph_generation_identity",
        "open_boundaries": open_boundaries,
        "model_scope": (
            "relation_specific_event_and_validity_coordinates_not_"
            "universal_bitemporality"
        ),
    }


def graph_relation_contract_payload(
    edge: dict[str, Any],
) -> dict[str, Any]:
    normalized = dict(edge)
    edge_type = str(normalized.get("type") or "")
    contract = GRAPH_RELATION_CONTRACTS.get(edge_type)
    source_kind = graph_node_contract_kind(normalized.get("source"))
    target_kind = graph_node_contract_kind(normalized.get("target"))
    expected_domain = tuple(contract.get("domain", ())) if contract else ()
    expected_range = tuple(contract.get("range", ())) if contract else ()

    def kind_status(actual: str, expected: tuple[str, ...]) -> str:
        if not expected or "*" in expected:
            return "valid"
        if actual == "unknown":
            return "unverified"
        return "valid" if actual in expected else "invalid"

    domain_status = kind_status(source_kind, expected_domain)
    range_status = kind_status(target_kind, expected_range)
    if "invalid" in {domain_status, range_status}:
        domain_range_status = "invalid"
    elif "unverified" in {domain_status, range_status}:
        domain_range_status = "unverified"
    else:
        domain_range_status = "valid"
    requires_correlation = bool(
        contract and contract.get("requires_correlation")
    )
    correlation_id = str(normalized.get("correlation_id") or "")
    source_correlation_id = str(
        normalized.get("source_correlation_id") or ""
    )
    target_correlation_id = str(
        normalized.get("target_correlation_id") or ""
    )
    if not requires_correlation:
        correlation_status = "not_required"
    elif not correlation_id:
        correlation_status = "missing"
    elif source_correlation_id and target_correlation_id:
        correlation_status = (
            "matched_identity"
            if correlation_id
            == source_correlation_id
            == target_correlation_id
            else "mismatched_identity"
        )
    else:
        correlation_status = "unverified_identity"
    evidence = graph_relation_evidence_status(normalized)
    temporal_semantics = graph_relation_temporal_semantics(
        normalized,
        contract,
    )
    source_projection_candidate = (
        normalized.get("source_projection_candidate") is True
    )
    known_relation = contract is not None
    rejected = bool(
        domain_range_status == "invalid"
        or correlation_status in {"missing", "mismatched_identity"}
        or temporal_semantics["order_status"] == "invalid"
        or temporal_semantics["validity_status"] == "invalid"
    )
    observed = bool(
        known_relation
        and domain_range_status == "valid"
        and correlation_status
        in {"not_required", "matched_identity"}
        and evidence["status"] == "present"
        and not source_projection_candidate
    )
    relation_state = (
        "rejected"
        if rejected
        else "observed_projection"
        if observed
        else "inferred_candidate"
    )
    relation_family = str(
        contract.get("family") if contract else "unclassified_candidate"
    )
    if relation_family == "mention":
        semantic_boundary = "mention_only_never_usage_or_consequence"
    elif relation_family in {"derived_anchor", "canonicalization"}:
        semantic_boundary = (
            "derived_navigation_never_usage_ownership_or_causality"
        )
    elif relation_family in {
        "structural_containment",
        "task_lineage",
        "goal_lineage",
        "agent_lineage",
        "ownership_context",
    }:
        semantic_boundary = "structural_navigation_not_causality"
    elif relation_family in {
        "action_result",
        "result_action",
        "action_status",
    }:
        semantic_boundary = (
            "correlation_link_requires_raw_result_status_read_before_consequence"
        )
    elif relation_family == "causality":
        semantic_boundary = (
            "causal_candidate_requires_action_result_verification_chain"
        )
    else:
        semantic_boundary = (
            "relation_projection_requires_evidence_read_before_claim"
        )
    normalized.update(
        {
            "relation_contract_version": (
                GRAPH_RELATION_CONTRACT_VERSION
            ),
            "relation_family": relation_family,
            "direction": "source_to_target",
            "domain": {
                "expected": list(expected_domain),
                "observed": source_kind,
                "status": domain_status,
            },
            "range": {
                "expected": list(expected_range),
                "observed": target_kind,
                "status": range_status,
            },
            "domain_range_status": domain_range_status,
            "relation_state": relation_state,
            "observed_vs_inferred": (
                "observed"
                if relation_state == "observed_projection"
                else "candidate"
                if relation_state == "inferred_candidate"
                else "rejected"
            ),
            "correlation_status": correlation_status,
            "correlation_identity": {
                "relation": correlation_id,
                "source": source_correlation_id,
                "target": target_correlation_id,
            },
            "evidence_status": evidence["status"],
            "evidence_ref_count": evidence["evidence_ref_count"],
            "strong_evidence_ref_count": (
                evidence["strong_evidence_ref_count"]
            ),
            "temporal_order_status": temporal_semantics[
                "order_status"
            ],
            "temporal_semantics": temporal_semantics,
            "semantic_boundary": semantic_boundary,
            "navigation_admissible": not rejected,
            "answer_admissible": False,
            "answer_admission_next": (
                "open correlation-matched raw/segment refs and apply the claim-shape gate"
            ),
        }
    )
    return normalized


def graph_relation_projection_state_from_connection(
    conn: sqlite3.Connection,
    *,
    sample_limit: int = 12,
) -> dict[str, Any]:
    if not sqlite_table_exists(conn, "edge_contribs"):
        return {
            "status": "missing",
            "edge_contribution_count": 0,
            "diagnostics": ["edge_contribs_table_missing"],
        }
    try:
        row = conn.execute(
            """
            SELECT
                COUNT(*) AS edge_count,
                SUM(
                    CASE
                    WHEN json_extract(
                        payload_json,
                        '$.relation_contract_version'
                    ) IS NULL
                    THEN 1 ELSE 0 END
                ) AS contract_missing_count,
                SUM(
                    CASE
                    WHEN json_extract(
                        payload_json,
                        '$.relation_contract_version'
                    ) != ?
                    THEN 1 ELSE 0 END
                ) AS contract_mismatch_count,
                SUM(
                    CASE
                    WHEN json_extract(
                        payload_json,
                        '$.relation_state'
                    ) = 'observed_projection'
                    THEN 1 ELSE 0 END
                ) AS observed_count,
                SUM(
                    CASE
                    WHEN json_extract(
                        payload_json,
                        '$.relation_state'
                    ) = 'inferred_candidate'
                    THEN 1 ELSE 0 END
                ) AS candidate_count,
                SUM(
                    CASE
                    WHEN json_extract(
                        payload_json,
                        '$.relation_state'
                    ) = 'rejected'
                    THEN 1 ELSE 0 END
                ) AS rejected_count,
                SUM(
                    CASE
                    WHEN json_extract(
                        payload_json,
                        '$.domain_range_status'
                    ) = 'invalid'
                    THEN 1 ELSE 0 END
                ) AS domain_range_invalid_count,
                SUM(
                    CASE
                    WHEN json_extract(
                        payload_json,
                        '$.temporal_order_status'
                    ) = 'invalid'
                    THEN 1 ELSE 0 END
                ) AS temporal_order_invalid_count,
                SUM(
                    CASE
                    WHEN json_extract(
                        payload_json,
                        '$.temporal_semantics.validity_status'
                    ) = 'invalid'
                    THEN 1 ELSE 0 END
                ) AS validity_invalid_count,
                SUM(
                    CASE
                    WHEN json_extract(
                        payload_json,
                        '$.answer_admissible'
                    ) NOT IN (0, 'false')
                    THEN 1 ELSE 0 END
                ) AS direct_answer_admission_violation_count
            FROM edge_contribs
            """,
            (GRAPH_RELATION_CONTRACT_VERSION,),
        ).fetchone()
        counts = {
            key: int_value(row[key]) if row else 0
            for key in (
                "edge_count",
                "contract_missing_count",
                "contract_mismatch_count",
                "observed_count",
                "candidate_count",
                "rejected_count",
                "domain_range_invalid_count",
                "temporal_order_invalid_count",
                "validity_invalid_count",
                "direct_answer_admission_violation_count",
            )
        }
        failure_count = sum(
            counts[key]
            for key in (
                "contract_missing_count",
                "contract_mismatch_count",
                "rejected_count",
                "domain_range_invalid_count",
                "temporal_order_invalid_count",
                "validity_invalid_count",
                "direct_answer_admission_violation_count",
            )
        )
        bounded_limit = max(0, min(int_value(sample_limit, 12), 50))
        samples = (
            [
                {
                    "source_key": str(item["source_key"] or ""),
                    "edge_id": str(item["edge_id"] or ""),
                    "edge_type": str(item["edge_type"] or ""),
                    "relation_state": str(
                        item["relation_state"] or ""
                    ),
                    "domain_range_status": str(
                        item["domain_range_status"] or ""
                    ),
                    "temporal_order_status": str(
                        item["temporal_order_status"] or ""
                    ),
                    "validity_status": str(
                        item["validity_status"] or ""
                    ),
                    "relation_contract_version": int_value(
                        item["relation_contract_version"]
                    ),
                }
                for item in conn.execute(
                    """
                    SELECT
                        source_key,
                        edge_id,
                        edge_type,
                        json_extract(
                            payload_json,
                            '$.relation_state'
                        ) AS relation_state,
                        json_extract(
                            payload_json,
                            '$.domain_range_status'
                        ) AS domain_range_status,
                        json_extract(
                            payload_json,
                            '$.temporal_order_status'
                        ) AS temporal_order_status,
                        json_extract(
                            payload_json,
                            '$.temporal_semantics.validity_status'
                        ) AS validity_status,
                        json_extract(
                            payload_json,
                            '$.relation_contract_version'
                        ) AS relation_contract_version
                    FROM edge_contribs
                    WHERE json_extract(
                              payload_json,
                              '$.relation_contract_version'
                          ) IS NULL
                       OR json_extract(
                              payload_json,
                              '$.relation_contract_version'
                          ) != ?
                       OR json_extract(
                              payload_json,
                              '$.relation_state'
                          ) = 'rejected'
                       OR json_extract(
                              payload_json,
                              '$.domain_range_status'
                          ) = 'invalid'
                       OR json_extract(
                              payload_json,
                              '$.temporal_order_status'
                          ) = 'invalid'
                       OR json_extract(
                              payload_json,
                              '$.temporal_semantics.validity_status'
                          ) = 'invalid'
                       OR json_extract(
                              payload_json,
                              '$.answer_admissible'
                          ) NOT IN (0, 'false')
                    ORDER BY source_key, edge_id
                    LIMIT ?
                    """,
                    (
                        GRAPH_RELATION_CONTRACT_VERSION,
                        bounded_limit,
                    ),
                ).fetchall()
            ]
            if bounded_limit and failure_count
            else []
        )
    except sqlite3.Error as exc:
        return {
            "status": "unverified",
            "edge_contribution_count": 0,
            "diagnostics": [
                f"graph_relation_projection_check_failed:{exc}"
            ],
        }
    return {
        "status": (
            "invalid"
            if failure_count
            else "current_with_inferred_candidates"
            if counts["candidate_count"]
            else "current"
        ),
        "relation_contract_version": (
            GRAPH_RELATION_CONTRACT_VERSION
        ),
        "edge_contribution_count": counts.pop("edge_count"),
        **counts,
        "failure_count": failure_count,
        "samples": samples,
        "claim_boundary": (
            "all graph relations remain navigation until raw or owner "
            "evidence is read through the matching claim-shape gate"
        ),
        "diagnostics": [],
    }


def graph_add_edge(edges: dict[str, dict[str, Any]], edge: dict[str, Any]) -> None:
    original_identity = tuple(
        str(edge.get(key) or "")
        for key in ("id", "source", "target")
    )
    edge = redact_derived_value(edge)
    redacted_identity = tuple(
        str(edge.get(key) or "")
        for key in ("id", "source", "target")
    )
    if redacted_identity != original_identity:
        return
    edge = graph_relation_contract_payload(edge)
    if not edge.get("navigation_admissible"):
        return
    source = str(edge.get("source") or "")
    target = str(edge.get("target") or "")
    edge_type = str(edge.get("type") or "")
    if not source or not target or not edge_type:
        return
    edge_id = str(edge.get("id") or graph_edge_id(source, target, edge_type))
    existing = edges.get(edge_id)
    if existing is None:
        edge["id"] = edge_id
        edge.setdefault("count", 1)
        edge.setdefault("evidence_refs", [])
        edges[edge_id] = edge
        return
    existing["count"] = int_value(existing.get("count"), 1) + int_value(edge.get("count"), 1)
    existing["evidence_refs"] = graph_merge_evidence_refs(existing.get("evidence_refs"), edge.get("evidence_refs"), limit=20)


class GraphSqliteAccumulator:
    """On-disk graph accumulator for large offline sidecar exports."""

    def __init__(self, aoa_root: Path, *, generated_at: str) -> None:
        self.aoa_root = aoa_root
        self.generated_at = generated_at
        paths = graph_paths(aoa_root)
        paths["root"].mkdir(parents=True, exist_ok=True)
        self.db_path = paths["root"] / f".{compact_stamp()}__graph-build__{os.getpid()}.sqlite3"
        if self.db_path.exists():
            self.db_path.unlink()
        self.conn = sqlite3.connect(str(self.db_path))
        self.conn.execute("PRAGMA journal_mode=OFF")
        self.conn.execute("PRAGMA synchronous=OFF")
        self.conn.execute("PRAGMA temp_store=MEMORY")
        self.conn.execute(
            """
            CREATE TABLE nodes (
                id TEXT PRIMARY KEY,
                node_type TEXT NOT NULL,
                payload_json TEXT NOT NULL,
                count INTEGER NOT NULL DEFAULT 1
            )
            """
        )
        self.conn.execute(
            """
            CREATE TABLE edges (
                id TEXT PRIMARY KEY,
                edge_type TEXT NOT NULL,
                payload_json TEXT NOT NULL,
                count INTEGER NOT NULL DEFAULT 1
            )
            """
        )
        self.conn.commit()
        self.pending = 0

    def _commit_maybe(self) -> None:
        self.pending += 1
        if self.pending >= 5000:
            self.conn.commit()
            self.pending = 0

    def add_node(self, node: dict[str, Any]) -> None:
        original_node_id = str(node.get("id") or "")
        node = redact_derived_value(node)
        node_id = str(node.get("id") or "")
        if node_id != original_node_id:
            return
        if not node_id:
            return
        payload = dict(node)
        payload["count"] = int_value(payload.get("count"), 1)
        if isinstance(payload.get("evidence_refs"), list):
            payload["evidence_refs"] = graph_merge_evidence_refs([], payload.get("evidence_refs"), limit=30)
        else:
            payload["evidence_refs"] = []
        node_type = str(payload.get("type") or "unknown")
        cursor = self.conn.execute(
            "INSERT OR IGNORE INTO nodes(id, node_type, payload_json, count) VALUES (?, ?, ?, ?)",
            (node_id, node_type, json.dumps(payload, ensure_ascii=False), int_value(payload.get("count"), 1)),
        )
        if cursor.rowcount == 0:
            self.conn.execute(
                "UPDATE nodes SET count = count + ? WHERE id = ?",
                (int_value(payload.get("count"), 1), node_id),
            )
        self._commit_maybe()

    def add_edge(self, edge: dict[str, Any]) -> None:
        original_identity = tuple(
            str(edge.get(key) or "")
            for key in ("id", "source", "target")
        )
        edge = redact_derived_value(edge)
        redacted_identity = tuple(
            str(edge.get(key) or "")
            for key in ("id", "source", "target")
        )
        if redacted_identity != original_identity:
            return
        edge = graph_relation_contract_payload(edge)
        if not edge.get("navigation_admissible"):
            return
        source = str(edge.get("source") or "")
        target = str(edge.get("target") or "")
        edge_type = str(edge.get("type") or "")
        if not source or not target or not edge_type:
            return
        edge_id = str(edge.get("id") or graph_edge_id(source, target, edge_type))
        payload = dict(edge)
        payload["id"] = edge_id
        payload["count"] = int_value(payload.get("count"), 1)
        if isinstance(payload.get("evidence_refs"), list):
            payload["evidence_refs"] = graph_merge_evidence_refs([], payload.get("evidence_refs"), limit=20)
        else:
            payload["evidence_refs"] = []
        cursor = self.conn.execute(
            "INSERT OR IGNORE INTO edges(id, edge_type, payload_json, count) VALUES (?, ?, ?, ?)",
            (edge_id, edge_type, json.dumps(payload, ensure_ascii=False), int_value(payload.get("count"), 1)),
        )
        if cursor.rowcount == 0:
            self.conn.execute(
                "UPDATE edges SET count = count + ? WHERE id = ?",
                (int_value(payload.get("count"), 1), edge_id),
            )
        self._commit_maybe()

    def _row_count(self, table: str) -> int:
        row = self.conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()
        return int(row[0] or 0) if row else 0

    def _type_counts(self, table: str, column: str) -> dict[str, int]:
        rows = self.conn.execute(f"SELECT {column}, COUNT(*) FROM {table} GROUP BY {column}").fetchall()
        return dict(sorted((str(row[0] or "unknown"), int(row[1] or 0)) for row in rows))

    def _iter_payloads(self, table: str) -> Iterable[dict[str, Any]]:
        for payload_json, count in self.conn.execute(f"SELECT payload_json, count FROM {table} ORDER BY id"):
            payload = json.loads(str(payload_json))
            if isinstance(payload, dict):
                payload["count"] = int_value(count, int_value(payload.get("count"), 1))
                yield payload

    def sample(self, table: str, *, limit: int = 20) -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        for payload in self._iter_payloads(table):
            rows.append(payload)
            if len(rows) >= limit:
                break
        return rows

    def write_sidecar(self, paths: dict[str, Path]) -> None:
        paths["root"].mkdir(parents=True, exist_ok=True)
        for table, path in (("nodes", paths["nodes"]), ("edges", paths["edges"])):
            tmp_path = path.with_name(f".{path.name}.{os.getpid()}.tmp")
            with tmp_path.open("w", encoding="utf-8") as handle:
                for payload in self._iter_payloads(table):
                    handle.write(json.dumps(payload, ensure_ascii=False) + "\n")
            tmp_path.replace(path)

    def index_payload(self, *, records: list[dict[str, Any]], diagnostics: list[str], source: str) -> dict[str, Any]:
        self.conn.commit()
        return graph_index_payload_from_counts(
            aoa_root=self.aoa_root,
            generated_at=self.generated_at,
            source=source,
            records=records,
            node_count=self._row_count("nodes"),
            edge_count=self._row_count("edges"),
            source_count=len(records),
            node_type_counts=self._type_counts("nodes", "node_type"),
            edge_type_counts=self._type_counts("edges", "edge_type"),
            diagnostics=diagnostics,
        )

    def close(self, *, cleanup: bool = True) -> None:
        self.conn.close()
        if cleanup:
            try:
                self.db_path.unlink()
            except OSError:
                pass


def graph_json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


class GraphMaintenanceBudgetExceeded(RuntimeError):
    """Raised to roll back one graph maintenance mutation pass cleanly."""


class GraphEntityRegistryDependencyChanged(RuntimeError):
    """Raised when graph mutation loses its pinned registry snapshot."""


def graph_assert_entity_registry_dependency_current(
    aoa_root: Path,
    expected_dependency_id: str,
) -> dict[str, Any]:
    current = graph_entity_registry_dependency_snapshot(
        aoa_root,
        ensure_current=False,
        allow_ephemeral=False,
    )
    current_dependency_id = str(
        current.get("dependency_id") or ""
    )
    if (
        current.get("status") != "current"
        or not expected_dependency_id
        or current_dependency_id != expected_dependency_id
    ):
        raise GraphEntityRegistryDependencyChanged(
            "graph_entity_registry_dependency_changed:"
            f"expected={expected_dependency_id or 'missing'}:"
            f"observed={current_dependency_id or 'missing'}:"
            f"status={current.get('status') or 'unknown'}"
        )
    return current


def graph_entity_registry_dependency_state(
    aoa_root: Path,
    observed_dependency_id: str,
) -> dict[str, Any]:
    current = graph_entity_registry_dependency_snapshot(
        aoa_root,
        ensure_current=False,
        allow_ephemeral=False,
    )
    expected_dependency_id = str(
        current.get("dependency_id") or ""
    )
    observed_dependency_id = str(observed_dependency_id or "")
    reasons = [
        str(reason)
        for reason in (
            current.get("reasons")
            if isinstance(current.get("reasons"), list)
            else []
        )
        if reason
    ]
    if not observed_dependency_id:
        reasons.append("graph_entity_registry_dependency_missing")
    elif (
        expected_dependency_id
        and observed_dependency_id != expected_dependency_id
    ):
        reasons.append("graph_entity_registry_dependency_mismatch")
    if not current.get("current") and not reasons:
        reasons.append("entity_registry_dependency_not_current")
    compatible = bool(
        current.get("current")
        and observed_dependency_id
        and observed_dependency_id == expected_dependency_id
    )
    return {
        "status": "current" if compatible else "stale",
        "compatible": compatible,
        "expected_dependency_id": expected_dependency_id,
        "observed_dependency_id": observed_dependency_id,
        "current_dependency": {
            key: current.get(key)
            for key in (
                "schema_version",
                "artifact_type",
                "status",
                "dependency_id",
                "identity",
                "snapshot_ref",
                "generation_compatible",
                "source_fingerprint_verified",
                "semantic_digest_verified",
                "runtime_overlay_required",
                "reasons",
                "truth_status",
            )
        },
        "reasons": list(dict.fromkeys(reasons)),
        "truth_status": (
            "graph_dependency_compatibility_against_current_"
            "persisted_entity_registry"
        ),
    }


def graph_check_budget(budget_deadline: float | None) -> None:
    if budget_deadline is not None and time.monotonic() >= budget_deadline:
        raise GraphMaintenanceBudgetExceeded("graph_maintenance_budget_exhausted")


def graph_phase_timer_start() -> float:
    return time.perf_counter()


def graph_phase_elapsed_ms(started: float) -> int:
    return max(0, int((time.perf_counter() - started) * 1000))


def graph_add_phase_timing(timings: dict[str, int], key: str, started: float) -> None:
    timings[key] = int_value(timings.get(key)) + graph_phase_elapsed_ms(started)


def graph_aggregate_evidence_limit(table_or_kind: str) -> int:
    value = str(table_or_kind or "")
    return 20 if value in {"edge", "edges", "edge_contribs"} else 30


def graph_compact_aggregate_payload(payload: dict[str, Any], *, kind: str) -> dict[str, Any]:
    compact = redact_derived_value(payload)
    compact.pop("refs", None)
    compact.pop("contrib_payload_mode", None)
    if isinstance(compact.get("route_signals"), list):
        compact["route_signal_count"] = len(compact["route_signals"])
        compact.pop("route_signals", None)
    refs = compact.pop("evidence_refs", None)
    if isinstance(refs, list):
        compact["evidence_ref_count"] = max(int_value(compact.get("evidence_ref_count"), 0), len(refs))
    compact["evidence_refs_compacted"] = True
    compact["aggregate_payload_mode"] = GRAPH_STORE_AGGREGATE_PAYLOAD_MODE
    compact["evidence_hydration_source"] = "node_contribs" if kind == "node" else "edge_contribs"
    return compact


def graph_payload_needs_evidence_hydration(payload: dict[str, Any]) -> bool:
    return (
        bool(payload.get("evidence_refs_compacted"))
        or str(payload.get("aggregate_payload_mode") or "") == GRAPH_STORE_AGGREGATE_PAYLOAD_MODE
    ) and not payload.get("evidence_refs")


def graph_hydrate_store_payload_evidence(
    conn: sqlite3.Connection,
    table: str,
    payloads: list[dict[str, Any]],
    *,
    row_scan_limit: int = 600,
) -> list[dict[str, Any]]:
    if table not in {"nodes", "edges"}:
        return payloads
    contrib_table = "node_contribs" if table == "nodes" else "edge_contribs"
    id_column = "node_id" if table == "nodes" else "edge_id"
    evidence_limit = graph_aggregate_evidence_limit(table)
    max_rows = max(evidence_limit, int_value(row_scan_limit, 600))
    for payload in payloads:
        if not isinstance(payload, dict) or not graph_payload_needs_evidence_hydration(payload):
            continue
        item_id = str(payload.get("id") or "")
        if not item_id:
            continue
        evidence_refs: list[Any] = []
        scanned_rows = 0
        try:
            cursor = conn.execute(
                f"SELECT payload_json FROM {contrib_table} WHERE {id_column} = ? ORDER BY source_key LIMIT ?",
                (item_id, max_rows),
            )
            for row in cursor:
                scanned_rows += 1
                try:
                    contrib = json.loads(str(row["payload_json"]))
                except (KeyError, TypeError, json.JSONDecodeError):
                    continue
                if isinstance(contrib, dict):
                    evidence_refs = graph_merge_evidence_refs(evidence_refs, contrib.get("evidence_refs"), limit=evidence_limit)
                if len(evidence_refs) >= evidence_limit:
                    break
        except sqlite3.Error:
            continue
        if evidence_refs:
            payload["evidence_refs"] = evidence_refs
            payload["evidence_refs_hydrated"] = True
            payload["evidence_hydration_row_count"] = scanned_rows
            payload["evidence_ref_count"] = max(int_value(payload.get("evidence_ref_count"), 0), len(evidence_refs))
    return payloads


def graph_source_key(source_type: str, session_id: str, segment_id: str = "") -> str:
    if source_type == "segment":
        return f"segment:{session_id}:{segment_id}"
    return f"session:{session_id}"


def graph_source_metadata(
    *,
    source_type: str,
    session_id: str,
    session_label: str,
    segment_id: str = "",
    source_paths: list[Path],
    identity: dict[str, Any] | None = None,
    source_hash_cache_entries: dict[str, dict[str, Any]] | None = None,
    source_hash_cache_updates: dict[str, dict[str, Any]] | None = None,
    source_hash_stats: dict[str, int] | None = None,
    source_hash_mode: str = "cached",
) -> dict[str, Any]:
    semantic_path_items: list[dict[str, Any]] = []
    diagnostics: list[str] = []
    max_mtime = 0.0
    try:
        logical_root = Path(
            os.path.commonpath(
                [str(path.parent) for path in source_paths]
            )
        )
    except (ValueError, OSError):
        logical_root = source_paths[0].parent if source_paths else Path(".")
    for ordinal, path in enumerate(source_paths):
        item = graph_source_hash_stat_item(
            path,
            semantic_root=logical_root,
            cache_entries=source_hash_cache_entries,
            cache_updates=source_hash_cache_updates,
            stats=source_hash_stats,
            hash_mode=source_hash_mode,
        )
        exists = bool(item.get("exists"))
        max_mtime = max(max_mtime, float(item["mtime"] or 0.0))
        if not exists:
            diagnostics.append(f"missing_graph_source_path:{path}")
        semantic_path_items.append(
            {
                "ordinal": ordinal,
                "logical_path": projection_logical_path(
                    path,
                    logical_root=logical_root,
                    ordinal=ordinal,
                ),
                "exists": exists,
                "semantic_sha256": str(
                    item.get("semantic_sha256") or ""
                ),
                "semantic_fingerprint_mode": str(
                    item.get("semantic_fingerprint_mode") or ""
                ),
            }
        )
    semantic_identity = projection_semantic_digest_value(
        identity or {},
        volatile_keys=(
            SESSION_PROJECTION_SEMANTIC_DIGEST_VOLATILE_KEYS
        ),
        logical_root=logical_root,
    )
    identity_payload = {
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "graph_store_schema_version": GRAPH_STORE_SCHEMA_VERSION,
        "graph_store_contrib_payload_mode": GRAPH_STORE_CONTRIB_PAYLOAD_MODE,
        "graph_event_route_signal_edge_policy": GRAPH_EVENT_ROUTE_SIGNAL_EDGE_POLICY,
        "graph_event_relationship_edge_policy": GRAPH_EVENT_RELATIONSHIP_EDGE_POLICY,
        "graph_relation_contract_version": GRAPH_RELATION_CONTRACT_VERSION,
        "route_signal_classifier_version": ROUTE_SIGNAL_CLASSIFIER_VERSION,
        "source_type": source_type,
        "session_id": session_id,
        "session_label": session_label,
        "segment_id": segment_id,
        "source_fingerprint_mode": GRAPH_SOURCE_FINGERPRINT_MODE,
        "paths": semantic_path_items,
        "identity": semantic_identity,
    }
    return {
        "source_key": graph_source_key(source_type, session_id, segment_id),
        "source_type": source_type,
        "session_id": session_id,
        "session_label": session_label,
        "segment_id": segment_id,
        "source_paths": [str(path) for path in source_paths],
        "source_path": str(source_paths[-1]) if source_paths else "",
        "source_sha": hashlib.sha256(graph_json(identity_payload).encode("utf-8")).hexdigest(),
        "source_mtime": max_mtime,
        "source_fingerprint_mode": GRAPH_SOURCE_FINGERPRINT_MODE,
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "graph_store_schema_version": GRAPH_STORE_SCHEMA_VERSION,
        "graph_event_route_signal_edge_policy": GRAPH_EVENT_ROUTE_SIGNAL_EDGE_POLICY,
        "route_signal_classifier_version": ROUTE_SIGNAL_CLASSIFIER_VERSION,
        "status": "blocked" if diagnostics else "current",
        "diagnostics": diagnostics,
    }


def graph_rows_from_maps(nodes: dict[str, dict[str, Any]], edges: dict[str, dict[str, Any]]) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    return (
        sorted(nodes.values(), key=lambda item: str(item.get("id") or "")),
        sorted(edges.values(), key=lambda item: str(item.get("id") or "")),
    )


def graph_lineage_agent_identity(
    manifest: dict[str, Any],
    session_index: dict[str, Any],
) -> dict[str, Any]:
    lineage = (
        manifest.get("lineage")
        if isinstance(manifest.get("lineage"), dict)
        else session_index.get("lineage")
        if isinstance(session_index.get("lineage"), dict)
        else {}
    )
    agent = (
        lineage.get("agent")
        if isinstance(lineage.get("agent"), dict)
        else {}
    )
    agent_path = str(agent.get("path") or "").strip()
    if not agent_path:
        return {}
    evidence = (
        lineage.get("evidence")
        if isinstance(lineage.get("evidence"), dict)
        else {}
    )
    return {
        "path": agent_path,
        "nickname": str(agent.get("nickname") or ""),
        "role": str(agent.get("role") or ""),
        "depth": int_value(agent.get("depth")),
        "relationship": str(
            lineage.get("relationship") or ""
        ),
        "parent_session_id": str(
            lineage.get("parent_session_id") or ""
        ),
        "raw_ref": str(evidence.get("raw_ref") or ""),
        "event_id": str(evidence.get("event_id") or ""),
        "source_type": str(
            evidence.get("source_type") or ""
        ),
    }


def graph_lineage_agent_evidence_refs(
    *,
    manifest: dict[str, Any],
    session_id: str,
    session_refs: dict[str, Any],
    identity: dict[str, Any],
) -> list[dict[str, Any]]:
    refs = dict(session_refs)
    raw_ref = str(identity.get("raw_ref") or "")
    if raw_ref:
        refs["raw"] = raw_ref
        raw_line = int_value(line_from_raw_ref(raw_ref))
        for segment in (
            manifest.get("segments")
            if isinstance(manifest.get("segments"), list)
            else []
        ):
            if not isinstance(segment, dict):
                continue
            source_range = (
                segment.get("source_range")
                if isinstance(
                    segment.get("source_range"),
                    dict,
                )
                else {}
            )
            if not (
                int_value(source_range.get("from_line"))
                <= raw_line
                <= int_value(source_range.get("to_line"))
            ):
                continue
            if segment.get("markdown"):
                refs["segment"] = str(
                    segment.get("markdown")
                )
            if segment.get("index"):
                refs["segment_index"] = str(
                    segment.get("index")
                )
            raw_block = (
                segment.get("raw_block")
                if isinstance(
                    segment.get("raw_block"),
                    dict,
                )
                else {}
            )
            if raw_block.get("path"):
                refs["raw_block"] = str(
                    raw_block.get("path")
                )
            break
    return [
        {
            "session_id": session_id,
            "event_id": str(identity.get("event_id") or ""),
            "refs": refs,
        }
    ]


def graph_contributions_for_record(
    record: dict[str, Any],
    *,
    source_keys: set[str] | None = None,
    entity_registry_index: (
        dict[tuple[str, str], dict[str, Any]] | None
    ) = None,
) -> tuple[list[dict[str, Any]], list[str]]:
    diagnostics: list[str] = []
    contributions: list[dict[str, Any]] = []
    # A session contribution and every segment contribution share the same
    # manifest and session index.  Reuse their stat-qualified fingerprints
    # only inside this one record build; a later record, scan, or rebuild must
    # establish its own source identity.
    source_hash_cache: dict[str, dict[str, Any]] = {}
    source_hash_stats: dict[str, int] = {}
    source_filter = {str(item) for item in source_keys or set() if str(item)}
    include_all_sources = not source_filter
    session_dir = session_dir_from_record(record)
    manifest_path = session_dir / "session.manifest.json"
    session_index_path = session_dir / SESSION_INDEX_JSON
    manifest = read_json(manifest_path, {})
    session_index = read_json(session_index_path, {})
    if not isinstance(manifest, dict) or not manifest:
        return [], [f"missing session manifest: {session_dir}"]
    if not isinstance(session_index, dict):
        session_index = {}
    display = manifest.get("display") if isinstance(manifest.get("display"), dict) else {}
    session_id = str(manifest.get("session_id") or record.get("session_id") or session_dir.name)
    session_label = str(manifest.get("session_label") or record.get("session_label") or display.get("label") or session_dir.name)
    session_title = str(manifest.get("session_title") or record.get("session_title") or display.get("title") or session_label)
    session_node_id = f"session:{session_id}"
    session_refs = {
        "session": str(manifest_path),
        "session_index": str(session_index_path),
        "session_md": str(session_dir / SESSION_INDEX_MARKDOWN),
    }
    aoa_root_for_registry = (
        session_dir.parent.parent
        if session_dir.parent.name == "sessions"
        else session_dir.parent
    )
    (
        expected_session_publish_id,
        expected_session_raw_sha256,
    ) = session_manifest_projection_expectations(manifest)
    session_generation_reasons = (
        generated_session_index_stale_reasons_for_session(
            session_dir,
            session_index,
        )
        if session_index
        else ["missing_session_index"]
    )
    if session_generation_reasons:
        diagnostic_reasons = ",".join(
            sorted(set(session_generation_reasons))
        )
        diagnostic = (
            "graph_source_generation_incompatible:"
            f"{session_id}:{diagnostic_reasons}:"
            "recovery=aoa-session-memory --root "
            f"{aoa_root_for_registry} reindex-sessions {session_id}"
        )
        blocked_candidates, _candidate_diagnostics = (
            graph_source_candidates_for_record(
                record,
                source_key_filters=source_filter,
            )
        )
        blocked_contributions: list[dict[str, Any]] = []
        for candidate in blocked_candidates:
            source = dict(candidate)
            source["status"] = "blocked"
            source["diagnostics"] = [diagnostic]
            blocked_contributions.append(
                {
                    "source": source,
                    "nodes": [],
                    "edges": [],
                }
            )
        return blocked_contributions, []

    session_nodes: dict[str, dict[str, Any]] = {}
    session_edges: dict[str, dict[str, Any]] = {}

    def add_session_node(node: dict[str, Any]) -> None:
        graph_add_node(session_nodes, node)

    def add_session_edge(edge: dict[str, Any]) -> None:
        graph_add_edge(session_edges, edge)

    registry_index = (
        entity_registry_index
        if entity_registry_index is not None
        else cached_entity_registry_entry_index(
            aoa_root_for_registry
        )
    )

    def registry_entry_for_route(layer: str, key: str) -> dict[str, Any] | None:
        route_layer = route_key_slug(layer, fallback="")
        route_key = route_key_slug(key, fallback="", max_chars=120)
        kind = "mcp_tool" if route_layer == "tool" and entity_registry_tool_key_is_mcp_tool(route_key) else ENTITY_REGISTRY_KIND_BY_ROUTE_LAYER.get(route_layer, route_layer)
        return registry_index.get((kind, route_key))

    def add_registry_route_links(
        *,
        add_node: Callable[[dict[str, Any]], None],
        add_edge: Callable[[dict[str, Any]], None],
        owner_node_id: str,
        route_node_id: str,
        layer: str,
        key: str,
        evidence_refs: list[dict[str, Any]],
        edge_type: str,
        count: int = 1,
        extra: dict[str, Any] | None = None,
    ) -> None:
        entry = registry_entry_for_route(layer, key)
        if not entry:
            return
        registry_node_id = f"entity_registry:{entry.get('entity_id')}"
        canonicalization = (
            entry.get("canonicalization")
            if isinstance(entry.get("canonicalization"), dict)
            else {}
        )
        add_node(
            {
                "id": registry_node_id,
                "type": "entity_registry",
                "label": f"{entry.get('kind')}:{entry.get('canonical_key')}",
                "entity_id": entry.get("entity_id"),
                "entity_kind": entry.get("kind"),
                "canonical_key": entry.get("canonical_key"),
                "status": entry.get("status"),
                "route_layer": entry.get("route_layer"),
                "route_signal": entry.get("route_signal"),
                "source_surface": entry.get("source_surface"),
                "owner": entry.get("owner"),
                "canonicalization": {
                    "schema_version": canonicalization.get(
                        "schema_version"
                    ),
                    "status": canonicalization.get("status"),
                    "identity_claim_allowed": canonicalization.get(
                        "identity_claim_allowed"
                    ),
                    "collision_preserved": canonicalization.get(
                        "collision_preserved"
                    ),
                    "candidate_count": canonicalization.get(
                        "candidate_count"
                    ),
                    "active_candidate_count": canonicalization.get(
                        "active_candidate_count"
                    ),
                    "selected_candidate_id": canonicalization.get(
                        "selected_candidate_id"
                    ),
                },
                "identity_candidate_ids": canonicalization.get(
                    "candidate_ids",
                    [],
                ),
                "refs": {"registry": str(aoa_root_for_registry / ENTITY_REGISTRY_PATH)},
                "evidence_refs": evidence_refs,
            }
        )
        edge_payload = {
            "source": owner_node_id,
            "target": registry_node_id,
            "type": edge_type,
            "session_id": session_id,
            "route_signal": route_signal_token(route_key_slug(layer, fallback="route_signal"), route_key_slug(key, fallback="generic")),
            "count": int_value(count, 1),
            "evidence_refs": evidence_refs,
        }
        if extra:
            edge_payload.update(extra)
        add_edge(edge_payload)
        add_edge(
            {
                "source": registry_node_id,
                "target": route_node_id,
                "type": "registry_entity_has_route_signal",
                "session_id": session_id,
                "route_signal": route_signal_token(route_key_slug(layer, fallback="route_signal"), route_key_slug(key, fallback="generic")),
                "evidence_refs": evidence_refs,
            }
        )

    work_context = manifest.get("work_context") if isinstance(manifest.get("work_context"), dict) else session_index.get("work_context")
    lineage_agent_identity = graph_lineage_agent_identity(
        manifest,
        session_index,
    )
    route_signal_counts = session_index.get("route_signal_counts") if isinstance(session_index.get("route_signal_counts"), dict) else {}
    session_source_key = graph_source_key("session", session_id)
    if include_all_sources or session_source_key in source_filter:
        add_session_node(
            {
                "id": session_node_id,
                "type": "session",
                "label": session_label,
                "title": session_title,
                "session_id": session_id,
                "session_label": session_label,
                "work_context": work_context,
                "refs": session_refs,
                "evidence_refs": [{"session_id": session_id, "refs": session_refs}],
            }
        )

        if lineage_agent_identity:
            agent_path = str(
                lineage_agent_identity.get("path") or ""
            )
            agent_key = route_key_slug(
                agent_path,
                fallback="agent",
                max_chars=120,
            )
            agent_node_id = graph_route_node_id(
                "agent",
                agent_path,
            )
            agent_evidence_refs = (
                graph_lineage_agent_evidence_refs(
                    manifest=manifest,
                    session_id=session_id,
                    session_refs=session_refs,
                    identity=lineage_agent_identity,
                )
            )
            add_session_node(
                {
                    "id": agent_node_id,
                    "type": graph_route_node_type(
                        "agent",
                        agent_key,
                    ),
                    "label": agent_path,
                    "route_layer": "agent",
                    "route_key": agent_key,
                    "route_signal": route_signal_token(
                        "agent",
                        agent_key,
                    ),
                    "agent_path": agent_path,
                    "agent_nickname": (
                        lineage_agent_identity.get(
                            "nickname"
                        )
                    ),
                    "agent_role": (
                        lineage_agent_identity.get("role")
                    ),
                    "agent_depth": (
                        lineage_agent_identity.get("depth")
                    ),
                    "parent_session_id": (
                        lineage_agent_identity.get(
                            "parent_session_id"
                        )
                    ),
                    "identity_scope": (
                        "observed_session_lineage_agent_path"
                    ),
                    "canonical_person_identity_claim": False,
                    "evidence_refs": agent_evidence_refs,
                }
            )
            add_session_edge(
                {
                    "source": session_node_id,
                    "target": agent_node_id,
                    "type": "session_has_agent_identity",
                    "session_id": session_id,
                    "agent_path": agent_path,
                    "evidence_refs": agent_evidence_refs,
                }
            )

        if isinstance(work_context, dict) and (work_context.get("work_root") or work_context.get("work_name")):
            work_node_id = graph_work_context_node_id(str(work_context.get("work_root") or ""), str(work_context.get("work_name") or ""))
            work_projection_fields = graph_work_context_projection_fields(
                work_context
            )
            add_session_node(
                {
                    "id": work_node_id,
                    "type": "work_context",
                    "label": work_context.get("work_name") or work_context.get("work_root"),
                    "work_root": work_context.get("work_root"),
                    "work_family": work_context.get("work_family"),
                    "status": work_context.get("status"),
                    "confidence": work_context.get("confidence"),
                    **work_projection_fields,
                    "evidence_refs": [{"session_id": session_id, "refs": session_refs}],
                }
            )
            add_session_edge(
                {
                    "source": session_node_id,
                    "target": work_node_id,
                    "type": "has_work_context",
                    "session_id": session_id,
                    **work_projection_fields,
                    "evidence_refs": [{"session_id": session_id, "refs": session_refs}],
                }
            )

        for layer, layer_counts in sorted(route_signal_counts.items()):
            if not isinstance(layer_counts, dict):
                continue
            for key, count in sorted(layer_counts.items()):
                route_node_id = graph_route_node_id(str(layer), str(key))
                route_signal_value = route_signal_token(route_key_slug(layer, fallback="route_signal"), route_key_slug(key, fallback="generic"))
                add_session_node(
                    {
                        "id": route_node_id,
                        "type": graph_route_node_type(str(layer), str(key)),
                        "label": route_signal_value,
                        "route_layer": route_key_slug(layer, fallback="route_signal"),
                        "route_key": route_key_slug(key, fallback="generic"),
                        "route_signal": route_signal_value,
                        "axis": ROUTE_SIGNAL_LAYER_TO_AXIS.get(route_key_slug(layer, fallback="route_signal"), ""),
                        "evidence_refs": [{"session_id": session_id, "refs": session_refs}],
                    }
                )
                add_session_edge(
                    {
                        "source": session_node_id,
                        "target": route_node_id,
                        "type": "session_has_route_signal",
                        "session_id": session_id,
                        "count": int_value(count, 1),
                        "evidence_refs": [{"session_id": session_id, "refs": session_refs}],
                    }
                )
                add_registry_route_links(
                    add_node=add_session_node,
                    add_edge=add_session_edge,
                    owner_node_id=session_node_id,
                    route_node_id=route_node_id,
                    layer=str(layer),
                    key=str(key),
                    evidence_refs=[{"session_id": session_id, "refs": session_refs}],
                    edge_type="session_has_registered_entity",
                    count=int_value(count, 1),
                )

        task_episodes = session_index_task_episode_components(
            session_dir,
            session_index,
        )
        for episode in task_episodes:
            if not isinstance(episode, dict):
                continue
            episode_id = str(episode.get("episode_id") or "")
            if not episode_id:
                continue
            task_node_id = f"task_episode:{session_id}:{episode_id}"
            add_session_node(
                {
                    "id": task_node_id,
                    "type": "task_episode",
                    "label": f"{session_label} {episode_id}",
                    "session_id": session_id,
                    "session_label": session_label,
                    "task_episode_id": episode_id,
                    "status": episode.get("status"),
                    "event_range": episode.get("event_range"),
                    "evidence_refs": [{"session_id": session_id, "refs": session_refs}],
                }
            )
            add_session_edge(
                {
                    "source": session_node_id,
                    "target": task_node_id,
                    "type": "has_task_episode",
                    "session_id": session_id,
                    "task_episode_id": episode_id,
                    "evidence_refs": [{"session_id": session_id, "refs": session_refs}],
                }
            )

        goal_lifecycles = session_index.get("goal_lifecycles") if isinstance(session_index.get("goal_lifecycles"), list) else []
        for lifecycle in goal_lifecycles:
            if not isinstance(lifecycle, dict):
                continue
            goal_id = str(lifecycle.get("goal_id") or "")
            if not goal_id:
                continue
            goal_node_id = graph_goal_lifecycle_node_id(session_id, goal_id)
            evidence_refs = [{"session_id": session_id, "refs": session_refs}]
            add_session_node(
                {
                    "id": goal_node_id,
                    "type": "goal_lifecycle",
                    "label": f"{goal_id} {lifecycle.get('status') or ''}".strip(),
                    "title": lifecycle.get("objective"),
                    "session_id": session_id,
                    "session_label": session_label,
                    "goal_id": goal_id,
                    "goal_instance_id": lifecycle.get("goal_instance_id"),
                    "status": lifecycle.get("status"),
                    "objective": lifecycle.get("objective"),
                    "event_count": lifecycle.get("event_count"),
                    "event_kinds": lifecycle.get("event_kinds"),
                    "ambiguity_flags": lifecycle.get("ambiguity_flags"),
                    "refs": {
                        "session": session_refs.get("session"),
                        "session_index": session_refs.get("session_index"),
                        "first": lifecycle.get("first_ref"),
                        "last": lifecycle.get("last_ref"),
                    },
                    "evidence_refs": evidence_refs,
                }
            )
            add_session_edge(
                {
                    "source": session_node_id,
                    "target": goal_node_id,
                    "type": "has_goal_lifecycle",
                    "session_id": session_id,
                    "goal_id": goal_id,
                    "evidence_refs": evidence_refs,
                }
            )
            for kind in lifecycle.get("event_kinds", []) if isinstance(lifecycle.get("event_kinds"), list) else []:
                route_node_id = graph_route_node_id("goal", str(kind))
                add_session_edge(
                    {
                        "source": goal_node_id,
                        "target": route_node_id,
                        "type": "goal_lifecycle_has_route_signal",
                        "session_id": session_id,
                        "goal_id": goal_id,
                        "route_signal": route_signal_token("goal", str(kind)),
                        "evidence_refs": evidence_refs,
                    }
                )
            for episode_id in lifecycle.get("task_episode_ids", []) if isinstance(lifecycle.get("task_episode_ids"), list) else []:
                if not episode_id:
                    continue
                add_session_edge(
                    {
                        "source": goal_node_id,
                        "target": f"task_episode:{session_id}:{episode_id}",
                        "type": "goal_lifecycle_in_task_episode",
                        "session_id": session_id,
                        "goal_id": goal_id,
                        "task_episode_id": episode_id,
                        "evidence_refs": evidence_refs,
                    }
                )
            for goal_event in lifecycle.get("events", []) if isinstance(lifecycle.get("events"), list) else []:
                if not isinstance(goal_event, dict):
                    continue
                refs = goal_event.get("refs") if isinstance(goal_event.get("refs"), dict) else {}
                event_node_id = str(refs.get("graph_event_node") or "")
                if not event_node_id:
                    continue
                add_session_edge(
                    {
                        "source": goal_node_id,
                        "target": event_node_id,
                        "type": "goal_lifecycle_has_event",
                        "session_id": session_id,
                        "goal_id": goal_id,
                        "event_id": goal_event.get("event_id"),
                        "evidence_refs": [{"session_id": session_id, "event_id": goal_event.get("event_id"), "refs": refs}],
                    }
                )

        node_rows, edge_rows = graph_rows_from_maps(session_nodes, session_edges)
        contributions.append(
            {
                "source": graph_source_metadata(
                    source_type="session",
                    session_id=session_id,
                    session_label=session_label,
                    source_paths=[manifest_path, session_index_path],
                    identity={
                        "session_title": session_title,
                        "work_context": work_context if isinstance(work_context, dict) else {},
                        "route_signal_counts": route_signal_counts,
                        "lineage_agent_identity": (
                            lineage_agent_identity
                        ),
                        "goal_lifecycle_counts": session_index.get("goal_lifecycle_counts"),
                        "session_index_generation_id": (
                            session_index.get("generation_id")
                        ),
                    },
                    source_hash_cache_entries=source_hash_cache,
                    source_hash_cache_updates=source_hash_cache,
                    source_hash_stats=source_hash_stats,
                ),
                "nodes": node_rows,
                "edges": edge_rows,
            }
        )

    segments = manifest.get("segments") if isinstance(manifest.get("segments"), list) else session_index.get("segments")
    for segment in segments if isinstance(segments, list) else []:
        if not isinstance(segment, dict):
            continue
        segment_id = str(segment.get("segment_id") or "")
        if not segment_id:
            continue
        segment_source_key = graph_source_key("segment", session_id, segment_id)
        if not include_all_sources and segment_source_key not in source_filter:
            continue
        segment_nodes: dict[str, dict[str, Any]] = {}
        segment_edges: dict[str, dict[str, Any]] = {}
        segment_route_signal_counts: Counter[tuple[str, str, str]] = Counter()
        segment_route_signal_evidence_refs: dict[tuple[str, str, str], list[Any]] = defaultdict(list)

        def add_segment_node(node: dict[str, Any]) -> None:
            graph_add_node(segment_nodes, node)

        def add_segment_edge(edge: dict[str, Any]) -> None:
            graph_add_edge(segment_edges, edge)

        segment_node_id = f"segment:{session_id}:{segment_id}"
        segment_index_path = graph_path_from_ref(segment.get("index"), base=session_dir) if segment.get("index") else session_dir / "segments" / f"{segment_id}.index.json"
        segment_refs = {
            "session": str(manifest_path),
            "session_index": str(session_index_path),
            "segment": str(segment.get("markdown") or ""),
            "segment_index": str(segment_index_path),
        }
        add_segment_node(
            {
                "id": segment_node_id,
                "type": "segment",
                "label": f"{session_label} segment {segment_id}",
                "session_id": session_id,
                "session_label": session_label,
                "segment_id": segment_id,
                "role": segment.get("role"),
                "source_range": segment.get("source_range"),
                "refs": segment_refs,
                "evidence_refs": [{"session_id": session_id, "segment_id": segment_id, "refs": segment_refs}],
            }
        )
        add_segment_edge(
            {
                "source": session_node_id,
                "target": segment_node_id,
                "type": "has_segment",
                "session_id": session_id,
                "segment_id": segment_id,
                "evidence_refs": [{"session_id": session_id, "segment_id": segment_id, "refs": segment_refs}],
            }
        )
        segment_index = read_json(segment_index_path, {})
        if not isinstance(segment_index, dict):
            diagnostics.append(f"missing segment index: {segment_index_path}")
            segment_index = {}
        segment_generation_reasons = (
            generated_segment_index_stale_reasons(
                segment_index,
                expected_publish_id=expected_session_publish_id,
                expected_raw_sha256=expected_session_raw_sha256,
            )
            if segment_index
            else ["missing_segment_index"]
        )
        if segment_generation_reasons:
            diagnostic = (
                "graph_segment_source_generation_incompatible:"
                f"{session_id}:{segment_id}:"
                f"{','.join(sorted(set(segment_generation_reasons)))}:"
                "recovery=aoa-session-memory --root "
                f"{aoa_root_for_registry} reindex-sessions {session_id}"
            )
            blocked_candidates, _candidate_diagnostics = (
                graph_source_candidates_for_record(
                    record,
                    source_key_filters={segment_source_key},
                )
            )
            for candidate in blocked_candidates:
                source = dict(candidate)
                source["status"] = "blocked"
                source["diagnostics"] = [diagnostic]
                contributions.append(
                    {
                        "source": source,
                        "nodes": [],
                        "edges": [],
                    }
                )
            continue
        segment_events = [
            item
            for item in (
                segment_index.get("events")
                if isinstance(segment_index.get("events"), list)
                else []
            )
            if isinstance(item, dict)
        ]
        segment_events_by_id = {
            str(item.get("event_id") or ""): item
            for item in segment_events
            if str(item.get("event_id") or "")
        }
        segment_event_refs_by_id = {
            event_id: graph_event_refs(
                session_dir=session_dir,
                segment=segment,
                segment_index_path=segment_index_path,
                event=item,
            )
            for event_id, item in segment_events_by_id.items()
        }
        for event in segment_events:
            if not isinstance(event, dict):
                continue
            event_id = str(event.get("event_id") or "")
            if not event_id:
                continue
            event_node_id = f"event:{session_id}:{segment_id}:{event_id}"
            event_refs = graph_event_refs(session_dir=session_dir, segment=segment, segment_index_path=segment_index_path, event=event)
            facets = event.get("facets") if isinstance(event.get("facets"), dict) else {}
            conversation_act = facets.get("conversation_act") if isinstance(facets.get("conversation_act"), dict) else {}
            session_act = facets.get("session_act") if isinstance(facets.get("session_act"), dict) else {}
            route_signals = graph_route_signals_from_event(event)
            event_route_signal_edges = (
                graph_select_event_route_signal_identities(
                    route_signals,
                    registry_entry_for_route=registry_entry_for_route,
                    require_event_materialized=True,
                    limit=GRAPH_EVENT_ROUTE_SIGNAL_EDGE_LIMIT,
                )
                if graph_should_materialize_high_fanout_event_edge("event_has_route_signal")
                else []
            )
            event_registered_entity_edges = (
                graph_select_event_route_signal_identities(
                    route_signals,
                    registry_entry_for_route=registry_entry_for_route,
                    require_registered=True,
                    limit=GRAPH_EVENT_REGISTERED_ENTITY_EDGE_LIMIT,
                )
                if graph_should_materialize_high_fanout_event_edge(GRAPH_ENTITY_USAGE_REPLACEMENT_EDGE_TYPE)
                else []
            )
            event_materializable_route_signal_count = sum(
                1 for signal in route_signals if graph_should_materialize_event_route_signal_edge(signal["layer"], signal["key"])
            )
            event_registered_route_signal_count = sum(
                1 for signal in route_signals if registry_entry_for_route(signal["layer"], signal["key"]) is not None
            )
            event_relationship_edges: list[
                tuple[str, dict[str, Any], dict[str, Any]]
            ] = []
            event_relationship_omitted_edge_count = 0
            event_relationship_rejected_correlation_count = 0
            for relation in event.get("relationships", []) if isinstance(event.get("relationships"), list) else []:
                if not isinstance(relation, dict) or not relation.get("event_id"):
                    continue
                rel_type = route_key_slug(relation.get("rel"), fallback="related_to")
                target_event = segment_events_by_id.get(
                    str(relation.get("event_id") or "")
                )
                relation_contract = GRAPH_RELATION_CONTRACTS.get(rel_type)
                if (
                    relation_contract
                    and relation_contract.get("requires_correlation")
                    and (
                        not isinstance(target_event, dict)
                        or not str(relation.get("correlation_id") or "")
                        or str(relation.get("correlation_id") or "")
                        != str(event.get("correlation_id") or "")
                        or str(relation.get("correlation_id") or "")
                        != str(target_event.get("correlation_id") or "")
                    )
                ):
                    event_relationship_rejected_correlation_count += 1
                    continue
                if graph_should_materialize_event_relationship_edge(rel_type):
                    event_relationship_edges.append(
                        (rel_type, relation, target_event or {})
                    )
                else:
                    event_relationship_omitted_edge_count += 1
            add_segment_node(
                {
                    "id": event_node_id,
                    "type": "event",
                    "label": str(event.get("title") or event.get("type") or event_id),
                    "title": event.get("title"),
                    "session_id": session_id,
                    "session_label": session_label,
                    "segment_id": segment_id,
                    "event_id": event_id,
                    "event_type": event.get("type"),
                    "family": event.get("family"),
                    "phase": event.get("phase"),
                    "actor": event.get("actor"),
                    "action": event.get("action"),
                    "object": event.get("object"),
                    "outcome": event.get("outcome"),
                    "conversation_act": conversation_act.get("kind"),
                    "session_act": session_act.get("kind"),
                    "timestamp": event.get("timestamp"),
                    "line": event.get("line"),
                    "route_signals": route_signals,
                    "route_signal_count": len(route_signals),
                    "route_signal_edge_count": len(event_route_signal_edges),
                    "route_signal_omitted_edge_count": max(0, event_materializable_route_signal_count - len(event_route_signal_edges)),
                    "registered_entity_edge_count": len(event_registered_entity_edges),
                    "registered_entity_omitted_edge_count": max(0, event_registered_route_signal_count - len(event_registered_entity_edges)),
                    "relationship_edge_policy": GRAPH_EVENT_RELATIONSHIP_EDGE_POLICY,
                    "relationship_count": len(event_relationship_edges) + event_relationship_omitted_edge_count,
                    "relationship_edge_count": len(event_relationship_edges),
                    "relationship_omitted_edge_count": event_relationship_omitted_edge_count,
                    "relationship_rejected_correlation_count": (
                        event_relationship_rejected_correlation_count
                    ),
                    "route_signal_materialization_policy": GRAPH_EVENT_ROUTE_SIGNAL_EDGE_POLICY,
                    "refs": event_refs,
                    "evidence_refs": [{"session_id": session_id, "segment_id": segment_id, "event_id": event_id, "refs": event_refs}],
                }
            )
            if graph_should_materialize_high_fanout_event_edge("has_event"):
                add_segment_edge(
                    {
                        "source": segment_node_id,
                        "target": event_node_id,
                        "type": "has_event",
                        "session_id": session_id,
                        "segment_id": segment_id,
                        "event_id": event_id,
                        "evidence_refs": [{"session_id": session_id, "segment_id": segment_id, "event_id": event_id, "refs": event_refs}],
                    }
                )
            raw_ref = str(event.get("raw_ref") or "")
            if raw_ref and GRAPH_MATERIALIZE_RAW_REF_NODES:
                raw_node_id = graph_raw_ref_node_id(session_id, raw_ref)
                add_segment_node(
                    {
                        "id": raw_node_id,
                        "type": "raw_ref",
                        "label": raw_ref,
                        "session_id": session_id,
                        "session_label": session_label,
                        "raw_ref": raw_ref,
                        "evidence_refs": [{"session_id": session_id, "segment_id": segment_id, "event_id": event_id, "refs": event_refs}],
                    }
                )
                add_segment_edge(
                    {
                        "source": event_node_id,
                        "target": raw_node_id,
                        "type": "has_raw_ref",
                        "session_id": session_id,
                        "segment_id": segment_id,
                        "event_id": event_id,
                        "evidence_refs": [{"session_id": session_id, "segment_id": segment_id, "event_id": event_id, "refs": event_refs}],
                    }
                )
            for signal in route_signals:
                layer = signal["layer"]
                key = signal["key"]
                route_signal_value = signal["route_signal"]
                route_node_id = graph_route_node_id(layer, key)
                route_signal_tuple = (layer, key, route_signal_value)
                segment_route_signal_counts[route_signal_tuple] += 1
                segment_route_signal_evidence_refs[route_signal_tuple] = graph_merge_evidence_refs(
                    segment_route_signal_evidence_refs.get(route_signal_tuple, []),
                    [{"session_id": session_id, "segment_id": segment_id, "event_id": event_id, "refs": event_refs}],
                    limit=GRAPH_STORE_CONTRIB_EDGE_EVIDENCE_LIMIT,
                )
                route_signal_identity = graph_route_signal_identity(layer, key, route_signal_value)
                materialize_event_edge = route_signal_identity in event_route_signal_edges
                materialize_registry_edge = route_signal_identity in event_registered_entity_edges
                if materialize_event_edge or materialize_registry_edge:
                    add_segment_node(
                        {
                            "id": route_node_id,
                            "type": graph_route_node_type(layer, key),
                            "label": route_signal_value,
                            "route_layer": layer,
                            "route_key": key,
                            "route_signal": route_signal_value,
                            "axis": ROUTE_SIGNAL_LAYER_TO_AXIS.get(layer, ""),
                            "evidence_refs": [{"session_id": session_id, "segment_id": segment_id, "event_id": event_id, "refs": event_refs}],
                        }
                    )
                if materialize_event_edge:
                    add_segment_edge(
                        {
                            "source": event_node_id,
                            "target": route_node_id,
                            "type": "event_has_route_signal",
                            "session_id": session_id,
                            "segment_id": segment_id,
                            "event_id": event_id,
                            "route_signal": route_signal_value,
                            "signal_source": signal.get("source"),
                            "signal_confidence": signal.get(
                                "confidence"
                            ),
                            "semantic_boundary": (
                                "derived route-signal navigation; this edge "
                                "does not by itself prove literal mention, "
                                "invocation, completion, or consequence"
                            ),
                            "materialization_policy": GRAPH_EVENT_ROUTE_SIGNAL_EDGE_POLICY,
                            "evidence_refs": [{"session_id": session_id, "segment_id": segment_id, "event_id": event_id, "refs": event_refs}],
                        }
                    )
                if materialize_registry_edge:
                    add_registry_route_links(
                        add_node=add_segment_node,
                        add_edge=add_segment_edge,
                        owner_node_id=event_node_id,
                        route_node_id=route_node_id,
                        layer=layer,
                        key=key,
                        evidence_refs=[{"session_id": session_id, "segment_id": segment_id, "event_id": event_id, "refs": event_refs}],
                        edge_type="event_has_registered_entity_signal",
                        extra={
                            "segment_id": segment_id,
                            "event_id": event_id,
                            "signal_source": signal.get(
                                "source"
                            ),
                            "signal_confidence": signal.get(
                                "confidence"
                            ),
                            "semantic_boundary": (
                                "registered entity navigation derived from "
                                "an event route signal; this edge does not "
                                "by itself prove literal mention, usage, "
                                "completion, or consequence"
                            ),
                        },
                    )
            for rel_type, relation, target_event in event_relationship_edges:
                target_event_node_id = f"event:{session_id}:{segment_id}:{relation.get('event_id')}"
                target_event_refs = segment_event_refs_by_id.get(
                    str(relation.get("event_id") or ""),
                    {},
                )
                relation_evidence_refs = graph_merge_evidence_refs(
                    [
                        {
                            "session_id": session_id,
                            "segment_id": segment_id,
                            "event_id": event_id,
                            "refs": event_refs,
                        }
                    ],
                    [
                        {
                            "session_id": session_id,
                            "segment_id": segment_id,
                            "event_id": relation.get("event_id"),
                            "refs": target_event_refs,
                        }
                    ]
                    if target_event_refs
                    else [],
                    limit=GRAPH_STORE_CONTRIB_EDGE_EVIDENCE_LIMIT,
                )
                add_segment_edge(
                    {
                        "source": event_node_id,
                        "target": target_event_node_id,
                        "type": rel_type,
                        "session_id": session_id,
                        "segment_id": segment_id,
                        "event_id": event_id,
                        "correlation_id": relation.get("correlation_id"),
                        "source_correlation_id": event.get(
                            "correlation_id"
                        ),
                        "target_correlation_id": target_event.get(
                            "correlation_id"
                        ),
                        "event_timestamp": event.get("timestamp"),
                        "target_event_timestamp": target_event.get(
                            "timestamp"
                        ),
                        "evidence_refs": relation_evidence_refs,
                    }
                )
        selected_segment_route_signals = graph_select_segment_route_signal_identities(
            segment_route_signal_counts,
            registry_entry_for_route=registry_entry_for_route,
            limit=GRAPH_SEGMENT_ROUTE_SIGNAL_EDGE_LIMIT,
        )
        if segment_node_id in segment_nodes:
            segment_nodes[segment_node_id]["route_signal_count"] = len(segment_route_signal_counts)
            segment_nodes[segment_node_id]["route_signal_materialized_count"] = len(selected_segment_route_signals)
            segment_nodes[segment_node_id]["route_signal_omitted_count"] = max(0, len(segment_route_signal_counts) - len(selected_segment_route_signals))
            segment_nodes[segment_node_id]["route_signal_materialization_policy"] = GRAPH_EVENT_ROUTE_SIGNAL_EDGE_POLICY
        for layer, key, route_signal_value in selected_segment_route_signals:
            route_node_id = graph_route_node_id(layer, key)
            route_signal_tuple = (layer, key, route_signal_value)
            evidence_refs = graph_merge_evidence_refs(
                segment_route_signal_evidence_refs.get(route_signal_tuple, []),
                [{"session_id": session_id, "segment_id": segment_id, "refs": segment_refs}],
                limit=GRAPH_STORE_CONTRIB_NODE_EVIDENCE_LIMIT,
            )
            add_segment_node(
                {
                    "id": route_node_id,
                    "type": graph_route_node_type(layer, key),
                    "label": route_signal_value,
                    "route_layer": layer,
                    "route_key": key,
                    "route_signal": route_signal_value,
                    "axis": ROUTE_SIGNAL_LAYER_TO_AXIS.get(layer, ""),
                    "evidence_refs": evidence_refs,
                }
            )
            add_segment_edge(
                {
                    "source": segment_node_id,
                    "target": route_node_id,
                    "type": "segment_has_route_signal",
                    "session_id": session_id,
                    "segment_id": segment_id,
                    "count": int_value(segment_route_signal_counts[(layer, key, route_signal_value)], 1),
                    "route_signal": route_signal_value,
                    "materialization_policy": GRAPH_EVENT_ROUTE_SIGNAL_EDGE_POLICY,
                    "evidence_refs": evidence_refs,
                }
            )
        node_rows, edge_rows = graph_rows_from_maps(segment_nodes, segment_edges)
        contributions.append(
            {
                "source": graph_source_metadata(
                    source_type="segment",
                    session_id=session_id,
                    session_label=session_label,
                    segment_id=segment_id,
                    source_paths=[manifest_path, session_index_path, segment_index_path],
                    identity={
                        "session_title": session_title,
                        "segment": segment,
                        "session_index_generation_id": (
                            session_index.get("generation_id")
                        ),
                        "segment_index_generation_id": (
                            segment_index.get("generation_id")
                        ),
                    },
                    source_hash_cache_entries=source_hash_cache,
                    source_hash_cache_updates=source_hash_cache,
                    source_hash_stats=source_hash_stats,
                ),
                "nodes": node_rows,
                "edges": edge_rows,
            }
        )
    return contributions, diagnostics


GRAPH_PROJECTION_SEMANTIC_DIGEST_VERSION = 2
GRAPH_PROJECTION_SEMANTIC_DIGEST_TABLE_ORDER = (
    ("graph_sources", "source_key"),
    ("node_contribs", "source_key, node_id"),
    ("edge_contribs", "source_key, edge_id"),
    ("nodes", "id"),
    ("edges", "id"),
    ("graph_type_counts", "kind, type"),
)
GRAPH_PROJECTION_SEMANTIC_DIGEST_VOLATILE_COLUMNS = frozenset(
    {
        "indexed_at",
        "source_mtime",
        "source_path",
        "source_paths_json",
    }
)


def graph_projection_semantic_digest(
    conn: sqlite3.Connection,
) -> dict[str, Any]:
    """Hash graph semantics without SQLite layout or publication time."""

    digest = hashlib.sha256()
    table_counts: dict[str, int] = {}
    for table, order_by in GRAPH_PROJECTION_SEMANTIC_DIGEST_TABLE_ORDER:
        if not sqlite_table_exists(conn, table):
            continue
        columns = [
            str(row[1])
            for row in conn.execute(
                f"PRAGMA table_info({table})"
            ).fetchall()
            if str(row[1])
            not in GRAPH_PROJECTION_SEMANTIC_DIGEST_VOLATILE_COLUMNS
        ]
        if not columns:
            continue
        quoted_columns = ", ".join(
            '"' + column.replace('"', '""') + '"'
            for column in columns
        )
        row_count = 0
        digest.update(f"table:{table}\n".encode("utf-8"))
        for row in conn.execute(
            f"""
            SELECT {quoted_columns}
            FROM {table}
            ORDER BY {order_by}
            """
        ):
            canonical_values = [
                (
                    {
                        "blob_sha256": hashlib.sha256(
                            bytes(value)
                        ).hexdigest(),
                        "blob_bytes": len(bytes(value)),
                    }
                    if isinstance(
                        value,
                        (bytes, bytearray, memoryview),
                    )
                    else value
                )
                for value in row
            ]
            digest.update(
                json.dumps(
                    canonical_values,
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            )
            digest.update(b"\n")
            row_count += 1
        table_counts[table] = row_count
    return {
        "version": GRAPH_PROJECTION_SEMANTIC_DIGEST_VERSION,
        "sha256": digest.hexdigest(),
        "table_counts": table_counts,
        "excluded_columns": sorted(
            GRAPH_PROJECTION_SEMANTIC_DIGEST_VOLATILE_COLUMNS
        ),
        "truth_status": (
            "semantic_graph_content_digest_not_sqlite_binary_digest"
        ),
    }


