def graph_entity_registry_entry_for_route(
    registry_index: dict[tuple[str, str], dict[str, Any]],
    layer: str,
    key: str,
) -> dict[str, Any] | None:
    route_layer = route_key_slug(layer, fallback="")
    route_key = route_key_slug(
        key,
        fallback="",
        max_chars=120,
    )
    kind = (
        "mcp_tool"
        if (
            route_layer == "tool"
            and entity_registry_tool_key_is_mcp_tool(route_key)
        )
        else ENTITY_REGISTRY_KIND_BY_ROUTE_LAYER.get(
            route_layer,
            route_layer,
        )
    )
    return registry_index.get((kind, route_key))


def graph_entity_registry_node_semantic_projection(
    entry: dict[str, Any],
) -> dict[str, Any]:
    canonicalization = (
        entry.get("canonicalization")
        if isinstance(entry.get("canonicalization"), dict)
        else {}
    )
    return {
        "entity_id": entry.get("entity_id"),
        "entity_kind": entry.get("kind"),
        "canonical_key": entry.get("canonical_key"),
        "status": entry.get("status"),
        "route_layer": entry.get("route_layer"),
        "route_signal": entry.get("route_signal"),
        "source_surface": entry.get("source_surface"),
        "owner": entry.get("owner"),
        "canonicalization": {
            "schema_version": canonicalization.get(
                "schema_version"
            ),
            "status": canonicalization.get("status"),
            "identity_claim_allowed": canonicalization.get(
                "identity_claim_allowed"
            ),
            "collision_preserved": canonicalization.get(
                "collision_preserved"
            ),
            "candidate_count": canonicalization.get(
                "candidate_count"
            ),
            "active_candidate_count": canonicalization.get(
                "active_candidate_count"
            ),
            "selected_candidate_id": canonicalization.get(
                "selected_candidate_id"
            ),
        },
        "identity_candidate_ids": canonicalization.get(
            "candidate_ids",
            [],
        ),
    }


def graph_entity_registry_node(
    entry: dict[str, Any],
    *,
    aoa_root: Path,
    evidence_refs: list[Any],
) -> dict[str, Any]:
    return {
        "id": f"entity_registry:{entry.get('entity_id')}",
        "type": "entity_registry",
        "label": (
            f"{entry.get('kind')}:{entry.get('canonical_key')}"
        ),
        **graph_entity_registry_node_semantic_projection(entry),
        "refs": {
            "registry": str(aoa_root / ENTITY_REGISTRY_PATH)
        },
        "evidence_refs": evidence_refs,
    }


def graph_source_registry_dependency_for_route_tokens(
    route_tokens: Iterable[dict[str, Any]],
    registry_index: dict[tuple[str, str], dict[str, Any]],
) -> dict[str, Any]:
    rows: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for token in route_tokens:
        if not isinstance(token, dict):
            continue
        layer = route_key_slug(token.get("layer"), fallback="")
        key = route_key_slug(
            token.get("key"), fallback="", max_chars=120
        )
        identity = (layer, key)
        if not layer or not key or identity in seen:
            continue
        seen.add(identity)
        entry = graph_entity_registry_entry_for_route(
            registry_index, layer, key
        )
        rows.append(
            {
                "layer": layer,
                "key": key,
                "entity": (
                    graph_entity_registry_node_semantic_projection(
                        entry
                    )
                    if isinstance(entry, dict)
                    else None
                ),
            }
        )
    rows.sort(key=lambda item: (item["layer"], item["key"]))
    digest = hashlib.sha256(
        json.dumps(
            rows,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    return {
        "schema_version": 1,
        "digest": digest,
        "route_count": len(rows),
        "resolved_entity_count": sum(
            1 for row in rows if row.get("entity") is not None
        ),
        "route_tokens": [
            {"layer": row["layer"], "key": row["key"]}
            for row in rows
        ],
    }


def graph_source_registry_dependency_for_contribution(
    contribution: dict[str, Any],
    registry_index: dict[tuple[str, str], dict[str, Any]],
) -> dict[str, Any]:
    route_tokens = [
        {
            "layer": node.get("route_layer"),
            "key": node.get("route_key"),
        }
        for node in (
            contribution.get("nodes")
            if isinstance(contribution.get("nodes"), list)
            else []
        )
        if isinstance(node, dict)
        and node.get("route_layer")
        and node.get("route_key")
    ]
    return graph_source_registry_dependency_for_route_tokens(
        route_tokens,
        registry_index,
    )


def graph_migrate_selective_registry_dependencies(
    *,
    conn: sqlite3.Connection,
    registry_index: dict[tuple[str, str], dict[str, Any]],
) -> dict[str, Any]:
    columns = {
        str(row[1])
        for row in conn.execute(
            "PRAGMA table_info(graph_sources)"
        ).fetchall()
    }
    if "entity_registry_route_tokens_json" not in columns:
        conn.execute(
            "ALTER TABLE graph_sources ADD COLUMN "
            "entity_registry_route_tokens_json TEXT NOT NULL DEFAULT '[]'"
        )
    if "entity_registry_selective_digest" not in columns:
        conn.execute(
            "ALTER TABLE graph_sources ADD COLUMN "
            "entity_registry_selective_digest TEXT NOT NULL DEFAULT ''"
        )
    route_tokens_by_source: defaultdict[
        str, list[dict[str, str]]
    ] = defaultdict(list)
    for row in conn.execute(
        "SELECT source_key, payload_json FROM node_contribs "
        "WHERE node_type != 'entity_registry'"
    ):
        try:
            payload = json.loads(str(row["payload_json"] or "{}"))
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict):
            continue
        layer = route_key_slug(
            payload.get("route_layer"), fallback=""
        )
        key = route_key_slug(
            payload.get("route_key"),
            fallback="",
            max_chars=120,
        )
        if layer and key:
            route_tokens_by_source[str(row["source_key"] or "")].append(
                {"layer": layer, "key": key}
            )
    updated = 0
    for row in conn.execute(
        "SELECT source_key FROM graph_sources"
    ).fetchall():
        source_key = str(row["source_key"] or "")
        dependency = graph_source_registry_dependency_for_route_tokens(
            route_tokens_by_source.get(source_key, []),
            registry_index,
        )
        conn.execute(
            "UPDATE graph_sources SET "
            "entity_registry_route_tokens_json = ?, "
            "entity_registry_selective_digest = ? "
            "WHERE source_key = ?",
            (
                graph_json(dependency["route_tokens"]),
                dependency["digest"],
                source_key,
            ),
        )
        updated += 1
    return {
        "status": "migrated",
        "source_count": updated,
        "route_bearing_source_count": len(route_tokens_by_source),
    }


