def path_total_size(path: Path) -> int:
    if not path.exists() and not path.is_symlink():
        return 0
    try:
        if path.is_file() or path.is_symlink():
            return path.stat().st_size
    except OSError:
        return 0
    total = 0
    for root, dirs, files in os.walk(path):
        dirs[:] = [name for name in dirs if name not in {".git", ".pytest_cache", "__pycache__"}]
        root_path = Path(root)
        for name in files:
            try:
                total += (root_path / name).stat().st_size
            except OSError:
                continue
    return total


def storage_size_entry(path: Path, *, label: str | None = None) -> dict[str, Any]:
    size = path_total_size(path)
    return {
        "label": label or path.name,
        "path": str(path),
        "exists": path.exists() or path.is_symlink(),
        "size_bytes": size,
        "size_human": human_size(size),
    }


def sqlite_storage_stats(
    db_path: Path,
    *,
    deep: bool = False,
    row_counts: bool = False,
    table_limit: int = 40,
) -> dict[str, Any]:
    payload: dict[str, Any] = storage_size_entry(db_path, label=db_path.name)
    payload.update({"kind": "sqlite", "ok": False, "diagnostics": []})
    wal_path = Path(str(db_path) + "-wal")
    shm_path = Path(str(db_path) + "-shm")
    wal_bytes = path_total_size(wal_path)
    shm_bytes = path_total_size(shm_path)
    payload["wal"] = {
        "path": str(wal_path),
        "exists": wal_path.exists(),
        "size_bytes": wal_bytes,
        "size_human": human_size(wal_bytes),
    }
    payload["shm"] = {
        "path": str(shm_path),
        "exists": shm_path.exists(),
        "size_bytes": shm_bytes,
        "size_human": human_size(shm_bytes),
    }
    payload["total_with_wal_bytes"] = int_value(payload.get("size_bytes")) + wal_bytes + shm_bytes
    payload["total_with_wal_human"] = human_size(payload["total_with_wal_bytes"])
    if not db_path.exists():
        payload["diagnostics"] = ["sqlite_db_missing"]
        return payload
    try:
        conn = sqlite3.connect(str(db_path))
        conn.row_factory = sqlite3.Row
        metadata: dict[str, str] = {}
        for meta_table in ("metadata", "meta"):
            try:
                rows = conn.execute(f"SELECT key, value FROM {meta_table} ORDER BY key").fetchall()
            except sqlite3.Error:
                continue
            for row in rows:
                metadata[str(row["key"])] = str(row["value"])
        if metadata:
            payload["metadata"] = metadata
            payload["raw_lexical_policy"] = search_raw_lexical_policy_from_metadata(metadata)
        page_size = int(conn.execute("PRAGMA page_size").fetchone()[0])
        page_count = int(conn.execute("PRAGMA page_count").fetchone()[0])
        freelist_count = int(conn.execute("PRAGMA freelist_count").fetchone()[0])
        payload.update(
            {
                "ok": True,
                "page_size": page_size,
                "page_count": page_count,
                "freelist_count": freelist_count,
                "allocated_bytes": page_size * page_count,
                "freelist_bytes": page_size * freelist_count,
                "freelist_human": human_size(page_size * freelist_count),
            }
        )
        if row_counts:
            payload["row_count_status"] = "requested"
            row_count_payload: dict[str, int] = {}
            tables = [
                str(row["name"])
                for row in conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name").fetchall()
            ]
            for table in tables:
                try:
                    row = conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()
                    row_count_payload[table] = int(row[0] or 0) if row else 0
                except sqlite3.Error:
                    continue
            payload["row_counts"] = row_count_payload
        else:
            payload["row_count_status"] = "not_requested"
        if deep:
            payload["deep_dbstat_status"] = "requested"
            try:
                rows = conn.execute(
                    """
                    SELECT name, SUM(pgsize) AS bytes, COUNT(*) AS pages
                    FROM dbstat
                    GROUP BY name
                    ORDER BY bytes DESC
                    LIMIT ?
                    """,
                    (max(1, int_value(table_limit, 40)),),
                ).fetchall()
                payload["table_sizes"] = [
                    {
                        "name": str(row["name"]),
                        "size_bytes": int(row["bytes"] or 0),
                        "size_human": human_size(int(row["bytes"] or 0)),
                        "pages": int(row["pages"] or 0),
                    }
                    for row in rows
                ]
                payload["deep_dbstat_status"] = "completed"
            except sqlite3.Error as exc:
                payload.setdefault("diagnostics", []).append(f"dbstat_unavailable:{exc}")
                payload["deep_dbstat_status"] = "unavailable"
        else:
            payload["deep_dbstat_status"] = "not_requested"
        conn.close()
    except sqlite3.Error as exc:
        payload["diagnostics"] = [f"sqlite_error:{exc}"]
    return payload


def sqlite_wal_checkpoint(
    db_path: Path,
    *,
    timeout: float = 120.0,
) -> dict[str, Any]:
    wal_path = Path(str(db_path) + "-wal")
    shm_path = Path(str(db_path) + "-shm")
    before = {
        "db_bytes": path_total_size(db_path),
        "wal_bytes": path_total_size(wal_path),
        "shm_bytes": path_total_size(shm_path),
    }
    diagnostics: list[str] = []
    result_rows: list[list[int]] = []
    if not db_path.exists():
        return {
            "path": str(db_path),
            "ok": False,
            "status": "missing",
            "mutates": False,
            "before": before,
            "after": before,
            "reclaimed_bytes": 0,
            "reclaimed_human": "0 B",
            "diagnostics": ["sqlite_db_missing"],
        }
    try:
        conn = sqlite3.connect(str(db_path), timeout=timeout)
        try:
            result_rows = [[int_value(value) for value in row] for row in conn.execute("PRAGMA wal_checkpoint(TRUNCATE)").fetchall()]
            conn.commit()
        finally:
            conn.close()
    except sqlite3.Error as exc:
        diagnostics.append(sqlite_error_diagnostic(exc))
    after = {
        "db_bytes": path_total_size(db_path),
        "wal_bytes": path_total_size(wal_path),
        "shm_bytes": path_total_size(shm_path),
    }
    busy = bool(result_rows and result_rows[0] and int_value(result_rows[0][0]) != 0)
    reclaimed = max(0, before["db_bytes"] + before["wal_bytes"] + before["shm_bytes"] - after["db_bytes"] - after["wal_bytes"] - after["shm_bytes"])
    status = "checkpointed"
    if diagnostics:
        status = "sqlite_error"
    elif busy:
        status = "busy_deferred"
        diagnostics.append("sqlite_wal_checkpoint_busy")
    return {
        "path": str(db_path),
        "ok": not diagnostics or busy,
        "status": status,
        "mutates": True,
        "result": result_rows,
        "before": before,
        "after": after,
        "reclaimed_bytes": reclaimed,
        "reclaimed_human": human_size(reclaimed),
        "diagnostics": diagnostics,
    }


def storage_maintenance(
    *,
    aoa_root: Path,
    write_report: bool = False,
) -> dict[str, Any]:
    now = utc_now()
    targets = {
        "graph_store": graph_paths(aoa_root)["store"],
        "search_store": search_db_path(aoa_root),
    }
    checkpoints = {
        name: sqlite_wal_checkpoint(path)
        for name, path in targets.items()
    }
    diagnostics = sorted(
        {
            f"{name}:{diag}"
            for name, item in checkpoints.items()
            for diag in (item.get("diagnostics", []) if isinstance(item.get("diagnostics"), list) else [])
            if diag
        }
    )
    reclaimed = sum(int_value(item.get("reclaimed_bytes")) for item in checkpoints.values())
    busy = any(str(item.get("status") or "") == "busy_deferred" for item in checkpoints.values())
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_storage_maintenance",
        "generated_at": now,
        "ok": not any(str(item.get("status") or "") == "sqlite_error" for item in checkpoints.values()),
        "mutates": True,
        "status": "deferred_busy" if busy else "checkpointed",
        "aoa_root": str(aoa_root),
        "actions": {
            "sqlite_wal_checkpoint_truncate": checkpoints,
        },
        "reclaimed_bytes": reclaimed,
        "reclaimed_human": human_size(reclaimed),
        "diagnostics": diagnostics,
        "stop_line": "Only SQLite WAL files are checkpointed here. Do not delete raw evidence or VACUUM live graph/search stores from this route.",
    }
    if write_report:
        diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
        diagnostics_dir.mkdir(parents=True, exist_ok=True)
        stem = f"{compact_stamp()}__storage-maintenance"
        report_json = diagnostics_dir / f"{stem}.json"
        report_md = diagnostics_dir / f"{stem}.md"
        write_json(report_json, payload)
        write_markdown(report_md, storage_maintenance_markdown(payload))
        payload["report_json"] = str(report_json)
        payload["report_markdown"] = str(report_md)
    return payload


def session_storage_breakdown(aoa_root: Path) -> dict[str, Any]:
    sessions_root = aoa_root / SESSION_ROOT
    buckets = {
        "raw_session_jsonl": 0,
        "raw_blocks": 0,
        "raw_ledgers": 0,
        "segment_markdown": 0,
        "segment_indexes": 0,
        "session_companions": 0,
        "hooks_incidents_distillation": 0,
    }
    raw_block_plain_bytes = 0
    raw_block_compressed_bytes = 0
    raw_block_other_bytes = 0
    if not sessions_root.exists():
        return {"root": str(sessions_root), "exists": False, "buckets": buckets, "total_bytes": 0, "total_human": "0 B"}
    for session_dir in sessions_root.iterdir():
        if not session_dir.is_dir():
            continue
        buckets["raw_session_jsonl"] += path_total_size(session_dir / "raw" / "session.raw.jsonl")
        blocks_dir = session_dir / "raw" / "blocks"
        buckets["raw_blocks"] += path_total_size(blocks_dir)
        if blocks_dir.exists():
            for path in blocks_dir.iterdir():
                if not path.is_file():
                    continue
                size = path.stat().st_size
                if path.name.endswith(".raw.jsonl"):
                    raw_block_plain_bytes += size
                elif path.name.endswith(".raw.jsonl.gz"):
                    raw_block_compressed_bytes += size
                else:
                    raw_block_other_bytes += size
        buckets["raw_ledgers"] += path_total_size(session_dir / "raw" / "blocks.index.json")
        buckets["raw_ledgers"] += path_total_size(session_dir / "raw" / "compaction-events.jsonl")
        for path in (session_dir / "segments").glob("*.md"):
            buckets["segment_markdown"] += path_total_size(path)
        for path in (session_dir / "segments").glob("*.index.json"):
            buckets["segment_indexes"] += path_total_size(path)
        for name in ("SESSION.md", "session.index.json", "session.manifest.json", "AGENTS.md"):
            buckets["session_companions"] += path_total_size(session_dir / name)
        for name in ("hooks", "incidents", "distillation", "naming"):
            buckets["hooks_incidents_distillation"] += path_total_size(session_dir / name)
    total = sum(buckets.values())
    return {
        "root": str(sessions_root),
        "exists": True,
        "buckets": {
            key: {"size_bytes": value, "size_human": human_size(value)}
            for key, value in sorted(buckets.items())
        },
        "total_bytes": total,
        "total_human": human_size(total),
        "raw_block_storage": {
            "plain_bytes": raw_block_plain_bytes,
            "plain_human": human_size(raw_block_plain_bytes),
            "compressed_bytes": raw_block_compressed_bytes,
            "compressed_human": human_size(raw_block_compressed_bytes),
            "other_bytes": raw_block_other_bytes,
            "other_human": human_size(raw_block_other_bytes),
        },
        "raw_block_duplication_candidate_bytes": min(buckets["raw_session_jsonl"], raw_block_plain_bytes),
        "raw_block_duplication_candidate_human": human_size(min(buckets["raw_session_jsonl"], raw_block_plain_bytes)),
    }


def graph_aggregate_payload_compaction_sample(
    db_path: Path,
    *,
    sample_limit: int = 400,
) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "status": "missing",
        "mutates": False,
        "sample_limit": max(1, int_value(sample_limit, 400)),
        "tables": {},
        "sample_count": 0,
        "invalid_payload_count": 0,
        "original_payload_bytes": 0,
        "compacted_payload_bytes": 0,
        "delta_bytes": 0,
        "delta_ratio": 0.0,
        "diagnostics": [],
    }
    if not db_path.exists():
        payload["diagnostics"].append("sqlite_db_missing")
        return payload
    try:
        conn = sqlite3.connect(str(db_path))
        conn.row_factory = sqlite3.Row
    except sqlite3.Error as exc:
        payload["status"] = "sqlite_error"
        payload["diagnostics"].append(sqlite_error_diagnostic(exc))
        return payload
    try:
        table_specs = (("nodes", "node"), ("edges", "edge"))
        per_table_limit = max(1, payload["sample_limit"] // len(table_specs))
        for table, kind in table_specs:
            table_payload = {
                "status": "empty",
                "sample_limit": per_table_limit,
                "rowid_max": 0,
                "sample_count": 0,
                "already_compact_count": 0,
                "invalid_payload_count": 0,
                "original_payload_bytes": 0,
                "compacted_payload_bytes": 0,
                "delta_bytes": 0,
                "delta_ratio": 0.0,
                "anchors": [],
                "diagnostics": [],
            }
            try:
                row = conn.execute(f"SELECT MAX(rowid) FROM {table}").fetchone()
                rowid_max = int_value(row[0]) if row else 0
            except sqlite3.Error as exc:
                table_payload["status"] = "sqlite_error"
                table_payload["diagnostics"].append(sqlite_error_diagnostic(exc))
                payload["diagnostics"].append(f"{table}:{sqlite_error_diagnostic(exc)}")
                payload["tables"][table] = table_payload
                continue
            table_payload["rowid_max"] = rowid_max
            if rowid_max <= 0:
                payload["tables"][table] = table_payload
                continue
            anchors = sorted({0, rowid_max // 4, rowid_max // 2, (rowid_max * 3) // 4, max(0, rowid_max - per_table_limit)})
            table_payload["anchors"] = anchors
            per_anchor_limit = max(1, per_table_limit // len(anchors))
            seen_rowids: set[int] = set()
            for anchor in anchors:
                remaining = per_table_limit - table_payload["sample_count"]
                if remaining <= 0:
                    break
                try:
                    rows = conn.execute(
                        f"SELECT rowid, payload_json FROM {table} WHERE rowid > ? ORDER BY rowid LIMIT ?",
                        (anchor, min(per_anchor_limit, remaining)),
                    ).fetchall()
                except sqlite3.Error as exc:
                    table_payload["status"] = "sqlite_error"
                    table_payload["diagnostics"].append(sqlite_error_diagnostic(exc))
                    payload["diagnostics"].append(f"{table}:{sqlite_error_diagnostic(exc)}")
                    break
                for row in rows:
                    rowid = int_value(row["rowid"])
                    if rowid in seen_rowids:
                        continue
                    seen_rowids.add(rowid)
                    payload_json = str(row["payload_json"] or "")
                    original_bytes = len(payload_json.encode("utf-8"))
                    table_payload["sample_count"] += 1
                    table_payload["original_payload_bytes"] += original_bytes
                    try:
                        row_payload = json.loads(payload_json)
                    except json.JSONDecodeError:
                        table_payload["invalid_payload_count"] += 1
                        continue
                    if not isinstance(row_payload, dict):
                        table_payload["invalid_payload_count"] += 1
                        continue
                    compacted_json = graph_json(graph_compact_aggregate_payload(row_payload, kind=kind))
                    compacted_bytes = len(compacted_json.encode("utf-8"))
                    table_payload["compacted_payload_bytes"] += compacted_bytes
                    table_payload["delta_bytes"] += max(0, original_bytes - compacted_bytes)
                    if compacted_json == payload_json:
                        table_payload["already_compact_count"] += 1
            original = int_value(table_payload["original_payload_bytes"])
            if original > 0:
                table_payload["delta_ratio"] = round(int_value(table_payload["delta_bytes"]) / original, 8)
            if table_payload["status"] != "sqlite_error":
                table_payload["status"] = "completed" if table_payload["sample_count"] else "empty"
            payload["tables"][table] = table_payload
            payload["sample_count"] += int_value(table_payload["sample_count"])
            payload["invalid_payload_count"] += int_value(table_payload["invalid_payload_count"])
            payload["original_payload_bytes"] += original
            payload["compacted_payload_bytes"] += int_value(table_payload["compacted_payload_bytes"])
            payload["delta_bytes"] += int_value(table_payload["delta_bytes"])
        if payload["original_payload_bytes"] > 0:
            payload["delta_ratio"] = round(payload["delta_bytes"] / payload["original_payload_bytes"], 8)
        if payload["sample_count"] <= 0:
            payload["status"] = "empty"
        elif payload["diagnostics"]:
            payload["status"] = "completed_with_diagnostics"
        else:
            payload["status"] = "completed"
    finally:
        conn.close()
    return payload


def graph_aggregate_payload_compaction_recommendation(
    *,
    table_sizes: dict[str, int],
    sample: dict[str, Any],
) -> dict[str, Any]:
    aggregate_table_bytes = int_value(table_sizes.get("nodes")) + int_value(table_sizes.get("edges"))
    if not table_sizes:
        return {
            "status": "implemented_for_new_rebuilds_and_touched_sources",
            "estimated_reclaimable_bytes": 0,
            "estimated_reclaimable_human": "requires --deep-dbstat",
            "estimate_status": "requires_deep_dbstat",
            "aggregate_table_size_bytes": 0,
            "aggregate_table_size_human": "requires --deep-dbstat",
            "next_route": "run storage-audit --deep-dbstat before deciding whether aggregate compaction or graph cardinality is the real weight driver",
        }
    sample_status = str(sample.get("status") or "not_requested")
    original_payload_bytes = int_value(sample.get("original_payload_bytes"))
    delta_bytes = int_value(sample.get("delta_bytes"))
    if sample_status in {"completed", "completed_with_diagnostics"} and original_payload_bytes > 0:
        delta_ratio = max(0.0, min(1.0, float(delta_bytes) / float(original_payload_bytes)))
        estimated = int(aggregate_table_bytes * delta_ratio)
        if estimated <= 0:
            return {
                "status": "already_compact_sampled_cardinality_dominates",
                "estimated_reclaimable_bytes": 0,
                "estimated_reclaimable_human": "0 B",
                "estimate_status": "sampled_no_payload_delta",
                "aggregate_table_size_bytes": aggregate_table_bytes,
                "aggregate_table_size_human": human_size(aggregate_table_bytes),
                "sample_delta_ratio": round(delta_ratio, 8),
                "next_route": "analyze graph cardinality, sharding, and query projections; do not rebuild solely for aggregate payload compaction",
            }
        return {
            "status": "sampled_payload_delta_available",
            "estimated_reclaimable_bytes": estimated,
            "estimated_reclaimable_human": human_size(estimated),
            "estimate_status": "sampled_payload_delta_ratio",
            "aggregate_table_size_bytes": aggregate_table_bytes,
            "aggregate_table_size_human": human_size(aggregate_table_bytes),
            "sample_delta_ratio": round(delta_ratio, 8),
            "next_route": "run a controlled graph-build all --write --store-only --in-place only if the sampled reclaim justifies the rebuild cost",
        }
    return {
        "status": "aggregate_payload_sample_unavailable",
        "estimated_reclaimable_bytes": 0,
        "estimated_reclaimable_human": "0 B",
        "estimate_status": f"sample_{sample_status}",
        "aggregate_table_size_bytes": aggregate_table_bytes,
        "aggregate_table_size_human": human_size(aggregate_table_bytes),
        "next_route": "fix the aggregate payload sample before using table size as a reclaim estimate; table bytes alone are cardinality evidence, not reclaimable bytes",
    }


def graph_raw_ref_materialization_recommendation(aoa_root: Path) -> dict[str, Any]:
    projection = graph_cardinality_projection_read(aoa_root, limit=80)
    counts = projection.get("counts") if isinstance(projection.get("counts"), dict) else {}
    node_counts = counts.get("node") if isinstance(counts.get("node"), dict) else {}
    edge_counts = counts.get("edge") if isinstance(counts.get("edge"), dict) else {}
    raw_ref_node_count = int_value(node_counts.get("raw_ref"))
    has_raw_ref_edge_count = int_value(edge_counts.get("has_raw_ref"))
    affected_rows = raw_ref_node_count + has_raw_ref_edge_count
    if GRAPH_MATERIALIZE_RAW_REF_NODES:
        status = "enabled"
        next_route = "evaluate whether raw_ref graph nodes are still required before disabling materialization"
    elif affected_rows:
        status = "disabled_for_new_builds_existing_store_mixed"
        next_route = "run graph-raw-ref-prune --apply --write-report to prune generated rows; physical graph.sqlite3 shrink still requires controlled VACUUM or rebuild with reserved disk"
    else:
        status = "disabled_for_new_builds_no_materialized_raw_ref_nodes"
        next_route = "no raw_ref graph-node compaction is needed; keep raw refs in event evidence packets"
    return {
        "status": status,
        "policy": GRAPH_RAW_REF_MATERIALIZATION_POLICY,
        "materialize_raw_ref_nodes": GRAPH_MATERIALIZE_RAW_REF_NODES,
        "raw_ref_node_count": raw_ref_node_count,
        "has_raw_ref_edge_count": has_raw_ref_edge_count,
        "affected_row_count": affected_rows,
        "estimate_status": "cardinality_only_rebuild_or_vacuum_required",
        "estimated_reclaimable_bytes": 0,
        "estimated_reclaimable_human": "requires controlled rebuild/prune",
        "quality_tradeoff": "none_expected; raw refs remain in event evidence refs and raw/segment/session authority stays unchanged",
        "speed_tradeoff": "smaller future graph stores; graph packets hydrate raw refs from event evidence instead of traversing raw_ref nodes",
        "projection_status": projection.get("status"),
        "next_route": next_route,
    }


def graph_event_sequence_projection_recommendation(
    *,
    aoa_root: Path,
    graph_store: dict[str, Any],
    table_sizes: dict[str, int],
) -> dict[str, Any]:
    projection = graph_cardinality_projection_read(aoa_root, limit=80)
    counts = projection.get("counts") if isinstance(projection.get("counts"), dict) else {}
    edge_counts = counts.get("edge") if isinstance(counts.get("edge"), dict) else {}
    omitted_types = sorted(GRAPH_EVENT_RELATIONSHIP_EDGE_OMIT_TYPES)
    sequence_edge_count = sum(int_value(edge_counts.get(edge_type)) for edge_type in omitted_types)
    total_edge_count = sum(int_value(value) for value in edge_counts.values())
    row_counts = graph_store.get("row_counts") if isinstance(graph_store.get("row_counts"), dict) else {}
    stored_edge_rows = int_value(row_counts.get("edges"), total_edge_count)
    stored_edge_contrib_rows = int_value(row_counts.get("edge_contribs"))
    edge_storage_bytes = sum(
        int_value(table_sizes.get(name))
        for name in (
            "edges",
            "edge_contribs",
            "sqlite_autoindex_edges_1",
            "sqlite_autoindex_edge_contribs_1",
            "idx_edges_source",
            "idx_edges_target",
            "idx_edges_source_type",
            "idx_edges_target_type",
            "idx_edge_contribs_edge",
        )
    )
    cardinality_denominator = max(total_edge_count, stored_edge_rows, 1)
    estimated_bytes = int(edge_storage_bytes * (sequence_edge_count / cardinality_denominator)) if sequence_edge_count > 0 and edge_storage_bytes > 0 else 0
    if str(projection.get("status") or "") != "current":
        status = "requires_cardinality_projection"
        next_route = "run graph-cardinality --refresh before estimating sequence-edge pressure"
    elif sequence_edge_count > 0:
        status = "policy_applied_after_rebuild_existing_store_mixed"
        next_route = "run graph-event-sequence-prune --apply --write-report, then maintenance-status and graph-cardinality --refresh; physical shrink still requires rebuild or VACUUM"
    else:
        status = "policy_already_applied_no_sequence_edges"
        next_route = "no sequence-edge graph cardinality action is needed"
    return {
        "status": status,
        "policy": GRAPH_EVENT_RELATIONSHIP_EDGE_POLICY,
        "omitted_edge_types": omitted_types,
        "sequence_edge_count": sequence_edge_count,
        "total_edge_count": total_edge_count,
        "stored_edge_rows": stored_edge_rows,
        "stored_edge_contrib_rows": stored_edge_contrib_rows,
        "edge_storage_bytes": edge_storage_bytes,
        "edge_storage_human": human_size(edge_storage_bytes),
        "estimated_reclaimable_bytes": estimated_bytes,
        "estimated_reclaimable_human": human_size(estimated_bytes) if estimated_bytes else "requires controlled rebuild/prune",
        "estimate_status": "cardinality_ratio_estimate" if estimated_bytes else "cardinality_only_rebuild_or_vacuum_required",
        "quality_tradeoff": "none_expected; linear event order remains in segment indexes and raw/session evidence, while graph keeps causal/correlation edges",
        "speed_tradeoff": "smaller graph neighborhoods and faster graph-store scans after generated rows are rebuilt or pruned",
        "projection_status": projection.get("status"),
        "next_route": next_route,
    }


def search_sqlite_physical_compaction_recommendation(plan: dict[str, Any]) -> dict[str, Any]:
    reclaimable = int_value(plan.get("conservative_reclaimable_bytes"))
    db_bytes = int_value(plan.get("db_bytes"))
    reclaim_ratio = round(reclaimable / db_bytes, 6) if db_bytes > 0 else 0.0
    status = str(plan.get("status") or "unknown")
    if plan.get("ok") and reclaimable <= 128 * 1024 * 1024:
        status = "low_reclaim_not_primary"
        next_route = "keep search-sqlite-compact as a safe route after large generated-store rewrites; current reclaim is too small to treat physical compaction as the search weight fix"
    elif plan.get("ok") and reclaim_ratio < 0.05:
        status = "low_reclaim_not_primary"
        next_route = "prefer search-index bounded raw lexical policy, shard policy, and route benchmarks before physical SQLite compaction; current freelist reclaim is small"
    elif plan.get("apply_ready"):
        next_route = "run search-sqlite-compact --write-report for a read-only plan; use --apply --method vacuum-into --target-path with optional --promote-copy and --delete-backup-after-verify only when disk headroom is sufficient"
    else:
        next_route = "fix search SQLite compaction preflight diagnostics before using physical compaction as a pressure route"
    return {
        "status": status,
        "quality_tradeoff": "none_expected_for_vacuum_into_copy; raw/session evidence is untouched and live replacement requires --promote-copy integrity checks",
        "speed_tradeoff": "manual-bulk SQLite copy/rewrite; not an interactive query path",
        "estimated_reclaimable_bytes": reclaimable,
        "estimated_reclaimable_human": plan.get("conservative_reclaimable_human"),
        "reclaim_ratio": reclaim_ratio,
        "required_free_human": plan.get("required_free_human"),
        "free_human": plan.get("free_human"),
        "min_free_after_human": plan.get("min_free_after_human"),
        "apply_ready": plan.get("apply_ready"),
        "next_route": next_route,
    }


def search_raw_text_fallback_dependency_recommendation(packet: dict[str, Any]) -> dict[str, Any]:
    status = str(packet.get("status") or "unknown")
    if status == "shard_full_text_ready":
        recommendation_status = "scoped_full_text_ready"
        next_route = "raw-text shard fan-out is available for materialized shard scope; keep monolith as generated fallback until broader route benchmarks justify removal"
    elif status == "monolith_required_for_raw_text_query":
        recommendation_status = "controlled_monolith_dependency"
        next_route = str(packet.get("next_route") or "use scoped full-text shard materialization for repeated literal raw-text work")
    elif status == "no_shards":
        recommendation_status = "requires_shard_materialization"
        next_route = "run search-shards all --write-report before evaluating raw-text shard fallback dependency"
    else:
        recommendation_status = "mixed_projection_review"
        next_route = str(packet.get("next_route") or "refresh search catalog and inspect shard raw-text support")
    return {
        "status": recommendation_status,
        "raw_text_fallback_status": status,
        "quality_tradeoff": packet.get("quality_tradeoff"),
        "speed_tradeoff": "structured routes stay fast and slim; literal raw-text queries use monolith fallback unless scoped full-text shards are materialized",
        "weight_tradeoff": packet.get("weight_tradeoff"),
        "estimated_reclaimable_bytes": 0,
        "estimated_reclaimable_human": "0 B",
        "estimate_status": "route_dependency_not_reclaim_estimate",
        "unsupported_shard_count": packet.get("unsupported_shard_count"),
        "structured_only_shard_count": packet.get("structured_only_shard_count"),
        "full_text_shard_count": packet.get("full_text_shard_count"),
        "scoped_full_text_next_commands": packet.get("scoped_full_text_next_commands"),
        "global_full_text_next_command": packet.get("global_full_text_next_command"),
        "next_route": next_route,
    }


def storage_audit(
    *,
    aoa_root: Path,
    deep_dbstat: bool = False,
    row_counts: bool = False,
    write_report: bool = False,
) -> dict[str, Any]:
    now = utc_now()
    graph_paths_payload = graph_paths(aoa_root)
    search_path = search_db_path(aoa_root)
    top_level = [
        storage_size_entry(aoa_root / name, label=name)
        for name in ("sessions", "graph", "search", "maps", "diagnostics")
    ]
    top_total = storage_size_entry(aoa_root, label=".aoa")
    graph_store = sqlite_storage_stats(graph_paths_payload["store"], deep=deep_dbstat, row_counts=row_counts)
    search_store = sqlite_storage_stats(search_path, deep=deep_dbstat, row_counts=row_counts)
    if deep_dbstat:
        graph_store["aggregate_payload_compaction_sample"] = graph_aggregate_payload_compaction_sample(graph_paths_payload["store"])
    sessions = session_storage_breakdown(aoa_root)
    raw_block_reclaim_bytes = int_value(sessions.get("raw_block_duplication_candidate_bytes"))
    search_raw_lexical_policy = (
        search_store.get("raw_lexical_policy")
        if isinstance(search_store.get("raw_lexical_policy"), dict)
        else {}
    )
    search_policy_status = search_raw_lexical_policy_status(search_raw_lexical_policy)
    table_sizes = {
        item.get("name"): int_value(item.get("size_bytes"))
        for item in graph_store.get("table_sizes", []) if isinstance(item, dict)
    }
    graph_compaction = graph_aggregate_payload_compaction_recommendation(
        table_sizes=table_sizes,
        sample=graph_store.get("aggregate_payload_compaction_sample") if isinstance(graph_store.get("aggregate_payload_compaction_sample"), dict) else {},
    )
    raw_ref_materialization = graph_raw_ref_materialization_recommendation(aoa_root)
    event_sequence_projection = graph_event_sequence_projection_recommendation(
        aoa_root=aoa_root,
        graph_store=graph_store,
        table_sizes=table_sizes,
    )
    graph_sqlite_plan = sqlite_vacuum_headroom_plan(
        db_path=graph_paths_payload["store"],
        method="vacuum-into",
        target_path=aoa_root / DIAGNOSTICS_ROOT / "graph.sqlite3.vacuum-copy",
        min_free_after_gb=GRAPH_SQLITE_COMPACT_DEFAULT_MIN_FREE_AFTER_GB,
    )
    search_sqlite_plan = sqlite_vacuum_headroom_plan(
        db_path=search_path,
        method="vacuum-into",
        target_path=aoa_root / DIAGNOSTICS_ROOT / "aoa-search.sqlite3.vacuum-copy",
        min_free_after_gb=SEARCH_SQLITE_COMPACT_DEFAULT_MIN_FREE_AFTER_GB,
    )
    search_shard_projection = session_memory_search_shard_projection_summary(aoa_root)
    search_raw_text_fallback = (
        search_shard_projection.get("raw_text_fallback_dependency")
        if isinstance(search_shard_projection.get("raw_text_fallback_dependency"), dict)
        else search_raw_text_fallback_route_packet(aoa_root=aoa_root)
    )
    sqlite_wal_reclaimable = int_value(graph_store.get("wal", {}).get("size_bytes") if isinstance(graph_store.get("wal"), dict) else 0) + int_value(
        search_store.get("wal", {}).get("size_bytes") if isinstance(search_store.get("wal"), dict) else 0
    )
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_storage_audit",
        "generated_at": now,
        "ok": True,
        "mutates": False,
        "aoa_root": str(aoa_root),
        "deep_dbstat": deep_dbstat,
        "row_counts": row_counts,
        "total": top_total,
        "top_level": top_level,
        "sessions": sessions,
        "graph_store": graph_store,
        "search_store": search_store,
        "recommendations": [
            {
                "id": "sqlite_wal_checkpoint",
                "status": "safe_live_route",
                "quality_tradeoff": "none_expected",
                "speed_tradeoff": "brief SQLite checkpoint lock; defers safely when readers or writers are active",
                "estimated_reclaimable_bytes": sqlite_wal_reclaimable,
                "estimated_reclaimable_human": human_size(sqlite_wal_reclaimable),
                "next_route": "run storage-maintenance --write-report to checkpoint graph/search WAL files",
            },
            {
                "id": "graph_compact_aggregate_payload",
                "status": graph_compaction["status"],
                "quality_tradeoff": "none_expected",
                "speed_tradeoff": "bounded graph packets hydrate refs on demand from contribution rows",
                "estimated_reclaimable_bytes": graph_compaction["estimated_reclaimable_bytes"],
                "estimated_reclaimable_human": graph_compaction["estimated_reclaimable_human"],
                "estimate_status": graph_compaction["estimate_status"],
                "aggregate_table_size_bytes": graph_compaction["aggregate_table_size_bytes"],
                "aggregate_table_size_human": graph_compaction["aggregate_table_size_human"],
                "sample_delta_ratio": graph_compaction.get("sample_delta_ratio"),
                "next_route": graph_compaction["next_route"],
            },
            {
                "id": "graph_event_sequence_edge_projection",
                "status": event_sequence_projection["status"],
                "quality_tradeoff": event_sequence_projection["quality_tradeoff"],
                "speed_tradeoff": event_sequence_projection["speed_tradeoff"],
                "policy": event_sequence_projection["policy"],
                "omitted_edge_types": event_sequence_projection["omitted_edge_types"],
                "sequence_edge_count": event_sequence_projection["sequence_edge_count"],
                "total_edge_count": event_sequence_projection["total_edge_count"],
                "stored_edge_rows": event_sequence_projection["stored_edge_rows"],
                "stored_edge_contrib_rows": event_sequence_projection["stored_edge_contrib_rows"],
                "edge_storage_bytes": event_sequence_projection["edge_storage_bytes"],
                "edge_storage_human": event_sequence_projection["edge_storage_human"],
                "estimated_reclaimable_bytes": event_sequence_projection["estimated_reclaimable_bytes"],
                "estimated_reclaimable_human": event_sequence_projection["estimated_reclaimable_human"],
                "estimate_status": event_sequence_projection["estimate_status"],
                "projection_status": event_sequence_projection["projection_status"],
                "next_route": event_sequence_projection["next_route"],
            },
            {
                "id": "graph_raw_ref_materialization_policy",
                "status": raw_ref_materialization["status"],
                "quality_tradeoff": raw_ref_materialization["quality_tradeoff"],
                "speed_tradeoff": raw_ref_materialization["speed_tradeoff"],
                "policy": raw_ref_materialization["policy"],
                "materialize_raw_ref_nodes": raw_ref_materialization["materialize_raw_ref_nodes"],
                "raw_ref_node_count": raw_ref_materialization["raw_ref_node_count"],
                "has_raw_ref_edge_count": raw_ref_materialization["has_raw_ref_edge_count"],
                "affected_row_count": raw_ref_materialization["affected_row_count"],
                "estimated_reclaimable_bytes": raw_ref_materialization["estimated_reclaimable_bytes"],
                "estimated_reclaimable_human": raw_ref_materialization["estimated_reclaimable_human"],
                "estimate_status": raw_ref_materialization["estimate_status"],
                "next_route": raw_ref_materialization["next_route"],
            },
            {
                "id": "graph_sqlite_physical_compaction",
                "status": graph_sqlite_plan["status"],
                "quality_tradeoff": "none_expected_for_vacuum_into_copy; raw/session evidence is untouched and live replacement requires --promote-copy integrity checks",
                "speed_tradeoff": "manual-bulk SQLite copy/rewrite; not an interactive query path",
                "estimated_reclaimable_bytes": graph_sqlite_plan["conservative_reclaimable_bytes"],
                "estimated_reclaimable_human": graph_sqlite_plan["conservative_reclaimable_human"],
                "required_free_human": graph_sqlite_plan["required_free_human"],
                "free_human": graph_sqlite_plan["free_human"],
                "min_free_after_human": graph_sqlite_plan["min_free_after_human"],
                "apply_ready": graph_sqlite_plan["apply_ready"],
                "next_route": "run graph-sqlite-compact --write-report for a read-only plan; use --apply --method vacuum-into --target-path with optional --promote-copy and --delete-backup-after-verify only when disk headroom is sufficient",
            },
            {"id": "search_sqlite_physical_compaction", **search_sqlite_physical_compaction_recommendation(search_sqlite_plan)},
            {
                "id": "search_raw_text_fallback_dependency",
                **search_raw_text_fallback_dependency_recommendation(search_raw_text_fallback),
            },
            {
                "id": "raw_block_offset_or_compressed_store",
                "status": "current_no_plain_duplicates" if raw_block_reclaim_bytes == 0 else "planned_safe_route",
                "quality_tradeoff": "none_if_raw refs and readers support offset/compressed blocks before cleanup",
                "estimated_reclaimable_bytes": raw_block_reclaim_bytes,
                "estimated_reclaimable_human": sessions.get("raw_block_duplication_candidate_human", "0 B"),
                "next_route": (
                    "none for plaintext raw-block duplicates; keep raw-block-ref-audit in storage verification and monitor compressed sidecar weight"
                    if raw_block_reclaim_bytes == 0
                    else "run raw-block-ref-audit all --limit 20 --sample-limit 80 --write-report, then raw-block-storage-compact all --skip-no-plain --limit 20 --estimate-compression --write-report before any apply"
                ),
            },
            {
                "id": "search_hot_store_v3",
                "status": search_policy_status,
                "quality_tradeoff": "none_expected; FTS keeps searchable text, compressed bodies hydrate snippets, full route postings stay normalized while hot rows keep bounded route previews and compact payload deltas",
                "raw_lexical_policy": search_raw_lexical_policy,
                "estimated_reclaimable_bytes": 0,
                "estimated_reclaimable_human": "0 B",
                "estimate_status": "requires_bounded_rebuild_benchmark" if search_policy_status != "bounded_policy_recorded" else "bounded_policy_recorded_residual_not_estimated",
                "next_route": "run search-index all with the bounded default raw lexical policy and compare storage-audit plus route-performance-baseline before considering deeper FTS sharding",
            },
        ],
        "stop_line": "Do not delete raw evidence. Prefer compact generated stores, offset refs, and rebuildable caches.",
    }
    if write_report:
        diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
        diagnostics_dir.mkdir(parents=True, exist_ok=True)
        stem = f"{compact_stamp()}__storage-audit"
        report_json = diagnostics_dir / f"{stem}.json"
        report_md = diagnostics_dir / f"{stem}.md"
        write_json(report_json, payload)
        write_markdown(report_md, storage_audit_markdown(payload))
        payload["report_json"] = str(report_json)
        payload["report_markdown"] = str(report_md)
    return payload


def storage_audit_markdown(payload: dict[str, Any]) -> str:
    lines = [
        "# Session Memory Storage Audit",
        "",
        f"- generated_at: `{payload.get('generated_at')}`",
        f"- aoa_root: `{payload.get('aoa_root')}`",
        f"- total: `{(payload.get('total') or {}).get('size_human') if isinstance(payload.get('total'), dict) else ''}`",
        f"- deep_dbstat: `{payload.get('deep_dbstat')}`",
        f"- row_counts: `{payload.get('row_counts')}`",
        "",
        "## Top Level",
        "",
        "| layer | size | path |",
        "| --- | ---: | --- |",
    ]
    for item in payload.get("top_level", []) if isinstance(payload.get("top_level"), list) else []:
        if isinstance(item, dict):
            lines.append(f"| `{item.get('label')}` | `{item.get('size_human')}` | `{item.get('path')}` |")
    sessions = payload.get("sessions") if isinstance(payload.get("sessions"), dict) else {}
    if sessions:
        lines.extend(["", "## Sessions", "", "| bucket | size |", "| --- | ---: |"])
        for key, item in (sessions.get("buckets") or {}).items() if isinstance(sessions.get("buckets"), dict) else []:
            if isinstance(item, dict):
                lines.append(f"| `{key}` | `{item.get('size_human')}` |")
        raw_block_storage = sessions.get("raw_block_storage") if isinstance(sessions.get("raw_block_storage"), dict) else {}
        if raw_block_storage:
            lines.extend(
                [
                    "",
                    "### Raw Block Storage",
                    "",
                    f"- plaintext_duplicate: `{raw_block_storage.get('plain_human')}`",
                    f"- compressed_sidecars: `{raw_block_storage.get('compressed_human')}`",
                    f"- other: `{raw_block_storage.get('other_human')}`",
                    f"- remaining_duplication_candidate: `{sessions.get('raw_block_duplication_candidate_human')}`",
                ]
            )
    for key in ("graph_store", "search_store"):
        store = payload.get(key) if isinstance(payload.get(key), dict) else {}
        if not store:
            continue
        wal = store.get("wal") if isinstance(store.get("wal"), dict) else {}
        lines.extend(
            [
                "",
                f"## {key}",
                "",
                f"- size: `{store.get('size_human')}`",
                f"- freelist: `{store.get('freelist_human')}`",
                f"- wal: `{wal.get('size_human')}`",
                f"- total_with_wal: `{store.get('total_with_wal_human')}`",
                f"- deep_dbstat_status: `{store.get('deep_dbstat_status')}`",
                f"- row_count_status: `{store.get('row_count_status')}`",
            ]
        )
        metadata = store.get("metadata") if isinstance(store.get("metadata"), dict) else {}
        if metadata:
            lines.extend(["", "| metadata | value |", "| --- | --- |"])
            for meta_key, meta_value in sorted(metadata.items()):
                lines.append(f"| `{meta_key}` | `{meta_value}` |")
        table_sizes = store.get("table_sizes") if isinstance(store.get("table_sizes"), list) else []
        if table_sizes:
            lines.extend(["", "| table | size |", "| --- | ---: |"])
            for item in table_sizes:
                if isinstance(item, dict):
                    lines.append(f"| `{item.get('name')}` | `{item.get('size_human')}` |")
        aggregate_sample = store.get("aggregate_payload_compaction_sample") if isinstance(store.get("aggregate_payload_compaction_sample"), dict) else {}
        if aggregate_sample:
            lines.extend(
                [
                    "",
                    "### Aggregate Payload Compaction Sample",
                    "",
                    f"- status: `{aggregate_sample.get('status')}`",
                    f"- sample_count: `{aggregate_sample.get('sample_count')}`",
                    f"- delta: `{human_size(int_value(aggregate_sample.get('delta_bytes')))}`",
                    f"- delta_ratio: `{aggregate_sample.get('delta_ratio')}`",
                ]
            )
    lines.extend(["", "## Recommendations", "", "| id | status | estimated reclaimable | next route |", "| --- | --- | ---: | --- |"])
    for item in payload.get("recommendations", []) if isinstance(payload.get("recommendations"), list) else []:
        if isinstance(item, dict):
            lines.append(f"| `{item.get('id')}` | `{item.get('status')}` | `{item.get('estimated_reclaimable_human')}` | {item.get('next_route')} |")
    lines.append("")
    return "\n".join(lines)


def storage_maintenance_markdown(payload: dict[str, Any]) -> str:
    lines = [
        "# Session Memory Storage Maintenance",
        "",
        f"- generated_at: `{payload.get('generated_at')}`",
        f"- ok: `{payload.get('ok')}`",
        f"- status: `{payload.get('status')}`",
        f"- mutates: `{payload.get('mutates')}`",
        f"- reclaimed: `{payload.get('reclaimed_human')}`",
        f"- stop_line: `{payload.get('stop_line')}`",
        "",
        "## WAL Checkpoints",
        "",
        "| target | status | reclaimed | diagnostics |",
        "| --- | --- | ---: | --- |",
    ]
    actions = payload.get("actions") if isinstance(payload.get("actions"), dict) else {}
    checkpoints = actions.get("sqlite_wal_checkpoint_truncate") if isinstance(actions.get("sqlite_wal_checkpoint_truncate"), dict) else {}
    for name, item in checkpoints.items():
        if not isinstance(item, dict):
            continue
        diagnostics = ", ".join(str(value) for value in item.get("diagnostics", []) if value) if isinstance(item.get("diagnostics"), list) else ""
        lines.append(f"| `{name}` | `{item.get('status')}` | `{item.get('reclaimed_human')}` | {diagnostics or 'none'} |")
    diagnostics = payload.get("diagnostics") if isinstance(payload.get("diagnostics"), list) else []
    if diagnostics:
        lines.extend(["", "## Diagnostics", ""])
        lines.extend(f"- `{item}`" for item in diagnostics)
    lines.append("")
    return "\n".join(lines)


def load_session_graph(aoa_root: Path, *, allow_ephemeral: bool = True) -> dict[str, Any]:
    paths = graph_paths(aoa_root)
    index = read_json(paths["index"], {})
    if paths["nodes"].exists() and paths["edges"].exists() and isinstance(index, dict) and index:
        commit_validation = graph_sidecar_commit_validation(
            aoa_root,
            index,
            verify_content=True,
            verify_store_semantics=True,
        )
        if commit_validation.get("ok"):
            nodes, node_diagnostics = read_jsonl_records(
                paths["nodes"]
            )
            edges, edge_diagnostics = read_jsonl_records(
                paths["edges"]
            )
            payload = dict(index)
            payload.update(
                {
                    "ok": (
                        bool(nodes)
                        and not node_diagnostics
                        and not edge_diagnostics
                    ),
                    "source": "sidecar",
                    "nodes": nodes,
                    "edges": edges,
                    "sidecar_commit_validation": commit_validation,
                    "diagnostics": (
                        list(index.get("diagnostics", []))
                        + node_diagnostics
                        + edge_diagnostics
                    ),
                }
            )
            return payload
        rejected_reasons = list(
            commit_validation.get("reasons") or []
        )
        if not allow_ephemeral:
            return {
                "schema_version": SCHEMA_VERSION,
                "artifact_type": "session_memory_graph_index",
                "graph_schema_version": GRAPH_SCHEMA_VERSION,
                "ok": False,
                "source": "rejected_sidecar",
                "nodes": [],
                "edges": [],
                "sidecar_commit_validation": commit_validation,
                "diagnostics": rejected_reasons,
            }
        payload = build_session_graph(
            aoa_root=aoa_root,
            write=False,
            include_rows=True,
        )
        payload["source"] = "ephemeral_after_sidecar_rejection"
        payload["sidecar_commit_validation"] = commit_validation
        payload.setdefault("diagnostics", []).extend(
            rejected_reasons
        )
        return payload
    if allow_ephemeral:
        payload = build_session_graph(aoa_root=aoa_root, write=False, include_rows=True)
        payload["source"] = "ephemeral_from_session_indexes"
        payload.setdefault("diagnostics", []).append("graph sidecar missing; built read-only ephemeral graph")
        return payload
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_index",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "ok": False,
        "source": "missing",
        "nodes": [],
        "edges": [],
        "diagnostics": ["graph sidecar missing; run graph-build --write outside read-only MCP"],
    }


def search_index_generated_at(aoa_root: Path) -> str:
    db_path = search_db_path(aoa_root)
    if not db_path.exists():
        return ""
    try:
        conn = sqlite3.connect(str(db_path))
        row = conn.execute("SELECT value FROM meta WHERE key = ?", ("generated_at",)).fetchone()
        conn.close()
    except sqlite3.Error:
        return ""
    return str(row[0] or "") if row else ""


def graph_freshness_scope_source_keys(
    aoa_root: Path,
    *,
    nodes: Iterable[dict[str, Any]] | None = None,
    edges: Iterable[dict[str, Any]] | None = None,
    max_source_keys: int = 128,
) -> dict[str, Any]:
    expected_generation_identity = (
        session_memory_expected_generation_identities(aoa_root)["graph"]
    )
    expected_generation_id = str(
        expected_generation_identity.get("generation_id") or ""
    )
    node_ids: list[str] = []
    for node in nodes or []:
        if not isinstance(node, dict):
            continue
        node_id = str(node.get("id") or "")
        node_type = str(node.get("type") or node.get("node_type") or "")
        evidence_bearing = bool(
            node_type == "event"
            or node.get("refs")
            or node.get("evidence_refs")
            or node.get("raw_ref")
            or node.get("segment_ref")
            or node.get("session_ref")
        )
        if node_id and evidence_bearing and node_id not in node_ids:
            node_ids.append(node_id)
    edge_ids: list[str] = []
    for edge in edges or []:
        if not isinstance(edge, dict):
            continue
        edge_id = str(edge.get("id") or "")
        if edge_id and edge_id not in edge_ids:
            edge_ids.append(edge_id)

    max_keys = max(1, min(int_value(max_source_keys, 128), 512))
    source_keys: set[str] = set()
    diagnostics: list[str] = []
    truncated = False
    db_path = graph_paths(aoa_root)["store"]
    if not db_path.exists():
        return {
            "status": "scope_store_missing",
            "source_keys": [],
            "node_id_count": len(node_ids),
            "edge_id_count": len(edge_ids),
            "source_key_count": 0,
            "truncated": False,
            "generation_status": "unresolved",
            "expected_generation_id": expected_generation_id,
            "diagnostics": ["graph_store_missing"],
        }

    conn: sqlite3.Connection | None = None
    source_generation_rows: list[dict[str, Any]] = []
    try:
        conn = sqlite3.connect(
            f"{db_path.resolve().as_uri()}?mode=ro",
            uri=True,
        )
        conn.row_factory = sqlite3.Row
        for table, column, identifiers in (
            ("node_contribs", "node_id", node_ids),
            ("edge_contribs", "edge_id", edge_ids),
        ):
            for offset in range(0, len(identifiers), 300):
                chunk = identifiers[offset : offset + 300]
                if not chunk:
                    continue
                remaining = max_keys + 1 - len(source_keys)
                if remaining <= 0:
                    truncated = True
                    break
                placeholders = ",".join("?" for _item in chunk)
                rows = conn.execute(
                    f"SELECT DISTINCT source_key FROM {table} WHERE {column} IN ({placeholders}) LIMIT ?",
                    (*chunk, remaining),
                ).fetchall()
                source_keys.update(str(row["source_key"] or "") for row in rows if str(row["source_key"] or ""))
                if len(source_keys) > max_keys:
                    truncated = True
                    break
            if truncated:
                break
        if source_keys:
            source_columns = {
                str(column[1])
                for column in conn.execute(
                    "PRAGMA table_info(graph_sources)"
                ).fetchall()
            }
            generation_id_expr = (
                "generation_id"
                if "generation_id" in source_columns
                else "''"
            )
            ordered_source_keys = sorted(source_keys)[:max_keys]
            for offset in range(0, len(ordered_source_keys), 300):
                chunk = ordered_source_keys[offset : offset + 300]
                placeholders = ",".join("?" for _item in chunk)
                source_generation_rows.extend(
                    {
                        "source_key": str(row["source_key"] or ""),
                        "generation_id": str(
                            row["generation_id"] or ""
                        ),
                        "status": str(row["status"] or ""),
                    }
                    for row in conn.execute(
                        f"""
                        SELECT source_key,
                               {generation_id_expr} AS generation_id,
                               status
                        FROM graph_sources
                        WHERE source_key IN ({placeholders})
                        """,
                        tuple(chunk),
                    ).fetchall()
                )
    except sqlite3.Error as exc:
        diagnostics.append(f"graph_scope_source_lookup_sqlite_error:{exc}")
    finally:
        if conn is not None:
            conn.close()

    ordered = sorted(source_keys)
    if len(ordered) > max_keys:
        ordered = ordered[:max_keys]
        truncated = True
    if truncated:
        diagnostics.append("graph_scope_source_lookup_truncated")
    resolved_generation_source_keys = {
        str(row.get("source_key") or "")
        for row in source_generation_rows
        if str(row.get("source_key") or "")
    }
    generation_mismatch_rows = [
        row
        for row in source_generation_rows
        if (
            str(row.get("generation_id") or "")
            != expected_generation_id
            or str(row.get("status") or "") != "current"
        )
    ]
    unresolved_generation_source_count = len(
        set(ordered) - resolved_generation_source_keys
    )
    generation_status = (
        "current"
        if (
            ordered
            and not truncated
            and not generation_mismatch_rows
            and not unresolved_generation_source_count
        )
        else (
            "stale"
            if generation_mismatch_rows
            else "unresolved"
        )
    )
    return {
        "status": "scope_sources_found" if ordered else "scope_sources_unresolved",
        "source_keys": ordered,
        "node_id_count": len(node_ids),
        "edge_id_count": len(edge_ids),
        "source_key_count": len(ordered),
        "truncated": truncated,
        "generation_status": generation_status,
        "expected_generation_id": expected_generation_id,
        "current_generation_source_count": (
            len(source_generation_rows) - len(generation_mismatch_rows)
        ),
        "generation_mismatch_source_count": len(
            generation_mismatch_rows
        ),
        "unresolved_generation_source_count": (
            unresolved_generation_source_count
        ),
        "generation_mismatch_samples": generation_mismatch_rows[:8],
        "diagnostics": diagnostics,
    }


def graph_freshness(
    aoa_root: Path,
    graph: dict[str, Any],
    *,
    scope_nodes: Iterable[dict[str, Any]] | None = None,
    scope_edges: Iterable[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    search_generated_at = search_index_generated_at(aoa_root)
    graph_generated_at = str(graph.get("generated_at") or "")
    source = str(graph.get("source") or "")
    scoped_projection = not source.startswith("sqlite_graph_store")
    scoped_nodes = (
        [item for item in scope_nodes if isinstance(item, dict)]
        if scoped_projection and scope_nodes is not None
        else [
            item
            for item in (
                graph.get("nodes")
                if scoped_projection and isinstance(graph.get("nodes"), list)
                else []
            )
            if isinstance(item, dict)
        ]
    )
    scoped_edges = (
        [item for item in scope_edges if isinstance(item, dict)]
        if scoped_projection and scope_edges is not None
        else [
            item
            for item in (
                graph.get("edges")
                if scoped_projection and isinstance(graph.get("edges"), list)
                else []
            )
            if isinstance(item, dict)
        ]
    )
    scoped_evidence_refs = (
        graph_collect_evidence(scoped_nodes, scoped_edges, limit=50)
        if scoped_projection
        else []
    )
    if scoped_projection:
        status = (
            "scope_unverified"
            if scoped_evidence_refs
            else "scope_unresolved"
        )
    else:
        status = "graph_store_current"
    store_query_state = (
        graph.get("store_state")
        if isinstance(graph.get("store_state"), dict)
        else (
            graph_store_query_state(aoa_root)
        )
    )
    if (
        source.startswith("sqlite_graph_store")
        and str(store_query_state.get("status") or "") != "current"
    ):
        status = "graph_store_stale"
    global_store_status = str(store_query_state.get("status") or "")
    if global_store_status == "current":
        scoped_global_status = (
            "current-generation-source-content-unverified"
        )
        scoped_global_recall_status = "unverified"
    elif global_store_status == "stale":
        scoped_global_status = "stale"
        scoped_global_recall_status = "partial_stale"
    else:
        scoped_global_status = "unresolved"
        scoped_global_recall_status = "unresolved"
    payload = {
        "status": status,
        "graph_source": source,
        "graph_generated_at": graph_generated_at,
        "search_index_generated_at": search_generated_at,
        "generation_identity": (
            store_query_state.get("generation_identity")
            if isinstance(
                store_query_state.get("generation_identity"),
                dict,
            )
            else {}
        ),
        "global_freshness": {
            "status": (
                scoped_global_status
                if scoped_projection
                else (
                    "current-generation-source-content-unverified"
                    if str(store_query_state.get("status") or "")
                    == "current"
                    else "stale"
                )
            )
            ,
            "store_state": store_query_state.get("status"),
            "reasons": store_query_state.get("reasons", []),
            "scope": "complete_graph_store",
        },
        "law": "freshness is a routing check; raw/segment refs remain stronger than graph packets",
    }
    if scoped_projection:
        payload.update(
            {
                "scope_status": status,
                "scope_basis": (
                    "non_store_navigation_refs_not_source_freshness_proof"
                ),
                "scope_node_count": len(scoped_nodes),
                "scope_edge_count": len(scoped_edges),
                "scope_evidence_ref_count": len(scoped_evidence_refs),
                "global_recall_status": scoped_global_recall_status,
                "scope_truth_status": (
                    "fresh construction time does not prove returned source "
                    "contributions or global graph recall are current"
                ),
                "scope_freshness": {
                    "status": status,
                    "evidence_ref_count": len(scoped_evidence_refs),
                    "coverage_truncated": bool(graph.get("truncated")),
                    "does_not_upgrade_global_freshness": True,
                },
            }
        )
        if not scoped_evidence_refs:
            payload["warning"] = (
                "bounded graph fallback returned no evidence-bearing navigation; "
                "scope and global graph freshness remain unresolved"
            )
    scope_requested = scope_nodes is not None or scope_edges is not None
    scope_lookup = (
        graph_freshness_scope_source_keys(
            aoa_root,
            nodes=scope_nodes,
            edges=scope_edges,
        )
        if source.startswith("sqlite_graph_store") and scope_requested
        else {}
    )
    if source.startswith("sqlite_graph_store"):
        try:
            scope_source_keys = (
                scope_lookup.get("source_keys")
                if isinstance(scope_lookup.get("source_keys"), list)
                else []
            )
            hot_state = (
                graph_store_hot_state(aoa_root, scope_source_keys=scope_source_keys)
                if scope_source_keys
                else graph_store_hot_state(aoa_root)
            )
            hot_status = graph_maintenance_status_from_state(
                hot_state,
                workspace_root=aoa_root.parent,
                aoa_root=aoa_root,
            )
            hot_diagnostics = (
                [str(item) for item in hot_state.get("diagnostics", []) if item]
                if isinstance(hot_state.get("diagnostics"), list)
                else []
            )
            payload.update(
                {
                    "hot_gate_status": hot_state.get("status"),
                    "needs_maintenance": bool(hot_state.get("needs_maintenance")),
                    "needs_full_rebuild": bool(hot_state.get("needs_full_rebuild")),
                    "actionable_graph_source_count": hot_status.get("actionable_count"),
                    "queued_graph_source_count": hot_status.get("queued_count"),
                    "deferred_live_source_count": hot_status.get("deferred_live_source_count"),
                    "ledger_store_missing_count": hot_status.get("ledger_store_missing_count"),
                    "latest_maintenance_remaining_count": hot_status.get("latest_maintenance_remaining_count"),
                    "latest_queue_maintenance_remaining_count": (
                        hot_status.get("latest_queue_maintenance", {}).get("remaining_count")
                        if isinstance(hot_status.get("latest_queue_maintenance"), dict)
                        else None
                    ),
                    "latest_queue_maintenance_selected_count": (
                        hot_status.get("latest_queue_maintenance", {}).get("selected_count")
                        if isinstance(hot_status.get("latest_queue_maintenance"), dict)
                        else None
                    ),
                    "latest_queue_maintenance_elapsed_ms": (
                        hot_status.get("latest_queue_maintenance", {}).get("elapsed_ms")
                        if isinstance(hot_status.get("latest_queue_maintenance"), dict)
                        else None
                    ),
                    "hot_gate_diagnostics": hot_diagnostics,
                    "maintenance_recommendation": hot_status.get("maintenance_recommendation", {}),
                }
            )
            if hot_state.get("needs_maintenance") or hot_state.get("needs_full_rebuild") or hot_diagnostics:
                payload["status"] = "graph_store_stale"
                payload["warning"] = "graph store has stale or incomplete hot-gate state; use graph packet as partial topology and verify through raw/segment refs"
            if scope_requested:
                scope = hot_state.get("scope") if isinstance(hot_state.get("scope"), dict) else {}
                scope_status = str(scope.get("status") or "scope_unverified")
                if scope_lookup.get("truncated"):
                    scope_status = "scope_unverified"
                scope_generation_status = str(
                    scope_lookup.get("generation_status")
                    or "unresolved"
                )
                if scope_generation_status == "stale":
                    scope_status = "scope_stale"
                elif scope_generation_status != "current":
                    scope_status = "scope_unverified"
                payload.update(
                    {
                        "scope_status": scope_status,
                        "scope_generation_status": (
                            scope_generation_status
                        ),
                        "scope_basis": "returned_evidence_contributions_plus_graph_source_ledger",
                        "scope_source_count": int_value(scope.get("source_count")),
                        "scope_current_source_count": int_value(scope.get("current_source_count")),
                        "scope_stale_source_count": int_value(scope.get("stale_source_count")),
                        "scope_deferred_live_source_count": int_value(scope.get("deferred_live_source_count")),
                        "scope_blocked_source_count": int_value(scope.get("blocked_source_count")),
                        "scope_unverified_source_count": int_value(scope.get("unverified_source_count")),
                        "scope_sources_sample": scope.get("sources_sample", []),
                        "scope_source_lookup": {
                            key: scope_lookup.get(key)
                            for key in (
                                "status",
                                "node_id_count",
                                "edge_id_count",
                                "source_key_count",
                                "truncated",
                                "generation_status",
                                "expected_generation_id",
                                "current_generation_source_count",
                                "generation_mismatch_source_count",
                                "unresolved_generation_source_count",
                                "generation_mismatch_samples",
                                "diagnostics",
                            )
                        },
                        "global_recall_status": (
                            "current"
                            if payload.get("status") == "graph_store_current"
                            else "partial_stale"
                            if payload.get("status") == "graph_store_stale"
                            else "unverified"
                        ),
                        "scope_truth_status": "scoped evidence freshness does not prove global graph recall or relation truth",
                        "scope_freshness": {
                            "status": scope_status,
                            "generation_status": (
                                scope_generation_status
                            ),
                            "source_count": int_value(
                                scope.get("source_count")
                            ),
                            "coverage_truncated": bool(
                                scope_lookup.get("truncated")
                            ),
                            "does_not_upgrade_global_freshness": True,
                        },
                    }
                )
        except Exception as exc:
            payload.update(
                {
                    "status": "graph_store_freshness_unverified",
                    "hot_gate_status": "unavailable",
                    "hot_gate_diagnostics": [f"graph_hot_gate_check_failed:{type(exc).__name__}"],
                }
            )
    return payload


def graph_store_query_state(aoa_root: Path) -> dict[str, Any]:
    paths = graph_paths(aoa_root)
    expected_generation_identity = (
        session_memory_expected_generation_identities(aoa_root)["graph"]
    )
    expected_generation_id = str(
        expected_generation_identity.get("generation_id") or ""
    )
    expected_entity_registry_dependency_id = str(
        graph_entity_registry_dependency_snapshot(
            aoa_root,
            ensure_current=False,
            allow_ephemeral=False,
        ).get("dependency_id")
        or ""
    )
    if not paths["store"].exists():
        return {
            "status": "missing",
            "db_path": str(paths["store"]),
            "metadata": {},
            "generation_identity": {
                "expected": expected_generation_identity,
                "observed_generation_id": "",
                "observed_identity": None,
                "compatible": False,
            },
            "diagnostics": ["graph_store_missing"],
        }
    try:
        conn = sqlite3.connect(
            f"{paths['store'].resolve().as_uri()}?mode=ro",
            uri=True,
        )
        conn.row_factory = sqlite3.Row
        try:
            table_names = {
                str(row["name"])
                for row in conn.execute(
                    "SELECT name FROM sqlite_master WHERE type = 'table'"
                ).fetchall()
            }
            metadata = (
                {
                    str(row["key"]): str(row["value"])
                    for row in conn.execute(
                        "SELECT key, value FROM metadata"
                    ).fetchall()
                }
                if "metadata" in table_names
                else {}
            )
            has_nodes = (
                conn.execute(
                    "SELECT 1 FROM nodes LIMIT 1"
                ).fetchone()
                is not None
                if "nodes" in table_names
                else False
            )
            has_edges = (
                conn.execute(
                    "SELECT 1 FROM edges LIMIT 1"
                ).fetchone()
                is not None
                if "edges" in table_names
                else False
            )
            source_version_state = (
                graph_source_version_state_from_connection(
                    conn,
                    sample_limit=8,
                    truth_status=(
                        "lightweight_readonly_graph_source_generation_summary"
                    ),
                    expected_generation_id=expected_generation_id,
                    expected_entity_registry_dependency_id=(
                        expected_entity_registry_dependency_id
                    ),
                )
                if "graph_sources" in table_names
                else graph_source_version_state_default_payload(
                    status="missing",
                    reason_group_counts={
                        "graph_sources_table_missing": 1
                    },
                    diagnostics=["graph_sources_table_missing"],
                    truth_status=(
                        "lightweight_readonly_graph_source_generation_summary"
                    ),
                    expected_generation_id=expected_generation_id,
                    expected_entity_registry_dependency_id=(
                        expected_entity_registry_dependency_id
                    ),
                )
            )
        finally:
            conn.close()
    except sqlite3.Error as exc:
        return {
            "status": "sqlite_error",
            "db_path": str(paths["store"]),
            "metadata": {},
            "generation_identity": {
                "expected": expected_generation_identity,
                "observed_generation_id": "",
                "observed_identity": None,
                "compatible": False,
            },
            "diagnostics": [f"graph_store_sqlite_error:{exc}"],
        }
    entity_registry_dependency_state = (
        graph_entity_registry_dependency_transition_state(
            aoa_root,
            str(
                metadata.get("entity_registry_dependency_id") or ""
            ),
            graph_entity_registry_dependency_from_metadata(
                metadata
            ),
        )
    )
    query_dependency_rebind_needed = bool(
        entity_registry_dependency_state.get("rebindable")
    )
    reasons: list[str] = []
    if int_value(metadata.get("graph_store_schema_version")) != GRAPH_STORE_SCHEMA_VERSION:
        reasons.append("graph_store_schema_mismatch")
    if int_value(metadata.get("graph_schema_version")) != GRAPH_SCHEMA_VERSION:
        reasons.append("graph_schema_mismatch")
    observed_generation_id = str(
        metadata.get("graph_generation_id") or ""
    )
    generation_compatible = (
        bool(expected_generation_id)
        and observed_generation_id == expected_generation_id
    )
    if not generation_compatible:
        reasons.append("graph_generation_mismatch")
    reasons.extend(
        str(reason)
        for reason in entity_registry_dependency_state.get(
            "reasons",
            [],
        )
        if reason
    )
    source_generation_mismatch_count = int_value(
        source_version_state.get("version_mismatch_source_count")
    )
    if source_generation_mismatch_count:
        reasons.append("graph_source_generation_or_version_mismatch")
    if not has_nodes:
        reasons.append("graph_store_nodes_empty")
    if not has_edges:
        reasons.append("graph_store_edges_empty")
    return {
        "status": "current" if not reasons else "stale",
        "db_path": str(paths["store"]),
        "db_mtime": path_mtime(paths["store"]),
        "metadata": metadata,
        "generation_identity": {
            "expected": expected_generation_identity,
            "observed_generation_id": observed_generation_id,
            "observed_identity": projection_generation_from_json(
                metadata.get("graph_generation_identity_json")
            ),
            "compatible": generation_compatible,
        },
        "entity_registry_dependency": (
            entity_registry_dependency_state
        ),
        "needs_dependency_rebind": (
            query_dependency_rebind_needed
        ),
        "source_version_state": source_version_state,
        "global_freshness": {
            "status": "current-generation"
            if not reasons
            else "stale",
            "generation_compatible": generation_compatible,
            "source_generation_mismatch_count": (
                source_generation_mismatch_count
            ),
            "entity_registry_dependency_compatible": (
                entity_registry_dependency_state.get("compatible")
            ),
            "source_content_freshness": "unverified_by_lightweight_route",
        },
        "reasons": reasons,
        "diagnostics": [],
        "query_scope": (
            "lightweight_store_generation_availability_not_full_source_dirty_audit"
        ),
    }


def graph_cardinality_projection_read(aoa_root: Path, *, limit: int = 40) -> dict[str, Any]:
    paths = graph_paths(aoa_root)
    bounded_limit = max(1, min(int_value(limit, 40), 200))
    if not paths["store"].exists():
        return {
            "status": "missing",
            "mutates": False,
            "db_path": str(paths["store"]),
            "counts": {"node": {}, "edge": {}},
            "top": {"node": [], "edge": []},
            "diagnostics": ["graph_store_missing"],
        }
    try:
        conn = sqlite3.connect(f"{paths['store'].resolve().as_uri()}?mode=ro", uri=True)
        conn.row_factory = sqlite3.Row
        try:
            table_exists = conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'graph_type_counts' LIMIT 1"
            ).fetchone() is not None
            if not table_exists:
                return {
                    "status": "projection_missing",
                    "mutates": False,
                    "db_path": str(paths["store"]),
                    "counts": {"node": {}, "edge": {}},
                    "top": {"node": [], "edge": []},
                    "diagnostics": ["graph_type_counts_projection_missing"],
                }
            metadata = {str(row["key"]): str(row["value"]) for row in conn.execute("SELECT key, value FROM metadata").fetchall()}
            counts: dict[str, dict[str, int]] = {}
            top: dict[str, list[dict[str, Any]]] = {}
            for kind in ("node", "edge"):
                rows = conn.execute(
                    "SELECT type, count FROM graph_type_counts WHERE kind = ? ORDER BY type",
                    (kind,),
                ).fetchall()
                counts[kind] = {str(row["type"] or "unknown"): int_value(row["count"]) for row in rows}
                top[kind] = [
                    {"type": str(row["type"] or "unknown"), "count": int_value(row["count"])}
                    for row in conn.execute(
                        "SELECT type, count FROM graph_type_counts WHERE kind = ? ORDER BY count DESC, type LIMIT ?",
                        (kind, bounded_limit),
                    ).fetchall()
                ]
            row = conn.execute("SELECT COUNT(*) FROM graph_type_counts").fetchone()
            row_count = int_value(row[0]) if row else 0
        finally:
            conn.close()
    except sqlite3.Error as exc:
        return {
            "status": "sqlite_error",
            "mutates": False,
            "db_path": str(paths["store"]),
            "counts": {"node": {}, "edge": {}},
            "top": {"node": [], "edge": []},
            "diagnostics": [sqlite_error_diagnostic(exc)],
        }
    status = "current" if str(metadata.get("graph_type_counts_status") or "") == "current" and row_count > 0 else "projection_missing"
    return {
        "status": status,
        "mutates": False,
        "db_path": str(paths["store"]),
        "row_count": row_count,
        "generated_at": metadata.get("graph_type_counts_generated_at", ""),
        "updated_at": metadata.get("graph_type_counts_updated_at", ""),
        "graph_updated_at": metadata.get("graph_type_counts_graph_updated_at", ""),
        "metadata": metadata,
        "counts": counts,
        "top": top,
        "diagnostics": [] if status == "current" else ["graph_type_counts_projection_missing"],
    }


def graph_cardinality(
    *,
    aoa_root: Path,
    refresh: bool = False,
    limit: int = 40,
) -> dict[str, Any]:
    started_at = time.monotonic()
    graph_state = graph_store_query_state(aoa_root)
    projection: dict[str, Any]
    mutates = bool(refresh)
    refresh_result: dict[str, Any] = {}
    if refresh:
        if graph_state.get("status") == "missing":
            projection = {
                "status": "missing",
                "mutates": False,
                "db_path": str(graph_paths(aoa_root)["store"]),
                "counts": {"node": {}, "edge": {}},
                "top": {"node": [], "edge": []},
                "diagnostics": ["graph_store_missing"],
            }
        elif graph_state.get("status") != "current":
            projection = {
                "status": "blocked",
                "mutates": False,
                "db_path": str(graph_paths(aoa_root)["store"]),
                "counts": {"node": {}, "edge": {}},
                "top": {"node": [], "edge": []},
                "diagnostics": [
                    "graph_store_not_current_for_cardinality_refresh",
                    *[
                        str(reason)
                        for reason in (
                            graph_state.get("reasons")
                            if isinstance(
                                graph_state.get("reasons"),
                                list,
                            )
                            else []
                        )
                        if reason
                    ],
                ],
            }
        else:
            store = GraphSqliteStore(aoa_root)
            try:
                projection = store.refresh_type_counts(limit=limit)
                refresh_result = {
                    "state_counts": store.state_counts(),
                    "metadata": {
                        key: store.metadata().get(key)
                        for key in (
                            "graph_type_counts_status",
                            "graph_type_counts_generated_at",
                            "graph_type_counts_updated_at",
                            "graph_type_counts_graph_updated_at",
                        )
                    },
                }
            finally:
                store.close()
    else:
        projection = graph_cardinality_projection_read(aoa_root, limit=limit)
    node_total = sum(int_value(value) for value in (projection.get("counts", {}).get("node", {}) if isinstance(projection.get("counts"), dict) else {}).values())
    edge_total = sum(int_value(value) for value in (projection.get("counts", {}).get("edge", {}) if isinstance(projection.get("counts"), dict) else {}).values())
    diagnostics = projection.get("diagnostics") if isinstance(projection.get("diagnostics"), list) else []
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_cardinality",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "graph_event_route_signal_edge_policy": GRAPH_EVENT_ROUTE_SIGNAL_EDGE_POLICY,
        "generated_at": utc_now(),
        "ok": str(projection.get("status") or "") == "current",
        "mutates": mutates,
        "refresh": refresh,
        "aoa_root": str(aoa_root),
        "graph_state": graph_state,
        "projection": projection,
        "node_count": node_total,
        "edge_count": edge_total,
        "top_node_types": (projection.get("top", {}) or {}).get("node", []) if isinstance(projection.get("top"), dict) else [],
        "top_edge_types": (projection.get("top", {}) or {}).get("edge", []) if isinstance(projection.get("top"), dict) else [],
        "refresh_result": refresh_result,
        "elapsed_ms": int((time.monotonic() - started_at) * 1000),
        "diagnostics": diagnostics,
        "next_route": (
            "use projection counts for graph size/cardinality questions"
            if str(projection.get("status") or "") == "current"
            else "run graph-cardinality --refresh through the heavy resource lane to materialize graph type counts"
        ),
    }
    if not payload["ok"]:
        payload["exact_next_command"] = (
            f"python3 scripts/aoa_session_memory.py graph-cardinality "
            f"--workspace-root {aoa_root.parent} --aoa-root {aoa_root} --refresh"
        )
    return payload


def graph_high_fanout_edge_policy_row(
    *,
    aoa_root: Path,
    edge_type: str,
    count: int,
    edge_total: int,
) -> dict[str, Any]:
    share = round(count / edge_total, 6) if edge_total > 0 else 0.0
    base = {
        "edge_type": edge_type,
        "count": count,
        "share": share,
        "high_fanout": count >= OPS_GRAPH_HIGH_FANOUT_EDGE_WARNING_COUNT,
        "can_prune_now": False,
        "replacement_required_before_prune": True,
        "authority_boundary": "graph edges are generated topology; raw/segment refs and owner source surfaces remain stronger",
    }
    if edge_type == "event_has_route_signal":
        return {
            **base,
            "class": "event_route_signal_fanout",
            "current_policy": GRAPH_EVENT_ROUTE_SIGNAL_EDGE_POLICY,
            "mitigation_status": "bounded_event_route_edges_with_segment_summary_replacement",
            "replacement_layers": ["segment_has_route_signal", "session_has_route_signal"],
            "compact_query_route": "graph-cooccurrence",
            "next_route": "Use graph-cooccurrence for dense operational anchors; rebuild stale graph sources only if this policy is missing from generated sources.",
            "example_command": f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} graph-cooccurrence <anchor> --aoa-root {aoa_root} --kind <kind> --limit 30",
        }
    if edge_type == "event_has_registered_entity_signal":
        return {
            **base,
            "class": "event_registered_entity_fanout",
            "current_policy": GRAPH_EVENT_ROUTE_SIGNAL_EDGE_POLICY,
            "mitigation_status": (
                "bounded_neutral_event_entity_signal_edges_preserve_refs"
            ),
            "replacement_layers": ["session_has_registered_entity", "usage-chain"],
            "compact_query_route": "usage-chain",
            "next_route": (
                "Keep event-level signal refs as navigation only; reduce only "
                "after a reviewed usage/rollup replacement preserves "
                "consequence and raw/segment refs."
            ),
            "example_command": f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} usage-chain <anchor> --aoa-root {aoa_root} --kind <kind>",
        }
    if edge_type in {"segment_has_route_signal", "session_has_route_signal", "session_has_registered_entity"}:
        return {
            **base,
            "class": "aggregate_summary_layer",
            "current_policy": "aggregate_summary_replacement_layer",
            "mitigation_status": "keep_as_compact_replacement_for_event_fanout",
            "replacement_layers": [],
            "compact_query_route": "search-operational-route-rollup-query",
            "next_route": "Keep this aggregate layer as compact navigation unless a stronger rollup replaces it with raw/segment refs.",
            "example_command": f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} search-operational-route-rollup-query <query> --aoa-root {aoa_root} --layer <layer>",
        }
    if edge_type in {
        "has_event",
        "answered_by",
        "responds_to",
        "has_correlated_status",
        "goal_lifecycle_has_event",
        "has_task_episode",
    }:
        return {
            **base,
            "class": "structural_event_chain",
            "current_policy": GRAPH_EVENT_RELATIONSHIP_EDGE_POLICY,
            "mitigation_status": "keep_bounded_query_routes_before_prune",
            "replacement_layers": ["agent-responses", "goal-lifecycles", "graph-timeline"],
            "compact_query_route": "graph-timeline",
            "next_route": "Use typed answer/goal/timeline routes before considering structural edge pruning.",
            "example_command": f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} graph-timeline <anchor> --aoa-root {aoa_root} --kind <kind> --limit 40",
        }
    return {
        **base,
        "class": "other_high_fanout_edge",
        "current_policy": "observe_before_mutation",
        "mitigation_status": "needs_targeted_policy_before_prune",
        "replacement_layers": [],
        "compact_query_route": "graph-cardinality",
        "next_route": "Measure the edge class and design a replacement route before any pruning.",
        "example_command": f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} graph-cardinality --aoa-root {aoa_root} --limit 20",
    }


def graph_entity_usage_replacement_corpus_profile(result: dict[str, Any]) -> dict[str, Any]:
    observed = result.get("observed") if isinstance(result.get("observed"), dict) else {}
    for profile in observed.get("profiles", []) if isinstance(observed.get("profiles"), list) else []:
        if isinstance(profile, dict) and profile.get("profile") == "graph_high_fanout_replacement":
            return profile
    return {}


def live_scenario_result_profile(result: dict[str, Any], profile_name: str) -> dict[str, Any]:
    observed = result.get("observed") if isinstance(result.get("observed"), dict) else {}
    for profile in observed.get("profiles", []) if isinstance(observed.get("profiles"), list) else []:
        if isinstance(profile, dict) and profile.get("profile") == profile_name:
            return profile
    return {}


def graph_entity_usage_replacement_report_min_source_mtime(aoa_root: Path) -> float:
    paths = [
        live_scenario_corpus_default_path(aoa_root),
        aoa_root / "scripts" / "aoa_session_memory.py",
    ]
    return max((path_mtime(path) for path in paths if path.exists()), default=0.0)


def refresh_episode_posting_cardinality_metadata(
    *,
    aoa_root: Path,
    limit: int | None = None,
    budget_seconds: float | None = None,
    write_report: bool = False,
) -> dict[str, Any]:
    """Backfill small per-session posting counts without rebuilding semantic episode rows."""
    started_at = time.monotonic()
    deadline = (
        started_at + max(0.0, float(budget_seconds))
        if budget_seconds is not None and float(budget_seconds) > 0
        else None
    )
    selected_limit = None if limit is None or int_value(limit) <= 0 else int_value(limit)
    db_path = search_db_path(aoa_root)
    diagnostics: list[str] = []
    completed_session_ids: list[str] = []
    selected_session_ids: list[str] = []
    processed_count = 0
    budget_exhausted = False
    if not db_path.exists():
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "session_memory_episode_posting_cardinality_metadata_refresh",
            "generated_at": utc_now(),
            "ok": False,
            "mutates": True,
            "status": "missing",
            "selected_count": 0,
            "processed_count": 0,
            "remaining_count": 0,
            "budget_exhausted": False,
            "diagnostics": ["search_index_missing"],
        }
    conn = init_search_db(db_path, rebuild=False, create_indexes=False)
    try:
        candidate_rows = conn.execute(
            "SELECT session_id FROM episode_semantic_session_state "
            "WHERE projection_version = ? AND route_signal_classifier_version = ? "
            "AND status IN ('current', 'no_task_episodes', 'no_admitted_episode_text') "
            "AND (posting_cardinality_metadata_version <> ? "
            "OR entity_posting_count < 0 OR direct_relation_posting_count < 0 "
            "OR posting_relation_counts_json = '') "
            "ORDER BY indexed_at, session_id",
            (
                EPISODE_SEMANTIC_PROJECTION_VERSION,
                ROUTE_SIGNAL_CLASSIFIER_VERSION,
                EPISODE_POSTING_CARDINALITY_METADATA_VERSION,
            ),
        ).fetchall()
        candidate_session_ids = [str(row["session_id"] or "") for row in candidate_rows if row["session_id"]]
        selected_session_ids = (
            candidate_session_ids
            if selected_limit is None
            else candidate_session_ids[:selected_limit]
        )
        for session_id in selected_session_ids:
            if deadline is not None and time.monotonic() >= deadline:
                budget_exhausted = True
                break
            relation_rows = conn.execute(
                "SELECT relation, COUNT(*) AS posting_count "
                "FROM episode_entity_postings WHERE session_id = ? "
                "GROUP BY relation ORDER BY relation",
                (session_id,),
            ).fetchall()
            relation_counts = {
                str(row["relation"] or "unknown"): int_value(row["posting_count"])
                for row in relation_rows
            }
            entity_posting_count = sum(relation_counts.values())
            direct_relation_posting_count = sum(
                int_value(relation_counts.get(relation))
                for relation in EPISODE_POSTINGS_COOCCURRENCE_DIRECT_RELATIONS
            )
            conn.execute(
                "UPDATE episode_semantic_session_state SET "
                "entity_posting_count = ?, direct_relation_posting_count = ?, "
                "posting_relation_counts_json = ?, posting_cardinality_metadata_version = ? "
                "WHERE session_id = ? AND projection_version = ? "
                "AND route_signal_classifier_version = ?",
                (
                    entity_posting_count,
                    direct_relation_posting_count,
                    json.dumps(dict(sorted(relation_counts.items())), ensure_ascii=False, separators=(",", ":")),
                    EPISODE_POSTING_CARDINALITY_METADATA_VERSION,
                    session_id,
                    EPISODE_SEMANTIC_PROJECTION_VERSION,
                    ROUTE_SIGNAL_CLASSIFIER_VERSION,
                ),
            )
            processed_count += 1
            completed_session_ids.append(session_id)
            if processed_count % 25 == 0:
                conn.commit()
        conn.commit()
        remaining_count = int_value(
            conn.execute(
                "SELECT COUNT(*) FROM episode_semantic_session_state "
                "WHERE projection_version = ? AND route_signal_classifier_version = ? "
                "AND status IN ('current', 'no_task_episodes', 'no_admitted_episode_text') "
                "AND (posting_cardinality_metadata_version <> ? "
                "OR entity_posting_count < 0 OR direct_relation_posting_count < 0 "
                "OR posting_relation_counts_json = '')",
                (
                    EPISODE_SEMANTIC_PROJECTION_VERSION,
                    ROUTE_SIGNAL_CLASSIFIER_VERSION,
                    EPISODE_POSTING_CARDINALITY_METADATA_VERSION,
                ),
            ).fetchone()[0]
        )
    except sqlite3.Error as exc:
        conn.rollback()
        diagnostics.append(sqlite_error_diagnostic(exc))
        remaining_count = 0
    finally:
        conn.close()
    if diagnostics:
        status = "failed"
    elif remaining_count <= 0:
        status = "current"
    elif budget_exhausted:
        status = "partial_budget_exhausted"
    else:
        status = "partial_limit"
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_episode_posting_cardinality_metadata_refresh",
        "generated_at": utc_now(),
        "ok": not diagnostics,
        "mutates": True,
        "status": status,
        "selected_count": len(selected_session_ids),
        "processed_count": processed_count,
        "completed_session_ids": completed_session_ids,
        "remaining_count": remaining_count,
        "budget_seconds": budget_seconds,
        "budget_exhausted": budget_exhausted,
        "posting_cardinality_metadata_version": EPISODE_POSTING_CARDINALITY_METADATA_VERSION,
        "count_basis": "per_session_grouped_physical_episode_entity_posting_rows",
        "truth_status": "generated_cardinality_metadata_refresh_not_relation_or_raw_truth",
        "diagnostics": diagnostics,
        "elapsed_ms": int((time.monotonic() - started_at) * 1000),
    }
    if write_report:
        stem = f"{compact_stamp()}__episode-posting-cardinality-metadata-refresh"
        report_json, report_md = reserve_diagnostic_report_paths(aoa_root / DIAGNOSTICS_ROOT, stem)
        write_json(report_json, payload)
        write_markdown(report_md, json_markdown_report("Episode Posting Cardinality Metadata Refresh", payload))
        payload["report_json"] = str(report_json)
        payload["report_md"] = str(report_md)
    return payload


def episode_direct_relation_postings_cardinality(aoa_root: Path) -> dict[str, Any]:
    """Read cheap per-session physical posting counts for the current classifier epoch."""
    started_at = time.monotonic()
    projection = episode_semantic_route_state(aoa_root)
    db_path = search_db_path(aoa_root)
    diagnostics = [
        *(str(item) for item in projection.get("diagnostics", []) if item),
        *(str(item) for item in projection.get("reasons", []) if item),
    ]
    relation_counts: Counter[str] = Counter()
    physical_all_posting_count = 0
    physical_direct_posting_count = 0
    current_epoch_session_count = 0
    metadata_complete_session_count = 0
    metadata_incomplete_session_ids: list[str] = []
    required_columns = {
        "entity_posting_count",
        "direct_relation_posting_count",
        "posting_relation_counts_json",
        "posting_cardinality_metadata_version",
        "projection_version",
        "route_signal_classifier_version",
        "status",
    }
    schema_available = False
    conn: sqlite3.Connection | None = None
    if db_path.exists():
        try:
            conn = connect_existing_search_db(db_path)
            schema_available = sqlite_table_exists(conn, "episode_semantic_session_state")
            columns = {
                str(row[1])
                for row in conn.execute("PRAGMA table_info(episode_semantic_session_state)").fetchall()
            } if schema_available else set()
            missing_columns = sorted(required_columns - columns)
            if missing_columns:
                diagnostics.extend(
                    f"episode_posting_cardinality_column_missing:{column}"
                    for column in missing_columns
                )
                core_columns = {
                    "session_id",
                    "projection_version",
                    "route_signal_classifier_version",
                    "status",
                }
                if core_columns.issubset(columns):
                    current_rows = conn.execute(
                        "SELECT session_id FROM episode_semantic_session_state "
                        "WHERE projection_version = ? AND route_signal_classifier_version = ? "
                        "AND status IN ('current', 'no_task_episodes', 'no_admitted_episode_text')",
                        (EPISODE_SEMANTIC_PROJECTION_VERSION, ROUTE_SIGNAL_CLASSIFIER_VERSION),
                    ).fetchall()
                    current_epoch_session_count = len(current_rows)
                    metadata_incomplete_session_ids.extend(
                        str(row["session_id"] or "")
                        for row in current_rows
                        if row["session_id"]
                    )
            else:
                state_rows = conn.execute(
                    "SELECT session_id, entity_posting_count, direct_relation_posting_count, "
                    "posting_relation_counts_json, posting_cardinality_metadata_version "
                    "FROM episode_semantic_session_state "
                    "WHERE projection_version = ? AND route_signal_classifier_version = ? "
                    "AND status IN ('current', 'no_task_episodes', 'no_admitted_episode_text')",
                    (EPISODE_SEMANTIC_PROJECTION_VERSION, ROUTE_SIGNAL_CLASSIFIER_VERSION),
                ).fetchall()
                current_epoch_session_count = len(state_rows)
                for row in state_rows:
                    session_id = str(row["session_id"] or "")
                    entity_count = int_value(row["entity_posting_count"], -1)
                    direct_count = int_value(row["direct_relation_posting_count"], -1)
                    metadata_version = int_value(row["posting_cardinality_metadata_version"])
                    try:
                        parsed_counts = json.loads(str(row["posting_relation_counts_json"] or ""))
                    except (TypeError, ValueError, json.JSONDecodeError):
                        parsed_counts = None
                    normalized_counts = {
                        str(relation): int_value(count)
                        for relation, count in parsed_counts.items()
                        if str(relation)
                    } if isinstance(parsed_counts, dict) else {}
                    counted_total = sum(normalized_counts.values())
                    counted_direct = sum(
                        int_value(normalized_counts.get(relation))
                        for relation in EPISODE_POSTINGS_COOCCURRENCE_DIRECT_RELATIONS
                    )
                    complete = bool(
                        metadata_version == EPISODE_POSTING_CARDINALITY_METADATA_VERSION
                        and entity_count >= 0
                        and direct_count >= 0
                        and counted_total == entity_count
                        and counted_direct == direct_count
                    )
                    if not complete:
                        if session_id:
                            metadata_incomplete_session_ids.append(session_id)
                        continue
                    metadata_complete_session_count += 1
                    physical_all_posting_count += entity_count
                    physical_direct_posting_count += direct_count
                    relation_counts.update(normalized_counts)
        except sqlite3.Error as exc:
            diagnostics.append(sqlite_error_diagnostic(exc))
            schema_available = False
        finally:
            if conn is not None:
                conn.close()
    else:
        diagnostics.append("search_index_missing")

    projection_status = str(projection.get("status") or "missing")
    indexed_session_count = int_value(projection.get("indexed_session_count"))
    covered_session_count = int_value(projection.get("covered_session_count"))
    projection_current = bool(
        projection_status == "current"
        and indexed_session_count > 0
        and covered_session_count >= indexed_session_count
        and current_epoch_session_count >= indexed_session_count
    )
    metadata_current = bool(
        projection_current
        and metadata_complete_session_count >= indexed_session_count
        and not metadata_incomplete_session_ids
    )
    if not schema_available:
        status = "missing"
    elif projection_status in {"missing", "stale"}:
        status = projection_status
    elif not projection_current or not metadata_current:
        status = "partial"
    else:
        status = "current"
    if not metadata_current and schema_available:
        diagnostics.append("episode_posting_cardinality_metadata_incomplete")
    excluded_non_direct_posting_count = max(
        0,
        physical_all_posting_count - physical_direct_posting_count,
    )
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_episode_direct_relation_postings_cardinality",
        "generated_at": utc_now(),
        "ok": status == "current",
        "mutates": False,
        "status": status,
        "proof_ready": status == "current",
        "current_epoch_only": True,
        "projection_name": "episode_entity_postings_direct_relations",
        "projection_status": projection_status,
        "projection": projection,
        "projection_version": EPISODE_SEMANTIC_PROJECTION_VERSION,
        "route_signal_classifier_version": ROUTE_SIGNAL_CLASSIFIER_VERSION,
        "posting_cardinality_metadata_version": EPISODE_POSTING_CARDINALITY_METADATA_VERSION,
        "indexed_session_count": indexed_session_count,
        "covered_session_count": covered_session_count,
        "current_epoch_session_count": current_epoch_session_count,
        "metadata_complete_session_count": metadata_complete_session_count,
        "metadata_incomplete_session_count": len(metadata_incomplete_session_ids),
        "metadata_incomplete_session_ids": metadata_incomplete_session_ids[:12],
        "physical_all_posting_count": physical_all_posting_count,
        "physical_direct_posting_count": physical_direct_posting_count,
        "excluded_non_direct_posting_count": excluded_non_direct_posting_count,
        "relation_counts": dict(sorted(relation_counts.items())),
        "direct_relations": sorted(EPISODE_POSTINGS_COOCCURRENCE_DIRECT_RELATIONS),
        "count_basis": "summed_per_session_physical_rows_written_with_current_episode_and_classifier_epoch",
        "truth_status": "generated_cardinality_watermarks_not_raw_or_relation_truth",
        "diagnostics": unique_preserving_order(diagnostics),
        "elapsed_ms": int((time.monotonic() - started_at) * 1000),
    }


def graph_route_signal_replacement_cardinality(aoa_root: Path) -> dict[str, Any]:
    """Combine the two physical read models that replace route-signal mention topology."""
    started_at = time.monotonic()
    direct_postings = episode_direct_relation_postings_cardinality(aoa_root)
    route_rollup = session_memory_operational_route_rollup_status(aoa_root=aoa_root)
    direct_current = bool(
        direct_postings.get("status") == "current"
        and direct_postings.get("proof_ready") is True
    )
    rollup_current = bool(
        route_rollup.get("status") == "current"
        and route_rollup.get("needs_refresh") is not True
        and int_value(route_rollup.get("source_mismatch_count")) == 0
        and int_value(route_rollup.get("route_rollup_row_count")) > 0
    )
    direct_count = int_value(direct_postings.get("physical_direct_posting_count"))
    rollup_count = int_value(route_rollup.get("route_rollup_row_count"))
    if direct_current and rollup_current:
        status = "current"
    elif str(direct_postings.get("status") or "") == "missing" and str(route_rollup.get("status") or "") == "missing":
        status = "missing"
    elif str(direct_postings.get("status") or "") == "stale":
        status = "stale"
    else:
        status = "partial"
    diagnostics = [
        *(str(item) for item in direct_postings.get("diagnostics", []) if item),
        *(str(item) for item in route_rollup.get("diagnostics", []) if item),
    ]
    if not direct_current:
        diagnostics.append("episode_direct_postings_cardinality_not_current")
    if not rollup_current:
        diagnostics.append("operational_route_rollup_not_current_for_cardinality")
    replacement_row_count = direct_count + rollup_count
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_route_signal_replacement_cardinality",
        "generated_at": utc_now(),
        "ok": status == "current",
        "mutates": False,
        "status": status,
        "proof_ready": status == "current",
        "target_projection": GRAPH_ROUTE_SIGNAL_REPLACEMENT_TARGET_PROJECTION,
        "after_count_source": "episode_direct_postings_plus_operational_route_rollup",
        "physical_direct_posting_count": direct_count,
        "operational_route_rollup_row_count": rollup_count,
        "replacement_row_count": replacement_row_count,
        "components": {
            "episode_entity_postings_direct_relations": direct_count,
            "operational_route_rollup_rows": rollup_count,
        },
        "episode_direct_postings": direct_postings,
        "operational_route_rollup": route_rollup,
        "count_basis": "physical_current_epoch_direct_postings_plus_current_operational_route_rollup_rows",
        "truth_status": "generated_cross_store_cardinality_comparison_not_relation_or_prune_truth",
        "diagnostics": unique_preserving_order(diagnostics),
        "elapsed_ms": int((time.monotonic() - started_at) * 1000),
    }


def graph_high_fanout_cardinality_edge_counts(
    edge_counts: dict[str, Any],
    edge_types: Sequence[str],
) -> dict[str, int]:
    return {
        str(edge_type): int_value(edge_counts.get(str(edge_type)))
        for edge_type in edge_types
        if str(edge_type)
    }


def graph_high_fanout_prune_applied_for_edge_types(
    metadata: dict[str, Any],
    edge_types: Sequence[str],
) -> bool:
    if not isinstance(metadata, dict):
        return False
    if str(metadata.get("graph_high_fanout_prune_policy") or "") != GRAPH_HIGH_FANOUT_PRUNE_POLICY:
        return False
    pruned = {
        str(item).strip()
        for item in str(metadata.get("graph_high_fanout_pruned_edge_types") or "").split(",")
        if str(item).strip()
    }
    required = {str(edge_type) for edge_type in edge_types if str(edge_type)}
    return bool(required) and required.issubset(pruned)


def graph_high_fanout_cardinality_target_comparison(
    *,
    edge_counts: dict[str, Any],
    node_counts: dict[str, Any] | None = None,
    target: dict[str, Any],
    prune_metadata: dict[str, Any] | None = None,
    replacement_cardinality: dict[str, Any] | None = None,
) -> dict[str, Any]:
    target_projection = str(target.get("target_projection") or "")
    before_edge_types = tuple(str(item) for item in target.get("before_edge_types", ()) if item)
    after_edge_types = tuple(str(item) for item in target.get("after_edge_types", ()) if item)
    physical_before_counts = graph_high_fanout_cardinality_edge_counts(
        edge_counts,
        before_edge_types,
    )
    before_counts = dict(physical_before_counts)
    physical_before_total = sum(physical_before_counts.values())
    before_count_source = "physical_graph_edge_type_counts"
    counterfactual_node_type = str(
        target.get("counterfactual_node_type") or ""
    )
    counterfactual_count = 0
    default_omitted_policy = bool(
        target.get("default_omitted_edge_policy")
    )
    if (
        physical_before_total <= 0
        and default_omitted_policy
        and set(before_edge_types).issubset(
            GRAPH_HIGH_FANOUT_DEFAULT_OMITTED_EDGE_TYPES
        )
        and counterfactual_node_type
    ):
        counterfactual_count = int_value(
            (node_counts or {}).get(counterfactual_node_type)
        )
        if counterfactual_count > 0 and len(before_edge_types) == 1:
            before_counts = {
                before_edge_types[0]: counterfactual_count
            }
            before_count_source = (
                "counterfactual_one_per_event_node_under_"
                "default_omitted_producer_policy"
            )
    after_count_source = str(target.get("after_count_source") or "graph_edge_type_counts")
    replacement_projection = replacement_cardinality if isinstance(replacement_cardinality, dict) else {}
    if after_count_source == "episode_direct_postings_plus_operational_route_rollup":
        components = (
            replacement_projection.get("components")
            if isinstance(replacement_projection.get("components"), dict)
            else {}
        )
        after_labels = tuple(str(item) for item in target.get("after_count_labels", ()) if item)
        after_counts = {
            label: int_value(components.get(label))
            for label in after_labels
        }
        after_edge_types = after_labels
    else:
        after_counts = graph_high_fanout_cardinality_edge_counts(edge_counts, after_edge_types)
    before_total = sum(before_counts.values())
    after_total = sum(after_counts.values())
    missing_before = [edge_type for edge_type in before_edge_types if int_value(before_counts.get(edge_type)) <= 0]
    missing_after = [edge_type for edge_type in after_edge_types if int_value(after_counts.get(edge_type)) <= 0]
    delta = before_total - after_total
    reduction_ratio = round(delta / before_total, 6) if before_total > 0 else 0.0
    replacement_projection_ready = bool(
        after_count_source != "episode_direct_postings_plus_operational_route_rollup"
        or (
            replacement_projection.get("status") == "current"
            and replacement_projection.get("proof_ready") is True
        )
    )
    post_prune_verified = (
        physical_before_total <= 0
        and before_count_source == "physical_graph_edge_type_counts"
        and not missing_after
        and after_total > 0
        and replacement_projection_ready
        and graph_high_fanout_prune_applied_for_edge_types(prune_metadata or {}, before_edge_types)
    )
    if post_prune_verified:
        status = "passed_post_prune"
        reason = "source high-fanout edge rows are already reviewed-pruned and replacement route edge counts remain materialized"
    elif not replacement_projection_ready:
        status = "blocked_replacement_projection_not_current"
        reason = "episode direct-postings and operational route-rollup cardinality must both be current before comparison"
    elif before_total <= 0:
        status = "failed"
        reason = (
            "source high-fanout edge count and declared counterfactual "
            "baseline are missing"
        )
    elif after_total <= 0 or missing_after:
        status = "failed"
        reason = "replacement route edge counts are missing"
    elif after_total >= before_total:
        status = "failed"
        reason = "replacement route cardinality is not smaller than source edge cardinality"
    else:
        status = "passed"
        reason = (
            "replacement route cardinality is smaller than the explicit "
            "default-omitted counterfactual broad edge baseline"
            if before_count_source.startswith("counterfactual_")
            else "replacement route cardinality is smaller than source edge cardinality"
        )
    rejected_edge_types = tuple(
        str(item)
        for item in target.get("rejected_after_edge_types", ())
        if item
    )
    rejected_counts = graph_high_fanout_cardinality_edge_counts(edge_counts, rejected_edge_types)
    rejected_total = sum(rejected_counts.values())
    rejected_candidate: dict[str, Any] = {}
    if rejected_edge_types:
        if before_total > 0 and rejected_total >= before_total:
            rejected_status = "failed"
            rejected_reason = "segment/session route-signal aggregate is larger than the source mention edge set"
        elif rejected_total > 0:
            rejected_status = "rejected"
            rejected_reason = "segment/session route-signal aggregate is not the selected direct-relation replacement"
        else:
            rejected_status = "missing"
            rejected_reason = "segment/session route-signal aggregate counts are unavailable"
        rejected_candidate = {
            "status": rejected_status,
            "after_edge_types": list(rejected_edge_types),
            "after_edge_counts": rejected_counts,
            "after_edge_count": rejected_total,
            "delta": before_total - rejected_total,
            "reduction_ratio": (
                round((before_total - rejected_total) / before_total, 6)
                if before_total > 0
                else 0.0
            ),
            "reason": rejected_reason,
            "truth_status": "measured_rejected_candidate_not_selected_replacement",
        }
    return {
        "target_projection": target_projection,
        "status": status,
        "passed": status in {"passed", "passed_post_prune"},
        "post_prune_verified": post_prune_verified,
        "proof_gate": GRAPH_HIGH_FANOUT_CARDINALITY_PROOF_GATE,
        "before_edge_types": list(before_edge_types),
        "after_edge_types": list(after_edge_types),
        "before_edge_counts": before_counts,
        "physical_before_edge_counts": physical_before_counts,
        "after_edge_counts": after_counts,
        "before_count_source": before_count_source,
        "configured_before_count_source": str(
            target.get("before_count_source") or ""
        ),
        "counterfactual_node_type": counterfactual_node_type,
        "counterfactual_node_count": counterfactual_count,
        "default_omitted_edge_policy": default_omitted_policy,
        "default_omitted_edge_types": sorted(
            GRAPH_HIGH_FANOUT_DEFAULT_OMITTED_EDGE_TYPES
        ),
        "after_count_source": after_count_source,
        "before_edge_count": before_total,
        "after_edge_count": after_total,
        "delta": delta,
        "reduction_ratio": reduction_ratio,
        "missing_before_edge_types": missing_before,
        "missing_after_edge_types": missing_after,
        "comparison_basis": target.get("comparison_basis"),
        "replacement_read_model": target.get("replacement_read_model"),
        "replacement_projection": replacement_projection,
        "rejected_candidate": rejected_candidate,
        "reason": reason,
    }


def graph_high_fanout_cardinality_comparison(
    *,
    aoa_root: Path,
    projection: dict[str, Any] | None = None,
    limit: int = 12,
    write_report: bool = False,
) -> dict[str, Any]:
    started_at = time.monotonic()
    selected_limit = max(1, min(int_value(limit, 12), 80))
    projection_payload = projection if isinstance(projection, dict) else graph_cardinality_projection_read(aoa_root, limit=selected_limit)
    counts = projection_payload.get("counts") if isinstance(projection_payload.get("counts"), dict) else {}
    node_counts = counts.get("node") if isinstance(counts.get("node"), dict) else {}
    edge_counts = counts.get("edge") if isinstance(counts.get("edge"), dict) else {}
    projection_status = str(projection_payload.get("status") or "unknown")
    prune_metadata = projection_payload.get("metadata") if isinstance(projection_payload.get("metadata"), dict) else {}
    route_signal_replacement_cardinality = graph_route_signal_replacement_cardinality(aoa_root)
    target_comparisons = [
        graph_high_fanout_cardinality_target_comparison(
            edge_counts=edge_counts,
            node_counts=node_counts,
            target=target,
            prune_metadata=prune_metadata,
            replacement_cardinality=(
                route_signal_replacement_cardinality
                if str(target.get("target_projection") or "") == GRAPH_ROUTE_SIGNAL_REPLACEMENT_TARGET_PROJECTION
                else None
            ),
        )
        for target in GRAPH_HIGH_FANOUT_CARDINALITY_TARGETS
    ]
    passed_targets = [item for item in target_comparisons if item.get("passed") is True]
    failed_targets = [item for item in target_comparisons if item.get("passed") is not True]
    blocked_targets = [
        item
        for item in failed_targets
        if str(item.get("status") or "").startswith("blocked_")
    ]
    post_prune_verified_targets = [item for item in target_comparisons if item.get("post_prune_verified") is True]
    before_total = sum(int_value(item.get("before_edge_count")) for item in target_comparisons)
    after_total = sum(int_value(item.get("after_edge_count")) for item in target_comparisons)
    delta = before_total - after_total
    reduction_ratio = round(delta / before_total, 6) if before_total > 0 else 0.0
    if projection_status != "current":
        status = "blocked_cardinality_projection_not_current"
        ok = False
        gate_status = "blocked"
        reason = "graph cardinality projection must be current before before/after comparison can be trusted"
    elif blocked_targets:
        status = "blocked_replacement_projection_not_current"
        ok = False
        gate_status = "blocked"
        reason = "one or more replacement read models are not current enough for global cardinality proof"
    elif not target_comparisons:
        status = "not_needed"
        ok = True
        gate_status = "not_needed"
        reason = "no high-fanout cardinality target projections are configured"
    elif failed_targets:
        status = "not_proven"
        ok = False
        gate_status = "failed"
        reason = "one or more target projections do not yet prove lower cardinality"
    else:
        status = "proven"
        ok = True
        gate_status = "passed"
        if post_prune_verified_targets and before_total <= 0:
            reason = "all configured high-fanout replacement projections are verified in post-prune mode"
        else:
            reason = "all configured high-fanout replacement projections prove lower cardinality"
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_high_fanout_cardinality_comparison",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": ok,
        "mutates": False,
        "status": status,
        "projection_status": projection_status,
        "target_count": len(target_comparisons),
        "passed_target_count": len(passed_targets),
        "failed_target_count": len(failed_targets),
        "blocked_target_count": len(blocked_targets),
        "post_prune_mode": bool(post_prune_verified_targets),
        "post_prune_verified_target_count": len(post_prune_verified_targets),
        "target_projections": [str(item.get("target_projection") or "") for item in target_comparisons if item.get("target_projection")],
        "proven_target_projections": [str(item.get("target_projection") or "") for item in passed_targets if item.get("target_projection")],
        "failed_target_projections": [str(item.get("target_projection") or "") for item in failed_targets if item.get("target_projection")],
        "target_comparisons": target_comparisons,
        "route_signal_replacement_cardinality": route_signal_replacement_cardinality,
        "before_edge_count": before_total,
        "after_edge_count": after_total,
        "delta": delta,
        "reduction_ratio": reduction_ratio,
        "comparison_gate": {
            "id": GRAPH_HIGH_FANOUT_CARDINALITY_PROOF_GATE,
            "status": gate_status,
            "passed": gate_status == "passed",
            "reason": reason,
        },
        "prune_gate": {
            "status": "blocked_read_only_cardinality_proof_not_apply_route",
            "apply_ready": False,
            "can_prune_now": False,
            "reason": "cardinality comparison is route evidence only; graph-row pruning still requires an explicit reviewed apply route and before/after mutation report",
            "required_before_apply": [
                "explicit_apply_route_with_before_after_report",
                "operator_reviewed_mutation_boundary",
            ],
            "mutation_boundary": "read_only_cardinality_comparison_no_graph_rows_are_deleted_or_rebuilt",
        },
        "projection_metadata": {
            "generated_at": projection_payload.get("generated_at"),
            "updated_at": projection_payload.get("updated_at"),
            "graph_updated_at": projection_payload.get("graph_updated_at"),
            "row_count": projection_payload.get("row_count"),
            "graph_high_fanout_prune_policy": prune_metadata.get("graph_high_fanout_prune_policy"),
            "graph_high_fanout_pruned_at": prune_metadata.get("graph_high_fanout_pruned_at"),
            "graph_high_fanout_pruned_edge_types": prune_metadata.get("graph_high_fanout_pruned_edge_types"),
        },
        "storage_scope": "cardinality_projection_only_not_physical_sqlite_shrink",
        "truth_status": "generated_cardinality_comparison_not_prune_permission",
        "exact_read_command": f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} graph-high-fanout-cardinality-comparison --workspace-root {aoa_root.parent} --aoa-root {aoa_root} --limit {selected_limit}",
        "authority_boundary": "cardinality comparison is generated route guidance; raw/segment refs and owner source surfaces remain stronger",
        "elapsed_ms": int((time.monotonic() - started_at) * 1000),
        "diagnostics": projection_payload.get("diagnostics", []) if isinstance(projection_payload.get("diagnostics"), list) else [],
    }
    if write_report:
        stem = f"{compact_stamp()}__graph-high-fanout-cardinality-comparison"
        report_json, report_md = reserve_diagnostic_report_paths(aoa_root / DIAGNOSTICS_ROOT, stem)
        write_json(report_json, payload)
        write_markdown(report_md, json_markdown_report("Graph High-Fanout Cardinality Comparison", payload))
        payload["report_json"] = str(report_json)
        payload["report_md"] = str(report_md)
    return payload


def graph_high_fanout_merge_cardinality_comparison(
    proof_states: dict[str, Any],
    comparison: dict[str, Any],
) -> dict[str, Any]:
    target_by_projection = {
        str(item.get("target_projection") or ""): item
        for item in comparison.get("target_comparisons", [])
        if isinstance(item, dict) and item.get("target_projection")
    } if isinstance(comparison.get("target_comparisons"), list) else {}
    merged: dict[str, Any] = {}
    for target_projection, proof_state in proof_states.items():
        if not isinstance(proof_state, dict):
            merged[target_projection] = proof_state
            continue
        updated = dict(proof_state)
        target_comparison = target_by_projection.get(str(target_projection))
        if isinstance(target_comparison, dict):
            updated["cardinality_comparison"] = target_comparison
            if proof_state.get("status") == "proven" and target_comparison.get("passed") is True:
                gates = {
                    str(gate)
                    for gate in updated.get("proven_gates", [])
                    if gate
                }
                gates.add(GRAPH_HIGH_FANOUT_CARDINALITY_PROOF_GATE)
                updated["proven_gates"] = sorted(gates)
                if isinstance(updated.get("still_missing_gates"), list):
                    updated["still_missing_gates"] = [
                        str(gate)
                        for gate in updated.get("still_missing_gates", [])
                        if str(gate) != GRAPH_HIGH_FANOUT_CARDINALITY_PROOF_GATE
                    ]
        merged[target_projection] = updated
    return merged


def graph_route_signal_replacement_corpus_evidence(aoa_root: Path) -> dict[str, Any]:
    required_mtime = graph_entity_usage_replacement_report_min_source_mtime(aoa_root)
    graph_store_mtime = path_mtime(graph_paths(aoa_root)["store"])
    stale_reports = 0
    incomplete_reports = 0
    for report in diagnostic_json_payloads(aoa_root, "*__live-scenario-corpus-check.json", limit=20):
        source = diagnostic_report_source(report)
        report_mtime = ops_float_value(report.get("_diagnostic_mtime"))
        if required_mtime and report_mtime < required_mtime:
            stale_reports += 1
            continue
        results = report.get("results") if isinstance(report.get("results"), list) else []
        result_by_id = {
            str(item.get("id") or ""): item
            for item in results
            if isinstance(item, dict) and item.get("id")
        }
        cooccurrence_result = result_by_id.get(GRAPH_ROUTE_SIGNAL_COOCCURRENCE_CORPUS_CASE_ID)
        rollup_result = result_by_id.get(GRAPH_ROUTE_SIGNAL_ROLLUP_CORPUS_CASE_ID)
        if not isinstance(cooccurrence_result, dict) or not isinstance(rollup_result, dict):
            incomplete_reports += 1
            continue
        cooccurrence_profile = live_scenario_result_profile(cooccurrence_result, "graph_cooccurrence")
        rollup_profile = live_scenario_result_profile(rollup_result, "route_rollup_query")
        cooccurrence_refs = (
            cooccurrence_profile.get("evidence_ref_counts")
            if isinstance(cooccurrence_profile.get("evidence_ref_counts"), dict)
            else {}
        )
        rollup_refs = (
            rollup_profile.get("evidence_ref_counts")
            if isinstance(rollup_profile.get("evidence_ref_counts"), dict)
            else {}
        )
        cooccurrence_ok = (
            cooccurrence_result.get("ok") is True
            and cooccurrence_profile.get("status") == "passed"
            and cooccurrence_profile.get("source") == "episode_entity_postings_direct_relations"
            and cooccurrence_profile.get("cooccurrence_basis") == "same_task_episode_direct_typed_relations"
            and cooccurrence_profile.get("bounded_store_query") is True
            and cooccurrence_profile.get("uses_episode_entity_postings") is True
            and cooccurrence_profile.get("uses_graph_store") is False
            and cooccurrence_profile.get("uses_mention_or_reference_relations") is False
            and cooccurrence_profile.get("freshness_status") == "current"
            and cooccurrence_profile.get("abstention_status") == "not_required"
            and int_value(cooccurrence_profile.get("anchor_event_count")) > 0
            and int_value(cooccurrence_profile.get("cooccurrence_count")) > 0
            and int_value(cooccurrence_profile.get("evidence_ref_count")) > 0
            and int_value(cooccurrence_refs.get("raw_ref")) > 0
            and int_value(cooccurrence_refs.get("segment_ref")) > 0
            and int_value(cooccurrence_refs.get("session_ref")) > 0
        )
        rollup_ok = (
            rollup_result.get("ok") is True
            and rollup_profile.get("status") == "passed"
            and rollup_profile.get("uses_materialized_route_rollup") is True
            and rollup_profile.get("resamples_shards") is False
            and rollup_profile.get("opens_monolith") is False
            and rollup_profile.get("uses_fts") is False
            and rollup_profile.get("hydrates_body") is False
            and rollup_profile.get("raw_or_segment_ref_present") is True
            and rollup_profile.get("freshness_status") == "current"
            and rollup_profile.get("needs_refresh") is not True
            and int_value(rollup_profile.get("result_count")) > 0
            and int_value(rollup_profile.get("matched_group_count")) > 0
            and int_value(rollup_refs.get("raw_ref")) > 0
            and int_value(rollup_refs.get("segment_ref")) > 0
        )
        if cooccurrence_ok and rollup_ok:
            return {
                "status": "proven",
                "case_ids": list(GRAPH_ROUTE_SIGNAL_REPLACEMENT_CORPUS_CASE_IDS),
                "target_projection": GRAPH_ROUTE_SIGNAL_REPLACEMENT_TARGET_PROJECTION,
                "proven_gates": sorted(GRAPH_ROUTE_SIGNAL_REPLACEMENT_PROVEN_GATES),
                "source": source,
                "freshness_basis": "corpus_and_route_code",
                "graph_store_mtime_observed": graph_store_mtime,
                "graph_store_mtime_is_blocking": False,
                "cooccurrence_anchor_event_count": int_value(cooccurrence_profile.get("anchor_event_count")),
                "cooccurrence_count": int_value(cooccurrence_profile.get("cooccurrence_count")),
                "cooccurrence_evidence_ref_count": int_value(cooccurrence_profile.get("evidence_ref_count")),
                "cooccurrence_source": cooccurrence_profile.get("source"),
                "cooccurrence_basis": cooccurrence_profile.get("cooccurrence_basis"),
                "cooccurrence_uses_episode_entity_postings": cooccurrence_profile.get("uses_episode_entity_postings"),
                "cooccurrence_uses_graph_store": cooccurrence_profile.get("uses_graph_store"),
                "cooccurrence_uses_mention_or_reference_relations": cooccurrence_profile.get("uses_mention_or_reference_relations"),
                "cooccurrence_freshness_status": cooccurrence_profile.get("freshness_status"),
                "route_rollup_result_count": int_value(rollup_profile.get("result_count")),
                "route_rollup_matched_group_count": int_value(rollup_profile.get("matched_group_count")),
                "route_rollup_freshness_status": rollup_profile.get("freshness_status"),
                "route_rollup_uses_materialized_projection": rollup_profile.get("uses_materialized_route_rollup"),
                "route_rollup_opens_monolith": rollup_profile.get("opens_monolith"),
                "route_rollup_uses_fts": rollup_profile.get("uses_fts"),
                "route_rollup_hydrates_body": rollup_profile.get("hydrates_body"),
                "fallback_routes": ["graph-cooccurrence", "search-operational-route-rollup-query"],
                "truth_status": "generated_live_scenario_corpus_evidence_not_prune_permission",
            }
        return {
            "status": "not_proven",
            "case_ids": list(GRAPH_ROUTE_SIGNAL_REPLACEMENT_CORPUS_CASE_IDS),
            "target_projection": GRAPH_ROUTE_SIGNAL_REPLACEMENT_TARGET_PROJECTION,
            "proven_gates": [],
            "source": source,
            "freshness_basis": "corpus_and_route_code",
            "graph_store_mtime_observed": graph_store_mtime,
            "graph_store_mtime_is_blocking": False,
            "cooccurrence_ok": cooccurrence_ok,
            "route_rollup_ok": rollup_ok,
            "cooccurrence_status": cooccurrence_profile.get("status"),
            "route_rollup_status": rollup_profile.get("status"),
            "cooccurrence_failures": (
                cooccurrence_result.get("failures")
                if isinstance(cooccurrence_result.get("failures"), list)
                else []
            ),
            "route_rollup_failures": (
                rollup_result.get("failures")
                if isinstance(rollup_result.get("failures"), list)
                else []
            ),
            "truth_status": "latest_live_scenario_corpus_cases_do_not_prove_route_signal_replacement",
        }
    return {
        "status": "stale_or_missing",
        "case_ids": list(GRAPH_ROUTE_SIGNAL_REPLACEMENT_CORPUS_CASE_IDS),
        "target_projection": GRAPH_ROUTE_SIGNAL_REPLACEMENT_TARGET_PROJECTION,
        "proven_gates": [],
        "stale_report_count": stale_reports,
        "incomplete_report_count": incomplete_reports,
        "required_min_source_mtime": required_mtime,
        "freshness_basis": "corpus_and_route_code",
        "graph_store_mtime_observed": graph_store_mtime,
        "graph_store_mtime_is_blocking": False,
        "exact_refresh_command": live_scenario_corpus_check_command_for_cases(
            aoa_root,
            GRAPH_ROUTE_SIGNAL_REPLACEMENT_CORPUS_CASE_IDS,
        ),
        "truth_status": "missing_current_live_scenario_corpus_evidence",
    }


def graph_structural_event_chain_corpus_evidence(aoa_root: Path) -> dict[str, Any]:
    required_mtime = graph_entity_usage_replacement_report_min_source_mtime(aoa_root)
    graph_store_mtime = path_mtime(graph_paths(aoa_root)["store"])
    stale_reports = 0
    incomplete_reports = 0
    for report in diagnostic_json_payloads(aoa_root, "*__live-scenario-corpus-check.json", limit=20):
        source = diagnostic_report_source(report)
        report_mtime = ops_float_value(report.get("_diagnostic_mtime"))
        if required_mtime and report_mtime < required_mtime:
            stale_reports += 1
            continue
        results = report.get("results") if isinstance(report.get("results"), list) else []
        result_by_id = {
            str(item.get("id") or ""): item
            for item in results
            if isinstance(item, dict) and item.get("id")
        }
        goal_result = result_by_id.get(GRAPH_STRUCTURAL_GOAL_LIFECYCLE_CORPUS_CASE_ID)
        closeout_result = result_by_id.get(GRAPH_STRUCTURAL_AGENT_CLOSEOUT_CORPUS_CASE_ID)
        timeline_result = result_by_id.get(GRAPH_STRUCTURAL_TIMELINE_CORPUS_CASE_ID)
        if not isinstance(goal_result, dict) or not isinstance(closeout_result, dict) or not isinstance(timeline_result, dict):
            incomplete_reports += 1
            continue
        goal_profile = live_scenario_result_profile(goal_result, "goal_lifecycle")
        closeout_profile = live_scenario_result_profile(closeout_result, "agent_closeout")
        timeline_profile = live_scenario_result_profile(timeline_result, "graph_timeline")
        goal_refs = (
            goal_profile.get("evidence_ref_counts")
            if isinstance(goal_profile.get("evidence_ref_counts"), dict)
            else {}
        )
        closeout_refs = (
            closeout_profile.get("evidence_ref_counts")
            if isinstance(closeout_profile.get("evidence_ref_counts"), dict)
            else {}
        )
        timeline_refs = (
            timeline_profile.get("evidence_ref_counts")
            if isinstance(timeline_profile.get("evidence_ref_counts"), dict)
            else {}
        )
        work_chain_routes = (
            goal_profile.get("work_chain_next_route_counts")
            if isinstance(goal_profile.get("work_chain_next_route_counts"), dict)
            else {}
        )
        goal_ok = (
            goal_result.get("ok") is True
            and goal_profile.get("status") == "passed"
            and int_value(goal_profile.get("result_count")) > 0
            and int_value(goal_profile.get("work_chain_linked_count")) > 0
            and int_value(goal_profile.get("work_chain_episode_count")) > 0
            and int_value(goal_profile.get("work_chain_goal_event_ref_count")) > 0
            and int_value(goal_profile.get("work_chain_answer_ref_count")) > 0
            and int_value(goal_profile.get("work_chain_closeout_ref_count")) > 0
            and int_value(work_chain_routes.get("task-episodes")) > 0
            and int_value(work_chain_routes.get("answer-neighborhood")) > 0
            and int_value(work_chain_routes.get("agent-reasoning-windows")) > 0
            and goal_profile.get("work_chain_uses_search") is False
            and goal_profile.get("work_chain_uses_graph") is False
            and goal_profile.get("work_chain_opens_raw") is False
            and goal_profile.get("work_chain_hydrates_body") is False
            and int_value(goal_refs.get("raw_ref")) > 0
            and int_value(goal_refs.get("segment_ref")) > 0
        )
        closeout_ok = (
            closeout_result.get("ok") is True
            and closeout_profile.get("status") == "passed"
            and int_value(closeout_profile.get("result_count")) > 0
            and int_value(closeout_refs.get("raw_ref")) > 0
            and int_value(closeout_refs.get("segment_ref")) > 0
        )
        timeline_failures = (
            timeline_result.get("failures")
            if isinstance(timeline_result.get("failures"), list)
            else []
        )
        timeline_only_stale_failure = bool(timeline_failures) and all(
            str(item).startswith("graph_timeline:graph_timeline_current:")
            for item in timeline_failures
        )
        timeline_ok = (
            (timeline_result.get("ok") is True or timeline_only_stale_failure)
            and timeline_profile.get("status") == "passed"
            and int_value(timeline_profile.get("event_count")) > 0
            and int_value(timeline_profile.get("evidence_ref_count")) > 0
            and int_value(timeline_refs.get("raw_ref")) > 0
            and int_value(timeline_refs.get("segment_ref")) > 0
            and timeline_profile.get("timeline_ordered") is True
            and str(timeline_profile.get("timeline_source") or "") == "sqlite_graph_store_direct_timeline"
            and bool(timeline_profile.get("freshness_status"))
        )
        if goal_ok and closeout_ok and timeline_ok:
            return {
                "status": "proven",
                "case_ids": list(GRAPH_STRUCTURAL_EVENT_CHAIN_CORPUS_CASE_IDS),
                "target_projection": GRAPH_STRUCTURAL_EVENT_CHAIN_TARGET_PROJECTION,
                "proven_gates": sorted(GRAPH_STRUCTURAL_EVENT_CHAIN_PROVEN_GATES),
                "still_missing_gates": [
                    "before_after_cardinality_comparison",
                ],
                "source": source,
                "freshness_basis": "corpus_and_route_code",
                "graph_store_mtime_observed": graph_store_mtime,
                "graph_store_mtime_is_blocking": False,
                "goal_result_count": int_value(goal_profile.get("result_count")),
                "work_chain_linked_count": int_value(goal_profile.get("work_chain_linked_count")),
                "work_chain_episode_count": int_value(goal_profile.get("work_chain_episode_count")),
                "work_chain_goal_event_ref_count": int_value(goal_profile.get("work_chain_goal_event_ref_count")),
                "work_chain_answer_ref_count": int_value(goal_profile.get("work_chain_answer_ref_count")),
                "work_chain_closeout_ref_count": int_value(goal_profile.get("work_chain_closeout_ref_count")),
                "work_chain_next_route_counts": dict(work_chain_routes),
                "work_chain_uses_search": goal_profile.get("work_chain_uses_search"),
                "work_chain_uses_graph": goal_profile.get("work_chain_uses_graph"),
                "work_chain_opens_raw": goal_profile.get("work_chain_opens_raw"),
                "work_chain_hydrates_body": goal_profile.get("work_chain_hydrates_body"),
                "agent_closeout_result_count": int_value(closeout_profile.get("result_count")),
                "timeline_event_count": int_value(timeline_profile.get("event_count")),
                "timeline_evidence_ref_count": int_value(timeline_profile.get("evidence_ref_count")),
                "timeline_source": timeline_profile.get("timeline_source"),
                "timeline_ordered": timeline_profile.get("timeline_ordered"),
                "timeline_freshness_status": timeline_profile.get("freshness_status"),
                "timeline_needs_maintenance": timeline_profile.get("needs_maintenance"),
                "timeline_result_ok": timeline_result.get("ok"),
                "timeline_only_stale_failure": timeline_only_stale_failure,
                "fallback_routes": ["goal-lifecycles", "task-episodes", "answer-neighborhood", "agent-reasoning-windows", "agent-closeouts"],
                "truth_status": "generated_live_scenario_corpus_evidence_not_prune_permission",
            }
        return {
            "status": "not_proven",
            "case_ids": list(GRAPH_STRUCTURAL_EVENT_CHAIN_CORPUS_CASE_IDS),
            "target_projection": GRAPH_STRUCTURAL_EVENT_CHAIN_TARGET_PROJECTION,
            "proven_gates": [],
            "source": source,
            "freshness_basis": "corpus_and_route_code",
            "graph_store_mtime_observed": graph_store_mtime,
            "graph_store_mtime_is_blocking": False,
            "goal_ok": goal_ok,
            "agent_closeout_ok": closeout_ok,
            "timeline_ok": timeline_ok,
            "goal_status": goal_profile.get("status"),
            "agent_closeout_status": closeout_profile.get("status"),
            "timeline_status": timeline_profile.get("status"),
            "timeline_event_count": int_value(timeline_profile.get("event_count")),
            "timeline_source": timeline_profile.get("timeline_source"),
            "timeline_ordered": timeline_profile.get("timeline_ordered"),
            "timeline_freshness_status": timeline_profile.get("freshness_status"),
            "timeline_result_ok": timeline_result.get("ok"),
            "timeline_only_stale_failure": timeline_only_stale_failure,
            "goal_failures": goal_result.get("failures") if isinstance(goal_result.get("failures"), list) else [],
            "agent_closeout_failures": closeout_result.get("failures") if isinstance(closeout_result.get("failures"), list) else [],
            "timeline_failures": timeline_failures,
            "truth_status": "latest_live_scenario_corpus_cases_do_not_prove_structural_event_chain_replacement",
        }
    return {
        "status": "stale_or_missing",
        "case_ids": list(GRAPH_STRUCTURAL_EVENT_CHAIN_CORPUS_CASE_IDS),
        "target_projection": GRAPH_STRUCTURAL_EVENT_CHAIN_TARGET_PROJECTION,
        "proven_gates": [],
        "stale_report_count": stale_reports,
        "incomplete_report_count": incomplete_reports,
        "required_min_source_mtime": required_mtime,
        "freshness_basis": "corpus_and_route_code",
        "graph_store_mtime_observed": graph_store_mtime,
        "graph_store_mtime_is_blocking": False,
        "exact_refresh_command": live_scenario_corpus_check_command_for_cases(
            aoa_root,
            GRAPH_STRUCTURAL_EVENT_CHAIN_CORPUS_CASE_IDS,
        ),
        "truth_status": "missing_current_live_scenario_corpus_evidence",
    }


def graph_entity_usage_replacement_corpus_evidence(aoa_root: Path) -> dict[str, Any]:
    required_mtime = graph_entity_usage_replacement_report_min_source_mtime(aoa_root)
    graph_store_mtime = path_mtime(graph_paths(aoa_root)["store"])
    stale_reports = 0
    for report in diagnostic_json_payloads(aoa_root, "*__live-scenario-corpus-check.json", limit=20):
        source = diagnostic_report_source(report)
        report_mtime = ops_float_value(report.get("_diagnostic_mtime"))
        if required_mtime and report_mtime < required_mtime:
            stale_reports += 1
            continue
        result = next(
            (
                item
                for item in report.get("results", [])
                if isinstance(item, dict)
                and item.get("id") == GRAPH_ENTITY_USAGE_REPLACEMENT_CORPUS_CASE_ID
            ),
            {},
        )
        if not result:
            continue
        profile = graph_entity_usage_replacement_corpus_profile(result)
        profile_ok = (
            result.get("ok") is True
            and profile.get("status") == "passed"
            and profile.get("replacement_proof_ok") is True
            and profile.get("target_projection") == GRAPH_ENTITY_USAGE_REPLACEMENT_TARGET_PROJECTION
            and int_value(profile.get("sample_count")) > 0
            and int_value(profile.get("graph_event_edge_missing_count")) == 0
            and int_value(profile.get("proof_failed_core_gate_count")) == 0
            and profile.get("replacement_prune_apply_ready") is False
        )
        if profile_ok:
            return {
                "status": "proven",
                "case_id": GRAPH_ENTITY_USAGE_REPLACEMENT_CORPUS_CASE_ID,
                "proven_gates": sorted(GRAPH_ENTITY_USAGE_REPLACEMENT_PROVEN_GATES),
                "source": source,
                "freshness_basis": "corpus_and_route_code",
                "graph_store_mtime_observed": graph_store_mtime,
                "graph_store_mtime_is_blocking": False,
                "sample_count": int_value(profile.get("sample_count")),
                "anchor_count": int_value(profile.get("anchor_count")),
                "anchor_counts": profile.get("anchor_counts") if isinstance(profile.get("anchor_counts"), dict) else {},
                "kind_counts": profile.get("kind_counts") if isinstance(profile.get("kind_counts"), dict) else {},
                "usage_event_count": int_value(profile.get("usage_event_count")),
                "graph_event_edge_checked_count": int_value(profile.get("graph_event_edge_checked_count")),
                "graph_event_edge_match_count": int_value(profile.get("graph_event_edge_match_count")),
                "graph_event_edge_missing_count": int_value(profile.get("graph_event_edge_missing_count")),
                "proof_failed_core_gate_count": int_value(profile.get("proof_failed_core_gate_count")),
                "max_sample_elapsed_ms": int_value(profile.get("max_sample_elapsed_ms")),
                "truth_status": "generated_live_scenario_corpus_evidence_not_prune_permission",
            }
        return {
            "status": "not_proven",
            "case_id": GRAPH_ENTITY_USAGE_REPLACEMENT_CORPUS_CASE_ID,
            "proven_gates": [],
            "source": source,
            "freshness_basis": "corpus_and_route_code",
            "graph_store_mtime_observed": graph_store_mtime,
            "graph_store_mtime_is_blocking": False,
            "failures": result.get("failures") if isinstance(result.get("failures"), list) else [],
            "observed_status": profile.get("status"),
            "replacement_proof_ok": profile.get("replacement_proof_ok"),
            "truth_status": "latest_live_scenario_corpus_case_does_not_prove_graph_replacement",
        }
    return {
        "status": "stale_or_missing",
        "case_id": GRAPH_ENTITY_USAGE_REPLACEMENT_CORPUS_CASE_ID,
        "proven_gates": [],
        "stale_report_count": stale_reports,
        "required_min_source_mtime": required_mtime,
        "freshness_basis": "corpus_and_route_code",
        "graph_store_mtime_observed": graph_store_mtime,
        "graph_store_mtime_is_blocking": False,
        "exact_refresh_command": live_scenario_corpus_check_command_for_case(
            aoa_root,
            GRAPH_ENTITY_USAGE_REPLACEMENT_CORPUS_CASE_ID,
        ),
        "truth_status": "missing_current_live_scenario_corpus_evidence",
    }


def graph_high_fanout_replacement_plan_for_edge(
    *,
    aoa_root: Path,
    edge_policy: dict[str, Any],
    proof_states: dict[str, Any] | None = None,
) -> dict[str, Any]:
    edge_type = str(edge_policy.get("edge_type") or "")
    edge_class = str(edge_policy.get("class") or "")
    compact_route = str(edge_policy.get("compact_query_route") or "")
    replacement_layers = [
        str(layer)
        for layer in edge_policy.get("replacement_layers", [])
        if layer
    ] if isinstance(edge_policy.get("replacement_layers"), list) else []
    common = list(GRAPH_HIGH_FANOUT_REPLACEMENT_COMMON_PROOF_GATES)
    if edge_type == "event_has_registered_entity_signal":
        proof_state = (proof_states or {}).get(GRAPH_ENTITY_USAGE_REPLACEMENT_TARGET_PROJECTION)
        if not isinstance(proof_state, dict):
            proof_state = {}
        proven_gates = {
            str(gate)
            for gate in proof_state.get("proven_gates", [])
            if gate
        } if proof_state.get("status") == "proven" else set()
        missing_gates = common + [
            "usage_chain_preserves_consequence_links",
            "entity_usage_rollup_samples_match_event_refs",
        ]
        missing_gates = [gate for gate in missing_gates if gate not in proven_gates]
        status = (
            "replacement_projection_quality_and_cardinality_proven"
            if not missing_gates
            else "replacement_projection_required"
        )
        return {
            "edge_type": edge_type,
            "status": status,
            "candidate_for_cardinality_reduction": True,
            "target_projection": "entity_usage_rollup_by_anchor_session_segment",
            "existing_compact_routes": ["usage-chain", "entity-usage-audit", "entity-registry"],
            "replacement_layers": replacement_layers,
            "proven_proof_gates": sorted(proven_gates),
            "missing_proof_gates": missing_gates,
            "proof_evidence": proof_state,
            "proof_commands": [
                f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} graph-entity-usage-replacement-proof <anchor> --aoa-root {aoa_root} --kind <kind>",
                f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} usage-chain <anchor> --aoa-root {aoa_root} --kind <kind>",
                f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} entity-usage-audit <anchor> --aoa-root {aoa_root} --kind <kind>",
                live_scenario_corpus_check_command_for_case(
                    aoa_root,
                    GRAPH_ENTITY_USAGE_REPLACEMENT_CORPUS_CASE_ID,
                ),
            ],
            "promotion_rule": "promote only after usage/consequence packets preserve raw/segment refs and route freshness on reviewed live cases",
            "can_prune_now": False,
        }
    if edge_type == "event_has_route_signal":
        proof_state = (proof_states or {}).get(GRAPH_ROUTE_SIGNAL_REPLACEMENT_TARGET_PROJECTION)
        if not isinstance(proof_state, dict):
            proof_state = {}
        proven_gates = {
            str(gate)
            for gate in proof_state.get("proven_gates", [])
            if gate
        } if proof_state.get("status") == "proven" else set()
        missing_gates = common + [
            "episode_postings_direct_relations_preserve_refs",
            "mention_and_reference_only_rows_rejected",
            "current_classifier_epoch_only",
            "cooccurrence_packet_preserves_dense_anchor_neighbors",
        ]
        missing_gates = [gate for gate in missing_gates if gate not in proven_gates]
        return {
            "edge_type": edge_type,
            "status": (
                "compact_layers_exist_replacement_quality_and_cardinality_proven"
                if not missing_gates
                else
                "compact_layers_exist_replacement_quality_proven_cardinality_unproven"
                if proven_gates
                else "compact_layers_exist_replacement_projection_unproven"
            ),
            "candidate_for_cardinality_reduction": True,
            "target_projection": GRAPH_ROUTE_SIGNAL_REPLACEMENT_TARGET_PROJECTION,
            "existing_compact_routes": ["graph-cooccurrence", "search-operational-route-rollup-query"],
            "replacement_layers": replacement_layers,
            "proven_proof_gates": sorted(proven_gates),
            "missing_proof_gates": missing_gates,
            "proof_evidence": proof_state,
            "proof_commands": [
                f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} graph-cooccurrence <anchor> --aoa-root {aoa_root} --kind <kind> --limit 30",
                f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} search-operational-route-rollup-query <query> --aoa-root {aoa_root} --layer <layer> --limit 12 --ref-limit 3",
                live_scenario_corpus_check_command_for_cases(
                    aoa_root,
                    GRAPH_ROUTE_SIGNAL_REPLACEMENT_CORPUS_CASE_IDS,
                ),
            ],
            "promotion_rule": "promote only after current-epoch direct episode postings reject mention/reference rows while cooccurrence and rollup packets preserve bounded neighbors, refs, freshness, and exact next expansion",
            "can_prune_now": False,
        }
    if edge_class == "structural_event_chain":
        proof_state = (proof_states or {}).get(GRAPH_STRUCTURAL_EVENT_CHAIN_TARGET_PROJECTION)
        if not isinstance(proof_state, dict):
            proof_state = {}
        proven_gates = {
            str(gate)
            for gate in proof_state.get("proven_gates", [])
            if gate
        } if proof_state.get("status") == "proven" else set()
        timeline_proven = "timeline_packet_preserves_work_chain_order" in proven_gates
        missing_gates = common + [
            "answer_goal_task_episode_coverage",
            "timeline_packet_preserves_work_chain_order",
        ]
        missing_gates = [gate for gate in missing_gates if gate not in proven_gates]
        return {
            "edge_type": edge_type,
            "status": (
                "typed_event_routes_quality_and_cardinality_proven"
                if not missing_gates
                else
                "typed_event_routes_quality_proven_cardinality_unproven"
                if timeline_proven
                else "typed_event_routes_quality_partially_proven_timeline_unproven"
                if proven_gates
                else "typed_event_routes_exist_structural_replacement_unproven"
            ),
            "candidate_for_cardinality_reduction": edge_type == "has_event",
            "target_projection": GRAPH_STRUCTURAL_EVENT_CHAIN_TARGET_PROJECTION,
            "existing_compact_routes": ["agent-responses", "goal-lifecycles", "graph-timeline"],
            "replacement_layers": replacement_layers,
            "proven_proof_gates": sorted(proven_gates),
            "missing_proof_gates": missing_gates,
            "proof_evidence": proof_state,
            "proof_commands": [
                f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} agent-responses --aoa-root {aoa_root} --limit 12",
                f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} goal-lifecycles --aoa-root {aoa_root} --limit 12",
                f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} graph-timeline <anchor> --aoa-root {aoa_root} --kind <kind> --limit 40",
                live_scenario_corpus_check_command_for_cases(
                    aoa_root,
                    GRAPH_STRUCTURAL_EVENT_CHAIN_CORPUS_CASE_IDS,
                ),
            ],
            "promotion_rule": "promote only after answer/goal/task packets prove the same work-chain navigation without unbounded structural expansion",
            "can_prune_now": False,
        }
    if edge_class == "aggregate_summary_layer":
        return {
            "edge_type": edge_type,
            "status": "keep_as_replacement_layer",
            "candidate_for_cardinality_reduction": False,
            "target_projection": "existing_aggregate_summary_layer",
            "existing_compact_routes": [compact_route] if compact_route else [],
            "replacement_layers": replacement_layers,
            "missing_proof_gates": [],
            "proof_commands": [
                f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} search-operational-route-rollup-query <query> --aoa-root {aoa_root} --layer <layer> --limit 12 --ref-limit 3",
            ],
            "promotion_rule": "keep as compact navigation unless a stronger route-rollup with refs replaces it",
            "can_prune_now": False,
        }
    missing_gates = common + ["targeted_edge_policy_written"]
    return {
        "edge_type": edge_type,
        "status": "targeted_policy_required",
        "candidate_for_cardinality_reduction": bool(edge_policy.get("high_fanout")),
        "target_projection": "unknown_until_edge_policy_is_written",
        "existing_compact_routes": [compact_route] if compact_route else [],
        "replacement_layers": replacement_layers,
        "missing_proof_gates": missing_gates,
        "proof_commands": [
            f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} graph-cardinality --aoa-root {aoa_root} --limit 20",
        ],
        "promotion_rule": "measure and write a targeted compact route before any pruning",
        "can_prune_now": False,
    }


def graph_high_fanout_replacement_readiness(
    *,
    aoa_root: Path,
    edge_policies: list[dict[str, Any]],
    projection_status: str,
    status: str,
) -> dict[str, Any]:
    candidate_plans = [
        row.get("replacement_plan")
        for row in edge_policies
        if isinstance(row.get("replacement_plan"), dict)
        and row["replacement_plan"].get("candidate_for_cardinality_reduction")
    ]
    missing_gate_ids = sorted(
        {
            str(gate)
            for plan in candidate_plans
            for gate in plan.get("missing_proof_gates", [])
            if gate
        }
    )
    proven_gate_ids = sorted(
        {
            str(gate)
            for plan in candidate_plans
            for gate in plan.get("proven_proof_gates", [])
            if gate
        }
    )
    candidate_edge_types = [
        str(plan.get("edge_type") or "")
        for plan in candidate_plans
        if plan.get("edge_type")
    ]
    target_projections = sorted(
        {
            str(plan.get("target_projection") or "")
            for plan in candidate_plans
            if plan.get("target_projection")
        }
    )
    proof_commands = []
    seen_commands: set[str] = set()
    for plan in candidate_plans:
        for command in plan.get("proof_commands", []):
            command_text = str(command)
            if command_text and command_text not in seen_commands:
                proof_commands.append(command_text)
                seen_commands.add(command_text)
    if projection_status != "current":
        readiness_status = "blocked_cardinality_projection_not_current"
    elif not candidate_plans:
        readiness_status = "not_needed"
    elif missing_gate_ids:
        readiness_status = "not_ready_for_prune"
    else:
        readiness_status = "ready_for_reviewed_apply_route"
    apply_ready = False
    if status == "normal" and not candidate_plans:
        gate_status = "not_needed"
        reason = "no high-fanout cardinality replacement is needed"
    elif projection_status != "current":
        gate_status = "blocked_cardinality_projection_not_current"
        reason = "graph cardinality projection must be current before replacement readiness can be trusted"
    elif not missing_gate_ids:
        gate_status = "blocked_explicit_apply_route_required"
        reason = "replacement projections are proven, but graph-row pruning still requires an explicit reviewed apply route and mutation before/after report"
    else:
        gate_status = "blocked_replacement_projection_not_proven"
        reason = "replacement projections must prove refs, freshness, fallback, live scenario quality, and before/after cardinality before any graph-row pruning"
    required_before_apply = sorted(
        set(missing_gate_ids)
        | {
            "explicit_apply_route_with_before_after_report",
            "operator_reviewed_mutation_boundary",
        }
    ) if candidate_plans else []
    return {
        "status": readiness_status,
        "apply_ready": apply_ready,
        "candidate_count": len(candidate_plans),
        "candidate_edge_types": candidate_edge_types,
        "target_projections": target_projections,
        "proof_gap_count": len(missing_gate_ids),
        "missing_proof_gates": missing_gate_ids,
        "proven_proof_gates": proven_gate_ids,
        "proof_commands": proof_commands[:12],
        "proof_evidence": [
            plan.get("proof_evidence")
            for plan in candidate_plans
            if isinstance(plan.get("proof_evidence"), dict) and plan.get("proof_evidence")
        ],
        "next_route": (
            "prove replacement projections on live scenarios before any graph prune or physical compaction route"
            if candidate_plans
            else "no replacement projection route is needed for the current high-fanout packet"
        ),
        "prune_gate": {
            "status": gate_status,
            "apply_ready": apply_ready,
            "can_prune_now": False,
            "reason": reason,
            "required_before_apply": required_before_apply,
            "mutation_boundary": "read_only_policy_packet_no_graph_rows_are_deleted_or_rebuilt",
        },
        "authority_boundary": "replacement readiness is generated route guidance; raw/segment refs and owner source surfaces remain stronger",
    }


def graph_high_fanout_policy_from_projection(
    *,
    aoa_root: Path,
    projection: dict[str, Any],
    limit: int = 12,
) -> dict[str, Any]:
    selected_limit = max(1, min(int_value(limit, 12), 80))
    counts = projection.get("counts") if isinstance(projection.get("counts"), dict) else {}
    node_counts = counts.get("node") if isinstance(counts.get("node"), dict) else {}
    edge_counts = counts.get("edge") if isinstance(counts.get("edge"), dict) else {}
    node_total = sum(int_value(value) for value in node_counts.values())
    edge_total = sum(int_value(value) for value in edge_counts.values())
    edge_rows = sorted(
        ((str(edge_type), int_value(count)) for edge_type, count in edge_counts.items()),
        key=lambda item: (-item[1], item[0]),
    )
    node_rows = sorted(
        ((str(node_type), int_value(count)) for node_type, count in node_counts.items()),
        key=lambda item: (-item[1], item[0]),
    )
    edge_policies = [
        graph_high_fanout_edge_policy_row(
            aoa_root=aoa_root,
            edge_type=edge_type,
            count=count,
            edge_total=edge_total,
        )
        for edge_type, count in edge_rows[:selected_limit]
    ]
    proof_states = {
        GRAPH_ENTITY_USAGE_REPLACEMENT_TARGET_PROJECTION: graph_entity_usage_replacement_corpus_evidence(aoa_root),
        GRAPH_ROUTE_SIGNAL_REPLACEMENT_TARGET_PROJECTION: graph_route_signal_replacement_corpus_evidence(aoa_root),
        GRAPH_STRUCTURAL_EVENT_CHAIN_TARGET_PROJECTION: graph_structural_event_chain_corpus_evidence(aoa_root),
    }
    cardinality_comparison = graph_high_fanout_cardinality_comparison(
        aoa_root=aoa_root,
        projection=projection,
        limit=selected_limit,
        write_report=False,
    )
    proof_states = graph_high_fanout_merge_cardinality_comparison(proof_states, cardinality_comparison)
    for row in edge_policies:
        row["replacement_plan"] = graph_high_fanout_replacement_plan_for_edge(
            aoa_root=aoa_root,
            edge_policy=row,
            proof_states=proof_states,
        )
    dominant_edges = [
        row
        for row in edge_policies
        if row.get("high_fanout") or str(row.get("class") or "") in {"event_route_signal_fanout", "event_registered_entity_fanout"}
    ]
    high_fanout_nodes = [
        {
            "node_type": node_type,
            "count": count,
            "share": round(count / node_total, 6) if node_total > 0 else 0.0,
            "high_fanout": count >= OPS_GRAPH_HIGH_FANOUT_NODE_WARNING_COUNT,
            "policy": "prefer typed route packets over unbounded node expansion",
        }
        for node_type, count in node_rows[:selected_limit]
        if count >= OPS_GRAPH_HIGH_FANOUT_NODE_WARNING_COUNT or node_type == "event"
    ]
    projection_status = str(projection.get("status") or "unknown")
    if projection_status != "current":
        status = "cardinality_projection_missing_or_stale"
    elif edge_total >= OPS_GRAPH_EDGE_CARDINALITY_WARNING_COUNT:
        status = "large_cardinality_dominates"
    elif dominant_edges or high_fanout_nodes:
        status = "localized_high_fanout"
    else:
        status = "normal"
    next_actions = [
        {
            "id": "use_compact_graph_routes_for_dense_anchors",
            "reason": "dense anchors should use bounded cooccurrence/timeline/usage packets before raw graph expansion",
            "mutates": False,
            "example_command": f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} graph-cooccurrence <anchor> --aoa-root {aoa_root} --kind <kind> --limit 30",
        },
        {
            "id": "refresh_graph_cardinality_if_stale",
            "reason": "type-count projection must be current before graph storage/cardinality decisions",
            "mutates": False,
            "command": [
                *session_memory_cli_command(aoa_root),
                "graph-cardinality",
                "--aoa-root",
                str(aoa_root),
                "--limit",
                str(selected_limit),
            ],
        },
    ]
    if cardinality_comparison.get("status") != "proven":
        next_actions.append(
            {
                "id": "prove_high_fanout_before_after_cardinality",
                "reason": "replacement projections need a current before/after cardinality comparison before any reviewed apply route",
                "mutates": False,
                "command": [
                    *session_memory_cli_command(aoa_root),
                    "graph-high-fanout-cardinality-comparison",
                    "--aoa-root",
                    str(aoa_root),
                    "--limit",
                    str(selected_limit),
                ],
            }
        )
    if status == "large_cardinality_dominates":
        next_actions.append(
            {
                "id": "design_high_fanout_replacement_before_prune",
                "reason": "physical compaction or row deletion must wait for a replacement route with refs/freshness/fallback proof",
                "mutates": False,
                "replacement_layers": sorted({layer for row in edge_policies for layer in row.get("replacement_layers", []) if layer}),
            }
        )
    replacement_readiness = graph_high_fanout_replacement_readiness(
        aoa_root=aoa_root,
        edge_policies=edge_policies,
        projection_status=projection_status,
        status=status,
    )
    if (
        status == "large_cardinality_dominates"
        and str(replacement_readiness.get("status") or "") == "ready_for_reviewed_apply_route"
        and int_value(replacement_readiness.get("proof_gap_count")) == 0
    ):
        next_actions.append(
            {
                "id": "review_high_fanout_prune_apply_route",
                "reason": "replacement projections are proven; use the explicit dry-run/apply route with before/after report before graph-row pruning",
                "mutates": False,
                "dry_run_command": [
                    *session_memory_cli_command(aoa_root),
                    "graph-high-fanout-prune",
                    "--aoa-root",
                    str(aoa_root),
                    "--write-report",
                ],
                "apply_command": [
                    *session_memory_cli_command(aoa_root),
                    "graph-high-fanout-prune",
                    "--aoa-root",
                    str(aoa_root),
                    "--apply",
                    "--write-report",
                ],
            }
        )
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_high_fanout_policy",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": projection_status == "current",
        "mutates": False,
        "status": status,
        "projection_status": projection_status,
        "node_count": node_total,
        "edge_count": edge_total,
        "edge_warning_count": OPS_GRAPH_EDGE_CARDINALITY_WARNING_COUNT,
        "high_fanout_edge_warning_count": OPS_GRAPH_HIGH_FANOUT_EDGE_WARNING_COUNT,
        "high_fanout_node_warning_count": OPS_GRAPH_HIGH_FANOUT_NODE_WARNING_COUNT,
        "edge_policies": edge_policies,
        "high_fanout_nodes": high_fanout_nodes,
        "dominant_edge_count": len(dominant_edges),
        "dominant_edge_types": [str(row.get("edge_type") or "") for row in dominant_edges],
        "graph_event_route_signal_edge_policy": GRAPH_EVENT_ROUTE_SIGNAL_EDGE_POLICY,
        "graph_event_relationship_edge_policy": GRAPH_EVENT_RELATIONSHIP_EDGE_POLICY,
        "graph_route_signal_materialization_limits": graph_route_signal_materialization_limits(),
        "replacement_cardinality_comparison": cardinality_comparison,
        "replacement_proof_states": proof_states,
        "replacement_readiness": replacement_readiness,
        "prune_gate": replacement_readiness.get("prune_gate"),
        "next_actions": next_actions,
        "exact_read_command": f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} graph-high-fanout-policy --workspace-root {aoa_root.parent} --aoa-root {aoa_root} --limit {selected_limit}",
        "exact_cardinality_command": f"python3 {aoa_root / 'scripts' / 'aoa_session_memory.py'} graph-cardinality --workspace-root {aoa_root.parent} --aoa-root {aoa_root} --limit {selected_limit}",
        "next_route": (
            "use compact graph routes and design replacement projections before mutating high-fanout edge rows"
            if status != "normal"
            else "continue using compact graph packets; no high-fanout policy action is needed"
        ),
        "mutation_boundary": "read_only_policy_packet_no_graph_rows_are_deleted_or_rebuilt",
        "authority_boundary": "graph policy is generated routing guidance; raw/segment refs and owner source surfaces remain stronger",
        "diagnostics": projection.get("diagnostics", []) if isinstance(projection.get("diagnostics"), list) else [],
    }


def graph_high_fanout_policy(*, aoa_root: Path, limit: int = 12) -> dict[str, Any]:
    projection = graph_cardinality_projection_read(aoa_root, limit=max(12, int_value(limit, 12)))
    return graph_high_fanout_policy_from_projection(aoa_root=aoa_root, projection=projection, limit=limit)


def graph_usage_event_node_id(event: dict[str, Any]) -> str:
    doc_id = str(event.get("doc_id") or "")
    if doc_id.startswith("event:"):
        return doc_id
    session_id = str(event.get("session_id") or "")
    segment_id = str(event.get("segment_id") or "")
    event_id = str(event.get("event_id") or "")
    if session_id and segment_id and event_id:
        return f"event:{session_id}:{segment_id}:{event_id}"
    return ""


def graph_ref_has_raw_or_segment(refs: dict[str, Any]) -> bool:
    return any(str(refs.get(key) or "").strip() for key in ("raw", "raw_block", "segment", "segment_index"))


def graph_usage_event_has_raw_or_segment_ref(event: dict[str, Any]) -> bool:
    refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
    return graph_ref_has_raw_or_segment(refs)


def graph_usage_event_source_key(event: dict[str, Any]) -> str:
    session_id = str(event.get("session_id") or "")
    segment_id = str(event.get("segment_id") or "")
    if session_id and segment_id:
        return graph_source_key("segment", session_id, segment_id)
    return ""


def graph_usage_event_deferred_live_info(
    aoa_root: Path,
    event: dict[str, Any],
    *,
    ledger_sources: dict[str, Any] | None = None,
    now_ts: float | None = None,
    quiet_seconds: float = GRAPH_HOT_LIVE_DEFER_SECONDS,
) -> dict[str, Any]:
    source_key = graph_usage_event_source_key(event)
    sources = ledger_sources if isinstance(ledger_sources, dict) else {}
    entry = sources.get(source_key) if source_key else None
    if not isinstance(entry, dict):
        return {"deferred_live": False, "source_key": source_key, "source_status": ""}
    status = str(entry.get("status") or "")
    live_transcript_mtime, _live_transcript_path = graph_state_item_live_transcript_mtime(entry)
    now_value = time.time() if now_ts is None else float(now_ts)
    threshold = now_value - max(0.0, float(quiet_seconds))
    deferred_live = bool(status in GRAPH_ACTIONABLE_SOURCE_STATUSES and live_transcript_mtime > threshold)
    return {
        "deferred_live": deferred_live,
        "source_key": source_key,
        "source_status": status,
        "session_id": event.get("session_id"),
        "segment_id": event.get("segment_id"),
        "event_id": event.get("event_id"),
        "event_node_id": graph_usage_event_node_id(event),
        "live_transcript_mtime": live_transcript_mtime if deferred_live else 0.0,
        "age_seconds": max(0.0, now_value - live_transcript_mtime) if deferred_live and live_transcript_mtime > 0 else 0.0,
    }


def graph_usage_events_for_edge_check(
    aoa_root: Path,
    usage_events: list[dict[str, Any]],
    *,
    limit: int,
    now_ts: float | None = None,
) -> dict[str, Any]:
    ledger = read_graph_source_state_ledger(aoa_root)
    sources = ledger.get("sources") if isinstance(ledger.get("sources"), dict) else {}
    stable_events: list[dict[str, Any]] = []
    deferred_events: list[dict[str, Any]] = []
    deferred_infos: list[dict[str, Any]] = []
    for event in usage_events:
        info = graph_usage_event_deferred_live_info(
            aoa_root,
            event,
            ledger_sources=sources,
            now_ts=now_ts,
        )
        if info.get("deferred_live"):
            deferred_events.append(event)
            deferred_infos.append(info)
            continue
        stable_events.append(event)
    selected_limit = max(1, int_value(limit, 1))
    return {
        "selected_usage_events": stable_events[:selected_limit],
        "stable_usage_event_count": len(stable_events),
        "deferred_live_usage_event_count": len(deferred_events),
        "deferred_live_usage_events_sample": deferred_infos[:8],
        "harvest_usage_event_count": len(usage_events),
    }


def graph_registry_nodes_for_route_nodes(
    conn: sqlite3.Connection,
    route_node_ids: list[str],
    *,
    limit: int,
) -> list[str]:
    registry_nodes: list[str] = []
    seen: set[str] = set()
    for node_id in route_node_ids:
        node_id = str(node_id or "")
        if not node_id:
            continue
        if node_id.startswith("entity_registry:") and node_id not in seen:
            registry_nodes.append(node_id)
            seen.add(node_id)
        remaining = max(1, limit - len(registry_nodes))
        rows = conn.execute(
            """
            SELECT source_node
            FROM edges
            WHERE target_node = ?
              AND edge_type = 'registry_entity_has_route_signal'
            LIMIT ?
            """,
            (node_id, remaining),
        ).fetchall()
        for row in rows:
            registry_node = str(row["source_node"] or "")
            if registry_node and registry_node not in seen:
                registry_nodes.append(registry_node)
                seen.add(registry_node)
            if len(registry_nodes) >= limit:
                return registry_nodes
    return registry_nodes


def graph_entity_usage_replacement_graph_sample(
    conn: sqlite3.Connection,
    *,
    registry_node_ids: list[str],
    sample_limit: int,
    post_prune_aggregate_mode: bool = False,
) -> dict[str, Any]:
    event_edge_count = 0
    aggregate_edge_count = 0
    sample_edge_ids: list[str] = []
    sample_session_edge_ids: list[str] = []
    per_registry: list[dict[str, Any]] = []
    for registry_node in registry_node_ids:
        registry_node = str(registry_node or "")
        if not registry_node:
            continue
        event_count = int_value(
            conn.execute(
                """
                SELECT COUNT(*)
                FROM edges
                WHERE target_node = ?
                  AND edge_type = ?
                """,
                (registry_node, GRAPH_ENTITY_USAGE_REPLACEMENT_EDGE_TYPE),
            ).fetchone()[0]
        )
        session_count = int_value(
            conn.execute(
                """
                SELECT COUNT(*)
                FROM edges
                WHERE target_node = ?
                  AND edge_type = ?
                """,
                (registry_node, GRAPH_ENTITY_USAGE_REPLACEMENT_AGGREGATE_EDGE_TYPE),
            ).fetchone()[0]
        )
        event_edge_count += event_count
        aggregate_edge_count += session_count
        if len(sample_edge_ids) < sample_limit:
            rows = conn.execute(
                """
                SELECT id
                FROM edges
                WHERE target_node = ?
                  AND edge_type = ?
                LIMIT ?
                """,
                (registry_node, GRAPH_ENTITY_USAGE_REPLACEMENT_EDGE_TYPE, max(1, sample_limit - len(sample_edge_ids))),
            ).fetchall()
            sample_edge_ids.extend(str(row["id"] or "") for row in rows if row["id"])
        if len(sample_session_edge_ids) < sample_limit:
            rows = conn.execute(
                """
                SELECT id
                FROM edges
                WHERE target_node = ?
                  AND edge_type = ?
                LIMIT ?
                """,
                (registry_node, GRAPH_ENTITY_USAGE_REPLACEMENT_AGGREGATE_EDGE_TYPE, max(1, sample_limit - len(sample_session_edge_ids))),
            ).fetchall()
            sample_session_edge_ids.extend(str(row["id"] or "") for row in rows if row["id"])
        per_registry.append(
            {
                "registry_node": registry_node,
                "event_edge_count": event_count,
                "session_aggregate_edge_count": session_count,
            }
        )
    event_samples = graph_store_fetch_payloads(conn, "edges", sample_edge_ids[:sample_limit])
    aggregate_samples = graph_store_fetch_payloads(conn, "edges", sample_session_edge_ids[:sample_limit])
    post_prune_event_edges_omitted = bool(post_prune_aggregate_mode and event_edge_count == 0 and aggregate_edge_count > 0)
    reduction_ratio = (
        round(1 - (aggregate_edge_count / event_edge_count), 6)
        if event_edge_count > 0
        else (1.0 if post_prune_event_edges_omitted else 0.0)
    )
    proof_mode = "post_prune_aggregate_refs" if post_prune_event_edges_omitted else "pre_prune_event_edge_samples"
    return {
        "proof_mode": proof_mode,
        "post_prune_aggregate_mode": bool(post_prune_aggregate_mode),
        "post_prune_event_edges_omitted": post_prune_event_edges_omitted,
        "event_edge_count": event_edge_count,
        "session_aggregate_edge_count": aggregate_edge_count,
        "sample_event_edge_count": len(event_samples),
        "sample_session_aggregate_edge_count": len(aggregate_samples),
        "sample_event_edges": event_samples,
        "sample_session_aggregate_edges": aggregate_samples,
        "per_registry": per_registry,
        "anchor_sample_reduction_ratio": reduction_ratio,
        "cardinality_improves_for_anchor": (event_edge_count > aggregate_edge_count > 0) or post_prune_event_edges_omitted,
    }


def graph_entity_usage_replacement_matching_edges(
    conn: sqlite3.Connection,
    *,
    usage_events: list[dict[str, Any]],
    registry_node_ids: list[str],
    sample_limit: int,
    post_prune_aggregate_mode: bool = False,
) -> dict[str, Any]:
    checked: list[dict[str, Any]] = []
    matched_edge_ids: list[str] = []
    missing: list[dict[str, Any]] = []
    for event in usage_events[:sample_limit]:
        event_node_id = graph_usage_event_node_id(event)
        session_id = str(event.get("session_id") or "")
        matched_registry_node = ""
        matched_edge_id = ""
        matched_mode = ""
        if event_node_id:
            for registry_node in registry_node_ids:
                edge_id = graph_edge_id(event_node_id, registry_node, GRAPH_ENTITY_USAGE_REPLACEMENT_EDGE_TYPE)
                row = conn.execute("SELECT id FROM edges WHERE id = ?", (edge_id,)).fetchone()
                if row:
                    matched_registry_node = registry_node
                    matched_edge_id = str(row["id"] or edge_id)
                    matched_mode = "event_edge"
                    break
        if not matched_edge_id and post_prune_aggregate_mode:
            for registry_node in registry_node_ids:
                row = None
                if session_id:
                    aggregate_edge_id = graph_edge_id(
                        f"session:{session_id}",
                        registry_node,
                        GRAPH_ENTITY_USAGE_REPLACEMENT_AGGREGATE_EDGE_TYPE,
                    )
                    row = conn.execute("SELECT id FROM edges WHERE id = ?", (aggregate_edge_id,)).fetchone()
                if row:
                    matched_registry_node = registry_node
                    matched_edge_id = str(row["id"] or "")
                    matched_mode = "post_prune_aggregate_refs"
                    break
        item = {
            "event_node_id": event_node_id,
            "session_id": event.get("session_id"),
            "segment_id": event.get("segment_id"),
            "event_id": event.get("event_id"),
            "usage_role": event.get("role"),
            "raw_or_segment_ref_present": graph_usage_event_has_raw_or_segment_ref(event),
            "matched": bool(matched_edge_id),
            "matched_registry_node": matched_registry_node,
            "matched_edge_id": matched_edge_id,
            "matched_mode": matched_mode,
            "event_edge_pruned": bool(post_prune_aggregate_mode and matched_mode == "post_prune_aggregate_refs"),
        }
        checked.append(item)
        if matched_edge_id:
            matched_edge_ids.append(matched_edge_id)
        else:
            missing.append(item)
    matched_edges = graph_store_fetch_payloads(conn, "edges", matched_edge_ids[:sample_limit])
    matched_edges_with_refs = 0
    for edge in matched_edges:
        refs = edge.get("evidence_refs") if isinstance(edge.get("evidence_refs"), list) else []
        if refs:
            matched_edges_with_refs += 1
    return {
        "matching_mode": "post_prune_aggregate_refs" if post_prune_aggregate_mode else "event_edge",
        "post_prune_aggregate_mode": bool(post_prune_aggregate_mode),
        "checked_count": len(checked),
        "matched_count": len(matched_edge_ids),
        "missing_count": len(missing),
        "usage_events_checked": checked,
        "missing_usage_events": missing[:sample_limit],
        "matched_edges": matched_edges,
        "matched_edges_with_evidence_refs": matched_edges_with_refs,
    }


def graph_replacement_gate(id_: str, status: str, *, reason: str, details: dict[str, Any] | None = None) -> dict[str, Any]:
    return {
        "id": id_,
        "status": status,
        "passed": status == "passed",
        "reason": reason,
        "details": details or {},
    }


def graph_entity_usage_replacement_proof(
    *,
    aoa_root: Path,
    anchor: str,
    kind: str = "auto",
    limit: int = 6,
    per_route_limit: int = 12,
    consequence_window: int = 6,
    sample_limit: int = 8,
    provider: str = "portable_sqlite",
    write_report: bool = False,
) -> dict[str, Any]:
    started_at = time.monotonic()
    normalized_kind = normalize_trace_route_kind(kind)
    if normalized_kind not in TRACE_ROUTE_KINDS:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "session_memory_graph_entity_usage_replacement_proof",
            "generated_at": utc_now(),
            "ok": False,
            "mutates": False,
            "anchor": anchor,
            **trace_kind_payload_fields(kind, normalized_kind),
            "diagnostics": [f"unknown trace kind: {kind}"],
        }
    selected_limit = max(1, min(int_value(limit, 6), 20))
    selected_sample_limit = max(1, min(int_value(sample_limit, 8), 40))
    selected_per_route_limit = max(selected_limit, min(int_value(per_route_limit, 12), 80))
    usage_harvest_limit = max(selected_limit, min(20, max(selected_per_route_limit, selected_limit * 6)))
    usage_harvest_per_route_limit = max(selected_per_route_limit, usage_harvest_limit)
    usage_packet = entity_usage_chain(
        aoa_root=aoa_root,
        anchor=anchor,
        kind=normalized_kind,
        limit=usage_harvest_limit,
        per_route_limit=usage_harvest_per_route_limit,
        consequence_window=consequence_window,
        document_limit=max(12, usage_harvest_limit * 4),
        provider=provider,
        write_report=False,
    )
    chains = usage_packet.get("usage_chain", {}).get("chains", []) if isinstance(usage_packet.get("usage_chain"), dict) else []
    harvested_usage_events = [
        item.get("usage_event")
        for item in chains
        if isinstance(item, dict) and isinstance(item.get("usage_event"), dict)
    ]
    usage_selection = graph_usage_events_for_edge_check(
        aoa_root,
        harvested_usage_events,
        limit=selected_limit,
    )
    usage_events = [
        event
        for event in usage_selection.get("selected_usage_events", [])
        if isinstance(event, dict)
    ]
    usage_quality = usage_packet.get("quality") if isinstance(usage_packet.get("quality"), dict) else {}
    raw_or_segment_usage_count = sum(1 for event in usage_events if graph_usage_event_has_raw_or_segment_ref(event))
    selected_event_node_ids = {graph_usage_event_node_id(event) for event in usage_events}
    selected_chains = [
        item
        for item in chains
        if isinstance(item, dict)
        and isinstance(item.get("usage_event"), dict)
        and graph_usage_event_node_id(item["usage_event"]) in selected_event_node_ids
    ]
    chain_with_link_count = sum(1 for item in selected_chains if "result_or_consequence_count" in item)
    chain_with_result_count = sum(1 for item in selected_chains if bool(item.get("has_result_or_consequence")))
    graph_state = graph_store_query_state(aoa_root)
    diagnostics: list[str] = []
    graph_resolution: dict[str, Any] = {}
    graph_sample: dict[str, Any] = {}
    edge_matches: dict[str, Any] = {}
    registry_node_ids: list[str] = []
    graph_metadata = graph_state.get("metadata") if isinstance(graph_state.get("metadata"), dict) else {}
    graph_store_availability_status = str(graph_state.get("status") or "unavailable")
    graph_freshness_packet = graph_freshness(
        aoa_root,
        {
            "source": (
                "sqlite_graph_store"
                if graph_store_availability_status in {"current", "stale"}
                else graph_store_availability_status
            ),
            "generated_at": str(graph_metadata.get("generated_at") or ""),
        },
    )
    graph_freshness_packet["store_availability_status"] = graph_store_availability_status
    graph_store_freshness_current = (
        graph_store_availability_status == "current"
        and str(graph_freshness_packet.get("status") or "") == "graph_store_current"
        and not bool(graph_freshness_packet.get("needs_maintenance"))
        and not bool(graph_freshness_packet.get("needs_full_rebuild"))
    )
    if not graph_store_freshness_current:
        diagnostics.append(
            f"graph_store_freshness_not_current:{str(graph_freshness_packet.get('status') or 'unavailable')}"
        )
    post_prune_aggregate_mode = graph_high_fanout_prune_applied_for_edge_types(
        graph_metadata,
        (GRAPH_ENTITY_USAGE_REPLACEMENT_EDGE_TYPE,),
    )
    if graph_state.get("status") != "current":
        diagnostics.append("graph_store_not_current")
    else:
        conn: sqlite3.Connection | None = None
        try:
            graph_store_path = graph_paths(aoa_root)["store"]
            conn = sqlite3.connect(f"{graph_store_path.resolve().as_uri()}?mode=ro", uri=True)
            conn.row_factory = sqlite3.Row
            graph_resolution = graph_store_resolve_anchor(conn, anchor, kind=normalized_kind, limit=max(10, selected_sample_limit))
            route_node_ids = [str(node_id) for node_id in graph_resolution.get("start_node_ids", []) if node_id]
            registry_node_ids = graph_registry_nodes_for_route_nodes(conn, route_node_ids, limit=max(4, selected_sample_limit))
            graph_sample = graph_entity_usage_replacement_graph_sample(
                conn,
                registry_node_ids=registry_node_ids,
                sample_limit=selected_sample_limit,
                post_prune_aggregate_mode=post_prune_aggregate_mode,
            )
            edge_matches = graph_entity_usage_replacement_matching_edges(
                conn,
                usage_events=usage_events,
                registry_node_ids=registry_node_ids,
                sample_limit=selected_sample_limit,
                post_prune_aggregate_mode=post_prune_aggregate_mode,
            )
        except sqlite3.Error as exc:
            diagnostics.append(f"graph_sqlite_error:{str(exc)[:180]}")
        finally:
            if conn is not None:
                conn.close()
    usage_count = len(usage_events)
    checked_count = int_value(edge_matches.get("checked_count"))
    matched_count = int_value(edge_matches.get("matched_count"))
    deferred_live_usage_event_count = int_value(usage_selection.get("deferred_live_usage_event_count"))
    gates = [
        graph_replacement_gate(
            "raw_or_segment_refs_preserved",
            (
                "passed"
                if usage_count and raw_or_segment_usage_count == usage_count
                else ("not_proven" if deferred_live_usage_event_count and not usage_count else "failed")
            ),
            reason="usage-chain usage events expose raw, raw-block, segment, or segment-index refs",
            details={
                "usage_event_count": usage_count,
                "raw_or_segment_ref_count": raw_or_segment_usage_count,
                "deferred_live_usage_event_count": deferred_live_usage_event_count,
            },
        ),
        graph_replacement_gate(
            "freshness_current_or_stale_flag_visible",
            (
                "passed"
                if usage_count
                and all(isinstance(event.get("freshness"), dict) and event.get("freshness", {}).get("status") for event in usage_events)
                else ("not_proven" if deferred_live_usage_event_count and not usage_count else "failed")
            ),
            reason="usage-chain keeps freshness status visible on checked usage events",
        ),
        graph_replacement_gate(
            "graph_store_freshness_current",
            "passed" if graph_store_freshness_current else "failed",
            reason="replacement proof can pass only when the graph store hot-gate freshness is current",
            details={
                "status": graph_freshness_packet.get("status"),
                "store_availability_status": graph_store_availability_status,
                "hot_gate_status": graph_freshness_packet.get("hot_gate_status"),
                "needs_maintenance": graph_freshness_packet.get("needs_maintenance"),
                "needs_full_rebuild": graph_freshness_packet.get("needs_full_rebuild"),
            },
        ),
        graph_replacement_gate(
            "fallback_route_named",
            "passed" if usage_packet.get("next_expansion_command") or usage_packet.get("next_expansion") else "failed",
            reason="usage-chain packet names a bounded next expansion route",
        ),
        graph_replacement_gate(
            "bounded_packet_default",
            "passed"
            if usage_quality.get("skipped_graph_rag_packet") is True
            and usage_quality.get("skipped_graph_neighborhood") is True
            and usage_quality.get("skipped_raw_preview_neighborhood") is True
            else "failed",
            reason="replacement route avoids GraphRAG, graph-neighborhood, and raw-preview expansion by default",
        ),
        graph_replacement_gate(
            "entity_usage_rollup_samples_match_event_refs",
            (
                "passed"
                if checked_count and matched_count == checked_count
                else ("not_proven" if deferred_live_usage_event_count and not checked_count else "failed")
            ),
            reason="usage-chain event refs match generated event edges or reviewed post-prune aggregate refs for this anchor sample",
            details={
                "matching_mode": edge_matches.get("matching_mode"),
                "post_prune_aggregate_mode": edge_matches.get("post_prune_aggregate_mode"),
                "checked_count": checked_count,
                "matched_count": matched_count,
                "missing_count": edge_matches.get("missing_count"),
                "deferred_live_usage_event_count": deferred_live_usage_event_count,
            },
        ),
        graph_replacement_gate(
            "sample_before_after_cardinality_comparison",
            "passed" if graph_sample.get("cardinality_improves_for_anchor") else "failed",
            reason="anchor sample compares event-level graph edges against aggregate edges or verifies aggregate refs after reviewed prune",
            details={
                "proof_mode": graph_sample.get("proof_mode"),
                "post_prune_aggregate_mode": graph_sample.get("post_prune_aggregate_mode"),
                "post_prune_event_edges_omitted": graph_sample.get("post_prune_event_edges_omitted"),
                "event_edge_count": graph_sample.get("event_edge_count"),
                "session_aggregate_edge_count": graph_sample.get("session_aggregate_edge_count"),
                "anchor_sample_reduction_ratio": graph_sample.get("anchor_sample_reduction_ratio"),
            },
        ),
        graph_replacement_gate(
            "usage_chain_preserves_consequence_links",
            (
                "passed"
                if usage_count and chain_with_link_count == usage_count
                else ("not_proven" if deferred_live_usage_event_count and not usage_count else "failed")
            ),
            reason="usage-chain keeps per-usage result_or_consequence link fields even when no consequence was observed",
            details={
                "chain_count": len(selected_chains),
                "chain_with_link_count": chain_with_link_count,
                "chain_with_result_count": chain_with_result_count,
                "deferred_live_usage_event_count": deferred_live_usage_event_count,
            },
        ),
        graph_replacement_gate(
            "global_before_after_cardinality_comparison",
            "not_proven",
            reason="this proof is bounded to one anchor; global graph-row pruning still needs an explicit apply route and before/after report",
        ),
    ]
    failed_core_gates = [
        gate["id"]
        for gate in gates
        if gate.get("status") == "failed"
        and gate.get("id") != "global_before_after_cardinality_comparison"
    ]
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_entity_usage_replacement_proof",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": bool(usage_packet.get("ok")) and usage_count > 0 and not failed_core_gates and bool(registry_node_ids),
        "mutates": False,
        "truth_status": "generated_graph_replacement_sample_proof_not_prune_permission",
        "anchor": anchor,
        **trace_kind_payload_fields(kind, normalized_kind),
        "target_edge_type": GRAPH_ENTITY_USAGE_REPLACEMENT_EDGE_TYPE,
        "target_projection": GRAPH_ENTITY_USAGE_REPLACEMENT_TARGET_PROJECTION,
        "replacement_scope": "anchor_sample",
        "post_prune_aggregate_mode": bool(post_prune_aggregate_mode),
        "graph_high_fanout_prune_policy": graph_metadata.get("graph_high_fanout_prune_policy"),
        "graph_high_fanout_pruned_edge_types": graph_metadata.get("graph_high_fanout_pruned_edge_types"),
        "freshness": graph_freshness_packet,
        "normalized_entity": usage_packet.get("normalized_entity") if isinstance(usage_packet.get("normalized_entity"), dict) else {},
        "usage_chain": {
            "ok": usage_packet.get("ok"),
            "usage_event_count": usage_count,
            "usage_event_harvest_count": usage_selection.get("harvest_usage_event_count"),
            "stable_usage_event_count": usage_selection.get("stable_usage_event_count"),
            "deferred_live_usage_event_count": deferred_live_usage_event_count,
            "deferred_live_usage_events_sample": usage_selection.get("deferred_live_usage_events_sample"),
            "chain_count": len(selected_chains),
            "chain_with_result_or_consequence_count": chain_with_result_count,
            "raw_or_segment_ref_count": raw_or_segment_usage_count,
            "first_ref": usage_packet.get("first_ref"),
            "quality": usage_quality,
            "next_expansion_command": usage_packet.get("next_expansion_command"),
        },
        "graph_resolution": {
            "status": graph_freshness_packet.get("status") or graph_store_availability_status,
            "store_availability_status": graph_store_availability_status,
            "route_candidates": graph_resolution.get("route_candidates", []) if isinstance(graph_resolution, dict) else [],
            "start_node_ids": graph_resolution.get("start_node_ids", []) if isinstance(graph_resolution, dict) else [],
            "registry_node_ids": registry_node_ids,
            "registry_node_count": len(registry_node_ids),
            "resolver_strategy": graph_resolution.get("resolver_strategy") if isinstance(graph_resolution, dict) else "",
        },
        "graph_sample": graph_sample,
        "edge_match": edge_matches,
        "proof_gates": gates,
        "proof_gate_summary": {
            "failed_core_gate_count": len(failed_core_gates),
            "failed_core_gates": failed_core_gates,
            "passed_gate_count": sum(1 for gate in gates if gate.get("status") == "passed"),
            "not_proven_gate_count": sum(1 for gate in gates if gate.get("status") == "not_proven"),
        },
        "prune_gate": {
            "status": "blocked_anchor_sample_only",
            "apply_ready": False,
            "can_prune_now": False,
            "reason": "anchor-sample replacement proof does not prove archive-wide cardinality, freshness, fallback, and before/after storage behavior",
            "required_before_apply": [
                "multi_anchor_live_scenario_corpus",
                "materialized_replacement_projection",
                "global_before_after_cardinality_comparison",
                "operator_reviewed_mutation_boundary",
            ],
            "mutation_boundary": "read_only_proof_packet_no_graph_rows_are_deleted_or_rebuilt",
        },
        "next_route": "run this proof across more dense anchors, then materialize the entity-usage rollup only after corpus and cardinality comparison stay green",
        "exact_read_command": entity_usage_chain_command(
            "graph-entity-usage-replacement-proof",
            anchor=anchor,
            kind=normalized_kind,
            aoa_root=aoa_root,
            limit=selected_limit,
            per_route_limit=selected_per_route_limit,
            extra=["--sample-limit", str(selected_sample_limit)],
        ),
        "authority_boundary": "replacement proof is generated route evidence; raw/segment refs and owner source surfaces remain stronger",
        "elapsed_ms": int((time.monotonic() - started_at) * 1000),
        "diagnostics": diagnostics,
    }
    if write_report:
        stem = f"{compact_stamp()}__graph-entity-usage-replacement-proof"
        report_json, report_md = reserve_diagnostic_report_paths(aoa_root / DIAGNOSTICS_ROOT, stem)
        write_json(report_json, payload)
        write_markdown(report_md, json_markdown_report("Graph Entity Usage Replacement Proof", payload))
        payload["report_json"] = str(report_json)
        payload["report_md"] = str(report_md)
    return payload


def normalize_graph_replacement_probes(
    probes: list[dict[str, Any]] | None,
    *,
    limit: int,
    per_route_limit: int,
    consequence_window: int,
    sample_limit: int,
) -> list[dict[str, Any]]:
    source = probes if probes else list(GRAPH_ENTITY_USAGE_REPLACEMENT_DEFAULT_PROBES)
    normalized: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for index, probe in enumerate(source):
        if not isinstance(probe, dict):
            continue
        anchor = str(probe.get("anchor") or probe.get("query") or "").strip()
        if not anchor:
            continue
        raw_kind = str(probe.get("kind") or "auto")
        normalized_kind = normalize_trace_route_kind(raw_kind)
        if normalized_kind not in TRACE_ROUTE_KINDS:
            normalized_kind = "auto"
        key = (anchor, normalized_kind)
        if key in seen:
            continue
        seen.add(key)
        normalized.append(
            {
                "name": str(probe.get("name") or route_key_slug(anchor, fallback=f"probe_{index}", max_chars=80)),
                "anchor": anchor,
                "kind": normalized_kind,
                "limit": max(1, min(int_value(probe.get("limit"), limit), 20)),
                "per_route_limit": max(1, min(int_value(probe.get("per_route_limit"), per_route_limit), 80)),
                "consequence_window": max(0, min(int_value(probe.get("consequence_window"), consequence_window), 40)),
                "sample_limit": max(1, min(int_value(probe.get("sample_limit"), sample_limit), 40)),
            }
        )
    return normalized


def graph_replacement_probe_summary(
    *,
    probe: dict[str, Any],
    proof: dict[str, Any],
    elapsed_ms: int,
) -> dict[str, Any]:
    usage_chain = proof.get("usage_chain") if isinstance(proof.get("usage_chain"), dict) else {}
    graph_sample = proof.get("graph_sample") if isinstance(proof.get("graph_sample"), dict) else {}
    edge_match = proof.get("edge_match") if isinstance(proof.get("edge_match"), dict) else {}
    proof_summary = proof.get("proof_gate_summary") if isinstance(proof.get("proof_gate_summary"), dict) else {}
    prune_gate = proof.get("prune_gate") if isinstance(proof.get("prune_gate"), dict) else {}
    diagnostics = [str(item) for item in proof.get("diagnostics", []) if item] if isinstance(proof.get("diagnostics"), list) else []
    failed_core_gate_count = int_value(proof_summary.get("failed_core_gate_count"))
    missing_edge_count = int_value(edge_match.get("missing_count"))
    usage_event_count = int_value(usage_chain.get("usage_event_count"))
    deferred_live_usage_event_count = int_value(usage_chain.get("deferred_live_usage_event_count"))
    checked_count = int_value(edge_match.get("checked_count"))
    target_projection = str(proof.get("target_projection") or "")
    post_prune_aggregate_mode = bool(
        proof.get("post_prune_aggregate_mode") is True
        or graph_sample.get("post_prune_aggregate_mode") is True
        or edge_match.get("post_prune_aggregate_mode") is True
        or edge_match.get("matching_mode") == "post_prune_aggregate_refs"
    )
    accepted_deferred_live = bool(
        deferred_live_usage_event_count > 0
        and usage_event_count <= 0
        and checked_count <= 0
        and missing_edge_count <= 0
        and failed_core_gate_count <= 0
    )
    quality_flags: list[str] = []
    if not proof.get("ok") and not accepted_deferred_live:
        quality_flags.append("graph_replacement_probe_not_ok")
    if usage_event_count <= 0 and not accepted_deferred_live:
        quality_flags.append("graph_replacement_probe_no_usage_events")
    if checked_count <= 0 and not accepted_deferred_live:
        quality_flags.append(
            "graph_replacement_probe_only_deferred_live_event_edges"
            if deferred_live_usage_event_count
            else "graph_replacement_probe_no_checked_event_edges"
        )
    if missing_edge_count > 0 and not post_prune_aggregate_mode:
        quality_flags.append("graph_replacement_probe_missing_event_edges")
    if failed_core_gate_count > 0:
        quality_flags.append("graph_replacement_probe_failed_core_gates")
    if prune_gate.get("apply_ready") is not False:
        quality_flags.append("graph_replacement_probe_prune_gate_not_closed")
    if target_projection != GRAPH_ENTITY_USAGE_REPLACEMENT_TARGET_PROJECTION:
        quality_flags.append("graph_replacement_probe_target_projection_mismatch")
    if diagnostics:
        quality_flags.append("graph_replacement_probe_diagnostics_present")
    status = "failed" if quality_flags else "passed"
    return {
        "name": probe.get("name"),
        "anchor": probe.get("anchor"),
        "kind": proof.get("kind") or probe.get("kind"),
        "status": status,
        "ok": not quality_flags,
        "accepted_deferred_live": accepted_deferred_live,
        "elapsed_ms": elapsed_ms,
        "target_projection": target_projection,
        "replacement_scope": proof.get("replacement_scope"),
        "post_prune_aggregate_mode": post_prune_aggregate_mode,
        "matching_mode": edge_match.get("matching_mode"),
        "proof_mode": graph_sample.get("proof_mode"),
        "usage_event_count": usage_event_count,
        "usage_event_harvest_count": int_value(usage_chain.get("usage_event_harvest_count")),
        "stable_usage_event_count": int_value(usage_chain.get("stable_usage_event_count")),
        "deferred_live_usage_event_count": deferred_live_usage_event_count,
        "raw_or_segment_ref_count": int_value(usage_chain.get("raw_or_segment_ref_count")),
        "graph_event_edge_checked_count": checked_count,
        "graph_event_edge_match_count": int_value(edge_match.get("matched_count")),
        "graph_event_edge_missing_count": missing_edge_count,
        "event_edge_count": int_value(graph_sample.get("event_edge_count")),
        "session_aggregate_edge_count": int_value(graph_sample.get("session_aggregate_edge_count")),
        "anchor_sample_reduction_ratio": graph_sample.get("anchor_sample_reduction_ratio"),
        "proof_failed_core_gate_count": failed_core_gate_count,
        "proof_not_proven_gate_count": int_value(proof_summary.get("not_proven_gate_count")),
        "replacement_prune_apply_ready": prune_gate.get("apply_ready"),
        "replacement_prune_gate_status": prune_gate.get("status"),
        "first_ref": usage_chain.get("first_ref") if isinstance(usage_chain.get("first_ref"), dict) else {},
        "quality_flags": quality_flags,
    }


def graph_high_fanout_replacement_scenario_audit(
    *,
    aoa_root: Path,
    probes: list[dict[str, Any]] | None = None,
    limit: int = 1,
    per_route_limit: int = 4,
    consequence_window: int = 4,
    sample_limit: int = 1,
    provider: str = "portable_sqlite",
) -> dict[str, Any]:
    started = time.monotonic()
    selected_limit = max(1, min(int_value(limit, 1), 20))
    selected_per_route_limit = max(selected_limit, min(int_value(per_route_limit, 4), 80))
    selected_sample_limit = max(1, min(int_value(sample_limit, 1), 40))
    selected_consequence_window = max(0, min(int_value(consequence_window, 4), 40))
    normalized_probes = normalize_graph_replacement_probes(
        probes,
        limit=selected_limit,
        per_route_limit=selected_per_route_limit,
        consequence_window=selected_consequence_window,
        sample_limit=selected_sample_limit,
    )
    samples: list[dict[str, Any]] = []
    for probe in normalized_probes:
        probe_started = time.monotonic()
        try:
            proof = graph_entity_usage_replacement_proof(
                aoa_root=aoa_root,
                anchor=str(probe["anchor"]),
                kind=str(probe["kind"]),
                limit=int_value(probe.get("limit"), selected_limit),
                per_route_limit=int_value(probe.get("per_route_limit"), selected_per_route_limit),
                consequence_window=int_value(probe.get("consequence_window"), selected_consequence_window),
                sample_limit=int_value(probe.get("sample_limit"), selected_sample_limit),
                provider=provider,
                write_report=False,
            )
            elapsed_ms = int((time.monotonic() - probe_started) * 1000)
            samples.append(graph_replacement_probe_summary(probe=probe, proof=proof, elapsed_ms=elapsed_ms))
        except Exception as exc:  # pragma: no cover - defensive route packet
            samples.append(
                {
                    "name": probe.get("name"),
                    "anchor": probe.get("anchor"),
                    "kind": probe.get("kind"),
                    "status": "failed",
                    "ok": False,
                    "elapsed_ms": int((time.monotonic() - probe_started) * 1000),
                    "error": str(exc)[:500],
                    "quality_flags": ["graph_replacement_probe_exception"],
                }
            )
    status_counts = Counter(str(sample.get("status") or "unknown") for sample in samples)
    kind_counts = Counter(str(sample.get("kind") or "unknown") for sample in samples if sample.get("kind"))
    anchor_counts = Counter(str(sample.get("anchor") or "") for sample in samples if sample.get("anchor"))
    quality = {
        "sample_count": len(samples),
        "passed_count": status_counts.get("passed", 0),
        "warn_count": status_counts.get("warn", 0),
        "failed_count": status_counts.get("failed", 0),
        "kind_counts": dict(sorted(kind_counts.items())),
        "anchor_count": len(anchor_counts),
        "anchor_counts": dict(sorted(anchor_counts.items())),
        "usage_event_count": sum(int_value(sample.get("usage_event_count")) for sample in samples),
        "usage_event_harvest_count": sum(int_value(sample.get("usage_event_harvest_count")) for sample in samples),
        "stable_usage_event_count": sum(int_value(sample.get("stable_usage_event_count")) for sample in samples),
        "deferred_live_usage_event_count": sum(int_value(sample.get("deferred_live_usage_event_count")) for sample in samples),
        "accepted_deferred_live_probe_count": sum(1 for sample in samples if sample.get("accepted_deferred_live") is True),
        "post_prune_aggregate_probe_count": sum(1 for sample in samples if sample.get("post_prune_aggregate_mode") is True),
        "raw_or_segment_ref_count": sum(int_value(sample.get("raw_or_segment_ref_count")) for sample in samples),
        "graph_event_edge_checked_count": sum(int_value(sample.get("graph_event_edge_checked_count")) for sample in samples),
        "graph_event_edge_match_count": sum(int_value(sample.get("graph_event_edge_match_count")) for sample in samples),
        "graph_event_edge_missing_count": sum(int_value(sample.get("graph_event_edge_missing_count")) for sample in samples),
        "event_edge_count": sum(int_value(sample.get("event_edge_count")) for sample in samples),
        "session_aggregate_edge_count": sum(int_value(sample.get("session_aggregate_edge_count")) for sample in samples),
        "proof_failed_core_gate_count": sum(int_value(sample.get("proof_failed_core_gate_count")) for sample in samples),
        "proof_not_proven_gate_count": sum(int_value(sample.get("proof_not_proven_gate_count")) for sample in samples),
        "replacement_prune_open_count": sum(1 for sample in samples if sample.get("replacement_prune_apply_ready") is not False),
        "target_projection_match_count": sum(
            1
            for sample in samples
            if sample.get("target_projection") == GRAPH_ENTITY_USAGE_REPLACEMENT_TARGET_PROJECTION
        ),
        "max_sample_elapsed_ms": max((int_value(sample.get("elapsed_ms")) for sample in samples), default=0),
        "elapsed_ms": int((time.monotonic() - started) * 1000),
    }
    first_ref = next(
        (
            sample.get("first_ref")
            for sample in samples
            if isinstance(sample.get("first_ref"), dict) and sample.get("first_ref")
        ),
        {},
    )
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_high_fanout_replacement_scenario_audit",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": bool(samples) and quality["failed_count"] == 0,
        "mutates": False,
        "truth_status": "multi_anchor_graph_replacement_live_scenario_not_prune_permission",
        "target_projection": GRAPH_ENTITY_USAGE_REPLACEMENT_TARGET_PROJECTION
        if samples and quality["target_projection_match_count"] == len(samples)
        else "",
        "replacement_scope": "multi_anchor_sample" if len(samples) > 1 else "anchor_sample",
        "samples": samples,
        "quality": quality,
        "first_ref": first_ref,
        "prune_gate": {
            "status": "blocked_multi_anchor_sample_only",
            "apply_ready": False,
            "can_prune_now": False,
            "reason": "multi-anchor replacement proof is still read-only route evidence and not an archive-wide prune permission",
            "required_before_apply": [
                "materialized_replacement_projection",
                "global_before_after_cardinality_comparison",
                "freshness_current_after_rebuild",
                "operator_reviewed_mutation_boundary",
            ],
            "mutation_boundary": "read_only_scenario_packet_no_graph_rows_are_deleted_or_rebuilt",
        },
        "next_route": "materialize the entity-usage rollup only after this corpus stays green and a separate before/after storage comparison proves equal-or-better recall",
        "authority_boundary": "scenario audit is generated route evidence; raw/segment refs and owner source surfaces remain stronger",
    }


def graph_node_by_id(graph: dict[str, Any]) -> dict[str, dict[str, Any]]:
    return {str(node.get("id")): node for node in graph.get("nodes", []) if isinstance(node, dict) and node.get("id")}


def graph_edge_by_id(graph: dict[str, Any]) -> dict[str, dict[str, Any]]:
    return {str(edge.get("id")): edge for edge in graph.get("edges", []) if isinstance(edge, dict) and edge.get("id")}


def graph_anchor_alias_keys(anchor: str) -> list[str]:
    aliases = trace_anchor_aliases(anchor)
    keys = [route_key_slug(alias, fallback="", max_chars=120) for alias in aliases]
    return [key for key in dict.fromkeys(keys) if key]


def graph_node_anchor_score(node: dict[str, Any], alias_keys: list[str]) -> int:
    values = [
        node.get("id"),
        node.get("label"),
        node.get("title"),
        node.get("route_key"),
        node.get("route_signal"),
        node.get("session_label"),
        node.get("event_type"),
        node.get("raw_ref"),
        node.get("work_root"),
    ]
    value_keys = [route_key_slug(value, fallback="", max_chars=180) for value in values if value]
    score = 0
    for alias in alias_keys:
        for value in value_keys:
            if not value:
                continue
            if alias == value:
                score = max(score, 100)
            elif len(alias) >= 3 and alias in value:
                score = max(score, 50)
            elif len(value) >= 3 and value in alias:
                score = max(score, 25)
    return score


TRACE_ROUTE_KIND_EXACT_GRAPH_LAYERS: dict[str, frozenset[str]] = {
    "hook": frozenset({"hook", "hook_health"}),
    "receipt": frozenset({"hook_health"}),
    "failure": frozenset({"failure_mode"}),
    "error": frozenset({"error", "failure_mode"}),
    "decision": frozenset({"decision", "decision_thread"}),
    "external": frozenset({"external_snapshot"}),
    "github": frozenset(
        {"github", "git", "external_snapshot"}
    ),
}


def graph_typed_route_layer_is_compatible(
    route_kind: str,
    route_layer: str,
) -> bool:
    if route_kind == "auto":
        return True
    allowed = TRACE_ROUTE_KIND_EXACT_GRAPH_LAYERS.get(
        route_kind,
        frozenset({route_kind}),
    )
    return route_layer in allowed


def graph_route_candidate_is_exact_anchor(
    candidate: dict[str, Any],
    *,
    anchor: str,
    route_kind: str,
) -> bool:
    layer = str(candidate.get("layer") or "")
    key = str(candidate.get("key") or "")
    if (
        not key
        or trace_route_candidate_is_generic(candidate)
        or not graph_typed_route_layer_is_compatible(route_kind, layer)
    ):
        return False
    if route_kind != "auto":
        return True
    return trace_route_candidate_matches_anchor(
        candidate,
        anchor=anchor,
    )


def graph_store_fetch_payloads(conn: sqlite3.Connection, table: str, ids: list[str]) -> list[dict[str, Any]]:
    if not ids:
        return []
    rows: list[dict[str, Any]] = []
    for item_id in ids:
        row = conn.execute(f"SELECT payload_json, count FROM {table} WHERE id = ?", (item_id,)).fetchone()
        if not row:
            continue
        payload = json.loads(str(row["payload_json"]))
        if isinstance(payload, dict):
            payload["count"] = int_value(row["count"], int_value(payload.get("count"), 1))
            rows.append(payload)
    return graph_hydrate_store_payload_evidence(conn, table, rows)


def graph_store_resolve_anchor(
    conn: sqlite3.Connection,
    anchor: str,
    *,
    kind: str = "auto",
    limit: int = 40,
) -> dict[str, Any]:
    normalized_kind = normalize_trace_route_kind(kind)
    route_kind = normalized_kind if normalized_kind in TRACE_ROUTE_KINDS else "auto"
    candidates = trace_route_candidates(anchor, kind=route_kind)
    diagnostics = trace_identity_diagnostics(anchor, kind=route_kind)
    lookup_candidates = trace_route_lookup_candidates(candidates, suppress_generic=bool(diagnostics))
    ordered_lookup_candidates = sorted(
        lookup_candidates,
        key=lambda candidate: (
            0
            if str(candidate.get("layer") or "") == route_kind
            else 1
            if str(candidate.get("layer") or "") != "entity"
            else 2,
            str(candidate.get("layer") or ""),
            str(candidate.get("key") or ""),
        ),
    )
    start_node_ids: list[str] = []
    exact_route_node_ids: list[str] = []
    for candidate in ordered_lookup_candidates:
        layer = str(candidate.get("layer") or "")
        key = str(candidate.get("key") or "")
        if (
            graph_route_candidate_is_exact_anchor(
                candidate,
                anchor=anchor,
                route_kind=route_kind,
            )
        ):
            route_node = graph_route_node_id(layer, key)
            row = conn.execute("SELECT id FROM nodes WHERE id = ?", (route_node,)).fetchone()
            if row and route_node not in start_node_ids:
                start_node_ids.append(route_node)
                exact_route_node_ids.append(route_node)
    alias_keys = graph_anchor_alias_keys(anchor)
    exact_node_id = str(anchor or "").strip()
    if exact_node_id:
        exact_node_row = conn.execute(
            "SELECT id, payload_json FROM nodes WHERE id = ?",
            (exact_node_id,),
        ).fetchone()
        if exact_node_row:
            exact_node_payload: dict[str, Any] = {}
            try:
                parsed_exact_node_payload = json.loads(
                    str(exact_node_row["payload_json"] or "{}")
                )
                if isinstance(parsed_exact_node_payload, dict):
                    exact_node_payload = parsed_exact_node_payload
            except (json.JSONDecodeError, TypeError):
                exact_node_payload = {}
            exact_node_parts = exact_node_id.split(":")
            exact_route_layer = (
                str(exact_node_payload.get("route_layer") or "")
                or exact_node_parts[2]
                if exact_node_id.startswith("route:")
                and len(exact_node_parts) >= 4
                else ""
            )
            if (
                route_kind != "auto"
                and exact_route_layer
                and not graph_typed_route_layer_is_compatible(
                    route_kind,
                    exact_route_layer,
                )
            ):
                diagnostics = list(
                    dict.fromkeys(
                        [
                            *diagnostics,
                            (
                                "exact_graph_node_kind_mismatch:"
                                f"requested={route_kind}:"
                                f"observed={exact_route_layer}"
                            ),
                        ]
                    )
                )
            else:
                return {
                    "anchor": anchor,
                    **trace_kind_payload_fields(kind, route_kind),
                    "aliases": trace_anchor_aliases(anchor),
                    "alias_keys": alias_keys,
                    "route_candidates": lookup_candidates,
                    "start_node_ids": [exact_node_id],
                    "resolver_strategy": "exact_node_id",
                    "diagnostics": diagnostics,
                }
    if route_kind != "auto":
        direct_key = route_key_slug(
            anchor,
            fallback="",
            max_chars=96 if route_kind == "path" else 120,
        )
        direct_route_node = graph_route_node_id(route_kind, direct_key) if direct_key else ""
        if direct_route_node:
            direct_route_row = conn.execute("SELECT id FROM nodes WHERE id = ?", (direct_route_node,)).fetchone()
            if direct_route_row:
                return {
                    "anchor": anchor,
                    **trace_kind_payload_fields(kind, route_kind),
                    "aliases": trace_anchor_aliases(anchor),
                    "alias_keys": alias_keys,
                    "route_candidates": lookup_candidates,
                    "start_node_ids": [direct_route_node],
                    "resolver_strategy": "exact_typed_route_key",
                    "diagnostics": diagnostics,
                }
    raw_ref_anchor = re.fullmatch(r"raw:line:\d+", exact_node_id, flags=re.IGNORECASE)
    if raw_ref_anchor:
        # A raw line number is local to a transcript, never a globally stable
        # graph identity.  Reject it even when today's store happens to expose
        # only one match: a later indexed session can create the same line and
        # silently change the answer.  Event ids mirror the padded raw line, so
        # a bounded id sample remains useful without scanning compacted JSON
        # payloads whose refs may have moved into node_contribs.
        raw_line = int(exact_node_id.rsplit(":", 1)[-1])
        candidate_limit = max(20, min(max(20, limit), 200))
        raw_rows = conn.execute(
            "SELECT id FROM nodes WHERE node_type = 'event' AND id GLOB ? ORDER BY id LIMIT ?",
            (f"event:*:*:{raw_line:06d}", candidate_limit + 1),
        ).fetchall()
        raw_event_ids = [str(row["id"]) for row in raw_rows[:candidate_limit]]
        raw_sessions = {
            parts[1]
            for node_id in raw_event_ids
            for parts in [node_id.split(":")]
            if len(parts) >= 4 and parts[1]
        }
        return {
            "anchor": anchor,
            **trace_kind_payload_fields(kind, route_kind),
            "aliases": trace_anchor_aliases(anchor),
            "alias_keys": alias_keys,
            "route_candidates": lookup_candidates,
            "start_node_ids": [],
            "candidate_node_ids": raw_event_ids[: min(limit, 20)],
            "candidate_session_count": len(raw_sessions),
            "candidate_sample_truncated": len(raw_rows) > candidate_limit,
            "scope_requirement": "session_scoped_event_node_id",
            "resolver_strategy": "ambiguous_raw_ref_requires_session_scope",
            "diagnostics": [
                *diagnostics,
                "ambiguous_raw_ref_requires_session_scoped_event_node_id",
            ],
        }
    if exact_route_node_ids and ":" not in str(anchor or ""):
        return {
            "anchor": anchor,
            **trace_kind_payload_fields(kind, route_kind),
            "aliases": trace_anchor_aliases(anchor),
            "alias_keys": alias_keys,
            "route_candidates": lookup_candidates,
            "start_node_ids": start_node_ids[:limit],
            "resolver_strategy": "exact_route_node",
            "diagnostics": diagnostics,
        }
    if diagnostics and not lookup_candidates:
        return {
            "anchor": anchor,
            **trace_kind_payload_fields(kind, route_kind),
            "aliases": trace_anchor_aliases(anchor),
            "alias_keys": alias_keys,
            "route_candidates": [],
            "start_node_ids": [],
            "resolver_strategy": "identity_diagnostic_no_route",
            "diagnostics": diagnostics,
        }
    # The graph store is a traversal projection, not a second full-text index.
    # Leading-wildcard scans over payload_json make an absent anchor cost scale
    # with the complete node table and duplicate the bounded retrieval route.
    # Resolve only indexed node/route identities here; let trace/search produce
    # the evidence-bearing seed when exact graph identity is unavailable.
    if exact_route_node_ids:
        return {
            "anchor": anchor,
            **trace_kind_payload_fields(kind, route_kind),
            "aliases": trace_anchor_aliases(anchor),
            "alias_keys": alias_keys,
            "route_candidates": lookup_candidates,
            "start_node_ids": exact_route_node_ids[:limit],
            "exact_start_node_ids": exact_route_node_ids[:limit],
            "candidate_node_ids": [],
            "resolver_strategy": "exact_route_node",
            "diagnostics": diagnostics,
        }
    return {
        "anchor": anchor,
        **trace_kind_payload_fields(kind, route_kind),
        "aliases": trace_anchor_aliases(anchor),
        "alias_keys": alias_keys,
        "route_candidates": lookup_candidates,
        "start_node_ids": [],
        "exact_start_node_ids": exact_route_node_ids[:limit],
        "candidate_node_ids": [],
        "resolver_strategy": "indexed_exact_miss_requires_retrieval_seed",
        "diagnostics": list(
            dict.fromkeys([*diagnostics, "graph_store_unindexed_payload_scan_skipped"])
        ),
    }


def graph_store_neighbor_edge_priority(edge_type: str) -> int:
    return {
        "registry_entity_has_route_signal": 0,
        "event_has_route_signal": 1,
        "segment_has_route_signal": 2,
        "event_has_registered_entity_signal": 3,
        "session_has_registered_entity": 4,
        "has_event": 5,
        "answered_by": 5,
        "responds_to": 5,
        "has_correlated_status": 5,
    }.get(str(edge_type or ""), 6)


def graph_store_neighbor_edge_rows(
    conn: sqlite3.Connection,
    *,
    node_id: str,
    edge_budget: int,
) -> tuple[list[sqlite3.Row], dict[str, Any]]:
    compact_unordered = edge_budget <= 64
    query_limit = max(32, min(200, edge_budget * 8))
    rows: list[sqlite3.Row] = []
    seen: set[str] = set()
    directions: list[dict[str, Any]] = []
    for column in ("source_node", "target_node"):
        if compact_unordered:
            sql = f"""
                SELECT id, source_node, target_node, edge_type, count
                FROM edges
                WHERE {column} = ?
                LIMIT ?
                """
        else:
            sql = f"""
                SELECT id, source_node, target_node, edge_type, count
                FROM edges
                WHERE {column} = ?
                ORDER BY
                  CASE edge_type
                    WHEN 'registry_entity_has_route_signal' THEN 0
                    WHEN 'event_has_route_signal' THEN 1
                    WHEN 'segment_has_route_signal' THEN 2
                    WHEN 'event_has_registered_entity_signal' THEN 3
                    WHEN 'session_has_registered_entity' THEN 4
                    WHEN 'has_event' THEN 5
                    WHEN 'answered_by' THEN 5
                    WHEN 'responds_to' THEN 5
                    WHEN 'has_correlated_status' THEN 5
                    ELSE 6
                  END,
                  count DESC,
                  id ASC
                LIMIT ?
                """
        fetched = conn.execute(sql, (node_id, query_limit)).fetchall()
        directions.append({"column": column, "fetched_count": len(fetched), "query_limit": query_limit})
        for row in fetched:
            edge_id = str(row["id"])
            if edge_id in seen:
                continue
            seen.add(edge_id)
            rows.append(row)
    rows.sort(key=lambda row: (graph_store_neighbor_edge_priority(str(row["edge_type"])), -int_value(row["count"]), str(row["id"])))
    return rows[: max(query_limit, edge_budget)], {
        "strategy": "split_unordered_compact" if compact_unordered else "split_ordered",
        "query_limit": query_limit,
        "directions": directions,
    }


def graph_from_store_neighborhood(
    *,
    aoa_root: Path,
    anchor: str,
    kind: str = "auto",
    depth: int = 1,
    limit: int = 40,
    edge_limit: int | None = None,
) -> dict[str, Any] | None:
    state = graph_store_query_state(aoa_root)
    if state.get("status") != "current":
        return None
    paths = graph_paths(aoa_root)
    try:
        conn = sqlite3.connect(str(paths["store"]))
        conn.row_factory = sqlite3.Row
        resolved = graph_store_resolve_anchor(conn, anchor, kind=kind, limit=max(10, limit))
        if not resolved.get("start_node_ids"):
            conn.close()
            return {
                "schema_version": SCHEMA_VERSION,
                "artifact_type": "session_memory_bounded_graph",
                "graph_schema_version": GRAPH_SCHEMA_VERSION,
                "generated_at": (state.get("metadata") or {}).get("updated_at") or (state.get("metadata") or {}).get("generated_at") or utc_now(),
                "ok": False,
                "truth_status": "bounded_graph_from_sqlite_store_not_reviewed_truth",
                "source": "sqlite_graph_store",
                "aoa_root": str(aoa_root),
                "node_count": 0,
                "edge_count": 0,
                "nodes": [],
                "edges": [],
                "resolved": resolved,
                "store_state": state,
                "diagnostics": [
                    *(state.get("diagnostics", []) if isinstance(state.get("diagnostics"), list) else []),
                    *(resolved.get("diagnostics", []) if isinstance(resolved.get("diagnostics"), list) else []),
                ],
            }
        depth = max(0, min(int_value(depth, 1), 3))
        limit = max(1, min(int_value(limit, 40), 200))
        default_edge_limit = max(24, min(limit * 4, 160))
        max_edges = max(1, min(int_value(edge_limit, default_edge_limit), 2000))
        selected_nodes: list[str] = []
        selected_edges: list[str] = []
        seen_nodes: set[str] = set()
        seen_edges: set[str] = set()
        omitted_node_count = 0
        omitted_edge_count = 0
        edge_query_strategies: Counter[str] = Counter()
        queue_nodes: deque[tuple[str, int]] = deque((node_id, 0) for node_id in resolved["start_node_ids"])
        while queue_nodes and len(selected_nodes) < limit:
            node_id, distance = queue_nodes.popleft()
            if node_id in seen_nodes:
                continue
            seen_nodes.add(node_id)
            selected_nodes.append(node_id)
            if distance >= depth:
                continue
            edge_rows, edge_query = graph_store_neighbor_edge_rows(conn, node_id=node_id, edge_budget=max_edges)
            edge_query_strategies[str(edge_query.get("strategy") or "unknown")] += 1
            for row in edge_rows:
                edge_id = str(row["id"])
                if edge_id not in seen_edges and len(selected_edges) < max_edges:
                    seen_edges.add(edge_id)
                    selected_edges.append(edge_id)
                elif edge_id not in seen_edges:
                    seen_edges.add(edge_id)
                    omitted_edge_count += 1
                neighbor = str(row["target_node"] if row["source_node"] == node_id else row["source_node"])
                if neighbor not in seen_nodes and len(selected_nodes) + len(queue_nodes) < limit:
                    queue_nodes.append((neighbor, distance + 1))
                elif neighbor not in seen_nodes:
                    omitted_node_count += 1
        nodes = graph_store_fetch_payloads(conn, "nodes", selected_nodes)
        edges = graph_store_fetch_payloads(conn, "edges", selected_edges)
        conn.close()
    except sqlite3.Error:
        return None
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_bounded_graph",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": (state.get("metadata") or {}).get("updated_at") or (state.get("metadata") or {}).get("generated_at") or utc_now(),
        "ok": bool(nodes),
        "truth_status": "bounded_graph_from_sqlite_store_not_reviewed_truth",
        "source": "sqlite_graph_store",
        "aoa_root": str(aoa_root),
        "node_count": len(nodes),
        "edge_count": len(edges),
        "node_limit": limit,
        "edge_limit": max_edges,
        "truncated": bool(queue_nodes or omitted_node_count or omitted_edge_count),
        "omitted_node_count": omitted_node_count + len(queue_nodes),
        "omitted_edge_count": omitted_edge_count,
        "nodes": nodes,
        "edges": edges,
        "resolved": resolved,
        "edge_query_strategies": dict(edge_query_strategies),
        "store_state": state,
        "diagnostics": state.get("diagnostics", []) if isinstance(state.get("diagnostics"), list) else [],
    }


def graph_from_store_timeline_events(
    *,
    aoa_root: Path,
    anchor: str,
    kind: str = "auto",
    limit: int = 40,
) -> dict[str, Any] | None:
    state = graph_store_query_state(aoa_root)
    if state.get("status") != "current":
        return None
    paths = graph_paths(aoa_root)
    edge_types = ("event_has_route_signal", "event_has_registered_entity_signal", "goal_lifecycle_has_event")
    route_structural_edge_types = ("goal_lifecycle_has_route_signal",)
    placeholders = ",".join("?" for _item in edge_types)
    route_structural_placeholders = ",".join("?" for _item in route_structural_edge_types)
    event_limit = max(1, min(int_value(limit, 40), 200))
    edge_fetch_limit = max(event_limit, min(event_limit * 8, 400))
    try:
        conn = sqlite3.connect(str(paths["store"]))
        conn.row_factory = sqlite3.Row
        resolved = graph_store_resolve_anchor(conn, anchor, kind=kind, limit=max(10, event_limit))
        start_node_ids = [str(node_id) for node_id in resolved.get("start_node_ids", []) if node_id]
        exact_event_match = (
            re.fullmatch(r"event:([^:]+):([^:]+):(\d+)", start_node_ids[0])
            if len(start_node_ids) == 1 and resolved.get("resolver_strategy") == "exact_node_id"
            else None
        )
        if exact_event_match:
            session_id, segment_id, event_text = exact_event_match.groups()
            event_number = int(event_text)
            before_count = 0 if event_limit == 1 else min(event_number, max(1, event_limit // 3))
            after_count = max(0, event_limit - before_count - 1)
            event_width = max(6, len(event_text))
            low_id = f"event:{session_id}:{segment_id}:{max(0, event_number - before_count):0{event_width}d}"
            high_id = f"event:{session_id}:{segment_id}:{event_number + after_count:0{event_width}d}"
            event_rows = conn.execute(
                """
                SELECT id
                FROM nodes
                WHERE node_type = 'event' AND id >= ? AND id <= ?
                ORDER BY id
                LIMIT ?
                """,
                (low_id, high_id, event_limit),
            ).fetchall()
            event_ids = [str(row["id"]) for row in event_rows]
            edge_ids: list[str] = []
            if event_ids:
                placeholders = ",".join("?" for _item in event_ids)
                edge_rows = conn.execute(
                    f"""
                    SELECT id
                    FROM edges
                    WHERE source_node IN ({placeholders})
                      AND target_node IN ({placeholders})
                    ORDER BY id
                    LIMIT ?
                    """,
                    (*event_ids, *event_ids, max(8, event_limit * 4)),
                ).fetchall()
                edge_ids = [str(row["id"]) for row in edge_rows]
            nodes = graph_store_fetch_payloads(conn, "nodes", event_ids)
            edges = graph_store_fetch_payloads(conn, "edges", edge_ids)
            correlations_by_node: defaultdict[str, list[str]] = defaultdict(list)
            for edge in edges:
                correlation_id = str(edge.get("correlation_id") or "")
                if not correlation_id:
                    continue
                for node_id in (str(edge.get("source") or ""), str(edge.get("target") or "")):
                    if node_id and correlation_id not in correlations_by_node[node_id]:
                        correlations_by_node[node_id].append(correlation_id)
            for node in nodes:
                correlations = correlations_by_node.get(str(node.get("id") or ""), [])
                if correlations:
                    node["correlation_id"] = correlations[0]
                    node["correlation_ids"] = correlations
            conn.close()
            return {
                "schema_version": SCHEMA_VERSION,
                "artifact_type": "session_memory_bounded_graph",
                "graph_schema_version": GRAPH_SCHEMA_VERSION,
                "generated_at": (state.get("metadata") or {}).get("updated_at") or (state.get("metadata") or {}).get("generated_at") or utc_now(),
                "ok": bool(nodes),
                "truth_status": "bounded_event_window_from_sqlite_store_not_reviewed_truth",
                "source": "sqlite_graph_store_direct_timeline",
                "timeline_mode": "exact_event_centered_segment_window",
                "event_window": {
                    "session_id": session_id,
                    "segment_id": segment_id,
                    "anchor_event_id": event_text,
                    "from_event_id": f"{max(0, event_number - before_count):0{event_width}d}",
                    "to_event_id": f"{event_number + after_count:0{event_width}d}",
                },
                "aoa_root": str(aoa_root),
                "node_count": len(nodes),
                "edge_count": len(edges),
                "nodes": nodes,
                "edges": edges,
                "resolved": resolved,
                "store_state": state,
                "diagnostics": state.get("diagnostics", []) if isinstance(state.get("diagnostics"), list) else [],
            }
        event_ids: list[str] = []
        edge_ids: list[str] = []
        structural_node_ids: list[str] = []
        seen_events: set[str] = set()
        seen_edges: set[str] = set()
        seen_structural_nodes: set[str] = set()
        for node_id in start_node_ids:
            if len(event_ids) >= edge_fetch_limit:
                break
            for column, opposite_column in (("target_node", "source_node"), ("source_node", "target_node")):
                remaining = max(1, edge_fetch_limit - len(event_ids))
                rows = conn.execute(
                    f"""
                    SELECT id, source_node, target_node, edge_type
                    FROM edges
                    WHERE {column} = ?
                      AND edge_type IN ({placeholders})
                    LIMIT ?
                    """,
                    (node_id, *edge_types, remaining),
                ).fetchall()
                for row in rows:
                    edge_id = str(row["id"])
                    candidate = str(row[opposite_column])
                    if not candidate.startswith("event:"):
                        continue
                    if edge_id and edge_id not in seen_edges:
                        seen_edges.add(edge_id)
                        edge_ids.append(edge_id)
                    if candidate not in seen_events:
                        seen_events.add(candidate)
                        event_ids.append(candidate)
                    if len(event_ids) >= edge_fetch_limit:
                        break
                if len(event_ids) >= edge_fetch_limit:
                    break
            if len(event_ids) >= edge_fetch_limit:
                break
            for column, opposite_column in (("target_node", "source_node"), ("source_node", "target_node")):
                remaining = max(1, edge_fetch_limit - len(event_ids))
                rows = conn.execute(
                    f"""
                    SELECT id, source_node, target_node, edge_type
                    FROM edges
                    WHERE {column} = ?
                      AND edge_type IN ({route_structural_placeholders})
                    LIMIT ?
                    """,
                    (node_id, *route_structural_edge_types, remaining),
                ).fetchall()
                for row in rows:
                    edge_id = str(row["id"])
                    candidate = str(row[opposite_column])
                    if not candidate.startswith("goal_lifecycle:"):
                        continue
                    if edge_id and edge_id not in seen_edges:
                        seen_edges.add(edge_id)
                        edge_ids.append(edge_id)
                    if candidate not in seen_structural_nodes:
                        seen_structural_nodes.add(candidate)
                        structural_node_ids.append(candidate)
                if len(event_ids) >= edge_fetch_limit:
                    break
        for node_id in structural_node_ids:
            if len(event_ids) >= edge_fetch_limit:
                break
            for column, opposite_column in (("source_node", "target_node"), ("target_node", "source_node")):
                remaining = max(1, edge_fetch_limit - len(event_ids))
                rows = conn.execute(
                    """
                    SELECT id, source_node, target_node, edge_type
                    FROM edges
                    WHERE {column} = ?
                      AND edge_type = 'goal_lifecycle_has_event'
                    LIMIT ?
                    """.format(column=column),
                    (node_id, remaining),
                ).fetchall()
                for row in rows:
                    edge_id = str(row["id"])
                    candidate = str(row[opposite_column])
                    if not candidate.startswith("event:"):
                        continue
                    if edge_id and edge_id not in seen_edges:
                        seen_edges.add(edge_id)
                        edge_ids.append(edge_id)
                    if candidate not in seen_events:
                        seen_events.add(candidate)
                        event_ids.append(candidate)
                    if len(event_ids) >= edge_fetch_limit:
                        break
                if len(event_ids) >= edge_fetch_limit:
                    break
        nodes = graph_store_fetch_payloads(conn, "nodes", [*structural_node_ids, *event_ids])
        edges = graph_store_fetch_payloads(conn, "edges", edge_ids)
        conn.close()
    except sqlite3.Error:
        return None
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_bounded_graph",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": (state.get("metadata") or {}).get("updated_at") or (state.get("metadata") or {}).get("generated_at") or utc_now(),
        "ok": bool(nodes),
        "truth_status": "bounded_graph_timeline_from_sqlite_store_not_reviewed_truth",
        "source": "sqlite_graph_store_direct_timeline",
        "aoa_root": str(aoa_root),
        "node_count": len(nodes),
        "edge_count": len(edges),
        "nodes": nodes,
        "edges": edges,
        "resolved": resolved,
        "store_state": state,
        "diagnostics": state.get("diagnostics", []) if isinstance(state.get("diagnostics"), list) else [],
    }


def resolve_graph_anchor(
    graph: dict[str, Any],
    anchor: str,
    *,
    kind: str = "auto",
    limit: int = 40,
) -> dict[str, Any]:
    node_map = graph_node_by_id(graph)
    normalized_kind = normalize_trace_route_kind(kind)
    route_kind = normalized_kind if normalized_kind in TRACE_ROUTE_KINDS else "auto"
    candidates = trace_route_candidates(anchor, kind=route_kind)
    diagnostics = trace_identity_diagnostics(anchor, kind=route_kind)
    lookup_candidates = trace_route_lookup_candidates(candidates, suppress_generic=bool(diagnostics))
    ordered_lookup_candidates = sorted(
        lookup_candidates,
        key=lambda candidate: (
            0
            if str(candidate.get("layer") or "") == route_kind
            else 1
            if str(candidate.get("layer") or "") != "entity"
            else 2,
            str(candidate.get("layer") or ""),
            str(candidate.get("key") or ""),
        ),
    )
    start_node_ids: list[str] = []
    exact_route_node_ids: list[str] = []
    scored: list[tuple[int, str]] = []

    for candidate in ordered_lookup_candidates:
        layer = str(candidate.get("layer") or "")
        key = str(candidate.get("key") or "")
        if graph_route_candidate_is_exact_anchor(
            candidate,
            anchor=anchor,
            route_kind=route_kind,
        ):
            route_node = graph_route_node_id(layer, key)
            if route_node in node_map and route_node not in start_node_ids:
                start_node_ids.append(route_node)
                exact_route_node_ids.append(route_node)
        elif layer:
            node_type = graph_route_node_type(layer)
            for node_id, node in node_map.items():
                if node.get("type") == node_type and node.get("route_layer") == layer and node_id not in start_node_ids:
                    start_node_ids.append(node_id)
                    if len(start_node_ids) >= limit:
                        break
    alias_keys = graph_anchor_alias_keys(anchor)
    if exact_route_node_ids and ":" not in str(anchor or ""):
        return {
            "anchor": anchor,
            **trace_kind_payload_fields(kind, route_kind),
            "aliases": trace_anchor_aliases(anchor),
            "alias_keys": alias_keys,
            "route_candidates": lookup_candidates,
            "start_node_ids": exact_route_node_ids[:limit],
            "resolver_strategy": "exact_route_node",
            "diagnostics": diagnostics,
        }
    if diagnostics and not lookup_candidates:
        return {
            "anchor": anchor,
            **trace_kind_payload_fields(kind, route_kind),
            "aliases": trace_anchor_aliases(anchor),
            "alias_keys": alias_keys,
            "route_candidates": [],
            "start_node_ids": [],
            "resolver_strategy": "identity_diagnostic_no_route",
            "diagnostics": diagnostics,
        }

    for node_id, node in node_map.items():
        if node_id in start_node_ids:
            continue
        score = graph_node_anchor_score(node, alias_keys)
        if score:
            scored.append((score, node_id))
    for _, node_id in sorted(scored, key=lambda item: (-item[0], item[1])):
        if node_id not in start_node_ids:
            start_node_ids.append(node_id)
        if len(start_node_ids) >= limit:
            break
    return {
        "anchor": anchor,
        **trace_kind_payload_fields(kind, route_kind),
        "aliases": trace_anchor_aliases(anchor),
        "alias_keys": alias_keys,
        "route_candidates": lookup_candidates,
        "start_node_ids": start_node_ids[:limit],
        "exact_start_node_ids": exact_route_node_ids[:limit],
        "candidate_node_ids": [
            node_id for node_id in start_node_ids[:limit] if node_id not in exact_route_node_ids
        ],
        "resolver_strategy": (
            "exact_route_node_with_fuzzy_candidates"
            if exact_route_node_ids
            else "fuzzy_alias_candidates"
        ),
        "diagnostics": diagnostics,
    }


GRAPH_EXACT_PATH_RESOLVER_STRATEGIES = {
    "exact_node_id",
    "exact_typed_route_key",
    "exact_route_node",
    "exact_route_node_with_fuzzy_candidates",
}


def graph_anchor_resolution_status(
    resolved: dict[str, Any],
    *,
    route_kind: str,
) -> str:
    start_node_ids = [
        str(node_id)
        for node_id in resolved.get("start_node_ids", [])
        if node_id
    ]
    if not start_node_ids:
        return "unresolved"
    strategy = str(resolved.get("resolver_strategy") or "")
    if strategy in GRAPH_EXACT_PATH_RESOLVER_STRATEGIES:
        return "exact"
    if normalize_trace_route_kind(route_kind) != "auto":
        return "candidate_only"
    return "candidate"


def graph_path_resolved_node_ids(
    resolved: dict[str, Any],
    *,
    route_kind: str,
    role: str,
) -> tuple[list[str], list[str]]:
    start_node_ids = [
        str(node_id)
        for node_id in resolved.get("start_node_ids", [])
        if node_id
    ]
    normalized_kind = normalize_trace_route_kind(route_kind)
    if normalized_kind == "auto":
        return start_node_ids, []
    status = graph_anchor_resolution_status(resolved, route_kind=normalized_kind)
    if status != "exact":
        return [], [f"typed_{role}_requires_exact_resolution"]
    if resolved.get("resolver_strategy") == "exact_route_node_with_fuzzy_candidates":
        exact_start_node_ids = [
            str(node_id)
            for node_id in resolved.get("exact_start_node_ids", [])
            if node_id
        ]
        if not exact_start_node_ids:
            return [], [f"typed_{role}_requires_exact_resolution"]
        return exact_start_node_ids, []
    return start_node_ids, []


def graph_adjacency(edges: list[dict[str, Any]]) -> dict[str, list[tuple[str, str]]]:
    adjacency: dict[str, list[tuple[str, str]]] = defaultdict(list)
    for edge in edges:
        if not isinstance(edge, dict):
            continue
        source = str(edge.get("source") or "")
        target = str(edge.get("target") or "")
        edge_id = str(edge.get("id") or "")
        if not source or not target:
            continue
        adjacency[source].append((target, edge_id))
        adjacency[target].append((source, edge_id))
    return adjacency


def graph_expand_node_ids(
    start_node_ids: list[str],
    *,
    edges: list[dict[str, Any]],
    depth: int,
    max_nodes: int,
    max_edges: int | None = None,
) -> tuple[list[str], list[str], dict[str, int | bool]]:
    adjacency = graph_adjacency(edges)
    selected_nodes: list[str] = []
    selected_edges: list[str] = []
    seen_nodes: set[str] = set()
    seen_edges: set[str] = set()
    edge_budget = max(1, min(int_value(max_edges, max(24, min(max_nodes * 4, 160))), 2000))
    omitted_node_count = 0
    omitted_edge_count = 0
    queue: deque[tuple[str, int]] = deque((node_id, 0) for node_id in start_node_ids)
    while queue and len(selected_nodes) < max_nodes:
        node_id, distance = queue.popleft()
        if node_id in seen_nodes:
            continue
        seen_nodes.add(node_id)
        selected_nodes.append(node_id)
        if distance >= depth:
            continue
        for neighbor, edge_id in adjacency.get(node_id, []):
            if edge_id and edge_id not in seen_edges and len(selected_edges) < edge_budget:
                seen_edges.add(edge_id)
                selected_edges.append(edge_id)
            elif edge_id and edge_id not in seen_edges:
                seen_edges.add(edge_id)
                omitted_edge_count += 1
            if neighbor not in seen_nodes and len(selected_nodes) + len(queue) < max_nodes:
                queue.append((neighbor, distance + 1))
            elif neighbor not in seen_nodes:
                omitted_node_count += 1
    return selected_nodes, selected_edges, {
        "edge_limit": edge_budget,
        "truncated": bool(queue or omitted_node_count or omitted_edge_count),
        "omitted_node_count": omitted_node_count + len(queue),
        "omitted_edge_count": omitted_edge_count,
    }


def graph_collect_evidence(
    nodes: list[dict[str, Any]],
    edges: list[dict[str, Any]],
    *,
    limit: int = 50,
) -> list[Any]:
    evidence: list[Any] = []
    for item in [*nodes, *edges]:
        if not isinstance(item, dict):
            continue
        if isinstance(item.get("evidence_refs"), list):
            evidence.extend(item["evidence_refs"])
        refs = item.get("refs")
        if isinstance(refs, dict) and refs:
            evidence.append({"node_id": item.get("id"), "refs": refs})
    return graph_unique_records(evidence, limit=limit)


def graph_compact_node_for_packet(node: dict[str, Any], *, evidence_limit: int = 3) -> dict[str, Any]:
    compact = dict(node)
    if isinstance(compact.get("evidence_refs"), list):
        if not isinstance(compact.get("refs"), dict) or not compact.get("refs"):
            for ref in compact["evidence_refs"]:
                refs = ref.get("refs") if isinstance(ref, dict) and isinstance(ref.get("refs"), dict) else {}
                if refs:
                    compact["refs"] = refs
                    break
        compact["evidence_refs"] = compact["evidence_refs"][:evidence_limit]
        if len(node.get("evidence_refs", [])) > evidence_limit:
            compact["evidence_ref_count"] = len(node.get("evidence_refs", []))
    if isinstance(compact.get("route_signals"), list):
        compact["route_signals"] = compact["route_signals"][:20]
    return compact


def graph_compact_edge_for_packet(edge: dict[str, Any], *, evidence_limit: int = 2) -> dict[str, Any]:
    compact = dict(edge)
    if isinstance(compact.get("evidence_refs"), list):
        compact["evidence_refs"] = compact["evidence_refs"][:evidence_limit]
        if len(edge.get("evidence_refs", [])) > evidence_limit:
            compact["evidence_ref_count"] = len(edge.get("evidence_refs", []))
    return compact


def graph_relation_packet_admission(
    edges: Iterable[dict[str, Any]],
    *,
    has_nodes: bool = False,
    truncated: bool = False,
    freshness: dict[str, Any] | None = None,
) -> dict[str, Any]:
    normalized_edges = [
        graph_relation_contract_payload(edge)
        for edge in edges
        if isinstance(edge, dict)
    ]
    relation_states = Counter(
        str(edge.get("relation_state") or "unclassified")
        for edge in normalized_edges
    )
    relation_families = Counter(
        str(edge.get("relation_family") or "unclassified_candidate")
        for edge in normalized_edges
    )
    rejected_correlations = [
        {
            "edge_id": str(edge.get("id") or ""),
            "edge_type": str(edge.get("type") or ""),
            "correlation_status": str(
                edge.get("correlation_status") or ""
            ),
            "correlation_identity": edge.get("correlation_identity"),
        }
        for edge in normalized_edges
        if str(edge.get("correlation_status") or "")
        in {"missing", "mismatched_identity"}
    ]
    invalid_relations = [
        {
            "edge_id": str(edge.get("id") or ""),
            "edge_type": str(edge.get("type") or ""),
            "domain": edge.get("domain"),
            "range": edge.get("range"),
        }
        for edge in normalized_edges
        if str(edge.get("domain_range_status") or "") == "invalid"
    ]
    unresolved_evidence_count = sum(
        1
        for edge in normalized_edges
        if str(edge.get("evidence_status") or "") != "present"
    )
    observed_count = relation_states["observed_projection"]
    candidate_count = relation_states["inferred_candidate"]
    rejected_count = relation_states["rejected"]
    navigation_admissible = bool(
        (normalized_edges or has_nodes)
        and not rejected_count
        and not invalid_relations
        and not rejected_correlations
    )
    if rejected_count or invalid_relations or rejected_correlations:
        status = "rejected_invalid_relation_context"
    elif truncated:
        status = "bounded_navigation_truncated"
    elif candidate_count:
        status = "candidate_navigation_requires_source_admission"
    elif observed_count:
        status = "observed_projection_navigation_requires_evidence_read"
    elif has_nodes:
        status = "node_navigation_without_relation_claim"
    else:
        status = "no_relation_evidence"
    freshness_payload = freshness if isinstance(freshness, dict) else {}
    return {
        "schema": "aoa_session_memory_graph_relation_admission_v1",
        "relation_contract_version": GRAPH_RELATION_CONTRACT_VERSION,
        "admitted": False,
        "answer_admissible": False,
        "navigation_admissible": navigation_admissible,
        "status": status,
        "insufficiency_reason": (
            "graph projections and traversal candidates require bounded "
            "source-aware evidence reading through the requested claim-shape gate"
        ),
        "edge_count": len(normalized_edges),
        "relation_state_counts": dict(sorted(relation_states.items())),
        "relation_family_counts": dict(sorted(relation_families.items())),
        "unresolved_evidence_edge_count": unresolved_evidence_count,
        "rejected_correlations": rejected_correlations[:12],
        "invalid_relations": invalid_relations[:12],
        "truncated": bool(truncated),
        "freshness_context": {
            "global_status": str(
                freshness_payload.get("global_recall_status")
                or freshness_payload.get("status")
                or "unresolved"
            ),
            "scoped_status": str(
                freshness_payload.get("scope_status")
                or freshness_payload.get("neighborhood_scope_status")
                or "unresolved"
            ),
        },
        "claim_shape_gates": {
            "relationship": {
                "admitted": False,
                "requires": (
                    "typed directed observed relation, resolvable refs, "
                    "compatible generation, and bounded source read"
                ),
            },
            "usage_or_consequence": {
                "admitted": False,
                "requires": (
                    "explicit lifecycle state plus correlation-matched "
                    "invocation, result, verification, and consequence evidence"
                ),
                "mention_is_usage": False,
            },
            "temporal_interval": {
                "admitted": False,
                "requires": (
                    "ordered internal source events, compatible temporal scope, "
                    "resolvable refs, and no critical truncation"
                ),
            },
            "causality": {
                "admitted": False,
                "requires": (
                    "evidence-bearing action/result/verification chain; "
                    "adjacency, cooccurrence, and similarity are insufficient"
                ),
            },
            "quantitative_comparison": {
                "admitted": False,
                "requires": (
                    "compatible subject/context/baseline plus a structured "
                    "measurement action and correlation-owned numeric result"
                ),
            },
            "negative_claim": {
                "admitted": False,
                "requires": (
                    "sufficient bounded coverage and freshness; otherwise unresolved"
                ),
            },
            "current_state": {
                "admitted": False,
                "requires": (
                    "current authoritative owner or runtime evidence outside "
                    "historical graph projection"
                ),
            },
        },
        "next_route": (
            "open the correlation-matched raw or segment refs and apply the "
            "specific claim-shape gate"
        ),
        "authority_boundary": (
            "Graph rows are versioned navigation projections; raw session "
            "evidence and current external owner surfaces remain authoritative."
        ),
    }


def graph_route_signals_from_values(value: Any) -> list[dict[str, str]]:
    if isinstance(value, str):
        tokens = value.strip("|").split("|")
    elif isinstance(value, (list, tuple)):
        tokens = [str(item) for item in value if item]
    else:
        tokens = []
    signals: list[dict[str, str]] = []
    for token in tokens:
        if ":" not in token:
            continue
        layer, key = token.split(":", 1)
        layer_slug = route_key_slug(layer, fallback="")
        key_slug = route_key_slug(key, fallback="")
        if layer_slug and key_slug:
            signals.append({"layer": layer_slug, "key": key_slug, "route_signal": route_signal_token(layer_slug, key_slug)})
    return graph_unique_records(signals, limit=80)


def graph_event_node_from_usage_event(event: dict[str, Any]) -> dict[str, Any]:
    refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
    session_id = str(event.get("session_id") or "")
    segment_id = str(event.get("segment_id") or "")
    event_id = str(event.get("event_id") or "")
    doc_id = str(event.get("doc_id") or "")
    node_id = doc_id if doc_id.startswith("event:") else f"event:{session_id}:{segment_id}:{event_id or route_key_slug(doc_id, fallback='event')}"
    evidence_ref = {
        "session_id": session_id,
        "segment_id": segment_id,
        "event_id": event_id,
        "doc_id": doc_id,
        "refs": refs,
    }
    return {
        "id": node_id,
        "type": "event",
        "label": event.get("title") or doc_id or event_id,
        "title": event.get("title"),
        "session_id": session_id,
        "session_label": event.get("session_label"),
        "session_date": event.get("session_date"),
        "segment_id": segment_id,
        "event_id": event_id,
        "event_type": event.get("event_type"),
        "family": event.get("family"),
        "phase": event.get("phase"),
        "actor": event.get("actor"),
        "action": event.get("action"),
        "outcome": event.get("outcome"),
        "conversation_act": event.get("conversation_act"),
        "session_act": event.get("session_act"),
        "role": event.get("role"),
        "source": event.get("source"),
        "relation": event.get("relation"),
        "distance": event.get("distance"),
        "timestamp": event.get("timestamp") or event.get("session_date"),
        "line": line_from_raw_ref(refs.get("raw")),
        "matched_routes": event.get("matched_routes", []) if isinstance(event.get("matched_routes"), list) else [],
        "route_signals": graph_route_signals_from_values(event.get("route_signals")),
        "refs": refs,
        "freshness": event.get("freshness"),
        "evidence_refs": [evidence_ref],
    }


def graph_route_signals_from_pipe(value: Any) -> list[dict[str, str]]:
    return graph_route_signals_from_values(value)


def graph_search_hit_route_relation(doc_type: str) -> str:
    return {
        "event": "event_has_route_signal",
        "task_episode": "task_episode_has_route_signal",
        "entity_registry": "registry_entity_has_route_signal",
        "segment": "segment_has_route_signal",
        "session": "session_has_route_signal",
        "goal_lifecycle": "goal_lifecycle_has_route_signal",
    }.get(str(doc_type or ""), "document_has_route_signal")


def graph_from_search_results(
    *,
    aoa_root: Path,
    hits: list[dict[str, Any]],
    source: str,
    route_candidates: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    nodes: dict[str, dict[str, Any]] = {}
    edges: dict[str, dict[str, Any]] = {}
    now = utc_now()
    for hit in hits:
        if not isinstance(hit, dict):
            continue
        doc_id = str(hit.get("doc_id") or "")
        parts = doc_id.split(":")
        doc_type = str(
            hit.get("doc_type")
            or ("event" if doc_id.startswith("event:") else "search_hit")
        )
        session_id = str(hit.get("session_id") or "")
        segment_id = str(hit.get("segment_id") or "")
        event_id = str(hit.get("event_id") or "")
        task_episode_id = str(
            hit.get("task_episode_id") or ""
        )
        goal_id = str(hit.get("goal_id") or "")
        entity_id = str(hit.get("entity_id") or "")
        if doc_type == "entity_registry":
            # Search tables reuse session/segment columns for portable
            # document grouping.  Those values are not evidence coordinates
            # for the owner registry and must not fabricate an archived
            # ``entity-registry`` session.
            session_id = ""
            segment_id = ""
            event_id = ""
            if not entity_id and len(parts) >= 2:
                entity_id = ":".join(parts[1:])
        else:
            if not session_id and len(parts) >= 2:
                session_id = parts[1]
            if doc_type == "event":
                if not segment_id and len(parts) >= 3:
                    segment_id = parts[2]
                if not event_id and len(parts) >= 4:
                    event_id = parts[3]
            elif doc_type == "segment":
                if not segment_id and len(parts) >= 3:
                    segment_id = parts[2]
                event_id = ""
            elif doc_type == "task_episode":
                if not task_episode_id:
                    task_episode_id = (
                        parts[2]
                        if len(parts) >= 3
                        else segment_id
                    )
                segment_id = ""
                event_id = ""
            elif doc_type == "goal_lifecycle":
                if not goal_id:
                    goal_id = (
                        parts[2]
                        if len(parts) >= 3
                        else segment_id
                    )
                segment_id = ""
                event_id = ""
            elif doc_type == "session":
                segment_id = ""
                event_id = ""
        session_label = str(
            hit.get("session_label") or session_id
        )
        if doc_type == "entity_registry":
            session_label = ""
        refs = hit.get("refs") if isinstance(hit.get("refs"), dict) else {}
        evidence_ref = {
            "doc_id": doc_id,
            "refs": refs,
        }
        if session_id:
            evidence_ref["session_id"] = session_id
        if segment_id:
            evidence_ref["segment_id"] = segment_id
        if event_id:
            evidence_ref["event_id"] = event_id
        if task_episode_id:
            evidence_ref["task_episode_id"] = (
                task_episode_id
            )
        if goal_id:
            evidence_ref["goal_id"] = goal_id
        if entity_id:
            evidence_ref["entity_id"] = entity_id
        session_node_id = f"session:{session_id or session_label or 'unknown'}"
        if doc_type != "entity_registry":
            graph_add_node(
                nodes,
                {
                    "id": session_node_id,
                    "type": "session",
                    "label": session_label,
                    "session_id": session_id,
                    "session_label": session_label,
                    "refs": (
                        {"session": refs.get("session")}
                        if refs.get("session")
                        else {}
                    ),
                    "evidence_refs": [evidence_ref],
                },
            )
        parent_node_id = session_node_id
        if doc_type == "event" and segment_id:
            segment_node_id = f"segment:{session_id}:{segment_id}"
            graph_add_node(
                nodes,
                {
                    "id": segment_node_id,
                    "type": "segment",
                    "label": f"{session_label} segment {segment_id}",
                    "session_id": session_id,
                    "session_label": session_label,
                    "segment_id": segment_id,
                    "refs": {key: refs.get(key) for key in ("session", "session_index", "segment", "segment_index") if refs.get(key)},
                    "evidence_refs": [evidence_ref],
                },
            )
            graph_add_edge(
                edges,
                {
                    "source": session_node_id,
                    "target": segment_node_id,
                    "type": "has_segment",
                    "session_id": session_id,
                    "segment_id": segment_id,
                    "evidence_refs": [evidence_ref],
                },
            )
            parent_node_id = segment_node_id
        if doc_type == "session":
            evidence_node_id = session_node_id
        elif doc_type == "segment":
            evidence_node_id = (
                doc_id
                if doc_id.startswith("segment:")
                else f"segment:{session_id}:{segment_id}"
            )
        elif doc_type == "event":
            evidence_node_id = (
                doc_id
                if doc_id.startswith("event:")
                else (
                    f"event:{session_id}:{segment_id}:"
                    f"{event_id or route_key_slug(doc_id, fallback='event')}"
                )
            )
        else:
            evidence_node_id = (
                doc_id
                or (
                    f"{route_key_slug(doc_type, fallback='search_hit')}:"
                    f"{session_id}:{route_key_slug(segment_id, fallback='document')}"
                )
            )
        graph_add_node(
            nodes,
            {
                "id": evidence_node_id,
                "type": doc_type,
                "label": hit.get("title") or doc_id,
                "title": hit.get("title"),
                "session_id": session_id,
                "session_label": session_label,
                "segment_id": segment_id,
                "event_id": event_id,
                "task_episode_id": task_episode_id,
                "goal_id": goal_id,
                "entity_id": entity_id,
                "event_type": hit.get("event_type"),
                "family": hit.get("family"),
                "phase": hit.get("phase"),
                "actor": hit.get("actor"),
                "action": hit.get("action"),
                "outcome": hit.get("outcome"),
                "conversation_act": hit.get("conversation_act"),
                "session_act": hit.get("session_act"),
                "route_signals": graph_route_signals_from_pipe(hit.get("route_signals")),
                "refs": refs,
                "freshness": hit.get("freshness"),
                "evidence_refs": [evidence_ref],
            },
        )
        containment_relation = {
            "event": "has_event",
            "task_episode": "has_task_episode",
            "goal_lifecycle": "has_goal_lifecycle",
            "segment": "has_segment",
        }.get(doc_type)
        if (
            containment_relation
            and parent_node_id != evidence_node_id
        ):
            graph_add_edge(
                edges,
                {
                    "source": parent_node_id,
                    "target": evidence_node_id,
                    "type": containment_relation,
                    "session_id": session_id,
                    "segment_id": segment_id,
                    "event_id": event_id,
                    "task_episode_id": task_episode_id,
                    "goal_id": goal_id,
                    "evidence_refs": [evidence_ref],
                },
            )
        if (
            doc_type == "event"
            and refs.get("raw")
            and GRAPH_MATERIALIZE_RAW_REF_NODES
        ):
            raw_node_id = graph_raw_ref_node_id(session_id, str(refs.get("raw")))
            graph_add_node(
                nodes,
                {
                    "id": raw_node_id,
                    "type": "raw_ref",
                    "label": refs.get("raw"),
                    "session_id": session_id,
                    "session_label": session_label,
                    "raw_ref": refs.get("raw"),
                    "evidence_refs": [evidence_ref],
                },
            )
            graph_add_edge(
                edges,
                {
                    "source": evidence_node_id,
                    "target": raw_node_id,
                    "type": "has_raw_ref",
                    "session_id": session_id,
                    "segment_id": segment_id,
                    "event_id": event_id,
                    "evidence_refs": [evidence_ref],
                },
            )
        signals = graph_route_signals_from_pipe(hit.get("route_signals"))
        # ``route_signals`` in the compact document row is a bounded preview.
        # The normalized posting that actually selected this document remains
        # authoritative navigation metadata even when that preview is
        # truncated before the matched token.  Preserve only the exact
        # matched postings reported by trace_route, not every inferred
        # candidate.
        signals.extend(
            graph_route_signals_from_values(
                hit.get("matched_routes")
            )
        )
        signals = graph_unique_records(signals, limit=80)
        if not signals and route_candidates:
            for candidate in route_candidates:
                if isinstance(candidate, dict) and candidate.get("layer") and candidate.get("key"):
                    signals.append(
                        {
                            "layer": route_key_slug(candidate.get("layer"), fallback=""),
                            "key": route_key_slug(candidate.get("key"), fallback=""),
                            "route_signal": str(candidate.get("route_signal") or ""),
                        }
                    )
        for signal in graph_unique_records(signals, limit=80):
            if not isinstance(signal, dict) or not signal.get("layer") or not signal.get("key"):
                continue
            route_node_id = graph_route_node_id(str(signal["layer"]), str(signal["key"]))
            graph_add_node(
                nodes,
                {
                    "id": route_node_id,
                    "type": graph_route_node_type(str(signal["layer"]), str(signal["key"])),
                    "label": signal.get("route_signal") or route_signal_token(str(signal["layer"]), str(signal["key"])),
                    "route_layer": signal["layer"],
                    "route_key": signal["key"],
                    "route_signal": signal.get("route_signal") or route_signal_token(str(signal["layer"]), str(signal["key"])),
                    "axis": ROUTE_SIGNAL_LAYER_TO_AXIS.get(str(signal["layer"]), ""),
                    "evidence_refs": [evidence_ref],
                },
            )
            graph_add_edge(
                edges,
                {
                    "source": evidence_node_id,
                    "target": route_node_id,
                    "type": graph_search_hit_route_relation(doc_type),
                    "session_id": session_id,
                    "segment_id": segment_id,
                    "event_id": event_id,
                    "route_signal": signal.get("route_signal") or route_signal_token(str(signal["layer"]), str(signal["key"])),
                    "evidence_refs": [evidence_ref],
                },
            )
    node_rows = sorted(nodes.values(), key=lambda item: str(item.get("id") or ""))
    edge_rows = sorted(edges.values(), key=lambda item: str(item.get("id") or ""))
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_bounded_graph",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": now,
        "ok": bool(node_rows),
        "truth_status": "bounded_graph_from_search_hits_not_reviewed_truth",
        "source": source,
        "aoa_root": str(aoa_root),
        "node_count": len(node_rows),
        "edge_count": len(edge_rows),
        "nodes": node_rows,
        "edges": edge_rows,
        "diagnostics": [],
    }


def graph_packet_cli_kind(kind: str, route_kind: str) -> str:
    requested = str(kind or "").strip()
    if requested in TRACE_ROUTE_KIND_CHOICES:
        return requested
    if route_kind in TRACE_ROUTE_KIND_CHOICES:
        return route_kind
    return "auto"


def graph_packet_expanded_limit(value: Any, *, default: int, maximum: int) -> int:
    current = int_value(value, default)
    current = max(1, current)
    return min(maximum, max(current + max(8, current // 2), current * 2))


def graph_packet_command_line(
    *,
    aoa_root: Path,
    command_name: str,
    anchors: list[str],
    kind: str,
    route_kind: str,
    session: str | None = None,
    limit: int | None = None,
    depth: int | None = None,
    edge_limit: int | None = None,
    max_depth: int | None = None,
) -> str:
    command = ["python3", "scripts/aoa_session_memory.py", command_name, *[str(anchor) for anchor in anchors], "--aoa-root", str(aoa_root)]
    command.extend(["--kind", graph_packet_cli_kind(kind, route_kind)])
    if session:
        command.extend(["--session", str(session)])
    if depth is not None:
        command.extend(["--depth", str(max(0, min(int_value(depth, 1), 3)))])
    if limit is not None:
        command.extend(["--limit", str(max(1, int_value(limit, 40)))])
    if edge_limit is not None:
        command.extend(["--edge-limit", str(max(1, int_value(edge_limit, 24)))])
    if max_depth is not None:
        command.extend(["--max-depth", str(max(1, min(int_value(max_depth, 4), 8)))])
    return " ".join(shlex.quote(part) for part in command)


def graph_neighborhood(
    *,
    aoa_root: Path,
    anchor: str,
    kind: str = "auto",
    session: str | None = None,
    depth: int = 1,
    limit: int = 40,
    edge_limit: int | None = None,
) -> dict[str, Any]:
    privacy_gate = derived_text_privacy_field_gate(anchor=anchor)
    if privacy_gate["blocked"]:
        return derived_text_privacy_blocked_navigation_result(
            artifact_type="session_memory_graph_neighborhood",
            fields=privacy_gate["fields"],
            metadata=privacy_gate["derived_text_privacy"],
            graph=True,
        )
    normalized_kind = normalize_trace_route_kind(kind)
    route_kind = normalized_kind if normalized_kind in TRACE_ROUTE_KINDS else "auto"
    store_graph = graph_from_store_neighborhood(
        aoa_root=aoa_root,
        anchor=anchor,
        kind=route_kind,
        depth=depth,
        limit=limit,
        edge_limit=edge_limit,
    )
    store_resolved = (
        store_graph.get("resolved")
        if isinstance(store_graph, dict) and isinstance(store_graph.get("resolved"), dict)
        else {}
    )
    store_resolution_strategy = str(store_resolved.get("resolver_strategy") or "")
    store_terminal_empty = store_resolution_strategy in {
        "identity_diagnostic_no_route",
        "ambiguous_raw_ref_requires_session_scope",
    }
    store_graph_selected = bool(
        store_graph is not None and (store_graph.get("ok") or store_terminal_empty)
    )
    if store_graph_selected:
        nodes = store_graph.get("nodes", []) if isinstance(store_graph.get("nodes"), list) else []
        edges = store_graph.get("edges", []) if isinstance(store_graph.get("edges"), list) else []
        evidence_ref_limit = max(12, min(int_value(store_graph.get("edge_limit"), 24) * 2, 50))
        evidence_refs = graph_collect_evidence(nodes, edges, limit=evidence_ref_limit)
        resolved = store_graph.get("resolved") if isinstance(store_graph.get("resolved"), dict) else {}
        current_command = graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-neighborhood",
            anchors=[anchor],
            kind=kind,
            route_kind=route_kind,
            session=session,
            depth=max(0, min(int_value(depth, 1), 3)),
            limit=int_value(store_graph.get("node_limit"), limit),
            edge_limit=int_value(store_graph.get("edge_limit")) if store_graph.get("edge_limit") is not None else None,
        )
        expansion_command = graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-neighborhood",
            anchors=[anchor],
            kind=kind,
            route_kind=route_kind,
            session=session,
            depth=min(max(0, min(int_value(depth, 1), 3)) + 1, 3),
            limit=graph_packet_expanded_limit(store_graph.get("node_limit"), default=limit, maximum=200),
            edge_limit=graph_packet_expanded_limit(store_graph.get("edge_limit"), default=edge_limit or 24, maximum=400),
        )
        freshness = graph_freshness(
            aoa_root,
            store_graph,
            scope_nodes=nodes,
            scope_edges=edges,
        )
        answer_admission = graph_relation_packet_admission(
            edges,
            has_nodes=bool(nodes),
            truncated=bool(store_graph.get("truncated")),
            freshness=freshness,
        )
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "session_memory_graph_neighborhood",
            "graph_schema_version": GRAPH_SCHEMA_VERSION,
            "generated_at": utc_now(),
            "ok": bool(nodes),
            "mutates": False,
            "truth_status": "graph_route_packet_not_reviewed_truth",
            "anchor": anchor,
            "session": session or "",
            **trace_kind_payload_fields(kind, route_kind),
            "depth": max(0, min(int_value(depth, 1), 3)),
            "resolved": resolved,
            "graph": {
                "source": store_graph.get("source"),
                "generated_at": store_graph.get("generated_at"),
                "node_count": store_graph.get("node_count"),
                "edge_count": store_graph.get("edge_count"),
            },
            "node_count": len(nodes),
            "edge_count": len(edges),
            "node_limit": store_graph.get("node_limit"),
            "edge_limit": store_graph.get("edge_limit"),
            "truncated": bool(store_graph.get("truncated")),
            "omitted_node_count": store_graph.get("omitted_node_count"),
            "omitted_edge_count": store_graph.get("omitted_edge_count"),
            "route_selection": {
                "first_route": "sqlite_graph_store_exact",
                "first_route_resolution": store_resolution_strategy or "exact_graph_store_seed",
                "selected_route": "sqlite_graph_store",
                "fallback_reason": "",
            },
            "edge_query_strategies": store_graph.get("edge_query_strategies") if isinstance(store_graph.get("edge_query_strategies"), dict) else {},
            "evidence_ref_limit": evidence_ref_limit,
            "nodes": [graph_compact_node_for_packet(node) for node in nodes],
            "edges": [graph_compact_edge_for_packet(edge) for edge in edges],
            "evidence_refs": evidence_refs,
            "freshness": freshness,
            "answer_admission": answer_admission,
            "diagnostics": [
                *(store_graph.get("diagnostics", []) if isinstance(store_graph.get("diagnostics"), list) else []),
                *(resolved.get("diagnostics", []) if isinstance(resolved.get("diagnostics"), list) else []),
            ],
            "next_route": "verify important claims through raw_ref, segment_ref, and session_ref before promotion",
            "next_command": current_command,
            "next_expansion_command": expansion_command,
            "next_expansion_reason": "Increase bounded graph depth/limits when the packet is truncated or more neighboring relations are needed.",
        }
    correlation_packet = graph_source_verified_correlation_timeline(
        aoa_root=aoa_root,
        anchor=anchor,
        kind=route_kind,
        session=session,
        limit=max(1, min(int_value(limit, 40), 200)),
    )
    if isinstance(correlation_packet, dict):
        correlation_nodes = (
            correlation_packet.get("nodes", [])
            if isinstance(correlation_packet.get("nodes"), list)
            else []
        )
        correlation_edges = (
            correlation_packet.get("edges", [])
            if isinstance(correlation_packet.get("edges"), list)
            else []
        )
        quality = (
            correlation_packet.get("quality")
            if isinstance(correlation_packet.get("quality"), dict)
            else {}
        )
        freshness = (
            correlation_packet.get("freshness")
            if isinstance(correlation_packet.get("freshness"), dict)
            else {}
        )
        truncated = bool(
            quality.get(
                "structured_correlation_candidate_budget_exhausted"
            )
        )
        evidence_ref_limit = max(
            12,
            min(max(1, int_value(edge_limit, 24)) * 2, 50),
        )
        evidence_refs = graph_collect_evidence(
            correlation_nodes,
            correlation_edges,
            limit=evidence_ref_limit,
        )
        answer_admission = graph_relation_packet_admission(
            correlation_edges,
            has_nodes=bool(correlation_nodes),
            truncated=truncated,
            freshness=freshness,
        )
        current_command = graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-neighborhood",
            anchors=[anchor],
            kind=kind,
            route_kind=route_kind,
            session=session,
            depth=0,
            limit=max(1, min(int_value(limit, 40), 200)),
            edge_limit=edge_limit,
        )
        timeline_command = graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-timeline",
            anchors=[anchor],
            kind=kind,
            route_kind=route_kind,
            session=session,
            limit=max(1, min(int_value(limit, 40), 200)),
        )
        store_diagnostics = (
            store_graph.get("diagnostics", [])
            if isinstance(store_graph, dict)
            and isinstance(store_graph.get("diagnostics"), list)
            else []
        )
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "session_memory_graph_neighborhood",
            "graph_schema_version": GRAPH_SCHEMA_VERSION,
            "generated_at": utc_now(),
            "ok": bool(correlation_nodes),
            "mutates": False,
            "truth_status": "graph_route_packet_not_reviewed_truth",
            "anchor": anchor,
            "session": session or "",
            **trace_kind_payload_fields(kind, route_kind),
            "depth": 0,
            "resolved": (
                correlation_packet.get("resolved")
                if isinstance(correlation_packet.get("resolved"), dict)
                else {}
            ),
            "graph": {
                "source": correlation_packet.get("source"),
                "generated_at": correlation_packet.get("generated_at"),
                "node_count": correlation_packet.get("node_count"),
                "edge_count": correlation_packet.get("edge_count"),
                "timeline_mode": "exact_structured_correlation",
            },
            "node_count": len(correlation_nodes),
            "edge_count": len(correlation_edges),
            "node_limit": max(1, min(int_value(limit, 40), 200)),
            "edge_limit": max(1, int_value(edge_limit, 24)),
            "truncated": truncated,
            "omitted_node_count": 0,
            "omitted_edge_count": 0,
            "route_selection": {
                "first_route": "sqlite_graph_store_exact",
                "first_route_resolution": (
                    store_resolution_strategy
                    or "graph_store_unavailable_or_noncurrent"
                ),
                "selected_route": (
                    "source_verified_correlation_trace"
                ),
                "fallback_reason": (
                    "exact_correlation_not_materialized_in_graph_store"
                ),
                "generic_fuzzy_graph_expansion_used": False,
            },
            "evidence_ref_limit": evidence_ref_limit,
            "nodes": [
                graph_compact_node_for_packet(node)
                for node in correlation_nodes
            ],
            "edges": [
                graph_compact_edge_for_packet(edge)
                for edge in correlation_edges
            ],
            "evidence_refs": evidence_refs,
            "freshness": freshness,
            "answer_admission": answer_admission,
            "quality": quality,
            "diagnostics": list(
                dict.fromkeys(
                    [
                        *store_diagnostics,
                        *(
                            correlation_packet.get("diagnostics", [])
                            if isinstance(
                                correlation_packet.get("diagnostics"),
                                list,
                            )
                            else []
                        ),
                    ]
                )
            ),
            "next_route": (
                "read the exact correlation source refs through the "
                "claim-shape gate; do not infer from identifier mentions"
            ),
            "next_command": current_command,
            "next_expansion_command": timeline_command,
            "next_expansion_reason": (
                "Use the exact source-verified timeline when ordered "
                "call/result evidence is needed; generic graph expansion is "
                "not an exact-correlation fallback."
            ),
        }
    trace = trace_route(
        aoa_root=aoa_root,
        anchor=anchor,
        kind=route_kind,
        session=session,
        limit=max(1, min(int_value(limit, 40), 200)),
        per_route_limit=max(5, min(int_value(limit, 40), 50)),
        # Route postings may be compacted out of event documents and retained
        # by stronger task-episode/entity-registry projections.  The exact
        # route filter remains the selector; restricting this navigation seed
        # to ``event`` would silently query a retired storage layer after a
        # deterministic rebuild.
        doc_type=None,
        explain=True,
        text_fallback_policy=(
            TRACE_TEXT_FALLBACK_SPECIFIC_ROUTE_HIT
        ),
    )
    hits = trace.get("results", []) if isinstance(trace.get("results"), list) else []
    trace_diagnostics = trace.get("diagnostics", []) if isinstance(trace.get("diagnostics"), list) else []
    trace_text_search_attempted = bool(
        trace.get("text_search_attempted")
    )
    trace_text_search_skipped = bool(
        trace.get("text_search_skipped")
    )
    duplicate_text_fallback_suppressed = bool(
        not hits
        and (
            trace_text_search_attempted
            or trace_text_search_skipped
        )
    )
    graph = graph_from_search_results(
        aoa_root=aoa_root,
        hits=hits,
        source="bounded_trace_search",
        route_candidates=trace.get("route_candidates", []) if isinstance(trace.get("route_candidates"), list) else [],
    )
    node_map = graph_node_by_id(graph)
    edge_map = graph_edge_by_id(graph)
    resolved = resolve_graph_anchor(graph, anchor, kind=route_kind, limit=max(10, limit))
    typed_route_layers = {
        "mcp": {"mcp"},
        "hook": {"hook", "hook_health"},
        "receipt": {"hook_health"},
        "failure": {"failure_mode"},
        "error": {"failure_mode"},
        "decision": {"decision_thread"},
        "external": {"external_snapshot"},
        "github": {"git", "delivery_state", "external_snapshot"},
    }.get(route_kind, {route_kind})
    typed_anchor_keys = set(graph_anchor_alias_keys(anchor))
    typed_retrieval_exact_ids = [
        str(node_id)
        for node_id in resolved.get("start_node_ids", [])
        if node_id in node_map
        and str(node_map[node_id].get("route_layer") or "")
        in typed_route_layers
        and str(node_map[node_id].get("route_key") or "")
        in typed_anchor_keys
    ]
    if (
        route_kind != "auto"
        and str(resolved.get("resolver_strategy") or "")
        == "fuzzy_alias_candidates"
        and typed_retrieval_exact_ids
    ):
        resolved["start_node_ids"] = typed_retrieval_exact_ids
        resolved["exact_start_node_ids"] = typed_retrieval_exact_ids
        resolved["candidate_node_ids"] = [
            str(node_id)
            for node_id in resolved.get("candidate_node_ids", [])
            if str(node_id) not in typed_retrieval_exact_ids
        ]
        resolved["resolver_strategy"] = (
            "typed_retrieval_seed_exact_route_key"
        )
    retrieval_candidate_only = bool(
        str(resolved.get("resolver_strategy") or "")
        == "fuzzy_alias_candidates"
        and not resolved.get("exact_start_node_ids")
    )
    if retrieval_candidate_only:
        resolved["candidate_node_ids"] = list(
            resolved.get("start_node_ids") or []
        )
        resolved["start_node_ids"] = []
        resolved["resolver_strategy"] = (
            "typed_anchor_unresolved_fuzzy_candidates"
            if route_kind != "auto"
            else "auto_anchor_unresolved_candidate_navigation"
        )
        resolved["diagnostics"] = list(
            dict.fromkeys(
                [
                    *(
                        resolved.get("diagnostics", [])
                        if isinstance(
                            resolved.get("diagnostics"),
                            list,
                        )
                        else []
                    ),
                    (
                        "typed_anchor_fuzzy_candidates_not_promoted"
                        if route_kind != "auto"
                        else "auto_anchor_partial_route_candidates_not_promoted"
                    ),
                ]
            )
        )
    depth = max(0, min(int_value(depth, 1), 3))
    limit = max(1, min(int_value(limit, 40), 200))
    selected_node_ids, selected_edge_ids, expansion_quality = graph_expand_node_ids(
        resolved["start_node_ids"],
        edges=graph.get("edges", []) if isinstance(graph.get("edges"), list) else [],
        depth=depth,
        max_nodes=limit,
        max_edges=edge_limit,
    )
    nodes = [node_map[node_id] for node_id in selected_node_ids if node_id in node_map]
    edges = [edge_map[edge_id] for edge_id in selected_edge_ids if edge_id in edge_map]
    candidate_nodes = [
        node_map[node_id]
        for node_id in (
            resolved.get("candidate_node_ids")
            if isinstance(resolved.get("candidate_node_ids"), list)
            else []
        )
        if node_id in node_map
    ][: max(1, min(limit, 20))]
    evidence_ref_limit = max(12, min(int_value(expansion_quality.get("edge_limit"), 24) * 2, 50))
    evidence_refs = graph_collect_evidence(nodes, edges, limit=evidence_ref_limit)
    store_diagnostics = (
        store_graph.get("diagnostics", [])
        if isinstance(store_graph, dict) and isinstance(store_graph.get("diagnostics"), list)
        else []
    )
    if store_resolution_strategy == "indexed_exact_miss_requires_retrieval_seed":
        store_diagnostics = [
            *store_diagnostics,
            "graph_store_exact_miss_used_bounded_retrieval_seed",
        ]
    selected_seed_route = (
        "bounded_trace_search_candidate_only"
        if retrieval_candidate_only
        else str(graph.get("source") or "bounded_trace_search")
    )
    current_command = graph_packet_command_line(
        aoa_root=aoa_root,
        command_name="graph-neighborhood",
        anchors=[anchor],
        kind=kind,
        route_kind=route_kind,
        session=session,
        depth=depth,
        limit=limit,
        edge_limit=expansion_quality.get("edge_limit"),
    )
    expansion_command = graph_packet_command_line(
        aoa_root=aoa_root,
        command_name="graph-neighborhood",
        anchors=[anchor],
        kind=kind,
        route_kind=route_kind,
        session=session,
        depth=min(depth + 1, 3),
        limit=graph_packet_expanded_limit(limit, default=limit, maximum=200),
        edge_limit=graph_packet_expanded_limit(expansion_quality.get("edge_limit"), default=edge_limit or 24, maximum=400),
    )
    freshness = {
        **graph_freshness(aoa_root, graph),
        "trace_result_count": trace.get("result_count"),
        "trace_ok": trace.get("ok"),
    }
    answer_admission = graph_relation_packet_admission(
        edges,
        has_nodes=bool(nodes),
        truncated=bool(expansion_quality.get("truncated")),
        freshness=freshness,
    )
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_neighborhood",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": bool(nodes),
        "mutates": False,
        "truth_status": "graph_route_packet_not_reviewed_truth",
        "anchor": anchor,
        "session": session or "",
        **trace_kind_payload_fields(kind, route_kind),
        "depth": depth,
        "resolved": resolved,
        "graph": {
            "source": graph.get("source"),
            "generated_at": graph.get("generated_at"),
            "node_count": graph.get("node_count"),
            "edge_count": graph.get("edge_count"),
        },
        "node_count": len(nodes),
        "edge_count": len(edges),
        "node_limit": limit,
        "edge_limit": expansion_quality.get("edge_limit"),
        "truncated": bool(expansion_quality.get("truncated")),
        "omitted_node_count": expansion_quality.get("omitted_node_count"),
        "omitted_edge_count": expansion_quality.get("omitted_edge_count"),
        "route_selection": {
            "first_route": "sqlite_graph_store_exact",
            "first_route_resolution": (
                store_resolution_strategy
                or ("graph_store_unavailable_or_noncurrent" if store_graph is None else "exact_graph_store_seed_incomplete")
            ),
            "selected_route": selected_seed_route,
            "fallback_reason": (
                (
                    "typed_exact_anchor_unresolved_candidate_navigation_only"
                    if route_kind != "auto"
                    else "auto_exact_anchor_unresolved_candidate_navigation_only"
                )
                if retrieval_candidate_only
                else
                "exact_graph_anchor_unresolved"
                if store_resolution_strategy == "indexed_exact_miss_requires_retrieval_seed"
                else "direct_graph_store_unavailable_or_incomplete"
            ),
            "text_fallback_policy": trace.get(
                "text_fallback_policy"
            ),
            "text_search_attempted": trace_text_search_attempted,
            "text_search_skipped": trace_text_search_skipped,
            "text_search_skip_reason": trace.get(
                "text_search_skip_reason"
            ),
            "text_fallback_already_attempted": (
                trace_text_search_attempted
            ),
            "duplicate_text_fallback_suppressed": (
                duplicate_text_fallback_suppressed
            ),
        },
        "evidence_ref_limit": evidence_ref_limit,
        "nodes": [graph_compact_node_for_packet(node) for node in nodes],
        "candidate_nodes": [
            graph_compact_node_for_packet(node)
            for node in candidate_nodes
        ],
        "edges": [graph_compact_edge_for_packet(edge) for edge in edges],
        "evidence_refs": evidence_refs,
        "freshness": freshness,
        "answer_admission": answer_admission,
        "diagnostics": list(
            dict.fromkeys(
                [
                    *store_diagnostics,
                    *(graph.get("diagnostics", []) if isinstance(graph.get("diagnostics"), list) else []),
                    *(trace.get("diagnostics", []) if isinstance(trace.get("diagnostics"), list) else []),
                    *(resolved.get("diagnostics", []) if isinstance(resolved.get("diagnostics"), list) else []),
                ]
            )
        ),
        "next_route": "verify important claims through raw_ref, segment_ref, and session_ref before promotion",
        "next_command": current_command,
        "next_expansion_command": expansion_command,
        "next_expansion_reason": "Increase bounded graph depth/limits when the packet is truncated or more neighboring relations are needed.",
    }


def graph_source_verified_correlation_timeline(
    *,
    aoa_root: Path,
    anchor: str,
    kind: str,
    session: str | None = None,
    limit: int,
) -> dict[str, Any] | None:
    """Resolve a structured correlation identifier through source events.

    Search hits are only candidate navigation.  A hit becomes part of the
    timeline when its archived segment event exposes the exact requested
    correlation id; quoting the identifier in unrelated text is rejected.
    """
    structured_identifier = literal_query_identifier_anchor(anchor)
    if (
        not structured_identifier
        or LITERAL_QUERY_STRUCTURED_IDENTIFIER_RE.fullmatch(
            structured_identifier
        )
        is None
    ):
        return None

    event_limit = max(1, min(int_value(limit, 40), 200))
    candidate_limit = max(20, min(200, event_limit * 8))
    exact_seed = search_sessions(
        aoa_root=aoa_root,
        query=structured_identifier,
        limit=candidate_limit,
        provider="portable_sqlite",
        session=session,
        doc_type="event",
        explain=True,
        semantic_preview=False,
        hydrate_body=False,
        raw_ref_preview=False,
        literal_postings_only=True,
        include_archived_raw_fallback=False,
    )
    exact_hits = (
        exact_seed.get("results", [])
        if isinstance(exact_seed.get("results"), list)
        else []
    )
    trace = (
        {
            "ok": exact_seed.get("ok"),
            "result_count": len(exact_hits),
            "results": exact_hits,
            "diagnostics": exact_seed.get("diagnostics", []),
            "selected_seed_route": "exact_literal_postings",
        }
        if exact_hits
        else trace_route(
            aoa_root=aoa_root,
            anchor=structured_identifier,
            kind=kind,
            session=session,
            limit=candidate_limit,
            per_route_limit=max(20, min(candidate_limit, 50)),
            doc_type="event",
            explain=True,
        )
    )
    hits = (
        trace.get("results", [])
        if isinstance(trace.get("results"), list)
        else []
    )
    segment_cache: dict[str, list[dict[str, Any]]] = {}
    manifest_cache: dict[str, dict[str, Any]] = {}
    raw_preview_cache: dict[tuple[str, str, str, int], dict[str, Any]] = {}
    accepted: dict[str, tuple[dict[str, Any], dict[str, Any], dict[str, Any]]] = {}
    source_event_verified_count = 0
    mention_only_rejected_count = 0
    unverifiable_count = 0
    duplicate_candidate_count = 0
    segment_peer_scan_count = 0
    segment_peer_candidate_count = 0
    segment_peer_admitted_count = 0
    segment_peer_unverifiable_count = 0
    segment_peer_raw_mismatch_count = 0

    for hit in hits:
        if not isinstance(hit, dict):
            continue
        source_event = segment_event_for_hit(
            hit,
            segment_cache=segment_cache,
        )
        if not source_event:
            unverifiable_count += 1
            continue
        source_event_verified_count += 1
        if str(source_event.get("correlation_id") or "") != structured_identifier:
            mention_only_rejected_count += 1
            continue

        compact_event = compact_usage_event_from_segment_event(
            source_event,
            hit=hit,
            role="context",
            source="source_verified_correlation_trace",
            source_doc_id=str(hit.get("doc_id") or ""),
            distance=0,
            relation="correlation_id_exact",
        )
        compact_event["timestamp"] = (
            source_event.get("timestamp")
            or hit.get("timestamp")
            or hit.get("session_date")
        )
        node = graph_event_node_from_usage_event(compact_event)
        node["object"] = source_event.get("object")
        node["correlation_id"] = structured_identifier
        node["matched_routes"] = (
            hit.get("matched_routes")
            if isinstance(hit.get("matched_routes"), list)
            else []
        )
        evidence_refs = (
            node.get("evidence_refs")
            if isinstance(node.get("evidence_refs"), list)
            else []
        )
        for evidence_ref in evidence_refs:
            if isinstance(evidence_ref, dict):
                evidence_ref["correlation_id"] = structured_identifier
                evidence_ref["admission"] = (
                    "source_event_correlation_id_exact"
                )
        node_id = str(node.get("id") or "")
        if node_id in accepted:
            duplicate_candidate_count += 1
            continue
        accepted[node_id] = (hit, source_event, node)

    # A stale search projection can expose only one side of an otherwise
    # current call/result pair.  Once one candidate has passed exact source
    # admission, recover same-segment peers from the current segment index and
    # verify their structured correlation against the archived raw payload.
    # This keeps search as navigation while preventing a one-sided stale seed
    # from masquerading as a complete causal timeline.
    scanned_segment_indexes: set[str] = set()
    for hit, _source_event, _node in list(accepted.values()):
        refs = event_refs_from_hit(hit)
        segment_index_ref = str(refs.get("segment_index") or "")
        if (
            not segment_index_ref
            or segment_index_ref in scanned_segment_indexes
        ):
            continue
        scanned_segment_indexes.add(segment_index_ref)
        segment_peer_scan_count += 1
        for peer_event in segment_events_for_hit(
            hit,
            segment_cache=segment_cache,
        ):
            if (
                str(peer_event.get("correlation_id") or "")
                != structured_identifier
            ):
                continue
            peer_node_id = (
                f"event:{hit.get('session_id')}:{hit.get('segment_id')}:"
                f"{peer_event.get('event_id')}"
            )
            if peer_node_id in accepted:
                continue
            segment_peer_candidate_count += 1
            peer_payload, peer_payload_status = (
                raw_payload_for_usage_segment_event(
                    peer_event,
                    hit=hit,
                    distance=0,
                    manifest_cache=manifest_cache,
                    raw_preview_cache=raw_preview_cache,
                )
            )
            if not peer_payload:
                segment_peer_unverifiable_count += 1
                continue
            if (
                str(payload_correlation_id(peer_payload) or "")
                != structured_identifier
            ):
                segment_peer_raw_mismatch_count += 1
                continue

            compact_event = compact_usage_event_from_segment_event(
                peer_event,
                hit=hit,
                role="context",
                source="source_verified_correlation_segment_peer",
                source_doc_id=str(hit.get("doc_id") or ""),
                distance=0,
                relation="correlation_id_exact_segment_peer",
            )
            compact_event["timestamp"] = (
                peer_event.get("timestamp")
                or hit.get("timestamp")
                or hit.get("session_date")
            )
            peer_node = graph_event_node_from_usage_event(compact_event)
            peer_node["object"] = peer_event.get("object")
            peer_node["correlation_id"] = structured_identifier
            peer_node["matched_routes"] = (
                hit.get("matched_routes")
                if isinstance(hit.get("matched_routes"), list)
                else []
            )
            peer_evidence_refs = (
                peer_node.get("evidence_refs")
                if isinstance(peer_node.get("evidence_refs"), list)
                else []
            )
            for evidence_ref in peer_evidence_refs:
                if isinstance(evidence_ref, dict):
                    evidence_ref["correlation_id"] = structured_identifier
                    evidence_ref["admission"] = (
                        "source_raw_correlation_id_exact_segment_peer"
                    )
            resolved_peer_node_id = str(peer_node.get("id") or "")
            if resolved_peer_node_id in accepted:
                duplicate_candidate_count += 1
                continue
            accepted[resolved_peer_node_id] = (
                hit,
                peer_event,
                peer_node,
            )
            segment_peer_admitted_count += 1

    source_tool_names: dict[tuple[str, str], str] = {}
    for hit, source_event, node in accepted.values():
        payload, _payload_status = raw_payload_for_usage_segment_event(
            source_event,
            hit=hit,
            distance=0,
            manifest_cache=manifest_cache,
            raw_preview_cache=raw_preview_cache,
        )
        if str(payload.get("type") or "") not in EPISODE_TEMPORAL_RAW_CALL_TYPES:
            continue
        source_tool_name = tool_name_from_payload(payload)
        if not source_tool_name:
            continue
        source_tool_names[
            (
                str(node.get("session_id") or ""),
                structured_identifier,
            )
        ] = source_tool_name

    structured_result_status_admitted_count = 0
    structured_result_timeout_count = 0
    for hit, source_event, node in accepted.values():
        if not entity_usage_segment_event_is_tool_result(source_event):
            continue
        source_tool_name = source_tool_names.get(
            (
                str(node.get("session_id") or ""),
                structured_identifier,
            ),
            "",
        )
        if not source_tool_name:
            continue
        result_payload, _payload_status = raw_payload_for_usage_segment_event(
            source_event,
            hit=hit,
            distance=0,
            manifest_cache=manifest_cache,
            raw_preview_cache=raw_preview_cache,
        )
        result_status = source_verified_structured_tool_result_status(
            result_payload,
            source_tool_name=source_tool_name,
        )
        if not result_status:
            continue
        node.update(result_status)
        node["outcome"] = result_status["result_outcome"]
        structured_result_status_admitted_count += 1
        if result_status.get("result_status") == "timed_out":
            structured_result_timeout_count += 1

    nodes = [row[2] for row in accepted.values()]
    nodes.sort(
        key=lambda node: (
            str(node.get("timestamp") or ""),
            str(node.get("session_label") or ""),
            int_value(node.get("line")),
            str(node.get("event_id") or ""),
        )
    )
    nodes_by_session_event: dict[tuple[str, str], list[dict[str, Any]]] = {}
    source_by_node_id: dict[str, dict[str, Any]] = {}
    for _hit, source_event, node in accepted.values():
        key = (
            str(node.get("session_id") or ""),
            str(node.get("event_id") or ""),
        )
        nodes_by_session_event.setdefault(key, []).append(node)
        source_by_node_id[str(node.get("id") or "")] = source_event

    edges: dict[str, dict[str, Any]] = {}
    admitted_relation_types = {
        "answered_by",
        "responds_to",
        "has_correlated_status",
    }
    for node in nodes:
        source_event = source_by_node_id.get(str(node.get("id") or ""), {})
        relationships = (
            source_event.get("relationships")
            if isinstance(source_event.get("relationships"), list)
            else []
        )
        for relationship in relationships:
            if not isinstance(relationship, dict):
                continue
            relation = str(relationship.get("rel") or "")
            if (
                relation not in admitted_relation_types
                or str(relationship.get("correlation_id") or "")
                != structured_identifier
            ):
                continue
            target_candidates = nodes_by_session_event.get(
                (
                    str(node.get("session_id") or ""),
                    str(relationship.get("event_id") or ""),
                ),
                [],
            )
            if len(target_candidates) != 1:
                continue
            target = target_candidates[0]
            source_refs = (
                node.get("evidence_refs")
                if isinstance(node.get("evidence_refs"), list)
                else []
            )
            target_refs = (
                target.get("evidence_refs")
                if isinstance(target.get("evidence_refs"), list)
                else []
            )
            graph_add_edge(
                edges,
                {
                    "source": node.get("id"),
                    "target": target.get("id"),
                    "type": relation,
                    "correlation_id": structured_identifier,
                    "source_correlation_id": node.get("correlation_id"),
                    "target_correlation_id": target.get("correlation_id"),
                    "source_event_timestamp": node.get("timestamp"),
                    "target_event_timestamp": target.get("timestamp"),
                    "session_id": node.get("session_id"),
                    "segment_id": node.get("segment_id"),
                    "evidence_refs": graph_unique_records(
                        [*source_refs, *target_refs],
                        limit=4,
                    ),
                },
            )

    accepted_statuses = [
        str(
            (
                row[0].get("freshness")
                if isinstance(row[0].get("freshness"), dict)
                else {}
            ).get("status")
            or "unknown"
        )
        for row in accepted.values()
    ]
    candidate_budget_exhausted = len(hits) >= candidate_limit
    correlation_freshness = graph_freshness(
        aoa_root,
        {
            "source": "bounded_source_verified_correlation_trace",
            "generated_at": utc_now(),
            "nodes": nodes,
            "edges": list(edges.values()),
            "truncated": candidate_budget_exhausted,
        },
    )
    stale_source_observation = any(
        "stale" in status
        or status in {"unverifiable", "missing", "sqlite_error"}
        for status in accepted_statuses
    )
    current_source_observation = bool(
        nodes
        and accepted_statuses
        and all(
            status
            in {
                "fresh",
                "current",
                "scope_current",
                "graph_store_current",
            }
            for status in accepted_statuses
        )
    )
    if current_source_observation:
        correlation_freshness["status"] = "scope_current"
        correlation_freshness["scope_status"] = (
            "scope_current"
        )
        correlation_freshness["scope_basis"] = (
            "exact_correlation_source_events_live_checked"
        )
        scope_freshness = (
            correlation_freshness.get("scope_freshness")
            if isinstance(
                correlation_freshness.get(
                    "scope_freshness"
                ),
                dict,
            )
            else {}
        )
        correlation_freshness["scope_freshness"] = {
            **scope_freshness,
            "status": "scope_current",
            "coverage_truncated": (
                candidate_budget_exhausted
            ),
            "does_not_upgrade_global_freshness": True,
        }
        correlation_freshness["scope_truth_status"] = (
            "returned exact-correlation source contributions "
            "were live-checked; global graph recall remains "
            "independently unverified"
        )
    elif nodes and stale_source_observation:
        correlation_freshness["status"] = "stale_readable"
        correlation_freshness["scope_status"] = "scope_stale_readable"
        scope_freshness = (
            correlation_freshness.get("scope_freshness")
            if isinstance(
                correlation_freshness.get("scope_freshness"),
                dict,
            )
            else {}
        )
        correlation_freshness["scope_freshness"] = {
            **scope_freshness,
            "status": "scope_stale_readable",
            "does_not_upgrade_global_freshness": True,
        }
    correlation_freshness.update(
        {
            "timeline_source": "source_verified_correlation_trace",
            "accepted_search_freshness_statuses": sorted(
                set(accepted_statuses)
            ),
            "trace_result_count": trace.get("result_count"),
            "trace_ok": trace.get("ok"),
            "selected_seed_route": trace.get(
                "selected_seed_route",
                "bounded_trace_route_fallback",
            ),
            "needs_maintenance": bool(
                stale_source_observation or not nodes
            ),
            "law": (
                "search hits are candidates; exact source-event correlation "
                "identity admits timeline events, while bounded source "
                "admission never upgrades global graph freshness"
            ),
        }
    )
    diagnostics = [
        *(
            trace.get("diagnostics", [])
            if isinstance(trace.get("diagnostics"), list)
            else []
        ),
        "structured_correlation_source_admission_applied",
    ]
    if mention_only_rejected_count:
        diagnostics.append(
            "structured_correlation_text_mentions_rejected:"
            f"{mention_only_rejected_count}"
        )
    if unverifiable_count:
        diagnostics.append(
            "structured_correlation_candidates_unverifiable:"
            f"{unverifiable_count}"
        )
    if segment_peer_admitted_count:
        diagnostics.append(
            "structured_correlation_segment_peer_expansion_applied:"
            f"{segment_peer_admitted_count}"
        )
    if segment_peer_unverifiable_count:
        diagnostics.append(
            "structured_correlation_segment_peers_unverifiable:"
            f"{segment_peer_unverifiable_count}"
        )
    if segment_peer_raw_mismatch_count:
        diagnostics.append(
            "structured_correlation_segment_peer_raw_mismatch:"
            f"{segment_peer_raw_mismatch_count}"
        )
    if candidate_budget_exhausted:
        diagnostics.append("structured_correlation_candidate_budget_exhausted")
    if not nodes:
        diagnostics.append("structured_correlation_exact_source_miss")

    node_ids = [str(node.get("id") or "") for node in nodes if node.get("id")]
    quality = {
        "timeline_mode": "exact_structured_correlation",
        "structured_correlation_identifier": structured_identifier,
        "structured_correlation_admission_scope": (
            "source_event_correlation_id_exact"
        ),
        "structured_correlation_candidate_limit": candidate_limit,
        "structured_correlation_candidate_count": len(hits),
        "structured_correlation_source_event_count": (
            source_event_verified_count
        ),
        "structured_correlation_accepted_event_count": len(nodes),
        "structured_correlation_mention_only_rejected_count": (
            mention_only_rejected_count
        ),
        "structured_correlation_unverifiable_count": unverifiable_count,
        "structured_correlation_duplicate_candidate_count": (
            duplicate_candidate_count
        ),
        "structured_correlation_segment_peer_scan_count": (
            segment_peer_scan_count
        ),
        "structured_correlation_segment_peer_candidate_count": (
            segment_peer_candidate_count
        ),
        "structured_correlation_segment_peer_admitted_count": (
            segment_peer_admitted_count
        ),
        "structured_correlation_segment_peer_unverifiable_count": (
            segment_peer_unverifiable_count
        ),
        "structured_correlation_segment_peer_raw_mismatch_count": (
            segment_peer_raw_mismatch_count
        ),
        "structured_correlation_candidate_budget_exhausted": (
            candidate_budget_exhausted
        ),
        "correlation_relation_count": len(edges),
        "structured_result_status_admitted_count": (
            structured_result_status_admitted_count
        ),
        "structured_result_timeout_count": structured_result_timeout_count,
    }
    return {
        "ok": bool(nodes),
        "source": "source_verified_correlation_trace",
        "generated_at": utc_now(),
        "node_count": len(nodes),
        "edge_count": len(edges),
        "nodes": nodes,
        "edges": list(edges.values()),
        "resolved": {
            "anchor": anchor,
            "session": session or "",
            "kind": kind,
            "structured_identifier": structured_identifier,
            "start_node_ids": node_ids,
            "exact_start_node_ids": node_ids,
            "candidate_node_ids": [],
            "resolver_strategy": (
                "source_event_correlation_id_exact"
                if node_ids
                else "source_event_correlation_id_exact_miss"
            ),
            "diagnostics": [],
        },
        "freshness": correlation_freshness,
        "quality": quality,
        "diagnostics": list(dict.fromkeys(diagnostics)),
    }


GRAPH_TIMELINE_OPERATIONAL_NOISE_EVENT_TYPES = {
    "ASSISTANT_REASONING_BOUNDARY",
    "CONTEXT_STATE",
}
GRAPH_TIMELINE_MIRROR_LOOKAHEAD = 3


def graph_timeline_event_ref_values(event: dict[str, Any]) -> dict[str, str]:
    refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
    if refs:
        return {str(key): str(value) for key, value in refs.items() if value}
    for ref in (
        event.get("evidence_refs", [])
        if isinstance(event.get("evidence_refs"), list)
        else []
    ):
        values = graph_ref_values(ref)
        if values:
            return values
    return {}


def graph_timeline_segment_agent_event(
    *,
    aoa_root: Path,
    event: dict[str, Any],
    cache: dict[str, dict[str, dict[str, Any]]],
) -> dict[str, Any]:
    refs = graph_timeline_event_ref_values(event)
    segment_index_path = graph_segment_index_path_from_ref(
        aoa_root,
        refs,
        session_id=str(event.get("session_id") or ""),
        segment_id=str(event.get("segment_id") or ""),
    )
    if segment_index_path is None:
        return {}
    cache_key = str(segment_index_path)
    if cache_key not in cache:
        segment_index = read_json(segment_index_path, {})
        by_raw_ref: dict[str, dict[str, Any]] = {}
        for indexed_event in (
            segment_index.get("events", [])
            if isinstance(segment_index, dict)
            and isinstance(segment_index.get("events"), list)
            else []
        ):
            if not isinstance(indexed_event, dict):
                continue
            raw_ref = str(indexed_event.get("raw_ref") or "")
            facets = (
                indexed_event.get("facets")
                if isinstance(indexed_event.get("facets"), dict)
                else {}
            )
            agent_event = (
                facets.get("agent_event")
                if isinstance(facets.get("agent_event"), dict)
                else {}
            )
            if raw_ref and agent_event:
                by_raw_ref[raw_ref] = agent_event
        cache[cache_key] = by_raw_ref
    return cache[cache_key].get(str(refs.get("raw") or ""), {})


def graph_timeline_events_are_proven_assistant_mirrors(
    *,
    stream_event: dict[str, Any],
    stream_agent_event: dict[str, Any],
    canonical_event: dict[str, Any],
    canonical_agent_event: dict[str, Any],
) -> bool:
    if (
        str(stream_event.get("event_type") or "").upper() != "ASSISTANT_MESSAGE"
        or str(canonical_event.get("event_type") or "").upper()
        != "ASSISTANT_MESSAGE"
        or str(stream_event.get("session_id") or "")
        != str(canonical_event.get("session_id") or "")
        or str(stream_event.get("segment_id") or "")
        != str(canonical_event.get("segment_id") or "")
        or str(stream_agent_event.get("source_lane") or "")
        != "event_msg_stream"
        or bool(stream_agent_event.get("canonical"))
        or str(canonical_agent_event.get("source_lane") or "")
        != "response_item"
        or not bool(canonical_agent_event.get("canonical"))
    ):
        return False
    stream_digest = str(stream_agent_event.get("content_sha256") or "")
    canonical_digest = str(canonical_agent_event.get("content_sha256") or "")
    if not stream_digest or stream_digest != canonical_digest:
        return False
    stream_line = int_value(stream_event.get("line"), -1)
    canonical_line = int_value(canonical_event.get("line"), -1)
    if (
        stream_line < 0
        or canonical_line < 0
        or not 0 < canonical_line - stream_line <= 2
    ):
        return False
    stream_timestamp = parse_utc_timestamp(
        str(stream_event.get("timestamp") or "")
    )
    canonical_timestamp = parse_utc_timestamp(
        str(canonical_event.get("timestamp") or "")
    )
    return bool(
        stream_timestamp is not None
        and canonical_timestamp is not None
        and 0
        <= (canonical_timestamp - stream_timestamp).total_seconds()
        <= SEARCH_EXACT_LITERAL_MIRROR_MAX_TIMESTAMP_DELTA_SECONDS
    )


def graph_timeline_operational_event_projection(
    *,
    aoa_root: Path,
    events: list[dict[str, Any]],
    anchor_event_id: str = "",
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Keep an exact event window operational while retaining proven mirror refs."""
    ordered = [dict(event) for event in events if isinstance(event, dict)]
    agent_event_cache: dict[str, dict[str, dict[str, Any]]] = {}
    agent_event_by_index = {
        index: graph_timeline_segment_agent_event(
            aoa_root=aoa_root,
            event=event,
            cache=agent_event_cache,
        )
        for index, event in enumerate(ordered)
        if str(event.get("event_type") or "").upper() == "ASSISTANT_MESSAGE"
    }
    suppressed_mirror_indexes: set[int] = set()
    mirror_by_canonical_index: dict[int, int] = {}
    for index, event in enumerate(ordered):
        agent_event = agent_event_by_index.get(index, {})
        if str(agent_event.get("source_lane") or "") != "event_msg_stream":
            continue
        stop = min(
            len(ordered),
            index + 1 + GRAPH_TIMELINE_MIRROR_LOOKAHEAD,
        )
        for candidate_index in range(index + 1, stop):
            candidate = ordered[candidate_index]
            candidate_agent_event = agent_event_by_index.get(
                candidate_index,
                {},
            )
            if not graph_timeline_events_are_proven_assistant_mirrors(
                stream_event=event,
                stream_agent_event=agent_event,
                canonical_event=candidate,
                canonical_agent_event=candidate_agent_event,
            ):
                continue
            suppressed_mirror_indexes.add(index)
            mirror_by_canonical_index[candidate_index] = index
            break

    selected: list[dict[str, Any]] = []
    suppressed_noise_counts: Counter[str] = Counter()
    for index, event in enumerate(ordered):
        event_id = str(event.get("event_id") or "")
        event_type = str(event.get("event_type") or "").upper()
        if index in suppressed_mirror_indexes and event_id != anchor_event_id:
            continue
        if (
            event_type in GRAPH_TIMELINE_OPERATIONAL_NOISE_EVENT_TYPES
            and event_id != anchor_event_id
        ):
            suppressed_noise_counts[event_type] += 1
            continue
        mirror_index = mirror_by_canonical_index.get(index)
        if mirror_index is not None:
            mirror = ordered[mirror_index]
            event["evidence_refs"] = graph_merge_evidence_refs(
                event.get("evidence_refs"),
                mirror.get("evidence_refs"),
                limit=6,
            )
            event["mirror_evidence"] = {
                "status": "proven_adjacent_runtime_mirror_collapsed",
                "basis": (
                    "segment_index_agent_event_content_sha256_"
                    "source_lane_and_timestamp"
                ),
                "canonical_event_id": event_id,
                "mirrored_event_id": str(mirror.get("event_id") or ""),
                "raw_refs": list(
                    dict.fromkeys(
                        str(
                            graph_timeline_event_ref_values(item).get("raw")
                            or ""
                        )
                        for item in (event, mirror)
                        if graph_timeline_event_ref_values(item).get("raw")
                    )
                ),
            }
        selected.append(event)
    return selected, {
        "projection": "operational_exact_event_window_v1",
        "input_event_count": len(ordered),
        "selected_event_count": len(selected),
        "suppressed_event_count": len(ordered) - len(selected),
        "proven_assistant_mirror_collapsed_count": len(
            suppressed_mirror_indexes
        ),
        "suppressed_noise_event_counts": dict(
            sorted(suppressed_noise_counts.items())
        ),
        "anchor_event_preserved": bool(
            not anchor_event_id
            or any(
                str(event.get("event_id") or "") == anchor_event_id
                for event in selected
            )
        ),
        "authority_boundary": (
            "projection suppresses navigation noise only; event window and "
            "merged raw refs preserve the route back to source evidence"
        ),
    }


def graph_timeline(
    *,
    aoa_root: Path,
    anchor: str,
    kind: str = "auto",
    session: str | None = None,
    limit: int = 40,
) -> dict[str, Any]:
    privacy_gate = derived_text_privacy_field_gate(anchor=anchor)
    if privacy_gate["blocked"]:
        return derived_text_privacy_blocked_navigation_result(
            artifact_type="session_memory_graph_timeline",
            fields=privacy_gate["fields"],
            metadata=privacy_gate["derived_text_privacy"],
            graph=True,
        )
    normalized_kind = normalize_trace_route_kind(kind)
    route_kind = normalized_kind if normalized_kind in TRACE_ROUTE_KINDS else "auto"
    event_limit = max(1, min(int_value(limit, 40), 200))
    neighborhood_limit = max(event_limit * 4, min(60, event_limit + 12))
    direct_packet = graph_from_store_timeline_events(aoa_root=aoa_root, anchor=anchor, kind=route_kind, limit=event_limit)
    direct_resolved = (
        direct_packet.get("resolved")
        if isinstance(direct_packet, dict) and isinstance(direct_packet.get("resolved"), dict)
        else {}
    )
    direct_terminal_empty = direct_resolved.get("resolver_strategy") in {
        "identity_diagnostic_no_route",
        "ambiguous_raw_ref_requires_session_scope",
    }
    direct_packet_selected = direct_packet is not None and (
        direct_packet.get("ok")
        or direct_resolved.get("start_node_ids")
        or direct_terminal_empty
    )
    correlation_packet = (
        graph_source_verified_correlation_timeline(
            aoa_root=aoa_root,
            anchor=anchor,
            kind=route_kind,
            session=session,
            limit=event_limit,
        )
        if not direct_packet_selected
        else None
    )
    correlation_packet_selected = isinstance(correlation_packet, dict)
    if direct_packet_selected:
        direct_nodes = direct_packet.get("nodes", []) if isinstance(direct_packet.get("nodes"), list) else []
        direct_edges = direct_packet.get("edges", []) if isinstance(direct_packet.get("edges"), list) else []
        packet = {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "session_memory_graph_neighborhood",
            "graph_schema_version": GRAPH_SCHEMA_VERSION,
            "generated_at": utc_now(),
            "ok": bool(direct_nodes),
            "mutates": False,
            "truth_status": "graph_route_packet_not_reviewed_truth",
            "anchor": anchor,
            **trace_kind_payload_fields(kind, route_kind),
            "depth": 1,
            "resolved": direct_packet.get("resolved") if isinstance(direct_packet.get("resolved"), dict) else {},
            "graph": {
                "source": direct_packet.get("source"),
                "generated_at": direct_packet.get("generated_at"),
                "node_count": direct_packet.get("node_count"),
                "edge_count": direct_packet.get("edge_count"),
                "timeline_mode": direct_packet.get("timeline_mode"),
                "event_window": direct_packet.get("event_window"),
            },
            "node_count": len(direct_nodes),
            "edge_count": len(direct_edges),
            "nodes": [graph_compact_node_for_packet(node) for node in direct_nodes],
            "edges": [graph_compact_edge_for_packet(edge) for edge in direct_edges],
            "evidence_refs": graph_collect_evidence(direct_nodes, direct_edges),
            "freshness": graph_freshness(
                aoa_root,
                direct_packet,
                scope_nodes=direct_nodes,
                scope_edges=direct_edges,
            ),
            "diagnostics": list(
                dict.fromkeys(
                    [
                        *(direct_packet.get("diagnostics", []) if isinstance(direct_packet.get("diagnostics"), list) else []),
                        *(direct_resolved.get("diagnostics", []) if isinstance(direct_resolved.get("diagnostics"), list) else []),
                    ]
                )
            ),
            "next_route": "verify important claims through raw_ref, segment_ref, and session_ref before promotion",
        }
    elif correlation_packet_selected:
        correlation_nodes = (
            correlation_packet.get("nodes", [])
            if isinstance(correlation_packet.get("nodes"), list)
            else []
        )
        correlation_edges = (
            correlation_packet.get("edges", [])
            if isinstance(correlation_packet.get("edges"), list)
            else []
        )
        packet = {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "session_memory_graph_neighborhood",
            "graph_schema_version": GRAPH_SCHEMA_VERSION,
            "generated_at": utc_now(),
            "ok": bool(correlation_nodes),
            "mutates": False,
            "truth_status": "graph_route_packet_not_reviewed_truth",
            "anchor": anchor,
            **trace_kind_payload_fields(kind, route_kind),
            "depth": 0,
            "resolved": (
                correlation_packet.get("resolved")
                if isinstance(correlation_packet.get("resolved"), dict)
                else {}
            ),
            "graph": {
                "source": correlation_packet.get("source"),
                "generated_at": correlation_packet.get("generated_at"),
                "node_count": correlation_packet.get("node_count"),
                "edge_count": correlation_packet.get("edge_count"),
                "timeline_mode": "exact_structured_correlation",
            },
            "node_count": len(correlation_nodes),
            "edge_count": len(correlation_edges),
            "nodes": [
                graph_compact_node_for_packet(node)
                for node in correlation_nodes
            ],
            "edges": [
                graph_compact_edge_for_packet(edge)
                for edge in correlation_edges
            ],
            "evidence_refs": graph_collect_evidence(
                correlation_nodes,
                correlation_edges,
            ),
            "freshness": correlation_packet.get("freshness"),
            "quality": (
                correlation_packet.get("quality")
                if isinstance(correlation_packet.get("quality"), dict)
                else {}
            ),
            "diagnostics": (
                correlation_packet.get("diagnostics", [])
                if isinstance(correlation_packet.get("diagnostics"), list)
                else []
            ),
            "next_route": "verify important claims through raw_ref, segment_ref, and session_ref before promotion",
        }
    else:
        packet = graph_neighborhood(
            aoa_root=aoa_root,
            anchor=anchor,
            kind=route_kind,
            session=session,
            depth=2,
            limit=neighborhood_limit,
        )
    events = [node for node in packet.get("nodes", []) if isinstance(node, dict) and node.get("type") == "event"]
    resolved = packet.get("resolved") if isinstance(packet.get("resolved"), dict) else {}
    if resolved.get("resolver_strategy") == "exact_route_node":
        start_node_ids = {str(node_id) for node_id in resolved.get("start_node_ids", []) if node_id}
        direct_event_ids: set[str] = set()
        for edge in packet.get("edges", []) if isinstance(packet.get("edges"), list) else []:
            if not isinstance(edge, dict):
                continue
            source = str(edge.get("source") or "")
            target = str(edge.get("target") or "")
            if source in start_node_ids and target.startswith("event:"):
                direct_event_ids.add(target)
            if target in start_node_ids and source.startswith("event:"):
                direct_event_ids.add(source)
        if direct_event_ids:
            events = [event for event in events if str(event.get("id") or "") in direct_event_ids]
    events.sort(key=lambda node: (str(node.get("timestamp") or ""), str(node.get("session_label") or ""), int_value(node.get("line")), str(node.get("event_id") or "")))
    packet_graph = packet.get("graph") if isinstance(packet.get("graph"), dict) else {}
    operational_projection: dict[str, Any] = {}
    if packet_graph.get("timeline_mode") == "exact_event_centered_segment_window":
        event_window = (
            packet_graph.get("event_window")
            if isinstance(packet_graph.get("event_window"), dict)
            else {}
        )
        events, operational_projection = (
            graph_timeline_operational_event_projection(
                aoa_root=aoa_root,
                events=events,
                anchor_event_id=str(event_window.get("anchor_event_id") or ""),
            )
        )
    selected = events[:event_limit]
    selected_event_ids = {str(event.get("id") or "") for event in selected if event.get("id")}
    selected_relations = [
        edge
        for edge in packet.get("edges", []) if isinstance(packet.get("edges"), list) and isinstance(edge, dict)
        if str(edge.get("source") or "") in selected_event_ids
        and str(edge.get("target") or "") in selected_event_ids
    ]
    evidence_refs = graph_collect_evidence(selected, selected_relations, limit=80)
    packet_graph_source = str(packet_graph.get("source") or "")
    timeline_source = (
        packet_graph_source
        if packet_graph_source
        in {
            "sqlite_graph_store_direct_timeline",
            "source_verified_correlation_trace",
        }
        else "graph_neighborhood"
    )
    provider_summary: dict[str, Any] = {}
    packet_quality = (
        packet.get("quality")
        if isinstance(packet.get("quality"), dict)
        else {}
    )
    quality: dict[str, Any] = {
        **packet_quality,
        **(
            {
                "timeline_mode": packet_graph.get("timeline_mode"),
                "event_window": packet_graph.get("event_window"),
                "correlation_relation_count": sum(
                    1
                    for edge in selected_relations
                    if str(edge.get("correlation_id") or "")
                ),
                **(
                    {"operational_projection": operational_projection}
                    if operational_projection
                    else {}
                ),
            }
            if packet_graph.get("timeline_mode")
            else {}
        ),
    }
    freshness = packet.get("freshness")
    diagnostics = packet.get("diagnostics", []) if isinstance(packet.get("diagnostics"), list) else []
    direct_resolution_strategy = str(direct_resolved.get("resolver_strategy") or "")
    if not direct_packet_selected and direct_packet is not None:
        direct_diagnostics = [
            *(direct_packet.get("diagnostics", []) if isinstance(direct_packet.get("diagnostics"), list) else []),
            *(direct_resolved.get("diagnostics", []) if isinstance(direct_resolved.get("diagnostics"), list) else []),
        ]
        if direct_resolution_strategy == "indexed_exact_miss_requires_retrieval_seed":
            direct_diagnostics.append("graph_store_exact_miss_used_bounded_retrieval_seed")
        diagnostics = list(dict.fromkeys([*direct_diagnostics, *diagnostics]))
    selected_route = (
        "sqlite_graph_store_direct_timeline"
        if direct_packet_selected
        else packet_graph_source or "graph_neighborhood"
    )
    route_selection = {
        "first_route": "sqlite_graph_store_exact",
        "first_route_resolution": (
            direct_resolution_strategy
            or ("graph_store_unavailable_or_noncurrent" if direct_packet is None else "direct_graph_timeline_incomplete")
        ),
        "selected_route": selected_route,
        "fallback_reason": (
            ""
            if direct_packet_selected
            else (
                "exact_graph_anchor_unresolved"
                if direct_resolution_strategy == "indexed_exact_miss_requires_retrieval_seed"
                else "direct_graph_timeline_unavailable_or_incomplete"
            )
        ),
    }
    if not selected and resolved.get("start_node_ids"):
        audit_limit = event_limit
        usage_audit = entity_usage_audit(
            aoa_root=aoa_root,
            anchor=anchor,
            kind=route_kind,
            session=session,
            limit=audit_limit,
            per_route_limit=max(audit_limit, min(audit_limit * 2, 100)),
            consequence_window=2,
            document_limit=40,
        )
        fallback_nodes: list[dict[str, Any]] = []
        seen_node_ids: set[str] = set()
        for bucket in (
            "usage_events",
            "result_events",
            "outcome_events",
            "entrypoint_events",
            "context_events",
            "consequence_events",
        ):
            for event in usage_audit.get(bucket, []) if isinstance(usage_audit.get(bucket), list) else []:
                if not isinstance(event, dict):
                    continue
                node = graph_event_node_from_usage_event(event)
                node_id = str(node.get("id") or "")
                if not node_id or node_id in seen_node_ids:
                    continue
                seen_node_ids.add(node_id)
                fallback_nodes.append(node)
        fallback_nodes.sort(key=lambda node: (str(node.get("timestamp") or ""), str(node.get("session_label") or ""), int_value(node.get("line")), str(node.get("event_id") or "")))
        selected = fallback_nodes[:audit_limit]
        evidence_refs = graph_collect_evidence(selected, [], limit=80)
        if selected:
            timeline_source = "entity_usage_audit_fallback"
            provider = usage_audit.get("provider") if isinstance(usage_audit.get("provider"), dict) else {}
            provider_summary = compact_search_provider_status_for_route(provider, provider_name="portable_sqlite") if provider else {}
            provider_payload = provider_summary.get("providers", {}).get("portable_sqlite") if isinstance(provider_summary.get("providers"), dict) else {}
            provider_freshness = provider_payload.get("freshness") if isinstance(provider_payload, dict) else {}
            usage_quality = usage_audit.get("quality") if isinstance(usage_audit.get("quality"), dict) else {}
            stale_event_count = int_value(
                usage_quality.get("stale_event_count")
            )
            unverifiable_event_count = int_value(
                usage_quality.get("unverifiable_event_count")
            )
            provider_freshness_status = str(
                provider_freshness.get("status")
                if isinstance(provider_freshness, dict)
                else ""
            )
            if stale_event_count or "stale" in provider_freshness_status:
                usage_scope_status = "scope_stale"
            elif (
                not evidence_refs
                or unverifiable_event_count
                or provider_freshness_status not in {"current", "fresh"}
            ):
                usage_scope_status = "scope_unverified"
            else:
                usage_scope_status = "scope_current"
            graph_freshness_context = (
                packet.get("freshness")
                if isinstance(packet.get("freshness"), dict)
                else {}
            )
            global_graph_freshness = (
                graph_freshness_context.get("global_freshness")
                if isinstance(
                    graph_freshness_context.get("global_freshness"),
                    dict,
                )
                else {
                    "status": "unresolved",
                    "scope": "complete_graph_store",
                    "reasons": [
                        "graph_neighborhood_global_freshness_unavailable"
                    ],
                }
            )
            freshness = {
                "status": usage_scope_status,
                "scope_status": usage_scope_status,
                "timeline_source": timeline_source,
                "graph_status": graph_freshness_context.get("status"),
                "graph_source": graph_freshness_context.get("graph_source"),
                "global_freshness": global_graph_freshness,
                "global_recall_status": (
                    graph_freshness_context.get("global_recall_status")
                    or "unresolved"
                ),
                "scope_freshness": {
                    "status": usage_scope_status,
                    "evidence_ref_count": len(evidence_refs),
                    "does_not_upgrade_global_freshness": True,
                },
                "graph_event_node_status": "missing_in_graph_neighborhood",
                "search_provider_status": provider_payload.get("status") if isinstance(provider_payload, dict) else None,
                "search_provider_freshness_status": provider_freshness_status or None,
                "law": (
                    "timeline fallback routes through usage events; scoped "
                    "source freshness never upgrades global graph recall and "
                    "raw/segment refs remain stronger than graph packets"
                ),
            }
            quality = {
                "fallback_source": "entity_usage_audit",
                "usage_event_count": usage_audit.get("usage_event_count"),
                "consequence_event_count": usage_audit.get("consequence_event_count"),
                "direct_usage_present": usage_quality.get("direct_usage_present"),
                "consequence_present": usage_quality.get("consequence_present"),
                "fresh_event_count": usage_quality.get("fresh_event_count"),
                "stale_event_count": usage_quality.get("stale_event_count"),
                "unverifiable_event_count": usage_quality.get("unverifiable_event_count"),
                "usage_role_fast_path_applied": usage_quality.get("usage_role_fast_path_applied"),
                "search_has_route_index": usage_quality.get("search_has_route_index"),
                "search_has_route_terms": usage_quality.get("search_has_route_terms"),
            }
            diagnostics = [
                *diagnostics,
                *(usage_audit.get("diagnostics", []) if isinstance(usage_audit.get("diagnostics"), list) else []),
                "graph_timeline_event_nodes_missing_used_entity_usage_fallback",
            ]
        else:
            diagnostics = [
                *diagnostics,
                *(usage_audit.get("diagnostics", []) if isinstance(usage_audit.get("diagnostics"), list) else []),
                "graph_timeline_event_nodes_missing_usage_fallback_empty",
            ]
    answer_admission = graph_relation_packet_admission(
        selected_relations,
        has_nodes=bool(selected),
        truncated=bool(
            packet.get("truncated")
            or len(events) > len(selected)
        ),
        freshness=(
            freshness if isinstance(freshness, dict) else {}
        ),
    )
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_timeline",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": bool(selected),
        "mutates": False,
        "truth_status": "graph_timeline_packet_not_reviewed_truth",
        "anchor": anchor,
        "session": session or "",
        **trace_kind_payload_fields(kind, route_kind),
        "timeline_source": timeline_source,
        "route_selection": route_selection,
        "event_count": len(selected),
        "events": [graph_compact_node_for_packet(event) for event in selected],
        "relations": [graph_compact_edge_for_packet(edge) for edge in selected_relations],
        "resolved": resolved,
        "evidence_refs": evidence_refs,
        "freshness": freshness,
        "answer_admission": answer_admission,
        "diagnostics": diagnostics,
        "next_route": "verify important claims through raw_ref, segment_ref, and session_ref before promotion",
        "next_command": graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-timeline",
            anchors=[anchor],
            kind=kind,
            route_kind=route_kind,
            session=session,
            limit=event_limit,
        ),
        "next_expansion_command": graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-timeline",
            anchors=[anchor],
            kind=kind,
            route_kind=route_kind,
            session=session,
            limit=graph_packet_expanded_limit(event_limit, default=event_limit, maximum=200),
        ),
        "next_expansion_reason": "Increase the bounded timeline limit when more event ordering evidence is needed.",
    }
    if provider_summary:
        payload["provider"] = provider_summary
    if quality:
        payload["quality"] = quality
    return payload


def graph_shortest_path(
    *,
    aoa_root: Path,
    source_anchor: str,
    target_anchor: str,
    kind: str = "auto",
    max_depth: int = 4,
) -> dict[str, Any]:
    privacy_gate = derived_text_privacy_field_gate(
        source_anchor=source_anchor,
        target_anchor=target_anchor,
    )
    if privacy_gate["blocked"]:
        return derived_text_privacy_blocked_navigation_result(
            artifact_type="session_memory_graph_shortest_path",
            fields=privacy_gate["fields"],
            metadata=privacy_gate["derived_text_privacy"],
            graph=True,
        )
    normalized_kind = normalize_trace_route_kind(kind)
    route_kind = normalized_kind if normalized_kind in TRACE_ROUTE_KINDS else "auto"
    source_packet = graph_neighborhood(aoa_root=aoa_root, anchor=source_anchor, kind=route_kind, depth=2, limit=80)
    target_packet = graph_neighborhood(aoa_root=aoa_root, anchor=target_anchor, kind=route_kind, depth=2, limit=80)
    graph = {
        "source": "bounded_shortest_path_union",
        "generated_at": utc_now(),
        "nodes": graph_unique_records(
            [
                *(source_packet.get("nodes", []) if isinstance(source_packet.get("nodes"), list) else []),
                *(target_packet.get("nodes", []) if isinstance(target_packet.get("nodes"), list) else []),
            ],
            limit=200,
        ),
        "edges": graph_unique_records(
            [
                *(source_packet.get("edges", []) if isinstance(source_packet.get("edges"), list) else []),
                *(target_packet.get("edges", []) if isinstance(target_packet.get("edges"), list) else []),
            ],
            limit=300,
        ),
        "diagnostics": [
            *(source_packet.get("diagnostics", []) if isinstance(source_packet.get("diagnostics"), list) else []),
            *(target_packet.get("diagnostics", []) if isinstance(target_packet.get("diagnostics"), list) else []),
        ],
    }
    node_map = graph_node_by_id(graph)
    edge_map = graph_edge_by_id(graph)
    source = resolve_graph_anchor(graph, source_anchor, kind=route_kind, limit=30)
    target = resolve_graph_anchor(graph, target_anchor, kind=route_kind, limit=30)
    source_start_node_ids, source_resolution_diagnostics = graph_path_resolved_node_ids(
        source,
        route_kind=route_kind,
        role="source",
    )
    target_start_node_ids, target_resolution_diagnostics = graph_path_resolved_node_ids(
        target,
        route_kind=route_kind,
        role="target",
    )
    target_ids = set(target_start_node_ids)
    adjacency = graph_adjacency(graph.get("edges", []) if isinstance(graph.get("edges"), list) else [])
    max_depth = max(1, min(int_value(max_depth, 4), 8))
    queue: deque[tuple[str, list[str], list[str]]] = deque(
        (node_id, [node_id], []) for node_id in source_start_node_ids
    )
    seen: set[str] = set()
    found_nodes: list[str] = []
    found_edges: list[str] = []
    while queue:
        node_id, path_nodes, path_edges = queue.popleft()
        if node_id in seen:
            continue
        seen.add(node_id)
        if node_id in target_ids:
            found_nodes = path_nodes
            found_edges = path_edges
            break
        if len(path_edges) >= max_depth:
            continue
        for neighbor, edge_id in adjacency.get(node_id, []):
            if neighbor in path_nodes:
                continue
            queue.append((neighbor, [*path_nodes, neighbor], [*path_edges, edge_id]))
    nodes = [node_map[node_id] for node_id in found_nodes if node_id in node_map]
    edges = [edge_map[edge_id] for edge_id in found_edges if edge_id in edge_map]
    evidence_refs = graph_collect_evidence(nodes, edges)
    freshness = graph_freshness(aoa_root, graph)
    answer_admission = graph_relation_packet_admission(
        edges,
        has_nodes=bool(nodes),
        freshness=freshness,
    )
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_shortest_path",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": bool(found_nodes),
        "mutates": False,
        "truth_status": "graph_path_packet_not_reviewed_truth",
        "source_anchor": source_anchor,
        "target_anchor": target_anchor,
        "source_resolved": source,
        "target_resolved": target,
        "max_depth": max_depth,
        "path_length": len(edges) if edges else 0,
        "nodes": [graph_compact_node_for_packet(node) for node in nodes],
        "edges": [graph_compact_edge_for_packet(edge) for edge in edges],
        "evidence_refs": evidence_refs,
        "freshness": freshness,
        "answer_admission": answer_admission,
        "diagnostics": list(
            dict.fromkeys(
                [
                    *(graph.get("diagnostics", []) if isinstance(graph.get("diagnostics"), list) else []),
                    *source_resolution_diagnostics,
                    *target_resolution_diagnostics,
                ]
            )
        ),
        "next_route": "verify path claims through raw_ref, segment_ref, and session_ref before promotion",
        "next_command": graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-shortest-path",
            anchors=[source_anchor, target_anchor],
            kind=kind,
            route_kind=route_kind,
            max_depth=max_depth,
        ),
        "next_expansion_command": graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-shortest-path",
            anchors=[source_anchor, target_anchor],
            kind=kind,
            route_kind=route_kind,
            max_depth=min(max_depth + 1, 8),
        ),
        "next_expansion_reason": "Increase bounded max depth when no bridge is found or a longer relation chain is acceptable.",
    }


