def graph_bridge_command_line(
    *,
    aoa_root: Path,
    source_anchor: str,
    target_anchor: str,
    kind: str,
    route_kind: str,
    source_kind: str,
    source_route_kind: str,
    target_kind: str,
    target_route_kind: str,
    limit: int,
    max_depth: int,
) -> str:
    command = [
        "python3",
        "scripts/aoa_session_memory.py",
        "graph-bridge",
        source_anchor,
        target_anchor,
        "--aoa-root",
        str(aoa_root),
        "--kind",
        graph_packet_cli_kind(kind, route_kind),
        "--limit",
        str(max(1, int_value(limit, 8))),
        "--max-depth",
        str(max(1, min(int_value(max_depth, 4), 8))),
    ]
    if str(source_kind or ""):
        command.extend(["--source-kind", graph_packet_cli_kind(source_kind, source_route_kind)])
    if str(target_kind or ""):
        command.extend(["--target-kind", graph_packet_cli_kind(target_kind, target_route_kind)])
    return " ".join(shlex.quote(part) for part in command)


def graph_bridge_entity_summary(
    *,
    anchor: str,
    requested_kind: str,
    route_kind: str,
    resolved: dict[str, Any],
    timeline: dict[str, Any],
) -> dict[str, Any]:
    route_key = route_key_slug(anchor, fallback="entity", max_chars=80)
    route_signal = f"{route_kind}:{route_key}" if route_kind != "auto" and route_key else ""
    resolution_status = graph_anchor_resolution_status(resolved, route_kind=route_kind)
    return {
        "anchor": anchor,
        "route_key": route_key,
        "kind": route_kind,
        "requested_kind": str(requested_kind or "auto"),
        "route_signal": route_signal,
        "resolver_strategy": resolved.get("resolver_strategy"),
        "resolution_status": resolution_status,
        "exact_resolution": resolution_status == "exact",
        "resolved_start_node_count": len(resolved.get("start_node_ids", []) if isinstance(resolved.get("start_node_ids"), list) else []),
        "timeline_event_count": int_value(timeline.get("event_count"), len(timeline.get("events") or [])),
        "candidate_timeline_event_count": int_value(timeline.get("candidate_event_count")),
        "timeline_ok": bool(timeline.get("ok")),
    }


def graph_bridge_compact_node(node: dict[str, Any]) -> dict[str, Any]:
    compact: dict[str, Any] = {}
    for key in (
        "id",
        "type",
        "label",
        "title",
        "event_type",
        "session_act",
        "conversation_act",
        "session_id",
        "session_label",
        "segment_id",
        "event_id",
        "timestamp",
        "line",
        "route_signal_count",
    ):
        if node.get(key) not in (None, "", [], {}):
            compact[key] = node.get(key)
    if isinstance(node.get("refs"), dict) and node["refs"]:
        compact["refs"] = node["refs"]
    elif isinstance(node.get("evidence_refs"), list):
        for ref in node["evidence_refs"]:
            refs = ref.get("refs") if isinstance(ref, dict) and isinstance(ref.get("refs"), dict) else {}
            if refs:
                compact["refs"] = refs
                break
    if isinstance(node.get("evidence_refs"), list) and node["evidence_refs"]:
        compact["evidence_ref_count"] = len(node["evidence_refs"])
    return compact


def graph_bridge_compact_edge(edge: dict[str, Any]) -> dict[str, Any]:
    compact: dict[str, Any] = {}
    for key in (
        "id",
        "type",
        "source",
        "target",
        "count",
        "relation_contract_version",
        "relation_family",
        "direction",
        "domain_range_status",
        "relation_state",
        "correlation_status",
        "evidence_status",
        "semantic_boundary",
        "answer_admissible",
    ):
        if edge.get(key) not in (None, "", [], {}):
            compact[key] = edge.get(key)
    if isinstance(edge.get("evidence_refs"), list) and edge["evidence_refs"]:
        compact["evidence_ref_count"] = len(edge["evidence_refs"])
    return compact


GRAPH_BRIDGE_DISCOVERY_ONLY_EDGE_TYPES = frozenset(
    {
        "cooccurs_with",
        "event_has_registered_entity_signal",
        "event_has_route_signal",
        "segment_has_route_signal",
        "session_has_registered_entity",
        "session_has_route_signal",
    }
)
GRAPH_BRIDGE_STRUCTURAL_EDGE_TYPES = frozenset(
    {
        "contains",
        "has_event",
        "has_raw_ref",
        "has_segment",
    }
)


def graph_bridge_path_admission(edges: list[dict[str, Any]]) -> dict[str, Any]:
    normalized_edges = [
        graph_relation_contract_payload(edge)
        for edge in edges
        if isinstance(edge, dict)
    ]
    edge_types = [
        str(edge.get("type") or "")
        for edge in normalized_edges
        if edge.get("type")
    ]
    discovery_families = {
        "mention",
        "derived_anchor",
        "canonicalization",
    }
    structural_families = {
        "structural_containment",
        "task_lineage",
        "goal_lineage",
        "ownership_context",
        "evidence_derivation",
    }
    discovery_edge_types = sorted(
        {
            str(edge.get("type") or "")
            for edge in normalized_edges
            if str(edge.get("relation_family") or "")
            in discovery_families
            or str(edge.get("type") or "")
            in GRAPH_BRIDGE_DISCOVERY_ONLY_EDGE_TYPES
        }
    )
    relation_edges = [
        edge
        for edge in normalized_edges
        if str(edge.get("relation_family") or "")
        not in discovery_families | structural_families
        and str(edge.get("type") or "")
        not in GRAPH_BRIDGE_DISCOVERY_ONLY_EDGE_TYPES
        and str(edge.get("type") or "")
        not in GRAPH_BRIDGE_STRUCTURAL_EDGE_TYPES
    ]
    relation_edge_types = sorted(
        {
            str(edge.get("type") or "")
            for edge in relation_edges
        }
    )
    candidate_edge_types = sorted(
        {
            str(edge.get("type") or "")
            for edge in relation_edges
            if str(edge.get("relation_state") or "")
            != "observed_projection"
        }
    )
    invalid_edge_types = sorted(
        {
            str(edge.get("type") or "")
            for edge in normalized_edges
            if not edge.get("navigation_admissible")
            or str(edge.get("relation_state") or "") == "rejected"
        }
    )
    if not edge_types:
        status = "no_candidate_path"
        admitted = False
        reason = "no bounded path joined the exact anchors"
    elif invalid_edge_types:
        status = "rejected_invalid_relation"
        admitted = False
        reason = (
            "the path contains a relation rejected by domain, range, "
            "correlation, or evidence contract"
        )
    elif discovery_edge_types:
        status = (
            "rejected_discovery_only"
            if not relation_edge_types
            else "rejected_discovery_edge_in_relation_path"
        )
        admitted = False
        reason = "mention, cooccurrence, and route-rollup edges are discovery hints, not typed relations"
    elif not relation_edge_types:
        status = "rejected_structural_only"
        admitted = False
        reason = "containment alone does not establish a relation between the requested anchors"
    elif candidate_edge_types:
        status = "rejected_inferred_relation_candidate"
        admitted = False
        reason = (
            "the path contains an inferred or unverified relation candidate; "
            "it remains discovery context until source admission"
        )
    else:
        status = "admitted_observed_typed_navigation"
        admitted = True
        reason = (
            "the bounded path contains observed typed relation projections and "
            "no discovery-only edge; source evidence still must be read"
        )
    return {
        "status": status,
        "admitted": admitted,
        "answer_admissible": False,
        "reason": reason,
        "edge_types": list(dict.fromkeys(edge_types)),
        "discovery_edge_types": discovery_edge_types,
        "relation_edge_types": relation_edge_types,
        "candidate_edge_types": candidate_edge_types,
        "invalid_edge_types": invalid_edge_types,
        "relation_contract_version": GRAPH_RELATION_CONTRACT_VERSION,
        "policy": (
            "reject discovery, invalid, and inferred relation edges; require "
            "at least one observed non-structural typed relation for navigation"
        ),
        "authority_boundary": (
            "path admission accepts navigation only and never admits a claim "
            "without bounded source-aware evidence reading"
        ),
    }


def graph_bridge_evidence_refs(refs: list[Any], *, limit: int) -> list[Any]:
    selected: list[Any] = []
    seen: set[str] = set()
    for ref in refs:
        values = graph_ref_values(ref)
        if any(values.get(key) for key in ("session", "segment", "raw")):
            token = "|".join(str(values.get(key) or "") for key in ("session", "segment", "raw"))
        else:
            token = "|".join(str(values.get(key) or "") for key in ("session_id", "segment_id", "event_id"))
        if not token.strip("|"):
            token = graph_evidence_ref_token(ref)
        if token in seen:
            continue
        seen.add(token)
        selected.append(ref)
        if len(selected) >= limit:
            break
    return selected


def graph_bridge_compact_freshness(packet: dict[str, Any]) -> dict[str, Any]:
    freshness = packet.get("freshness") if isinstance(packet.get("freshness"), dict) else {}
    compact = {
        key: freshness.get(key)
        for key in (
            "status",
            "graph_source",
            "graph_generated_at",
            "search_index_generated_at",
            "hot_gate_status",
            "needs_maintenance",
            "needs_full_rebuild",
            "actionable_graph_source_count",
            "deferred_live_source_count",
            "ledger_store_missing_count",
            "latest_maintenance_remaining_count",
            "scope_status",
            "scope_source_count",
            "scope_current_source_count",
            "scope_stale_source_count",
            "scope_deferred_live_source_count",
            "scope_blocked_source_count",
            "scope_unverified_source_count",
            "global_recall_status",
            "neighborhood_scope_status",
        )
        if freshness.get(key) not in (None, "", [], {})
    }
    recommendation = freshness.get("maintenance_recommendation") if isinstance(freshness.get("maintenance_recommendation"), dict) else {}
    if recommendation and recommendation.get("route") not in (None, "", "none"):
        compact["maintenance_recommendation"] = {
            key: recommendation.get(key)
            for key in ("route", "reason", "command", "actionable_count", "blocked_count")
            if recommendation.get(key) not in (None, "", [], {})
        }
    return compact


def graph_bridge_selected_event_scope_freshness(
    events: Iterable[dict[str, Any]],
    neighborhood_freshness: dict[str, Any],
) -> dict[str, Any]:
    source_keys = sorted(
        {
            graph_source_key(
                "segment",
                str(event.get("session_id") or ""),
                str(event.get("segment_id") or ""),
            )
            for event in events
            if isinstance(event, dict)
            and str(event.get("session_id") or "")
            and str(event.get("segment_id") or "")
        }
    )
    if not source_keys:
        return {}
    samples = (
        neighborhood_freshness.get("scope_sources_sample")
        if isinstance(neighborhood_freshness.get("scope_sources_sample"), list)
        else []
    )
    sample_by_key = {
        str(item.get("source_key") or ""): item
        for item in samples
        if isinstance(item, dict) and item.get("source_key")
    }
    selected_sources: list[dict[str, Any]] = []
    counts: Counter[str] = Counter()
    for source_key in source_keys:
        source = sample_by_key.get(source_key)
        if isinstance(source, dict):
            selected = dict(source)
            status = str(selected.get("status") or "unverified")
        else:
            selected = {
                "source_key": source_key,
                "status": "unverified",
                "reasons": ["selected_event_source_missing_from_neighborhood_scope_sample"],
            }
            status = "unverified"
        selected_sources.append(selected)
        counts[status] += 1
    if counts["blocked"]:
        scope_status = "scope_blocked"
    elif counts["stale"] or counts["missing"]:
        scope_status = "scope_stale"
    elif counts["deferred_live"]:
        scope_status = "scope_deferred_live"
    elif counts["unverified"]:
        scope_status = "scope_unverified"
    elif counts["current"] == len(source_keys):
        scope_status = "scope_current"
    else:
        scope_status = "scope_unverified"
    return {
        "scope_status": scope_status,
        "scope_basis": "selected_timeline_event_sources_from_neighborhood_scope",
        "scope_source_count": len(source_keys),
        "scope_current_source_count": counts["current"],
        "scope_stale_source_count": counts["stale"] + counts["missing"],
        "scope_deferred_live_source_count": counts["deferred_live"],
        "scope_blocked_source_count": counts["blocked"],
        "scope_unverified_source_count": counts["unverified"],
        "scope_sources_sample": selected_sources[:12],
        "scope_truth_status": "selected timeline evidence freshness does not prove neighborhood completeness, global recall, or relation truth",
    }


def graph_bridge_compact_timeline_from_neighborhood(
    *,
    aoa_root: Path,
    anchor: str,
    requested_kind: str,
    route_kind: str,
    neighborhood: dict[str, Any],
    limit: int,
) -> dict[str, Any]:
    selected_limit = max(1, min(int_value(limit, 8), 30))
    nodes = neighborhood.get("nodes") if isinstance(neighborhood.get("nodes"), list) else []
    events = [node for node in nodes if isinstance(node, dict) and node.get("type") == "event"]
    events.sort(key=lambda node: (str(node.get("timestamp") or ""), str(node.get("session_label") or ""), int_value(node.get("line")), str(node.get("event_id") or "")))
    candidate_events = events[:selected_limit]
    selected_event_evidence_refs = graph_bridge_evidence_refs(
        graph_collect_evidence(candidate_events, [], limit=selected_limit * 4),
        limit=max(selected_limit * 4, selected_limit),
    )
    resolved = neighborhood.get("resolved") if isinstance(neighborhood.get("resolved"), dict) else {}
    resolution_status = graph_anchor_resolution_status(resolved, route_kind=route_kind)
    typed_candidate_only = route_kind != "auto" and resolution_status != "exact"
    selected_events = [] if typed_candidate_only else candidate_events
    evidence_refs = [] if typed_candidate_only else selected_event_evidence_refs
    candidate_evidence_refs = (
        graph_bridge_evidence_refs(
            [
                *(neighborhood.get("evidence_refs", []) if isinstance(neighborhood.get("evidence_refs"), list) else []),
                *selected_event_evidence_refs,
            ],
            limit=max(selected_limit * 4, selected_limit),
        )
        if typed_candidate_only
        else []
    )
    diagnostics = list(
        neighborhood.get("diagnostics", [])
        if isinstance(neighborhood.get("diagnostics"), list)
        else []
    )
    if typed_candidate_only:
        diagnostics.append("typed_anchor_timeline_requires_exact_resolution")
    freshness = dict(neighborhood.get("freshness") if isinstance(neighborhood.get("freshness"), dict) else {})
    selected_scope = graph_bridge_selected_event_scope_freshness(candidate_events, freshness)
    if selected_scope:
        freshness["neighborhood_scope_status"] = freshness.get("scope_status")
        freshness.update(selected_scope)
    freshness["timeline_source"] = "side_neighborhood_compact_sample"
    freshness["timeline_deferred"] = True
    freshness["law"] = "graph-bridge first packet uses bounded side-neighborhood refs; run graph-timeline only when deeper ordering is needed."
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_timeline",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": bool(selected_events or evidence_refs),
        "mutates": False,
        "truth_status": "graph_timeline_packet_not_reviewed_truth",
        "anchor": anchor,
        **trace_kind_payload_fields(requested_kind, route_kind),
        "timeline_source": "side_neighborhood_compact_sample",
        "resolution_status": resolution_status,
        "event_count": len(selected_events),
        "events": selected_events,
        "candidate_event_count": len(candidate_events) if typed_candidate_only else 0,
        "candidate_events": candidate_events if typed_candidate_only else [],
        "candidate_evidence_refs": candidate_evidence_refs if typed_candidate_only else [],
        "resolved": resolved,
        "evidence_refs": evidence_refs,
        "freshness": freshness,
        "diagnostics": diagnostics,
        "next_route": "Run graph-timeline only when event ordering needs more examples; verify important claims through raw/segment refs.",
        "next_command": graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-timeline",
            anchors=[anchor],
            kind=requested_kind,
            route_kind=route_kind,
            limit=selected_limit,
        ),
        "next_expansion_command": graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-timeline",
            anchors=[anchor],
            kind=requested_kind,
            route_kind=route_kind,
            limit=graph_packet_expanded_limit(selected_limit, default=selected_limit, maximum=200),
        ),
    }


def graph_bridge(
    *,
    aoa_root: Path,
    source_anchor: str,
    target_anchor: str,
    kind: str = "auto",
    source_kind: str = "",
    target_kind: str = "",
    max_depth: int = 4,
    limit: int = 8,
) -> dict[str, Any]:
    privacy_gate = derived_text_privacy_field_gate(
        source_anchor=source_anchor,
        target_anchor=target_anchor,
    )
    if privacy_gate["blocked"]:
        return derived_text_privacy_blocked_navigation_result(
            artifact_type="session_memory_graph_bridge",
            fields=privacy_gate["fields"],
            metadata=privacy_gate["derived_text_privacy"],
            graph=True,
        )
    normalized_kind = normalize_trace_route_kind(kind)
    route_kind = normalized_kind if normalized_kind in TRACE_ROUTE_KINDS else "auto"
    normalized_source_kind = normalize_trace_route_kind(source_kind or route_kind)
    source_route_kind = normalized_source_kind if normalized_source_kind in TRACE_ROUTE_KINDS else route_kind
    normalized_target_kind = normalize_trace_route_kind(target_kind or route_kind)
    target_route_kind = normalized_target_kind if normalized_target_kind in TRACE_ROUTE_KINDS else route_kind
    selected_limit = max(1, min(int_value(limit, 8), 30))
    selected_max_depth = max(1, min(int_value(max_depth, 4), 8))
    started = time.monotonic()
    phase_timings: list[dict[str, Any]] = []

    def timed_phase(name: str, func: Callable[[], dict[str, Any]]) -> dict[str, Any]:
        phase_started = time.monotonic()
        result = func()
        phase_timings.append({"phase": name, "elapsed_ms": int((time.monotonic() - phase_started) * 1000)})
        return result

    bridge_side_depth = selected_max_depth
    bridge_node_limit = max(selected_limit, 4)
    bridge_edge_limit = max(selected_limit * 2, 8)
    source_neighborhood = timed_phase(
        "source_neighborhood",
        lambda: graph_neighborhood(
            aoa_root=aoa_root,
            anchor=source_anchor,
            kind=source_route_kind,
            depth=bridge_side_depth,
            limit=bridge_node_limit,
            edge_limit=bridge_edge_limit,
        ),
    )
    target_neighborhood = timed_phase(
        "target_neighborhood",
        lambda: graph_neighborhood(
            aoa_root=aoa_root,
            anchor=target_anchor,
            kind=target_route_kind,
            depth=bridge_side_depth,
            limit=bridge_node_limit,
            edge_limit=bridge_edge_limit,
        ),
    )
    path = timed_phase(
        "shortest_path",
        lambda: graph_shortest_path_from_packets(
            aoa_root=aoa_root,
            source_anchor=source_anchor,
            target_anchor=target_anchor,
            source_packet=source_neighborhood,
            target_packet=target_neighborhood,
            kind=route_kind,
            source_kind=source_route_kind,
            target_kind=target_route_kind,
            max_depth=selected_max_depth,
        ),
    )
    source_timeline = timed_phase(
        "source_compact_timeline",
        lambda: graph_bridge_compact_timeline_from_neighborhood(
            aoa_root=aoa_root,
            anchor=source_anchor,
            requested_kind=source_kind or route_kind,
            route_kind=source_route_kind,
            neighborhood=source_neighborhood,
            limit=selected_limit,
        ),
    )
    target_timeline = timed_phase(
        "target_compact_timeline",
        lambda: graph_bridge_compact_timeline_from_neighborhood(
            aoa_root=aoa_root,
            anchor=target_anchor,
            requested_kind=target_kind or route_kind,
            route_kind=target_route_kind,
            neighborhood=target_neighborhood,
            limit=selected_limit,
        ),
    )

    path_nodes = path.get("nodes") if isinstance(path.get("nodes"), list) else []
    path_edges = path.get("edges") if isinstance(path.get("edges"), list) else []
    source_events = source_timeline.get("events") if isinstance(source_timeline.get("events"), list) else []
    target_events = target_timeline.get("events") if isinstance(target_timeline.get("events"), list) else []
    source_candidate_events = source_timeline.get("candidate_events") if isinstance(source_timeline.get("candidate_events"), list) else []
    target_candidate_events = target_timeline.get("candidate_events") if isinstance(target_timeline.get("candidate_events"), list) else []
    source_candidate_evidence_refs = source_timeline.get("candidate_evidence_refs") if isinstance(source_timeline.get("candidate_evidence_refs"), list) else []
    target_candidate_evidence_refs = target_timeline.get("candidate_evidence_refs") if isinstance(target_timeline.get("candidate_evidence_refs"), list) else []
    candidate_path_found = bool(path.get("ok") and path_nodes)
    path_admission = graph_bridge_path_admission(
        [edge for edge in path_edges if isinstance(edge, dict)]
    )
    path_found = bool(candidate_path_found and path_admission.get("admitted"))
    accepted_path_nodes = path_nodes if path_found else []
    accepted_path_edges = path_edges if path_found else []
    candidate_path_evidence_refs = (
        path.get("evidence_refs", [])
        if isinstance(path.get("evidence_refs"), list)
        else []
    )
    evidence_refs = graph_bridge_evidence_refs(
        [
            *(candidate_path_evidence_refs if path_found else []),
            *(source_timeline.get("evidence_refs", []) if isinstance(source_timeline.get("evidence_refs"), list) else []),
            *(target_timeline.get("evidence_refs", []) if isinstance(target_timeline.get("evidence_refs"), list) else []),
        ],
        limit=80,
    )
    ref_counts = graph_ref_quality_counts(evidence_refs)
    source_resolved = path.get("source_resolved") if isinstance(path.get("source_resolved"), dict) else {}
    target_resolved = path.get("target_resolved") if isinstance(path.get("target_resolved"), dict) else {}
    source_resolution_status = graph_anchor_resolution_status(
        source_resolved,
        route_kind=source_route_kind,
    )
    target_resolution_status = graph_anchor_resolution_status(
        target_resolved,
        route_kind=target_route_kind,
    )
    noise_flags: list[str] = []
    if not candidate_path_found:
        noise_flags.append("no_bounded_graph_path_found")
    elif not path_found:
        path_status = str(path_admission.get("status") or "rejected")
        noise_flags.append(
            "bridge_path_rejected_discovery_only"
            if path_status.startswith("rejected_discovery")
            else f"bridge_path_{path_status}"
        )
    if source_route_kind != "auto" and source_resolution_status != "exact":
        noise_flags.append("typed_source_requires_exact_resolution")
    if target_route_kind != "auto" and target_resolution_status != "exact":
        noise_flags.append("typed_target_requires_exact_resolution")
    if not evidence_refs:
        noise_flags.append("no_evidence_refs_returned")
    if not (ref_counts.get("raw_ref_count") or ref_counts.get("segment_ref_count")):
        noise_flags.append("no_raw_or_segment_refs")
    for label, packet in (("path", path), ("source_timeline", source_timeline), ("target_timeline", target_timeline)):
        freshness = packet.get("freshness") if isinstance(packet.get("freshness"), dict) else {}
        if freshness.get("needs_maintenance") or freshness.get("status") in {"stale", "graph_store_stale"}:
            noise_flags.append(f"{label}_freshness_requires_attention")
    for label, packet in (("source_neighborhood", source_neighborhood), ("target_neighborhood", target_neighborhood)):
        freshness = packet.get("freshness") if isinstance(packet.get("freshness"), dict) else {}
        if freshness.get("needs_maintenance") or freshness.get("status") in {"stale", "graph_store_stale"}:
            noise_flags.append(f"{label}_freshness_requires_attention")

    current_command = graph_bridge_command_line(
        aoa_root=aoa_root,
        source_anchor=source_anchor,
        target_anchor=target_anchor,
        kind=kind,
        route_kind=route_kind,
        source_kind=source_kind,
        source_route_kind=source_route_kind,
        target_kind=target_kind,
        target_route_kind=target_route_kind,
        limit=selected_limit,
        max_depth=selected_max_depth,
    )
    expansion_command = graph_bridge_command_line(
        aoa_root=aoa_root,
        source_anchor=source_anchor,
        target_anchor=target_anchor,
        kind=kind,
        route_kind=route_kind,
        source_kind=source_kind,
        source_route_kind=source_route_kind,
        target_kind=target_kind,
        target_route_kind=target_route_kind,
        limit=graph_packet_expanded_limit(selected_limit, default=selected_limit, maximum=30),
        max_depth=min(selected_max_depth + 1, 8),
    )
    bridge_freshness = {
        "path": graph_bridge_compact_freshness(path),
        "source_timeline": graph_bridge_compact_freshness(
            source_timeline
        ),
        "target_timeline": graph_bridge_compact_freshness(
            target_timeline
        ),
        "source_neighborhood": graph_bridge_compact_freshness(
            source_neighborhood
        ),
        "target_neighborhood": graph_bridge_compact_freshness(
            target_neighborhood
        ),
    }
    answer_admission = graph_relation_packet_admission(
        path_edges,
        has_nodes=bool(path_nodes),
        truncated=bool(
            source_neighborhood.get("truncated")
            or target_neighborhood.get("truncated")
        ),
        freshness=(
            path.get("freshness")
            if isinstance(path.get("freshness"), dict)
            else {}
        ),
    )
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_bridge",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": bool(path_found or evidence_refs or source_events or target_events),
        "mutates": False,
        "truth_status": "graph_bridge_packet_not_reviewed_truth",
        "source_anchor": source_anchor,
        "target_anchor": target_anchor,
        **trace_kind_payload_fields(kind, route_kind),
        "source_kind": source_route_kind,
        "target_kind": target_route_kind,
        "normalized_entities": {
            "source": graph_bridge_entity_summary(
                anchor=source_anchor,
                requested_kind=source_kind or route_kind,
                route_kind=source_route_kind,
                resolved=source_resolved,
                timeline=source_timeline,
            ),
            "target": graph_bridge_entity_summary(
                anchor=target_anchor,
                requested_kind=target_kind or route_kind,
                route_kind=target_route_kind,
                resolved=target_resolved,
                timeline=target_timeline,
            ),
        },
        "bridge": {
            "path_found": path_found,
            "path_status": path_admission.get("status"),
            "path_admission": path_admission,
            "path_length": int_value(path.get("path_length"), len(accepted_path_edges)) if path_found else 0,
            "candidate_path_found": candidate_path_found,
            "candidate_path_length": int_value(path.get("path_length"), len(path_edges)) if candidate_path_found else 0,
            "max_depth": selected_max_depth,
            "nodes": [graph_bridge_compact_node(node) for node in accepted_path_nodes[:selected_limit] if isinstance(node, dict)],
            "edges": [graph_bridge_compact_edge(edge) for edge in accepted_path_edges[: max(selected_limit * 2, selected_limit)] if isinstance(edge, dict)],
            "evidence_refs": candidate_path_evidence_refs[:selected_limit] if path_found else [],
            "next_expansion_command": path.get("next_expansion_command"),
        },
        "usage_chain": {
            "source_event_count": int_value(source_timeline.get("event_count"), len(source_events)),
            "target_event_count": int_value(target_timeline.get("event_count"), len(target_events)),
            "source_events": [graph_bridge_compact_node(event) for event in source_events[:selected_limit] if isinstance(event, dict)],
            "target_events": [graph_bridge_compact_node(event) for event in target_events[:selected_limit] if isinstance(event, dict)],
        },
        "candidate_context": {
            "law": "fuzzy typed-anchor matches and discovery-only graph paths remain auditable context and cannot satisfy a typed bridge or usage claim",
            "bridge_path": {
                "status": path_admission.get("status"),
                "reason": path_admission.get("reason"),
                "path_found": candidate_path_found,
                "path_length": int_value(path.get("path_length"), len(path_edges)) if candidate_path_found else 0,
                "nodes": [graph_bridge_compact_node(node) for node in path_nodes[:selected_limit] if isinstance(node, dict)] if candidate_path_found and not path_found else [],
                "edges": [graph_bridge_compact_edge(edge) for edge in path_edges[: max(selected_limit * 2, selected_limit)] if isinstance(edge, dict)] if candidate_path_found and not path_found else [],
                "evidence_refs": candidate_path_evidence_refs[:selected_limit] if candidate_path_found and not path_found else [],
            },
            "source_node_ids": (
                source_resolved.get("start_node_ids", [])
                if source_resolution_status == "candidate_only"
                and isinstance(source_resolved.get("start_node_ids"), list)
                else []
            ),
            "target_node_ids": (
                target_resolved.get("start_node_ids", [])
                if target_resolution_status == "candidate_only"
                and isinstance(target_resolved.get("start_node_ids"), list)
                else []
            ),
            "source_event_count": len(source_candidate_events),
            "target_event_count": len(target_candidate_events),
            "source_events": [graph_bridge_compact_node(event) for event in source_candidate_events[:selected_limit] if isinstance(event, dict)],
            "target_events": [graph_bridge_compact_node(event) for event in target_candidate_events[:selected_limit] if isinstance(event, dict)],
            "source_evidence_refs": source_candidate_evidence_refs[: max(selected_limit * 3, selected_limit)],
            "target_evidence_refs": target_candidate_evidence_refs[: max(selected_limit * 3, selected_limit)],
        },
        "evidence_refs": evidence_refs[: max(selected_limit * 3, selected_limit)],
        "evidence_ref_count": len(evidence_refs),
        "freshness": bridge_freshness,
        "answer_admission": answer_admission,
        "quality": {
            "one_short_route": True,
            "path_found": path_found,
            "path_status": path_admission.get("status"),
            "path_length": int_value(path.get("path_length"), len(accepted_path_edges)) if path_found else 0,
            "path_node_count": len(accepted_path_nodes),
            "path_edge_count": len(accepted_path_edges),
            "candidate_path_found": candidate_path_found,
            "candidate_path_node_count": len(path_nodes),
            "candidate_path_edge_count": len(path_edges),
            "path_admission": path_admission,
            "compact_side_neighborhood": True,
            "side_neighborhood_depth": bridge_side_depth,
            "side_neighborhood_node_limit": bridge_node_limit,
            "side_neighborhood_edge_limit": bridge_edge_limit,
            "side_timeline_policy": "side_neighborhood_compact_sample",
            "side_timelines_deferred": True,
            "source_event_count": int_value(source_timeline.get("event_count"), len(source_events)),
            "target_event_count": int_value(target_timeline.get("event_count"), len(target_events)),
            "source_neighborhood_node_count": int_value(source_neighborhood.get("node_count"), len(source_neighborhood.get("nodes") or [])),
            "target_neighborhood_node_count": int_value(target_neighborhood.get("node_count"), len(target_neighborhood.get("nodes") or [])),
            "evidence_ref_count": len(evidence_refs),
            "raw_or_segment_ref_present": bool(ref_counts.get("raw_ref_count") or ref_counts.get("segment_ref_count")),
            "ref_counts": ref_counts,
            "noise_flag_count": len(noise_flags),
        },
        "noise_flags": noise_flags,
        "diagnostics": [
            *(path.get("diagnostics", []) if isinstance(path.get("diagnostics"), list) else []),
            *(source_timeline.get("diagnostics", []) if isinstance(source_timeline.get("diagnostics"), list) else []),
            *(target_timeline.get("diagnostics", []) if isinstance(target_timeline.get("diagnostics"), list) else []),
            *(source_neighborhood.get("diagnostics", []) if isinstance(source_neighborhood.get("diagnostics"), list) else []),
            *(target_neighborhood.get("diagnostics", []) if isinstance(target_neighborhood.get("diagnostics"), list) else []),
        ],
        "elapsed_ms": int((time.monotonic() - started) * 1000),
        "timings": phase_timings,
        "next_route": "Use graph-bridge as a compact relation route; verify important claims through raw_ref, segment_ref, and owner source surfaces.",
        "next_command": current_command,
        "next_expansion_command": expansion_command,
        "next_expansion": [
            {
                "id": "shortest_path",
                "command": path.get("next_expansion_command"),
                "use_when": "the bounded bridge path is missing or a longer relation chain is acceptable",
            },
            {
                "id": "source_timeline",
                "command": source_timeline.get("next_expansion_command"),
                "use_when": "source-side usage/event ordering needs more examples",
            },
            {
                "id": "target_timeline",
                "command": target_timeline.get("next_expansion_command"),
                "use_when": "target-side usage/event ordering needs more examples",
            },
        ],
        "authority_boundary": "graph bridge routes relation evidence only; raw/segment refs and owner source surfaces remain stronger.",
    }
    return payload


def graph_cooccurrence_from_packet(
    *,
    aoa_root: Path,
    packet: dict[str, Any],
    anchor: str,
    kind: str = "auto",
    limit: int = 30,
    source: str = "bounded_cooccurrence_neighborhood",
) -> dict[str, Any]:
    normalized_kind = normalize_trace_route_kind(kind)
    route_kind = normalized_kind if normalized_kind in TRACE_ROUTE_KINDS else "auto"
    graph = {
        "source": source,
        "generated_at": utc_now(),
        "nodes": packet.get("nodes", []) if isinstance(packet.get("nodes"), list) else [],
        "edges": packet.get("edges", []) if isinstance(packet.get("edges"), list) else [],
        "diagnostics": packet.get("diagnostics", []) if isinstance(packet.get("diagnostics"), list) else [],
    }
    node_map = graph_node_by_id(graph)
    resolved = packet.get("resolved") if isinstance(packet.get("resolved"), dict) else {}
    if not resolved.get("start_node_ids"):
        resolved = resolve_graph_anchor(graph, anchor, kind=route_kind, limit=60)
    if not resolved.get("start_node_ids"):
        resolved = packet.get("resolved", resolved) if isinstance(packet.get("resolved"), dict) else resolved
    start_ids = set(resolved.get("start_node_ids", []))
    event_to_routes: dict[str, set[str]] = defaultdict(set)
    route_to_events: dict[str, set[str]] = defaultdict(set)
    for edge in graph.get("edges", []) if isinstance(graph.get("edges"), list) else []:
        if not isinstance(edge, dict) or edge.get("type") != "event_has_route_signal":
            continue
        source = str(edge.get("source") or "")
        target = str(edge.get("target") or "")
        event_to_routes[source].add(target)
        route_to_events[target].add(source)
    anchor_events: set[str] = set()
    for node_id in start_ids:
        node = node_map.get(node_id, {})
        if node.get("type") == "event":
            anchor_events.add(node_id)
        if node_id in route_to_events:
            anchor_events.update(route_to_events[node_id])
    counts: Counter[str] = Counter()
    samples: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for event_id in anchor_events:
        event_node = node_map.get(event_id, {})
        for route_id in event_to_routes.get(event_id, set()):
            if route_id in start_ids:
                continue
            counts[route_id] += 1
            if len(samples[route_id]) < 5:
                samples[route_id].append(
                    {
                        "event_node_id": event_id,
                        "event_title": event_node.get("title") or event_node.get("label"),
                        "session_id": event_node.get("session_id"),
                        "segment_id": event_node.get("segment_id"),
                        "event_id": event_node.get("event_id"),
                        "refs": event_node.get("refs"),
                    }
                )
    selected = []
    for route_id, count in counts.most_common(max(1, min(int_value(limit, 30), 100))):
        route_node = node_map.get(route_id, {})
        selected.append({"node": graph_compact_node_for_packet(route_node), "count": count, "samples": samples.get(route_id, [])})
    evidence_nodes = [node_map[event_id] for event_id in anchor_events if event_id in node_map]
    selected_limit = max(1, min(int_value(limit, 30), 100))
    diagnostics = list(graph.get("diagnostics", []))
    if anchor_events and not selected:
        diagnostics.append("graph_cooccurrence_no_route_neighbors_in_bounded_packet")
    if packet.get("truncated") and not selected:
        diagnostics.append("graph_cooccurrence_bounded_packet_truncated_before_cooccurrence_routes")
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_cooccurrence",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": bool(selected),
        "mutates": False,
        "truth_status": "cooccurrence_packet_not_reviewed_truth",
        "source": source,
        "anchor": anchor,
        **trace_kind_payload_fields(kind, route_kind),
        "resolved": resolved,
        "anchor_event_count": len(anchor_events),
        "cooccurrence_count": len(selected),
        "cooccurrences": selected,
        "evidence_refs": graph_collect_evidence(evidence_nodes, [], limit=80),
        "freshness": packet.get("freshness") if isinstance(packet.get("freshness"), dict) else graph_freshness(aoa_root, graph),
        "diagnostics": diagnostics,
        "next_route": (
            "verify cooccurrence claims through raw_ref, segment_ref, and session_ref before promotion"
            if selected
            else "use graph-neighborhood for nearby evidence refs or increase the bounded cooccurrence route only when route cooccurrences are required"
        ),
        "next_command": graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-cooccurrence",
            anchors=[anchor],
            kind=kind,
            route_kind=route_kind,
            limit=selected_limit,
        ),
        "next_expansion_command": graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-cooccurrence",
            anchors=[anchor],
            kind=kind,
            route_kind=route_kind,
            limit=graph_packet_expanded_limit(selected_limit, default=selected_limit, maximum=100),
        ),
        "next_expansion_reason": "Increase the bounded cooccurrence limit when more neighboring route signals are needed.",
    }


def graph_route_node_signal(node_id: str, node: dict[str, Any] | None = None) -> dict[str, str]:
    if isinstance(node, dict):
        layer = route_key_slug(node.get("route_layer"), fallback="")
        key = route_key_slug(node.get("route_key"), fallback="")
        if layer and key:
            return {
                "layer": layer,
                "key": key,
                "route_signal": str(node.get("route_signal") or route_signal_token(layer, key)),
            }
    parts = str(node_id or "").split(":", 3)
    if len(parts) == 4 and parts[0] == "route":
        layer = route_key_slug(parts[2], fallback="")
        key = route_key_slug(parts[3], fallback="")
        if layer and key:
            return {"layer": layer, "key": key, "route_signal": route_signal_token(layer, key)}
    return {}


def graph_segment_index_path_from_ref(
    aoa_root: Path,
    refs: dict[str, str],
    *,
    session_id: str = "",
    segment_id: str = "",
) -> Path | None:
    segment_ref = str(refs.get("segment_index") or refs.get("segment") or "")
    if segment_ref:
        segment_path = path_without_anchor(segment_ref)
        if not segment_path.is_absolute():
            segment_path = aoa_root / segment_path
        if segment_path.suffix == ".md":
            candidate = segment_path.with_suffix(".index.json")
            if candidate.exists():
                return candidate
        if segment_path.suffix == ".json" and segment_path.exists():
            return segment_path
    session_ref = str(refs.get("session") or "")
    if session_ref and segment_id:
        session_path = path_without_anchor(session_ref)
        if not session_path.is_absolute():
            session_path = aoa_root / session_path
        session_dir = session_path.parent
        for candidate in sorted((session_dir / "segments").glob(f"{segment_id}*.index.json")):
            if candidate.exists():
                return candidate
    if session_id and segment_id:
        session_dir = aoa_root / SESSION_ROOT / session_id
        for candidate in sorted((session_dir / "segments").glob(f"{segment_id}*.index.json")):
            if candidate.exists():
                return candidate
    return None


def graph_event_ref_from_segment_index_event(
    *,
    segment_index_path: Path,
    segment_index: dict[str, Any],
    edge_ref: dict[str, Any],
    event: dict[str, Any],
) -> dict[str, Any]:
    refs = graph_ref_values(edge_ref)
    source_block = segment_index.get("source_block") if isinstance(segment_index.get("source_block"), dict) else {}
    markdown = str(segment_index.get("markdown") or refs.get("segment") or "")
    md_anchor = str(event.get("md_anchor") or "")
    if md_anchor:
        segment_ref = md_anchor
        if markdown and "#" not in md_anchor and Path(md_anchor).name == md_anchor:
            segment_ref = md_anchor
    else:
        segment_ref = markdown
    event_refs = {
        "session": refs.get("session", ""),
        "segment": segment_ref,
        "segment_index": str(segment_index_path),
        "raw": str(event.get("raw_ref") or ""),
        "raw_block": str(source_block.get("rel") or source_block.get("path") or ""),
    }
    event_refs = {key: value for key, value in event_refs.items() if value}
    return {
        "session_id": refs.get("session_id") or edge_ref.get("session_id") or "",
        "segment_id": refs.get("segment_id") or edge_ref.get("segment_id") or str(segment_index.get("segment_id") or ""),
        "event_id": str(event.get("event_id") or ""),
        "refs": event_refs,
    }


def graph_cooccurrence_hydrate_raw_refs_from_segments(
    *,
    aoa_root: Path,
    route_node_ids: set[str],
    context_edge_payloads: list[dict[str, Any]],
    limit: int = 80,
) -> list[dict[str, Any]]:
    route_signals = {
        node_id: graph_route_node_signal(node_id)
        for node_id in route_node_ids
    }
    target_signals = {
        (signal.get("layer"), signal.get("key"))
        for signal in route_signals.values()
        if signal.get("layer") and signal.get("key")
    }
    if not target_signals:
        return []
    selected: list[dict[str, Any]] = []
    segment_cache: dict[Path, dict[str, Any]] = {}
    for edge in context_edge_payloads:
        if len(selected) >= limit:
            break
        if not isinstance(edge, dict) or str(edge.get("type") or "") != "segment_has_route_signal":
            continue
        source = str(edge.get("source") or "")
        parts = source.split(":", 2)
        session_id = parts[1] if len(parts) == 3 and parts[0] == "segment" else ""
        segment_id = parts[2] if len(parts) == 3 and parts[0] == "segment" else ""
        for edge_ref in edge.get("evidence_refs", []) if isinstance(edge.get("evidence_refs"), list) else []:
            refs = graph_ref_values(edge_ref)
            segment_index_path = graph_segment_index_path_from_ref(
                aoa_root,
                refs,
                session_id=session_id,
                segment_id=segment_id,
            )
            if segment_index_path is None:
                continue
            if segment_index_path not in segment_cache:
                segment_cache[segment_index_path] = read_json(segment_index_path, {})
            segment_index = segment_cache.get(segment_index_path, {})
            events = segment_index.get("events") if isinstance(segment_index.get("events"), list) else []
            for event in events:
                if len(selected) >= limit:
                    break
                if not isinstance(event, dict):
                    continue
                event_signals = {
                    (signal.get("layer"), signal.get("key"))
                    for signal in graph_route_signals_from_event(event)
                    if signal.get("layer") and signal.get("key")
                }
                if not (event_signals & target_signals):
                    continue
                ref = graph_event_ref_from_segment_index_event(
                    segment_index_path=segment_index_path,
                    segment_index=segment_index,
                    edge_ref=edge_ref,
                    event=event,
                )
                if graph_ref_values(ref).get("raw"):
                    selected.append(ref)
    return graph_unique_records(selected, limit=limit)


def episode_postings_cooccurrence_route_pair(
    layer: Any,
    key: Any,
) -> tuple[str, str] | None:
    normalized_layer = route_key_slug(layer, fallback="")
    normalized_key = route_key_slug(key, fallback="", max_chars=120)
    if not normalized_layer or not normalized_key:
        return None
    if normalized_layer in EPISODE_POSTINGS_COOCCURRENCE_SUPPRESSED_LAYERS:
        return None
    if normalized_layer.startswith("namespace") or normalized_key.startswith("namespace_"):
        return None
    if normalized_key in EPISODE_POSTINGS_COOCCURRENCE_SUPPRESSED_KEYS:
        return None
    if normalized_layer == "tool" and normalized_key == "exec":
        normalized_key = "exec_command"
    return normalized_layer, normalized_key


def episode_postings_cooccurrence_anchor_pair_allowed(
    pair: tuple[str, str],
    *,
    route_kind: str,
) -> bool:
    layer, _key = pair
    if route_kind == "auto":
        return layer in GRAPH_ROUTE_NODE_TYPE_BY_LAYER
    kind_layers = {
        "mcp": {"mcp"},
        "hook": {"hook"},
        "receipt": {"hook_health"},
        "failure": {"failure_mode", "error"},
        "error": {"failure_mode", "error"},
        "decision": {"decision_thread"},
        "github": {"git"},
        "external": {"external_snapshot"},
    }
    return layer in kind_layers.get(route_kind, {route_kind})


def episode_postings_cooccurrence_ref(row: dict[str, Any]) -> dict[str, Any]:
    refs = {
        "raw": str(row.get("raw_ref") or ""),
        "segment": str(row.get("segment_ref") or ""),
        "segment_index": str(row.get("segment_index_ref") or ""),
        "session": str(row.get("session_ref") or ""),
    }
    return {
        "session_id": str(row.get("session_id") or ""),
        "episode_id": str(row.get("episode_id") or ""),
        "relation": str(row.get("relation") or ""),
        "route_signal": str(row.get("route_signal") or ""),
        "refs": {key: value for key, value in refs.items() if value},
    }


def graph_cooccurrence_from_episode_postings(
    *,
    aoa_root: Path,
    anchor: str,
    kind: str = "auto",
    limit: int = 30,
) -> dict[str, Any] | None:
    """Read direct typed relations from task episodes before noisy graph mentions."""
    started = time.monotonic()
    db_path = search_db_path(aoa_root)
    if not db_path.exists():
        return None
    normalized_kind = normalize_trace_route_kind(kind)
    route_kind = normalized_kind if normalized_kind in TRACE_ROUTE_KINDS else "auto"
    selected_limit = max(1, min(int_value(limit, 30), 100))
    context_limit = max(24, min(selected_limit * 12, 128))
    context_candidate_limit = max(512, min(context_limit * 64, 8192))
    route_row_limit = max(512, min(context_limit * 48, 6144))
    evidence_ref_limit = max(12, min(selected_limit * 4, 64))
    projection = episode_semantic_route_state(aoa_root)
    diagnostics = [
        *(str(item) for item in projection.get("diagnostics", []) if item),
        *(str(item) for item in projection.get("reasons", []) if item),
    ]

    candidate_signals = episode_entity_candidate_signals(anchor, route_kind)
    query_pairs: list[tuple[str, str]] = []
    canonical_anchor_pairs: set[tuple[str, str]] = set()
    for signal in candidate_signals:
        raw_layer, separator, raw_key = str(signal).partition(":")
        if not separator:
            continue
        query_layer = route_key_slug(raw_layer, fallback="")
        query_key = route_key_slug(raw_key, fallback="", max_chars=120)
        canonical = episode_postings_cooccurrence_route_pair(query_layer, query_key)
        if canonical is None or not episode_postings_cooccurrence_anchor_pair_allowed(
            canonical,
            route_kind=route_kind,
        ):
            continue
        query_pair = (query_layer, query_key)
        if query_pair not in query_pairs:
            query_pairs.append(query_pair)
        canonical_anchor_pairs.add(canonical)

    conn: sqlite3.Connection | None = None
    schema_available = False
    classifier_epoch_available = False
    relation_counts: Counter[str] = Counter()
    anchor_context_population_count = 0
    anchor_context_population_exact = True
    anchor_rows: list[dict[str, Any]] = []
    selected_doc_rowids: list[int] = []
    selected_session_by_doc: dict[int, str] = {}
    route_rows: list[dict[str, Any]] = []
    route_row_sample_truncated = False
    try:
        conn = connect_existing_search_db(db_path)
        required_tables = {
            "episode_entity_postings",
            "episode_semantic_meta",
            "episode_semantic_session_state",
        }
        schema_available = all(sqlite_table_exists(conn, table) for table in required_tables)
        if not schema_available:
            return None
        state_columns = {
            str(row[1])
            for row in conn.execute("PRAGMA table_info(episode_semantic_session_state)").fetchall()
        }
        classifier_epoch_available = "route_signal_classifier_version" in state_columns
        if not query_pairs:
            diagnostics.append("no_specific_episode_postings_anchor")
        elif not classifier_epoch_available:
            diagnostics.append("episode_semantic_route_signal_classifier_version_missing")
        else:
            pair_clause = " OR ".join(
                "(postings.route_layer = ? AND postings.route_key = ?)"
                for _pair in query_pairs
            )
            pair_params: list[Any] = [value for pair in query_pairs for value in pair]
            current_clause = (
                "meta.projection_version = ? "
                "AND state.projection_version = ? "
                "AND state.route_signal_classifier_version = ? "
                "AND state.status IN ('current', 'no_task_episodes', 'no_admitted_episode_text')"
            )
            current_params: list[Any] = [
                EPISODE_SEMANTIC_PROJECTION_VERSION,
                EPISODE_SEMANTIC_PROJECTION_VERSION,
                ROUTE_SIGNAL_CLASSIFIER_VERSION,
            ]
            base_from = (
                " FROM episode_entity_postings AS postings "
                "JOIN episode_semantic_meta AS meta ON meta.doc_rowid = postings.doc_rowid "
                "JOIN episode_semantic_session_state AS state ON state.session_id = postings.session_id "
                f"WHERE ({pair_clause}) AND {current_clause}"
            )
            for row in conn.execute(
                "SELECT postings.relation, COUNT(*) AS relation_count"
                + base_from
                + " AND postings.relation IN ("
                + ",".join("?" for _relation in EPISODE_ENTITY_RELATION_PRIORITY)
                + ")"
                + " GROUP BY postings.relation",
                (*pair_params, *current_params, *EPISODE_ENTITY_RELATION_PRIORITY),
            ).fetchall():
                relation_counts[str(row["relation"] or "unknown")] = int_value(row["relation_count"])
            direct_relations = sorted(EPISODE_POSTINGS_COOCCURRENCE_DIRECT_RELATIONS)
            relation_placeholders = ",".join("?" for _relation in direct_relations)
            direct_suffix = f" AND postings.relation IN ({relation_placeholders})"
            candidate_context_rows = [
                dict(row)
                for row in conn.execute(
                    "SELECT postings.doc_rowid, MIN(postings.session_id) AS session_id"
                    + base_from
                    + direct_suffix
                    + " GROUP BY postings.doc_rowid "
                    + "LIMIT ?",
                    (
                        *pair_params,
                        *current_params,
                        *direct_relations,
                        context_candidate_limit + 1,
                    ),
                ).fetchall()
            ]
            anchor_context_population_exact = len(candidate_context_rows) <= context_candidate_limit
            anchor_rows = candidate_context_rows[:context_candidate_limit]
            anchor_context_population_count = len(anchor_rows)

            rows_by_doc: dict[int, list[dict[str, Any]]] = defaultdict(list)
            docs_by_session: dict[str, set[int]] = defaultdict(set)
            for row in anchor_rows:
                doc_rowid = int_value(row.get("doc_rowid"))
                session_id = str(row.get("session_id") or "")
                if not doc_rowid or not session_id:
                    continue
                rows_by_doc[doc_rowid].append(row)
                docs_by_session[session_id].add(doc_rowid)
                selected_session_by_doc[doc_rowid] = session_id
            selection_seed = "\x00".join(
                [
                    EPISODE_POSTINGS_COOCCURRENCE_CONTEXT_SELECTION_POLICY,
                    *(f"{layer}:{key}" for layer, key in sorted(canonical_anchor_pairs)),
                ]
            )

            def selection_key(*values: Any) -> str:
                payload = "\x00".join([selection_seed, *(str(value or "") for value in values)])
                return hashlib.sha256(payload.encode("utf-8")).hexdigest()

            session_heads: list[tuple[str, int]] = []
            extra_docs: list[tuple[str, int]] = []
            for session_id, doc_rowids in docs_by_session.items():
                ordered = sorted(
                    doc_rowids,
                    key=lambda doc_rowid: (selection_key(session_id, doc_rowid), doc_rowid),
                )
                if ordered:
                    session_heads.append((session_id, ordered[0]))
                    extra_docs.extend((session_id, doc_rowid) for doc_rowid in ordered[1:])
            session_heads.sort(key=lambda item: (selection_key("session", item[0]), item[0], item[1]))
            selected_doc_rowids = [doc_rowid for _session_id, doc_rowid in session_heads[:context_limit]]
            if len(selected_doc_rowids) < context_limit:
                extra_docs.sort(
                    key=lambda item: (selection_key("extra", item[0], item[1]), item[0], item[1])
                )
                selected_doc_rowids.extend(
                    doc_rowid
                    for _session_id, doc_rowid in extra_docs[: context_limit - len(selected_doc_rowids)]
                )
            if selected_doc_rowids:
                doc_placeholders = ",".join("?" for _doc_rowid in selected_doc_rowids)
                fetched_route_rows = conn.execute(
                    "SELECT postings.* FROM episode_entity_postings AS postings "
                    f"WHERE postings.doc_rowid IN ({doc_placeholders}) "
                    f"AND postings.relation IN ({relation_placeholders}) "
                    "ORDER BY postings.doc_rowid, postings.raw_line, postings.route_layer, postings.route_key "
                    "LIMIT ?",
                    (*selected_doc_rowids, *direct_relations, route_row_limit + 1),
                ).fetchall()
                route_row_sample_truncated = len(fetched_route_rows) > route_row_limit
                route_rows = [dict(row) for row in fetched_route_rows[:route_row_limit]]
    except sqlite3.Error as exc:
        diagnostics.append(sqlite_error_diagnostic(exc))
        schema_available = False
    finally:
        if conn is not None:
            conn.close()
    if not schema_available:
        return None

    selected_doc_ids = set(selected_doc_rowids)
    selected_session_ids = {
        selected_session_by_doc.get(doc_rowid, "")
        for doc_rowid in selected_doc_ids
        if selected_session_by_doc.get(doc_rowid, "")
    }
    anchor_evidence_refs: list[dict[str, Any]] = []
    anchor_ref_docs: set[int] = set()
    for row in route_rows:
        doc_rowid = int_value(row.get("doc_rowid"))
        canonical = episode_postings_cooccurrence_route_pair(
            row.get("route_layer"),
            row.get("route_key"),
        )
        if doc_rowid in anchor_ref_docs or canonical not in canonical_anchor_pairs:
            continue
        anchor_ref_docs.add(doc_rowid)
        anchor_evidence_refs.append(episode_postings_cooccurrence_ref(row))

    accumulators: dict[tuple[str, str], dict[str, Any]] = {}
    seen_occurrences: set[tuple[int, str, str]] = set()
    for row in route_rows:
        relation = str(row.get("relation") or "")
        canonical = episode_postings_cooccurrence_route_pair(
            row.get("route_layer"),
            row.get("route_key"),
        )
        if canonical is None or canonical in canonical_anchor_pairs:
            continue
        doc_rowid = int_value(row.get("doc_rowid"))
        route_signal = route_signal_token(*canonical)
        identity = (doc_rowid, route_signal, relation)
        if identity in seen_occurrences:
            continue
        seen_occurrences.add(identity)
        accumulator = accumulators.setdefault(
            canonical,
            {
                "sessions": set(),
                "episodes": set(),
                "relations": Counter(),
                "weighted_relation_score": 0,
                "occurrence_count": 0,
                "samples": [],
            },
        )
        session_id = str(row.get("session_id") or "")
        episode_id = str(row.get("episode_id") or "")
        if session_id:
            accumulator["sessions"].add(session_id)
        accumulator["episodes"].add((session_id, episode_id, doc_rowid))
        accumulator["relations"][relation] += 1
        accumulator["weighted_relation_score"] += EPISODE_POSTINGS_COOCCURRENCE_RELATION_WEIGHTS.get(
            relation,
            1,
        )
        accumulator["occurrence_count"] += 1
        if len(accumulator["samples"]) < 5:
            sample = episode_postings_cooccurrence_ref(row)
            if sample not in accumulator["samples"]:
                accumulator["samples"].append(sample)

    ranked_pairs = sorted(
        accumulators,
        key=lambda pair: (
            -len(accumulators[pair]["sessions"]),
            -len(accumulators[pair]["episodes"]),
            -int_value(accumulators[pair]["weighted_relation_score"]),
            pair[0],
            pair[1],
        ),
    )[:selected_limit]
    candidate_cooccurrences: list[dict[str, Any]] = []
    neighbor_evidence_refs: list[dict[str, Any]] = []
    for layer, key in ranked_pairs:
        accumulator = accumulators[(layer, key)]
        samples = list(accumulator["samples"])
        neighbor_evidence_refs.extend(samples)
        node = {
            "id": graph_route_node_id(layer, key),
            "type": graph_route_node_type(layer, key),
            "label": f"{layer}:{key}",
            "route_layer": layer,
            "route_key": key,
            "route_signal": route_signal_token(layer, key),
            "relation_counts": dict(sorted(accumulator["relations"].items())),
            "evidence_refs": samples,
        }
        candidate_cooccurrences.append(
            {
                "node": graph_compact_node_for_packet(node),
                "count": int_value(accumulator["occurrence_count"]),
                "context_count": len(accumulator["episodes"]),
                "episode_count": len(accumulator["episodes"]),
                "session_count": len(accumulator["sessions"]),
                "weighted_relation_score": int_value(accumulator["weighted_relation_score"]),
                "relation_counts": dict(sorted(accumulator["relations"].items())),
                "samples": samples,
            }
        )

    evidence_refs = graph_unique_records(
        [*anchor_evidence_refs, *neighbor_evidence_refs],
        limit=evidence_ref_limit,
    )
    ref_counts = graph_ref_quality_counts(evidence_refs)
    projection_current = bool(
        str(projection.get("status") or "") == "current"
        and int_value(projection.get("indexed_session_count"))
        <= int_value(projection.get("covered_session_count"))
    )
    if not projection_current:
        abstention_status = "insufficient_projection_coverage"
    elif anchor_context_population_count <= 0:
        abstention_status = "reference_only_or_unobserved"
    elif not candidate_cooccurrences:
        abstention_status = "no_direct_relation_neighbors"
    elif not (
        ref_counts.get("has_raw_ref")
        and ref_counts.get("has_segment_ref")
        and ref_counts.get("has_session_ref")
    ):
        abstention_status = "insufficient_evidence_refs"
    else:
        abstention_status = "not_required"
    accepted = abstention_status == "not_required"
    if route_row_sample_truncated:
        diagnostics.append("episode_postings_cooccurrence_route_row_sample_truncated")
    if not anchor_context_population_exact:
        diagnostics.append("episode_postings_cooccurrence_anchor_context_candidate_truncated")
    if not accepted:
        diagnostics.append(f"episode_postings_cooccurrence_abstained:{abstention_status}")

    resolved_nodes = [
        {
            "id": graph_route_node_id(layer, key),
            "type": graph_route_node_type(layer, key),
            "route_layer": layer,
            "route_key": key,
            "route_signal": route_signal_token(layer, key),
        }
        for layer, key in sorted(canonical_anchor_pairs)
    ]
    if abstention_status == "insufficient_projection_coverage":
        evidence_route_command = memory_query_command("projection-status", aoa_root=aoa_root)
        next_route = "refresh or wait for the episode semantic classifier epoch before repeating this query"
    elif route_kind == "hook":
        evidence_route_command = (
            "python3 scripts/aoa_session_memory.py hook-receipts "
            f"--aoa-root {shlex.quote(str(aoa_root))} --event-name {shlex.quote(anchor)} --limit 20"
        )
        next_route = "use structured hook receipts before any broader mention route"
    else:
        evidence_route_command = (
            "python3 scripts/aoa_session_memory.py usage-chain "
            f"{shlex.quote(anchor)} --kind {shlex.quote(route_kind)} "
            f"--aoa-root {shlex.quote(str(aoa_root))} --limit 20"
        )
        next_route = "verify typed episode relations through usage-chain and raw evidence refs"
    repeat_command = graph_packet_command_line(
        aoa_root=aoa_root,
        command_name="graph-cooccurrence",
        anchors=[anchor],
        kind=kind,
        route_kind=route_kind,
        limit=selected_limit,
    )
    freshness = {
        "status": str(projection.get("status") or "missing"),
        "source": "episode_semantic_route_state",
        "projection": projection,
        "candidate_epoch_policy": "only current episode and classifier epoch rows are query candidates",
    }
    answer_rules = graph_answer_rules(
        evidence_refs=evidence_refs if accepted else [],
        freshness=freshness,
        min_evidence_ref_count=1,
        review_status="unreviewed",
    )
    if not accepted:
        answer_rules["status"] = abstention_status
        answer_rules["important_claim_allowed"] = False
        answer_rules["graph_rag_synthesis_allowed"] = False
        answer_rules["claim_scope"] = "blocked"
        answer_rules["required_disclaimer"] = abstention_status
    packet = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_cooccurrence",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": accepted,
        "mutates": False,
        "truth_status": "episode_postings_cooccurrence_navigation_not_reviewed_truth",
        "source": "episode_entity_postings_direct_relations",
        "cooccurrence_basis": "same_task_episode_direct_typed_relations",
        "context_selection_policy": EPISODE_POSTINGS_COOCCURRENCE_CONTEXT_SELECTION_POLICY,
        "cooccurrence_ranking_policy": EPISODE_POSTINGS_COOCCURRENCE_RANKING_POLICY,
        "anchor": anchor,
        **trace_kind_payload_fields(kind, route_kind),
        "candidate_route_signals": candidate_signals,
        "resolved": {
            "query": anchor,
            "resolver_strategy": "episode_postings_exact_route",
            "status": (
                "exact_direct_relation"
                if anchor_context_population_count
                else "reference_only"
                if relation_counts
                else "unresolved_in_current_projection"
            ),
            "start_node_ids": [node["id"] for node in resolved_nodes],
            "exact_start_node_ids": [node["id"] for node in resolved_nodes],
            "route_candidates": resolved_nodes,
        },
        "anchor_relation_counts": dict(sorted(relation_counts.items())),
        "anchor_context_count": len(selected_doc_ids),
        "anchor_context_population_count": anchor_context_population_count,
        "anchor_context_population_exact": anchor_context_population_exact,
        "anchor_context_candidate_count": len(anchor_rows),
        "anchor_context_candidate_limit": context_candidate_limit,
        "anchor_context_candidate_truncated": not anchor_context_population_exact,
        "anchor_context_session_count": len(selected_session_ids),
        "anchor_event_count": len(selected_doc_ids),
        "anchor_event_count_basis": "direct_relation_task_episodes",
        "anchor_context_sample_limit": context_limit,
        "route_row_sample_limit": route_row_limit,
        "route_row_sample_truncated": route_row_sample_truncated,
        "cooccurrence_count": len(candidate_cooccurrences) if accepted else 0,
        "cooccurrences": candidate_cooccurrences if accepted else [],
        "candidate_cooccurrence_count": len(candidate_cooccurrences),
        "candidate_cooccurrences": [] if accepted else candidate_cooccurrences,
        "evidence_ref_limit": evidence_ref_limit,
        "evidence_refs": evidence_refs,
        "freshness": freshness,
        "abstention": {
            "status": abstention_status,
            "policy": (
                "mention and action-reference rows never become cooccurrence contexts; "
                "incomplete classifier coverage never falls through to the noisy mention graph"
            ),
        },
        "quality": {
            "one_short_route": True,
            "bounded_store_query": True,
            "uses_episode_entity_postings": True,
            "uses_graph_store": False,
            "uses_mention_or_reference_relations": False,
            "direct_relations": sorted(EPISODE_POSTINGS_COOCCURRENCE_DIRECT_RELATIONS),
            "context_selection_policy": EPISODE_POSTINGS_COOCCURRENCE_CONTEXT_SELECTION_POLICY,
            "cooccurrence_ranking_policy": EPISODE_POSTINGS_COOCCURRENCE_RANKING_POLICY,
            "anchor_context_count": len(selected_doc_ids),
            "anchor_context_population_count": anchor_context_population_count,
            "anchor_context_population_exact": anchor_context_population_exact,
            "anchor_context_session_count": len(selected_session_ids),
            "cooccurrence_count": len(candidate_cooccurrences) if accepted else 0,
            "candidate_cooccurrence_count": len(candidate_cooccurrences),
            "evidence_ref_count": len(evidence_refs),
            **ref_counts,
        },
        "answer_rules": answer_rules,
        "cost_profile": {
            "source": "compact_episode_entity_postings",
            "monolith_scanned": False,
            "graph_store_opened": False,
            "context_candidate_limit": context_candidate_limit,
            "context_sample_limit": context_limit,
            "route_row_limit": route_row_limit,
        },
        "diagnostics": unique_preserving_order(diagnostics),
        "next_route": next_route,
        "next_command": repeat_command if accepted else evidence_route_command,
        "next_expansion_command": evidence_route_command,
        "next_expansion_reason": "Open the typed evidence route; do not widen into mention cooccurrence.",
        "authority_boundary": (
            "episode postings route direct relation candidates only; raw, segment, session, receipt, "
            "and owner source evidence remain stronger"
        ),
        "elapsed_ms": int((time.monotonic() - started) * 1000),
    }
    return packet


def graph_cooccurrence_from_store_aggregate(
    *,
    aoa_root: Path,
    anchor: str,
    kind: str = "auto",
    limit: int = 30,
) -> dict[str, Any] | None:
    state = graph_store_query_state(aoa_root)
    if state.get("status") != "current":
        return None
    normalized_kind = normalize_trace_route_kind(kind)
    route_kind = normalized_kind if normalized_kind in TRACE_ROUTE_KINDS else "auto"
    selected_limit = max(1, min(int_value(limit, 30), 100))
    context_limit = max(40, min(selected_limit * 16, 320))
    route_edge_limit = max(120, min(context_limit * 8, 2400))
    context_candidate_limit = max(context_limit, min(context_limit * 64, 20_000))
    aggregate_edge_types = ("segment_has_route_signal",)
    placeholders = ",".join("?" for _item in aggregate_edge_types)
    paths = graph_paths(aoa_root)
    diagnostics: list[str] = []
    try:
        conn = sqlite3.connect(str(paths["store"]))
        conn.row_factory = sqlite3.Row
        resolved = graph_store_resolve_anchor(conn, anchor, kind=route_kind, limit=max(10, selected_limit))
        start_ids = [str(node_id) for node_id in resolved.get("start_node_ids", []) if node_id]
        if not start_ids:
            conn.close()
            return None
        start_id_set = set(start_ids)
        start_placeholders = ",".join("?" for _item in start_ids)
        population_row = conn.execute(
            f"""
            SELECT COUNT(DISTINCT source_node) AS context_count
            FROM edges INDEXED BY idx_edges_target_type
            WHERE target_node IN ({start_placeholders})
              AND edge_type IN ({placeholders})
            """,
            (*start_ids, *aggregate_edge_types),
        ).fetchone()
        context_population_count = int_value(population_row["context_count"] if population_row is not None else 0)
        context_candidates: list[sqlite3.Row] = []
        seen_context_ids: set[str] = set()
        context_candidate_truncated = False
        for node_id in start_ids:
            if len(context_candidates) >= context_candidate_limit:
                context_candidate_truncated = True
                break
            remaining = max(1, context_candidate_limit - len(context_candidates))
            rows = conn.execute(
                f"""
                SELECT id, source_node, target_node, edge_type, count
                FROM edges INDEXED BY idx_edges_target_type
                WHERE target_node = ?
                  AND edge_type IN ({placeholders})
                LIMIT ?
                """,
                (node_id, *aggregate_edge_types, remaining + 1),
            ).fetchall()
            if len(rows) > remaining:
                context_candidate_truncated = True
            for row in rows:
                context_id = str(row["source_node"] or "")
                if not context_id or context_id in seen_context_ids:
                    continue
                seen_context_ids.add(context_id)
                context_candidates.append(row)
                if len(context_candidates) >= context_candidate_limit:
                    break
        if not context_candidates:
            conn.close()
            return None

        def context_session_id(context_id: str) -> str:
            parts = str(context_id or "").split(":", 2)
            return parts[1] if len(parts) == 3 and parts[0] == "segment" else str(context_id or "")

        selection_seed = "\x00".join(
            [GRAPH_COOCCURRENCE_CONTEXT_SELECTION_POLICY, *sorted(start_ids)]
        )

        def context_selection_key(*values: str) -> str:
            payload = "\x00".join([selection_seed, *(str(value or "") for value in values)])
            return hashlib.sha256(payload.encode("utf-8")).hexdigest()

        contexts_by_session: dict[str, list[sqlite3.Row]] = defaultdict(list)
        for row in context_candidates:
            context_id = str(row["source_node"] or "")
            contexts_by_session[context_session_id(context_id)].append(row)
        session_heads: list[tuple[str, sqlite3.Row]] = []
        remaining_context_rows: list[sqlite3.Row] = []
        for session_id, session_rows in contexts_by_session.items():
            ordered_rows = sorted(
                session_rows,
                key=lambda row: (
                    context_selection_key(session_id, str(row["source_node"] or "")),
                    -max(1, int_value(row["count"], 1)),
                    str(row["source_node"] or ""),
                ),
            )
            session_heads.append((session_id, ordered_rows[0]))
            remaining_context_rows.extend(ordered_rows[1:])
        session_heads.sort(key=lambda item: (context_selection_key("session", item[0]), item[0]))
        context_rows = [row for _session_id, row in session_heads[:context_limit]]
        if len(context_rows) < context_limit:
            remaining_context_rows.sort(
                key=lambda row: (
                    context_selection_key("extra", str(row["source_node"] or "")),
                    str(row["source_node"] or ""),
                )
            )
            context_rows.extend(remaining_context_rows[: context_limit - len(context_rows)])
        context_ids = [str(row["source_node"] or "") for row in context_rows if row["source_node"]]
        context_id_set = set(context_ids)
        selected_session_counts = Counter(context_session_id(context_id) for context_id in context_ids)
        selected_session_count = len(selected_session_counts)
        max_session_context_share = round(
            max(selected_session_counts.values(), default=0) / max(1, len(context_ids)),
            6,
        )
        route_counts: Counter[str] = Counter()
        route_context_counts: dict[str, Counter[str]] = defaultdict(Counter)
        route_session_ids: dict[str, set[str]] = defaultdict(set)
        samples: dict[str, list[dict[str, Any]]] = defaultdict(list)
        selected_route_edge_ids: list[str] = []
        route_edge_ids_by_route: dict[str, list[str]] = defaultdict(list)
        seen_route_edges: set[str] = set()
        per_context_edge_limit = max(1, route_edge_limit // max(1, len(context_ids)))
        route_edge_sample_truncated = False
        for context_id in context_ids:
            rows = conn.execute(
                f"""
                SELECT id, source_node, target_node, edge_type, count
                FROM edges INDEXED BY idx_edges_source_type
                WHERE source_node = ?
                  AND edge_type IN ({placeholders})
                  AND target_node NOT IN ({start_placeholders})
                ORDER BY count DESC, target_node ASC, id ASC
                LIMIT ?
                """,
                (context_id, *aggregate_edge_types, *start_ids, per_context_edge_limit + 1),
            ).fetchall()
            if len(rows) > per_context_edge_limit:
                route_edge_sample_truncated = True
            for row in rows[:per_context_edge_limit]:
                edge_id = str(row["id"])
                route_id = str(row["target_node"] or "")
                route_counts[route_id] += max(1, int_value(row["count"], 1))
                route_context_counts[route_id][context_id] += 1
                route_session_ids[route_id].add(context_session_id(context_id))
                if edge_id not in seen_route_edges and len(selected_route_edge_ids) < route_edge_limit:
                    seen_route_edges.add(edge_id)
                    selected_route_edge_ids.append(edge_id)
                    route_edge_ids_by_route[route_id].append(edge_id)
                if len(samples[route_id]) < 5:
                    samples[route_id].append(
                        {
                            "context_node_id": context_id,
                            "context_type": context_id.split(":", 1)[0] if ":" in context_id else "unknown",
                            "edge_id": edge_id,
                        }
                    )
        route_ids = sorted(
            route_counts,
            key=lambda route_id: (
                -len(route_session_ids.get(route_id, set())),
                -len(route_context_counts.get(route_id, {})),
                -int_value(route_counts.get(route_id), 0),
                route_id,
            ),
        )[:selected_limit]
        evidence_ref_limit = max(12, min(selected_limit * 2, 40))
        evidence_context_ids = context_ids[: min(len(context_ids), evidence_ref_limit)]
        context_nodes = graph_store_fetch_payloads(conn, "nodes", evidence_context_ids)
        route_nodes = graph_store_fetch_payloads(conn, "nodes", route_ids)
        edge_payload_ids = [
            *(str(row["id"]) for row in context_rows[: min(len(context_rows), evidence_ref_limit)]),
            *(
                edge_id
                for route_id in route_ids
                for edge_id in route_edge_ids_by_route.get(route_id, [])[:2]
            ),
        ]
        selected_edge_payload_ids: list[str] = []
        seen_edge_payload_ids: set[str] = set()
        for edge_id in edge_payload_ids:
            if not edge_id or edge_id in seen_edge_payload_ids:
                continue
            seen_edge_payload_ids.add(edge_id)
            selected_edge_payload_ids.append(edge_id)
            if len(selected_edge_payload_ids) >= route_edge_limit:
                break
        edge_payloads = graph_store_fetch_payloads(conn, "edges", selected_edge_payload_ids)
        conn.close()
    except sqlite3.Error:
        return None
    route_node_map = {str(node.get("id")): node for node in route_nodes if isinstance(node, dict)}
    selected: list[dict[str, Any]] = []
    for route_id in route_ids:
        count = int_value(route_counts.get(route_id), 0)
        selected.append(
            {
                "node": graph_compact_node_for_packet(route_node_map.get(route_id, {"id": route_id})),
                "count": count,
                "context_count": len(route_context_counts.get(route_id, {})),
                "session_count": len(route_session_ids.get(route_id, set())),
                "samples": samples.get(route_id, []),
            }
        )
    context_sample_truncated = context_population_count > len(context_rows)
    route_edge_sample_truncated = bool(
        route_edge_sample_truncated or len(selected_route_edge_ids) >= route_edge_limit
    )
    if context_rows and not selected:
        diagnostics.append("graph_cooccurrence_no_route_neighbors_in_aggregate_store_sample")
    if context_candidate_truncated:
        diagnostics.append("graph_cooccurrence_anchor_context_candidate_truncated")
    if context_sample_truncated:
        diagnostics.append("graph_cooccurrence_anchor_context_sample_truncated")
    if route_edge_sample_truncated:
        diagnostics.append("graph_cooccurrence_route_edge_sample_truncated")
    raw_refs = graph_cooccurrence_hydrate_raw_refs_from_segments(
        aoa_root=aoa_root,
        route_node_ids=set(start_ids) | set(route_ids),
        context_edge_payloads=edge_payloads,
        limit=evidence_ref_limit,
    )
    evidence_refs = graph_unique_records(
        [
            *raw_refs,
            *graph_collect_evidence(context_nodes, edge_payloads, limit=evidence_ref_limit),
        ],
        limit=evidence_ref_limit,
    )
    ref_counts = graph_ref_quality_counts(evidence_refs)
    if selected and not ref_counts.get("has_raw_ref"):
        diagnostics.append("graph_cooccurrence_aggregate_raw_refs_missing")
    freshness_graph = {
        "source": "sqlite_graph_store_aggregate_cooccurrence",
        "generated_at": (state.get("metadata") or {}).get("updated_at") or (state.get("metadata") or {}).get("generated_at") or utc_now(),
    }
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_cooccurrence",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": bool(selected) and ref_counts.get("has_segment_ref"),
        "mutates": False,
        "truth_status": "cooccurrence_packet_not_reviewed_truth",
        "source": "sqlite_graph_store_aggregate_cooccurrence",
        "cooccurrence_basis": "aggregate_segment_route_signal_edges_session_diversified",
        "context_selection_policy": GRAPH_COOCCURRENCE_CONTEXT_SELECTION_POLICY,
        "cooccurrence_ranking_policy": GRAPH_COOCCURRENCE_RANKING_POLICY,
        "anchor": anchor,
        **trace_kind_payload_fields(kind, route_kind),
        "resolved": resolved,
        "anchor_context_count": len(context_id_set),
        "anchor_context_population_count": context_population_count,
        "anchor_context_candidate_count": len(context_candidates),
        "anchor_context_candidate_limit": context_candidate_limit,
        "anchor_context_candidate_truncated": context_candidate_truncated,
        "anchor_context_session_count": selected_session_count,
        "anchor_context_max_session_share": max_session_context_share,
        "anchor_event_count": len(context_id_set),
        "anchor_event_count_basis": "aggregate_route_contexts",
        "anchor_context_sample_limit": context_limit,
        "anchor_context_sample_truncated": context_sample_truncated,
        "route_edge_sample_limit": route_edge_limit,
        "route_edge_per_context_limit": per_context_edge_limit,
        "route_edge_sample_truncated": route_edge_sample_truncated,
        "evidence_ref_limit": evidence_ref_limit,
        "cooccurrence_count": len(selected),
        "cooccurrences": selected,
        "evidence_refs": evidence_refs,
        "freshness": graph_freshness(aoa_root, freshness_graph),
        "quality": {
            "one_short_route": True,
            "bounded_store_query": True,
            "aggregate_route_signal_query": True,
            "uses_event_has_route_signal_edges": False,
            "uses_session_has_route_signal_edges": False,
            "context_selection_policy": GRAPH_COOCCURRENCE_CONTEXT_SELECTION_POLICY,
            "cooccurrence_ranking_policy": GRAPH_COOCCURRENCE_RANKING_POLICY,
            "anchor_context_count": len(context_id_set),
            "anchor_context_population_count": context_population_count,
            "anchor_context_candidate_count": len(context_candidates),
            "anchor_context_candidate_truncated": context_candidate_truncated,
            "anchor_context_session_count": selected_session_count,
            "anchor_context_max_session_share": max_session_context_share,
            "anchor_event_count": len(context_id_set),
            "anchor_event_count_basis": "aggregate_route_contexts",
            "cooccurrence_count": len(selected),
            "evidence_ref_count": len(evidence_refs),
            "evidence_ref_limit": evidence_ref_limit,
            "raw_ref_count": ref_counts.get("raw_ref_count"),
            "segment_ref_count": ref_counts.get("segment_ref_count"),
            "anchor_context_sample_truncated": context_sample_truncated,
            "route_edge_per_context_limit": per_context_edge_limit,
            "route_edge_sample_truncated": route_edge_sample_truncated,
        },
        "diagnostics": diagnostics,
        "next_route": (
            "verify aggregate cooccurrence claims through raw_ref, segment_ref, and session_ref before promotion"
            if selected
            else "fall back to event-level graph cooccurrence or route-rollup query when aggregate cooccurrence has no neighboring routes"
        ),
        "next_command": graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-cooccurrence",
            anchors=[anchor],
            kind=kind,
            route_kind=route_kind,
            limit=selected_limit,
        ),
        "next_expansion_command": graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-cooccurrence",
            anchors=[anchor],
            kind=kind,
            route_kind=route_kind,
            limit=graph_packet_expanded_limit(selected_limit, default=selected_limit, maximum=100),
        ),
        "next_expansion_reason": "Increase the bounded cooccurrence limit when more neighboring route signals are needed.",
        "authority_boundary": "graph cooccurrence routes relation evidence only; raw/segment refs and owner source surfaces remain stronger.",
    }


def graph_cooccurrence_from_store(
    *,
    aoa_root: Path,
    anchor: str,
    kind: str = "auto",
    limit: int = 30,
) -> dict[str, Any] | None:
    state = graph_store_query_state(aoa_root)
    if state.get("status") != "current":
        return None
    normalized_kind = normalize_trace_route_kind(kind)
    route_kind = normalized_kind if normalized_kind in TRACE_ROUTE_KINDS else "auto"
    selected_limit = max(1, min(int_value(limit, 30), 100))
    anchor_event_limit = max(40, min(selected_limit * 10, 300))
    route_edge_limit = max(120, min(anchor_event_limit * 12, 2400))
    paths = graph_paths(aoa_root)
    diagnostics: list[str] = []
    try:
        conn = sqlite3.connect(str(paths["store"]))
        conn.row_factory = sqlite3.Row
        resolved = graph_store_resolve_anchor(conn, anchor, kind=route_kind, limit=max(10, selected_limit))
        start_ids = [str(node_id) for node_id in resolved.get("start_node_ids", []) if node_id]
        if not start_ids:
            conn.close()
            return None
        anchor_events: list[str] = []
        seen_anchor_events: set[str] = set()
        for node_id in start_ids:
            if node_id.startswith("event:") and node_id not in seen_anchor_events:
                seen_anchor_events.add(node_id)
                anchor_events.append(node_id)
            if len(anchor_events) >= anchor_event_limit:
                break
            for column, opposite_column, index_name in (
                ("target_node", "source_node", "idx_edges_target"),
                ("source_node", "target_node", "idx_edges_source"),
            ):
                if len(anchor_events) >= anchor_event_limit:
                    break
                remaining = anchor_event_limit - len(anchor_events)
                rows = conn.execute(
                    f"""
                    SELECT source_node, target_node
                    FROM edges INDEXED BY {index_name}
                    WHERE {column} = ?
                      AND edge_type = 'event_has_route_signal'
                    LIMIT ?
                    """,
                    (node_id, remaining),
                ).fetchall()
                for row in rows:
                    event_id = str(row[opposite_column] or "")
                    if not event_id.startswith("event:") or event_id in seen_anchor_events:
                        continue
                    seen_anchor_events.add(event_id)
                    anchor_events.append(event_id)
                    if len(anchor_events) >= anchor_event_limit:
                        break
        route_counts: Counter[str] = Counter()
        samples: dict[str, list[dict[str, Any]]] = defaultdict(list)
        selected_edge_ids: list[str] = []
        seen_edge_ids: set[str] = set()
        start_id_set = set(start_ids)
        for offset in range(0, len(anchor_events), 80):
            if len(selected_edge_ids) >= route_edge_limit:
                break
            chunk = anchor_events[offset : offset + 80]
            if not chunk:
                continue
            placeholders = ",".join("?" for _item in chunk)
            remaining_edges = max(1, route_edge_limit - len(selected_edge_ids))
            rows = conn.execute(
                f"""
                SELECT id, source_node, target_node, count
                FROM edges INDEXED BY idx_edges_source
                WHERE source_node IN ({placeholders})
                  AND edge_type = 'event_has_route_signal'
                LIMIT ?
                """,
                (*chunk, remaining_edges),
            ).fetchall()
            for row in rows:
                edge_id = str(row["id"])
                route_id = str(row["target_node"] or "")
                event_id = str(row["source_node"] or "")
                if route_id in start_id_set:
                    continue
                route_counts[route_id] += max(1, int_value(row["count"], 1))
                if edge_id not in seen_edge_ids and len(selected_edge_ids) < route_edge_limit:
                    seen_edge_ids.add(edge_id)
                    selected_edge_ids.append(edge_id)
                if len(samples[route_id]) < 5:
                    samples[route_id].append({"event_node_id": event_id})
        route_ids = [route_id for route_id, _count in route_counts.most_common(selected_limit)]
        event_nodes = graph_store_fetch_payloads(conn, "nodes", anchor_events)
        route_nodes = graph_store_fetch_payloads(conn, "nodes", route_ids)
        edge_payloads = graph_store_fetch_payloads(conn, "edges", selected_edge_ids[: min(route_edge_limit, selected_limit * 20)])
        conn.close()
    except sqlite3.Error:
        return None
    event_node_map = {str(node.get("id")): node for node in event_nodes if isinstance(node, dict)}
    route_node_map = {str(node.get("id")): node for node in route_nodes if isinstance(node, dict)}
    selected: list[dict[str, Any]] = []
    for route_id, count in route_counts.most_common(selected_limit):
        sample_rows: list[dict[str, Any]] = []
        for sample in samples.get(route_id, []):
            event_node = event_node_map.get(str(sample.get("event_node_id") or ""), {})
            sample_rows.append(
                {
                    "event_node_id": sample.get("event_node_id"),
                    "event_title": event_node.get("title") or event_node.get("label"),
                    "session_id": event_node.get("session_id"),
                    "segment_id": event_node.get("segment_id"),
                    "event_id": event_node.get("event_id"),
                    "refs": event_node.get("refs"),
                }
            )
        selected.append(
            {
                "node": graph_compact_node_for_packet(route_node_map.get(route_id, {"id": route_id})),
                "count": count,
                "samples": sample_rows,
            }
        )
    anchor_event_sample_truncated = len(anchor_events) >= anchor_event_limit
    route_edge_sample_truncated = len(selected_edge_ids) >= route_edge_limit
    if anchor_events and not selected:
        diagnostics.append("graph_cooccurrence_no_route_neighbors_in_store_sample")
    if anchor_event_sample_truncated:
        diagnostics.append("graph_cooccurrence_anchor_event_sample_truncated")
    if route_edge_sample_truncated:
        diagnostics.append("graph_cooccurrence_route_edge_sample_truncated")
    freshness_graph = {
        "source": "sqlite_graph_store_direct_cooccurrence",
        "generated_at": (state.get("metadata") or {}).get("updated_at") or (state.get("metadata") or {}).get("generated_at") or utc_now(),
    }
    evidence_refs = graph_collect_evidence(event_nodes, edge_payloads, limit=80)
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_cooccurrence",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": bool(selected),
        "mutates": False,
        "truth_status": "cooccurrence_packet_not_reviewed_truth",
        "source": "sqlite_graph_store_direct_cooccurrence",
        "anchor": anchor,
        **trace_kind_payload_fields(kind, route_kind),
        "resolved": resolved,
        "anchor_event_count": len(anchor_events),
        "anchor_event_sample_limit": anchor_event_limit,
        "anchor_event_sample_truncated": anchor_event_sample_truncated,
        "route_edge_sample_limit": route_edge_limit,
        "route_edge_sample_truncated": route_edge_sample_truncated,
        "cooccurrence_count": len(selected),
        "cooccurrences": selected,
        "evidence_refs": evidence_refs,
        "freshness": graph_freshness(aoa_root, freshness_graph),
        "quality": {
            "one_short_route": True,
            "bounded_store_query": True,
            "anchor_event_count": len(anchor_events),
            "cooccurrence_count": len(selected),
            "evidence_ref_count": len(evidence_refs),
            "anchor_event_sample_truncated": anchor_event_sample_truncated,
            "route_edge_sample_truncated": route_edge_sample_truncated,
        },
        "diagnostics": diagnostics,
        "next_route": (
            "verify cooccurrence claims through raw_ref, segment_ref, and session_ref before promotion"
            if selected
            else "use graph-neighborhood for nearby evidence refs or increase the bounded cooccurrence route only when route cooccurrences are required"
        ),
        "next_command": graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-cooccurrence",
            anchors=[anchor],
            kind=kind,
            route_kind=route_kind,
            limit=selected_limit,
        ),
        "next_expansion_command": graph_packet_command_line(
            aoa_root=aoa_root,
            command_name="graph-cooccurrence",
            anchors=[anchor],
            kind=kind,
            route_kind=route_kind,
            limit=graph_packet_expanded_limit(selected_limit, default=selected_limit, maximum=100),
        ),
        "next_expansion_reason": "Increase the bounded cooccurrence limit when more neighboring route signals are needed.",
        "authority_boundary": "graph cooccurrence routes relation evidence only; raw/segment refs and owner source surfaces remain stronger.",
    }


def graph_cooccurrence(
    *,
    aoa_root: Path,
    anchor: str,
    kind: str = "auto",
    limit: int = 30,
) -> dict[str, Any]:
    privacy_gate = derived_text_privacy_field_gate(anchor=anchor)
    if privacy_gate["blocked"]:
        return derived_text_privacy_blocked_navigation_result(
            artifact_type="session_memory_graph_cooccurrence",
            fields=privacy_gate["fields"],
            metadata=privacy_gate["derived_text_privacy"],
            graph=True,
        )
    normalized_kind = normalize_trace_route_kind(kind)
    route_kind = normalized_kind if normalized_kind in TRACE_ROUTE_KINDS else "auto"
    episode_postings_packet = graph_cooccurrence_from_episode_postings(
        aoa_root=aoa_root,
        anchor=anchor,
        kind=kind,
        limit=limit,
    )
    if episode_postings_packet is not None:
        return episode_postings_packet
    aggregate_packet = graph_cooccurrence_from_store_aggregate(aoa_root=aoa_root, anchor=anchor, kind=kind, limit=limit)
    if aggregate_packet is not None and aggregate_packet.get("ok"):
        return aggregate_packet
    store_packet = graph_cooccurrence_from_store(aoa_root=aoa_root, anchor=anchor, kind=kind, limit=limit)
    if store_packet is not None:
        if aggregate_packet is not None:
            store_packet.setdefault("diagnostics", []).extend(
                str(item)
                for item in aggregate_packet.get("diagnostics", [])
                if item
            )
            store_packet["aggregate_cooccurrence_fallback_status"] = aggregate_packet.get("ok")
        return store_packet
    packet = graph_neighborhood(aoa_root=aoa_root, anchor=anchor, kind=route_kind, depth=1, limit=max(limit * 6, 60))
    return graph_cooccurrence_from_packet(
        aoa_root=aoa_root,
        packet=packet,
        anchor=anchor,
        kind=kind,
        limit=limit,
        source="bounded_cooccurrence_neighborhood",
    )


def refs_from_search_hits(hits: list[dict[str, Any]], *, limit: int = 60) -> list[dict[str, Any]]:
    refs: list[dict[str, Any]] = []
    for hit in hits:
        if not isinstance(hit, dict):
            continue
        hit_refs = hit.get("refs") if isinstance(hit.get("refs"), dict) else {}
        refs.append(
            {
                "doc_id": hit.get("doc_id"),
                "session_id": hit.get("session_id"),
                "segment_id": hit.get("segment_id"),
                "event_id": hit.get("event_id"),
                "refs": hit_refs,
                "freshness": hit.get("freshness"),
            }
        )
    return graph_unique_records(refs, limit=limit)


def graph_lexical_seed(
    *,
    aoa_root: Path,
    query: str,
    kind: str,
    limit: int,
    neighborhood: dict[str, Any] | None = None,
    include_semantic_context: bool = False,
    rerank_local: bool = False,
) -> dict[str, Any]:
    """Choose the cheapest specific text lane needed to seed graph retrieval.

    Exact structured identifiers use the exact-output posting projection.
    A resolved typed graph anchor already supplies evidence-bearing seeds, so
    repeating a payload-wide FTS scan adds cost and semantic noise without
    increasing the bounded graph scope. Natural-language and unresolved
    anchors retain the lexical fallback.
    """
    text = str(query or "").strip()
    normalized_kind = normalize_trace_route_kind(kind)
    route_kind = (
        normalized_kind
        if normalized_kind in TRACE_ROUTE_KINDS
        else "auto"
    )
    structured_identifier = literal_query_identifier_anchor(text)
    if (
        structured_identifier
        and LITERAL_QUERY_STRUCTURED_IDENTIFIER_RE.fullmatch(
            structured_identifier
        )
        is not None
    ):
        payload = search_sessions(
            aoa_root=aoa_root,
            query=structured_identifier,
            limit=limit,
            doc_type="event",
            explain=True,
            semantic_preview=False,
            hydrate_body=False,
            raw_ref_preview=False,
            literal_postings_only=True,
            include_archived_raw_fallback=False,
        )
        payload["graph_seed_route"] = "exact_literal_postings"
        return payload

    graph_packet = neighborhood if isinstance(neighborhood, dict) else {}
    graph_refs = (
        graph_packet.get("evidence_refs", [])
        if isinstance(graph_packet.get("evidence_refs"), list)
        else []
    )
    resolved = (
        graph_packet.get("resolved")
        if isinstance(graph_packet.get("resolved"), dict)
        else {}
    )
    if (
        route_kind != "auto"
        and graph_refs
        and isinstance(resolved.get("start_node_ids"), list)
        and resolved.get("start_node_ids")
    ):
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "search_results",
            "search_schema_version": SEARCH_SCHEMA_VERSION,
            "generated_at": utc_now(),
            "ok": True,
            "mutates": False,
            "truth_status": (
                "typed_graph_seed_satisfied_no_payload_wide_text_scan"
            ),
            "query": text,
            "normalized_query": "",
            "result_count": 0,
            "results": [],
            "graph_seed_route": "typed_graph_anchor",
            "route_selection": {
                "first_route": "typed_graph_anchor",
                "selected_route": "typed_graph_anchor",
                "fallback_reason": "",
                "semantic_or_lexical_expansion_used": False,
            },
            "cost_profile": {
                "uses_fts": False,
                "bounded": True,
            },
            "diagnostics": [
                "graph_lexical_seed_skipped_specific_graph_anchor"
            ],
        }

    payload = search_sessions(
        aoa_root=aoa_root,
        query=text,
        limit=limit,
        include_semantic_context=include_semantic_context,
        rerank_local=rerank_local,
        explain=True,
    )
    payload["graph_seed_route"] = "portable_lexical_search"
    return payload


def graph_rag_packet(
    *,
    aoa_root: Path,
    query: str,
    anchor: str = "",
    kind: str = "auto",
    mode: str = "hybrid",
    limit: int = 8,
    include_semantic_context: bool = False,
    rerank_local: bool = False,
) -> dict[str, Any]:
    privacy_gate = derived_text_privacy_field_gate(
        query=query,
        anchor=anchor,
    )
    if privacy_gate["blocked"]:
        return derived_text_privacy_blocked_navigation_result(
            artifact_type="session_memory_graphrag_packet",
            fields=privacy_gate["fields"],
            metadata=privacy_gate["derived_text_privacy"],
            graph=True,
        )
    text = str(query or anchor or "").strip()
    if not text:
        normalized_kind = normalize_trace_route_kind(kind)
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "session_memory_graphrag_packet",
            "graph_schema_version": GRAPH_SCHEMA_VERSION,
            "generated_at": utc_now(),
            "ok": False,
            "query": query,
            **trace_kind_payload_fields(kind, normalized_kind if normalized_kind in TRACE_ROUTE_KINDS else "auto"),
            "diagnostics": ["query or anchor is required"],
        }
    limit = max(1, min(int_value(limit, 8), 50))
    anchor_text = str(anchor or text)
    normalized_kind = normalize_trace_route_kind(kind)
    route_kind = normalized_kind if normalized_kind in TRACE_ROUTE_KINDS else "auto"
    neighborhood = graph_neighborhood(aoa_root=aoa_root, anchor=anchor_text, kind=route_kind, depth=2, limit=max(limit * 8, 40))
    lexical = graph_lexical_seed(
        aoa_root=aoa_root,
        query=text,
        kind=route_kind,
        limit=limit,
        neighborhood=neighborhood,
        include_semantic_context=include_semantic_context,
        rerank_local=rerank_local,
    )
    cooccurrence = graph_cooccurrence_from_packet(
        aoa_root=aoa_root,
        packet=neighborhood,
        anchor=anchor_text,
        kind=route_kind,
        limit=min(limit * 4, 40),
        source="shared_graphrag_neighborhood",
    )
    search_hits = lexical.get("results", []) if isinstance(lexical.get("results"), list) else []
    lexical_refs = refs_from_search_hits(search_hits, limit=limit * 4)
    graph_refs = neighborhood.get("evidence_refs", []) if isinstance(neighborhood.get("evidence_refs"), list) else []
    cooccurring_routes = [
        item
        for item in cooccurrence.get("cooccurrences", [])[: max(1, min(limit, 20))]
        if isinstance(item, dict)
    ]
    evidence_refs = graph_unique_records([*lexical_refs, *graph_refs], limit=max(30, limit * 8))
    packet = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graphrag_packet",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": bool(search_hits or graph_refs),
        "mutates": False,
        "truth_status": "rag_graphrag_evidence_packet_not_reviewed_truth",
        "query": text,
        "anchor": anchor_text,
        **trace_kind_payload_fields(kind, route_kind),
        "mode": mode,
        "retrieval_modes": {
            "lexical": lexical.get(
                "graph_seed_route",
                "portable_lexical_search",
            ),
            "vector": "optional_semantic_overlay" if include_semantic_context else "not_requested",
            "rerank": "optional_local_rerank" if rerank_local else "not_requested",
            "graph": "route_signal_sidecar_or_ephemeral_graph",
            "graphrag": "lexical_entrypoints_plus_graph_expansion_plus_cooccurrence_packet",
        },
        "lexical": {
            "ok": lexical.get("ok"),
            "result_count": lexical.get("result_count"),
            "provider": lexical.get("provider"),
            "results": search_hits[:limit],
        },
        "graph": {
            "ok": neighborhood.get("ok"),
            "source": neighborhood.get("graph", {}).get("source") if isinstance(neighborhood.get("graph"), dict) else None,
            "node_count": neighborhood.get("node_count"),
            "edge_count": neighborhood.get("edge_count"),
            "resolved": neighborhood.get("resolved"),
            "nodes": neighborhood.get("nodes", [])[: max(limit * 3, 12)],
            "edges": neighborhood.get("edges", [])[: max(limit * 3, 12)],
        },
        "communities": {
            "method": "route_signal_cooccurrence",
            "source": cooccurrence.get("source"),
            "items": cooccurring_routes,
        },
        "evidence_refs": evidence_refs,
        "freshness": {
            "search": {
                "index_generated_at": lexical.get("index_generated_at"),
                "provider_status": lexical.get("provider", {}).get("status") if isinstance(lexical.get("provider"), dict) else None,
            },
            "graph": neighborhood.get("freshness"),
        },
        "diagnostics": [
            *(lexical.get("diagnostics", []) if isinstance(lexical.get("diagnostics"), list) else []),
            *(neighborhood.get("diagnostics", []) if isinstance(neighborhood.get("diagnostics"), list) else []),
        ],
        "stop_line": "GraphRAG may rank routes and gather refs, but it does not promote claims without raw/segment/session evidence review.",
    }
    packet["answer_rules"] = graph_answer_rules(
        evidence_refs=evidence_refs,
        freshness=packet.get("freshness") if isinstance(packet.get("freshness"), dict) else {},
        min_evidence_ref_count=1,
        review_status="unreviewed",
    )
    if not packet["answer_rules"].get("graph_rag_synthesis_allowed"):
        packet["diagnostics"].append(f"answer_rule_gate:{packet['answer_rules'].get('status')}")
    packet["evidence_envelope"] = session_memory_evidence_envelope(
        aoa_root=aoa_root,
        query=text,
        payload=packet,
        route_id="bounded_graphrag",
        route_reason=(
            "lexical seed plus bounded graph neighborhood and cooccurrence "
            "expansion"
        ),
        route_authority="generated_graph_and_search_navigation_only",
        answer_admission=packet.get("answer_rules"),
        next_route={
            "kind": "bounded_raw_evidence_read",
            "status": "ready" if evidence_refs else "unresolved",
            "evidence_refs": evidence_refs[:8],
            "mutates": False,
        },
        budgets={
            "result_limit": limit,
            "graph_node_limit": max(limit * 8, 40),
            "evidence_ref_limit": max(30, limit * 8),
            "bounded": True,
        },
    )
    return packet


def graph_explain_packet(
    *,
    aoa_root: Path,
    intent: str,
    anchor: str = "",
    query: str = "",
    kind: str = "auto",
    limit: int = 8,
) -> dict[str, Any]:
    privacy_gate = derived_text_privacy_field_gate(
        intent=intent,
        anchor=anchor,
        query=query,
    )
    if privacy_gate["blocked"]:
        return derived_text_privacy_blocked_navigation_result(
            artifact_type="session_memory_graph_explain_packet",
            fields=privacy_gate["fields"],
            metadata=privacy_gate["derived_text_privacy"],
            graph=True,
        )
    intent_text = str(intent or query or anchor or "").strip()
    normalized_kind = normalize_trace_route_kind(kind)
    route_kind = normalized_kind if normalized_kind in TRACE_ROUTE_KINDS else "auto"
    packet = graph_rag_packet(
        aoa_root=aoa_root,
        query=query or intent_text,
        anchor=anchor or intent_text,
        kind=route_kind,
        mode="explain",
        limit=limit,
    )
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_explain_packet",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "ok": bool(packet.get("ok")),
        "mutates": False,
        "truth_status": "graph_explain_packet_not_reviewed_truth",
        "intent": intent_text,
        "anchor": anchor or intent_text,
        "query": query or intent_text,
        **trace_kind_payload_fields(kind, route_kind),
        "explanation": {
            "entrypoints": "portable lexical search plus route-candidate graph expansion",
            "graph_expansion": (
                "bounded trace/search hits are converted into event, route-signal, session, and segment nodes; "
                "raw refs stay in event evidence refs"
            ),
            "community_signal": "cooccurrence is route-signal co-presence around evidence events",
            "freshness": "search provider and graph packet freshness are routing checks, not authority",
            "authority": "raw/segment/session refs remain stronger than packet summaries",
        },
        "packet": packet,
        "evidence_refs": packet.get("evidence_refs", []),
        "answer_rules": packet.get("answer_rules"),
        "stop_line": "Use this explanation to choose evidence to read, not as reviewed truth.",
    }


