GRAPH_QUALITY_FRESH_STATUSES = {"graph_store_current", "scope_current"}


def _graph_eval_body(
    *,
    aoa_root: Path,
    limit: int = 6,
    include_semantic_context: bool = False,
    rerank_local: bool = False,
) -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    for question in GRAPH_EVAL_QUESTIONS:
        query = str(question["query"])
        anchor = str(question["anchor"])
        kind = str(question.get("kind") or "auto")
        lexical = search_sessions(aoa_root=aoa_root, query=query, limit=limit, explain=True)
        graph_only = graph_neighborhood(aoa_root=aoa_root, anchor=anchor, kind=kind, depth=2, limit=max(limit * 6, 30))
        graphrag = graph_rag_packet(
            aoa_root=aoa_root,
            query=query,
            anchor=anchor,
            kind=kind,
            mode="eval",
            limit=limit,
            include_semantic_context=include_semantic_context,
            rerank_local=rerank_local,
        )
        vector_status = "not_requested"
        vector_count = 0
        if include_semantic_context:
            semantic = search_sessions(aoa_root=aoa_root, query=query, limit=limit, include_semantic_context=True, explain=True)
            provider = semantic.get("provider") if isinstance(semantic.get("provider"), dict) else {}
            overlay = provider.get("semantic_overlay") if isinstance(provider.get("semantic_overlay"), dict) else {}
            vector_status = str(overlay.get("status") or ("available" if overlay.get("ok") else "unavailable"))
            vector_count = int_value(overlay.get("result_count"), 0)
        lexical_hits = lexical.get("results", []) if isinstance(lexical.get("results"), list) else []
        graph_refs = graph_only.get("evidence_refs", []) if isinstance(graph_only.get("evidence_refs"), list) else []
        graphrag_refs = graphrag.get("evidence_refs", []) if isinstance(graphrag.get("evidence_refs"), list) else []
        results.append(
            {
                "id": question["id"],
                "query": query,
                "anchor": anchor,
                "kind": kind,
                "lexical_only": {"ok": lexical.get("ok"), "hit_count": len(lexical_hits), "has_refs": bool(refs_from_search_hits(lexical_hits, limit=limit))},
                "vector_only": {"status": vector_status, "hit_count": vector_count},
                "graph_only": {"ok": graph_only.get("ok"), "evidence_ref_count": len(graph_refs), "node_count": graph_only.get("node_count")},
                "hybrid": {
                    "evidence_ref_count": len(graph_unique_records([*refs_from_search_hits(lexical_hits), *graph_refs], limit=100)),
                    "has_raw_or_segment_refs": any(
                        isinstance(item, dict)
                        and isinstance(item.get("refs"), dict)
                        and (item["refs"].get("raw") or item["refs"].get("segment"))
                        for item in [*refs_from_search_hits(lexical_hits), *graph_refs]
                    ),
                },
                "graphrag": {"ok": graphrag.get("ok"), "evidence_ref_count": len(graphrag_refs), "mode": graphrag.get("mode")},
            }
        )
    generated_at = utc_now()
    eval_freshness = graph_freshness(
        aoa_root,
        {
            "source": "bounded_graph_eval_summary",
            "generated_at": generated_at,
            "nodes": [],
            "edges": [],
        },
    )
    eval_freshness.update(
        {
            "search_index_generated_at": search_index_generated_at(
                aoa_root
            ),
            "law": (
                "an evaluation execution timestamp proves neither returned "
                "source freshness nor global graph recall"
            ),
        }
    )
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_eval",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": generated_at,
        "ok": any(item["hybrid"]["evidence_ref_count"] for item in results),
        "mutates": False,
        "truth_status": "retrieval_quality_probe_not_reviewed_truth",
        "question_count": len(results),
        "results": results,
        "freshness": eval_freshness,
        "note": "Evaluation compares retrieval surfaces on known debug anchors; vector-only is optional and may report not_requested/unavailable.",
    }


def generation_pinned_evaluation(
    *,
    aoa_root: Path,
    evaluator: Callable[[], dict[str, Any]],
    artifact_type: str,
    sessions: Sequence[str] | None = None,
    owner_job: str = "generation-pinned-evaluation",
) -> dict[str, Any]:
    """Run one read-only evaluation under a lease and reject any drift."""

    def evaluate_under_lease() -> dict[str, Any]:
        before = evaluation_generation_settled_snapshot(
            aoa_root=aoa_root,
            sessions=sessions,
        )
        if not before.get("ok"):
            incompatible_generation = bool(
                str(before.get("status") or "")
                == "incompatible_generation"
            )
            return {
                "schema_version": SCHEMA_VERSION,
                "artifact_type": artifact_type,
                "generated_at": utc_now(),
                "ok": False,
                "status": (
                    "refused_incompatible_generation_snapshot"
                    if incompatible_generation
                    else "refused_incomplete_generation_snapshot"
                ),
                "mutates": False,
                "truth_status": (
                    "evaluation_refused_before_candidate_generation"
                ),
                "results": [],
                "generation_pin": {
                    "schema_version": (
                        EVALUATION_GENERATION_PIN_COMPARISON_SCHEMA_VERSION
                    ),
                    "status": (
                        "refused_incompatible_generation_snapshot"
                        if incompatible_generation
                        else "refused_incomplete_generation_snapshot"
                    ),
                    "answer_or_score_admissible": False,
                    "before": evaluation_generation_snapshot_summary(
                        before
                    ),
                    "reasons": [
                        "incompatible_projection_generation"
                        if incompatible_generation
                        else "before_snapshot_incomplete"
                    ],
                },
            }
        evaluation = evaluator()
        after = evaluation_generation_settled_snapshot(
            aoa_root=aoa_root,
            sessions=sessions,
        )
        comparison = evaluation_generation_compare(before, after)
        stable = bool(comparison.get("ok"))
        evaluation_ok = bool(evaluation.get("ok"))
        evaluation["generation_pin"] = comparison
        evaluation["evaluation_result_admissible"] = bool(
            stable and evaluation_ok
        )
        if not stable:
            evaluation["ok"] = False
            evaluation["status"] = str(
                comparison.get("status")
                or "invalidated_generation_drift"
            )
            evaluation["truth_status"] = (
                "evaluation_candidates_invalidated_not_scored"
            )
            evaluation["diagnostics"] = unique_preserving_order(
                [
                    *(
                        evaluation.get("diagnostics", [])
                        if isinstance(evaluation.get("diagnostics"), list)
                        else []
                    ),
                    *(
                        comparison.get("reasons", [])
                        if isinstance(comparison.get("reasons"), list)
                        else []
                    ),
                ]
            )
        else:
            evaluation["status"] = (
                "completed_generation_stable"
                if evaluation_ok
                else str(evaluation.get("status") or "evaluation_failed")
            )
        return evaluation

    locked = run_with_maintenance_lock(
        aoa_root,
        evaluate_under_lease,
        owner_job=owner_job,
        mode="evaluation-read",
        target=(
            ",".join(str(item) for item in sessions)
            if sessions
            else "all"
        ),
        reason="prevent_projection_publication_during_generation_pinned_eval",
        touched_surfaces=[],
        lock_timeout_sec=0.0,
    )
    if locked.get("artifact_type") == (
        "session_memory_maintenance_lock_conflict"
    ):
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": artifact_type,
            "generated_at": utc_now(),
            "ok": False,
            "status": "refused_active_projection_writer",
            "mutates": False,
            "truth_status": "evaluation_refused_before_candidate_generation",
            "results": [],
            "evaluation_result_admissible": False,
            "generation_pin": {
                "schema_version": (
                    EVALUATION_GENERATION_PIN_COMPARISON_SCHEMA_VERSION
                ),
                "status": "refused_active_projection_writer",
                "answer_or_score_admissible": False,
                "reasons": ["maintenance_lease_conflict"],
            },
            "maintenance_conflict": locked,
        }
    return locked


def graph_eval(
    *,
    aoa_root: Path,
    limit: int = 6,
    include_semantic_context: bool = False,
    rerank_local: bool = False,
    sessions: Sequence[str] | None = None,
) -> dict[str, Any]:
    return generation_pinned_evaluation(
        aoa_root=aoa_root,
        sessions=sessions,
        artifact_type="session_memory_graph_eval",
        owner_job="graph-eval-generation-pin",
        evaluator=lambda: _graph_eval_body(
            aoa_root=aoa_root,
            limit=limit,
            include_semantic_context=include_semantic_context,
            rerank_local=rerank_local,
        ),
    )


def parse_graph_quality_anchor(value: str) -> dict[str, str]:
    text = str(value or "").strip()
    if not text:
        return {}
    parts = text.split(":", 2)
    if len(parts) == 3 and normalize_trace_route_kind(parts[1]) in TRACE_ROUTE_KINDS:
        anchor_id, raw_kind, anchor = parts
        kind = normalize_trace_route_kind(raw_kind)
    elif len(parts) == 2 and normalize_trace_route_kind(parts[0]) in TRACE_ROUTE_KINDS:
        raw_kind, anchor = parts
        kind = normalize_trace_route_kind(raw_kind)
        anchor_id = readable_slug(anchor, fallback=kind, max_chars=80)
    else:
        anchor_id = readable_slug(text, fallback="anchor", max_chars=80)
        kind = "auto"
        anchor = text
    return {
        "id": route_key_slug(anchor_id, fallback="anchor", max_chars=80),
        "anchor": anchor.strip(),
        "kind": kind,
        "role": kind,
    }


def graph_quality_anchor_items(anchors: list[Any] | None = None) -> list[dict[str, str]]:
    if not anchors:
        return [dict(item) for item in GRAPH_QUALITY_SAMPLE_ANCHORS]
    items: list[dict[str, str]] = []
    for item in anchors:
        if isinstance(item, dict):
            anchor = str(item.get("anchor") or item.get("query") or "").strip()
            if not anchor:
                continue
            kind = normalize_trace_route_kind(str(item.get("kind") or "auto"))
            route_kind = kind if kind in TRACE_ROUTE_KINDS else "auto"
            role = normalize_trace_route_kind(str(item.get("role") or kind or "auto"))
            route_role = role if role in TRACE_ROUTE_KINDS else route_kind
            anchor_id = str(item.get("id") or readable_slug(anchor, fallback=kind, max_chars=80))
            items.append(
                {
                    "id": route_key_slug(anchor_id, fallback="anchor", max_chars=80),
                    "anchor": anchor,
                    "kind": route_kind,
                    "role": route_role,
                }
            )
            continue
        parsed = parse_graph_quality_anchor(str(item))
        if parsed:
            items.append(parsed)
    deduped: list[dict[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for item in items:
        token = (str(item.get("kind") or ""), str(item.get("anchor") or ""))
        if token in seen:
            continue
        seen.add(token)
        deduped.append(item)
    return deduped


def graph_ref_values(ref: Any) -> dict[str, str]:
    if not isinstance(ref, dict):
        return {}
    values: dict[str, str] = {}
    nested = ref.get("refs") if isinstance(ref.get("refs"), dict) else {}
    for key in ("session", "session_index", "segment", "segment_index", "raw", "raw_block"):
        value = nested.get(key) if nested else ref.get(key)
        if value:
            values[key] = str(value)
    for key in ("session_id", "segment_id", "event_id", "doc_id"):
        if ref.get(key):
            values[key] = str(ref.get(key))
    return values


def graph_ref_quality_counts(evidence_refs: list[Any]) -> dict[str, Any]:
    counts = Counter()
    for ref in evidence_refs:
        values = graph_ref_values(ref)
        if values.get("raw"):
            counts["raw"] += 1
        if values.get("segment"):
            counts["segment"] += 1
        if values.get("session"):
            counts["session"] += 1
        if values.get("segment_index"):
            counts["segment_index"] += 1
    return {
        "raw_ref_count": counts["raw"],
        "segment_ref_count": counts["segment"],
        "session_ref_count": counts["session"],
        "segment_index_ref_count": counts["segment_index"],
        "has_raw_ref": counts["raw"] > 0,
        "has_segment_ref": counts["segment"] > 0,
        "has_session_ref": counts["session"] > 0,
    }


def graph_freshness_status_values(value: Any) -> list[str]:
    statuses: list[str] = []
    if isinstance(value, dict):
        status = value.get("status")
        if status:
            statuses.append(str(status))
        for nested in value.values():
            statuses.extend(graph_freshness_status_values(nested))
    elif isinstance(value, list):
        for item in value:
            statuses.extend(graph_freshness_status_values(item))
    return [status for status in dict.fromkeys(statuses) if status]


def graph_answer_rules(
    *,
    evidence_refs: list[Any],
    freshness: dict[str, Any] | None = None,
    min_evidence_ref_count: int = 1,
    review_status: str = "unreviewed",
) -> dict[str, Any]:
    ref_counts = graph_ref_quality_counts(evidence_refs)
    freshness_statuses = graph_freshness_status_values(freshness or {})
    ref_freshness_statuses = graph_freshness_status_values(evidence_refs)
    all_freshness_statuses = [*freshness_statuses, *ref_freshness_statuses]
    flags: list[str] = []
    if int_value(ref_counts.get("raw_ref_count")) <= 0:
        flags.append("missing_raw_ref")
    if int_value(ref_counts.get("segment_ref_count")) <= 0:
        flags.append("missing_segment_ref")
    if int_value(ref_counts.get("session_ref_count")) <= 0:
        flags.append("missing_session_ref")
    if int_value(ref_counts.get("raw_ref_count")) + int_value(ref_counts.get("segment_ref_count")) + int_value(ref_counts.get("session_ref_count")) == 0:
        flags.append("no_evidence_refs")
    if len(evidence_refs) < max(1, int_value(min_evidence_ref_count, 1)):
        flags.append("below_min_evidence_ref_count")
    if any("stale" in status or status in {"unverifiable", "missing", "sqlite_error"} for status in all_freshness_statuses):
        flags.append("stale_or_unverifiable")

    if "no_evidence_refs" in flags:
        status = "insufficient_evidence"
        important_claim_allowed = False
    elif "stale_or_unverifiable" in flags:
        status = "stale"
        important_claim_allowed = False
    elif any(flag in flags for flag in {"missing_raw_ref", "missing_segment_ref", "missing_session_ref", "below_min_evidence_ref_count"}):
        status = "weak_route"
        important_claim_allowed = False
    else:
        status = "needs_review" if review_status not in {"reviewed", "accepted", "accept"} else "evidence_ready"
        important_claim_allowed = status == "evidence_ready"

    return {
        "status": status,
        "important_claim_allowed": important_claim_allowed,
        "graph_rag_synthesis_allowed": important_claim_allowed,
        "claim_scope": "route_evidence_only_until_reviewed" if status == "needs_review" else ("evidence_backed" if status == "evidence_ready" else "blocked"),
        "required_disclaimer": "" if important_claim_allowed else status,
        "flags": flags,
        "freshness_statuses": all_freshness_statuses,
        "requirements": {
            "has_raw_ref": True,
            "has_segment_ref": True,
            "has_session_ref": True,
            "min_evidence_ref_count": max(1, int_value(min_evidence_ref_count, 1)),
        },
        "observed": {
            "evidence_ref_count": len(evidence_refs),
            **ref_counts,
        },
        "law": (
            "GraphRAG-style answers must not make important claims without "
            "raw, segment, and session evidence refs plus an explicit "
            "accepted review/admission state."
        ),
    }


def graph_ref_raw_preview(
    ref: Any,
    *,
    aoa_root: Path,
    max_chars: int = 360,
) -> dict[str, Any]:
    values = graph_ref_values(ref)
    raw_ref = values.get("raw", "")
    manifest_ref = values.get("session", "")
    if not raw_ref:
        return {"status": "missing_raw_ref", "line": None, "text": ""}
    if not manifest_ref:
        return {"status": "missing_session_manifest_ref", "line": line_from_raw_ref(raw_ref), "text": ""}
    manifest_path = Path(manifest_ref)
    if not manifest_path.is_absolute():
        manifest_path = aoa_root / manifest_path
    manifest = read_json(manifest_path, {})
    if not isinstance(manifest, dict) or not manifest:
        return {"status": "session_manifest_unavailable", "line": line_from_raw_ref(raw_ref), "text": ""}
    preview = raw_semantic_preview(
        manifest_raw_path(manifest_path.parent, manifest),
        raw_ref,
        max_chars=max_chars,
    )
    preview_status = str(preview.get("status") or "")
    if preview_status in {
        "raw_semantic_text",
        "raw_semantic_text_redacted",
        "encrypted_reasoning_boundary",
    }:
        preview = dict(preview)
        preview["status"] = "available"
        preview["representation"] = "derived_semantic_projection"
        preview["representation_status"] = preview_status
    return preview


def graph_quality_sample_ref(
    ref: Any,
    *,
    aoa_root: Path,
) -> dict[str, Any]:
    values = graph_ref_values(ref)
    return {
        "ref": ref,
        "has_raw_ref": bool(values.get("raw")),
        "has_segment_ref": bool(values.get("segment")),
        "has_session_ref": bool(values.get("session")),
        "raw_preview": (
            graph_ref_raw_preview(ref, aoa_root=aoa_root)
            if values.get("raw")
            else {
                "status": "missing_raw_ref",
                "line": None,
                "text": "",
            }
        ),
    }


def graph_quality_sample_refs(
    evidence_refs: list[Any],
    *,
    aoa_root: Path,
    limit: int,
) -> list[dict[str, Any]]:
    def rank(ref: Any) -> tuple[int, int, int]:
        values = graph_ref_values(ref)
        return (
            0 if values.get("raw") else 1,
            0 if values.get("segment") else 1,
            0 if values.get("session") else 1,
        )

    ordered = sorted(evidence_refs, key=rank)
    bounded_limit = max(1, limit)
    selected = [
        graph_quality_sample_ref(ref, aoa_root=aoa_root)
        for ref in ordered[:bounded_limit]
    ]

    def has_readable_semantic_preview(
        sample: dict[str, Any],
    ) -> bool:
        preview = (
            sample.get("raw_preview")
            if isinstance(sample.get("raw_preview"), dict)
            else {}
        )
        return bool(
            preview.get("status") == "available"
            and preview.get("representation_status")
            in {
                "raw_semantic_text",
                "raw_semantic_text_redacted",
            }
        )

    if any(has_readable_semantic_preview(sample) for sample in selected):
        return selected
    # Completeness ranking is stable and deliberately has no path/JSON
    # tie-break. If the first equally complete refs are structural-only,
    # retain that stable order but replace the final sample with the first
    # source-readable semantic ref so a manual quality audit is reviewable.
    for ref in ordered[bounded_limit:]:
        sample = graph_quality_sample_ref(ref, aoa_root=aoa_root)
        if not has_readable_semantic_preview(sample):
            continue
        if selected:
            selected[-1] = sample
        else:
            selected.append(sample)
        break
    return selected


def graph_quality_route_nodes(nodes: list[dict[str, Any]], *, limit: int = 12) -> list[dict[str, Any]]:
    selected: list[dict[str, Any]] = []
    for node in nodes:
        if not isinstance(node, dict):
            continue
        if str(node.get("type") or "") not in {"entity", "skill", "mcp", "hook", "tool", "agent", "path", "goal", "failure", "decision", "route_signal"}:
            continue
        selected.append(
            {
                "id": node.get("id"),
                "type": node.get("type"),
                "label": node.get("label"),
                "route_layer": node.get("route_layer"),
                "route_key": node.get("route_key"),
                "route_signal": node.get("route_signal"),
            }
        )
        if len(selected) >= limit:
            break
    return selected


GRAPH_QUALITY_INFORMATIONAL_DIAGNOSTICS = frozenset(
    {
        "graph_lexical_seed_skipped_specific_graph_anchor",
        "graph_store_unindexed_payload_scan_skipped",
        "structured_correlation_source_admission_applied",
        "graph_store_exact_miss_used_bounded_retrieval_seed",
        "typed_anchor_fuzzy_candidates_not_promoted",
        "segment_index_ref_derived_by_segment_id",
    }
)

GRAPH_QUALITY_INFORMATIONAL_DIAGNOSTIC_PREFIXES = (
    "exact_literal_postings_adjacent_message_mirror_deduplicated:",
)


def graph_quality_diagnostic_finding(
    diagnostic: Any,
) -> dict[str, str]:
    code = str(diagnostic or "").strip()
    if (
        code in GRAPH_QUALITY_INFORMATIONAL_DIAGNOSTICS
        or any(
            code.startswith(prefix)
            for prefix in GRAPH_QUALITY_INFORMATIONAL_DIAGNOSTIC_PREFIXES
        )
        or code.startswith("answer_rule_gate:")
    ):
        return {
            "code": code,
            "severity": "informational",
            "category": (
                "protective_answer_gate"
                if code.startswith("answer_rule_gate:")
                else "expected_bounded_route_posture"
            ),
        }
    return {
        "code": code,
        "severity": "critical",
        "category": "unexpected_retrieval_or_projection_diagnostic",
    }


def graph_quality_audit(
    *,
    aoa_root: Path,
    anchors: list[Any] | None = None,
    limit: int = 8,
    sample_ref_limit: int = 3,
    full_graphrag: bool = False,
    write_report: bool = False,
) -> dict[str, Any]:
    now = utc_now()
    anchor_items = graph_quality_anchor_items(anchors)
    limit = max(1, min(int_value(limit, 8), 50))
    sample_ref_limit = max(1, min(int_value(sample_ref_limit, 3), 12))
    samples: list[dict[str, Any]] = []
    diagnostics: list[str] = []
    status_counts: Counter[str] = Counter()

    for anchor_item in anchor_items:
        anchor = str(anchor_item.get("anchor") or "")
        kind = str(anchor_item.get("kind") or "auto")
        neighborhood = graph_neighborhood(
            aoa_root=aoa_root,
            anchor=anchor,
            kind=kind,
            depth=2,
            limit=max(limit * 6, 30),
        )
        lexical = graph_lexical_seed(
            aoa_root=aoa_root,
            query=anchor,
            kind=kind,
            limit=limit,
            neighborhood=neighborhood,
        )
        graphrag = (
            graph_rag_packet(
                aoa_root=aoa_root,
                query=anchor,
                anchor=anchor,
                kind=kind,
                mode="quality_audit",
                limit=limit,
            )
            if full_graphrag
            else {}
        )
        neighborhood_refs = neighborhood.get("evidence_refs", []) if isinstance(neighborhood.get("evidence_refs"), list) else []
        lexical_hits = lexical.get("results", []) if isinstance(lexical.get("results"), list) else []
        lexical_refs = refs_from_search_hits(lexical_hits, limit=limit * 4)
        graphrag_refs = graphrag.get("evidence_refs", []) if isinstance(graphrag.get("evidence_refs"), list) else []
        evidence_refs = graph_unique_records([*neighborhood_refs, *lexical_refs, *graphrag_refs], limit=max(30, limit * 10))
        ref_counts = graph_ref_quality_counts(evidence_refs)
        freshness = neighborhood.get("freshness") if isinstance(neighborhood.get("freshness"), dict) else {}
        answer_rules = graph_answer_rules(evidence_refs=evidence_refs, freshness=freshness, min_evidence_ref_count=1)
        resolved = neighborhood.get("resolved") if isinstance(neighborhood.get("resolved"), dict) else {}
        graph_nodes = neighborhood.get("nodes", []) if isinstance(neighborhood.get("nodes"), list) else []
        graph_edges = neighborhood.get("edges", []) if isinstance(neighborhood.get("edges"), list) else []
        typed_identity_abstention = bool(
            str(resolved.get("resolver_strategy") or "")
            == "typed_anchor_unresolved_fuzzy_candidates"
            and not graph_nodes
            and kind != "auto"
        )
        flags: list[str] = []
        notes: list[str] = []
        if typed_identity_abstention:
            notes.append(
                "typed_identity_unresolved_fuzzy_candidates_retained_as_navigation_only"
            )
        if not graph_nodes and not typed_identity_abstention:
            flags.append("no_graph_nodes")
        if not graph_edges and not typed_identity_abstention:
            flags.append("no_graph_edges")
        if not evidence_refs:
            flags.append("no_evidence_refs")
        if not ref_counts["has_raw_ref"]:
            flags.append("missing_raw_refs")
        if not ref_counts["has_segment_ref"]:
            flags.append("missing_segment_refs")
        if not ref_counts["has_session_ref"]:
            flags.append("missing_session_refs")
        if (
            not resolved.get("start_node_ids")
            and not typed_identity_abstention
        ):
            flags.append("no_resolved_start_nodes")
        if (
            str(freshness.get("status") or "")
            not in GRAPH_QUALITY_FRESH_STATUSES
            and not typed_identity_abstention
        ):
            flags.append("stale_or_unverifiable")
        packet_diagnostics = [
            *(neighborhood.get("diagnostics", []) if isinstance(neighborhood.get("diagnostics"), list) else []),
            *(lexical.get("diagnostics", []) if isinstance(lexical.get("diagnostics"), list) else []),
            *(graphrag.get("diagnostics", []) if isinstance(graphrag.get("diagnostics"), list) else []),
        ]
        diagnostic_findings = [
            graph_quality_diagnostic_finding(item)
            for item in dict.fromkeys(
                str(item)
                for item in packet_diagnostics
                if str(item)
            )
        ]
        critical_diagnostics = [
            item
            for item in diagnostic_findings
            if item.get("severity") == "critical"
        ]
        informational_diagnostics = [
            item
            for item in diagnostic_findings
            if item.get("severity") == "informational"
        ]
        if informational_diagnostics:
            notes.append(
                "informational_or_protective_packet_diagnostics_present"
            )
        if critical_diagnostics and not typed_identity_abstention:
            flags.append("packet_diagnostics_present")
            diagnostics.extend(
                f"{anchor_item.get('id')}:{item['code']}"
                for item in critical_diagnostics
            )
        elif critical_diagnostics:
            diagnostics.extend(
                f"{anchor_item.get('id')}:{item['code']}"
                for item in critical_diagnostics
            )
        review_status = (
            "correct_typed_abstention"
            if typed_identity_abstention
            else "ready_for_manual_verdict"
            if not flags
            else "needs_repair_before_verdict"
        )
        status_counts[review_status] += 1
        samples.append(
            {
                "id": anchor_item.get("id"),
                "anchor": anchor,
                "kind": kind,
                "role": anchor_item.get("role"),
                "ok": review_status
                in {
                    "ready_for_manual_verdict",
                    "correct_typed_abstention",
                },
                "review_status": review_status,
                "quality_flags": flags,
                "quality_notes": notes,
                "diagnostic_findings": diagnostic_findings,
                "critical_diagnostics": critical_diagnostics,
                "informational_diagnostics": (
                    informational_diagnostics
                ),
                "graph": {
                    "neighborhood_ok": neighborhood.get("ok"),
                    "lexical_ok": lexical.get("ok"),
                    "lexical_hit_count": len(lexical_hits),
                    "hybrid_ok": bool(neighborhood_refs or lexical_refs or graphrag_refs),
                    "full_graphrag_requested": bool(full_graphrag),
                    "full_graphrag_ok": graphrag.get("ok") if full_graphrag else None,
                    "node_count": neighborhood.get("node_count"),
                    "edge_count": neighborhood.get("edge_count"),
                    "start_node_count": len(resolved.get("start_node_ids", []) if isinstance(resolved.get("start_node_ids"), list) else []),
                    "route_candidate_count": len(resolved.get("route_candidates", []) if isinstance(resolved.get("route_candidates"), list) else []),
                    "top_route_nodes": graph_quality_route_nodes(graph_nodes),
                },
                "evidence": {
                    "evidence_ref_count": len(evidence_refs),
                    **ref_counts,
                    "sample_refs": graph_quality_sample_refs(
                        evidence_refs,
                        aoa_root=aoa_root,
                        limit=sample_ref_limit,
                    ),
                },
                "freshness": freshness,
                "answer_rules": answer_rules,
                "review": {
                    "status": "unreviewed",
                    "verdict": "",
                    "reviewer_action": "accept | reject | repair_index | repair_classifier | expand_anchor_set",
                    "checklist": [
                        "Do raw previews support the requested anchor?",
                        "Do segment/session refs route to stronger evidence?",
                        "Are global graph freshness and returned-scope freshness independently proven?",
                        "Are start nodes and route candidates specific rather than generic?",
                    ],
                },
            }
        )

    critical_failures = [
        sample
        for sample in samples
        if sample.get("review_status")
        not in {
            "ready_for_manual_verdict",
            "correct_typed_abstention",
        }
    ]
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_quality_audit",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": now,
        "ok": bool(samples) and not critical_failures,
        "mutates": False,
        "truth_status": "graph_quality_samples_not_reviewed_truth",
        "anchor_count": len(anchor_items),
        "sample_count": len(samples),
        "ready_for_manual_verdict_count": status_counts["ready_for_manual_verdict"],
        "correct_typed_abstention_count": status_counts[
            "correct_typed_abstention"
        ],
        "needs_repair_before_verdict_count": status_counts["needs_repair_before_verdict"],
        "sample_ref_limit": sample_ref_limit,
        "full_graphrag": bool(full_graphrag),
        "retrieval_mode": "graph_neighborhood_plus_lexical_refs" if not full_graphrag else "graph_neighborhood_plus_full_graphrag_packet",
        "samples": samples,
        "diagnostics": diagnostics,
        "next_route": "Review sample raw/segment/session refs; if quality flags are present, run index-maintenance before trusting graph packets.",
    }
    if write_report:
        diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
        diagnostics_dir.mkdir(parents=True, exist_ok=True)
        stem = f"{compact_stamp()}__graph-quality-audit"
        report_json = diagnostics_dir / f"{stem}.json"
        report_md = diagnostics_dir / f"{stem}.md"
        write_json(report_json, payload)
        write_markdown(report_md, graph_quality_audit_markdown(payload))
        payload["report_json"] = str(report_json)
        payload["report_markdown"] = str(report_md)
    return payload


def graph_quality_audit_markdown(payload: dict[str, Any]) -> str:
    lines = [
        "# Graph Quality Audit",
        "",
        f"- generated_at: `{payload.get('generated_at')}`",
        f"- ok: `{payload.get('ok')}`",
        f"- anchor_count: `{payload.get('anchor_count')}`",
        f"- ready_for_manual_verdict: `{payload.get('ready_for_manual_verdict_count')}`",
        f"- correct_typed_abstention: `{payload.get('correct_typed_abstention_count')}`",
        f"- needs_repair_before_verdict: `{payload.get('needs_repair_before_verdict_count')}`",
        "",
        (
            "Samples are verdict-ready when evidence refs and freshness are "
            "adequate, or when a typed exact miss honestly retains "
            "type-incompatible fuzzy rows as navigation-only candidates."
        ),
        "",
        "## Samples",
        "",
        "| id | kind | status | refs | flags |",
        "| --- | --- | --- | ---: | --- |",
    ]
    for sample in payload.get("samples", []) if isinstance(payload.get("samples"), list) else []:
        if not isinstance(sample, dict):
            continue
        evidence = sample.get("evidence") if isinstance(sample.get("evidence"), dict) else {}
        flags = ", ".join(str(item) for item in sample.get("quality_flags", []) if item)
        lines.append(
            "| `{id}` | `{kind}` | `{status}` | {refs} | `{flags}` |".format(
                id=sample.get("id"),
                kind=sample.get("kind"),
                status=sample.get("review_status"),
                refs=evidence.get("evidence_ref_count", 0),
                flags=flags or "none",
            )
        )
    for sample in payload.get("samples", []) if isinstance(payload.get("samples"), list) else []:
        if not isinstance(sample, dict):
            continue
        evidence = sample.get("evidence") if isinstance(sample.get("evidence"), dict) else {}
        lines.extend(["", f"### {sample.get('id')}", ""])
        lines.append(f"- anchor: `{sample.get('anchor')}`")
        lines.append(f"- kind: `{sample.get('kind')}`")
        lines.append(f"- review_status: `{sample.get('review_status')}`")
        lines.append(f"- evidence_ref_count: `{evidence.get('evidence_ref_count')}`")
        for ref in evidence.get("sample_refs", []) if isinstance(evidence.get("sample_refs"), list) else []:
            if not isinstance(ref, dict):
                continue
            preview = ref.get("raw_preview") if isinstance(ref.get("raw_preview"), dict) else {}
            lines.extend(
                [
                    "",
                    f"- raw_preview_status: `{preview.get('status')}`",
                    "```text",
                    str(preview.get("text") or ""),
                    "```",
                ]
            )
    diagnostics = payload.get("diagnostics") if isinstance(payload.get("diagnostics"), list) else []
    if diagnostics:
        lines.extend(["", "## Diagnostics", ""])
        for item in diagnostics:
            lines.append(f"- `{item}`")
    return "\n".join(lines) + "\n"


GRAPH_QUALITY_REVIEW_ACTIONS = {
    "accept",
    "reject",
    "weak",
    "wrong_anchor",
    "stale",
    "repair_index",
    "repair_classifier",
    "expand_anchor_set",
    "skip",
    "open",
}


def graph_quality_identity(sample: dict[str, Any]) -> str:
    identity = str(sample.get("id") or "").strip()
    if identity:
        return identity
    anchor = str(sample.get("anchor") or "")
    kind = str(sample.get("kind") or "auto")
    return route_key_slug(f"{kind}_{anchor}", fallback="graph_quality_sample", max_chars=120)


def parse_graph_quality_verdict(value: str) -> tuple[str, dict[str, Any]]:
    if "=" not in value:
        raise ValueError("verdict must use sample_id=verdict[:action[:note]]")
    identity, payload = value.split("=", 1)
    parts = payload.split(":", 2)
    verdict = parts[0].strip()
    action = parts[1].strip() if len(parts) > 1 and parts[1].strip() else verdict
    note = parts[2].strip() if len(parts) > 2 else ""
    if verdict not in GRAPH_QUALITY_REVIEW_ACTIONS:
        raise ValueError(f"unsupported graph quality verdict {verdict!r}")
    if action not in GRAPH_QUALITY_REVIEW_ACTIONS:
        raise ValueError(f"unsupported graph quality reviewer action {action!r}")
    return identity.strip(), {
        "verdict": verdict,
        "reviewer_action": action,
        "note": note,
    }


def load_graph_quality_verdict_file(path: Path) -> dict[str, dict[str, Any]]:
    payload = read_json(path, {})
    if not isinstance(payload, dict):
        raise ValueError(f"invalid graph quality verdict file: {path}")
    raw_items = payload.get("verdicts") or payload.get("reviews") or []
    if not isinstance(raw_items, list):
        raise ValueError(f"graph quality verdict file must contain verdicts list: {path}")
    verdicts: dict[str, dict[str, Any]] = {}
    for item in raw_items:
        if not isinstance(item, dict):
            continue
        identity = str(item.get("identity") or item.get("id") or "").strip()
        if not identity:
            anchor = str(item.get("anchor") or "").strip()
            kind = str(item.get("kind") or "auto").strip()
            identity = route_key_slug(f"{kind}_{anchor}", fallback="", max_chars=120) if anchor else ""
        if not identity:
            raise ValueError(f"graph quality verdict item missing identity: {path}")
        verdict = str(item.get("verdict") or "").strip()
        action = str(item.get("reviewer_action") or item.get("action") or verdict).strip()
        if verdict not in GRAPH_QUALITY_REVIEW_ACTIONS:
            raise ValueError(f"unsupported graph quality verdict {verdict!r} in {path}")
        if action not in GRAPH_QUALITY_REVIEW_ACTIONS:
            raise ValueError(f"unsupported graph quality reviewer action {action!r} in {path}")
        verdicts[identity] = {
            "verdict": verdict,
            "reviewer_action": action,
            "note": str(item.get("note") or ""),
        }
    return verdicts


def graph_quality_regression_candidate(sample: dict[str, Any], review: dict[str, Any]) -> dict[str, Any]:
    evidence = sample.get("evidence") if isinstance(sample.get("evidence"), dict) else {}
    freshness = sample.get("freshness") if isinstance(sample.get("freshness"), dict) else {}
    verdict = str(review.get("verdict") or "")
    if verdict == "accept":
        polarity = "positive"
    elif verdict == "weak":
        polarity = "weak"
    elif verdict == "wrong_anchor":
        polarity = "wrong_anchor"
    elif verdict == "stale":
        polarity = "stale"
    else:
        polarity = "negative"
    sample_refs = evidence.get("sample_refs") if isinstance(evidence.get("sample_refs"), list) else []
    return {
        "identity": graph_quality_identity(sample),
        "polarity": polarity,
        "anchor": sample.get("anchor"),
        "kind": sample.get("kind"),
        "role": sample.get("role"),
        "expected": {
            "route_type": sample.get("kind"),
            "expected_refs": {
                "has_raw_ref": bool(evidence.get("has_raw_ref")),
                "has_segment_ref": bool(evidence.get("has_segment_ref")),
                "has_session_ref": bool(evidence.get("has_session_ref")),
                "min_evidence_ref_count": min(int_value(evidence.get("evidence_ref_count")), 3),
            },
            "has_raw_ref": bool(evidence.get("has_raw_ref")),
            "has_segment_ref": bool(evidence.get("has_segment_ref")),
            "has_session_ref": bool(evidence.get("has_session_ref")),
            "min_evidence_ref_count": min(int_value(evidence.get("evidence_ref_count")), 3),
            "freshness_expectation": {
                "status": freshness.get("status"),
                "acceptable_statuses": [freshness.get("status")] if freshness.get("status") else [],
            },
            "freshness_status": freshness.get("status"),
            "review_verdict": verdict,
        },
        "sample_refs": sample_refs[:3],
        "note": review.get("note") or "",
    }


def graph_quality_review(
    *,
    aoa_root: Path,
    audit_path: Path,
    verdict_values: list[str] | None = None,
    verdict_file: Path | None = None,
    reviewer: str = "agent",
    write_report: bool = False,
) -> dict[str, Any]:
    now = utc_now()
    audit = read_json(audit_path, {})
    if not isinstance(audit, dict) or audit.get("artifact_type") != "session_memory_graph_quality_audit":
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "session_memory_graph_quality_review",
            "generated_at": now,
            "ok": False,
            "audit_path": str(audit_path),
            "diagnostics": ["audit_path is not a session_memory_graph_quality_audit JSON artifact"],
            "samples": [],
            "quality_feedback": [],
            "regression_candidates": [],
        }

    diagnostics: list[str] = []
    verdicts: dict[str, dict[str, Any]] = {}
    if verdict_file is not None:
        try:
            verdicts.update(load_graph_quality_verdict_file(verdict_file))
        except ValueError as exc:
            diagnostics.append(str(exc))
    for value in verdict_values or []:
        try:
            identity, verdict = parse_graph_quality_verdict(value)
            verdicts[identity] = verdict
        except ValueError as exc:
            diagnostics.append(str(exc))

    samples = audit.get("samples") if isinstance(audit.get("samples"), list) else []
    sample_ids = {
        graph_quality_identity(sample)
        for sample in samples
        if isinstance(sample, dict)
    }
    for identity in sorted(set(verdicts) - sample_ids):
        diagnostics.append(f"verdict did not match a graph quality sample: {identity}")

    reviewed_samples: list[dict[str, Any]] = []
    quality_feedback: list[dict[str, Any]] = []
    regression_candidates: list[dict[str, Any]] = []
    verdict_counts: Counter[str] = Counter()
    action_counts: Counter[str] = Counter()
    for sample in samples:
        if not isinstance(sample, dict):
            continue
        identity = graph_quality_identity(sample)
        verdict = verdicts.get(identity)
        review_status = "reviewed" if verdict else "open"
        review = {
            "status": review_status,
            "verdict": verdict.get("verdict") if verdict else "open",
            "reviewer_action": verdict.get("reviewer_action") if verdict else "open",
            "reviewer": reviewer,
            "reviewed_at": now if verdict else "",
            "note": verdict.get("note") if verdict else "",
        }
        verdict_counts[str(review["verdict"])] += 1
        action_counts[str(review["reviewer_action"])] += 1
        reviewed = {
            "identity": identity,
            "id": sample.get("id"),
            "anchor": sample.get("anchor"),
            "kind": sample.get("kind"),
            "role": sample.get("role"),
            "quality_flags": sample.get("quality_flags", []),
            "graph": sample.get("graph"),
            "evidence": sample.get("evidence"),
            "freshness": sample.get("freshness"),
            "answer_rules": sample.get("answer_rules"),
            "review": review,
        }
        reviewed_samples.append(reviewed)
        if not verdict:
            continue
        action = str(verdict.get("reviewer_action") or "")
        if action in {"reject", "weak", "wrong_anchor", "stale", "repair_index", "repair_classifier", "expand_anchor_set"}:
            quality_feedback.append(
                {
                    "identity": identity,
                    "anchor": sample.get("anchor"),
                    "kind": sample.get("kind"),
                    "action": action,
                    "verdict": verdict.get("verdict"),
                    "note": verdict.get("note") or "",
                    "quality_flags": sample.get("quality_flags", []),
                    "evidence_summary": {
                        key: sample.get("evidence", {}).get(key)
                        for key in ("evidence_ref_count", "has_raw_ref", "has_segment_ref", "has_session_ref")
                        if isinstance(sample.get("evidence"), dict)
                    },
                    "freshness": sample.get("freshness"),
                }
            )
        if str(verdict.get("verdict") or "") in {"accept", "reject", "weak", "wrong_anchor", "stale"}:
            regression_candidates.append(graph_quality_regression_candidate(sample, review))

    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_quality_review",
        "graph_schema_version": GRAPH_SCHEMA_VERSION,
        "generated_at": now,
        "ok": not diagnostics,
        "mutates": False,
        "truth_status": "graph_quality_review_not_reviewed_memory_truth",
        "audit_path": str(audit_path),
        "audit_generated_at": audit.get("generated_at"),
        "reviewer": reviewer,
        "sample_count": len(reviewed_samples),
        "reviewed_count": sum(1 for sample in reviewed_samples if sample.get("review", {}).get("status") == "reviewed"),
        "open_count": sum(1 for sample in reviewed_samples if sample.get("review", {}).get("status") == "open"),
        "verdict_counts": dict(sorted(verdict_counts.items())),
        "action_counts": dict(sorted(action_counts.items())),
        "quality_feedback_count": len(quality_feedback),
        "quality_feedback": quality_feedback,
        "regression_candidate_count": len(regression_candidates),
        "regression_candidates": regression_candidates,
        "samples": reviewed_samples,
        "diagnostics": diagnostics,
        "next_route": "Accepted and rejected samples are candidates for a later graph regression corpus; this review does not mutate raw evidence or route indexes.",
    }
    if write_report:
        diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
        diagnostics_dir.mkdir(parents=True, exist_ok=True)
        stem = f"{compact_stamp()}__graph-quality-review"
        report_json = diagnostics_dir / f"{stem}.json"
        report_md = diagnostics_dir / f"{stem}.md"
        write_json(report_json, payload)
        write_markdown(report_md, graph_quality_review_markdown(payload))
        payload["report_json"] = str(report_json)
        payload["report_markdown"] = str(report_md)
    return payload


def graph_quality_review_markdown(payload: dict[str, Any]) -> str:
    lines = [
        "# Graph Quality Review",
        "",
        f"- generated_at: `{payload.get('generated_at')}`",
        f"- ok: `{payload.get('ok')}`",
        f"- audit_path: `{payload.get('audit_path')}`",
        f"- sample_count: `{payload.get('sample_count')}`",
        f"- reviewed_count: `{payload.get('reviewed_count')}`",
        f"- open_count: `{payload.get('open_count')}`",
        f"- quality_feedback_count: `{payload.get('quality_feedback_count')}`",
        f"- regression_candidate_count: `{payload.get('regression_candidate_count')}`",
        "",
        "## Verdict Counts",
        "",
    ]
    for verdict, count in (payload.get("verdict_counts") or {}).items() if isinstance(payload.get("verdict_counts"), dict) else []:
        lines.append(f"- `{verdict}`: {count}")
    feedback = payload.get("quality_feedback") if isinstance(payload.get("quality_feedback"), list) else []
    if feedback:
        lines.extend(["", "## Quality Feedback", "", "| identity | action | note |", "| --- | --- | --- |"])
        for item in feedback:
            if not isinstance(item, dict):
                continue
            lines.append(f"| `{item.get('identity')}` | `{item.get('action')}` | {item.get('note') or ''} |")
    candidates = payload.get("regression_candidates") if isinstance(payload.get("regression_candidates"), list) else []
    if candidates:
        lines.extend(["", "## Regression Candidates", "", "| identity | polarity | anchor | expected |", "| --- | --- | --- | --- |"])
        for item in candidates:
            if not isinstance(item, dict):
                continue
            expected = item.get("expected") if isinstance(item.get("expected"), dict) else {}
            lines.append(
                "| `{identity}` | `{polarity}` | `{anchor}` | `{expected}` |".format(
                    identity=item.get("identity"),
                    polarity=item.get("polarity"),
                    anchor=item.get("anchor"),
                    expected=short_text(json.dumps(expected, ensure_ascii=False, sort_keys=True), max_chars=180),
                )
            )
    lines.extend(["", "## Samples", "", "| identity | verdict | action | note |", "| --- | --- | --- | --- |"])
    for sample in payload.get("samples", []) if isinstance(payload.get("samples"), list) else []:
        if not isinstance(sample, dict):
            continue
        review = sample.get("review") if isinstance(sample.get("review"), dict) else {}
        lines.append(
            f"| `{sample.get('identity')}` | `{review.get('verdict')}` | `{review.get('reviewer_action')}` | {review.get('note') or ''} |"
        )
    diagnostics = payload.get("diagnostics") if isinstance(payload.get("diagnostics"), list) else []
    if diagnostics:
        lines.extend(["", "## Diagnostics", ""])
        for item in diagnostics:
            lines.append(f"- `{item}`")
    return "\n".join(lines) + "\n"


GRAPH_QUALITY_CORPUS_POLARITIES = {"positive", "weak", "negative", "stale", "wrong_anchor"}


def graph_quality_corpus_default_path(aoa_root: Path) -> Path:
    return aoa_root / GRAPH_QUALITY_CORPUS_PATH


def graph_quality_case_from_candidate(candidate: dict[str, Any]) -> dict[str, Any]:
    expected = candidate.get("expected") if isinstance(candidate.get("expected"), dict) else {}
    expected_refs = expected.get("expected_refs") if isinstance(expected.get("expected_refs"), dict) else expected
    polarity = str(candidate.get("polarity") or "positive")
    if polarity not in GRAPH_QUALITY_CORPUS_POLARITIES:
        polarity = "negative"
    identity = str(candidate.get("identity") or candidate.get("id") or "")
    return {
        "id": route_key_slug(identity or f"{candidate.get('kind')}_{candidate.get('anchor')}", fallback="graph_quality_case", max_chars=120),
        "polarity": polarity,
        "anchor": candidate.get("anchor"),
        "kind": candidate.get("kind") or "auto",
        "role": candidate.get("role") or candidate.get("kind") or "auto",
        "expected": {
            "route_type": expected.get("route_type") or candidate.get("kind") or "auto",
            "freshness_expectation": expected.get("freshness_expectation") if isinstance(expected.get("freshness_expectation"), dict) else {
                "status": expected.get("freshness_status"),
                "acceptable_statuses": [expected.get("freshness_status")] if expected.get("freshness_status") else [],
            },
            "expected_refs": {
                "has_raw_ref": bool(expected_refs.get("has_raw_ref")),
                "has_segment_ref": bool(expected_refs.get("has_segment_ref")),
                "has_session_ref": bool(expected_refs.get("has_session_ref")),
                "min_evidence_ref_count": max(0, int_value(expected_refs.get("min_evidence_ref_count"), 1)),
            },
            "review_verdict": expected.get("review_verdict") or "",
        },
        "sample_refs": candidate.get("sample_refs", []) if isinstance(candidate.get("sample_refs"), list) else [],
        "note": candidate.get("note") or "",
    }


def graph_quality_corpus_from_review(
    *,
    aoa_root: Path,
    review_paths: list[Path],
    corpus_path: Path | None = None,
    write_corpus: bool = False,
    write_report: bool = False,
) -> dict[str, Any]:
    now = utc_now()
    diagnostics: list[str] = []
    cases_by_id: dict[str, dict[str, Any]] = {}
    source_reviews: list[str] = []
    for review_path in review_paths:
        review = read_json(review_path, {})
        if not isinstance(review, dict) or review.get("artifact_type") != "session_memory_graph_quality_review":
            diagnostics.append(f"not a graph-quality-review report: {review_path}")
            continue
        source_reviews.append(str(review_path))
        for candidate in review.get("regression_candidates", []) if isinstance(review.get("regression_candidates"), list) else []:
            if not isinstance(candidate, dict):
                continue
            case = graph_quality_case_from_candidate(candidate)
            cases_by_id[str(case["id"])] = case
    cases = sorted(cases_by_id.values(), key=lambda item: (str(item.get("polarity") or ""), str(item.get("id") or "")))
    polarity_counts = dict(sorted(Counter(str(case.get("polarity") or "unknown") for case in cases).items()))
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_quality_regression_corpus",
        "corpus_schema_version": 1,
        "generated_at": now,
        "ok": bool(cases) and not diagnostics,
        "mutates": bool(write_corpus),
        "truth_status": "reviewed_graph_quality_controls_not_memory_truth",
        "source_reviews": source_reviews,
        "case_count": len(cases),
        "polarity_counts": polarity_counts,
        "required_polarities": sorted(GRAPH_QUALITY_CORPUS_POLARITIES),
        "missing_polarities": sorted(GRAPH_QUALITY_CORPUS_POLARITIES - set(polarity_counts)),
        "cases": cases,
        "diagnostics": diagnostics,
    }
    if write_corpus:
        target = corpus_path or graph_quality_corpus_default_path(aoa_root)
        target.parent.mkdir(parents=True, exist_ok=True)
        write_json(target, payload)
        payload["corpus_path"] = str(target)
    if write_report:
        diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
        diagnostics_dir.mkdir(parents=True, exist_ok=True)
        stem = f"{compact_stamp()}__graph-quality-corpus"
        report_json = diagnostics_dir / f"{stem}.json"
        report_md = diagnostics_dir / f"{stem}.md"
        write_json(report_json, payload)
        write_markdown(report_md, graph_quality_corpus_markdown(payload))
        payload["report_json"] = str(report_json)
        payload["report_markdown"] = str(report_md)
    return payload


def graph_quality_corpus_markdown(payload: dict[str, Any]) -> str:
    lines = [
        "# Graph Quality Regression Corpus",
        "",
        f"- generated_at: `{payload.get('generated_at')}`",
        f"- ok: `{payload.get('ok')}`",
        f"- case_count: `{payload.get('case_count')}`",
        f"- missing_polarities: `{', '.join(payload.get('missing_polarities', [])) if isinstance(payload.get('missing_polarities'), list) else ''}`",
        "",
        "| id | polarity | kind | anchor | expected refs |",
        "| --- | --- | --- | --- | --- |",
    ]
    for case in payload.get("cases", []) if isinstance(payload.get("cases"), list) else []:
        if not isinstance(case, dict):
            continue
        expected = case.get("expected") if isinstance(case.get("expected"), dict) else {}
        expected_refs = expected.get("expected_refs") if isinstance(expected.get("expected_refs"), dict) else {}
        lines.append(
            "| `{id}` | `{polarity}` | `{kind}` | `{anchor}` | `{refs}` |".format(
                id=case.get("id"),
                polarity=case.get("polarity"),
                kind=case.get("kind"),
                anchor=case.get("anchor"),
                refs=short_text(json.dumps(expected_refs, ensure_ascii=False, sort_keys=True), max_chars=160),
            )
        )
    diagnostics = payload.get("diagnostics") if isinstance(payload.get("diagnostics"), list) else []
    if diagnostics:
        lines.extend(["", "## Diagnostics", ""])
        for item in diagnostics:
            lines.append(f"- `{item}`")
    return "\n".join(lines) + "\n"


def load_graph_quality_corpus(path: Path) -> tuple[dict[str, Any], list[str]]:
    payload = read_json(path, {})
    if not isinstance(payload, dict) or payload.get("artifact_type") != "session_memory_graph_quality_regression_corpus":
        return {}, [f"not a graph quality regression corpus: {path}"]
    cases = payload.get("cases")
    if not isinstance(cases, list):
        return payload, [f"corpus has no cases list: {path}"]
    return payload, []


def graph_quality_corpus_case_check(aoa_root: Path, case: dict[str, Any], *, limit: int) -> dict[str, Any]:
    live_check = str(case.get("live_check") or "run")
    if live_check in {"skip", "fixture_required"}:
        return {
            "id": case.get("id"),
            "polarity": case.get("polarity"),
            "anchor": case.get("anchor"),
            "kind": case.get("kind"),
            "ok": True,
            "skipped": True,
            "skip_reason": live_check,
            "failures": [],
            "observed": {},
        }
    expected = case.get("expected") if isinstance(case.get("expected"), dict) else {}
    expected_refs = expected.get("expected_refs") if isinstance(expected.get("expected_refs"), dict) else {}
    freshness_expectation = expected.get("freshness_expectation") if isinstance(expected.get("freshness_expectation"), dict) else {}
    audit = graph_quality_audit(
        aoa_root=aoa_root,
        anchors=[{"id": case.get("id"), "anchor": case.get("anchor"), "kind": case.get("kind") or "auto", "role": case.get("role") or case.get("kind") or "auto"}],
        limit=limit,
        sample_ref_limit=2,
    )
    sample = audit.get("samples", [{}])[0] if isinstance(audit.get("samples"), list) and audit.get("samples") else {}
    evidence = sample.get("evidence") if isinstance(sample.get("evidence"), dict) else {}
    freshness = sample.get("freshness") if isinstance(sample.get("freshness"), dict) else {}
    answer_rules = sample.get("answer_rules") if isinstance(sample.get("answer_rules"), dict) else graph_answer_rules(
        evidence_refs=[],
        freshness=freshness,
    )
    failures: list[str] = []
    route_type = str(expected.get("route_type") or "")
    if route_type and route_type != str(sample.get("kind") or ""):
        failures.append(f"route_type:{sample.get('kind')}!={route_type}")
    for key in ("has_raw_ref", "has_segment_ref", "has_session_ref"):
        if key in expected_refs and bool(evidence.get(key)) != bool(expected_refs.get(key)):
            failures.append(f"{key}:{evidence.get(key)}!={expected_refs.get(key)}")
    min_refs = int_value(expected_refs.get("min_evidence_ref_count"), 0)
    if min_refs and int_value(evidence.get("evidence_ref_count")) < min_refs:
        failures.append(f"evidence_ref_count:{evidence.get('evidence_ref_count')}<{min_refs}")
    acceptable_statuses = [
        str(item)
        for item in freshness_expectation.get("acceptable_statuses", [])
        if item
    ] if isinstance(freshness_expectation.get("acceptable_statuses"), list) else []
    expected_status = str(freshness_expectation.get("status") or "")
    if expected_status and not acceptable_statuses:
        acceptable_statuses = [expected_status]
    if acceptable_statuses and str(freshness.get("status") or "") not in acceptable_statuses:
        failures.append(f"freshness_status:{freshness.get('status')} not in {acceptable_statuses}")
    polarity = str(case.get("polarity") or "")
    if polarity == "positive" and answer_rules.get("status") in {"insufficient_evidence", "stale", "weak_route"}:
        failures.append(f"answer_rule_gate:{answer_rules.get('status')}")
    return {
        "id": case.get("id"),
        "polarity": polarity,
        "anchor": case.get("anchor"),
        "kind": case.get("kind"),
        "ok": not failures,
        "skipped": False,
        "failures": failures,
        "observed": {
            "route_type": sample.get("kind"),
            "review_status": sample.get("review_status"),
            "evidence": {
                "evidence_ref_count": evidence.get("evidence_ref_count"),
                "has_raw_ref": evidence.get("has_raw_ref"),
                "has_segment_ref": evidence.get("has_segment_ref"),
                "has_session_ref": evidence.get("has_session_ref"),
            },
            "freshness": freshness,
            "answer_rules": answer_rules,
        },
    }


def graph_quality_corpus_check(
    *,
    aoa_root: Path,
    corpus_path: Path | None = None,
    limit: int = 6,
    write_report: bool = False,
) -> dict[str, Any]:
    now = utc_now()
    target = corpus_path or graph_quality_corpus_default_path(aoa_root)
    corpus, diagnostics = load_graph_quality_corpus(target)
    cases = corpus.get("cases") if isinstance(corpus.get("cases"), list) else []
    results = [
        graph_quality_corpus_case_check(aoa_root, case, limit=max(1, min(int_value(limit, 6), 30)))
        for case in cases
        if isinstance(case, dict)
    ]
    failures = [result for result in results if not result.get("ok")]
    polarity_counts = dict(sorted(Counter(str(case.get("polarity") or "unknown") for case in cases if isinstance(case, dict)).items()))
    missing_polarities = sorted(GRAPH_QUALITY_CORPUS_POLARITIES - set(polarity_counts))
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_quality_regression_check",
        "generated_at": now,
        "ok": not diagnostics and not failures and not missing_polarities,
        "mutates": False,
        "corpus_path": str(target),
        "case_count": len(results),
        "passed_count": sum(1 for result in results if result.get("ok")),
        "skipped_count": sum(1 for result in results if result.get("skipped")),
        "failed_count": len(failures),
        "polarity_counts": polarity_counts,
        "missing_polarities": missing_polarities,
        "results": results,
        "diagnostics": diagnostics,
    }
    if write_report:
        diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
        diagnostics_dir.mkdir(parents=True, exist_ok=True)
        stem = f"{compact_stamp()}__graph-quality-corpus-check"
        report_json = diagnostics_dir / f"{stem}.json"
        report_md = diagnostics_dir / f"{stem}.md"
        write_json(report_json, payload)
        write_markdown(report_md, graph_quality_corpus_check_markdown(payload))
        payload["report_json"] = str(report_json)
        payload["report_markdown"] = str(report_md)
    return payload


def graph_quality_corpus_check_markdown(payload: dict[str, Any]) -> str:
    lines = [
        "# Graph Quality Corpus Check",
        "",
        f"- generated_at: `{payload.get('generated_at')}`",
        f"- ok: `{payload.get('ok')}`",
        f"- corpus_path: `{payload.get('corpus_path')}`",
        f"- passed: `{payload.get('passed_count')}/{payload.get('case_count')}`",
        f"- skipped: `{payload.get('skipped_count')}`",
        f"- missing_polarities: `{', '.join(payload.get('missing_polarities', [])) if isinstance(payload.get('missing_polarities'), list) else ''}`",
        "",
        "| id | polarity | ok | skipped | failures |",
        "| --- | --- | --- | --- | --- |",
    ]
    for result in payload.get("results", []) if isinstance(payload.get("results"), list) else []:
        if isinstance(result, dict):
            lines.append(f"| `{result.get('id')}` | `{result.get('polarity')}` | `{result.get('ok')}` | `{result.get('skipped')}` | `{', '.join(result.get('failures', []))}` |")
    diagnostics = payload.get("diagnostics") if isinstance(payload.get("diagnostics"), list) else []
    if diagnostics:
        lines.extend(["", "## Diagnostics", ""])
        for item in diagnostics:
            lines.append(f"- `{item}`")
    return "\n".join(lines) + "\n"


def path_without_anchor(value: Any) -> Path:
    text = str(value or "")
    if "#" in text:
        text = text.split("#", 1)[0]
    return Path(text)


def resolve_evidence_ref_path(value: Any, *, raw_path_value: Any = "") -> Path:
    path = path_without_anchor(value)
    if path.is_absolute() or not raw_path_value:
        return path
    raw_path = Path(str(raw_path_value))
    session_dir = raw_path.parent.parent if raw_path.parent.name == "raw" else raw_path.parent
    candidates = [session_dir / path, session_dir / "segments" / path]
    for candidate in candidates:
        if candidate.exists():
            return candidate
    return candidates[0]


def raw_ref_is_alive(raw_path: Path, raw_ref: Any) -> bool:
    line_no = line_from_raw_ref(raw_ref)
    if not line_no or not raw_path.is_file():
        return False
    try:
        with raw_path.open("r", encoding="utf-8", errors="replace") as handle:
            for current_line, _line in enumerate(handle, start=1):
                if current_line == line_no:
                    return True
                if current_line > line_no:
                    return False
    except OSError:
        return False
    return False


def evidence_ref_integrity_state(aoa_root: Path, *, sample_limit: int = 200) -> dict[str, Any]:
    db_path = search_db_path(aoa_root)
    if not db_path.exists():
        return {"status": "missing", "ok": False, "sample_limit": sample_limit, "checked_count": 0, "broken_count": 0, "broken_refs": [], "diagnostics": ["search_index_missing"]}
    broken: list[dict[str, Any]] = []
    checked = 0
    try:
        conn = connect_existing_search_db(db_path)
        rows = conn.execute(
            """
            SELECT id, doc_type, manifest_path, segment_id, event_id, segment_ref, segment_index_path, raw_path, raw_ref, raw_block_ref
            FROM documents
            WHERE doc_type IN ('event', 'segment', 'incident')
            ORDER BY rowid DESC
            LIMIT ?
            """,
            (max(1, int_value(sample_limit, 200)),),
        ).fetchall()
        conn.close()
    except sqlite3.Error as exc:
        status = sqlite_error_status(exc)
        return {"status": status, "ok": False, "sample_limit": sample_limit, "checked_count": 0, "broken_count": 0, "broken_refs": [], "diagnostics": [sqlite_error_diagnostic(exc)]}
    for row in rows:
        checked += 1
        missing: list[str] = []
        resolved_refs, _resolution = resolve_search_result_refs(row)
        ref_values = {
            "manifest_path": row["manifest_path"],
            "segment_ref": resolved_refs.get("segment", row["segment_ref"]),
            "segment_index_path": resolved_refs.get("segment_index", row["segment_index_path"]),
            "raw_block_ref": resolved_refs.get("raw_block", row["raw_block_ref"]),
        }
        for column in ("manifest_path", "segment_ref", "segment_index_path", "raw_block_ref"):
            value = ref_values[column]
            if not value:
                continue
            path = resolve_evidence_ref_path(value, raw_path_value=str(search_row_raw_path(row) or ""))
            if not path.exists():
                missing.append(column)
        raw_ref = row["raw_ref"]
        raw_path = search_row_raw_path(row)
        if raw_ref and (raw_path is None or not raw_ref_is_alive(raw_path, raw_ref)):
            missing.append("raw_ref")
        if missing:
            broken.append({"doc_id": row["id"], "doc_type": row["doc_type"], "missing": missing})
    return {
        "status": "alive" if not broken else "broken",
        "ok": not broken,
        "sample_limit": sample_limit,
        "checked_count": checked,
        "broken_count": len(broken),
        "broken_refs": broken[:20],
        "diagnostics": [],
    }


def graph_sidecar_state(aoa_root: Path, *, latest_source_mtime: float = 0.0, expected_session_count: int | None = None) -> dict[str, Any]:
    paths = graph_paths(aoa_root)
    index_path = paths["index"]
    sidecar_artifacts = graph_sidecar_artifact_paths(aoa_root)
    existing_artifacts = sorted(name for name, path in sidecar_artifacts.items() if path.exists())
    missing_artifacts = sorted(name for name in sidecar_artifacts if name not in existing_artifacts)
    if missing_artifacts:
        all_missing = not existing_artifacts
        return {
            "status": "not_exported" if all_missing else "partial",
            "snapshot_required": False,
            "needs_snapshot_refresh": not all_missing,
            "needs_offline_graph_build": False,
            "index": str(index_path),
            "existing_artifacts": existing_artifacts,
            "missing_artifacts": missing_artifacts,
            "diagnostics": ["graph_sidecar_not_exported" if all_missing else "graph_sidecar_partial"],
        }
    payload = read_json(index_path, {})
    if not isinstance(payload, dict):
        return {
            "status": "invalid",
            "snapshot_required": False,
            "needs_snapshot_refresh": True,
            "needs_offline_graph_build": False,
            "index": str(index_path),
            "existing_artifacts": existing_artifacts,
            "missing_artifacts": [],
            "diagnostics": ["graph_sidecar_index_invalid"],
        }
    commit_validation = graph_sidecar_commit_validation(
        aoa_root,
        payload,
        verify_content=False,
        verify_store_semantics=False,
    )
    graph_mtime = max(path_mtime(index_path), path_mtime(paths["nodes"]), path_mtime(paths["edges"]))
    search_generated_at = search_index_generated_at(aoa_root)
    graph_generated_at = str(payload.get("generated_at") or "")
    reasons: list[str] = list(
        commit_validation.get("reasons") or []
    )
    if int_value(payload.get("graph_schema_version")) != GRAPH_SCHEMA_VERSION:
        reasons.append("graph_schema_mismatch")
    if int_value(payload.get("node_count")) <= 0:
        reasons.append("graph_nodes_empty")
    if int_value(payload.get("edge_count")) <= 0:
        reasons.append("graph_edges_empty")
    if expected_session_count is not None and int_value(payload.get("session_count")) != expected_session_count:
        reasons.append("graph_session_count_mismatch")
    if latest_source_mtime > 0 and graph_mtime < latest_source_mtime:
        reasons.append("source_newer_than_graph_sidecar")
    relation = "unknown"
    if search_generated_at and graph_generated_at:
        if search_generated_at > graph_generated_at:
            relation = "search_newer_than_graph"
        elif graph_generated_at > search_generated_at:
            relation = "graph_newer_than_search"
        else:
            relation = "same_generation_time"
    return {
        "status": "current" if not reasons else "stale",
        "snapshot_required": False,
        "needs_snapshot_refresh": bool(reasons),
        "needs_offline_graph_build": False,
        "index": str(index_path),
        "existing_artifacts": existing_artifacts,
        "missing_artifacts": [],
        "graph_generated_at": graph_generated_at,
        "search_index_generated_at": search_generated_at,
        "search_vs_graph": relation,
        "graph_mtime": graph_mtime,
        "latest_source_mtime": latest_source_mtime,
        "session_count": int_value(payload.get("session_count")),
        "expected_session_count": expected_session_count,
        "node_count": int_value(payload.get("node_count")),
        "edge_count": int_value(payload.get("edge_count")),
        "reasons": reasons,
        "commit_validation": commit_validation,
        "diagnostics": [],
    }


def graph_freshness_gates(
    *,
    aoa_root: Path,
    target: str = "all",
    since: str | None = None,
    until: str | None = None,
    limit: int | None = None,
    ref_sample_limit: int = 200,
    stable_quiet_seconds: float | None = None,
    now_ts: float | None = None,
    write_report: bool = False,
    selected_records: list[dict[str, Any]] | None = None,
    selection_scope: dict[str, Any] | None = None,
) -> dict[str, Any]:
    now = utc_now()
    diagnostics: list[str] = []
    try:
        records = (
            list(selected_records)
            if selected_records is not None
            else [resolve_session_record(aoa_root, target)]
            if target != "all"
            else chronological_session_records(
                aoa_root,
                since=since,
                until=until,
                limit=limit,
            )
        )
    except ValueError as exc:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "session_memory_graph_freshness_gates",
            "generated_at": now,
            "ok": False,
            "diagnostics": [str(exc)],
            "gates": [],
        }
    selected_latest_source_mtime, selected_latest_source_paths = latest_index_source_mtime(aoa_root, records)
    selected_latest_graph_mtime, selected_latest_graph_paths = latest_graph_source_mtime(aoa_root, records)
    stable_mode = stable_quiet_seconds is not None
    gate_records = records
    gate_projection_fingerprints: list[dict[str, Any]] | None = None
    deferred_live_sessions: list[dict[str, Any]] = []
    quiescence: dict[str, Any] = {
        "enabled": False,
        "mode": "strict_full_selection",
        "selected_count": len(records),
        "checked_count": len(records),
        "deferred_live_session_count": 0,
    }
    if stable_mode:
        gate_records, gate_projection_fingerprints, deferred_live_sessions, quiescence = projection_quiescence_split(
            records,
            quiet_seconds=stable_quiet_seconds if stable_quiet_seconds is not None else 0.0,
            now_ts=now_ts,
        )
    latest_source_mtime, latest_source_paths = latest_index_source_mtime(aoa_root, gate_records)
    latest_graph_mtime, latest_graph_paths = latest_graph_source_mtime(aoa_root, gate_records)
    route_drift = route_index_drift_records(gate_records)
    declared_global_scope_complete = bool(
        isinstance(selection_scope, dict)
        and selection_scope.get("global_scope_complete") is True
    )
    global_selection = bool(
        graph_selection_is_global(
            target=target,
            since=since,
            until=until,
            limit=limit,
        )
        and (selected_records is None or declared_global_scope_complete)
    )
    graph_selection_global = global_selection and not deferred_live_sessions
    search_gate_projection_fingerprints = search_projection_fingerprints_for_records(gate_records) if stable_mode else None
    search_state = sqlite_search_index_state(
        aoa_root,
        latest_source_mtime,
        gate_records,
        projection_fingerprints=search_gate_projection_fingerprints,
        **(
            {"source_scope_complete": True}
            if graph_selection_global
            else {}
        ),
    )
    atlas_state = atlas_index_state(
        aoa_root,
        latest_source_mtime,
        gate_records,
        projection_fingerprints=gate_projection_fingerprints,
        **(
            {"source_scope_complete": True}
            if graph_selection_global
            else {}
        ),
    )
    store_state = graph_store_state(
        aoa_root=aoa_root,
        target=target,
        since=since,
        until=until,
        limit=limit,
        selected_records=(
            gate_records
            if stable_mode or selected_records is not None
            else None
        ),
        selected_records_global=(
            graph_selection_global
            if stable_mode or selected_records is not None
            else None
        ),
    )
    graph_state = graph_sidecar_state(
        aoa_root,
        latest_source_mtime=latest_graph_mtime,
        expected_session_count=len(gate_records) if graph_selection_global else None,
    )
    refs_state = evidence_ref_integrity_state(aoa_root, sample_limit=ref_sample_limit)
    entity_registry_state = entity_registry_maintenance_status(aoa_root)
    entity_registry_repair_needed = bool(entity_registry_state.get("needs_maintenance"))
    episode_semantic_state = episode_semantic_projection_state(aoa_root, records=gate_records)
    episode_semantic_repair_needed = bool(episode_semantic_state.get("needs_refresh"))
    episode_posting_cardinality_state = episode_direct_relation_postings_cardinality(aoa_root)
    episode_posting_cardinality_repair_needed = (
        int_value(episode_posting_cardinality_state.get("metadata_incomplete_session_count")) > 0
    )
    episode_dense_state = episode_dense_projection_state(aoa_root, records=gate_records)
    episode_dense_repair_needed = bool(episode_dense_state.get("needs_refresh"))
    graph_store_current_statuses = {"current", "current_with_blocked_sources", "current_with_retired_sources"}
    needs_index_maintenance = (
        bool(route_drift)
        or bool(search_state.get("needs_refresh"))
        or bool(atlas_state.get("needs_refresh"))
        or entity_registry_repair_needed
        or episode_semantic_repair_needed
        or episode_posting_cardinality_repair_needed
    )
    needs_graph_maintenance = bool(store_state.get("needs_maintenance")) or store_state.get("status") == "missing"
    needs_sidecar_export = bool(graph_state.get("needs_snapshot_refresh")) and store_state.get("status") in graph_store_current_statuses
    needs_graph_build = bool(store_state.get("needs_full_rebuild"))
    sidecar_gate_ok = graph_state.get("status") in {"current", "not_exported"}
    if entity_registry_repair_needed:
        diagnostics.append("entity_registry_missing_or_stale")
        diagnostics.extend(str(item) for item in entity_registry_state.get("diagnostics", []) if item)
    if episode_posting_cardinality_repair_needed:
        diagnostics.append("episode_posting_cardinality_metadata_missing_or_stale")
    gates = []
    if stable_mode:
        gates.append(
            {
                "name": "quiescent_session_subset",
                "ok": len(gate_records) > 0 or not records,
                "state": {
                    "selected_count": len(records),
                    "checked_count": len(gate_records),
                    "deferred_live_session_count": len(deferred_live_sessions),
                    "quiet_seconds": quiescence.get("quiet_seconds"),
                },
            }
        )
        gates.append(
            {
                "name": "live_sessions_deferred",
                "ok": True,
                "state": {
                    "deferred_live_session_count": len(deferred_live_sessions),
                    "note": "recently changed sessions are reported but not checked by stable mode",
                },
            }
        )
    gates.extend([
        {"name": "map_fresh", "ok": not route_drift and atlas_state.get("status") == "current", "state": {"route_drift_count": len(route_drift), "atlas_status": atlas_state.get("status")}},
        {"name": "search_fresh", "ok": search_state.get("status") == "current", "state": search_state},
        {"name": "entity_registry_fresh", "ok": not entity_registry_repair_needed, "state": entity_registry_state},
        {"name": "episode_semantic_projection_fresh", "ok": not episode_semantic_repair_needed, "state": episode_semantic_state},
        {"name": "episode_posting_cardinality_metadata_current", "ok": not episode_posting_cardinality_repair_needed, "state": episode_posting_cardinality_state},
        {"name": "graph_store_current", "ok": store_state.get("status") in graph_store_current_statuses, "state": store_state},
        {"name": "graph_sidecar_snapshot", "ok": sidecar_gate_ok, "state": graph_state},
        {"name": "refs_alive", "ok": refs_state.get("ok"), "state": refs_state},
        {"name": "index_maintenance_needed", "ok": not needs_index_maintenance, "state": {"needed": needs_index_maintenance}},
        {"name": "graph_maintenance_needed", "ok": not needs_graph_maintenance, "state": {"needed": needs_graph_maintenance}},
        {"name": "sidecar_export_needed", "ok": not needs_sidecar_export, "state": {"needed": needs_sidecar_export}},
        {"name": "offline_graph_build_needed", "ok": not needs_graph_build, "state": {"needed": needs_graph_build}},
    ])
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_graph_freshness_gates",
        "generated_at": now,
        "ok": not diagnostics and all(bool(gate.get("ok")) for gate in gates),
        "mutates": False,
        "truth_status": (
            "stable_quiescent_subset_gate_deferred_live_sessions_are_not_checked"
            if stable_mode
            else "bounded_selected_records_freshness_gate_not_global"
            if selected_records is not None
            else "strict_full_selection_freshness_gate"
        ),
        "target": target,
        "selection_source": (
            "provided_records"
            if selected_records is not None
            else "target_filters"
        ),
        "selection_scope": selection_scope or {},
        "global_scope_complete": graph_selection_global,
        "selected_count": len(records),
        "checked_count": len(gate_records),
        "deferred_live_session_count": len(deferred_live_sessions),
        "quiescence": quiescence,
        "deferred_live_sessions": deferred_live_sessions[:40],
        "selected_latest_source_mtime": selected_latest_source_mtime,
        "selected_latest_source_paths": selected_latest_source_paths,
        "selected_latest_graph_source_mtime": selected_latest_graph_mtime,
        "selected_latest_graph_source_paths": selected_latest_graph_paths,
        "latest_source_mtime": latest_source_mtime,
        "latest_source_paths": latest_source_paths,
        "latest_graph_source_mtime": latest_graph_mtime,
        "latest_graph_source_paths": latest_graph_paths,
        "route_drift_count": len(route_drift),
        "route_drift": route_drift[:20],
        "search_index": search_state,
        "atlas_index": atlas_state,
        "entity_registry": entity_registry_state,
        "episode_semantic_projection": episode_semantic_state,
        "episode_semantic_repair_needed": episode_semantic_repair_needed,
        "episode_posting_cardinality": episode_posting_cardinality_state,
        "episode_posting_cardinality_repair_needed": episode_posting_cardinality_repair_needed,
        "episode_dense_projection": episode_dense_state,
        "episode_dense_repair_needed": episode_dense_repair_needed,
        "needs_optional_dense_maintenance": episode_dense_repair_needed,
        "graph_store": store_state,
        "graph_sidecar": graph_state,
        "refs": refs_state,
        "needs_index_maintenance": needs_index_maintenance,
        "needs_graph_maintenance": needs_graph_maintenance,
        "needs_sidecar_export": needs_sidecar_export,
        "needs_offline_graph_build": needs_graph_build,
        "search_vs_graph": graph_state.get("search_vs_graph"),
        "gates": gates,
        "diagnostics": diagnostics,
        "next_route": "Use strict mode for full truth; use --stable only as a quiescent subset gate during live writes. Run index-maintenance when map/search/atlas gates fail; run graph-maintenance for dirty graph sources; export sidecar snapshots only for offline/debug/publication needs; run offline graph-build for schema/corruption recovery; inspect broken refs before synthesis.",
    }
    if write_report:
        diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
        diagnostics_dir.mkdir(parents=True, exist_ok=True)
        stem = f"{compact_stamp()}__graph-freshness-gates"
        report_json = diagnostics_dir / f"{stem}.json"
        report_md = diagnostics_dir / f"{stem}.md"
        write_json(report_json, payload)
        write_markdown(report_md, graph_freshness_gates_markdown(payload))
        payload["report_json"] = str(report_json)
        payload["report_markdown"] = str(report_md)
    return payload


def route_cache_freshness_markdown(payload: dict[str, Any]) -> str:
    lines = [
        "# Route Cache Freshness Gates",
        "",
        f"- generated_at: `{payload.get('generated_at')}`",
        f"- ok: `{payload.get('ok')}`",
        f"- target: `{payload.get('target')}`",
        f"- selected_count: `{payload.get('selected_count')}`",
        f"- needs_index_maintenance: `{payload.get('needs_index_maintenance')}`",
        f"- needs_graph_maintenance: `{payload.get('needs_graph_maintenance')}`",
        f"- search_index: `{(payload.get('search_index') or {}).get('status') if isinstance(payload.get('search_index'), dict) else ''}`",
        f"- atlas_index: `{(payload.get('atlas_index') or {}).get('status') if isinstance(payload.get('atlas_index'), dict) else ''}`",
        f"- entity_registry: `{(payload.get('entity_registry') or {}).get('status') if isinstance(payload.get('entity_registry'), dict) else ''}`",
        f"- episode_posting_cardinality: `{(payload.get('episode_posting_cardinality') or {}).get('status') if isinstance(payload.get('episode_posting_cardinality'), dict) else ''}` incomplete=`{(payload.get('episode_posting_cardinality') or {}).get('metadata_incomplete_session_count') if isinstance(payload.get('episode_posting_cardinality'), dict) else ''}`",
        f"- route_drift_count: `{payload.get('route_drift_count')}`",
        f"- graph_store: `{(payload.get('graph_store') or {}).get('status') if isinstance(payload.get('graph_store'), dict) else ''}`",
    ]
    diagnostics = payload.get("diagnostics") if isinstance(payload.get("diagnostics"), list) else []
    if diagnostics:
        lines.extend(["", "## Diagnostics", ""])
        lines.extend(f"- `{item}`" for item in diagnostics)
    warnings = payload.get("warnings") if isinstance(payload.get("warnings"), list) else []
    if warnings:
        lines.extend(["", "## Warnings", ""])
        lines.extend(f"- `{item}`" for item in warnings)
    return "\n".join(lines) + "\n"


def route_cache_freshness_gates(
    *,
    aoa_root: Path,
    target: str = "all",
    since: str | None = None,
    until: str | None = None,
    limit: int | None = None,
    write_report: bool = False,
    selected_records: list[dict[str, Any]] | None = None,
    selection_scope: dict[str, Any] | None = None,
) -> dict[str, Any]:
    now = utc_now()
    explicit_source_filters = target != "all" or since is not None or until is not None or limit is not None
    source_scan = selected_records is not None or explicit_source_filters
    records: list[dict[str, Any]] = []
    latest_source_mtime = 0.0
    latest_source_paths: list[str] = []
    route_drift: list[dict[str, Any]] = []
    if source_scan:
        try:
            records = (
                list(selected_records or [])
                if selected_records is not None
                else ([resolve_session_record(aoa_root, target)] if target != "all" else chronological_session_records(aoa_root, since=since, until=until, limit=limit))
            )
        except ValueError as exc:
            return {
                "schema_version": SCHEMA_VERSION,
                "artifact_type": "session_memory_route_cache_freshness_gates",
                "generated_at": now,
                "ok": False,
                "target": target,
                "selected_count": 0,
                "needs_index_maintenance": True,
                "needs_graph_maintenance": True,
                "needs_sidecar_export": False,
                "needs_offline_graph_build": False,
                "truth_status": "hot_route_cache_projection_scan_failed",
                "source_scan": True,
                "diagnostics": [str(exc)],
                "gates": [],
            }
        latest_source_mtime, latest_source_paths = latest_index_source_mtime(aoa_root, records)
        route_drift = route_index_drift_records(records)
        source_scope_complete = bool(
            graph_selection_is_global(
                target=target,
                since=since,
                until=until,
                limit=limit,
            )
            and (
                selected_records is None
                or (
                    isinstance(selection_scope, dict)
                    and selection_scope.get("global_scope_complete") is True
                )
            )
        )
        search_state = sqlite_search_index_state(
            aoa_root,
            latest_source_mtime,
            records,
            projection_fingerprints=search_projection_fingerprints_for_records(records),
            **(
                {"source_scope_complete": True}
                if source_scope_complete
                else {}
            ),
        )
        atlas_state = atlas_index_state(
            aoa_root,
            latest_source_mtime,
            records,
            **(
                {"source_scope_complete": True}
                if source_scope_complete
                else {}
            ),
        )
        truth_status = "hot_route_cache_bounded_projection_scan"
        selection_source = "provided_records" if selected_records is not None else "target_filters"
        selected_count = len(records)
    else:
        search_state = sqlite_search_index_hot_state(aoa_root)
        atlas_state = atlas_index_hot_state(aoa_root)
        truth_status = "hot_route_cache_cached_state_no_source_scan"
        selection_source = "cached_projection_state"
        selected_count = max(
            int_value(search_state.get("indexed_session_state_count")),
            int_value(atlas_state.get("projection_session_count")),
        )
    graph_hot_state = graph_store_hot_state(aoa_root)
    entity_registry_state = entity_registry_maintenance_status(aoa_root)
    entity_registry_repair_needed = bool(entity_registry_state.get("needs_maintenance"))
    episode_semantic_state = episode_semantic_projection_state(
        aoa_root,
        records=records if source_scan else None,
    )
    episode_semantic_repair_needed = bool(episode_semantic_state.get("needs_refresh"))
    episode_posting_cardinality_state = episode_direct_relation_postings_cardinality(aoa_root)
    episode_posting_cardinality_repair_needed = (
        int_value(episode_posting_cardinality_state.get("metadata_incomplete_session_count")) > 0
    )
    episode_dense_state = episode_dense_projection_state(
        aoa_root,
        records=records if source_scan else None,
    )
    episode_dense_repair_needed = bool(episode_dense_state.get("needs_refresh"))
    search_shards_state = session_memory_search_shard_projection_summary(aoa_root)
    has_existing_search_shards = (
        int_value(search_shards_state.get("existing_shard_count")) > 0
        or int_value(search_shards_state.get("shard_db_total_bytes")) > 0
    )
    search_shards_repair_needed = (
        has_existing_search_shards
        and (
            str(search_shards_state.get("status") or "") in {"incomplete", "stale"}
            or int_value(search_shards_state.get("actionable_noncurrent_shard_count")) > 0
        )
    )
    operational_route_rollup_state = session_memory_operational_route_rollup_status(
        aoa_root=aoa_root,
        search_shards=search_shards_state,
    )
    operational_route_rollup_repair_needed = (
        bool(operational_route_rollup_state.get("needs_refresh"))
        and str(search_shards_state.get("status") or "") in {"current", "current_with_deferred_live_updates"}
    )
    needs_index_maintenance = (
        bool(route_drift)
        or bool(search_state.get("needs_refresh"))
        or bool(atlas_state.get("needs_refresh"))
        or entity_registry_repair_needed
        or episode_semantic_repair_needed
        or episode_posting_cardinality_repair_needed
        or search_shards_repair_needed
        or operational_route_rollup_repair_needed
    )
    needs_graph_maintenance = bool(graph_hot_state.get("needs_maintenance")) or graph_hot_state.get("status") in {"missing", "stale"}
    diagnostics = ["index_maintenance_needed"] if needs_index_maintenance else []
    if entity_registry_repair_needed:
        diagnostics.append("entity_registry_missing_or_stale")
        diagnostics.extend(str(item) for item in entity_registry_state.get("diagnostics", []) if item)
    if episode_semantic_repair_needed:
        diagnostics.append("episode_semantic_projection_missing_or_stale")
        diagnostics.extend(str(item) for item in episode_semantic_state.get("diagnostics", []) if item)
    if episode_posting_cardinality_repair_needed:
        diagnostics.append("episode_posting_cardinality_metadata_missing_or_stale")
    if search_shards_repair_needed:
        diagnostics.append("search_shards_incomplete_or_stale")
        diagnostics.extend(str(item) for item in search_shards_state.get("diagnostics", []) if item)
    if operational_route_rollup_repair_needed:
        diagnostics.append("operational_route_rollup_missing_or_stale")
        diagnostics.extend(str(item) for item in operational_route_rollup_state.get("diagnostics", []) if item)
    if needs_graph_maintenance:
        diagnostics.append("graph_maintenance_needed")
    diagnostics.extend(str(item) for item in search_state.get("diagnostics", []) if item)
    diagnostics.extend(str(item) for item in atlas_state.get("diagnostics", []) if item)
    diagnostics.extend(str(item) for item in graph_hot_state.get("diagnostics", []) if item)
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_route_cache_freshness_gates",
        "generated_at": now,
        "ok": not needs_index_maintenance and not needs_graph_maintenance,
        "truth_status": truth_status,
        "source_scan": source_scan,
        "target": target,
        "since": since,
        "until": until,
        "limit": limit,
        "selection_source": selection_source,
        "selection_scope": selection_scope
        or (
            {"mode": selection_source, "source_filters_applied": explicit_source_filters}
            if source_scan
            else {"mode": "cached_projection_state_all_hot", "source_filters_applied": False}
        ),
        "selected_count": selected_count,
        "needs_index_maintenance": needs_index_maintenance,
        "needs_graph_maintenance": needs_graph_maintenance,
        "needs_sidecar_export": False,
        "needs_offline_graph_build": bool(graph_hot_state.get("needs_full_rebuild")),
        "search_vs_graph": None,
        "latest_source_mtime": latest_source_mtime,
        "latest_source_paths": latest_source_paths,
        "route_drift_count": len(route_drift),
        "route_drift": route_drift[:40],
        "search_index": search_state,
        "atlas_index": atlas_state,
        "entity_registry": entity_registry_state,
        "entity_registry_repair_needed": entity_registry_repair_needed,
        "episode_semantic_projection": episode_semantic_state,
        "episode_semantic_repair_needed": episode_semantic_repair_needed,
        "episode_posting_cardinality": episode_posting_cardinality_state,
        "episode_posting_cardinality_repair_needed": episode_posting_cardinality_repair_needed,
        "episode_dense_projection": episode_dense_state,
        "episode_dense_repair_needed": episode_dense_repair_needed,
        "needs_optional_dense_maintenance": episode_dense_repair_needed,
        "search_shards": search_shards_state,
        "search_shards_repair_needed": search_shards_repair_needed,
        "operational_route_rollup": operational_route_rollup_state,
        "operational_route_rollup_repair_needed": operational_route_rollup_repair_needed,
        "graph_store": graph_hot_state,
        "diagnostics": diagnostics,
    }
    if write_report:
        diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
        diagnostics_dir.mkdir(parents=True, exist_ok=True)
        stem = f"{compact_stamp()}__route-cache-freshness-gates"
        report_json = diagnostics_dir / f"{stem}.json"
        report_md = diagnostics_dir / f"{stem}.md"
        write_json(report_json, payload)
        write_markdown(report_md, route_cache_freshness_markdown(payload))
        payload["report_json"] = str(report_json)
        payload["report_markdown"] = str(report_md)
    return payload


def latest_diagnostic_summary(aoa_root: Path, glob_pattern: str, *, exclude_markers: Iterable[str] = ()) -> dict[str, Any]:
    diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
    excluded = tuple(str(marker) for marker in exclude_markers if str(marker))
    candidates = sorted(
        (
            path
            for path in diagnostics_dir.glob(glob_pattern)
            if path.is_file()
            and path.suffix == ".json"
            and not any(marker in str(path) for marker in excluded)
        ),
        key=lambda path: path.stat().st_mtime if path.exists() else 0.0,
        reverse=True,
    )
    if not candidates:
        return {"exists": False, "pattern": glob_pattern}
    path = candidates[0]
    payload = read_json(path, {})
    payload = payload if isinstance(payload, dict) else {}
    markdown = path.with_suffix(".md")
    return {
        "exists": True,
        "pattern": glob_pattern,
        "path": str(path),
        "markdown": str(markdown) if markdown.exists() else "",
        "mtime": path_mtime(path),
        "artifact_type": payload.get("artifact_type"),
        "generated_at": payload.get("generated_at"),
        "ok": payload.get("ok"),
        "status": payload.get("status"),
        "diagnostics": payload.get("diagnostics", []) if isinstance(payload.get("diagnostics"), list) else [],
    }


def systemd_unit_execstart_lines(unit_text: str) -> list[str]:
    lines: list[str] = []
    for raw_line in str(unit_text or "").splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#") or not line.startswith("ExecStart="):
            continue
        value = line.split("=", 1)[1].strip()
        if value:
            lines.append(value)
    return lines


def argv_flag_value(argv: list[str], flag: str) -> str | None:
    if flag not in argv:
        return None
    index = argv.index(flag)
    if index + 1 >= len(argv):
        return ""
    return str(argv[index + 1])


def numeric_graph_drip_values_match(observed: str | None, expected: Any) -> bool:
    if observed is None:
        return True
    try:
        return float(observed) == float(expected)
    except (TypeError, ValueError):
        return str(observed) == str(expected)


def session_memory_resource_unit_contract(service: str, unit_text: str) -> dict[str, Any]:
    profile = SESSION_MEMORY_RESOURCE_MAINTENANCE_UNITS.get(service)
    if not profile:
        return {
            "service": service,
            "status": "not_session_memory_resource_unit",
            "diagnostics": [],
        }
    settings = AUTO_MAINTENANCE_PROFILES.get(profile, {})
    diagnostics: list[str] = []
    execstart_lines = systemd_unit_execstart_lines(unit_text)
    command_line = next((line for line in execstart_lines if "auto-maintenance-resource" in line), "")
    argv: list[str] = []
    observed_profile = ""
    if not command_line:
        diagnostics.append("systemd_unit_missing_auto_maintenance_resource_execstart")
    else:
        try:
            argv = shlex.split(command_line)
        except ValueError as exc:
            diagnostics.append(f"systemd_unit_execstart_parse_failed:{exc}")
        if argv and "auto-maintenance-resource" in argv:
            index = argv.index("auto-maintenance-resource")
            observed_profile = argv[index + 1] if index + 1 < len(argv) else ""
            if observed_profile != profile:
                diagnostics.append(f"systemd_unit_profile_mismatch:{observed_profile or 'missing'}")
        elif argv:
            diagnostics.append("systemd_unit_missing_auto_maintenance_resource_command")

    expected_graph_drip_on_block = bool(settings.get("graph_drip_on_block"))
    if argv:
        if "--no-graph-drip-on-block" in argv and expected_graph_drip_on_block:
            diagnostics.append("systemd_unit_disables_profile_graph_drip")
        if "--graph-drip-on-block" in argv and not expected_graph_drip_on_block:
            diagnostics.append("systemd_unit_enables_graph_drip_against_profile")

    observed_overrides: dict[str, str] = {}
    mismatched_overrides: list[dict[str, Any]] = []
    for flag, key in SESSION_MEMORY_GRAPH_DRIP_OVERRIDE_FLAGS.items():
        value = argv_flag_value(argv, flag) if argv else None
        if value is None:
            continue
        observed_overrides[key] = value
        expected = settings.get(key)
        if expected is None:
            diagnostics.append(f"systemd_unit_unexpected_graph_drip_override:{key}")
            mismatched_overrides.append({"key": key, "observed": value, "expected": None})
        elif not numeric_graph_drip_values_match(value, expected):
            diagnostics.append(f"systemd_unit_stale_graph_drip_override:{key}")
            mismatched_overrides.append({"key": key, "observed": value, "expected": expected})

    return {
        "service": service,
        "profile": profile,
        "status": "drift" if diagnostics else "current",
        "command_line": command_line,
        "observed_profile": observed_profile,
        "expected_graph_drip_on_block": expected_graph_drip_on_block,
        "explicit_graph_drip_overrides": observed_overrides,
        "mismatched_graph_drip_overrides": mismatched_overrides,
        "profile_graph_drip_defaults": {
            key: settings.get(key)
            for key in SESSION_MEMORY_GRAPH_DRIP_OVERRIDE_FLAGS.values()
            if key in settings
        },
        "diagnostics": diagnostics,
        "truth_status": "installed_systemd_unit_contract_projection",
    }


def session_memory_unit_file_contracts(unit_dir: Path | None = None) -> list[dict[str, Any]]:
    root = unit_dir or (Path.home() / ".config" / "systemd" / "user")
    contracts: list[dict[str, Any]] = []
    for service in sorted(SESSION_MEMORY_RESOURCE_MAINTENANCE_UNITS):
        path = root / service
        if not path.exists():
            continue
        try:
            text = path.read_text(encoding="utf-8")
        except OSError as exc:
            contracts.append(
                {
                    "service": service,
                    "status": "probe_failed",
                    "path": str(path),
                    "diagnostics": [f"{exc.__class__.__name__}:{exc}"],
                }
            )
            continue
        contract = session_memory_resource_unit_contract(service, text)
        contract["path"] = str(path)
        contract["probe_source"] = "unit_file"
        contracts.append(contract)
    return contracts


def session_memory_unit_contract_diagnostics(contracts: list[dict[str, Any]]) -> list[str]:
    diagnostics: list[str] = []
    for contract in contracts:
        service = str(contract.get("service") or "")
        for diagnostic in contract.get("diagnostics", []) if isinstance(contract.get("diagnostics"), list) else []:
            diagnostics.append(f"{service}:{diagnostic}" if service else str(diagnostic))
    return diagnostics


def systemd_show_property_blocks(text: str) -> list[dict[str, str]]:
    blocks: list[dict[str, str]] = []
    current: dict[str, str] = {}
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped:
            if current:
                blocks.append(current)
                current = {}
            continue
        if "=" not in stripped:
            continue
        key, value = stripped.split("=", 1)
        current[key] = value
    if current:
        blocks.append(current)
    return blocks


def session_memory_timer_runtime_states(
    executable: str,
    timers: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[str], list[str]]:
    units = sorted(
        {
            str(timer.get("unit") or "")
            for timer in timers
            if str(timer.get("unit") or "") and bool(timer.get("next_schedule_missing"))
        }
    )
    if not units:
        return [], [], []
    command = [
        executable,
        "--user",
        "show",
        *units,
        "-p",
        "Id",
        "-p",
        "ActiveState",
        "-p",
        "SubState",
        "-p",
        "NextElapseUSecRealtime",
        "-p",
        "NextElapseUSecMonotonic",
        "-p",
        "LastTriggerUSec",
        "-p",
        "Result",
    ]
    try:
        completed = subprocess.run(command, check=False, capture_output=True, text=True, timeout=3)
    except (OSError, subprocess.TimeoutExpired) as exc:
        return [], [f"systemd_timer_runtime_probe_failed:{exc.__class__.__name__}:{exc}"], []
    if completed.returncode != 0:
        return (
            [],
            [f"systemd_timer_runtime_probe_failed:returncode:{completed.returncode}"],
            [(completed.stderr or "").strip()[:500]],
        )
    states: list[dict[str, Any]] = []
    diagnostics: list[str] = []
    for block in systemd_show_property_blocks(completed.stdout or ""):
        unit = str(block.get("Id") or "")
        active_state = str(block.get("ActiveState") or "")
        sub_state = str(block.get("SubState") or "")
        next_realtime = str(block.get("NextElapseUSecRealtime") or "")
        next_monotonic = str(block.get("NextElapseUSecMonotonic") or "")
        next_schedule_missing = not next_realtime and next_monotonic in {"", "infinity"}
        state_diagnostics: list[str] = []
        if active_state != "active":
            state_diagnostics.append(f"systemd_timer_not_active:{unit or 'unknown'}:{active_state or 'unknown'}")
        elif sub_state == "elapsed" and next_schedule_missing:
            state_diagnostics.append(f"systemd_timer_elapsed_without_next:{unit or 'unknown'}")
        diagnostics.extend(state_diagnostics)
        states.append(
            {
                "unit": unit,
                "active_state": active_state,
                "sub_state": sub_state,
                "next_elapse_realtime": next_realtime,
                "next_elapse_monotonic": next_monotonic,
                "last_trigger": str(block.get("LastTriggerUSec") or ""),
                "result": str(block.get("Result") or ""),
                "next_schedule_missing": next_schedule_missing,
                "diagnostics": state_diagnostics,
            }
        )
    observed_units = {str(state.get("unit") or "") for state in states}
    for unit in units:
        if unit not in observed_units:
            diagnostics.append(f"systemd_timer_runtime_state_missing:{unit}")
    return states, diagnostics, []


def session_memory_timer_status() -> dict[str, Any]:
    executable = shutil.which("systemctl")
    if not executable:
        return {"ok": True, "status": "systemctl_unavailable", "timers": [], "diagnostics": ["systemctl not found"]}
    command = [executable, "--user", "list-timers", "--all", "*aoa-session-memory*", "--no-legend", "--no-pager"]
    try:
        completed = subprocess.run(command, check=False, capture_output=True, text=True, timeout=3)
    except (OSError, subprocess.TimeoutExpired) as exc:
        return {"ok": False, "status": "timer_probe_failed", "timers": [], "diagnostics": [f"{exc.__class__.__name__}:{exc}"]}
    timers: list[dict[str, Any]] = []
    for line in (completed.stdout or "").splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        parts = stripped.split()
        unit = next((part for part in parts if part.endswith(".timer")), "")
        service = next((part for part in parts if part.endswith(".service")), "")
        timers.append(
            {
                "line": stripped,
                "unit": unit,
                "service": service,
                "next_schedule_missing": stripped.startswith("-"),
            }
        )
    unit_contracts: list[dict[str, Any]] = []
    contract_diagnostics: list[str] = []
    if completed.returncode != 0:
        unit_contracts = session_memory_unit_file_contracts()
        contract_diagnostics = session_memory_unit_contract_diagnostics(unit_contracts)
        fallback_status = "unit_file_fallback_with_unit_drift" if contract_diagnostics else "unit_file_fallback"
        return {
            "ok": not contract_diagnostics,
            "status": fallback_status,
            "command": shlex.join(command),
            "timer_count": 0,
            "timers": [],
            "unit_contracts": unit_contracts,
            "stderr": (completed.stderr or "").strip()[:500],
            "systemctl_returncode": completed.returncode,
            "warnings": [f"systemctl_timer_probe_unavailable:{completed.returncode}"],
            "diagnostics": contract_diagnostics,
        }
    else:
        services = sorted(
            {
                str(timer.get("service") or "")
                for timer in timers
                if str(timer.get("service") or "") in SESSION_MEMORY_RESOURCE_MAINTENANCE_UNITS
            }
        )
        for service in services:
            cat_command = [executable, "--user", "cat", service]
            try:
                cat_completed = subprocess.run(cat_command, check=False, capture_output=True, text=True, timeout=3)
            except (OSError, subprocess.TimeoutExpired) as exc:
                unit_contracts.append(
                    {
                        "service": service,
                        "status": "probe_failed",
                        "command": shlex.join(cat_command),
                        "diagnostics": [f"{exc.__class__.__name__}:{exc}"],
                    }
                )
                contract_diagnostics.append(f"systemd_unit_contract_probe_failed:{service}")
                continue
            contract = session_memory_resource_unit_contract(service, cat_completed.stdout or "")
            contract["command"] = shlex.join(cat_command)
            contract["cat_returncode"] = cat_completed.returncode
            contract["stderr"] = (cat_completed.stderr or "").strip()[:500]
            if cat_completed.returncode != 0:
                contract["status"] = "probe_failed"
                contract.setdefault("diagnostics", []).append(f"systemctl_cat_returncode:{cat_completed.returncode}")
            unit_contracts.append(contract)
        contract_diagnostics = session_memory_unit_contract_diagnostics(unit_contracts)
    timer_runtime_states, timer_runtime_diagnostics, timer_runtime_warnings = session_memory_timer_runtime_states(
        executable,
        timers,
    )
    diagnostics = [*contract_diagnostics, *timer_runtime_diagnostics]
    status = "systemctl_error"
    if completed.returncode == 0:
        if contract_diagnostics and timer_runtime_diagnostics:
            status = "available_with_timer_and_unit_drift"
        elif contract_diagnostics:
            status = "available_with_unit_drift"
        elif timer_runtime_diagnostics:
            status = "available_with_timer_drift"
        else:
            status = "available"
    return {
        "ok": completed.returncode == 0 and not diagnostics,
        "status": status,
        "command": shlex.join(command),
        "timer_count": len(timers),
        "timers": timers[:12],
        "timer_runtime_states": timer_runtime_states,
        "unit_contracts": unit_contracts,
        "stderr": (completed.stderr or "").strip()[:500],
        "warnings": timer_runtime_warnings,
        "diagnostics": diagnostics,
    }


def graph_maintenance_status_from_state(
    graph_state: dict[str, Any],
    *,
    workspace_root: Path | str = "/path/to/workspace",
    aoa_root: Path | str = "/path/to/workspace/.aoa",
) -> dict[str, Any]:
    source_state = graph_state.get("source_state") if isinstance(graph_state.get("source_state"), dict) else {}
    ledger = graph_state.get("ledger") if isinstance(graph_state.get("ledger"), dict) else {}
    queue = graph_state.get("queue") if isinstance(graph_state.get("queue"), dict) else {}
    latest_maintenance = graph_state.get("latest_maintenance") if isinstance(graph_state.get("latest_maintenance"), dict) else {}
    latest_queue_maintenance = graph_state.get("latest_queue_maintenance") if isinstance(graph_state.get("latest_queue_maintenance"), dict) else {}
    source_version_state = graph_state.get("source_version_state") if isinstance(graph_state.get("source_version_state"), dict) else {}
    status_counts = (
        source_state.get("status_counts")
        if isinstance(source_state.get("status_counts"), dict)
        else ledger.get("status_counts") if isinstance(ledger.get("status_counts"), dict) else {}
    )
    source_version_mismatch_count = int_value(source_version_state.get("version_mismatch_source_count"))
    ledger_store_missing_total_count = int_value(ledger.get("store_missing_source_estimate"))
    ledger_store_missing_count = int_value(
        ledger.get("actionable_store_missing_source_estimate", ledger_store_missing_total_count)
    )
    ledger_store_missing_deferred_count = int_value(ledger.get("deferred_store_missing_source_estimate"))
    latest_remaining_total_count = int_value(latest_maintenance.get("remaining_count")) if latest_maintenance.get("usable_for_hot_gate") else 0
    latest_remaining_count = int_value(
        latest_maintenance.get("actionable_remaining_count", latest_remaining_total_count)
    )
    dirty_count = int_value(source_state.get("dirty_count")) + source_version_mismatch_count
    missing_count = max(int_value(source_state.get("missing_count")) + ledger_store_missing_count, latest_remaining_count)
    blocked_count = int_value(source_state.get("blocked_count"))
    retired_count = int_value(source_state.get("retired_count") or ledger.get("retired_count"))
    actionable_count = (
        int_value(ledger.get("actionable_count"))
        + int_value(queue.get("actionable_count"))
        + source_version_mismatch_count
        + ledger_store_missing_count
    )
    actionable_count = max(actionable_count, latest_remaining_count)
    deferred_live_count = int_value(ledger.get("deferred_live_source_count")) + int_value(queue.get("deferred_live_source_count"))
    if actionable_count and dirty_count <= 0 and missing_count <= 0:
        dirty_count = actionable_count
    reason_group_counts: dict[str, int] = {}
    source_reason_group_counts = source_version_state.get("reason_group_counts")
    if isinstance(source_reason_group_counts, dict):
        for reason, count in source_reason_group_counts.items():
            reason_group_counts[str(reason)] = int_value(count)
    if ledger_store_missing_count:
        reason_group_counts["graph_source_ledger_store_count_mismatch"] = ledger_store_missing_count
    if latest_remaining_count:
        reason_group_counts["latest_graph_maintenance_remaining_sources"] = latest_remaining_count
    for reason in graph_state.get("diagnostics", []) if isinstance(graph_state.get("diagnostics"), list) else []:
        if reason in {"graph_store_nodes_empty", "graph_store_edges_empty", "graph_store_schema_mismatch", "graph_schema_mismatch"}:
            reason_group_counts[str(reason)] = max(1, int_value(reason_group_counts.get(str(reason))))
    maintenance_recommendation = graph_source_maintenance_recommendation(
        source_count=max(
            int_value(graph_state.get("source_count")),
            int_value(source_state.get("source_count")),
            int_value(source_version_state.get("source_count")),
            int_value(ledger.get("source_count")),
        ),
        existing_source_count=int_value(graph_state.get("source_count")),
        dirty_count=dirty_count,
        missing_count=missing_count,
        orphaned_count=int_value(source_state.get("orphaned_count")),
        blocked_count=blocked_count,
        reason_group_counts=reason_group_counts,
        workspace_root=str(workspace_root),
        aoa_root=str(aoa_root),
        latest_maintenance=latest_maintenance,
    )
    latest_maintenance_status = {
        key: latest_maintenance.get(key)
        for key in [
            "exists",
            "path",
            "mtime",
            "ok",
            "apply",
            "target",
            "scope_is_global",
            "selection_scope",
            "remaining_count",
            "actionable_remaining_count",
            "selected_count",
            "batch_limit",
            "candidate_pool_limit",
            "max_refresh_nodes",
            "max_refresh_edges",
            "budget_exhausted",
            "elapsed_ms",
            "aggregate_refresh_ms",
            "mutation_rolled_back",
            "usable_for_hot_gate",
            "queue_queued_count",
            "budget_deferred_source_count",
            "time_budget_deferred_source_count",
        ]
        if key in latest_maintenance
    }
    latest_queue_maintenance_status = {
        key: latest_queue_maintenance.get(key)
        for key in [
            "exists",
            "path",
            "mtime",
            "ok",
            "apply",
            "target",
            "selection_scope",
            "scope_is_global",
            "use_queue",
            "remaining_count",
            "selected_count",
            "batch_limit",
            "candidate_pool_limit",
            "max_refresh_nodes",
            "max_refresh_edges",
            "budget_exhausted",
            "elapsed_ms",
            "aggregate_refresh_ms",
            "mutation_rolled_back",
            "queue_queued_count",
            "queue_removed_count",
            "budget_deferred_source_count",
            "time_budget_deferred_source_count",
        ]
        if key in latest_queue_maintenance
    }
    return {
        "status": graph_state.get("status"),
        "needs_maintenance": bool(graph_state.get("needs_maintenance")),
        "needs_full_rebuild": bool(graph_state.get("needs_full_rebuild")),
        "source_count": graph_state.get("source_count") or source_state.get("source_count") or source_version_state.get("source_count"),
        "existing_source_count": int_value(graph_state.get("source_count")),
        "status_counts": status_counts,
        "dirty_count": dirty_count,
        "missing_count": missing_count,
        "blocked_count": blocked_count,
        "retired_count": retired_count,
        "actionable_count": actionable_count,
        "queued_count": int_value(queue.get("queued_count")),
        "ledger_store_missing_count": ledger_store_missing_count,
        "ledger_store_missing_total_count": ledger_store_missing_total_count,
        "deferred_ledger_store_missing_count": ledger_store_missing_deferred_count,
        "latest_maintenance_remaining_count": latest_remaining_count,
        "latest_maintenance_remaining_total_count": latest_remaining_total_count,
        "latest_maintenance": latest_maintenance_status,
        "latest_queue_maintenance": latest_queue_maintenance_status,
        "deferred_live_source_count": deferred_live_count,
        "deferred_live_sources_sample": [
            item
            for item in [
                *(ledger.get("deferred_live_sources_sample", []) if isinstance(ledger.get("deferred_live_sources_sample"), list) else []),
                *(queue.get("deferred_live_sources_sample", []) if isinstance(queue.get("deferred_live_sources_sample"), list) else []),
            ][:16]
            if isinstance(item, dict)
        ],
        "source_version_state": source_version_state,
        "reason_group_counts": reason_group_counts,
        "maintenance_recommendation": maintenance_recommendation,
        "truth_status": graph_state.get("truth_status"),
        "diagnostics": graph_state.get("diagnostics", []) if isinstance(graph_state.get("diagnostics"), list) else [],
    }


def search_maintenance_status_from_provider(provider_status: dict[str, Any]) -> dict[str, Any]:
    providers = provider_status.get("providers") if isinstance(provider_status.get("providers"), dict) else {}
    portable = providers.get("portable_sqlite") if isinstance(providers.get("portable_sqlite"), dict) else {}
    freshness = portable.get("freshness") if isinstance(portable.get("freshness"), dict) else {}
    raw_lexical_policy = portable.get("raw_lexical_policy") if isinstance(portable.get("raw_lexical_policy"), dict) else {}
    storage_policy_status = search_raw_lexical_policy_status(raw_lexical_policy)
    return {
        "status": freshness.get("status") or portable.get("status"),
        "provider_status": portable.get("status"),
        "freshness_mode": provider_status.get("freshness_mode") or provider_status.get("status_mode"),
        "count_mode": portable.get("count_mode"),
        "has_documents": portable.get("has_documents"),
        "has_route_index": portable.get("has_route_index"),
        "has_route_terms": portable.get("has_route_terms"),
        "metadata": portable.get("metadata") if isinstance(portable.get("metadata"), dict) else {},
        "raw_lexical_policy": raw_lexical_policy,
        "storage_policy_status": storage_policy_status,
        "needs_storage_policy_rebuild": storage_policy_status != "bounded_policy_recorded",
        "actionable_dirty_session_count": int_value(freshness.get("actionable_dirty_session_count")),
        "deferred_live_session_count": int_value(freshness.get("deferred_live_session_count")),
        "dirty_session_count": int_value(freshness.get("dirty_session_count")),
        "missing_freshness_state_count": int_value(freshness.get("missing_freshness_state_count")),
        "actionable_dirty_sessions": freshness.get("actionable_dirty_sessions", [])[:8]
        if isinstance(freshness.get("actionable_dirty_sessions"), list)
        else [],
        "deferred_live_sessions": freshness.get("deferred_live_sessions", [])[:8]
        if isinstance(freshness.get("deferred_live_sessions"), list)
        else [],
        "reasons": freshness.get("reasons", []) if isinstance(freshness.get("reasons"), list) else [],
        "diagnostics": portable.get("diagnostics", []) if isinstance(portable.get("diagnostics"), list) else [],
    }


def maintenance_light_sqlite_size(db_path: Path) -> dict[str, Any]:
    entry = storage_size_entry(db_path, label=db_path.name)
    wal_path = Path(str(db_path) + "-wal")
    shm_path = Path(str(db_path) + "-shm")
    wal_size = path_total_size(wal_path)
    shm_size = path_total_size(shm_path)
    entry.update(
        {
            "kind": "sqlite",
            "wal": {
                "path": str(wal_path),
                "exists": wal_path.exists(),
                "size_bytes": wal_size,
                "size_human": human_size(wal_size),
            },
            "shm": {
                "path": str(shm_path),
                "exists": shm_path.exists(),
                "size_bytes": shm_size,
                "size_human": human_size(shm_size),
            },
            "total_with_wal_bytes": int_value(entry.get("size_bytes")) + wal_size + shm_size,
            "total_with_wal_human": human_size(int_value(entry.get("size_bytes")) + wal_size + shm_size),
        }
    )
    return entry


def maintenance_storage_status(aoa_root: Path) -> dict[str, Any]:
    search_db = search_db_path(aoa_root)
    graph_db = graph_paths(aoa_root)["store"]
    search_root = aoa_root / SEARCH_ROOT
    graph_root = aoa_root / GRAPH_ROOT
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_maintenance_storage_status",
        "generated_at": utc_now(),
        "search_db": maintenance_light_sqlite_size(search_db),
        "graph_db": maintenance_light_sqlite_size(graph_db),
        "search_root": storage_size_entry(search_root, label="search"),
        "graph_root": storage_size_entry(graph_root, label="graph"),
        "search_rebuild_temps": search_rebuild_tmp_status(
            aoa_root
        ),
        "graph_rebuild_temps": graph_rebuild_tmp_status(aoa_root),
        "session_projection_stages": (
            session_projection_stage_status(
                aoa_root,
                include_unowned_content_digest=False,
                include_raw_authority_verification=False,
            )
        ),
    }


def maintenance_sqlite_size_brief(entry: dict[str, Any]) -> dict[str, Any]:
    return {
        key: entry.get(key)
        for key in (
            "path",
            "exists",
            "size_bytes",
            "size_human",
            "total_with_wal_bytes",
            "total_with_wal_human",
        )
        if key in entry
    }


def search_shard_materialization_ops_summary(report: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(report, dict) or not report:
        return {"exists": False}
    elapsed_ms = int_value(report.get("elapsed_ms"))
    document_count = int_value(report.get("document_count"))
    processed_count = int_value(report.get("processed_count"))
    elapsed_seconds = elapsed_ms / 1000.0 if elapsed_ms > 0 else 0.0
    shards = report.get("shards") if isinstance(report.get("shards"), list) else []
    slow_sessions = report.get("slow_sessions") if isinstance(report.get("slow_sessions"), list) else []
    slow_session_warning_count = report.get("slow_session_warning_count")
    if slow_session_warning_count is None:
        slow_session_warning_count = sum(1 for item in slow_sessions if isinstance(item, dict) and item.get("warning"))
    return {
        "exists": True,
        "source": diagnostic_report_source(report),
        "ok": report.get("ok"),
        "status": report.get("status"),
        "target": report.get("target"),
        "requested_shard": report.get("requested_shard"),
        "selected_count": report.get("selected_count"),
        "processed_count": processed_count,
        "budget_exhausted": bool(
            report.get("budget_exhausted")
            or any("budget_exhausted" in str(item) for item in report.get("diagnostics", []) if item)
        ),
        "partial": report.get("partial"),
        "dirty_only": report.get("dirty_only"),
        "dirty_candidate_count": report.get("dirty_candidate_count"),
        "dirty_selected_count": report.get("dirty_selected_count"),
        "dirty_pre_limit_selected_count": report.get("dirty_pre_limit_selected_count"),
        "dirty_limit": report.get("dirty_limit"),
        "dirty_limited_count": report.get("dirty_limited_count"),
        "shard_count": report.get("shard_count"),
        "document_count": document_count,
        "document_counts": report.get("document_counts") if isinstance(report.get("document_counts"), dict) else {},
        "event_document_count": report.get("event_document_count"),
        "event_document_ratio": report.get("event_document_ratio"),
        "elapsed_ms": elapsed_ms if elapsed_ms > 0 else report.get("elapsed_ms"),
        "documents_per_second": round(document_count / elapsed_seconds, 2)
        if elapsed_seconds > 0 and document_count > 0
        else report.get("documents_per_second"),
        "sessions_per_second": round(processed_count / elapsed_seconds, 3)
        if elapsed_seconds > 0 and processed_count > 0
        else report.get("sessions_per_second"),
        "slow_sessions": search_slow_session_rows(slow_sessions),
        "slow_session_warning_count": slow_session_warning_count,
        "slow_session_threshold_ms": report.get("slow_session_threshold_ms"),
        "structured_only": report.get("structured_only"),
        "shard_storage_mode": report.get("shard_storage_mode"),
        "search_fts_storage_mode": report.get("search_fts_storage_mode"),
        "raw_text_query_support": report.get("raw_text_query_support"),
        "requested_context_tail_omission_policy": report.get("requested_context_tail_omission_policy"),
        "context_tail_omission_policy": report.get("context_tail_omission_policy"),
        "context_tail_omission_policy_resolution": report.get("context_tail_omission_policy_resolution")
        if isinstance(report.get("context_tail_omission_policy_resolution"), dict)
        else {},
        "search_document_storage_profile": report.get("search_document_storage_profile"),
        "search_body_preview_chars": report.get("search_body_preview_chars"),
        "search_route_signals_preview_chars": report.get("search_route_signals_preview_chars"),
        "search_tags_preview_chars": report.get("search_tags_preview_chars"),
        "search_tags_storage_policy": report.get("search_tags_storage_policy"),
        "shards": [
            {
                key: item.get(key)
                for key in (
                    "shard",
                    "status",
                    "ok",
                    "session_count",
                    "processed_count",
                    "remaining_count",
                    "budget_exhausted",
                    "document_count",
                    "document_counts",
                    "event_document_count",
                    "elapsed_ms",
                    "documents_per_second",
                    "slow_session_warning_count",
                    "db_path",
                    "context_tail_omission_policy",
                    "search_document_storage_profile",
                    "search_body_preview_chars",
                    "search_tags_storage_policy",
                )
                if isinstance(item, dict) and key in item
            }
            for item in shards[:8]
            if isinstance(item, dict)
        ],
        "diagnostics": report.get("diagnostics", []) if isinstance(report.get("diagnostics"), list) else [],
    }


def search_shard_fast_path_defaults(
    *,
    status: str,
    shard_count: int,
    materialized_shard_count: int,
    shard_rows: list[dict[str, Any]],
) -> dict[str, Any]:
    shard_fanout_ready = (
        status == "current"
        and shard_count > 0
        and materialized_shard_count == shard_count
    ) or status == "current_with_deferred_live_updates"
    raw_text_support = {
        str(item.get("raw_text_query_support") or "")
        for item in shard_rows
        if isinstance(item, dict) and item.get("raw_text_query_support")
    }
    raw_text_shards_ready = shard_fanout_ready and raw_text_support == {SEARCH_RAW_TEXT_QUERY_SUPPORT_FULL}
    default_projection = SEARCH_ACTIVE_PROJECTION_SHARD_FANOUT if shard_fanout_ready else SEARCH_ACTIVE_PROJECTION_MONOLITH
    return {
        "agent_event_routes": {
            "default_use_shards": True,
            "default_projection": default_projection,
            "readiness": status,
            "shard_fanout_ready": shard_fanout_ready,
            "fallback_projection": SEARCH_ACTIVE_PROJECTION_MONOLITH,
            "rollback_flag": "--no-shards",
            "default_max_shards": 24,
            "raw_text_query_projection": SEARCH_ACTIVE_PROJECTION_SHARD_FANOUT if raw_text_shards_ready else SEARCH_ACTIVE_PROJECTION_MONOLITH,
            "raw_text_query_route": "structured shards use monolith fallback for raw-text queries unless materialized with --full-text",
            "commands": [
                "agent-responses",
                "agent-closeouts",
                "agent-progress-updates",
                "agent-reasoning-windows",
                "answer-neighborhood",
            ],
            "authority_boundary": "raw transcript and session indexes remain authority; shards and monolith are generated routing projections.",
        }
    }


def session_memory_search_shard_projection_summary(aoa_root: Path) -> dict[str, Any]:
    catalog = read_search_catalog(aoa_root)
    shards = catalog.get("shards") if isinstance(catalog.get("shards"), list) else []
    status_counts: Counter[str] = Counter()
    shard_rows: list[dict[str, Any]] = []
    total_shard_bytes = 0
    total_session_count = 0
    total_document_count = 0
    current_session_count = 0
    stale_session_count = 0
    missing_session_count = 0
    deferred_live_session_count = 0
    existing_shard_count = 0
    diagnostics: list[str] = []
    for raw_item in shards:
        if not isinstance(raw_item, dict):
            continue
        item = dict(raw_item)
        freshness_counts = item.get("freshness_counts") if isinstance(item.get("freshness_counts"), dict) else {}
        item_deferred_live_count = int_value(freshness_counts.get("deferred_live"))
        shard_key = str(item.get("shard") or "")
        db_path_value = str(item.get("shard_db_path") or "")
        db_path = Path(db_path_value) if db_path_value else search_shard_db_path(aoa_root, shard_key)
        if db_path.exists():
            existing_shard_count += 1
        size_entry = maintenance_light_sqlite_size(db_path)
        total_bytes = int_value(size_entry.get("total_with_wal_bytes"), int_value(size_entry.get("size_bytes")))
        total_shard_bytes += total_bytes
        status = str(item.get("status") or ("current" if item.get("materialized") else "missing"))
        catalog_document_count = int_value(item.get("document_count"))
        document_count = catalog_document_count
        document_count_source = str(item.get("document_count_source") or "catalog")
        if db_path.exists():
            actual_document_count = search_db_document_count_at_path(db_path)
            if actual_document_count is not None:
                document_count = int_value(actual_document_count)
                document_count_source = (
                    "current_shard_documents_table"
                    if status == "current"
                    else "existing_shard_documents_table"
                )
                if document_count != catalog_document_count:
                    diagnostics.append(f"shard_document_count_catalog_mismatch:{shard_key}")
        status_counts[status] += 1
        total_session_count += int_value(item.get("session_count"))
        total_document_count += document_count
        current_session_count += int_value(item.get("current_session_count"))
        stale_session_count += int_value(item.get("stale_session_count"))
        missing_session_count += int_value(item.get("missing_session_count"))
        deferred_live_session_count += item_deferred_live_count
        shard_rows.append(
            {
                "shard": shard_key,
                "status": status,
                "materialized": bool(item.get("materialized")),
                "session_count": item.get("session_count"),
                "current_session_count": item.get("current_session_count"),
                "stale_session_count": item.get("stale_session_count"),
                "missing_session_count": item.get("missing_session_count"),
                "deferred_live_session_count": item_deferred_live_count,
                "document_count": document_count,
                "catalog_document_count": catalog_document_count,
                "document_count_source": document_count_source,
                "storage_mode": item.get("storage_mode"),
                "raw_text_query_support": item.get("raw_text_query_support"),
                "storage_profile": item.get("storage_profile"),
                "expected_storage_profile": item.get("expected_storage_profile"),
                "context_tail_omission_policy": item.get("context_tail_omission_policy"),
                **maintenance_sqlite_size_brief(size_entry),
            }
        )
    materialized_shard_count = int_value(
        catalog.get("materialized_shard_count"),
        sum(1 for item in shard_rows if item.get("status") == "current"),
    )
    shard_count = int_value(catalog.get("shard_count"), len(shard_rows))
    missing_shard_count = int_value(status_counts.get("missing"))
    stale_shard_count = int_value(status_counts.get("stale"))
    noncurrent_shards = [item for item in shard_rows if item.get("status") != "current"]
    actionable_noncurrent_shards = [
        item
        for item in noncurrent_shards
        if not (
            item.get("status") == "stale"
            and int_value(item.get("missing_session_count")) == 0
            and int_value(item.get("stale_session_count")) > 0
            and int_value(item.get("stale_session_count")) <= int_value(item.get("deferred_live_session_count"))
        )
    ]
    monolith_entry = maintenance_light_sqlite_size(search_db_path(aoa_root))
    monolith_total_bytes = int_value(monolith_entry.get("total_with_wal_bytes"), int_value(monolith_entry.get("size_bytes")))
    latest_reports = diagnostic_json_payloads(aoa_root, "*__search-shards.json", limit=1)
    latest_materialization = search_shard_materialization_ops_summary(latest_reports[0] if latest_reports else None)
    if not catalog.get("ok"):
        status = "catalog_not_current"
    elif shard_count <= 0:
        status = "empty"
    elif actionable_noncurrent_shards:
        status = "incomplete"
    elif noncurrent_shards:
        status = "current_with_deferred_live_updates"
    else:
        status = "current"
    combined_bytes = monolith_total_bytes + total_shard_bytes
    fast_path_defaults = search_shard_fast_path_defaults(
        status=status,
        shard_count=shard_count,
        materialized_shard_count=materialized_shard_count,
        shard_rows=shard_rows,
    )
    raw_text_fallback_dependency = search_raw_text_fallback_route_packet(
        aoa_root=aoa_root,
        shard_rows=shard_rows,
        candidate_shard_count=shard_count,
        queried_shard_count=materialized_shard_count,
    )
    fast_path_defaults.setdefault("agent_event_routes", {})["raw_text_fallback_dependency_status"] = raw_text_fallback_dependency["status"]
    fast_path_defaults.setdefault("agent_event_routes", {})["raw_text_fallback_dependency_next_route"] = raw_text_fallback_dependency["next_route"]
    return {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_search_shard_projection_summary",
        "generated_at": utc_now(),
        "mutates": False,
        "status": status,
        "catalog": search_catalog_summary(catalog),
        "catalog_path": catalog.get("catalog_path"),
        "catalog_status": catalog.get("status"),
        "catalog_generated_at": catalog.get("generated_at"),
        "shard_strategy": catalog.get("shard_strategy", SEARCH_SHARD_STRATEGY),
        "active_projection": catalog.get("active_projection", SEARCH_ACTIVE_PROJECTION_MONOLITH),
        "fallback_status": (catalog.get("fallback") or {}).get("status") if isinstance(catalog.get("fallback"), dict) else "",
        "session_count": catalog.get("session_count"),
        "shard_count": shard_count,
        "existing_shard_count": existing_shard_count,
        "materialized_shard_count": materialized_shard_count,
        "current_shard_count": int_value(status_counts.get("current")),
        "stale_shard_count": stale_shard_count,
        "missing_shard_count": missing_shard_count,
        "noncurrent_shard_count": len(noncurrent_shards),
        "status_counts": dict(sorted(status_counts.items())),
        "total_session_count": total_session_count,
        "current_session_count": current_session_count,
        "stale_session_count": stale_session_count,
        "missing_session_count": missing_session_count,
        "deferred_live_session_count": deferred_live_session_count,
        "actionable_noncurrent_shard_count": len(actionable_noncurrent_shards),
        "document_count": total_document_count,
        "shard_db_total_bytes": total_shard_bytes,
        "shard_db_total_human": human_size(total_shard_bytes),
        "monolith_db_total_bytes": monolith_total_bytes,
        "monolith_db_total_human": human_size(monolith_total_bytes),
        "combined_search_projection_total_bytes": combined_bytes,
        "combined_search_projection_total_human": human_size(combined_bytes),
        "largest_shards": sorted(shard_rows, key=lambda item: int_value(item.get("total_with_wal_bytes")), reverse=True)[:8],
        "noncurrent_shards": noncurrent_shards[:8],
        "actionable_noncurrent_shards": actionable_noncurrent_shards[:8],
        "latest_materialization": latest_materialization,
        "fast_path_defaults": fast_path_defaults,
        "raw_text_fallback_dependency": raw_text_fallback_dependency,
        "raw_text_query_route": "structured shards use monolith fallback for raw-text queries unless materialized with --full-text",
        "exact_refresh_command": f"python3 scripts/aoa_session_memory.py search-catalog --aoa-root {aoa_root} --refresh",
        "exact_materialize_command": f"python3 scripts/aoa_session_memory.py search-shards all --aoa-root {aoa_root} --write-report",
        "diagnostics": diagnostics,
        "truth_status": "generated_search_catalog_and_shard_files_are_navigation_not_raw_archive_truth",
    }


def ops_float_value(value: Any, default: float = 0.0) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def diagnostic_json_payloads(aoa_root: Path, glob_pattern: str, *, limit: int = OPS_DIAGNOSTIC_SCAN_LIMIT) -> list[dict[str, Any]]:
    diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
    if not diagnostics_dir.exists():
        return []
    limit_value = max(0, limit)
    if limit_value <= 0:
        return []
    candidate_iter = (path for path in diagnostics_dir.glob(glob_pattern) if path.is_file() and path.suffix == ".json")
    if limit_value == 1:
        latest = max(candidate_iter, key=path_mtime, default=None)
        candidates = [latest] if latest is not None else []
    else:
        candidates = sorted(candidate_iter, key=path_mtime, reverse=True)
    reports: list[dict[str, Any]] = []
    for path in candidates[:limit_value]:
        payload = read_json(path, {})
        report = dict(payload) if isinstance(payload, dict) else {}
        markdown = path.with_suffix(".md")
        report["_diagnostic_path"] = str(path)
        report["_diagnostic_markdown"] = str(markdown) if markdown.exists() else ""
        report["_diagnostic_mtime"] = path_mtime(path)
        reports.append(report)
    return reports


def diagnostic_report_source(report: dict[str, Any]) -> dict[str, Any]:
    return {
        "path": report.get("_diagnostic_path"),
        "markdown": report.get("_diagnostic_markdown") or "",
        "mtime": report.get("_diagnostic_mtime"),
        "artifact_type": report.get("artifact_type"),
        "generated_at": report.get("generated_at"),
    }


def maintenance_report_coordinator(report: dict[str, Any]) -> dict[str, Any]:
    for key in ("maintenance_coordinator", "coordinator"):
        value = report.get(key)
        if isinstance(value, dict):
            return value
    return {}


def resource_launch_execution_brief(report: dict[str, Any]) -> dict[str, Any]:
    execution = report.get("execution") if isinstance(report.get("execution"), dict) else {}
    systemd = execution.get("systemd") if isinstance(execution.get("systemd"), dict) else {}
    if not execution and not systemd and "elapsed_ms" not in report:
        return {}
    return {
        "elapsed_ms": report.get("elapsed_ms"),
        "returncode": execution.get("returncode", report.get("returncode")),
        "resource_class": report.get("resource_class"),
        "resource_kind": report.get("resource_kind"),
        "timeout_sec": report.get("timeout_sec"),
        "systemd": {
            key: systemd.get(key)
            for key in (
                "unit",
                "result",
                "main_status",
                "service_runtime",
                "cpu_time_consumed",
                "memory_peak",
                "generated_unit",
            )
            if key in systemd
        },
    }


def maintenance_coordinator_brief(job: dict[str, Any]) -> dict[str, Any]:
    return {
        key: job.get(key)
        for key in (
            "job_id",
            "status",
            "owner_job",
            "mode",
            "profile",
            "pid",
            "started_at",
            "deadline_at",
            "finished_at",
            "elapsed_ms",
            "lock_wait_ms",
            "target",
            "reason",
            "touched_surfaces",
        )
        if key in job
    }


