def entity_usage_event_role(event_type: str, conversation_act: str = "", session_act: str = "") -> str:
    event_type = str(event_type or "")
    conversation_act = str(conversation_act or "")
    session_act = str(session_act or "")
    if session_act == "runtime_context_envelope":
        return "context"
    if session_act in GOAL_SESSION_ACTS:
        return "usage"
    if event_type in ENTITY_USAGE_DIRECT_TYPES:
        return "usage"
    if event_type in ENTITY_USAGE_RESULT_TYPES:
        return "result"
    if event_type in ENTITY_USAGE_OUTCOME_TYPES:
        return "outcome"
    if event_type in ENTITY_USAGE_ENTRYPOINT_TYPES:
        return "entrypoint"
    if "request" in conversation_act or "request" in session_act:
        return "entrypoint"
    return "context"


def entity_usage_javascript_code_mask(source: str) -> bytearray:
    """Mark JavaScript code while excluding quoted text and comments.

    Custom ``exec`` calls are JavaScript wrappers around nested tools.  A
    validator command inside a patch, regex, or documentation string is not a
    shell invocation, so command recovery must first distinguish executable
    wrapper syntax from inert string content.
    """
    mask = bytearray(b"\x01" * len(source))
    index = 0
    while index < len(source):
        if source.startswith("//", index):
            end = source.find("\n", index + 2)
            end = len(source) if end < 0 else end
            mask[index:end] = b"\x00" * (end - index)
            index = end
            continue
        if source.startswith("/*", index):
            end = source.find("*/", index + 2)
            end = len(source) if end < 0 else end + 2
            mask[index:end] = b"\x00" * (end - index)
            index = end
            continue
        quote = source[index]
        if quote not in {"'", '"', "`"}:
            index += 1
            continue
        start = index
        index += 1
        while index < len(source):
            if source[index] == "\\":
                index = min(len(source), index + 2)
                continue
            if source[index] == quote:
                index += 1
                break
            index += 1
        mask[start:index] = b"\x00" * (index - start)
    return mask


def entity_usage_javascript_matching_delimiter(
    source: str,
    *,
    start: int,
    opening: str,
    closing: str,
    code_mask: bytearray,
) -> int | None:
    depth = 0
    for index in range(start, len(source)):
        if not code_mask[index]:
            continue
        if source[index] == opening:
            depth += 1
        elif source[index] == closing:
            depth -= 1
            if depth == 0:
                return index
    return None


def entity_usage_javascript_literal_value(
    source: str,
    *,
    start: int,
    code_mask: bytearray,
) -> str | None:
    if start >= len(source) or source[start] not in {"'", '"', "`"}:
        return None
    end = start + 1
    while end < len(source) and not code_mask[end]:
        end += 1
    literal = source[start:end]
    if len(literal) < 2:
        return None
    if literal[0] == "`" and literal[-1] == "`":
        return literal[1:-1].strip()
    try:
        value = literal_eval_untrusted_source(literal)
    except (SyntaxError, ValueError):
        return None
    return value.strip() if isinstance(value, str) and value.strip() else None


def entity_usage_javascript_variable_expression_start(
    source: str,
    *,
    name: str,
    before: int,
    code_mask: bytearray,
) -> int | None:
    declaration_re = re.compile(
        rf"\b(?:const|let|var)\s+{re.escape(name)}\s*="
    )
    starts = [
        match.end()
        for match in declaration_re.finditer(source, 0, before)
        if code_mask[match.start()]
    ]
    if not starts:
        return None
    start = starts[-1]
    while start < before and source[start].isspace():
        start += 1
    return start


def entity_usage_javascript_array_item_starts(
    source: str,
    *,
    start: int,
    code_mask: bytearray,
) -> list[int]:
    if start >= len(source) or source[start] != "[":
        return []
    end = entity_usage_javascript_matching_delimiter(
        source,
        start=start,
        opening="[",
        closing="]",
        code_mask=code_mask,
    )
    if end is None:
        return []
    item_starts = [start + 1]
    depths = {"(": 0, "[": 0, "{": 0}
    closing_to_opening = {")": "(", "]": "[", "}": "{"}
    for index in range(start + 1, end):
        if not code_mask[index]:
            continue
        char = source[index]
        if char in depths:
            depths[char] += 1
        elif char in closing_to_opening:
            opening = closing_to_opening[char]
            depths[opening] = max(0, depths[opening] - 1)
        elif char == "," and not any(depths.values()):
            item_starts.append(index + 1)
    normalized: list[int] = []
    for item_start in item_starts:
        while item_start < end and source[item_start].isspace():
            item_start += 1
        if item_start < end:
            normalized.append(item_start)
    return normalized


def entity_usage_javascript_array_item_start(
    source: str,
    *,
    start: int,
    item_index: int,
    code_mask: bytearray,
) -> int | None:
    item_starts = entity_usage_javascript_array_item_starts(
        source,
        start=start,
        code_mask=code_mask,
    )
    if item_index >= len(item_starts):
        return None
    return item_starts[item_index]


def entity_usage_javascript_mapped_command_values(
    source: str,
    *,
    name: str,
    call_start: int,
    code_mask: bytearray,
) -> list[str]:
    values: list[str] = []
    for map_match in ENTITY_USAGE_CUSTOM_EXEC_DESTRUCTURED_MAP_RE.finditer(
        source,
        0,
        call_start,
    ):
        if not code_mask[map_match.start()]:
            continue
        bindings = [
            value.strip()
            for value in map_match.group("bindings").split(",")
        ]
        if name not in bindings:
            continue
        map_opening = source.find("(", map_match.start(), map_match.end())
        map_closing = entity_usage_javascript_matching_delimiter(
            source,
            start=map_opening,
            opening="(",
            closing=")",
            code_mask=code_mask,
        )
        if map_closing is None or call_start > map_closing:
            continue
        collection_start = entity_usage_javascript_variable_expression_start(
            source,
            name=map_match.group("collection"),
            before=map_match.start(),
            code_mask=code_mask,
        )
        if collection_start is None:
            continue
        for row_start in entity_usage_javascript_array_item_starts(
            source,
            start=collection_start,
            code_mask=code_mask,
        ):
            value_start = entity_usage_javascript_array_item_start(
                source,
                start=row_start,
                item_index=bindings.index(name),
                code_mask=code_mask,
            )
            if value_start is None:
                continue
            value = entity_usage_javascript_literal_value(
                source,
                start=value_start,
                code_mask=code_mask,
            )
            if value:
                values.append(value)
    return list(dict.fromkeys(values))


def entity_usage_javascript_command_expression(
    source: str,
    *,
    start: int,
    before: int,
    code_mask: bytearray,
    depth: int = 0,
) -> str | None:
    if depth > 4:
        return None
    while start < len(source) and source[start].isspace():
        start += 1
    direct = entity_usage_javascript_literal_value(
        source,
        start=start,
        code_mask=code_mask,
    )
    if direct:
        return direct
    reference = re.match(
        r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)(?:\[(?P<index>\d+)\])?",
        source[start:],
    )
    if not reference:
        return None
    variable_start = entity_usage_javascript_variable_expression_start(
        source,
        name=reference.group("name"),
        before=before,
        code_mask=code_mask,
    )
    if variable_start is None:
        return None
    if reference.group("index") is not None:
        variable_start = entity_usage_javascript_array_item_start(
            source,
            start=variable_start,
            item_index=int(reference.group("index")),
            code_mask=code_mask,
        )
        if variable_start is None:
            return None
    return entity_usage_javascript_command_expression(
        source,
        start=variable_start,
        before=before,
        code_mask=code_mask,
        depth=depth + 1,
    )


def entity_usage_custom_exec_command_candidates(payload: dict[str, Any]) -> list[str]:
    if (
        str(payload.get("type") or "") != "custom_tool_call"
        or normalized_tool_name(tool_name_from_payload(payload)) != "exec"
    ):
        return []
    raw_source = payload.get("input")
    if not isinstance(raw_source, str) or not raw_source.strip():
        return []
    source = raw_source[:131072]
    code_mask = entity_usage_javascript_code_mask(source)
    candidates: list[str] = []
    for call_match in ENTITY_USAGE_CUSTOM_EXEC_CALL_RE.finditer(source):
        if not code_mask[call_match.start()]:
            continue
        opening = source.find("(", call_match.start(), call_match.end())
        closing = entity_usage_javascript_matching_delimiter(
            source,
            start=opening,
            opening="(",
            closing=")",
            code_mask=code_mask,
        )
        if closing is None:
            continue
        for property_match in ENTITY_USAGE_CUSTOM_EXEC_COMMAND_PROPERTY_RE.finditer(
            source,
            opening + 1,
            closing,
        ):
            # A JSON-style property key (``{"cmd": ...}``) is quoted and
            # therefore masked as inert string content.  Its trailing colon is
            # still executable object syntax; checking that position admits
            # real quoted keys without matching ``"cmd: ..."`` inside a value
            # or documentation string.
            property_syntax_index = max(
                property_match.start(),
                property_match.end() - 1,
            )
            if not code_mask[property_syntax_index]:
                continue
            value = entity_usage_javascript_command_expression(
                source,
                start=property_match.end(),
                before=call_match.start(),
                code_mask=code_mask,
            )
            if value:
                candidates.append(value)
            else:
                reference = re.match(
                    r"(?P<name>[A-Za-z_$][A-Za-z0-9_$]*)",
                    source[property_match.end() :],
                )
                if reference:
                    candidates.extend(
                        entity_usage_javascript_mapped_command_values(
                            source,
                            name=reference.group("name"),
                            call_start=call_match.start(),
                            code_mask=code_mask,
                        )
                    )
        for shorthand_match in ENTITY_USAGE_CUSTOM_EXEC_COMMAND_SHORTHAND_RE.finditer(
            source,
            opening + 1,
            closing,
        ):
            name_start = shorthand_match.start("name")
            if not code_mask[name_start]:
                continue
            value = entity_usage_javascript_command_expression(
                source,
                start=name_start,
                before=call_match.start(),
                code_mask=code_mask,
            )
            if value:
                candidates.append(value)
            else:
                candidates.extend(
                    entity_usage_javascript_mapped_command_values(
                        source,
                        name=shorthand_match.group("name"),
                        call_start=call_match.start(),
                        code_mask=code_mask,
                    )
                )
        if len(candidates) >= 16:
            break
    return list(dict.fromkeys(candidate for candidate in candidates if candidate))


def entity_usage_python_command_vectors(node: ast.AST) -> list[list[str]]:
    try:
        value = literal_eval_untrusted_source(node)
    except (TypeError, ValueError, SyntaxError):
        return []
    if (
        isinstance(value, (list, tuple))
        and value
        and all(isinstance(item, str) for item in value)
    ):
        return [[str(item) for item in value]]
    if isinstance(value, (list, tuple)):
        return [
            [str(item) for item in candidate]
            for candidate in value
            if (
                isinstance(candidate, (list, tuple))
                and candidate
                and all(isinstance(item, str) for item in candidate)
            )
        ]
    return []


def entity_usage_python_subprocess_call(node: ast.Call) -> bool:
    function = node.func
    if not isinstance(function, ast.Attribute):
        return False
    if function.attr not in {"Popen", "call", "check_call", "check_output", "run"}:
        return False
    return isinstance(function.value, ast.Name) and function.value.id == "subprocess"


def entity_usage_python_heredoc_subprocess_commands(command: str) -> list[str]:
    """Recover static argv vectors that an executed Python heredoc invokes."""
    commands: list[str] = []
    heredoc_re = re.compile(
        r"<<-?\s*(?P<quote>['\"]?)(?P<marker>[A-Za-z_][A-Za-z0-9_]*)"
        r"(?P=quote)[^\n]*\n"
    )
    for heredoc in heredoc_re.finditer(command):
        marker = heredoc.group("marker")
        terminator = re.search(
            rf"(?m)^{re.escape(marker)}\s*$",
            command[heredoc.end() :],
        )
        if not terminator:
            continue
        body = command[
            heredoc.end() : heredoc.end() + terminator.start()
        ]
        try:
            tree = ast.parse(body)
        except SyntaxError:
            continue
        assigned_vectors: dict[str, list[list[str]]] = {}
        for node in ast.walk(tree):
            if not isinstance(node, (ast.Assign, ast.AnnAssign)):
                continue
            value = node.value
            vectors = entity_usage_python_command_vectors(value)
            if not vectors:
                continue
            targets = (
                node.targets
                if isinstance(node, ast.Assign)
                else [node.target]
            )
            for target in targets:
                if isinstance(target, ast.Name):
                    assigned_vectors[target.id] = vectors
        for node in ast.walk(tree):
            if isinstance(node, ast.For) and isinstance(node.target, ast.Name):
                vectors = entity_usage_python_command_vectors(node.iter)
                if vectors and any(
                    isinstance(candidate, ast.Call)
                    and entity_usage_python_subprocess_call(candidate)
                    and candidate.args
                    and isinstance(candidate.args[0], ast.Name)
                    and candidate.args[0].id == node.target.id
                    for candidate in ast.walk(node)
                ):
                    commands.extend(shlex.join(vector) for vector in vectors)
            if not isinstance(node, ast.Call) or not entity_usage_python_subprocess_call(node):
                continue
            if not node.args:
                continue
            vectors = entity_usage_python_command_vectors(node.args[0])
            if isinstance(node.args[0], ast.Name):
                vectors = assigned_vectors.get(node.args[0].id, [])
            commands.extend(shlex.join(vector) for vector in vectors)
    return list(dict.fromkeys(commands))


def entity_usage_execution_command_candidates(payload: dict[str, Any]) -> list[str]:
    """Recover only shell commands proven by one structured raw tool call."""
    if str(payload.get("type") or "") == "custom_tool_call":
        candidates = entity_usage_custom_exec_command_candidates(payload)
    else:
        if normalized_tool_name(
            tool_name_from_payload(payload)
        ) not in ENTITY_USAGE_DIRECT_SHELL_TOOL_NAMES:
            return []
        direct = raw_command_text_from_payload(payload)
        candidates = [direct] if direct else []
    nested = [
        nested_command
        for command in candidates
        for nested_command in entity_usage_python_heredoc_subprocess_commands(command)
    ]
    raw_candidates = list(
        dict.fromkeys(
            candidate
            for candidate in [*candidates, *nested]
            if candidate
        )
    )
    return [
        derived_text_privacy_text(candidate)
        for candidate in raw_candidates
    ]


def entity_usage_hook_command_proves_invocation(
    command: str,
    *,
    anchor: str,
) -> bool:
    """Admit an exact hook CLI operation, not hook vocabulary in a command.

    Hook lifecycle receipts remain the authority for whether a runtime hook
    fired. This route only proves that the requested hook-facing CLI operation
    itself was invoked (for example ``codex-hooks-status``).
    """
    anchor_key = route_key_slug(anchor, fallback="", max_chars=120)
    if not anchor_key:
        return False
    for tokens in session_memory_query_demand_shell_segments(command):
        executable, arguments = entity_usage_shell_segment_executable(tokens)
        if not executable:
            continue
        subcommand_arguments = list(arguments)
        executable_key = entity_usage_execution_anchor_key(executable)
        if executable in {
            "python",
            "python3",
            "pypy",
            "pypy3",
        } or re.fullmatch(r"python3(?:\.\d+)+", executable):
            target_kind, target = entity_usage_python_target(arguments)
            if target_kind != "script":
                continue
            target_key = entity_usage_execution_anchor_key(
                Path(str(target).replace("\\", "/")).name
            )
            if target_key != "aoa_session_memory_py":
                continue
            try:
                target_index = arguments.index(target)
            except ValueError:
                continue
            subcommand_arguments = arguments[target_index + 1 :]
        elif executable_key not in {
            "aoa_session_memory",
            "aoa_session_memory_py",
        }:
            continue
        subcommand = next(
            (
                str(argument)
                for argument in subcommand_arguments
                if str(argument) and not str(argument).startswith("-")
            ),
            "",
        )
        if (
            route_key_slug(
                subcommand,
                fallback="",
                max_chars=120,
            )
            == anchor_key
        ):
            return True
    return False


def entity_usage_execution_anchor_key(value: Any) -> str:
    return "_".join(re.findall(r"[a-z0-9]+", str(value or "").casefold()))


def entity_usage_shell_segment_executable(tokens: list[str]) -> tuple[str, list[str]]:
    remaining = [str(token) for token in tokens if str(token)]
    while remaining:
        head = remaining[0]
        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*=.*", head):
            remaining.pop(0)
            continue
        wrapper = Path(head).name
        if wrapper in {"env", "sudo", "command"}:
            remaining.pop(0)
            while remaining and str(remaining[0]).startswith("-"):
                option = remaining.pop(0)
                if wrapper == "env" and option in {"-u", "--unset"} and remaining:
                    remaining.pop(0)
            continue
        if wrapper == "time":
            remaining.pop(0)
            while remaining and str(remaining[0]).startswith("-"):
                option = remaining.pop(0)
                if option in {"-f", "--format", "-o", "--output"} and remaining:
                    remaining.pop(0)
            continue
        break
    if len(remaining) >= 2 and Path(remaining[0]).name in {"uv", "poetry", "pipenv"} and remaining[1] == "run":
        remaining = remaining[2:]
        while remaining and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*=.*", remaining[0]):
            remaining.pop(0)
    if not remaining:
        return "", []
    return Path(remaining[0]).name.casefold(), remaining[1:]


def entity_usage_shell_forwarding_wrappers(command: str) -> dict[str, int]:
    """Find local shell helpers that visibly forward ``"$@"`` after shifts."""
    wrappers: dict[str, int] = {}
    function_re = re.compile(
        r"(?ms)(?:^|\n)\s*(?P<name>[A-Za-z_][A-Za-z0-9_]*)\s*"
        r"\(\s*\)\s*\{(?P<body>.*?)\}"
    )
    for match in function_re.finditer(str(command or "")):
        body = str(match.group("body") or "")
        forwards_argv = bool(
            re.search(r"\$\(\s*\"\$@\"", body)
            or re.search(r"(?m)^\s*\"\$@\"(?:\s|$)", body)
        )
        if not forwards_argv:
            continue
        consumed = 0
        for shift_match in re.finditer(
            r"(?m)(?:^|;)\s*shift(?:\s+(?P<count>\d+))?(?:\s*(?:;|$))",
            body,
        ):
            consumed += int(shift_match.group("count") or "1")
        wrappers[str(match.group("name") or "").casefold()] = consumed
    return wrappers


def entity_usage_python_target(arguments: list[str]) -> tuple[str, str]:
    index = 0
    while index < len(arguments):
        token = str(arguments[index])
        if token == "-m":
            return "module", str(arguments[index + 1]) if index + 1 < len(arguments) else ""
        if token in {"-", "-c"} or token.startswith("-c"):
            return "inline", ""
        if token.startswith("-"):
            index += 1
            continue
        return "script", token
    return "", ""


def entity_usage_execution_command_proves_invocation(
    command: str,
    *,
    anchor: str,
    kind: str,
) -> bool:
    anchor_key = entity_usage_execution_anchor_key(anchor)
    if not anchor_key:
        return False
    anchor_basename_key = ""
    if kind in {"script", "validator"} and literal_query_looks_like_path(anchor):
        anchor_basename_key = entity_usage_execution_anchor_key(
            Path(str(anchor).replace("\\", "/")).name
        )
    forwarding_wrappers = entity_usage_shell_forwarding_wrappers(command)
    for tokens in session_memory_query_demand_shell_segments(command):
        segment_key = entity_usage_execution_anchor_key(" ".join(tokens))
        if anchor_key not in segment_key:
            continue
        executable, arguments = entity_usage_shell_segment_executable(tokens)
        if executable in forwarding_wrappers:
            arguments = arguments[forwarding_wrappers[executable] :]
            executable, arguments = entity_usage_shell_segment_executable(
                arguments
            )
        if not executable:
            continue
        if kind == "script":
            executable_key = entity_usage_execution_anchor_key(executable)
            if anchor_key in executable_key or (
                anchor_basename_key
                and anchor_basename_key == executable_key
            ):
                return True
            if executable in {"python", "python3", "pypy", "pypy3"} or re.fullmatch(
                r"python3(?:\.\d+)+",
                executable,
            ):
                target_kind, target = entity_usage_python_target(arguments)
                target_key = entity_usage_execution_anchor_key(target)
                target_basename_key = entity_usage_execution_anchor_key(
                    Path(str(target).replace("\\", "/")).name
                )
                if (
                    target_kind in {"module", "script"}
                    and (
                        anchor_key in target_key
                        or (
                            anchor_basename_key
                            and anchor_basename_key == target_basename_key
                        )
                    )
                ):
                    return True
                continue
            if executable in {"bash", "sh", "zsh", "node", "ruby", "perl"}:
                target = next(
                    (
                        token
                        for token in arguments
                        if token and not str(token).startswith("-")
                    ),
                    "",
                )
                target_key = entity_usage_execution_anchor_key(target)
                target_basename_key = entity_usage_execution_anchor_key(
                    Path(str(target).replace("\\", "/")).name
                )
                if anchor_key in target_key or (
                    anchor_basename_key
                    and anchor_basename_key == target_basename_key
                ):
                    return True
            continue
        if kind == "test":
            if executable in {"pytest", "py.test", "jest", "vitest"}:
                return True
            if executable in {"python", "python3", "pypy", "pypy3"} or re.fullmatch(
                r"python3(?:\.\d+)+",
                executable,
            ):
                target_kind, target = entity_usage_python_target(arguments)
                target_key = entity_usage_execution_anchor_key(target)
                if target_kind == "module" and target_key in {"pytest", "unittest"}:
                    return True
                if target_kind == "script" and anchor_key in target_key and target_key.startswith("test_"):
                    return True
            if executable in {"npm", "pnpm", "yarn", "bun"} and any(
                str(token).casefold() in {"test", "jest", "vitest"}
                for token in arguments[:3]
            ):
                return True
            if executable == "cargo" and arguments and str(arguments[0]).casefold() == "test":
                return True
            if executable == "go" and arguments and str(arguments[0]).casefold() == "test":
                return True
            continue
        if kind == "validator":
            executable_key = entity_usage_execution_anchor_key(executable)
            if anchor_key in executable_key or (
                anchor_basename_key
                and anchor_basename_key == executable_key
            ):
                return True
            if executable in {"python", "python3", "pypy", "pypy3"} or re.fullmatch(
                r"python3(?:\.\d+)+",
                executable,
            ):
                target_kind, target = entity_usage_python_target(arguments)
                target_key = entity_usage_execution_anchor_key(target)
                target_basename_key = entity_usage_execution_anchor_key(
                    Path(str(target).replace("\\", "/")).name
                )
                if target_kind in {"module", "script"} and (
                    anchor_key in target_key
                    or (
                        anchor_basename_key
                        and anchor_basename_key == target_basename_key
                    )
                ):
                    return True
                continue
            if executable in {"bash", "sh", "zsh", "node", "ruby", "perl"}:
                target = next(
                    (token for token in arguments if token and not str(token).startswith("-")),
                    "",
                )
                target_key = entity_usage_execution_anchor_key(target)
                target_basename_key = entity_usage_execution_anchor_key(
                    Path(str(target).replace("\\", "/")).name
                )
                if anchor_key in target_key or (
                    anchor_basename_key
                    and anchor_basename_key == target_basename_key
                ):
                    return True
    return False


ENTITY_USAGE_FILE_INSPECTION_EXECUTABLES = frozenset(
    {
        "awk",
        "bat",
        "cat",
        "head",
        "less",
        "more",
        "nl",
        "sed",
        "tail",
    }
)


def entity_usage_execution_command_proves_inspection_read(
    command: str,
    *,
    anchor: str,
) -> bool:
    """Recognize an exact file-bearing read without promoting text mentions."""

    anchor_key = entity_usage_execution_anchor_key(anchor)
    if not anchor_key:
        return False
    anchor_basename_key = entity_usage_execution_anchor_key(
        Path(str(anchor).replace("\\", "/")).name
    )
    for tokens in session_memory_query_demand_shell_segments(command):
        executable, arguments = entity_usage_shell_segment_executable(tokens)
        if executable not in ENTITY_USAGE_FILE_INSPECTION_EXECUTABLES:
            continue
        argument_keys = [
            entity_usage_execution_anchor_key(argument)
            for argument in arguments
            if str(argument)
        ]
        if any(
            key
            and (
                anchor_key in key
                or (
                    anchor_basename_key
                    and anchor_basename_key == key
                )
            )
            for key in argument_keys
        ):
            return True
    return False


def entity_usage_execution_parent_command_is_runner(command: str) -> bool:
    for tokens in session_memory_query_demand_shell_segments(command):
        executable, arguments = entity_usage_shell_segment_executable(tokens)
        if not executable:
            continue
        targets: list[str] = []
        if executable in {"python", "python3", "pypy", "pypy3"} or re.fullmatch(
            r"python3(?:\.\d+)+",
            executable,
        ):
            target_kind, target = entity_usage_python_target(arguments)
            if target_kind in {"module", "script"}:
                targets.append(target)
        elif executable in {"bash", "sh", "zsh", "node", "ruby", "perl"}:
            targets.extend(
                str(token)
                for token in arguments
                if token and not str(token).startswith("-")
            )
        elif executable in {
            "cargo",
            "go",
            "gradle",
            "make",
            "ninja",
            "nox",
            "npm",
            "pnpm",
            "pytest",
            "tox",
            "yarn",
        }:
            targets.extend([executable, *arguments[:3]])
        else:
            targets.append(executable)
        if any(
            set(entity_usage_execution_anchor_key(target).split("_"))
            & set(ENTITY_USAGE_PARENT_RUNNER_TARGET_TERMS)
            for target in targets
        ):
            return True
    return False


def entity_usage_execution_result_marker_commands(
    payload: dict[str, Any],
    *,
    anchor: str,
    kind: str,
) -> list[str]:
    if str(payload.get("type") or "") not in {
        "custom_tool_call_output",
        "function_call_output",
        "tool_call_output",
    }:
        return []
    output = text_from_content(
        payload.get("output"),
        max_chars=ENTITY_USAGE_ASYNC_RAW_PREVIEW_MAX_CHARS,
    )
    commands: list[str] = []
    for line in output.splitlines()[:512]:
        marker = ENTITY_USAGE_STRUCTURED_RUNNER_LINE_RE.match(line.strip())
        if not marker:
            continue
        body = str(marker.group("body") or "").strip()
        variants = [body]
        if ":" in body:
            variants.append(body.split(":", 1)[1].strip())
        for candidate in variants:
            if (
                candidate
                and entity_usage_execution_command_proves_invocation(
                    candidate,
                    anchor=anchor,
                    kind=kind,
                )
            ):
                commands.append(
                    derived_text_privacy_text(candidate)
                )
                break
    return list(dict.fromkeys(commands))


def entity_usage_execution_result_parent(
    source_event: dict[str, Any],
    *,
    hit: dict[str, Any],
    segment_cache: dict[str, list[dict[str, Any]]],
    manifest_cache: dict[str, dict[str, Any]],
    raw_preview_cache: dict[tuple[str, str, str, int], dict[str, Any]],
) -> tuple[list[str], dict[str, Any], str]:
    correlation_id = str(source_event.get("correlation_id") or "")
    if not correlation_id:
        return [], {}, "result_correlation_missing"
    events = segment_events_for_hit(hit, segment_cache=segment_cache)
    source_index = next(
        (
            index
            for index, event in enumerate(events)
            if str(event.get("event_id") or "")
            == str(source_event.get("event_id") or "")
        ),
        None,
    )
    if source_index is None:
        return [], {}, "result_event_not_in_segment"
    for index in range(source_index - 1, max(-1, source_index - 25), -1):
        candidate = events[index]
        if str(candidate.get("correlation_id") or "") != correlation_id:
            continue
        if str(candidate.get("type") or "") not in ENTITY_USAGE_DIRECT_TYPES:
            continue
        payload, status = raw_payload_for_usage_segment_event(
            candidate,
            hit=hit,
            distance=index - source_index,
            manifest_cache=manifest_cache,
            raw_preview_cache=raw_preview_cache,
        )
        if not payload:
            return [], candidate, f"parent_payload_unavailable:{status}"
        commands = entity_usage_execution_command_candidates(payload)
        if commands:
            return commands, candidate, "available"
        continuation_identity = async_continuation_transport_identity_from_payload(
            payload
        )
        continuation_kind = str(continuation_identity.get("kind") or "")
        continuation_id = str(continuation_identity.get("id") or "")
        if not continuation_kind or not continuation_id:
            return [], candidate, "parent_command_unresolved"
        for result_index in range(index - 1, max(-1, index - 25), -1):
            running_event = events[result_index]
            if not entity_usage_segment_event_is_tool_result(running_event):
                continue
            running_payload, _running_status = raw_payload_for_usage_segment_event(
                running_event,
                hit=hit,
                distance=result_index - source_index,
                manifest_cache=manifest_cache,
                raw_preview_cache=raw_preview_cache,
            )
            if not running_payload:
                continue
            running_identity = async_running_transport_identity_from_payload(
                running_payload
            )
            if (
                str(running_identity.get("kind") or "") != continuation_kind
                or str(running_identity.get("id") or "") != continuation_id
            ):
                continue
            origin_correlation = str(running_event.get("correlation_id") or "")
            if not origin_correlation:
                return [], running_event, "async_origin_correlation_missing"
            for origin_index in range(
                result_index - 1,
                max(-1, result_index - 25),
                -1,
            ):
                origin_event = events[origin_index]
                if (
                    str(origin_event.get("correlation_id") or "")
                    != origin_correlation
                    or str(origin_event.get("type") or "")
                    not in ENTITY_USAGE_DIRECT_TYPES
                ):
                    continue
                origin_payload, origin_status = (
                    raw_payload_for_usage_segment_event(
                        origin_event,
                        hit=hit,
                        distance=origin_index - source_index,
                        manifest_cache=manifest_cache,
                        raw_preview_cache=raw_preview_cache,
                    )
                )
                if not origin_payload:
                    return (
                        [],
                        origin_event,
                        f"async_origin_payload_unavailable:{origin_status}",
                    )
                origin_commands = entity_usage_execution_command_candidates(
                    origin_payload
                )
                return (
                    origin_commands,
                    origin_event,
                    (
                        "available_via_async_transport"
                        if origin_commands
                        else "async_origin_command_unresolved"
                    ),
                )
            return [], running_event, "async_origin_command_not_found"
        return (
            [],
            candidate,
            f"async_running_origin_not_found:{continuation_kind}:{continuation_id}",
        )
    return [], {}, "correlated_parent_command_not_found"


def skill_artifact_content_read_present(
    text: str,
    *,
    anchor_pattern: re.Pattern[str] | None,
) -> bool:
    """Recognize a bounded command that opens one named SKILL.md body.

    A path passed to history, listing, or metadata commands remains a mention.
    This deliberately narrow lane covers direct readers and the observed
    ``git show <revision>:<path>/SKILL.md`` blob-read form.
    """
    if not anchor_pattern or "skill.md" not in text:
        return False
    for command in re.split(r"[;\n]", text):
        if "skill.md" not in command or not anchor_pattern.search(command):
            continue
        artifact_end = command.find("skill.md") + len("skill.md")
        prefix = command[:artifact_end]
        if re.search(r"\b(?:cat|sed|head|tail|less|bat)\b", prefix):
            return True
        git_show = re.search(r"\bgit\b.*?\bshow\b(?P<args>.*?skill\.md)", prefix)
        if git_show and ":" in str(git_show.group("args") or ""):
            return True
    return False


def skill_prompt_catalog_entry_from_payload(
    payload: dict[str, Any],
    *,
    anchor: str,
) -> dict[str, str]:
    """Return one exact Available-skills entry from a structured prompt message."""
    if (
        str(payload.get("type") or "") != "message"
        or str(payload.get("role") or "").casefold() not in {"developer", "system"}
    ):
        return {}
    normalized_anchor = canonical_skill_entity_key(anchor)
    if not normalized_anchor:
        return {}
    content = payload.get("content")
    if not isinstance(content, list):
        return {}
    for item in content:
        if not isinstance(item, dict):
            continue
        text = item.get("text")
        if not isinstance(text, str) or "### Available skills" not in text:
            continue
        section = text.partition("### Available skills")[2]
        if "</skills_instructions>" in section:
            section = section.partition("</skills_instructions>")[0]
        for line in section.splitlines():
            match = SKILL_PROMPT_CATALOG_ENTRY_RE.match(line)
            if not match:
                continue
            name = match.group("name").strip()
            if canonical_skill_entity_key(name) != normalized_anchor:
                continue
            return {
                "name": name,
                "canonical_name": normalized_anchor,
                "source": match.group("source").strip(),
            }
    return {}


def skill_prompt_visibility_segment_ref(
    session_dir: Path,
    segment: dict[str, Any],
    event: dict[str, Any],
) -> str:
    md_anchor = str(event.get("md_anchor") or "")
    if not md_anchor:
        return str(segment.get("markdown") or "")
    path_text, separator, anchor = md_anchor.partition("#")
    path = Path(path_text)
    if not path.is_absolute():
        path = (
            session_dir / "segments" / path.name
            if path.parent == Path(".")
            else session_dir / path
        )
    return f"{path}#{anchor}" if separator else str(path)


def skill_prompt_visibility_probe(
    *,
    aoa_root: Path,
    anchor: str,
    session: str | None,
) -> dict[str, Any]:
    """Read only the initial structured prompt context for one scoped skill query."""
    packet: dict[str, Any] = {
        "schema_version": SKILL_PROMPT_VISIBILITY_SCHEMA_VERSION,
        "applied": bool(session),
        "status": "not_requested",
        "mutates": False,
        "bounded": True,
        "scope": "session_initial_context",
        "context_event_limit": SKILL_PROMPT_VISIBILITY_CONTEXT_EVENT_LIMIT,
        "raw_line_max_chars": SKILL_PROMPT_VISIBILITY_RAW_MAX_CHARS,
        "context_event_count": 0,
        "context_event_count_scanned": 0,
        "raw_ref_count_opened": 0,
        "unverifiable_raw_ref_count": 0,
        "match_count": 0,
        "absence_claim_allowed": False,
        "diagnostics": [],
        "_hits": [],
    }
    if not session:
        return packet
    try:
        record = resolve_session_record(aoa_root, session)
    except ValueError as exc:
        packet["status"] = "session_unresolved"
        packet["diagnostics"] = [str(exc)]
        return packet
    session_dir = session_dir_from_record(record)
    manifest_path = session_dir / "session.manifest.json"
    manifest = read_json(manifest_path, {})
    if not isinstance(manifest, dict) or not manifest:
        packet["status"] = "manifest_unavailable"
        packet["diagnostics"] = [f"missing session manifest: {manifest_path}"]
        return packet
    segments = [
        item
        for item in manifest.get("segments", [])
        if isinstance(item, dict) and str(item.get("index") or "")
    ] if isinstance(manifest.get("segments"), list) else []
    if not segments:
        packet["status"] = "initial_segment_unavailable"
        packet["diagnostics"] = ["session manifest has no indexed segments"]
        return packet

    def segment_sort_key(item: dict[str, Any]) -> tuple[int, str]:
        segment_id = str(item.get("segment_id") or "")
        return (
            int(segment_id) if segment_id.isdigit() else 1_000_000,
            segment_id,
        )

    segment = min(segments, key=segment_sort_key)
    index_path = session_relative_path(session_dir, segment.get("index"))
    segment_index = read_json(index_path, {})
    if not isinstance(segment_index, dict) or not segment_index:
        packet["status"] = "initial_segment_index_unavailable"
        packet["diagnostics"] = [f"missing initial segment index: {index_path}"]
        return packet
    expected_publish_id, expected_raw_sha256 = (
        session_manifest_projection_expectations(manifest)
    )
    generation_reasons = generated_segment_index_stale_reasons(
        segment_index,
        expected_publish_id=expected_publish_id,
        expected_raw_sha256=expected_raw_sha256,
    )
    expected_generation = session_memory_expected_generation_identities(
        aoa_root
    ).get("segment_index", {})
    observed_generation = (
        segment_index.get("generation_identity")
        if isinstance(segment_index.get("generation_identity"), dict)
        else {}
    )
    packet["generation_identities"] = {
        "expected": {"segment_index": expected_generation},
        "observed": {"segment_index": observed_generation},
        "compatible": not generation_reasons,
    }
    if generation_reasons:
        packet["status"] = "incompatible_generation"
        packet["diagnostics"] = unique_preserving_order(
            [
                "prompt_visibility_segment_generation_incompatible",
                *generation_reasons,
            ]
        )
        return packet
    context_events = [
        event
        for event in segment_index.get("events", [])
        if isinstance(event, dict)
        and str(event.get("type") or "").upper() == "CONTEXT_STATE"
        and str(event.get("raw_ref") or "")
    ] if isinstance(segment_index.get("events"), list) else []
    packet["context_event_count"] = len(context_events)
    context_window_truncated = (
        len(context_events) > SKILL_PROMPT_VISIBILITY_CONTEXT_EVENT_LIMIT
    )
    packet["context_window_truncated"] = context_window_truncated
    raw_block_ref = segment_raw_block_ref(segment_index, session_dir)
    source_roles: Counter[str] = Counter()

    for event in context_events[:SKILL_PROMPT_VISIBILITY_CONTEXT_EVENT_LIMIT]:
        packet["context_event_count_scanned"] = (
            int_value(packet.get("context_event_count_scanned")) + 1
        )
        raw_ref = str(event.get("raw_ref") or "")
        raw_packet = raw_block_line_preview(
            session_dir,
            manifest,
            raw_ref,
            raw_block_ref=raw_block_ref,
            max_chars=SKILL_PROMPT_VISIBILITY_RAW_MAX_CHARS,
        )
        if raw_packet.get("status") != "available":
            raw_packet = raw_line_preview(
                manifest_raw_path(session_dir, manifest),
                raw_ref,
                max_chars=SKILL_PROMPT_VISIBILITY_RAW_MAX_CHARS,
            )
        packet["raw_ref_count_opened"] = (
            int_value(packet.get("raw_ref_count_opened")) + 1
        )
        try:
            row = json.loads(str(raw_packet.get("text") or ""))
        except json.JSONDecodeError:
            packet["unverifiable_raw_ref_count"] = (
                int_value(packet.get("unverifiable_raw_ref_count")) + 1
            )
            continue
        payload = row.get("payload") if isinstance(row, dict) else {}
        if (
            not isinstance(payload, dict)
            or str(row.get("type") or "") != "response_item"
            or str(payload.get("type") or "") != "message"
        ):
            continue
        source_role = str(payload.get("role") or "").casefold()
        if source_role not in {"developer", "system"}:
            continue
        source_roles[source_role] += 1
        entry = skill_prompt_catalog_entry_from_payload(payload, anchor=anchor)
        if not entry:
            continue
        normalized_anchor = str(entry.get("canonical_name") or "")
        event_id = str(event.get("event_id") or "")
        segment_id = str(segment.get("segment_id") or segment_index.get("segment_id") or "")
        packet["_hits"] = [
            {
                "doc_id": (
                    f"event:{record.get('session_id') or manifest.get('session_id')}:"
                    f"{segment_id}:{event_id}"
                ),
                "entity_usage_source_override": "raw_context_skill_catalogue_probe",
                "entity_usage_role_override": "context",
                "event_type": "CONTEXT_STATE",
                "family": event.get("family") or "context_memory",
                "phase": event.get("phase") or "observe",
                "actor": event.get("actor") or "codex_runtime",
                "action": event.get("action") or "report_context",
                "outcome": event.get("outcome") or "observed",
                "conversation_act": "",
                "session_act": "memory_context",
                "session_id": record.get("session_id") or manifest.get("session_id"),
                "session_label": record.get("session_label") or manifest.get("session_label"),
                "session_date": session_record_date(record),
                "segment_id": segment_id,
                "event_id": event_id,
                "title": f"{source_role.title()} skill catalogue entry: {entry.get('name')}",
                "snippet": f"{entry.get('name')} (file: {entry.get('source')})",
                "route_signals": [f"skill:{normalized_anchor}"],
                "skill_evidence_state": "prompt_visible",
                "prompt_visibility_admission": "structured_available_skills_entry",
                "prompt_visibility_source_role": source_role,
                "prompt_visibility_skill_key": normalized_anchor,
                "prompt_visibility_source": entry.get("source"),
                "refs": {
                    "session": str(manifest_path),
                    "segment": skill_prompt_visibility_segment_ref(
                        session_dir,
                        segment,
                        event,
                    ),
                    "segment_index": str(index_path),
                    "raw": raw_ref,
                    "raw_block": raw_block_ref,
                },
                "freshness": {
                    "status": "bounded_current",
                    "basis": "query_time_exact_archived_raw_context_ref",
                    "live_verification": False,
                    "reasons": [],
                },
            }
        ]
        packet["status"] = "matched"
        packet["match_count"] = 1
        packet["source_role_counts"] = dict(sorted(source_roles.items()))
        packet["absence_claim_allowed"] = False
        return packet

    packet["source_role_counts"] = dict(sorted(source_roles.items()))
    complete = (
        not context_window_truncated
        and int_value(packet.get("unverifiable_raw_ref_count")) == 0
    )
    packet["status"] = "not_present" if complete else "incomplete"
    packet["absence_claim_allowed"] = complete
    return packet


def skill_session_evidence_probe(
    *,
    aoa_root: Path,
    anchor: str,
    session: str | None,
    before_event_id: str | None = None,
) -> dict[str, Any]:
    """Recover exact selection/read candidates from a scoped source snapshot.

    The segment route is used only to find exact skill-linked candidates.  A
    state is emitted after its raw row is opened; ``skill_read`` additionally
    requires a same-correlation, non-failing result.  This is a bounded
    query-time catch-up route, not a replacement projection.
    """
    packet: dict[str, Any] = {
        "schema_version": SKILL_SESSION_EVIDENCE_PROBE_SCHEMA_VERSION,
        "applied": bool(session),
        "status": "not_requested",
        "mutates": False,
        "bounded": True,
        "anchor": anchor,
        "before_event_id": str(before_event_id or ""),
        "exact_candidate_count": 0,
        "raw_ref_verified_count": 0,
        "raw_ref_unverifiable_count": 0,
        "selected_count": 0,
        "skill_read_count": 0,
        "read_result_verified_count": 0,
        "read_result_unverifiable_count": 0,
        "match_count": 0,
        "absence_claim_allowed": False,
        "diagnostics": [],
        "_hits": [],
    }
    if not session:
        return packet
    scan = session_query_source_event_scan(
        aoa_root=aoa_root,
        session=session,
    )
    entries = [
        entry
        for entry in (
            scan.get("_entries")
            if isinstance(scan.get("_entries"), list)
            else []
        )
        if isinstance(entry, dict)
    ]
    normalized_anchor = canonical_skill_entity_key(anchor) or route_key_slug(
        anchor,
        fallback="skill",
        max_chars=100,
    )
    before_key = str(before_event_id or "").strip()
    before_key = before_key.zfill(6) if before_key.isdigit() else before_key
    filtered_entries: list[dict[str, Any]] = []
    entries_by_correlation: defaultdict[str, list[dict[str, Any]]] = defaultdict(list)
    for entry in entries:
        event = entry.get("event") if isinstance(entry.get("event"), dict) else {}
        event_id = str(event.get("event_id") or "")
        if before_key and event_id and event_id >= before_key:
            continue
        filtered_entries.append(entry)
        correlation_id = str(event.get("correlation_id") or "")
        if correlation_id:
            entries_by_correlation[correlation_id].append(entry)

    anchor_tokens = [
        token for token in re.split(r"[-_:]+", normalized_anchor) if token
    ]
    anchor_pattern = re.compile(
        r"(?<![A-Za-z0-9_:-])"
        + r"[-_:]".join(re.escape(token) for token in anchor_tokens)
        + r"(?![A-Za-z0-9_:-])",
        flags=re.IGNORECASE,
    ) if anchor_tokens else None
    manifest_cache: dict[str, dict[str, Any]] = {}
    raw_preview_cache: dict[tuple[str, str, str, int], dict[str, Any]] = {}
    hits: dict[str, dict[str, Any]] = {}
    admitted_read_entries: list[
        tuple[
            dict[str, Any],
            dict[str, Any],
            dict[str, Any],
            dict[str, Any],
        ]
    ] = []
    raw_failures = 0
    result_failures = 0
    exact_candidate_count = 0
    for entry in filtered_entries:
        event = entry.get("event") if isinstance(entry.get("event"), dict) else {}
        exact_skill_route = any(
            str(signal.get("layer") or "") == "skill"
            and route_key_slug(
                signal.get("key"),
                fallback="",
                max_chars=100,
            )
            == normalized_anchor
            for signal in graph_route_signals_from_event(event)
            if isinstance(signal, dict)
        )
        if not exact_skill_route:
            continue
        exact_candidate_count += 1
        hit = session_query_source_hit(
            scan,
            entry,
            source="session_scoped_query_time_raw_skill_probe",
        )
        payload, payload_status = raw_payload_for_usage_segment_event(
            event,
            hit=hit,
            distance=0,
            manifest_cache=manifest_cache,
            raw_preview_cache=raw_preview_cache,
        )
        if not payload:
            raw_failures += 1
            continue
        source_type = str(event.get("source_type") or "response_item")
        raw_text = semantic_text_for_classification(
            source_type,
            payload,
            max_chars=ENTITY_USAGE_ASYNC_RAW_PREVIEW_MAX_CHARS,
        )
        hit["snippet"] = raw_text
        candidate_state = skill_evidence_state_for_event(
            hit,
            anchor=anchor,
        )
        if candidate_state == "selected":
            hit["skill_evidence_state"] = "selected"
            hit["skill_state_admission"] = (
                "raw_exact_assistant_selection_candidate"
            )
            hits[str(hit.get("doc_id") or "")] = hit
            packet["selected_count"] = (
                int_value(packet.get("selected_count")) + 1
            )
            continue
        if candidate_state != "skill_read":
            continue
        commands = entity_usage_execution_command_candidates(payload)
        exact_skill_artifact_read = bool(
            anchor_pattern
            and any(
                skill_artifact_content_read_present(
                    command.casefold(),
                    anchor_pattern=anchor_pattern,
                )
                for command in commands
            )
        )
        if not exact_skill_artifact_read:
            continue
        correlation_id = str(event.get("correlation_id") or "")
        result_entry: dict[str, Any] = {}
        result_payload: dict[str, Any] = {}
        result_status = "missing_same_correlation_result"
        for correlated_entry in entries_by_correlation.get(correlation_id, []):
            correlated_event = (
                correlated_entry.get("event")
                if isinstance(correlated_entry.get("event"), dict)
                else {}
            )
            if str(correlated_event.get("event_id") or "") <= str(
                event.get("event_id") or ""
            ):
                continue
            correlated_type = str(correlated_event.get("type") or "").upper()
            if correlated_type not in ENTITY_USAGE_RESULT_TYPES:
                continue
            correlated_hit = session_query_source_hit(
                scan,
                correlated_entry,
                source="session_scoped_query_time_raw_skill_read_result",
            )
            candidate_payload, candidate_status = (
                raw_payload_for_usage_segment_event(
                    correlated_event,
                    hit=correlated_hit,
                    distance=1,
                    manifest_cache=manifest_cache,
                    raw_preview_cache=raw_preview_cache,
                )
            )
            if candidate_payload:
                result_entry = correlated_entry
                result_payload = candidate_payload
                result_status = candidate_status
                break
        observation = entity_usage_execution_result_observation(
            result_payload
        )
        observation_status = str(observation.get("status") or "")
        if (
            not result_entry
            or result_status != "available"
            or observation_status in {"failed", "timed_out"}
        ):
            result_failures += 1
            continue
        result_hit = session_query_source_hit(
            scan,
            result_entry,
            source="session_scoped_query_time_raw_skill_read_result",
        )
        hit["skill_evidence_state"] = "skill_read"
        hit["skill_state_admission"] = (
            "raw_exact_skill_artifact_read_with_correlation_owned_result"
        )
        hit["execution_read_result_refs"] = {
            key: value
            for key, value in (result_hit.get("refs") or {}).items()
            if value
        }
        hits[str(hit.get("doc_id") or "")] = hit
        admitted_read_entries.append(
            (entry, hit, result_entry, result_payload)
        )
        packet["skill_read_count"] = (
            int_value(packet.get("skill_read_count")) + 1
        )
        packet["read_result_verified_count"] = (
            int_value(packet.get("read_result_verified_count")) + 1
        )

    # A declarative assistant plan may use a human route label rather than the
    # filesystem package name.  Admit it as a selection candidate only when a
    # canonical assistant message is immediately followed, without a user
    # boundary or competing skill, by the exact successful SKILL.md read above.
    # The read supplies identity; the declaration supplies selection intent.
    entry_positions = {id(entry): index for index, entry in enumerate(filtered_entries)}
    positive_selection_declaration = re.compile(
        r"(?:\b(?:i\s+am|i['’]m|i\s+will|i['’]ll)\s+"
        r"(?:use|using|apply|select|choose)\b|"
        r"\b(?:using|applying|selecting|choosing)\b|"
        r"\b(?:использую|применяю|выбираю|буду\s+"
        r"(?:использовать|применять|выбирать))\b)",
        flags=re.IGNORECASE,
    )
    negative_selection_declaration = re.compile(
        r"(?:\b(?:do\s+not|don't|will\s+not|won't|not)\s+"
        r"(?:use|using|apply|select|choose)\b|"
        r"\b(?:не\s+использую|не\s+применяю|не\s+выбираю|"
        r"не\s+буду\s+(?:использовать|применять|выбирать))\b)",
        flags=re.IGNORECASE,
    )
    selection_object = re.compile(
        r"\b(?:skill|скилл|route|маршрут|workflow|процедур[ауые]?)\b",
        flags=re.IGNORECASE,
    )
    for read_entry, read_hit, _result_entry, _result_payload in admitted_read_entries:
        read_position = entry_positions.get(id(read_entry))
        if read_position is None:
            continue
        lower = max(0, read_position - 6)
        for candidate_entry in reversed(filtered_entries[lower:read_position]):
            candidate_event = (
                candidate_entry.get("event")
                if isinstance(candidate_entry.get("event"), dict)
                else {}
            )
            candidate_type = str(candidate_event.get("type") or "").upper()
            if candidate_type == "USER_INTENT":
                break
            if (
                candidate_type not in {"ASSISTANT_PLAN", "ASSISTANT_MESSAGE"}
                or str(candidate_event.get("source_type") or "")
                != "response_item"
            ):
                continue
            candidate_position = entry_positions.get(id(candidate_entry), -1)
            competing_skill_keys = {
                str(signal.get("key") or "")
                for intervening_entry in filtered_entries[
                    candidate_position + 1 : read_position + 1
                ]
                for signal in graph_route_signals_from_event(
                    intervening_entry.get("event")
                    if isinstance(intervening_entry.get("event"), dict)
                    else {}
                )
                if isinstance(signal, dict)
                and str(signal.get("layer") or "") == "skill"
                and str(signal.get("key") or "") != normalized_anchor
            }
            if competing_skill_keys:
                break
            selection_hit = session_query_source_hit(
                scan,
                candidate_entry,
                source="session_scoped_query_time_raw_skill_selection_probe",
            )
            selection_payload, selection_payload_status = (
                raw_payload_for_usage_segment_event(
                    candidate_event,
                    hit=selection_hit,
                    distance=0,
                    manifest_cache=manifest_cache,
                    raw_preview_cache=raw_preview_cache,
                )
            )
            if not selection_payload:
                raw_failures += 1
                break
            selection_text = semantic_text_for_classification(
                str(candidate_event.get("source_type") or "response_item"),
                selection_payload,
                max_chars=ENTITY_USAGE_ASYNC_RAW_PREVIEW_MAX_CHARS,
            )
            if (
                not positive_selection_declaration.search(selection_text)
                or negative_selection_declaration.search(selection_text)
                or not selection_object.search(selection_text)
            ):
                continue
            selection_hit["snippet"] = selection_text
            selection_hit["skill_evidence_state"] = "selected"
            selection_hit["skill_state_admission"] = (
                "raw_assistant_selection_declaration_followed_by_exact_"
                "correlation_verified_skill_read"
            )
            selection_hit["selection_target_refs"] = dict(
                read_hit.get("refs") or {}
            )
            selection_route = route_signal_token(
                "skill",
                normalized_anchor,
            )
            selection_hit["route_signals"] = unique_preserving_order(
                [
                    *(
                        selection_hit.get("route_signals", [])
                        if isinstance(
                            selection_hit.get("route_signals"), list
                        )
                        else []
                    ),
                    selection_route,
                ]
            )
            selection_hit["entity_usage_role_override"] = "entrypoint"
            selection_doc_id = str(selection_hit.get("doc_id") or "")
            if selection_doc_id and selection_doc_id not in hits:
                hits[selection_doc_id] = selection_hit
                packet["selected_count"] = (
                    int_value(packet.get("selected_count")) + 1
                )
            break

    # ``procedure-observed`` is deliberately narrower than skill invocation:
    # the exact returned SKILL.md body must name a concrete procedure anchor,
    # and a later structured action must execute that anchor and receive its
    # own non-failing same-correlation result before the next user boundary.
    # This proves an observed procedural step, not benefit or causal effect.
    procedure_hits: dict[str, dict[str, Any]] = {}
    procedure_result_failures = 0
    for (
        _read_entry,
        read_hit,
        read_result_entry,
        read_result_payload,
    ) in admitted_read_entries:
        read_result_event = (
            read_result_entry.get("event")
            if isinstance(read_result_entry.get("event"), dict)
            else {}
        )
        procedure_body = semantic_text_for_classification(
            str(read_result_event.get("source_type") or "response_item"),
            read_result_payload,
            max_chars=ENTITY_USAGE_ASYNC_RAW_PREVIEW_MAX_CHARS,
        )
        declared_anchors = {
            match.casefold()
            for match in re.findall(
                r"\baoa_session_[a-z0-9_]{3,}\b",
                procedure_body,
                flags=re.IGNORECASE,
            )
        }
        if not declared_anchors:
            continue
        result_position = entry_positions.get(id(read_result_entry))
        if result_position is None:
            continue
        for candidate_entry in filtered_entries[
            result_position + 1 : result_position + 65
        ]:
            candidate_event = (
                candidate_entry.get("event")
                if isinstance(candidate_entry.get("event"), dict)
                else {}
            )
            if str(candidate_event.get("type") or "").upper() == "USER_INTENT":
                break
            candidate_hit = session_query_source_hit(
                scan,
                candidate_entry,
                source=(
                    "session_scoped_query_time_raw_skill_procedure_probe"
                ),
            )
            candidate_payload, _candidate_payload_status = (
                raw_payload_for_usage_segment_event(
                    candidate_event,
                    hit=candidate_hit,
                    distance=0,
                    manifest_cache=manifest_cache,
                    raw_preview_cache=raw_preview_cache,
                )
            )
            if not candidate_payload:
                continue
            invoked_tool = normalized_tool_name(
                tool_name_from_payload(candidate_payload)
            ).casefold()
            matched_anchor = next(
                (
                    declared
                    for declared in sorted(declared_anchors)
                    if invoked_tool == declared
                ),
                "",
            )
            if not matched_anchor:
                continue
            correlation_id = str(
                candidate_event.get("correlation_id") or ""
            )
            procedure_result_entry: dict[str, Any] = {}
            procedure_result_payload: dict[str, Any] = {}
            for correlated_entry in entries_by_correlation.get(
                correlation_id, []
            ):
                correlated_event = (
                    correlated_entry.get("event")
                    if isinstance(correlated_entry.get("event"), dict)
                    else {}
                )
                if str(correlated_event.get("event_id") or "") <= str(
                    candidate_event.get("event_id") or ""
                ):
                    continue
                if str(correlated_event.get("type") or "").upper() not in (
                    ENTITY_USAGE_RESULT_TYPES
                ):
                    continue
                correlated_hit = session_query_source_hit(
                    scan,
                    correlated_entry,
                    source=(
                        "session_scoped_query_time_raw_skill_procedure_result"
                    ),
                )
                candidate_result_payload, candidate_result_status = (
                    raw_payload_for_usage_segment_event(
                        correlated_event,
                        hit=correlated_hit,
                        distance=1,
                        manifest_cache=manifest_cache,
                        raw_preview_cache=raw_preview_cache,
                    )
                )
                if (
                    candidate_result_payload
                    and candidate_result_status == "available"
                ):
                    procedure_result_entry = correlated_entry
                    procedure_result_payload = candidate_result_payload
                    break
            result_observation = entity_usage_execution_result_observation(
                procedure_result_payload
            )
            if (
                not procedure_result_entry
                or str(result_observation.get("status") or "")
                in {"failed", "timed_out"}
            ):
                procedure_result_failures += 1
                continue
            procedure_result_hit = session_query_source_hit(
                scan,
                procedure_result_entry,
                source=(
                    "session_scoped_query_time_raw_skill_procedure_result"
                ),
            )
            candidate_hit.update(
                {
                    "entity_usage_role_override": "context",
                    "skill_evidence_state": "procedure_observed",
                    "skill_state_admission": (
                        "returned_skill_body_declared_exact_anchor_then_"
                        "structured_action_with_same_correlation_result"
                    ),
                    "snippet": matched_anchor,
                    "procedure_anchor": matched_anchor,
                    "observed_identity_source": str(
                        read_hit.get("snippet") or ""
                    ),
                    "procedure_definition_refs": dict(
                        session_query_source_hit(
                            scan,
                            read_result_entry,
                            source=(
                                "session_scoped_query_time_raw_skill_body"
                            ),
                        ).get("refs")
                        or {}
                    ),
                    "procedure_action_result_refs": dict(
                        procedure_result_hit.get("refs") or {}
                    ),
                }
            )
            procedure_doc_id = str(candidate_hit.get("doc_id") or "")
            if procedure_doc_id:
                procedure_hits[procedure_doc_id] = candidate_hit
            break
    hits.update(procedure_hits)
    packet.update(
        {
            "exact_candidate_count": exact_candidate_count,
            "raw_ref_verified_count": len(hits),
            "raw_ref_unverifiable_count": raw_failures,
            "read_result_unverifiable_count": result_failures,
            "procedure_observed_count": len(procedure_hits),
            "procedure_result_unverifiable_count": (
                procedure_result_failures
            ),
            "match_count": len(hits),
            "status": (
                "matched"
                if hits
                else "incomplete"
                if str(scan.get("status") or "") != "complete"
                or raw_failures
                or result_failures
                else "not_present"
            ),
            "source_scan": session_query_source_scan_summary(scan),
            "diagnostics": unique_preserving_order(
                [
                    *(
                        scan.get("diagnostics", [])
                        if isinstance(scan.get("diagnostics"), list)
                        else []
                    ),
                    *(
                        ["skill_candidate_raw_ref_unverifiable"]
                        if raw_failures
                        else []
                    ),
                    *(
                        ["skill_read_same_correlation_result_unverifiable"]
                        if result_failures
                        else []
                    ),
                ]
            ),
            "_hits": list(hits.values()),
        }
    )
    return packet


def skill_evidence_state_for_event(event: dict[str, Any], *, anchor: str) -> str:
    """Classify one skill-linked event without promoting route co-occurrence to invocation."""
    event_type = str(event.get("event_type") or "").upper()
    action = str(event.get("action") or "").casefold()
    conversation_act = str(event.get("conversation_act") or "").casefold()
    session_act = str(event.get("session_act") or "").casefold()
    haystack = " ".join(
        str(value or "")
        for value in (
            event.get("title"),
            event.get("snippet"),
            " ".join(str(item) for item in event.get("matched_routes", []) if item)
            if isinstance(event.get("matched_routes"), list)
            else "",
            " ".join(str(item) for item in event.get("route_signals", []) if item)
            if isinstance(event.get("route_signals"), list)
            else event.get("route_signals"),
        )
    ).casefold()
    normalized_anchor = canonical_skill_entity_key(anchor) or route_key_slug(
        anchor,
        fallback="skill",
        max_chars=100,
    )
    if (
        str(event.get("prompt_visibility_admission") or "")
        == "structured_available_skills_entry"
        and str(event.get("prompt_visibility_skill_key") or "")
        == normalized_anchor
    ):
        return "prompt_visible"
    route_signal_values: list[str] = []
    for value in (event.get("route_signals"), event.get("matched_routes")):
        if isinstance(value, str):
            route_signal_values.extend(item for item in value.split("|") if item)
        elif isinstance(value, (list, tuple)):
            route_signal_values.extend(str(item) for item in value if item)
    exact_skill_route_keys = {
        route_key_slug(str(signal).partition(":")[2], fallback="", max_chars=100)
        for signal in route_signal_values
        if ":" in str(signal)
        and str(signal).partition(":")[0].casefold() == "skill"
    }
    exact_skill_route_keys.discard("")
    exact_skill_route_present = normalized_anchor in exact_skill_route_keys
    anchor_tokens = [token for token in re.split(r"[-_:]+", normalized_anchor) if token]
    anchor_token_pattern = r"[-_:]".join(re.escape(token) for token in anchor_tokens)
    bounded_anchor_pattern = (
        r"(?<![A-Za-z0-9_:-])" + anchor_token_pattern + r"(?![A-Za-z0-9_:-])"
        if anchor_tokens
        else ""
    )
    anchor_text_pattern = re.compile(bounded_anchor_pattern, flags=re.IGNORECASE) if bounded_anchor_pattern else None
    anchor_present = exact_skill_route_present or bool(
        anchor_text_pattern and anchor_text_pattern.search(haystack)
    )
    skill_content_read_detected = bool(
        anchor_present
        and event_type in {"TOOL_CALL", "COMMAND", "FILE_READ"}
        and skill_artifact_content_read_present(
            haystack,
            anchor_pattern=anchor_text_pattern,
        )
    )

    if session_act == "skill_explicit_selection":
        structured_skill_name = route_key_slug(
            event.get("structured_skill_name"),
            fallback="",
            max_chars=80,
        )
        if structured_skill_name:
            if structured_skill_name == normalized_anchor:
                return "selected"
            return "mentioned" if anchor_present else "cooccurrence"
        if exact_skill_route_keys == {normalized_anchor}:
            return "selected"

    if event_type in {"FILE_WRITE", "DIFF"} or action in {"write", "edit", "mutate_workspace"} or session_act in {"file_mutation", "memory_write"}:
        return "edited" if anchor_present else "cooccurrence"
    if skill_content_read_detected:
        return "skill_read"
    if event_type == "FILE_READ" or action in {"read", "inspect_workspace"} or session_act in {"file_inspection", "memory_read"}:
        if anchor_present and ("skill.md" in haystack or "skills_" in haystack or "skill:" in haystack):
            return "skill_read"
        return "mentioned" if anchor_present else "cooccurrence"
    assistant_selection_surface = event_type in {
        "ASSISTANT_PLAN",
        "ASSISTANT_MESSAGE",
        "DECISION",
        "CHECKPOINT",
    }
    selection_text = " ".join(
        str(value or "")
        for value in (event.get("title"), event.get("snippet"))
    ).casefold()
    selection_target_pattern = (
        r"(?:[`'\"])?(?:the\s+)?(?:"
        + r"(?:skill|скилл|скилла)[:\s]+"
        + anchor_token_pattern
        + r"(?![A-Za-z0-9_:-])|"
        + bounded_anchor_pattern
        + r")"
        + r"(?:[`'\"])?(?:\s+(?:skill|скилл))?"
        if bounded_anchor_pattern
        else ""
    )
    positive_selection_verb_pattern = (
        r"(?:"
        r"\b(?:i\s+am|i['’]m|i\s+will|i['’]ll)\s+(?:use|using|apply|select|choose)\s+"
        r"|\b(?:using|applying|selecting|selected|choosing)\s+"
        r"|\b(?:использую|применяю|выбираю|буду\s+(?:использовать|применять|выбирать))\s+"
        r")"
    )
    negative_selection_verb_pattern = (
        r"(?:"
        r"\b(?:i\s+)?(?:do\s+not|don't|will\s+not|won't)\s+(?:use|apply|select|choose)\s+"
        r"|\bnot\s+(?:using|applying|selecting|choosing)\s+"
        r"|\b(?:не\s+использую|не\s+применяю|не\s+выбираю|не\s+буду\s+(?:использовать|применять|выбирать))\s+"
        r")"
    )
    selection_list_item_pattern = (
        r"(?:[`'\"“”‘’])?"
        r"(?:(?:the\s+)?(?:skill|скилл|скилла)\s+)?"
        r"[A-Za-z0-9][A-Za-z0-9_.:@+/-]{0,120}"
        r"(?:[`'\"“”‘’])?"
    )
    selection_list_separator_pattern = r"(?:\s*,\s*|\s+(?:and|и)\s+|\s*&\s*)"
    coordinated_selection_prefix_pattern = (
        r"(?:" + selection_list_item_pattern + selection_list_separator_pattern + r")+"
    )
    selection_clause_body_pattern = (
        r"(?:(?:`[^`\n]{1,160}`)|[^.!?:;\n`]){1,360}?"
    )
    coordinated_selection_object_pattern = (
        selection_clause_body_pattern
        + r"(?:\s+|\s*,\s*)(?:and|и|&)\s+"
        + selection_target_pattern
    )
    positive_selection_pattern = (
        re.compile(
            positive_selection_verb_pattern + selection_target_pattern,
            flags=re.IGNORECASE,
        )
        if selection_target_pattern
        else None
    )
    coordinated_positive_selection_pattern = (
        re.compile(
            positive_selection_verb_pattern
            + coordinated_selection_prefix_pattern
            + selection_target_pattern,
            flags=re.IGNORECASE,
        )
        if selection_target_pattern
        else None
    )
    described_coordinated_positive_selection_pattern = (
        re.compile(
            positive_selection_verb_pattern
            + coordinated_selection_object_pattern,
            flags=re.IGNORECASE,
        )
        if selection_target_pattern
        else None
    )
    negative_selection_pattern = (
        re.compile(
            negative_selection_verb_pattern
            + selection_target_pattern
            + r"|"
            + r"\b(?:instead\s+of|rather\s+than)(?:\s+using)?\s+"
            + selection_target_pattern
            + r"|\bвместо\s+"
            + selection_target_pattern
            + r"|\bnot\s+"
            + selection_target_pattern
            + r"|"
            + bounded_anchor_pattern
            + r"\s+не\s+(?:использую|применяю|выбираю)",
            flags=re.IGNORECASE,
        )
        if selection_target_pattern
        else None
    )
    coordinated_negative_selection_pattern = (
        re.compile(
            negative_selection_verb_pattern
            + coordinated_selection_prefix_pattern
            + selection_target_pattern,
            flags=re.IGNORECASE,
        )
        if selection_target_pattern
        else None
    )
    described_coordinated_negative_selection_pattern = (
        re.compile(
            negative_selection_verb_pattern
            + coordinated_selection_object_pattern,
            flags=re.IGNORECASE,
        )
        if selection_target_pattern
        else None
    )
    selection_target_present = bool(
        (
            positive_selection_pattern
            and positive_selection_pattern.search(selection_text)
        )
        or (
            coordinated_positive_selection_pattern
            and coordinated_positive_selection_pattern.search(selection_text)
        )
        or (
            described_coordinated_positive_selection_pattern
            and described_coordinated_positive_selection_pattern.search(selection_text)
        )
    )
    selection_target_negated = bool(
        (
            negative_selection_pattern
            and negative_selection_pattern.search(selection_text)
        )
        or (
            coordinated_negative_selection_pattern
            and coordinated_negative_selection_pattern.search(selection_text)
        )
        or (
            described_coordinated_negative_selection_pattern
            and described_coordinated_negative_selection_pattern.search(selection_text)
        )
    )
    explicit_selection_signal = (
        "skill_selected" in selection_text
        or "skill selection" in conversation_act
    )
    if (
        assistant_selection_surface
        and anchor_present
        and not selection_target_negated
        and (selection_target_present or explicit_selection_signal)
    ):
        return "selected"
    return "mentioned" if anchor_present else "cooccurrence"


def effective_skill_evidence_state_for_event(
    event: dict[str, Any],
    *,
    anchor: str,
) -> str:
    """Preserve a stricter raw-backed state before heuristic reclassification."""
    explicit_state = str(event.get("skill_evidence_state") or "")
    if explicit_state in SKILL_ACCEPTED_EVIDENCE_STATES:
        return explicit_state
    return skill_evidence_state_for_event(event, anchor=anchor)


def _skill_usage_receipt_key_issues(
    value: Any,
    *,
    label: str,
    required: set[str],
    allowed: set[str],
) -> tuple[dict[str, Any], list[str]]:
    if not isinstance(value, dict):
        return {}, [f"{label}: expected object"]
    issues: list[str] = []
    missing = sorted(required - set(value))
    extra = sorted(set(value) - allowed)
    if missing:
        issues.append(f"{label}: missing fields: {', '.join(missing)}")
    if extra:
        issues.append(f"{label}: unknown fields: {', '.join(extra)}")
    return value, issues


def _skill_usage_receipt_ref_issues(
    value: Any,
    *,
    label: str,
    min_items: int = 0,
) -> list[str]:
    if not isinstance(value, list):
        return [f"{label}: expected array"]
    issues: list[str] = []
    if len(value) < min_items:
        issues.append(f"{label}: requires at least {min_items} item(s)")
    seen: set[str] = set()
    for index, item in enumerate(value):
        if not isinstance(item, str) or not item.strip():
            issues.append(f"{label}[{index}]: expected non-empty evidence ref")
            continue
        if len(item) > 2048:
            issues.append(f"{label}[{index}]: evidence ref exceeds 2048 characters")
        if item in seen:
            issues.append(f"{label}[{index}]: duplicate evidence ref")
        seen.add(item)
    return issues


def validate_skill_usage_receipt(
    payload: Any,
    *,
    expected_skill: str | None = None,
) -> list[str]:
    top, issues = _skill_usage_receipt_key_issues(
        payload,
        label="<root>",
        required={
            "schema_version",
            "receipt_id",
            "created_at",
            "skill",
            "runtime",
            "episode",
            "evidence",
            "attribution",
            "review",
            "authority",
        },
        allowed={
            "schema_version",
            "receipt_id",
            "created_at",
            "skill",
            "runtime",
            "episode",
            "evidence",
            "attribution",
            "review",
            "authority",
        },
    )
    if not top:
        return issues
    if top.get("schema_version") != SKILL_USAGE_RECEIPT_SCHEMA_VERSION:
        issues.append(
            f"schema_version: expected {SKILL_USAGE_RECEIPT_SCHEMA_VERSION!r}"
        )
    receipt_id = str(top.get("receipt_id") or "")
    if SKILL_USAGE_RECEIPT_ID_RE.fullmatch(receipt_id) is None:
        issues.append("receipt_id: expected skill-use-<stable-slug>")
    for field in ("created_at",):
        try:
            parse_timestamp_arg(str(top.get(field) or ""))
        except ValueError as exc:
            issues.append(f"{field}: {exc}")

    skill, nested = _skill_usage_receipt_key_issues(
        top.get("skill"),
        label="skill",
        required={
            "name",
            "source_version",
            "source_fingerprint",
            "source_revision",
            "source_ref",
            "capability_graph_hash",
            "installed_status",
            "prompt_visible_status",
            "selected_version",
            "selected_fingerprint",
            "executed_version",
            "executed_fingerprint",
            "identity_status",
        },
        allowed={
            "name",
            "source_version",
            "source_fingerprint",
            "source_revision",
            "source_ref",
            "capability_graph_hash",
            "installed_status",
            "installed_version",
            "installed_digest",
            "install_receipt_ref",
            "prompt_visible_status",
            "prompt_visible_version",
            "prompt_description_sha256",
            "selected_version",
            "selected_fingerprint",
            "executed_version",
            "executed_fingerprint",
            "identity_status",
        },
    )
    issues.extend(nested)
    raw_skill_name = str(skill.get("name") or "")
    skill_name = canonical_skill_entity_key(raw_skill_name)
    if (
        not skill_name
        or SKILL_USAGE_RECEIPT_SKILL_RE.fullmatch(raw_skill_name) is None
    ):
        issues.append("skill.name: expected one canonical skill identity")
    expected_key = canonical_skill_entity_key(expected_skill or "")
    if expected_key and skill_name != expected_key:
        issues.append(
            f"skill.name: receipt names {skill_name!r}, expected {expected_key!r}"
        )
    version_fields = (
        "source_version",
        "selected_version",
        "executed_version",
    )
    for field in version_fields:
        if SKILL_USAGE_RECEIPT_VERSION_RE.fullmatch(
            str(skill.get(field) or "")
        ) is None:
            issues.append(f"skill.{field}: expected semantic version")
    for field in ("installed_version", "prompt_visible_version"):
        if field in skill and SKILL_USAGE_RECEIPT_VERSION_RE.fullmatch(
            str(skill.get(field) or "")
        ) is None:
            issues.append(f"skill.{field}: expected semantic version")
    for field in (
        "source_fingerprint",
        "capability_graph_hash",
        "selected_fingerprint",
        "executed_fingerprint",
    ):
        if SKILL_USAGE_RECEIPT_SHA256_RE.fullmatch(
            str(skill.get(field) or "")
        ) is None:
            issues.append(f"skill.{field}: expected lowercase sha256")
    for field in ("installed_digest", "prompt_description_sha256"):
        if field in skill and SKILL_USAGE_RECEIPT_SHA256_RE.fullmatch(
            str(skill.get(field) or "")
        ) is None:
            issues.append(f"skill.{field}: expected lowercase sha256")
    if not str(skill.get("source_revision") or "").strip():
        issues.append("skill.source_revision: expected non-empty source revision")
    if not str(skill.get("source_ref") or "").strip():
        issues.append("skill.source_ref: expected non-empty evidence ref")
    surface_statuses = {
        "current",
        "drift",
        "not-applicable",
        "unverifiable",
    }
    installed_status = str(skill.get("installed_status") or "")
    prompt_visible_status = str(skill.get("prompt_visible_status") or "")
    if installed_status not in surface_statuses:
        issues.append("skill.installed_status: unsupported value")
    if prompt_visible_status not in surface_statuses:
        issues.append("skill.prompt_visible_status: unsupported value")
    installed_fields = (
        "installed_version",
        "installed_digest",
        "install_receipt_ref",
    )
    if installed_status in {"current", "drift"}:
        for field in installed_fields:
            if not str(skill.get(field) or "").strip():
                issues.append(
                    f"skill.{field}: required when installed_status="
                    f"{installed_status}"
                )
    elif installed_status == "not-applicable":
        for field in installed_fields:
            if field in skill:
                issues.append(
                    f"skill.{field}: forbidden when installed_status="
                    "not-applicable"
                )
    prompt_fields = (
        "prompt_visible_version",
        "prompt_description_sha256",
    )
    if prompt_visible_status in {"current", "drift"}:
        for field in prompt_fields:
            if not str(skill.get(field) or "").strip():
                issues.append(
                    f"skill.{field}: required when prompt_visible_status="
                    f"{prompt_visible_status}"
                )
    elif prompt_visible_status == "not-applicable":
        for field in prompt_fields:
            if field in skill:
                issues.append(
                    f"skill.{field}: forbidden when prompt_visible_status="
                    "not-applicable"
                )
    if skill.get("identity_status") not in {"current", "drift", "unverifiable"}:
        issues.append("skill.identity_status: unsupported value")
    if "install_receipt_ref" in skill and not str(
        skill.get("install_receipt_ref") or ""
    ).strip():
        issues.append("skill.install_receipt_ref: expected non-empty evidence ref")
    core_versions = {
        str(skill.get(field) or "")
        for field in ("source_version", "selected_version", "executed_version")
    }
    core_fingerprints = {
        str(skill.get(field) or "")
        for field in (
            "source_fingerprint",
            "selected_fingerprint",
            "executed_fingerprint",
        )
    }
    drift_present = bool(
        installed_status == "drift"
        or prompt_visible_status == "drift"
        or len(core_versions) != 1
        or len(core_fingerprints) != 1
        or (
            installed_status == "current"
            and skill.get("installed_version") != skill.get("source_version")
        )
        or (
            prompt_visible_status == "current"
            and skill.get("prompt_visible_version")
            != skill.get("source_version")
        )
    )
    if skill.get("identity_status") == "current":
        if drift_present or installed_status == "unverifiable" or (
            prompt_visible_status == "unverifiable"
        ):
            issues.append(
                "skill.identity_status=current requires every applicable "
                "surface plus selected/executed versions and fingerprints "
                "to be current"
            )
    elif skill.get("identity_status") == "drift" and not drift_present:
        issues.append(
            "skill.identity_status=drift requires one explicit surface, "
            "version, or fingerprint mismatch"
        )
    elif skill.get("identity_status") == "unverifiable" and (
        installed_status != "unverifiable"
        and prompt_visible_status != "unverifiable"
    ):
        issues.append(
            "skill.identity_status=unverifiable requires an unverifiable "
            "installed or prompt-visible surface"
        )

    runtime, nested = _skill_usage_receipt_key_issues(
        top.get("runtime"),
        label="runtime",
        required={
            "runtime",
            "host",
            "model",
            "initial_context_ref",
            "retrieval_mode",
            "tools",
            "permissions",
        },
        allowed={
            "runtime",
            "host",
            "model",
            "initial_context_ref",
            "retrieval_mode",
            "tools",
            "permissions",
        },
    )
    issues.extend(nested)
    for field in ("runtime", "host", "model", "initial_context_ref"):
        if not isinstance(runtime.get(field), str) or not str(
            runtime.get(field) or ""
        ).strip():
            issues.append(f"runtime.{field}: expected non-empty string")
    if runtime.get("retrieval_mode") not in {
        "prompt-visible",
        "direct",
        "retrieved",
        "composed",
    }:
        issues.append("runtime.retrieval_mode: unsupported value")
    if (
        runtime.get("retrieval_mode") == "prompt-visible"
        and prompt_visible_status
        not in {"current", "drift", "unverifiable"}
    ):
        issues.append(
            "runtime.retrieval_mode=prompt-visible requires a declared "
            "prompt-visible identity surface"
        )
    for field in ("tools", "permissions"):
        values = runtime.get(field)
        if not isinstance(values, list) or any(
            not isinstance(item, str) or not item.strip() for item in values or []
        ):
            issues.append(f"runtime.{field}: expected array of non-empty strings")
        elif len(values) != len(set(values)):
            issues.append(f"runtime.{field}: duplicate values are forbidden")

    episode, nested = _skill_usage_receipt_key_issues(
        top.get("episode"),
        label="episode",
        required={"session_id", "task_episode_id", "request_ref", "outcome_ref"},
        allowed={"session_id", "task_episode_id", "request_ref", "outcome_ref"},
    )
    issues.extend(nested)
    for field in ("session_id", "task_episode_id", "request_ref", "outcome_ref"):
        if not isinstance(episode.get(field), str) or not str(
            episode.get(field) or ""
        ).strip():
            issues.append(f"episode.{field}: expected non-empty string")

    evidence, nested = _skill_usage_receipt_key_issues(
        top.get("evidence"),
        label="evidence",
        required={
            "state",
            "procedure_observations",
            "tool_calls",
            "checkpoints",
            "verifier",
            "consequence_refs",
        },
        allowed={
            "state",
            "procedure_observations",
            "tool_calls",
            "checkpoints",
            "verifier",
            "consequence_refs",
        },
    )
    issues.extend(nested)
    state = str(evidence.get("state") or "")
    if state not in {"procedure_observed", "verified", "completed", "deflected"}:
        issues.append("evidence.state: unsupported value")
    observations = evidence.get("procedure_observations")
    if not isinstance(observations, list):
        issues.append("evidence.procedure_observations: expected array")
        observations = []
    observed_count = 0
    for index, raw_observation in enumerate(observations):
        observation, nested = _skill_usage_receipt_key_issues(
            raw_observation,
            label=f"evidence.procedure_observations[{index}]",
            required={"section", "status", "evidence_ref"},
            allowed={"section", "status", "evidence_ref"},
        )
        issues.extend(nested)
        if not str(observation.get("section") or "").strip():
            issues.append(
                f"evidence.procedure_observations[{index}].section: expected value"
            )
        if observation.get("status") not in {
            "observed",
            "not-observed",
            "not-applicable",
        }:
            issues.append(
                f"evidence.procedure_observations[{index}].status: unsupported value"
            )
        if not str(observation.get("evidence_ref") or "").strip():
            issues.append(
                f"evidence.procedure_observations[{index}].evidence_ref: expected ref"
            )
        if observation.get("status") == "observed":
            observed_count += 1

    tool_calls = evidence.get("tool_calls")
    if not isinstance(tool_calls, list):
        issues.append("evidence.tool_calls: expected array")
        tool_calls = []
    for index, raw_call in enumerate(tool_calls):
        call, nested = _skill_usage_receipt_key_issues(
            raw_call,
            label=f"evidence.tool_calls[{index}]",
            required={"tool", "call_ref", "result_ref"},
            allowed={"tool", "call_ref", "result_ref"},
        )
        issues.extend(nested)
        for field in ("tool", "call_ref", "result_ref"):
            if not str(call.get(field) or "").strip():
                issues.append(
                    f"evidence.tool_calls[{index}].{field}: expected value"
                )

    checkpoints = evidence.get("checkpoints")
    if not isinstance(checkpoints, list):
        issues.append("evidence.checkpoints: expected array")
        checkpoints = []
    passed_checkpoint_count = 0
    for index, raw_checkpoint in enumerate(checkpoints):
        checkpoint, nested = _skill_usage_receipt_key_issues(
            raw_checkpoint,
            label=f"evidence.checkpoints[{index}]",
            required={"id", "status", "evidence_refs"},
            allowed={"id", "status", "evidence_refs"},
        )
        issues.extend(nested)
        if not str(checkpoint.get("id") or "").strip():
            issues.append(f"evidence.checkpoints[{index}].id: expected value")
        if checkpoint.get("status") not in {
            "passed",
            "failed",
            "not-run",
            "not-applicable",
        }:
            issues.append(
                f"evidence.checkpoints[{index}].status: unsupported value"
            )
        if checkpoint.get("status") == "passed":
            passed_checkpoint_count += 1
        issues.extend(
            _skill_usage_receipt_ref_issues(
                checkpoint.get("evidence_refs"),
                label=f"evidence.checkpoints[{index}].evidence_refs",
                min_items=1 if checkpoint.get("status") == "passed" else 0,
            )
        )

    verifier, nested = _skill_usage_receipt_key_issues(
        evidence.get("verifier"),
        label="evidence.verifier",
        required={
            "kind",
            "id",
            "independent_from_executor",
            "verdict",
            "evidence_refs",
        },
        allowed={
            "kind",
            "id",
            "independent_from_executor",
            "verdict",
            "evidence_refs",
        },
    )
    issues.extend(nested)
    if verifier.get("kind") not in {
        "owner-check",
        "independent-eval",
        "human-review",
        "tool",
    }:
        issues.append("evidence.verifier.kind: unsupported value")
    if not str(verifier.get("id") or "").strip():
        issues.append("evidence.verifier.id: expected value")
    if not isinstance(verifier.get("independent_from_executor"), bool):
        issues.append(
            "evidence.verifier.independent_from_executor: expected boolean"
        )
    if verifier.get("verdict") not in {
        "passed",
        "failed",
        "inconclusive",
        "not-run",
    }:
        issues.append("evidence.verifier.verdict: unsupported value")
    issues.extend(
        _skill_usage_receipt_ref_issues(
            verifier.get("evidence_refs"),
            label="evidence.verifier.evidence_refs",
            min_items=1 if verifier.get("verdict") == "passed" else 0,
        )
    )
    consequence_refs = evidence.get("consequence_refs")
    issues.extend(
        _skill_usage_receipt_ref_issues(
            consequence_refs,
            label="evidence.consequence_refs",
            min_items=1 if state == "completed" else 0,
        )
    )

    attribution, nested = _skill_usage_receipt_key_issues(
        top.get("attribution"),
        label="attribution",
        required={
            "invocation_status",
            "contribution_status",
            "alternative_explanations",
        },
        allowed={
            "invocation_status",
            "contribution_status",
            "alternative_explanations",
            "comparison_ref",
            "eval_verdict_ref",
        },
    )
    issues.extend(nested)
    invocation_status = attribution.get("invocation_status")
    if invocation_status not in {"observed", "deflected"}:
        issues.append("attribution.invocation_status: unsupported value")
    contribution_status = attribution.get("contribution_status")
    if contribution_status not in {
        "candidate",
        "supported",
        "not-supported",
        "unknown",
    }:
        issues.append("attribution.contribution_status: unsupported value")
    alternatives = attribution.get("alternative_explanations")
    if (
        not isinstance(alternatives, list)
        or not alternatives
        or any(not isinstance(item, str) or not item.strip() for item in alternatives)
    ):
        issues.append(
            "attribution.alternative_explanations: expected non-empty string array"
        )
    if contribution_status == "supported":
        if not str(attribution.get("comparison_ref") or "").strip():
            issues.append(
                "attribution.comparison_ref: required for supported contribution"
            )
        if not str(attribution.get("eval_verdict_ref") or "").strip():
            issues.append(
                "attribution.eval_verdict_ref: required for supported contribution"
            )
        if verifier.get("independent_from_executor") is not True:
            issues.append(
                "supported contribution requires a verifier independent from executor"
            )

    review, nested = _skill_usage_receipt_key_issues(
        top.get("review"),
        label="review",
        required={
            "status",
            "reviewer",
            "reviewer_kind",
            "independent_from_executor",
            "authority_ref",
            "reviewed_at",
            "evidence_refs",
        },
        allowed={
            "status",
            "reviewer",
            "reviewer_kind",
            "independent_from_executor",
            "authority_ref",
            "reviewed_at",
            "evidence_refs",
        },
    )
    issues.extend(nested)
    if review.get("status") != "approved":
        issues.append("review.status: only approved receipts are ingestible")
    if not str(review.get("reviewer") or "").strip():
        issues.append("review.reviewer: expected value")
    if review.get("reviewer_kind") not in {
        "owner",
        "human",
        "independent-agent",
        "tool",
    }:
        issues.append("review.reviewer_kind: unsupported value")
    if review.get("independent_from_executor") is not True:
        issues.append(
            "review.independent_from_executor: must be true for admission"
        )
    if not str(review.get("authority_ref") or "").strip():
        issues.append("review.authority_ref: expected evidence ref")
    try:
        parse_timestamp_arg(str(review.get("reviewed_at") or ""))
    except ValueError as exc:
        issues.append(f"review.reviewed_at: {exc}")
    issues.extend(
        _skill_usage_receipt_ref_issues(
            review.get("evidence_refs"),
            label="review.evidence_refs",
            min_items=1,
        )
    )

    authority, nested = _skill_usage_receipt_key_issues(
        top.get("authority"),
        label="authority",
        required={"candidate_only", "benefit_verdict", "claim_limit"},
        allowed={"candidate_only", "benefit_verdict", "claim_limit"},
    )
    issues.extend(nested)
    if authority.get("candidate_only") is not True:
        issues.append("authority.candidate_only: must remain true")
    if authority.get("benefit_verdict") is not False:
        issues.append("authority.benefit_verdict: must remain false")
    if authority.get("claim_limit") != SKILL_USAGE_RECEIPT_CLAIM_LIMIT:
        issues.append("authority.claim_limit: owner proof ceiling changed")

    if state == "deflected":
        if invocation_status != "deflected":
            issues.append(
                "deflected evidence requires attribution.invocation_status=deflected"
            )
        if consequence_refs:
            issues.append(
                "deflected evidence must not claim execution consequences"
            )
        if contribution_status not in {"not-supported", "unknown"}:
            issues.append(
                "deflected evidence cannot claim candidate or supported "
                "contribution"
            )
    else:
        if invocation_status != "observed":
            issues.append(
                "observed procedure evidence requires invocation_status=observed"
            )
        if observed_count < 1:
            issues.append(
                "observed invocation requires at least one observed procedure section"
            )
    if state in {"verified", "completed"}:
        if not checkpoints or passed_checkpoint_count != len(checkpoints):
            issues.append(
                f"{state} evidence requires every declared checkpoint to pass"
            )
        if verifier.get("verdict") != "passed":
            issues.append(f"{state} evidence requires a passed verifier")
    return sorted(set(issues))


def skill_usage_receipt_admission(
    payload: dict[str, Any],
    *,
    receipt_ref: str = "",
    expected_skill: str | None = None,
) -> dict[str, Any]:
    issues = validate_skill_usage_receipt(
        payload,
        expected_skill=expected_skill,
    )
    skill = payload.get("skill") if isinstance(payload.get("skill"), dict) else {}
    evidence = (
        payload.get("evidence") if isinstance(payload.get("evidence"), dict) else {}
    )
    attribution = (
        payload.get("attribution")
        if isinstance(payload.get("attribution"), dict)
        else {}
    )
    episode = (
        payload.get("episode") if isinstance(payload.get("episode"), dict) else {}
    )
    state = str(evidence.get("state") or "")
    identity_status = str(skill.get("identity_status") or "")
    identity_resolved = identity_status in {"current", "drift"}
    source_current = identity_status == "current"
    selection_execution_identity_matches = bool(
        skill.get("selected_version")
        and skill.get("selected_version") == skill.get("executed_version")
        and skill.get("selected_fingerprint")
        and skill.get("selected_fingerprint")
        == skill.get("executed_fingerprint")
    )
    observed_procedure = any(
        isinstance(item, dict) and item.get("status") == "observed"
        for item in evidence.get("procedure_observations", [])
        if isinstance(evidence.get("procedure_observations"), list)
    )
    checkpoints_passed = bool(evidence.get("checkpoints")) and all(
        isinstance(item, dict) and item.get("status") == "passed"
        for item in evidence.get("checkpoints", [])
        if isinstance(evidence.get("checkpoints"), list)
    )
    verifier = (
        evidence.get("verifier")
        if isinstance(evidence.get("verifier"), dict)
        else {}
    )
    reviewed = (
        isinstance(payload.get("review"), dict)
        and payload["review"].get("status") == "approved"
        and payload["review"].get("independent_from_executor") is True
        and bool(str(payload["review"].get("authority_ref") or "").strip())
    )
    invocation_claim_allowed = bool(
        not issues
        and reviewed
        and identity_resolved
        and selection_execution_identity_matches
        and state in {"procedure_observed", "verified", "completed"}
        and observed_procedure
        and attribution.get("invocation_status") == "observed"
    )
    verification_claim_allowed = bool(
        invocation_claim_allowed
        and state in {"verified", "completed"}
        and checkpoints_passed
        and verifier.get("verdict") == "passed"
    )
    deflection_claim_allowed = bool(
        not issues
        and reviewed
        and identity_resolved
        and selection_execution_identity_matches
        and state == "deflected"
        and attribution.get("invocation_status") == "deflected"
    )
    consequence_refs = (
        evidence.get("consequence_refs")
        if isinstance(evidence.get("consequence_refs"), list)
        else []
    )
    effect_attribution_candidate_present = bool(
        verification_claim_allowed
        and consequence_refs
        and attribution.get("contribution_status")
        in {"candidate", "supported", "not-supported"}
    )
    return {
        "receipt_id": payload.get("receipt_id"),
        "receipt_ref": receipt_ref,
        "skill": skill.get("name"),
        "source_version": skill.get("source_version"),
        "source_fingerprint": skill.get("source_fingerprint"),
        "source_revision": skill.get("source_revision"),
        "source_ref": skill.get("source_ref"),
        "capability_graph_hash": skill.get("capability_graph_hash"),
        "installed_status": skill.get("installed_status"),
        "installed_version": skill.get("installed_version"),
        "installed_digest": skill.get("installed_digest"),
        "prompt_visible_status": skill.get("prompt_visible_status"),
        "prompt_visible_version": skill.get("prompt_visible_version"),
        "selected_version": skill.get("selected_version"),
        "selected_fingerprint": skill.get("selected_fingerprint"),
        "executed_version": skill.get("executed_version"),
        "executed_fingerprint": skill.get("executed_fingerprint"),
        "identity_status": identity_status,
        "identity_resolved": identity_resolved,
        "source_current": source_current,
        "selection_execution_identity_matches": (
            selection_execution_identity_matches
        ),
        "promotion_identity_eligible": source_current,
        "session_id": episode.get("session_id"),
        "task_episode_id": episode.get("task_episode_id"),
        "state": state,
        "valid": not issues,
        "reviewed": reviewed,
        "invocation_claim_allowed": invocation_claim_allowed,
        "verification_claim_allowed": verification_claim_allowed,
        "deflection_claim_allowed": deflection_claim_allowed,
        "effect_attribution_candidate_present": (
            effect_attribution_candidate_present
        ),
        "contribution_status": attribution.get("contribution_status"),
        "benefit_claim_allowed": False,
        "benefit_claim_blocker": (
            "aoa_evals_verdict_resolution_required"
            if effect_attribution_candidate_present
            else "no_verified_effect_attribution_candidate"
        ),
        "issues": issues,
        "authority_boundary": SKILL_USAGE_RECEIPT_CLAIM_LIMIT,
    }


def load_skill_usage_receipts(
    *,
    aoa_root: Path,
    anchor: str | None = None,
    session: str | None = None,
    limit: int = 100,
) -> dict[str, Any]:
    root = aoa_root / SKILL_USAGE_RECEIPT_ROOT
    expected_skill = canonical_skill_entity_key(anchor or "")
    receipts: list[dict[str, Any]] = []
    diagnostics: list[str] = []
    scanned_count = 0
    if root.is_dir() and not root.is_symlink():
        for path in sorted(root.glob("*.json")):
            if scanned_count >= max(1, min(limit, 1000)):
                diagnostics.append("skill_usage_receipt_scan_truncated")
                break
            scanned_count += 1
            if path.is_symlink() or not path.is_file():
                diagnostics.append(
                    f"{path.name}:receipt_must_be_regular_non_symlink_file"
                )
                continue
            if path.stat().st_size > SKILL_USAGE_RECEIPT_MAX_BYTES:
                diagnostics.append(f"{path.name}:receipt_exceeds_size_limit")
                continue
            try:
                payload = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, UnicodeDecodeError, json.JSONDecodeError):
                diagnostics.append(f"{path.name}:receipt_unreadable_or_invalid_json")
                continue
            payload_skill = (
                payload.get("skill", {}).get("name")
                if isinstance(payload, dict)
                and isinstance(payload.get("skill"), dict)
                else ""
            )
            canonical_payload_skill = canonical_skill_entity_key(
                str(payload_skill or "")
            )
            if expected_skill and canonical_payload_skill != expected_skill:
                continue
            admission = skill_usage_receipt_admission(
                payload if isinstance(payload, dict) else {},
                receipt_ref=str(path),
                expected_skill=expected_skill,
            )
            if session and str(admission.get("session_id") or "") != session:
                continue
            receipts.append(admission)
            diagnostics.extend(
                f"{path.name}:{issue}" for issue in admission.get("issues", [])
            )
    return {
        "schema_version": "skill_usage_receipt_inventory_v1",
        "root": str(root),
        "anchor": expected_skill or "",
        "session": session or "",
        "scanned_count": scanned_count,
        "receipt_count": len(receipts),
        "valid_count": sum(bool(item.get("valid")) for item in receipts),
        "invocation_claim_count": sum(
            bool(item.get("invocation_claim_allowed")) for item in receipts
        ),
        "verification_claim_count": sum(
            bool(item.get("verification_claim_allowed")) for item in receipts
        ),
        "deflection_claim_count": sum(
            bool(item.get("deflection_claim_allowed")) for item in receipts
        ),
        "effect_attribution_candidate_count": sum(
            bool(item.get("effect_attribution_candidate_present"))
            for item in receipts
        ),
        "receipts": receipts,
        "diagnostics": diagnostics[:100],
        "authority_boundary": SKILL_USAGE_RECEIPT_CLAIM_LIMIT,
    }


def record_skill_usage_receipt(
    *,
    aoa_root: Path,
    receipt_path: Path,
    apply: bool = False,
) -> dict[str, Any]:
    receipt_path = receipt_path.expanduser().resolve()
    diagnostics: list[str] = []
    if receipt_path.is_symlink() or not receipt_path.is_file():
        diagnostics.append("receipt_source_must_be_regular_non_symlink_file")
        payload: Any = {}
    elif receipt_path.stat().st_size > SKILL_USAGE_RECEIPT_MAX_BYTES:
        diagnostics.append("receipt_source_exceeds_size_limit")
        payload = {}
    else:
        try:
            payload = json.loads(receipt_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
            diagnostics.append(f"receipt_source_unreadable_or_invalid_json:{exc}")
            payload = {}
    issues = validate_skill_usage_receipt(payload)
    diagnostics.extend(issues)
    receipt_id = str(payload.get("receipt_id") or "") if isinstance(payload, dict) else ""
    target = aoa_root / SKILL_USAGE_RECEIPT_ROOT / f"{receipt_id}.json"
    source_digest = (
        hashlib.sha256(
            json.dumps(
                payload,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        if isinstance(payload, dict) and payload
        else ""
    )
    existing_status = "missing"
    if target.is_symlink():
        diagnostics.append("receipt_target_must_not_be_symlink")
        existing_status = "invalid"
    elif target.is_file():
        try:
            existing = json.loads(target.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            diagnostics.append("receipt_target_contains_invalid_json")
            existing_status = "invalid"
        else:
            existing_digest = hashlib.sha256(
                json.dumps(
                    existing,
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()
            existing_status = (
                "current" if existing_digest == source_digest else "conflict"
            )
            if existing_status == "conflict":
                diagnostics.append(
                    "immutable_receipt_id_conflict_use_a_new_receipt_id"
                )
    elif target.exists():
        diagnostics.append("receipt_target_is_not_a_regular_file")
        existing_status = "invalid"
    ok = not diagnostics
    status = (
        "invalid"
        if not ok
        else "current"
        if existing_status == "current"
        else "recorded"
        if apply
        else "planned"
    )
    if ok and apply and existing_status == "missing":
        write_json(target, payload)
    admission = (
        skill_usage_receipt_admission(
            payload,
            receipt_ref=str(target if apply else receipt_path),
        )
        if isinstance(payload, dict) and payload
        else {}
    )
    return {
        "schema_version": "skill_usage_receipt_record_v1",
        "artifact_type": "session_memory_skill_usage_receipt_record",
        "generated_at": utc_now(),
        "ok": ok,
        "mutates": bool(ok and apply and existing_status == "missing"),
        "apply": bool(apply),
        "status": status,
        "source": str(receipt_path),
        "source_digest": source_digest,
        "target": str(target),
        "existing_status": existing_status,
        "admission": admission,
        "diagnostics": diagnostics,
        "authority_boundary": SKILL_USAGE_RECEIPT_CLAIM_LIMIT,
    }


def skill_evidence_summary(
    events: list[dict[str, Any]],
    *,
    anchor: str,
    false_correlation_events: list[dict[str, Any]] | None = None,
    reviewed_receipts: list[dict[str, Any]] | None = None,
    receipt_diagnostics: list[str] | None = None,
) -> dict[str, Any]:
    state_counts: Counter[str] = Counter()
    association_state_counts: Counter[str] = Counter()
    associations_by_event: dict[str, list[tuple[dict[str, Any], str]]] = defaultdict(list)
    input_event_count = 0
    for original_index, event in enumerate(events):
        if not isinstance(event, dict):
            continue
        input_event_count += 1
        explicit_state = str(event.get("skill_evidence_state") or "")
        state = (
            explicit_state
            if explicit_state in SKILL_ACCEPTED_EVIDENCE_STATES
            else skill_evidence_state_for_event(event, anchor=anchor)
        )
        association_state_counts[state] += 1
        evidence_event_key = entity_usage_event_identity(event, fallback_index=original_index)
        associations_by_event[evidence_event_key].append((event, state))
    for associations in associations_by_event.values():
        canonical_state = min(
            (state for _event, state in associations),
            key=lambda state: SKILL_EVIDENCE_CANONICAL_STRENGTH.get(state, 99),
        )
        state_counts[canonical_state] += 1
        for event, _state in associations:
            event["skill_evidence_state"] = canonical_state
    receipt_rows = [
        item
        for item in (reviewed_receipts or [])
        if isinstance(item, dict)
    ]
    receipt_state_counts: Counter[str] = Counter(
        str(item.get("state") or "")
        for item in receipt_rows
        if item.get("valid") and str(item.get("state") or "")
    )
    admitted_invocation_receipts = [
        item for item in receipt_rows if item.get("invocation_claim_allowed")
    ]
    admitted_verification_receipts = [
        item for item in receipt_rows if item.get("verification_claim_allowed")
    ]
    admitted_deflection_receipts = [
        item for item in receipt_rows if item.get("deflection_claim_allowed")
    ]
    effect_attribution_receipts = [
        item
        for item in receipt_rows
        if item.get("effect_attribution_candidate_present")
    ]
    behavioral_candidate_present = any(
        state_counts.get(state, 0) > 0 for state in SKILL_BEHAVIORAL_CANDIDATE_STATES
    ) or bool(
        receipt_state_counts.get("procedure_observed")
        or receipt_state_counts.get("verified")
        or receipt_state_counts.get("completed")
    )
    dispatch_candidate_present = any(
        state_counts.get(state, 0) > 0 for state in SKILL_DISPATCH_CANDIDATE_STATES
    )
    structured_selection_event_keys = {
        entity_usage_event_identity(event, fallback_index=original_index)
        for original_index, event in enumerate(events)
        if isinstance(event, dict)
        and str(event.get("session_act") or "").casefold() == "skill_explicit_selection"
        and str(event.get("skill_evidence_state") or "").casefold() == "selected"
    }
    structured_skill_selection_event_count = len(structured_selection_event_keys)
    task_episode_link_event_keys = {
        entity_usage_event_identity(event, fallback_index=original_index)
        for original_index, event in enumerate(events)
        if isinstance(event, dict)
        and str(event.get("task_episode_id") or "")
        and str(event.get("skill_evidence_state") or "") in SKILL_ACCEPTED_EVIDENCE_STATES
    }
    task_episode_refs_by_key: dict[tuple[str, str], dict[str, str]] = {}
    for event in events:
        if not isinstance(event, dict):
            continue
        task_episode_id = str(event.get("task_episode_id") or "")
        session_id = str(event.get("session_id") or "")
        session_label = str(event.get("session_label") or "")
        session_key = session_id or session_label
        if not task_episode_id or not session_key:
            continue
        task_episode_ref = {"task_episode_id": task_episode_id}
        if session_id:
            task_episode_ref["session_id"] = session_id
        if session_label:
            task_episode_ref["session_label"] = session_label
        task_episode_refs_by_key[(session_key, task_episode_id)] = task_episode_ref
    task_episode_refs = [
        task_episode_refs_by_key[key]
        for key in sorted(task_episode_refs_by_key)
    ]
    bounded_task_episode_refs = task_episode_refs[:ENTITY_USAGE_ROUTE_SIGNAL_SAMPLE_LIMIT]
    rejection_events = [
        event
        for event in (false_correlation_events or [])
        if isinstance(event, dict)
    ]
    unique_rejected_event_keys: set[str] = set()
    for original_index, event in enumerate(rejection_events):
        refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
        rejected_key = str(event.get("doc_id") or "") or "|".join(
            str(value or "")
            for value in (
                event.get("session_id") or event.get("session_label"),
                event.get("segment_id"),
                event.get("event_id"),
                refs.get("raw"),
            )
        ).strip("|")
        unique_rejected_event_keys.add(rejected_key or f"input:{original_index}")
    invocation_claim_allowed = bool(admitted_invocation_receipts)
    deflection_claim_allowed = bool(admitted_deflection_receipts)
    return {
        "schema_version": SKILL_EVIDENCE_SCHEMA_VERSION,
        "candidate_only": not (
            invocation_claim_allowed or deflection_claim_allowed
        ),
        "benefit_candidate_only": True,
        "supported_states": list(SKILL_ACCEPTED_EVIDENCE_STATES),
        "automatic_candidate_states": sorted(SKILL_AUTOMATIC_CANDIDATE_STATES),
        "receipt_or_review_states": sorted(SKILL_RECEIPT_OR_REVIEW_STATES),
        "rejection_edge_states": sorted(SKILL_REJECTION_EDGE_STATES),
        "state_counts": dict(sorted(state_counts.items())),
        "reviewed_receipt_state_counts": dict(
            sorted(receipt_state_counts.items())
        ),
        "association_state_counts": dict(sorted(association_state_counts.items())),
        "input_event_count": input_event_count,
        "unique_evidence_event_count": len(associations_by_event),
        "unique_evidence_fact_count": len(associations_by_event),
        "duplicate_evidence_association_count": input_event_count - len(associations_by_event),
        "structured_skill_selection_event_count": structured_skill_selection_event_count,
        "task_episode_link_event_count": len(task_episode_link_event_keys),
        "task_episode_ref_count": len(task_episode_refs),
        "task_episode_refs": bounded_task_episode_refs,
        "task_episode_refs_truncated": len(task_episode_refs) > len(bounded_task_episode_refs),
        "dimensions": {
            "prompt_visible_candidate_present": state_counts.get("prompt_visible", 0) > 0,
            "selection_candidate_present": state_counts.get("selected", 0) > 0,
            "structured_skill_selection_candidate_present": structured_skill_selection_event_count > 0,
            "skill_payload_loaded_candidate_present": structured_skill_selection_event_count > 0,
            "task_episode_link_candidate_present": bool(task_episode_link_event_keys),
            "skill_read_candidate_present": state_counts.get("skill_read", 0) > 0,
            "procedure_candidate_present": state_counts.get("procedure_observed", 0) > 0,
            "verification_candidate_present": state_counts.get("verified", 0) > 0,
            "completion_candidate_present": state_counts.get("completed", 0) > 0,
            "deflection_candidate_present": state_counts.get("deflected", 0) > 0,
            "reviewed_invocation_receipt_present": bool(
                admitted_invocation_receipts
            ),
            "reviewed_verification_receipt_present": bool(
                admitted_verification_receipts
            ),
            "reviewed_deflection_receipt_present": bool(
                admitted_deflection_receipts
            ),
            "effect_attribution_candidate_present": bool(
                effect_attribution_receipts
            ),
        },
        "dispatch_candidate_present": dispatch_candidate_present,
        "behavioral_candidate_present": behavioral_candidate_present,
        "correlation_rejections": {
            "state": "false_correlation",
            "edge_count": len(rejection_events),
            "unique_event_count": len(unique_rejected_event_keys),
        },
        "prompt_visibility_ingestion_available": True,
        "state_ingestion": {
            "prompt_visible": {
                "available": True,
                "mode": "session_scoped_query_time_raw_context_probe",
                "claim_boundary": "visibility_only_not_selection_invocation_or_behavior",
            },
            "procedure_observed": {
                "available": True,
                "mode": "immutable_owner_reviewed_skill_usage_receipt",
            },
            "verified": {
                "available": True,
                "mode": "immutable_owner_reviewed_skill_usage_receipt",
            },
            "completed": {
                "available": True,
                "mode": "immutable_owner_reviewed_skill_usage_receipt",
            },
            "deflected": {
                "available": True,
                "mode": "immutable_owner_reviewed_skill_usage_receipt",
            },
        },
        "receipt_or_review_ingestion_available": True,
        "reviewed_receipt_count": len(receipt_rows),
        "reviewed_valid_receipt_count": sum(
            bool(item.get("valid")) for item in receipt_rows
        ),
        "reviewed_invocation_receipt_count": len(
            admitted_invocation_receipts
        ),
        "reviewed_verification_receipt_count": len(
            admitted_verification_receipts
        ),
        "reviewed_deflection_receipt_count": len(
            admitted_deflection_receipts
        ),
        "effect_attribution_candidate_count": len(
            effect_attribution_receipts
        ),
        "reviewed_receipts": receipt_rows[:ENTITY_USAGE_ROUTE_SIGNAL_SAMPLE_LIMIT],
        "reviewed_receipts_truncated": (
            len(receipt_rows) > ENTITY_USAGE_ROUTE_SIGNAL_SAMPLE_LIMIT
        ),
        "receipt_diagnostics": list(receipt_diagnostics or [])[:100],
        "invocation_claim_allowed": invocation_claim_allowed,
        "deflection_claim_allowed": deflection_claim_allowed,
        "verification_claim_allowed": bool(
            admitted_verification_receipts
        ),
        "effect_attribution_candidate_present": bool(
            effect_attribution_receipts
        ),
        "benefit_claim_allowed": False,
        "benefit_claim_blocker": (
            "aoa_evals_verdict_resolution_required"
            if effect_attribution_receipts
            else "no_verified_effect_attribution_candidate"
        ),
        "invocation_claim_blocker": (
            ""
            if invocation_claim_allowed
            else "receipt_proves_deflection_not_invocation"
            if deflection_claim_allowed
            else "reviewed_receipt_identity_or_procedure_evidence_not_admitted"
            if receipt_rows
            else "candidate_states_require_task_episode_correlation_and_owner_review"
            if behavioral_candidate_present or dispatch_candidate_present
            else "no_procedure_or_dispatch_candidate_observed_in_bounded_route"
        ),
        "authority_boundary": (
            "session-memory may admit an immutable reviewed invocation receipt; "
            "effect attribution remains a candidate and aoa-evals owns benefit "
            "and promotion verdicts"
        ),
    }


def entity_usage_segment_event_is_tool_result(event: dict[str, Any]) -> bool:
    event_type = str(event.get("type") or event.get("event_type") or "").upper()
    if event_type in ENTITY_USAGE_RESULT_TYPES:
        return True
    facets = event.get("facets") if isinstance(event.get("facets"), dict) else {}
    payload_type = str(facets.get("payload_type") or "").casefold()
    # Content classification may legitimately promote a structured tool
    # result to SECURITY_TOUCHPOINT (or another semantic event class). Keep
    # the raw response-item role available to correlation/async traversal.
    if (
        payload_type
        in {
            "custom_tool_call_output",
            "function_call_output",
        }
        and str(event.get("correlation_id") or "")
    ):
        return True
    if event_type != "HOOK_EVENT":
        return False
    title = str(event.get("title") or "").casefold()
    action = str(event.get("action") or "").casefold()
    return any(
        marker in " ".join([title, action])
        for marker in (
            "mcp_tool_call_end",
            "tool_call_end",
            "function_call_output",
            "tool_output",
        )
    )


def entity_usage_segment_event_is_correlated_status(event: dict[str, Any]) -> bool:
    event_type = str(event.get("type") or event.get("event_type") or "").upper()
    facets = event.get("facets") if isinstance(event.get("facets"), dict) else {}
    return bool(
        event_type == "CONTEXT_STATE"
        and str(facets.get("message_type") or "") == "sub_agent_activity"
        and str(event.get("correlation_id") or "")
    )


def entity_usage_segment_event_raw_content_digest(
    event: dict[str, Any],
    *,
    hit: dict[str, Any],
    manifest_cache: dict[str, dict[str, Any]] | None = None,
    raw_preview_cache: dict[tuple[str, str, str, int], dict[str, Any]] | None = None,
) -> str:
    compact = compact_usage_event_from_segment_event(
        event,
        hit=hit,
        role="context",
        source="segment_mirror_probe",
        source_doc_id=str(hit.get("doc_id") or ""),
        distance=0,
        relation="mirror_probe",
    )
    preview = raw_preview_for_usage_event(
        compact,
        max_chars=ENTITY_USAGE_ASYNC_RAW_PREVIEW_MAX_CHARS,
        manifest_cache=manifest_cache,
        raw_preview_cache=raw_preview_cache,
    )
    if str(preview.get("status") or "") != "available":
        return ""
    try:
        row = json.loads(str(preview.get("text") or ""))
    except json.JSONDecodeError:
        return ""
    if not isinstance(row, dict):
        return ""
    source_type = str(row.get("type") or "")
    payload = row.get("payload")
    semantic = semantic_text_for_classification(
        source_type,
        payload,
        max_chars=CLASSIFIER_TEXT_MAX_CHARS,
    )
    normalized = re.sub(r"\s+", " ", semantic.lower()).strip()
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest() if normalized else ""


def entity_usage_segment_event_has_canonical_agent_mirror(
    events: list[dict[str, Any]],
    index: int,
    *,
    lookahead: int = 3,
    hit: dict[str, Any] | None = None,
    manifest_cache: dict[str, dict[str, Any]] | None = None,
    raw_preview_cache: dict[tuple[str, str, str, int], dict[str, Any]] | None = None,
    diagnostics: dict[str, int] | None = None,
) -> bool:
    """Recognize one exact event-stream copy followed by its canonical item."""
    if index < 0 or index >= len(events):
        return False
    event = events[index]
    facets = event.get("facets") if isinstance(event.get("facets"), dict) else {}
    agent_event = facets.get("agent_event") if isinstance(facets.get("agent_event"), dict) else {}
    digest = str(agent_event.get("content_sha256") or "")
    timestamp = str(event.get("timestamp") or "")
    if (
        str(agent_event.get("source_lane") or "") != "event_msg_stream"
        or bool(agent_event.get("canonical"))
        or not timestamp
    ):
        return False
    stop = min(len(events), index + 1 + max(1, min(int_value(lookahead, 3), 8)))
    for candidate in events[index + 1 : stop]:
        candidate_facets = (
            candidate.get("facets")
            if isinstance(candidate.get("facets"), dict)
            else {}
        )
        candidate_agent = (
            candidate_facets.get("agent_event")
            if isinstance(candidate_facets.get("agent_event"), dict)
            else {}
        )
        candidate_timestamp = str(candidate.get("timestamp") or "")
        timestamp_match = candidate_timestamp == timestamp
        if not timestamp_match:
            stream_dt = parse_utc_timestamp(timestamp)
            candidate_dt = parse_utc_timestamp(candidate_timestamp)
            timestamp_match = bool(
                stream_dt
                and candidate_dt
                and abs((candidate_dt - stream_dt).total_seconds())
                <= ENTITY_USAGE_AGENT_MIRROR_TIMESTAMP_TOLERANCE_SECONDS
            )
        if not (
            bool(candidate_agent.get("canonical"))
            and str(candidate_agent.get("source_lane") or "") == "response_item"
            and timestamp_match
        ):
            continue
        candidate_digest = str(candidate_agent.get("content_sha256") or "")
        if digest and candidate_digest and candidate_digest == digest:
            if diagnostics is not None:
                diagnostics["agent_stream_mirror_index_digest_verified_count"] = (
                    int_value(
                        diagnostics.get(
                            "agent_stream_mirror_index_digest_verified_count"
                        )
                    )
                    + 1
                )
            return True
        if hit is None:
            continue
        raw_digest = entity_usage_segment_event_raw_content_digest(
            event,
            hit=hit,
            manifest_cache=manifest_cache,
            raw_preview_cache=raw_preview_cache,
        )
        candidate_raw_digest = entity_usage_segment_event_raw_content_digest(
            candidate,
            hit=hit,
            manifest_cache=manifest_cache,
            raw_preview_cache=raw_preview_cache,
        )
        if raw_digest and candidate_raw_digest and raw_digest == candidate_raw_digest:
            if diagnostics is not None:
                diagnostics["agent_stream_mirror_raw_verified_count"] = (
                    int_value(
                        diagnostics.get("agent_stream_mirror_raw_verified_count")
                    )
                    + 1
                )
            return True
    return False


def entity_usage_event_is_foreign_correlated_result(
    source_correlation: str,
    event: dict[str, Any],
) -> bool:
    """Reject a result or structured status owned by another open tool call."""
    event_correlation = str(event.get("correlation_id") or "")
    return bool(
        source_correlation
        and event_correlation
        and event_correlation != source_correlation
        and (
            entity_usage_segment_event_is_tool_result(event)
            or entity_usage_segment_event_is_correlated_status(event)
        )
    )


def compact_usage_route_signals(value: Any, *, limit: int = ENTITY_USAGE_ROUTE_SIGNAL_SAMPLE_LIMIT) -> tuple[list[str], int]:
    signals: list[str] = []
    if isinstance(value, str):
        signals = [item for item in value.split("|") if item]
    elif isinstance(value, list):
        signals = [str(item) for item in value if item]
    elif isinstance(value, tuple):
        signals = [str(item) for item in value if item]
    seen: set[str] = set()
    unique: list[str] = []
    for signal in signals:
        if signal in seen:
            continue
        seen.add(signal)
        unique.append(signal)
    bounded_limit = max(0, min(int_value(limit, ENTITY_USAGE_ROUTE_SIGNAL_SAMPLE_LIMIT), 200))
    return unique[:bounded_limit], len(unique)


def entity_usage_hit_sort_key(hit: dict[str, Any], event: dict[str, Any], original_index: int) -> tuple[int, int, int, int]:
    matched_routes = hit.get("matched_routes") if isinstance(hit.get("matched_routes"), list) else []
    text_only_rank = 1 if matched_routes and all(str(item) == "text" for item in matched_routes) else 0
    freshness_status = entity_usage_event_freshness_status(event)
    freshness_rank = ENTITY_USAGE_FRESHNESS_PRIORITY.get(freshness_status, 1)
    return (
        ENTITY_USAGE_ROLE_PRIORITY.get(str(event.get("role") or "context"), 99),
        text_only_rank,
        freshness_rank,
        original_index,
    )


def entity_usage_event_is_execution_inspection_read(event: dict[str, Any]) -> bool:
    return bool(
        (
            str(event.get("execution_entity_usage_admission") or "")
            == "structured_inspection_read_proven"
            and bool(event.get("execution_read_result_refs"))
        )
        or (
            str(event.get("execution_entity_usage_admission") or "")
            == "inspection_or_reference_not_invocation"
            and (
                str(event.get("event_type") or "") == "FILE_READ"
                or str(event.get("action") or "")
                in {"read", "inspect_workspace"}
                or str(event.get("session_act") or "")
                == "file_inspection"
            )
        )
    )


def entity_usage_action_diverse_selection(
    ranked_pairs: list[tuple[dict[str, Any], dict[str, Any], int]],
    *,
    normalized_kind: str,
    limit: int,
) -> tuple[list[tuple[dict[str, Any], dict[str, Any], int]], dict[str, Any]]:
    """Preserve core evidence while surfacing one bounded inspection sample."""
    selected = list(ranked_pairs[:limit])
    quality: dict[str, Any] = {
        "policy": "preserve_core_roles_then_sample_execution_inspection",
        "eligible": normalized_kind in ENTITY_USAGE_EXECUTION_ADMISSION_KINDS,
        "applied": False,
        "read_sample_present": False,
        "selected_event_id": "",
        "replaced_event_id": "",
    }
    if normalized_kind not in ENTITY_USAGE_EXECUTION_ADMISSION_KINDS:
        return selected, quality

    selected_read = next(
        (
            event
            for _hit, event, _index in selected
            if entity_usage_event_is_execution_inspection_read(event)
        ),
        None,
    )
    if selected_read is not None:
        quality["read_sample_present"] = True
        quality["selected_event_id"] = str(selected_read.get("event_id") or "")
        return selected, quality

    replacement = next(
        (
            pair
            for pair in ranked_pairs[limit:]
            if entity_usage_event_is_execution_inspection_read(pair[1])
        ),
        None,
    )
    if replacement is None:
        return selected, quality

    replace_index = next(
        (
            index
            for index in range(len(selected) - 1, -1, -1)
            if str(selected[index][1].get("role") or "") == "context"
            and not entity_usage_event_is_execution_inspection_read(selected[index][1])
        ),
        None,
    )
    if replace_index is None:
        selected_usage_count = sum(
            str(event.get("role") or "") == "usage"
            for _hit, event, _index in selected
        )
        if selected_usage_count > 1:
            replace_index = next(
                (
                    index
                    for index in range(len(selected) - 1, -1, -1)
                    if str(selected[index][1].get("role") or "") == "usage"
                    and set(
                        entity_usage_event_action_semantics(selected[index][1])
                    ).issubset(
                        {
                            action
                            for other_index, (_hit, event, _pair_index) in enumerate(
                                selected
                            )
                            if other_index != index
                            for action in entity_usage_event_action_semantics(event)
                        }
                    )
                ),
                None,
            )
    if replace_index is None:
        return selected, quality

    replaced_event = selected[replace_index][1]
    selected[replace_index] = replacement
    quality.update(
        {
            "applied": True,
            "read_sample_present": True,
            "selected_event_id": str(replacement[1].get("event_id") or ""),
            "replaced_event_id": str(replaced_event.get("event_id") or ""),
        }
    )
    return selected, quality


def event_refs_from_hit(hit: dict[str, Any]) -> dict[str, str]:
    refs = hit.get("refs") if isinstance(hit.get("refs"), dict) else {}
    return {
        "session": str(refs.get("session") or ""),
        "segment": str(refs.get("segment") or ""),
        "segment_index": str(refs.get("segment_index") or ""),
        "raw": str(refs.get("raw") or ""),
        "raw_block": str(refs.get("raw_block") or ""),
    }


def entity_usage_event_identity(event: dict[str, Any], *, fallback_index: int = 0) -> str:
    """Return the underlying archived-event identity, independent of packet role."""
    doc_id = str(event.get("doc_id") or "")
    if doc_id:
        return doc_id
    refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
    identity = "|".join(
        str(value or "")
        for value in (
            event.get("session_id") or event.get("session_label"),
            event.get("segment_id"),
            event.get("event_id"),
            refs.get("raw"),
        )
    ).strip("|")
    return identity or f"input:{fallback_index}"


def unique_entity_usage_events(events: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Deduplicate views while preserving the strongest correlated semantics."""
    unique: list[dict[str, Any]] = []
    positions: dict[str, int] = {}
    priorities: dict[str, tuple[int, int, int]] = {}

    def merge_views(preferred: dict[str, Any], alternate: dict[str, Any]) -> dict[str, Any]:
        def populated(value: Any) -> bool:
            return value is not None and value != "" and value != () and value != [] and value != {}

        merged = dict(preferred)
        for key, value in alternate.items():
            if key in {"matched_routes", "route_signals"}:
                current_values = merged.get(key)
                current_list = (
                    [str(item) for item in current_values if item]
                    if isinstance(current_values, (list, tuple))
                    else [item for item in str(current_values or "").split("|") if item]
                )
                alternate_list = (
                    [str(item) for item in value if item]
                    if isinstance(value, (list, tuple))
                    else [item for item in str(value or "").split("|") if item]
                )
                merged[key] = list(dict.fromkeys([*current_list, *alternate_list]))
                continue
            if key == "refs" and isinstance(value, dict):
                current_refs = merged.get("refs") if isinstance(merged.get("refs"), dict) else {}
                merged["refs"] = {
                    ref_key: current_refs.get(ref_key) or ref_value
                    for ref_key, ref_value in {**value, **current_refs}.items()
                }
                continue
            if not populated(merged.get(key)) and populated(value):
                merged[key] = value
        states = [
            str(item.get("skill_evidence_state") or "")
            for item in (preferred, alternate)
            if str(item.get("skill_evidence_state") or "") in SKILL_ACCEPTED_EVIDENCE_STATES
        ]
        if states:
            merged["skill_evidence_state"] = min(
                states,
                key=lambda state: SKILL_EVIDENCE_CANONICAL_STRENGTH.get(state, 99),
            )
        return merged

    for original_index, event in enumerate(events):
        if not isinstance(event, dict):
            continue
        identity = entity_usage_event_identity(event, fallback_index=original_index)
        refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
        correlation_richness = sum(
            1
            for value in (
                event.get("correlation_id"),
                event.get("source_correlation_id"),
                event.get("rejected_correlation_id"),
                event.get("relation"),
                refs.get("raw"),
                refs.get("segment_index"),
            )
            if value
        )
        priority = (
            ENTITY_USAGE_ROLE_PRIORITY.get(str(event.get("role") or "context"), 99),
            -correlation_richness,
            original_index,
        )
        if identity not in positions:
            positions[identity] = len(unique)
            priorities[identity] = priority
            unique.append(dict(event))
            continue
        position = positions[identity]
        if priority < priorities[identity]:
            unique[position] = merge_views(event, unique[position])
            priorities[identity] = priority
        else:
            unique[position] = merge_views(unique[position], event)
    return unique


def compact_usage_event_from_search_hit(hit: dict[str, Any], *, role: str | None = None, source: str = "search") -> dict[str, Any]:
    source_override = str(hit.get("entity_usage_source_override") or "")
    usage_role_override = str(hit.get("entity_usage_role_override") or "")
    resolved_role = role or (
        usage_role_override
        if usage_role_override in {"entrypoint", "usage", "result", "outcome", "context"}
        else ""
    ) or entity_usage_event_role(
        str(hit.get("event_type") or ""),
        str(hit.get("conversation_act") or ""),
        str(hit.get("session_act") or ""),
    )
    route_signals, route_signal_count = compact_usage_route_signals(hit.get("route_signals"))
    return {
        "doc_id": hit.get("doc_id"),
        "source": source_override or source,
        "role": resolved_role,
        "session_id": hit.get("session_id"),
        "session_label": hit.get("session_label"),
        "session_date": hit.get("session_date"),
        "segment_id": hit.get("segment_id"),
        "event_id": hit.get("event_id"),
        "event_type": hit.get("event_type"),
        "task_episode_id": hit.get("task_episode_id"),
        "correlation_id": hit.get("correlation_id"),
        "family": hit.get("family"),
        "phase": hit.get("phase"),
        "actor": hit.get("actor"),
        "action": hit.get("action"),
        "outcome": hit.get("outcome"),
        "conversation_act": hit.get("conversation_act"),
        "session_act": hit.get("session_act"),
        "mcp_usage_admission": hit.get("mcp_usage_admission"),
        "mcp_usage_admission_service_key": hit.get(
            "mcp_usage_admission_service_key"
        ),
        "mcp_tool_usage_admission": hit.get(
            "mcp_tool_usage_admission"
        ),
        "mcp_tool_usage_route_key": hit.get(
            "mcp_tool_usage_route_key"
        ),
        "mcp_tool_usage_service_key": hit.get(
            "mcp_tool_usage_service_key"
        ),
        "mcp_tool_usage_tool_key": hit.get(
            "mcp_tool_usage_tool_key"
        ),
        "tool_usage_admission": hit.get("tool_usage_admission"),
        "tool_usage_admission_key": hit.get("tool_usage_admission_key"),
        "tool_usage_invocation_name": hit.get(
            "tool_usage_invocation_name"
        ),
        "tool_usage_invocation_namespace": hit.get(
            "tool_usage_invocation_namespace"
        ),
        "hook_usage_admission": hit.get("hook_usage_admission"),
        "execution_entity_usage_admission": hit.get("execution_entity_usage_admission"),
        "execution_entity_usage_admission_reason": hit.get(
            "execution_entity_usage_admission_reason"
        ),
        "execution_entity_usage_kind": hit.get("execution_entity_usage_kind"),
        "execution_entity_usage_result_status": hit.get(
            "execution_entity_usage_result_status"
        ),
        "execution_entity_usage_result_code": hit.get(
            "execution_entity_usage_result_code"
        ),
        "execution_entity_usage_result_evidence": hit.get(
            "execution_entity_usage_result_evidence"
        ),
        "execution_parent_refs": (
            dict(hit.get("execution_parent_refs"))
            if isinstance(hit.get("execution_parent_refs"), dict)
            else {}
        ),
        "execution_read_result_refs": (
            dict(hit.get("execution_read_result_refs"))
            if isinstance(hit.get("execution_read_result_refs"), dict)
            else {}
        ),
        "skill_evidence_state": hit.get("skill_evidence_state"),
        "skill_state_admission": hit.get("skill_state_admission"),
        "selection_target_refs": (
            dict(hit.get("selection_target_refs"))
            if isinstance(hit.get("selection_target_refs"), dict)
            else {}
        ),
        "prompt_visibility_admission": hit.get("prompt_visibility_admission"),
        "prompt_visibility_source_role": hit.get(
            "prompt_visibility_source_role"
        ),
        "prompt_visibility_skill_key": hit.get("prompt_visibility_skill_key"),
        "prompt_visibility_source": hit.get("prompt_visibility_source"),
        "matched_routes": hit.get("matched_routes", []),
        "route_signals": route_signals,
        "route_signal_count": route_signal_count,
        "route_signals_truncated": route_signal_count > len(route_signals),
        "title": hit.get("title"),
        "snippet": hit.get("snippet"),
        "refs": event_refs_from_hit(hit),
        "freshness": hit.get("freshness"),
    }


def compact_usage_event_from_segment_event(
    event: dict[str, Any],
    *,
    hit: dict[str, Any],
    role: str,
    source: str,
    source_doc_id: str,
    distance: int,
    relation: str,
) -> dict[str, Any]:
    hit_refs = event_refs_from_hit(hit)
    facets = event.get("facets") if isinstance(event.get("facets"), dict) else {}
    conversation_act = facets.get("conversation_act") if isinstance(facets.get("conversation_act"), dict) else {}
    session_act = facets.get("session_act") if isinstance(facets.get("session_act"), dict) else {}
    route_signals = graph_route_signals_from_event(event)
    full_route_signal_values = [
        str(signal.get("route_signal") or "")
        for signal in route_signals
        if isinstance(signal, dict) and str(signal.get("route_signal") or "")
    ]
    route_signal_values, route_signal_count = compact_usage_route_signals(
        full_route_signal_values
    )
    verification_signals = [
        signal
        for signal in full_route_signal_values
        if signal == "delivery_state:tests_green"
    ]
    segment_ref = str(event.get("md_anchor") or hit_refs.get("segment") or "")
    raw_ref = str(event.get("raw_ref") or "")
    return {
        "doc_id": f"event:{hit.get('session_id')}:{hit.get('segment_id')}:{event.get('event_id')}",
        "source": source,
        "source_doc_id": source_doc_id,
        "distance": distance,
        "relation": relation,
        "role": role,
        "session_id": hit.get("session_id"),
        "session_label": hit.get("session_label"),
        "session_date": hit.get("session_date"),
        "segment_id": hit.get("segment_id"),
        "event_id": event.get("event_id"),
        "event_type": event.get("type"),
        "task_episode_id": event.get("task_episode_id"),
        "correlation_id": event.get("correlation_id"),
        "family": event.get("family"),
        "phase": event.get("phase"),
        "actor": event.get("actor"),
        "action": event.get("action"),
        "outcome": event.get("outcome"),
        "conversation_act": conversation_act.get("kind"),
        "session_act": session_act.get("kind"),
        "structured_skill_name": session_act.get("skill_name"),
        "tool_transport_status": facets.get("tool_transport_status"),
        "verification_signals": verification_signals,
        "mcp_result_identity": (
            dict(facets.get("mcp_result_identity"))
            if isinstance(facets.get("mcp_result_identity"), dict)
            else {}
        ),
        "route_signals": route_signal_values,
        "route_signal_count": route_signal_count,
        "route_signals_truncated": route_signal_count > len(route_signal_values),
        "title": event.get("title"),
        "refs": {
            "session": hit_refs.get("session", ""),
            "segment": segment_ref,
            "segment_index": hit_refs.get("segment_index", ""),
            "raw": raw_ref,
            "raw_block": hit_refs.get("raw_block", ""),
        },
        "freshness": hit.get("freshness"),
    }


def raw_preview_for_usage_event(
    event: dict[str, Any],
    *,
    max_chars: int = 600,
    manifest_cache: dict[str, dict[str, Any]] | None = None,
    raw_preview_cache: dict[tuple[str, str, str, int], dict[str, Any]] | None = None,
) -> dict[str, Any]:
    refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
    raw_ref = str(refs.get("raw") or "")
    manifest_ref = str(refs.get("session") or "")
    raw_block_ref = str(refs.get("raw_block") or "")
    cache_key = (manifest_ref, raw_ref, raw_block_ref, max(0, int_value(max_chars, 600)))
    if raw_preview_cache is not None and cache_key in raw_preview_cache:
        return dict(raw_preview_cache[cache_key])
    if not raw_ref or not manifest_ref:
        return {"status": "missing_raw_or_session_ref", "line": line_from_raw_ref(raw_ref), "text": ""}
    manifest_path = Path(manifest_ref)
    manifest = manifest_cache.get(manifest_ref) if manifest_cache is not None else None
    if manifest is None:
        manifest = read_json(manifest_path, {})
        if manifest_cache is not None and isinstance(manifest, dict):
            manifest_cache[manifest_ref] = manifest
    if not isinstance(manifest, dict) or not manifest:
        return {"status": "session_manifest_unavailable", "line": line_from_raw_ref(raw_ref), "text": ""}
    block_preview: dict[str, Any] | None = None
    if raw_block_ref:
        block_preview = raw_block_line_preview(
            manifest_path.parent,
            manifest,
            raw_ref,
            raw_block_ref=raw_block_ref,
            max_chars=max_chars,
        )
        if block_preview.get("status") == "available":
            block_preview = dict(block_preview)
            block_preview["source"] = "raw_block"
            if raw_preview_cache is not None:
                raw_preview_cache[cache_key] = dict(block_preview)
            return block_preview
    preview = raw_line_preview(manifest_raw_path(manifest_path.parent, manifest), raw_ref, max_chars=max_chars)
    preview = dict(preview)
    preview["source"] = "raw_session_jsonl"
    if block_preview is not None:
        preview["raw_block_fallback"] = {
            "status": block_preview.get("status"),
            "diagnostics": block_preview.get("diagnostics", []),
        }
    if raw_preview_cache is not None:
        raw_preview_cache[cache_key] = dict(preview)
    return preview


def raw_payload_for_usage_segment_event(
    event: dict[str, Any],
    *,
    hit: dict[str, Any],
    distance: int,
    manifest_cache: dict[str, dict[str, Any]] | None = None,
    raw_preview_cache: dict[tuple[str, str, str, int], dict[str, Any]] | None = None,
) -> tuple[dict[str, Any], str]:
    """Open one bounded raw ref and return its structured event payload.

    A truncated preview is deliberately not parsed or guessed from.  The
    segment index remains navigation, while the exact raw line decides whether
    a transport, wait, or MCP receipt edge can be admitted.
    """
    compact = compact_usage_event_from_segment_event(
        event,
        hit=hit,
        role="context",
        source="segment_async_probe",
        source_doc_id=str(hit.get("doc_id") or ""),
        distance=distance,
        relation="async_probe",
    )
    preview = raw_preview_for_usage_event(
        compact,
        max_chars=ENTITY_USAGE_ASYNC_RAW_PREVIEW_MAX_CHARS,
        manifest_cache=manifest_cache,
        raw_preview_cache=raw_preview_cache,
    )
    status = str(preview.get("status") or "unavailable")
    if status != "available":
        return {}, status
    try:
        row = json.loads(str(preview.get("text") or ""))
    except json.JSONDecodeError:
        return {}, "raw_preview_not_complete_json"
    if not isinstance(row, dict):
        return {}, "raw_row_not_object"
    row_type = str(row.get("type") or "")
    payload = row.get("payload")
    if not isinstance(payload, dict):
        return {}, "raw_structured_payload_missing"
    if row_type == "response_item":
        return payload, "available"
    if (
        row_type == "event_msg"
        and str(payload.get("type") or "") == "mcp_tool_call_end"
    ):
        return payload, "available"
    return {}, "raw_row_not_supported_structured_item"


def document_path_mentions(text: Any, *, limit: int = 20) -> list[str]:
    seen: set[str] = set()
    paths: list[str] = []
    for match in ENTITY_USAGE_DOCUMENT_PATH_PATTERN.finditer(str(text or "")):
        value = match.group(0).strip("`'\".,:;)")
        if not value or value in seen:
            continue
        seen.add(value)
        paths.append(value)
        if len(paths) >= limit:
            break
    return paths


def entity_usage_document_refs(
    events: list[dict[str, Any]],
    *,
    limit: int = 60,
    manifest_cache: dict[str, dict[str, Any]] | None = None,
    raw_preview_cache: dict[tuple[str, str, str, int], dict[str, Any]] | None = None,
) -> list[dict[str, Any]]:
    refs: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()

    def add(kind: str, value: str, event: dict[str, Any], *, role: str, detail: str = "") -> None:
        if not value:
            return
        token = (kind, value, str(event.get("doc_id") or event.get("event_id") or ""))
        if token in seen:
            return
        seen.add(token)
        refs.append(
            {
                "kind": kind,
                "value": value,
                "role": role,
                "detail": detail,
                "session_label": event.get("session_label"),
                "event_id": event.get("event_id"),
                "event_type": event.get("event_type"),
                "source_doc_id": event.get("doc_id"),
            }
        )

    for event in events:
        if not isinstance(event, dict):
            continue
        role = str(event.get("role") or "context")
        event_refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
        for kind, key in [
            ("session_manifest", "session"),
            ("segment_markdown", "segment"),
            ("segment_index", "segment_index"),
            ("raw_block", "raw_block"),
            ("raw_line", "raw"),
        ]:
            add(kind, str(event_refs.get(key) or ""), event, role=role)
        preview = raw_preview_for_usage_event(
            event,
            manifest_cache=manifest_cache,
            raw_preview_cache=raw_preview_cache,
        )
        search_text = " ".join(
            str(part or "")
            for part in [
                event.get("title"),
                event.get("snippet"),
                preview.get("text") if isinstance(preview, dict) and preview.get("status") == "available" else "",
            ]
        )
        for path in document_path_mentions(search_text):
            add("mentioned_path", path, event, role=role)
        if len(refs) >= limit:
            break
    return refs[:limit]


def segment_events_for_hit(
    hit: dict[str, Any],
    *,
    segment_cache: dict[str, list[dict[str, Any]]] | None = None,
) -> list[dict[str, Any]]:
    refs = event_refs_from_hit(hit)
    index_path = Path(str(refs.get("segment_index") or ""))
    if not index_path.exists():
        return []
    cache_key = str(index_path)
    if segment_cache is not None and cache_key in segment_cache:
        return segment_cache[cache_key]
    segment_index = read_json(index_path, {})
    if not isinstance(segment_index, dict):
        return []
    events = [event for event in segment_index.get("events", []) if isinstance(event, dict)]
    if segment_cache is not None:
        segment_cache[cache_key] = events
    return events


def segment_event_for_hit(
    hit: dict[str, Any],
    *,
    segment_cache: dict[str, list[dict[str, Any]]] | None = None,
) -> dict[str, Any]:
    event_id = str(hit.get("event_id") or "")
    if not event_id:
        return {}
    return next(
        (
            event
            for event in segment_events_for_hit(hit, segment_cache=segment_cache)
            if str(event.get("event_id") or "") == event_id
        ),
        {},
    )


def entity_usage_execution_same_correlation_result(
    source_event: dict[str, Any],
    *,
    hit: dict[str, Any],
    segment_cache: dict[str, list[dict[str, Any]]],
    manifest_cache: dict[str, dict[str, Any]],
    raw_preview_cache: dict[tuple[str, str, str, int], dict[str, Any]],
) -> tuple[dict[str, Any], dict[str, Any], str]:
    """Open the first exact result owned by one structured execution request."""
    correlation_id = str(source_event.get("correlation_id") or "")
    if not correlation_id:
        return {}, {}, "source_correlation_missing"
    events = segment_events_for_hit(hit, segment_cache=segment_cache)
    source_index = next(
        (
            index
            for index, event in enumerate(events)
            if str(event.get("event_id") or "")
            == str(source_event.get("event_id") or "")
        ),
        None,
    )
    if source_index is None:
        return {}, {}, "source_event_not_in_segment"
    for index in range(source_index + 1, min(len(events), source_index + 25)):
        candidate = events[index]
        if str(candidate.get("correlation_id") or "") != correlation_id:
            continue
        if not entity_usage_segment_event_is_tool_result(candidate):
            continue
        payload, status = raw_payload_for_usage_segment_event(
            candidate,
            hit=hit,
            distance=index - source_index,
            manifest_cache=manifest_cache,
            raw_preview_cache=raw_preview_cache,
        )
        if not payload:
            return {}, candidate, f"result_payload_unavailable:{status}"
        return payload, candidate, "available"
    return {}, {}, "same_correlation_result_not_found"


def entity_usage_execution_prelaunch_failure_reason(
    commands: list[str],
    result_payload: dict[str, Any],
    *,
    anchor: str,
    kind: str,
) -> str:
    """Return only source-proven reasons that the requested entity never ran.

    A command string proves intent to launch a nested script/test/validator.
    Exact same-correlation output can still contradict that intent.  Keep the
    negative gate deliberately narrow: an explicit missing runner/target, or
    the observed zsh special-``path`` failure paired with the captured
    command's rc=127.
    """
    if not result_payload:
        return ""
    output = text_from_content(
        result_payload.get("output"),
        max_chars=ENTITY_USAGE_ASYNC_RAW_PREVIEW_MAX_CHARS,
    )
    if not output:
        return ""
    anchor_key = entity_usage_execution_anchor_key(anchor)
    relevant_executables: set[str] = set()
    for command in commands:
        for tokens in session_memory_query_demand_shell_segments(command):
            if anchor_key not in entity_usage_execution_anchor_key(
                " ".join(tokens)
            ):
                continue
            executable, _arguments = entity_usage_shell_segment_executable(tokens)
            if executable:
                relevant_executables.add(executable)
    for executable in sorted(relevant_executables):
        executable_name = re.escape(Path(executable).name)
        if re.search(
            rf"(?im)(?:command\s+not\s+found:\s*(?:\S*/)?{executable_name}\b|"
            rf"(?:^|\n)[^\n]*\b{executable_name}\s*:\s*command\s+not\s+found)",
            output,
        ):
            return "runner_command_not_found"
    if anchor_key and re.search(
        rf"(?im)can't\s+open\s+file[^\n]*{re.escape(Path(anchor).name)}",
        output,
    ):
        return "target_file_not_opened"
    zsh_command_resolution_failed = bool(
        re.search(r"(?im)^zsh:\d+:\s+command\s+not\s+found:", output)
    )
    captured_rc_127 = bool(re.search(r"(?im)\brc\s*=\s*127\b", output))
    zsh_path_assignment_before_target = any(
        re.search(r"(?m)^\s*path\s*=\s*[^\n;]+", command)
        and anchor_key in entity_usage_execution_anchor_key(command)
        for command in commands
    )
    if (
        kind in ENTITY_USAGE_EXECUTION_ADMISSION_KINDS
        and zsh_command_resolution_failed
        and captured_rc_127
        and zsh_path_assignment_before_target
    ):
        return "zsh_path_assignment_command_resolution_failed"
    return ""


def entity_usage_execution_result_observation(
    result_payload: dict[str, Any],
    *,
    prelaunch_failure_reason: str = "",
) -> dict[str, Any]:
    """Classify only explicit execution status carried by the owned result."""
    if not result_payload:
        return {
            "status": "unverifiable",
            "code": None,
            "evidence": "same_correlation_result_unavailable",
        }
    output = text_from_content(
        result_payload.get("output"),
        max_chars=ENTITY_USAGE_ASYNC_RAW_PREVIEW_MAX_CHARS,
    )
    rc_values = [
        int(match)
        for match in re.findall(r"(?im)\brc\s*=\s*(-?\d+)\b", output)
    ]
    explicit_exit_values = [
        int(match)
        for match in re.findall(
            r"(?im)(?:process|command|script)\s+"
            r"(?:exited|failed)(?:\s+with)?(?:\s+(?:status|code))?\s*[:=]?\s*(-?\d+)\b",
            output,
        )
    ]
    codes = rc_values or explicit_exit_values
    code = codes[0] if len(set(codes)) == 1 and codes else None
    if prelaunch_failure_reason:
        return {
            "status": "not_invoked",
            "code": code,
            "evidence": prelaunch_failure_reason,
        }
    if code is not None:
        return {
            "status": "succeeded" if code == 0 else "failed",
            "code": code,
            "evidence": "owned_result_explicit_exit_code",
        }
    if re.search(
        r"(?im)^(?:script|command|process)\s+failed\b",
        output,
    ):
        return {
            "status": "failed",
            "code": None,
            "evidence": "owned_result_explicit_failure_envelope",
        }
    if output:
        return {
            "status": "observed",
            "code": None,
            "evidence": "owned_result_without_entity_specific_exit_code",
        }
    return {
        "status": "unverifiable",
        "code": None,
        "evidence": "owned_result_text_empty",
    }


def async_continuation_events_for_usage_hit(
    hit: dict[str, Any],
    *,
    events: list[dict[str, Any]],
    start: int,
    window: int,
    manifest_cache: dict[str, dict[str, Any]] | None = None,
    raw_preview_cache: dict[tuple[str, str, str, int], dict[str, Any]] | None = None,
    diagnostics: dict[str, int] | None = None,
) -> dict[int, dict[str, Any]]:
    """Follow a bounded async transport chain using raw structured identity.

    The origin result must expose an outer ``Script running`` envelope.  Each
    continuation hop then requires an exact structured ``wait.cell_id`` and a
    result owned by that wait correlation.  Event adjacency alone never forms
    the edge.
    """
    if diagnostics is not None:
        for key in ENTITY_USAGE_ASYNC_DIAGNOSTIC_KEYS:
            diagnostics.setdefault(key, 0)

    def bump(key: str, amount: int = 1) -> None:
        if diagnostics is not None:
            diagnostics[key] = int_value(diagnostics.get(key)) + amount

    source_event = events[start]
    source_correlation = str(source_event.get("correlation_id") or "")
    if not source_correlation:
        return {}
    bump("probe_count")
    per_hop_window = max(
        ENTITY_USAGE_ASYNC_MIN_PER_HOP_WINDOW,
        min(int_value(window, 8), 24),
    )
    if diagnostics is not None:
        diagnostics["per_hop_window"] = max(
            int_value(diagnostics.get("per_hop_window")),
            per_hop_window,
        )
    payload_cache: dict[int, tuple[dict[str, Any], str]] = {}

    def payload_for(index: int) -> tuple[dict[str, Any], str]:
        if index not in payload_cache:
            payload_cache[index] = raw_payload_for_usage_segment_event(
                events[index],
                hit=hit,
                distance=index - start,
                manifest_cache=manifest_cache,
                raw_preview_cache=raw_preview_cache,
            )
        return payload_cache[index]

    direct_result_index: int | None = None
    direct_result_payload: dict[str, Any] = {}
    direct_upper = min(len(events), start + 1 + per_hop_window)
    for index in range(start + 1, direct_upper):
        event = events[index]
        if not entity_usage_segment_event_is_tool_result(event):
            continue
        if str(event.get("correlation_id") or "") != source_correlation:
            continue
        payload, status = payload_for(index)
        if not payload:
            bump("raw_unverifiable_event_count")
            continue
        if str(payload_correlation_id(payload) or "") != source_correlation:
            bump("correlation_mismatch_candidate_count")
            continue
        direct_result_index = index
        direct_result_payload = payload
        break
    if direct_result_index is None:
        return {}

    running_identity = async_running_transport_identity_from_payload(
        direct_result_payload
    )
    transport_kind = str(running_identity.get("kind") or "")
    transport_id = str(running_identity.get("id") or "")
    if not transport_kind or not transport_id:
        displayed_output = text_from_content(
            direct_result_payload.get("output"),
            max_chars=4096,
        ).casefold()
        if (
            "script running with cell id" in displayed_output
            or "script running with cell_id" in displayed_output
            or "process running with session id" in displayed_output
            or "process running with session_id" in displayed_output
        ):
            bump("nested_or_non_running_output_count")
        return {}
    bump("running_origin_count")

    accepted: dict[int, dict[str, Any]] = {}
    cursor = direct_result_index
    for hop in range(1, ENTITY_USAGE_ASYNC_MAX_HOPS + 1):
        wait_index: int | None = None
        wait_payload: dict[str, Any] = {}
        wait_correlation = ""
        wait_upper = min(len(events), cursor + 1 + per_hop_window)
        for index in range(cursor + 1, wait_upper):
            event = events[index]
            if str(event.get("type") or "") not in ENTITY_USAGE_DIRECT_TYPES:
                continue
            payload, _status = payload_for(index)
            if not payload:
                continue
            continuation_identity = (
                async_continuation_transport_identity_from_payload(payload)
            )
            candidate_kind = str(continuation_identity.get("kind") or "")
            candidate_id = str(continuation_identity.get("id") or "")
            if not candidate_kind or not candidate_id:
                continue
            if candidate_kind != transport_kind or candidate_id != transport_id:
                bump("cell_mismatch_candidate_count")
                continue
            raw_correlation = str(payload_correlation_id(payload) or "")
            if not raw_correlation:
                bump("correlation_mismatch_candidate_count")
                continue
            wait_index = index
            wait_payload = payload
            wait_correlation = raw_correlation
            break
        if wait_index is None:
            bump("pending_chain_count")
            break

        wait_event = compact_usage_event_from_segment_event(
            events[wait_index],
            hit=hit,
            role="consequence",
            source="segment_async_continuation",
            source_doc_id=str(hit.get("doc_id") or ""),
            distance=wait_index - start,
            relation=(
                "async_wait_cell_id"
                if transport_kind == "cell"
                else "async_process_session_id"
            ),
        )
        wait_event_fields = {
            "correlation_id": wait_correlation,
            "source_correlation_id": source_correlation,
            "async_hop": hop,
            "async_transport_state": "wait_call",
        }
        if transport_kind == "cell":
            wait_event_fields["async_cell_id"] = transport_id
        else:
            wait_event_fields.update(
                {
                    "async_transport_kind": transport_kind,
                    "async_transport_id": transport_id,
                }
            )
        wait_event.update(wait_event_fields)
        accepted[wait_index] = wait_event
        bump("accepted_wait_call_count")

        result_index: int | None = None
        result_payload: dict[str, Any] = {}
        result_upper = min(len(events), wait_index + 1 + per_hop_window)
        for index in range(wait_index + 1, result_upper):
            event = events[index]
            if not entity_usage_segment_event_is_tool_result(event):
                continue
            payload, _status = payload_for(index)
            if not payload:
                if str(event.get("correlation_id") or "") == wait_correlation:
                    bump("raw_unverifiable_event_count")
                continue
            result_correlation = str(payload_correlation_id(payload) or "")
            if result_correlation != wait_correlation:
                bump("correlation_mismatch_candidate_count")
                continue
            result_index = index
            result_payload = payload
            break
        if result_index is None:
            bump("pending_chain_count")
            break

        result_event = compact_usage_event_from_segment_event(
            events[result_index],
            hit=hit,
            role="result",
            source="segment_async_continuation",
            source_doc_id=str(hit.get("doc_id") or ""),
            distance=result_index - start,
            relation="async_wait_result",
        )
        next_identity = async_running_transport_identity_from_payload(result_payload)
        next_kind = str(next_identity.get("kind") or "")
        next_id = str(next_identity.get("id") or "")
        result_event_fields = {
            "correlation_id": wait_correlation,
            "source_correlation_id": source_correlation,
            "async_hop": hop,
            "async_transport_state": "running" if next_id else "terminal",
        }
        if transport_kind == "cell":
            result_event_fields["async_cell_id"] = transport_id
        else:
            result_event_fields.update(
                {
                    "async_transport_kind": transport_kind,
                    "async_transport_id": transport_id,
                }
            )
        result_event.update(result_event_fields)
        if next_id:
            # The outer async envelope is stronger status evidence than words
            # inside the displayed process output. Preserve a shadowed ERROR
            # classification for audit, but do not present a still-running
            # poll as a failed consequence.
            if str(result_event.get("event_type") or "") == "ERROR":
                result_event["classified_event_type"] = "ERROR"
                result_event["event_type"] = "TOOL_OUTPUT"
                result_event["classification_shadowed_by"] = (
                    "source_verified_async_running_envelope"
                )
            result_event.update(
                {
                    "outcome": "observed",
                    "result_status": "running",
                    "result_status_basis": (
                        "source_verified_async_transport_envelope"
                    ),
                    "result_status_admission": (
                        "source_verified_async_wait_result"
                    ),
                }
            )
        else:
            terminal_outcome = command_output_envelope_outcome(
                tool_transport_text(result_payload)
            )
            if terminal_outcome:
                result_event.update(
                    {
                        "outcome": terminal_outcome,
                        "result_status": terminal_outcome,
                        "result_status_basis": (
                            "source_verified_async_terminal_envelope"
                        ),
                        "result_status_admission": (
                            "source_verified_async_wait_result"
                        ),
                    }
                )
        accepted[result_index] = result_event
        bump("accepted_wait_result_count")
        if not next_id:
            bump("completed_chain_count")
            break
        if next_kind != transport_kind or next_id != transport_id:
            bump("cell_mismatch_candidate_count")
            bump("pending_chain_count")
            break
        if hop >= ENTITY_USAGE_ASYNC_MAX_HOPS:
            bump("hop_limit_exhausted_count")
            bump("pending_chain_count")
            break
        cursor = result_index
    return accepted


def consequence_events_for_usage_hit(
    hit: dict[str, Any],
    *,
    window: int = 8,
    segment_cache: dict[str, list[dict[str, Any]]] | None = None,
    false_correlation_events: list[dict[str, Any]] | None = None,
    manifest_cache: dict[str, dict[str, Any]] | None = None,
    raw_preview_cache: dict[tuple[str, str, str, int], dict[str, Any]] | None = None,
    async_diagnostics: dict[str, int] | None = None,
    causal_diagnostics: dict[str, int] | None = None,
) -> list[dict[str, Any]]:
    usage_event_id = str(hit.get("event_id") or "")
    if not usage_event_id:
        return []
    events = segment_events_for_hit(hit, segment_cache=segment_cache)
    if not events:
        return []
    index_by_id = {str(event.get("event_id") or ""): idx for idx, event in enumerate(events)}
    start = index_by_id.get(usage_event_id)
    if start is None:
        return []
    usage_event = events[start]
    usage_correlation = str(usage_event.get("correlation_id") or "")
    usage_payload, _usage_payload_status = raw_payload_for_usage_segment_event(
        usage_event,
        hit=hit,
        distance=0,
        manifest_cache=manifest_cache,
        raw_preview_cache=raw_preview_cache,
    )
    source_tool_name = (
        tool_name_from_payload(usage_payload)
        if usage_payload
        else ""
    )
    source_mcp_identity_items = (
        mcp_tool_invocation_identities_from_payload(usage_payload)
    )
    requested_source_mcp_route_key = str(
        hit.get("mcp_tool_usage_route_key") or ""
    )
    if requested_source_mcp_route_key:
        source_mcp_identity_items = [
            identity
            for identity in source_mcp_identity_items
            if str(identity.get("route_key") or "")
            == requested_source_mcp_route_key
        ]
    source_mcp_identities = {
        (
            str(identity.get("service_key") or ""),
            str(identity.get("tool_key") or ""),
        )
        for identity in source_mcp_identity_items
        if str(identity.get("service_key") or "")
        and str(identity.get("tool_key") or "")
    }
    source_mcp_identity_fallback_allowed = bool(
        source_mcp_identities
        and any(
            str(invocation.get("namespace") or "") == "mcp"
            for invocation in custom_exec_nested_tool_invocations(
                usage_payload
            )
        )
    )
    if causal_diagnostics is not None:
        for key in ENTITY_USAGE_CAUSAL_DIAGNOSTIC_KEYS:
            causal_diagnostics.setdefault(key, 0)

    def bump_causal(key: str, amount: int = 1) -> None:
        if causal_diagnostics is not None:
            causal_diagnostics[key] = int_value(causal_diagnostics.get(key)) + amount

    selected: list[dict[str, Any]] = []
    max_distance = max(1, min(int_value(window, 8), 24))
    async_events_by_index = async_continuation_events_for_usage_hit(
        hit,
        events=events,
        start=start,
        window=max_distance,
        manifest_cache=manifest_cache,
        raw_preview_cache=raw_preview_cache,
        diagnostics=async_diagnostics,
    )
    last_index = min(len(events), start + 1 + max_distance)
    if async_events_by_index:
        last_index = min(len(events), max(last_index, max(async_events_by_index) + 1))
    selected_limit = max_distance + (ENTITY_USAGE_ASYNC_MAX_HOPS * 2)
    terminal_correlated_result_seen = False
    user_boundary_seen = False
    post_terminal_reasoning_boundary_seen = False
    parallel_correlation_ids: set[str] = set()
    structured_mcp_identity_fallback_open = (
        source_mcp_identity_fallback_allowed
    )
    for index in range(start + 1, last_index):
        distance = index - start
        event = events[index]
        event_type = str(event.get("type") or "")
        if event_type == "USER_INTENT":
            structured_mcp_identity_fallback_open = False
            user_boundary_seen = True
            bump_causal("user_boundary_count")
            continue
        if event_type == "ASSISTANT_REASONING_BOUNDARY":
            structured_mcp_identity_fallback_open = False
            if terminal_correlated_result_seen and not user_boundary_seen:
                post_terminal_reasoning_boundary_seen = True
                continue
        if index in async_events_by_index:
            async_event = async_events_by_index[index]
            selected.append(async_event)
            if (
                str(async_event.get("relation") or "") == "async_wait_result"
                and str(async_event.get("async_transport_state") or "") == "terminal"
            ):
                terminal_correlated_result_seen = True
            if len(selected) >= selected_limit:
                break
            continue
        if distance > max_distance:
            continue
        correlation = str(event.get("correlation_id") or "")
        is_tool_result = entity_usage_segment_event_is_tool_result(event)
        is_correlated_status = entity_usage_segment_event_is_correlated_status(event)
        result_payload_for_event: dict[str, Any] | None = None
        structured_mcp_receipt_identity: dict[str, str] = {}
        structured_mcp_receipt_match = False
        structured_mcp_receipt_match_basis = ""
        if is_tool_result and source_mcp_identities:
            result_payload, _result_payload_status = (
                raw_payload_for_usage_segment_event(
                    event,
                    hit=hit,
                    distance=distance,
                    manifest_cache=manifest_cache,
                    raw_preview_cache=raw_preview_cache,
                )
            )
            if isinstance(result_payload, dict):
                result_payload_for_event = result_payload
                structured_mcp_receipt_identity = (
                    structured_mcp_result_identity(result_payload)
                )
                receipt_identity_key = (
                    str(
                        structured_mcp_receipt_identity.get(
                            "service_key"
                        )
                        or ""
                    ),
                    str(
                        structured_mcp_receipt_identity.get(
                            "tool_key"
                        )
                        or ""
                    ),
                )
                structured_mcp_receipt_identity_matches_source = (
                    bool(receipt_identity_key[0])
                    and bool(receipt_identity_key[1])
                    and receipt_identity_key in source_mcp_identities
                )
                if (
                    structured_mcp_receipt_identity_matches_source
                    and usage_correlation
                    and correlation == usage_correlation
                ):
                    structured_mcp_receipt_match = True
                    structured_mcp_receipt_match_basis = (
                        "correlation_identity"
                    )
                elif (
                    structured_mcp_receipt_identity_matches_source
                    and structured_mcp_identity_fallback_open
                ):
                    structured_mcp_receipt_match = True
                    structured_mcp_receipt_match_basis = (
                        "nested_exec_immediate_identity_fallback"
                    )
                elif structured_mcp_receipt_identity_matches_source:
                    bump_causal(
                        "structured_mcp_receipt_identity_ambiguous_rejected_count"
                    )
        if (
            event_type in ENTITY_USAGE_DIRECT_TYPES
            or is_tool_result
            or is_correlated_status
        ):
            structured_mcp_identity_fallback_open = False
        if (
            usage_correlation
            and correlation
            and correlation != usage_correlation
            and not structured_mcp_receipt_match
            and (
                event_type in ENTITY_USAGE_DIRECT_TYPES
                or is_tool_result
                or is_correlated_status
            )
        ):
            parallel_correlation_ids.add(correlation)
        if entity_usage_segment_event_has_canonical_agent_mirror(
            events,
            index,
            hit=hit,
            manifest_cache=manifest_cache,
            raw_preview_cache=raw_preview_cache,
            diagnostics=causal_diagnostics,
        ):
            bump_causal("agent_stream_mirror_rejected_count")
            continue
        if (
            not structured_mcp_receipt_match
            and entity_usage_event_is_foreign_correlated_result(
                usage_correlation,
                event,
            )
        ):
            if false_correlation_events is not None:
                rejected = compact_usage_event_from_segment_event(
                    event,
                    hit=hit,
                    role="context",
                    source="segment_neighbor_rejected",
                    source_doc_id=str(hit.get("doc_id") or ""),
                    distance=distance,
                    relation="false_correlation",
                )
                rejected["source_correlation_id"] = usage_correlation
                rejected["rejected_correlation_id"] = correlation
                false_correlation_events.append(rejected)
            continue
        structured_result_status: dict[str, str] = {}
        relation = "next_relevant_event"
        if structured_mcp_receipt_match:
            relation = (
                "structured_mcp_receipt_correlation_identity_match"
                if structured_mcp_receipt_match_basis
                == "correlation_identity"
                else "structured_mcp_receipt_identity_match"
            )
            receipt_outcome = structured_payload_outcome(
                result_payload_for_event
            )
            if receipt_outcome in {"succeeded", "failed"}:
                structured_result_status = {
                    "result_status": receipt_outcome,
                    "result_status_basis": (
                        "source_verified_mcp_tool_call_end_identity"
                    ),
                    "result_status_admission": (
                        "source_verified_"
                        f"{relation}"
                    ),
                    "result_status_tool": str(
                        structured_mcp_receipt_identity.get(
                            "route_key"
                        )
                        or ""
                    ),
                    "result_outcome": receipt_outcome,
                }
                bump_causal("structured_result_status_admitted_count")
            terminal_correlated_result_seen = True
            bump_causal("structured_mcp_receipt_admitted_count")
            bump_causal(
                (
                    "structured_mcp_receipt_correlation_identity_admitted_count"
                    if structured_mcp_receipt_match_basis
                    == "correlation_identity"
                    else "structured_mcp_receipt_identity_fallback_admitted_count"
                )
            )
        elif usage_correlation and correlation == usage_correlation:
            if is_correlated_status:
                relation = "same_correlation_status"
                bump_causal("correlated_status_accepted_count")
            else:
                relation = "same_correlation_id"
            if is_tool_result:
                result_payload = result_payload_for_event
                if result_payload is None:
                    result_payload, _status = (
                        raw_payload_for_usage_segment_event(
                            event,
                            hit=hit,
                            distance=distance,
                            manifest_cache=manifest_cache,
                            raw_preview_cache=raw_preview_cache,
                        )
                    )
                structured_result_status = (
                    source_verified_structured_tool_result_status(
                        result_payload,
                        source_tool_name=source_tool_name,
                    )
                )
                if structured_result_status:
                    bump_causal("structured_result_status_admitted_count")
                    if (
                        structured_result_status.get("result_status")
                        == "timed_out"
                    ):
                        bump_causal("structured_result_timeout_count")
                terminal_correlated_result_seen = bool(
                    result_payload
                    and str(payload_correlation_id(result_payload) or "") == usage_correlation
                    and not async_running_transport_identity_from_payload(result_payload)
                )
        elif usage_correlation and is_tool_result:
            if (
                event_type == "VERIFICATION"
                and terminal_correlated_result_seen
                and not user_boundary_seen
            ):
                if (
                    parallel_correlation_ids
                    and post_terminal_reasoning_boundary_seen
                ):
                    if false_correlation_events is not None:
                        rejected = compact_usage_event_from_segment_event(
                            event,
                            hit=hit,
                            role="context",
                            source="segment_neighbor_rejected",
                            source_doc_id=str(hit.get("doc_id") or ""),
                            distance=distance,
                            relation="parallel_batch_verification_context",
                        )
                        rejected["source_correlation_id"] = usage_correlation
                        rejected["parallel_correlation_ids"] = sorted(
                            parallel_correlation_ids
                        )
                        rejected["causal_admission"] = (
                            "rejected_parallel_batch_ambiguity"
                        )
                        false_correlation_events.append(rejected)
                    bump_causal("parallel_batch_verification_rejected_count")
                    continue
                relation = "post_correlated_verification"
                bump_causal("post_correlated_outcome_accepted_count")
            else:
                bump_causal("uncorrelated_result_rejected_count")
                continue
        elif event_type in ENTITY_USAGE_OUTCOME_TYPES and usage_correlation:
            if not terminal_correlated_result_seen or user_boundary_seen:
                bump_causal("uncorrelated_outcome_rejected_count")
                continue
            if (
                parallel_correlation_ids
                and post_terminal_reasoning_boundary_seen
            ):
                if false_correlation_events is not None:
                    rejected = compact_usage_event_from_segment_event(
                        event,
                        hit=hit,
                        role="context",
                        source="segment_neighbor_rejected",
                        source_doc_id=str(hit.get("doc_id") or ""),
                        distance=distance,
                        relation="parallel_batch_outcome_context",
                    )
                    rejected["source_correlation_id"] = usage_correlation
                    rejected["parallel_correlation_ids"] = sorted(
                        parallel_correlation_ids
                    )
                    rejected["causal_admission"] = (
                        "rejected_parallel_batch_ambiguity"
                    )
                    false_correlation_events.append(rejected)
                bump_causal("parallel_batch_outcome_rejected_count")
                continue
            relation = "post_correlated_outcome"
            bump_causal("post_correlated_outcome_accepted_count")
        elif (
            event_type not in ENTITY_USAGE_CONSEQUENCE_TYPES
            and not is_tool_result
            and not is_correlated_status
        ):
            continue
        facets = event.get("facets") if isinstance(event.get("facets"), dict) else {}
        conversation_act = facets.get("conversation_act") if isinstance(facets.get("conversation_act"), dict) else {}
        session_act = facets.get("session_act") if isinstance(facets.get("session_act"), dict) else {}
        role = (
            "consequence"
            if is_correlated_status
            else "result"
            if is_tool_result
            else entity_usage_event_role(
                event_type,
                str(conversation_act.get("kind") or ""),
                str(session_act.get("kind") or ""),
            )
        )
        compact_event = compact_usage_event_from_segment_event(
            event,
            hit=hit,
            role=role if role != "context" else "consequence",
            source="segment_neighbor",
            source_doc_id=str(hit.get("doc_id") or ""),
            distance=distance,
            relation=relation,
        )
        if structured_result_status:
            compact_event.update(structured_result_status)
            compact_event["outcome"] = structured_result_status[
                "result_outcome"
            ]
        if structured_mcp_receipt_match:
            compact_event["mcp_result_identity"] = dict(
                structured_mcp_receipt_identity
            )
            compact_event["source_correlation_id"] = usage_correlation
            compact_event["causal_admission"] = relation
        selected.append(compact_event)
        if len(selected) >= selected_limit:
            break
    return selected


def usage_event_with_raw_preview(
    event: dict[str, Any],
    *,
    max_chars: int = 600,
    manifest_cache: dict[str, dict[str, Any]] | None = None,
    raw_preview_cache: dict[tuple[str, str, str, int], dict[str, Any]] | None = None,
) -> dict[str, Any]:
    enriched = dict(event)
    enriched["raw_preview"] = raw_preview_for_usage_event(
        enriched,
        max_chars=max_chars,
        manifest_cache=manifest_cache,
        raw_preview_cache=raw_preview_cache,
    )
    return enriched


def local_usage_neighborhood_for_hit(
    hit: dict[str, Any],
    *,
    before: int = 3,
    after: int = 8,
    raw_preview_chars: int = 600,
    segment_cache: dict[str, list[dict[str, Any]]] | None = None,
    manifest_cache: dict[str, dict[str, Any]] | None = None,
    raw_preview_cache: dict[tuple[str, str, str, int], dict[str, Any]] | None = None,
) -> dict[str, Any]:
    usage_event_id = str(hit.get("event_id") or "")
    if not usage_event_id:
        return {
            "ok": False,
            "diagnostics": ["usage_hit_missing_event_id"],
            "source_usage_event": usage_event_with_raw_preview(
                compact_usage_event_from_search_hit(hit, role="usage"),
                max_chars=raw_preview_chars,
                manifest_cache=manifest_cache,
                raw_preview_cache=raw_preview_cache,
            ),
            "local_events": [],
            "consequence_events": [],
            "document_refs": [],
        }
    events = segment_events_for_hit(hit, segment_cache=segment_cache)
    if not events:
        return {
            "ok": False,
            "diagnostics": ["segment_events_unavailable"],
            "source_usage_event": usage_event_with_raw_preview(
                compact_usage_event_from_search_hit(hit, role="usage"),
                max_chars=raw_preview_chars,
                manifest_cache=manifest_cache,
                raw_preview_cache=raw_preview_cache,
            ),
            "local_events": [],
            "consequence_events": [],
            "document_refs": [],
        }
    index_by_id = {str(event.get("event_id") or ""): idx for idx, event in enumerate(events)}
    start = index_by_id.get(usage_event_id)
    if start is None:
        return {
            "ok": False,
            "diagnostics": ["usage_event_not_found_in_segment_index"],
            "source_usage_event": usage_event_with_raw_preview(
                compact_usage_event_from_search_hit(hit, role="usage"),
                max_chars=raw_preview_chars,
                manifest_cache=manifest_cache,
                raw_preview_cache=raw_preview_cache,
            ),
            "local_events": [],
            "consequence_events": [],
            "document_refs": [],
        }

    before = max(0, min(int_value(before, 3), 24))
    after = max(1, min(int_value(after, 8), 48))
    raw_preview_chars = max(0, min(int_value(raw_preview_chars, 600), 2000))
    source_event = events[start]
    source_correlation = str(source_event.get("correlation_id") or "")
    lower = max(0, start - before)
    upper = min(len(events), start + after + 1)
    local_events: list[dict[str, Any]] = []

    for idx in range(lower, upper):
        event = events[idx]
        offset = idx - start
        relation = "selected_usage" if offset == 0 else ("before_context" if offset < 0 else "after_context")
        facets = event.get("facets") if isinstance(event.get("facets"), dict) else {}
        conversation_act = facets.get("conversation_act") if isinstance(facets.get("conversation_act"), dict) else {}
        session_act = facets.get("session_act") if isinstance(facets.get("session_act"), dict) else {}
        role = entity_usage_event_role(
            str(event.get("type") or ""),
            str(conversation_act.get("kind") or ""),
            str(session_act.get("kind") or ""),
        )
        correlation = str(event.get("correlation_id") or "")
        if offset == 0:
            compact = compact_usage_event_from_search_hit(hit, role="usage", source="route_only_search")
            role = "usage"
        else:
            is_tool_result = entity_usage_segment_event_is_tool_result(event)
            foreign_correlated_result = (
                offset > 0
                and entity_usage_event_is_foreign_correlated_result(source_correlation, event)
            )
            if foreign_correlated_result:
                relation = "foreign_correlation_context"
                role = "context"
            elif offset > 0 and source_correlation and correlation == source_correlation:
                relation = "same_correlation_id"
            elif offset > 0 and (str(event.get("type") or "") in ENTITY_USAGE_CONSEQUENCE_TYPES or is_tool_result):
                relation = "consequence_candidate"
            if is_tool_result and role == "context" and not foreign_correlated_result:
                role = "result"
            compact = compact_usage_event_from_segment_event(
                event,
                hit=hit,
                role=role if role != "context" else ("consequence" if relation in {"same_correlation_id", "consequence_candidate"} else "context"),
                source="segment_neighborhood",
                source_doc_id=str(hit.get("doc_id") or ""),
                distance=abs(offset),
                relation=relation,
            )
        compact["offset"] = offset
        compact["relation"] = relation
        compact["raw_preview"] = raw_preview_for_usage_event(
            compact,
            max_chars=raw_preview_chars,
            manifest_cache=manifest_cache,
            raw_preview_cache=raw_preview_cache,
        ) if raw_preview_chars else {"status": "not_requested", "line": None, "text": ""}
        local_events.append(compact)

    consequence_events = [
        event
        for event in local_events
        if int_value(event.get("offset")) > 0
        and (
            str(event.get("relation") or "") in {"same_correlation_id", "consequence_candidate"}
            or str(event.get("role") or "") in {"result", "outcome", "consequence"}
        )
    ]
    document_refs = entity_usage_document_refs(
        local_events,
        limit=80,
        manifest_cache=manifest_cache,
        raw_preview_cache=raw_preview_cache,
    )
    raw_preview_counts: Counter[str] = Counter()
    for event in local_events:
        preview = event.get("raw_preview") if isinstance(event.get("raw_preview"), dict) else {}
        raw_preview_counts[str(preview.get("status") or "unknown")] += 1
    return {
        "ok": True,
        "source_usage_event": next(
            (event for event in local_events if int_value(event.get("offset")) == 0),
            usage_event_with_raw_preview(
                compact_usage_event_from_search_hit(hit, role="usage"),
                max_chars=raw_preview_chars,
                manifest_cache=manifest_cache,
                raw_preview_cache=raw_preview_cache,
            ),
        ),
        "before": before,
        "after": after,
        "local_event_count": len(local_events),
        "consequence_event_count": len(consequence_events),
        "document_ref_count": len(document_refs),
        "raw_preview_counts": dict(sorted(raw_preview_counts.items())),
        "local_events": local_events,
        "consequence_events": consequence_events,
        "document_refs": document_refs,
        "diagnostics": [],
    }


def merge_usage_hit(target: dict[str, dict[str, Any]], hit: dict[str, Any], matched_route: str) -> None:
    doc_id = str(hit.get("doc_id") or "")
    if not doc_id:
        return
    existing = target.get(doc_id)
    if existing is None:
        existing = dict(hit)
        existing["matched_routes"] = []
        target[doc_id] = existing
    else:
        # A query-time raw-backed hit may arrive before the materialized
        # projection for the same archived event.  Preserve its stronger raw
        # admission while filling projection-only join coordinates such as a
        # task episode id.
        for key in (
            "task_episode_id",
            "timestamp",
            "session_date",
            "snippet",
        ):
            if not existing.get(key) and hit.get(key):
                existing[key] = hit.get(key)
    matched = existing.setdefault("matched_routes", [])
    if isinstance(matched, list) and matched_route and matched_route not in matched:
        matched.append(matched_route)


def entity_usage_event_freshness_status(event: dict[str, Any]) -> str:
    freshness = event.get("freshness") if isinstance(event.get("freshness"), dict) else {}
    return str(freshness.get("status") or "unverifiable")


def entity_usage_freshness_counts(events: list[dict[str, Any]]) -> dict[str, int]:
    counts: Counter[str] = Counter()
    for event in events:
        if isinstance(event, dict):
            counts[entity_usage_event_freshness_status(event)] += 1
    return dict(sorted(counts.items()))


def entity_usage_sessions_summary(events: list[dict[str, Any]]) -> list[dict[str, Any]]:
    summaries: dict[str, dict[str, Any]] = {}
    for event in events:
        label = str(event.get("session_label") or event.get("session_id") or "unknown")
        summary = summaries.setdefault(
            label,
            {
                "session_label": label,
                "session_id": event.get("session_id"),
                "session_date": event.get("session_date"),
                "entrypoint_event_count": 0,
                "usage_event_count": 0,
                "result_event_count": 0,
                "outcome_event_count": 0,
                "context_event_count": 0,
                "fresh_event_count": 0,
                "stale_event_count": 0,
                "unverifiable_event_count": 0,
                "freshness_counts": {},
                "event_refs": [],
            },
        )
        role = str(event.get("role") or "context")
        key = f"{role}_event_count" if role in {"entrypoint", "usage", "result", "outcome"} else "context_event_count"
        summary[key] = int_value(summary.get(key)) + 1
        freshness_status = entity_usage_event_freshness_status(event)
        if freshness_status in {
            "fresh",
            "current",
            "bounded_current",
            "current_with_deferred_live_updates",
        }:
            freshness_key = "fresh_event_count"
        elif freshness_status in {"stale", "dirty"}:
            freshness_key = "stale_event_count"
        else:
            freshness_key = "unverifiable_event_count"
        summary[freshness_key] = int_value(summary.get(freshness_key)) + 1
        freshness_counts = summary.setdefault("freshness_counts", {})
        if isinstance(freshness_counts, dict):
            freshness_counts[freshness_status] = int_value(freshness_counts.get(freshness_status)) + 1
        refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
        ref_value = refs.get("raw") or refs.get("segment") or refs.get("session")
        if ref_value and ref_value not in summary["event_refs"] and len(summary["event_refs"]) < 6:
            summary["event_refs"].append(ref_value)
    return sorted(summaries.values(), key=lambda item: (str(item.get("session_date") or ""), str(item.get("session_label") or "")), reverse=True)


def entity_usage_audit(
    *,
    aoa_root: Path,
    anchor: str,
    kind: str = "auto",
    limit: int = 20,
    per_route_limit: int = 20,
    consequence_window: int = 8,
    document_limit: int = 60,
    provider: str = "portable_sqlite",
    session: str | None = None,
    correlation_id: str | None = None,
    before_event_id: str | None = None,
    write_report: bool = False,
) -> dict[str, Any]:
    now = utc_now()
    requested_kind = str(kind or "auto").strip().lower() or "auto"
    normalized_kind = normalize_trace_route_kind(kind)
    normalized_correlation_id = str(correlation_id or "").strip()
    if normalized_kind not in TRACE_ROUTE_KINDS:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "session_memory_entity_usage_audit",
            "generated_at": now,
            "ok": False,
            "mutates": False,
            "anchor": anchor,
            **trace_kind_payload_fields(kind, normalized_kind),
            "diagnostics": [f"unknown trace kind: {kind}"],
        }
    if normalized_correlation_id and not session:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "session_memory_entity_usage_audit",
            "generated_at": now,
            "ok": False,
            "mutates": False,
            "anchor": anchor,
            **trace_kind_payload_fields(kind, normalized_kind),
            "correlation_id": normalized_correlation_id,
            "diagnostics": [
                "exact correlation selection requires an explicit session"
            ],
        }
    if (
        normalized_correlation_id
        and not ENTITY_USAGE_CORRELATION_ID_RE.fullmatch(
            normalized_correlation_id
        )
    ):
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "session_memory_entity_usage_audit",
            "generated_at": now,
            "ok": False,
            "mutates": False,
            "anchor": anchor,
            **trace_kind_payload_fields(kind, normalized_kind),
            "correlation_id": normalized_correlation_id,
            "diagnostics": [
                "invalid exact correlation identifier"
            ],
        }
    exact_instance_mode = bool(normalized_correlation_id)
    limit = max(1, min(int_value(limit, 20), 200))
    per_route_limit = max(1, min(int_value(per_route_limit, 20), 100))
    # Global audits keep the advertised fetch limit as the hard upstream budget
    # and reserve its last row as a sentinel. A session-scoped paged audit may
    # request one explicit extra sentinel row; expose that request budget below.
    route_fetch_limit = max(per_route_limit, min(100, max(limit * 4, limit + 8, 12)))
    route_candidate_limit = max(1, route_fetch_limit - 1)
    route_upstream_request_limit = route_fetch_limit + 1 if session else route_fetch_limit
    route_selected_candidate_limit = route_fetch_limit if session else route_candidate_limit
    diagnostics = trace_identity_diagnostics(anchor, kind=normalized_kind)
    mcp_tool_resolution = (
        mcp_tool_route_resolution(
            aoa_root,
            anchor,
            session=session,
        )
        if requested_kind == "mcp_tool"
        else {}
    )
    mcp_tool_query_time_source_hits = [
        hit
        for hit in mcp_tool_resolution.pop("_session_hits", [])
        if isinstance(hit, dict)
    ] if requested_kind == "mcp_tool" else []
    skill_query_time_source_probe = (
        skill_session_evidence_probe(
            aoa_root=aoa_root,
            anchor=anchor,
            session=session,
            before_event_id=before_event_id,
        )
        if normalized_kind == "skill"
        else {}
    )
    skill_query_time_source_hits = [
        hit
        for hit in skill_query_time_source_probe.pop("_hits", [])
        if isinstance(hit, dict)
    ] if normalized_kind == "skill" else []
    if exact_instance_mode:
        mcp_tool_query_time_source_hits = [
            hit
            for hit in mcp_tool_query_time_source_hits
            if str(hit.get("correlation_id") or "")
            == normalized_correlation_id
        ]
        skill_query_time_source_hits = [
            hit
            for hit in skill_query_time_source_hits
            if str(hit.get("correlation_id") or "")
            == normalized_correlation_id
        ]
    candidates = (
        list(mcp_tool_resolution.get("route_candidates", []))
        if requested_kind == "mcp_tool"
        else trace_route_candidates(anchor, kind=normalized_kind)
    )
    lookup_candidates = trace_route_lookup_candidates(candidates, suppress_generic=bool(diagnostics))
    query_candidates = lookup_candidates
    skill_dispatch_query_candidates = lookup_candidates
    if normalized_kind == "skill":
        exact_skill_candidates = [
            candidate
            for candidate in lookup_candidates
            if str(candidate.get("layer") or "") == "skill"
        ]
        if exact_skill_candidates:
            query_candidates = exact_skill_candidates
            exact_skill_keys = {
                str(candidate.get("key") or "")
                for candidate in exact_skill_candidates
                if str(candidate.get("key") or "")
            }
            exact_entity_dispatch_candidates = [
                candidate
                for candidate in lookup_candidates
                if str(candidate.get("layer") or "") == "entity"
                and str(candidate.get("key") or "") in exact_skill_keys
            ]
            skill_dispatch_query_candidates = [
                *exact_skill_candidates,
                *exact_entity_dispatch_candidates,
            ]
    if exact_instance_mode:
        # Exact instance selection is source-coordinate first. Do not pay for
        # or admit unrelated aggregate route candidates from the same session.
        query_candidates = []
        skill_dispatch_query_candidates = []
    merged: dict[str, dict[str, Any]] = {}
    for source_hit in mcp_tool_query_time_source_hits:
        merge_usage_hit(
            merged,
            source_hit,
            "session_scoped_query_time_raw_mcp_probe",
        )
    for source_hit in skill_query_time_source_hits:
        merge_usage_hit(
            merged,
            source_hit,
            "session_scoped_query_time_raw_skill_probe",
        )
    exact_correlation_probe = entity_usage_exact_correlation_probe(
        aoa_root=aoa_root,
        session=session,
        correlation_id=normalized_correlation_id,
    )
    exact_correlation_hits = [
        hit
        for hit in exact_correlation_probe.pop("_hits", [])
        if isinstance(hit, dict)
    ]
    for source_hit in exact_correlation_hits:
        merge_usage_hit(
            merged,
            source_hit,
            "session_scoped_query_time_exact_correlation_probe",
        )
    route_result_summaries: list[dict[str, Any]] = []
    usage_role_fast_path_supported = bool(
        lookup_candidates
        and not exact_instance_mode
        and normalized_kind in ENTITY_USAGE_DIRECT_TRACE_KINDS
        and search_usage_role_filter_supported(aoa_root, provider=provider)
    )
    usage_role_fast_path_applied = False
    usage_role_fast_path_fetch_limit = 0
    usage_role_fast_path_hit_count = 0
    usage_role_fast_path_usage_hit_count = 0
    broad_route_search_skipped = False
    skill_dispatch_fast_path_applied = False
    skill_dispatch_fast_path_hit_count = 0
    skill_dispatch_entity_probe_applied = False
    skill_dispatch_entity_probe_result_count = 0
    skill_dispatch_entity_probe_accepted_count = 0
    skill_dispatch_entity_probe_rejected_non_dispatch_count = 0
    skill_dispatch_entity_probe_mirror_rejected_count = 0
    upstream_candidate_window_truncated = False
    upstream_usage_candidate_window_truncated = False
    upstream_candidate_window_incomplete = False
    upstream_query_failure_count = 0
    upstream_query_failure_diagnostics: list[str] = []
    if exact_instance_mode:
        diagnostics.extend(
            str(item)
            for item in exact_correlation_probe.get("diagnostics", [])
            if item
        )
        if not exact_correlation_probe.get(
            "candidate_count_exhaustive"
        ):
            upstream_candidate_window_incomplete = True
    mcp_usage_admission_checked_doc_ids: set[str] = set()
    mcp_usage_admission_segment_cache: dict[str, list[dict[str, Any]]] = {}
    mcp_usage_invocation_admitted_count = 0
    mcp_usage_mention_only_rejected_count = 0
    mcp_usage_invocation_unverifiable_count = 0
    tool_usage_admission_checked_doc_ids: set[str] = set()
    tool_usage_admission_segment_cache: dict[str, list[dict[str, Any]]] = {}
    tool_usage_admission_manifest_cache: dict[str, dict[str, Any]] = {}
    tool_usage_admission_raw_preview_cache: dict[
        tuple[str, str, str, int],
        dict[str, Any],
    ] = {}
    tool_usage_invocation_admitted_count = 0
    tool_usage_mention_only_rejected_count = 0
    tool_usage_invocation_unverifiable_count = 0
    mcp_tool_usage_admission_checked_doc_ids: set[str] = set()
    mcp_tool_usage_admission_segment_cache: dict[
        str,
        list[dict[str, Any]],
    ] = {}
    mcp_tool_invocation_admitted_count = 0
    mcp_tool_mention_only_rejected_count = 0
    mcp_tool_invocation_unverifiable_count = 0
    hook_usage_admission_checked_doc_ids: set[str] = set()
    hook_usage_admission_segment_cache: dict[str, list[dict[str, Any]]] = {}
    hook_usage_admission_manifest_cache: dict[str, dict[str, Any]] = {}
    hook_usage_admission_raw_preview_cache: dict[
        tuple[str, str, str, int],
        dict[str, Any],
    ] = {}
    hook_usage_invocation_admitted_count = 0
    hook_usage_command_invocation_admitted_count = 0
    hook_usage_session_activity_rejected_count = 0
    hook_usage_invocation_unverifiable_count = 0
    execution_usage_admission_checked_doc_ids: set[str] = set()
    execution_usage_admission_segment_cache: dict[str, list[dict[str, Any]]] = {}
    execution_usage_admission_manifest_cache: dict[str, dict[str, Any]] = {}
    execution_usage_admission_raw_preview_cache: dict[
        tuple[str, str, str, int],
        dict[str, Any],
    ] = {}
    execution_usage_invocation_admitted_count = 0
    execution_usage_reference_rejected_count = 0
    execution_usage_prelaunch_failure_rejected_count = 0
    execution_usage_invocation_unverifiable_count = 0
    execution_usage_structured_result_candidate_count = 0
    execution_usage_structured_result_admitted_count = 0
    execution_usage_structured_result_parent_rejected_count = 0
    execution_usage_structured_result_parent_unverifiable_count = 0
    execution_inspection_probe_applied = False
    execution_inspection_probe_result_count = 0
    execution_inspection_probe_selected_count = 0
    route_candidate_mcp_keys = {
        str(candidate.get("key") or "")
        for candidate in lookup_candidates
        if str(candidate.get("layer") or "") == "mcp"
        and str(candidate.get("key") or "")
    }
    requested_tool_route_keys = {
        str(candidate.get("key") or "")
        for candidate in lookup_candidates
        if str(candidate.get("layer") or "") == "tool"
        and str(candidate.get("key") or "")
    }
    requested_mcp_tool_identities = [
        identity
        for identity in mcp_tool_resolution.get("identities", [])
        if isinstance(identity, dict)
    ] if requested_kind == "mcp_tool" else []
    requested_mcp_tool_route_keys = {
        str(identity.get("route_key") or "")
        for identity in requested_mcp_tool_identities
        if str(identity.get("route_key") or "")
    }
    requested_mcp_tool_service_keys = {
        str(identity.get("service_key") or "")
        for identity in requested_mcp_tool_identities
        if str(identity.get("service_key") or "")
    }
    requested_mcp_tool_keys = {
        str(identity.get("tool_key") or "")
        for identity in requested_mcp_tool_identities
        if str(identity.get("tool_key") or "")
    }
    # A consumer may ask about an MCP tool by its short runtime name while
    # keeping kind=mcp because the claim under review is transport-backed
    # invocation.  Keep the exact entity/tool retrieval lane, but derive the
    # owning service key solely for structured invocation admission.  This
    # avoids broadening the candidate query to every call made through the
    # service.
    mcp_anchor_service_key = (
        mcp_service_key_for_tool_name(anchor)
        if normalized_kind == "mcp"
        else None
    )
    requested_mcp_route_keys = set(route_candidate_mcp_keys)
    if mcp_anchor_service_key:
        requested_mcp_route_keys.add(mcp_anchor_service_key)
    requested_hook_route_keys = {
        str(candidate.get("key") or "")
        for candidate in lookup_candidates
        if str(candidate.get("layer") or "") in {"hook", "hook_health"}
        and str(candidate.get("key") or "")
        and str(candidate.get("key") or "") not in {
            "raw_unavailable",
            "deferred_sync_or_worker_queue",
            "hook_json_validity",
        }
    }

    def apply_mcp_tool_usage_invocation_admission() -> None:
        nonlocal mcp_tool_invocation_admitted_count
        nonlocal mcp_tool_mention_only_rejected_count
        nonlocal mcp_tool_invocation_unverifiable_count
        if requested_kind != "mcp_tool":
            return
        identity_status = str(
            mcp_tool_resolution.get("status") or "unresolved"
        )
        for hit in merged.values():
            doc_id = str(hit.get("doc_id") or "")
            if (
                not doc_id
                or doc_id in mcp_tool_usage_admission_checked_doc_ids
            ):
                continue
            if compact_usage_event_from_search_hit(hit).get("role") != "usage":
                mcp_tool_usage_admission_checked_doc_ids.add(doc_id)
                continue
            if identity_status != "resolved":
                hit["entity_usage_role_override"] = "context"
                hit["mcp_tool_usage_admission"] = (
                    "ambiguous_mcp_tool_identity"
                    if identity_status == "ambiguous"
                    else "unresolved_mcp_tool_identity"
                )
                mcp_tool_mention_only_rejected_count += 1
                mcp_tool_usage_admission_checked_doc_ids.add(doc_id)
                continue
            source_event = segment_event_for_hit(
                hit,
                segment_cache=mcp_tool_usage_admission_segment_cache,
            )
            if not source_event:
                hit["entity_usage_role_override"] = "context"
                hit["mcp_tool_usage_admission"] = (
                    "invocation_source_unverifiable"
                )
                mcp_tool_invocation_unverifiable_count += 1
                mcp_tool_usage_admission_checked_doc_ids.add(doc_id)
                continue
            facets = (
                source_event.get("facets")
                if isinstance(source_event.get("facets"), dict)
                else {}
            )
            route_signals = (
                facets.get("route_signals")
                if isinstance(facets.get("route_signals"), list)
                else []
            )
            structured_route_key = next(
                (
                    str(signal.get("key") or "")
                    for signal in route_signals
                    if isinstance(signal, dict)
                    and str(signal.get("layer") or "") == "tool"
                    and str(signal.get("key") or "")
                    in requested_mcp_tool_route_keys
                    and str(signal.get("source") or "") == "tool_name"
                ),
                "",
            )
            if structured_route_key:
                identity = next(
                    (
                        item
                        for item in requested_mcp_tool_identities
                        if str(item.get("route_key") or "")
                        == structured_route_key
                    ),
                    {},
                )
                hit["mcp_tool_usage_admission"] = (
                    "structured_invocation_proven"
                )
                hit["mcp_tool_usage_route_key"] = structured_route_key
                hit["mcp_tool_usage_service_key"] = str(
                    identity.get("service_key") or ""
                )
                hit["mcp_tool_usage_tool_key"] = str(
                    identity.get("tool_key") or ""
                )
                mcp_tool_invocation_admitted_count += 1
            else:
                hit["entity_usage_role_override"] = "context"
                hit["mcp_tool_usage_admission"] = (
                    "mention_or_listing_not_structured_invocation"
                )
                mcp_tool_mention_only_rejected_count += 1
            mcp_tool_usage_admission_checked_doc_ids.add(doc_id)

    def apply_tool_usage_invocation_admission() -> None:
        nonlocal tool_usage_invocation_admitted_count
        nonlocal tool_usage_mention_only_rejected_count
        nonlocal tool_usage_invocation_unverifiable_count
        if (
            normalized_kind != "tool"
            or requested_kind == "mcp_tool"
            or not requested_tool_route_keys
        ):
            return
        for hit in merged.values():
            doc_id = str(hit.get("doc_id") or "")
            if not doc_id or doc_id in tool_usage_admission_checked_doc_ids:
                continue
            if compact_usage_event_from_search_hit(hit).get("role") != "usage":
                tool_usage_admission_checked_doc_ids.add(doc_id)
                continue
            source_event = segment_event_for_hit(
                hit,
                segment_cache=tool_usage_admission_segment_cache,
            )
            if not source_event:
                hit["entity_usage_role_override"] = "context"
                hit["tool_usage_admission"] = "invocation_source_unverifiable"
                tool_usage_invocation_unverifiable_count += 1
                tool_usage_admission_checked_doc_ids.add(doc_id)
                continue
            facets = (
                source_event.get("facets")
                if isinstance(source_event.get("facets"), dict)
                else {}
            )
            route_signals = (
                facets.get("route_signals")
                if isinstance(facets.get("route_signals"), list)
                else []
            )
            structured_tool_key = next(
                (
                    str(signal.get("key") or "")
                    for signal in route_signals
                    if isinstance(signal, dict)
                    and str(signal.get("layer") or "") == "tool"
                    and str(signal.get("key") or "") in requested_tool_route_keys
                    and str(signal.get("source") or "") == "tool_name"
                ),
                "",
            )
            if structured_tool_key:
                hit["tool_usage_admission"] = "structured_invocation_proven"
                hit["tool_usage_admission_key"] = structured_tool_key
                hit["tool_usage_invocation_name"] = str(
                    facets.get("tool_qualified_name")
                    or facets.get("tool_name")
                    or structured_tool_key
                )
                hit["tool_usage_invocation_namespace"] = str(
                    facets.get("tool_namespace") or ""
                )
                tool_usage_invocation_admitted_count += 1
                tool_usage_admission_checked_doc_ids.add(doc_id)
                continue
            payload, payload_status = raw_payload_for_usage_segment_event(
                source_event,
                hit=hit,
                distance=0,
                manifest_cache=tool_usage_admission_manifest_cache,
                raw_preview_cache=tool_usage_admission_raw_preview_cache,
            )
            if not payload:
                hit["entity_usage_role_override"] = "context"
                hit["tool_usage_admission"] = (
                    f"invocation_source_unverifiable:{payload_status}"
                )
                tool_usage_invocation_unverifiable_count += 1
                tool_usage_admission_checked_doc_ids.add(doc_id)
                continue
            nested_invocation = next(
                (
                    invocation
                    for invocation in custom_exec_nested_tool_invocations(
                        payload
                    )
                    if route_key_slug(
                        normalized_tool_name(
                            str(invocation.get("name") or "")
                        ),
                        fallback="",
                        max_chars=120,
                    )
                    in requested_tool_route_keys
                ),
                {},
            )
            if nested_invocation:
                nested_name = str(nested_invocation.get("name") or "")
                nested_key = route_key_slug(
                    normalized_tool_name(nested_name),
                    fallback="",
                    max_chars=120,
                )
                hit["tool_usage_admission"] = (
                    "structured_nested_invocation_proven"
                )
                hit["tool_usage_admission_key"] = nested_key
                hit["tool_usage_invocation_name"] = nested_name
                hit["tool_usage_invocation_namespace"] = str(
                    nested_invocation.get("namespace") or ""
                )
                tool_usage_invocation_admitted_count += 1
            else:
                # A TOOL_CALL describes the surrounding transport action, not
                # every tool-like word inside its arguments, paths, or output.
                # Exact postings and text fallback both remain navigation, but
                # only a direct or raw-verified nested call becomes usage.
                hit["entity_usage_role_override"] = "context"
                hit["tool_usage_admission"] = (
                    "mention_not_structured_tool_invocation"
                )
                tool_usage_mention_only_rejected_count += 1
            tool_usage_admission_checked_doc_ids.add(doc_id)

    def apply_mcp_usage_invocation_admission() -> None:
        nonlocal mcp_usage_invocation_admitted_count
        nonlocal mcp_usage_mention_only_rejected_count
        nonlocal mcp_usage_invocation_unverifiable_count
        if normalized_kind != "mcp" or not requested_mcp_route_keys:
            return
        for hit in merged.values():
            doc_id = str(hit.get("doc_id") or "")
            if not doc_id or doc_id in mcp_usage_admission_checked_doc_ids:
                continue
            if compact_usage_event_from_search_hit(hit).get("role") != "usage":
                mcp_usage_admission_checked_doc_ids.add(doc_id)
                continue
            source_event = segment_event_for_hit(
                hit,
                segment_cache=mcp_usage_admission_segment_cache,
            )
            if not source_event:
                hit["mcp_usage_admission"] = "invocation_source_unverifiable"
                mcp_usage_invocation_unverifiable_count += 1
                mcp_usage_admission_checked_doc_ids.add(doc_id)
                continue
            facets = source_event.get("facets") if isinstance(source_event.get("facets"), dict) else {}
            route_signals = (
                facets.get("route_signals")
                if isinstance(facets.get("route_signals"), list)
                else []
            )
            invocation_service_key = next(
                (
                    str(signal.get("key") or "")
                    for signal in route_signals
                    if isinstance(signal, dict)
                    and str(signal.get("layer") or "") == "mcp"
                    and str(signal.get("key") or "") in requested_mcp_route_keys
                    and str(signal.get("source") or "")
                    in {"mcp_tool", "mcp_tool_service"}
                ),
                "",
            )
            if invocation_service_key:
                hit["mcp_usage_admission"] = "structured_invocation_proven"
                hit["mcp_usage_admission_service_key"] = (
                    invocation_service_key
                )
                mcp_usage_invocation_admitted_count += 1
            else:
                # Search document roles describe the event class, not whether
                # this requested MCP service was actually invoked.  Keep the
                # archived TOOL_CALL visible, but demote this entity-specific
                # view when the only match is a mention or query argument.
                hit["entity_usage_role_override"] = "context"
                hit["mcp_usage_admission"] = "mention_or_query_target_not_invocation"
                mcp_usage_mention_only_rejected_count += 1
            mcp_usage_admission_checked_doc_ids.add(doc_id)

    def apply_hook_usage_invocation_admission() -> None:
        nonlocal hook_usage_invocation_admitted_count
        nonlocal hook_usage_command_invocation_admitted_count
        nonlocal hook_usage_session_activity_rejected_count
        nonlocal hook_usage_invocation_unverifiable_count
        if normalized_kind != "hook":
            return
        for hit in merged.values():
            doc_id = str(hit.get("doc_id") or "")
            if not doc_id or doc_id in hook_usage_admission_checked_doc_ids:
                continue
            if compact_usage_event_from_search_hit(hit).get("role") != "usage":
                hook_usage_admission_checked_doc_ids.add(doc_id)
                continue
            source_event = segment_event_for_hit(
                hit,
                segment_cache=hook_usage_admission_segment_cache,
            )
            if not source_event:
                hit["entity_usage_role_override"] = "context"
                hit["hook_usage_admission"] = "hook_invocation_source_unverifiable"
                hook_usage_invocation_unverifiable_count += 1
                hook_usage_admission_checked_doc_ids.add(doc_id)
                continue
            facets = source_event.get("facets") if isinstance(source_event.get("facets"), dict) else {}
            route_signals = (
                facets.get("route_signals")
                if isinstance(facets.get("route_signals"), list)
                else []
            )
            exact_hook_signal = any(
                isinstance(signal, dict)
                and str(signal.get("layer") or "") in {"hook", "hook_health"}
                and route_key_slug(str(signal.get("key") or ""), fallback="") in requested_hook_route_keys
                for signal in route_signals
            )
            invocation_proven = (
                str(source_event.get("type") or "").upper() == "HOOK_EVENT"
                and exact_hook_signal
            )
            if invocation_proven:
                hit["hook_usage_admission"] = "structured_hook_event_proven"
                hook_usage_invocation_admitted_count += 1
                hook_usage_admission_checked_doc_ids.add(doc_id)
                continue
            payload, payload_status = raw_payload_for_usage_segment_event(
                source_event,
                hit=hit,
                distance=0,
                manifest_cache=hook_usage_admission_manifest_cache,
                raw_preview_cache=hook_usage_admission_raw_preview_cache,
            )
            commands = (
                entity_usage_execution_command_candidates(payload)
                if payload
                else []
            )
            command_invocation_proven = any(
                entity_usage_hook_command_proves_invocation(
                    command,
                    anchor=anchor,
                )
                for command in commands
            )
            if command_invocation_proven:
                hit["hook_usage_admission"] = (
                    "structured_hook_command_invocation_proven"
                )
                hook_usage_invocation_admitted_count += 1
                hook_usage_command_invocation_admitted_count += 1
            else:
                # Commands that inspect processes, mutate hook files, or quote
                # lifecycle names are session activity around hooks. They do
                # not prove that this requested operation or hook fired; the
                # exact command and receipt routes remain the authorities.
                hit["entity_usage_role_override"] = "context"
                hit["hook_usage_admission"] = (
                    "session_activity_not_hook_invocation"
                    if payload
                    else f"hook_invocation_source_unverifiable:{payload_status}"
                )
                if payload:
                    hook_usage_session_activity_rejected_count += 1
                else:
                    hook_usage_invocation_unverifiable_count += 1
            hook_usage_admission_checked_doc_ids.add(doc_id)

    def apply_execution_usage_invocation_admission() -> None:
        nonlocal execution_usage_invocation_admitted_count
        nonlocal execution_usage_reference_rejected_count
        nonlocal execution_usage_prelaunch_failure_rejected_count
        nonlocal execution_usage_invocation_unverifiable_count
        nonlocal execution_usage_structured_result_candidate_count
        nonlocal execution_usage_structured_result_admitted_count
        nonlocal execution_usage_structured_result_parent_rejected_count
        nonlocal execution_usage_structured_result_parent_unverifiable_count
        if normalized_kind not in ENTITY_USAGE_EXECUTION_ADMISSION_KINDS:
            return
        for hit in merged.values():
            doc_id = str(hit.get("doc_id") or "")
            if not doc_id or doc_id in execution_usage_admission_checked_doc_ids:
                continue
            original_role = str(
                compact_usage_event_from_search_hit(hit).get("role") or ""
            )
            if original_role not in {"usage", "result"}:
                execution_usage_admission_checked_doc_ids.add(doc_id)
                continue
            source_event = segment_event_for_hit(
                hit,
                segment_cache=execution_usage_admission_segment_cache,
            )
            if not source_event:
                hit["entity_usage_role_override"] = "context"
                hit["execution_entity_usage_admission"] = "invocation_source_unverifiable"
                execution_usage_invocation_unverifiable_count += 1
                execution_usage_admission_checked_doc_ids.add(doc_id)
                continue
            source_correlation_id = str(source_event.get("correlation_id") or "")
            if source_correlation_id:
                # Search projections are navigation surfaces and may omit this
                # field.  The opened segment event is the stronger source for
                # the correlation needed to inspect an admitted or rejected
                # execution request.
                hit["correlation_id"] = source_correlation_id
            payload, payload_status = raw_payload_for_usage_segment_event(
                source_event,
                hit=hit,
                distance=0,
                manifest_cache=execution_usage_admission_manifest_cache,
                raw_preview_cache=execution_usage_admission_raw_preview_cache,
            )
            if not payload:
                if original_role == "usage":
                    hit["entity_usage_role_override"] = "context"
                    hit["execution_entity_usage_admission"] = (
                        f"invocation_source_unverifiable:{payload_status}"
                    )
                    execution_usage_invocation_unverifiable_count += 1
                execution_usage_admission_checked_doc_ids.add(doc_id)
                continue
            if original_role == "result":
                result_commands = entity_usage_execution_result_marker_commands(
                    payload,
                    anchor=anchor,
                    kind=normalized_kind,
                )
                if not result_commands:
                    execution_usage_admission_checked_doc_ids.add(doc_id)
                    continue
                execution_usage_structured_result_candidate_count += 1
                parent_commands, parent_event, parent_status = (
                    entity_usage_execution_result_parent(
                        source_event,
                        hit=hit,
                        segment_cache=execution_usage_admission_segment_cache,
                        manifest_cache=execution_usage_admission_manifest_cache,
                        raw_preview_cache=execution_usage_admission_raw_preview_cache,
                    )
                )
                if not parent_commands:
                    hit["execution_entity_usage_admission"] = (
                        f"structured_result_parent_unverifiable:{parent_status}"
                    )
                    execution_usage_structured_result_parent_unverifiable_count += 1
                    execution_usage_admission_checked_doc_ids.add(doc_id)
                    continue
                if not any(
                    entity_usage_execution_parent_command_is_runner(command)
                    for command in parent_commands
                ):
                    hit["execution_entity_usage_admission"] = (
                        "structured_result_marker_parent_not_runner"
                    )
                    execution_usage_structured_result_parent_rejected_count += 1
                    execution_usage_admission_checked_doc_ids.add(doc_id)
                    continue
                hit_refs = event_refs_from_hit(hit)
                hit["entity_usage_role_override"] = "usage"
                hit["execution_entity_usage_admission"] = (
                    "structured_result_invocation_proven"
                )
                hit["execution_entity_usage_kind"] = normalized_kind
                hit["execution_parent_refs"] = {
                    "session": hit_refs.get("session", ""),
                    "segment": str(
                        parent_event.get("md_anchor")
                        or hit_refs.get("segment")
                        or ""
                    ),
                    "segment_index": hit_refs.get("segment_index", ""),
                    "raw": str(parent_event.get("raw_ref") or ""),
                    "raw_block": hit_refs.get("raw_block", ""),
                }
                execution_usage_invocation_admitted_count += 1
                execution_usage_structured_result_admitted_count += 1
                execution_usage_admission_checked_doc_ids.add(doc_id)
                continue
            commands = entity_usage_execution_command_candidates(payload)
            invocation_proven = any(
                entity_usage_execution_command_proves_invocation(
                    command,
                    anchor=anchor,
                    kind=normalized_kind,
                )
                for command in commands
            )
            if invocation_proven:
                result_payload, _result_event, result_status = (
                    entity_usage_execution_same_correlation_result(
                        source_event,
                        hit=hit,
                        segment_cache=execution_usage_admission_segment_cache,
                        manifest_cache=execution_usage_admission_manifest_cache,
                        raw_preview_cache=execution_usage_admission_raw_preview_cache,
                    )
                )
                prelaunch_failure_reason = (
                    entity_usage_execution_prelaunch_failure_reason(
                        commands,
                        result_payload,
                        anchor=anchor,
                        kind=normalized_kind,
                    )
                )
                result_observation = entity_usage_execution_result_observation(
                    result_payload,
                    prelaunch_failure_reason=prelaunch_failure_reason,
                )
                if prelaunch_failure_reason:
                    hit["entity_usage_role_override"] = "context"
                    hit["execution_entity_usage_admission"] = (
                        "invocation_prelaunch_failure_observed"
                    )
                    hit["execution_entity_usage_admission_reason"] = (
                        prelaunch_failure_reason
                    )
                    hit["execution_entity_usage_kind"] = normalized_kind
                    hit["execution_entity_usage_result_status"] = (
                        result_observation.get("status")
                    )
                    hit["execution_entity_usage_result_code"] = (
                        result_observation.get("code")
                    )
                    hit["execution_entity_usage_result_evidence"] = (
                        result_observation.get("evidence")
                    )
                    execution_usage_prelaunch_failure_rejected_count += 1
                    execution_usage_admission_checked_doc_ids.add(doc_id)
                    continue
                hit["execution_entity_usage_admission"] = (
                    "structured_command_invocation_proven"
                )
                hit["execution_entity_usage_kind"] = normalized_kind
                hit["execution_entity_usage_result_status"] = (
                    result_observation.get("status")
                )
                hit["execution_entity_usage_result_code"] = (
                    result_observation.get("code")
                )
                hit["execution_entity_usage_result_evidence"] = (
                    result_observation.get("evidence")
                )
                if result_status != "available":
                    hit["execution_entity_usage_admission_reason"] = (
                        f"structured_command_intent:{result_status}"
                    )
                execution_usage_invocation_admitted_count += 1
            else:
                # Reading, grepping, checking existence, or importing helpers
                # from a validator/test artifact stays visible as context.  It
                # does not prove that the requested test or validator ran.
                hit["entity_usage_role_override"] = "context"
                inspection_read = any(
                    entity_usage_execution_command_proves_inspection_read(
                        command,
                        anchor=anchor,
                    )
                    for command in commands
                )
                if inspection_read:
                    (
                        result_payload,
                        result_event,
                        result_status,
                    ) = entity_usage_execution_same_correlation_result(
                        source_event,
                        hit=hit,
                        segment_cache=(
                            execution_usage_admission_segment_cache
                        ),
                        manifest_cache=(
                            execution_usage_admission_manifest_cache
                        ),
                        raw_preview_cache=(
                            execution_usage_admission_raw_preview_cache
                        ),
                    )
                    result_observation = (
                        entity_usage_execution_result_observation(
                            result_payload
                        )
                    )
                    result_observation_status = str(
                        result_observation.get("status") or ""
                    )
                    hit_refs = event_refs_from_hit(hit)
                    result_refs = {
                        "session": hit_refs.get("session", ""),
                        "segment": str(
                            result_event.get("md_anchor")
                            or hit_refs.get("segment")
                            or ""
                        ),
                        "segment_index": hit_refs.get(
                            "segment_index",
                            "",
                        ),
                        "raw": str(result_event.get("raw_ref") or ""),
                        "raw_block": hit_refs.get("raw_block", ""),
                    }
                    if (
                        result_status == "available"
                        and result_payload
                        and result_refs.get("raw")
                        and result_observation_status
                        not in {"failed", "timed_out"}
                    ):
                        hit["execution_entity_usage_admission"] = (
                            "structured_inspection_read_proven"
                        )
                        hit["execution_entity_usage_kind"] = (
                            normalized_kind
                        )
                        hit[
                            "execution_entity_usage_result_status"
                        ] = result_observation_status or "observed"
                        hit["execution_entity_usage_result_evidence"] = (
                            result_observation.get("evidence")
                            or "correlation_owned_nonfailure_read_result"
                        )
                        hit["execution_read_result_refs"] = {
                            key: value
                            for key, value in result_refs.items()
                            if value
                        }
                    else:
                        hit["execution_entity_usage_admission"] = (
                            "inspection_or_reference_not_invocation"
                        )
                        hit["execution_entity_usage_admission_reason"] = (
                            "inspection_result_unresolved:"
                            f"{result_status or result_observation_status or 'missing'}"
                        )
                else:
                    hit["execution_entity_usage_admission"] = (
                        "inspection_or_reference_not_invocation"
                    )
                execution_usage_reference_rejected_count += 1
            execution_usage_admission_checked_doc_ids.add(doc_id)

    def bounded_route_results(
        payload: dict[str, Any],
        *,
        selected_limit: int,
        usage_role_filter: str | None = None,
    ) -> tuple[list[dict[str, Any]], bool]:
        nonlocal upstream_candidate_window_truncated
        nonlocal upstream_usage_candidate_window_truncated
        nonlocal upstream_candidate_window_incomplete
        nonlocal upstream_query_failure_count
        if not payload.get("ok"):
            upstream_candidate_window_incomplete = True
            upstream_query_failure_count += 1
            upstream_query_failure_diagnostics.extend(
                str(item)
                for item in payload.get("diagnostics", [])
                if item
            )
        candidates = [
            hit
            for hit in payload.get("results", [])
            if isinstance(hit, dict)
        ] if isinstance(payload.get("results"), list) else []
        selected = candidates[:selected_limit]
        truncated = len(candidates) > len(selected)
        if truncated:
            upstream_candidate_window_truncated = True
            if usage_role_filter == "usage":
                upstream_usage_candidate_window_truncated = True
        return selected, truncated

    def merged_route_counts() -> tuple[int, int, int]:
        apply_mcp_tool_usage_invocation_admission()
        apply_tool_usage_invocation_admission()
        apply_mcp_usage_invocation_admission()
        apply_hook_usage_invocation_admission()
        apply_execution_usage_invocation_admission()
        hit_count = len(merged)
        usage_count = sum(
            1
            for hit in merged.values()
            if compact_usage_event_from_search_hit(hit).get("role") == "usage"
        )
        evidence_count = sum(
            1
            for hit in merged.values()
            if compact_usage_event_from_search_hit(hit).get("role") != "context"
        )
        return hit_count, usage_count, evidence_count

    if usage_role_fast_path_supported:
        usage_role_fast_path_applied = True
        usage_role_fast_path_fetch_limit = route_fetch_limit
        for candidate in query_candidates:
            route_signal_value = str(candidate.get("route_signal") or "")
            route_layer_value = str(candidate.get("layer") or "") if not route_signal_value else None
            matched_route = route_signal_value or f"{candidate.get('layer')}:*"
            payload = search_sessions(
                aoa_root=aoa_root,
                query="",
                limit=(usage_role_fast_path_fetch_limit + 1 if session else usage_role_fast_path_fetch_limit),
                provider=provider,
                session=session,
                event_id_before=before_event_id,
                doc_type="event",
                route_layer=route_layer_value,
                route_signal=route_signal_value or None,
                usage_role="usage",
                explain=True,
                semantic_preview=False,
                hydrate_body=False,
            )
            selected_hits, candidate_window_truncated = bounded_route_results(
                payload,
                selected_limit=(
                    usage_role_fast_path_fetch_limit
                    if session
                    else max(1, usage_role_fast_path_fetch_limit - 1)
                ),
                usage_role_filter="usage",
            )
            route_result_summaries.append(
                {
                    "candidate": candidate,
                    "ok": payload.get("ok"),
                    "result_count": payload.get("result_count"),
                    "selected_result_count": len(selected_hits),
                    "candidate_window_truncated": candidate_window_truncated,
                    "requested_per_route_limit": per_route_limit,
                    "fetch_limit": usage_role_fast_path_fetch_limit,
                    "usage_role_filter": "usage",
                    "diagnostics": payload.get("diagnostics", []),
                }
            )
            if not payload.get("ok"):
                diagnostics.extend(str(item) for item in payload.get("diagnostics", []))
                continue
            for hit in selected_hits:
                merge_usage_hit(merged, hit, matched_route)
        usage_role_fast_path_hit_count, usage_role_fast_path_usage_hit_count, _usage_role_evidence_count = merged_route_counts()

    if usage_role_fast_path_applied and (
        normalized_kind == "skill"
        or usage_role_fast_path_usage_hit_count >= limit
    ):
        broad_route_search_skipped = True
    else:
        for candidate in query_candidates:
            route_signal_value = str(candidate.get("route_signal") or "")
            route_layer_value = str(candidate.get("layer") or "") if not route_signal_value else None
            matched_route = route_signal_value or f"{candidate.get('layer')}:*"
            payload = search_sessions(
                aoa_root=aoa_root,
                query="",
                limit=route_upstream_request_limit,
                provider=provider,
                session=session,
                event_id_before=before_event_id,
                doc_type="event",
                route_layer=route_layer_value,
                route_signal=route_signal_value or None,
                explain=True,
                semantic_preview=False,
                hydrate_body=False,
            )
            selected_hits, candidate_window_truncated = bounded_route_results(
                payload,
                selected_limit=route_selected_candidate_limit,
            )
            route_result_summaries.append(
                {
                    "candidate": candidate,
                    "ok": payload.get("ok"),
                    "result_count": payload.get("result_count"),
                    "selected_result_count": len(selected_hits),
                    "candidate_window_truncated": candidate_window_truncated,
                    "requested_per_route_limit": per_route_limit,
                    "fetch_limit": route_fetch_limit,
                    "diagnostics": payload.get("diagnostics", []),
                }
            )
            if not payload.get("ok"):
                diagnostics.extend(str(item) for item in payload.get("diagnostics", []))
                continue
            for hit in selected_hits:
                merge_usage_hit(merged, hit, matched_route)

    if normalized_kind == "skill" and usage_role_fast_path_supported:
        skill_dispatch_fast_path_applied = True
        dispatch_doc_ids_before = set(merged)
        for dispatch_role in ("outcome", "entrypoint"):
            for candidate in skill_dispatch_query_candidates:
                route_signal_value = str(candidate.get("route_signal") or "")
                route_layer_value = str(candidate.get("layer") or "") if not route_signal_value else None
                matched_route = route_signal_value or f"{candidate.get('layer')}:*"
                entity_dispatch_probe = str(candidate.get("layer") or "") == "entity"
                if entity_dispatch_probe:
                    skill_dispatch_entity_probe_applied = True
                payload = search_sessions(
                    aoa_root=aoa_root,
                    query="",
                    limit=route_upstream_request_limit,
                    provider=provider,
                    session=session,
                    event_id_before=before_event_id,
                    doc_type="event",
                    route_layer=route_layer_value,
                    route_signal=route_signal_value or None,
                    usage_role=dispatch_role,
                    explain=True,
                    semantic_preview=False,
                    hydrate_body=False,
                )
                dispatch_hits, candidate_window_truncated = bounded_route_results(
                    payload,
                    selected_limit=route_selected_candidate_limit,
                    usage_role_filter=dispatch_role,
                )
                route_result_summaries.append(
                    {
                        "candidate": candidate,
                        "ok": payload.get("ok"),
                        "result_count": payload.get("result_count"),
                        "selected_result_count": len(dispatch_hits),
                        "candidate_window_truncated": candidate_window_truncated,
                        "requested_per_route_limit": per_route_limit,
                        "fetch_limit": route_fetch_limit,
                        "usage_role_filter": dispatch_role,
                        "dispatch_candidate_probe": True,
                        "dispatch_entity_probe": entity_dispatch_probe,
                        "diagnostics": payload.get("diagnostics", []),
                    }
                )
                if not payload.get("ok"):
                    diagnostics.extend(str(item) for item in payload.get("diagnostics", []))
                    continue
                if not entity_dispatch_probe:
                    for hit in dispatch_hits:
                        merge_usage_hit(merged, hit, matched_route)
                    continue
                skill_dispatch_entity_probe_result_count += len(dispatch_hits)
                dispatch_candidates: list[tuple[dict[str, Any], dict[str, Any], str]] = []
                for hit in dispatch_hits:
                    event = compact_usage_event_from_search_hit(hit)
                    state = effective_skill_evidence_state_for_event(
                        event,
                        anchor=anchor,
                    )
                    if state not in SKILL_DISPATCH_CANDIDATE_STATES:
                        skill_dispatch_entity_probe_rejected_non_dispatch_count += 1
                        continue
                    dispatch_candidates.append((hit, event, state))
                canonical_dispatch_candidates = [
                    item
                    for item in dispatch_candidates
                    if str(item[0].get("agent_event_source") or "") == "response_item"
                ]
                for hit, event, state in dispatch_candidates:
                    raw_line = line_from_raw_ref(
                        str((event.get("refs") or {}).get("raw") or "")
                        if isinstance(event.get("refs"), dict)
                        else ""
                    )
                    is_stream_mirror = bool(
                        str(hit.get("agent_event_source") or "") == "event_msg_stream"
                        and raw_line > 0
                        and any(
                            canonical_state == state
                            and canonical_event.get("session_id") == event.get("session_id")
                            and abs(
                                line_from_raw_ref(
                                    str((canonical_event.get("refs") or {}).get("raw") or "")
                                    if isinstance(canonical_event.get("refs"), dict)
                                    else ""
                                )
                                - raw_line
                            )
                            <= 2
                            for _canonical_hit, canonical_event, canonical_state in canonical_dispatch_candidates
                        )
                    )
                    if is_stream_mirror:
                        skill_dispatch_entity_probe_mirror_rejected_count += 1
                        continue
                    merge_usage_hit(merged, hit, matched_route)
                    skill_dispatch_entity_probe_accepted_count += 1
        skill_dispatch_fast_path_hit_count = len(set(merged) - dispatch_doc_ids_before)

    route_hit_count, route_usage_hit_count, route_evidence_hit_count = merged_route_counts()
    if (
        normalized_kind in ENTITY_USAGE_EXECUTION_ADMISSION_KINDS
        and not any(
            entity_usage_event_is_execution_inspection_read(
                compact_usage_event_from_search_hit(hit)
            )
            for hit in merged.values()
        )
    ):
        exact_inspection_candidate = next(
            (
                candidate
                for candidate in query_candidates
                if str(candidate.get("layer") or "") == normalized_kind
                and str(candidate.get("route_signal") or "")
            ),
            None,
        )
        if exact_inspection_candidate is not None:
            execution_inspection_probe_applied = True
            route_signal_value = str(
                exact_inspection_candidate.get("route_signal") or ""
            )
            payload = search_sessions(
                aoa_root=aoa_root,
                query="",
                limit=1,
                provider=provider,
                session=session,
                event_id_before=before_event_id,
                doc_type="event",
                event_type="FILE_READ",
                usage_role="usage",
                route_signal=route_signal_value,
                explain=True,
                semantic_preview=False,
                hydrate_body=False,
            )
            inspection_hits, candidate_window_truncated = bounded_route_results(
                payload,
                selected_limit=1,
                usage_role_filter="usage",
            )
            execution_inspection_probe_result_count = int_value(
                payload.get("result_count")
            )
            execution_inspection_probe_selected_count = len(inspection_hits)
            route_result_summaries.append(
                {
                    "candidate": exact_inspection_candidate,
                    "ok": payload.get("ok"),
                    "result_count": payload.get("result_count"),
                    "selected_result_count": len(inspection_hits),
                    "candidate_window_truncated": candidate_window_truncated,
                    "requested_per_route_limit": per_route_limit,
                    "fetch_limit": 1,
                    "usage_role_filter": "usage",
                    "event_type_filter": "FILE_READ",
                    "inspection_action_probe": True,
                    "diagnostics": payload.get("diagnostics", []),
                }
            )
            if payload.get("ok"):
                for hit in inspection_hits:
                    merge_usage_hit(merged, hit, route_signal_value)
                (
                    route_hit_count,
                    route_usage_hit_count,
                    route_evidence_hit_count,
                ) = merged_route_counts()
            else:
                diagnostics.extend(
                    str(item)
                    for item in payload.get("diagnostics", [])
                    if item
                )
    route_usage_retry_applied = False
    route_usage_retry_fetch_limit = 0
    if (
        lookup_candidates
        and not exact_instance_mode
        and route_hit_count > 0
        and route_usage_hit_count == 0
        and normalized_kind != "skill"
        and normalized_kind in ENTITY_USAGE_DIRECT_TRACE_KINDS
        and route_fetch_limit < 100
    ):
        route_usage_retry_fetch_limit = 100
        if route_usage_retry_fetch_limit > route_fetch_limit:
            route_usage_retry_applied = True
            for candidate in query_candidates:
                route_signal_value = str(candidate.get("route_signal") or "")
                route_layer_value = str(candidate.get("layer") or "") if not route_signal_value else None
                matched_route = route_signal_value or f"{candidate.get('layer')}:*"
                payload = search_sessions(
                    aoa_root=aoa_root,
                    query="",
                    limit=(route_usage_retry_fetch_limit + 1 if session else route_usage_retry_fetch_limit),
                    provider=provider,
                    session=session,
                    event_id_before=before_event_id,
                    doc_type="event",
                    route_layer=route_layer_value,
                    route_signal=route_signal_value or None,
                    explain=True,
                    semantic_preview=False,
                    hydrate_body=False,
                )
                selected_hits, candidate_window_truncated = bounded_route_results(
                    payload,
                    selected_limit=(
                        route_usage_retry_fetch_limit
                        if session
                        else max(1, route_usage_retry_fetch_limit - 1)
                    ),
                )
                route_result_summaries.append(
                    {
                        "candidate": candidate,
                        "ok": payload.get("ok"),
                        "result_count": payload.get("result_count"),
                        "selected_result_count": len(selected_hits),
                        "candidate_window_truncated": candidate_window_truncated,
                        "requested_per_route_limit": per_route_limit,
                        "fetch_limit": route_usage_retry_fetch_limit,
                        "retry_reason": "direct_usage_not_found_in_initial_route_window",
                        "diagnostics": payload.get("diagnostics", []),
                    }
                )
                if not payload.get("ok"):
                    diagnostics.extend(str(item) for item in payload.get("diagnostics", []))
                    continue
                for hit in selected_hits:
                    merge_usage_hit(merged, hit, matched_route)
            route_hit_count = len(merged)
            route_usage_hit_count = sum(
                1
                for hit in merged.values()
                if compact_usage_event_from_search_hit(hit).get("role") == "usage"
            )
            route_evidence_hit_count = sum(
                1
                for hit in merged.values()
                if compact_usage_event_from_search_hit(hit).get("role") != "context"
            )
    text_search_skipped = False
    text_search_skip_reason = ""
    skip_text_search = exact_instance_mode or (
        bool(diagnostics) and not lookup_candidates
    )
    if skip_text_search:
        text_search_skip_reason = (
            "exact_correlation_source_probe_selected"
            if exact_instance_mode
            else "identity_diagnostic_without_route_candidates"
        )
    route_evidence_satisfies_kind = route_usage_hit_count > 0 or (
        normalized_kind not in ENTITY_USAGE_DIRECT_TRACE_KINDS and route_evidence_hit_count > 0
    )
    skill_route_state_counts: Counter[str] = Counter()
    if normalized_kind == "skill":
        for route_hit in merged.values():
            route_event = compact_usage_event_from_search_hit(route_hit)
            skill_route_state_counts[
                effective_skill_evidence_state_for_event(
                    route_event,
                    anchor=anchor,
                )
            ] += 1
    skill_route_dispatch_candidate_present = any(
        skill_route_state_counts.get(state, 0) > 0
        for state in SKILL_DISPATCH_CANDIDATE_STATES
    )
    skill_prompt_visibility = {}
    if normalized_kind == "skill" and session and not exact_instance_mode:
        skill_prompt_visibility = skill_prompt_visibility_probe(
            aoa_root=aoa_root,
            anchor=anchor,
            session=session,
        )
        prompt_visibility_hits = skill_prompt_visibility.pop("_hits", [])
        for prompt_visibility_hit in (
            prompt_visibility_hits
            if isinstance(prompt_visibility_hits, list)
            else []
        ):
            if isinstance(prompt_visibility_hit, dict):
                merge_usage_hit(
                    merged,
                    prompt_visibility_hit,
                    "prompt_visibility_probe",
                )
    elif normalized_kind == "skill" and not exact_instance_mode:
        skill_prompt_visibility = skill_prompt_visibility_probe(
            aoa_root=aoa_root,
            anchor=anchor,
            session=None,
        )
    if isinstance(skill_prompt_visibility, dict):
        skill_prompt_visibility.pop("_hits", None)
    skill_text_fallback_deferred = False
    if (
        not skip_text_search
        and lookup_candidates
        and normalized_kind == "skill"
        and skill_route_dispatch_candidate_present
    ):
        skip_text_search = True
        text_search_skipped = True
        text_search_skip_reason = "skill_dispatch_candidate_route_sufficient"
    elif (
        not skip_text_search
        and normalized_kind == "skill"
        and lookup_candidates
        and skill_dispatch_fast_path_applied
    ):
        skip_text_search = True
        text_search_skipped = True
        skill_text_fallback_deferred = True
        text_search_skip_reason = "skill_dispatch_route_exhausted_text_fallback_deferred"
    elif (
        not skip_text_search
        and lookup_candidates
        and normalized_kind != "skill"
        and normalized_kind in ENTITY_USAGE_DIRECT_TRACE_KINDS
        and route_usage_hit_count > 0
    ):
        skip_text_search = True
        text_search_skipped = True
        text_search_skip_reason = "direct_usage_route_sufficient"
    elif (
        not skip_text_search
        and lookup_candidates
        and normalized_kind != "skill"
        and route_hit_count >= limit
        and route_evidence_satisfies_kind
    ):
        skip_text_search = True
        text_search_skipped = True
        text_search_skip_reason = "route_evidence_window_sufficient"
    text_result_count = 0
    if not skip_text_search:
        text_roles: tuple[str | None, ...] = (
            ("outcome", "entrypoint")
            if normalized_kind == "skill"
            else (None,)
        )
        for text_role in text_roles:
            text_payload = search_sessions(
                aoa_root=aoa_root,
                query=anchor,
                limit=route_upstream_request_limit,
                provider=provider,
                session=session,
                event_id_before=before_event_id,
                doc_type="event",
                usage_role=text_role,
                explain=True,
                semantic_preview=False,
                hydrate_body=False,
            )
            text_result_count += int_value(text_payload.get("result_count"))
            if text_payload.get("ok"):
                selected_hits, _candidate_window_truncated = bounded_route_results(
                    text_payload,
                    selected_limit=route_selected_candidate_limit,
                    usage_role_filter=text_role,
                )
                for hit in selected_hits:
                    merge_usage_hit(merged, hit, "text")
            elif text_payload.get("diagnostics"):
                upstream_candidate_window_incomplete = True
                upstream_query_failure_count += 1
                upstream_query_failure_diagnostics.extend(
                    str(item)
                    for item in text_payload.get("diagnostics", [])
                    if item
                )
                diagnostics.extend(str(item) for item in text_payload.get("diagnostics", []))

    apply_mcp_tool_usage_invocation_admission()
    apply_tool_usage_invocation_admission()
    apply_mcp_usage_invocation_admission()
    apply_hook_usage_invocation_admission()
    apply_execution_usage_invocation_admission()

    def usage_audit_sort_key(item: tuple[dict[str, Any], dict[str, Any], int]) -> tuple[int, ...]:
        hit, event, original_index = item
        base_key = entity_usage_hit_sort_key(hit, event, original_index)
        if normalized_kind != "skill":
            return base_key
        state = effective_skill_evidence_state_for_event(
            event,
            anchor=anchor,
        )
        return (SKILL_EVIDENCE_STATE_PRIORITY.get(state, 99), *base_key)

    ranked_pairs = sorted(
        (
            (hit, compact_usage_event_from_search_hit(hit), original_index)
            for original_index, hit in enumerate(merged.values())
        ),
        key=usage_audit_sort_key,
    )
    selected_ranked_pairs = list(ranked_pairs[:limit])
    hits = [hit for hit, _event, _original_index in selected_ranked_pairs]
    events = [event for _hit, event, _original_index in selected_ranked_pairs]
    segment_cache: dict[str, list[dict[str, Any]]] = {}
    selected_usage_correlations: set[tuple[str, str]] = set()
    for hit, event in zip(hits, events):
        if event.get("role") != "usage":
            continue
        source_event = segment_event_for_hit(hit, segment_cache=segment_cache)
        source_correlation = str(source_event.get("correlation_id") or event.get("correlation_id") or "")
        if source_correlation:
            event["correlation_id"] = source_correlation
            selected_usage_correlations.add(
                (
                    str(event.get("session_id") or event.get("session_label") or ""),
                    source_correlation,
                )
            )
    direct_result_correlation_candidate_count = 0
    direct_result_correlation_owned_count = 0
    direct_result_correlation_rejected_count = 0
    direct_result_correlation_unverifiable_count = 0
    for hit, event in zip(hits, events):
        if event.get("role") != "result":
            continue
        event_type = str(event.get("event_type") or "").upper()
        if event_type not in {"TOOL_OUTPUT", "COMMAND_OUTPUT", "HOOK_EVENT"}:
            continue
        direct_result_correlation_candidate_count += 1
        source_event = segment_event_for_hit(hit, segment_cache=segment_cache)
        result_correlation = str(source_event.get("correlation_id") or event.get("correlation_id") or "")
        if not result_correlation:
            direct_result_correlation_unverifiable_count += 1
            event["result_admission"] = "correlation_unverifiable"
            continue
        event["correlation_id"] = result_correlation
        correlation_key = (
            str(event.get("session_id") or event.get("session_label") or ""),
            result_correlation,
        )
        if correlation_key in selected_usage_correlations:
            direct_result_correlation_owned_count += 1
            event["result_admission"] = "correlation_owned"
            continue
        direct_result_correlation_rejected_count += 1
        event["role"] = "context"
        event["relation"] = "route_result_correlation_rejected"
        event["result_admission"] = "rejected_missing_selected_usage_correlation"
    # Result ownership is part of the effective role.  Apply the bounded
    # action-diversity sample only after foreign result candidates have been
    # demoted to context, so one of those noise slots may be replaced without
    # displacing a true usage or owned result.
    selected_ranked_pairs, action_diversity = entity_usage_action_diverse_selection(
        ranked_pairs,
        normalized_kind=normalized_kind,
        limit=limit,
    )
    hits = [hit for hit, _event, _original_index in selected_ranked_pairs]
    events = [event for _hit, event, _original_index in selected_ranked_pairs]
    if normalized_kind == "skill":
        for event in events:
            skill_state = effective_skill_evidence_state_for_event(
                event,
                anchor=anchor,
            )
            event["skill_evidence_state"] = skill_state
            if skill_state in SKILL_CONTEXT_ONLY_STATES:
                event["role"] = "context"
    entrypoint_events = [event for event in events if event.get("role") == "entrypoint"]
    usage_events = [event for event in events if event.get("role") == "usage"]
    intrinsic_result_usage_events = [
        event
        for event in usage_events
        if str(event.get("execution_entity_usage_admission") or "")
        == "structured_result_invocation_proven"
    ]
    result_events = [event for event in events if event.get("role") == "result"]
    outcome_events = [event for event in events if event.get("role") == "outcome"]
    context_events = [event for event in events if event.get("role") == "context"]
    manifest_cache: dict[str, dict[str, Any]] = {}
    raw_preview_cache: dict[tuple[str, str, str, int], dict[str, Any]] = {}
    consequence_events: list[dict[str, Any]] = []
    seen_consequences: set[tuple[str, str]] = set()
    false_correlation_events: list[dict[str, Any]] = []
    seen_false_correlations: set[tuple[str, str]] = set()
    async_diagnostics: dict[str, int] = {
        key: 0 for key in ENTITY_USAGE_ASYNC_DIAGNOSTIC_KEYS
    }
    causal_diagnostics: dict[str, int] = {
        key: 0 for key in ENTITY_USAGE_CAUSAL_DIAGNOSTIC_KEYS
    }
    for hit, event in zip(hits, events):
        if event.get("role") != "usage":
            continue
        if (
            str(event.get("execution_entity_usage_admission") or "")
            == "structured_result_invocation_proven"
        ):
            # The raw runner output is already the invocation and its result
            # evidence.  Following later transcript events from this point
            # would manufacture foreign consequence edges.
            continue
        rejected_for_hit: list[dict[str, Any]] = []
        for consequence in consequence_events_for_usage_hit(
            hit,
            window=consequence_window,
            segment_cache=segment_cache,
            false_correlation_events=rejected_for_hit,
            manifest_cache=manifest_cache,
            raw_preview_cache=raw_preview_cache,
            async_diagnostics=async_diagnostics,
            causal_diagnostics=causal_diagnostics,
        ):
            consequence_id = str(consequence.get("doc_id") or "")
            source_doc_id = str(consequence.get("source_doc_id") or hit.get("doc_id") or "")
            consequence_edge = (source_doc_id, consequence_id)
            if consequence_id and consequence_edge in seen_consequences:
                continue
            if consequence_id:
                seen_consequences.add(consequence_edge)
            if normalized_kind == "skill":
                consequence["skill_evidence_state"] = skill_evidence_state_for_event(
                    consequence,
                    anchor=anchor,
                )
            consequence_events.append(consequence)
        for rejected in rejected_for_hit:
            rejected_key = (
                str(rejected.get("source_doc_id") or ""),
                str(rejected.get("doc_id") or rejected.get("event_id") or ""),
            )
            if rejected_key in seen_false_correlations:
                continue
            seen_false_correlations.add(rejected_key)
            if normalized_kind == "skill":
                rejected["skill_evidence_state"] = "false_correlation"
            false_correlation_events.append(rejected)
    skill_receipt_inventory = (
        load_skill_usage_receipts(
            aoa_root=aoa_root,
            anchor=anchor,
            session=session,
        )
        if normalized_kind == "skill"
        else {}
    )
    skill_evidence = (
        skill_evidence_summary(
            [*events, *consequence_events],
            anchor=anchor,
            false_correlation_events=false_correlation_events,
            reviewed_receipts=(
                skill_receipt_inventory.get("receipts", [])
                if isinstance(skill_receipt_inventory, dict)
                and isinstance(skill_receipt_inventory.get("receipts"), list)
                else []
            ),
            receipt_diagnostics=(
                skill_receipt_inventory.get("diagnostics", [])
                if isinstance(skill_receipt_inventory, dict)
                and isinstance(
                    skill_receipt_inventory.get("diagnostics"), list
                )
                else []
            ),
        )
        if normalized_kind == "skill"
        else {}
    )
    if normalized_kind == "skill" and isinstance(skill_evidence, dict):
        skill_evidence["query_time_source_probe"] = (
            skill_query_time_source_probe
        )
        state_ingestion = (
            skill_evidence.get("state_ingestion")
            if isinstance(skill_evidence.get("state_ingestion"), dict)
            else {}
        )
        state_ingestion["selected"] = {
            "available": True,
            "mode": (
                "session_scoped_query_time_raw_exact_selection_probe"
            ),
            "claim_boundary": (
                "selection_candidate_only_not_load_invocation_or_effect"
            ),
        }
        state_ingestion["skill_read"] = {
            "available": True,
            "mode": (
                "session_scoped_query_time_raw_skill_artifact_read_"
                "with_correlation_owned_result"
            ),
            "claim_boundary": (
                "artifact_read_only_not_procedure_invocation_or_effect"
            ),
        }
        skill_evidence["state_ingestion"] = state_ingestion
    accepted_event_associations = [
        *usage_events,
        *result_events,
        *outcome_events,
        *entrypoint_events,
        *context_events,
        *consequence_events,
    ]
    accepted_events_for_docs = unique_entity_usage_events(accepted_event_associations)
    unique_false_correlation_event_count = len(unique_entity_usage_events(false_correlation_events))
    freshness_counts = entity_usage_freshness_counts(accepted_events_for_docs)
    false_correlation_freshness_counts = entity_usage_freshness_counts(false_correlation_events)
    document_refs = entity_usage_document_refs(
        accepted_events_for_docs,
        limit=document_limit,
        manifest_cache=manifest_cache,
        raw_preview_cache=raw_preview_cache,
    )
    sessions = entity_usage_sessions_summary(accepted_events_for_docs)
    provider_status = search_provider_status_fast(aoa_root=aoa_root, provider_name=provider)
    provider_payload = provider_status.get("providers", {}).get(provider) if isinstance(provider_status.get("providers"), dict) else {}
    generic_direct_event_present = bool(usage_events)
    materialized_candidate_event_count = len(ranked_pairs)
    materialized_candidate_usage_event_count = sum(
        1 for _hit, event, _original_index in ranked_pairs if event.get("role") == "usage"
    )
    candidate_event_count = materialized_candidate_event_count + int(upstream_candidate_window_truncated)
    candidate_usage_event_count = (
        materialized_candidate_usage_event_count + int(upstream_usage_candidate_window_truncated)
    )
    selected_event_count = len(events)
    selected_usage_event_count = len(usage_events)
    omitted_event_count = max(0, candidate_event_count - selected_event_count)
    omitted_usage_event_count = max(0, candidate_usage_event_count - selected_usage_event_count)
    candidate_window_truncated = bool(
        upstream_candidate_window_truncated
        or materialized_candidate_event_count > selected_event_count
    )
    selected_numeric_event_ids = [
        str(event.get("event_id") or "")
        for event in events
        if str(event.get("event_id") or "").isdigit()
    ]
    next_before_event_id = (
        min(selected_numeric_event_ids, key=lambda value: int(value))
        if session and candidate_window_truncated and selected_numeric_event_ids
        else ""
    )
    quality = {
        "direct_usage_present": generic_direct_event_present,
        "generic_direct_event_present": generic_direct_event_present,
        "skill_behavioral_candidate_present": (
            bool(skill_evidence.get("behavioral_candidate_present"))
            if normalized_kind == "skill"
            else None
        ),
        "skill_dispatch_candidate_present": (
            bool(skill_evidence.get("dispatch_candidate_present"))
            if normalized_kind == "skill"
            else None
        ),
        "skill_invocation_claim_allowed": (
            bool(skill_evidence.get("invocation_claim_allowed"))
            if normalized_kind == "skill"
            else None
        ),
        "skill_prompt_visibility_probe": (
            skill_prompt_visibility
            if normalized_kind == "skill"
            else {}
        ),
        "skill_query_time_source_probe": (
            skill_query_time_source_probe
            if normalized_kind == "skill"
            else {}
        ),
        "skill_query_time_source_hit_count": (
            len(skill_query_time_source_hits)
            if normalized_kind == "skill"
            else 0
        ),
        "direct_result_correlation_candidate_count": direct_result_correlation_candidate_count,
        "direct_result_correlation_owned_count": direct_result_correlation_owned_count,
        "direct_result_correlation_rejected_count": direct_result_correlation_rejected_count,
        "direct_result_correlation_unverifiable_count": direct_result_correlation_unverifiable_count,
        "async_continuation": dict(async_diagnostics),
        "causal_admission": dict(causal_diagnostics),
        "consequence_present": bool(
            consequence_events
            or result_events
            or outcome_events
            or intrinsic_result_usage_events
        ),
        "intrinsic_result_usage_event_count": len(
            intrinsic_result_usage_events
        ),
        "false_correlation_event_present": bool(false_correlation_events),
        "false_correlation_edge_count": len(false_correlation_events),
        "unique_false_correlation_event_count": (
            unique_false_correlation_event_count
        ),
        "accepted_event_association_count": len(accepted_event_associations),
        "unique_accepted_event_count": len(accepted_events_for_docs),
        "duplicate_accepted_event_association_count": len(accepted_event_associations) - len(accepted_events_for_docs),
        "document_refs_present": bool(document_refs),
        "route_candidate_count": len(lookup_candidates),
        "queried_route_candidate_count": len(query_candidates),
        "route_result_count": len(hits),
        "requested_per_route_limit": per_route_limit,
        "route_fetch_limit": route_fetch_limit,
        "route_candidate_limit": route_candidate_limit,
        "route_upstream_request_limit": route_upstream_request_limit,
        "route_selected_candidate_limit": route_selected_candidate_limit,
        "candidate_event_count": candidate_event_count,
        "materialized_candidate_event_count": materialized_candidate_event_count,
        "selected_event_count": selected_event_count,
        "omitted_event_count": omitted_event_count,
        "candidate_window_truncated": candidate_window_truncated,
        "candidate_window_incomplete": upstream_candidate_window_incomplete,
        "candidate_count_exhaustive": bool(
            not upstream_candidate_window_truncated
            and not upstream_candidate_window_incomplete
        ),
        "candidate_count_basis": (
            "exact_session_correlation_source_scan"
            if exact_instance_mode
            and exact_correlation_probe.get(
                "candidate_count_exhaustive"
            )
            else
            "incomplete_upstream_query"
            if upstream_candidate_window_incomplete
            else "lower_bound_upstream_probe"
            if upstream_candidate_window_truncated
            else "exact_materialized_candidate_pool"
        ),
        "upstream_candidate_window_truncated": upstream_candidate_window_truncated,
        "upstream_candidate_window_incomplete": upstream_candidate_window_incomplete,
        "upstream_query_failure_count": upstream_query_failure_count,
        "upstream_query_failure_diagnostics": list(
            dict.fromkeys(upstream_query_failure_diagnostics)
        ),
        "candidate_usage_event_count": candidate_usage_event_count,
        "materialized_candidate_usage_event_count": materialized_candidate_usage_event_count,
        "selected_usage_event_count": selected_usage_event_count,
        "omitted_usage_event_count": omitted_usage_event_count,
        "before_event_id": str(before_event_id or ""),
        "next_before_event_id": next_before_event_id,
        "exact_instance_mode": exact_instance_mode,
        "exact_correlation_id": normalized_correlation_id,
        "exact_correlation_probe": exact_correlation_probe,
        "exact_correlation_source_hit_count": len(
            exact_correlation_hits
        ),
        "text_result_count": text_result_count,
        "text_search_skipped": text_search_skipped,
        "text_search_skip_reason": text_search_skip_reason,
        "route_hit_count_before_text_fallback": route_hit_count,
        "route_usage_hit_count_before_text_fallback": route_usage_hit_count,
        "route_evidence_hit_count_before_text_fallback": route_evidence_hit_count,
        "skill_route_state_counts_before_text_fallback": dict(sorted(skill_route_state_counts.items())),
        "skill_route_dispatch_candidate_present_before_text_fallback": skill_route_dispatch_candidate_present,
        "skill_text_fallback_deferred": skill_text_fallback_deferred,
        "route_usage_retry_applied": route_usage_retry_applied,
        "route_usage_retry_fetch_limit": route_usage_retry_fetch_limit,
        "broad_route_retry_applied": route_usage_retry_applied,
        "broad_route_search_fully_skipped": broad_route_search_skipped and not route_usage_retry_applied,
        "usage_role_fast_path_supported": usage_role_fast_path_supported,
        "usage_role_fast_path_applied": usage_role_fast_path_applied,
        "usage_role_fast_path_fetch_limit": usage_role_fast_path_fetch_limit,
        "usage_role_fast_path_hit_count": usage_role_fast_path_hit_count,
        "usage_role_fast_path_usage_hit_count": usage_role_fast_path_usage_hit_count,
        "usage_role_fast_path_broad_route_search_skipped": broad_route_search_skipped,
        "mcp_usage_invocation_admission_applied": bool(
            normalized_kind == "mcp" and requested_mcp_route_keys
        ),
        "mcp_usage_requested_service_keys": sorted(
            requested_mcp_route_keys
        ),
        "mcp_usage_anchor_service_key": mcp_anchor_service_key or "",
        "mcp_usage_anchor_service_resolution": (
            "route_candidate"
            if mcp_anchor_service_key in route_candidate_mcp_keys
            else "tool_name_to_service"
            if mcp_anchor_service_key
            else "unresolved"
            if normalized_kind == "mcp"
            else "not_requested"
        ),
        "mcp_usage_invocation_admitted_count": mcp_usage_invocation_admitted_count,
        "mcp_usage_mention_only_rejected_count": mcp_usage_mention_only_rejected_count,
        "mcp_usage_invocation_unverifiable_count": mcp_usage_invocation_unverifiable_count,
        "mcp_tool_usage_invocation_admission_applied": (
            requested_kind == "mcp_tool"
        ),
        "mcp_tool_identity_status": (
            mcp_tool_resolution.get("status")
            if requested_kind == "mcp_tool"
            else "not_requested"
        ),
        "mcp_tool_identity_resolution_source": (
            mcp_tool_resolution.get("resolution_source")
            if requested_kind == "mcp_tool"
            else ""
        ),
        "mcp_tool_identity_count": (
            int_value(mcp_tool_resolution.get("identity_count"))
            if requested_kind == "mcp_tool"
            else 0
        ),
        "mcp_tool_requested_route_keys": sorted(
            requested_mcp_tool_route_keys
        ),
        "mcp_tool_requested_service_keys": sorted(
            requested_mcp_tool_service_keys
        ),
        "mcp_tool_requested_tool_keys": sorted(
            requested_mcp_tool_keys
        ),
        "mcp_tool_invocation_admitted_count": (
            mcp_tool_invocation_admitted_count
        ),
        "mcp_tool_mention_only_rejected_count": (
            mcp_tool_mention_only_rejected_count
        ),
        "mcp_tool_invocation_unverifiable_count": (
            mcp_tool_invocation_unverifiable_count
        ),
        "mcp_tool_query_time_source_hit_count": (
            len(mcp_tool_query_time_source_hits)
            if requested_kind == "mcp_tool"
            else 0
        ),
        "mcp_tool_resolution": (
            mcp_tool_resolution
            if requested_kind == "mcp_tool"
            else {}
        ),
        "tool_usage_invocation_admission_applied": bool(
            normalized_kind == "tool"
            and requested_kind != "mcp_tool"
            and requested_tool_route_keys
        ),
        "tool_usage_invocation_admission_scope": (
            "all_candidates_structured_identity_or_raw_nested_invocation"
            if (
                normalized_kind == "tool"
                and requested_kind != "mcp_tool"
                and requested_tool_route_keys
            )
            else "not_requested"
        ),
        "tool_usage_requested_keys": sorted(requested_tool_route_keys),
        "tool_usage_invocation_admitted_count": (
            tool_usage_invocation_admitted_count
        ),
        "tool_usage_mention_only_rejected_count": (
            tool_usage_mention_only_rejected_count
        ),
        "tool_usage_invocation_unverifiable_count": (
            tool_usage_invocation_unverifiable_count
        ),
        "hook_usage_invocation_admission_applied": normalized_kind == "hook",
        "hook_usage_invocation_admitted_count": hook_usage_invocation_admitted_count,
        "hook_usage_command_invocation_admitted_count": (
            hook_usage_command_invocation_admitted_count
        ),
        "hook_usage_session_activity_rejected_count": hook_usage_session_activity_rejected_count,
        "hook_usage_invocation_unverifiable_count": hook_usage_invocation_unverifiable_count,
        "execution_usage_invocation_admission_applied": (
            normalized_kind in ENTITY_USAGE_EXECUTION_ADMISSION_KINDS
        ),
        "execution_usage_invocation_admission_kind": (
            normalized_kind
            if normalized_kind in ENTITY_USAGE_EXECUTION_ADMISSION_KINDS
            else ""
        ),
        "execution_usage_invocation_admitted_count": execution_usage_invocation_admitted_count,
        "execution_usage_reference_rejected_count": execution_usage_reference_rejected_count,
        "execution_usage_prelaunch_failure_rejected_count": (
            execution_usage_prelaunch_failure_rejected_count
        ),
        "execution_usage_invocation_unverifiable_count": execution_usage_invocation_unverifiable_count,
        "execution_usage_structured_result_candidate_count": execution_usage_structured_result_candidate_count,
        "execution_usage_structured_result_admitted_count": execution_usage_structured_result_admitted_count,
        "execution_usage_structured_result_parent_rejected_count": execution_usage_structured_result_parent_rejected_count,
        "execution_usage_structured_result_parent_unverifiable_count": execution_usage_structured_result_parent_unverifiable_count,
        "execution_inspection_probe_applied": execution_inspection_probe_applied,
        "execution_inspection_probe_result_count": execution_inspection_probe_result_count,
        "execution_inspection_probe_selected_count": execution_inspection_probe_selected_count,
        "action_diversity": action_diversity,
        "skill_dispatch_fast_path_applied": skill_dispatch_fast_path_applied,
        "skill_dispatch_fast_path_hit_count": skill_dispatch_fast_path_hit_count,
        "skill_dispatch_entity_probe_applied": skill_dispatch_entity_probe_applied,
        "skill_dispatch_entity_probe_candidate_count": (
            len(skill_dispatch_query_candidates) - len(query_candidates)
            if normalized_kind == "skill"
            else 0
        ),
        "skill_dispatch_entity_probe_result_count": skill_dispatch_entity_probe_result_count,
        "skill_dispatch_entity_probe_accepted_count": skill_dispatch_entity_probe_accepted_count,
        "skill_dispatch_entity_probe_rejected_non_dispatch_count": skill_dispatch_entity_probe_rejected_non_dispatch_count,
        "skill_dispatch_entity_probe_mirror_rejected_count": skill_dispatch_entity_probe_mirror_rejected_count,
        "search_route_index_count": provider_payload.get("route_index_count") if isinstance(provider_payload, dict) else None,
        "search_route_term_count": provider_payload.get("route_term_count") if isinstance(provider_payload, dict) else None,
        "search_has_route_index": bool(
            provider_payload.get("has_route_index")
            if isinstance(provider_payload, dict) and provider_payload.get("has_route_index") is not None
            else int_value(provider_payload.get("route_index_count") if isinstance(provider_payload, dict) else 0) > 0
        ),
        "search_has_route_terms": bool(
            provider_payload.get("has_route_terms")
            if isinstance(provider_payload, dict) and provider_payload.get("has_route_terms") is not None
            else int_value(provider_payload.get("route_term_count") if isinstance(provider_payload, dict) else 0) > 0
        ),
        "freshness_counts": freshness_counts,
        "false_correlation_freshness_counts": false_correlation_freshness_counts,
        "fresh_event_count": int_value(freshness_counts.get("fresh")),
        "stale_event_count": int_value(freshness_counts.get("stale")),
        "unverifiable_event_count": int_value(freshness_counts.get("unverifiable")),
    }
    next_page_command = (
        entity_usage_chain_command(
            "entity-usage-audit",
            anchor=anchor,
            kind=normalized_kind,
            aoa_root=aoa_root,
            session=session,
            correlation_id=normalized_correlation_id,
            before_event_id=next_before_event_id,
            limit=limit,
            per_route_limit=per_route_limit,
            extra=["--full"],
        )
        if next_before_event_id
        else ""
    )
    payload = {
        "schema_version": SCHEMA_VERSION,
        "artifact_type": "session_memory_entity_usage_audit",
        "generated_at": now,
        "ok": bool(
            hits
            or (
                normalized_kind == "skill"
                and (
                    skill_evidence.get("invocation_claim_allowed")
                    or skill_evidence.get("deflection_claim_allowed")
                )
            )
        )
        and not any(
            str(item).startswith("unknown_mcp_service_identity:")
            for item in diagnostics
        ),
        "mutates": False,
        "truth_status": "session_memory_entity_usage_routes_to_evidence_not_reviewed_truth",
        "anchor": anchor,
        **trace_kind_payload_fields(kind, normalized_kind),
        "inferred_kinds": infer_trace_route_kinds(anchor, normalized_kind),
        "aliases": trace_anchor_aliases(anchor),
        "session": session or "",
        "correlation_id": normalized_correlation_id,
        "selection_scope": (
            {
                "mode": "exact_session_correlation",
                "session": session or "",
                "correlation_id": normalized_correlation_id,
                "source_probe_status": exact_correlation_probe.get(
                    "status"
                ),
                "candidate_count_exhaustive": bool(
                    exact_correlation_probe.get(
                        "candidate_count_exhaustive"
                    )
                ),
                "absence_claim_allowed": False,
            }
            if exact_instance_mode
            else {
                "mode": "bounded_entity_aggregate",
                "session": session or "",
                "absence_claim_allowed": False,
            }
        ),
        "route_candidates": lookup_candidates,
        "route_result_summaries": route_result_summaries,
        "event_count": len(events),
        "truncated": bool(quality.get("candidate_window_truncated")),
        "incomplete": bool(quality.get("candidate_window_incomplete")),
        "truncation": {
            "status": (
                "incomplete"
                if quality.get("candidate_window_incomplete")
                else "truncated"
                if quality.get("candidate_window_truncated")
                else "complete"
            ),
            "requested_limit": limit,
            "candidate_event_count": int_value(quality.get("candidate_event_count")),
            "selected_event_count": int_value(quality.get("selected_event_count")),
            "omitted_event_count": int_value(quality.get("omitted_event_count")),
            "candidate_usage_event_count": int_value(quality.get("candidate_usage_event_count")),
            "selected_usage_event_count": int_value(quality.get("selected_usage_event_count")),
            "omitted_usage_event_count": int_value(quality.get("omitted_usage_event_count")),
            "candidate_count_exhaustive": bool(quality.get("candidate_count_exhaustive")),
            "candidate_count_basis": str(quality.get("candidate_count_basis") or ""),
            "before_event_id": str(quality.get("before_event_id") or ""),
            "next_before_event_id": str(quality.get("next_before_event_id") or ""),
            "next_page_command": next_page_command,
        },
        "entrypoint_event_count": len(entrypoint_events),
        "usage_event_count": len(usage_events),
        "result_event_count": len(result_events),
        "outcome_event_count": len(outcome_events),
        "context_event_count": len(context_events),
        "consequence_event_count": len(consequence_events),
        "false_correlation_event_count": len(false_correlation_events),
        "false_correlation_edge_count": len(false_correlation_events),
        "unique_false_correlation_event_count": (
            unique_false_correlation_event_count
        ),
        "entrypoint_events": entrypoint_events,
        "usage_events": usage_events,
        "result_events": result_events,
        "outcome_events": outcome_events,
        "context_events": context_events,
        "consequence_events": consequence_events,
        "false_correlation_events": false_correlation_events,
        "async_continuation": dict(async_diagnostics),
        "causal_admission": dict(causal_diagnostics),
        "document_refs": document_refs,
        "sessions": sessions,
        "skill_evidence": skill_evidence,
        "quality": quality,
        "provider": provider_status,
        "diagnostics": diagnostics,
        "next_route": (
            "Continue the same bounded session-local candidate route before the returned event id."
            if next_page_command
            else "Use raw/segment/session refs to verify claims; this packet is an evidence route, not promoted truth."
        ),
        "next_expansion_command": next_page_command,
    }
    if write_report:
        diagnostics_dir = aoa_root / DIAGNOSTICS_ROOT
        diagnostics_dir.mkdir(parents=True, exist_ok=True)
        stem = f"{compact_stamp()}__entity-usage-audit__{route_key_slug(anchor, fallback='anchor', max_chars=80)}"
        report_json = diagnostics_dir / f"{stem}.json"
        report_md = diagnostics_dir / f"{stem}.md"
        write_json(report_json, payload)
        write_markdown(report_md, entity_usage_audit_markdown(payload))
        payload["report_json"] = str(report_json)
        payload["report_markdown"] = str(report_md)
    return payload


def entity_usage_audit_markdown(payload: dict[str, Any]) -> str:
    skill_evidence = payload.get("skill_evidence") if isinstance(payload.get("skill_evidence"), dict) else {}
    lines = [
        "# Entity Usage Audit",
        "",
        f"- generated_at: `{payload.get('generated_at')}`",
        f"- anchor: `{payload.get('anchor')}`",
        f"- kind: `{payload.get('kind')}`",
        f"- ok: `{payload.get('ok')}`",
        f"- usage_events: `{payload.get('usage_event_count')}`",
        f"- consequence_events: `{payload.get('consequence_event_count')}`",
        f"- false_correlation_edges: `{payload.get('false_correlation_edge_count', 0)}`",
        f"- document_refs: `{len(payload.get('document_refs', []) if isinstance(payload.get('document_refs'), list) else [])}`",
    ]
    if skill_evidence:
        lines.extend(
            [
                f"- skill_evidence_schema: `{skill_evidence.get('schema_version')}`",
                f"- skill_candidate_only: `{skill_evidence.get('candidate_only')}`",
                f"- skill_state_counts: `{json.dumps(skill_evidence.get('state_counts', {}), ensure_ascii=False, sort_keys=True)}`",
                f"- skill_behavioral_candidate_present: `{skill_evidence.get('behavioral_candidate_present')}`",
                f"- skill_dispatch_candidate_present: `{skill_evidence.get('dispatch_candidate_present')}`",
                f"- skill_invocation_claim_allowed: `{skill_evidence.get('invocation_claim_allowed')}`",
                f"- skill_invocation_claim_blocker: `{skill_evidence.get('invocation_claim_blocker')}`",
                f"- skill_reviewed_receipt_count: `{skill_evidence.get('reviewed_receipt_count')}`",
                f"- skill_verification_claim_allowed: `{skill_evidence.get('verification_claim_allowed')}`",
                f"- skill_effect_attribution_candidate_present: `{skill_evidence.get('effect_attribution_candidate_present')}`",
                f"- skill_benefit_claim_allowed: `{skill_evidence.get('benefit_claim_allowed')}`",
            ]
        )
    lines.extend(["", "## Usage Events", ""])
    for event in payload.get("usage_events", []) if isinstance(payload.get("usage_events"), list) else []:
        if isinstance(event, dict):
            refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
            lines.append(f"- `{event.get('skill_evidence_state') or ''}` `{event.get('event_type')}` `{event.get('title')}` `{refs.get('raw') or refs.get('segment') or ''}`")
    lines.extend(["", "## Consequences", ""])
    for event in payload.get("consequence_events", []) if isinstance(payload.get("consequence_events"), list) else []:
        if isinstance(event, dict):
            refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
            lines.append(f"- `{event.get('event_type')}` `{event.get('relation')}` `{event.get('title')}` `{refs.get('raw') or refs.get('segment') or ''}`")
    candidate_events = unique_entity_usage_events(
        [
            event
            for bucket in ("entrypoint_events", "result_events", "outcome_events", "context_events")
            for event in (payload.get(bucket, []) if isinstance(payload.get(bucket), list) else [])
            if isinstance(event, dict) and event.get("skill_evidence_state")
        ]
    )
    if candidate_events:
        lines.extend(["", "## Dispatch and Outcome Candidates", ""])
        for event in candidate_events:
            refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
            lines.append(
                f"- `{event.get('skill_evidence_state')}` `{event.get('event_id')}` `{event.get('event_type')}` "
                f"`{event.get('title')}` `{refs.get('raw') or refs.get('segment') or ''}`"
            )
    rejected_events = payload.get("false_correlation_events") if isinstance(payload.get("false_correlation_events"), list) else []
    if rejected_events:
        lines.extend(["", "## Rejected Foreign Correlations", ""])
        for event in rejected_events:
            if not isinstance(event, dict):
                continue
            refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
            lines.append(
                f"- source=`{event.get('source_correlation_id')}` rejected=`{event.get('rejected_correlation_id')}` "
                f"event=`{event.get('event_id')}` ref=`{refs.get('raw') or refs.get('segment') or ''}`"
            )
    docs = payload.get("document_refs") if isinstance(payload.get("document_refs"), list) else []
    if docs:
        lines.extend(["", "## Document Refs", ""])
        for item in docs[:30]:
            if isinstance(item, dict):
                lines.append(f"- `{item.get('kind')}` `{item.get('value')}`")
    diagnostics = payload.get("diagnostics") if isinstance(payload.get("diagnostics"), list) else []
    if diagnostics:
        lines.extend(["", "## Diagnostics", ""])
        for item in diagnostics:
            lines.append(f"- `{item}`")
    return "\n".join(lines) + "\n"


def entity_usage_event_action_semantics(event: dict[str, Any]) -> list[str]:
    event_type = str(event.get("event_type") or "")
    role = str(event.get("role") or "")
    action = str(event.get("action") or "")
    outcome = str(event.get("outcome") or "")
    conversation_act = str(event.get("conversation_act") or "")
    session_act = str(event.get("session_act") or "")
    skill_evidence_state = str(event.get("skill_evidence_state") or "")
    if skill_evidence_state == "false_correlation":
        return ["context"]
    if session_act == "skill_explicit_selection" and not skill_evidence_state:
        return ["selected"]
    haystack = " ".join(
        str(value or "")
        for value in (
            event_type,
            role,
            event.get("family"),
            event.get("phase"),
            action,
            outcome,
            conversation_act,
            session_act,
            event.get("title"),
            event.get("snippet"),
            " ".join(str(item) for item in event.get("matched_routes", []) if item)
            if isinstance(event.get("matched_routes"), list)
            else "",
            " ".join(str(item) for item in event.get("route_signals", []) if item)
            if isinstance(event.get("route_signals"), list)
            else "",
        )
    ).lower()
    actions: list[str] = []
    execution_admission = str(
        event.get("execution_entity_usage_admission") or ""
    )
    execution_kind = str(event.get("execution_entity_usage_kind") or "")
    execution_result_status = str(
        event.get("execution_entity_usage_result_status") or ""
    )
    result_status = str(event.get("result_status") or "")
    if execution_admission == "structured_inspection_read_proven":
        return ["read"]
    if execution_admission == "inspection_or_reference_not_invocation":
        if (
            event_type == "FILE_READ"
            or action in {"read", "inspect_workspace"}
            or session_act == "file_inspection"
        ):
            return ["read"]
        return ["referenced"]
    if execution_admission.startswith("invocation_source_unverifiable"):
        return ["context"]
    if execution_admission == "invocation_prelaunch_failure_observed":
        return ["requested", "failed"]
    if execution_admission == "structured_command_invocation_proven":
        actions = ["called"]
        if execution_kind in {"test", "validator"}:
            actions.append("validated")
        actions.append("invoked")
        if execution_result_status == "failed":
            actions.append("failed")
        return actions

    def add(value: str) -> None:
        if value and value not in actions:
            actions.append(value)

    if result_status == "timed_out":
        add("timed_out")
    if execution_admission == "structured_result_invocation_proven":
        add("called")
        if execution_kind in ENTITY_USAGE_EXECUTION_ADMISSION_KINDS:
            add("validated")
    if skill_evidence_state == "selected":
        add("selected")
    elif skill_evidence_state == "skill_read":
        add("read")
    elif skill_evidence_state in SKILL_NON_PROCEDURE_STATES:
        add(skill_evidence_state)
    if skill_evidence_state in SKILL_NON_PROCEDURE_STATES:
        return actions or ["context"]
    if event_type in {"TOOL_CALL", "COMMAND"} or action in {"call_tool", "run_command"} or session_act in {"tool_call", "command_run", "app_connector_call"}:
        add("called")
    if event_type == "FILE_READ" or action in {"read", "inspect_workspace"} or session_act in {"file_inspection", "memory_read"}:
        add("read")
    if event_type in {"FILE_WRITE", "DIFF"} or action in {"write", "edit", "mutate_workspace"} or session_act in {"file_mutation", "memory_write"}:
        add("edited")
    configuration_target_present = bool(
        "config" in haystack or "configured" in haystack or "settings" in haystack
    )
    configuration_mutation_evidence = bool(
        event_type in {"FILE_WRITE", "DIFF"}
        or action in {"write", "edit", "mutate_workspace"}
        or session_act in {"file_mutation", "memory_write"}
        or (
            role == "usage"
            and event_type in {"COMMAND", "TOOL_CALL"}
            and re.search(
                r"\b(?:configure|configured|set|update|write|edit|apply|install)\b",
                haystack,
            )
        )
    )
    if role == "usage" and configuration_target_present and configuration_mutation_evidence:
        add("configured")
    structured_verification_evidence = bool(
        event_type == "VERIFICATION"
        or "verification" in conversation_act
        or "verification" in session_act
    )
    executable_usage_evidence = bool(
        role == "usage"
        and (
            event_type in {"COMMAND", "TOOL_CALL"}
            or action in {"call_tool", "run_command"}
            or session_act
            in {"tool_call", "command_run", "app_connector_call"}
        )
    )
    if structured_verification_evidence or (
        executable_usage_evidence
        and (
            "validate" in haystack
            or "validator" in haystack
            or "pytest" in haystack
            or "test:" in haystack
        )
    ):
        add("validated")
    if (
        event_type == "ERROR"
        or outcome == "failed"
        or "failure" in conversation_act
        or "error" in session_act
    ):
        add("failed")
    structured_mutation_evidence = bool(
        event_type in {"FILE_WRITE", "DIFF"}
        or action in {"write", "edit", "mutate_workspace"}
        or session_act in {"file_mutation", "memory_write"}
    )
    if (
        structured_mutation_evidence or executable_usage_evidence
    ) and any(
        term in haystack
        for term in ("repair", "repaired", "fix", "fixed", "исправ", "почин")
    ):
        add("repaired")
    if role == "usage" and skill_evidence_state not in SKILL_NON_PROCEDURE_STATES:
        add("invoked")
    elif role in {"result", "outcome", "consequence"} and outcome in {"observed", "succeeded"}:
        add("observed")
    return actions or ["context"]


def entity_usage_chain_event(event: dict[str, Any]) -> dict[str, Any]:
    refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
    task_episode_id = str(event.get("task_episode_id") or "")
    task_episode_ref = str(
        event.get("task_episode_ref")
        or refs.get("task_episode")
        or (
            f"task_episode:{event.get('session_id')}:{task_episode_id}"
            if event.get("session_id") and task_episode_id
            else ""
        )
    )
    route_signals, route_signal_count = compact_usage_route_signals(event.get("route_signals"), limit=8)
    matched_routes = event.get("matched_routes") if isinstance(event.get("matched_routes"), list) else []
    usage_actions = entity_usage_event_action_semantics(event)
    freshness = event.get("freshness") if isinstance(event.get("freshness"), dict) else {}
    return {
        "doc_id": event.get("doc_id"),
        "source": event.get("source"),
        "source_doc_id": event.get("source_doc_id"),
        "distance": event.get("distance"),
        "relation": event.get("relation"),
        "role": event.get("role"),
        "session_id": event.get("session_id"),
        "session_label": event.get("session_label"),
        "session_date": event.get("session_date"),
        "segment_id": event.get("segment_id"),
        "event_id": event.get("event_id"),
        "event_type": event.get("event_type"),
        "task_episode_id": task_episode_id,
        "task_episode_ref": task_episode_ref,
        "correlation_id": event.get("correlation_id"),
        "source_correlation_id": event.get("source_correlation_id"),
        "rejected_correlation_id": event.get("rejected_correlation_id"),
        "parallel_correlation_ids": (
            event.get("parallel_correlation_ids", [])[:8]
            if isinstance(event.get("parallel_correlation_ids"), list)
            else []
        ),
        "causal_admission": event.get("causal_admission"),
        "async_cell_id": event.get("async_cell_id"),
        "async_hop": event.get("async_hop"),
        "async_transport_kind": event.get("async_transport_kind"),
        "async_transport_id": event.get("async_transport_id"),
        "async_transport_state": event.get("async_transport_state"),
        "classified_event_type": event.get("classified_event_type"),
        "classification_shadowed_by": event.get(
            "classification_shadowed_by"
        ),
        "family": event.get("family"),
        "phase": event.get("phase"),
        "actor": event.get("actor"),
        "action": event.get("action"),
        "outcome": event.get("outcome"),
        "result_status": event.get("result_status"),
        "result_status_basis": event.get("result_status_basis"),
        "result_status_admission": event.get("result_status_admission"),
        "result_status_tool": event.get("result_status_tool"),
        "tool_transport_status": event.get("tool_transport_status"),
        "verification_signals": (
            event.get("verification_signals", [])[:4]
            if isinstance(event.get("verification_signals"), list)
            else []
        ),
        "skill_evidence_state": event.get("skill_evidence_state"),
        "skill_state_admission": event.get("skill_state_admission"),
        "selection_target_refs": (
            dict(event.get("selection_target_refs"))
            if isinstance(event.get("selection_target_refs"), dict)
            else {}
        ),
        "prompt_visibility_admission": event.get(
            "prompt_visibility_admission"
        ),
        "prompt_visibility_source_role": event.get(
            "prompt_visibility_source_role"
        ),
        "prompt_visibility_skill_key": event.get(
            "prompt_visibility_skill_key"
        ),
        "prompt_visibility_source": event.get("prompt_visibility_source"),
        "observed_identity_source": event.get(
            "observed_identity_source"
        ),
        "procedure_anchor": event.get("procedure_anchor"),
        "procedure_definition_refs": (
            dict(event.get("procedure_definition_refs"))
            if isinstance(event.get("procedure_definition_refs"), dict)
            else {}
        ),
        "procedure_action_result_refs": (
            dict(event.get("procedure_action_result_refs"))
            if isinstance(
                event.get("procedure_action_result_refs"), dict
            )
            else {}
        ),
        "usage_actions": usage_actions,
        "primary_usage_action": usage_actions[0] if usage_actions else "",
        "conversation_act": event.get("conversation_act"),
        "session_act": event.get("session_act"),
        "mcp_usage_admission": event.get("mcp_usage_admission"),
        "mcp_usage_admission_service_key": event.get(
            "mcp_usage_admission_service_key"
        ),
        "mcp_tool_usage_admission": event.get(
            "mcp_tool_usage_admission"
        ),
        "mcp_tool_usage_route_key": event.get(
            "mcp_tool_usage_route_key"
        ),
        "mcp_tool_usage_service_key": event.get(
            "mcp_tool_usage_service_key"
        ),
        "mcp_tool_usage_tool_key": event.get(
            "mcp_tool_usage_tool_key"
        ),
        "mcp_result_identity": (
            dict(event.get("mcp_result_identity"))
            if isinstance(event.get("mcp_result_identity"), dict)
            else {}
        ),
        "tool_usage_admission": event.get("tool_usage_admission"),
        "tool_usage_admission_key": event.get("tool_usage_admission_key"),
        "tool_usage_invocation_name": event.get(
            "tool_usage_invocation_name"
        ),
        "tool_usage_invocation_namespace": event.get(
            "tool_usage_invocation_namespace"
        ),
        "hook_usage_admission": event.get("hook_usage_admission"),
        "execution_entity_usage_admission": event.get(
            "execution_entity_usage_admission"
        ),
        "execution_entity_usage_admission_reason": event.get(
            "execution_entity_usage_admission_reason"
        ),
        "execution_entity_usage_kind": event.get(
            "execution_entity_usage_kind"
        ),
        "execution_entity_usage_result_status": event.get(
            "execution_entity_usage_result_status"
        ),
        "execution_entity_usage_result_code": event.get(
            "execution_entity_usage_result_code"
        ),
        "execution_entity_usage_result_evidence": event.get(
            "execution_entity_usage_result_evidence"
        ),
        "execution_parent_refs": (
            dict(event.get("execution_parent_refs"))
            if isinstance(event.get("execution_parent_refs"), dict)
            else {}
        ),
        "execution_read_result_refs": (
            dict(event.get("execution_read_result_refs"))
            if isinstance(event.get("execution_read_result_refs"), dict)
            else {}
        ),
        "matched_routes": matched_routes[:6],
        "matched_routes_truncated": len(matched_routes) > 6,
        "route_signals": route_signals,
        "route_signal_count": event.get("route_signal_count") or route_signal_count,
        "route_signals_truncated": bool(event.get("route_signals_truncated")) or route_signal_count > len(route_signals),
        "title": event.get("title"),
        "snippet": short_text(str(event.get("snippet") or ""), max_chars=220) if event.get("snippet") else None,
        "refs": {
            "session": refs.get("session", ""),
            "segment": refs.get("segment", ""),
            "segment_index": refs.get("segment_index", ""),
            "raw": refs.get("raw", ""),
            "raw_block": refs.get("raw_block", ""),
            "task_episode": task_episode_ref,
        },
        "freshness": {
            "status": freshness.get("status"),
            "reasons": freshness.get("reasons", [])[:3] if isinstance(freshness.get("reasons"), list) else [],
            "basis": freshness.get("basis"),
            "live_verification": freshness.get("live_verification"),
            "segment_index_live_check": freshness.get("segment_index_live_check"),
        } if freshness else {},
    }


def entity_usage_chain_refs(events: list[dict[str, Any]], document_refs: list[dict[str, Any]], *, limit: int = 24) -> list[dict[str, Any]]:
    refs: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()

    def add(kind: str, value: Any, event: dict[str, Any] | None = None) -> None:
        value_text = str(value or "")
        if not value_text:
            return
        key = (kind, value_text)
        if key in seen:
            return
        seen.add(key)
        item: dict[str, Any] = {"kind": kind, "value": value_text}
        if isinstance(event, dict):
            item.update(
                {
                    "session_label": event.get("session_label"),
                    "event_id": event.get("event_id"),
                    "event_type": event.get("event_type"),
                    "role": event.get("role"),
                    "source_doc_id": event.get("doc_id"),
                }
            )
        refs.append(item)

    for event in events:
        if not isinstance(event, dict):
            continue
        refs_payload = event.get("refs") if isinstance(event.get("refs"), dict) else {}
        add("session_manifest", refs_payload.get("session"), event)
        add("receipt_ref", refs_payload.get("receipt"), event)
        add("segment_markdown", refs_payload.get("segment"), event)
        add("segment_index", refs_payload.get("segment_index"), event)
        add("raw_line", refs_payload.get("raw"), event)
        add("raw_block", refs_payload.get("raw_block"), event)
        add(
            "task_episode",
            refs_payload.get("task_episode")
            or event.get("task_episode_ref"),
            event,
        )
        parent_refs = (
            event.get("execution_parent_refs")
            if isinstance(event.get("execution_parent_refs"), dict)
            else {}
        )
        add("segment_markdown", parent_refs.get("segment"), event)
        add("segment_index", parent_refs.get("segment_index"), event)
        add("raw_line", parent_refs.get("raw"), event)
        add("raw_block", parent_refs.get("raw_block"), event)
        read_result_refs = (
            event.get("execution_read_result_refs")
            if isinstance(event.get("execution_read_result_refs"), dict)
            else {}
        )
        add("segment_markdown", read_result_refs.get("segment"), event)
        add("segment_index", read_result_refs.get("segment_index"), event)
        add("raw_line", read_result_refs.get("raw"), event)
        add("raw_block", read_result_refs.get("raw_block"), event)
        selection_target_refs = (
            event.get("selection_target_refs")
            if isinstance(event.get("selection_target_refs"), dict)
            else {}
        )
        procedure_definition_refs = (
            event.get("procedure_definition_refs")
            if isinstance(event.get("procedure_definition_refs"), dict)
            else {}
        )
        procedure_action_result_refs = (
            event.get("procedure_action_result_refs")
            if isinstance(
                event.get("procedure_action_result_refs"), dict
            )
            else {}
        )
        add("segment_markdown", selection_target_refs.get("segment"), event)
        add("segment_index", selection_target_refs.get("segment_index"), event)
        add("raw_line", selection_target_refs.get("raw"), event)
        add("raw_block", selection_target_refs.get("raw_block"), event)
        if len(refs) >= limit:
            return refs[:limit]
    for item in document_refs:
        if not isinstance(item, dict):
            continue
        add(str(item.get("kind") or "document_ref"), item.get("value"))
        if len(refs) >= limit:
            break
    return refs[:limit]


FIRST_REF_VALUE_KEYS = (
    ("raw", "raw"),
    ("raw_ref", "raw"),
    ("raw_block", "raw_block"),
    ("segment", "segment"),
    ("segment_ref", "segment"),
    ("segment_index", "segment_index"),
    ("receipt", "receipt"),
    ("session", "session"),
    ("session_ref", "session"),
    ("session_index", "session_index"),
)
FIRST_REF_STRONG_KEYS = {"raw", "raw_block", "segment", "segment_index", "receipt"}
FIRST_REF_KIND_VALUE_KEYS = {
    "raw_line": "raw",
    "raw_ref": "raw",
    "raw_block": "raw_block",
    "segment_markdown": "segment",
    "segment_ref": "segment",
    "segment_index": "segment_index",
    "receipt": "receipt",
    "receipt_ref": "receipt",
    "session_manifest": "session",
    "session_ref": "session",
    "session_index": "session_index",
}


def first_ref_value_is_evidence_coordinate(value: Any) -> bool:
    text = str(value or "").strip()
    if not text:
        return False
    # Generation and content hashes can occur under dependency keys named
    # ``segment_index`` or ``session_index``.  They are identities, not
    # resolvable evidence coordinates.
    return re.fullmatch(r"[0-9a-fA-F]{64}", text) is None


def first_ref_payload(values: dict[str, Any]) -> dict[str, str]:
    payload: dict[str, str] = {}
    for source_key, target_key in FIRST_REF_VALUE_KEYS:
        value = values.get(source_key)
        if (
            isinstance(value, str)
            and first_ref_value_is_evidence_coordinate(value)
            and not payload.get(target_key)
        ):
            payload[target_key] = value.strip()
    return payload


def first_ref_from_kind_value(kind: str, value: Any) -> dict[str, str]:
    target_key = FIRST_REF_KIND_VALUE_KEYS.get(route_key_slug(kind, fallback=""))
    if (
        not target_key
        or not isinstance(value, str)
        or not first_ref_value_is_evidence_coordinate(value)
    ):
        return {}
    return {target_key: value.strip()}


def first_ref_has_strong_evidence(first_ref: dict[str, Any]) -> bool:
    return any(first_ref.get(key) for key in FIRST_REF_STRONG_KEYS)


def merge_first_ref_value(first_ref: dict[str, str], key: str, value: Any) -> None:
    if key and value and not first_ref.get(key):
        first_ref[key] = str(value)


def entity_usage_chain_first_ref(events: list[dict[str, Any]], evidence_refs: list[dict[str, Any]]) -> dict[str, Any]:
    fallback_ref: dict[str, str] = {}
    for event in events:
        if not isinstance(event, dict):
            continue
        refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
        first_ref = first_ref_payload(refs)
        if first_ref_has_strong_evidence(first_ref):
            return first_ref
        if first_ref and not fallback_ref:
            fallback_ref = first_ref
    first_ref = dict(fallback_ref)
    for item in evidence_refs:
        if not isinstance(item, dict):
            continue
        kind = str(item.get("kind") or "")
        value = str(item.get("value") or "")
        if not value:
            continue
        for key, ref_value in first_ref_from_kind_value(kind, value).items():
            merge_first_ref_value(first_ref, key, ref_value)
    return first_ref


def entity_usage_chain_command(
    command_name: str,
    *,
    anchor: str,
    kind: str,
    aoa_root: Path,
    session: str | None = None,
    correlation_id: str | None = None,
    before_event_id: str | None = None,
    limit: int | None = None,
    per_route_limit: int | None = None,
    extra: list[str] | None = None,
) -> str:
    command = [
        "python3",
        "scripts/aoa_session_memory.py",
        command_name,
        anchor,
        "--aoa-root",
        str(aoa_root),
        "--kind",
        kind,
    ]
    if session:
        command.extend(["--session", session])
    if correlation_id:
        command.extend(["--correlation-id", correlation_id])
    if before_event_id:
        command.extend(["--before-event-id", str(before_event_id)])
    if limit is not None:
        command.extend(["--limit", str(limit)])
    if per_route_limit is not None:
        command.extend(["--per-route-limit", str(per_route_limit)])
    if extra:
        command.extend(extra)
    return shlex.join(command)


def entity_usage_event_has_strong_ref(event: dict[str, Any]) -> bool:
    refs = (
        event.get("refs")
        if isinstance(event.get("refs"), dict)
        else {}
    )
    parent_refs = (
        event.get("execution_parent_refs")
        if isinstance(event.get("execution_parent_refs"), dict)
        else {}
    )
    return any(
        str(container.get(key) or "")
        for container in (refs, parent_refs)
        for key in (
            "raw",
            "raw_block",
            "segment",
            "segment_index",
            "receipt",
        )
    )


def entity_usage_event_is_structured_invocation(
    event: dict[str, Any],
    *,
    normalized_kind: str,
    requested_kind: str,
) -> bool:
    if str(event.get("role") or "") != "usage":
        return False
    if normalized_kind == "skill":
        return False
    admissions = {
        str(event.get("mcp_usage_admission") or ""),
        str(event.get("mcp_tool_usage_admission") or ""),
        str(event.get("tool_usage_admission") or ""),
        str(event.get("hook_usage_admission") or ""),
        str(event.get("execution_entity_usage_admission") or ""),
    }
    structured_admissions = {
        "structured_invocation_proven",
        "structured_nested_invocation_proven",
        "structured_hook_event_proven",
        "structured_hook_command_invocation_proven",
        "structured_command_invocation_proven",
        "structured_result_invocation_proven",
    }
    if admissions & structured_admissions:
        return entity_usage_event_has_strong_ref(event)
    if requested_kind == "mcp_tool":
        return False
    return bool(
        str(event.get("event_type") or "").upper()
        in ENTITY_USAGE_DIRECT_TYPES
        and str(event.get("correlation_id") or "")
        and entity_usage_event_has_strong_ref(event)
    )


def entity_usage_state_evidence_sample(
    events: Iterable[dict[str, Any]],
    *,
    limit: int = 6,
) -> list[dict[str, Any]]:
    samples: list[dict[str, Any]] = []
    seen: set[str] = set()
    for event in events:
        if not isinstance(event, dict):
            continue
        identity = str(
            event.get("doc_id")
            or "|".join(
                str(value or "")
                for value in (
                    event.get("session_id")
                    or event.get("session_label"),
                    event.get("segment_id"),
                    event.get("event_id"),
                    event.get("correlation_id"),
                )
            ).strip("|")
        )
        if not identity or identity in seen:
            continue
        seen.add(identity)
        refs = (
            event.get("refs")
            if isinstance(event.get("refs"), dict)
            else {}
        )
        read_result_refs = (
            event.get("execution_read_result_refs")
            if isinstance(
                event.get("execution_read_result_refs"),
                dict,
            )
            else {}
        )
        selection_target_refs = (
            event.get("selection_target_refs")
            if isinstance(event.get("selection_target_refs"), dict)
            else {}
        )
        procedure_definition_refs = (
            event.get("procedure_definition_refs")
            if isinstance(event.get("procedure_definition_refs"), dict)
            else {}
        )
        procedure_action_result_refs = (
            event.get("procedure_action_result_refs")
            if isinstance(event.get("procedure_action_result_refs"), dict)
            else {}
        )
        samples.append(
            {
                "candidate_id": identity,
                "session_id": str(event.get("session_id") or ""),
                "session_label": str(
                    event.get("session_label") or ""
                ),
                "segment_id": str(event.get("segment_id") or ""),
                "event_id": str(event.get("event_id") or ""),
                "event_type": str(event.get("event_type") or ""),
                "correlation_id": str(
                    event.get("correlation_id") or ""
                ),
                "relation": str(event.get("relation") or ""),
                "refs": {
                    key: str(refs.get(key) or "")
                    for key in (
                        "raw",
                        "raw_block",
                        "segment",
                        "segment_index",
                        "receipt",
                        "session",
                    )
                    if refs.get(key)
                },
                **(
                    {
                        "read_result_refs": {
                            key: str(read_result_refs.get(key) or "")
                            for key in (
                                "raw",
                                "raw_block",
                                "segment",
                                "segment_index",
                                "session",
                            )
                            if read_result_refs.get(key)
                        }
                    }
                    if read_result_refs
                    else {}
                ),
                **(
                    {
                        "selection_target_refs": {
                            key: str(selection_target_refs.get(key) or "")
                            for key in (
                                "raw",
                                "raw_block",
                                "segment",
                                "segment_index",
                                "session",
                            )
                            if selection_target_refs.get(key)
                        }
                    }
                    if selection_target_refs
                    else {}
                ),
                **(
                    {
                        "procedure_anchor": str(
                            event.get("procedure_anchor") or ""
                        ),
                        "procedure_definition_refs": {
                            key: str(
                                procedure_definition_refs.get(key) or ""
                            )
                            for key in (
                                "raw",
                                "raw_block",
                                "segment",
                                "segment_index",
                                "session",
                            )
                            if procedure_definition_refs.get(key)
                        },
                        "procedure_action_result_refs": {
                            key: str(
                                procedure_action_result_refs.get(key) or ""
                            )
                            for key in (
                                "raw",
                                "raw_block",
                                "segment",
                                "segment_index",
                                "session",
                            )
                            if procedure_action_result_refs.get(key)
                        },
                    }
                    if procedure_definition_refs
                    and procedure_action_result_refs
                    else {}
                ),
            }
        )
        if len(samples) >= limit:
            break
    return samples


def entity_usage_lifecycle_projection(
    *,
    normalized_kind: str,
    requested_kind: str,
    registry_lookup: dict[str, Any],
    skill_evidence: dict[str, Any],
    entrypoint_events: list[dict[str, Any]],
    usage_events: list[dict[str, Any]],
    result_events: list[dict[str, Any]],
    outcome_events: list[dict[str, Any]],
    context_events: list[dict[str, Any]],
    consequence_events: list[dict[str, Any]],
    chains: list[dict[str, Any]],
    false_correlation_events: list[dict[str, Any]],
    truncated: bool,
    incomplete: bool,
    candidate_count_exhaustive: bool,
) -> dict[str, Any]:
    def rejected_context(event: dict[str, Any]) -> bool:
        return bool(
            str(event.get("skill_evidence_state") or "")
            in {"false_correlation", "cooccurrence"}
            or str(event.get("relation") or "")
            in ENTITY_USAGE_LIFECYCLE_REJECTED_RELATIONS
            or str(event.get("causal_admission") or "").startswith(
                "rejected_"
            )
        )

    accepted_events = unique_entity_usage_events(
        [
            *entrypoint_events,
            *usage_events,
            *result_events,
            *outcome_events,
            *context_events,
            *consequence_events,
        ]
    )
    accepted_events = [
        event for event in accepted_events if not rejected_context(event)
    ]
    skill_state_events: defaultdict[str, list[dict[str, Any]]] = (
        defaultdict(list)
    )
    for event in accepted_events:
        state = str(event.get("skill_evidence_state") or "")
        if state:
            skill_state_events[state].append(event)

    registry_entries = [
        entry
        for entry in (
            registry_lookup.get("entries")
            if isinstance(registry_lookup.get("entries"), list)
            else []
        )
        if isinstance(entry, dict)
        and str(entry.get("status") or "") != "unknown"
    ]
    registry_canonicalization = [
        entry.get("canonicalization")
        if isinstance(entry.get("canonicalization"), dict)
        else {}
        for entry in registry_entries
    ]
    registry_ambiguous = (
        len(registry_entries) > 1
        or any(
            canonicalization.get("status")
            == "ambiguous_candidates_preserved"
            for canonicalization in registry_canonicalization
        )
    )
    registry_identity_resolved = bool(
        len(registry_entries) == 1
        and registry_canonicalization
        and registry_canonicalization[0].get("status") == "resolved"
    )
    registry_identity_status = (
        "ambiguous"
        if registry_ambiguous
        else "resolved"
        if registry_identity_resolved
        else "unproven"
    )
    registry_candidate_ids = sorted(
        {
            str(candidate.get("candidate_id") or "")
            for entry in registry_entries
            for candidate in (
                entry.get("identity_candidates")
                if isinstance(entry.get("identity_candidates"), list)
                else []
            )
            if isinstance(candidate, dict)
            and str(candidate.get("candidate_id") or "")
        }
    )
    registry_refs = [
        ref
        for entry in registry_entries
        for ref in (
            entry.get("source_refs")
            if isinstance(entry.get("source_refs"), list)
            else []
        )
    ]

    candidate_paths: dict[str, str] = {}
    for entry in registry_entries:
        for candidate in (
            entry.get("identity_candidates")
            if isinstance(entry.get("identity_candidates"), list)
            else []
        ):
            if not isinstance(candidate, dict):
                continue
            candidate_id = str(candidate.get("candidate_id") or "")
            if not candidate_id:
                continue
            for source_ref in (
                candidate.get("source_refs")
                if isinstance(candidate.get("source_refs"), list)
                else []
            ):
                if not isinstance(source_ref, dict):
                    continue
                path = str(source_ref.get("path") or "").strip()
                if path:
                    candidate_paths[path] = candidate_id

    observed_identity_by_doc: dict[str, dict[str, Any]] = {}
    raw_identity_by_ref: dict[str, dict[str, Any]] = {}
    for event in accepted_events:
        doc_id = str(event.get("doc_id") or "")
        material = "\n".join(
            str(value or "")
            for value in (
                event.get("snippet"),
                event.get("prompt_visibility_source"),
                event.get("observed_identity_source"),
            )
        )
        matched_candidate_ids = sorted(
            {
                candidate_id
                for path, candidate_id in candidate_paths.items()
                if path and path in material
            }
        )
        resolution: dict[str, Any] = {}
        if len(matched_candidate_ids) == 1:
            resolution = {
                "status": "resolved_observed_instance",
                "candidate_ids": matched_candidate_ids,
                "basis": "raw_structured_event_names_exact_registry_source_path",
            }
        elif len(matched_candidate_ids) > 1:
            resolution = {
                "status": "ambiguous_observed_instance",
                "candidate_ids": matched_candidate_ids,
                "basis": "one_event_names_multiple_registry_source_paths",
            }
        elif entity_usage_event_is_structured_invocation(
            event,
            normalized_kind=normalized_kind,
            requested_kind=requested_kind,
        ):
            resolution = {
                "status": "resolved_observed_route_identity",
                "candidate_ids": [],
                "basis": (
                    "structured_entity_specific_invocation_with_exact_"
                    "route_identity"
                ),
            }
        if not resolution:
            continue
        if doc_id:
            observed_identity_by_doc[doc_id] = resolution
        refs = event.get("refs") if isinstance(event.get("refs"), dict) else {}
        raw_ref = str(refs.get("raw") or "")
        if raw_ref:
            raw_identity_by_ref[raw_ref] = resolution

    # Propagate an already resolved identity only across an explicit source-doc
    # link or a structured selection target.  Adjacency and co-occurrence never
    # participate in identity attribution.
    for event in accepted_events:
        doc_id = str(event.get("doc_id") or "")
        if not doc_id or doc_id in observed_identity_by_doc:
            continue
        source_doc_id = str(event.get("source_doc_id") or "")
        resolution = observed_identity_by_doc.get(source_doc_id, {})
        if not resolution:
            selection_refs = (
                event.get("selection_target_refs")
                if isinstance(event.get("selection_target_refs"), dict)
                else {}
            )
            resolution = raw_identity_by_ref.get(
                str(selection_refs.get("raw") or ""),
                {},
            )
        if resolution:
            observed_identity_by_doc[doc_id] = {
                **resolution,
                "basis": (
                    "correlation_or_structured_target_link_to_"
                    + str(resolution.get("basis") or "observed_identity")
                ),
            }
    invoked_events = [
        event
        for event in usage_events
        if entity_usage_event_is_structured_invocation(
            event,
            normalized_kind=normalized_kind,
            requested_kind=requested_kind,
        )
    ]
    invoked_doc_ids = {
        str(event.get("doc_id") or "")
        for event in invoked_events
        if str(event.get("doc_id") or "")
    }
    correlation_owned_events: list[dict[str, Any]] = []
    for chain in chains:
        if not isinstance(chain, dict):
            continue
        usage_event = (
            chain.get("usage_event")
            if isinstance(chain.get("usage_event"), dict)
            else {}
        )
        usage_doc_id = str(usage_event.get("doc_id") or "")
        if (
            not usage_doc_id
            or usage_doc_id not in invoked_doc_ids
            or rejected_context(usage_event)
        ):
            continue
        admitted_for_chain: list[dict[str, Any]] = []
        for event in (
            chain.get("result_or_consequence_events")
            if isinstance(
                chain.get("result_or_consequence_events"), list
            )
            else []
        ):
            if not isinstance(event, dict) or rejected_context(event):
                continue
            source_doc_id = str(event.get("source_doc_id") or "")
            relation = str(event.get("relation") or "")
            if source_doc_id != usage_doc_id:
                continue
            if (
                relation
                not in ENTITY_USAGE_LIFECYCLE_CORRELATION_RELATIONS
            ):
                continue
            admitted_for_chain.append(event)
        intrinsic_result_evidence = bool(
            chain.get("intrinsic_result_evidence")
            and str(
                usage_event.get("execution_entity_usage_admission")
                or ""
            )
            == "structured_result_invocation_proven"
        )
        correlation_owned_events.extend(admitted_for_chain)
        if intrinsic_result_evidence:
            correlation_owned_events.append(usage_event)

    completion_events = [
        event
        for event in unique_entity_usage_events(correlation_owned_events)
        if str(event.get("result_status") or "")
        == "succeeded"
        or str(
            event.get("execution_entity_usage_result_status") or ""
        )
        == "succeeded"
        or str(event.get("outcome") or "") == "succeeded"
        or str(event.get("async_transport_state") or "")
        in {"completed", "succeeded"}
        or str(event.get("tool_transport_status") or "")
        == "completed"
    ]
    verification_events = [
        event
        for event in unique_entity_usage_events(correlation_owned_events)
        if (
            str(event.get("relation") or "")
            == "post_correlated_verification"
            or (
                str(
                    event.get(
                        "execution_entity_usage_admission"
                    )
                    or ""
                )
                == "structured_result_invocation_proven"
                and str(
                    event.get(
                        "execution_entity_usage_result_status"
                    )
                    or ""
                )
                == "succeeded"
                and str(
                    event.get("execution_entity_usage_kind") or ""
                )
                in {"test", "validator"}
            )
            or (
                normalized_kind == "test"
                and "delivery_state:tests_green"
                in (
                    event.get("verification_signals")
                    if isinstance(
                        event.get("verification_signals"), list
                    )
                    else []
                )
            )
        )
    ]
    failure_events = [
        event
        for event in unique_entity_usage_events(correlation_owned_events)
        if str(event.get("result_status") or "")
        in {"failed", "timed_out"}
        or str(event.get("execution_entity_usage_result_status") or "")
        == "failed"
        or str(event.get("outcome") or "") == "failed"
        or "failed"
        in (
            event.get("usage_actions")
            if isinstance(event.get("usage_actions"), list)
            else []
        )
    ]
    consequence_producing_events: list[dict[str, Any]] = []
    accepted_chain_count = 0
    for chain in chains:
        if not isinstance(chain, dict):
            continue
        usage_event = (
            chain.get("usage_event")
            if isinstance(chain.get("usage_event"), dict)
            else {}
        )
        usage_doc_id = str(usage_event.get("doc_id") or "")
        if (
            not usage_doc_id
            or usage_doc_id not in invoked_doc_ids
            or rejected_context(usage_event)
        ):
            continue
        attached = [
            event
            for event in (
                chain.get("result_or_consequence_events")
                if isinstance(
                    chain.get("result_or_consequence_events"),
                    list,
                )
                else []
            )
            if (
                isinstance(event, dict)
                and not rejected_context(event)
                and str(event.get("source_doc_id") or "")
                == usage_doc_id
                and str(event.get("relation") or "")
                in ENTITY_USAGE_LIFECYCLE_CORRELATION_RELATIONS
            )
        ]
        causal_consequences = [
            event
            for event in attached
            if str(event.get("relation") or "") in {
                "post_correlated_outcome",
                "post_correlated_verification",
            }
        ]
        if not causal_consequences:
            continue
        accepted_chain_count += 1
        consequence_producing_events.extend(
            [usage_event, *causal_consequences]
        )

    mentioned_events = [
        event
        for event in context_events
        if (
            not rejected_context(event)
            and (
            str(event.get("skill_evidence_state") or "")
            == "mentioned"
            or str(event.get("relation") or "")
            not in {
                "false_correlation",
                "parallel_batch_outcome_context",
                "parallel_batch_verification_context",
            }
            )
        )
    ]
    prompt_visible_events = skill_state_events["prompt_visible"]
    selected_events = skill_state_events["selected"]
    skill_loaded_events = [
        event
        for event in skill_state_events["skill_read"]
        if isinstance(event.get("execution_read_result_refs"), dict)
        and event.get("execution_read_result_refs", {}).get("raw")
    ]
    execution_read_events = [
        event
        for event in context_events
        if (
            str(event.get("execution_entity_usage_admission") or "")
            == "structured_inspection_read_proven"
            and isinstance(
                event.get("execution_read_result_refs"),
                dict,
            )
            and event.get("execution_read_result_refs", {}).get("raw")
        )
    ]
    read_events = [
        *skill_state_events["skill_read"],
        *execution_read_events,
    ]
    procedure_events = skill_state_events["procedure_observed"]
    skill_completed_events = skill_state_events["completed"]
    skill_verified_events = skill_state_events["verified"]
    deflected_events = skill_state_events["deflected"]

    def state_payload(
        state: str,
        events: Iterable[dict[str, Any]],
        *,
        status: str,
        basis: str,
        source_observed: bool = False,
        extra_count: int = 0,
    ) -> dict[str, Any]:
        unique_events = unique_entity_usage_events(
            [event for event in events if isinstance(event, dict)]
        )
        strong_ref_count = sum(
            1
            for event in unique_events
            if entity_usage_event_has_strong_ref(event)
        )
        positive_instance_admitted = bool(
            source_observed
            and unique_events
            and strong_ref_count
        )
        state_identity_resolutions = [
            observed_identity_by_doc.get(str(event.get("doc_id") or ""), {})
            for event in unique_events
        ]
        state_identity_resolutions = [
            item for item in state_identity_resolutions if item
        ]
        state_identity_candidate_ids = sorted(
            {
                str(candidate_id)
                for item in state_identity_resolutions
                for candidate_id in (
                    item.get("candidate_ids")
                    if isinstance(item.get("candidate_ids"), list)
                    else []
                )
                if str(candidate_id)
            }
        )
        state_identity_ambiguous = any(
            str(item.get("status") or "").startswith("ambiguous")
            for item in state_identity_resolutions
        )
        state_identity_admitted = bool(
            state_identity_resolutions and not state_identity_ambiguous
        )
        return {
            "state": state,
            "status": status,
            "present": bool(unique_events or extra_count),
            "evidence_count": len(unique_events) + extra_count,
            "strong_evidence_event_count": strong_ref_count,
            "basis": basis,
            "evidence_sample": entity_usage_state_evidence_sample(
                unique_events
            ),
            "positive_instance_admitted": (
                positive_instance_admitted
            ),
            "exhaustive_claim_admitted": bool(
                positive_instance_admitted
                and candidate_count_exhaustive
                and not truncated
                and not incomplete
            ),
            "negative_claim_admitted": False,
            "identity_attribution_admitted": state_identity_admitted,
            "identity_status": (
                "ambiguous_observed_instance"
                if state_identity_ambiguous
                else "resolved_observed_instance"
                if state_identity_admitted
                else registry_identity_status
            ),
            "observed_identity_candidate_ids": (
                state_identity_candidate_ids
            ),
            "identity_basis": unique_preserving_order(
                [
                    str(item.get("basis") or "")
                    for item in state_identity_resolutions
                    if str(item.get("basis") or "")
                ]
            ),
        }

    absent_status = (
        "unresolved"
        if incomplete
        else "not_observed_in_bounded_scope"
    )
    states: dict[str, dict[str, Any]] = {}
    states["registered"] = {
        "state": "registered",
        "status": (
            "candidate_ambiguous"
            if registry_ambiguous
            else "identity_unproven"
            if registry_entries and not registry_identity_resolved
            else "projection_observed"
            if registry_entries
            else absent_status
        ),
        "present": bool(registry_entries),
        "evidence_count": len(registry_entries),
        "strong_evidence_event_count": 0,
        "basis": (
            "generated_entity_registry_identity_with_source_refs"
            if registry_entries
            else "no_registry_identity_in_current_lookup"
        ),
        "entity_ids": sorted(
            {
                str(entry.get("entity_id") or "")
                for entry in registry_entries
                if str(entry.get("entity_id") or "")
            }
        ),
        "source_refs": registry_refs[:12],
        "identity_status": registry_identity_status,
        "identity_candidate_ids": registry_candidate_ids,
        "identity_attribution_admitted": (
            registry_identity_resolved
        ),
        "positive_instance_admitted": False,
        "exhaustive_claim_admitted": False,
        "negative_claim_admitted": False,
    }
    states["mentioned"] = state_payload(
        "mentioned",
        mentioned_events,
        status=(
            "projection_observed"
            if mentioned_events
            else absent_status
        ),
        basis="exact_or_typed_context_association_not_usage",
    )
    states["prompt-visible"] = state_payload(
        "prompt-visible",
        prompt_visible_events,
        status=(
            "source_observed"
            if prompt_visible_events
            else absent_status
        ),
        basis="structured_available_skills_raw_context_entry",
        source_observed=True,
    )
    states["selected"] = state_payload(
        "selected",
        selected_events,
        status="candidate" if selected_events else absent_status,
        basis="explicit_dispatch_or_assistant_selection_candidate",
    )
    states["loaded"] = state_payload(
        "loaded",
        skill_loaded_events,
        status=(
            "source_observed"
            if skill_loaded_events
            else "candidate"
            if selected_events
            else absent_status
        ),
        basis=(
            "correlation_owned_skill_body_returned_into_agent_context"
            if skill_loaded_events
            else "selection_does_not_prove_payload_load; "
            "correlation_owned_skill_body_or_runtime_load_receipt_required"
        ),
        source_observed=bool(skill_loaded_events),
        extra_count=(
            0 if skill_loaded_events else int(bool(selected_events))
        ),
    )
    states["loaded"]["candidate_present"] = bool(selected_events)
    if not skill_loaded_events:
        states["loaded"]["present"] = False
    states["read"] = state_payload(
        "read",
        read_events,
        status="source_observed" if read_events else absent_status,
        basis=(
            "structured_skill_artifact_content_read"
            if normalized_kind == "skill"
            else (
                "structured_file_inspection_plus_correlation_owned_"
                "nonfailure_result"
            )
        ),
        source_observed=True,
    )
    states["procedure-observed"] = state_payload(
        "procedure-observed",
        procedure_events,
        status="source_observed" if procedure_events else absent_status,
        basis=(
            "returned_skill_body_declared_exact_procedure_anchor_then_"
            "structured_action_with_same_correlation_nonfailure_result; "
            "not benefit or causal-effect proof"
        ),
        source_observed=True,
    )
    states["invoked"] = state_payload(
        "invoked",
        invoked_events,
        status="source_observed" if invoked_events else absent_status,
        basis=(
            "structured_entity_specific_invocation_with_resolvable_source_ref"
        ),
        source_observed=True,
    )
    states["completed"] = state_payload(
        "completed",
        (
            skill_completed_events
            if normalized_kind == "skill"
            else completion_events
        ),
        status=(
            "candidate"
            if normalized_kind == "skill"
            and skill_completed_events
            else "source_observed"
            if completion_events
            else absent_status
        ),
        basis=(
            "owner_review_required_for_skill_completion"
            if normalized_kind == "skill"
            else (
                "correlation_owned_terminal_result_or_transport_completion"
            )
        ),
        source_observed=normalized_kind != "skill",
    )
    states["verified"] = state_payload(
        "verified",
        (
            skill_verified_events
            if normalized_kind == "skill"
            else verification_events
        ),
        status=(
            "candidate"
            if normalized_kind == "skill"
            and skill_verified_events
            else "source_observed"
            if verification_events
            else absent_status
        ),
        basis=(
            "owner_review_required_for_skill_verification"
            if normalized_kind == "skill"
            else (
                "structured_or_post_correlated_verification; test results "
                "also require a correlation-owned tests_green signal"
            )
        ),
        source_observed=normalized_kind != "skill",
    )
    states["consequence-producing"] = state_payload(
        "consequence-producing",
        consequence_producing_events,
        status=(
            "source_observed"
            if consequence_producing_events
            else absent_status
        ),
        basis=(
            "correlation_owned_post_result_outcome_or_verification_chain; "
            "transport completion and status alone are not consequences"
        ),
        source_observed=True,
    )
    states["failed"] = state_payload(
        "failed",
        failure_events,
        status="source_observed" if failure_events else absent_status,
        basis="correlation_owned_failure_or_timeout_status",
        source_observed=True,
    )
    states["deflected"] = state_payload(
        "deflected",
        deflected_events,
        status="candidate" if deflected_events else absent_status,
        basis="owner_receipt_or_review_required",
    )

    claim_admission_by_state = {
        state: {
            "positive_instance_admitted": bool(
                payload.get("positive_instance_admitted")
            ),
            "exhaustive_claim_admitted": bool(
                payload.get("exhaustive_claim_admitted")
            ),
            "negative_claim_admitted": False,
            "status": payload.get("status"),
            "identity_attribution_admitted": (
                bool(payload.get("identity_attribution_admitted"))
            ),
        }
        for state, payload in states.items()
    }
    observed_identity_candidate_ids = sorted(
        {
            str(candidate_id)
            for resolution in observed_identity_by_doc.values()
            for candidate_id in (
                resolution.get("candidate_ids")
                if isinstance(resolution.get("candidate_ids"), list)
                else []
            )
            if str(candidate_id)
        }
    )
    observed_identity_resolved = bool(
        observed_identity_by_doc
        and not any(
            str(resolution.get("status") or "").startswith("ambiguous")
            for resolution in observed_identity_by_doc.values()
        )
    )
    return {
        "schema": "aoa_session_memory_entity_usage_lifecycle_v1",
        "schema_version": ENTITY_USAGE_LIFECYCLE_SCHEMA_VERSION,
        "states_order": list(ENTITY_USAGE_LIFECYCLE_STATES),
        "states": states,
        "present_states": [
            state
            for state in ENTITY_USAGE_LIFECYCLE_STATES
            if states[state].get("present")
        ],
        "identity": {
            "status": registry_identity_status,
            "aggregate_entry_count": len(registry_entries),
            "candidate_count": len(registry_candidate_ids),
            "candidate_ids": registry_candidate_ids,
            "entity_ids": states["registered"].get("entity_ids", []),
            "collision_preserved": registry_ambiguous,
            "identity_attribution_admitted": (
                registry_identity_resolved
            ),
            "observed_instance_status": (
                "resolved"
                if observed_identity_resolved
                else "ambiguous"
                if observed_identity_by_doc
                else "unproven"
            ),
            "observed_instance_candidate_ids": (
                observed_identity_candidate_ids
            ),
            "observed_instance_identity_attribution_admitted": (
                observed_identity_resolved
            ),
            "claim_boundary": (
                "global registry collisions remain preserved; one raw "
                "structured event may still resolve the exact observed "
                "instance without globally merging candidates"
            ),
        },
        "correlation": {
            "accepted_consequence_chain_count": accepted_chain_count,
            "rejected_context_count": len(
                false_correlation_events
            ),
            "rejected_context_sample": (
                entity_usage_state_evidence_sample(
                    false_correlation_events
                )
            ),
            "law": (
                "a result, status, verification, or consequence belongs to an "
                "invocation only after structured correlation admission"
            ),
        },
        "coverage": {
            "truncated": bool(truncated),
            "incomplete": bool(incomplete),
            "candidate_count_exhaustive": bool(
                candidate_count_exhaustive
            ),
        },
        "answer_admission": {
            "admitted": False,
            "status": "requires_explicit_usage_state_claim",
            "umbrella_used_claim_admitted": False,
            "reason": (
                "the word used collapses distinct lifecycle states; select "
                "registered, mentioned, prompt-visible, selected, loaded, "
                "read, procedure-observed, invoked, completed, verified, "
                "consequence-producing, failed, or deflected"
            ),
            "claim_admission_by_state": claim_admission_by_state,
            "negative_claim_admitted": False,
            "negative_claim_reason": (
                "bounded session-memory retrieval cannot prove absence unless "
                "scope, freshness, and raw coverage are complete"
            ),
            "current_state_claim_admitted": False,
            "current_state_next_route": (
                "verify the current authoritative owner or runtime surface"
            ),
        },
        "authority_boundary": (
            "This lifecycle is a source-linked read model. Raw session events, "
            "receipts, and current owner/runtime sources remain authoritative."
        ),
    }


def entity_usage_chain(
    *,
    aoa_root: Path,
    anchor: str,
    kind: str = "auto",
    limit: int = 6,
    per_route_limit: int = 12,
    consequence_window: int = 6,
    document_limit: int = 24,
    provider: str = "portable_sqlite",
    session: str | None = None,
    correlation_id: str | None = None,
    before_event_id: str | None = None,
    include_source_audit: bool = False,
    write_report: bool = False,
) -> dict[str, Any]:
    now = utc_now()
    requested_kind = str(kind or "auto").strip().lower() or "auto"
    normalized_kind = normalize_trace_route_kind(kind)
    if normalized_kind not in TRACE_ROUTE_KINDS:
        return {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "session_memory_entity_usage_chain",
            "generated_at": now,
            "ok": False,
            "mutates": False,
            "anchor": anchor,
            **trace_kind_payload_fields(kind, normalized_kind),
            "diagnostics": [f"unknown trace kind: {kind}"],
        }
    limit = max(1, min(int_value(limit, 6), 50))
    per_route_limit = max(1, min(int_value(per_route_limit, 12), 100))
    consequence_window = max(1, min(int_value(consequence_window, 6), 24))
    document_limit = max(0, min(int_value(document_limit, 24), 100))
    audit_kind = (
        requested_kind
        if requested_kind == "mcp_tool"
        else normalized_kind
    )
    audit = entity_usage_audit(
        aoa_root=aoa_root,
        anchor=anchor,
        kind=audit_kind,
        limit=limit,
        per_route_limit=per_route_limit,
        consequence_window=consequence_window,
        document_limit=document_limit,
        provider=provider,
        session=session,
        correlation_id=correlation_id,
        before_event_id=before_event_id,
        write_report=False,
    )
    entrypoint_events = [
        entity_usage_chain_event(event)
        for event in audit.get("entrypoint_events", []) if isinstance(event, dict)
    ][:limit]
    usage_events = [
        entity_usage_chain_event(event)
        for event in audit.get("usage_events", []) if isinstance(event, dict)
    ][:limit]
    result_events = [
        entity_usage_chain_event(event)
        for event in audit.get("result_events", []) if isinstance(event, dict)
    ][:limit]
    outcome_events = [
        entity_usage_chain_event(event)
        for event in audit.get("outcome_events", []) if isinstance(event, dict)
    ][:limit]
    consequence_events = [
        entity_usage_chain_event(event)
        for event in audit.get("consequence_events", []) if isinstance(event, dict)
    ][: max(limit * consequence_window, limit)]
    false_correlation_events = [
        entity_usage_chain_event(event)
        for event in audit.get("false_correlation_events", []) if isinstance(event, dict)
    ][: max(limit * consequence_window, limit)]
    candidate_context_events = [
        entity_usage_chain_event(event)
        for event in audit.get("context_events", []) if isinstance(event, dict)
    ][:limit]
    consequences_by_source: dict[str, list[dict[str, Any]]] = defaultdict(list)
    unmatched_consequences: list[dict[str, Any]] = []
    for event in consequence_events:
        source_doc_id = str(event.get("source_doc_id") or "")
        if source_doc_id:
            consequences_by_source[source_doc_id].append(event)
        else:
            unmatched_consequences.append(event)
    chains: list[dict[str, Any]] = []
    for event in usage_events:
        source_doc_id = str(event.get("doc_id") or "")
        consequences = consequences_by_source.get(source_doc_id, [])
        intrinsic_result_evidence = (
            str(event.get("execution_entity_usage_admission") or "")
            == "structured_result_invocation_proven"
        )
        chains.append(
            {
                "usage_event": event,
                "result_or_consequence_events": consequences[:consequence_window],
                "result_or_consequence_count": (
                    len(consequences) + int(intrinsic_result_evidence)
                ),
                "has_result_or_consequence": bool(
                    consequences or intrinsic_result_evidence
                ),
                "intrinsic_result_evidence": intrinsic_result_evidence,
            }
        )
    attached_result_or_consequence_count = sum(
        int_value(item.get("result_or_consequence_count"))
        for item in chains
    )
    chain_with_result_or_consequence_count = sum(
        1 for item in chains if item.get("has_result_or_consequence")
    )
    attached_result_or_consequence_present = (
        chain_with_result_or_consequence_count > 0
    )
    attached_consequence_doc_ids = {
        str(event.get("doc_id") or "")
        for item in chains
        for event in (
            item.get("result_or_consequence_events", [])
            if isinstance(item.get("result_or_consequence_events"), list)
            else []
        )
        if isinstance(event, dict) and str(event.get("doc_id") or "")
    }
    context_events = [
        event
        for event in candidate_context_events
        if not str(event.get("doc_id") or "")
        or str(event.get("doc_id") or "")
        not in attached_consequence_doc_ids
    ]
    attached_context_duplicate_suppressed_count = (
        len(candidate_context_events) - len(context_events)
    )
    result_or_outcome_candidates = unique_entity_usage_events(
        [*result_events, *outcome_events]
    )
    unattached_result_or_outcome_candidates = [
        event
        for event in result_or_outcome_candidates
        if not str(event.get("doc_id") or "")
        or str(event.get("doc_id") or "") not in attached_consequence_doc_ids
    ]
    document_refs = [
        item for item in audit.get("document_refs", []) if isinstance(item, dict)
    ][:document_limit]
    accepted_chain_event_associations = [
        *entrypoint_events,
        *usage_events,
        *result_events,
        *outcome_events,
        *consequence_events,
        *context_events,
    ]
    unique_accepted_chain_events = unique_entity_usage_events(accepted_chain_event_associations)
    unique_false_correlation_event_count = len(unique_entity_usage_events(false_correlation_events))
    all_chain_events = [*accepted_chain_event_associations, *false_correlation_events]
    usage_action_counts: Counter[str] = Counter()
    primary_usage_action_counts: Counter[str] = Counter()
    usage_action_samples: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for event in unique_accepted_chain_events:
        if not isinstance(event, dict):
            continue
        if event.get("skill_evidence_state") in {"false_correlation", "cooccurrence"}:
            continue
        primary_action = str(event.get("primary_usage_action") or "")
        if primary_action:
            primary_usage_action_counts[primary_action] += 1
        for action in event.get("usage_actions", []) if isinstance(event.get("usage_actions"), list) else []:
            action_text = str(action or "")
            if not action_text:
                continue
            usage_action_counts[action_text] += 1
            if len(usage_action_samples[action_text]) < 3:
                usage_action_samples[action_text].append(
                    {
                        "role": event.get("role"),
                        "event_type": event.get("event_type"),
                        "session_label": event.get("session_label"),
                        "event_id": event.get("event_id"),
                        "title": event.get("title"),
                        "refs": event.get("refs") if isinstance(event.get("refs"), dict) else {},
                    }
                )
    evidence_refs = entity_usage_chain_refs(all_chain_events, document_refs, limit=max(12, document_limit or 12))
    first_ref = entity_usage_chain_first_ref(all_chain_events, evidence_refs)
    source_episode_refs: list[dict[str, Any]] = []
    seen_source_episodes: set[tuple[str, str]] = set()
    for event in unique_entity_usage_events(all_chain_events):
        if not isinstance(event, dict):
            continue
        session_id = str(event.get("session_id") or "")
        task_episode_id = str(event.get("task_episode_id") or "")
        if not session_id or not task_episode_id:
            continue
        episode_key = (session_id, task_episode_id)
        if episode_key in seen_source_episodes:
            continue
        seen_source_episodes.add(episode_key)
        refs = (
            event.get("refs")
            if isinstance(event.get("refs"), dict)
            else {}
        )
