def command_skill_usage_receipt(args: argparse.Namespace) -> int:
    explicit_workspace = (
        Path(args.workspace_root) if args.workspace_root else None
    )
    root = aoa_root_for(
        explicit_workspace,
        Path(args.aoa_root) if args.aoa_root else None,
    )
    if args.skill_usage_receipt_action == "list":
        payload = load_skill_usage_receipts(
            aoa_root=root,
            anchor=args.skill,
            session=args.session_filter,
            limit=args.limit,
        )
        stdout_payload = (
            payload
            if args.full
            else {
                key: value
                for key, value in payload.items()
                if key != "receipts"
            }
        )
        print(json.dumps(stdout_payload, indent=2, ensure_ascii=False))
        return 0 if not payload.get("diagnostics") else 1
    if args.skill_usage_receipt_action == "record":
        payload = record_skill_usage_receipt(
            aoa_root=root,
            receipt_path=Path(args.receipt),
            apply=args.apply,
        )
        print(json.dumps(payload, indent=2, ensure_ascii=False))
        return 0 if payload.get("ok") else 1

    receipt_path = Path(args.receipt).expanduser().resolve()
    diagnostics: list[str] = []
    payload_value: Any = {}
    if receipt_path.is_symlink() or not receipt_path.is_file():
        diagnostics.append("receipt_source_must_be_regular_non_symlink_file")
    elif receipt_path.stat().st_size > SKILL_USAGE_RECEIPT_MAX_BYTES:
        diagnostics.append("receipt_source_exceeds_size_limit")
    else:
        try:
            payload_value = json.loads(receipt_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
            diagnostics.append(f"receipt_source_unreadable_or_invalid_json:{exc}")
    diagnostics.extend(validate_skill_usage_receipt(payload_value))
    admission = (
        skill_usage_receipt_admission(
            payload_value,
            receipt_ref=str(receipt_path),
        )
        if isinstance(payload_value, dict) and payload_value
        else {}
    )
    result = {
        "schema_version": "skill_usage_receipt_validation_v1",
        "artifact_type": "session_memory_skill_usage_receipt_validation",
        "generated_at": utc_now(),
        "ok": not diagnostics,
        "mutates": False,
        "receipt": str(receipt_path),
        "admission": admission,
        "diagnostics": sorted(set(diagnostics)),
        "authority_boundary": SKILL_USAGE_RECEIPT_CLAIM_LIMIT,
    }
    print(json.dumps(result, indent=2, ensure_ascii=False))
    return 0 if result["ok"] else 1


