def bounded_results_print_payload(payload: dict[str, Any], *, full: bool = False, sample_results: int = 20, compact_func=None, note: str = "") -> dict[str, Any]:
    if full:
        return payload
    results = payload.get("results", [])
    result_count = len(results) if isinstance(results, list) else 0
    sample: list[Any] = []
    if isinstance(results, list) and results:
        if result_count <= sample_results:
            sample = results
        else:
            head_count = max(1, sample_results // 2)
            tail_count = max(1, sample_results - head_count)
            sample = results[:head_count] + results[-tail_count:]
    compact = {key: value for key, value in payload.items() if key != "results"}
    renderer = compact_func or (lambda item: item)
    compact["result_count"] = result_count
    compact["results_sample"] = [renderer(item) for item in sample if isinstance(item, dict)]
    compact["results_omitted"] = max(0, result_count - len(sample))
    compact["print"] = {"full": False, "note": note or "results are bounded on stdout; pass --full or read the written report for complete results"}
    return compact


def bounded_trace_print_payload(
    payload: dict[str, Any],
    *,
    full: bool = False,
    sample_results: int = 20,
) -> dict[str, Any]:
    if full:
        return payload
    compact = bounded_results_print_payload(
        payload,
        full=False,
        sample_results=sample_results,
        compact_func=compact_trace_result,
        note=(
            "route trace results are bounded on stdout; pass --full or read "
            "the written report for complete refs"
        ),
    )
    results = compact.pop("results_sample", [])
    compact["results"] = results
    compact["returned_result_count"] = len(results) if isinstance(results, list) else 0
    compact["truncated"] = int_value(compact.get("results_omitted")) > 0
    compact["result_window"] = {
        "mode": "sample",
        "returned": compact["returned_result_count"],
        "total": int_value(compact.get("result_count")),
        "omitted": int_value(compact.get("results_omitted")),
    }
    return compact


