def command_index_maintenance(args: argparse.Namespace) -> int:
    explicit_workspace = Path(args.workspace_root) if args.workspace_root else None
    root = aoa_root_for(explicit_workspace, Path(args.aoa_root) if args.aoa_root else None)
    since = since_date_from_args(args.since, args.since_days if args.since_days is not None else None)
    max_raw_bytes = int(args.max_raw_mb * 1024 * 1024) if args.max_raw_mb is not None else None
    token_max_raw_bytes = int(args.token_max_raw_mb * 1024 * 1024) if args.token_max_raw_mb is not None else None
    skip_token_accounting = bool(getattr(args, "skip_token_accounting", False))

    def run_maintenance() -> dict[str, Any]:
        return maintain_indexes(
            aoa_root=root,
            target=args.session,
            observe_query_demand=bool(getattr(args, "observe_query_demand", False)),
            since=since,
            until=args.until,
            limit=args.limit,
            discovery_limit=getattr(args, "discovery_limit", None),
            repair_limit=getattr(args, "repair_limit", None),
            search_shard_repair_limit=getattr(
                args, "search_shard_repair_limit", None
            ),
            apply=args.apply,
            max_raw_bytes=max_raw_bytes,
            token_max_raw_bytes=token_max_raw_bytes,
            sample_audit=args.sample_audit,
            sample_limit=args.sample_limit,
            max_raw_chars=args.max_raw_chars,
            graph_batch_limit=args.graph_batch_limit,
            graph_refresh_chunk_size=args.graph_refresh_chunk_size,
            graph_max_refresh_nodes=getattr(args, "graph_max_refresh_nodes", GRAPH_MAINTENANCE_AUTO_MAX_REFRESH_NODES),
            graph_max_refresh_edges=getattr(args, "graph_max_refresh_edges", GRAPH_MAINTENANCE_AUTO_MAX_REFRESH_EDGES),
            repair_indexes=not args.skip_index_repair,
            repair_token_accounting=not skip_token_accounting,
            repair_graph=not args.skip_graph_repair,
            write_report=args.write_report,
            reason=args.reason,
            budget_seconds=args.budget_seconds,
            progress_every=args.progress_every,
        )

    payload = (
        run_with_maintenance_lock(
            root,
            run_maintenance,
            owner_job="index-maintenance",
            mode="manual-bulk",
                target=args.session,
                reason=args.reason,
                touched_surfaces=maintenance_surfaces(
                    repair_indexes=not args.skip_index_repair,
                    repair_token_accounting=not skip_token_accounting,
                    repair_graph=not args.skip_graph_repair,
                ),
            budget_seconds=args.budget_seconds,
        )
        if args.apply
        else run_maintenance()
    )
    if args.write_report and not payload.get("report_json"):
        payload = ensure_index_maintenance_report(root, payload)
    print(json.dumps(index_maintenance_print_payload(payload, full=args.full), indent=2, ensure_ascii=False))
    return 0 if payload.get("ok") else 1


def command_auto_maintenance(args: argparse.Namespace) -> int:
    explicit_workspace = Path(args.workspace_root) if args.workspace_root else None
    root = aoa_root_for(explicit_workspace, Path(args.aoa_root) if args.aoa_root else None)
    workspace = explicit_workspace or root.parent
    since = since_date_from_args(args.since, args.since_days if args.since_days is not None else None)
    max_raw_bytes = int(args.max_raw_mb * 1024 * 1024) if args.max_raw_mb is not None else None
    token_max_raw_bytes = int(args.token_max_raw_mb * 1024 * 1024) if args.token_max_raw_mb is not None else None
    payload = auto_maintenance(
        workspace_root=workspace,
        aoa_root=root,
        profile=args.profile,
        target=args.session,
        since=since,
        since_days=None if args.since is not None else args.since_days,
        until=args.until,
        limit=args.limit,
        discovery_limit=getattr(args, "discovery_limit", None),
        repair_limit=getattr(args, "repair_limit", None),
        search_shard_repair_limit=getattr(
            args, "search_shard_repair_limit", None
        ),
        dense_repair_limit=getattr(args, "dense_repair_limit", None),
        apply=args.apply,
        max_raw_bytes=max_raw_bytes,
        token_max_raw_bytes=token_max_raw_bytes,
        graph_batch_limit=args.graph_batch_limit,
        graph_refresh_chunk_size=args.graph_refresh_chunk_size,
        graph_max_refresh_nodes=getattr(args, "graph_max_refresh_nodes", None),
        graph_max_refresh_edges=getattr(args, "graph_max_refresh_edges", None),
        ref_sample_limit=args.ref_sample_limit,
        sample_audit=False if args.no_sample_audit else (True if args.sample_audit else None),
        repair_indexes=args.repair_indexes,
        repair_graph=args.repair_graph,
        write_report=args.write_report,
        lock_timeout_sec=args.lock_timeout_sec,
        reason=args.reason,
        budget_seconds=args.budget_seconds,
        progress_every=args.progress_every,
    )
    print(json.dumps(auto_maintenance_print_payload(payload, full=args.full), indent=2, ensure_ascii=False))
    return 0 if payload.get("ok") else 1


