        graph_drip_candidate_pool_limit=args.graph_drip_candidate_pool_limit,
        since=since,
        since_days=None if args.since is not None else args.since_days,
        until=args.until,
        limit=args.limit,
        repair_limit=args.repair_limit,
        search_shard_repair_limit=getattr(
            args, "search_shard_repair_limit", None
        ),
        dense_repair_limit=getattr(args, "dense_repair_limit", None),
        max_raw_mb=args.max_raw_mb,
        token_max_raw_mb=args.token_max_raw_mb,
