    workspace = explicit_workspace or root.parent
    payload = auto_maintenance_retry_dispatch(
        workspace_root=workspace,
        aoa_root=root,
        apply=args.apply,
        limit=args.limit,
        write_report=args.write_report,
    )
    stdout_payload = payload if args.full else {
        key: value
        for key, value in payload.items()
        if key not in {"queue_before", "queue_after"}
    }
    if not args.full:
        stdout_payload["queue_before"] = {
            key: payload.get("queue_before", {}).get(key)
            for key in ("status", "queued_count", "due_count", "in_flight_count", "next_attempt_at", "path")
        }
        stdout_payload["queue_after"] = {
            key: payload.get("queue_after", {}).get(key)
            for key in ("status", "queued_count", "due_count", "in_flight_count", "next_attempt_at", "path")
        }
    print(json.dumps(stdout_payload, indent=2, ensure_ascii=False))
    return 0 if payload.get("ok") else 1


