def command_search_shards(args: argparse.Namespace) -> int:
    explicit_workspace = Path(args.workspace_root) if args.workspace_root else None
    root = aoa_root_for(explicit_workspace, Path(args.aoa_root) if args.aoa_root else None)
    since = since_date_from_args(args.since, args.since_days if args.since_days is not None else None)
    max_raw_bytes = (
        -1
        if getattr(args, "unbounded_raw_text", False)
        else int(args.max_raw_mb * 1024 * 1024) if args.max_raw_mb is not None else None
    )

    def run_search_shards() -> dict[str, Any]:
        return materialize_search_shards(
            aoa_root=root,
            target=args.session,
            since=since,
            until=args.until,
            limit=args.limit,
            shard=args.shard,
            max_raw_bytes=max_raw_bytes,
            use_default_raw_lexical_budget=not getattr(args, "unbounded_raw_text", False),
            write_report=args.write_report,
            budget_seconds=args.budget_seconds,
            progress_every=args.progress_every,
            structured_only=not getattr(args, "full_text", False),
            rebuild_shards=not args.no_rebuild,
            dirty_only=bool(getattr(args, "dirty_only", False)),
            include_deferred_live=bool(getattr(args, "include_deferred_live", False)),
            context_tail_omission_policy=getattr(args, "context_tail_omission_policy", SEARCH_CONTEXT_TAIL_OMISSION_POLICY_AUTO),
        )

    payload = run_with_maintenance_lock(
        root,
        run_search_shards,
        owner_job="search-shards",
        mode="manual-bulk",
        target=args.shard or args.session,
        reason="operator_requested",
        touched_surfaces=maintenance_surfaces(repair_indexes=False, repair_graph=False, search=True, entity_registry=False),
        budget_seconds=args.budget_seconds,
    )
    if args.full:
        stdout_payload = payload
    else:
        stdout_payload = {key: value for key, value in payload.items() if key != "sessions"}
    print(json.dumps(stdout_payload, indent=2, ensure_ascii=False))
    return 0 if payload.get("ok") else 1


