def command_search_operational_shrink_apply(args: argparse.Namespace) -> int:
    explicit_workspace = Path(args.workspace_root) if args.workspace_root else None
    root = aoa_root_for(explicit_workspace, Path(args.aoa_root) if args.aoa_root else None)
    workspace = explicit_workspace or root.parent

    def run_shrink_apply() -> dict[str, Any]:
        return session_memory_search_operational_shrink_apply(
            workspace_root=workspace,
            aoa_root=root,
            apply=args.apply,
            max_shards=args.max_shards,
            per_shard_timeout_seconds=args.per_shard_timeout,
            route_rollup_limit=args.route_rollup_limit,
            live_scenario_case_limit=args.live_scenario_case_limit,
            literal_probe_max_shards=args.literal_probe_max_shards,
            literal_query_timeout_ms=args.literal_query_timeout_ms,
            budget_seconds=args.budget_seconds,
            progress_every=args.progress_every,
            post_check_gates=not args.skip_post_gates,
            write_report=args.write_report,
        )

    payload = run_with_maintenance_lock(
        root,
        run_shrink_apply,
        owner_job="search-operational-shrink-apply",
        mode="manual-bulk" if args.apply else "probe",
        target="all",
        reason="operator_requested" if args.apply else "operator_probe",
        touched_surfaces=maintenance_surfaces(repair_indexes=False, repair_graph=False, search=True, entity_registry=False),
        budget_seconds=args.budget_seconds,
    )
    if args.full:
        stdout_payload = payload
    else:
        stdout_payload = {
            key: value
            for key, value in payload.items()
            if key not in {"before", "after", "preflight_gates"}
        }
    print(json.dumps(stdout_payload, indent=2, ensure_ascii=False))
    return 0 if payload.get("ok") else 1


def command_search(args: argparse.Namespace) -> int:
    explicit_workspace = Path(args.workspace_root) if args.workspace_root else None
    root = aoa_root_for(explicit_workspace, Path(args.aoa_root) if args.aoa_root else None)
    query = args.query or args.query_text or ""
    payload = search_sessions(
        aoa_root=root,
        query=query,
        limit=args.limit,
        provider=args.provider,
        include_host_context=args.include_host_context,
        include_semantic_context=args.include_semantic_context,
        rerank_local=args.rerank_local,
        rerank_candidate_limit=args.rerank_candidate_limit,
        allow_host_warnings=args.allow_host_warnings,
        host_timeout=args.host_timeout,
        session=args.session_filter,
        doc_type=args.doc_type,
        event_type=args.event_type,
        family=args.family,
        outcome=args.outcome,
        conversation_act=args.conversation_act,
        session_act=args.session_act,
        agent_event=args.agent_event,
        usage_role=args.usage_role,
        task_episode_id=args.task_episode_id,
        route_layer=args.route_layer,
        route_signal=args.route_signal,
        archive_status=args.archive_status,
        freshness_status=args.freshness_status,
        date_from=args.date_from,
        date_to=args.date_to,
        explain=args.explain,
        use_shards=args.use_shards,
        max_shards=args.max_shards,
        query_timeout_ms=getattr(args, "query_timeout_ms", SEARCH_FTS_QUERY_TIMEOUT_MS),
        literal_postings_only=getattr(args, "literal_postings_only", False),
        include_archived_raw_fallback=getattr(args, "archived_raw_fallback", True),
    )
    literal_shape = literal_query_shape(query)
    attach_session_memory_evidence_envelope(
        payload,
        aoa_root=root,
        query=query,
        route_id=(
            "exact_or_typed_search"
            if literal_shape.get("primary")
            in {
                LITERAL_QUERY_KIND_IDENTIFIER,
                LITERAL_QUERY_KIND_PATH,
                LITERAL_QUERY_KIND_RAW_REF,
                LITERAL_QUERY_KIND_SESSION_ID,
                LITERAL_QUERY_KIND_COMMAND,
            }
            else "portable_lexical_search"
        ),
        route_reason=(
            "use exact or typed postings before semantic expansion"
            if literal_shape.get("primary")
            != LITERAL_QUERY_KIND_HUMAN_PHRASE
            else "bounded portable lexical candidate generation"
        ),
        route_authority="generated_search_navigation_requires_ref_read",
        budgets={
            "result_limit": args.limit,
            "query_timeout_ms": getattr(
                args,
                "query_timeout_ms",
                SEARCH_FTS_QUERY_TIMEOUT_MS,
            ),
            "max_shards": args.max_shards,
            "bounded": True,
        },
    )
    print(json.dumps(payload, indent=2, ensure_ascii=False))
    return 0 if payload.get("ok") else 1


def command_live_tail_search(args: argparse.Namespace) -> int:
    explicit_workspace = Path(args.workspace_root) if args.workspace_root else None
    root = aoa_root_for(explicit_workspace, Path(args.aoa_root) if args.aoa_root else None)
    query = args.query or args.query_text or ""
    requested_mode = str(args.mode or "auto")
    effective_mode = requested_mode
    if requested_mode == "auto":
        shape = literal_query_shape(query)
        effective_mode = (
            "exact"
            if shape.get("primary")
            in {
                LITERAL_QUERY_KIND_PATH,
                LITERAL_QUERY_KIND_COMMAND,
                LITERAL_QUERY_KIND_RAW_REF,
                LITERAL_QUERY_KIND_SESSION_ID,
                LITERAL_QUERY_KIND_EXACT_PHRASE,
                LITERAL_QUERY_KIND_ERROR_TEXT,
            }
            else "semantic"
        )
    max_delta_bytes = int(max(0.001, float(args.max_delta_mb)) * 1024 * 1024)
    if effective_mode == "exact":
        payload = live_tail_exact_search(
            aoa_root=root,
            session=args.session_filter,
            query=query,
            limit=args.limit,
            date_from=args.date_from,
            date_to=args.date_to,
            max_delta_bytes=max_delta_bytes,
            max_lines=args.max_lines,
            explain=args.explain,
        )
    else:
        payload = live_tail_episode_search(
            aoa_root=root,
            session=args.session_filter,
            query=query,
            limit=args.limit,
            episode_status=args.status,
            date_from=args.date_from,
            date_to=args.date_to,
            time_from=args.time_from,
            time_to=args.time_to,
            max_delta_bytes=max_delta_bytes,
            max_lines=args.max_lines,
            rerank_local=args.rerank_local,
            rerank_candidate_limit=args.rerank_candidate_limit,
            explain=args.explain,
        )
    payload["requested_mode"] = requested_mode
    payload["effective_mode"] = effective_mode
    attach_session_memory_evidence_envelope(
        payload,
        aoa_root=root,
        query=query,
        route_id=f"live_tail_{effective_mode}",
        route_reason="bounded session-scoped read of the append-only live tail",
        route_authority="live_raw_transcript_snapshot",
        budgets={
            "result_limit": args.limit,
            "max_delta_bytes": max_delta_bytes,
            "max_lines": args.max_lines,
            "bounded": True,
        },
    )
    print(json.dumps(payload, indent=2, ensure_ascii=False))
    return 0 if payload.get("ok") else 1


