def command_graph_build(args: argparse.Namespace) -> int:
    explicit_workspace = Path(args.workspace_root) if args.workspace_root else None
    root = aoa_root_for(explicit_workspace, Path(args.aoa_root) if args.aoa_root else None)
    since = since_date_from_args(args.since, args.since_days if args.since_days is not None else None)
    if args.in_place and not args.store_only:
        payload = {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "session_memory_graph_index",
            "graph_schema_version": GRAPH_SCHEMA_VERSION,
            "generated_at": utc_now(),
            "ok": False,
            "mutates": False,
            "truth_status": "graph_export_not_run",
            "diagnostics": ["--in-place is only valid with --store-only; sidecar export rebuilds use the existing export guard"],
        }
        print(json.dumps(payload, indent=2, ensure_ascii=False))
        return 1
    if args.write and not args.store_only and args.session == "all" and args.limit is None and not args.force_large_export:
        payload = {
            "schema_version": SCHEMA_VERSION,
            "artifact_type": "session_memory_graph_index",
            "graph_schema_version": GRAPH_SCHEMA_VERSION,
            "generated_at": utc_now(),
            "ok": False,
            "mutates": False,
            "truth_status": "graph_export_not_run",
            "diagnostics": [
                "refusing unbounded full graph export; pass --limit for a bounded sidecar or --force-large-export for an explicit offline rebuild"
            ],
            "next_route": "interactive graph and GraphRAG tools use bounded trace/search packets and do not require a full sidecar export",
        }
        print(json.dumps(payload, indent=2, ensure_ascii=False))
        return 1
    def run_build() -> dict[str, Any]:
        return build_session_graph(
            aoa_root=root,
            target=args.session,
            since=since,
            until=args.until,
            limit=args.limit,
            write=args.write,
            include_rows=args.full,
            reclaim_existing_sidecar=bool(args.write and not args.store_only and args.force_large_export and args.session == "all" and args.limit is None),
            export_sidecar=not args.store_only,
            atomic_store_rebuild=not args.in_place,
            progress_every=args.progress_every,
        )

    payload = (
        run_with_maintenance_lock(
            root,
            run_build,
            owner_job="graph-build",
            mode="manual-bulk",
            target=args.session,
            reason="operator_requested",
            touched_surfaces=maintenance_surfaces(
                repair_indexes=False,
                repair_graph=False,
                graph=True,
                entity_registry=True,
            ),
        )
        if args.write
        else run_build()
    )
    print(json.dumps(payload, indent=2, ensure_ascii=False))
    return 0 if payload.get("ok") else 1


def command_graph_registry_rebind(
    args: argparse.Namespace,
) -> int:
    explicit_workspace = (
        Path(args.workspace_root)
        if args.workspace_root
        else None
    )
    root = aoa_root_for(
        explicit_workspace,
        Path(args.aoa_root) if args.aoa_root else None,
    )

    def run_rebind() -> dict[str, Any]:
        payload = graph_entity_registry_dependency_rebind(
            aoa_root=root,
            apply=bool(args.apply),
            previous_producer_source=(
                Path(args.previous_producer_source)
                if args.previous_producer_source
                else None
            ),
            sample_limit=args.sample_limit,
        )
        if args.write_report:
            report_root = root / "diagnostics"
            report_root.mkdir(parents=True, exist_ok=True)
            stem = (
                f"{compact_stamp()}__graph-registry-rebind"
            )
            report_json = report_root / f"{stem}.json"
            report_markdown = report_root / f"{stem}.md"
            payload["report_json"] = str(report_json)
            payload["report_markdown"] = str(report_markdown)
            payload["report_written"] = True
            payload["graph_mutates"] = bool(
                payload.get("mutates")
            )
            payload["mutates"] = True
            write_json(report_json, payload)
            write_markdown(
                report_markdown,
                "\n".join(
                    [
                        "# Graph registry dependency rebind",
                        "",
                        f"- status: `{payload.get('status')}`",
                        f"- ok: `{payload.get('ok')}`",
                        f"- apply: `{payload.get('apply')}`",
                        (
                            "- dependency binding changed: "
                            f"`{payload.get('dependency_binding_changed')}`"
                        ),
                        (
                            "- graph content changed: "
                            f"`{payload.get('graph_content_changed')}`"
                        ),
                        (
                            "- source rows rebound: "
                            f"`{payload.get('source_rows_rebound', 0)}`"
                        ),
                        (
                            "- diagnostics: "
                            f"`{', '.join(payload.get('diagnostics', [])) or 'none'}`"
                        ),
                        "",
                        (
                            "Raw sessions and external owner sources remain "
                            "stronger than this generated dependency binding."
                        ),
                    ]
                )
                + "\n",
            )
        return payload

    payload = (
        run_with_maintenance_lock(
            root,
            run_rebind,
            owner_job="graph-registry-rebind",
            mode="manual-bulk",
            target="graph/entity-registry-dependency",
            reason="operator_requested",
            touched_surfaces=maintenance_surfaces(
                repair_indexes=False,
                repair_graph=False,
                graph=True,
            ),
        )
        if args.apply or args.write_report
        else run_rebind()
    )
    print(json.dumps(payload, indent=2, ensure_ascii=False))
    return 0 if payload.get("ok") else 1


