def command_evaluation_generation_pin(args: argparse.Namespace) -> int:
    explicit_workspace = (
        Path(args.workspace_root) if args.workspace_root else None
    )
    root = aoa_root_for(
        explicit_workspace,
        Path(args.aoa_root) if args.aoa_root else None,
    )
    pin_path = Path(args.pin).expanduser().resolve(strict=False)
    if args.pin_action == "capture":
        payload = run_with_maintenance_lock(
            root,
            lambda: evaluation_generation_pin_capture_payload(
                aoa_root=root,
                sessions=args.session,
            ),
            owner_job="evaluation-generation-pin-capture",
            mode="evaluation-read",
            target=(
                ",".join(args.session)
                if args.session
                else "all"
            ),
            reason="capture_stable_evaluation_source_and_projection_generation",
            touched_surfaces=[],
            lock_timeout_sec=0.0,
        )
        if payload.get("artifact_type") == (
            "session_memory_maintenance_lock_conflict"
        ):
            payload = {
                "schema_version": EVALUATION_GENERATION_PIN_SCHEMA_VERSION,
                "artifact_type": "session_memory_evaluation_generation_pin",
                "generated_at": utc_now(),
                "ok": False,
                "status": "refused_active_projection_writer",
                "mutates": False,
                "pin_path": str(pin_path),
                "answer_or_score_admissible": False,
                "maintenance_conflict": payload,
                "diagnostics": ["maintenance_lease_conflict"],
            }
        else:
            payload["pin_path"] = str(pin_path)
            payload["memory_mutates"] = False
            payload["writes_pin_manifest"] = bool(payload.get("ok"))
            if payload.get("ok"):
                payload["mutates"] = True
                write_json(pin_path, payload)
        stdout_payload = (
            payload
            if args.full
            else {
                key: payload.get(key)
                for key in (
                    "schema_version",
                    "artifact_type",
                    "generated_at",
                    "ok",
                    "status",
                    "pin_id",
                    "pin_path",
                    "memory_mutates",
                    "writes_pin_manifest",
                    "diagnostics",
                    "maintenance_coordinator",
                    "maintenance_conflict",
                )
                if key in payload
            }
        )
    else:
        pin = read_json(pin_path, {})
        if not isinstance(pin, dict) or not pin:
            payload = {
                "schema_version": (
                    EVALUATION_GENERATION_PIN_COMPARISON_SCHEMA_VERSION
                ),
                "artifact_type": (
                    "session_memory_evaluation_generation_pin_comparison"
                ),
                "generated_at": utc_now(),
                "ok": False,
                "status": "refused_pin_unavailable",
                "mutates": False,
                "pin_path": str(pin_path),
                "answer_or_score_admissible": False,
                "diagnostics": ["evaluation_generation_pin_unavailable"],
            }
        else:
            payload = run_with_maintenance_lock(
                root,
                lambda: evaluation_generation_pin_check_payload(
                    aoa_root=root,
                    pin=pin,
                ),
                owner_job="evaluation-generation-pin-check",
                mode="evaluation-read",
                target="pinned-scope",
                reason="recheck_evaluation_source_and_projection_generation",
                touched_surfaces=[],
                lock_timeout_sec=0.0,
            )
            if payload.get("artifact_type") == (
                "session_memory_maintenance_lock_conflict"
            ):
                payload = {
                    "schema_version": (
                        EVALUATION_GENERATION_PIN_COMPARISON_SCHEMA_VERSION
                    ),
                    "artifact_type": (
                        "session_memory_evaluation_generation_pin_comparison"
                    ),
                    "generated_at": utc_now(),
                    "ok": False,
                    "status": "refused_active_projection_writer",
                    "mutates": False,
                    "answer_or_score_admissible": False,
                    "maintenance_conflict": payload,
                    "diagnostics": ["maintenance_lease_conflict"],
                }
            payload["pin_path"] = str(pin_path)
        stdout_payload = (
            payload
            if args.full
            else {
                key: payload.get(key)
                for key in (
                    "schema_version",
                    "artifact_type",
                    "ok",
                    "status",
                    "pin_path",
                    "answer_or_score_admissible",
                    "before_identity_sha256",
                    "after_identity_sha256",
                    "changed_components",
                    "reasons",
                    "diagnostics",
                    "maintenance_coordinator",
                    "maintenance_conflict",
                )
                if key in payload
            }
        )
    print(json.dumps(stdout_payload, indent=2, ensure_ascii=False))
    return 0 if payload.get("ok") else 1


