def command_hooks_config(args: argparse.Namespace) -> int:
    explicit_workspace = Path(args.workspace_root) if args.workspace_root else None
    root = aoa_root_for(explicit_workspace, Path(args.aoa_root) if args.aoa_root else None)
    workspace_root = workspace_root_for(explicit_workspace, root)
    config = build_user_hooks_config(workspace_root, root, python_bin=args.python_bin)
    if not args.write:
        print(json.dumps(config, indent=2, ensure_ascii=False))
        return 0

    target = Path(args.write).expanduser()
    backup_path: Path | None = None
    if target.exists() and not args.no_backup:
        backup_path = target.with_name(f"{target.name}.{compact_stamp()}.bak")
        backup_path.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(target, backup_path)
    write_json(target, config)
    payload = {
        "schema_version": SCHEMA_VERSION,
        "ok": True,
        "written_to": str(target),
        "backup_path": str(backup_path) if backup_path else None,
        "workspace_root": str(workspace_root),
        "aoa_root": str(root),
        "events": REQUIRED_HOOK_EVENTS,
    }
    print(json.dumps(payload, indent=2, ensure_ascii=False))
    return 0


def command_export_bundle(args: argparse.Namespace) -> int:
    source = Path(args.source_aoa_root) if args.source_aoa_root else default_source_aoa_root()
    target = Path(args.target_dir)
    if args.with_sessions:
        print(
            json.dumps(
                {
                    "schema_version": SCHEMA_VERSION,
                    "ok": False,
                    "status": "rejected_before_target_mutation",
                    "error": (
                        "portable bundles cannot include session archives or "
                        "raw evidence; use an explicitly private "
                        "owner-to-owner migration route instead"
                    ),
                },
                indent=2,
                ensure_ascii=False,
            )
        )
        return 1
    if target.exists() and args.force:
        runtime_markers = export_force_runtime_target_markers(target)
        if runtime_markers:
            print(
                json.dumps(
                    {
                        "schema_version": SCHEMA_VERSION,
                        "ok": False,
                        "status": (
                            "rejected_runtime_target_before_mutation"
                        ),
                        "target": str(target),
                        "runtime_markers": runtime_markers,
                        "error": (
                            "export-bundle --force accepts a clean portable "
                            "target, not an installed runtime root"
                        ),
                        "next_route": (
                            "use install --force for a runtime kernel upgrade"
                        ),
                    },
                    indent=2,
                    ensure_ascii=False,
                )
            )
            return 1
        clear_export_target_for_force(target)
    payload = copy_portable_bundle(
        source_aoa_root=source,
        target_aoa_root=target,
        include_sessions=args.with_sessions,
        include_tests=not args.no_tests,
        overwrite=args.force,
    )
    public_safety = (
        payload.get("public_safety")
        if isinstance(payload.get("public_safety"), dict)
        else {}
    )
    ok = bool(public_safety.get("ok"))
    print(
        json.dumps(
            {"schema_version": SCHEMA_VERSION, "ok": ok, **payload},
            indent=2,
            ensure_ascii=False,
        )
    )
    return 0 if ok else 1


